internal object NtkForwardAdjacentValidatedRecoveryPolicy {
    fun shouldRearm(
        validatedEpoch: Long,
        lastValidatedRedriveEpoch: Long,
        boundaryMatches: Boolean,
        structureCommitted: Boolean,
    ): Boolean = validatedEpoch > 0L && boundaryMatches && !structureCommitted &&
        lastValidatedRedriveEpoch < validatedEpoch

    fun blocksOrdinarySameTargetReselection(
        retiredTargetPath: String,
        candidateTargetPath: String,
    ): Boolean = retiredTargetPath.isNotEmpty() &&
        retiredTargetPath.equals(candidateTargetPath, ignoreCase = true)

    fun observedBoundaryMatches(
        observedPath: String,
        predecessorPath: String,
        targetPath: String,
    ): Boolean = observedPath.isEmpty() ||
        observedPath.equals(predecessorPath, ignoreCase = true) ||
        observedPath.equals(targetPath, ignoreCase = true)
}

/**
 * Retains one real validated-network edge for an exact adjacent owner which is not the current
 * viewport boundary yet. The owning Session/viewer generation is checked before latching; this
 * policy only decides whether the same immutable owner may consume that epoch once.
 */
internal object NtkAdjacentValidatedEpochCatchUpPolicy {
    fun shouldResetRequestGeneration(
        terminalCatchUp: Boolean,
        activeCatchUp: Boolean,
        replacementInFlight: Boolean,
    ): Boolean = terminalCatchUp || (activeCatchUp && !replacementInFlight)

    fun exactBoundaryMatches(
        readingPath: String,
        predecessorPath: String,
        targetPath: String,
    ): Boolean = readingPath.isNotEmpty() &&
        (readingPath.equals(predecessorPath, ignoreCase = true) ||
            readingPath.equals(targetPath, ignoreCase = true))

    fun latch(
        validatedEpoch: Long,
        lastConsumedEpoch: Long,
        pendingEpoch: Long,
    ): Long = if (validatedEpoch > 0L && validatedEpoch > lastConsumedEpoch &&
        validatedEpoch > pendingEpoch
    ) {
        validatedEpoch
    } else {
        pendingEpoch
    }

    fun consume(
        pendingEpoch: Long,
        lastConsumedEpoch: Long,
        exactBoundary: Boolean,
    ): Long = pendingEpoch.takeIf {
        exactBoundary && it > 0L && it > lastConsumedEpoch
    } ?: 0L
}

internal object NtkStrictDecodeReleasePolicy {
    fun releaseThreshold(pageCount: Int, webtoon: Boolean = false): Int {
        require(pageCount > 0)
        if (pageCount <= 12) return pageCount
        // Keep the small overlap lane active, but do not open the bulk pool while the first H2
        // burst is establishing throughput. A webtoon releases at its exact five-page physical
        // scroll runway: waiting for unrelated page 5 after pages 0-4 were already resident kept
        // page 4 encoded-but-undecoded at the user's first boundary. Other strips retain twelve.
        return (if (webtoon) 5 else 12).coerceAtMost(pageCount)
    }

    fun shouldRelease(residentPageCount: Int, pageCount: Int, webtoon: Boolean = false): Boolean =
        residentPageCount >= releaseThreshold(pageCount, webtoon)
}

/**
 * Keeps exact encoded-body ownership separate from decoded-pixel demand.
 *
 * A rolling scene may finish downloading every immutable original, but claiming one decode task
 * per body turns that source-completion edge into an unbounded native/GPU work queue.  Only pixels
 * which can affect the current physical frame, its finite launch runway, or an identity-qualified
 * liveness/warm edge are allowed to own a decoder.  Later viewport updates can losslessly admit any
 * other source from its resident exact body.
 */
internal object NtkStrictRollingDecodeRequestPolicy {
    /**
     * A short chapter, or a short authoritative suffix after a saved-page resume, is a bounded
     * completion job even when its decoded pixels cannot all remain resident at once. Letting each
     * required canonical page decode once records drawable completion and leaves rolling
     * retirement free to release its pixels. Longer strips stay demand-driven so an
     * all-bodies-resident event cannot manufacture a large decoder/GPU queue behind the viewport.
     */
    const val MAX_BOUNDED_COMPLETE_SCENE_PAGES = 24

    fun allows(
        rollingPixelResidency: Boolean,
        completionSpanPageCount: Int,
        insideRollingPixelWindow: Boolean,
        initialScrollRunway: Boolean,
        viewportBlocker: Boolean,
        compositorForwardWarm: Boolean,
        physicalForwardWarm: Boolean,
    ): Boolean =
        !rollingPixelResidency ||
            completionSpanPageCount in 1..MAX_BOUNDED_COMPLETE_SCENE_PAGES ||
            insideRollingPixelWindow || initialScrollRunway || viewportBlocker ||
            compositorForwardWarm || physicalForwardWarm
}

/**
 * Revision-aware ownership for completion-driven exact-manifest appends.
 *
 * A target path can legitimately be selected, replaced, and selected again before an older
 * manifest callback leaves its executor. Keeping both pending and in-flight ownership keyed by
 * path alone lets that old callback either overwrite the new pending value or consume its only
 * wake-up. Pending installation therefore keeps the greatest monotonic claim revision, while an
 * in-flight release must match the exact revision that acquired the path.
 */
internal class NtkForwardAdjacentExactManifestAppendGate<T>(
    private val revisionOf: (T) -> Long,
) {
    private val pendingByPath = ConcurrentHashMap<String, T>()
    private val inFlightRevisionByPath = ConcurrentHashMap<String, Long>()

    fun installNewest(path: String, proposed: T): T {
        require(path.isNotBlank())
        val proposedRevision = revisionOf(proposed)
        require(proposedRevision > 0L)
        return checkNotNull(pendingByPath.compute(path) { _, current ->
            if (current == null || proposedRevision > revisionOf(current)) proposed else current
        })
    }

    fun current(path: String): T? = pendingByPath[path]

    fun snapshot(): Map<String, T> = HashMap(pendingByPath)

    fun isCurrent(path: String, expected: T): Boolean = pendingByPath[path] === expected

    fun removePending(path: String, expected: T): Boolean {
        var removed = false
        pendingByPath.computeIfPresent(path) { _, current ->
            if (current === expected) {
                removed = true
                null
            } else {
                current
            }
        }
        return removed
    }

    fun removePendingRevision(path: String, expectedRevision: Long): Boolean {
        require(expectedRevision > 0L)
        val current = pendingByPath[path] ?: return false
        if (revisionOf(current) != expectedRevision) return false
        return pendingByPath.remove(path, current)
    }

    fun tryAcquire(path: String, revision: Long): Boolean {
        require(path.isNotBlank())
        require(revision > 0L)
        return inFlightRevisionByPath.putIfAbsent(path, revision) == null
    }

    fun release(path: String, revision: Long): Boolean {
        require(revision > 0L)
        return inFlightRevisionByPath.remove(path, revision)
    }

    fun clear() {
        pendingByPath.clear()
        inFlightRevisionByPath.clear()
    }
}

internal object NtkStrictTerminalDecodePolicy {
    const val DEFAULT_PARALLELISM = 5
    const val DIRECT_WIFI_CURRENT_WEBTOON_PARALLELISM = 7
    const val DEFAULT_EXPAND_MIN_BACKLOG = 12
    const val DIRECT_WIFI_CURRENT_WEBTOON_EXPAND_MIN_BACKLOG = 7

    fun expandedParallelism(
        rollingPixelResidency: Boolean,
        terminalBacklog: Int,
        directWifi: Boolean,
        currentForegroundEpisode: Boolean,
        webtoon: Boolean,
    ): Int? {
        if (rollingPixelResidency) return null
        val directWifiCurrentWebtoon = directWifi && currentForegroundEpisode && webtoon
        val expandMinBacklog = if (directWifiCurrentWebtoon) {
            DIRECT_WIFI_CURRENT_WEBTOON_EXPAND_MIN_BACKLOG
        } else {
            DEFAULT_EXPAND_MIN_BACKLOG
        }
        if (terminalBacklog < expandMinBacklog) return null
        return if (directWifiCurrentWebtoon) {
            DIRECT_WIFI_CURRENT_WEBTOON_PARALLELISM
        } else {
            DEFAULT_PARALLELISM
        }
    }
}

internal object NtkStrictActiveScrollDecodePolicy {
    const val HOST_INITIAL_INTERACTION_GRACE_MS = 1_500L

    /**
     * The first exact frame is the point at which a reader can immediately put a finger down.
     * Keep encoded offscreen bodies private through that short reaction window; otherwise a
     * non-preemptible native decode admitted just before ACTION_DOWN can monopolize the host GPU
     * throughout the whole gesture. The finite p0..p4 runway and an identity-bound physical
     * blocker never use this hold.
     */
    fun shouldHoldHostOffscreenBeforeFirstInteraction(
        hostSurfaceRuntime: Boolean,
        currentForegroundEpisode: Boolean,
        anchor: Boolean,
        initialScrollRunway: Boolean,
        initialViewportRequired: Boolean = false,
        physicalScrollEverStarted: Boolean,
        firstPhysicalFrameAtMs: Long,
        firstAnchorPixelsAtMs: Long = firstPhysicalFrameAtMs,
        nowMs: Long,
    ): Boolean {
        if (!hostSurfaceRuntime || !currentForegroundEpisode || anchor ||
            initialScrollRunway || initialViewportRequired || physicalScrollEverStarted
        ) return false
        val graceOriginMs = if (firstPhysicalFrameAtMs > 0L) {
            firstPhysicalFrameAtMs
        } else {
            firstAnchorPixelsAtMs
        }
        // Before p0 exists, keeping speculative pixels private is still correct. Once p0 owns
        // pixels, however, a missing/coalesced compositor callback must not become an unbounded
        // decode lock. Short comic pages may need p1 to create that first complete frame at all.
        return graceOriginMs <= 0L ||
            nowMs - graceOriginMs < HOST_INITIAL_INTERACTION_GRACE_MS
    }

    /**
     * A dense decode/NativeAlloc-GC wave can starve the independent Surface producer even when
     * every decoder is background-priority. A host-GPU reader therefore parks speculative
     * offscreen work throughout physical input and its existing quiet interval; the exact Surface
     * blocker remains independently admissible. Once that interval expires, the fixed rolling
     * executor may consume the verified-body backlog in parallel. This avoids running one
     * 110-140 ms JPEG decode continuously under every gesture without turning a genuinely idle
     * reader into a permanently serial ten-second tail.
     */
    fun shouldDeferHostOffscreenUntilQuiet(
        hostSurfaceRuntime: Boolean,
        physicalScrollEverStarted: Boolean,
        currentForegroundEpisode: Boolean,
        anchor: Boolean,
    ): Boolean = hostSurfaceRuntime && physicalScrollEverStarted &&
        currentForegroundEpisode && !anchor

    /** Mobile direct-WiFi manhwa keeps its established one-at-a-time active-input gate. */
    fun shouldShareVisibleDecodeGate(
        hostSurfaceRuntime: Boolean,
        physicalScrollEverStarted: Boolean,
        directWifi: Boolean,
        currentForegroundEpisode: Boolean,
        activeInput: Boolean,
        anchor: Boolean,
        manhwa: Boolean,
    ): Boolean = currentForegroundEpisode && !anchor &&
        directWifi && activeInput && manhwa &&
        // Host Surface work uses the stronger park-or-blocker policy above. Keep these parameters
        // explicit so a caller cannot silently forget which runtime/interaction proof it captured.
        (!hostSurfaceRuntime || !physicalScrollEverStarted)

}

/**
 * Keeps decoded adjacent webtoon pixels bounded to the runway the reader can actually consume.
 * Exact body downloads may still complete for the whole episode; only bitmap publication is
 * parked. This is host-emulator-only because physical devices keep their established cache and
 * renderer policy.
 */
internal object NtkAdjacentDecodedRunwayPolicy {
    fun shouldParkRemainder(
        hostGpuEmulatorRuntime: Boolean,
        directWifi: Boolean,
        episodePath: String,
        requiredRunwayPages: Int,
        drawablePagesAtOrAhead: Int,
    ): Boolean =
        hostGpuEmulatorRuntime &&
            directWifi &&
            episodePath.startsWith("/webtoon/") &&
            requiredRunwayPages > 0 &&
            drawablePagesAtOrAhead >= requiredRunwayPages

}

/**
 * Separates a recoverable exact runway from decoded-bitmap residency. A chapter that is still
 * offscreen must not keep every decoded page pinned, but its strict owner may park the remaining
 * suffix only after the canonical p0..pN runway is both attached and independently recoverable.
 */
internal object NtkStrictOffscreenRemainderParkPolicy {
    fun hasPreparedRunway(
        episodePath: String,
        claimLive: Boolean,
        requiredRunwayPages: Int,
        orderedAttachedSourceIndexes: List<Int>,
        liveSourceIndexes: Set<Int>,
        recoverableSourceIndexes: Set<Int>,
    ): Boolean {
        if ((!episodePath.startsWith("/manhwa/") && !episodePath.startsWith("/webtoon/")) ||
            !claimLive || requiredRunwayPages <= 0
        ) {
            return false
        }
        val expected = (0 until requiredRunwayPages).toList()
        return orderedAttachedSourceIndexes == expected &&
            expected.all(recoverableSourceIndexes::contains) &&
            liveSourceIndexes.all(expected::contains)
    }

    fun shouldPark(
        cancelled: Boolean,
        directWifiStrictAdjacent: Boolean,
        viewportInsideEpisode: Boolean,
        episodePath: String,
        claimLive: Boolean,
        requiredRunwayPages: Int,
        orderedAttachedSourceIndexes: List<Int>,
        liveSourceIndexes: Set<Int>,
        recoverableSourceIndexes: Set<Int>,
    ): Boolean =
        !cancelled &&
            directWifiStrictAdjacent &&
            !viewportInsideEpisode &&
            hasPreparedRunway(
                episodePath = episodePath,
                claimLive = claimLive,
                requiredRunwayPages = requiredRunwayPages,
                orderedAttachedSourceIndexes = orderedAttachedSourceIndexes,
                liveSourceIndexes = liveSourceIndexes,
                recoverableSourceIndexes = recoverableSourceIndexes,
            )
}

/**
 * Bounds exact decoded pixels after an adjacent chapter becomes the physical foreground. The
 * source actor may already own every encoded body, but Surface only needs a small source runway
 * beyond the source page currently under the user's finger. A viewport event wakes the parked
 * owner as that frontier advances, so this limits residency without turning the suffix into a
 * timer-driven or partially drawable list.
 */
internal object NtkStrictAdjacentProgressiveRunwayPolicy {
    /**
     * The first source is the complete offscreen contract: it lets the user cross the boundary
     * without changing the predecessor's page table again. Sources after p0 stay encoded and
     * private until the physical viewport has actually entered the episode. Even after entry,
     * publication waits for the current touch/fling ownership interval to retire.
     */
    fun shouldParkIncompleteInitialTail(
        viewportInsideEpisode: Boolean,
        foregroundMotionActive: Boolean,
        physicalScrollEverStarted: Boolean,
    ): Boolean = physicalScrollEverStarted &&
        (!viewportInsideEpisode || foregroundMotionActive)

    fun shouldPark(
        viewportInsideEpisode: Boolean,
        foregroundMotionActive: Boolean,
        currentSourceIndex: Int,
        firstMissingSourceIndex: Int,
        forwardSourceRunway: Int,
    ): Boolean {
        if (!viewportInsideEpisode || firstMissingSourceIndex < 0 || forwardSourceRunway <= 0) {
            return false
        }
        // The source is already the physical foreground and every suffix body remains bound to
        // the exact manifest. Once real touch/fling has retired, completing those immutable pixels
        // prevents the next gesture from inheriting network/decode/publication work and guarantees
        // that a user who pauses can resume through the complete chapter. During actual motion,
        // however, even a page inside the forward runway must remain parked: Bitmap decode and
        // host-buffer acquisition are non-preemptible and can otherwise resume from pool pressure
        // directly inside the next frame interval. The already attached runway remains scrollable;
        // the next idle edge advances it one exact source cohort at a time.
        if (!foregroundMotionActive) return false
        // An actual-frame signal can precede the coalesced WindowEvent that resolves the new
        // chapter's first PageRef. Keep the installed p0..p3 runway stable for that brief handoff
        // instead of interpreting a stale predecessor anchor as permission to publish all.
        if (currentSourceIndex < 0) return true
        return firstMissingSourceIndex > currentSourceIndex
    }
}

/** Single decoded-pixel admission contract shared by every direct-Wi-Fi adjacent call path. */
internal object NtkDirectAdjacentPixelAdmissionPolicy {
    fun shouldDefer(
        viewportInsideEpisode: Boolean,
        sourceIndex: Int,
        currentSourceIndex: Int,
        physicalIntent: Boolean,
        foregroundMotionActive: Boolean,
        idleForwardRunway: Int,
    ): Boolean {
        if (sourceIndex < 0 || idleForwardRunway < 0) return true
        // Surface reports only the first incomplete page that physically clamps a real forward
        // gesture.  Trust exactly one source beyond the highest authoritative drawable already
        // installed in that physical window, even during the brief transition-card/p0 interval
        // before episode metadata ownership catches up.  Requiring viewportInsideEpisode first
        // made p1 wait for the episode switch while the switch waited for forward progress past
        // p1.  The one-source bound still rejects a distant placeholder and cannot open a suffix
        // decode wave.
        if (physicalIntent &&
            sourceIndex <= (currentSourceIndex + 1).coerceAtLeast(0)
        ) return false
        // Only p0 is required to cross an offscreen chapter boundary. p1 and later stay as exact
        // encoded bodies until the chapter becomes physical; writing their HostExact mirrors while
        // the predecessor is moving takes the emulator gfxstream lock away from the display thread.
        // Alternate p0 paths also honor this motion gate; the sparse p0 owner has its own longer
        // pointer-quiet admission before promotion.
        if (!viewportInsideEpisode) return sourceIndex > 0 || foregroundMotionActive
        // A Surface intent may cover several placeholder pages when exact geometry is still being
        // appended. Only the next source in reading order is a real blocker; letting a distant
        // placeholder (for example p8 while p0 is absent) bypass the gate recreates the whole
        // offscreen GPU-write wave under the predecessor gesture.
        if (currentSourceIndex < 0 || sourceIndex > currentSourceIndex + idleForwardRunway) {
            return true
        }
        // Near-forward pixels may fill only after the current gesture/fling becomes quiet.
        return foregroundMotionActive
    }
}

/**
 * Resolves source progress for an exact adjacent episode without requiring the pixels which are
 * currently being repaired to already be installed. A previously presented, identity-bound
 * physical anchor is valid progress after pressure/rolling eviction; an unproven placeholder is
 * represented by -1 and remains unable to widen the decode frontier.
 */
internal object NtkDirectAdjacentViewportSourcePolicy {
    fun resolve(
        installedPhysicalSource: Int,
        installedBoundarySource: Int,
        previouslyPresentedPhysicalAnchorSource: Int,
    ): Int = maxOf(
        installedPhysicalSource,
        installedBoundarySource,
        previouslyPresentedPhysicalAnchorSource,
    )
}

/** Exact identity gate for the event-owned remainder of a strict adjacent episode. */
internal object NtkStrictRemainingAdjacentDescriptorWaitPolicy {
    data class PageIdentity(
        val normalizedEpisodePath: String,
        val sourceIndex: Int,
        val manifestDigest: String,
        val manifestPageCount: Int,
        val canonicalAsset: String,
    )

    fun shouldOwnWait(
        sourceEventChannelBound: Boolean,
        claimLive: Boolean,
        claimPath: String,
        claimManifestDigest: String,
        claimRevision: Long,
        authoritativePath: String,
        authoritativeManifestDigest: String,
        authoritativeRevision: Long,
        authoritativeAssets: List<String>,
        pages: List<PageIdentity>,
    ): Boolean {
        if (!sourceEventChannelBound || !claimLive || pages.isEmpty() ||
            claimRevision <= 0L || !NtkStripDigests.isSha256(claimManifestDigest) ||
            (!claimPath.startsWith("/manhwa/") && !claimPath.startsWith("/webtoon/")) ||
            authoritativeAssets.isEmpty()
        ) {
            return false
        }
        if (authoritativePath != claimPath ||
            authoritativeManifestDigest != claimManifestDigest ||
            authoritativeRevision != claimRevision
        ) {
            return false
        }
        return pages.all { page ->
            page.normalizedEpisodePath == claimPath &&
                page.sourceIndex in authoritativeAssets.indices &&
                page.manifestDigest == claimManifestDigest &&
                page.manifestPageCount == authoritativeAssets.size &&
                page.canonicalAsset == authoritativeAssets[page.sourceIndex]
        }
    }

    fun requiresNativeExactBatch(
        descriptorWaitOwned: Boolean,
        normalizedEpisodePath: String,
    ): Boolean = descriptorWaitOwned &&
        (normalizedEpisodePath.startsWith("/webtoon/") ||
            normalizedEpisodePath.startsWith("/manhwa/"))
}

/** One terminal decision for a generation-bound suffix wait that receives no source event. */
internal object NtkStrictRemainingAdjacentWatchdogPolicy {
    enum class Decision {
        NONE,
        WAKE,
        REARM_AFTER_PROGRESS,
        INVALIDATE_AND_WAKE,
    }

    fun decide(
        cancelled: Boolean,
        bindingCurrent: Boolean,
        waiterPresent: Boolean,
        claimLive: Boolean,
        descriptorReadyOrIdentityChanged: Boolean,
        sourceProgressed: Boolean,
        sourceCallsActive: Boolean,
    ): Decision = when {
        cancelled || !bindingCurrent || !waiterPresent -> Decision.NONE
        descriptorReadyOrIdentityChanged || !claimLive -> Decision.WAKE
        // An active OkHttp body can be receiving bytes without changing the topology-only
        // snapshot (started/adopted/active counts). Its per-call read timeout owns that terminal
        // edge; retiring the whole generation here cancels healthy slow bodies just before their
        // normal attempt completes.
        sourceProgressed || sourceCallsActive -> Decision.REARM_AFTER_PROGRESS
        else -> Decision.INVALIDATE_AND_WAKE
    }
}

/** Resolves in-flight source ownership without trusting an actor-published stale debug view. */
internal object NtkStrictDescriptorWaitProgressPolicy {
    fun activeCalls(
        cachedQuarantineCalls: Int,
        liveQuarantineCalls: Int?,
        exactCalls: Int,
        unresolvedStreamedExactBodies: Int,
    ): Int {
        require(cachedQuarantineCalls >= 0)
        require(liveQuarantineCalls == null || liveQuarantineCalls >= 0)
        require(exactCalls >= 0)
        require(unresolvedStreamedExactBodies >= 0)
        val quarantineCalls = liveQuarantineCalls ?: cachedQuarantineCalls
        return (quarantineCalls.toLong() + exactCalls.toLong() +
            unresolvedStreamedExactBodies.toLong())
            .coerceAtMost(Int.MAX_VALUE.toLong())
            .toInt()
    }
}

/** Preserves a recovery deadline across lifecycle/event wakes instead of restarting its clock. */
internal object NtkStrictRecoveryBindDeadlinePolicy {
    fun remainingDelayMs(
        nowMs: Long,
        lastRecoveryRequestAtMs: Long,
        lastDeadlineFireAtMs: Long,
        intervalMs: Long = NtkAdjacentStrictClaimRecoveryPolicy.REQUEST_RETRY_MS,
    ): Long {
        require(nowMs >= 0L)
        require(lastRecoveryRequestAtMs >= 0L)
        require(lastDeadlineFireAtMs >= 0L)
        require(intervalMs > 0L)
        val epoch = maxOf(lastRecoveryRequestAtMs, lastDeadlineFireAtMs)
        if (epoch <= 0L) return intervalMs
        return (intervalMs - (nowMs - epoch).coerceAtLeast(0L)).coerceAtLeast(1L)
    }
}

/** One running owner plus one retained event edge per exact adjacent path. */
internal class NtkPathEventWakeLatch {
    private val lock = Any()
    private val inFlight = HashSet<String>()
    private val pending = HashSet<String>()

    fun tryAcquire(path: String): Boolean = synchronized(lock) {
        if (path.isEmpty()) return@synchronized false
        if (inFlight.add(path)) {
            true
        } else {
            pending.add(path)
            false
        }
    }

    /** Returns true when an event raced the prior owner and must acquire a fresh turn. */
    fun release(path: String): Boolean = synchronized(lock) {
        inFlight.remove(path)
        pending.remove(path)
    }

    fun cancel(path: String) = synchronized(lock) {
        inFlight.remove(path)
        pending.remove(path)
        Unit
    }

    fun clear() = synchronized(lock) {
        inFlight.clear()
        pending.clear()
    }
}

/** Atomically binds one delayed callback and its dedupe key to each exact episode path. */
internal class NtkPathScheduledRetryRegistry<T : Any> {
    class Owner<T : Any> internal constructor(
        val path: String,
        val retryKey: String,
        val token: T,
    )

    data class Registration<T : Any>(
        val owner: Owner<T>,
        val replaced: Owner<T>?,
    )

    private val lock = Any()
    private val retryKeys = HashSet<String>()
    private val owners = HashMap<String, Owner<T>>()

    fun register(path: String, retryKey: String, token: T): Registration<T>? =
        synchronized(lock) {
            if (path.isEmpty() || retryKey.isEmpty() || !retryKeys.add(retryKey)) {
                return@synchronized null
            }
            val owner = Owner(path, retryKey, token)
            val replaced = owners.put(path, owner)
            if (replaced != null && replaced.retryKey != retryKey) {
                retryKeys.remove(replaced.retryKey)
            }
            Registration(owner, replaced)
        }

    /** Returns true exactly once for the newest path owner. */
    fun claim(owner: Owner<T>): Boolean = synchronized(lock) {
        val current = owners[owner.path]
        if (current !== owner) {
            // A replacement may have reused this exact key after retiring the old owner. Never
            // let the stale callback erase that ABA-new reservation.
            if (current?.retryKey != owner.retryKey) retryKeys.remove(owner.retryKey)
            return@synchronized false
        }
        owners.remove(owner.path)
        retryKeys.remove(owner.retryKey)
        true
    }

    fun cancel(owner: Owner<T>): Boolean = synchronized(lock) {
        val current = owners[owner.path]
        if (current !== owner) {
            if (current?.retryKey != owner.retryKey) retryKeys.remove(owner.retryKey)
            return@synchronized false
        }
        owners.remove(owner.path)
        retryKeys.remove(owner.retryKey)
        true
    }

    fun cancelPath(path: String): Owner<T>? = synchronized(lock) {
        owners.remove(path)?.also { owner -> retryKeys.remove(owner.retryKey) }
    }

    fun clear(): List<Owner<T>> = synchronized(lock) {
        val removed = owners.values.toList()
        owners.clear()
        retryKeys.clear()
        removed
    }

    internal fun hasRetryKey(retryKey: String): Boolean = synchronized(lock) {
        retryKey in retryKeys
    }

    internal fun ownerCount(): Int = synchronized(lock) { owners.size }
}

/** Fail closed for the emulator-only exact manhwa runway unless its live descriptor owns the page. */
internal object NtkAdjacentRunwayBodyAuthorityPolicy {
    fun isPublishable(
        strictManifestAuthority: Boolean,
        descriptorReady: Boolean,
        strictBodyReady: Boolean,
        genericCacheReady: Boolean,
    ): Boolean = descriptorReady ||
        (!strictManifestAuthority && (strictBodyReady || genericCacheReady))

    fun mayConsumeUnprovenPreparedOrGenericCache(strictManifestAuthority: Boolean): Boolean =
        !strictManifestAuthority
}

internal object NtkWifiAdjacentCascadePolicy {
    // The first next episode is prepared from the initial episode. Once the reader has crossed
    // that boundary, page five remains the demand signal only while the new episode is unfinished.
    // A fully drawable B has no remaining foreground image/decode work to protect, so B -> C must
    // start immediately even when the boundary lands on B page four. Otherwise a reader can reach
    // B's tail before the exact C runway exists despite having already paid B's complete workload.
    const val MIN_ACTIVE_SOURCE_PAGE_INDEX = 4

    fun shouldStart(
        wifiTransportActive: Boolean,
        initialEpisode: Boolean,
        directWifiCurrentEpisodeComplete: Boolean = false,
        activeSourcePageIndex: Int,
    ): Boolean =
        !wifiTransportActive ||
            initialEpisode ||
            directWifiCurrentEpisodeComplete ||
            activeSourcePageIndex >= MIN_ACTIVE_SOURCE_PAGE_INDEX
}

/**
 * Fail-closed completion proof for one continuously appended episode.
 *
 * A four-page runway is deliberately smaller than the authoritative episode. It must never be
 * mistaken for a complete episode when manifest metadata is missing, duplicated, or out of order.
 */
internal object NtkCompletedForwardEpisodePolicy {
    fun isComplete(
        authoritativeCount: Int,
        sourceIndexes: List<Int>,
        drawableReady: List<Boolean>,
        requiredFirstSource: Int = 0,
    ): Boolean {
        if (authoritativeCount <= 0 || sourceIndexes.isEmpty()) return false
        if (requiredFirstSource !in 0 until authoritativeCount) return false
        if (sourceIndexes.size != drawableReady.size) return false
        // Auto-cut can expose both display halves of one exact source image. Both halves must be
        // drawable, but canonical completeness is the ordered distinct source coverage.
        if (sourceIndexes.distinct() != (0 until authoritativeCount).toList()) return false
        return sourceIndexes.indices.all { index ->
            sourceIndexes[index] < requiredFirstSource || drawableReady[index]
        }
    }
}

internal object NtkDirectWifiAdjacentRunwayTailHandoffPolicy {
    fun shouldOwnWait(
        cancelled: Boolean,
        directWifiStrictAdjacent: Boolean,
        episodePath: String,
        requiredRunwayPageCount: Int,
        installedSourceIndexes: Set<Int>,
    ): Boolean {
        if (cancelled || !directWifiStrictAdjacent) return false
        if (!episodePath.startsWith("/webtoon/") && !episodePath.startsWith("/manhwa/")) {
            return false
        }
        if (requiredRunwayPageCount <= 1) return false
        val installedCount = installedSourceIndexes.size
        if (installedCount !in 1 until requiredRunwayPageCount) return false
        return installedSourceIndexes == (0 until installedCount).toSet()
    }

    fun shouldHandoff(
        cancelled: Boolean,
        directWifiStrictAdjacent: Boolean,
        episodePath: String,
        requiredRunwayPageCount: Int,
        installedSourceIndexes: Set<Int>,
        firstReadySourceIndex: Int,
    ): Boolean {
        if (!shouldOwnWait(
                cancelled,
                directWifiStrictAdjacent,
                episodePath,
                requiredRunwayPageCount,
                installedSourceIndexes,
            )
        ) return false
        val installedCount = installedSourceIndexes.size
        return firstReadySourceIndex == installedCount &&
            firstReadySourceIndex in 1 until requiredRunwayPageCount
    }
}

/**
 * Tall webtoon p1..p3 remain one native publication unit. Manhwa originals are much larger and
 * are published one source cohort at a time; batching four of them made a background decode hold
 * an emulator CPU for 180-240 ms during the predecessor's final physical scroll.
 */
internal object NtkDirectWifiAdjacentAtomicRunwayTailPolicy {
    fun requiredReadyCount(
        directWifiStrictAdjacent: Boolean,
        episodePath: String,
        requiredRunwayPageCount: Int,
        installedSourceIndexes: Set<Int>,
    ): Int {
        if (!NtkDirectWifiAdjacentRunwayTailHandoffPolicy.shouldOwnWait(
                cancelled = false,
                directWifiStrictAdjacent = directWifiStrictAdjacent,
                episodePath = episodePath,
                requiredRunwayPageCount = requiredRunwayPageCount,
                installedSourceIndexes = installedSourceIndexes,
            )
        ) return 1
        if (episodePath.startsWith("/manhwa/")) return 1
        return requiredRunwayPageCount - installedSourceIndexes.size
    }
}

/** Converts a canonical source-page cohort into its complete display-ref prefix. */
internal object NtkAdjacentRunwaySourceCohortPolicy {
    fun leadingRefCount(
        sourceIndexes: List<Int>,
        requiredSourceCount: Int,
    ): Int {
        if (sourceIndexes.isEmpty() || requiredSourceCount <= 0) return 0
        var sourceCount = 0
        var previousSource = -1
        var refsInCurrentSource = 0
        sourceIndexes.forEachIndexed { index, sourceIndex ->
            if (sourceIndex < 0) return 0
            if (index == 0 || sourceIndex != previousSource) {
                if (sourceCount == requiredSourceCount) return index
                if (index > 0 && sourceIndex != previousSource + 1) return 0
                sourceCount++
                refsInCurrentSource = 1
            } else {
                refsInCurrentSource++
                if (refsInCurrentSource > 2) return 0
            }
            previousSource = sourceIndex
        }
        return sourceIndexes.size.takeIf { sourceCount == requiredSourceCount } ?: 0
    }
}

/**
 * Publishes exactly the complete source-p0 display cohort. A source may have two auto-cut display
 * refs, so it must remain atomic, but resident p1..pN are intentionally paced by the ordered tail
 * publisher instead of being decoded in one long frame-hostile burst.
 */
internal object NtkDirectWifiAdjacentInitialAtomicRunwayPolicy {
    fun attachedImagePageCount(
        directWifiStrictAdjacent: Boolean,
        episodePath: String,
        sourceIndexes: List<Int>,
        publishable: List<Boolean>,
        maximumRunwayPages: Int,
        strictExactDescriptorOnly: Boolean = false,
        sourceSides: List<Int> = emptyList(),
    ): Int {
        if (!directWifiStrictAdjacent || !episodePath.startsWith("/manhwa/") ||
            sourceIndexes.isEmpty() || sourceIndexes.size != publishable.size ||
            maximumRunwayPages <= 0
        ) return 1
        val availableSourceCount = sourceIndexes.distinct().size
        val requiredSourceCount = minOf(maximumRunwayPages, availableSourceCount)
        val requiredRefCount = NtkAdjacentRunwaySourceCohortPolicy.leadingRefCount(
            sourceIndexes,
            requiredSourceCount,
        )
        if (requiredRefCount <= 0) return if (strictExactDescriptorOnly) 0 else 1
        val exactPrefix = sourceIndexes.take(requiredRefCount) ==
            (0 until requiredSourceCount).toList()
        val exactPageRefPrefix = if (strictExactDescriptorOnly) {
            isExactPageRefPrefix(
                sourceIndexes.take(requiredRefCount),
                sourceSides.take(requiredRefCount),
            )
        } else {
            exactPrefix
        }
        val exactLeadingSourceRefCount = if (exactPageRefPrefix) {
            NtkAdjacentRunwaySourceCohortPolicy.leadingRefCount(
                sourceIndexes.take(requiredRefCount),
                requiredSourceCount = 1,
            )
        } else {
            0
        }
        return when {
            exactLeadingSourceRefCount > 0 &&
                publishable.take(exactLeadingSourceRefCount).all { it } ->
                exactLeadingSourceRefCount
            strictExactDescriptorOnly -> 0
            else -> 1
        }
    }

    private fun isExactPageRefPrefix(
        sourceIndexes: List<Int>,
        sourceSides: List<Int>,
    ): Boolean {
        if (sourceIndexes.isEmpty() || sourceIndexes.size != sourceSides.size ||
            sourceIndexes.first() != 0 || sourceSides.first() != 0
        ) return false
        for (index in 1 until sourceIndexes.size) {
            val previousSource = sourceIndexes[index - 1]
            val source = sourceIndexes[index]
            val side = sourceSides[index]
            when {
                source == previousSource -> {
                    if (sourceSides[index - 1] != 0 || side != 1) return false
                }
                source == previousSource + 1 -> {
                    if (side != 0) return false
                }
                else -> return false
            }
        }
        return true
    }
}

/** Keeps opaque/decreasing episode ids ordered by an exact live strict-adjacent claim only. */
internal object NtkDirectWifiStrictAdjacentOrderPolicy {
    fun shouldSkipNumericIdFallback(
        directWifiStrictAdjacentTransport: Boolean,
        currentTailEpisodePath: String?,
        targetEpisodePath: String?,
        exactClaimTargetEpisodePath: String?,
        exactClaimPredecessorEpisodePath: String?,
        exactClaimLive: Boolean,
        maxExistingEpisodeId: Long?,
        targetEpisodeId: Long,
    ): Boolean {
        val currentTailPath = NtkStripDigests.normalizeEpisodePath(
            currentTailEpisodePath.orEmpty(),
        )
        val targetPath = NtkStripDigests.normalizeEpisodePath(targetEpisodePath.orEmpty())
        val claimTargetPath = NtkStripDigests.normalizeEpisodePath(
            exactClaimTargetEpisodePath.orEmpty(),
        )
        val claimPredecessorPath = NtkStripDigests.normalizeEpisodePath(
            exactClaimPredecessorEpisodePath.orEmpty(),
        )
        val exactLiveSuccessor = directWifiStrictAdjacentTransport &&
            exactClaimLive &&
            currentTailPath.isNotEmpty() &&
            targetPath.isNotEmpty() &&
            targetPath == claimTargetPath &&
            currentTailPath == claimPredecessorPath &&
            currentTailPath != targetPath
        if (exactLiveSuccessor) return false
        return maxExistingEpisodeId != null && targetEpisodeId <= maxExistingEpisodeId
    }
}

/**
 * One coherent bitmap-admission decision.  Viewport anchor, input direction and retained bounds
 * are produced at different points in a window transaction; publishing those mutable fields
 * independently let a decode worker combine a new anchor with an old retained range.  The worker
 * now consumes this immutable final range or fails closed until the current structure publishes
 * another snapshot.
 */
internal data class NtkProtectedBitmapWindowSnapshot(
    val revision: Long,
    val sourceGeneration: Int,
    val structureGeneration: Int,
    val pageCount: Int,
    val anchor: Int,
    val direction: Int,
    val first: Int,
    val last: Int,
)

internal object NtkProtectedBitmapWindowSnapshotPolicy {
    fun isCurrent(
        snapshot: NtkProtectedBitmapWindowSnapshot?,
        revision: Long,
        structureGeneration: Int,
        pageCount: Int,
    ): Boolean = snapshot != null &&
        snapshot.revision == revision &&
        snapshot.structureGeneration == structureGeneration &&
        // Appending a successor runway does not renumber any index covered by the already
        // published window.  Requiring exact page-count equality made every progressive tail
        // append invalidate that window even though indexedStateGeneration deliberately remains
        // unchanged.  Prefix insertion/removal and compaction still fail closed because they
        // advance structureGeneration; shrinking below the published table also remains invalid.
        pageCount >= snapshot.pageCount &&
        snapshot.pageCount > 0 &&
        snapshot.first >= 0 &&
        snapshot.last in snapshot.first until snapshot.pageCount

    fun admits(
        snapshot: NtkProtectedBitmapWindowSnapshot?,
        revision: Long,
        structureGeneration: Int,
        pageCount: Int,
        index: Int,
    ): Boolean = isCurrent(snapshot, revision, structureGeneration, pageCount) &&
        index in snapshot!!.first..snapshot.last
}

/** Keeps strict source admission and the first drawable/decode anchor on the same resume page. */
internal object NtkStrictResumeAnchorPolicy {
    fun resolve(
        strictExact: Boolean,
        startAtFirstPage: Boolean,
        strictSourceFloor: Int,
        storedPage: Int,
    ): Int {
        if (startAtFirstPage) return 0
        // The generation-owned discovery floor is the page whose byte source was admitted. If it
        // is non-zero, using an older preference value as the UI/decode anchor makes every
        // admitted follower wait for an excluded p0 forever. A zero floor cannot distinguish a
        // genuine p0 resume from missing registry state, so preserve the stored fallback there.
        return if (strictExact && strictSourceFloor > 0) {
            strictSourceFloor
        } else {
            storedPage.coerceAtLeast(0)
        }
    }
}

/**
 * Binds the opening decode owner to the immutable launch source rather than transient UI motion.
 * A swipe can move the reported page before any pixels exist; that must not turn a follower into
 * the anchor or make the real launch source wait on its own installation latch.
 */
internal object NtkStrictLaunchDecodeAnchorPolicy {
    fun resolve(
        initialRunwayDecode: Boolean,
        sourceIndex: Int,
        launchSourceIndex: Int,
        requestedAnchor: Boolean,
    ): Boolean = if (initialRunwayDecode && launchSourceIndex >= 0) {
        sourceIndex == launchSourceIndex
    } else {
        requestedAnchor
    }
}

class ReaderSession(
    private val context: Context,
    private val manga: Manga,
    private val title: Title?,
    private val viewerWidth: Int,
    private val viewerHeight: Int,
    private val autoCut: Boolean,
    private val reverse: Boolean,
    preparedKey: String?,
    private val startAtFirstPage: Boolean = false,
    private val listener: Listener,
    private val imageRepository: ReaderImageRepository = LegacyReaderImageRepository,
    /**
     * Non-null only when the inline controller already owns the exact, physically validated
     * viewport + forward runway lease for this same episode and surface dimensions.
     */
    private val preparedLaunchRunwaySpec: ReaderPreparedStore.LaunchRunwaySpec? = null,
    private val pagePipeline: ReaderPagePipeline? = null,
    /** Exact NTK cold-entry policy with a forward-only byte and decode runway. */
    private val strictExactLaunchSeal: StrictExactLaunchSeal? = null
) {
    private val strictExactColdRolling: Boolean = strictExactLaunchSeal != null
    /**
     * Legacy saved titles can lack sourceSite. Resolve that fallback once for this reader instead
     * of consulting the mutable home-screen HTTP client on every policy check. A site switch while
     * the reader is open must never turn the same episode from WFWF into NTK (or vice versa).
     */
    private val legacyBlankSourceNtkAtCreation: Boolean = runCatching {
        MainApplication.getHttpClient().isNtk
    }.getOrDefault(false)
    private val initialNtkEpisodePath = manga.ntkEpisodePath?.trim().orEmpty()
    private val strictExactViewerOwnerEpisodePathAtCreation =
        NtkStripDigests.normalizeEpisodePath(
            strictExactLaunchSeal?.normalizedEpisodePath.orEmpty()
                .ifBlank { initialNtkEpisodePath },
        )
    private val strictExactForegroundViewerGenerationAtCreation: Long = run {
        val generation = ViewerTelemetry.activeGeneration()
        if (strictExactLaunchSeal != null &&
            generation > 0L &&
            ViewerTelemetry.isActiveViewer(
                generation,
                strictExactViewerOwnerEpisodePathAtCreation,
            )
        ) {
            generation
        } else {
            0L
        }
    }
    private val strictForwardSourceFloor: Int = strictExactLaunchSeal?.let { seal ->
        if (!startAtFirstPage && strictExactForegroundViewerGenerationAtCreation > 0L) {
            NtkSourceSpoolRegistry.currentInitialPageIndex(
                seal.normalizedEpisodePath,
                strictExactForegroundViewerGenerationAtCreation,
            ).coerceIn(0, seal.pageCount - 1)
        } else {
            0
        }
    } ?: 0
    /**
     * The launch floor above is immutable resume evidence. This runtime floor can only move toward
     * earlier sources after the Activity proves a busy physical reverse offset. Keeping the two
     * values separate prevents layout/restore callbacks from silently changing launch semantics.
     */
    private val strictActiveSourceFloor = AtomicInteger(strictForwardSourceFloor)
    /** False once this Session's launch display indexes are shifted or split; never reopens. */
    private val strictForwardSuffixLaunchShapeValid = AtomicBoolean(true)
    enum class InitialPrerenderResult {
        NOT_RENDERED,
        RENDERED_ONLY,
        RENDERED_AND_COMMIT
    }

    interface Listener {
        fun onPagesReady(count: Int)
        fun onPagesAppended(count: Int)
        /**
         * Publishes a page-table suffix whose decoded drawables are committed in the same main
         * loop turn. The receiver must not defer the structure behind input quiet: doing so makes
         * the following identity-qualified drawable callbacks target pages that do not exist yet.
         */
        fun onPreparedAdjacentPagesAppended(count: Int) = onPagesAppended(count)
        fun onPagesPrepended(count: Int, insertedCount: Int, holdUntilReadyCount: Int = 0)
        fun onPagesRemoved(startIndex: Int, removedCount: Int, totalCount: Int)
        fun onInitialPage(index: Int)
        fun onPageLoading(index: Int)
        fun onPageBoundsReady(index: Int, width: Int, height: Int)
        fun onPageReady(index: Int, bitmap: Bitmap)
        fun onPageProofReady(index: Int, bitmap: Bitmap) = onPageReady(index, bitmap)
        fun onPageTilesReady(index: Int, pageWidth: Int, pageHeight: Int, tiles: List<ReaderTile>)
        /**
         * Publishes a canonical decoded page to a non-visual, frame-paced install queue as soon
         * as decode completes. The normal delivery path still owns the bitmap lifetime and the
         * current viewport still decides when the page is attached to the physical Surface.
         */
        fun onPageDecodedRenderReady(
            index: Int,
            pageWidth: Int,
            pageHeight: Int,
            tiles: List<ReaderTile>
        ): Boolean = false
        /** True only after the Activity has adopted this generation and cleared any early queue. */
        fun isStrictAuthoritativeWorkerHandoffActive(): Boolean = false
        /**
         * Installs the immutable original-tile winner while preserving its source proof. This is
         * the only listener lane allowed to acknowledge a strict inline page as physically owned.
         */
        fun onPageAuthoritativeTilesReady(
            index: Int,
            sourceIndex: Int,
            pageWidth: Int,
            pageHeight: Int,
            tiles: List<ReaderTile>,
            proof: ReaderPreparedStore.PreparedOriginalProof
        ): Boolean = false
        fun onPageLaunchRunwayTilesReady(
            index: Int,
            pageWidth: Int,
            pageHeight: Int,
            tiles: List<ReaderTile>
        ) = onPageTilesReady(index, pageWidth, pageHeight, tiles)
        fun onPageProofTilesReady(index: Int, pageWidth: Int, pageHeight: Int, tiles: List<ReaderTile>) =
            onPageTilesReady(index, pageWidth, pageHeight, tiles)
        /** Atomic structure/card/identity plus exact p0 source-row head publication. */
        fun onAdjacentExactP0HeadReady(publication: NtkAdjacentExactP0HeadPublication): Boolean = false
        /** Completes the same immutable p0 owner without replacing its installed head resources. */
        fun onAdjacentExactP0TailReady(delta: NtkAdjacentExactP0Delta): Boolean = false
        /** Atomically installs a proved, contiguous p1-p3 batch under the same adjacent manifest. */
        fun onAdjacentExactRunwayBatchReady(
            publication: NtkAdjacentExactRunwayBatchPublication,
        ): Boolean = false
        fun isPageDrawableInstalled(index: Int): Boolean = false
        fun isExactPreparedStoreTilePageInstalled(
            index: Int,
            pageWidth: Int,
            pageHeight: Int,
            tiles: List<ReaderTile>
        ): Boolean = false
        /**
         * Narrower than [isPageDrawableInstalled]: legacy readers may have a preview installed
         * that still needs a full-width upgrade. Progressive inline readers return true only for
         * the canonical immutable full-quality tile winner.
         */
        fun isPageAuthoritativeDrawableInstalled(index: Int): Boolean = false
        fun isPageAuthoritativeDrawableInstalled(
            index: Int,
            pageWidth: Int,
            pageHeight: Int,
            tiles: List<ReaderTile>
        ): Boolean = isPageAuthoritativeDrawableInstalled(index)
        /**
         * Current Surface ownership only. Unlike [isPageAuthoritativeDrawableInstalled], this
         * must not include a queued or historically accepted Activity hand-off. Pixel retirement
         * can clear the Surface after that hand-off bit was recorded, and rehydration must then
         * be allowed to install the canonical body again.
         */
        fun isPageAuthoritativeDrawableCurrentlyInstalled(index: Int): Boolean =
            isPageAuthoritativeDrawableInstalled(index)
        fun isPageAuthoritativeDrawableCurrentlyInstalled(
            index: Int,
            pageWidth: Int,
            pageHeight: Int,
            tiles: List<ReaderTile>
        ): Boolean = isPageAuthoritativeDrawableCurrentlyInstalled(index)
        fun areAllAuthoritativeDrawablesInstalled(pageCount: Int): Boolean = false
        /** ABA-safe O(1) current-Surface proof for the immutable forward-resume source suffix. */
        fun currentStrictForwardSuffixProofRevision(
            episodePath: String,
            discoveryGeneration: Long,
            manifestDigest: String,
            pageCount: Int,
            firstSource: Int,
            lastSource: Int,
        ): Long = 0L
        /** Announces that only a multi-GiB scene will retain a bounded exact-pixel runway. */
        fun onStrictRollingHistoricalSceneActivated() {}
        fun onInitialPageDecoded(index: Int, bitmap: Bitmap): InitialPrerenderResult =
            InitialPrerenderResult.NOT_RENDERED

        fun onInitialPageTilesDecoded(
            index: Int,
            pageWidth: Int,
            pageHeight: Int,
            tiles: List<ReaderTile>
        ): InitialPrerenderResult = InitialPrerenderResult.NOT_RENDERED

        fun onInitialContinuousPageDecoded(index: Int, bitmap: Bitmap): InitialPrerenderResult =
            InitialPrerenderResult.NOT_RENDERED

        fun onInitialContinuousPageTilesDecoded(
            index: Int,
            pageWidth: Int,
            pageHeight: Int,
            tiles: List<ReaderTile>
        ): InitialPrerenderResult = InitialPrerenderResult.NOT_RENDERED
        /** Begins the renderer-only native twin while an adjacent card is still far offscreen. */
        fun onPageCardPreparationRequested(title: String) {}
        fun onPageCard(index: Int, title: String)
        fun onPageError(index: Int, message: String)
        /**
         * Reports that the immutable current-episode source exhausted its finite operation ledger.
         * The Activity may replace the source only for a transport failure and only after a real
         * unvalidated -> validated network edge; identity/integrity failures remain fail-closed.
         */
        fun onStrictExactSourceTerminal(
            episodePath: String,
            retryableTransport: Boolean,
        ) {}
        fun onPageCleared(index: Int)
        /**
         * Releases a far-offscreen pixel winner while retaining the proof that this canonical
         * page was decoded and installed once. The default preserves legacy listener behavior.
         */
        fun onPageRollingEvicted(index: Int) = onPageCleared(index)
        /**
         * Host exact-storage admission has already selected this page as reclaimable. Unlike an
         * ordinary rolling clear, a queued worker-to-main install for the same page must also be
         * retired or it can keep the pooled HardwareBuffer lease alive while the allocator waits.
         */
        fun onPageHostPressureRollingEvicted(index: Int) = onPageRollingEvicted(index)
        /**
         * Transfers terminal ownership of exact Session-owned identities after their visual
         * replacement/clear has been ordered. Returning false relinquishes explicit recycling;
         * the producer must leave native GlobalRefs/GC to finish safely rather than use a timer.
         */
        fun onSessionOwnedBitmapRetirement(bitmaps: List<Bitmap>): Boolean = false
        fun onMessage(message: String)
        fun onCaptchaRequired(manga: Manga)
        /**
         * Requests the exact ACK-owned manifest for one same-work forward neighbor. The Activity
         * remains the lifecycle owner; ReaderSession never opens an arbitrary pre-click flight.
         */
        fun onAdjacentExactManifestRequired(
            manga: Manga,
            predecessorEpisodePath: String,
        ) {}
        /**
         * Publishes the provider-validated predecessor/target claim before its prepared pixels can
         * reach the renderer. The claim revision and Activity generation gate make stale or ABA
         * Session notifications harmless.
         */
        fun onForwardAdjacentPathResolved(
            predecessorEpisodePath: String,
            targetEpisodePath: String,
            claimRevision: Long,
        ) {}
        fun onBoundaryAppendFinished(anchor: Int, direction: Int, silent: Boolean, suppressedCaptcha: Boolean)
    }

    enum class AppendStartResult {
        STARTED,
        BUSY,
        CANCELLED
    }

    data class PageInfo(
        val manga: Manga,
        val title: String,
        val localPage: Int,
        val totalPages: Int,
        val sourcePageIndex: Int,
        val side: Int,
        val layoutReady: Boolean,
        val transitionCard: Boolean
    )

    data class PageIdentity(
        val normalizedEpisodePath: String,
        val sourcePageIndex: Int,
        val canonicalAsset: String,
        val manifestDigest: String,
        val manifestPageCount: Int
    )

    private data class PageRef(
        val manga: Manga,
        var image: String?,
        val transitionTitle: String? = null,
        val sourceIndex: Int = 0,
        var pageIndex: Int = -1,
        val localPage: Int = 0,
        var totalPages: Int = 0,
        val side: Int = PAGE_SIDE_FIRST,
        val allowAutoSplit: Boolean = true,
        val manifestDigest: String = "",
        val manifestPageCount: Int = 0,
        // Immutable manifest identity. Transport refreshes are allowed to replace `image`, but
        // committed-frame validation must continue to compare the page against the asset that
        // produced manifestDigest. Kotlin data-class copy preserves this field when only the
        // transport URL changes.
        val canonicalAsset: String = NtkStripDigests.canonicalAsset(image.orEmpty())
    )

    /**
     * Identity-bound copy of the latest externally reported viewport. Numeric offsets are relative
     * to [anchorPage], so prefix compaction can resolve the same physical viewport at its new index
     * instead of replaying an obsolete retained-window coordinate.
     */
    private data class ReportedWindow(
        val anchorPage: PageRef?,
        val fallbackAnchor: Int,
        val firstOffset: Int,
        val lastOffset: Int,
        val physicalFirstOffset: Int,
        val physicalLastOffset: Int,
        val busy: Boolean,
        val directionHint: Int,
    )

    /**
     * Immutable page identities from the last clean native frame that contained current-launch
     * bodies. Unlike reported layout coordinates, these cannot be widened by provisional heights
