    /**
     * Keeps the session's independently cancellable executors without constructing every
     * ThreadPoolExecutor and queue on the activity-launch path.  shutdown* is terminal even when
     * the delegate was never needed, so a late callback cannot recreate work after cancel().
     */
    private class LazySessionExecutor(private val factory: () -> ExecutorService) {
        private val lock = Any()

        @Volatile
        private var delegate: ExecutorService? = null

        @Volatile
        private var shutdown = false

        fun execute(command: Runnable) {
            executor().execute(command)
        }

        fun setCorePoolSize(size: Int): Boolean {
            require(size > 0)
            val pool = try {
                executor() as? ThreadPoolExecutor
            } catch (_: RejectedExecutionException) {
                null
            } ?: return false
            if (size > pool.maximumPoolSize || pool.isShutdown) return false
            return runCatching {
                pool.corePoolSize = size
                true
            }.getOrDefault(false)
        }

        /**
         * Removes the exact not-yet-started command without constructing a dormant executor.
         * Callers can then transfer the same Runnable (and therefore the same single-flight
         * ownership) to an urgent lane instead of starting a duplicate decode.
         */
        fun removeQueued(command: Runnable): Boolean {
            val pool = delegate as? ThreadPoolExecutor ?: return false
            if (pool.isShutdown) return false
            return pool.queue.remove(command)
        }

        fun shutdown() {
            val current = synchronized(lock) {
                shutdown = true
                delegate
            }
            current?.shutdown()
        }

        fun shutdownNow() {
            val current = synchronized(lock) {
                shutdown = true
                delegate
            }
            current?.shutdownNow()
        }

        private fun executor(): ExecutorService {
            delegate?.let { return it }
            return synchronized(lock) {
                if (shutdown) throw RejectedExecutionException("Reader session executor is shut down")
                delegate ?: factory().also { delegate = it }
            }
        }
    }

