    private val forwardAdjacentExactManifestSubscription = AtomicReference<Closeable?>()
    private val adjacentStrictRecoveryManifestSubscription = AtomicReference<Closeable?>()
    private val forwardAdjacentControlAfterBodiesResidentStarted = AtomicBoolean(false)
    private val adjacentStrictRecoveryStates = HashMap<String, AdjacentStrictRecoveryState>()
    private val consumedStrictSourcePaths = ConcurrentHashMap.newKeySet<String>()
    private val strictRequiredEpisodePathRetained = AtomicBoolean(false)
    private val strictExactEpisodeToken = strictExactLaunchSeal?.manifestSeal?.revision
        ?.takeIf { it > 0L }
        ?.let(::NtkEpisodeToken)
    private var earlyNtkImageUrlsUnregister: (() -> Unit)? = null
    private val nextLoading = AtomicBoolean(false)
    private val previousAppendLoading = AtomicBoolean(false)
    private val nextAppendLoading = AtomicBoolean(false)
    private val ntkGeneratedBatchUnavailablePaths = ConcurrentHashMap.newKeySet<String>()
    private val ntkInitialUnavailableReplacementStarted = AtomicBoolean(false)
    private val deferredGeneratedTailTrimKeys = ConcurrentHashMap.newKeySet<String>()
    private val ntkEpisodeMetadataLoading = AtomicBoolean(false)
    private val deferredAdjacentPrepareMailbox = NtkDeferredAdjacentPrepareMailbox()
    private val ntkAdjacentAfterAckReleaseAtMs = AtomicLong(0L)
    private val timelinePrimeLoading = AtomicBoolean(false)
    private val timelinePrimeRequested = AtomicBoolean(false)
    private val repositoryLoading = AtomicBoolean(false)
    private val repositoryCancellations = ConcurrentHashMap.newKeySet<MangaRepository.Cancellation>()
    private val windowLock = Object()
    private var lastWindowAnchor = -1
    private var lastWindowDirection = 0
    private var lastSourcePrefetchAnchor = -1
    private val strictRollingControlMailbox = StrictRollingControlMailbox()
    private val publishedWindowIngressGate = PublishedWindowIngressGate<Array<PageRef>>()
    /** Written only by the ReaderControl lane. Gaps are expected when latest-only events merge. */
    private var strictRollingLastAppliedControlSequence = 0L
    private val launchPreparedKey = preparedKey
    private val preparedEntry = preparedEntryForLaunch()
    private val preparedStoreKey = preparedEntry?.key ?: preparedKey
    // The Session can be constructed before the staging decoder publishes any tiles.  A frozen
    // snapshot (and especially maxOrNull on a sparse map) is therefore neither a physical
    // installation proof nor a safe runway watermark.  Refresh this only from the exact
    // contiguous Store identities that the listener confirms are installed.
    private val preparedLaunchDrawableLast = AtomicInteger(-1)
    private val preparedStoreDrawableLast = AtomicInteger(
        if (preparedLaunchRunwaySpec != null) {
            preparedEntry?.contiguousLaunchRunwayTileLast(preparedLaunchRunwaySpec)
                ?: -1
        } else {
            -1
        }
    )
    private val preparedPostActivationContinuationBase = AtomicInteger(-1)
    private val clearPreparedBitmapsRunnable = Runnable {
        val key = preparedStoreKey ?: return@Runnable
        if (!cancelled.get() && ReaderPreparedStore.get(key) === preparedEntry) {
            ReaderPreparedStore.clearBitmaps(key)
        }
    }
    private val deliveryDrainRunnable = Runnable { drainDecodeDeliveries() }
    private val pagesInstalled = AtomicBoolean(false)
    private val preparedListener = object : ReaderPreparedStore.Listener {
        override fun onUrlsReady(images: List<String>, startPage: Int) {
            if (!preparedImagesMatchCurrentEpisode(images)) {
                logNtkRepositoryStage(
                    manga,
                    "prepared_urls_rejected_episode_mismatch",
                    "count=${images.size},first=${images.firstOrNull()?.takeLast(96).orEmpty()}"
                )
                if (!pagesInstalled.get()) loadFromRepository()
                return
            }
            val resolvedStartPage = resolvePreparedStartPage(startPage)
            installImages(images, resolvedStartPage, false)
            flushEarlyPreparedBitmaps()
            releasePreparedStoreBitmapsSoon()
            val snapshot = preparedEntry?.snapshot()
            if (!hasCompletePreparedWindow(snapshot) &&
                !ReaderWarmupCoordinator.ownsKnownUrlsDecode(preparedStoreKey)
            ) {
                requestPageForeground(resolvedStartPage)
                requestInitialFanout(resolvedStartPage)
            }
        }

        override fun onBitmapReady(index: Int, bitmap: Bitmap) {
            if (!pagesInstalled.get()) {
                val snapshot = preparedEntry?.snapshot()
                val urls = snapshot?.images
                if (!urls.isNullOrEmpty()) {
                    if (!preparedSnapshotMatchesCurrentEpisode(snapshot)) {
                        logNtkRepositoryStage(
                            manga,
                            "prepared_bitmap_rejected_episode_mismatch",
                            "count=${urls.size},first=${urls.firstOrNull()?.takeLast(96).orEmpty()}"
                        )
                        if (!pagesInstalled.get()) loadFromRepository()
                        return
                    }
                    val resolvedStartPage = resolvePreparedStartPage(snapshot.startPage)
                    installImages(urls, resolvedStartPage, false)
                    ViewerWarmupManager.logMetric("reader_prepared_bitmap_installed_pages", 1L)
                    deliverPreparedSourceBitmap(index, bitmap)
                    flushEarlyPreparedBitmaps()
                    releasePreparedStoreBitmapsSoon()
                    if (!hasCompletePreparedWindow(snapshot) &&
                        !ReaderWarmupCoordinator.ownsKnownUrlsDecode(preparedStoreKey)
                    ) {
                        requestPageForeground(resolvedStartPage)
                        requestInitialFanout(resolvedStartPage)
                    }
                    return
                }
                if (!bitmap.isRecycled) earlyPreparedBitmaps[index] = bitmap
                return
            }
            deliverPreparedSourceBitmap(index, bitmap)
        }

        override fun onBitmapBatchReady(bitmaps: Map<Int, Bitmap>) {
            val snapshot = preparedEntry?.snapshot()
            val urls = snapshot?.images
            if (!pagesInstalled.get() && !urls.isNullOrEmpty()) {
                if (!preparedSnapshotMatchesCurrentEpisode(snapshot)) {
                    logNtkRepositoryStage(
                        manga,
                        "prepared_bitmap_batch_rejected_episode_mismatch",
                        "count=${urls.size},first=${urls.firstOrNull()?.takeLast(96).orEmpty()}"
                    )
                    loadFromRepository()
                    return
                }
                installImages(urls, resolvePreparedStartPage(snapshot.startPage), false)
            }
            for ((index, bitmap) in bitmaps) {
                if (!bitmap.isRecycled) deliverPreparedSourceBitmap(index, bitmap)
            }
            flushEarlyPreparedBitmaps()
            releasePreparedStoreBitmapsSoon()
            val startPage = snapshot?.let { resolvePreparedStartPage(it.startPage) } ?: 0
            if (!hasCompletePreparedWindow(snapshot) &&
                !ReaderWarmupCoordinator.ownsKnownUrlsDecode(preparedStoreKey)
            ) {
                requestPageForeground(startPage)
                requestInitialFanout(startPage)
            }
        }

        override fun onTilePageBatchReady(tilePages: Map<Int, ReaderPreparedStore.PreparedTilePage>) {
            val snapshot = preparedEntry?.snapshot()
            val urls = snapshot?.images
            if (!pagesInstalled.get() && !urls.isNullOrEmpty()) {
                if (!preparedSnapshotMatchesCurrentEpisode(snapshot)) {
                    logNtkRepositoryStage(
                        manga,
                        "prepared_tile_batch_rejected_episode_mismatch",
                        "count=${urls.size},first=${urls.firstOrNull()?.takeLast(96).orEmpty()}"
                    )
                    loadFromRepository()
                    return
                }
                installImages(urls, resolvePreparedStartPage(snapshot.startPage), false)
            }
            for ((index, tilePage) in tilePages) {
                deliverPreparedSourceTilePage(index, tilePage)
            }
            refreshPreparedStoreDrawableLast()
            schedulePreparedPostActivationContinuationIfNeeded()
            releasePreparedStoreBitmapsSoon()
            val startPage = snapshot?.let { resolvePreparedStartPage(it.startPage) } ?: 0
            if (!hasCompletePreparedWindow(snapshot) &&
                !ReaderWarmupCoordinator.ownsKnownUrlsDecode(preparedStoreKey)
            ) {
                requestPageForeground(startPage)
                requestInitialFanout(startPage)
            }
        }

        override fun onFailed() {
            if (!pagesInstalled.get()) loadFromRepository()
        }
    }

    fun start() {
        if (strictExactColdRolling) {
            startStrictExactColdSession()
            return
        }
        registerEarlyNtkImageUrlRefreshListener()
        val entry = preparedEntry
        if (entry != null) {
            val snapshot = entry.addListener(preparedListener)
            ViewerWarmupManager.logMetric(
                "reader_prepared_start_" + snapshot.status.name.lowercase(java.util.Locale.ROOT),
                snapshot.bitmaps.size.toLong()
            )
            if (installPreparedSnapshot(snapshot)) return
            if (snapshot.status != ReaderPreparedStore.Status.FAILED) {
                loadFromRepository()
                return
            }
        } else if (!preparedStoreKey.isNullOrEmpty()) {
            ViewerWarmupManager.logMetric("reader_prepared_start_missing", 1L)
        }
        val installedPreloadedEarlyUrls = installPreloadedEarlyNtkUrlsFromSessionStart()
        if (!installedPreloadedEarlyUrls) {
            schedulePreloadedEarlyNtkUrlsImmediateInstall()
        }
        scheduleImmediateNtkGeneratedInitialUrls()
        if (pagesInstalled.get()) return
        loadFromRepository()
    }

    /**
     * Fail-closed exact cold entry. No prepared Store, early URL mirror, generated descriptor or
     * repository state is consulted on this branch. The local per-episode bookmark is still the
     * user's requested viewport and must remain the initial source/decode/render anchor.
     */
    private fun startStrictExactColdSession() {
        val launchSeal = strictExactLaunchSeal ?: return
        val currentAuthority = NtkSourceSpoolRegistry.currentAuthoritativeManifest(
            launchSeal.normalizedEpisodePath
        )
        if (!launchSeal.matchesEpisodePath(manga.ntkEpisodePath) ||
            !launchSeal.hasSameAuthority(currentAuthority) ||
            manga.getImgs(null)?.map(NtkStripDigests::canonicalAsset) != launchSeal.canonicalAssets
        ) {
            failStrictExactColdSession("launch_seal_mismatch")
            return
        }
        if (strictRequiredEpisodePathRetained.compareAndSet(false, true) &&
            !ReaderImageCache.retainRequiredNtkEpisodePath(
                launchSeal.normalizedEpisodePath,
                "strict_exact_session"
            )
        ) {
            strictRequiredEpisodePathRetained.set(false)
            failStrictExactColdSession("required_path_retain_failed")
            return
        }
        val sourceTransport = NtkSourceSpoolRegistry.claim(
            launchSeal.normalizedEpisodePath,
            launchSeal.manifestDigest
        ) as? NtkStrictSourceTransport
        if (sourceTransport == null ||
            !NtkSourceSpoolRegistry.markClaimPhase(
                launchSeal.normalizedEpisodePath,
                launchSeal.manifestDigest,
                NtkManifestClaimPhase.BINDING
            )
        ) {
            (sourceTransport as? Closeable)?.close()
            failStrictExactColdSession("source_claim_failed")
            return
        }
        strictExactSourceTransport.set(sourceTransport)
        val episode = strictExactEpisodeToken ?: run {
            (sourceTransport as? Closeable)?.close()
            failStrictExactColdSession("invalid_episode_token")
            return
        }

        val installed = try {
            PerfTrace.begin("ViewerItemBind")
            manga.setImgs(ArrayList(launchSeal.canonicalAssets))
            manga.ntkImageCount = launchSeal.pageCount
            installImages(
                launchSeal.canonicalAssets,
                requestedStartPage(),
                requestInitialWindow = false
            )
        } finally {
            PerfTrace.end()
        }
        if (installed < 0) {
            (sourceTransport as? Closeable)?.close()
            failStrictExactColdSession("exact_install_failed")
            return
        }
        val installedSource = synchronized(pagesLock) {
            pages.getOrNull(installed)?.sourceIndex
        } ?: installed
        currentViewportAnchor.set(installed)
        val initialAdmission = StrictRollingAdmission.initial(
            launchSeal.pageCount,
            installedSource,
            strictForwardSourceFloor,
        )
        strictRollingAdmission.set(initialAdmission)
        // The product contract for this sealed episode is full-episode readiness, and the epoch-0
        // admission already owns every canonical source. Make that same immutable range physically
        // installable before the first body can finish; otherwise early offscreen originals are
        // parked in a primed backlog and decoded again only when scrolling reaches them.
        physicalDeliveryFirstPage = installed
        physicalDeliveryLastPage = synchronized(pagesLock) { pages.lastIndex }

        val residentBinding = try {
            sourceTransport.bindResidentBodies(
                episode,
                launchSeal.manifestSeal,
                NtkStrictResidentBodyListener(::onStrictExactResidentBody)
            )
        } catch (failure: Throwable) {
            (sourceTransport as? Closeable)?.close()
            failStrictExactColdSession("resident_bind_${failure.javaClass.simpleName}")
            return
        }
        strictExactResidentBodyBinding.set(residentBinding)
        val binding = try {
            sourceTransport.bindEpisode(
                episode,
                launchSeal.manifestSeal,
                installedSource,
                NtkSourceEventListener(::onStrictExactSourceEvent)
            )
        } catch (failure: Throwable) {
            strictExactResidentBodyBinding.getAndSet(null)?.close()
            (sourceTransport as? Closeable)?.close()
            failStrictExactColdSession("source_bind_${failure.javaClass.simpleName}")
            return
        }
        strictExactSourceBinding.set(binding)
        applyStrictExactSourceDemand(initialAdmission)
        for (sourceIndex in initialAdmission.allowedFirstSource..initialAdmission.allowedLastSource) {
            displayIndexesForStrictSource(sourceIndex).forEachIndexed { offset, displayIndex ->
                requestStrictExactSourcePage(
                    displayIndex,
                    anchor = sourceIndex == installedSource && offset == 0,
                    generation = 0
                )
            }
        }
        Log.d(
            TAG,
            "reader_ntk_strict_cold_started path=${launchSeal.normalizedEpisodePath}," +
                "manifestDigest=${launchSeal.manifestDigest},pages=${launchSeal.pageCount},demand=" +
                "${initialAdmission.allowedFirstSource}-${initialAdmission.allowedLastSource}"
        )
    }

    private fun failStrictExactColdSession(reason: String) {
        releaseStrictRequiredEpisodePath("strict_exact_fail:$reason")
        Log.e(TAG, "reader_ntk_strict_cold_fail_closed reason=$reason")
        main.post {
            if (!cancelled.get()) listener.onMessage("이미지 원본 확인에 실패했습니다.")
        }
    }

    private fun onStrictExactSourceEvent(event: SourceEvent) {
        if (cancelled.get()) return
        val launchSeal = strictExactLaunchSeal ?: return
        if (consumedStrictSourcePaths.contains(launchSeal.normalizedEpisodePath)) return
        when (event) {
            is SourceEvent.MetadataReady -> {
                val metadata = event.metadata
                val sourceIndex = metadata.pageIndex
                if (!launchSeal.matchesSource(sourceIndex, metadata.canonicalAsset) ||
                    metadata.manifestDigest != launchSeal.manifestDigest
                ) {
                    failStrictExactColdSession("metadata_identity_mismatch_$sourceIndex")
                    return
                }
                displayIndexesForStrictSource(sourceIndex).forEach { displayIndex ->
                    pageRef(displayIndex)?.let { page ->
                        postStrictExactPageBounds(
                            displayIndex,
                            page,
                            metadata.sourceWidth,
                            metadata.sourceHeight
                        )
                    }
                }
            }
            is SourceEvent.BodyPublished -> {
                acceptStrictExactBodyDescriptor(event.descriptor)
            }
            is SourceEvent.TerminalFailure -> {
                val retryableTransport =
                    NtkStrictSourceFailurePolicy.isRetryableTransportFailure(event.error)
                main.post {
                    if (!cancelled.get()) {
                        listener.onStrictExactSourceTerminal(
                            launchSeal.normalizedEpisodePath,
                            retryableTransport,
                        )
                    }
                }
                displayIndexesForStrictSource(event.pageIndex).forEach { displayIndex ->
                    pageRef(displayIndex)?.let { postPageError(displayIndex, it, event.error as? Exception
                        ?: java.io.IOException(event.error)) }
                }
            }
        }
    }

    private fun onStrictExactResidentBody(descriptor: NtkStrictBodyDescriptor) {
        if (cancelled.get()) return
        if (strictExactLaunchSeal?.normalizedEpisodePath?.let(consumedStrictSourcePaths::contains) == true) {
            return
        }
        acceptStrictExactBodyDescriptor(descriptor)
    }

    /** Thread-safe, idempotent render admission shared by the physical fast channel and ledger. */
    private fun acceptStrictExactBodyDescriptor(descriptor: NtkStrictBodyDescriptor) {
        val launchSeal = strictExactLaunchSeal ?: return
        val sourceIndex = descriptor.sourceKey.pageIndex
        if (!launchSeal.matchesSource(sourceIndex, descriptor.metadata.canonicalAsset) ||
            descriptor.sourceKey.manifestDigest != launchSeal.manifestDigest ||
            descriptor.sourceKey.canonicalAssetDigest !=
            NtkStripDigests.canonicalAssetDigestSha256(
                launchSeal.canonicalAssets.getOrNull(sourceIndex).orEmpty()
            )
        ) {
            failStrictExactColdSession("body_identity_mismatch_$sourceIndex")
            return
        }
        val existing = strictExactBodyDescriptors.putIfAbsent(sourceIndex, descriptor)
        if (existing != null) {
            if (existing.sourceKey != descriptor.sourceKey ||
                existing.metadata != descriptor.metadata ||
                existing.proof != descriptor.proof
            ) failStrictExactColdSession("body_descriptor_mutation_$sourceIndex")
            return
        }
        val sourceRgbaBytes = descriptor.metadata.sourceWidth.toLong()
            .coerceAtLeast(1L)
            .let { width ->
                val height = descriptor.metadata.sourceHeight.toLong().coerceAtLeast(1L)
                if (width > Long.MAX_VALUE / 4L || height > Long.MAX_VALUE / (width * 4L)) {
                    Long.MAX_VALUE
                } else {
                    width * height * 4L
                }
            }
        strictExactRequiredBitmapBytes.updateAndGet { current ->
            if (sourceRgbaBytes == Long.MAX_VALUE || current > Long.MAX_VALUE - sourceRgbaBytes) {
                Long.MAX_VALUE
            } else {
                current + sourceRgbaBytes
            }
        }
        val directWifiCurrentEpisode =
            isNtkManhwaOrWebtoonEpisodePath(launchSeal.normalizedEpisodePath) &&
                NtkSourceSpoolRegistry.isCurrentDirectWifiRendererProfile(
                    launchSeal.normalizedEpisodePath,
                    strictExactForegroundViewerGenerationAtCreation,
                ) &&
                isStrictExactCurrentForegroundEpisode()
        if (ReaderExactDecodeStoragePolicy.useBoundedRollingResidency(
                launchSeal.normalizedEpisodePath,
                launchSeal.pageCount,
                descriptor.metadata.sourceWidth,
                descriptor.metadata.sourceHeight,
                directWifiCurrentEpisode = directWifiCurrentEpisode,
            )
        ) {
            if (directWifiCurrentEpisode) {
                strictExactDirectWifiRollingPixelResidency.set(true)
            }
            activateStrictExactRollingPixelResidency(launchSeal.pageCount, sourceRgbaBytes)
        }
        val displayIndexes = displayIndexesForStrictSource(sourceIndex)
        displayIndexes.forEach { displayIndex ->
            pageRef(displayIndex)?.let { page ->
                postStrictExactPageBounds(
                    displayIndex,
                    page,
                    descriptor.metadata.sourceWidth,
                    descriptor.metadata.sourceHeight
                )
            }
        }
        val admission = strictRollingAdmission.get() ?: return
        val anchorDisplay = currentViewportAnchor.get().coerceAtLeast(0)
        val anchorSource = pageRef(anchorDisplay)?.sourceIndex ?: 0
        // Keep the first visible image urgent, but do not let 100+ decoders contend with the main
        // response wave. Long strips release only after one complete physical refill ring.
        val bulkReleased = strictExactBulkDecodeReleased.get()
        val overlapDecode = sourceIndex != anchorSource && !bulkReleased &&
            tryAdmitStrictExactOverlapDecode()
        if (admission.admitsSource(sourceIndex) &&
            (sourceIndex == anchorSource || bulkReleased || overlapDecode)
        ) {
            displayIndexes.forEach { displayIndex ->
                requestStrictExactSourcePage(
                    displayIndex,
                    anchor = displayIndex == anchorDisplay,
                    generation = admission.epoch.toInt(),
                    overlap = overlapDecode
                )
            }
        }
        val residentPageCount = strictExactBodyDescriptors.size
        val strictWebtoon = launchSeal.normalizedEpisodePath.startsWith("/webtoon/")
        val bulkReleaseThreshold = NtkStrictDecodeReleasePolicy.releaseThreshold(
            launchSeal.pageCount,
            strictWebtoon,
        )
        if (NtkStrictDecodeReleasePolicy.shouldRelease(
                residentPageCount,
                launchSeal.pageCount,
                strictWebtoon,
            ) &&
            strictExactBulkDecodeReleased.compareAndSet(false, true)
        ) {
            // Opening the full pool near the beginning of a body wave made JPEG work compete with
            // HTTP EOF/SHA validation. This point is either fully resident (short work) or one
            // complete bounded source refill ring (long strip).
            for (readySource in launchSeal.canonicalAssets.indices) {
                if (!admission.admitsSource(readySource)) continue
                if (!strictExactBodyDescriptors.containsKey(readySource)) continue
                displayIndexesForStrictSource(readySource).forEach { displayIndex ->
                    requestStrictExactSourcePage(
                        displayIndex,
                        anchor = displayIndex == anchorDisplay,
                        generation = admission.epoch.toInt()
                    )
                }
            }
            Log.d(
                TAG,
                "reader_ntk_strict_bulk_decode_released pages=${launchSeal.pageCount}," +
                    "sources=$residentPageCount,threshold=$bulkReleaseThreshold," +
                    "epoch=${admission.epoch}"
            )
        }
        // Body callbacks can cross the release CAS concurrently. A callback may have observed the
        // old false value above while another callback's release sweep passed this source index
        // before its descriptor became visible. Re-read the authoritative flag after both actions
        // and idempotently admit this exact descriptor. The in-flight/installed guards inside the
        // request make an already scheduled page a no-op.
        if (strictExactBulkDecodeReleased.get() && admission.admitsSource(sourceIndex)) {
            displayIndexes.forEach { displayIndex ->
                requestStrictExactSourcePage(
                    displayIndex,
                    anchor = displayIndex == anchorDisplay,
                    generation = admission.epoch.toInt(),
                    overlap = false,
                )
            }
        }
        maybeStartForwardAdjacentControlAfterCurrentBodiesResident(launchSeal)
        if (residentPageCount == launchSeal.pageCount) {
            val terminalDecodeBacklog = strictExactDecodeInFlight.size
            val currentForegroundEpisode =
                strictExactForegroundViewerGenerationAtCreation > 0L &&
                (ViewerTelemetry.isActiveViewer(
                    strictExactForegroundViewerGenerationAtCreation,
                    initialNtkEpisodePath,
                ) || ViewerTelemetry.isActiveViewer(
                    strictExactForegroundViewerGenerationAtCreation,
                    launchSeal.normalizedEpisodePath,
                ))
            val directWifiActive = isDirectWifiStrictAdjacentTransportActive()
            val terminalDecodeParallelism = NtkStrictTerminalDecodePolicy.expandedParallelism(
                rollingPixelResidency = strictExactRollingPixelResidency.get(),
                terminalBacklog = terminalDecodeBacklog,
                directWifi = directWifiActive,
                currentForegroundEpisode = currentForegroundEpisode,
                webtoon = strictWebtoon,
            )
            val terminalDecodeExpanded =
                terminalDecodeParallelism != null &&
                    strictExactTerminalDecodeExpanded.compareAndSet(false, true) &&
                    strictExactBulkDecode.setCorePoolSize(
                        terminalDecodeParallelism
                    )
            if (terminalDecodeExpanded) {
                Log.d(
                    TAG,
                        "reader_ntk_terminal_decode_expanded backlog=$terminalDecodeBacklog," +
                        "parallelism=$terminalDecodeParallelism," +
                        "currentForeground=$currentForegroundEpisode,directWifi=" +
                        directWifiActive,
                )
            }
            // A terminal sweep makes the invariant explicit: every resident, admitted source has
            // either been installed or owns exactly one decode task before all-resident is logged.
            // This is normal viewer work after each post-click body, never a test-only preload.
            for (readySource in launchSeal.canonicalAssets.indices) {
                if (!admission.admitsSource(readySource) ||
                    !strictExactBodyDescriptors.containsKey(readySource)
                ) continue
                displayIndexesForStrictSource(readySource).forEach { displayIndex ->
                    requestStrictExactSourcePage(
                        displayIndex,
                        anchor = displayIndex == anchorDisplay,
                        generation = admission.epoch.toInt(),
                        overlap = false,
                    )
                }
            }
            Log.d(
                TAG,
                "reader_ntk_all_bodies_resident pages=$residentPageCount," +
                    "webtoon=$strictWebtoon,epoch=${admission.epoch}," +
                    "decodeAdmissions=${strictExactDecodeAdmissions.get()}," +
                    "decodeTerminals=${strictExactDecodeTerminals.get()}," +
                    "decodeInFlight=${strictExactDecodeInFlight.size}," +
                    "installed=${strictExactAuthoritativeHandoffPages.size}",
            )
        }
    }

    private fun tryAdmitStrictExactOverlapDecode(): Boolean {
        while (true) {
            val admitted = strictExactOverlapDecodeAdmissions.get()
            if (admitted >= STRICT_EXACT_OVERLAP_DECODE_LIMIT) return false
            if (strictExactOverlapDecodeAdmissions.compareAndSet(admitted, admitted + 1)) return true
        }
    }

    private fun isStrictExactCurrentForegroundEpisode(): Boolean {
        val viewerGeneration = strictExactForegroundViewerGenerationAtCreation
        if (viewerGeneration <= 0L) return false
        val launchPath = strictExactLaunchSeal?.normalizedEpisodePath.orEmpty()
        return ViewerTelemetry.isActiveViewer(viewerGeneration, initialNtkEpisodePath) ||
            ViewerTelemetry.isActiveViewer(viewerGeneration, launchPath)
    }

    private fun activateStrictExactRollingPixelResidency(
        pageCount: Int,
        representativePageBytes: Long,
    ) {
        if (!strictExactRollingPixelResidency.compareAndSet(false, true)) {
            // An early-built session can discover the oversized scene before Activity adoption
            // clears its generation ledger. Reassert the idempotent mode on later descriptors.
            listener.onStrictRollingHistoricalSceneActivated()
            return
        }
        val initialAnchor = currentStartPage().coerceIn(0, pageCount - 1)
        val directWifiRolling = strictExactDirectWifiRollingPixelResidency.get()
        val initialForwardRunwayPages = ReaderStrictBitmapResidencyPolicy
            .initialForwardRunwayPages(
                directWifiRolling = directWifiRolling,
                ordinaryPages = STRICT_OVERSIZED_INITIAL_FORWARD_RUNWAY_PAGES,
            )
        synchronized(deliveredBitmaps) {
            retainedFirstPage = max(
                0,
                initialAnchor - if (directWifiRolling) 0 else STRICT_OVERSIZED_BEHIND_PAGES,
            )
            retainedLastPage = minOf(
                pageCount - 1,
                initialAnchor + initialForwardRunwayPages - 1,
            )
            retainedAnchorPage = initialAnchor
        }
        listener.onStrictRollingHistoricalSceneActivated()
        Log.d(
            TAG,
            "reader_strict_oversized_rolling_residency pages=$pageCount," +
                "representativePageBytes=$representativePageBytes," +
                "budget=$NTK_STRICT_OVERSIZED_BITMAP_BYTES," +
                "runway=$initialForwardRunwayPages",
        )
        trimDeliveredBitmapsToBudget()
    }

    private fun postStrictExactPageBounds(
        index: Int,
        page: PageRef,
        width: Int,
        height: Int
    ) {
        if (width <= 0 || height <= 0) return
        ReaderImageCache.rememberStrictSourceBounds(
            page.manga.ntkEpisodePath,
            page.sourceIndex,
            width,
            height,
        )
        val currentIndex = currentPageIndex(page, index)
        if (currentIndex < 0) return
        sourceWidths[currentIndex] = width
        val display = displayBounds(width, height, page.side, page.allowAutoSplit)
        pendingStrictExactBounds[currentIndex] = StrictExactBoundsDelivery(
            currentIndex,
            page,
            display.width(),
            display.height()
        )
        if (strictExactBoundsDrainPosted.compareAndSet(false, true)) {
            main.post(strictExactBoundsDrainRunnable)
        }
    }

    /** Coalesces a full manifest's bounds into one main-loop turn and one layout traversal. */
    private fun drainStrictExactBoundsOnMain() {
        while (!cancelled.get()) {
            val batch = pendingStrictExactBounds.entries.mapNotNull { entry ->
                if (pendingStrictExactBounds.remove(entry.key, entry.value)) entry.value else null
            }.sortedBy { it.index }
            batch.forEach { delivery ->
                val latestIndex = currentPageIndex(delivery.page, delivery.index)
                if (!cancelled.get() && latestIndex >= 0) {
                    listener.onPageBoundsReady(latestIndex, delivery.width, delivery.height)
                }
            }
            strictExactBoundsDrainPosted.set(false)
            if (pendingStrictExactBounds.isEmpty() ||
                !strictExactBoundsDrainPosted.compareAndSet(false, true)
            ) return
        }
        strictExactBoundsDrainPosted.set(false)
        pendingStrictExactBounds.clear()
    }

    private fun displayIndexesForStrictSource(sourceIndex: Int): List<Int> =
        strictExactDisplayIndexesBySource.computeIfAbsent(sourceIndex) {
            synchronized(pagesLock) {
                pages.withIndex()
                    .filter { (_, page) ->
                        page.transitionTitle == null && page.sourceIndex == sourceIndex
                    }
                    .map { it.index }
            }
        }

    private fun applyStrictExactSourceDemand(admission: StrictRollingAdmission) {
        val transport = strictExactSourceTransport.get() ?: return
        val episode = strictExactEpisodeToken ?: return
        val launchSeal = strictExactLaunchSeal ?: return
        val admitted = (admission.allowedFirstSource..admission.allowedLastSource).toList()
        val visibleSources = if (admission.physicalDrawPresented) {
            synchronized(pagesLock) {
                (admission.visibleFirstDisplay..admission.visibleLastDisplay)
                    .mapNotNull { index ->
                        pages.getOrNull(index)
                            ?.takeIf { page ->
                                page.transitionTitle == null && isStrictExactLaunchPage(page)
                            }
                            ?.sourceIndex
                    }
                    .filter { it in admitted }
                    .distinct()
            }
        } else {
            listOf(admission.allowedFirstSource)
        }
        val hard = visibleSources.ifEmpty { listOf(admission.allowedFirstSource) }.let { values ->
            if (admission.direction < 0) values.sortedDescending() else values.sorted()
        }
        val soft = admission.orderedSoftSources(hard)
        val background = launchSeal.canonicalAssets.indices
            .filterNot { it in admitted }
        transport.applySourceDemand(
            episode,
            NtkSourceDemandSnapshot(
                authority = episode.value,
                demandEpoch = admission.epoch,
                hardPages = hard.toIntArray(),
                softPages = soft.toIntArray(),
                backgroundPages = background.toIntArray()
            )
        )
    }

    private fun schedulePreloadedEarlyNtkUrlsImmediateInstall() {
        if (!isNtkSource(manga, title) || cancelled.get() || pagesInstalled.get()) return
        try {
            initialRecovery.execute {
                if (!cancelled.get()) installPreloadedEarlyNtkUrlsFromSessionStart()
            }
        } catch (_: RejectedExecutionException) {
            if (!cancelled.get()) installPreloadedEarlyNtkUrlsFromSessionStart()
        }
    }

    private fun installPreloadedEarlyNtkUrlsFromSessionStart(): Boolean {
        if (cancelled.get() || pagesInstalled.get()) return false
        if (!isNtkSource(manga, title)) {
            logNtkRepositoryStage(
                manga,
                "early_urls_session_start_preloaded_skip",
                "reason=not_ntk_source,path=${manga.ntkEpisodePath}"
            )
            return false
        }
        val now = SystemClock.elapsedRealtime()
        val minCreatedAt = max(0L, now - NTK_PRELOADED_EARLY_URL_ACCEPT_MS)
        var earlyUrls = ReaderImageCache.earlyNtkImageUrls(manga.ntkEpisodePath, minCreatedAt)
        if (earlyUrls.size < ntkEarlyUrlMinCount(manga) &&
            isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)
        ) {
            val anyCurrentUrls = ReaderImageCache.earlyNtkImageUrls(manga.ntkEpisodePath, 0L)
            if (anyCurrentUrls.any { isNtkGeneratedImageUrl(it) }) {
                earlyUrls = anyCurrentUrls
                logNtkRepositoryStage(
                    manga,
                    "early_urls_session_start_preloaded_use_current",
                    "count=${earlyUrls.size},minCreatedAt=$minCreatedAt"
                )
            }
        }
        if (earlyUrls.size < ntkEarlyUrlMinCount(manga)) {
            val currentCount = ReaderImageCache.earlyNtkImageUrls(manga.ntkEpisodePath, 0L).size
            logNtkRepositoryStage(
                manga,
                "early_urls_session_start_preloaded_skip",
                "reason=empty,count=${earlyUrls.size},current=$currentCount,minCreatedAt=$minCreatedAt"
            )
            return false
        }
        val installed = installEarlyNtkUrls(manga, earlyUrls, now)
        logNtkRepositoryStage(
            manga,
            "early_urls_session_start_preloaded",
            "installed=$installed,count=${earlyUrls.size},ms=${SystemClock.elapsedRealtime() - now}"
        )
        return installed
    }

    private fun scheduleImmediateNtkGeneratedInitialUrls() {
        if (!isNtkSource(manga, title) || cancelled.get()) return
        try {
            initialRecovery.execute {
                if (!cancelled.get()) {
                    primeImmediateNtkGeneratedInitialUrls()
                }
            }
        } catch (_: RejectedExecutionException) {
            if (!cancelled.get()) primeImmediateNtkGeneratedInitialUrls()
        }
    }

    private fun registerEarlyNtkImageUrlRefreshListener() {
        if (!isNtkSource(manga, title) || earlyNtkImageUrlsUnregister != null) return
        val path = manga.ntkEpisodePath?.trim().orEmpty()
        if (path.isEmpty()) return
        earlyNtkImageUrlsUnregister = ReaderImageCache.addEarlyNtkImageUrlsSourceListener { changedPath, urls, source ->
            if (!cancelled.get() && urls.isNotEmpty()) {
                handlePendingAdjacentEarlyAppendUrlsChanged(changedPath, urls)
            }
            if (cancelled.get() || changedPath != path || urls.isEmpty()) return@addEarlyNtkImageUrlsSourceListener
            val sourceValue = source.orEmpty()
            earlyNtkImageUrlRefreshLatest.set(EarlyNtkImageUrlRefreshEvent(urls, sourceValue))
            if (!earlyNtkImageUrlRefreshScheduled.compareAndSet(false, true)) return@addEarlyNtkImageUrlsSourceListener
            executeEarlyNtkImageUrlRefreshDrain(
                urgent = isUrgentKpDescriptorFullEarlyUrlEvent(urls, sourceValue) ||
                    isUrgentProtectedNumericApiEarlyUrlEvent(urls, sourceValue)
            )
        }
    }

    private fun executeEarlyNtkImageUrlRefreshDrain(urgent: Boolean = false) {
        try {
            val executor = if (urgent) initialRecovery else control
            executor.execute {
                drainEarlyNtkImageUrlRefreshEvents()
            }
        } catch (_: RejectedExecutionException) {
            drainEarlyNtkImageUrlRefreshEvents()
        }
    }

    private fun isUrgentKpDescriptorFullEarlyUrlEvent(urls: List<String>, source: String): Boolean {
        if (urls.isEmpty()) return false
        if (!isKpWebtoonSlugEpisodePath(manga.ntkEpisodePath.orEmpty())) return false
        if (!source.contains("native-api-full-kp-cv", ignoreCase = true) &&
            !source.contains("native-api-full-partial-kp-cv", ignoreCase = true)
        ) {
            return false
        }
        val trustedCount = ReaderImageCache.trustedNtkImageApiCount(
            manga.ntkEpisodePath,
            SystemClock.elapsedRealtime() - 30_000L
        )
        if (trustedCount > 0 && urls.size < trustedCount) return false
        return urls.all { isNtkKpDescriptorImageUrl(it) }
    }

    private fun isUrgentProtectedNumericApiEarlyUrlEvent(urls: List<String>, source: String): Boolean {
        if (urls.isEmpty()) return false
        val path = manga.ntkEpisodePath?.trim().orEmpty()
        if (!path.matches(Regex("^/(?:webtoon|manhwa)/\\d{1,12}/\\d{1,12}$", RegexOption.IGNORE_CASE))) {
            return false
        }
        if (!urls.all { ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(it) }) return false
        if (urls.size <= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return true
        if (!source.contains("native-api-full", ignoreCase = true) &&
            !source.contains("viewer-api-token", ignoreCase = true)
        ) {
            return false
        }
        val trustedCount = ReaderImageCache.trustedNtkImageApiCount(
            path,
            SystemClock.elapsedRealtime() - 30_000L
        )
        return trustedCount > 0 && urls.size >= trustedCount
    }

    private fun registerPendingAdjacentEarlyAppendTarget(target: Manga, direction: Int) {
        if (!isNtkSource(target, title)) return
        if (direction == 0) return
        val path = target.ntkEpisodePath?.trim().orEmpty()
        if (path.isEmpty()) return
        val now = SystemClock.elapsedRealtime()
        pendingAdjacentEarlyAppendTargets[path] = PendingAdjacentEarlyAppend(target, direction, now)
        val earlyUrls = ReaderImageCache.earlyNtkAppendImageUrls(path, now - 30000L).ifEmpty {
            ReaderImageCache.earlyNtkImageUrls(path, now - 30000L)
        }
        if (earlyUrls.isNotEmpty()) {
            handlePendingAdjacentEarlyAppendUrlsChanged(path, earlyUrls)
        }
    }

    private fun handlePendingAdjacentEarlyAppendUrlsChanged(changedPath: String, urls: List<String>) {
        val key = changedPath.trim()
        if (key.isEmpty() || urls.isEmpty()) return
        val pending = pendingAdjacentEarlyAppendTargets[key] ?: return
        val now = SystemClock.elapsedRealtime()
        if (now - pending.createdAtMs > NTK_PENDING_ADJACENT_EARLY_APPEND_TTL_MS) {
            pendingAdjacentEarlyAppendTargets.remove(key, pending)
            return
        }
        if (synchronized(pagesLock) { containsEpisodeForAppendLocked(pending.target) }) {
            pendingAdjacentEarlyAppendTargets.remove(key, pending)
            return
        }
        if (!pending.started.compareAndSet(false, true)) return
        try {
            control.execute {
                var keepPending = false
                try {
                    if (cancelled.get()) return@execute
                    if (synchronized(pagesLock) { containsEpisodeForAppendLocked(pending.target) }) return@execute
                    val installed = installEarlyGeneratedAppendUrlsIfAvailable(pending.target)
                    val installedUrls = if (installed > 0) {
                        imageRepository.imageUrls(pending.target, appContext)
                    } else {
                        urls
                    }
                    val publishUrls = completeKnownGeneratedAppendUrls(pending.target, installedUrls)
                    if (publishUrls.isEmpty()) {
                        keepPending = true
                        pending.started.set(false)
                        return@execute
                    }
                    if (imageRepository.imageUrls(pending.target, appContext).isEmpty()) {
                        pending.target.setImgs(ArrayList(publishUrls))
                    }
                    val warmUrls = ntkBoundaryAppendWarmUrls(
                        pending.target,
                        publishUrls,
                        pending.direction,
                        silentMissing = true
                    )
                    startAdjacentForegroundStreams(pending.target, warmUrls, pending.direction)
                    appendResolvedEpisode(pending.target, publishUrls, pending.direction)
                    Log.d(
                        TAG,
                        "append_adjacent_early_event_installed path=$key " +
                            "images=${publishUrls.size} direction=${pending.direction}"
                    )
                } finally {
                    if (!keepPending) {
                        pendingAdjacentEarlyAppendTargets.remove(key, pending)
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            pending.started.set(false)
        }
    }

    private fun drainEarlyNtkImageUrlRefreshEvents() {
        try {
            while (!cancelled.get()) {
                val event = earlyNtkImageUrlRefreshLatest.getAndSet(null) ?: return
                if (event.urls.isEmpty()) return
                handleEarlyNtkImageUrlsChanged(
                    event.urls,
                    source = event.source,
                    urgentFullKpDescriptor =
                        isUrgentKpDescriptorFullEarlyUrlEvent(event.urls, event.source) ||
                            isUrgentProtectedNumericApiEarlyUrlEvent(event.urls, event.source)
                )
            }
        } finally {
            earlyNtkImageUrlRefreshScheduled.set(false)
            if (
            !cancelled.get() &&
            earlyNtkImageUrlRefreshLatest.get()?.urls?.isNotEmpty() == true &&
            earlyNtkImageUrlRefreshScheduled.compareAndSet(false, true)
        ) {
                val pending = earlyNtkImageUrlRefreshLatest.get()
                executeEarlyNtkImageUrlRefreshDrain(
                    urgent = pending?.let {
                        isUrgentKpDescriptorFullEarlyUrlEvent(it.urls, it.source) ||
                            isUrgentProtectedNumericApiEarlyUrlEvent(it.urls, it.source)
                    } == true
                )
            }
        }
    }

    private fun handleEarlyNtkImageUrlsChanged(
        urls: List<String>,
        source: String = "",
        urgentFullKpDescriptor: Boolean = false
    ) {
        if (cancelled.get() || urls.isEmpty()) return
        var eventUrls = urls
        val currentPath = manga.ntkEpisodePath?.trim().orEmpty()
        if (isKpWebtoonSlugEpisodePath(currentPath)) {
            val installedCount = synchronized(pagesLock) { pages.size }
            val protectedApiManifest = eventUrls.any {
                it.contains("/api/m/i?", ignoreCase = true)
            }
            val directUploadHead = if (protectedApiManifest || eventUrls.any { isNtkUploadCdnImageUrl(it) }) {
                eventUrls.filter { isNtkUploadCdnImageUrl(it) || isNaverWebtoonPageImageUrl(it) }.distinct()
            } else {
                emptyList()
            }
            if (directUploadHead.size >= 4 && directUploadHead.size < eventUrls.size) {
                logNtkRepositoryStage(
                    manga,
                    "early_urls_event_kp_drop_protected_tail",
                    "from=${eventUrls.size},to=${directUploadHead.size},installed=$installedCount"
                )
                eventUrls = directUploadHead
            }
            val trustedApiCount = ReaderImageCache.trustedNtkImageApiCount(
                currentPath,
                SystemClock.elapsedRealtime() - 30_000L
            )
            val trustedFirst = urls.any {
                ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(it) ||
                    isNtkProtectedCdnImageUrl(it) ||
                    isNaverWebtoonPageImageUrl(it)
            }
            val requiredCount = if (installedCount == 0) {
                if (directUploadHead.size >= 4) {
                    4
                } else if (directUploadHead.isNotEmpty()) {
                    max(4, minOf(trustedApiCount.takeIf { it > 0 } ?: NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES,
                        NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES))
                } else if (trustedFirst && eventUrls.isNotEmpty()) {
                    1
                } else if (trustedApiCount > 0) {
                    max(4, minOf(trustedApiCount, NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES))
                } else {
                    4
                }
            } else {
                if (directUploadHead.size >= 4) 4 else if (trustedFirst) 1 else max(4, trustedApiCount)
            }
            if (eventUrls.size < requiredCount) {
                logNtkRepositoryStage(
                    manga,
                    "early_urls_event_defer_kp_partial",
                    "count=${eventUrls.size},raw=${urls.size},required=$requiredCount,trustedApi=$trustedApiCount," +
                        "trustedFirst=$trustedFirst,installed=$installedCount"
                )
                return
            }
        }
        val start = currentStartPage()
        val target = pageRef(start)?.manga ?: manga
        val installedCount = synchronized(pagesLock) { pages.size }
        val forceVerifiedPublish = shouldForceImmediateVerifiedEarlyUrlRefresh(eventUrls, source)
        val loadStartedAtForEvent = repositoryLoadStartedAtMs.get().takeIf { it > 0L } ?: SystemClock.elapsedRealtime()
        if (
            shouldSkipGeneratedTailExpansionAfterAuthoritativeDirect(
                target,
                eventUrls,
                installedCount,
                loadStartedAtForEvent,
                "early_urls_event"
            )
        ) {
            return
        }
        if (installedCount == 0 && !pagesInstalled.get() && isNtkSource(target, title)) {
            logNtkRepositoryStage(
                target,
                "early_urls_event_initial_install",
                "count=${eventUrls.size},page=$start,ms=${SystemClock.elapsedRealtime() - loadStartedAtForEvent}"
            )
            if (installEarlyNtkUrls(target, eventUrls, loadStartedAtForEvent)) {
                return
            }
        }
        if (installedCount > 0 &&
            eventUrls.size > installedCount &&
            earlyNtkEventFullAppendScheduled.compareAndSet(false, true)
        ) {
            logNtkRepositoryStage(
                target,
                "early_urls_event_expand_detected",
                "from=$installedCount,to=${eventUrls.size},raw=${urls.size},page=$start,ms=${SystemClock.elapsedRealtime() - loadStartedAtForEvent}"
            )
            if (urgentFullKpDescriptor) {
                try {
                    logNtkRepositoryStage(
                        target,
                        "early_urls_event_expand_urgent_kp_descriptor",
                        "from=$installedCount,to=${eventUrls.size},page=$start,ms=${SystemClock.elapsedRealtime() - loadStartedAtForEvent}"
                    )
                            appendInitialNtkUrlsAfterEarlyInstall(
                                target,
                                eventUrls,
                                loadStartedAtForEvent,
                                allowFirstBitmapDefer = false,
                                forceImmediatePublish = true
                            )
                    mainImmediate.post {
                        requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), eventUrls.size)
                    }
                    scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(0L)
                } finally {
                    earlyNtkEventFullAppendScheduled.set(false)
                }
                return
            }
            if (installedCount < NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES &&
                eventUrls.size >= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
            ) {
                if (isUrgentProtectedNumericApiEarlyUrlEvent(eventUrls, source)) {
                    try {
                        val runwayUrls = eventUrls.take(NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)
                        logNtkRepositoryStage(
                            target,
                            "early_urls_event_numeric_runway_immediate",
                            "from=$installedCount,to=${runwayUrls.size},full=${eventUrls.size}," +
                                "ms=${SystemClock.elapsedRealtime() - loadStartedAtForEvent}"
                        )
                        appendInitialNtkUrlsAfterEarlyInstall(
                            target,
                            runwayUrls,
                            loadStartedAtForEvent,
                            allowFirstBitmapDefer = false,
                            forceImmediatePublish = true
                        )
                        mainImmediate.post {
                            requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), runwayUrls.size)
                        }
                    } finally {
                        earlyNtkEventFullAppendScheduled.set(false)
                    }
                    return
                }
                try {
                    val runwayUrls = eventUrls.take(NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)
                    logNtkRepositoryStage(
                        target,
                        "early_urls_event_runway_append",
                            "from=$installedCount,to=$NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES," +
                            "full=${eventUrls.size},ms=${SystemClock.elapsedRealtime() - loadStartedAtForEvent}"
                    )
                    control.execute {
                        try {
                            appendInitialNtkUrlsAfterEarlyInstall(
                                target,
                                runwayUrls,
                                loadStartedAtForEvent,
                                allowFirstBitmapDefer = false,
                                forceImmediatePublish = forceVerifiedPublish
                            )
                            requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), runwayUrls.size)
                            appendInitialNtkUrlsAfterEarlyInstall(
                                target,
                                eventUrls,
                                loadStartedAtForEvent,
                                allowFirstBitmapDefer = false,
                                forceImmediatePublish = forceVerifiedPublish
                            )
                            requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), eventUrls.size)
                            scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(0L)
                        } finally {
                            earlyNtkEventFullAppendScheduled.set(false)
                        }
                    }
                } finally {
                }
                return
            }
            try {
                control.execute {
                    try {
                        appendInitialNtkUrlsAfterEarlyInstall(
                            target,
                            eventUrls,
                            loadStartedAtForEvent,
                            allowFirstBitmapDefer = false,
                            forceImmediatePublish = forceVerifiedPublish
                        )
                        mainImmediate.post {
                            requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), eventUrls.size)
                        }
                    } finally {
                        earlyNtkEventFullAppendScheduled.set(false)
                    }
                }
            } catch (_: RejectedExecutionException) {
                earlyNtkEventFullAppendScheduled.set(false)
            }
        }
        if (installedCount > 0 &&
            urls.size < installedCount &&
            shouldAllowNtkGeneratedVerifiedShrink(target, urls)
        ) {
            val loadStartedAt = repositoryLoadStartedAtMs.get().takeIf { it > 0L } ?: SystemClock.elapsedRealtime()
            logNtkRepositoryStage(
                target,
                "early_urls_event_shrink_detected",
                "from=$installedCount,to=${urls.size},page=$start,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            appendInitialNtkUrlsAfterEarlyInstall(
                target,
                urls,
                loadStartedAt,
                allowFirstBitmapDefer = false,
                forceImmediatePublish = true
            )
            requestInitialContinuousPagesFromEarlyUrls(start, urls.size)
            return
        }
        val forceSourceIndexRefresh =
            forceVerifiedPublish &&
                installedCount > 0 &&
                urls.size >= installedCount
        if (!shouldRefreshInstalledNtkGeneratedImagesFromEarlyUrls(
                target,
                urls,
                forceBySourceIndex = forceSourceIndexRefresh
            )
        ) return
        val loadStartedAt = repositoryLoadStartedAtMs.get().takeIf { it > 0L } ?: SystemClock.elapsedRealtime()
        val installedImages = currentNtkInstalledImages(target)
        if (
            installedCount > 0 &&
            urls.size <= installedCount &&
            isPureGeneratedExtensionPromotion(installedImages, urls)
        ) {
            refreshInstalledNtkGeneratedImagesFromEarlyUrls(
                target,
                urls,
                "early_urls_event_extension_promotion_initial"
            )
            primeInitialInteractiveRunwayBytes("early_urls_event_extension_promotion")
            requestInitialContinuousPagesFromEarlyUrls(start, urls.size)
            logNtkRepositoryStage(
                target,
                "early_urls_event_extension_promotion_silent",
                "count=${urls.size},installed=$installedCount,page=$start,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            return
        }
        val refreshReason = if (forceSourceIndexRefresh) {
            "early_urls_event_same_count_force"
        } else {
            "early_urls_event_same_count"
        }
        if (!refreshInstalledNtkGeneratedImagesFromEarlyUrls(
                target,
                urls,
                refreshReason,
                forceBySourceIndex = forceSourceIndexRefresh
            )
        ) return
        val requestAnchor = if (forceSourceIndexRefresh) {
            currentViewportAnchor.get()
                .takeIf { it >= 0 }
                ?.coerceIn(0, urls.lastIndex)
                ?: start
        } else {
            start
        }
        logNtkRepositoryStage(
            target,
            if (forceSourceIndexRefresh) {
                "early_urls_event_same_count_force_replace"
            } else {
                "early_urls_event_same_count_replace"
            },
            "count=${urls.size},page=$requestAnchor,start=$start," +
                "source=$source,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        requestPageForeground(requestAnchor)
        requestInitialContinuousPagesFromEarlyUrls(requestAnchor, urls.size)
        scheduleNtkAnchorCachedDecodeRetry(requestAnchor, refreshReason, loadStartedAt)
        scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(0L)
    }

    private fun shouldForceImmediateVerifiedEarlyUrlRefresh(urls: List<String>, source: String): Boolean {
        if (!isNtkSource(manga, title) || urls.isEmpty()) return false
        if (source.contains("payload-direct", ignoreCase = true) ||
            source.contains("native-api", ignoreCase = true) ||
            source.contains("viewer-api-token", ignoreCase = true) ||
            source.contains("bridge-result", ignoreCase = true)
        ) {
            return true
        }
        return urls.any { image ->
            isNtkBoardUploadImageUrl(image) ||
                isNaverWebtoonPageImageUrl(image) ||
                isNtkProtectedCdnImageUrl(image) ||
                ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(image)
        }
    }

    private fun primeImmediateNtkGeneratedInitialUrls(): Boolean {
        if (!isNtkSource(manga, title) || cancelled.get()) return false
        if (pagesInstalled.get()) return false
        val path = manga.ntkEpisodePath?.trim().orEmpty()
        val match = NTK_VIEWER_EPISODE_PATH.matchEntire(path) ?: return false
        val segment = match.groupValues[1].lowercase(Locale.ROOT)
        if (segment != "webtoon" && segment != "manhwa") return false
        val pathWorkId = match.groupValues[2].trim()
        val pathEpisodeToken = match.groupValues[3].trim()
        if (isModernProtectedNumericNtkPath(path)) {
            manga.startNtkEarlyViewerApiPrefetch(MainApplication.getHttpClient())
            Log.d(TAG, "ntk_immediate_generated_initial_skip_protected_api path=$path")
            return true
        }
        if (segment == "webtoon" && !pathEpisodeToken.matches(Regex("\\d{1,12}"))) {
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_skip path=$path " +
                    "reason=slug_webtoon_non_numeric_episode"
            )
            ViewerWarmupManager.logMetric("reader_ntk_immediate_generated_initial_skip", 1L)
            return false
        }
        val imageWorkId = manga.ntkImageWorkId.trim().ifEmpty { pathWorkId }
        val recordedImageEpisodeId = manga.ntkImageEpisodeId.trim()
        val trustedKnownGeneratedCount = hasTrustedKnownGeneratedInitialCount(manga)
        val largeUntrustedWebtoonCount =
            segment == "webtoon" &&
                manga.ntkImageCount > NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD &&
                !trustedKnownGeneratedCount
        if (largeUntrustedWebtoonCount && !pathEpisodeToken.matches(Regex("\\d{1,12}"))) {
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_skip path=$path " +
                    "reason=untrusted_large_webtoon_count count=${manga.ntkImageCount}"
            )
            return false
        } else if (largeUntrustedWebtoonCount) {
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_limited path=$path " +
                    "reason=untrusted_large_webtoon_count_initial_only count=${manga.ntkImageCount}"
            )
        }
        val cachedIdentity = try {
            CustomHttpClient.cachedNtkImageIdentity(path)
        } catch (_: Throwable) {
            null
        }
        val recentGeneratedSuccess = ReaderImageCache
            .earlyNtkGeneratedSuccessImageUrls(path, SystemClock.elapsedRealtime() - 30000L)
        if (
            segment == "webtoon" &&
            pathEpisodeToken.matches(Regex("\\d{1,12}")) &&
            cachedIdentity != null &&
            cachedIdentity.workId.matches(Regex("\\d{1,12}")) &&
            cachedIdentity.episodeId == pathEpisodeToken &&
            cachedIdentity.count > 0
        ) {
            val count = cachedIdentity.count.coerceIn(1, 128)
            val urls = ArrayList<String>(count)
            for (page in 1..count) {
                urls.add(
                    "https://fifa.worldcup73.xyz/black/episodes/${cachedIdentity.workId}/" +
                        "${cachedIdentity.episodeId}/p%03d.jpeg".format(Locale.ROOT, page)
                )
            }
            manga.ntkImageWorkId = cachedIdentity.workId
            manga.ntkImageEpisodeId = cachedIdentity.episodeId
            manga.ntkImageCount = urls.size
            ReaderImageCache.rememberAuthoritativeNtkImageUrlsFromBrowser(
                path,
                urls,
                "reader-immediate-cached-identity"
            )
            ReaderImageCache.rememberEarlyNtkImageUrls(path, urls)
            installImmediateGeneratedEarlyUrls(urls, "cached_identity_full_prime")
            val startIndex = currentStartPage().coerceIn(0, urls.lastIndex)
            val streamCount = minOf(ntkInitialGeneratedDecodeRunwayPages(), urls.size - startIndex)
            var startedCount = 0
            for (offset in 0 until streamCount) {
                val pageIndex = startIndex + offset
                if (
                    startBoundedForegroundStreamFetch(
                        appContext,
                        manga,
                        urls[pageIndex],
                        null,
                        false,
                        null,
                        pageIndex,
                        true
                    )
                ) {
                    startedCount++
                }
            }
            Log.d(
                TAG,
                "ntk_immediate_cached_identity_full_prime path=$path " +
                    "workId=${cachedIdentity.workId} episodeId=${cachedIdentity.episodeId} " +
                    "count=${urls.size} streamCount=$streamCount startedCount=$startedCount"
            )
            return true
        }
        if (segment == "manhwa" && recentGeneratedSuccess.isEmpty()) {
            manga.startNtkEarlyViewerApiPrefetch(MainApplication.getHttpClient())
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_defer_manhwa_browser_manifest path=$path " +
                    "workId=$imageWorkId pathWorkId=$pathWorkId " +
                    "pathEpisodeId=$pathEpisodeToken count=${manga.ntkImageCount}"
            )
            return true
        }
        if (segment == "webtoon" &&
            pathWorkId.matches(Regex("\\d{1,12}")) &&
            pathEpisodeToken.matches(Regex("\\d{1,12}")) &&
            manga.ntkImageCount > 0 &&
            imageWorkId == pathWorkId &&
            (cachedIdentity == null ||
                cachedIdentity.workId != imageWorkId ||
                cachedIdentity.episodeId != pathEpisodeToken) &&
            recentGeneratedSuccess.isEmpty()
        ) {
            if (
                cachedIdentity != null &&
                cachedIdentity.workId.matches(Regex("\\d{1,12}")) &&
                cachedIdentity.episodeId == pathEpisodeToken &&
                cachedIdentity.count > 0
            ) {
                val count = minOf(cachedIdentity.count, 128)
                val urls = ArrayList<String>(count)
                for (page in 1..count) {
                    urls.add(
                        "https://fifa.worldcup73.xyz/black/episodes/${cachedIdentity.workId}/" +
                            "${cachedIdentity.episodeId}/p%03d.jpeg".format(Locale.ROOT, page)
                    )
                }
                ReaderImageCache.rememberEarlyNtkImageUrls(path, urls)
                installImmediateGeneratedEarlyUrls(urls, "cached_identity_prime")
                var started = 0
                val startIndex = currentStartPage().coerceIn(0, urls.lastIndex)
                val immediate = ntkInitialGeneratedDecodeRunwayPages().coerceAtMost(urls.size - startIndex)
                for (index in 0 until immediate) {
                    val pageIndex = startIndex + index
                    if (
                        ReaderImageCache.startForegroundStreamFetch(
                            appContext,
                            manga,
                            urls[pageIndex],
                            null,
                            false,
                            null,
                            pageIndex,
                            true
                        )
                    ) {
                        started++
                    }
                }
                Log.d(
                    TAG,
                    "ntk_immediate_cached_identity_initial_prime path=$path " +
                        "workId=${cachedIdentity.workId} episodeId=${cachedIdentity.episodeId} " +
                        "count=${urls.size} startedCount=$started"
                )
                return true
            }
            manga.startNtkEarlyViewerApiPrefetch(MainApplication.getHttpClient())
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_defer_authority path=$path " +
                    "workId=$imageWorkId pathWorkId=$pathWorkId pathEpisodeId=$pathEpisodeToken " +
                    "identityWorkId=${cachedIdentity?.workId.orEmpty()} " +
                    "identityEpisodeId=${cachedIdentity?.episodeId.orEmpty()} count=${manga.ntkImageCount}"
            )
            return true
        }
        if (
            segment == "webtoon" &&
            shouldPreferNtkApiForCanonicalWebtoonPath(pathWorkId, pathEpisodeToken) &&
            recentGeneratedSuccess.isEmpty()
        ) {
            manga.startNtkEarlyViewerApiPrefetch(MainApplication.getHttpClient())
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_defer_canonical_api_first path=$path " +
                    "workId=$imageWorkId pathWorkId=$pathWorkId " +
                    "pathEpisodeId=$pathEpisodeToken count=${manga.ntkImageCount}"
            )
            return true
        }
        if (segment == "webtoon" &&
            !pathWorkId.matches(Regex("\\d{1,12}")) &&
            pathEpisodeToken.matches(Regex("\\d{1,12}"))
        ) {
            manga.startNtkEarlyViewerApiPrefetch(MainApplication.getHttpClient())
            Log.d(
                TAG,
                "ntk_immediate_slug_generated_initial_api_first path=$path " +
                    "workId=$imageWorkId pathWorkId=$pathWorkId pathEpisodeId=$pathEpisodeToken " +
                    "count=${manga.ntkImageCount}"
            )
            ViewerWarmupManager.logMetric("reader_ntk_immediate_slug_generated_initial_api_first", 1L)
            return true
        }
        if (
            segment == "webtoon" &&
            !pathEpisodeToken.matches(Regex("\\d{1,12}")) &&
            recentGeneratedSuccess.isEmpty()
        ) {
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_skip path=$path " +
                    "reason=slug_requires_verified_payload count=${manga.ntkImageCount}"
            )
            return false
        }
        val canPrimePathEpisodeWithImageWork =
            segment == "webtoon" &&
                imageWorkId.matches(Regex("\\d{1,12}")) &&
                pathEpisodeToken.matches(Regex("\\d{1,12}"))
        if (
            segment == "webtoon" &&
            pathEpisodeToken.matches(Regex("\\d{1,12}")) &&
            imageWorkId != pathWorkId &&
            recentGeneratedSuccess.isEmpty()
        ) {
            manga.startNtkEarlyViewerApiPrefetch(MainApplication.getHttpClient())
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_defer_mismatched_webtoon_work path=$path " +
                    "workId=$imageWorkId pathWorkId=$pathWorkId pathEpisodeId=$pathEpisodeToken " +
                    "count=${manga.ntkImageCount}"
            )
            return true
        }
        if (
            segment == "webtoon" &&
            pathEpisodeToken.matches(Regex("\\d{1,12}")) &&
            (largeUntrustedWebtoonCount || recordedImageEpisodeId.matches(Regex("\\d{1,12}"))) &&
            !canPrimePathEpisodeWithImageWork &&
            recentGeneratedSuccess.isEmpty()
        ) {
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_defer_unverified_numeric_webtoon path=$path " +
                    "workId=$imageWorkId pathWorkId=$pathWorkId pathEpisodeId=$pathEpisodeToken " +
                    "recordedEpisodeId=$recordedImageEpisodeId count=${manga.ntkImageCount}"
            )
            return true
        }
        val imageEpisodeId = if (
            segment == "webtoon" &&
            pathEpisodeToken.matches(Regex("\\d{1,12}")) &&
            pathEpisodeToken != recordedImageEpisodeId
        ) {
            pathEpisodeToken
        } else {
            recordedImageEpisodeId.ifEmpty {
                pathEpisodeToken.takeIf { it.matches(Regex("\\d{1,12}")) }.orEmpty()
            }
        }
        if (!imageWorkId.matches(Regex("\\d{1,12}")) ||
            !imageEpisodeId.matches(Regex("\\d{1,12}"))
        ) {
            return false
        }
        val useWtEpisodeUrls =
            segment == "webtoon" &&
                !pathWorkId.matches(Regex("\\d{1,12}")) &&
                imageWorkId == pathWorkId &&
                recordedImageEpisodeId.matches(Regex("\\d{1,12}")) &&
                recordedImageEpisodeId != pathEpisodeToken &&
                manga.ntkImageCount in 1..64
        val initialLimit = if (trustedKnownGeneratedCount) {
            manga.ntkImageCount
        } else if (
            segment == "webtoon" &&
            manga.ntkImageCount in 1..NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD
        ) {
            manga.ntkImageCount
        } else if (segment == "webtoon") {
            NTK_WEBTOON_GENERATED_INITIAL_RECOVERY_PAGES
        } else {
            NTK_GENERATED_INITIAL_RECOVERY_PAGES
        }
        val count = if (manga.ntkImageCount > 0) {
            minOf(initialLimit, manga.ntkImageCount)
        } else {
            initialLimit
        }
        val urls = ArrayList<String>(count)
        val initialExtension = ntkGeneratedInitialExtension(segment, pathEpisodeToken)
        if (
            segment == "webtoon" &&
            initialExtension.equals("jpg", ignoreCase = true) &&
            manga.ntkImageCount > 0 &&
            imageWorkId.matches(Regex("\\d{1,12}")) &&
            imageEpisodeId.matches(Regex("\\d{1,12}")) &&
            !(imageWorkId == pathWorkId &&
                imageEpisodeId == pathEpisodeToken &&
                recordedImageEpisodeId == pathEpisodeToken) &&
            recentGeneratedSuccess.isEmpty()
        ) {
            manga.startNtkEarlyViewerApiPrefetch(MainApplication.getHttpClient())
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_defer_verify path=$path " +
                    "workId=$imageWorkId pathWorkId=$pathWorkId " +
                    "imageEpisodeId=$imageEpisodeId count=${manga.ntkImageCount}"
            )
            return true
        }
        for (page in 1..count) {
            val pageName = "p%03d.%s".format(Locale.ROOT, page, initialExtension)
            val url = if (segment == "webtoon") {
                if (useWtEpisodeUrls) {
                    "https://fifa.worldcup73.xyz/wt/episodes/$pathWorkId/$pathEpisodeToken/$pageName"
                } else {
                    "http://fifa.worldcup73.xyz/black/episodes/$imageWorkId/$imageEpisodeId/$pageName"
                }
            } else {
                if (segment == "manhwa") {
                    "https://booktoki9.org/manhwa/$imageWorkId/$imageEpisodeId/$pageName"
                } else {
                    "http://apihost93.com/$segment/$imageWorkId/$imageEpisodeId/$pageName"
                }
            }
            urls.add(url)
        }
        ReaderImageCache.rememberEarlyNtkImageUrls(path, urls)
        installImmediateGeneratedEarlyUrls(urls, "prime")
        val first = urls.firstOrNull() ?: return false
        val startIndex = currentStartPage().coerceIn(0, urls.lastIndex)
        val immediateCount = minOf(ntkImmediateGeneratedInitialForegroundPages(segment), urls.size - startIndex)
        val visibleImmediateCount = if (
            !firstBitmapLogged.get() &&
            (segment == "webtoon" || segment == "manhwa")
        ) {
            0
        } else if (segment == "webtoon" || segment == "manhwa") {
            minOf(maxOf(immediateCount, NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES), urls.size)
        } else {
            immediateCount
        }
        var startedCount = 0
        urls.drop(startIndex).take(visibleImmediateCount).forEachIndexed { offset, image ->
            val pageIndex = startIndex + offset
            val started = ReaderImageCache.startForegroundStreamFetch(
                appContext,
                manga,
                image,
                null,
                false,
                null,
                pageIndex,
                true
            )
            if (started) startedCount++
        }
        var hedgeStartedCount = 0
        var wtHedgeStartedCount = 0
        if (
            segment == "webtoon" &&
            visibleImmediateCount > 0 &&
            firstBitmapLogged.get() &&
            pathWorkId.matches(Regex("\\d{1,12}")) &&
            pathEpisodeToken.matches(Regex("\\d{1,12}"))
        ) {
            for (offset in 0 until visibleImmediateCount) {
                val pageIndex = startIndex + offset
                val pageName = "p%03d.%s".format(Locale.ROOT, pageIndex + 1, initialExtension)
                val image = "https://fifa.worldcup73.xyz/wt/episodes/$pathWorkId/$pathEpisodeToken/$pageName"
                val started = ReaderImageCache.startForegroundStreamFetch(
                    appContext,
                    manga,
                    image,
                    null,
                    false,
                    null,
                    pageIndex,
                    true
                )
                if (started) wtHedgeStartedCount++
            }
        }
        var jpgHedgeStarted = false
        var jpgHedgeScheduled = false
        if (visibleImmediateCount > 0 && segment == "webtoon") {
            val hedgeExtension = if (initialExtension.equals("jpg", ignoreCase = true)) "jpeg" else "jpg"
            val jpgHedge = replaceNtkGeneratedImageExtension(first, hedgeExtension)
            if (jpgHedge.isNotEmpty() && jpgHedge != first) {
                jpgHedgeScheduled = scheduleDelayedInitialJpgHedge(
                    first,
                    jpgHedge,
                    SystemClock.elapsedRealtime()
                )
            }
        }
        if (urls.size > startIndex + visibleImmediateCount && initialContinuousDrawableDelivered(currentStartPage())) {
            urls.drop(startIndex + visibleImmediateCount).forEachIndexed { tailIndex, image ->
                val pageIndex = startIndex + visibleImmediateCount + tailIndex
                main.postDelayed({
                    if (cancelled.get()) return@postDelayed
                    if (!initialContinuousDrawableDelivered(currentStartPage())) return@postDelayed
                    val started = ReaderImageCache.startForegroundStreamFetch(
                        appContext,
                        manga,
                        image,
                        null,
                        false,
                        null,
                        pageIndex,
                        false
                    )
                    Log.d(
                        TAG,
                        "ntk_immediate_generated_initial_tail_prime path=$path " +
                            "page=$pageIndex started=$started first=${image.substringAfterLast('/')}"
                    )
                }, NTK_IMMEDIATE_GENERATED_INITIAL_TAIL_STAGGER_MS * (tailIndex + 1))
            }
        }
        Log.d(
            TAG,
            "ntk_immediate_generated_initial_prime path=$path segment=$segment " +
                "workId=$imageWorkId imageEpisodeId=$imageEpisodeId count=${urls.size} " +
                "immediateCount=$immediateCount visibleImmediateCount=$visibleImmediateCount " +
                "started=${startedCount > 0} startedCount=$startedCount " +
                "hedgeStartedCount=$hedgeStartedCount wtHedgeStartedCount=$wtHedgeStartedCount " +
                "jpgHedgeStarted=$jpgHedgeStarted jpgHedgeScheduled=$jpgHedgeScheduled " +
                "first=${first.substringAfterLast('/')}"
        )
        ViewerWarmupManager.logMetric("reader_ntk_immediate_generated_initial_prime", startedCount.toLong())
        return true
    }

    private fun hasTrustedKnownGeneratedInitialCount(target: Manga): Boolean {
        val knownCount = target.ntkImageCount
        if (knownCount <= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD) return false
        val path = target.ntkEpisodePath?.trim().orEmpty()
        val match = NTK_VIEWER_EPISODE_PATH.matchEntire(path) ?: return false
        val segment = match.groupValues[1].lowercase(Locale.ROOT)
        val pathWorkId = match.groupValues[2].trim()
        val pathEpisodeToken = match.groupValues[3].trim()
        val imageWorkId = target.ntkImageWorkId.trim().ifEmpty { pathWorkId }
        val recordedImageEpisodeId = target.ntkImageEpisodeId.trim()
        if (segment != "webtoon" && segment != "manhwa") return false
        if (!pathWorkId.matches(Regex("\\d{1,12}"))) return false
        if (!pathEpisodeToken.matches(Regex("\\d{1,12}"))) return false
        if (!imageWorkId.matches(Regex("\\d{1,12}"))) return false
        val imageEpisodeId = recordedImageEpisodeId.ifEmpty { pathEpisodeToken }
        if (!imageEpisodeId.matches(Regex("\\d{1,12}"))) return false
        if (imageWorkId != pathWorkId) return false
        return imageEpisodeId == pathEpisodeToken || recordedImageEpisodeId.isBlank()
    }

    private fun installImmediateGeneratedEarlyUrls(urls: List<String>, reason: String): Boolean {
        if (cancelled.get() || urls.isEmpty() || pagesInstalled.get()) return false
        if (!isNtkSource(manga, title)) return false
        val loadStartedAt = repositoryLoadStartedAtMs.get().takeIf { it > 0L }
            ?: SystemClock.elapsedRealtime()
        val installed = installEarlyNtkUrls(manga, urls, loadStartedAt)
        logNtkRepositoryStage(
            manga,
            "immediate_generated_early_install",
            "reason=$reason,installed=$installed,count=${urls.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        return installed
    }

    private fun ntkImmediateGeneratedInitialForegroundPages(segment: String): Int {
        return if (segment.equals("webtoon", ignoreCase = true)) {
            NTK_WEBTOON_IMMEDIATE_GENERATED_INITIAL_FOREGROUND_PAGES
        } else {
            NTK_IMMEDIATE_GENERATED_INITIAL_FOREGROUND_PAGES
        }
    }

    private fun startVerifiedNtkGeneratedInitialProbe(
        path: String,
        segment: String,
        imageWorkId: String,
        pathEpisodeToken: String,
        recordedImageEpisodeId: String,
        loadStartedAt: Long
    ) {
        if (isModernProtectedNumericNtkPath(path)) {
            manga.startNtkEarlyViewerApiPrefetch(MainApplication.getHttpClient())
            Log.d(TAG, "ntk_verified_generated_initial_probe_skip_protected_api path=$path")
            return
        }
        if (!imageWorkId.matches(Regex("\\d{1,12}"))) return
        val candidateEpisodeIds = LinkedHashSet<String>()
        val hasNumericPathEpisode = pathEpisodeToken.matches(Regex("\\d{1,12}"))
        if (hasNumericPathEpisode) {
            candidateEpisodeIds.add(pathEpisodeToken)
            if (recordedImageEpisodeId.matches(Regex("\\d{1,12}"))) {
                candidateEpisodeIds.add(recordedImageEpisodeId)
            }
        } else if (recordedImageEpisodeId.matches(Regex("\\d{1,12}"))) {
            candidateEpisodeIds.add(recordedImageEpisodeId)
        }
        if (candidateEpisodeIds.isEmpty()) return
        val count = when {
            manga.ntkImageCount > 0 -> manga.ntkImageCount
            else -> NTK_WEBTOON_GENERATED_INITIAL_RECOVERY_PAGES
        }
        val started = AtomicBoolean(false)
        startSpeculativeVerifiedInitialCandidateStreams(
            path = path,
            segment = segment,
            imageWorkId = imageWorkId,
            candidateEpisodeIds = candidateEpisodeIds,
            initialPageCount = count
        )
        Log.d(
            TAG,
            "ntk_verified_generated_initial_probe_skip path=$path workId=$imageWorkId " +
                "pathEpisodeId=$pathEpisodeToken recordedEpisodeId=$recordedImageEpisodeId"
        )
        ViewerWarmupManager.logMetric("reader_ntk_verified_generated_initial_probe_skip", 1L)
        return
        Thread({
            Process.setThreadPriority(Process.THREAD_PRIORITY_DEFAULT)
            val startedAt = SystemClock.elapsedRealtime()
            try {
                val probes = ArrayList<Pair<String, String>>()
                for (episodeId in candidateEpisodeIds) {
                    for (extension in listOf("jpg", "jpeg", "png", "webp")) {
                        probes.add(episodeId to extension)
                    }
                }
                val latch = CountDownLatch(probes.size)
                val winner = AtomicReference<Pair<String, String>?>(null)
                probes.forEach { probe ->
                    Thread({
                        try {
                            if (cancelled.get() || winner.get() != null) return@Thread
                            val first = ntkGeneratedInitialUrl(segment, imageWorkId, probe.first, 1, probe.second)
                            if (isReachableNtkGeneratedProbe(first)) {
                                winner.compareAndSet(null, probe)
                            }
                        } catch (_: Exception) {
                        } finally {
                            latch.countDown()
                        }
                    }, "ntk-generated-probe").apply {
                        isDaemon = true
                        start()
                    }
                }
                latch.await(NTK_GENERATED_INITIAL_PROBE_TOTAL_WAIT_MS, TimeUnit.MILLISECONDS)
                val hit = winner.get()
                if (hit != null && !cancelled.get()) {
                    val urls = (1..count).map { page ->
                        ntkGeneratedInitialUrl(segment, imageWorkId, hit.first, page, hit.second)
                    }
                    ReaderImageCache.rememberEarlyNtkImageUrls(path, urls)
                    urls.take(ntkImmediateGeneratedInitialForegroundPages(segment))
                        .forEachIndexed { index, image ->
                            ReaderImageCache.startForegroundStreamFetch(
                                appContext,
                                manga,
                                image,
                                null,
                                false,
                                null,
                                index,
                                true
                            )
                        }
                    Log.d(
                        TAG,
                        "ntk_verified_generated_initial_publish path=$path workId=$imageWorkId " +
                            "episodeId=${hit.first} extension=${hit.second} count=${urls.size} " +
                            "ms=${SystemClock.elapsedRealtime() - startedAt}"
                    )
                    started.set(true)
                    return@Thread
                }
                if (ntkGeneratedBatchUnavailablePaths.add(path)) {
                    Log.d(
                        TAG,
                        "ntk_verified_generated_initial_unavailable path=$path workId=$imageWorkId " +
                            "pathEpisodeId=$pathEpisodeToken recordedEpisodeId=$recordedImageEpisodeId " +
                            "ms=${SystemClock.elapsedRealtime() - startedAt}"
                    )
                    replaceUnavailableGeneratedInitialWithAdjacent(manga, loadStartedAt)
                }
            } catch (e: Exception) {
                if (!cancelled.get()) recordIfUnexpected(e)
            } finally {
                if (!started.get()) {
                    ViewerWarmupManager.logMetric("reader_ntk_verified_generated_initial_miss", 1L)
                }
            }
        }, "ntk-verified-generated-initial").apply {
            isDaemon = true
            start()
        }
    }

    private fun startSpeculativeVerifiedInitialCandidateStreams(
        path: String,
        segment: String,
        imageWorkId: String,
        candidateEpisodeIds: Set<String>,
        initialPageCount: Int
    ) {
        if (isModernProtectedNumericNtkPath(path)) return
        if (segment != "webtoon") return
        val firstCandidate = candidateEpisodeIds.firstOrNull { it.matches(Regex("\\d{1,12}")) } ?: return
        val startIndex = currentStartPage().coerceAtLeast(0)
        val streamLimit = ntkInitialGeneratedDecodeRunwayPages()
        val streamCount = initialPageCount.coerceAtLeast(1).coerceAtMost(streamLimit)
        val preferredExtension = "png"
        val urls = (startIndex + 1..startIndex + streamCount).map { page ->
            ntkGeneratedInitialUrl(segment, imageWorkId, firstCandidate, page, preferredExtension)
        }
        try {
            ReaderImageCache.rememberEarlyNtkImageUrls(path, urls)
            var startedCount = 0
            val streamUrls = urls.take(streamLimit).distinct()
            streamUrls.forEach { image ->
                val page = generatedImagePageNumber(image)
                val pageIndex = if (page > 0) page - 1 else startIndex
                val started = ReaderImageCache.startForegroundStreamFetch(
                    appContext,
                    manga,
                    image,
                    null,
                    false,
                    null,
                    pageIndex,
                    true
                )
                if (started) startedCount++
            }
            Log.d(
                TAG,
                "ntk_verified_generated_initial_candidate_stream path=$path " +
                "workId=$imageWorkId episodeId=$firstCandidate started=$startedCount " +
                    "count=${urls.size} extension=$preferredExtension " +
                    "first=${urls.firstOrNull().orEmpty().substringAfterLast('/')}"
            )
        } catch (e: Exception) {
            Log.d(TAG, "ntk_verified_generated_initial_candidate_stream_error path=$path,$e")
        }
    }

    private fun generatedImagePageNumber(image: String): Int {
        val name = image.substringBefore('?').substringBefore('#').substringAfterLast('/')
        val match = Regex("(?i)^p(\\d{1,4})\\.(?:jpg|jpeg|png|webp)$").find(name) ?: return -1
        return match.groupValues.getOrNull(1)?.toIntOrNull() ?: -1
    }

    private fun immediateGeneratedInitialPrimaryExtension(
        segment: String,
        pathWorkId: String,
        generatedWorkId: String,
        pathEpisodeToken: String,
        recordedImageEpisodeId: String
    ): String {
        if (segment != "webtoon") return ntkGeneratedInitialExtension(segment, pathEpisodeToken)
        return ntkGeneratedInitialExtension(segment, pathEpisodeToken)
    }

    private fun immediateGeneratedInitialUrls(
        segment: String,
        workId: String,
        episodeId: String,
        count: Int,
        extension: String
    ): ArrayList<String> {
        val urls = ArrayList<String>(count)
        for (page in 1..count) {
            urls.add(ntkGeneratedInitialUrl(segment, workId, episodeId, page, extension))
        }
        return urls
    }

    private fun startImmediateInitialExtensionHedges(
        segment: String,
        workId: String,
        episodeId: String,
        count: Int,
        primaryExtension: String,
        immediateCount: Int
    ): Int {
        if (segment != "webtoon" || count <= 0 || immediateCount <= 0) return 0
        val hedgeExtensions = listOf("png", "jpg", "jpeg", "webp").filter { it != primaryExtension }
        if (hedgeExtensions.isEmpty()) return 0
        val hedgePages = minOf(
            count,
            immediateCount,
            NTK_IMMEDIATE_GENERATED_INITIAL_EXTENSION_HEDGE_PAGES
        )
        for (page in 1..hedgePages) {
            for (extension in hedgeExtensions) {
                val image = ntkGeneratedInitialUrl(segment, workId, episodeId, page, extension)
                val primaryImage = ntkGeneratedInitialUrl(segment, workId, episodeId, page, primaryExtension)
                AppDispatchers.runIoDelayed({
                    if (cancelled.get()) return@runIoDelayed
                    if (ReaderImageCache.cachedExactFile(appContext, manga, primaryImage) != null) {
                        Log.d(
                            TAG,
                            "ntk_immediate_generated_initial_extension_hedge_skip path=${manga.ntkEpisodePath} " +
                                "page=$page reason=primary_cached hedge=${image.substringAfterLast('/')}"
                        )
                        return@runIoDelayed
                    }
                    if (!ReaderImageCache.isKnownNtkGeneratedNotFound(manga, primaryImage)) {
                        Log.d(
                            TAG,
                            "ntk_immediate_generated_initial_extension_hedge_skip path=${manga.ntkEpisodePath} " +
                                "page=$page reason=primary_not_failed primary=$primaryExtension " +
                                "hedge=${image.substringAfterLast('/')}"
                        )
                        return@runIoDelayed
                    }
                    val started = ReaderImageCache.startForegroundStreamFetch(
                        appContext,
                        manga,
                        image,
                        null,
                        false,
                        null,
                        page - 1,
                        true
                    )
                    Log.d(
                        TAG,
                        "ntk_immediate_generated_initial_extension_hedge_start path=${manga.ntkEpisodePath} " +
                            "page=$page started=$started primary=$primaryExtension hedge=${image.substringAfterLast('/')}"
                    )
                }, NTK_IMMEDIATE_GENERATED_INITIAL_EXTENSION_HEDGE_DELAY_MS)
            }
        }
        Log.d(
            TAG,
            "ntk_immediate_generated_initial_extension_hedge path=${manga.ntkEpisodePath} " +
                "primary=$primaryExtension pages=$hedgePages scheduled=${hedgePages * hedgeExtensions.size}"
        )
        return 0
    }

    private fun ntkGeneratedInitialUrl(
        segment: String,
        workId: String,
        episodeId: String,
        page: Int,
        extension: String
    ): String {
        val pageName = "p%03d.%s".format(Locale.ROOT, page, extension)
        return if (segment == "webtoon") {
            "http://fifa.worldcup73.xyz/black/episodes/$workId/$episodeId/$pageName"
        } else if (segment == "manhwa") {
            "https://booktoki9.org/manhwa/$workId/$episodeId/$pageName"
        } else {
            "http://apihost93.com/$segment/$workId/$episodeId/$pageName"
        }
    }

    private fun isReachableNtkGeneratedProbe(url: String): Boolean {
        val connection = (URL(url).openConnection() as HttpURLConnection).apply {
            requestMethod = "GET"
            connectTimeout = NTK_GENERATED_INITIAL_PROBE_TIMEOUT_MS
            readTimeout = NTK_GENERATED_INITIAL_PROBE_TIMEOUT_MS
            instanceFollowRedirects = true
            setRequestProperty("Range", "bytes=0-0")
            setRequestProperty(
                "User-Agent",
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 " +
                    "(KHTML, like Gecko) Chrome/136.0.0.0 Safari/537.36"
            )
            setRequestProperty("Accept", "image/avif,image/webp,image/apng,image/*,*/*;q=0.8")
        }
        return try {
            val code = connection.responseCode
            code in 200..299
        } finally {
            connection.disconnect()
        }
    }

    private fun scheduleDelayedInitialJpgHedge(
        first: String,
        jpgHedge: String,
        scheduledAtMs: Long
    ): Boolean {
        if (first.isBlank() || jpgHedge.isBlank()) return false
        AppDispatchers.runIoDelayed({
            maybeStartDelayedInitialJpgHedge(first, jpgHedge, scheduledAtMs)
        }, NTK_INITIAL_JPG_HEDGE_DELAY_MS)
        Log.d(
            TAG,
            "ntk_immediate_generated_initial_jpg_hedge_scheduled path=${manga.ntkEpisodePath} " +
                "delayMs=$NTK_INITIAL_JPG_HEDGE_DELAY_MS first=${first.substringAfterLast('/')} " +
                "hedge=${jpgHedge.substringAfterLast('/')}"
        )
        return true
    }

    private fun maybeStartDelayedInitialJpgHedge(
        first: String,
        jpgHedge: String,
        scheduledAtMs: Long
    ) {
        if (cancelled.get()) return
        val elapsedMs = SystemClock.elapsedRealtime() - scheduledAtMs
        val hedgePage = generatedImagePageNumber(jpgHedge).takeIf { it > 0 } ?: 1
        val hedgePageIndex = hedgePage - 1
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        if (hedgePageIndex < anchor) {
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_jpg_hedge_skip path=${manga.ntkEpisodePath} " +
                    "reason=stale_anchor anchor=$anchor page=$hedgePageIndex elapsedMs=$elapsedMs " +
                    "hedge=${jpgHedge.substringAfterLast('/')}"
            )
            return
        }
        if (ReaderImageCache.cachedExactFile(appContext, manga, first) != null ||
            hasRecentInitialGeneratedSuccess(first)
        ) {
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_jpg_hedge_skip path=${manga.ntkEpisodePath} " +
                    "reason=primary_ready elapsedMs=$elapsedMs first=${first.substringAfterLast('/')}"
            )
            return
        }
        if (!ReaderImageCache.isKnownNtkGeneratedNotFound(manga, first)) {
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_jpg_hedge_skip path=${manga.ntkEpisodePath} " +
                    "reason=primary_not_failed elapsedMs=$elapsedMs first=${first.substringAfterLast('/')}"
            )
            return
        }
        if (ReaderImageCache.hasActiveFetch(manga, first) &&
            elapsedMs < NTK_INITIAL_JPG_HEDGE_MAX_WAIT_MS
        ) {
            AppDispatchers.runIoDelayed({
                maybeStartDelayedInitialJpgHedge(first, jpgHedge, scheduledAtMs)
            }, NTK_INITIAL_JPG_HEDGE_RECHECK_MS)
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_jpg_hedge_wait path=${manga.ntkEpisodePath} " +
                    "elapsedMs=$elapsedMs recheckMs=$NTK_INITIAL_JPG_HEDGE_RECHECK_MS " +
                    "first=${first.substringAfterLast('/')}"
            )
            return
        }
        val started = ReaderImageCache.startForegroundStreamFetch(
            appContext,
            manga,
            jpgHedge,
            null,
            false,
            null,
            hedgePageIndex,
            true
        )
        Log.d(
            TAG,
            "ntk_immediate_generated_initial_jpg_hedge_start path=${manga.ntkEpisodePath} " +
                "started=$started elapsedMs=$elapsedMs first=${first.substringAfterLast('/')} " +
                "hedge=${jpgHedge.substringAfterLast('/')}"
        )
    }

    private fun hasRecentInitialGeneratedSuccess(first: String): Boolean {
        return ReaderImageCache
            .earlyNtkGeneratedSuccessImageUrls(manga.ntkEpisodePath, SystemClock.elapsedRealtime() - 30000L)
            .any { it == first }
    }

    private fun scheduleNtkInitialTailGeneratedStreamAfterDelay(
        target: Manga,
        image: String,
        pageIndex: Int,
        delayMs: Long
    ) {
        main.postDelayed({
            if (cancelled.get()) return@postDelayed
            val quietMs = ntkBackgroundWarmQuietRemainingMs()
            if (!firstBitmapLogged.get() || quietMs > 0L) {
                scheduleNtkInitialTailGeneratedStreamAfterDelay(
                    target,
                    image,
                    pageIndex,
                    if (quietMs > 0L) quietMs else NTK_BACKGROUND_WARM_RECHECK_MS
                )
                return@postDelayed
            }
            val started = ReaderImageCache.startForegroundStreamFetch(
                appContext,
                target,
                image,
                null,
                false,
                null,
                pageIndex,
                false
            )
            Log.d(
                TAG,
                "ntk_immediate_generated_initial_tail_after_first_bitmap path=${target.ntkEpisodePath} " +
                    "page=$pageIndex started=$started first=${image.substringAfterLast('/')}"
            )
        }, delayMs.coerceAtLeast(NTK_BACKGROUND_WARM_RECHECK_MS))
    }

    private fun ntkGeneratedInitialExtension(segment: String, pathEpisodeToken: String): String {
        if (segment == "webtoon" && pathEpisodeToken.matches(Regex("\\d{1,12}"))) return "png"
        return "jpg"
    }

    private fun replaceNtkGeneratedImageExtension(url: String, extension: String): String {
        if (url.isEmpty() || extension.isEmpty()) return ""
        val query = url.indexOf('?').takeIf { it >= 0 } ?: url.length
        val fragment = url.indexOf('#').takeIf { it >= 0 } ?: url.length
        val cut = minOf(query, fragment)
        val main = url.substring(0, cut)
        val suffix = url.substring(cut)
        val dot = main.lastIndexOf('.')
        val slash = main.lastIndexOf('/')
        if (dot <= slash) return url
        return main.substring(0, dot + 1) + extension + suffix
    }

    private fun loadFromRepository() {
        if (!repositoryLoading.compareAndSet(false, true)) return
        val queuedAt = SystemClock.elapsedRealtime()
        network.execute {
            val startedAt = SystemClock.elapsedRealtime()
            repositoryLoadStartedAtMs.set(startedAt)
            try {
                if (pagesInstalled.get()) {
                    logNtkRepositoryStage(manga, "load_skip_pages_installed", "queueMs=${startedAt - queuedAt}")
                    return@execute
                }
                logNtkRepositoryStage(manga, "load_start", "queueMs=${startedAt - queuedAt}")
                attachTitle()
                if (pagesInstalled.get()) {
                    logNtkRepositoryStage(
                        manga,
                        "load_skip_pages_installed_after_attach",
                        "ms=${SystemClock.elapsedRealtime() - startedAt}"
                    )
                    return@execute
                }
                var activeManga = manga
                if (installPreloadedEarlyNtkUrlsIfReady(activeManga, startedAt)) {
                    return@execute
                }
                var urls = imageRepository.imageUrls(activeManga, appContext)
                logNtkRepositoryStage(
                    activeManga,
                    "cached_urls_checked",
                    "count=${urls?.size ?: 0},ms=${SystemClock.elapsedRealtime() - startedAt}"
                )
                if (urls.isNullOrEmpty()) {
                    val cancellation = repositoryCancellation(userVisible = true)
                    val ntkInitial = isNtkSource(manga, title)
                    if (ntkInitial && !isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) {
                        cancellation.prioritizeWebViewFallback()
                    }
                    val initialFetch = if (ntkInitial) {
                        fetchInitialAllowingEarlyNtkUrls(activeManga, cancellation, startedAt)
                    } else {
                        try {
                            InitialFetchOutcome(imageRepository.fetchViewerInitial(activeManga, cancellation), false)
                        } finally {
                            releaseRepositoryCancellation(cancellation)
                        }
                    }
                    if (initialFetch.installedEarly) {
                        return@execute
                    }
                    val result = initialFetch.result
                    logNtkRepositoryStage(activeManga, "fetch_initial_done", "result=$result,ms=${SystemClock.elapsedRealtime() - startedAt}")
                    if (cancelled.get()) return@execute
                    if (result != Title.LOAD_OK && result != Title.LOAD_CAPTCHA) {
                        if (waitInstallEarlyNtkUrlsBeforeUnavailable(activeManga, startedAt)) {
                            return@execute
                        }
                        resolveInitialNtkUnavailableEpisode(activeManga)?.let { replacement ->
                            activeManga = replacement.first
                            urls = replacement.second
                            Log.d(
                                TAG,
                                "ntk_initial_unavailable_replaced sourcePath=${manga.ntkEpisodePath} " +
                                    "targetPath=${activeManga.ntkEpisodePath} images=${urls.size}"
                            )
                            val startPage = 0
                            startInitialForegroundStreamIfNeeded(activeManga, urls, startPage, startedAt)
                            installImagesForManga(activeManga, urls, startPage, false)
                            flushEarlyPreparedBitmaps()
                            requestPageForeground(startPage)
                            requestInitialContinuousPagesFromEarlyUrls(startPage, urls.size)
                            requestInitialFanout(startPage)
                            return@execute
                        }
                    }
                    if (result != Title.LOAD_OK) {
                        if (result == Title.LOAD_CAPTCHA) {
                            postCaptchaRequired(manga)
                            return@execute
                        }
                        postInitialPageError("이미지를 불러오지 못했습니다")
                        return@execute
                    }
                    urls = imageRepository.imageUrls(activeManga, appContext)
                }
                if (urls.isNullOrEmpty()) {
                    postInitialPageError("표시할 이미지가 없습니다")
                    return@execute
                }
                if (installEarlyGeneratedNtkUrlsIfBoardOnly(activeManga, urls, startedAt)) {
                    return@execute
                }
                val startPage = requestedStartPage().coerceIn(0, urls.lastIndex)
                startInitialForegroundStreamIfNeeded(activeManga, urls, startPage, startedAt)
                logNtkRepositoryStage(activeManga, "urls_ready", "count=${urls.size},ms=${SystemClock.elapsedRealtime() - startedAt}")
                installImagesForManga(activeManga, urls, startPage, false)
                flushEarlyPreparedBitmaps()
                logNtkRepositoryStage(activeManga, "request_foreground", "page=$startPage,ms=${SystemClock.elapsedRealtime() - startedAt}")
                requestPageForeground(startPage)
                requestInitialContinuousPagesFromEarlyUrls(startPage, urls.size)
                requestInitialFanout(startPage)
            } catch (e: Exception) {
                recordIfUnexpected(e)
                if (!isExpectedCancellation(e)) postInitialPageError("이미지를 불러오지 못했습니다")
            } finally {
                repositoryLoading.set(false)
            }
        }
    }

    private fun waitInstallEarlyNtkUrlsBeforeUnavailable(target: Manga, loadStartedAt: Long): Boolean {
        if (!isNtkSource(target, title) || firstBitmapLogged.get()) return false
        val deadline = SystemClock.elapsedRealtime() + NTK_UNAVAILABLE_EARLY_URL_GRACE_MS
        while (!cancelled.get() && !firstBitmapLogged.get() && SystemClock.elapsedRealtime() < deadline) {
            val earlyUrls = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, loadStartedAt)
            if (earlyUrls.size >= ntkEarlyUrlMinCount(target) && installEarlyNtkUrls(target, earlyUrls, loadStartedAt)) {
                logNtkRepositoryStage(
                    target,
                    "early_urls_before_unavailable",
                    "count=${earlyUrls.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                return true
            }
            try {
                Thread.sleep(NTK_UNAVAILABLE_EARLY_URL_POLL_MS)
            } catch (e: InterruptedException) {
                Thread.currentThread().interrupt()
                return false
            }
        }
        if (isKpWebtoonSlugEpisodePath(target.ntkEpisodePath)) {
            val handoffDeadline = max(deadline, loadStartedAt + NTK_EARLY_URL_HANDOFF_WAIT_MS)
            while (!cancelled.get() && !firstBitmapLogged.get() && SystemClock.elapsedRealtime() < handoffDeadline) {
                val protectedUrls = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, loadStartedAt)
                if (protectedUrls.any { isNtkUploadCdnImageUrl(it) || isNaverWebtoonPageImageUrl(it) } &&
                    installEarlyNtkUrls(target, protectedUrls, loadStartedAt)
                ) {
                    logNtkRepositoryStage(
                        target,
                        "early_kp_upload_urls_before_unavailable",
                        "count=${protectedUrls.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    return true
                }
                if (protectedUrls.none { isNtkProtectedViewerApiImage(it) }) return false
                logNtkRepositoryStage(
                    target,
                    "early_kp_protected_urls_wait_upload_before_unavailable",
                    "count=${protectedUrls.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                try {
                    Thread.sleep(NTK_EARLY_URL_POLL_MS)
                } catch (e: InterruptedException) {
                    Thread.currentThread().interrupt()
                    return false
                }
            }
        }
        return false
    }

    private fun ntkEarlyUrlMinCount(target: Manga): Int {
        if (isKpWebtoonSlugEpisodePath(target.ntkEpisodePath)) {
            return NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
        }
        return 1
    }

    private fun installPreloadedEarlyNtkUrlsIfReady(target: Manga, loadStartedAt: Long): Boolean {
        if (!isNtkSource(target, title)) return false
        val minCreatedAt = max(0L, loadStartedAt - NTK_PRELOADED_EARLY_URL_ACCEPT_MS)
        val earlyUrls = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, minCreatedAt)
        if (earlyUrls.size < ntkEarlyUrlMinCount(target)) return false
        if (!installEarlyNtkUrls(target, earlyUrls, loadStartedAt)) return false
        logNtkRepositoryStage(
            target,
            "early_urls_preloaded",
            "count=${earlyUrls.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        return true
    }

    private fun fetchInitialAllowingEarlyNtkUrls(
        target: Manga,
        cancellation: MangaRepository.Cancellation,
        loadStartedAt: Long
    ): InitialFetchOutcome {
        val task = FutureTask {
            imageRepository.fetchViewerInitial(target, cancellation)
        }
        try {
            network.execute(task)
        } catch (_: RejectedExecutionException) {
            return try {
                InitialFetchOutcome(imageRepository.fetchViewerInitial(target, cancellation), false)
            } finally {
                releaseRepositoryCancellation(cancellation)
            }
        }

        val deadline = loadStartedAt + NTK_EARLY_URL_HANDOFF_WAIT_MS
        var releaseDeferred = false
        try {
            while (!cancelled.get() && !task.isDone && SystemClock.elapsedRealtime() < deadline) {
                val earlyUrls = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, loadStartedAt)
                if (earlyUrls.size >= ntkEarlyUrlMinCount(target) && installEarlyNtkUrls(target, earlyUrls, loadStartedAt)) {
                    releaseDeferred = true
                    finishInitialFetchAfterEarlyInstall(target, task, cancellation, loadStartedAt)
                    return InitialFetchOutcome(Title.LOAD_OK, true)
                }
                try {
                    Thread.sleep(NTK_EARLY_URL_POLL_MS)
                } catch (e: InterruptedException) {
                    Thread.currentThread().interrupt()
                    throw e
                }
            }
            if (isNtkSource(target, title) && !task.isDone) {
                val lateDeadline = loadStartedAt + NTK_EARLY_URL_LATE_HANDOFF_WAIT_MS
                while (!cancelled.get() && !task.isDone && SystemClock.elapsedRealtime() < lateDeadline) {
                    val earlyUrls = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, loadStartedAt)
                    if (earlyUrls.size >= ntkEarlyUrlMinCount(target) &&
                        installEarlyNtkUrls(target, earlyUrls, loadStartedAt)
                    ) {
                        releaseDeferred = true
                        finishInitialFetchAfterEarlyInstall(target, task, cancellation, loadStartedAt)
                        logNtkRepositoryStage(
                            target,
                            "early_urls_before_fetch_done_late",
                            "count=${earlyUrls.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                        )
                        return InitialFetchOutcome(Title.LOAD_OK, true)
                    }
                    try {
                        Thread.sleep(NTK_EARLY_URL_POLL_MS)
                    } catch (e: InterruptedException) {
                        Thread.currentThread().interrupt()
                        throw e
                    }
                }
            }
            val result = task.get()
            val earlyUrls = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, loadStartedAt)
            if (earlyUrls.size >= ntkEarlyUrlMinCount(target) && installEarlyNtkUrls(target, earlyUrls, loadStartedAt)) {
                releaseDeferred = true
                finishInitialFetchAfterEarlyInstall(target, task, cancellation, loadStartedAt)
                logNtkRepositoryStage(
                    target,
                    "early_urls_after_fetch_done",
                    "count=${earlyUrls.size},result=$result,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                return InitialFetchOutcome(Title.LOAD_OK, true)
            }
            if (result != Title.LOAD_OK && target.ntkViewerParseReason == "unavailable") {
                logNtkRepositoryStage(
                    target,
                    "early_urls_after_fetch_done_skip_unavailable",
                    "result=$result,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                return InitialFetchOutcome(result, false)
            }
            val shouldKeepPollingForEarlyUrls =
                result != Title.LOAD_OK ||
                    (isNtkSource(target, title) && imageRepository.imageUrls(target, appContext).isNullOrEmpty())
            if (shouldKeepPollingForEarlyUrls) {
                while (!cancelled.get() && SystemClock.elapsedRealtime() < deadline) {
                    val delayedEarlyUrls = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, loadStartedAt)
                    if (delayedEarlyUrls.size >= ntkEarlyUrlMinCount(target) &&
                        installEarlyNtkUrls(target, delayedEarlyUrls, loadStartedAt)
                    ) {
                        releaseDeferred = true
                        finishInitialFetchAfterEarlyInstall(target, task, cancellation, loadStartedAt)
                        logNtkRepositoryStage(
                            target,
                            "early_urls_after_fetch_done_late",
                            "count=${delayedEarlyUrls.size},result=$result,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                        )
                        return InitialFetchOutcome(Title.LOAD_OK, true)
                    }
                    if (result == Title.LOAD_OK &&
                        !imageRepository.imageUrls(target, appContext).isNullOrEmpty()
                    ) {
                        break
                    }
                    try {
                        Thread.sleep(NTK_EARLY_URL_POLL_MS)
                    } catch (e: InterruptedException) {
                        Thread.currentThread().interrupt()
                        throw e
                    }
                }
            }
            return InitialFetchOutcome(result, false)
        } catch (e: ExecutionException) {
            throw (e.cause ?: e)
        } finally {
            if (!releaseDeferred) releaseRepositoryCancellation(cancellation)
        }
    }

    private fun installEarlyNtkUrls(target: Manga, urls: List<String>, loadStartedAt: Long): Boolean {
        if (cancelled.get() || pagesInstalled.get()) return false
        val latest = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, loadStartedAt)
        val sourceUrls = if (latest.size > urls.size) latest else urls
        if (shouldWaitForCompleteKpApiUrls(target, sourceUrls)) {
            logNtkRepositoryStage(
                target,
                "early_urls_defer_kp_partial",
                "count=${sourceUrls.size},raw=${urls.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            return false
        }
        val installPartialOnly = shouldInstallPartialEarlyNtkUrlsWithoutExpansion(target, sourceUrls)
        val partialRunwayUrls = if (installPartialOnly) {
            initialContinuousRunwayUrlsFromPartial(target, sourceUrls)
        } else {
            null
        }
        val initialUrls = if (partialRunwayUrls != null) {
            partialRunwayUrls
        } else if (installPartialOnly) {
            sourceUrls
        } else if (shouldLimitLargeUntrustedGeneratedEarlyUrls(target, sourceUrls)) {
            limitedLargeUntrustedGeneratedUrls(target, sourceUrls)
        } else if (shouldKeepManhwaGeneratedEarlyToObservedUrls(target, sourceUrls)) {
            sourceUrls
        } else if (shouldDeferGeneratedEarlyExpansionBeforeFirstBitmap(target, sourceUrls)) {
            expandInitialVerifiedGeneratedEarlyUrls(target, sourceUrls)
        } else {
            expandVerifiedGeneratedEarlyUrls(target, sourceUrls)
        }
        val startPage = requestedStartPage().coerceIn(0, initialUrls.lastIndex)
        val directManifestCount = ReaderImageCache.trustedNtkImageApiCount(
            target.ntkEpisodePath,
            SystemClock.elapsedRealtime() - 30_000L
        )
        val authoritativeNativeDirectManifest = directManifestCount > 0 &&
            initialUrls.size >= directManifestCount &&
            ReaderImageCache.hasCompleteValidatedNativeDirectEarlyNtkImageUrls(
                target.ntkEpisodePath,
                directManifestCount,
                SystemClock.elapsedRealtime() - 30_000L
            )
        if (isNtkSource(target, title) && ntkCoordinator == null) {
            ntkCoordinator = NtkEpisodeCoordinator(target.ntkEpisodePath, true, startPage)
        }
        logNtkRepositoryStage(
            target,
            "early_urls_ready",
                "count=${initialUrls.size},raw=${urls.size},source=${sourceUrls.size}," +
                "partialOnly=$installPartialOnly,partialRunway=${partialRunwayUrls?.size ?: 0}," +
                "page=$startPage,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        val startImage = initialUrls.getOrNull(startPage).orEmpty()
        val naverOriginalFirst = isNaverWebtoonPageImageUrl(startImage)
        val naverStartCached = naverOriginalFirst &&
            ReaderImageCache.cachedFile(appContext, target, startImage) != null
        if (!naverOriginalFirst) {
            registerNtkAnchorAssetCachedDecode(
                startPage,
                target,
                startImage,
                "early_urls_ready_preinstall",
                loadStartedAt
            )
            startNaverOriginalForegroundStreamBeforeInstall(target, initialUrls, startPage, loadStartedAt)
            startEarlyNtkAnchorForegroundStreamBeforeInstall(target, initialUrls, startPage, loadStartedAt)
        }
        val anchorStreamStartedBeforeInstall = if (!naverOriginalFirst) {
            startInitialForegroundStreamIfNeeded(target, initialUrls, startPage, loadStartedAt)
        } else {
            false
        }
        installImagesForManga(target, initialUrls, startPage, false)
        if (isNtkSource(target, title)) {
            val publishInitialStructure = Runnable {
                if (!cancelled.get()) {
                    deliverInitialPagesReadyForCurrentPagesIfNeeded()
                }
            }
            if (!mainImmediate.post(publishInitialStructure)) {
                main.post(publishInitialStructure)
            }
        }
        logNtkRepositoryStage(
            target,
            "request_foreground",
            "source=early,page=$startPage,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        if (!naverOriginalFirst) {
            requestPageForeground(startPage)
        }
        val naverImmediateDecode = naverOriginalFirst &&
            scheduleNaverOriginalImmediateDecode(startPage, "early_urls_ready", loadStartedAt)
        if (!naverImmediateDecode) {
            scheduleNtkAnchorCachedDecodeRetry(startPage, "early_urls_ready", loadStartedAt)
        }
        if (naverOriginalFirst) {
            if (!naverImmediateDecode && !naverStartCached) requestPageForeground(startPage)
            logNtkRepositoryStage(
                target,
                "early_naver_first_foreground_only",
                "page=$startPage,count=${initialUrls.size},cached=$naverStartCached,immediate=$naverImmediateDecode,adjacent=deferred,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
        } else if (authoritativeNativeDirectManifest) {
            startVerifiedGeneratedCurrentEpisodeStreams()
            logNtkRepositoryStage(
                target,
                "early_native_direct_single_owner",
                "page=$startPage,count=${initialUrls.size},trusted=$directManifestCount"
            )
        } else {
            requestInitialContinuousPagesFromEarlyUrls(startPage, initialUrls.size)
        }
        if (isNtkSource(target, title) &&
            !authoritativeNativeDirectManifest &&
            initialUrls.size > NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
        ) {
            postMainPreferFrontDuringInput(Runnable {
                if (!cancelled.get()) {
                    requestAllUndeliveredNtkPages("early_urls_initial_full")
                }
            })
        }
        flushEarlyPreparedBitmaps()
        scheduleGeneratedEarlyExpansionAfterFirstBitmap(target, initialUrls, loadStartedAt)
        appendExpandedEarlyNtkUrlsUntilFirstBitmap(target, initialUrls.size, loadStartedAt)
        scheduleExpandedEarlyNtkUrlsMainAppend(target, initialUrls.size, loadStartedAt)
        if (!naverOriginalFirst && initialUrls.size <= startPage + 1) requestInitialFanout(startPage)
        if (!naverOriginalFirst && !anchorStreamStartedBeforeInstall) {
            startInitialForegroundStreamIfNeeded(target, initialUrls, startPage, loadStartedAt)
        }
        return true
    }

    private fun shouldWaitForCompleteKpApiUrls(target: Manga, urls: List<String>): Boolean {
        if (!isKpWebtoonSlugEpisodePath(target.ntkEpisodePath)) return false
        if (urls.none { isNtkProtectedViewerApiImage(it) }) return false
        if (urls.any { isNtkUploadCdnImageUrl(it) || isNaverWebtoonPageImageUrl(it) }) return false
        logNtkRepositoryStage(
            target,
            "early_urls_defer_kp_protected_wait_upload",
            "count=${urls.size}"
        )
        return true
    }

    private fun isNtkProtectedViewerApiImage(image: String?): Boolean {
        if (image.isNullOrBlank()) return false
        return try {
            Uri.parse(image).path.equals("/api/m/i", ignoreCase = true)
        } catch (_: Throwable) {
            image.contains("/api/m/i?", ignoreCase = true)
        }
    }

    private fun shouldInstallPartialEarlyNtkUrlsWithoutExpansion(target: Manga, urls: List<String>): Boolean {
        if (urls.size >= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        if (target.ntkImageCount < NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return false
        return urls.all { isNtkGeneratedImageUrl(it) || ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(it) }
    }

    private fun initialContinuousRunwayUrlsFromPartial(target: Manga, urls: List<String>): List<String>? {
        if (urls.isEmpty() || urls.size >= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return null
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return null
        val knownCount = target.ntkImageCount
        if (knownCount < NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return null
        val seed = urls.firstOrNull { isNtkGeneratedImageUrl(it) } ?: return null
        val runway = ArrayList<String>(NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)
        for (page in 1..NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) {
            val generated = ntkGeneratedImageUrlForTarget(seed, target, page) ?: return null
            runway.add(generated)
        }
        logNtkRepositoryStage(
            target,
            "early_urls_partial_initial_runway",
            "from=${urls.size},to=${runway.size},known=$knownCount,first=${seed.substringAfterLast('/')}"
        )
        return runway
    }

    private fun scheduleExpandedEarlyNtkUrlsMainAppend(
        target: Manga,
        initialInstalledCount: Int,
        loadStartedAt: Long
    ) {
        if (!isNtkSource(target, title) || initialInstalledCount <= 0) return
        if (!earlyNtkMainAppendScheduled.compareAndSet(false, true)) return
        val deadline = loadStartedAt + NTK_EARLY_GENERATED_EXPAND_BEFORE_FIRST_BITMAP_WAIT_MS
        val poll = object : Runnable {
            override fun run() {
                if (cancelled.get()) {
                    earlyNtkMainAppendScheduled.set(false)
                    return
                }
                val latest = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, 0L)
                val installedCount = synchronized(pagesLock) { pages.size }
                val shouldRefreshSameCount =
                    latest.size <= installedCount &&
                        shouldRefreshInstalledNtkGeneratedImagesFromEarlyUrls(target, latest)
                if (latest.size > installedCount || shouldRefreshSameCount) {
                    val latestTrustedApiRunway = latest.any {
                        ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(it)
                    }
                    if (shouldRefreshSameCount) {
                        val installedImages = currentNtkInstalledImages(target)
                        if (isPureGeneratedExtensionPromotion(installedImages, latest)) {
                            refreshInstalledNtkGeneratedImagesFromEarlyUrls(
                                target,
                                latest,
                                "early_urls_main_same_count_extension_promotion_initial"
                            )
                            primeInitialInteractiveRunwayBytes("early_urls_main_extension_promotion")
                            requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), latest.size)
                            logNtkRepositoryStage(
                                target,
                                "early_urls_main_same_count_extension_promotion_silent",
                                "count=${latest.size},installed=$installedCount,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                            )
                            earlyNtkMainAppendScheduled.set(false)
                            return
                        }
                    }
                    val activeExpansionQuietMs = ntkGeneratedStructureExpansionQuietMs()
                    if (
                        latest.size > installedCount &&
                        firstBitmapLogged.get() &&
                        activeExpansionQuietMs > 0L &&
                        !latestTrustedApiRunway &&
                        !isTrustedDirectGeneratedEpisode(target)
                    ) {
                        logNtkRepositoryStage(
                            target,
                            "early_urls_main_expand_defer_active",
                            "from=$installedCount,to=${latest.size},delayMs=$activeExpansionQuietMs," +
                                "ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                        )
                        val retryMs = if (installedCount >= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) {
                            activeExpansionQuietMs.coerceAtLeast(500L)
                        } else {
                            activeExpansionQuietMs
                                .coerceAtMost(NTK_BACKGROUND_WARM_RECHECK_MS)
                                .coerceAtLeast(250L)
                        }
                        main.postDelayed(this, retryMs)
                        return
                    }
                    logNtkRepositoryStage(
                        target,
                        if (shouldRefreshSameCount) {
                            "early_urls_main_same_count_replace_detected"
                        } else {
                            "early_urls_main_expand_detected"
                        },
                        "from=$installedCount,to=${latest.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    if (shouldRefreshSameCount) {
                        try {
                            refreshInstalledNtkGeneratedImagesFromEarlyUrls(
                                target,
                                latest,
                                "early_urls_main_same_count_before_first"
                            )
                            val start = currentStartPage()
                            requestPageForeground(start)
                            requestInitialContinuousPagesFromEarlyUrls(start, latest.size)
                            scheduleNtkAnchorCachedDecodeRetry(
                                start,
                                "early_urls_main_same_count_before_first",
                                loadStartedAt
                            )
                            scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(0L)
                        } finally {
                            earlyNtkMainAppendScheduled.set(false)
                            if (
                                !cancelled.get() &&
                                !firstBitmapLogged.get() &&
                                SystemClock.elapsedRealtime() < deadline
                            ) {
                                main.postDelayed(
                                    {
                                        scheduleExpandedEarlyNtkUrlsMainAppend(
                                            target,
                                            latest.size.coerceAtLeast(1),
                                            loadStartedAt
                                        )
                                    },
                                    NTK_EARLY_URL_POLL_MS
                                )
                            }
                        }
                        return
                    }
                    control.execute {
                        try {
                            appendInitialNtkUrlsAfterEarlyInstall(
                                target,
                                latest,
                                loadStartedAt,
                                allowFirstBitmapDefer = !isTrustedDirectGeneratedEpisode(target) && !latestTrustedApiRunway,
                                forceImmediatePublish = shouldForceImmediateVerifiedEarlyUrlRefresh(
                                    latest,
                                    "main_append"
                                )
                            )
                            requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), latest.size)
                        } finally {
                            earlyNtkMainAppendScheduled.set(false)
                            if (
                                !cancelled.get() &&
                                !firstBitmapLogged.get() &&
                                SystemClock.elapsedRealtime() < deadline
                            ) {
                                main.postDelayed(
                                    {
                                        scheduleExpandedEarlyNtkUrlsMainAppend(
                                            target,
                                            latest.size.coerceAtLeast(1),
                                            loadStartedAt
                                        )
                                    },
                                    NTK_EARLY_URL_POLL_MS
                                )
                            }
                        }
                    }
                    return
                }
                if (SystemClock.elapsedRealtime() < deadline) {
                    main.postDelayed(this, NTK_EARLY_URL_POLL_MS)
                } else {
                    logNtkRepositoryStage(
                        target,
                        "early_urls_main_expand_stop",
                        "installed=$installedCount,latest=${latest.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    earlyNtkMainAppendScheduled.set(false)
                }
            }
        }
        main.postDelayed(poll, NTK_EARLY_URL_POLL_MS)
    }

    private fun startNaverOriginalForegroundStreamBeforeInstall(
        target: Manga,
        urls: List<String>,
        startPage: Int,
        loadStartedAt: Long
    ) {
        val image = urls.getOrNull(startPage) ?: return
        if (!isNaverWebtoonPageImageUrl(image)) return
        val started = try {
            ReaderImageCache.startForegroundStreamFetch(
                appContext,
                target,
                image,
                imageCancellation,
                anchorHedge = false,
                permit = null,
                pageIndex = startPage,
                visiblePriority = true
            )
        } catch (e: Exception) {
            recordIfUnexpected(e)
            false
        }
        logNtkRepositoryStage(
            target,
            "early_naver_foreground_stream_before_install",
            "started=$started,page=$startPage,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
    }

    private fun startEarlyNtkAnchorForegroundStreamBeforeInstall(
        target: Manga,
        urls: List<String>,
        startPage: Int,
        loadStartedAt: Long
    ) {
        val image = urls.getOrNull(startPage) ?: return
        if (!ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(image)) return
        val started = try {
            startBoundedForegroundStreamFetch(
                appContext,
                target,
                image,
                imageCancellation,
                anchorHedge = false,
                permit = null,
                pageIndex = startPage,
                visiblePriority = true
            )
        } catch (e: Exception) {
            recordIfUnexpected(e)
            false
        }
        logNtkRepositoryStage(
            target,
            "early_ntk_anchor_foreground_stream_before_install",
            "started=$started,page=$startPage,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
    }

    private fun isNaverWebtoonPageImageUrl(image: String): Boolean {
        return try {
            val uri = Uri.parse(image)
            val host = uri.host?.lowercase(Locale.ROOT).orEmpty()
            val path = uri.path.orEmpty().lowercase(Locale.ROOT)
            host == "image-comic.pstatic.net" &&
                path.matches(Regex("^/webtoon/\\d{5,}/\\d+/[^/?#]+\\.(jpg|jpeg|png|webp)$")) &&
                !path.contains("thumbnail") &&
                !path.contains("/ad/") &&
                !path.contains("/ads/")
        } catch (_: Throwable) {
            false
        }
    }

    private fun scheduleNaverOriginalImmediateDecode(index: Int, reason: String, startedAt: Long): Boolean {
        if (cancelled.get() || firstBitmapLogged.get()) return false
        val page = pageRef(index) ?: return false
        val image = page.image ?: return false
        if (!isNaverWebtoonPageImageUrl(image)) return false
        if (hasDeliveredBitmap(index) || (pendingDeliveryWidths[index] ?: 0) > 0) return true
        if (!urgentLoading.add(index)) return false
        urgentLoadingPages[index] = page
        val targetWidth = targetWidth(true)
        urgentDecode.execute {
            val decodeStartedAt = SystemClock.elapsedRealtime()
            var delivered = false
            try {
                if (
                    cancelled.get() ||
                    firstBitmapLogged.get() ||
                    pageRef(index) != page ||
                    hasDeliveredBitmap(index) ||
                    (pendingDeliveryWidths[index] ?: 0) > 0
                ) {
                    return@execute
                }
                val result = decodeNaverOriginalImmediateResult(index, page, image, targetWidth, decodeStartedAt)
                    ?: run {
                        logNtkPagePerf(index, "early_naver_immediate_decode_skip", "reason=$reason,cached=false")
                        return@execute
                    }
                if (
                    cancelled.get() ||
                    pageRef(index) != page ||
                    currentPageIndexForDelivery(page, index) < 0
                ) {
                    recycleDecodeResult(result)
                    return@execute
                }
                logNtkPagePerf(
                    index,
                    "early_naver_immediate_decode_ready",
                    "reason=$reason,waitMs=${decodeStartedAt - startedAt},decodeMs=${SystemClock.elapsedRealtime() - decodeStartedAt},width=${result.width}"
                )
                delivered = true
                postDecodeResult(Delivery(index, page, result, decodeStartedAt, targetWidth, retainWhenBusy = true))
                try {
                    network.execute {
                        startNaverOriginalAdjacentForegroundStreamsFromPages(index, "anchor_decoded", decodeStartedAt)
                    }
                } catch (_: RejectedExecutionException) {
                    startNaverOriginalAdjacentForegroundStreamsFromPages(index, "anchor_decoded_inline", decodeStartedAt)
                }
                scheduleNaverOriginalAdjacentDecodeAfterAnchor(index, "early_naver_immediate", decodeStartedAt)
            } catch (e: Exception) {
                recordIfUnexpected(e)
                postPageError(index, page, e)
            } finally {
                urgentLoadingPages.remove(index, page)
                urgentLoading.remove(index)
                if (!delivered) ViewerWarmupManager.logMetric("reader_naver_immediate_decode_not_delivered", index.toLong())
            }
        }
        return true
    }

    private fun decodeNaverOriginalImmediateResult(
        index: Int,
        page: PageRef,
        image: String,
        targetWidth: Int,
        decodeStartedAt: Long
    ): PageDecodeResult? {
        val cached = waitNaverOriginalCachedFile(page.manga, image, decodeStartedAt) ?: return null
        logNtkPagePerf(index, "early_naver_cached_file_decode", "target=$targetWidth,bytes=${cached.length()}")
        return decodePage(index, page, cached, targetWidth)
    }

    private fun startNaverOriginalAdjacentForegroundStreamsFromPages(
        startPage: Int,
        reason: String,
        startedAt: Long
    ) {
        if (cancelled.get()) return
        val target = pageRef(startPage)?.manga ?: manga
        var startedCount = 0
        val last = minOf(startPage + 2, synchronized(pagesLock) { pages.size } - 1)
        if (last <= startPage) return
        for (index in (startPage + 1)..last) {
            val page = pageRef(index) ?: continue
            val image = page.image ?: continue
            if (!isNaverWebtoonPageImageUrl(image)) continue
            val started = try {
                ReaderImageCache.startForegroundStreamFetch(
                    appContext,
                    page.manga,
                    image,
                    imageCancellation,
                    anchorHedge = false,
                    permit = null,
                    pageIndex = index,
                    visiblePriority = false
                )
            } catch (e: Exception) {
                recordIfUnexpected(e)
                false
            }
            if (started) startedCount++
        }
        logNtkRepositoryStage(
            target,
            "early_naver_adjacent_streams_after_anchor_file",
            "start=$startPage,started=$startedCount,reason=$reason,ms=${SystemClock.elapsedRealtime() - startedAt}"
        )
    }

    private fun scheduleNaverOriginalAdjacentDecodeAfterAnchor(
        startPage: Int,
        reason: String,
        startedAt: Long
    ) {
        main.postDelayed({
            if (cancelled.get()) return@postDelayed
            val elapsed = SystemClock.elapsedRealtime() - startedAt
            if (!firstDrawableDelivered.get() && elapsed < NTK_NAVER_ORIGINAL_ADJACENT_DECODE_MAX_WAIT_MS) {
                scheduleNaverOriginalAdjacentDecodeAfterAnchor(startPage, reason, startedAt)
                return@postDelayed
            }
            logNtkRepositoryStage(
                pageRef(startPage)?.manga ?: manga,
                "early_naver_adjacent_decode_after_anchor",
                "start=$startPage,reason=$reason,firstDrawable=${firstDrawableDelivered.get()},ms=$elapsed"
            )
            requestInitialContinuousPagesFromEarlyUrls(startPage, synchronized(pagesLock) { pages.size })
        }, NTK_NAVER_ORIGINAL_ADJACENT_DECODE_RECHECK_MS)
    }

    private fun waitNaverOriginalCachedFile(manga: Manga, image: String, startedAt: Long): File? {
        val deadline = startedAt + NTK_NAVER_ORIGINAL_FIRST_FILE_WAIT_MS
        while (!cancelled.get() && !firstBitmapLogged.get() && SystemClock.elapsedRealtime() <= deadline) {
            ReaderImageCache.cachedFile(appContext, manga, image)?.let { return it }
            try {
                Thread.sleep(NTK_EARLY_URL_POLL_MS)
            } catch (_: InterruptedException) {
                Thread.currentThread().interrupt()
                return null
            }
        }
        return ReaderImageCache.cachedFile(appContext, manga, image)
    }

    private fun scheduleGeneratedEarlyExpansionAfterFirstBitmap(
        target: Manga,
        urls: List<String>,
        loadStartedAt: Long
    ) {
        if (!isNtkSource(target, title) || urls.isEmpty()) return
        if (shouldKeepManhwaGeneratedEarlyToObservedUrls(target, urls)) {
            scheduleObservedManhwaGeneratedExpansionAfterFirstBitmap(target, urls.size, loadStartedAt)
            return
        }
        try {
            control.execute {
            val deadline = SystemClock.elapsedRealtime() + NTK_EARLY_GENERATED_EXPAND_AFTER_FIRST_BITMAP_WAIT_MS
            while (!cancelled.get() && !firstDrawableDelivered.get() && SystemClock.elapsedRealtime() < deadline) {
                try {
                    Thread.sleep(NTK_EARLY_URL_POLL_MS)
                } catch (e: InterruptedException) {
                    Thread.currentThread().interrupt()
                    return@execute
                }
            }
            if (cancelled.get() || !firstDrawableDelivered.get()) return@execute
            val publishDuringTouch = shouldPublishGeneratedExpansionDuringTouch(target, urls)
            if (!publishDuringTouch && shouldQuietNtkGeneratedExpansionAfterFirstBitmap(target, urls)) {
                waitForInitialFullFetchQuietAfterFirstBitmap(target)
                if (cancelled.get()) return@execute
            }
            val expanded = expandVerifiedGeneratedEarlyUrls(target, urls)
            if (expanded.size <= urls.size) return@execute
            waitForNtkGeneratedStructureExpansionQuiet(target, loadStartedAt, "after_first")
            if (cancelled.get()) return@execute
            appendInitialNtkUrlsAfterEarlyInstall(
                target,
                expanded,
                loadStartedAt,
                allowFirstBitmapDefer = !publishDuringTouch
            )
            logNtkRepositoryStage(
                target,
                "early_urls_generated_expand_after_first",
                "count=${expanded.size},publishDuringTouch=$publishDuringTouch,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            }
        } catch (_: RejectedExecutionException) {
            // Late URL refreshes can race with session teardown.
        }
    }

    private fun ntkGeneratedStructureExpansionQuietMs(): Long {
        if (!isImmediateNtkGeneratedUx()) return 0L
        return maxOf(
            ntkInitialInteractiveSettleRemainingMs(),
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS)
        )
    }

    private fun waitForNtkGeneratedStructureExpansionQuiet(
        target: Manga,
        loadStartedAt: Long,
        reason: String
    ) {
        while (!cancelled.get()) {
            val quietMs = ntkGeneratedStructureExpansionQuietMs()
            if (quietMs <= 0L) return
            logNtkRepositoryStage(
                target,
                "early_urls_generated_expand_defer_active_$reason",
                "delayMs=$quietMs,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            try {
                Thread.sleep(quietMs.coerceAtMost(NTK_EARLY_URL_POLL_MS))
            } catch (e: InterruptedException) {
                Thread.currentThread().interrupt()
                return
            }
        }
    }

    private fun appendExpandedEarlyNtkUrlsUntilFirstBitmap(
        target: Manga,
        initialInstalledCount: Int,
        loadStartedAt: Long
    ) {
        if (!isNtkSource(target, title) || initialInstalledCount <= 0) return
        try {
            control.execute {
            var installedCount = initialInstalledCount
            var installedImages = currentNtkInstalledImages(target)
            var installedStartImage = installedImages.getOrNull(currentStartPage())
            val deadline = SystemClock.elapsedRealtime() + NTK_EARLY_GENERATED_EXPAND_BEFORE_FIRST_BITMAP_WAIT_MS
            while (!cancelled.get() && !firstBitmapLogged.get() && SystemClock.elapsedRealtime() < deadline) {
                val earlyUrls = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, 0L)
                val startPage = currentStartPage()
                val incomingStartImage = earlyUrls.getOrNull(startPage)
                val startImageChanged = isSameInitialGeneratedPageReplacement(installedStartImage, incomingStartImage)
                val verifiedReplacementChanged = hasInitialVerifiedReplacement(installedImages, earlyUrls)
                val anchorAlreadyReadable = (startImageChanged || verifiedReplacementChanged) &&
                    (hasDeliveredOrPendingDrawable(startPage) ||
                        ReaderImageCache.hasNtkAnchorAssetForEpisode(target))
                if (anchorAlreadyReadable && earlyUrls.size <= installedCount) {
                    installedImages = mergeInitialVerifiedReplacements(installedImages, earlyUrls)
                    installedStartImage = incomingStartImage
                    logNtkRepositoryStage(
                        target,
                        "early_urls_anchor_replace_defer_before_first",
                        "count=$installedCount,incoming=${earlyUrls.size}," +
                            "page=$startPage,first=${incomingStartImage?.substringAfterLast('/') ?: ""}," +
                            "ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    try {
                        Thread.sleep(NTK_EARLY_URL_POLL_MS)
                    } catch (e: InterruptedException) {
                        Thread.currentThread().interrupt()
                        return@execute
                    }
                    continue
                }
                if (earlyUrls.size > installedCount || startImageChanged || verifiedReplacementChanged) {
                    val targetPath = target.ntkEpisodePath?.trim().orEmpty()
                    val unavailableGeneratedWebtoonBatch =
                        targetPath.startsWith("/webtoon/", ignoreCase = true) &&
                            earlyUrls.isNotEmpty() &&
                            earlyUrls.all { isNtkGeneratedImageUrl(it) } &&
                            ntkGeneratedBatchUnavailablePaths.contains(targetPath)
                    if (unavailableGeneratedWebtoonBatch) {
                        logNtkRepositoryStage(
                            target,
                            "early_urls_generated_expand_suppressed_after_not_found",
                            "incoming=${earlyUrls.size},installed=$installedCount," +
                                "page=$startPage,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                        )
                        removeInitialUnavailableGeneratedPages(target)
                        return@execute
                    }
                    val replacementUrls = if (
                        (startImageChanged || verifiedReplacementChanged) &&
                        earlyUrls.size < installedImages.size
                    ) {
                        mergeInitialVerifiedReplacements(installedImages, earlyUrls)
                    } else {
                        earlyUrls
                    }
                    appendInitialNtkUrlsAfterEarlyInstall(
                        target,
                        replacementUrls,
                        loadStartedAt,
                        allowFirstBitmapDefer = !startImageChanged && !verifiedReplacementChanged,
                        forceImmediatePublish = startImageChanged ||
                            verifiedReplacementChanged ||
                            shouldForceImmediateVerifiedEarlyUrlRefresh(replacementUrls, "before_first_poll")
                    )
                    installedImages = currentNtkInstalledImages(target)
                    installedCount = installedImages.size
                    installedStartImage = installedImages.getOrNull(startPage)
                    logNtkRepositoryStage(
                        target,
                        if (startImageChanged || verifiedReplacementChanged) {
                            "early_urls_anchor_replace_before_first"
                        } else {
                            "early_urls_generated_expand_before_first"
                        },
                        "count=$installedCount,incoming=${earlyUrls.size},merged=${replacementUrls.size}," +
                            "page=$startPage,first=${incomingStartImage?.substringAfterLast('/') ?: ""}," +
                            "ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), installedCount)
                    val currentAnchor = currentStartPage()
                    requestPageForeground(currentAnchor)
                    scheduleNtkAnchorCachedDecode(currentAnchor, "early_urls_anchor_replace_before_first", loadStartedAt)
                }
                try {
                    Thread.sleep(NTK_EARLY_URL_POLL_MS)
                } catch (e: InterruptedException) {
                    Thread.currentThread().interrupt()
                    return@execute
                }
            }
            }
        } catch (_: RejectedExecutionException) {
            // Late URL refreshes can race with session teardown.
        }
    }

    private fun scheduleNtkAnchorCachedDecode(index: Int, reason: String, startedAt: Long) {
        tryScheduleNtkAnchorCachedDecode(index, reason, startedAt)
    }

    private fun registerNtkAnchorAssetCachedDecode(
        index: Int,
        target: Manga,
        image: String,
        reason: String,
        startedAt: Long
    ): Boolean {
        if (cancelled.get() || firstBitmapLogged.get()) return false
        if (image.isBlank() || !isNtkGeneratedImageUrl(image)) return false
        if (!isNtkSource(target, title) || !isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        val listenerKey = ntkAnchorAssetDecodeListenerKey(index, target, image)
        if (!initialAnchorAssetDecodeListenerKeys.add(listenerKey)) return true
        val accepted = ReaderImageCache.runWhenNtkAnchorAssetReady(
            appContext,
            target,
            image,
            Runnable {
                runNtkAnchorAssetReadyCachedDecode(index, target, image, reason, startedAt, listenerKey, 0)
            }
        )
        if (!accepted) {
            initialAnchorAssetDecodeListenerKeys.remove(listenerKey)
            return false
        }
        logNtkRepositoryStage(
            target,
            "anchor_asset_decode_listener",
            "reason=$reason,page=$index,image=${image.substringAfterLast('/').takeLast(64)}"
        )
        return true
    }

    private fun runNtkAnchorAssetReadyCachedDecode(
        index: Int,
        target: Manga,
        image: String,
        reason: String,
        startedAt: Long,
        listenerKey: String,
        attempt: Int
    ) {
        if (cancelled.get() || firstBitmapLogged.get()) {
            initialAnchorAssetDecodeListenerKeys.remove(listenerKey)
            return
        }
        val page = pageRef(index)
        if (
            page == null ||
            page.transitionTitle != null ||
            !Manga.sameEpisodeIdentity(page.manga, target) ||
            !sameNtkAnchorAssetImage(page.image.orEmpty(), image, index)
        ) {
            if (attempt < NTK_ANCHOR_ASSET_DECODE_PAGE_BIND_RETRIES) {
                main.postDelayed({
                    runNtkAnchorAssetReadyCachedDecode(
                        index,
                        target,
                        image,
                        reason,
                        startedAt,
                        listenerKey,
                        attempt + 1
                    )
                }, NTK_EARLY_URL_POLL_MS)
            } else {
                initialAnchorAssetDecodeListenerKeys.remove(listenerKey)
            }
            return
        }
        initialAnchorAssetDecodeListenerKeys.remove(listenerKey)
        scheduleNtkAnchorAssetReadyDecode(
            index,
            page,
            "${reason}_asset_ready",
            startedAt
        )
        requestInitialContinuousPagesFromEarlyUrls(index, synchronized(pagesLock) { pages.size })
    }

    private fun scheduleNtkAnchorAssetReadyDecode(
        index: Int,
        page: PageRef,
        reason: String,
        byteStartedAt: Long
    ) {
        if (cancelled.get() || firstBitmapLogged.get() || pageRef(index) != page) return
        val initialAnchor = index == currentStartPage()
        if (hasDeliveredBitmap(index) || (!initialAnchor && (pendingDeliveryWidths[index] ?: 0) > 0)) return
        if (initialAnchor) {
            pendingDeliveryWidths.remove(index)
            initialGeneratedDirectDecodeInFlight.remove(index)
            initialGeneratedCachedDecodeInFlight.remove(index)
            visibleGeneratedDecodeHedges.remove(index)
            loading.remove(index)
            urgentLoading.remove(index)
            loadingPages.remove(index)
            urgentLoadingPages.remove(index)
        }
        val image = page.image ?: return
        val anchorBytes = ReaderImageCache.ntkAnchorAssetBytes(page.manga, image)
        val cached = if (anchorBytes == null) ReaderImageCache.cachedFile(appContext, page.manga, image) else null
        if (anchorBytes == null && cached == null) {
            scheduleVisibleGeneratedCachedDecode(index, page, reason, byteStartedAt, forceRequeue = true)
            return
        }
        try {
            val executor = if (!firstBitmapLogged.get() && index == currentStartPage()) {
                initialAnchorDecode
            } else {
                urgentDecode
            }
            executor.execute {
                val decodeStartedAt = SystemClock.elapsedRealtime()
                var posted = false
                try {
                    if (initialAnchor) {
                        pendingDeliveryWidths.remove(index)
                        initialGeneratedDirectDecodeInFlight.remove(index)
                        initialGeneratedCachedDecodeInFlight.remove(index)
                        visibleGeneratedDecodeHedges.remove(index)
                    }
                    if (
                        cancelled.get() ||
                        firstBitmapLogged.get() ||
                        pageRef(index) != page ||
                        hasDeliveredBitmap(index) ||
                        (!initialAnchor && (pendingDeliveryWidths[index] ?: 0) > 0)
                    ) {
                        return@execute
                    }
                    val targetWidth = targetWidth(page, true)
                    val result = if (anchorBytes != null) {
                        decodePageBytes(index, page, anchorBytes, targetWidth)
                    } else {
                        decodePage(index, page, cached ?: return@execute, targetWidth)
                    }
                    if (
                        cancelled.get() ||
                        pageRef(index) != page ||
                        currentPageIndexForDelivery(page, index) < 0
                    ) {
                        recycleDecodeResult(result)
                        return@execute
                    }
                    logNtkPagePerf(
                        index,
                        "ntk_anchor_asset_ready_decode_ready",
                        "reason=$reason,byteMs=${decodeStartedAt - byteStartedAt},decodeMs=${SystemClock.elapsedRealtime() - decodeStartedAt},width=${result.width}"
                    )
                    posted = true
                    postDecodeResult(Delivery(index, page, result, decodeStartedAt, targetWidth, retainWhenBusy = true))
                    cancelInitialGeneratedForegroundWorkAfterDrawableQueued(
                        page,
                        image,
                        "anchor_asset_ready_decode_posted"
                    )
                } catch (e: Exception) {
                    recordIfUnexpected(e)
                    postPageError(index, page, e)
                } finally {
                    if (!posted && !firstBitmapLogged.get() && !hasDeliveredBitmap(index)) {
                        logNtkPagePerf(index, "ntk_anchor_asset_ready_decode_aborted", "reason=$reason")
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
        }
    }

    private fun sameNtkAnchorAssetImage(actual: String, expected: String, fallbackIndex: Int): Boolean {
        if (actual == expected) return true
        if (!isNtkGeneratedImageUrl(actual) || !isNtkGeneratedImageUrl(expected)) return false
        val actualPage = ntkImagePageNumber(actual) ?: ntkGeneratedPageNumber(actual) ?: return false
        val expectedPage = ntkImagePageNumber(expected) ?: ntkGeneratedPageNumber(expected) ?: (fallbackIndex + 1)
        return actualPage == expectedPage
    }

    private fun ntkAnchorAssetDecodeListenerKey(index: Int, target: Manga, image: String): String {
        val page = ntkImagePageNumber(image) ?: ntkGeneratedPageNumber(image) ?: (index + 1)
        return "${target.baseMode}|${target.ntkEpisodePath.orEmpty()}|$page|${image.substringAfterLast('/')}"
    }

    private fun removeInitialAnchorAssetDecodeListenersForEpisode(target: Manga) {
        val prefix = "${target.baseMode}|${target.ntkEpisodePath.orEmpty()}|"
        initialAnchorAssetDecodeListenerKeys.removeAll { it.startsWith(prefix) }
    }

    private fun scheduleNtkAnchorCachedDecodeRetry(index: Int, reason: String, startedAt: Long) {
        if (cancelled.get() || firstBitmapLogged.get()) return
        refreshInstalledNtkGeneratedImagesFromLatestEarlyUrls(
            pageRef(index)?.manga ?: manga,
            "anchor_cached_decode_retry_$reason",
            startedAt
        )
        val now = SystemClock.elapsedRealtime()
        ntkAnchorCachedDecodeRetryUntilMs.updateAndGet { current ->
            max(current, now + NTK_ANCHOR_CACHED_DECODE_RETRY_MS)
        }
        if (tryScheduleNtkAnchorCachedDecode(index, reason, startedAt)) return
        val page = pageRef(index)
        val image = page?.image
        if (page != null && !image.isNullOrBlank()) {
            registerNtkAnchorAssetCachedDecode(index, page.manga, image, reason, startedAt)
        }
        if (!ntkAnchorCachedDecodeRetryPosted.compareAndSet(false, true)) return
        try {
            anchorPoll.execute {
                try {
                    while (
                        !cancelled.get() &&
                        !firstBitmapLogged.get() &&
                        SystemClock.elapsedRealtime() <= ntkAnchorCachedDecodeRetryUntilMs.get()
                    ) {
                        if (tryScheduleNtkAnchorCachedDecode(index, reason, startedAt)) return@execute
                        try {
                            Thread.sleep(NTK_EARLY_URL_POLL_MS)
                        } catch (_: InterruptedException) {
                            Thread.currentThread().interrupt()
                            return@execute
                        }
                    }
                } finally {
                    ntkAnchorCachedDecodeRetryPosted.set(false)
                    if (
                        !cancelled.get() &&
                        !firstBitmapLogged.get() &&
                        SystemClock.elapsedRealtime() <= ntkAnchorCachedDecodeRetryUntilMs.get()
                    ) {
                        scheduleNtkAnchorCachedDecodeRetry(index, reason, startedAt)
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            ntkAnchorCachedDecodeRetryPosted.set(false)
        }
    }

    private fun tryScheduleNtkAnchorCachedDecode(index: Int, reason: String, startedAt: Long): Boolean {
        if (cancelled.get() || firstBitmapLogged.get()) return false
        val page = pageRef(index) ?: return false
        if (!isNtkSource(page.manga, title) || page.transitionTitle != null) return false
        val image = page.image ?: return false
        ReaderImageCache.ntkAnchorAssetBytes(page.manga, image)?.let { bytes ->
            return tryScheduleNtkAnchorBytesDecode(index, page, image, bytes, reason, startedAt)
        }
        val cached = ReaderImageCache.cachedFile(appContext, page.manga, image) ?: run {
            val now = SystemClock.elapsedRealtime()
            val last = ntkAnchorCachedDecodeLastMissLogAtMs.get()
            if (now - last >= 250L && ntkAnchorCachedDecodeLastMissLogAtMs.compareAndSet(last, now)) {
                logNtkPagePerf(index, "ntk_anchor_cached_decode_skip", "reason=$reason,cached=false")
            }
            return false
        }
        if (!initialAnchorCachedDecodeStarted.compareAndSet(false, true)) {
            logNtkPagePerf(index, "ntk_anchor_cached_decode_skip", "reason=$reason,already_started=true")
            return true
        }
        try {
            initialAnchorDecode.execute {
                val decodeStartedAt = SystemClock.elapsedRealtime()
                var posted = false
                try {
                    if (
                        cancelled.get() ||
                        firstBitmapLogged.get() ||
                        pageRef(index) != page ||
                        hasDeliveredBitmap(index)
                    ) {
                        return@execute
                    }
                    val targetWidth = targetWidth(page, true)
                    val result = cachedDecodedResult(
                        index,
                        page,
                        targetWidth,
                        shouldUsePreviewDecodedCache(index, targetWidth)
                    ) ?: decodePage(index, page, cached, targetWidth)
                    if (
                        cancelled.get() ||
                        pageRef(index) != page ||
                        currentPageIndexForDelivery(page, index) < 0
                    ) {
                        recycleDecodeResult(result)
                        return@execute
                    }
                    logNtkPagePerf(
                        index,
                        "ntk_anchor_cached_decode_ready",
                        "reason=$reason,waitMs=${decodeStartedAt - startedAt},decodeMs=${SystemClock.elapsedRealtime() - decodeStartedAt},width=${result.width}"
                    )
                    posted = true
                    postDecodeResult(Delivery(index, page, result, decodeStartedAt, targetWidth, retainWhenBusy = true))
                    cancelInitialGeneratedForegroundWorkAfterDrawableQueued(
                        page,
                        image,
                        "anchor_cached_decode_posted"
                    )
                } catch (e: Exception) {
                    recordIfUnexpected(e)
                    postPageError(index, page, e)
                } finally {
                    if (!posted && !firstBitmapLogged.get() && !hasDeliveredBitmap(index)) {
                        initialAnchorCachedDecodeStarted.set(false)
                        logNtkPagePerf(index, "ntk_anchor_cached_decode_aborted", "reason=$reason")
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            initialAnchorCachedDecodeStarted.set(false)
            return false
        }
        return true
    }

    private fun currentNtkInstalledImages(target: Manga): List<String> = synchronized(pagesLock) {
        val bySource = TreeMap<Int, String>()
        for (ref in pages) {
            if (ref.transitionTitle != null || !Manga.sameEpisodeIdentity(ref.manga, target)) continue
            val image = ref.image ?: continue
            if (!bySource.containsKey(ref.sourceIndex)) bySource[ref.sourceIndex] = image
        }
        bySource.values.toList()
    }

    private fun isPureGeneratedExtensionPromotion(
        current: List<String>,
        incoming: List<String>
    ): Boolean {
        if (current.isEmpty() || incoming.isEmpty()) return false
        val limit = minOf(current.size, incoming.size)
        var changed = false
        for (index in 0 until limit) {
            val before = current[index]
            val after = incoming[index]
            if (before == after) continue
            changed = true
            if (!isNtkGeneratedImageUrl(before) || !isNtkGeneratedImageUrl(after)) return false
            val beforeBase = generatedUrlWithoutExtension(before) ?: return false
            val afterBase = generatedUrlWithoutExtension(after) ?: return false
            if (!beforeBase.equals(afterBase, ignoreCase = true)) return false
        }
        return changed
    }

    private fun generatedUrlWithoutExtension(image: String): String? {
        val clean = image.substringBefore('#').substringBefore('?')
        val dot = clean.lastIndexOf('.')
        val slash = clean.lastIndexOf('/')
        if (dot <= slash) return null
        return clean.substring(0, dot)
    }

    private fun hasInitialVerifiedReplacement(current: List<String>, incoming: List<String>): Boolean {
        if (current.isEmpty() || incoming.isEmpty()) return false
        for (candidate in incoming) {
            val page = ntkImagePageNumber(candidate) ?: continue
            val index = page - 1
            if (index !in current.indices) continue
            val existing = current[index]
            if (existing == candidate) continue
            if (!isSameInitialGeneratedPageReplacement(existing, candidate)) continue
            return true
        }
        return false
    }

    private fun mergeInitialVerifiedReplacements(current: List<String>, incoming: List<String>): List<String> {
        if (current.isEmpty() || incoming.isEmpty()) return incoming
        val merged = ArrayList(current)
        for (candidate in incoming) {
            val page = ntkImagePageNumber(candidate) ?: continue
            val index = page - 1
            if (index !in merged.indices) continue
            val existing = merged[index]
            if (existing == candidate) continue
            if (isSameInitialGeneratedPageReplacement(existing, candidate)) {
                merged[index] = candidate
            }
        }
        return merged
    }

    private fun isSameInitialGeneratedPageReplacement(current: String?, incoming: String?): Boolean {
        if (current.isNullOrBlank() || incoming.isNullOrBlank() || current == incoming) return false
        if (isSameInitialProtectedCdnReplacement(current, incoming)) return true
        if (!isNtkGeneratedImageUrl(current)) return false
        val currentPage = ntkImagePageNumber(current) ?: return false
        val incomingPage = ntkImagePageNumber(incoming) ?: return false
        return currentPage == incomingPage &&
            incomingPage in 1..NTK_GENERATED_INITIAL_RECOVERY_WINDOW_PAGES &&
            !isNtkBoardUploadImageUrl(current) &&
            !isNtkBoardUploadImageUrl(incoming)
    }

    private fun isSameInitialProtectedCdnReplacement(current: String, incoming: String): Boolean {
        val path = manga.ntkEpisodePath.orEmpty()
        if (!Regex("^/webtoon/[^0-9/?#][^/?#]*/[^/?#]+$", RegexOption.IGNORE_CASE).matches(path)) {
            return false
        }
        if (isNtkGeneratedImageUrl(current) || isNtkGeneratedImageUrl(incoming)) return false
        if (isNtkBoardUploadImageUrl(current) || isNtkBoardUploadImageUrl(incoming)) return false
        return isNtkProtectedCdnImageUrl(current) && isNtkProtectedCdnImageUrl(incoming)
    }

    private fun shouldDeferGeneratedEarlyExpansionBeforeFirstBitmap(target: Manga, urls: List<String>): Boolean {
        if (!isNtkSource(target, title)) return false
        if (urls.none { isNtkGeneratedImageUrl(it) }) return false
        return urls.size < NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD
    }

    private fun shouldLimitLargeUntrustedGeneratedEarlyUrls(target: Manga, urls: List<String>): Boolean {
        if (!isNtkSource(target, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        if (urls.none { isNtkGeneratedImageUrl(it) }) return false
        if (isTrustedDirectWebtoonGeneratedEpisode(target)) return false
        val trustedApiCount = ReaderImageCache.trustedNtkImageApiCount(target.ntkEpisodePath, 0L)
        val knownCount = target.ntkImageCount
        if (knownCount > NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD &&
            trustedApiCount < minOf(knownCount, urls.size)
        ) {
            return true
        }
        val looksLikeDefaultGeneratedGuess =
            urls.size >= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD &&
                knownCount <= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD &&
                trustedApiCount <= 0
        if (looksLikeDefaultGeneratedGuess) return true
        if (urls.size <= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD &&
            knownCount <= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD
        ) return false
        return trustedApiCount < minOf(urls.size, NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)
    }

    private fun limitedLargeUntrustedGeneratedUrls(
        target: Manga,
        urls: List<String>,
        minGeneratedLimit: Int = 0
    ): List<String> {
        if (urls.isEmpty()) return urls
        val installedForEpisode = synchronized(pagesLock) {
            pages.count { ref ->
                ref.transitionTitle == null && looseSameEpisodeForAppend(ref.manga, target)
            }
        }
        val runway = ntkInitialGeneratedRecoveryPagesForTarget(target)
            .coerceAtLeast(NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)
        val firstMissingPage = ReaderImageCache.knownNtkGeneratedFirstNotFoundPage(target.ntkEpisodePath)
        val missingCap = if (firstMissingPage > 1) firstMissingPage - 1 else Int.MAX_VALUE
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        val untrustedKnownCount = target.ntkImageCount
        val trustedApiCount = ReaderImageCache.trustedNtkImageApiCount(target.ntkEpisodePath, 0L)
        val anchorLimited = untrustedKnownCount > NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD &&
            trustedApiCount <= 0 &&
            firstMissingPage <= 0 &&
            anchor >= runway
        val desired = if (anchorLimited) {
            maxOf(runway, anchor + 1, minGeneratedLimit)
        } else {
            maxOf(runway, anchor + runway, minGeneratedLimit)
        }
        val limit = minOf(urls.size, desired, missingCap)
        if (limit >= urls.size) return urls
        logNtkRepositoryStage(
            target,
            "early_urls_large_untrusted_generated_limit",
            "from=${urls.size},to=$limit,installed=$installedForEpisode,anchor=$anchor," +
                "min=$minGeneratedLimit,missingPage=$firstMissingPage,anchorLimited=$anchorLimited"
        )
        return urls.take(limit)
    }

    private fun shouldKeepManhwaGeneratedEarlyToObservedUrls(target: Manga, urls: List<String>): Boolean {
        if (!isNtkSource(target, title)) return false
        if (!isNtkManhwaEpisodePath(target.ntkEpisodePath)) return false
        val knownCount = target.ntkImageCount
        if (knownCount >= urls.size) return false
        return urls.all { isNtkGeneratedImageUrl(it) }
    }

    private fun shouldQuietNtkGeneratedExpansionAfterFirstBitmap(target: Manga, urls: List<String>): Boolean {
        if (!isNtkSource(target, title)) return false
        if (urls.none { isNtkGeneratedImageUrl(it) }) return false
        return isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath) ||
            target.baseMode == MTitle.base_webtoon
    }

    private fun shouldPublishGeneratedExpansionDuringTouch(target: Manga, urls: List<String>): Boolean {
        if (!isNtkSource(target, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        if (urls.none { isNtkGeneratedImageUrl(it) }) return false
        return urls.size >= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
    }

    private fun isInitialGeneratedFullAppendReadyForImmediatePublish(target: Manga, total: Int): Boolean {
        if (!isNtkSource(target, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        return total >= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
    }

    private fun expandVerifiedGeneratedEarlyUrls(target: Manga, urls: List<String>): List<String> {
        if (!isNtkSource(target, title) || urls.isEmpty()) return urls
        val seed = urls.firstOrNull { isNtkGeneratedImageUrl(it) } ?: return urls
        if (
            !firstBitmapLogged.get() &&
            urls.size >= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES &&
            isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)
        ) {
            logNtkRepositoryStage(
                target,
                "early_urls_generated_expand_skip_pre_first",
                "count=${urls.size},known=${target.ntkImageCount}"
            )
            return urls
        }
        val knownCount = target.ntkImageCount
        if (
            knownCount <= 0 &&
            ReaderImageCache.trustedNtkImageApiCount(target.ntkEpisodePath, 0L) <= 0
        ) {
            return urls
        }
        val desiredCount = ntkGeneratedEarlyExpandCount(target, urls.size, knownCount)
        if (desiredCount <= urls.size) return urls
        val expanded = ArrayList<String>(desiredCount)
        for (page in 1..desiredCount) {
            val generated = ntkGeneratedImageUrlForTarget(seed, target, page) ?: break
            expanded.add(generated)
        }
        if (expanded.size <= urls.size) return urls
        target.setNtkImageCount(expanded.size)
        logNtkRepositoryStage(
            target,
            "early_urls_generated_expand",
            "from=${urls.size},to=${expanded.size},known=$knownCount"
        )
        return expanded
    }

    private fun expandInitialVerifiedGeneratedEarlyUrls(target: Manga, urls: List<String>): List<String> {
        if (!isNtkSource(target, title) || urls.isEmpty()) return urls
        val seed = urls.firstOrNull { isNtkGeneratedImageUrl(it) } ?: return urls
        val knownCount = target.ntkImageCount
        if (
            knownCount <= 0 &&
            ReaderImageCache.trustedNtkImageApiCount(target.ntkEpisodePath, 0L) <= 0
        ) {
            return urls
        }
        val desiredCount = when {
            isNtkWebtoonEpisodePath(target.ntkEpisodePath) && knownCount > urls.size -> knownCount
            knownCount > urls.size && knownCount <= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD -> knownCount
            knownCount > urls.size -> minOf(knownCount, ntkInitialGeneratedRecoveryPagesForTarget(target))
            else -> maxOf(urls.size, ntkInitialGeneratedRecoveryPagesForTarget(target))
        }
        if (desiredCount <= urls.size) return urls
        val expanded = ArrayList<String>(desiredCount)
        for (page in 1..desiredCount) {
            val generated = ntkGeneratedImageUrlForTarget(seed, target, page) ?: break
            expanded.add(generated)
        }
        if (expanded.size <= urls.size) return urls
        if (knownCount > 0 || expanded.size >= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD) {
            target.setNtkImageCount(maxOf(knownCount, expanded.size))
        }
        logNtkRepositoryStage(
            target,
            "early_urls_generated_initial_expand",
            "from=${urls.size},to=${expanded.size},known=$knownCount"
        )
        return expanded
    }

    private fun ntkInitialGeneratedRecoveryPagesForTarget(target: Manga): Int {
        if (isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) {
            val knownCount = target.ntkImageCount
            val recoveryPages = if (
                isNtkWebtoonEpisodePath(target.ntkEpisodePath) ||
                target.baseMode == MTitle.base_webtoon
            ) {
                NTK_WEBTOON_GENERATED_INITIAL_RECOVERY_PAGES
            } else {
                NTK_GENERATED_INITIAL_RECOVERY_PAGES
            }
            return if (knownCount > 0) {
                minOf(knownCount, recoveryPages)
            } else {
                recoveryPages
            }
        }
        return NTK_GENERATED_INITIAL_RECOVERY_PAGES
    }

    private fun ntkGeneratedEarlyExpandCount(target: Manga, currentCount: Int, knownCount: Int): Int {
        if (target.baseMode == MTitle.base_comic && !isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) {
            if (knownCount > 0) return maxOf(currentCount, knownCount)
            val comicLimit = maxOf(currentCount, NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD)
            return when {
                knownCount > currentCount -> minOf(knownCount, comicLimit)
                else -> comicLimit
            }
        }
        if (isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) {
            val trustedCount = trustedNtkGeneratedImageCount(target)
            if (trustedCount > currentCount) return trustedCount
            if (isTrustedDirectWebtoonGeneratedEpisode(target) && knownCount > currentCount) {
                return knownCount
            }
            val recoveryLimit = ntkInitialGeneratedRecoveryPagesForTarget(target)
            val cappedKnown = if (knownCount > 0) minOf(knownCount, recoveryLimit) else recoveryLimit
            return maxOf(currentCount, cappedKnown)
        }
        return when {
            knownCount > currentCount -> knownCount
            currentCount >= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD -> currentCount
            else -> currentCount
        }
    }

    private fun isNtkManhwaOrWebtoonEpisodePath(path: String?): Boolean {
        return NTK_VIEWER_EPISODE_PATH.matchEntire(path?.trim().orEmpty()) != null
    }

    private fun isNtkManhwaEpisodePath(path: String?): Boolean {
        return path.orEmpty().startsWith("/manhwa/", ignoreCase = true)
    }

    private fun isNtkWebtoonEpisodePath(path: String?): Boolean {
        return path.orEmpty().startsWith("/webtoon/", ignoreCase = true)
    }

    private fun shouldSkipForwardNtkOutOfOrderAppendLocked(target: Manga): Boolean {
        return shouldSkipForwardNtkOutOfOrderAppend(target, pages)
    }

    /** Runs episode-list authority resolution on a stable page-reference snapshot off pagesLock. */
    private fun shouldSkipForwardNtkOutOfOrderAppend(
        target: Manga,
        pageSnapshot: List<PageRef>,
    ): Boolean {
        val targetParts = ntkNumericEpisodePathParts(target.ntkEpisodePath) ?: return false
        val tailSource = pageSnapshot.asReversed()
            .firstOrNull { it.transitionTitle == null }
            ?.manga
        if (tailSource != null) {
            if (looseSameEpisodeForAppend(tailSource, target)) return false
            // A season reset can leave an older row immediately next to the current episode in
            // the server list (for example, "0032 - 31화" beside "시즌2 32화"). That legacy row
            // also parses like a fractional 32-31 episode, so nextEp() alone cannot disambiguate
            // it. The exact visible +1 and closest canonical-path authorities are the same ones
            // used by adjacent loading; prefer them only when both resolve to the same episode.
            val titleEpisodes = Utils.snapshotEpisodes(tailSource.title ?: title)
            val episodes = if (titleEpisodes.isNotEmpty()) {
                titleEpisodes
            } else {
                Utils.snapshotEpisodes(tailSource)
            }
            val visibleAuthority = ntkVisibleNumberAdjacentCandidate(
                tailSource,
                episodes,
                ReaderSurfaceView.DIRECTION_NEXT,
            )
            val canonicalAuthority = ntkNumericPathAdjacentCandidate(
                tailSource,
                episodes,
                ReaderSurfaceView.DIRECTION_NEXT,
            )
            when (NtkAdjacentAuthorityConsensusPolicy.decideTarget(
                visibleAuthority,
                canonicalAuthority,
                target,
                ::looseSameEpisodeForAppend,
            )) {
                NtkAdjacentAuthorityConsensusPolicy.TargetDecision.ACCEPT -> return false
                NtkAdjacentAuthorityConsensusPolicy.TargetDecision.REJECT -> return true
                NtkAdjacentAuthorityConsensusPolicy.TargetDecision.DEFER_TO_LEGACY -> Unit
            }
            // NTK database ids are not chronological for every title. When no exact authority
            // exists, the server episode-list neighbor still outranks numeric id monotonicity.
            // Apply the same numeric direction proof as candidate discovery. A reversed legacy
            // list must not first select A over C and then reject the correctly resolved C runway
            // at structure publication.
            val authoritativeNext = ntkTrustedProvidedAdjacentCandidate(
                tailSource,
                ReaderSurfaceView.DIRECTION_NEXT,
            )
            if (authoritativeNext != null) {
                return !looseSameEpisodeForAppend(authoritativeNext, target)
            }
        }
        var maxExistingEpisodeId = Long.MIN_VALUE
        for (page in pageSnapshot) {
            if (page.transitionTitle != null) continue
            val parts = ntkNumericEpisodePathParts(page.manga.ntkEpisodePath) ?: continue
            if (parts.first != targetParts.first || parts.second != targetParts.second) continue
            if (parts.third > maxExistingEpisodeId) maxExistingEpisodeId = parts.third
        }
        val targetPath = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath.orEmpty(),
        )
        val directWifiStrictAdjacent = isDirectWifiStrictAdjacentTransportActive()
        val strictClaim = if (directWifiStrictAdjacent && targetPath.isNotEmpty()) {
            adjacentStrictSourceClaims[targetPath]
        } else {
            null
        }
        return NtkDirectWifiStrictAdjacentOrderPolicy.shouldSkipNumericIdFallback(
            directWifiStrictAdjacentTransport = directWifiStrictAdjacent,
            currentTailEpisodePath = tailSource?.ntkEpisodePath,
            targetEpisodePath = targetPath,
            exactClaimTargetEpisodePath = targetPath.takeIf { strictClaim != null },
            exactClaimPredecessorEpisodePath = strictClaim?.predecessorEpisodePath,
            exactClaimLive = strictClaim?.let {
                isAdjacentStrictSourceClaimLive(targetPath, it)
            } == true,
            maxExistingEpisodeId = maxExistingEpisodeId.takeIf { it != Long.MIN_VALUE },
            targetEpisodeId = targetParts.third,
        )
    }

    private fun pageReferenceSnapshotStillCurrentLocked(snapshot: List<PageRef>): Boolean {
        if (pages.size != snapshot.size) return false
        for (index in snapshot.indices) {
            if (pages[index] !== snapshot[index]) return false
        }
        return true
    }

    private fun isKpWebtoonSlugEpisodePath(path: String?): Boolean {
        return path?.trim().orEmpty()
            .matches(Regex("^/webtoon/\\d{1,12}/kp-[^/?#]+(?:[/?#].*)?$", RegexOption.IGNORE_CASE))
    }

    private fun installEarlyGeneratedNtkUrlsIfBoardOnly(target: Manga, urls: List<String>, loadStartedAt: Long): Boolean {
        if (!isNtkSource(target, title) || urls.none { isNtkBoardUploadImageUrl(it) }) return false
        logNtkRepositoryStage(
            target,
            "board_only_install_original",
            "count=${urls.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        return installEarlyNtkUrls(target, urls, loadStartedAt)
    }

    private fun requestInitialContinuousPagesFromEarlyUrls(startPage: Int, urlCount: Int) {
        if (!isNtkSource(manga, title)) return
        val firstImage = pageRef(startPage)?.image.orEmpty()
        val now = SystemClock.elapsedRealtime()
        val phase = if (firstBitmapLogged.get() || ntkFirstBitmapAtMs.get() > 0L) "after" else "before"
        val coalesceKey = "$startPage|$urlCount|${firstImage.substringAfterLast('/')}|$phase"
        val previousKey = lastInitialContinuousRequestKey.get()
        val previousAt = lastInitialContinuousRequestAtMs.get()
        if (coalesceKey == previousKey && now - previousAt < NTK_INITIAL_CONTINUOUS_COALESCE_MS) {
            logNtkRepositoryStage(
                manga,
                "early_urls_initial_continuous_coalesced",
                "start=$startPage,count=$urlCount,phase=$phase"
            )
            return
        }
        lastInitialContinuousRequestKey.set(coalesceKey)
        lastInitialContinuousRequestAtMs.set(now)
        val initialGeneratedRunway =
            isNtkGeneratedImageUrl(firstImage) &&
                isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)
        val initialKpDescriptorRunway =
            isKpWebtoonSlugEpisodePath(manga.ntkEpisodePath) &&
                isNtkKpDescriptorImageUrl(firstImage)
        val trustedApiSlugWebtoonFirst = isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath) &&
            ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(firstImage) &&
            !hasVerifiedGeneratedInitialRun(startPage)
        val initialContinuousRunway = initialGeneratedRunway || trustedApiSlugWebtoonFirst
        val effectiveUrlCount = if (!firstBitmapLogged.get()) {
            if (isNaverWebtoonPageImageUrl(firstImage)) {
                minOf(urlCount, startPage + 3)
            } else if (isNtkWebtoonEpisodePath(manga.ntkEpisodePath)) {
                if (initialContinuousRunway) {
                    minOf(urlCount, startPage + ntkInitialGeneratedDecodeRunwayPages())
                } else if (hasVerifiedGeneratedInitialRun(startPage)) {
                    minOf(urlCount, startPage + ntkInitialGeneratedRecoveryPagesForTarget(manga))
                } else {
                    minOf(urlCount, startPage + NTK_WEBTOON_INITIAL_VISIBLE_RECOVERY_PAGES)
                }
            } else if (isNtkSyntheticEpisodePath(manga.ntkEpisodePath)) {
                minOf(urlCount, startPage + NTK_SYNTHETIC_INITIAL_VISIBLE_PAGES)
            } else if (isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) {
                if (initialGeneratedRunway) {
                    val preFirstRunway = if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L) {
                        NTK_INITIAL_PRE_FIRST_MANHWA_DECODE_PAGES
                    } else {
                        ntkInitialGeneratedDecodeRunwayPages()
                    }
                    minOf(urlCount, startPage + preFirstRunway)
                } else {
                    minOf(urlCount, startPage + ntkInitialGeneratedRecoveryPagesForTarget(manga))
                }
            } else {
                urlCount
            }
        } else {
            urlCount
        }
        if (!firstBitmapLogged.get()) {
            val anchorAssetReady = ReaderImageCache.hasNtkAnchorAssetForEpisode(manga)
            val allowPreFirstInitialContinuous =
                initialGeneratedRunway ||
                    trustedApiSlugWebtoonFirst ||
                    anchorAssetReady ||
                    hasVerifiedGeneratedInitialRun(startPage) ||
                    isFreshExactEarlyNtkImageUrl(manga, firstImage)
            if (!allowPreFirstInitialContinuous) {
                logNtkRepositoryStage(
                    manga,
                    "early_urls_initial_continuous_defer_until_first_bitmap",
                    "start=$startPage,count=$urlCount,effective=$effectiveUrlCount,anchorAsset=$anchorAssetReady"
                )
                scheduleNtkAnchorCachedDecodeRetry(
                    startPage,
                    "initial_continuous_deferred_until_first_bitmap",
                    SystemClock.elapsedRealtime()
                )
                return
            }
            logNtkRepositoryStage(
                manga,
                "early_urls_initial_continuous_pre_first",
                "start=$startPage,count=$urlCount,effective=$effectiveUrlCount," +
                    "trustedApiSlug=$trustedApiSlugWebtoonFirst"
            )
        }
        val count = synchronized(pagesLock) { pages.size }
        if (
            initialContinuousRunway &&
            (firstBitmapLogged.get() || ntkFirstBitmapAtMs.get() > 0L) &&
            (viewportBusy.get() || readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L)
        ) {
            val viewportAnchor = currentViewportAnchor.get()
                .takeIf { it >= 0 }
                ?.coerceIn(0, count - 1)
                ?: startPage.coerceIn(0, count - 1)
            val activeLast = minOf(
                count - 1,
                effectiveUrlCount - 1,
                viewportAnchor + initialContinuousViewportAheadPages()
            )
            var requested = 0
            if (activeLast >= viewportAnchor) {
                for (index in viewportAnchor..activeLast) {
                    val page = pageRef(index) ?: continue
                    if (page.transitionTitle != null) continue
                    requestPage(
                        index,
                        busy = true,
                        anchor = index == viewportAnchor,
                        generation = FOREGROUND_PRIME_WARM_GENERATION
                    )
                    requested++
                }
            }
            Log.d(
                TAG,
                "reader_ntk_initial_continuous_active_viewport start=$startPage," +
                    "anchor=$viewportAnchor,last=$activeLast,requested=$requested,count=$urlCount"
            )
            ViewerWarmupManager.logMetric("reader_ntk_initial_continuous_active_viewport", requested.toLong())
            return
        }
        if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L && !initialContinuousRunway) {
            requestPageForeground(startPage)
            logNtkRepositoryStage(
                manga,
                "early_urls_initial_continuous_anchor_only_until_first_bitmap",
                "start=$startPage,count=$urlCount,effective=$effectiveUrlCount"
            )
            return
        } else if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L) {
            requestPageForeground(startPage)
            logNtkRepositoryStage(
                manga,
                "early_urls_initial_continuous_runway_before_first_bitmap",
                "start=$startPage,count=$urlCount,effective=$effectiveUrlCount"
            )
            if (initialKpDescriptorRunway) {
                logNtkRepositoryStage(
                    manga,
                    "early_urls_initial_continuous_kp_descriptor_anchor_gate",
                    "start=$startPage,count=$urlCount,effective=$effectiveUrlCount,next=false"
                )
                return
            }
            if (
                isImmediateNtkGeneratedUx() &&
                !isNtkKpDescriptorImageUrl(firstImage) &&
                !isNtkUploadCdnImageUrl(firstImage)
            ) {
                val refs = synchronized(pagesLock) { pages.toList() }
                if (refs.isNotEmpty()) {
                    requestBrowserManifestInitialViewport("early_urls_pre_first_viewport")
                    requestInitialFastFlingGeneratedRunway("early_urls_pre_first")
                }
                return
            }
        }
        val nearGeneratedTailViewport =
            initialContinuousRunway &&
                startPage > 0
        val allowPreviousBeforeFirstDrawable =
            firstBitmapLogged.get() ||
                !initialContinuousRunway ||
                ReaderImageCache.hasNtkAnchorAssetForEpisode(manga)
        if (startPage > 0 &&
            allowPreviousBeforeFirstDrawable &&
            (!shouldLimitImmediateGeneratedToViewport() || nearGeneratedTailViewport) &&
            (!isImmediateGeneratedShortPageRunway() || nearGeneratedTailViewport)
        ) {
            val firstPrevious = (startPage - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES).coerceAtLeast(0)
            for (index in firstPrevious until startPage) {
                requestPage(
                    index,
                    busy = true,
                    anchor = false,
                    generation = FOREGROUND_PRIME_WARM_GENERATION
                )
            }
            if (nearGeneratedTailViewport) {
                logNtkRepositoryStage(
                    manga,
                    "early_urls_initial_continuous_previous_for_tail_viewport",
                    "start=$startPage,firstPrevious=$firstPrevious,count=$count"
                )
            }
        }
        val continuousWindowPages = if (initialContinuousRunway) {
            if (shouldLimitImmediateGeneratedToViewport()) {
                if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L) {
                    if (isNtkWebtoonEpisodePath(manga.ntkEpisodePath)) {
                        NTK_PRE_FIRST_WEBTOON_DRAWABLE_RUNWAY_PAGES
                    } else {
                        NTK_PRE_FIRST_MANHWA_DRAWABLE_RUNWAY_PAGES
                    }
                } else if (isNtkWebtoonEpisodePath(manga.ntkEpisodePath)) {
                    NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES + initialContinuousViewportAheadPages()
                } else if (!firstBitmapLogged.get()) {
                    NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
                } else {
                    NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
                }
            } else if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L) {
                NTK_INITIAL_PRE_FIRST_MANHWA_DECODE_PAGES
            } else {
                ntkInitialGeneratedDecodeRunwayPages()
            }
        } else {
            NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
        }
        val last = minOf(count - 1, effectiveUrlCount - 1, startPage + continuousWindowPages - 1)
        if (last <= startPage) return
        if (
            !firstBitmapLogged.get() &&
            trustedApiSlugWebtoonFirst &&
            isModernProtectedNumericNtkPath(manga.ntkEpisodePath?.trim().orEmpty())
        ) {
            for (index in (startPage + 1)..last) {
                val page = pageRef(index) ?: continue
                val image = page.image.orEmpty()
                if (!ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(image)) continue
                startBoundedForegroundStreamFetch(
                    appContext,
                    page.manga,
                    image,
                    imageCancellation,
                    pageIndex = index,
                    visiblePriority = true
                )
            }
        }
        for (index in (startPage + 1)..last) {
            val page = pageRef(index)
            val verifiedInitialGenerated = page != null &&
                shouldAllowVerifiedNearGeneratedBeforeAnchorAsset(
                    index,
                    page,
                    startPage,
                    anchor = false,
                    generation = FOREGROUND_PRIME_WARM_GENERATION
                )
            val directInitialGeneratedAhead = when {
                !firstBitmapLogged.get() &&
                    ntkFirstBitmapAtMs.get() <= 0L &&
                    initialGeneratedRunway ->
                    continuousWindowPages - 1
                shouldLimitImmediateGeneratedToViewport() &&
                    initialGeneratedRunway &&
                    isNtkWebtoonEpisodePath(manga.ntkEpisodePath) ->
                    NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES + initialContinuousViewportAheadPages() - 1
                shouldLimitImmediateGeneratedToViewport() &&
                    initialGeneratedRunway &&
                    !firstBitmapLogged.get() &&
                    page != null &&
                    isNtkManhwaEpisodePath(page.manga.ntkEpisodePath) ->
                    NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
                shouldLimitImmediateGeneratedToViewport() ->
                    NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
                isImmediateGeneratedShortPageRunway() -> 4
                page != null && isNtkWebtoonEpisodePath(page.manga.ntkEpisodePath) ->
                    NTK_GENERATED_INITIAL_CONTINUOUS_RUNWAY_PAGES
                page != null && isNtkManhwaEpisodePath(page.manga.ntkEpisodePath) ->
                    NTK_GENERATED_INITIAL_CONTINUOUS_RUNWAY_PAGES
                else -> NTK_DEFAULT_GENERATED_INITIAL_DIRECT_AHEAD_PAGES
            }
            val directInitialGenerated = page != null &&
                index <= startPage + directInitialGeneratedAhead &&
                isNtkGeneratedImageUrl(page.image.orEmpty())
            val directInitialTrustedApi = page != null &&
                trustedApiSlugWebtoonFirst &&
                index <= startPage + directInitialGeneratedAhead &&
                ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(page.image.orEmpty())
            val directInitialNaverOriginal = page != null &&
                index <= startPage + 2 &&
                isNaverWebtoonPageImageUrl(page.image.orEmpty())
            val delayMs = if (verifiedInitialGenerated || directInitialGenerated || directInitialTrustedApi || directInitialNaverOriginal) {
                0L
            } else {
                NTK_INITIAL_CONTINUOUS_STAGGER_MS * (index - startPage)
            }
            val busy = directInitialNaverOriginal ||
                directInitialGenerated ||
                directInitialTrustedApi ||
                index <= startPage + NTK_INITIAL_CONTINUOUS_BUSY_PAGES
            if (delayMs <= 0L) {
                requestPage(index, busy = busy, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
            } else {
                main.postDelayed({
                    if (!cancelled.get()) {
                        requestPage(index, busy = busy, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
                    }
                }, delayMs)
            }
        }
        Log.d(
            TAG,
            "reader_ntk_initial_continuous_request start=$startPage,count=${last - startPage}," +
                "runway=$continuousWindowPages," +
                "staggerMs=$NTK_INITIAL_CONTINUOUS_STAGGER_MS"
        )
        ViewerWarmupManager.logMetric("reader_ntk_initial_continuous_request", (last - startPage).toLong())
    }

    private fun hasVerifiedGeneratedInitialRun(startPage: Int): Boolean {
        if (!isNtkSource(manga, title)) return false
        if (!isNtkWebtoonEpisodePath(manga.ntkEpisodePath)) return false
        val count = synchronized(pagesLock) { pages.size }
        if (count <= startPage + 1) return false
        val first = pageRef(startPage) ?: return false
        val next = pageRef(startPage + 1) ?: return false
        if (!isNtkGeneratedImageUrl(first.image.orEmpty())) return false
        if (!isNtkGeneratedImageUrl(next.image.orEmpty())) return false
        if (isFreshExactEarlyNtkImageUrl(manga, first.image)) return true
        return ReaderImageCache.hintedNtkGeneratedImageUrl(next.image.orEmpty()) != null ||
            hasFreshEarlyNtkImageUrlFor(manga, next.image, requireExact = false)
    }

    private fun finishInitialFetchAfterEarlyInstall(
        target: Manga,
        task: FutureTask<Int>,
        cancellation: MangaRepository.Cancellation,
        loadStartedAt: Long
    ) {
        network.execute {
            try {
                if (shouldDeferInitialFullFetchAfterEarlyInstall(target)) {
                    logNtkRepositoryStage(
                        target,
                        "fetch_initial_after_early_keep_inflight",
                        "ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    if (shouldCancelInitialFullFetchDuringAnchor(target)) {
                        cancellation.cancel()
                        task.cancel(true)
                        logNtkRepositoryStage(
                            target,
                            "fetch_initial_after_early_cancel_for_anchor",
                            "ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                        )
                        waitForFirstBitmapBeforeInitialFullFetch(target, loadStartedAt)
                        if (!cancelled.get()) fetchInitialFullAfterEarlyInstall(target, loadStartedAt)
                        return@execute
                    }
                    waitForFirstBitmapBeforeInitialFullFetch(target, loadStartedAt)
                    if (cancelled.get()) {
                        cancellation.cancel()
                        task.cancel(true)
                        return@execute
                    }
                    val result = task.get()
                    val urls = imageRepository.imageUrls(target, appContext)
                    logNtkRepositoryStage(
                        target,
                        "fetch_initial_done_after_early_inflight",
                        "result=$result,count=${urls?.size ?: 0},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    if (!cancelled.get() && result == Title.LOAD_OK && !urls.isNullOrEmpty()) {
                        appendInitialNtkUrlsAfterEarlyInstall(
                            target,
                            urls,
                            loadStartedAt,
                            allowFirstBitmapDefer = !shouldPublishGeneratedExpansionDuringTouch(target, urls)
                        )
                    }
                    return@execute
                }
                appendExpandedEarlyNtkUrlsBeforeInitialFetchDone(
                    target,
                    initialInstalledCount = synchronized(pagesLock) { pages.size },
                    task,
                    loadStartedAt
                )
                val result = task.get()
                val urls = imageRepository.imageUrls(target, appContext)
                logNtkRepositoryStage(
                    target,
                    "fetch_initial_done_after_early",
                    "result=$result,count=${urls?.size ?: 0},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                if (!cancelled.get() && result == Title.LOAD_OK && !urls.isNullOrEmpty()) {
                    appendInitialNtkUrlsAfterEarlyInstall(
                        target,
                        urls,
                        loadStartedAt,
                        allowFirstBitmapDefer = !shouldPublishGeneratedExpansionDuringTouch(target, urls)
                    )
                }
            } catch (e: Exception) {
                recordIfUnexpected(e)
                logNtkRepositoryStage(
                    target,
                    "fetch_initial_done_after_early_error",
                    "error=${e.javaClass.simpleName},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
            } finally {
                releaseRepositoryCancellation(cancellation)
            }
        }
    }

    private fun shouldDeferInitialFullFetchAfterEarlyInstall(target: Manga): Boolean {
        if (isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        return isNtkSource(target, title) && !firstBitmapLogged.get()
    }

    private fun shouldCancelInitialFullFetchDuringAnchor(target: Manga): Boolean {
        if (!isNtkSource(target, title) || firstBitmapLogged.get()) return false
        return synchronized(pagesLock) {
            pages.isNotEmpty() && pages.all { ref ->
                ref.transitionTitle != null || isNtkGeneratedImageUrl(ref.image.orEmpty())
            }
        }
    }

    private fun waitForFirstBitmapBeforeInitialFullFetch(target: Manga, loadStartedAt: Long) {
        val deadline = loadStartedAt + NTK_INITIAL_FULL_FETCH_AFTER_EARLY_DEFER_MS
        while (!cancelled.get() && !firstBitmapLogged.get() && SystemClock.elapsedRealtime() < deadline) {
            try {
                Thread.sleep(NTK_EARLY_URL_POLL_MS)
            } catch (e: InterruptedException) {
                Thread.currentThread().interrupt()
                return
            }
        }
        logNtkRepositoryStage(
            target,
            "fetch_initial_after_early_defer_full_done",
            "firstBitmap=${firstBitmapLogged.get()},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
    }

    private fun fetchInitialFullAfterEarlyInstall(target: Manga, loadStartedAt: Long) {
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) {
            waitForInitialFullFetchQuietAfterFirstBitmap(target)
        }
        val fullCancellation = repositoryCancellation(userVisible = false)
        if (isNtkSource(target, title) && !isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) {
            fullCancellation.prioritizeWebViewFallback()
        }
        try {
            val result = imageRepository.fetchViewerInitial(target, fullCancellation)
            val urls = imageRepository.imageUrls(target, appContext)
            logNtkRepositoryStage(
                target,
                "fetch_initial_done_after_early_deferred_full",
                "result=$result,count=${urls?.size ?: 0},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            if (!cancelled.get() && result == Title.LOAD_OK && !urls.isNullOrEmpty()) {
                appendInitialNtkUrlsAfterEarlyInstall(
                    target,
                    urls,
                    loadStartedAt,
                    allowFirstBitmapDefer = !shouldPublishGeneratedExpansionDuringTouch(target, urls)
                )
            }
        } catch (e: Exception) {
            recordIfUnexpected(e)
            logNtkRepositoryStage(
                target,
                "fetch_initial_done_after_early_deferred_full_error",
                "error=${e.javaClass.simpleName},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
        } finally {
            releaseRepositoryCancellation(fullCancellation)
        }
    }

    private fun appendExpandedEarlyNtkUrlsBeforeInitialFetchDone(
        target: Manga,
        initialInstalledCount: Int,
        task: FutureTask<Int>,
        loadStartedAt: Long
    ) {
        if (!isNtkSource(target, title) || initialInstalledCount <= 0) return
        var installedCount = initialInstalledCount
        val deadline = SystemClock.elapsedRealtime() + NTK_EARLY_URL_EXPANSION_WAIT_MS
        while (!cancelled.get() && !task.isDone && SystemClock.elapsedRealtime() < deadline) {
            val earlyUrls = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, loadStartedAt)
            if (earlyUrls.size > installedCount) {
                appendInitialNtkUrlsAfterEarlyInstall(target, earlyUrls, loadStartedAt)
                installedCount = earlyUrls.size
                logNtkRepositoryStage(
                    target,
                    "early_urls_expand_before_fetch_done",
                    "count=$installedCount,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), installedCount)
            }
            try {
                Thread.sleep(NTK_EARLY_URL_POLL_MS)
            } catch (e: InterruptedException) {
                Thread.currentThread().interrupt()
                return
            }
        }
    }

    private fun appendInitialNtkUrlsAfterEarlyInstall(
        target: Manga,
        urls: List<String>,
        loadStartedAt: Long,
        allowFirstBitmapDefer: Boolean = true,
        minGeneratedLimit: Int = 0,
        forceImmediatePublish: Boolean = false
    ) {
        if (cancelled.get() || urls.isEmpty()) return
        val verifiedApiUrls = ReaderImageCache.cachedNtkApiFallbackImages(target.ntkEpisodePath)
        val knownGeneratedCount = target.ntkImageCount
        val shouldPreferSameLengthVerifiedApi =
            shouldPreferSameLengthVerifiedApiGeneratedUrls(target, urls, verifiedApiUrls)
        val shouldReplaceWithShortVerifiedApi =
            verifiedApiUrls.isNotEmpty() &&
                verifiedApiUrls.size < urls.size &&
                (
                    isNtkSyntheticEpisodePath(target.ntkEpisodePath) ||
                    knownGeneratedCount <= 0 ||
                        verifiedApiUrls.size >= knownGeneratedCount ||
                        urls.none { isNtkGeneratedImageUrl(it) }
                )
        val observedManhwaGeneratedUrls = if (shouldKeepManhwaGeneratedAppendToObservedUrls(target, urls)) {
            observedInitialManhwaGeneratedUrls(target, urls)
        } else {
            emptyList()
        }
        if (observedManhwaGeneratedUrls.isNotEmpty()) {
            val installedGeneratedCount = installedGeneratedPageCountForCurrentEpisode()
            if (firstBitmapLogged.get() && installedGeneratedCount > observedManhwaGeneratedUrls.size) {
                Log.d(
                    TAG,
                    "reader_ntk_generated_full_skip_observed_shrink path=${target.ntkEpisodePath}," +
                        "installed=$installedGeneratedCount,observed=${observedManhwaGeneratedUrls.size}," +
                        "incoming=${urls.size}"
                )
                return
            }
        }
        var sourceUrls = if (observedManhwaGeneratedUrls.isNotEmpty()) {
            Log.d(
                TAG,
                "reader_ntk_generated_full_keep_observed_manhwa path=${target.ntkEpisodePath}," +
                    "from=${urls.size},to=${observedManhwaGeneratedUrls.size}"
            )
            observedManhwaGeneratedUrls
        } else if (shouldReplaceWithShortVerifiedApi || shouldPreferSameLengthVerifiedApi) {
            Log.d(
                TAG,
                "reader_ntk_generated_full_replace_with_verified_api path=${target.ntkEpisodePath}," +
                    "from=${urls.size},to=${verifiedApiUrls.size}," +
                    "reason=${if (shouldPreferSameLengthVerifiedApi) "same_length_verified" else "short_verified"}"
            )
            target.ntkImageCount = verifiedApiUrls.size
            ReaderImageCache.rememberAuthoritativeNtkImageUrlsFromBrowser(
                target.ntkEpisodePath,
                verifiedApiUrls,
                "verified-api-short-cap"
            )
            verifiedApiUrls
        } else {
            if (verifiedApiUrls.isNotEmpty() && verifiedApiUrls.size < urls.size) {
                Log.d(
                    TAG,
                    "reader_ntk_generated_full_keep_known_count path=${target.ntkEpisodePath}," +
                        "generated=${urls.size},verified=${verifiedApiUrls.size},known=$knownGeneratedCount"
                )
            }
            urls
        }
        val holdVerifiedGeneratedFanout =
            firstBitmapLogged.get() &&
                verifiedGeneratedFullStreamStarted.get() &&
                sourceUrls.any { !isNtkGeneratedImageUrl(it) } &&
                synchronized(pagesLock) {
                    pages.isNotEmpty() &&
                        pages.any { page ->
                            page.transitionTitle == null &&
                                Manga.sameEpisodeIdentity(page.manga, target) &&
                                isNtkGeneratedImageUrl(page.image.orEmpty())
                        } &&
                        pages.none { page ->
                            page.transitionTitle == null &&
                                Manga.sameEpisodeIdentity(page.manga, target) &&
                                !isNtkGeneratedImageUrl(page.image.orEmpty())
                        }
                }
        if (holdVerifiedGeneratedFanout) {
            logNtkRepositoryStage(
                target,
                "early_urls_direct_refresh_hold_verified_generated_fanout",
                "incoming=${sourceUrls.size},installed=${synchronized(pagesLock) { pages.size }}," +
                    "ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            return
        }
        if (shouldLimitLargeUntrustedGeneratedEarlyUrls(target, sourceUrls)) {
            sourceUrls = limitedLargeUntrustedGeneratedUrls(target, sourceUrls, minGeneratedLimit)
        }
        sourceUrls = filterKnownMissingGeneratedInitialUrls(target, sourceUrls, loadStartedAt)
        if (sourceUrls.isEmpty()) return
        if (
            shouldSkipGeneratedTailExpansionAfterAuthoritativeDirect(
                target,
                sourceUrls,
                synchronized(pagesLock) { pages.size },
                loadStartedAt,
                "early_urls_append_full"
            )
        ) {
            return
        }
        if (shouldKeepCurrentNaverOriginalRefs(target, sourceUrls)) {
            logNtkRepositoryStage(
                target,
                "early_urls_generated_refresh_skip_naver_original",
                "incoming=${sourceUrls.size},installed=${synchronized(pagesLock) { pages.size }},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            return
        }
        if (firstBitmapLogged.get() &&
            isNtkSource(target, title) &&
            sourceUrls.all { isNtkGeneratedImageUrl(it) }
        ) {
            val installedForEpisode = installedDrawablePageCountForEpisode(target)
            if (installedForEpisode > sourceUrls.size &&
                !shouldAllowNtkGeneratedVerifiedShrink(target, sourceUrls)
            ) {
                Log.d(
                    TAG,
                    "reader_ntk_generated_full_skip_late_shrink path=${target.ntkEpisodePath}," +
                        "installed=$installedForEpisode,incoming=${sourceUrls.size}"
                )
                return
            }
        }
        var fullRefs = pageRefsForImages(target, sourceUrls)
        if (fullRefs.isEmpty()) return
        var trustedCompleteGeneratedManifest = false
        if (isNtkSource(target, title)) {
            val trustedApiCount = ReaderImageCache.trustedNtkImageApiCount(
                target.ntkEpisodePath,
                loadStartedAt - 1_200L
            )
            val keepMetadataBackedExpansion = shouldKeepMetadataBackedGeneratedEarlyExpansion(
                target,
                fullRefs,
                trustedApiCount,
                loadStartedAt
            )
            trustedCompleteGeneratedManifest =
                trustedApiCount > 0 && fullRefs.size >= trustedApiCount
            if (
                trustedApiCount > 0 &&
                fullRefs.size >= trustedApiCount &&
                target.ntkImageCount != trustedApiCount
            ) {
                val previousCount = target.ntkImageCount
                target.setNtkImageCount(trustedApiCount)
                logNtkRepositoryStage(
                    target,
                    "early_urls_trusted_count_promote",
                    "from=$previousCount,to=$trustedApiCount,urls=${fullRefs.size}," +
                        "ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
            }
            if (trustedApiCount > 0 && fullRefs.size > trustedApiCount && !keepMetadataBackedExpansion) {
                logNtkRepositoryStage(
                    target,
                    "early_urls_generated_full_cap_to_trusted_manifest",
                    "from=${fullRefs.size},to=$trustedApiCount,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                fullRefs = fullRefs.take(trustedApiCount)
                if (target.ntkImageCount <= 0 || target.ntkImageCount > trustedApiCount) {
                    target.setNtkImageCount(trustedApiCount)
                }
            } else if (keepMetadataBackedExpansion) {
                val previousCount = target.ntkImageCount
                if (previousCount <= 0 || previousCount < fullRefs.size) {
                    target.setNtkImageCount(fullRefs.size)
                }
                logNtkRepositoryStage(
                    target,
                    "early_urls_generated_full_keep_metadata_tail",
                    "count=${fullRefs.size},trusted=$trustedApiCount,known=$previousCount," +
                        "effectiveKnown=${target.ntkImageCount}," +
                        "ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
            }
        }
        if (isNtkSource(target, title) &&
            isGeneratedOnlyNtkRefs(fullRefs) &&
            target.ntkImageCount > 0 &&
            fullRefs.size > target.ntkImageCount
        ) {
            val trustedApiCount = ReaderImageCache.trustedNtkImageApiCount(
                target.ntkEpisodePath,
                loadStartedAt - 1_200L
            )
            val recentEarlyFullCount = ReaderImageCache.earlyNtkImageUrls(
                target.ntkEpisodePath,
                loadStartedAt - 1_200L
            ).size
            val trustedDiscoveredBeyondDefault =
                trustedApiCount >= fullRefs.size ||
                    (
                        fullRefs.size > NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD &&
                            recentEarlyFullCount >= fullRefs.size
                    )
            if (trustedDiscoveredBeyondDefault) {
                val previousCount = target.ntkImageCount
                target.setNtkImageCount(fullRefs.size)
                Log.d(
                    TAG,
                    "reader_ntk_generated_full_trusted_count_expand path=${target.ntkEpisodePath}," +
                        "from=$previousCount,to=${fullRefs.size},trusted=$trustedApiCount," +
                        "early=$recentEarlyFullCount"
                )
            } else {
                Log.d(
                    TAG,
                    "reader_ntk_generated_full_cap_to_verified_count path=${target.ntkEpisodePath}," +
                        "from=${fullRefs.size},to=${target.ntkImageCount},trusted=$trustedApiCount," +
                        "early=$recentEarlyFullCount"
                )
                fullRefs = fullRefs.take(target.ntkImageCount)
            }
        }
        var generatedOnlyRefs = isGeneratedOnlyNtkRefs(fullRefs)
        if (shouldSkipLateInitialEpisodeShrink(target, fullRefs, sourceUrls, loadStartedAt)) return
        if (allowFirstBitmapDefer && shouldDeferInitialFullAppendUntilFirstBitmap(fullRefs)) {
            deferInitialFullAppendUntilFirstBitmap(target, sourceUrls, loadStartedAt)
            return
        }
        if (allowFirstBitmapDefer && shouldDeferGeneratedFullAppendUntilReaderQuiet(generatedOnlyRefs)) {
            deferGeneratedFullAppendUntilReaderQuiet(target, sourceUrls, loadStartedAt)
            return
        }
        val startIndex: Int
        val total: Int
        var previousTotal = 0
        var refreshedExisting = false
        var refreshedInPlace = false
        var preserveResolvedDuringVerifiedRefresh = false
        val supersededGeneratedImages = ArrayList<String>()
        synchronized(pagesLock) {
            if (pages.isEmpty()) return
            previousTotal = pages.size
            fullRefs = replaceNtkBoardUploadsWithGeneratedFullRefs(target, fullRefs)
            generatedOnlyRefs = isGeneratedOnlyNtkRefs(fullRefs)
            if (
            generatedOnlyRefs &&
            firstBitmapLogged.get() &&
            fullRefs.size < pages.size
        ) {
            if (!shouldAllowNtkGeneratedVerifiedShrink(target, sourceUrls)) {
                    logNtkRepositoryStage(
                        target,
                        "early_urls_refresh_full_skip_active_generated_shrink",
                        "from=${pages.size},to=${fullRefs.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    return
                }
            }
            if (
                generatedOnlyRefs &&
                fullRefs.size < pages.size &&
                !shouldAllowNtkGeneratedVerifiedShrink(target, sourceUrls)
            ) {
                logNtkRepositoryStage(
                    target,
                    "early_urls_refresh_full_skip_unverified_generated_shrink",
                    "from=${pages.size},to=${fullRefs.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                return
            }
            val replaceGeneratedSeedWithFullBoard =
                pages.size < fullRefs.size &&
                    pages.all { it.transitionTitle != null || isNtkGeneratedImageUrl(it.image.orEmpty()) } &&
                    fullRefs.any { isNtkBoardUploadImageUrl(it.image) }
            val replaceGeneratedSeedWithVerifiedUrls =
                shouldRefreshGeneratedSeedWithVerifiedUrls(target, fullRefs)
            val replaceKpDescriptorSeedWithVerifiedUrls =
                shouldReplaceKpDescriptorSeedWithVerifiedUrls(target, fullRefs)
            if (pages.size >= fullRefs.size ||
                replaceGeneratedSeedWithFullBoard ||
                replaceGeneratedSeedWithVerifiedUrls ||
                replaceKpDescriptorSeedWithVerifiedUrls
            ) {
                if (!replaceGeneratedSeedWithFullBoard && !shouldRefreshInitialNtkInstalledRefs(fullRefs)) return
                beginStructurePublish()
                refreshedExisting = true
                startIndex = 0
                preserveResolvedDuringVerifiedRefresh = firstBitmapLogged.get() &&
                    (replaceGeneratedSeedWithFullBoard || replaceGeneratedSeedWithVerifiedUrls)
                if (replaceGeneratedSeedWithFullBoard ||
                    replaceGeneratedSeedWithVerifiedUrls ||
                    replaceKpDescriptorSeedWithVerifiedUrls
                ) {
                    pages.withIndex().mapNotNullTo(supersededGeneratedImages) { (index, page) ->
                        page.image
                            ?.takeIf { page.transitionTitle == null }
                            ?.takeIf { Manga.sameEpisodeIdentity(page.manga, target) }
                            ?.takeIf { isNtkGeneratedImageUrl(it) }
                            ?.takeIf {
                                !preserveResolvedDuringVerifiedRefresh ||
                                    !hasListenerDrawableDelivery(index, page)
                            }
                    }
                }
                if (preserveResolvedDuringVerifiedRefresh) {
                    val previousPages = pages.toList()
                    fullRefs.forEachIndexed { index, replacement ->
                        replacement.pageIndex = index
                        replacement.totalPages = fullRefs.size
                    }
                    pages.clear()
                    fullRefs.forEachIndexed { index, replacement ->
                        val previous = previousPages.getOrNull(index)
                        if (previous != null && hasListenerDrawableDelivery(index, previous)) {
                            previous.pageIndex = index
                            previous.totalPages = fullRefs.size
                            pages.add(previous)
                        } else {
                            pages.add(replacement)
                        }
                    }
                    refreshedInPlace = true
                } else if (replaceGeneratedSeedWithVerifiedUrls && pages.size == fullRefs.size) {
                    if (!shouldPreserveGeneratedDrawableReadyState(generatedOnlyRefs)) {
                        deliveredDrawableProofWidths.clear()
                        listenerDrawableDeliveries.clear()
                        drawableReadyHistory.clear()
                    }
                    refreshedInPlace = true
                    pages.forEachIndexed { index, page ->
                        val replacement = fullRefs[index]
                        page.image = replacement.image
                        page.totalPages = fullRefs.size
                        page.pageIndex = index
                    }
                } else {
                    fullRefs.forEachIndexed { index, page ->
                        page.pageIndex = index
                        page.totalPages = fullRefs.size
                    }
                    pages.clear()
                    pages.addAll(fullRefs)
                    if (!shouldPreserveGeneratedDrawableReadyState(generatedOnlyRefs)) {
                        deliveredDrawableProofWidths.clear()
                        listenerDrawableDeliveries.clear()
                        drawableReadyHistory.clear()
                    }
                }
                loading.clear()
                loadingPages.clear()
                loadingStartedAtMs.clear()
                urgentLoading.clear()
                urgentLoadingPages.clear()
                inFlightWidths.clear()
                failedPages.clear()
                if (!preserveResolvedDuringVerifiedRefresh && !shouldPreserveGeneratedDrawableReadyState(generatedOnlyRefs)) {
                    decodedWidths.clear()
                }
                desiredWidths.clear()
                pendingDeliveryWidths.clear()
                sourceWidths.clear()
                achievableWidths.clear()
                bytePrefetching.clear()
                fullEpisodeSourcePrefetching.clear()
                immediateGeneratedFullSourcePrefetchPosted.set(false)
                visibleGeneratedByteHedges.clear()
                visibleGeneratedDecodeHedges.clear()
                initialAnchorAssetDecodeListenerKeys.clear()
                initialGeneratedAssetDecodeListeners.clear()
                visibleGeneratedCachedDecodeRetries.clear()
                initialGeneratedCachedDecodeInFlight.clear()
                initialGeneratedDirectDecodeInFlight.clear()
                initialInteractiveRunwayByteFetches.clear()
                initialAnchorDeliveryPosted.set(false)
                if (!preserveResolvedDuringVerifiedRefresh && !shouldPreserveGeneratedDrawableReadyState(generatedOnlyRefs)) {
                    listenerDrawableDeliveries.clear()
                    drawableReadyHistory.clear()
                }
                preRenderedInitialContinuousDeliveries.clear()
                preRenderedCommittedDeliveries.clear()
                total = pages.size
            } else {
                beginStructurePublish()
                startIndex = pages.size
                for (index in pages.indices) {
                    pages[index].totalPages = fullRefs.size
                }
                val appendable = fullRefs.drop(startIndex)
                appendable.forEachIndexed { offset, page -> page.pageIndex = startIndex + offset }
                pages.addAll(appendable)
                total = pages.size
            }
            capturePublishedPageIndexLocked()
        }
        if (!refreshedExisting) clearPageStateFromIndex(startIndex, appendOnlyTail = true)
        logNtkRepositoryStage(
            target,
            if (refreshedExisting) "early_urls_refresh_full" else "early_urls_append_full",
            "from=$startIndex,total=$total,previous=$previousTotal,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        if (supersededGeneratedImages.isNotEmpty()) {
            val superseded = supersededGeneratedImages.distinct()
            try {
                network.execute {
                    ReaderImageCache.cancelNtkGeneratedForegroundWorkForImages(
                        target,
                        superseded,
                        "early_urls_refresh_full_superseded"
                    )
                }
            } catch (_: RejectedExecutionException) {
            }
        }
        val gateGeneratedAppendNotify =
            generatedOnlyRefs &&
                !refreshedExisting &&
                firstBitmapLogged.get() &&
                !isImmediateNtkGeneratedUx() &&
                shouldGateGeneratedAppendNotifyUntilNearReady(startIndex, total)
        val generatedWarmStartedBeforePublish =
            generatedOnlyRefs && firstBitmapLogged.get() && ntkGeneratedAppendPublishDelayMs() <= 0L
        if (generatedWarmStartedBeforePublish) {
            warmNtkGeneratedInitialPagesLimited(currentStartPage(), loadStartedAt)
        }
        val posted = postInitialFullAppendPublish(
            target = target,
            total = total,
            generatedOnlyRefs = generatedOnlyRefs,
            loadStartedAt = loadStartedAt,
            refreshedExisting = refreshedExisting,
            previousTotal = previousTotal,
            forceImmediatePublish = forceImmediatePublish ||
                trustedCompleteGeneratedManifest ||
                (refreshedExisting && previousTotal > total) ||
                (refreshedExisting && !generatedOnlyRefs)
        ) {
            try {
                if (!cancelled.get() && !gateGeneratedAppendNotify && !refreshedInPlace) {
                    val currentTotal = synchronized(pagesLock) { pages.size }
                    if (!refreshedExisting && total < currentTotal) {
                        logNtkRepositoryStage(
                            target,
                            "early_urls_append_full_skip_stale_publish",
                            "total=$total,current=$currentTotal,previous=$previousTotal,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                        )
                    } else if (refreshedExisting && previousTotal > total) {
                        listener.onPagesRemoved(total, previousTotal - total, total)
                    } else if (refreshedExisting && previousTotal == total && generatedOnlyRefs) {
                        logNtkRepositoryStage(
                            target,
                            "early_urls_refresh_full_skip_same_count_publish",
                            "total=$total,previous=$previousTotal,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                        )
                    } else {
                        listener.onPagesAppended(total)
                    }
                }
            } finally {
                finishStructurePublish()
            }
            if (generatedOnlyRefs) {
                if (isImmediateNtkGeneratedUx() && isActiveGeneratedTouchOrQuiet()) {
                    requestGeneratedViewportProofAndRunwayBytes("generated_full_publish")
                    logNtkRepositoryStage(
                        target,
                        "early_urls_append_full_generated_fast_fling_skip_active",
                        "total=$total,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                } else {
                    requestInitialFastFlingGeneratedRunway("generated_full_publish")
                }
                if (!generatedWarmStartedBeforePublish) {
                    logNtkRepositoryStage(
                        target,
                        "early_urls_append_full_skip_generated_warm",
                        "total=$total,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    warmNtkGeneratedInitialPagesLimited(currentStartPage(), loadStartedAt)
                }
                requestGeneratedPublishWarmPagesAfterInitialContinuous("generated_full_publish")
                if (refreshedInPlace) {
                    val start = currentStartPage()
                    requestPage(start, busy = true, anchor = true, generation = FOREGROUND_PRIME_WARM_GENERATION)
                    requestInitialContinuousPagesFromEarlyUrls(start, total)
                }
                if (gateGeneratedAppendNotify) {
                    notifyGeneratedAppendWhenNearReady(target, startIndex, total, loadStartedAt)
                }
            } else {
                warmNtkInitialPages(currentStartPage())
                val refs = synchronized(pagesLock) { pages.toList() }
                requestInitialRapidScrollGeneratedWindow(refs, "initial_full_publish")
                if (refreshedExisting && isImmediateNtkGeneratedUx()) {
                    requestAllUndeliveredNtkPages("verified_refresh_full")
                }
            }
        }
        if (!posted) finishStructurePublish()
    }

    private fun requestGeneratedPublishWarmPagesAfterInitialContinuous(reason: String) {
        if (shouldDeferGeneratedFullSurfaceWorkForInitialContinuous()) {
            main.postDelayed({
                if (!cancelled.get()) requestGeneratedPublishWarmPagesAfterInitialContinuous(reason)
            }, NTK_FIRST_BITMAP_FOLLOWUP_RECHECK_MS)
            return
        }
        requestGeneratedPublishWarmPages(reason)
    }

    private fun shouldDeferGeneratedFullSurfaceWorkForInitialContinuous(): Boolean {
        if (!isNtkSource(manga, title)) return false
        val path = manga.ntkEpisodePath.orEmpty()
        val initialContinuousPath = path.startsWith("/webtoon/", ignoreCase = true) ||
            path.startsWith("/manhwa/", ignoreCase = true) ||
            manga.baseMode == MTitle.base_webtoon
        if (!initialContinuousPath) return false
        val start = currentStartPage()
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0 || start !in 0 until count) return false
        val lastRequired = minOf(count - 1, start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1)
        for (index in start..lastRequired) {
            val page = pageRef(index) ?: return true
            if (!hasListenerDrawableDelivery(index, page)) return true
        }
        return false
    }

    private fun shouldGateGeneratedAppendNotifyUntilNearReady(startIndex: Int, total: Int): Boolean {
        if (!isNtkSource(manga, title)) return false
        val firstNearDrawable = firstGeneratedAppendDrawableIndex(startIndex, total) ?: return false
        val page = pageRef(firstNearDrawable) ?: return true
        return !hasListenerDrawableDelivery(firstNearDrawable, page)
    }

    private fun notifyGeneratedAppendWhenNearReady(target: Manga, startIndex: Int, total: Int, loadStartedAt: Long) {
        val firstNearDrawable = firstGeneratedAppendDrawableIndex(startIndex, total) ?: return
        val requiredLast = generatedAppendNotifyRequiredLast(startIndex, total, firstNearDrawable)
        val notify = object : Runnable {
            override fun run() {
                if (cancelled.get()) return
                val ready = hasGeneratedAppendDrawableDeliveryRange(startIndex, requiredLast)
                if (!ready) {
                    main.postDelayed(this, NTK_GENERATED_APPEND_NOTIFY_NEAR_READY_POLL_MS)
                    return
                }
                logNtkRepositoryStage(
                    target,
                    "early_urls_append_full_notify_near_ready",
                    "firstNear=$firstNearDrawable,requiredLast=$requiredLast,total=$total,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                val publishDelayMs = ntkGeneratedAppendPublishDelayMs()
                if (publishDelayMs > 0L) {
                    logNtkRepositoryStage(
                        target,
                        "early_urls_append_full_notify_defer_reader_busy",
                        "delayMs=$publishDelayMs,total=$total,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    main.postDelayed(this, publishDelayMs)
                    return
                }
                listener.onPagesAppended(total)
            }
        }
        notify.run()
    }

    private fun generatedAppendNotifyRequiredLast(startIndex: Int, total: Int, firstNearDrawable: Int): Int {
        if (total <= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) {
            return minOf(total - 1, pagesLastIndex())
        }
        return firstNearDrawable
    }

    private fun hasGeneratedAppendDrawableDeliveryRange(startIndex: Int, requiredLast: Int): Boolean {
        if (requiredLast < startIndex) return false
        for (index in startIndex..requiredLast) {
            val page = pageRef(index) ?: return false
            if (!hasListenerDrawableDelivery(index, page)) return false
        }
        return true
    }

    private fun pagesLastIndex(): Int = synchronized(pagesLock) { pages.lastIndex }

    private fun ntkGeneratedAppendPublishDelayMs(): Long {
        return 0L
    }

    private fun shouldPreserveGeneratedDrawableReadyState(generatedOnlyRefs: Boolean): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (generatedOnlyRefs) return true
        return isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath) &&
            ReaderImageCache.trustedNtkImageApiCount(manga.ntkEpisodePath, 0L) > 0
    }

    private fun firstGeneratedAppendDrawableIndex(startIndex: Int, total: Int): Int? = synchronized(pagesLock) {
        if (startIndex >= total) return@synchronized null
        val last = minOf(total - 1, pages.lastIndex)
        for (index in startIndex..last) {
            val page = pages.getOrNull(index) ?: continue
            if (page.transitionTitle == null) return@synchronized index
        }
        null
    }

    private fun filterKnownMissingGeneratedInitialUrls(
        target: Manga,
        urls: List<String>,
        loadStartedAt: Long
    ): List<String> {
        if (!isNtkSource(target, title) || urls.none { isNtkGeneratedImageUrl(it) }) return urls
        if (shouldBlockTrustedNtkGeneratedShrink(target, urls.size, "filter_known_missing_before")) return urls
        val targetPath = target.ntkEpisodePath?.trim().orEmpty()
        val allGenerated = urls.all { isNtkGeneratedImageUrl(it) }
        if (
            targetPath.startsWith("/webtoon/", ignoreCase = true) &&
            allGenerated &&
            ntkGeneratedBatchUnavailablePaths.contains(targetPath)
        ) {
            if (trustedNtkGeneratedImageCount(target) > 0) {
                logNtkRepositoryStage(
                    target,
                    "early_urls_keep_generated_batch_authoritative",
                    "count=${urls.size},trusted=${trustedNtkGeneratedImageCount(target)},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                return urls
            }
            return emptyList()
        }
        var removed = 0
        val trustedCount = trustedNtkGeneratedImageCount(target)
        val filtered = urls.filterIndexed { index, image ->
            val remove = isNtkGeneratedImageUrl(image) && ReaderImageCache.isKnownNtkGeneratedNotFound(target, image)
            if (remove && trustedCount > 0 && index < trustedCount) {
                logNtkRepositoryStage(
                    target,
                    "early_urls_keep_known_missing_inside_authoritative",
                    "page=${index + 1},trusted=$trustedCount,image=${image.substringAfterLast('/')}"
                )
                return@filterIndexed true
            }
            if (remove) removed++
            !remove
        }
        if (removed > 0) {
            if (
                targetPath.startsWith("/webtoon/", ignoreCase = true) &&
                allGenerated
            ) {
                if (filtered.isEmpty()) {
                    if (trustedCount > 0) return urls
                    if (ntkGeneratedBatchUnavailablePaths.add(targetPath)) {
                        logNtkRepositoryStage(
                            target,
                            "early_urls_drop_generated_batch_after_not_found",
                            "from=${urls.size},removed=$removed,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                        )
                        removeInitialUnavailableGeneratedPages(target)
                        replaceUnavailableGeneratedInitialWithAdjacent(target, loadStartedAt)
                    }
                    return emptyList()
                }
                logNtkRepositoryStage(
                    target,
                    "early_urls_filter_generated_not_found_partial",
                    "from=${urls.size},to=${filtered.size},removed=$removed,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                return filtered
            }
            logNtkRepositoryStage(
                target,
                "early_urls_filter_generated_not_found",
                "from=${urls.size},to=${filtered.size},removed=$removed,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
        }
        return filtered
    }

    private fun shouldKeepManhwaGeneratedAppendToObservedUrls(target: Manga, urls: List<String>): Boolean {
        if (!isNtkSource(target, title)) return false
        if (!isNtkManhwaEpisodePath(target.ntkEpisodePath)) return false
        if (urls.size <= 1 || urls.any { !isNtkGeneratedImageUrl(it) }) return false
        val trustedApiCount = ReaderImageCache.trustedNtkImageApiCount(
            target.ntkEpisodePath,
            SystemClock.elapsedRealtime() - 30_000L
        )
        if (trustedApiCount >= urls.size) return false
        val knownCount = target.ntkImageCount
        if (knownCount >= urls.size) return false
        val observed = observedInitialManhwaGeneratedUrls(target, urls)
        return observed.isNotEmpty() && observed.size < urls.size
    }

    private fun observedInitialManhwaGeneratedUrls(target: Manga, fallback: List<String>): List<String> {
        val observed = ReaderImageCache
            .earlyNtkGeneratedSuccessImageUrls(target.ntkEpisodePath, SystemClock.elapsedRealtime() - 30000L)
            .filter { isNtkGeneratedImageUrl(it) }
        if (observed.isNotEmpty()) return observed
        val verifiedInitial = ReaderImageCache
            .earlyNtkImageUrls(target.ntkEpisodePath, SystemClock.elapsedRealtime() - 30000L)
            .filter { isNtkGeneratedImageUrl(it) }
        if (verifiedInitial.size > 1) {
            val count = minOf(verifiedInitial.size, fallback.size, ntkInitialGeneratedRecoveryPagesForTarget(target))
            if (count > 1) return fallback.take(count)
        }
        return fallback.take(1)
    }

    private fun installedGeneratedPageCountForCurrentEpisode(): Int = synchronized(pagesLock) {
        pages.count { page ->
            page.transitionTitle == null && isNtkGeneratedImageUrl(page.image.orEmpty())
        }
    }

    private fun installedDrawablePageCountForEpisode(target: Manga): Int = synchronized(pagesLock) {
        pages.count { page ->
            page.transitionTitle == null && looseSameEpisodeForAppend(page.manga, target)
        }
    }

    private fun shouldSkipGeneratedTailExpansionAfterAuthoritativeDirect(
        target: Manga,
        urls: List<String>,
        installedCount: Int,
        loadStartedAt: Long,
        reason: String
    ): Boolean {
        if (!isNtkSource(target, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        if (installedCount <= 0 || urls.size <= installedCount) return false
        if (urls.none { isNtkGeneratedImageUrl(it) }) return false
        val trustedApiCount = ReaderImageCache.trustedNtkImageApiCount(target.ntkEpisodePath, 0L)
        if (trustedApiCount <= 0 || trustedApiCount > installedCount) return false
        val metadataTailComplete = ReaderImageCache.hasMetadataBackedTailEarlyNtkImageUrls(
            target.ntkEpisodePath,
            urls.size,
            0L
        )
        if (metadataTailComplete) {
            logNtkRepositoryStage(
                target,
                "early_urls_generated_tail_keep_metadata_tail",
                "reason=$reason,installed=$installedCount,incoming=${urls.size},trusted=$trustedApiCount," +
                    "ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            return false
        }
        if (!metadataTailComplete && urls.size > trustedApiCount) {
            logNtkRepositoryStage(
                target,
                "early_urls_generated_tail_skip_trusted_manifest",
                "reason=$reason,installed=$installedCount,incoming=${urls.size},trusted=$trustedApiCount," +
                    "ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            return true
        }
        val directInstalled = synchronized(pagesLock) {
            pages.count { page ->
                page.transitionTitle == null &&
                    looseSameEpisodeForAppend(page.manga, target) &&
                    !isNtkGeneratedImageUrl(page.image.orEmpty())
            }
        }
        if (directInstalled < trustedApiCount) return false
        val directHeadCount = urls.take(trustedApiCount).count { !isNtkGeneratedImageUrl(it) }
        if (directHeadCount < trustedApiCount) return false
        logNtkRepositoryStage(
            target,
            "early_urls_generated_tail_skip_authoritative_direct",
            "reason=$reason,installed=$installedCount,incoming=${urls.size},trusted=$trustedApiCount," +
                "directInstalled=$directInstalled,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        return true
    }

    private fun shouldSkipLateInitialEpisodeShrink(
        target: Manga,
        fullRefs: List<PageRef>,
        sourceUrls: List<String>,
        loadStartedAt: Long
    ): Boolean {
        if (!firstBitmapLogged.get() || !isNtkSource(target, title) || fullRefs.isEmpty()) return false
        val installedForEpisode = installedDrawablePageCountForEpisode(target)
        val incomingForEpisode = fullRefs.count { ref ->
            ref.transitionTitle == null && looseSameEpisodeForAppend(ref.manga, target)
        }
        if (installedForEpisode <= incomingForEpisode) return false
        val knownCount = target.ntkImageCount
        val knownComplete = knownCount > 0 && incomingForEpisode >= knownCount
        if (knownComplete) return false
        logNtkRepositoryStage(
            target,
            "early_urls_refresh_full_skip_late_episode_shrink",
            "installed=$installedForEpisode,incoming=$incomingForEpisode,known=$knownCount,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        return true
    }

    private fun shouldAvoidFrontQueueDuringActiveNtkInput(): Boolean {
        if (!isNtkSource(manga, title)) return false
        if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L) return false
        return viewportBusy.get() ||
            ntkInitialInteractiveSettleRemainingMs() > 0L ||
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L
    }

    private fun isActiveInitialGeneratedInput(): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L) return false
        return viewportBusy.get() ||
            ntkInitialInteractiveSettleRemainingMs() > 0L ||
            readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS) > 0L ||
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L
    }

    private fun postMainPreferFrontDuringInput(runnable: Runnable): Boolean {
        return if (shouldAvoidFrontQueueDuringActiveNtkInput()) {
            main.post(runnable)
        } else {
            mainImmediate.post(runnable)
        }
    }

    private fun postPublishPreferFrontDuringInput(publish: () -> Unit): Boolean {
        return postMainPreferFrontDuringInput(Runnable { publish() })
    }

    private fun postInitialFullAppendPublish(
        target: Manga,
        total: Int,
        generatedOnlyRefs: Boolean,
        loadStartedAt: Long,
        refreshedExisting: Boolean = false,
        previousTotal: Int = 0,
        forceImmediatePublish: Boolean = false,
        publish: () -> Unit
    ): Boolean {
        if (!isNtkSource(target, title)) {
            return main.post(publish)
        }
        if (forceImmediatePublish) {
            logNtkRepositoryStage(
                target,
                "early_urls_append_full_publish_forced_immediate",
                "total=$total,generated=$generatedOnlyRefs,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            return postPublishPreferFrontDuringInput(publish)
        }
        if (shouldPublishInitialContinuousRunwayImmediately(target, total, generatedOnlyRefs)) {
            logNtkRepositoryStage(
                target,
                "early_urls_append_full_publish_initial_runway",
                "total=$total,generated=$generatedOnlyRefs,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            return postPublishPreferFrontDuringInput(publish)
        }
        val trustedDirectWebtoon = isTrustedDirectWebtoonGeneratedEpisode(target)
        if (trustedDirectWebtoon) {
            val firstBitmapReady = firstBitmapLogged.get() || ntkFirstBitmapAtMs.get() > 0L
            val sameCountRefresh = refreshedExisting && previousTotal == total
            if (generatedOnlyRefs && firstBitmapReady && sameCountRefresh) {
                val quietMs = generatedFullAppendQuietRemainingMs()
                if (quietMs > 0L) {
                    logNtkRepositoryStage(
                        target,
                        "early_urls_append_full_publish_trusted_direct_webtoon_defer_quiet",
                        "total=$total,previous=$previousTotal,delayMs=$quietMs,generated=$generatedOnlyRefs," +
                            "ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    return main.postDelayed(publish, quietMs)
                }
            }
            logNtkRepositoryStage(
                target,
                "early_urls_append_full_publish_trusted_direct_webtoon",
                "total=$total,previous=$previousTotal,generated=$generatedOnlyRefs," +
                    "refresh=$refreshedExisting,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            return postPublishPreferFrontDuringInput(publish)
        }
        if (firstBitmapLogged.get() || ntkFirstBitmapAtMs.get() > 0L) {
            if (generatedOnlyRefs) {
                val quietMs = ntkBackgroundWarmQuietRemainingMs()
                if (quietMs > 0L) {
                    logNtkRepositoryStage(
                        target,
                        "early_urls_append_full_publish_generated_defer_quiet",
                        "total=$total,delayMs=$quietMs,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    return main.postDelayed(publish, quietMs)
                }
                logNtkRepositoryStage(
                    target,
                    "early_urls_append_full_publish_generated_immediate",
                    "total=$total,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                return postPublishPreferFrontDuringInput(publish)
            }
            logNtkRepositoryStage(
                target,
                "early_urls_append_full_publish_front_after_bitmap_delivery",
                "total=$total,generated=$generatedOnlyRefs,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            return if (generatedOnlyRefs) {
                main.post(publish)
            } else {
                postPublishPreferFrontDuringInput(publish)
            }
        }
        try {
            control.execute {
                val deadline = SystemClock.elapsedRealtime() + NTK_INITIAL_FULL_APPEND_PUBLISH_AFTER_FIRST_BITMAP_WAIT_MS
                while (!cancelled.get() &&
                    !firstBitmapLogged.get() &&
                    ntkFirstBitmapAtMs.get() <= 0L &&
                    SystemClock.elapsedRealtime() < deadline
                ) {
                    try {
                        Thread.sleep(NTK_EARLY_URL_POLL_MS)
                    } catch (e: InterruptedException) {
                        Thread.currentThread().interrupt()
                        main.post(publish)
                        return@execute
                    }
                }
                val firstBitmapReady = firstBitmapLogged.get() || ntkFirstBitmapAtMs.get() > 0L
                logNtkRepositoryStage(
                    target,
                    "early_urls_append_full_publish_${if (firstBitmapReady) "after_first_bitmap" else "deadline"}",
                    "firstBitmap=$firstBitmapReady,total=$total,generated=$generatedOnlyRefs,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                val posted = if (firstBitmapReady) {
                    postPublishPreferFrontDuringInput(publish)
                } else {
                    main.post(publish)
                }
                if (!posted) finishStructurePublish()
            }
        } catch (_: RejectedExecutionException) {
            if (!main.post(publish)) finishStructurePublish()
        }
        return true
    }

    private fun shouldPublishInitialContinuousRunwayImmediately(
        target: Manga,
        total: Int,
        generatedOnlyRefs: Boolean
    ): Boolean {
        if (!generatedOnlyRefs) return false
        if (total > NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        return synchronized(pagesLock) { pages.size <= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES }
    }

    private fun shouldDeferInitialFullAppendUntilFirstBitmap(fullRefs: List<PageRef>): Boolean {
        if (firstBitmapLogged.get() || ntkFirstBitmapAtMs.get() > 0L) return false
        if (!isNtkSource(manga, title)) return false
        if (!isGeneratedOnlyNtkRefs(fullRefs)) return false
        val installedCount = synchronized(pagesLock) { pages.size }
        if (
            isNtkWebtoonEpisodePath(manga.ntkEpisodePath) &&
            installedCount in 1..NTK_WEBTOON_INITIAL_VISIBLE_RECOVERY_PAGES &&
            fullRefs.size > installedCount
        ) {
            logNtkRepositoryStage(
                manga,
                "early_urls_append_full_no_defer_webtoon_initial",
                "installed=$installedCount,total=${fullRefs.size}"
            )
            return false
        }
        return installedCount > 0 && fullRefs.size > installedCount
    }

    private fun shouldDeferGeneratedFullAppendUntilReaderQuiet(generatedOnlyRefs: Boolean): Boolean {
        if (!generatedOnlyRefs) return false
        if (!isNtkSource(manga, title)) return false
        if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L) return false
        return generatedFullAppendQuietRemainingMs() > 0L
    }

    private fun isTrustedDirectWebtoonGeneratedEpisode(target: Manga): Boolean {
        if (!isNtkWebtoonEpisodePath(target.ntkEpisodePath)) return false
        val latest = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, 0L)
        if (latest.isEmpty()) return false
        val generatedWtUrls = latest.all { isNtkGeneratedImageUrl(it) } &&
            latest.any { it.contains("/wt/episodes/", ignoreCase = true) }
        if (generatedWtUrls) return true
        val trustedApiCount = ReaderImageCache.trustedNtkImageApiCount(target.ntkEpisodePath, 0L)
        if (trustedApiCount < minOf(latest.size, NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)) return false
        return latest.all {
            isNtkGeneratedImageUrl(it) ||
                ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(it)
        }
    }

    private fun generatedFullAppendQuietRemainingMs(): Long {
        if (!isNtkSource(manga, title)) return 0L
        val touchQuiet = readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS)
        return maxOf(touchQuiet, ntkBackgroundWarmQuietRemainingMs())
    }

    private fun deferGeneratedFullAppendUntilReaderQuiet(target: Manga, urls: List<String>, loadStartedAt: Long) {
        val delayMs = generatedFullAppendQuietRemainingMs().coerceAtLeast(NTK_GENERATED_FULL_APPEND_RECHECK_MS)
        main.postDelayed({
            if (cancelled.get()) return@postDelayed
            val quietMs = generatedFullAppendQuietRemainingMs()
            if (quietMs > 0L) {
                deferGeneratedFullAppendUntilReaderQuiet(target, urls, loadStartedAt)
                return@postDelayed
            }
            appendInitialNtkUrlsAfterEarlyInstall(
                target,
                urls,
                loadStartedAt,
                allowFirstBitmapDefer = false
            )
        }, delayMs)
    }

    private fun deferInitialFullAppendUntilFirstBitmap(target: Manga, urls: List<String>, loadStartedAt: Long) {
        if (!initialFullAppendDeferredUntilFirstBitmap.compareAndSet(false, true)) return
        control.execute {
            val deadline = SystemClock.elapsedRealtime() + NTK_INITIAL_FULL_APPEND_AFTER_FIRST_BITMAP_WAIT_MS
            while (!cancelled.get() &&
                !firstBitmapLogged.get() &&
                ntkFirstBitmapAtMs.get() <= 0L &&
                SystemClock.elapsedRealtime() < deadline
            ) {
                try {
                    Thread.sleep(NTK_EARLY_URL_POLL_MS)
                } catch (e: InterruptedException) {
                    Thread.currentThread().interrupt()
                    initialFullAppendDeferredUntilFirstBitmap.set(false)
                    return@execute
                }
            }
            initialFullAppendDeferredUntilFirstBitmap.set(false)
            if (!cancelled.get()) {
                logNtkRepositoryStage(
                    target,
                    "early_urls_append_full_after_first_bitmap",
                    "firstBitmap=${firstBitmapLogged.get()},count=${urls.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                appendInitialNtkUrlsAfterEarlyInstall(target, urls, loadStartedAt, allowFirstBitmapDefer = false)
            }
        }
    }

    private fun shouldKeepCurrentNaverOriginalRefs(target: Manga, sourceUrls: List<String>): Boolean {
        if (!isNtkSource(target, title)) return false
        if (sourceUrls.isEmpty() || !sourceUrls.all { isNtkGeneratedImageUrl(it) }) return false
        return synchronized(pagesLock) {
            pages.any { current ->
                current.transitionTitle == null &&
                    Manga.sameEpisodeIdentity(current.manga, target) &&
                    isNaverWebtoonPageImageUrl(current.image.orEmpty())
            }
        }
    }

    private fun isGeneratedOnlyNtkRefs(refs: List<PageRef>): Boolean {
        if (refs.isEmpty()) return false
        return refs.all { ref ->
            ref.transitionTitle != null || isNtkGeneratedDescriptorOrImagePage(ref)
        }
    }

    private fun shouldKeepMetadataBackedGeneratedEarlyExpansion(
        target: Manga,
        refs: List<PageRef>,
        trustedApiCount: Int,
        loadStartedAt: Long
    ): Boolean {
        if (trustedApiCount <= 0 || refs.size <= trustedApiCount) return false
        val metadataTailComplete = ReaderImageCache.hasMetadataBackedTailEarlyNtkImageUrls(
            target.ntkEpisodePath,
            refs.size,
            loadStartedAt - 1_200L
        )
        if (target.ntkImageCount > 0 && target.ntkImageCount < refs.size && !metadataTailComplete) return false
        val earlyUrls = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, loadStartedAt - 1_200L)
        if (earlyUrls.size < refs.size) return false
        val headLimit = minOf(trustedApiCount, refs.size, earlyUrls.size)
        for (index in 0 until headLimit) {
            if (!sameNtkAnchorAssetImage(refs[index].image.orEmpty(), earlyUrls[index], index)) return false
        }
        for (index in trustedApiCount until refs.size) {
            val image = refs[index].image.orEmpty()
            if (!isNtkGeneratedImageUrl(image)) return false
            if (!sameNtkAnchorAssetImage(image, earlyUrls[index], index)) return false
        }
        return true
    }

    private fun isCurrentManhwaGeneratedOnlyRefs(): Boolean {
        if (!isNtkManhwaEpisodePath(manga.ntkEpisodePath)) return false
        val refs = synchronized(pagesLock) { pages.toList() }
        return isGeneratedOnlyNtkRefs(refs)
    }

    private fun replaceNtkBoardUploadsWithGeneratedFullRefs(target: Manga, fullRefs: List<PageRef>): List<PageRef> {
        if (!isNtkSource(target, title) || fullRefs.isEmpty()) return fullRefs
        if (fullRefs.none { isNtkBoardUploadImageUrl(it.image) }) return fullRefs
        val trustedApiCount = ReaderImageCache.trustedNtkImageApiCount(target.ntkEpisodePath, 0L)
        if (trustedApiCount >= fullRefs.count { it.transitionTitle == null }) {
            logNtkRepositoryStage(
                target,
                "board_uploads_keep_trusted_manifest",
                "count=${fullRefs.count { isNtkBoardUploadImageUrl(it.image) }},trusted=$trustedApiCount,total=${fullRefs.size}"
            )
            return fullRefs
        }
        val seed = currentNtkGeneratedSeed()
        if (seed != null) {
            return replaceNtkBoardUploadsWithGeneratedSeed(target, fullRefs, seed)
        }
        logNtkRepositoryStage(
            target,
            "board_uploads_keep_original",
            "count=${fullRefs.count { isNtkBoardUploadImageUrl(it.image) }}"
        )
        return fullRefs
    }

    private fun replaceNtkBoardUploadsWithGeneratedSeed(
        target: Manga,
        fullRefs: List<PageRef>,
        seed: String
    ): List<PageRef> {
        val boardCount = fullRefs.count { isNtkBoardUploadImageUrl(it.image) }
        val reportedCount = target.ntkImageCount
        val preserveMetadataBackedFullList =
            reportedCount >= fullRefs.size ||
                ReaderImageCache.hasMetadataBackedTailEarlyNtkImageUrls(
                    target.ntkEpisodePath,
                    fullRefs.size,
                    SystemClock.elapsedRealtime() - 30_000L
                )
        val reportedCountCap =
            reportedCount > 0 &&
                reportedCount < fullRefs.size &&
                !preserveMetadataBackedFullList
        val sourceRefs = if (
            reportedCountCap
        ) {
            fullRefs.take(reportedCount)
        } else if (
            boardCount > 0 &&
            fullRefs.size > NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD &&
            !preserveMetadataBackedFullList
        ) {
            fullRefs.take(NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD)
        } else {
            fullRefs
        }
        val replaced = sourceRefs.map { ref ->
            if (ref.transitionTitle != null || !isNtkBoardUploadImageUrl(ref.image)) {
                ref
            } else {
                val generated = ntkGeneratedImageUrlForTarget(seed, target, ref.sourceIndex + 1)
                if (generated == null) ref else ref.copy(image = generated)
            }
        }
        if (replaced == fullRefs) return fullRefs
        Log.d(
            TAG,
            "ntk_generated_full_replace_board_uploads path=${target.ntkEpisodePath}," +
                "count=$boardCount,from=${fullRefs.size},to=${replaced.size}," +
                "reportedCount=$reportedCount,reportedCap=$reportedCountCap," +
                "seed=${seed.substringAfter("://")}"
        )
        return replaced
    }

    private fun currentNtkGeneratedSeed(): String? {
        val pageSeed = pages.firstOrNull {
            it.transitionTitle == null && isNtkGeneratedImageUrl(it.image.orEmpty())
        }?.image
        if (pageSeed != null) return pageSeed
        return ReaderImageCache
            .earlyNtkImageUrls(manga.ntkEpisodePath, SystemClock.elapsedRealtime() - 30000L)
            .firstOrNull { isNtkGeneratedImageUrl(it) }
    }

    private fun shouldRefreshInitialNtkInstalledRefs(fullRefs: List<PageRef>): Boolean {
        if (!isNtkSource(manga, title)) return false
        if (fullRefs.isEmpty()) return false
        if (pages.size != fullRefs.size) return true
        for (index in fullRefs.indices) {
            val current = pages.getOrNull(index) ?: return true
            val incoming = fullRefs[index]
            if (current.transitionTitle != incoming.transitionTitle) return true
            if (current.image != incoming.image) return true
            if (current.manga.ntkEpisodePath != incoming.manga.ntkEpisodePath) return true
        }
        return false
    }

    private fun shouldRefreshGeneratedSeedWithVerifiedUrls(target: Manga, fullRefs: List<PageRef>): Boolean {
        if (!isNtkSource(target, title) || fullRefs.isEmpty()) return false
        if (fullRefs.all { it.transitionTitle != null || isNtkGeneratedImageUrl(it.image.orEmpty()) }) return false
        return pages.any { current ->
            current.transitionTitle == null &&
                Manga.sameEpisodeIdentity(current.manga, target) &&
                isNtkGeneratedImageUrl(current.image.orEmpty())
        }
    }

    private fun shouldReplaceKpDescriptorSeedWithVerifiedUrls(target: Manga, fullRefs: List<PageRef>): Boolean {
        if (!isNtkSource(target, title) || !isKpWebtoonSlugEpisodePath(target.ntkEpisodePath)) return false
        if (fullRefs.isEmpty() || fullRefs.size <= pages.size) return false
        val incomingFirst = fullRefs.firstOrNull()?.image.orEmpty()
        if (!isNtkKpDescriptorImageUrl(incomingFirst)) return false
        val currentFirst = pages.firstOrNull {
            it.transitionTitle == null && Manga.sameEpisodeIdentity(it.manga, target)
        }?.image.orEmpty()
        if (!isNtkKpDescriptorImageUrl(currentFirst) || currentFirst == incomingFirst) return false
        val currentBare = currentFirst.substringBefore('#').substringBefore('?')
        val incomingBare = incomingFirst.substringBefore('#').substringBefore('?')
        return currentBare.endsWith(incomingBare.substringAfterLast('/'), ignoreCase = true) ||
            incomingBare.endsWith(currentBare.substringAfterLast('/'), ignoreCase = true)
    }

    private fun shouldPreferSameLengthVerifiedApiGeneratedUrls(
        target: Manga,
        urls: List<String>,
        verifiedApiUrls: List<String>
    ): Boolean {
        if (!isNtkSource(target, title)) return false
        if (urls.isEmpty() || verifiedApiUrls.isEmpty()) return false
        if (verifiedApiUrls.size < urls.size) return false
        if (!urls.all { isNtkGeneratedImageUrl(it) }) return false
        if (!verifiedApiUrls.all { isNtkGeneratedImageUrl(it) }) return false
        if (urls.firstOrNull() == verifiedApiUrls.firstOrNull()) return false
        val known = target.ntkImageCount
        return known <= 0 || verifiedApiUrls.size >= minOf(urls.size, known)
    }

    private fun startInitialForegroundStreamIfNeeded(
        target: Manga,
        urls: List<String>,
        startPage: Int,
        loadStartedAt: Long
    ): Boolean {
        if (!isNtkSource(target, title)) return false
        val image = urls.getOrNull(startPage) ?: return false
        val started = try {
            val permit = ntkCoordinator?.imagePermit(
                startPage,
                target,
                image,
                NtkImageLane.FIRST_IMAGE,
                "startInitialForegroundStreamIfNeeded"
            )
            if (!ntkCoordinatorAllowsStream(startPage, target, image, permit, "startInitialForegroundStreamIfNeeded")) {
                false
            } else {
                startBoundedForegroundStreamFetch(
                    appContext,
                    target,
                    image,
                    imageCancellation,
                    anchorHedge = false,
                    permit = permit,
                    pageIndex = startPage
                )
            }
        } catch (e: Exception) {
            recordIfUnexpected(e)
            false
        }
        Log.d(
            TAG,
            "reader_anchor_stream_after_urls page=$startPage,started=$started,count=${urls.size}," +
                "ms=${SystemClock.elapsedRealtime() - loadStartedAt},path=${target.ntkEpisodePath}"
        )
        scheduleNtkAnchorCachedDecodeRetry(startPage, "anchor_stream_after_urls", loadStartedAt)
        ViewerWarmupManager.logMetric("reader_anchor_stream_after_urls", if (started) 1L else 0L)
        return started
    }

    private fun startAdjacentForegroundStreams(
        target: Manga,
        urls: List<String>,
        direction: Int,
        asyncLaunch: Boolean = false
    ) {
        if (!isNtkSource(target, title) || urls.isEmpty()) return
        if (direction > 0 &&
            isNtkContinuousAdjacentCompletionPolicyActive() &&
            !isCurrentEpisodeCompleteForImmediateAdjacentStream(target, direction)
        ) {
            Log.d(
                TAG,
                "append_adjacent_foreground_streams_wait_current_complete " +
                    "path=${target.ntkEpisodePath}"
            )
            return
        }
        if (direction > 0 && holdOrRecoverAdjacentStrictSource(target)) {
            Log.d(
                TAG,
                "append_adjacent_foreground_streams_strict_owned path=${target.ntkEpisodePath}",
            )
            return
        }
        if (direction > 0 && shouldDeferAdjacentRunwayBehindActiveRemaining(target)) return
        if (asyncLaunch) {
            try {
                network.execute {
                    startAdjacentForegroundStreams(target, urls, direction, asyncLaunch = false)
                }
            } catch (_: RejectedExecutionException) {
            }
            return
        }
        // At the physical end of a fully delivered current episode these are no longer
        // background warm-up requests: they are the next pixels in the user's forward viewport.
        // Do not make that runway wait for the scroll-idle debounce that can remain continuously
        // armed while the user is pressing against the bottom edge.
        val currentEpisodeCompleteForImmediateAdjacent =
            isCurrentEpisodeCompleteForImmediateAdjacentStream(target, direction)
        val activeTouchQuietMs = if (
            isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath) &&
            !currentEpisodeCompleteForImmediateAdjacent
        ) {
            val requiredQuietMs = if (isImmediateNtkGeneratedUx() && direction > 0) {
                NTK_ADJACENT_FOREGROUND_INPUT_QUIET_MS
            } else {
                NTK_BACKGROUND_WARM_TOUCH_QUIET_MS
            }
            maxOf(
                readerQuietRemainingMs(requiredQuietMs),
                if (isImmediateNtkGeneratedUx()) 0L else readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS),
                if (isImmediateNtkGeneratedUx()) 0L else ntkInitialInteractiveSettleRemainingMs(),
                if (viewportBusy.get()) requiredQuietMs else 0L
            )
        } else {
            0L
        }
        val quietMs = if (currentEpisodeCompleteForImmediateAdjacent) {
            0L
        } else {
            maxOf(ntkBackgroundPrepareQuietRemainingMs(), activeTouchQuietMs)
        }
        if (quietMs > 0L) {
            Log.d(
                TAG,
                "append_adjacent_foreground_streams_defer targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} direction=$direction quietMs=$quietMs"
            )
            main.postDelayed({
                if (cancelled.get()) return@postDelayed
                try {
                    control.execute { startAdjacentForegroundStreams(target, urls, direction) }
                } catch (_: RejectedExecutionException) {
                }
            }, quietMs.coerceAtLeast(NTK_ADJACENT_FOREGROUND_STREAM_RECHECK_MS))
            return
        }
        ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
            target.ntkEpisodePath,
            NTK_ADJACENT_APPEND_FOREGROUND_PATH_TTL_MS,
            "start_adjacent_streams"
        )
        val streamPages = adjacentInitialForegroundStreamPages(target, urls, direction)
        if (streamPages <= 0) return
        val indexes = if (direction < 0) {
            ((urls.size - streamPages).coerceAtLeast(0) until urls.size).toList().asReversed()
        } else {
            (0 until minOf(urls.size, streamPages)).toList()
        }
        var startedCount = 0
        var skippedRecent = 0
        var hedgeStartedCount = 0
        for (index in indexes) {
            val image = urls.getOrNull(index) ?: continue
            val appendKey = adjacentForegroundStreamKey(target, image, index)
            if (hasRecentAdjacentForegroundStream(target, image, index)) {
                skippedRecent++
                continue
            }
            val started = startAdjacentForegroundStreamPage(
                target,
                image,
                index,
                source = "startAdjacentForegroundStreams",
                visiblePriority = true
            )
            if (started) {
                adjacentForegroundStreamedAppendKeys[appendKey] = SystemClock.elapsedRealtime()
                startedCount++
            }
            if (started || ReaderImageCache.cachedFile(appContext, target, image) == null) {
                hedgeStartedCount += startAdjacentGeneratedExtensionHedges(
                    target,
                    image,
                    index,
                    source = "startAdjacentForegroundStreams"
                )
            }
        }
        Log.d(
            TAG,
            "append_adjacent_foreground_streams targetId=${target.id} path=${target.ntkEpisodePath} " +
                "direction=$direction,started=$startedCount,hedgeStarted=$hedgeStartedCount," +
                "skippedRecent=$skippedRecent,count=${indexes.size}"
        )
    }

    private fun startAdjacentForegroundStreamsForRefs(
        target: Manga,
        refs: List<PageRef>,
        direction: Int,
        asyncLaunch: Boolean = false
    ) {
        if (!isNtkSource(target, title) || refs.isEmpty()) return
        if (direction > 0 &&
            isNtkContinuousAdjacentCompletionPolicyActive() &&
            !isCurrentEpisodeCompleteForImmediateAdjacentStream(target, direction)
        ) {
            Log.d(
                TAG,
                "append_adjacent_foreground_ref_streams_wait_current_complete " +
                    "path=${target.ntkEpisodePath}"
            )
            return
        }
        if (direction > 0 && holdOrRecoverAdjacentStrictSource(target)) {
            Log.d(
                TAG,
                "append_adjacent_foreground_ref_streams_strict_owned path=${target.ntkEpisodePath}",
            )
            return
        }
        if (direction > 0 && shouldDeferAdjacentRunwayBehindActiveRemaining(target)) return
        if (asyncLaunch) {
            try {
                network.execute {
                    startAdjacentForegroundStreamsForRefs(target, refs, direction, asyncLaunch = false)
                }
            } catch (_: RejectedExecutionException) {
            }
            return
        }
        val currentEpisodeCompleteForImmediateAdjacent =
            isCurrentEpisodeCompleteForImmediateAdjacentStream(target, direction)
        val activeTouchQuietMs = if (
            isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath) &&
            !currentEpisodeCompleteForImmediateAdjacent
        ) {
            val requiredQuietMs = if (isImmediateNtkGeneratedUx() && direction > 0) {
                NTK_ADJACENT_FOREGROUND_INPUT_QUIET_MS
            } else {
                NTK_BACKGROUND_WARM_TOUCH_QUIET_MS
            }
            maxOf(
                readerQuietRemainingMs(requiredQuietMs),
                if (isImmediateNtkGeneratedUx()) 0L else readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS),
                if (isImmediateNtkGeneratedUx()) 0L else ntkInitialInteractiveSettleRemainingMs(),
                if (viewportBusy.get()) requiredQuietMs else 0L
            )
        } else {
            0L
        }
        val quietMs = if (currentEpisodeCompleteForImmediateAdjacent) {
            0L
        } else {
            maxOf(ntkBackgroundPrepareQuietRemainingMs(), activeTouchQuietMs)
        }
        if (quietMs > 0L) {
            Log.d(
                TAG,
                "append_adjacent_foreground_ref_streams_defer targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} direction=$direction quietMs=$quietMs"
            )
            main.postDelayed({
                if (cancelled.get()) return@postDelayed
                try {
                    control.execute { startAdjacentForegroundStreamsForRefs(target, refs, direction) }
                } catch (_: RejectedExecutionException) {
                }
            }, quietMs.coerceAtLeast(NTK_ADJACENT_FOREGROUND_STREAM_RECHECK_MS))
            return
        }
        ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
            target.ntkEpisodePath,
            NTK_ADJACENT_APPEND_FOREGROUND_PATH_TTL_MS,
            "start_adjacent_ref_streams"
        )
        val streamRefs = adjacentInitialForegroundStreamRefs(target, refs, direction)
        if (streamRefs.isEmpty()) return
        var startedCount = 0
        var skippedRecent = 0
        var hedgeStartedCount = 0
        for (ref in streamRefs) {
            val image = ref.image ?: continue
            val sourceIndex = adjacentForegroundStreamRefIndex(ref, image)
            if (hasRecentAdjacentForegroundStream(target, image, sourceIndex)) {
                skippedRecent++
                continue
            }
            val appendKey = adjacentForegroundStreamKey(target, image, sourceIndex)
            val started = startAdjacentForegroundStreamPage(
                target,
                image,
                sourceIndex,
                source = "startAdjacentForegroundStreamsForRefs",
                visiblePriority = true
            )
            if (started) {
                adjacentForegroundStreamedAppendKeys[appendKey] = SystemClock.elapsedRealtime()
                startedCount++
            }
            if (started || ReaderImageCache.cachedFile(appContext, target, image) == null) {
                hedgeStartedCount += startAdjacentGeneratedExtensionHedges(
                    target,
                    image,
                    sourceIndex,
                    source = "startAdjacentForegroundStreamsForRefs"
                )
            }
        }
        Log.d(
            TAG,
            "append_adjacent_foreground_ref_streams targetId=${target.id} path=${target.ntkEpisodePath} " +
                "direction=$direction,started=$startedCount,hedgeStarted=$hedgeStartedCount," +
                "skippedRecent=$skippedRecent,count=${streamRefs.size}"
        )
    }

    private fun startAdjacentGeneratedExtensionHedges(
        target: Manga,
        image: String,
        index: Int,
        source: String
    ): Int {
        if (!isImmediateNtkGeneratedUx()) return 0
        if (!isNtkSource(target, title)) return 0
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return 0
        if (!isNtkGeneratedImageUrl(image)) return 0
        if (index !in 0 until NTK_APPEND_GENERATED_EXTENSION_HEDGE_PAGES) return 0
        val currentExtension = generatedImageExtension(image)
        if (!currentExtension.matches(Regex("jpg|jpeg|png|webp", RegexOption.IGNORE_CASE))) return 0
        val hedgeExtensions = listOf("jpeg", "jpg")
            .filterNot { it.equals(currentExtension, ignoreCase = true) }
        var startedCount = 0
        for (extension in hedgeExtensions) {
            val hedge = replaceNtkGeneratedImageExtension(image, extension)
            if (hedge.isEmpty() || hedge == image) continue
            val appendKey = adjacentForegroundStreamKey(target, hedge, index)
            if (hasRecentAdjacentForegroundStream(target, hedge, index)) continue
            if (startAdjacentForegroundStreamPage(
                    target,
                    hedge,
                    index,
                    source = "${source}_extension_hedge",
                    visiblePriority = true
                )
            ) {
                adjacentForegroundStreamedAppendKeys[appendKey] = SystemClock.elapsedRealtime()
                startedCount++
            }
        }
        if (startedCount > 0) {
            Log.d(
                TAG,
                "append_adjacent_generated_extension_hedge targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} index=$index source=$source " +
                    "primary=${image.substringAfterLast('/')} started=$startedCount"
            )
        }
        return startedCount
    }

    private fun startAdjacentForegroundStreamPage(
        target: Manga,
        image: String,
        index: Int,
        source: String,
        visiblePriority: Boolean
    ): Boolean {
        return try {
            val permit = ntkCoordinator?.imagePermit(
                index,
                target,
                image,
                NtkImageLane.NEAR_WARMUP,
                source
            )
            if (!ntkCoordinatorAllowsStream(index, target, image, permit, source)) {
                false
            } else {
                startBoundedForegroundStreamFetch(
                    appContext,
                    target,
                    image,
                    imageCancellation,
                    anchorHedge = false,
                    permit = permit,
                    pageIndex = index,
                    visiblePriority = visiblePriority
                )
            }
        } catch (e: Exception) {
            recordIfUnexpected(e)
            false
        }
    }

    private fun adjacentGeneratedAppendForegroundPages(
        target: Manga,
        urls: List<String>,
        direction: Int
    ): Int {
        if (urls.isEmpty()) return 0
        val pages = if (direction > 0 && isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) {
            generatedAppendVisibleRunwayPageLimit(target)
        } else {
            NTK_ADJACENT_FOREGROUND_STREAM_PAGES
        }
        return minOf(urls.size, pages.coerceAtLeast(1))
    }

    private fun adjacentInitialForegroundStreamPages(
        target: Manga,
        urls: List<String>,
        direction: Int
    ): Int {
        if (urls.isEmpty()) return 0
        if (direction > 0 &&
            isImmediateNtkGeneratedUx() &&
            isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath) &&
            urls.any { isNtkGeneratedImageUrl(it) }
        ) {
            if (isInitialTailAdjacentPreappendTarget(target)) {
                return minOf(
                    urls.size,
                    requiredGeneratedAppendReadyPages(target).coerceAtLeast(1)
                )
            }
            if (isActiveGeneratedTouchOrQuiet() || viewportBusy.get()) {
                return NtkAdjacentRunwayPreparationPolicy.activeAtomicRunwayRequestPages(
                    availablePages = urls.size,
                    atomicPublishPages = NTK_APPEND_INITIAL_RUNWAY_READY_PAGES,
                    activeReadyPages = NTK_APPEND_INITIAL_ACTIVE_RUNWAY_READY_PAGES,
                    activeForegroundPages = NTK_ADJACENT_ACTIVE_FOREGROUND_STREAM_PAGES,
                )
            }
            return minOf(
                urls.size,
                maxOf(
                    requiredGeneratedAppendReadyPages(target).coerceAtLeast(1),
                    initialAdjacentRunwayPageLimit(target.ntkEpisodePath),
                    generatedAppendVisibleRunwayPageLimit(target),
                    NTK_ADJACENT_ACTIVE_FOREGROUND_STREAM_PAGES
                )
            )
        }
        return adjacentGeneratedAppendForegroundPages(target, urls, direction)
    }

    private fun adjacentInitialForegroundStreamRefs(
        target: Manga,
        refs: List<PageRef>,
        direction: Int
    ): List<PageRef> {
        if (refs.isEmpty()) return emptyList()
        val urls = refs.mapNotNull { it.image }
        val streamPages = adjacentInitialForegroundStreamPages(target, urls, direction)
        if (streamPages <= 0) return emptyList()
        val imageRefs = refs.filter { ref ->
            ref.transitionTitle == null && !ref.image.isNullOrBlank()
        }
        return if (direction < 0) {
            imageRefs.takeLast(streamPages).asReversed()
        } else {
            imageRefs.take(streamPages)
        }
    }

    private fun adjacentForegroundStreamRefIndex(ref: PageRef, image: String): Int {
        if (ref.sourceIndex >= 0) return ref.sourceIndex
        ntkImagePageNumber(image)?.let { return (it - 1).coerceAtLeast(0) }
        ntkGeneratedPageNumber(image)?.let { return (it - 1).coerceAtLeast(0) }
        if (ref.localPage > 0) return ref.localPage - 1
        if (ref.pageIndex >= 0) return ref.pageIndex
        return 0
    }

    private fun adjacentForegroundStreamKey(target: Manga, image: String?, index: Int): String {
        val path = target.ntkEpisodePath?.trim().orEmpty()
        val page = ntkImagePageNumber(image.orEmpty()) ?: ntkGeneratedPageNumber(image.orEmpty()) ?: index + 1
        val extension = generatedImageExtension(image)
            .takeIf { it.isNotEmpty() }
            ?: "raw"
        return "$path#$page#$extension"
    }

    private fun hasRecentAdjacentForegroundStream(target: Manga, image: String?, index: Int): Boolean {
        val key = adjacentForegroundStreamKey(target, image, index)
        val startedAt = adjacentForegroundStreamedAppendKeys[key] ?: return false
        if (ReaderImageCache.wasNtkEpisodeWorkCancelledSince(target.ntkEpisodePath, startedAt)) {
            adjacentForegroundStreamedAppendKeys.remove(key, startedAt)
            return false
        }
        val ageMs = SystemClock.elapsedRealtime() - startedAt
        if (ageMs > NTK_APPEND_FOREGROUND_STREAM_SUPPRESS_MS) {
            adjacentForegroundStreamedAppendKeys.remove(key, startedAt)
            return false
        }
        return true
    }

    private fun logNtkRepositoryStage(target: Manga, stage: String, detail: String) {
        if (!isNtkSource(target, title)) return
        Log.d(TAG, "reader_repository_stage stage=$stage,path=${target.ntkEpisodePath},$detail")
    }

    private fun preparedEntryForLaunch(): ReaderPreparedStore.Entry? {
        if (launchPreparedKey.isNullOrEmpty()) return null
        val exact = ReaderPreparedStore.get(launchPreparedKey)
        if (isNtkSource(manga, title) && isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) {
            return exact
        }
        return ReaderPreparedStore.findReadyCompatible(launchPreparedKey) ?: exact
    }

    private fun installPreparedSnapshot(snapshot: ReaderPreparedStore.Snapshot): Boolean {
        if (!preparedSnapshotMatchesCurrentEpisode(snapshot)) {
            logNtkRepositoryStage(
                manga,
                "prepared_snapshot_rejected_episode_mismatch",
                "status=${snapshot.status},count=${snapshot.images?.size ?: 0}," +
                    "first=${snapshot.images?.firstOrNull()?.takeLast(96).orEmpty()}"
            )
            return false
        }
        val urls = snapshot.images
        if (!urls.isNullOrEmpty()) {
            val resolvedStartPage = resolvePreparedStartPage(snapshot.startPage)
            val startPage = installImages(urls, resolvedStartPage, false, notifyInitialPage = false)
            if (preparedLaunchRunwaySpec != null) {
                // The Store already owns the exact, full-quality launch runway. Start the
                // verified byte fanout now, while EpisodeActivity is still staging, instead of
                // waiting for the first post-runway decode to discover the same manifest. The
                // fanout is bounded by protectedNumericBitmapWindow(); while the prepared owner
                // is active decodeRefs stays empty. The immutable Store runway and its one exact
                // attached-root prepare pass are therefore unchanged.
                startVerifiedGeneratedCurrentEpisodeStreams()
            }
            for (entry in snapshot.bitmaps.entries) deliverPreparedSourceBitmap(entry.key, entry.value)
            for (entry in snapshot.tilePages.entries) deliverPreparedSourceTilePage(entry.key, entry.value)
            flushEarlyPreparedBitmaps()
            main.post {
                if (!cancelled.get() && startPage >= 0) listener.onInitialPage(startPage)
            }
            releasePreparedStoreBitmapsSoon()
            if (!hasCompletePreparedWindow(snapshot) &&
                !ReaderWarmupCoordinator.ownsKnownUrlsDecode(preparedStoreKey)
            ) {
                requestPageForeground(resolvedStartPage)
                requestInitialFanout(resolvedStartPage)
            }
            return true
        }
        for (entry in snapshot.bitmaps.entries) {
            if (!entry.value.isRecycled) earlyPreparedBitmaps[entry.key] = entry.value
        }
        return false
    }

    /**
     * A WINDOW_READY entry normally represents only the launch window.  Treat it as a complete
     * drawable surface only when every source image has the exact prepared bitmap still alive.
     * Those bitmaps are installed above as borrowed identities, so an eager foreground/fanout
     * request here would only schedule duplicate upgrades on the activity-start call stack.  The
     * existing first-bitmap quiet/background follow-ups remain responsible for later refinement.
     */
    private fun hasCompletePreparedWindow(snapshot: ReaderPreparedStore.Snapshot?): Boolean {
        if (snapshot?.status != ReaderPreparedStore.Status.WINDOW_READY) return false
        val images = snapshot.images ?: return false
        if (images.isEmpty()) return false
        return images.indices.all { index ->
            snapshot.bitmaps[index]?.let { !it.isRecycled } == true ||
                snapshot.tilePages[index]?.let { page ->
                    page.pageWidth > 0 && page.pageHeight > 0 && page.tiles.isNotEmpty() &&
                        page.tiles.none { it.bitmap.isRecycled }
                } == true
        }
    }

    private fun preparedSnapshotMatchesCurrentEpisode(snapshot: ReaderPreparedStore.Snapshot): Boolean {
        if (!isNtkSource(manga, title) || !isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) return true
        if (!Manga.sameEpisodeIdentity(snapshot.manga, manga)) return false
        return preparedImagesMatchCurrentEpisode(snapshot.images)
    }

    private fun preparedImagesMatchCurrentEpisode(images: List<String>?): Boolean {
        if (!isNtkSource(manga, title) || !isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) return true
        if (images.isNullOrEmpty()) return true
        return images.all { ntkDirectImageBelongsToCurrentEpisode(it) }
    }

    private fun ntkDirectImageBelongsToCurrentEpisode(image: String): Boolean {
        val path = manga.ntkEpisodePath?.trim()?.trimStart('/')?.lowercase(java.util.Locale.ROOT)
            ?: return false
        if (path.isEmpty()) return false
        val normalized = image.lowercase(java.util.Locale.ROOT)
        if (normalized.contains("/api/m/i?")) return false
        return normalized.contains("/$path/")
    }


    private fun releasePreparedStoreBitmapsSoon() {
        if (preparedStoreKey == null) return
        main.removeCallbacks(clearPreparedBitmapsRunnable)
        if (!firstBitmapLogged.get()) return
        main.postDelayed(clearPreparedBitmapsRunnable, PREPARED_BITMAP_RELEASE_DELAY_MS)
    }

    private fun resolveInitialNtkUnavailableEpisode(source: Manga): Pair<Manga, List<String>>? {
        if (!isNtkSource(source, title)) return null
        val generatedUnavailable = ntkGeneratedBatchUnavailablePaths.contains(source.ntkEpisodePath?.trim().orEmpty())
        if (source.ntkViewerParseReason != "unavailable" && !generatedUnavailable) return null
        val currentTitle = title ?: source.title ?: manga.title ?: return null
        if (syncNtkTitlePathFromEpisode(currentTitle, source)) {
            currentTitle.removeEps()
        }
        restoreNtkEpisodeSnapshotIfNeeded(currentTitle, source)
        if (currentTitle.eps == null || currentTitle.eps.size <= 1) {
            Log.d(
                TAG,
                "ntk_initial_unavailable_fetch_episodes_start sourcePath=${source.ntkEpisodePath} " +
                    "titlePath=${currentTitle.path.orEmpty()} eps=${currentTitle.eps?.size ?: 0}"
            )
            val result = withRepositoryCancellation(userVisible = true) {
                imageRepository.fetchEpisodesForeground(currentTitle, it)
            }
            Log.d(
                TAG,
                "ntk_initial_unavailable_fetch_episodes_done sourcePath=${source.ntkEpisodePath} " +
                    "result=$result eps=${currentTitle.eps?.size ?: 0}"
            )
            if (cancelled.get() || result != Title.LOAD_OK) return null
        }
        attachTitle()
        val episodes = Utils.snapshotEpisodes(currentTitle)
        Log.d(
            TAG,
            "ntk_initial_unavailable_episodes sourcePath=${source.ntkEpisodePath} " +
                "count=${episodes.size} first=${episodes.firstOrNull()?.ntkEpisodePath.orEmpty()} " +
                "last=${episodes.lastOrNull()?.ntkEpisodePath.orEmpty()}"
        )
        if (episodes.isNotEmpty()) {
            manga.setEps(episodes)
            source.setEps(episodes)
            persistNtkEpisodeSnapshot(currentTitle, episodes)
        }
        source.title = currentTitle
        source.titleId = currentTitle.id
        // Unavailable-episode recovery is automatic, so it must never walk backward. Readers
        // overwhelmingly continue forward and a hidden previous-episode fetch wastes bandwidth on
        // every network class while competing with the only useful replacement candidate.
        val unavailableRecoveryDirections = listOf(ReaderSurfaceView.DIRECTION_NEXT)
        for (direction in unavailableRecoveryDirections) {
            var checked = 0
            val candidates = adjacentEpisodeCandidates(source, episodes, direction)
            Log.d(
                TAG,
                "ntk_initial_unavailable_candidates direction=$direction sourcePath=${source.ntkEpisodePath} " +
                    "count=${candidates.size} first=${candidates.firstOrNull()?.ntkEpisodePath.orEmpty()}"
            )
            for (candidate in candidates) {
                if (checked >= ADJACENT_EXISTING_SKIP_LIMIT) break
                candidate.title = currentTitle
                candidate.titleId = currentTitle.id
                candidate.mode = source.mode
                if (episodes.isNotEmpty()) candidate.setEps(episodes)
                Log.d(
                    TAG,
                    "ntk_initial_unavailable_candidate_probe direction=$direction sourcePath=${source.ntkEpisodePath} " +
                        "targetPath=${candidate.ntkEpisodePath} checked=$checked"
                )
                val appendLoad = loadAppendUrlsForCandidate(
                    candidate,
                    source,
                    currentTitle,
                    direction,
                )
                if (cancelled.get()) return null
                if (appendLoad.result == Title.LOAD_OK && appendLoad.urls.isNotEmpty()) {
                    Log.d(
                        TAG,
                        "ntk_initial_unavailable_candidate direction=$direction sourcePath=${source.ntkEpisodePath} " +
                            "targetPath=${candidate.ntkEpisodePath} images=${appendLoad.urls.size}"
                    )
                    return candidate to appendLoad.urls
                }
                Log.d(
                    TAG,
                    "ntk_initial_unavailable_candidate_skip direction=$direction sourcePath=${source.ntkEpisodePath} " +
                        "targetPath=${candidate.ntkEpisodePath} result=${appendLoad.result} " +
                        "reason=${candidate.ntkViewerParseReason} images=${appendLoad.urls.size}"
                )
                candidate.setImgs(null)
                checked++
            }
        }
        return null
    }

    private fun installImages(
        urls: List<String>,
        requestedStartPage: Int,
        requestInitialWindow: Boolean,
        notifyInitialPage: Boolean = true
    ): Int = installImagesForManga(manga, urls, requestedStartPage, requestInitialWindow, notifyInitialPage)

    private fun installImagesForManga(
        target: Manga,
        urls: List<String>,
        requestedStartPage: Int,
        requestInitialWindow: Boolean,
        notifyInitialPage: Boolean = true
    ): Int {
        if (cancelled.get() || urls.isEmpty()) return -1
        if (!pagesInstalled.compareAndSet(false, true)) return -1
        val refs = pageRefsForImages(target, urls)
        synchronized(pagesLock) {
            pages.clear()
            deliveredDrawableProofWidths.clear()
            refs.forEachIndexed { index, page ->
                page.pageIndex = index
            }
            pages.addAll(refs)
            capturePublishedPageIndexLocked()
        }
        val startPage = displayStartPage(requestedStartPage, requestedStartSide(), refs)
        resolvedInitialStartPage.set(startPage)
        if (strictExactColdRolling) {
            strictRollingAdmission.compareAndSet(
                null,
                StrictRollingAdmission.initial(
                    refs.size,
                    startPage,
                    strictForwardSourceFloor,
                )
            )
        }
        if (isNtkSource(target, title)) {
            ntkCoordinator = NtkEpisodeCoordinator(target.ntkEpisodePath, true, startPage)
        }
        if (!strictExactColdRolling) {
            maybeStartInitialTailAdjacentPreappend(target, startPage, refs.size, "install_images")
        }
        main.post {
            if (!cancelled.get()) {
                deliverInitialPagesReadyIfNeeded(refs.size, startPage, notifyInitialPage)
            }
        }
        if (!autoCut && !isNtkSource(manga, title) && timelinePrimeRequested.compareAndSet(false, true)) {
            primeForwardTimeline()
        }
        if (requestInitialWindow) requestInitialWindow(startPage, false)
        if (!strictExactColdRolling) {
            requestInitialTailPreviousGeneratedPages(startPage, refs.size, "install_images")
        }
        return startPage
    }

    private fun requestInitialWindow(startPage: Int, busy: Boolean) {
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return
        val preFirstNtkLast = if (
            isNtkSource(manga, title) &&
            !firstBitmapLogged.get() &&
            isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)
        ) {
            startPage
        } else {
            startPage + ReaderPipelinePolicy.INITIAL_WINDOW_AFTER
        }
        requestWindow(
            max(0, startPage - ReaderPipelinePolicy.INITIAL_WINDOW_BEFORE),
            minOf(count - 1, preFirstNtkLast),
            startPage,
            busy
        )
    }

    private fun requestInitialFanout(startPage: Int) {
        if (isNtkSource(manga, title) && !firstBitmapLogged.get()) {
            ViewerWarmupManager.logMetric("reader_ntk_initial_fanout_eager", startPage.toLong())
            warmNtkInitialPages(startPage)
            return
        }
        if (shouldDeferInitialFanoutUntilAnchor()) {
            pendingInitialFanoutPage.set(startPage)
            prefetchImageFilesAround(startPage)
            return
        }
        startInitialFanout(startPage)
    }

    private fun startInitialFanout(startPage: Int) {
        if (!initialFanoutStarted.compareAndSet(false, true)) return
        if (isNtkSource(manga, title)) {
            warmNtkInitialPages(startPage)
        } else {
            requestInitialWindow(startPage, false)
            prefetchImageFilesAround(startPage)
        }
    }

    private fun warmNtkInitialPages(startPage: Int) {
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return
        val anchor = startPage.coerceIn(0, count - 1)
        if (!hasActiveOrDeliveredPage(anchor)) {
            requestPage(anchor, busy = true, anchor = true, generation = FOREGROUND_PRIME_WARM_GENERATION)
        }
        if (!firstBitmapLogged.get() && isImmediateNtkGeneratedUx()) {
            startInteractiveFullSourcePrefetch("pre_first_initial")
            if (preparedLaunchRunwaySpec != null) {
                // The controller obtained this spec only after the Store proved the canonical
                // original, full-quality viewport plus 1.5-view runway. Re-requesting the much
                // wider legacy 16/24-page foreground window here duplicates those installed
                // pages and lets far downloads/disk publication contend with the first touch.
                // The verified byte-only tail remains active on its background lane; an actual
                // viewport request still promotes the needed page immediately.
                Log.d(
                    TAG,
                    "reader_ntk_initial_warm_use_prepared_physical_runway start=$anchor," +
                        "viewport=${preparedLaunchRunwaySpec.viewportWidth}x${preparedLaunchRunwaySpec.viewportHeight}," +
                        "aheadPx=${preparedLaunchRunwaySpec.requiredAheadPx}"
                )
                return
            }
            val preFirstRunway = if (isNtkWebtoonSource(manga, title)) {
                NTK_PRE_FIRST_WEBTOON_DRAWABLE_RUNWAY_PAGES
            } else {
                NTK_PRE_FIRST_MANHWA_DRAWABLE_RUNWAY_PAGES
            }
            val last = minOf(count - 1, anchor + preFirstRunway - 1)
            var requested = 0
            if (last > anchor) {
                for (index in (anchor + 1)..last) {
                    val page = pageRef(index) ?: continue
                    if (page.transitionTitle != null) continue
                    val image = page.image.orEmpty()
                    if (!isNtkGeneratedImageUrl(image) &&
                        !ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(image) &&
                        !isNtkBoardUploadImageUrl(image) &&
                        !isNaverWebtoonPageImageUrl(image) &&
                        !isNtkProtectedCdnImageUrl(image)
                    ) {
                        continue
                    }
                    requestPage(index, busy = true, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
                    requested++
                }
            }
            Log.d(
                TAG,
                "reader_ntk_initial_warm_pre_first_generated_runway start=$anchor,last=$last," +
                    "runway=$preFirstRunway,requested=$requested"
            )
            return
        }
        if (!firstBitmapLogged.get()) return
        if (isImmediateNtkGeneratedUx() && isActiveGeneratedTouchOrQuiet()) {
            val refs = synchronized(pagesLock) { pages.toList() }
            requestInitialRapidScrollGeneratedWindow(refs, "initial_warm_active")
            Log.d(
                TAG,
                "reader_ntk_initial_warm_defer_active_input page=$anchor,total=$count"
            )
            return
        }
        val quietMs = ntkBackgroundWarmQuietRemainingMs()
        if (quietMs > 0L && !isImmediateNtkGeneratedUx()) {
            Log.d(TAG, "reader_ntk_initial_warm_defer_quiet page=$anchor,delayMs=$quietMs")
            main.postDelayed({
                if (!cancelled.get()) warmNtkInitialPages(startPage)
            }, quietMs.coerceAtLeast(NTK_BACKGROUND_WARM_RECHECK_MS))
            return
        }
        val bootPriorityPages = if (isNtkWebtoonSource(manga, title)) {
            NTK_WEBTOON_INITIAL_BOOT_PRIORITY_PAGES
        } else {
            NTK_INITIAL_BOOT_PRIORITY_PAGES
        }
        val bootUrgentPages = if (isNtkWebtoonSource(manga, title)) {
            NTK_WEBTOON_INITIAL_BOOT_URGENT_PAGES
        } else {
            NTK_INITIAL_BOOT_URGENT_PAGES
        }
        val bootBackgroundPages = if (isNtkWebtoonSource(manga, title)) {
            NTK_WEBTOON_INITIAL_BOOT_BACKGROUND_PAGES
        } else {
            NTK_INITIAL_BOOT_BACKGROUND_PAGES
        }
        for (offset in 1..bootPriorityPages) {
            val ahead = anchor + offset
            if (ahead < count) {
                val generation = if (offset <= NTK_FOREGROUND_STREAM_AHEAD_PAGES) {
                    FOREGROUND_PRIME_WARM_GENERATION
                } else {
                    PRIME_WARM_GENERATION
                }
                requestPage(
                    ahead,
                    busy = offset <= bootUrgentPages,
                    anchor = false,
                    generation = generation
                )
            }
        }
        val backgroundLast = minOf(count - 1, anchor + bootBackgroundPages)
        if (ntkCurrentBackgroundWarmDelayMs() <= 0L
            && anchor + bootPriorityPages + 1 <= backgroundLast
        ) {
            for (index in (anchor + bootPriorityPages + 1)..backgroundLast) {
                requestPage(index, busy = false, anchor = false, generation = PRIME_WARM_GENERATION)
            }
        }
        prefetchNtkInitialNextBytes(anchor, count)
        scheduleNtkFullEpisodeWarmRetry(startPage)
    }

    fun requestAllPagesForBrowserManifest() {
        requestAllUndeliveredNtkPages("browser_manifest_handoff")
    }

    fun requestInitialViewportForBrowserManifest() {
        main.post {
            requestBrowserManifestInitialViewport("browser_manifest_handoff")
        }
    }

    private fun clearVisibleActiveLoadsForBrowserManifest(reason: String) {
        if (!isNtkSource(manga, title) || cancelled.get()) return
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty()) return
        val start = currentStartPage().coerceIn(0, refs.lastIndex)
        val anchor = (currentViewportAnchor.get().takeIf { it >= 0 } ?: start)
            .coerceIn(0, refs.lastIndex)
        val first = max(0, anchor - NTK_BROWSER_MANIFEST_INITIAL_VIEWPORT_BEHIND_PAGES)
        val last = minOf(refs.lastIndex, anchor + NTK_BROWSER_MANIFEST_ACTIVE_VIEWPORT_AHEAD_PAGES)
        var cleared = 0
        val clearedIndexes = ArrayList<Int>()
        for (index in first..last) {
            if (hasDeliveredOrPendingDrawable(index)) continue
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            val image = page.image.orEmpty()
            if (image.isBlank() || isNtkGeneratedImageUrl(image)) continue
            val hadActiveState =
                loading.contains(index) ||
                    urgentLoading.contains(index) ||
                    loadingPages.containsKey(index) ||
                    urgentLoadingPages.containsKey(index) ||
                    inFlightWidths.containsKey(index) ||
                    failedPages.contains(index) ||
                    visibleGeneratedByteHedges.contains(index) ||
                    visibleGeneratedDecodeHedges.contains(index) ||
                    initialGeneratedDirectDecodeInFlight.contains(index) ||
                    initialGeneratedCachedDecodeInFlight.contains(index) ||
                    initialGeneratedAssetDecodeListeners.contains(index)
            if (!hadActiveState) continue
            loading.remove(index)
            urgentLoading.remove(index)
            loadingPages.remove(index)
            urgentLoadingPages.remove(index)
            loadingStartedAtMs.remove(index)
            inFlightWidths.remove(index)
            pendingDeliveryWidths.remove(index)
            failedPages.remove(index)
            visibleGeneratedByteHedges.remove(index)
            visibleGeneratedDecodeHedges.remove(index)
            initialGeneratedDirectDecodeInFlight.remove(index)
            initialGeneratedCachedDecodeInFlight.remove(index)
            initialGeneratedAssetDecodeListeners.remove(index)
            initialInteractiveRunwayByteFetches.remove(index)
            cleared++
            if (clearedIndexes.size < 32) clearedIndexes.add(index)
        }
        if (cleared > 0) {
            Log.d(
                TAG,
                "reader_ntk_browser_manifest_clear_visible_active reason=$reason,start=$start," +
                    "anchor=$anchor,range=$first-$last,cleared=$cleared," +
                    "indexes=${clearedIndexes.joinToString("|")}"
            )
        }
    }

    private fun requestBrowserManifestInitialViewport(reason: String) {
        if (!isNtkSource(manga, title) || cancelled.get()) return
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty()) return
        val start = currentStartPage().coerceIn(0, refs.lastIndex)
        val anchor = (currentViewportAnchor.get().takeIf { it >= 0 } ?: start)
            .coerceIn(0, refs.lastIndex)
        val first = if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L) {
            if (isImmediateNtkGeneratedUx() &&
                refs.lastIndex - start <= NTK_INITIAL_TAIL_ADJACENT_PREAPPEND_PAGES
            ) {
                max(0, start - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)
            } else {
                start
            }
        } else {
            max(0, anchor - NTK_BROWSER_MANIFEST_INITIAL_VIEWPORT_BEHIND_PAGES)
        }
        val beforeFirstDrawable = !firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L
        val ahead = if (beforeFirstDrawable) {
            0
        } else if (viewportBusy.get() || ntkInitialInteractiveSettleRemainingMs() > 0L) {
            NTK_BROWSER_MANIFEST_ACTIVE_VIEWPORT_AHEAD_PAGES
        } else {
            NTK_BROWSER_MANIFEST_INITIAL_VIEWPORT_AHEAD_PAGES
        }
        val last = minOf(refs.lastIndex, anchor + ahead)
        var requested = 0
        val requestedIndexes = ArrayList<Int>()
        for (index in first..last) {
            if (hasDeliveredOrPendingDrawable(index)) continue
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!hasPageSourceReady(index, page) && !isNtkUploadCdnImageUrl(page.image)) {
                forcePrefetchNtkPageSource(
                    index,
                    page,
                    reason,
                    allowDuringInitialInteractive = true
                )
            }
            requestPage(
                index,
                busy = true,
                anchor = index == start || index == anchor,
                generation = FOREGROUND_PRIME_WARM_GENERATION
            )
            requested++
            if (requestedIndexes.size < 32) requestedIndexes.add(index)
        }
        Log.d(
            TAG,
            "reader_ntk_browser_manifest_initial_viewport reason=$reason,start=$start," +
                "anchor=$anchor,range=$first-$last,preFirst=$beforeFirstDrawable," +
                "requested=$requested,total=${refs.size}," +
                "requestedIndexes=${requestedIndexes.joinToString("|")}"
        )
    }

    private fun isTrustedDirectManhwaGeneratedEpisode(target: Manga): Boolean {
        if (!isNtkManhwaEpisodePath(target.ntkEpisodePath)) return false
        val latest = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, 0L)
        if (latest.isEmpty()) return false
        if (!latest.all { isNtkGeneratedImageUrl(it) }) return false
        val directPagePattern = Regex(
            "/manhwa/\\d{1,12}/\\d{1,12}/p\\d{3}\\.(?:jpe?g|png|webp)(?:[?#].*)?$",
            RegexOption.IGNORE_CASE
        )
        return latest.all { image ->
            val hostMatch = image.contains("booktoki", ignoreCase = true) ||
                image.contains("mana.apihost93.com", ignoreCase = true)
            hostMatch && directPagePattern.containsMatchIn(image)
        }
    }

    private fun isTrustedDirectGeneratedEpisode(target: Manga): Boolean {
        return isTrustedDirectWebtoonGeneratedEpisode(target) ||
            isTrustedDirectManhwaGeneratedEpisode(target)
    }

    fun pageReadinessSnapshotForTest(): ReaderSurfaceView.PageReadinessSnapshot {
        val refs = synchronized(pagesLock) { pages.toList() }
        var ready = 0
        var loadingCount = 0
        var errorCount = 0
        var cardCount = 0
        var unresolved = 0
        val loadingIndexes = ArrayList<Int>()
        val unresolvedIndexes = ArrayList<Int>()
        refs.forEachIndexed { index, page ->
            val card = page.transitionTitle != null
            val cached = hasPageSourceReady(index, page) ||
                hasRecentNtkGeneratedSuccessForPage(page)
            val delivered =
                hasDeliveredBitmap(index) ||
                    hasListenerDrawableDelivery(index, page) ||
                    (pendingDeliveryWidths[index] ?: 0) > 0 ||
                    (deliveredDrawableProofWidths[index] ?: 0) > 0
            val failed = failedPages.contains(index)
            val loadingActive =
                loading.contains(index) ||
                    loadingPages.containsKey(index) ||
                    urgentLoading.contains(index) ||
                    urgentLoadingPages.containsKey(index) ||
                    inFlightWidths.containsKey(index)
            when {
                card -> {
                    cardCount++
                    ready++
                }
                delivered || cached -> ready++
                failed -> {
                    errorCount++
                    unresolved++
                    unresolvedIndexes.add(index)
                }
                loadingActive -> {
                    loadingCount++
                    unresolved++
                    loadingIndexes.add(index)
                    unresolvedIndexes.add(index)
                }
                else -> {
                    unresolved++
                    unresolvedIndexes.add(index)
                }
            }
        }
        return ReaderSurfaceView.PageReadinessSnapshot(
            pageCount = refs.size,
            drawablePages = ready,
            loadingPages = loadingCount,
            errorPages = errorCount,
            cardPages = cardCount,
            unresolvedPages = unresolved,
            loadingIndexes = loadingIndexes.joinToString("|"),
            unresolvedIndexes = unresolvedIndexes.joinToString("|")
        )
    }

    private fun scheduleNtkFullEpisodeWarmRetry(startPage: Int) {
        if (!isNtkSource(manga, title)) return
        if (isImmediateNtkGeneratedUx()) return
        val attempt = ntkFullEpisodeWarmRetries.incrementAndGet()
        if (attempt > NTK_FULL_EPISODE_WARM_RETRY_MAX) return
        val delayMs = NTK_FULL_EPISODE_WARM_RETRY_MS * attempt
        main.postDelayed({
            if (cancelled.get()) return@postDelayed
            requestAllUndeliveredNtkPages("retry_$attempt")
            warmNtkInitialPages(startPage)
        }, delayMs)
    }

    private fun requestAllUndeliveredNtkPages(reason: String) {
        requestAllUndeliveredNtkPages(reason, 0)
    }

    private fun requestAllUndeliveredNtkPages(reason: String, startOffset: Int) {
        if (strictExactColdRolling) return
        if (!isNtkSource(manga, title)) return
        if (shouldPreferInFlightNumericManhwaApiManifest()) {
            if (numericManhwaApiRaceRetryPosted.compareAndSet(false, true)) {
                main.postDelayed({
                    numericManhwaApiRaceRetryPosted.set(false)
                    if (!cancelled.get()) requestAllUndeliveredNtkPages(reason, startOffset)
                }, 120L)
            }
            Log.d(TAG, "reader_ntk_generated_full_defer_api_race reason=$reason,offset=$startOffset")
            return
        }
        val generatedFullPublishWarm =
            reason.startsWith("generated_full_publish") ||
                reason.startsWith("publish_generated_full_publish")
        val generatedFullDecodeWarm = reason.startsWith("generated_full_decode") || generatedFullPublishWarm
        val currentEpisodeCompletionWarm = reason.startsWith("current_full_before_next")
        val currentEpisodeReadyWarm = reason.startsWith("current_ready_before_next")
        val currentEpisodeExpansionWarm =
            currentEpisodeCompletionWarm || currentEpisodeReadyWarm || generatedFullPublishWarm
        val currentEpisodeForegroundBoundaryWarm = currentEpisodeReadyWarm
        val browserManifestDirectFullWarm = reason == "browser_manifest_direct_full"
        val earlyInitialFullWarm = reason == "early_urls_initial_full"
        val immediatePublishedFullSurfaceWarm = reason == "immediate_generated_full_surface"
        val verifiedRefreshFullWarm = reason == "verified_refresh_full"
        val immediateAllSurfaceWarm =
            earlyInitialFullWarm || browserManifestDirectFullWarm || immediatePublishedFullSurfaceWarm
        if (isImmediateNtkGeneratedUx() && immediateAllSurfaceWarm) {
            requestGeneratedViewportProofAndRunwayBytes(reason)
            startImmediateGeneratedFullSourcePrefetch(reason)
            scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(
                NTK_GENERATED_FULL_BYTE_PREFETCH_BATCH_DELAY_MS
            )
            Log.d(
                TAG,
                "reader_ntk_early_initial_full_surface_begin_immediate " +
                    "reason=$reason,offset=$startOffset,anchor=${currentViewportAnchor.get()},start=${currentStartPage()}"
            )
        }
        if (browserManifestDirectFullWarm && isStructurePublishPending()) {
            Log.d(
                TAG,
                "reader_ntk_browser_manifest_direct_full_defer_structure offset=$startOffset"
            )
            main.postDelayed({
                if (!cancelled.get()) requestAllUndeliveredNtkPages(reason, startOffset)
            }, NTK_BROWSER_MANIFEST_STRUCTURE_RETRY_MS)
            return
        }
        if (
            isImmediateNtkGeneratedUx() &&
            (generatedFullDecodeWarm || currentEpisodeCompletionWarm || currentEpisodeReadyWarm) &&
            synchronized(pagesLock) { pages.isNotEmpty() && isGeneratedOnlyNtkRefs(pages) }
        ) {
            requestGeneratedViewportProofAndRunwayBytes(reason)
            startImmediateGeneratedFullSourcePrefetch(reason)
            scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(
                NTK_GENERATED_FULL_BYTE_PREFETCH_BATCH_DELAY_MS
            )
            return
        }
        val bulkDeferMs = generatedFullEpisodeBulkDeferMs(reason)
        if (bulkDeferMs > 0L) {
            Log.d(
                TAG,
                "reader_ntk_full_episode_bulk_defer reason=$reason,delayMs=$bulkDeferMs,offset=$startOffset"
            )
            scheduleGeneratedFullEpisodeBulkRetry(reason, startOffset, bulkDeferMs)
            return
        }
        val rawIndexes = synchronized(pagesLock) { pages.indices.toList() }
        var requested = 0
        var staleCleared = 0
        var boundaryDeliveryReset = 0
        val requestedIndexes = ArrayList<Int>()
        val staleIndexes = ArrayList<Int>()
        val boundaryResetIndexes = ArrayList<Int>()
        val now = SystemClock.elapsedRealtime()
        val strictCoverageWarm =
                browserManifestDirectFullWarm ||
                earlyInitialFullWarm ||
                immediatePublishedFullSurfaceWarm ||
                verifiedRefreshFullWarm ||
                (generatedFullDecodeWarm && !isImmediateNtkGeneratedUx())
        val interactiveFullSourceWarm = reason.startsWith("interactive_full_source")
        val immediateGeneratedFullSurfaceWarm =
            isImmediateNtkGeneratedUx() &&
                reason.startsWith("generated_full_decode")
        val activeImmediateGeneratedFullWarm =
            immediateGeneratedFullSurfaceWarm && isActiveGeneratedTouchOrQuiet()
        val immediateAppendFullWarm =
            false
        val anchor = if (interactiveFullSourceWarm || currentEpisodeExpansionWarm) {
            currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        } else {
            currentStartPage()
        }.coerceAtLeast(0)
        val indexes = if (browserManifestDirectFullWarm && rawIndexes.isNotEmpty()) {
            val tailStart = max(0, rawIndexes.last() - NTK_BROWSER_MANIFEST_TAIL_PRIORITY_PAGES + 1)
            rawIndexes.filter { it >= tailStart } + rawIndexes.filter { it < tailStart }
        } else if (immediateAllSurfaceWarm && rawIndexes.isNotEmpty()) {
            val split = anchor.coerceIn(rawIndexes.first(), rawIndexes.last())
            rawIndexes.filter { it >= split } + rawIndexes.filter { it < split }
        } else if ((generatedFullDecodeWarm || interactiveFullSourceWarm || currentEpisodeExpansionWarm) && rawIndexes.isNotEmpty()) {
            val split = anchor.coerceIn(rawIndexes.first(), rawIndexes.last())
            rawIndexes.filter { it >= split } + rawIndexes.filter { it < split }
        } else {
            rawIndexes
        }
        val safeStartOffset = startOffset.coerceIn(0, indexes.size)
        val generatedFullSourceOnlyWarm = strictCoverageWarm &&
            !immediateAppendFullWarm &&
            indexes.size > NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES &&
            synchronized(pagesLock) { pages.all { it.transitionTitle != null || isNtkGeneratedDescriptorOrImagePage(it) } }
        val avoidLargeUntrustedGeneratedFullSurfaceWarm =
            shouldAvoidLargeUntrustedGeneratedFullSurfaceWarm(reason, indexes)
        val forceFullSurfaceWarm = strictCoverageWarm &&
            !activeImmediateGeneratedFullWarm &&
            (immediateAllSurfaceWarm || indexes.size <= NTK_FULL_SURFACE_WARM_MAX_PAGES) &&
            !avoidLargeUntrustedGeneratedFullSurfaceWarm
        if (strictCoverageWarm) {
            deliveryResumeAtMs.set(0L)
            flushInitialHeldDeliveries("promote")
        }
        val holdGeneratedTailForInitialContinuous =
            !immediateGeneratedFullSurfaceWarm &&
                !browserManifestDirectFullWarm &&
                !earlyInitialFullWarm &&
                shouldHoldNtkGeneratedTailForInitialContinuous()
        val staleLoadingMs = if (strictCoverageWarm) {
            NTK_FULL_EPISODE_STRICT_STALE_LOADING_MS
        } else {
            NTK_FULL_EPISODE_STALE_LOADING_MS
        }
        fun hasActiveRequestState(index: Int): Boolean {
            return loading.contains(index) ||
                loadingPages.containsKey(index) ||
                urgentLoading.contains(index) ||
                urgentLoadingPages.containsKey(index) ||
                inFlightWidths.containsKey(index) ||
                pendingDeliveryWidths.containsKey(index)
        }
        var activeWarmRequests = indexes.count { index ->
            !hasDeliveredBitmap(index) && hasActiveRequestState(index)
        }
        val knownFullGeneratedInteractiveWarm =
            interactiveFullSourceWarm && isKnownFullGeneratedEpisodeInstalled()
        val interactiveAheadPages = if (knownFullGeneratedInteractiveWarm) {
            NTK_INTERACTIVE_FULL_SOURCE_KNOWN_AHEAD
        } else {
            NTK_INTERACTIVE_FULL_SOURCE_AHEAD
        }
        val interactiveActiveRequestLimit = if (knownFullGeneratedInteractiveWarm) {
            NTK_INTERACTIVE_FULL_SOURCE_KNOWN_ACTIVE_REQUEST_LIMIT
        } else {
            NTK_INTERACTIVE_FULL_SOURCE_ACTIVE_REQUEST_LIMIT
        }
        var examined = 0
        var nextOffset = -1
        for (position in safeStartOffset until indexes.size) {
            if (
                strictCoverageWarm &&
                !forceFullSurfaceWarm &&
                examined >= NTK_FULL_EPISODE_WARM_MAIN_BATCH_PAGES
            ) {
                nextOffset = position
                break
            }
            examined++
            val index = indexes[position]
            if (hasDeliveredBitmap(index)) continue
            if (interactiveFullSourceWarm) {
                val interactiveFirst = max(0, anchor - NTK_INTERACTIVE_FULL_SOURCE_BEHIND)
                val interactiveLast = anchor + interactiveAheadPages
                if (index !in interactiveFirst..interactiveLast) {
                    continue
                }
                if (
                    activeWarmRequests >= interactiveActiveRequestLimit &&
                    index !in max(0, anchor - NTK_FULL_EPISODE_STRICT_VISIBLE_RADIUS)..(anchor + NTK_FULL_EPISODE_STRICT_VISIBLE_RADIUS)
                ) {
                    continue
                }
            }
            if (holdGeneratedTailForInitialContinuous &&
                index > anchor + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
            ) {
                continue
            }
            val page = pageRef(index)
            if (strictCoverageWarm && page != null && trimBlankNtkGeneratedTail(index, page)) {
                continue
            }
            val visibleWarmRange =
                max(0, anchor - NTK_FULL_EPISODE_STRICT_VISIBLE_RADIUS)..(anchor + NTK_FULL_EPISODE_STRICT_VISIBLE_RADIUS)
            val initialRunwayLast = anchor + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
            if (
                avoidLargeUntrustedGeneratedFullSurfaceWarm &&
                index > initialRunwayLast &&
                index !in visibleWarmRange
            ) {
                continue
            }
            var hasActiveLoadState = hasActiveRequestState(index)
            val loadingStartedAt = loadingStartedAtMs[index]
            val loadingAge = loadingStartedAt?.let { now - it } ?: 0L
            if (loadingAge >= staleLoadingMs || failedPages.contains(index)) {
                loading.remove(index)
                loadingPages.remove(index)
                loadingStartedAtMs.remove(index)
                urgentLoading.remove(index)
                urgentLoadingPages.remove(index)
                inFlightWidths.remove(index)
                pendingDeliveryWidths.remove(index)
                failedPages.remove(index)
                hasActiveLoadState = false
                staleCleared++
                if (staleIndexes.size < 32) staleIndexes.add(index)
            }
            if (currentEpisodeForegroundBoundaryWarm) {
                val boundaryFirst = max(0, anchor - NTK_INTERACTIVE_PROOF_BEHIND_PAGES)
                val boundaryLast = anchor + NTK_GENERATED_FULL_PUBLISH_PROOF_AHEAD_PAGES
                if (index !in boundaryFirst..boundaryLast) {
                    continue
                }
                if (page != null && !hasListenerDrawableDelivery(index, page)) {
                    loading.remove(index)
                    loadingPages.remove(index)
                    loadingStartedAtMs.remove(index)
                    urgentLoading.remove(index)
                    urgentLoadingPages.remove(index)
                    inFlightWidths.remove(index)
                    pendingDeliveryWidths.remove(index)
                    failedPages.remove(index)
                    if (hasActiveLoadState) {
                        boundaryDeliveryReset++
                        if (boundaryResetIndexes.size < 32) boundaryResetIndexes.add(index)
                    }
                    hasActiveLoadState = false
                }
            }
            if (!interactiveFullSourceWarm && !strictCoverageWarm && !forceFullSurfaceWarm && !currentEpisodeExpansionWarm &&
                index >= NTK_PRE_ANCHOR_VERIFIED_GENERATED_AHEAD
            ) {
                continue
            }
            if (
                generatedFullSourceOnlyWarm &&
                !forceFullSurfaceWarm &&
                !immediateAppendFullWarm &&
                index > anchor + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES &&
                index !in max(0, anchor - NTK_FULL_EPISODE_STRICT_VISIBLE_RADIUS)..(anchor + NTK_FULL_EPISODE_STRICT_VISIBLE_RADIUS)
            ) {
                continue
            }
            if (
                strictCoverageWarm &&
                !forceFullSurfaceWarm &&
                !immediateAppendFullWarm &&
                !hasActiveLoadState &&
                !hasDeliveredBitmap(index) &&
                activeWarmRequests >= NTK_FULL_EPISODE_STRICT_ACTIVE_REQUEST_LIMIT &&
                index !in visibleWarmRange
            ) {
                continue
            }
            if (page != null && !hasPageSourceReady(index, page)) {
                forcePrefetchNtkPageSource(
                    index,
                    page,
                    reason,
                    allowDuringInitialInteractive = interactiveFullSourceWarm ||
                        (strictCoverageWarm && isImmediateNtkGeneratedUx())
                )
                if (interactiveFullSourceWarm && !hasActiveLoadState && !hasDeliveredBitmap(index)) {
                    activeWarmRequests++
                }
            }
            if (interactiveFullSourceWarm) {
                requested++
                if (requestedIndexes.size < 32) requestedIndexes.add(index)
                continue
            }
            if (strictCoverageWarm && forceFullSurfaceWarm && isImmediateNtkGeneratedUx() && page != null) {
                immediateFullSurfacePrimeKeys.add(immediateFullSurfacePrimeKey(page))
            }
            requestPage(
                index,
                busy = strictCoverageWarm || currentEpisodeForegroundBoundaryWarm,
                anchor = false,
                generation = if (strictCoverageWarm || currentEpisodeForegroundBoundaryWarm) {
                    FOREGROUND_PRIME_WARM_GENERATION
                } else {
                    PRIME_WARM_GENERATION
                }
            )
            if ((strictCoverageWarm || currentEpisodeForegroundBoundaryWarm) && !hasActiveLoadState && !hasDeliveredBitmap(index)) {
                activeWarmRequests++
            }
            requested++
            if (requestedIndexes.size < 32) requestedIndexes.add(index)
        }
        Log.d(
            TAG,
            "reader_ntk_full_episode_warm reason=$reason,requested=$requested," +
                "staleCleared=$staleCleared,boundaryReset=$boundaryDeliveryReset,total=${indexes.size}," +
                "offset=$safeStartOffset,examined=$examined,nextOffset=$nextOffset," +
                "requestedIndexes=${requestedIndexes.joinToString("|")}," +
                "staleIndexes=${staleIndexes.joinToString("|")}," +
                "boundaryResetIndexes=${boundaryResetIndexes.joinToString("|")}"
        )
        if (nextOffset >= 0) {
            main.postDelayed({
                if (!cancelled.get()) requestAllUndeliveredNtkPages(reason, nextOffset)
            }, NTK_FULL_EPISODE_WARM_MAIN_BATCH_DELAY_MS)
        }
    }

    private fun scheduleGeneratedFullEpisodeBulkRetry(reason: String, startOffset: Int, delayMs: Long) {
        if (!generatedFullEpisodeBulkRetryScheduled.compareAndSet(false, true)) return
        main.postDelayed({
            generatedFullEpisodeBulkRetryScheduled.set(false)
            if (!cancelled.get()) requestAllUndeliveredNtkPages(reason, startOffset)
        }, delayMs.coerceAtLeast(500L))
    }

    private fun shouldAvoidLargeUntrustedGeneratedFullSurfaceWarm(reason: String, indexes: List<Int>): Boolean {
        if (!reason.startsWith("generated_full_decode")) return false
        if (reason == "generated_full_decode_initial" || reason == "generated_full_decode_publish") return false
        if (!isNtkWebtoonEpisodePath(manga.ntkEpisodePath)) return false
        if (manga.ntkImageCount <= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD &&
            indexes.size <= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD
        ) return false
        if (isTrustedDirectWebtoonGeneratedEpisode(manga)) return false
        if (ReaderImageCache.knownNtkGeneratedFirstNotFoundPage(manga.ntkEpisodePath) > 1) return true
        return synchronized(pagesLock) {
            pages.isNotEmpty() &&
                pages.all { it.transitionTitle != null || isNtkGeneratedImageUrl(it.image.orEmpty()) }
        }
    }

    private fun generatedFullEpisodeBulkDeferMs(reason: String): Long {
        val generatedFullDecode = reason.startsWith("generated_full_decode")
        val appendedEpisodeWarm = reason.startsWith("append_full")
        val browserManifestHandoff = reason == "browser_manifest_handoff"
        val interactiveFullSource = reason.startsWith("interactive_full_source")
        if (!generatedFullDecode && !appendedEpisodeWarm && !browserManifestHandoff && !interactiveFullSource) return 0L
        if (!isImmediateNtkGeneratedUx()) return 0L
        if (interactiveFullSource) return 0L
        if (appendedEpisodeWarm) return 0L
        if (reason == "generated_full_decode_initial" || reason == "generated_full_decode_publish") return 0L
        val quietMs = maxOf(
            ntkBackgroundWarmQuietRemainingMs(),
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS),
            ntkInitialInteractiveSettleRemainingMs()
        )
        if (shouldHoldNtkGeneratedTailForInitialContinuous()) {
            return maxOf(quietMs, NTK_GENERATED_FULL_BULK_HOLD_RECHECK_MS)
        }
        return quietMs
    }

    private fun requestGeneratedPublishWarmPages(reason: String) {
        if (!isNtkSource(manga, title)) return
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty()) return
        if (
            isActiveInitialGeneratedInput() &&
            isGeneratedOnlyNtkRefs(refs) &&
            !isImmediateNtkGeneratedUx()
        ) {
            requestActiveGeneratedViewportOnly(refs, reason)
            return
        }
        if (!isGeneratedOnlyNtkRefs(refs) || refs.size <= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) {
            requestAllUndeliveredNtkPages(reason)
            return
        }
        if (isImmediateNtkGeneratedUx() && isGeneratedOnlyNtkRefs(refs)) {
            requestGeneratedViewportProofAndRunwayBytes(reason)
            startImmediateGeneratedFullSourcePrefetch("publish_$reason")
            startInteractiveFullSourcePrefetch("publish_$reason")
            scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(NTK_GENERATED_FULL_BYTE_PREFETCH_BATCH_DELAY_MS)
            Log.d(
                TAG,
                "reader_ntk_generated_publish_begin_full_surface reason=$reason,total=${refs.size}"
            )
            requestAllUndeliveredNtkPages("immediate_generated_full_surface")
            return
        }
        if (refs.size <= NTK_GENERATED_PUBLISH_FULL_WARM_PAGE_LIMIT &&
            !shouldAvoidLargeUntrustedGeneratedFullSurfaceWarm("generated_full_decode_publish", refs.indices.toList())
        ) {
            requestAllUndeliveredNtkPages("generated_full_decode_publish")
            return
        }
        val anchor = currentStartPage().coerceIn(0, refs.lastIndex)
        val first = max(0, anchor - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)
        val last = minOf(refs.lastIndex, anchor + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1)
        var requested = 0
        val requestedIndexes = ArrayList<Int>()
        for (index in first..last) {
            if (hasDeliveredBitmap(index)) continue
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!hasPageSourceReady(index, page)) {
                forcePrefetchNtkPageSource(index, page, reason)
            }
            requestPage(index, busy = index != anchor, anchor = index == anchor, generation = PRIME_WARM_GENERATION)
            requested++
            if (requestedIndexes.size < 32) requestedIndexes.add(index)
        }
        Log.d(
            TAG,
            "reader_ntk_generated_publish_window_warm reason=$reason,requested=$requested," +
                "range=$first-$last,total=${refs.size},requestedIndexes=${requestedIndexes.joinToString("|")}"
        )
    }

    private fun requestActiveGeneratedViewportOnly(refs: List<PageRef>, reason: String) {
        if (refs.isEmpty()) return
        val anchor = (currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage())
            .coerceIn(0, refs.lastIndex)
        val last = minOf(refs.lastIndex, anchor + activeGeneratedProofAheadPages())
        var requested = 0
        val requestedIndexes = ArrayList<Int>()
        for (index in anchor..last) {
            if (hasDeliveredOrPendingDrawable(index)) continue
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!isNtkGeneratedDescriptorOrImagePage(page)) continue
            if (!hasPageSourceReady(index, page)) continue
            if (scheduleVisibleGeneratedCachedDecode(
                    index,
                    page,
                    "${reason}_active_cached_proof",
                    SystemClock.elapsedRealtime(),
                    forceRequeue = true,
                    proofDrawable = true
                )
            ) {
                requested++
                if (requestedIndexes.size < 32) requestedIndexes.add(index)
            }
        }
        Log.d(
            TAG,
            "reader_ntk_generated_publish_active_viewport_only reason=$reason," +
                "anchor=$anchor,last=$last,requested=$requested,total=${refs.size}," +
                "requestedIndexes=${requestedIndexes.joinToString("|")}"
        )
    }

    private fun requestGeneratedViewportProofAndRunwayBytes(reason: String) {
        if (!isImmediateNtkGeneratedUx()) return
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty() || !isGeneratedOnlyNtkRefs(refs)) return
        val start = currentStartPage().coerceIn(0, refs.lastIndex)
        val anchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?.coerceIn(0, refs.lastIndex)
            ?: start
        val forceRunwayProof = shouldForceImmediateGeneratedRunwayProof(reason)
        val proofFirst = max(0, anchor - NTK_INTERACTIVE_PROOF_BEHIND_PAGES)
        val proofLastUncapped = minOf(
            refs.lastIndex,
            anchor + generatedViewportProofAheadPages(reason, forceRunwayProof)
        )
        val rollingRunwayLast = minOf(
            refs.lastIndex,
            proofLastUncapped + activeRollingRunwayByteAheadPages(anchor)
        )
        val runwayLastUncapped = if (reason == "active_scroll_window" || viewportBusy.get()) {
            // A live gesture only needs the decoded proof window plus a small compressed-byte
            // lead. Expanding back to the 24-page launch window here starts far-tail fetches at
            // the exact moment InputDispatcher needs the app CPU and also drives avoidable GC.
            rollingRunwayLast
        } else {
            minOf(
                refs.lastIndex,
                maxOf(initialInteractiveRunwayLastIndex(refs.size), rollingRunwayLast)
            )
        }
        val knownFullInitialRunwayCap =
            isKnownFullGeneratedEpisodeInstalled() &&
                !forceRunwayProof &&
                (
                    reason == "early_urls_initial_full" ||
                        (
                        reason == "generated_full_decode_initial" ||
                        reason == "generated_full_decode_publish" ||
                        reason == "generated_full_publish" ||
                        reason.startsWith("publish_", ignoreCase = true)
                        ) &&
                        (
                            !firstBitmapLogged.get() ||
                                ntkInitialInteractiveSettleRemainingMs() > 0L ||
                                readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L
                            )
                    )
        val initialRunwayCapLast = if (reason == "early_urls_initial_full") {
            anchor
        } else {
            minOf(
                refs.lastIndex,
                anchor + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
            )
        }
        val proofLast = if (knownFullInitialRunwayCap) {
            minOf(proofLastUncapped, initialRunwayCapLast)
        } else {
            proofLastUncapped
        }
        val runwayLast = if (knownFullInitialRunwayCap) {
            minOf(runwayLastUncapped, initialRunwayCapLast)
        } else {
            runwayLastUncapped
        }
        val effectiveRunwayLast = if (forceRunwayProof) {
            minOf(refs.lastIndex, anchor + NTK_GENERATED_FULL_PUBLISH_PROOF_AHEAD_PAGES)
        } else {
            runwayLast
        }
        val proofRequestLimit = generatedViewportProofRequestLimit(reason, forceRunwayProof)
        var deferredProof = false
        var proofRequested = 0
        var bytesRequested = 0
        val requestedIndexes = ArrayList<Int>()
        val now = SystemClock.elapsedRealtime()
        for (index in proofFirst..proofLast) {
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!isNtkGeneratedDescriptorOrImagePage(page)) continue
            if (hasDeliveredOrPendingDrawable(index)) continue
            if (proofRequested >= proofRequestLimit) {
                deferredProof = true
                if (!hasPageSourceReady(index, page) &&
                    startInitialInteractiveRunwayByteFetch(index, page, "${reason}_throttled_source_bytes")
                ) {
                    bytesRequested++
                    if (requestedIndexes.size < 32) requestedIndexes.add(index)
                }
                continue
            }
            val scheduled = scheduleVisibleGeneratedCachedDecode(
                index,
                page,
                "${reason}_viewport_proof",
                now,
                forceRequeue = true,
                proofDrawable = true
            )
            if (scheduled) {
                proofRequested++
            } else if (startInitialInteractiveRunwayByteFetch(index, page, "${reason}_proof_bytes")) {
                bytesRequested++
            }
            if (requestedIndexes.size < 32) requestedIndexes.add(index)
        }
        val allowRunwayBytes = forceRunwayProof || !shouldSkipImmediateGeneratedRunwayBytes(reason)
        if (allowRunwayBytes && effectiveRunwayLast > proofLast) {
            for (index in (proofLast + 1)..effectiveRunwayLast) {
                val page = refs.getOrNull(index) ?: continue
                if (page.transitionTitle != null) continue
                if (!isNtkGeneratedDescriptorOrImagePage(page)) continue
                if (hasDeliveredOrPendingDrawable(index)) continue
                if (hasPageSourceReady(index, page)) {
                    if (forceRunwayProof &&
                        proofRequested < proofRequestLimit &&
                        scheduleVisibleGeneratedCachedDecode(
                            index,
                            page,
                            "${reason}_runway_proof_ready",
                            now,
                            forceRequeue = true,
                            proofDrawable = true,
                            allowOutsideProofWindow = true
                        )
                    ) {
                        proofRequested++
                        if (requestedIndexes.size < 32) requestedIndexes.add(index)
                    } else if (forceRunwayProof) {
                        deferredProof = true
                    }
                    continue
                }
                val allowProofForRunway = forceRunwayProof && proofRequested < proofRequestLimit
                if (forceRunwayProof && !allowProofForRunway) {
                    deferredProof = true
                }
                if (startInitialInteractiveRunwayByteFetch(
                        index,
                        page,
                        if (allowProofForRunway) "${reason}_runway_bytes" else "${reason}_throttled_source_bytes",
                        forceProofDrawable = allowProofForRunway,
                        allowOutsideProofWindow = allowProofForRunway
                    )
                ) {
                    bytesRequested++
                    if (requestedIndexes.size < 32) requestedIndexes.add(index)
                }
            }
        }
        if (deferredProof) {
            scheduleGeneratedViewportProofAndRunwayRetry(reason)
        }
        if ((proofRequested > 0 || bytesRequested > 0 || forceRunwayProof || deferredProof) &&
            shouldLogRateLimitedDiagnostic("generated_viewport_proof_runway")
        ) {
            Log.d(
                TAG,
                "reader_ntk_generated_viewport_proof_runway reason=$reason,anchor=$anchor," +
                    "proof=$proofFirst-$proofLast,runwayLast=$effectiveRunwayLast,baseRunwayLast=$runwayLast," +
                    "proofRequested=$proofRequested,bytesRequested=$bytesRequested,allowRunway=$allowRunwayBytes," +
                    "forceRunwayProof=$forceRunwayProof," +
                    "requestedIndexes=${requestedIndexes.joinToString("|")}"
            )
        }
    }

    private fun shouldForceImmediateGeneratedRunwayProof(reason: String): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        return reason == "generated_full_publish" ||
            reason.startsWith("current_full_before_next", ignoreCase = true) ||
            reason.startsWith("current_ready_before_next", ignoreCase = true) ||
            reason.startsWith("publish_generated_full_publish", ignoreCase = true)
    }

    private fun activeGeneratedProofAheadPages(): Int {
        if (!isImmediateNtkGeneratedUx()) return interactiveProofAheadPages()
        if (!isActiveGeneratedTouchOrQuiet() && !viewportBusy.get()) return interactiveProofAheadPages()
        if (isActiveGeneratedNearEpisodeTail()) return NTK_ACTIVE_TAIL_PROOF_AHEAD_PAGES
        return NTK_ACTIVE_GENERATED_PROOF_AHEAD_PAGES
    }

    private fun generatedViewportProofAheadPages(reason: String, forceRunwayProof: Boolean): Int {
        if (!isImmediateNtkGeneratedUx()) return interactiveProofAheadPages()
        if (!isActiveGeneratedTouchOrQuiet() && !viewportBusy.get()) return interactiveProofAheadPages()
        if (isActiveGeneratedNearEpisodeTail()) return NTK_ACTIVE_TAIL_PROOF_AHEAD_PAGES
        return if (forceRunwayProof) {
            NTK_ACTIVE_GENERATED_FORCE_PROOF_AHEAD_PAGES
        } else {
            NTK_ACTIVE_GENERATED_PROOF_AHEAD_PAGES
        }
    }

    private fun generatedViewportProofRequestLimit(reason: String, forceRunwayProof: Boolean): Int {
        if (!isImmediateNtkGeneratedUx()) return Int.MAX_VALUE
        if (!isActiveGeneratedTouchOrQuiet() && !viewportBusy.get()) return Int.MAX_VALUE
        if (isActiveGeneratedNearEpisodeTail()) return NTK_ACTIVE_TAIL_PROOF_REQUEST_LIMIT
        return if (forceRunwayProof) {
            NTK_ACTIVE_GENERATED_FORCE_PROOF_REQUEST_LIMIT
        } else {
            NTK_ACTIVE_GENERATED_PROOF_REQUEST_LIMIT
        }
    }

    private fun isActiveGeneratedNearEpisodeTail(): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return false
        val anchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?.coerceIn(0, count - 1)
            ?: currentStartPage().coerceIn(0, count - 1)
        return count - 1 - anchor <= NTK_ACTIVE_TAIL_PROOF_TRIGGER_REMAINING_PAGES
    }

    private fun scheduleGeneratedViewportProofAndRunwayRetry(reason: String) {
        if (!generatedViewportProofRunwayReposts.add(reason)) return
        main.postDelayed({
            if (cancelled.get()) {
                generatedViewportProofRunwayReposts.remove(reason)
                return@postDelayed
            }
            try {
                control.execute {
                    generatedViewportProofRunwayReposts.remove(reason)
                    if (!cancelled.get()) requestGeneratedViewportProofAndRunwayBytes(reason)
                }
            } catch (_: RejectedExecutionException) {
                generatedViewportProofRunwayReposts.remove(reason)
            }
        }, NTK_ACTIVE_GENERATED_PROOF_REPOST_MS)
    }

    private fun shouldSkipImmediateGeneratedRunwayBytes(reason: String): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (reason == "generated_limited_warm_active") return false
        if (reason == "active_scroll_window") return false
        if (viewportBusy.get()) return true
        if (readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L) return true
        return reason == "generated_full_decode_initial" ||
            reason == "generated_full_decode_publish" ||
            reason == "generated_full_publish" ||
            reason.startsWith("publish_", ignoreCase = true)
    }

    private fun forcePrefetchNtkPageSource(
        index: Int,
        page: PageRef,
        reason: String,
        allowDuringInitialInteractive: Boolean = false
    ) {
        if (!isNtkSource(page.manga, title)) return
        if (page.transitionTitle != null || page.image.isNullOrEmpty()) return
        if (!allowDuringInitialInteractive &&
            shouldDeferInitialInteractiveGeneratedBackground(index, page, PRIME_WARM_GENERATION)
        ) {
            return
        }
        val generatedSourceOnlyWarm =
            isImmediateNtkGeneratedUx() &&
                (
                    reason.startsWith("generated_full_decode") ||
                        reason.startsWith("immediate_full_source") ||
                        reason.startsWith("interactive_full_source") ||
                        reason.startsWith("current_full_before_next") ||
                        reason.contains("runway", ignoreCase = true)
                )
        val immediateFullSurfaceDecode =
            isImmediateNtkGeneratedUx() &&
                reason.startsWith("generated_full_decode") &&
                !generatedSourceOnlyWarm &&
                !isActiveGeneratedTouchOrQuiet()
        if (hasPageSourceReady(index, page)) {
            if (reason.startsWith("interactive_full_source")) {
                decodeInteractiveGeneratedProofAfterSource(index, page, reason, SystemClock.elapsedRealtime())
            }
            if (!generatedSourceOnlyWarm && immediateFullSurfaceDecode && shouldDecodeAfterNtkSourcePrefetch(index, reason)) {
                val now = SystemClock.elapsedRealtime()
                decodeInitialContinuousCachedAfterSource(index, page, reason, now)
                decodeFullSurfaceCachedAfterSource(index, page, reason, now)
            }
            return
        }
        if (!fullEpisodeSourcePrefetching.add(index)) return
        try {
            sourcePrefetchNetwork.execute {
                val startedAt = SystemClock.elapsedRealtime()
                try {
                    if (!cancelled.get() && pageRef(index) == page && !hasPageSourceReady(index, page)) {
                        prefetchImageFile(
                            index,
                            page,
                            foreground = false,
                            visiblePriority = false
                        )
                        logNtkPagePerf(
                            index,
                            "full_episode_source_prefetch_done",
                            "reason=$reason,ms=${SystemClock.elapsedRealtime() - startedAt}"
                        )
                        if (reason.startsWith("interactive_full_source")) {
                            decodeInteractiveGeneratedProofAfterSource(index, page, reason, startedAt)
                            return@execute
                        }
                        if (generatedSourceOnlyWarm) {
                            logNtkPagePerf(index, "full_episode_source_prefetch_source_only", "reason=$reason")
                            return@execute
                        }
                        if (
                            !immediateFullSurfaceDecode &&
                            isImmediateNtkGeneratedUx() &&
                            (viewportBusy.get() ||
                                ntkInitialInteractiveSettleRemainingMs() > 0L ||
                                readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L)
                        ) {
                            logNtkPagePerf(index, "full_episode_source_prefetch_decode_defer_active", "reason=$reason")
                            return@execute
                        }
                        if (shouldDecodeAfterNtkSourcePrefetch(index, reason)) {
                            decodeInitialContinuousCachedAfterSource(index, page, reason, startedAt)
                            decodeFullSurfaceCachedAfterSource(index, page, reason, startedAt)
                        }
                    }
                } catch (e: Exception) {
                    if (isExpectedCancellation(e)) {
                        logNtkPagePerf(
                            index,
                            "full_episode_source_prefetch_cancelled",
                            "reason=$reason,ms=${SystemClock.elapsedRealtime() - startedAt}"
                        )
                    } else {
                        logNtkPagePerf(
                            index,
                            "full_episode_source_prefetch_error",
                            "reason=$reason,ms=${SystemClock.elapsedRealtime() - startedAt}," +
                                "source=${page.sourceIndex},path=${page.manga.ntkEpisodePath}," +
                                "image=${page.image},error=${e.javaClass.simpleName}:${e.message}"
                        )
                        recordIfUnexpected(e)
                        if (!cancelled.get() && pageRef(index) == page) {
                            postPageError(index, page, e)
                        }
                    }
                } finally {
                    fullEpisodeSourcePrefetching.remove(index)
                }
            }
        } catch (_: RejectedExecutionException) {
            fullEpisodeSourcePrefetching.remove(index)
        }
    }

    /**
     * Keeps compressed bytes beyond the canonical launch runway moving without putting them on
     * the eight-lane visible executor. A later real viewport request remains free to use the
     * urgent path; this lane neither waits for input nor gates scrolling.
     */
    private fun scheduleProgressiveFarTailSource(
        index: Int,
        page: PageRef,
        reason: String
    ): Boolean {
        if (cancelled.get() || pageRef(index) != page || hasPageSourceReady(index, page)) return false
        if (!fullEpisodeSourcePrefetching.add(index)) return false
        return try {
            progressiveFarTailNetwork.execute {
                val startedAt = SystemClock.elapsedRealtime()
                try {
                    if (!cancelled.get() && pageRef(index) == page && !hasPageSourceReady(index, page)) {
                        prefetchImageFile(index, page, foreground = false, visiblePriority = false)
                        logNtkPagePerf(
                            index,
                            "progressive_far_tail_source_ready",
                            "reason=$reason,ms=${SystemClock.elapsedRealtime() - startedAt}"
                        )
                    }
                } catch (e: Exception) {
                    if (!isExpectedCancellation(e)) {
                        logNtkPagePerf(
                            index,
                            "progressive_far_tail_source_error",
                            "reason=$reason,error=${e.javaClass.simpleName}"
                        )
                    }
                } finally {
                    fullEpisodeSourcePrefetching.remove(index)
                }
            }
            true
        } catch (_: RejectedExecutionException) {
            fullEpisodeSourcePrefetching.remove(index)
            false
        }
    }

    private fun warmNtkGeneratedInitialPagesLimited(startPage: Int, loadStartedAt: Long) {
        if (!isNtkSource(manga, title)) return
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return
        val anchor = startPage.coerceIn(0, count - 1)
        if (!firstBitmapLogged.get()) {
            if (!isNtkManhwaEpisodePath(manga.ntkEpisodePath)) return
            if (!hasDeliveredOrPendingDrawable(anchor)) return
        } else {
            if (isImmediateNtkGeneratedUx() && isActiveGeneratedTouchOrQuiet()) {
                requestGeneratedViewportProofAndRunwayBytes("generated_limited_warm_active")
                logNtkRepositoryStage(
                    manga,
                    "early_urls_append_full_generated_limited_warm_skip_active",
                    "anchor=$anchor,total=$count,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                return
            }
            val quietMs = ntkBackgroundWarmQuietRemainingMs()
            if (quietMs > 0L) {
                logNtkRepositoryStage(
                    manga,
                    "early_urls_append_full_generated_limited_warm_defer_quiet",
                    "delayMs=$quietMs,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                )
                main.postDelayed({
                    if (!cancelled.get()) warmNtkGeneratedInitialPagesLimited(startPage, loadStartedAt)
                }, quietMs.coerceAtLeast(NTK_BACKGROUND_WARM_RECHECK_MS))
                return
            }
        }
        val warmAhead = if (shouldDeferGeneratedFullSurfaceWorkForInitialContinuous()) {
            NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        } else {
            ntkGeneratedInitialLimitedWarmPages()
        }
        val last = minOf(count - 1, anchor + warmAhead)
        if (last <= anchor) return
        logNtkRepositoryStage(
            manga,
            "early_urls_append_full_generated_limited_warm",
            "from=${anchor + 1},to=$last,total=$count,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        val foregroundPages = ntkGeneratedInitialLimitedForegroundPages()
        val busyPages = ntkGeneratedInitialLimitedBusyPages()
        for (index in (anchor + 1)..last) {
            val offset = index - anchor
            val generation = if (offset <= foregroundPages) {
                FOREGROUND_PRIME_WARM_GENERATION
            } else {
                PRIME_WARM_GENERATION
            }
            requestPage(
                index,
                busy = offset <= busyPages,
                anchor = false,
                generation = generation
            )
        }
    }

    private fun waitForInitialFullFetchQuietAfterFirstBitmap(target: Manga) {
        if (!isNtkSource(target, title) || !firstBitmapLogged.get()) return
        val firstBitmapAt = ntkFirstBitmapAtMs.get()
        if (firstBitmapAt <= 0L) return
        while (!cancelled.get()) {
            val now = SystemClock.uptimeMillis()
            val firstQuietMs = (
                firstBitmapAt + NTK_INITIAL_FULL_FETCH_AFTER_FIRST_BITMAP_QUIET_MS - now
            ).coerceAtLeast(0L)
            val interactionQuietMs = readerQuietRemainingMs(NTK_INITIAL_FULL_FETCH_TOUCH_QUIET_MS)
            val waitMs = max(firstQuietMs, interactionQuietMs)
            if (waitMs <= 0L) return
            try {
                Thread.sleep(waitMs.coerceAtMost(NTK_INITIAL_FULL_FETCH_QUIET_POLL_MS))
            } catch (e: InterruptedException) {
                Thread.currentThread().interrupt()
                return
            }
        }
    }

    private fun ntkGeneratedInitialLimitedForegroundPages(): Int {
        return if (isNtkWebtoonSource(manga, title)) {
            NTK_WEBTOON_GENERATED_INITIAL_LIMITED_FOREGROUND_PAGES
        } else if (isCurrentManhwaGeneratedOnlyRefs()) {
            NTK_MANHWA_GENERATED_INITIAL_VISIBLE_AHEAD_PAGES
        } else {
            NTK_GENERATED_INITIAL_LIMITED_FOREGROUND_PAGES
        }
    }

    private fun ntkGeneratedInitialLimitedBusyPages(): Int {
        return if (isNtkWebtoonSource(manga, title)) {
            NTK_WEBTOON_GENERATED_INITIAL_LIMITED_BUSY_PAGES
        } else if (isCurrentManhwaGeneratedOnlyRefs()) {
            NTK_MANHWA_GENERATED_INITIAL_VISIBLE_AHEAD_PAGES
        } else {
            NTK_GENERATED_INITIAL_LIMITED_BUSY_PAGES
        }
    }

    private fun ntkGeneratedInitialLimitedWarmPages(): Int {
        return if (isNtkWebtoonSource(manga, title)) {
            NTK_WEBTOON_GENERATED_INITIAL_LIMITED_WARM_PAGES
        } else if (isCurrentManhwaGeneratedOnlyRefs()) {
            NTK_MANHWA_GENERATED_INITIAL_VISIBLE_AHEAD_PAGES
        } else {
            NTK_GENERATED_INITIAL_LIMITED_WARM_PAGES
        }
    }

    private fun ntkInitialBytePrefetchAheadPages(): Int {
        val refs = synchronized(pagesLock) { pages.toList() }
        if (isGeneratedOnlyNtkRefs(refs)) {
            return if (isNtkManhwaEpisodePath(manga.ntkEpisodePath)) {
                NTK_MANHWA_GENERATED_INITIAL_VISIBLE_AHEAD_PAGES
            } else {
                NTK_WEBTOON_INITIAL_BYTE_PREFETCH_AHEAD_PAGES
            }
        }
        return if (isNtkWebtoonSource(manga, title)) {
            NTK_WEBTOON_INITIAL_BYTE_PREFETCH_AHEAD_PAGES
        } else {
            NTK_INITIAL_BYTE_PREFETCH_AHEAD_PAGES
        }
    }

    private fun prefetchNtkInitialNextBytes(anchor: Int, count: Int) {
        if (!isNtkSource(manga, title)) return
        if (!firstBitmapLogged.get()) return
        if (MainApplication.p?.getDataSave() == true) return
        if (isImmediateGeneratedShortPageRunway() && isWithinFirstBitmapInputGrace()) return
        val last = minOf(count - 1, anchor + ntkInitialBytePrefetchAheadPages())
        if (last <= anchor) return
        val generation = FOREGROUND_PRIME_WARM_GENERATION
        for (index in (anchor + 1)..last) {
            val page = pageRef(index) ?: continue
            if (page.transitionTitle != null) continue
            prefetchBusyPage(index, page, generation)
        }
        Log.d(TAG, "reader_ntk_initial_next_byte_prefetch anchor=$anchor count=${last - anchor}")
        ViewerWarmupManager.logMetric("reader_ntk_initial_next_byte_prefetch", (last - anchor).toLong())
    }

    private fun hasActiveOrDeliveredPage(index: Int): Boolean {
        if (loading.contains(index) || urgentLoading.contains(index)) return true
        if ((pendingDeliveryWidths[index] ?: 0) > 0) return true
        return hasDeliveredBitmap(index)
    }

    private fun releaseInitialFanoutIfAnchorReady(index: Int) {
        val pending = pendingInitialFanoutPage.get()
        if (pending < 0 || index != pending) return
        if (!pendingInitialFanoutPage.compareAndSet(pending, -1)) return
        startInitialFanout(index)
    }

    private fun postReleaseInitialFanoutIfPending(index: Int) {
        if (pendingInitialFanoutPage.get() != index) return
        main.post { releaseInitialFanoutIfAnchorReady(index) }
    }

    private fun shouldDeferInitialFanoutUntilAnchor(): Boolean {
        return !isNtkSource(manga, title)
    }

    private fun prefetchImageFilesAround(startPage: Int, after: Int = START_SOURCE_PREFETCH_AFTER) {
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty()) return
        val first = startPage.coerceIn(0, refs.lastIndex)
        val effectiveAfter = if (ntkCurrentBackgroundWarmDelayMs() > 0L) {
            minOf(after, NTK_INITIAL_PRIORITY_PAGES)
        } else {
            after
        }
        val last = minOf(refs.lastIndex, first + effectiveAfter)
        if (last < first) return
        val ordered = ArrayList<Int>(last - first + 1)
        val anchor = startPage.coerceIn(first, last)
        lastSourcePrefetchAnchor = anchor
        val generation = windowGeneration.get()
        ordered.add(anchor)
        for (offset in 1..max(last - anchor, anchor - first)) {
            val ahead = anchor + offset
            if (ahead <= last) ordered.add(ahead)
            val behind = anchor - offset
            if (behind >= first) ordered.add(behind)
        }
        for (index in ordered) {
            if (index == anchor) continue
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            prefetchBusyPage(index, page, generation)
        }
    }

    private fun resolvePreparedStartPage(preparedStartPage: Int): Int {
        val requested = requestedStartPage()
        return if (!startAtFirstPage && requested > 0 && preparedStartPage <= 0) requested else preparedStartPage
    }

    private fun requestPageForeground(index: Int) {
        if (isNtkSource(manga, title) && autoCut && index > 0) {
            requestPage(index - 1, busy = false, anchor = false, generation = windowGeneration.get())
        }
        requestPage(index, busy = false, anchor = true, generation = windowGeneration.get())
    }

    private fun deliverPreparedSourceBitmap(sourceIndex: Int, bitmap: Bitmap) {
        if (!autoCut) {
            deliverPreparedBitmap(sourceIndex, bitmap, false)
            return
        }
        val refs = synchronized(pagesLock) {
            pages.withIndex()
                .filter { it.value.sourceIndex == sourceIndex && it.value.transitionTitle == null }
                .map { it.index to it.value }
        }
        if (refs.isEmpty()) {
            if (!bitmap.isRecycled) earlyPreparedBitmaps[sourceIndex] = bitmap
            return
        }
        for ((pageIndex, page) in refs) {
            val prepared = preparedBitmapForPage(bitmap, page) ?: continue
            deliverPreparedBitmap(pageIndex, prepared.first, prepared.second)
        }
    }

    private data class PendingTile(
        val sourceTop: Int,
        val sourceBottom: Int,
        val bitmap: Bitmap
    )

    private fun preparedBitmapForPage(bitmap: Bitmap, page: PageRef): Pair<Bitmap, Boolean>? {
        if (bitmap.isRecycled) return null
        if (!shouldSplitPreparedBitmapForPage(autoCut, page.allowAutoSplit, bitmap.width, bitmap.height)) {
            return if (page.side == PAGE_SIDE_FIRST) bitmap to false else null
        }
        val cropWidth = max(1, bitmap.width / 2)
        val cropX = if (page.side == PAGE_SIDE_FIRST) {
            if (reverse) 0 else bitmap.width - cropWidth
        } else {
            if (reverse) bitmap.width - cropWidth else 0
        }
        val displayBitmap = Bitmap.createBitmap(cropWidth, bitmap.height, displayConfig(bitmap))
        Canvas(displayBitmap).drawBitmap(
            bitmap,
            Rect(cropX, 0, cropX + cropWidth, bitmap.height),
            Rect(0, 0, cropWidth, bitmap.height),
            null
        )
        return displayBitmap to true
    }

    private fun deliverPreparedBitmap(index: Int, bitmap: Bitmap, owned: Boolean) {
        deliverPreparedBitmap(index, bitmap, owned, true)
    }

    private fun deliverPreparedBitmap(index: Int, bitmap: Bitmap, owned: Boolean, allowInitialHold: Boolean) {
        if (Looper.myLooper() !== Looper.getMainLooper()) {
            main.post { deliverPreparedBitmap(index, bitmap, owned, allowInitialHold) }
            return
        }
        var deliveryIndex = index
        if (!firstBitmapLogged.get()) {
            deliveryIndex = collapseInitialMissingNtkGeneratedPrefixForPrepared(index)
        }
        if (cancelled.get() || deliveryIndex < 0 || bitmap.isRecycled) return
        val deliveryPage = pageRef(deliveryIndex) ?: run {
            if (owned && !bitmap.isRecycled) recycleBitmapAsync(bitmap)
            return
        }
        if (usesProtectedNumericNtkPipeline(deliveryPage) &&
            !isInsideProtectedNumericBitmapWindow(deliveryIndex, deliveryPage)
        ) {
            if (owned && !bitmap.isRecycled) recycleBitmapAsync(bitmap)
            return
        }
        if (allowInitialHold && shouldHoldInitialNtkIndex(deliveryIndex)) {
            loading.remove(deliveryIndex)
            loadingPages.remove(deliveryIndex)
            loadingStartedAtMs.remove(deliveryIndex)
            urgentLoading.remove(deliveryIndex)
            urgentLoadingPages.remove(deliveryIndex)
            initialPreparedBacklog.put(deliveryIndex, PreparedDelivery(bitmap, owned))?.let { previous ->
                if (previous.owned && previous.bitmap !== bitmap &&
                    !isBitmapProtectedFromRecycle(previous.bitmap)
                ) {
                    recycleBitmapAsync(previous.bitmap)
                }
            }
            Log.d(TAG, "reader_initial_hold_prepared page=$deliveryIndex,start=${currentStartPage()},width=${bitmap.width}")
            scheduleInitialDeliveryFallback()
            return
        }
        decodedWidths[deliveryIndex] = max(decodedWidths[deliveryIndex] ?: 0, bitmap.width)
        loading.remove(deliveryIndex)
        loadingPages.remove(deliveryIndex)
        loadingStartedAtMs.remove(deliveryIndex)
        urgentLoading.remove(deliveryIndex)
        urgentLoadingPages.remove(deliveryIndex)
        if (listener.isPageDrawableInstalled(deliveryIndex)) {
            val alreadyTracked = synchronized(deliveredBitmaps) {
                deliveredBitmaps[deliveryIndex] === bitmap
            }
            if (owned && !alreadyTracked && !bitmap.isRecycled) recycleBitmapAsync(bitmap)
            markFirstPreparedBitmapDelivered(preparedBitmapDrawHeightPx(bitmap))
            deliveryPage?.let { page ->
                markDecodedDrawableReady(deliveryIndex, page, bitmap.width)
            }
            ntkCoordinator?.markAnchorBitmapDecoded(deliveryIndex)
            ntkCoordinator?.markFirstDrawableCommitted(deliveryIndex)
            postReleaseInitialFanoutIfPending(deliveryIndex)
            return
        }
        if (trackDeliveredBitmap(deliveryIndex, deliveryPage, bitmap, owned) < 0) {
            redriveAfterTerminalBitmapConflict(
                deliveryIndex,
                deliveryPage,
                bitmap.width,
                "prepared_bitmap",
            )
            return
        }
        val preRenderedInitialAnchor =
            if (shouldPreRenderPreparedInitialAnchor(deliveryIndex, bitmap)) {
                try {
                    listener.onInitialPageDecoded(deliveryIndex, bitmap)
                } catch (e: Throwable) {
                    Log.d(
                        TAG,
                        "reader_prepared_initial_anchor_prerender_error page=$deliveryIndex," +
                            "error=${e.javaClass.simpleName}"
                    )
                    InitialPrerenderResult.NOT_RENDERED
                }
            } else {
                InitialPrerenderResult.NOT_RENDERED
            }
        if (preRenderedInitialAnchor != InitialPrerenderResult.NOT_RENDERED) {
            synchronized(indexedStateLock) {
                preRenderedInitialDeliveries.add(deliveryIndex)
            }
            markFirstDrawableCommitted(deliveryIndex, "prepared_initial_anchor_prerender")
            Log.d(
                TAG,
                "reader_prepared_initial_anchor_prerender page=$deliveryIndex," +
                    "result=$preRenderedInitialAnchor,width=${bitmap.width}"
            )
        }
        markFirstPreparedBitmapDelivered(preparedBitmapDrawHeightPx(bitmap))
        val publishPrepared = Runnable {
            if (!cancelled.get()) {
                deliverInitialPagesReadyForCurrentPagesIfNeeded()
                listener.onPageReady(deliveryIndex, bitmap)
                deliveryPage?.let { page ->
                    markDecodedDrawableReady(deliveryIndex, page, bitmap.width)
                    maybeStartInitialTailAdjacentPreappendForAnchor(
                        deliveryIndex,
                        "prepared_drawable_ready"
                    )
                }
                ntkCoordinator?.markAnchorBitmapDecoded(deliveryIndex)
                ntkCoordinator?.markFirstDrawableCommitted(deliveryIndex)
                postReleaseInitialFanoutIfPending(deliveryIndex)
            }
        }
        main.post(publishPrepared)
    }

    private fun shouldPreRenderPreparedInitialAnchor(index: Int, bitmap: Bitmap): Boolean {
        if (bitmap.isRecycled) return false
        if (!isNtkSource(manga, title)) return false
        if (firstDrawableDelivered.get()) return false
        return index == currentStartPage()
    }

    private fun markFirstDrawableCommitted(index: Int, reason: String) {
        val firstCommit = firstDrawableDelivered.compareAndSet(false, true)
        ntkCoordinator?.markFirstDrawableCommitted(index)
        if (!firstCommit || !isImmediateNtkGeneratedUx()) return
        if (strictExactColdRolling) {
            strictExactEpisodeToken?.let { episode ->
                strictExactSourceTransport.get()?.onInitialDrawableCommitted(episode)
            }
            strictOffscreenPublishResumeAtMs.set(
                SystemClock.uptimeMillis() + STRICT_EXACT_FIRST_FRAME_PUBLICATION_GRACE_MS
            )
            main.postDelayed(
                {
                    if (!cancelled.get()) flushInitialHeldDeliveries("strict_first_frame")
                },
                STRICT_EXACT_FIRST_FRAME_PUBLICATION_GRACE_MS
            )
        }
        Log.d(TAG, "reader_first_drawable_committed page=$index,reason=$reason,start=${currentStartPage()}")
        Log.d(TAG, "reader_first_drawable_followups_wait_for_input_quiet start=${currentStartPage()}")
    }

    private fun collapseInitialMissingNtkGeneratedPrefixForPrepared(index: Int): Int {
        if (index <= 0 || firstBitmapLogged.get()) return index
        val start = currentStartPage()
        if (index <= start) return index
        var removed = 0
        var removeStart = start
        var total = 0
        synchronized(pagesLock) {
            if (index !in pages.indices || start !in pages.indices) return index
            val target = pages[index]
            if (!isNtkSource(target.manga, title) ||
                !isNtkManhwaOrWebtoonEpisodePath(target.manga.ntkEpisodePath) ||
                !isNtkGeneratedImageUrl(target.image.orEmpty())
            ) {
                return index
            }
            if (trustedNtkGeneratedImageCount(target.manga) > 0) {
                Log.d(
                    TAG,
                    "collapse_initial_missing_generated_prefix_skip_authoritative_count " +
                        "trusted=${trustedNtkGeneratedImageCount(target.manga)},oldIndex=$index," +
                        "path=${target.manga.ntkEpisodePath}"
                )
                return index
            }
            var canCollapse = true
            for (candidateIndex in start until index) {
                val candidate = pages.getOrNull(candidateIndex) ?: return index
                if (candidate.transitionTitle != null ||
                    !Manga.sameEpisodeIdentity(candidate.manga, target.manga) ||
                    !isNtkGeneratedImageUrl(candidate.image.orEmpty()) ||
                    !ReaderImageCache.isKnownNtkGeneratedNotFound(candidate.manga, candidate.image.orEmpty())
                ) {
                    canCollapse = false
                    break
                }
            }
            if (!canCollapse) {
                removeStart = start + 1
                if (index <= removeStart) return index
                for (candidateIndex in removeStart until index) {
                    val candidate = pages.getOrNull(candidateIndex) ?: return index
                    if (candidate.transitionTitle != null ||
                        !Manga.sameEpisodeIdentity(candidate.manga, target.manga) ||
                        !isNtkGeneratedImageUrl(candidate.image.orEmpty()) ||
                        !ReaderImageCache.isKnownNtkGeneratedNotFound(candidate.manga, candidate.image.orEmpty())
                    ) {
                        return index
                    }
                }
            }
            removed = index - removeStart
            beginStructurePublish()
            repeat(removed) { pages.removeAt(removeStart) }
            pages.forEachIndexed { pageIndex, ref -> ref.pageIndex = pageIndex }
            removePageStateRange(removeStart, removed)
            total = pages.size
            capturePublishedPageIndexLocked()
        }
        val posted = main.post {
            try {
                if (!cancelled.get()) {
                    listener.onPagesRemoved(removeStart, removed, total)
                }
            } finally {
                finishStructurePublish()
                requestRetainedWindowAfterStructureChange()
            }
        }
        if (!posted) {
            finishStructurePublish()
            requestRetainedWindowAfterStructureChange()
        }
        Log.d(
            TAG,
            "collapse_initial_missing_generated_prefix start=$removeStart,removed=$removed," +
                "oldIndex=$index,newIndex=${index - removed},path=${manga.ntkEpisodePath}"
        )
        return index - removed
    }

    private fun scheduleInitialMissingNtkGeneratedGapCollapse(reason: String, attempts: Int) {
        if (attempts <= 0 || cancelled.get()) return
        main.postDelayed({
            if (cancelled.get() || initialContinuousDrawableDelivered(currentStartPage())) return@postDelayed
            val collapsed = collapseInitialMissingNtkGeneratedGapToCachedPage(reason)
            if (collapsed) {
                requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), synchronized(pagesLock) { pages.size })
                return@postDelayed
            }
            scheduleInitialMissingNtkGeneratedGapCollapse(reason, attempts - 1)
        }, 80L)
    }

    private fun collapseInitialMissingNtkGeneratedGapToCachedPage(reason: String): Boolean {
        if (!isNtkSource(manga, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) return false
        val start = currentStartPage()
        if (!initialContinuousDrawableDelivered(start)) return false
        val snapshot = synchronized(pagesLock) { pages.toList() }
        if (start !in snapshot.indices) return false
        val anchor = snapshot[start]
        if (anchor.transitionTitle != null ||
            !isNtkGeneratedImageUrl(anchor.image.orEmpty())
        ) {
            return false
        }
        if (trustedNtkGeneratedImageCount(anchor.manga) > 0) {
            Log.d(
                TAG,
                "collapse_initial_missing_generated_gap_skip_authoritative_count " +
                    "trusted=${trustedNtkGeneratedImageCount(anchor.manga)},reason=$reason," +
                    "path=${anchor.manga.ntkEpisodePath}"
            )
            return false
        }
        val lastCandidate = minOf(snapshot.lastIndex, start + NTK_INITIAL_RAPID_SCROLL_DECODE_AHEAD_PAGES)
        for (candidateIndex in (start + 2)..lastCandidate) {
            val candidate = snapshot.getOrNull(candidateIndex) ?: continue
            if (candidate.transitionTitle != null ||
                !Manga.sameEpisodeIdentity(candidate.manga, anchor.manga) ||
                !isNtkGeneratedImageUrl(candidate.image.orEmpty())
            ) {
                continue
            }
            var gapMissing = true
            for (gapIndex in (start + 1) until candidateIndex) {
                val gap = snapshot.getOrNull(gapIndex)
                if (gap == null ||
                    gap.transitionTitle != null ||
                    !Manga.sameEpisodeIdentity(gap.manga, anchor.manga) ||
                    !isNtkGeneratedImageUrl(gap.image.orEmpty()) ||
                    !ReaderImageCache.isKnownNtkGeneratedNotFound(gap.manga, gap.image.orEmpty())
                ) {
                    gapMissing = false
                    break
                }
            }
            if (!gapMissing) continue
            if (!hasPageSourceReady(candidateIndex, candidate) &&
                !hasEarlyNtkGeneratedSuccessForPage(candidate)
            ) {
                continue
            }
            val removeStart = start + 1
            val removed = candidateIndex - removeStart
            var total = 0
            synchronized(pagesLock) {
                if (candidateIndex !in pages.indices || pages[candidateIndex] !== candidate) return false
                for (gapIndex in removeStart until candidateIndex) {
                    if (pages.getOrNull(gapIndex) !== snapshot[gapIndex]) return false
                }
                beginStructurePublish()
                repeat(removed) { pages.removeAt(removeStart) }
                pages.forEachIndexed { pageIndex, ref -> ref.pageIndex = pageIndex }
                removePageStateRange(removeStart, removed)
                total = pages.size
                capturePublishedPageIndexLocked()
            }
            val posted = main.post {
                try {
                    if (!cancelled.get()) {
                        listener.onPagesRemoved(removeStart, removed, total)
                    }
                } finally {
                    finishStructurePublish()
                    requestRetainedWindowAfterStructureChange()
                }
            }
            if (!posted) {
                finishStructurePublish()
                requestRetainedWindowAfterStructureChange()
            }
            Log.d(
                TAG,
                "collapse_initial_missing_generated_gap reason=$reason,start=$removeStart," +
                    "removed=$removed,cachedIndex=$candidateIndex,newIndex=${candidateIndex - removed}," +
                    "path=${manga.ntkEpisodePath}"
            )
            return true
        }
        return false
    }

    private fun hasEarlyNtkGeneratedSuccessForPage(page: PageRef): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        val targetPage = ntkImagePageNumber(page.image.orEmpty()) ?: (page.sourceIndex + 1)
        if (targetPage <= 0) return false
        val earlyUrls = ReaderImageCache.earlyNtkGeneratedSuccessImageUrls(
            page.manga.ntkEpisodePath,
            SystemClock.elapsedRealtime() - 30000L
        )
        return earlyUrls.any { candidate ->
            ntkImagePageNumber(candidate) == targetPage &&
            ntkImageCandidateMatchesEpisode(candidate, page.manga)
        }
    }

    private fun deliverPreparedSourceTilePage(
        sourceIndex: Int,
        prepared: ReaderPreparedStore.PreparedTilePage
    ) {
        if (Looper.myLooper() !== Looper.getMainLooper()) {
            main.post { deliverPreparedSourceTilePage(sourceIndex, prepared) }
            return
        }
        if (autoCut || prepared.pageWidth <= 0 || prepared.pageHeight <= 0 ||
            prepared.tiles.isEmpty() || prepared.tiles.any { it.bitmap.isRecycled }
        ) {
            return
        }
        var deliveryIndex = sourceIndex
        if (!firstBitmapLogged.get()) {
            deliveryIndex = collapseInitialMissingNtkGeneratedPrefixForPrepared(sourceIndex)
        }
        if (cancelled.get() || deliveryIndex < 0) return
        val deliveryPage = pageRef(deliveryIndex) ?: return
        if (!ReaderPreparedStore.isCanonicalOriginalTilePage(
                prepared,
                deliveryPage.image,
                NTK_GENERATED_DRAW_TILE_HEIGHT
            )
        ) {
            logNtkPagePerf(
                deliveryIndex,
                "prepared_tile_rejected_provenance",
                "source=$sourceIndex,asset=${deliveryPage.image.orEmpty().takeLast(96)}"
            )
            return
        }
        if (usesProtectedNumericNtkPipeline(deliveryPage) &&
            !isInsideProtectedNumericBitmapWindow(deliveryIndex, deliveryPage)
        ) {
            return
        }
        decodedWidths[deliveryIndex] = max(decodedWidths[deliveryIndex] ?: 0, prepared.pageWidth)
        loading.remove(deliveryIndex)
        loadingPages.remove(deliveryIndex)
        loadingStartedAtMs.remove(deliveryIndex)
        urgentLoading.remove(deliveryIndex)
        urgentLoadingPages.remove(deliveryIndex)
        val tiles = prepared.tiles
        val drawnHeight = max(
            1f,
            max(1, viewerWidth).toFloat() * prepared.pageHeight / prepared.pageWidth.toFloat()
        )
        if (listener.isPageDrawableInstalled(deliveryIndex)) {
            // Mirror only the exact borrowed Store winner. A Session-owned installed winner must
            // remain tracked and owned; replacing it here would recycle pixels still in use.
            if (listener.isExactPreparedStoreTilePageInstalled(
                    deliveryIndex,
                    prepared.pageWidth,
                    prepared.pageHeight,
                    tiles
                )
            ) {
                if (trackDeliveredTiles(deliveryIndex, deliveryPage, tiles, owned = false) < 0) {
                    rollbackPublishedBitmapConflict(
                        deliveryIndex,
                        deliveryPage,
                        prepared.pageWidth,
                        "prepared_store_already_installed",
                    )
                    return
                }
                if (listener.isPageAuthoritativeDrawableCurrentlyInstalled(currentStartPage())) {
                    // The Store batch is adopted atomically by the surface. Reflect that genuine
                    // installed first drawable in Session state as well, otherwise legacy
                    // pre-first fanout continues after a fully drawable surface is already live.
                    markFirstDrawableCommitted(
                        currentStartPage(),
                        "prepared_store_already_installed"
                    )
                }
            }
            markFirstPreparedBitmapDelivered(drawnHeight)
            markDecodedDrawableReady(deliveryIndex, deliveryPage, prepared.pageWidth)
            ntkCoordinator?.markAnchorBitmapDecoded(deliveryIndex)
            ntkCoordinator?.markFirstDrawableCommitted(deliveryIndex)
            postReleaseInitialFanoutIfPending(deliveryIndex)
            return
        }
        if (trackDeliveredTiles(deliveryIndex, deliveryPage, tiles, owned = false) < 0) {
            redriveAfterTerminalBitmapConflict(
                deliveryIndex,
                deliveryPage,
                prepared.pageWidth,
                "prepared_tiles",
            )
            return
        }
        val preRenderedInitialAnchor = if (!firstDrawableDelivered.get() && deliveryIndex == currentStartPage()) {
            try {
                listener.onInitialPageTilesDecoded(
                    deliveryIndex,
                    prepared.pageWidth,
                    prepared.pageHeight,
                    tiles
                )
            } catch (e: Throwable) {
                Log.d(
                    TAG,
                    "reader_prepared_initial_tile_prerender_error page=$deliveryIndex," +
                        "error=${e.javaClass.simpleName}"
                )
                InitialPrerenderResult.NOT_RENDERED
            }
        } else {
            InitialPrerenderResult.NOT_RENDERED
        }
        if (preRenderedInitialAnchor != InitialPrerenderResult.NOT_RENDERED) {
            synchronized(indexedStateLock) {
                preRenderedInitialDeliveries.add(deliveryIndex)
            }
            markFirstDrawableCommitted(deliveryIndex, "prepared_initial_tile_prerender")
        }
        markFirstPreparedBitmapDelivered(drawnHeight)
        val launchRunway = isAckIndependentGeneratedRunwayIndex(deliveryIndex, deliveryPage)
        val publishPrepared = Runnable {
            if (!cancelled.get()) {
                deliverInitialPagesReadyForCurrentPagesIfNeeded()
                if (launchRunway) {
                    listener.onPageLaunchRunwayTilesReady(
                        deliveryIndex,
                        prepared.pageWidth,
                        prepared.pageHeight,
                        tiles
                    )
                } else {
                    listener.onPageTilesReady(
                        deliveryIndex,
                        prepared.pageWidth,
                        prepared.pageHeight,
                        tiles
                    )
                }
                markDecodedDrawableReady(deliveryIndex, deliveryPage, prepared.pageWidth)
                ntkCoordinator?.markAnchorBitmapDecoded(deliveryIndex)
                ntkCoordinator?.markFirstDrawableCommitted(deliveryIndex)
                postReleaseInitialFanoutIfPending(deliveryIndex)
            }
        }
        if (launchRunway) {
            mainImmediate.post(publishPrepared)
        } else {
            main.post(publishPrepared)
        }
    }

    private fun hasRecentNtkGeneratedSuccessForPage(page: PageRef): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(page.manga, title)) return false
        val targetPage = ntkImagePageNumber(page.image.orEmpty()) ?: (page.sourceIndex + 1)
        if (targetPage <= 0) return false
        val earlyUrls = ReaderImageCache.earlyNtkGeneratedSuccessImageUrls(page.manga.ntkEpisodePath, 0L)
        return earlyUrls.any { candidate ->
            ntkImagePageNumber(candidate) == targetPage &&
                ntkImageCandidateMatchesEpisode(candidate, page.manga)
        }
    }

    private fun preparedBitmapDrawHeightPx(bitmap: Bitmap): Float {
        if (bitmap.isRecycled || bitmap.width <= 0 || bitmap.height <= 0) return 0f
        val width = max(1, viewerWidth).toFloat()
        return max(1f, width * bitmap.height / bitmap.width.toFloat())
    }

    private fun markFirstPreparedBitmapDelivered(drawHeightPx: Float = 0f) {
        if (firstBitmapLogged.compareAndSet(false, true)) {
            val firstBitmapElapsedAt = SystemClock.elapsedRealtime()
            ntkFirstBitmapAtMs.set(SystemClock.uptimeMillis())
            if (drawHeightPx > 0f) {
                ntkFirstDrawableDrawHeightPx.compareAndSet(0, drawHeightPx.toInt().coerceAtLeast(1))
            }
            ViewerWarmupManager.logMetric("reader_first_bitmap_prepared", 1L)
            releasePreparedStoreBitmapsSoon()
            maybeStartInitialTailAdjacentPreappend(manga, currentStartPage(), pagesLastIndex() + 1, "first_bitmap_prepared")
            startFirstBitmapFollowups(firstBitmapElapsedAt, firstBitmapElapsedAt)
            scheduleNtkEpisodeMetadataAfterFirstBitmap()
        }
    }

    private fun flushEarlyPreparedBitmaps() {
        val pending = earlyPreparedBitmaps.entries.toList()
        earlyPreparedBitmaps.clear()
        for (entry in pending) deliverPreparedSourceBitmap(entry.key, entry.value)
    }

    fun requestWindow(first: Int, last: Int, anchor: Int, busy: Boolean) {
        if (strictExactColdRolling) {
            requestWindowAsync(first, last, anchor, busy)
            return
        }
        requestWindow(first, last, anchor, busy, true)
    }

    /**
     * Completes the host-pressure eviction transaction only after Surface has removed the exact
     * drawable. The pressure marker was published before that main-thread clear, so this ACK is
     * the first safe edge on which an intersecting physical frontier may reclaim the PageRef.
     */
    fun onHostPressureSurfaceClearCompleted(index: Int, cleared: Boolean) {
        if (cancelled.get()) return
        val page = synchronized(pagesLock) {
            pages.getOrNull(index)?.takeIf {
                hostExactPoolPressureRetiredPages.contains(index)
            }?.also { candidate ->
                if (cleared) {
                    hostPressurePendingSurfaceRetirements.remove(candidate)
                    hostPressureSurfaceRetirementsInFlight.remove(candidate)
                }
            }
        }
        if (!cleared) return
        if (page != null && canAccessAppendOnlyStablePrefix(index)) {
            routeStrictAdjacentExactRehydrate(index, page, visibleIntent = true)
        }
        // Off-screen markers intentionally remain parked. This durable redrive observes the exact
        // post-clear Surface state now, and a later physical WindowEvent has the same narrow
        // stable-prefix route while an unrelated tail page is still publishing.
        requestRetainedWindowAfterStructureChange()
    }

    fun noteUserInteraction() {
        lastUserInteractionMs.set(SystemClock.uptimeMillis())
        cancelNtkBackgroundFallbacksForActiveInput("touch")
    }

    /**
     * Called only after the inline host has atomically switched to ACTIVE and made the real reader
     * visible. Staging remains byte-only beyond the canonical Store runway; this continuation can
     * therefore never enlarge the exact pre-tap attached-root prepare set.
     */
    fun onViewerActivated() {
        if (!viewerActivated.compareAndSet(false, true)) return
        if (strictExactColdRolling) {
            // Physical draw proof is the only caller allowed to expand the strict source gate.
            return
        }
        // Strict source work is admitted only after the real viewer becomes active. The source
        // window itself is bounded around the viewport, so this is not a hidden pre-download.
        startVerifiedGeneratedCurrentEpisodeStreams()
        if (preparedLaunchRunwaySpec == null || !isImmediateNtkGeneratedUx()) return
        handOffContiguousPreparedStoreRunwayOnActivation()
        if (!preparedPostActivationContinuationStarted.compareAndSet(false, true)) return
        schedulePreparedPostActivationContinuationIfNeeded()
    }

    /** Revalidates event-parked suffixes after Android returns the existing reader to foreground. */
    fun onHostResumed() {
        if (cancelled.get()) return
        synchronized(hostLifecyclePixelLock) {
            hostLifecycleResumed = true
            hostLifecyclePixelLock.notifyAll()
        }
        HostExactHardwareTilePool.notePhysicalReaderHostResumed()
        val maintenanceDeadline =
            SystemClock.uptimeMillis() + NTK_FORWARD_HISTORY_RESUME_QUIET_MS
        forwardHistoryHostResumeNotBeforeMs.getAndUpdate { current ->
            maxOf(current, maintenanceDeadline)
        }
        currentViewportAnchor.get().takeIf { it >= 0 }?.let { anchor ->
            // A paused host deliberately leaves destructive history maintenance unposted. Resume
            // supplies the missing ownership edge; the quiet deadline above then keeps the actual
            // mutation away from the first restored frame and first user gesture.
            forwardReadingPosition.set(anchor)
            scheduleForwardReadingDrain()
        }
        redriveParkedAdjacentRemaindersAfterEvent()
        if (!viewportBusy.get()) scheduleParkedInitialAdjacentRunwayWakeAfterPhysicalIdle()
    }

    /**
     * Keeps verified bodies and network ownership alive across HOME, but stops CPU/native pixel
     * materialization while no reader Surface can consume it. Workers retain their exact
     * descriptor and resume from the same lease after [onHostResumed]; no request or image is
     * discarded.
     */
    fun onHostPaused() {
        if (cancelled.get()) return
        synchronized(hostLifecyclePixelLock) {
            hostLifecycleResumed = false
        }
    }

    private fun awaitHostLifecyclePixelDecodeAdmission() {
        while (!hostLifecycleResumed) {
            if (cancelled.get() || Thread.currentThread().isInterrupted) {
                throw InterruptedException("Reader host pixel decode admission cancelled")
            }
            synchronized(hostLifecyclePixelLock) {
                if (!hostLifecycleResumed && !cancelled.get()) {
                    hostLifecyclePixelLock.wait(50L)
                }
            }
        }
    }

    /**
     * Coalesces the physical quiet edge for exact p0 structure publication. Descriptor residency is
     * already true for these owners, so repeatedly polling it cannot reveal new information. The
     * next real idle edge is the publication authority; one long watchdog remains only for a lost
     * lifecycle callback.
     */
    private fun scheduleParkedInitialAdjacentRunwayWakeAfterPhysicalIdle() {
        if (cancelled.get() || parkedInitialAdjacentRunwayRetries.isEmpty() ||
            !parkedInitialAdjacentIdleWakePosted.compareAndSet(false, true)
        ) return
        val quietDelayMs = physicalTouchQuietRemainingMs(
            NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS,
        ).coerceAtLeast(1L)
        val posted = main.postDelayed({
            parkedInitialAdjacentIdleWakePosted.set(false)
            if (!cancelled.get() && !viewportBusy.get()) {
                wakeParkedInitialAdjacentRunwayRetries()
            }
        }, quietDelayMs)
        if (!posted) parkedInitialAdjacentIdleWakePosted.set(false)
    }

    private fun wakeParkedInitialAdjacentRunwayRetries() {
        if (cancelled.get() || parkedInitialAdjacentRunwayRetries.isEmpty()) return
        parkedInitialAdjacentRunwayRetries.values.toList().forEach { retry ->
            main.removeCallbacks(retry)
            retry.run()
        }
    }

    /**
     * Opens the rolling window only after ReaderSurfaceView reports a committed, identity-valid
     * real-pixel frame. Decode delivery alone is intentionally insufficient.
     */
    fun onExactNtkActualFramePresented(pageIndex: Int) {
        onExactNtkPhysicalDrawPresented(pageIndex, pageIndex, 1)
    }

    /**
     * Releases an appended episode's source fallback only after its own exact pixels have crossed
     * the physical frame-commit boundary. The launch episode uses [strictExactSourceTransport],
     * while appended episodes retain distinct claims in [adjacentStrictSourceClaims]; forwarding
     * an adjacent commit only to the launch transport leaves a failed adjacent body permanently
     * parked behind its first-actual-frame gate.
     */
    fun onExactNtkAdjacentActualFramePresented(
        episodePath: String,
        firstVisibleSourceIndex: Int = 0,
        lastVisibleSourceIndex: Int = firstVisibleSourceIndex,
        direction: Int = 1,
        viewportOwnsEpisode: Boolean = true,
    ) {
        if (cancelled.get()) return
        val normalizedPath = NtkStripDigests.normalizeEpisodePath(episodePath)
        if (normalizedPath.isEmpty()) return
        val claim = adjacentStrictSourceClaims[normalizedPath] ?: return
        if (!isAdjacentStrictSourceClaimLive(normalizedPath, claim)) return
        // Transfer foreground byte ownership at the same compositor proof that authored this
        // demand. Waiting until the asynchronous source-actor callback returned let the newly
        // admitted next source enter the optional/offscreen byte lane even though it was already
        // the visible episode.
        NtkReaderTransferPacer.notePhysicalForegroundEpisode(this, normalizedPath)
        applyAdjacentStrictViewportSourceDemand(
            normalizedPath,
            claim,
            firstVisibleSourceIndex,
            lastVisibleSourceIndex,
            direction,
        )
        recordExactAdjacentCompositorForwardWarm(
            normalizedPath,
            claim,
            lastVisibleSourceIndex,
            direction,
        )
        releaseStrictLaunchPixelProtectionAfterSuccessorPresented()
        // A mixed predecessor-tail/adjacent-p0 frame proves p0 demand, but opening p5+ bulk work
        // there makes network/actor callbacks compete with the p0->p1 compositor transition. The
        // initial exact runway already owns every body needed to clear that boundary. Release the
        // remaining source wave only after one immutable committed viewport contains this episode
        // and no other episode's pixels. This also prevents a B/C boundary from releasing C merely
        // because the original launch episode A has already left the long-lived session.
        if (viewportOwnsEpisode && claim.viewportActivated.compareAndSet(false, true)) {
            try {
                claim.transport.onAdjacentViewportActivated(claim.episode)
                Log.d(
                    TAG,
                    "append_adjacent_strict_source_viewport_release path=$normalizedPath " +
                        "digest=${claim.manifestDigest}",
                )
            } catch (failure: Exception) {
                // A later compositor-proven frame may retry if teardown raced this delivery.
                claim.viewportActivated.set(false)
                if (!cancelled.get() && !isExpectedCancellation(failure)) {
                    recordIfUnexpected(failure)
                }
                return
            }
        } else if (!viewportOwnsEpisode && !claim.viewportActivated.get() &&
            shouldLogRateLimitedDiagnostic(
                "adjacent_viewport_wait_clean|$normalizedPath",
                60_000L,
            )
        ) {
            Log.d(
                TAG,
                "append_adjacent_strict_source_viewport_release_wait_clean " +
                    "path=$normalizedPath,digest=${claim.manifestDigest}",
            )
        }
        if (!claim.firstActualFramePresented.compareAndSet(false, true)) {
            // Re-entry can reuse the same immutable claim. Refresh the foreground identity and
            // close any descriptor-before-waiter race without repeating the transport callback.
            latestEnteredExactEpisodePath.set(normalizedPath)
            requestLatestExactAdjacentCompositorForwardWarm()
            requestEnteredExactEpisodePixelCompletion(normalizedPath)
            return
        }
        try {
            claim.transport.onFirstActualFramePresented(claim.episode)
            Log.d(
                TAG,
                "append_adjacent_strict_source_first_actual path=$normalizedPath " +
                    "digest=${claim.manifestDigest}",
            )
            latestEnteredExactEpisodePath.set(normalizedPath)
            wakeRemainingAdjacentAppendAfterExactFirstActual(normalizedPath)
            requestLatestExactAdjacentCompositorForwardWarm()
        } catch (failure: Exception) {
            // A later compositor-proven frame may retry if the transport rejected this delivery.
            claim.firstActualFramePresented.set(false)
            recordIfUnexpected(failure)
        }
    }

    /**
     * Records exactly one source ahead of a clean adjacent native frame.
     *
     * Source demand above may fetch its encoded body, but this method never starts network work.
     * Pixel decode is admitted only after the generation-bound descriptor/body is already resident.
     */
    private fun recordExactAdjacentCompositorForwardWarm(
        normalizedPath: String,
        claim: AdjacentStrictSourceClaim,
        lastVisibleSourceIndex: Int,
        direction: Int,
    ) {
        if (direction < 0 || lastVisibleSourceIndex < 0 ||
            lastVisibleSourceIndex >= claim.pageCount - 1
        ) {
            latestExactAdjacentCompositorForwardWarm.set(null)
            return
        }
        val nextSourceIndex = lastVisibleSourceIndex + 1
        val target = synchronized(pagesLock) {
            pages.firstOrNull { candidate ->
                candidate.transitionTitle == null &&
                    candidate.sourceIndex == nextSourceIndex &&
                    candidate.manifestDigest == claim.manifestDigest &&
                    NtkStripDigests.normalizeEpisodePath(
                        candidate.manga.ntkEpisodePath.orEmpty(),
                    ) == normalizedPath &&
                    strictAdjacentRehydrateIdentity(candidate) != null
            }
        }
        latestExactAdjacentCompositorForwardWarm.set(
            target?.let { page ->
                ExactAdjacentCompositorForwardWarm(
                    normalizedPath = normalizedPath,
                    visibleLastSourceIndex = lastVisibleSourceIndex,
                    page = page,
                )
            },
        )
        if (target != null && shouldLogRateLimitedDiagnostic(
                "compositor_forward_warm_record|$normalizedPath|$nextSourceIndex",
                60_000L,
            )
        ) {
            Log.d(
                TAG,
                "reader_compositor_forward_warm_record path=$normalizedPath " +
                    "visibleLast=$lastVisibleSourceIndex target=$nextSourceIndex " +
                    "direction=$direction index=${target.pageIndex}",
            )
        }
    }

    private fun isLatestExactAdjacentCompositorForwardWarm(
        index: Int,
        page: PageRef,
    ): Boolean {
        val proof = latestExactAdjacentCompositorForwardWarm.get() ?: return false
        val proofIdentity = strictAdjacentRehydrateIdentity(proof.page) ?: return false
        if (strictAdjacentRehydrateIdentity(page) != proofIdentity ||
            page.sourceIndex != proof.visibleLastSourceIndex + 1 ||
            latestEnteredExactEpisodePath.get() != proof.normalizedPath
        ) return false
        val claim = adjacentStrictSourceClaims[proof.normalizedPath] ?: return false
        if (!claim.firstActualFramePresented.get() ||
            !isAdjacentStrictSourceClaimLive(proof.normalizedPath, claim) ||
            page.manifestDigest != claim.manifestDigest
        ) return false
        return synchronized(pagesLock) {
            val currentIndex = pageIndexLocked(page, index)
            val proofIndex = pageIndexLocked(proof.page, proof.page.pageIndex)
            currentIndex in pages.indices && pages[currentIndex] === page &&
                proofIndex in pages.indices && pages[proofIndex] === proof.page
        }
    }

    private fun requestLatestExactAdjacentCompositorForwardWarm() {
        if (cancelled.get()) return
        val proof = latestExactAdjacentCompositorForwardWarm.get() ?: return
        val currentIndex = synchronized(pagesLock) {
            pageIndexLocked(proof.page, proof.page.pageIndex)
        }
        if (currentIndex < 0 ||
            !isLatestExactAdjacentCompositorForwardWarm(currentIndex, proof.page)
        ) {
            latestExactAdjacentCompositorForwardWarm.compareAndSet(proof, null)
            return
        }
        // The viewport source-demand actor owns byte acquisition. A compositor warm may consume
        // only a body it has already published; body publication calls this helper again.
        if (strictAdjacentBodyDescriptor(proof.page) == null &&
            strictAdjacentPublishedBody(proof.page) == null
        ) {
            if (shouldLogRateLimitedDiagnostic(
                    "compositor_forward_warm_body_wait|${proof.normalizedPath}|" +
                        proof.page.sourceIndex,
                    60_000L,
                )
            ) {
                Log.d(
                    TAG,
                    "reader_compositor_forward_warm_body_wait path=${proof.normalizedPath} " +
                        "source=${proof.page.sourceIndex} index=$currentIndex",
                )
            }
            return
        }
        if (shouldLogRateLimitedDiagnostic(
                "compositor_forward_warm_route|${proof.normalizedPath}|${proof.page.sourceIndex}",
                60_000L,
            )
        ) {
            Log.d(
                TAG,
                "reader_compositor_forward_warm_route path=${proof.normalizedPath} " +
                    "source=${proof.page.sourceIndex} index=$currentIndex",
            )
        }
        routeStrictAdjacentExactRehydrate(
            currentIndex,
            proof.page,
            visibleIntent = true,
            compositorForwardWarmIntent = true,
        )
    }

    /**
     * Converts a compositor-proven adjacent viewport into bounded physical source admission.
     *
     * Exact manifest authority still covers every source, but only visible sources and a small
     * bidirectional runway enter the network actor. Every later committed viewport advances this
     * window monotonically through source-demand epochs. Pages outside it remain BACKGROUND and
     * therefore own neither an HTTP call nor a parked socket.
     */
    private fun applyAdjacentStrictViewportSourceDemand(
        normalizedPath: String,
        claim: AdjacentStrictSourceClaim,
        firstVisibleSourceIndex: Int,
        lastVisibleSourceIndex: Int,
        direction: Int,
    ) {
        if (claim.pageCount <= 0 || !isAdjacentStrictSourceClaimLive(normalizedPath, claim)) return
        val first = minOf(firstVisibleSourceIndex, lastVisibleSourceIndex)
            .coerceIn(0, claim.pageCount - 1)
        val last = maxOf(firstVisibleSourceIndex, lastVisibleSourceIndex)
            .coerceIn(first, claim.pageCount - 1)
        val forward = direction >= 0
        val hard = if (forward) {
            (first..last).toList()
        } else {
            (first..last).toList().asReversed()
        }
        val primaryRunway = if (forward) {
            ((last + 1)..minOf(
                claim.pageCount - 1,
                last + NTK_ADJACENT_VIEWPORT_SOURCE_LOOKAHEAD,
            )).toList()
        } else {
            (maxOf(0, first - NTK_ADJACENT_VIEWPORT_SOURCE_LOOKAHEAD) until first)
                .toList()
                .asReversed()
        }
        val oppositeRunway = if (forward) {
            (maxOf(0, first - NTK_ADJACENT_VIEWPORT_OPPOSITE_LOOKAHEAD) until first)
                .toList()
                .asReversed()
        } else {
            ((last + 1)..minOf(
                claim.pageCount - 1,
                last + NTK_ADJACENT_VIEWPORT_OPPOSITE_LOOKAHEAD,
            )).toList()
        }
        val hardSet = hard.toHashSet()
        val soft = (primaryRunway + oppositeRunway).filterNot(hardSet::contains).distinct()
        val admitted = (hard + soft).toHashSet()
        val background = (0 until claim.pageCount).filterNot(admitted::contains)
        val signature = buildString {
            append(if (forward) 'F' else 'R')
            append('|')
            hard.joinTo(this, ",")
            append('|')
            soft.joinTo(this, ",")
        }
        val epoch = synchronized(claim) {
            if (claim.sourceDemandSignature == signature) return
            claim.sourceDemandSignature = signature
            ++claim.sourceDemandEpoch
        }
        claim.transport.applySourceDemand(
            claim.episode,
            NtkSourceDemandSnapshot(
                authority = claim.episode.value,
                demandEpoch = epoch,
                hardPages = hard.toIntArray(),
                softPages = soft.toIntArray(),
                backgroundPages = background.toIntArray(),
            ),
        )
    }

    /**
     * The immutable launch scene is the only source of first-frame pixels until an exact appended
     * episode is physically committed. That compositor proof transfers decoded-pixel ownership to
     * the normal budget/LRU permanently; encoded launch bodies and PageRefs remain independently
     * available for exact reverse rehydrate.
     */
    private fun releaseStrictLaunchPixelProtectionAfterSuccessorPresented() {
        if (!strictExactColdRolling ||
            !strictExactSuccessorPhysicallyPresented.compareAndSet(false, true)
        ) {
            return
        }
        try {
            control.execute {
                if (!cancelled.get()) trimDeliveredBitmapsToBudget()
            }
        } catch (_: RejectedExecutionException) {
            // Session teardown owns all delivered pixels after the control lane closes.
        }
    }

    fun onExactNtkPhysicalDrawPresented(
        firstVisibleDisplay: Int,
        lastVisibleDisplay: Int,
        direction: Int
    ) {
        if (!strictExactColdRolling || cancelled.get()) return
        // Capture exact immutable identities before the latest-only control mailbox can coalesce
        // this presentation with a newer layout report. Provisional placeholder heights can make
        // the latter claim that ten unrendered pages fit on screen; only a clean native frame is
        // authoritative for decoded-pixel residency. Structural cards and adjacent bodies are
        // deliberately excluded from the current launch's rolling pixel window.
        val published = publishedPageIndex.get()
        if (firstVisibleDisplay in published.indices &&
            lastVisibleDisplay in firstVisibleDisplay until published.size
        ) {
            var firstExact: PageRef? = null
            var lastExact: PageRef? = null
            for (displayIndex in firstVisibleDisplay..lastVisibleDisplay) {
                val candidate = published[displayIndex]
                if (candidate.transitionTitle == null && isStrictExactLaunchPage(candidate)) {
                    if (firstExact == null) firstExact = candidate
                    lastExact = candidate
                }
            }
            if (firstExact != null && lastExact != null) {
                val exactLast = checkNotNull(lastExact)
                latestExactCompositorWindow.set(
                    ExactCompositorWindow(
                        firstPage = checkNotNull(firstExact),
                        lastPage = exactLast,
                        direction = direction,
                    )
                )
                val nextSource = exactLast.sourceIndex + 1
                val warmPage = if (direction >= 0) {
                    published.firstOrNull { candidate ->
                        candidate.transitionTitle == null &&
                            isStrictExactLaunchPage(candidate) &&
                            candidate.sourceIndex == nextSource
                    }
                } else {
                    null
                }
                latestExactLaunchCompositorForwardWarm.set(
                    warmPage?.let { page ->
                        ExactLaunchCompositorForwardWarm(
                            visibleLastSourceIndex = exactLast.sourceIndex,
                            page = page,
                        )
                    },
                )
            }
        }
        // Native presentation arrives through the Activity's main-thread semantic listener.
        // Never make input wait for the session page-table monitor here: adjacent publication,
        // pixel retirement and budget trimming legitimately hold that monitor on ReaderControl.
        // The latest-only control mailbox already preserves the newest physical viewport, so its
        // owner can derive the same immutable page evidence after admission without weakening the
        // compositor proof or reordering it with the rolling-window transaction below.
        val scheduleDrain = strictRollingControlMailbox.offerPhysicalDraw(
            firstVisibleDisplay,
            lastVisibleDisplay,
            direction
        )
        if (scheduleDrain) scheduleStrictRollingControlDrain()
    }

    /**
     * The current-launch counterpart of adjacent compositor warming. It proves only source+1 from
     * an immutable clean frame and never creates byte demand; the normal admission/retention
     * window remains authoritative for whether that already-resident body may decode.
     */
    private fun isLatestExactLaunchCompositorForwardWarm(
        index: Int,
        page: PageRef,
    ): Boolean {
        val proof = latestExactLaunchCompositorForwardWarm.get() ?: return false
        if (proof.page !== page || page.sourceIndex != proof.visibleLastSourceIndex + 1 ||
            !isStrictExactLaunchPage(page)
        ) return false
        val window = latestExactCompositorWindow.get() ?: return false
        if (window.direction < 0 || window.lastPage.sourceIndex != proof.visibleLastSourceIndex) {
            return false
        }
        val currentIndex = currentPageIndex(page, index)
        return currentIndex >= 0 && pageRef(currentIndex) === page
    }

    private fun applyExactNtkPhysicalDrawPresented(
        firstVisibleDisplay: Int,
        lastVisibleDisplay: Int,
        direction: Int
    ) {
        if (!strictExactColdRolling || cancelled.get()) return
        // HWUI commit callbacks prove that the initial real pixels reached a frame. They are not
        // viewport-control events. Once the gate is open, a callback can lag the latest scroll
        // window and must not regress its anchor or replace its source demand.
        val previous = strictRollingAdmission.get() ?: return
        if (!previous.shouldOpenPhysicalDrawGate()) return
        val launchSeal = strictExactLaunchSeal ?: return
        var displayCount = 0
        var firstPresentedLaunchDisplay = -1
        var physicalForwardEvidence: PageRef? = null
        val visibleSources = IntArray(
            (lastVisibleDisplay - firstVisibleDisplay + 1).coerceAtLeast(0),
        )
        var visibleSourceCount = 0
        synchronized(pagesLock) {
            displayCount = pages.size
            if (firstVisibleDisplay !in 0 until displayCount ||
                lastVisibleDisplay !in firstVisibleDisplay until displayCount
            ) return
            for (displayIndex in firstVisibleDisplay..lastVisibleDisplay) {
                val page = pages[displayIndex]
                if (page.transitionTitle != null) continue
                if (isStrictExactLaunchPage(page)) {
                    if (firstPresentedLaunchDisplay < 0) {
                        firstPresentedLaunchDisplay = displayIndex
                    }
                    visibleSources[visibleSourceCount++] = page.sourceIndex
                }
                if (direction == ReaderSurfaceView.DIRECTION_NEXT && page.sourceIndex >= 0 &&
                    (physicalForwardEvidence == null ||
                        page.sourceIndex > checkNotNull(physicalForwardEvidence).sourceIndex)
                ) {
                    physicalForwardEvidence = page
                }
            }
        }
        physicalForwardEvidence?.let { evidence ->
            latestPhysicalForwardBoundaryPage.getAndUpdate { prior ->
                if (prior != null &&
                    looseSameEpisodeForAppend(prior.manga, evidence.manga) &&
                    prior.sourceIndex >= evidence.sourceIndex
                ) {
                    prior
                } else {
                    evidence
                }
            }
            activeRemainingAdjacentRunwayTargetPath(evidence.manga)
                .takeIf(String::isNotEmpty)
                ?.let(::wakeStrictRemainingAdjacentAppend)
        }
        // The first HWUI callback is coalesced on the latest-only control mailbox. A fast physical
        // fling can therefore present p0, advance to p4, and replace that callback before this
        // worker enters pagesLock. Requiring the launch anchor in the later visible range strands
        // every rolling decoder behind a frame that already happened. Any exact PageRef belonging
        // to this immutable launch seal is equally strong compositor evidence; adjacent episodes
        // are excluded by the full episode/source identity check above.
        if (visibleSourceCount <= 0) return
        for (index in 0 until visibleSourceCount) {
            val sourceIndex = visibleSources[index]
            if (sourceIndex !in launchSeal.canonicalAssets.indices) return
        }
        strictExactInitialPhysicalFramePresentedAtMs.compareAndSet(
            0L,
            SystemClock.elapsedRealtime(),
        )
        strictExactInitialPhysicalFramePresented.countDown()
        viewerActivated.compareAndSet(false, true)
        currentViewportAnchor.set(firstPresentedLaunchDisplay)
        val episode = strictExactEpisodeToken ?: return
        strictExactSourceTransport.get()?.onFirstActualFramePresented(episode)
        // The current manifest and first compositor-proven pixels are authoritative now. Resolve
        // only the exact next episode's document while the user reads the current chapter. The
        // current image body wave remains untouched; adjacent image bodies and decode still wait
        // for current-episode completion. This overlaps the multi-second tokenized-document RTT
        // that otherwise begins only after a fast reader has already reached the tail.
        (title ?: manga.title)?.let { currentTitle ->
            maybeStartInitialAdjacentMetadataPrefetch(
                manga,
                currentTitle,
                "first_actual_frame"
            )
        }
        // This is the first compositor-proven canonical pixel. Starting only the bounded
        // adjacent runway here cannot hide viewer entry and gives a continuous forward reader a
        // real chance to cross the episode boundary without an empty frame.
        maybeStartInitialTailAdjacentPreappend(
            manga,
            currentStartPage(),
            displayCount,
            "first_actual_frame"
        )
        // The first proof uses the normal window transaction to make the gate transition atomic
        // with its initial post-draw demand. Every later demand comes only from a WindowEvent.
        requestStrictExactColdWindow(
            firstVisibleDisplay,
            lastVisibleDisplay,
            firstVisibleDisplay,
            busy = false,
            retainWindow = true,
            pageCount = displayCount,
            committedDirection = direction,
            physicalDrawPresentedOverride = true
        )
    }

    fun snapshotState(): SessionStateSnapshot {
        val pageCount = synchronized(pagesLock) { pages.size }
        val delivered = synchronized(deliveredBitmaps) {
            Triple(deliveredBitmaps.size, deliveredTiles.size, deliveredBitmapBytesLocked())
        }
        return SessionStateSnapshot(
            cancelled = cancelled.get(),
            viewerActivated = viewerActivated.get(),
            pageCount = pageCount,
            loadingPages = loadingPages.size,
            urgentLoadingPages = urgentLoadingPages.size,
            bytePrefetchingPages = bytePrefetching.size,
            pendingDeliveries = deliveryQueue.size + primedDeliveryBacklog.size +
                initialDeliveryBacklog.size + initialPreparedBacklog.size,
            deliveredBitmapPages = delivered.first,
            deliveredTilePages = delivered.second,
            deliveredBitmapBytes = delivered.third,
            retainedFirstPage = retainedFirstPage,
            retainedLastPage = retainedLastPage,
            retainedAnchorPage = retainedAnchorPage,
            physicalFirstPage = physicalDeliveryFirstPage,
            physicalLastPage = physicalDeliveryLastPage,
            protectedNetworkInUse = NTK_PROTECTED_NETWORK_PARALLELISM -
                protectedNumericNetworkGate.availablePermits(),
            protectedDecodeInUse = protectedNumericDecodeParallelism -
                protectedNumericDecodeGate.availablePermits()
        )
    }

    fun structuralPageCount(): Int =
        (pendingPublishedPageIndex.get() ?: publishedPageIndex.get()).size

    fun usesDirectWifiRollingResidency(): Boolean =
        strictExactDirectWifiRollingPixelResidency.get()

    /**
     * Admits the first source that physically intersects a restored viewport.
     *
     * A bookmark stores the progress page. Its saved offset can still expose one or more earlier
     * short pages, so using the bookmark as an immutable network floor leaves those real viewport
     * pixels permanently unavailable. This runtime floor only moves backward and the ordinary
     * strict admission/identity checks still own every request and drawable publication.
     */
    fun recordStrictExactPhysicalVisibleFloor(physicalFirstPage: Int) {
        if (!strictExactColdRolling || physicalFirstPage < 0 || cancelled.get()) return
        val pageIndex = publishedPageIndex.get()
        if (pageIndex.isEmpty()) return
        val bounded = physicalFirstPage.coerceIn(0, pageIndex.lastIndex)
        val first = pageIndex[bounded]
        if (!isStrictExactLaunchPage(first)) return
        val visibleFloor = first.sourceIndex.coerceAtLeast(0)
        var floorLowered = false
        while (true) {
            val current = strictActiveSourceFloor.get()
            if (visibleFloor >= current) break
            if (strictActiveSourceFloor.compareAndSet(current, visibleFloor)) {
                floorLowered = true
                break
            }
        }
        if (floorLowered) requestRetainedWindowAfterStructureChange()
    }

    /**
     * Preserves a compositor-proven reverse gesture before the latest-only control mailbox can
     * coalesce its busy MOVE with the following idle UP. This applies to every strict exact launch,
     * not only short webtoons: a resumed manhwa can otherwise move below its saved source floor
     * while that historical page remains inadmissible, and the clean-frame forward fence then has
     * no drawable page with which to release the user's return gesture.
     */
    fun recordStrictExactPhysicalReverseFloor(physicalFirstPage: Int) {
        if (!strictExactColdRolling || physicalFirstPage < 0 || cancelled.get()) return
        var floorLowered = false
        val pageIndex = publishedPageIndex.get()
        if (pageIndex.isNotEmpty()) {
            val bounded = physicalFirstPage.coerceIn(0, pageIndex.lastIndex)
            val first = pageIndex[bounded]
            if (!isStrictExactLaunchPage(first)) return
            val reverseFloor = (first.sourceIndex -
                StrictRollingAdmission.REVERSE_PREDECESSOR_SOURCE_COUNT).coerceAtLeast(0)
            while (true) {
                val current = strictActiveSourceFloor.get()
                if (reverseFloor >= current) break
                if (strictActiveSourceFloor.compareAndSet(current, reverseFloor)) {
                    floorLowered = true
                    break
                }
            }
        }
        // A direct strict restore callback may return before publishing another WindowEvent.
        // The floor transition itself must therefore own a durable, coalesced control redrive.
        if (floorLowered) requestRetainedWindowAfterStructureChange()
    }

    /**
     * Maps a physical display index to the first currently admitted launch source. A proven busy
     * reverse gesture instead keeps the exact physical index and widens the runtime source floor
     * by at most three predecessor sources. Display indexes can be renumbered after an episode is
     * pruned, so source identity -- never the raw display number -- owns this decision.
     */
    @JvmOverloads
    fun directWifiRollingForwardRequestStartPage(
        physicalFirstPage: Int,
        directionHint: Int = 0,
    ): Int {
        if (!strictExactDirectWifiRollingPixelResidency.get() || physicalFirstPage < 0) {
            return physicalFirstPage
        }
        val pageIndex = publishedPageIndex.get()
        if (pageIndex.isEmpty()) return physicalFirstPage
        val bounded = physicalFirstPage.coerceIn(0, pageIndex.lastIndex)
        val first = pageIndex[bounded]
        if (!isStrictExactLaunchPage(first)) return bounded
        return run {
            if (directionHint < 0) {
                val reverseFloor = (first.sourceIndex -
                    StrictRollingAdmission.REVERSE_PREDECESSOR_SOURCE_COUNT).coerceAtLeast(0)
                strictActiveSourceFloor.getAndUpdate { current -> minOf(current, reverseFloor) }
                return@run bounded
            }
            val activeFloor = strictActiveSourceFloor.get()
            if (first.sourceIndex >= activeFloor) return@run bounded
            (bounded..pageIndex.lastIndex).firstOrNull { index ->
                val page = pageIndex[index]
                isStrictExactLaunchPage(page) &&
                    page.sourceIndex >= activeFloor
            } ?: bounded
        }
    }

    /** Releases only decoded pixels outside the active physical window. */
    @JvmOverloads
    fun trimMemory(aggressive: Boolean = false): SessionStateSnapshot {
        val pageCount = synchronized(pagesLock) { pages.size }
        if (pageCount > 0) {
            val anchor = (currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage())
                .coerceIn(0, pageCount - 1)
            val first = if (physicalDeliveryLastPage >= physicalDeliveryFirstPage) {
                physicalDeliveryFirstPage.coerceIn(0, pageCount - 1)
            } else {
                anchor
            }
            val last = if (physicalDeliveryLastPage >= physicalDeliveryFirstPage) {
                physicalDeliveryLastPage.coerceIn(first, pageCount - 1)
            } else {
                anchor
            }
            evictDeliveredBitmaps(first, last, forcePressure = true)
            trimPendingProtectedNumericBitmaps(first, last)
        }
        ReaderImageCache.trimVolatileMemory(appContext, aggressive)
        val snapshot = snapshotState()
        ViewerTelemetry.setBitmapBytes(snapshot.deliveredBitmapBytes)
        return snapshot
    }

    private fun schedulePreparedPostActivationContinuationIfNeeded() {
        if (!viewerActivated.get() || cancelled.get()) return
        try {
            control.execute {
                startPreparedPostActivationContinuation()
            }
        } catch (_: RejectedExecutionException) {
            // A later Store publication or window request retries naturally.
        }
    }

    fun notePhysicalTouch(active: Boolean) {
        if (active) physicalScrollEverStarted.set(true)
        physicalTouchActive.set(active)
        NtkReaderTransferPacer.noteTouch(this, active)
        lastPhysicalTouchMs.set(SystemClock.uptimeMillis())
        noteUserInteraction()
        if (strictExactDirectWifiRollingPixelResidency.get()) {
            // ACTION_DOWN reaches the Activity before the Surface's coalesced busy WindowEvent.
            // This level closes that admission race. ACTION_UP releases only pointer ownership;
            // the Surface-motion level remains authoritative while a fling is alive.
            directWifiForwardPhysicalTouchActive.set(active)
            directWifiForwardSurfaceMotionAtMs.set(SystemClock.uptimeMillis())
        }
        if (active) cancelRedundantInitialAdjacentMetadataForPhysicalInput()
        if (!active) {
            // A release may expose pages prepared during the gesture. Drain them immediately;
            // scrolling itself remains unconstrained and decoded pixels are never held for an
            // artificial touch/UP boundary.
            scheduleDeliveryDrain()
            scheduleStrictAdjacentMotionDeferredWake()
        }
    }

    @JvmOverloads
    fun requestWindowAsync(
        first: Int,
        last: Int,
        anchor: Int,
        busy: Boolean,
        directionHint: Int = 0,
        physicalFirst: Int = first,
        physicalLast: Int = last,
    ) {
        if (cancelled.get()) return
        if (directionHint < 0) {
            // A real reverse gesture revokes the older forward drawable-prefix blocker. This is
            // deliberately keyed by Surface's sticky direction evidence rather than an inferred
            // anchor delta: geometry repair can move the clean viewport backward without user
            // reverse input, while an actual reverse must be allowed to abandon the missing page.
            latestCurrentLaunchBlockedForwardPage.set(null)
        }
        latestWindowIngressBusy.set(busy)
        val pageIndex = publishedPageIndex.get()
        if (!publishedWindowIngressGate.reserve(
                pageIndex,
                first,
                last,
                anchor,
                physicalFirst,
                physicalLast,
                busy,
                directionHint,
            )
        ) {
            return
        }
        publishReportedWindow(
            pageIndex,
            first,
            last,
            anchor,
            physicalFirst,
            physicalLast,
            busy,
            directionHint,
        )
        offerWindowAsync(first, last, anchor, busy, directionHint)
    }

    /**
     * Replays an otherwise identical window only when Surface proves that its physical viewport
     * still contains loading pixels. Normal high-rate traffic remains deduplicated by
     * [publishedWindowIngressGate]; this narrow recovery edge promotes existing PageRef
     * single-flights after pixel retirement without creating duplicate network ownership.
     */
    fun requestVisibleLoadingWindowAsync(
        first: Int,
        last: Int,
        anchor: Int,
        physicalFirst: Int,
        physicalLast: Int,
        busy: Boolean,
        directionHint: Int,
    ) {
        if (cancelled.get()) return
        // This callback is a pixel-liveness replay, not a physical-motion edge. Its snapshot can
        // have been captured while a structure mutation still reported the preceding busy level.
        // Only requestWindowAsync owns the latest physical busy state; otherwise a loading page can
        // resurrect motion after Surface has already published idle and park its own re-decode.
        val physicalBusy = latestWindowIngressBusy.get()
        val pageIndex = publishedPageIndex.get()
        if (pageIndex.isEmpty()) return
        publishReportedWindow(
            pageIndex,
            first,
            last,
            anchor,
            physicalFirst,
            physicalLast,
            physicalBusy,
            directionHint,
        )
        offerWindowAsync(first, last, anchor, physicalBusy, directionHint)
    }

    /**
     * Keeps the nearest forward body requested by real input until ReaderControl consumes it.
     *
     * The Surface emits a special physical range containing the first drawable-prefix blocker,
     * then ordinary frame/window traffic can report the literal viewport before the asynchronous
     * control lane runs. A plain latest-value write revoked that one-page authority and let the
     * decoded body be treated as speculative. Preserve only the forward frontier (never an
     * ever-growing union behind the viewport), and drop it as soon as the viewport moves beyond
     * it or an explicit reverse event arrives.
     */
    private fun publishReportedWindow(
        pageIndex: Array<PageRef>,
        first: Int,
        last: Int,
        anchor: Int,
        physicalFirst: Int,
        physicalLast: Int,
        busy: Boolean,
        directionHint: Int,
    ) {
        if (pageIndex.isEmpty()) {
            latestReportedWindow.set(null)
            return
        }
        val safeAnchor = anchor.coerceIn(0, pageIndex.lastIndex)
        val safeFirst = first.coerceIn(0, pageIndex.lastIndex)
        val safeLast = last.coerceIn(safeFirst, pageIndex.lastIndex)
        val safePhysicalFirst = physicalFirst.coerceIn(0, pageIndex.lastIndex)
        val safePhysicalLast = physicalLast.coerceIn(safePhysicalFirst, pageIndex.lastIndex)
        val boundedDirection = directionHint.coerceIn(-1, 1)
        publishPhysicalForwardIntentPage(
            pageIndex,
            safePhysicalFirst,
            safePhysicalLast,
            boundedDirection,
        )
        while (true) {
            val prior = latestReportedWindow.get()
            var retainedPhysicalLast = safePhysicalLast
            if (boundedDirection >= 0 && prior != null && prior.directionHint >= 0) {
                val priorAnchor = prior.anchorPage?.let { anchorPage ->
                    pageIndex.indexOfFirst { page -> page === anchorPage }
                } ?: -1
                if (priorAnchor in pageIndex.indices) {
                    val priorLast = (priorAnchor + prior.physicalLastOffset)
                        .coerceIn(0, pageIndex.lastIndex)
                    // Blocked-forward evidence is at most two indexes beyond the literal tail
                    // (one transition card plus one body). Do not retain arbitrary stale runway.
                    if (priorLast >= safePhysicalFirst &&
                        priorLast <= safePhysicalLast + 2
                    ) {
                        retainedPhysicalLast = maxOf(retainedPhysicalLast, priorLast)
                    }
                }
            }
            val replacement = ReportedWindow(
                anchorPage = pageIndex[safeAnchor],
                fallbackAnchor = safeAnchor,
                firstOffset = safeFirst - safeAnchor,
                lastOffset = safeLast - safeAnchor,
                physicalFirstOffset = safePhysicalFirst - safeAnchor,
                physicalLastOffset = retainedPhysicalLast - safeAnchor,
                busy = busy,
                directionHint = boundedDirection,
            )
            if (latestReportedWindow.compareAndSet(prior, replacement)) return
        }
    }

    private fun publishPhysicalForwardIntentPage(
        pageIndex: Array<PageRef>,
        physicalFirst: Int,
        physicalLast: Int,
        directionHint: Int,
    ) {
        if (directionHint < 0) {
            latestPhysicalForwardIntentPage.set(null)
            return
        }
        val candidate = (physicalLast downTo physicalFirst)
            .asSequence()
            .map(pageIndex::get)
            .firstOrNull { page ->
                page.transitionTitle == null &&
                    strictAdjacentRehydrateIdentity(page) != null
            }
            ?: return
        latestPhysicalForwardIntentPage.getAndUpdate { prior ->
            val priorStillPublished = prior != null && pageIndex.any { current -> current === prior }
            if (priorStillPublished &&
                looseSameEpisodeForAppend(checkNotNull(prior).manga, candidate.manga) &&
                prior.sourceIndex >= candidate.sourceIndex
            ) {
                prior
            } else {
                candidate
            }
        }
    }

    /** Caller holds [pagesLock]; maps the Surface's exact viewport through prefix compaction. */
    private fun reportedPhysicalWindowLocked(
        fallbackAnchor: Int,
        fallbackFirst: Int,
        fallbackLast: Int,
    ): IntRange {
        check(Thread.holdsLock(pagesLock))
        if (pages.isEmpty()) return IntRange.EMPTY
        val safeFallbackAnchor = fallbackAnchor.coerceIn(0, pages.lastIndex)
        val safeFallbackFirst = fallbackFirst.coerceIn(0, pages.lastIndex)
        val safeFallbackLast = fallbackLast.coerceIn(safeFallbackFirst, pages.lastIndex)
        val reported = latestReportedWindow.get() ?: return safeFallbackFirst..safeFallbackLast
        val reportedAnchor = reported.anchorPage?.let { page ->
            pageIndexLocked(page, reported.fallbackAnchor)
        } ?: -1
        if (reportedAnchor !in pages.indices) return safeFallbackFirst..safeFallbackLast
        val first = (reportedAnchor + reported.physicalFirstOffset).coerceIn(0, pages.lastIndex)
        val last = (reportedAnchor + reported.physicalLastOffset).coerceIn(first, pages.lastIndex)
        return first..last
    }

    /**
     * Caller holds [pagesLock]. Decoded rolling pixels follow only the last compositor-proven
     * current-launch span. Before the first proof, admit at most the cold launch pair; never trust
     * placeholder geometry to widen that fallback. A real forward drag may add exactly one missing
     * body immediately after the proven span, identified by PageRef rather than a mutable index.
     */
    private fun compositorProvenStrictExactPixelWindowLocked(
        fallbackAnchor: Int,
        fallbackFirst: Int,
        fallbackLast: Int,
    ): IntRange {
        check(Thread.holdsLock(pagesLock))
        if (pages.isEmpty()) return IntRange.EMPTY
        val safeFallbackAnchor = fallbackAnchor.coerceIn(0, pages.lastIndex)
        val safeFallbackFirst = fallbackFirst.coerceIn(0, pages.lastIndex)
        val safeFallbackLast = fallbackLast.coerceIn(safeFallbackFirst, pages.lastIndex)
        val coldFirst = safeFallbackAnchor.coerceIn(safeFallbackFirst, safeFallbackLast)
        val coldLast = minOf(safeFallbackLast, coldFirst + 1)
        val proof = latestExactCompositorWindow.get()
        val proofFirst = proof?.firstPage?.let { page -> pageIndexLocked(page, -1) } ?: -1
        val proofLast = proof?.lastPage?.let { page -> pageIndexLocked(page, -1) } ?: -1
        val base = if (proof != null &&
            proofFirst in pages.indices &&
            proofLast in proofFirst until pages.size &&
            pages[proofFirst] === proof.firstPage &&
            pages[proofLast] === proof.lastPage &&
            proof.firstPage.transitionTitle == null &&
            proof.lastPage.transitionTitle == null &&
            isStrictExactLaunchPage(proof.firstPage) &&
            isStrictExactLaunchPage(proof.lastPage)
        ) {
            proofFirst..proofLast
        } else {
            coldFirst..coldLast
        }
        val blocker = latestCurrentLaunchBlockedForwardPage.get() ?: return base
        val blockerIndex = pageIndexLocked(blocker, -1)
        return if (blockerIndex in base.last..minOf(pages.lastIndex, base.last + 1) &&
            pages[blockerIndex] === blocker &&
            blocker.transitionTitle == null &&
            isStrictExactLaunchPage(blocker)
        ) {
            base.first..maxOf(base.last, blockerIndex)
        } else {
            base
        }
    }

    /** Caller holds [pagesLock]; protects one page of input hysteresis on both viewport edges. */
    private fun reportedPhysicalDecodeProtectionWindowLocked(
        fallbackAnchor: Int,
        fallbackFirst: Int,
        fallbackLast: Int,
    ): IntRange {
        check(Thread.holdsLock(pagesLock))
        val physical = reportedPhysicalWindowLocked(
            fallbackAnchor,
            fallbackFirst,
            fallbackLast,
        )
        if (pages.isEmpty() || physical.isEmpty()) return physical
        val safeFallbackFirst = fallbackFirst.coerceIn(0, pages.lastIndex)
        val safeFallbackLast = fallbackLast.coerceIn(safeFallbackFirst, pages.lastIndex)
        val reported = latestReportedWindow.get()
        val reportedAnchor = reported?.anchorPage?.let { page ->
            pageIndexLocked(page, reported.fallbackAnchor)
        } ?: -1
        val requestedFirst: Int
        val requestedLast: Int
        if (reported != null && reportedAnchor in pages.indices) {
            requestedFirst = (reportedAnchor + reported.firstOffset).coerceIn(0, pages.lastIndex)
            requestedLast = (reportedAnchor + reported.lastOffset)
                .coerceIn(requestedFirst, pages.lastIndex)
        } else {
            requestedFirst = safeFallbackFirst
            requestedLast = safeFallbackLast
        }
        val protected = HostExactHardwareTilePoolPressurePolicy
            .physicalViewportWithImmediateInputFrontier(
                pageCount = pages.size,
                physicalVisibleFirst = physical.first,
                physicalVisibleLast = physical.last,
                requestedFirst = requestedFirst,
                requestedLast = requestedLast,
            )
        return if (protected[1] >= protected[0]) {
            protected[0]..protected[1]
        } else {
            physical
        }
    }

    /**
     * Caller holds [pagesLock]. Rehydration is narrower than decode protection: only pixels in
     * the Surface's physical-intent range may reclaim a slot retired under allocation pressure.
     * A blocked forward body is already included in that reported range by the Surface; adding
     * ordinary one-page decode hysteresis here immediately refills a slot that the next atomic
     * page batch still needs.
     */
    private fun reportedHostPressureRehydrateWindowLocked(
        fallbackAnchor: Int,
    ): IntRange {
        check(Thread.holdsLock(pagesLock))
        val physical = reportedPhysicalWindowLocked(
            fallbackAnchor = fallbackAnchor,
            fallbackFirst = fallbackAnchor,
            fallbackLast = fallbackAnchor,
        )
        if (pages.isEmpty() || physical.isEmpty() ||
            hostExactPoolPressureRetiredPages.isEmpty()
        ) return physical
        // Drawable-prefix clamping can stop the literal viewport one transition card before the
        // first pressure-retired body. That body can never become literally visible, so requiring
        // literal intersection creates a closed loop: the Surface waits for pixels while the
        // Session waits for the Surface to cross the missing pixels. Reuse the existing bounded
        // physical-intent contract and admit only the nearest retired body within its two-index
        // card allowance. Far speculative runway pages remain parked.
        val maximumBlockedForward = (physical.last + 2).coerceAtMost(pages.lastIndex)
        val blockedForward = hostExactPoolPressureRetiredPages.asSequence()
            .filter { index -> index in physical.last..maximumBlockedForward }
            .minOrNull()
            ?: return physical
        val intent = HostExactHardwareTilePoolPressurePolicy
            .physicalViewportIncludingBlockedForwardBody(
                pageCount = pages.size,
                physicalVisibleFirst = physical.first,
                physicalVisibleLast = physical.last,
                blockedForwardPage = blockedForward,
            )
        return if (intent[1] >= intent[0]) intent[0]..intent[1] else physical
    }

    private fun offerWindowAsync(
        first: Int,
        last: Int,
        anchor: Int,
        busy: Boolean,
        directionHint: Int,
    ) {
        if (cancelled.get()) return
        val scheduleDrain = strictRollingControlMailbox.offerWindow(
            first,
            last,
            anchor,
            busy,
            directionHint,
        )
        if (scheduleDrain) scheduleStrictRollingControlDrain()
    }

    private fun scheduleStrictRollingControlDrain() {
        try {
            control.execute(::drainStrictRollingControlMailbox)
        } catch (_: RejectedExecutionException) {
            strictRollingControlMailbox.clear()
        }
    }

    private fun drainStrictRollingControlMailbox() {
        while (!cancelled.get()) {
            val batch = strictRollingControlMailbox.pollBatch()
            if (batch == null) {
                if (strictRollingControlMailbox.finishDrainIfEmpty()) return
                continue
            }
            for (event in batch.events) {
                if (event.sequence <= strictRollingLastAppliedControlSequence) {
                    Log.e(
                        TAG,
                        "reader_ntk_strict_control_stale_drop sequence=${event.sequence}," +
                            "last=$strictRollingLastAppliedControlSequence,type=${event.javaClass.simpleName}"
                    )
                    continue
                }
                strictRollingLastAppliedControlSequence = event.sequence
                when (event) {
                    is StrictRollingControlMailbox.PhysicalDrawEvent ->
                        applyExactNtkPhysicalDrawPresented(
                            event.firstVisibleDisplay,
                            event.lastVisibleDisplay,
                            event.direction
                        )
                    is StrictRollingControlMailbox.WindowEvent ->
                        requestWindow(
                            event.first,
                            event.last,
                            event.anchor,
                            event.busy,
                            retainWindow = true,
                            directionHint = event.directionHint,
                        )
                }
            }
        }
        strictRollingControlMailbox.clear()
    }

    private fun requestWindow(
        first: Int,
        last: Int,
        anchor: Int,
        busy: Boolean,
        retainWindow: Boolean,
        directionHint: Int = 0,
    ) {
        if (cancelled.get()) return
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return
        val boundedAnchor = anchor.coerceIn(0, count - 1)
        val anchorPage = pageRef(boundedAnchor)
        val activeViewportPath = anchorPage?.manga?.ntkEpisodePath
            ?.trim()
            ?.takeIf { it.isNotEmpty() }
            ?: manga.ntkEpisodePath
        activeViewportPath?.let(::resumeParkedAdjacentRemainder)
        if (
            anchorPage != null &&
            !Manga.sameEpisodeIdentity(anchorPage.manga, manga) &&
            isNtkSource(anchorPage.manga, title)
        ) {
            ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
                activeViewportPath,
                NTK_ADJACENT_APPEND_FOREGROUND_PATH_TTL_MS,
                "active_viewport"
            )
        }
        val wasBusy = viewportBusy.getAndSet(busy)
        if (wasBusy != busy) NtkReaderTransferPacer.noteViewportMotion(this, busy)
        val now = SystemClock.uptimeMillis()
        if (busy) {
            lastUserInteractionMs.set(now)
            deliveryResumeAtMs.set(Long.MAX_VALUE)
            cancelNtkBackgroundFallbacksForActiveInput("window")
            if (!wasBusy && isImmediateNtkGeneratedUx()) {
                ReaderImageCache.pauseOtherNtkEpisodeActiveWork(
                    activeViewportPath,
                    "active-scroll"
                )
                val clearedPreparedEpisodes =
                    ReaderPreparedStore.clearOtherNtkEpisodeBitmaps(activeViewportPath)
                if (clearedPreparedEpisodes > 0) {
                    Log.d(
                        TAG,
                        "reader_ntk_active_scroll_clear_adjacent_prepared count=$clearedPreparedEpisodes"
                    )
                }
            }
        } else if (wasBusy) {
            deliveryResumeAtMs.set(now + IDLE_DELIVERY_RESUME_DELAY_MS)
            val idleSuffixPath = NtkStripDigests.normalizeEpisodePath(
                activeViewportPath.orEmpty(),
            )
            if (idleSuffixPath.isNotEmpty()) {
                // The first resume check above intentionally observed the old moving state. Give
                // the last physical input edge its existing 48 ms quiet fence, then consume this
                // exact busy->idle lifecycle edge once. A new gesture makes the callback a no-op;
                // a genuine pause completes the already verified foreground chapter instead of
                // leaving its final sources parked forever with no further descriptor event.
                val quietDelayMs = physicalTouchQuietRemainingMs(
                    NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS,
                ).coerceAtLeast(1L)
                main.postDelayed({
                    if (!cancelled.get() && !viewportBusy.get() &&
                        parkedAdjacentRemainderAppends.containsKey(idleSuffixPath)
                    ) {
                        wakeStrictRemainingAdjacentAppend(idleSuffixPath)
                    }
                }, quietDelayMs)
            }
            scheduleParkedInitialAdjacentRunwayWakeAfterPhysicalIdle()
            scheduleStrictAdjacentMotionDeferredWake()
        }
        if (isStructurePublishPending()) {
            requestHostPressureStablePrefixDuringAppendOnlyPublish(
                boundedAnchor,
            )
            return
        }
        requestLatestPhysicalForwardIntentPage()
        val retainedRedriveRevisionAtStart = retainedWindowRedriveRevisionSnapshot()
        if (strictExactColdRolling && anchorPage?.let(::isStrictExactLaunchPage) == true) {
            if (firstBitmapLogged.get()) {
                // The strict exact window has its own early return below. Start the bounded
                // adjacent runway before entering it, otherwise even a real tail viewport can
                // never reach the shared next-episode preparation path.
                maybeStartInitialTailAdjacentPreappendForAnchor(boundedAnchor, "window_tail")
            }
            requestStrictExactColdWindow(
                first,
                last,
                anchor,
                busy,
                retainWindow,
                count,
                retainedRedriveRevisionAtStart = retainedRedriveRevisionAtStart,
                directionHint = directionHint,
            )
            return
        }
        // A continuous reader is one protected numeric session even while its physical anchor is
        // a just-appended body/divider whose Manga metadata has not inherited the launch Title yet.
        // Reserve, validate and publish the transaction from one immutable decision; mixing the
        // page-scoped result here with the session-scoped result below produced ticket=0 followed
        // by an infinite protected-snapshot retry.
        val usesProtectedBitmapWindow =
            usesProtectedNumericNtkPipeline(anchorPage) || usesProtectedNumericNtkPipeline()
        val protectedBitmapWindowTransaction = synchronized(pagesLock) {
            if (retainWindow && pages.size == count && usesProtectedBitmapWindow) {
                protectedBitmapWindowRevision.incrementAndGet() to indexedStateGeneration.get()
            } else {
                0L to indexedStateGeneration.get()
            }
        }
        val protectedBitmapWindowTicket = protectedBitmapWindowTransaction.first
        val protectedBitmapWindowStructureGeneration = protectedBitmapWindowTransaction.second
        if (retainWindow && usesProtectedBitmapWindow &&
            protectedBitmapWindowTicket <= 0L
        ) {
            retryRetainedWindowAfterFailedCommit(retainedRedriveRevisionAtStart, "generic-ticket")
            return
        }
        var windowAnchor = anchor.coerceIn(0, count - 1)
        var windowFirstBase = first.coerceIn(0, count - 1)
        var windowLastBase = last.coerceIn(0, count - 1)
        if (
            isImmediateNtkGeneratedUx() &&
            !firstBitmapLogged.get()
        ) {
            val initialStart = currentStartPage().coerceIn(0, count - 1)
            if (
                initialStart >= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES &&
                windowAnchor < NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES &&
                kotlin.math.abs(initialStart - windowAnchor) > NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
            ) {
                Log.d(
                    TAG,
                    "reader_ntk_pre_first_window_anchor_correct old=$windowAnchor,new=$initialStart," +
                        "first=$first,last=$last,busy=$busy"
                )
                windowAnchor = initialStart
                windowFirstBase = initialStart
                windowLastBase = minOf(count - 1, initialStart + initialContinuousViewportAheadPages())
            }
        }
        val previousViewportAnchor = currentViewportAnchor.get()
        val incomingNeedsGeneratedDrawable =
            isImmediateNtkGeneratedUx() &&
                busy &&
                windowAnchor in 0 until count &&
                pageRef(windowAnchor)?.let { page ->
                    isNtkGeneratedImageUrl(page.image.orEmpty()) &&
                        !hasDeliveredOrPendingDrawable(windowAnchor)
                } == true
        if (
            isImmediateNtkGeneratedUx() &&
            previousViewportAnchor >= NTK_ACTIVE_VIEWPORT_BACKTRACK_MIN_PAGE &&
            windowAnchor <= previousViewportAnchor - NTK_ACTIVE_VIEWPORT_BACKTRACK_TOLERANCE_PAGES &&
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L &&
            directionHint >= 0 &&
            !busy &&
            !incomingNeedsGeneratedDrawable
        ) {
            Log.d(
                TAG,
                "reader_ntk_active_anchor_backtrack_ignored old=$previousViewportAnchor," +
                    "incoming=$windowAnchor,first=$first,last=$last,busy=$busy"
            )
            windowAnchor = previousViewportAnchor.coerceIn(0, count - 1)
            windowFirstBase = max(0, minOf(windowFirstBase, windowAnchor))
            windowLastBase = minOf(count - 1, maxOf(windowLastBase, windowAnchor))
        }
        currentViewportAnchor.set(windowAnchor)
        val activePath = pageRef(windowAnchor)?.manga?.ntkEpisodePath
            ?.let(NtkStripDigests::normalizeEpisodePath)
            .orEmpty()
        if (windowAnchor != previousViewportAnchor ||
            parkedAdjacentRemainderAppends.containsKey(activePath)
        ) {
            // Prefix/structure publication can replace the PageRef at the same numeric anchor
            // (most notably launch-tail -> incoming transition card). The physical WindowEvent
            // is still new evidence even when its integer anchor is unchanged, so re-evaluate a
            // parked exact suffix by identity rather than waiting for a numeric move that the
            // forward cap itself may prevent.
            resumeParkedAdjacentRemainder(activePath)
        }
        redriveParkedAdjacentRemaindersNearViewport(windowFirstBase, windowLastBase)
        // Stage the physical span locally. A protected transaction publishes it only together
        // with the same-generation retained/snapshot state below; otherwise a prefix mutation can
        // shift the current fields and then have this stale request overwrite them before failing.
        val physicalDeliveryFirstCandidate = minOf(windowFirstBase, windowAnchor)
            .coerceIn(0, count - 1)
        val physicalDeliveryLastCandidate = maxOf(windowLastBase, windowAnchor)
            .coerceIn(physicalDeliveryFirstCandidate, count - 1)
        if (firstBitmapLogged.get()) {
            maybeStartInitialTailAdjacentPreappendForAnchor(windowAnchor, "window_tail")
        }
        if (busy) {
            startInteractiveFullSourcePrefetch("scroll_window")
            requestActiveGeneratedScrollRunway(windowAnchor, count)
        }
        val windowFirstInput: Int
        val windowLastInput: Int
        val ntkWebtoon = isNtkWebtoonSource(manga, title)
        val ntkInitialAnchorWindow = isNtkSource(manga, title) &&
            firstBitmapLogged.get() &&
            windowAnchor == currentStartPage() &&
            first <= windowAnchor
        if (isNtkSource(manga, title) && !firstBitmapLogged.get()) {
            if (ntkWebtoon && isImmediateNtkGeneratedUx()) {
                windowFirstInput = windowFirstBase
                windowLastInput = minOf(
                    count - 1,
                    max(windowLastBase, windowAnchor + ntkPreFirstDrawableRunwayPages() - 1)
                )
            } else {
                windowFirstInput = windowAnchor
                windowLastInput = windowAnchor
            }
        } else if (ntkInitialAnchorWindow) {
            val interactiveInitial = ntkWebtoon &&
                isImmediateNtkGeneratedUx() &&
                (busy || ntkInitialInteractiveSettleRemainingMs() > 0L || viewportBusy.get())
            val initialAhead = if (interactiveInitial) {
                NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
            } else if (ntkWebtoon) {
                NTK_WEBTOON_INITIAL_DECODE_AHEAD_PAGES
            } else {
                NTK_INITIAL_DECODE_AHEAD_PAGES
            }
            windowFirstInput = windowFirstBase
            windowLastInput = minOf(count - 1, max(last, windowAnchor + initialAhead))
        } else {
            val restrictInitialGeneratedWindow = shouldRestrictInitialGeneratedWindowForRealUx(busy)
            windowFirstInput = windowFirstBase
            windowLastInput = if (ntkWebtoon && firstBitmapLogged.get()) {
                val ntkWindowAfter = if (busy) {
                    if (restrictInitialGeneratedWindow) {
                        NTK_INITIAL_INTERACTIVE_VIEWPORT_AHEAD_PAGES
                    } else {
                        NTK_WEBTOON_BUSY_WINDOW_AFTER
                    }
                } else {
                    if (restrictInitialGeneratedWindow) {
                        NTK_INITIAL_INTERACTIVE_VIEWPORT_AHEAD_PAGES
                    } else {
                        NTK_WEBTOON_WINDOW_AFTER
                    }
                }
                if (restrictInitialGeneratedWindow) {
                    minOf(count - 1, windowAnchor + ntkWindowAfter)
                } else {
                    minOf(count - 1, max(last, windowAnchor + ntkWindowAfter))
                }
            } else if (busy && isNtkSource(manga, title) && firstBitmapLogged.get()) {
                minOf(count - 1, last + NTK_BUSY_VISIBLE_EDGE_EXTRA_PAGES)
            } else if (isNtkSource(manga, title) &&
                firstBitmapLogged.get() &&
                isNtkGeneratedPageRef(windowAnchor)
            ) {
                minOf(count - 1, last + NTK_BUSY_VISIBLE_EDGE_EXTRA_PAGES)
            } else {
                last
            }
        }
        val requestList: List<Int>
        val generation: Int
        val safeFirst: Int
        val safeLast: Int
        val direction: Int
        synchronized(windowLock) {
            safeFirst = windowFirstInput.coerceIn(0, count - 1)
            safeLast = windowLastInput.coerceIn(safeFirst, count - 1)
            generation = windowGeneration.incrementAndGet()
            direction = resolveWindowDirection(
                previousAnchor = lastWindowAnchor,
                currentAnchor = windowAnchor,
                previousDirection = lastWindowDirection,
                directionHint = directionHint,
                busy = busy,
            )
            lastWindowAnchor = windowAnchor
            if (direction != 0) lastWindowDirection = direction
            requestList = windowOrder(safeFirst, safeLast, windowAnchor, direction)
        }
        val protectedBitmapWindow = if (retainWindow && usesProtectedBitmapWindow) {
            val bounds = protectedNumericBitmapWindowBoundsForSession(
                count,
                windowAnchor,
                direction,
                minOf(windowFirstBase, windowAnchor),
                maxOf(windowLastBase, windowAnchor),
            )
            bounds[0]..bounds[1]
        } else {
            null
        }
        if (retainWindow) {
            val retainFirst = protectedBitmapWindow?.first ?: safeFirst
            val retainLast = protectedBitmapWindow?.last ?: safeLast
            val retainedCommitted = if (protectedBitmapWindow != null) {
                synchronized(pagesLock) {
                    if (!publishProtectedBitmapWindowSnapshot(
                            ticket = protectedBitmapWindowTicket,
                            expectedStructureGeneration = protectedBitmapWindowStructureGeneration,
                            pageCount = count,
                            anchor = windowAnchor,
                            direction = direction,
                            first = retainFirst,
                            last = retainLast,
                            sourceGeneration = generation,
                        )
                    ) {
                        false
                    } else {
                        physicalDeliveryFirstPage = physicalDeliveryFirstCandidate
                        physicalDeliveryLastPage = physicalDeliveryLastCandidate
                        synchronized(deliveredBitmaps) {
                            retainedFirstPage = retainFirst
                            retainedLastPage = retainLast
                            retainedAnchorPage = windowAnchor.coerceIn(retainFirst, retainLast)
                        }
                        true
                    }
                }
            } else {
                physicalDeliveryFirstPage = physicalDeliveryFirstCandidate
                physicalDeliveryLastPage = physicalDeliveryLastCandidate
                synchronized(deliveredBitmaps) {
                    retainedFirstPage = retainFirst
                    retainedLastPage = retainLast
                    retainedAnchorPage = windowAnchor.coerceIn(retainFirst, retainLast)
                }
                true
            }
            if (!retainedCommitted) {
                retryRetainedWindowAfterFailedCommit(
                    retainedRedriveRevisionAtStart,
                    "generic-retained-commit",
                )
                return
            }
            // The structure transaction above must be atomic with the retained numeric indexes,
            // but decoded-pixel budgeting and pending-delivery pruning do not mutate [pages].
            // Keeping those O(resident pixels + queued deliveries) scans under pagesLock blocks
            // main-thread pageInfo() for an entire physical-scroll frame on long readers.
            if (protectedBitmapWindow != null) {
                trimDeliveredPixelsForRetainedWindow(retainFirst, retainLast)
                trimPendingProtectedNumericBitmaps(retainFirst, retainLast)
            }
            acknowledgeRetainedWindowRedrive(retainedRedriveRevisionAtStart)
            if (primedDeliveryBacklog.isNotEmpty()) scheduleDeliveryDrain()
        }
        if (busy) {
            val generatedWindow = isNtkGeneratedPageRef(windowAnchor)
            val generatedBusyPrefetchLast = if (generatedWindow) {
                val prefetchAfter = if (isImmediateNtkGeneratedUx() && isActiveGeneratedTouchOrQuiet()) {
                    NTK_ACTIVE_GENERATED_SOURCE_PREFETCH_AFTER
                } else {
                    NTK_GENERATED_BUSY_SOURCE_PREFETCH_AFTER
                }
                minOf(safeLast, windowAnchor + prefetchAfter)
            } else {
                safeLast
            }
            val busyVisibleRadius = if (ntkWebtoon) {
                NTK_WEBTOON_BUSY_VISIBLE_DECODE_RADIUS
            } else if (generatedWindow) {
                NTK_GENERATED_BUSY_VISIBLE_DECODE_RADIUS
            } else {
                BUSY_VISIBLE_DECODE_RADIUS
            }
            val restrictInitialGeneratedWindow = shouldRestrictInitialGeneratedWindowForRealUx(busy)
            val visibleFirst = if (restrictInitialGeneratedWindow) {
                windowAnchor
            } else if (direction < 0) {
                safeFirst
            } else {
                max(safeFirst, windowAnchor - busyVisibleRadius)
            }
            val visibleLast = if (restrictInitialGeneratedWindow) {
                val restrictedAhead = if (firstBitmapLogged.get() && isWithinFirstBitmapInputGrace()) {
                    1
                } else {
                    NTK_INITIAL_INTERACTIVE_VIEWPORT_AHEAD_PAGES
                }
                minOf(safeLast, windowAnchor + restrictedAhead)
            } else if (direction >= 0) {
                val decodeAhead = if (isNtkSource(manga, title) && !firstBitmapLogged.get()) {
                    if (ntkWebtoon && isImmediateNtkGeneratedUx()) {
                        ntkPreFirstDrawableRunwayPages() - 1
                    } else {
                        0
                    }
                } else if (ntkInitialAnchorWindow && ntkWebtoon) {
                    0
                } else if (ntkInitialAnchorWindow) {
                    NTK_INITIAL_PRIORITY_PAGES
                } else if (ntkWebtoon) {
                    NTK_WEBTOON_BUSY_DIRECTIONAL_DECODE_AHEAD
                } else if (generatedWindow) {
                    NTK_GENERATED_BUSY_DIRECTIONAL_DECODE_AHEAD
                } else {
                    BUSY_DIRECTIONAL_DECODE_AHEAD
                }
                minOf(safeLast, windowAnchor + decodeAhead)
            } else {
                minOf(safeLast, windowAnchor + busyVisibleRadius)
            }
            if (
                retainWindow &&
                protectedBitmapWindow == null &&
                isNtkSource(manga, title) &&
                firstBitmapLogged.get() &&
                isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)
            ) {
                val activeGeneratedEviction = isImmediateNtkGeneratedUx() && generatedWindow
                val initialRunwayRetainLast = if (
                    activeGeneratedEviction &&
                    (
                        ntkInitialInteractiveSettleRemainingMs() > 0L ||
                            isWithinFirstBitmapInputGrace() ||
                            !initialContinuousDrawableDelivered(currentStartPage())
                    )
                ) {
                    initialInteractiveRunwayLastIndex(count)
                } else {
                    -1
                }
                val retainFirst = if (activeGeneratedEviction) {
                    if (direction < 0) {
                        max(0, windowAnchor - NTK_ACTIVE_GENERATED_RETAIN_AHEAD_PAGES)
                    } else {
                        max(0, visibleFirst - NTK_ACTIVE_GENERATED_RETAIN_BEHIND_PAGES)
                    }
                } else {
                    visibleFirst
                }
                val retainLast = if (activeGeneratedEviction) {
                    if (direction < 0) {
                        minOf(
                            count - 1,
                            maxOf(visibleLast + NTK_ACTIVE_GENERATED_RETAIN_BEHIND_PAGES, initialRunwayRetainLast)
                        )
                    } else {
                        minOf(
                            count - 1,
                            maxOf(
                                visibleLast,
                                windowAnchor + NTK_ACTIVE_GENERATED_RETAIN_AHEAD_PAGES,
                                initialRunwayRetainLast
                            )
                        )
                    }
                } else {
                    visibleLast
                }
                synchronized(deliveredBitmaps) {
                    retainedFirstPage = retainFirst
                    retainedLastPage = retainLast
                    retainedAnchorPage = windowAnchor.coerceIn(retainFirst, retainLast)
                }
                if (activeGeneratedEviction) {
                    trimDeliveredPixelsForRetainedWindow(retainFirst, retainLast)
                }
            }
            val visible = if (generatedWindow && direction > 0) {
                forwardBiasedWindowOrder(visibleFirst, visibleLast, windowAnchor)
            } else {
                windowOrder(visibleFirst, visibleLast, windowAnchor, direction)
            }
            for (i in visible) {
                pageRef(i)?.let { page ->
                    if (
                        isImmediateNtkGeneratedUx() &&
                        isNtkGeneratedPageRef(i) &&
                        hasPageSourceReady(i, page) &&
                        !hasDeliveredOrPendingDrawable(i)
                    ) {
                        promoteVisibleGeneratedCachedDecode(i, page, "busy_window_source_ready")
                    }
                }
                requestPage(i, true, i == windowAnchor, generation)
            }
            if (!ntkInitialAnchorWindow && !restrictInitialGeneratedWindow) {
                for (i in requestList) {
                    if (generatedWindow && i > generatedBusyPrefetchLast) continue
                    if (!visible.contains(i)) pageRef(i)?.let { prefetchBusyPage(i, it, generation) }
                }
            }
            trimDecodedWidth(windowAnchor, true)
            if (!ntkInitialAnchorWindow && !restrictInitialGeneratedWindow) {
                maybePrefetchNtkSourceAround(windowAnchor, true)
            }
            return
        }
        if (ntkWebtoon) {
            val restrictInitialGeneratedWindow = shouldRestrictInitialGeneratedWindowForRealUx(busy)
            val visibleRadius = if (ntkInitialAnchorWindow) {
                0
            } else {
                NTK_WEBTOON_IDLE_VISIBLE_DECODE_RADIUS
            }
            val visibleFirst = max(safeFirst, windowAnchor - visibleRadius)
            val visibleLast = if (restrictInitialGeneratedWindow) {
                val restrictedAhead = if (firstBitmapLogged.get() && isWithinFirstBitmapInputGrace()) {
                    1
                } else {
                        initialContinuousViewportAheadPages()
                }
                minOf(safeLast, windowAnchor + restrictedAhead)
            } else {
                minOf(safeLast, windowAnchor + visibleRadius)
            }
            val decodeFirst = visibleFirst
            val decodeAhead = if (ntkInitialAnchorWindow || restrictInitialGeneratedWindow) {
                0
            } else {
                NTK_WEBTOON_IDLE_DECODE_AHEAD
            }
            val decodeLast = minOf(safeLast, windowAnchor + decodeAhead)
            val prefetchLast = if (isNtkGeneratedPageRef(windowAnchor)) {
                if (ntkInitialAnchorWindow) windowAnchor else minOf(safeLast, windowAnchor + NTK_GENERATED_BUSY_SOURCE_PREFETCH_AFTER)
            } else {
                safeLast
            }
            val visible = windowOrder(visibleFirst, visibleLast, windowAnchor, direction)
            for (i in visible) {
                pageRef(i)?.let { page ->
                    if (
                        isImmediateNtkGeneratedUx() &&
                        isNtkGeneratedPageRef(i) &&
                        hasPageSourceReady(i, page) &&
                        !hasDeliveredOrPendingDrawable(i)
                    ) {
                        promoteVisibleGeneratedCachedDecode(i, page, "idle_window_source_ready")
                    }
                }
                requestPage(i, busy = true, anchor = i == windowAnchor, generation)
            }
            for (i in requestList) {
                if (visible.contains(i)) continue
                val page = pageRef(i) ?: continue
                if (i in decodeFirst..decodeLast) {
                    requestPage(i, busy = false, anchor = i == windowAnchor, generation)
                } else if (i <= prefetchLast && !restrictInitialGeneratedWindow) {
                    prefetchBusyPage(i, page, generation)
                }
            }
            trimDecodedWidth(windowAnchor, busy)
            if (!restrictInitialGeneratedWindow) {
                maybePrefetchNtkSourceAround(windowAnchor, busy)
            }
            return
        }
        for (i in requestList) requestPage(i, busy, i == windowAnchor, generation)
        trimDecodedWidth(windowAnchor, busy)
        maybePrefetchNtkSourceAround(windowAnchor, busy)
    }

    private fun requestStrictExactColdWindow(
        first: Int,
        last: Int,
        anchor: Int,
        busy: Boolean,
        retainWindow: Boolean,
        pageCount: Int,
        committedDirection: Int? = null,
        physicalDrawPresentedOverride: Boolean? = null,
        directionHint: Int = 0,
        retainedRedriveRevisionAtStart: Long = retainedWindowRedriveRevisionSnapshot(),
    ) {
        if (pageCount <= 0 || cancelled.get()) return
        val launchSeal = strictExactLaunchSeal ?: return
        val safeAnchor = anchor.coerceIn(0, pageCount - 1)
        val visibleFirst = minOf(first, safeAnchor).coerceIn(0, pageCount - 1)
        val visibleLast = maxOf(last, safeAnchor).coerceIn(visibleFirst, pageCount - 1)
        val protectedBitmapWindowTransaction = synchronized(pagesLock) {
            if (retainWindow && pages.size == pageCount && usesProtectedNumericNtkPipeline()) {
                protectedBitmapWindowRevision.incrementAndGet() to indexedStateGeneration.get()
            } else {
                0L to indexedStateGeneration.get()
            }
        }
        val protectedBitmapWindowTicket = protectedBitmapWindowTransaction.first
        val protectedBitmapWindowStructureGeneration = protectedBitmapWindowTransaction.second
        if (retainWindow && usesProtectedNumericNtkPipeline() &&
            protectedBitmapWindowTicket <= 0L
        ) {
            retryRetainedWindowAfterFailedCommit(retainedRedriveRevisionAtStart, "strict-ticket")
            return
        }
        val previous = strictRollingAdmission.get()
            ?: StrictRollingAdmission.initial(
                launchSeal.pageCount,
                initialSource = strictForwardSourceFloor,
            )
        // The Activity records the reverse floor before publishing its latest-only WindowEvent.
        // If an immediate UP/forward callback coalesces that event, consume the monotonic floor
        // once here instead of losing a real physical reverse gesture.
        val pendingReverseFloor = strictActiveSourceFloor.get()
        val hasPendingReverseExpansion = pendingReverseFloor < previous.allowedFirstSource
        // Resolve the immutable blocker without nesting pagesLock inside windowLock. Several
        // renderer callbacks publish page-table state before recording their window direction,
        // so preserving the global lock order here is part of the scroll hot-path contract.
        val blockedForwardIndex = latestCurrentLaunchBlockedForwardPage.get()?.let { blocker ->
            synchronized(pagesLock) { pageIndexLocked(blocker, -1) }
        } ?: -1
        val direction: Int
        synchronized(windowLock) {
            direction = when {
                hasPendingReverseExpansion -> -1
                directionHint < 0 -> -1
                directionHint > 0 -> 1
                committedDirection != null -> if (committedDirection < 0) -1 else 1
                else -> resolveWindowDirection(
                    previousAnchor = lastWindowAnchor,
                    currentAnchor = safeAnchor,
                    previousDirection = lastWindowDirection,
                    directionHint = 0,
                    busy = busy,
                    blockedForwardIndex = blockedForwardIndex,
                ).takeIf { it != 0 } ?: 1
            }
            lastWindowAnchor = safeAnchor
            lastWindowDirection = direction
        }
        currentViewportAnchor.set(safeAnchor)
        val physicalVisibleRange = synchronized(pagesLock) {
            // Both logical and reported physical coordinates can contain provisional placeholder
            // heights. Pixel residency therefore follows the last clean native frame plus only the
            // immutable body that a real forward gesture proved is blocking that frame.
            compositorProvenStrictExactPixelWindowLocked(
                fallbackAnchor = safeAnchor,
                fallbackFirst = visibleFirst,
                fallbackLast = visibleLast,
            )
        }
        val rollingPixelDemandRange = NtkStrictRollingDecodeDemandPolicy
            .bridgePhysicalFrameToLogicalAnchor(
                physicalVisibleRange = physicalVisibleRange,
                logicalAnchor = safeAnchor,
                pageCount = pageCount,
            )
        val visibleSources = synchronized(pagesLock) {
            (visibleFirst..visibleLast)
                .mapNotNull { pages.getOrNull(it) }
                .filter { it.transitionTitle == null && isStrictExactLaunchPage(it) }
                .map { it.sourceIndex }
        }
        if (visibleSources.isEmpty()) {
            // The outer caller observed a launch page at [safeAnchor]. An empty launch-source
            // window therefore means the indexed page table changed after this transaction
            // reserved its revision. Do not leave that revision unpublished/fail-closed.
            retryRetainedWindowAfterFailedCommit(
                retainedRedriveRevisionAtStart,
                "strict-visible-sources-empty",
            )
            return
        }
        val physicalReverseFloor = StrictRollingAdmission.observedPhysicalReverseFloor(
            pendingReverseFloor,
            visibleSources.minOrNull() ?: pendingReverseFloor,
            direction,
            windowBusy = busy,
        )
        if (physicalReverseFloor < pendingReverseFloor) {
            strictActiveSourceFloor.getAndUpdate { current ->
                minOf(current, physicalReverseFloor)
            }
        }
        val effectiveReverseFloor = minOf(
            strictActiveSourceFloor.get(),
            pendingReverseFloor,
            physicalReverseFloor,
        )
        val allowReverseExpansion = effectiveReverseFloor < previous.allowedFirstSource
        val admission = StrictRollingAdmission.update(
            previous,
            launchSeal.pageCount,
            visibleFirst,
            visibleLast,
            visibleSources.minOrNull() ?: 0,
            visibleSources.maxOrNull() ?: 0,
            direction,
            physicalDrawPresented = physicalDrawPresentedOverride ?: previous.physicalDrawPresented,
            allowReverseExpansion = allowReverseExpansion,
            reverseSourceFloor = effectiveReverseFloor,
        )
        val admissionChanged = admission !== previous
        val sourceDemandChanged = admissionChanged && !previous.hasSameSourceDemand(admission)
        if (tryCommitStrictForwardSuffixWindow(
                launchSeal = launchSeal,
                previous = previous,
                admission = admission,
                admissionChanged = admissionChanged,
                sourceDemandChanged = sourceDemandChanged,
                pageCount = pageCount,
                retainWindow = retainWindow,
                safeAnchor = safeAnchor,
                direction = direction,
                visibleFirst = visibleFirst,
                visibleLast = visibleLast,
                physicalVisibleRange = physicalVisibleRange,
                protectedBitmapWindowTicket = protectedBitmapWindowTicket,
                protectedBitmapWindowStructureGeneration =
                    protectedBitmapWindowStructureGeneration,
                retainedRedriveRevisionAtStart = retainedRedriveRevisionAtStart,
            )
        ) return
        val transactionBitmapBounds = if (retainWindow && protectedBitmapWindowTicket > 0L) {
            if (strictExactRollingPixelResidency.get()) {
                // Rolling source admission can span the immutable launch manifest, but decoded
                // pixel admission is only the continuous physical-frame-to-logical-anchor
                // corridor. The compositor intentionally holds its last clean frame while a
                // reverse page is absent. Protecting only that stale physical span while decode
                // demand used the bridge made shouldSkipDecodeOutsideProtectedNumericWindow()
                // reject every page capable of replacing the frame. Use the exact same bounded
                // corridor for demand and lifetime ownership.
                intArrayOf(rollingPixelDemandRange.first, rollingPixelDemandRange.last)
            } else {
                protectedNumericBitmapWindowBoundsForSession(
                    pageCount,
                    safeAnchor,
                    direction,
                    visibleFirst,
                    visibleLast,
                )
            }
        } else {
            null
        }
        if (transactionBitmapBounds != null) {
            val published = synchronized(pagesLock) {
                publishProtectedBitmapWindowSnapshot(
                    ticket = protectedBitmapWindowTicket,
                    expectedStructureGeneration = protectedBitmapWindowStructureGeneration,
                    pageCount = pageCount,
                    anchor = safeAnchor,
                    direction = direction,
                    first = transactionBitmapBounds[0],
                    last = transactionBitmapBounds[1],
                    sourceGeneration = windowGeneration.get(),
                )
            }
            if (!published) {
                retryRetainedWindowAfterFailedCommit(
                    retainedRedriveRevisionAtStart,
                    "strict-initial-publish",
                )
                return
            }
        }
        // Body publication requests the admitted display indexes directly, so an unchanged
        // viewport must not advance the source epoch or repeat source demand. Rolling pixel
        // pressure is different: the Surface can release one exact drawable while the source
        // admission remains unchanged. Recheck only the current physical display window so that
        // its historic handoff bit is validated against Surface ownership and, when missing,
        // safely re-decoded from the already-admitted source.
        if (admission === previous) {
            if (admission.physicalDrawPresented && strictExactRollingPixelResidency.get()) {
                // Same source demand does not mean the same pixel demand. During reverse input
                // the source admission can already cover the whole historical range while the
                // logical anchor continues moving behind the compositor's held clean frame.
                // The old shortcut re-requested the bridge pages but left retainedFirst/Last at
                // the previous viewport, so each successful install was immediately selected for
                // retirement. Reuse the normal bounded pixel commit with sourceDemandChanged=false
                // to update retention, delivery and decode from one corridor transaction.
                finishStrictExactColdWindowDemand(
                    admission = admission,
                    sourceDemandChanged = false,
                    generation = windowGeneration.get(),
                    pageCount = pageCount,
                    retainWindow = retainWindow,
                    protectedBitmapWindowTicket = protectedBitmapWindowTicket,
                    protectedBitmapWindowStructureGeneration =
                        protectedBitmapWindowStructureGeneration,
                    retainedRedriveRevisionAtStart = retainedRedriveRevisionAtStart,
                    safeAnchor = safeAnchor,
                    direction = direction,
                    visibleFirst = visibleFirst,
                    visibleLast = visibleLast,
                    visibleSources = visibleSources,
                    transactionBitmapBounds = transactionBitmapBounds,
                    physicalVisibleRange = physicalVisibleRange,
                    busy = busy,
                )
                return
            }
            if (transactionBitmapBounds != null && !strictExactRollingPixelResidency.get()) {
                val committed = synchronized(pagesLock) {
                    if (!isProtectedBitmapWindowTransactionCurrent(
                            protectedBitmapWindowTicket,
                            protectedBitmapWindowStructureGeneration,
                            pageCount,
                        )
                    ) {
                        false
                    } else {
                        synchronized(deliveredBitmaps) {
                            retainedFirstPage = transactionBitmapBounds[0]
                            retainedLastPage = transactionBitmapBounds[1]
                            retainedAnchorPage = safeAnchor.coerceIn(
                                transactionBitmapBounds[0],
                                transactionBitmapBounds[1],
                            )
                        }
                        trimPendingProtectedNumericBitmaps(
                            transactionBitmapBounds[0],
                            transactionBitmapBounds[1],
                        )
                        true
                    }
                }
                if (!committed) {
                    retryRetainedWindowAfterFailedCommit(
                        retainedRedriveRevisionAtStart,
                        "strict-unchanged-commit",
                    )
                    return
                }
            }
            if (retainWindow) acknowledgeRetainedWindowRedrive(retainedRedriveRevisionAtStart)
            return
        }
        // Display-boundary jitter still updates pixel retention and visible decode requests, but
        // it must not invalidate the same physical source work. Reusing the generation keeps a
        // long 0-3/0-5 boundary oscillation from building an endless cancel/redecode queue.
        val generation = if (sourceDemandChanged) {
            windowGeneration.incrementAndGet()
        } else {
            windowGeneration.get()
        }
        strictRollingAdmission.set(admission)
        strictActiveSourceFloor.getAndUpdate { current ->
            minOf(current, admission.allowedFirstSource)
        }
        if (!strictExactRollingPixelResidency.get() &&
            listener.areAllAuthoritativeDrawablesInstalled(pageCount)
        ) {
            // Once the immutable full scene is physically installed, viewport motion has no
            // source/decode work left to schedule. The old path rescanned and re-requested all
            // 114 pages for every motion event; Perfetto measured one ReaderControl task at
            // 90.24 ms and the compositor consequently missed 132.32 ms. Keep only the anchor
            // and retention bookkeeping needed by the active renderer.
            val committed = if (retainWindow && protectedBitmapWindowTicket > 0L) {
                synchronized(pagesLock) {
                    if (!publishProtectedBitmapWindowSnapshot(
                            ticket = protectedBitmapWindowTicket,
                            expectedStructureGeneration = protectedBitmapWindowStructureGeneration,
                            pageCount = pageCount,
                            anchor = safeAnchor,
                            direction = direction,
                            first = 0,
                            last = pageCount - 1,
                            sourceGeneration = windowGeneration.get(),
                        )
                    ) {
                        false
                    } else {
                        physicalDeliveryFirstPage = 0
                        physicalDeliveryLastPage = pageCount - 1
                        synchronized(deliveredBitmaps) {
                            retainedFirstPage = 0
                            retainedLastPage = pageCount - 1
                            retainedAnchorPage = safeAnchor
                        }
                        true
                    }
                }
            } else {
                physicalDeliveryFirstPage = 0
                physicalDeliveryLastPage = pageCount - 1
                if (retainWindow) {
                    synchronized(deliveredBitmaps) {
                        retainedFirstPage = 0
                        retainedLastPage = pageCount - 1
                        retainedAnchorPage = safeAnchor
                    }
                }
                true
            }
            if (!committed) {
                retryRetainedWindowAfterFailedCommit(
                    retainedRedriveRevisionAtStart,
                    "strict-full-scene-commit",
                )
                return
            }
            if (retainWindow) acknowledgeRetainedWindowRedrive(retainedRedriveRevisionAtStart)
            return
        }
        finishStrictExactColdWindowDemand(
            admission = admission,
            sourceDemandChanged = sourceDemandChanged,
            generation = generation,
            pageCount = pageCount,
            retainWindow = retainWindow,
            protectedBitmapWindowTicket = protectedBitmapWindowTicket,
            protectedBitmapWindowStructureGeneration =
                protectedBitmapWindowStructureGeneration,
            retainedRedriveRevisionAtStart = retainedRedriveRevisionAtStart,
            safeAnchor = safeAnchor,
            direction = direction,
            visibleFirst = visibleFirst,
            visibleLast = visibleLast,
            visibleSources = visibleSources,
            transactionBitmapBounds = transactionBitmapBounds,
            physicalVisibleRange = physicalVisibleRange,
            busy = busy,
        )
    }

    private fun finishStrictExactColdWindowDemand(
        admission: StrictRollingAdmission,
        sourceDemandChanged: Boolean,
        generation: Int,
        pageCount: Int,
        retainWindow: Boolean,
        protectedBitmapWindowTicket: Long,
        protectedBitmapWindowStructureGeneration: Int,
        retainedRedriveRevisionAtStart: Long,
        safeAnchor: Int,
        direction: Int,
        visibleFirst: Int,
        visibleLast: Int,
        visibleSources: List<Int>,
        transactionBitmapBounds: IntArray?,
        physicalVisibleRange: IntRange,
        busy: Boolean,
    ) {
        if (sourceDemandChanged) applyStrictExactSourceDemand(admission)

        val rollingDecodeCorridor = NtkStrictRollingDecodeDemandPolicy
            .bridgePhysicalFrameToLogicalAnchor(
                physicalVisibleRange = physicalVisibleRange,
                logicalAnchor = safeAnchor,
                pageCount = pageCount,
            )
        val demandedDisplays = synchronized(pagesLock) {
            // Rolling residency needs source bytes for the admitted episode runway, but decoded
            // pixels only for the physical viewport and the continuous bridge to the latest
            // logical anchor. The compositor intentionally holds its last complete frame while a
            // retired reverse page is missing; using only that stale physical range would never
            // request the pixels needed to replace it. Iterating every admitted display on each
            // 60/90 Hz sample is still avoided, and the source transport independently fetches the
            // complete admitted byte range.
            val indexes = if (strictExactRollingPixelResidency.get()) {
                rollingDecodeCorridor
            } else {
                pages.indices
            }
            indexes.mapNotNull { index ->
                val page = pages.getOrNull(index) ?: return@mapNotNull null
                index.takeIf {
                    page.transitionTitle == null && isStrictExactLaunchPage(page) &&
                        admission.admitsSource(page.sourceIndex)
                }
            }
        }
        if (demandedDisplays.isEmpty()) {
            if (protectedBitmapWindowTicket > 0L) {
                retryRetainedWindowAfterFailedCommit(
                    retainedRedriveRevisionAtStart,
                    "strict-demand-empty",
                )
            }
            return
        }
        val demandFirst = demandedDisplays.minOrNull() ?: physicalVisibleRange.first
        val demandLast = demandedDisplays.maxOrNull() ?: physicalVisibleRange.last
        if (!retainWindow) {
            physicalDeliveryFirstPage = demandFirst
            physicalDeliveryLastPage = demandLast
        }

        var directWifiForwardWarmPage: Int? = null
        var exactLaunchCompositorForwardWarmPage: Int? = null
        if (retainWindow) {
            val rollingPixels = strictExactRollingPixelResidency.get()
            val directWifiRolling = strictExactDirectWifiRollingPixelResidency.get()
            // Adjacent exact pages at the launch tail are decoded through the same scoped pixel
            // admission used by the generic window path. Retention and pending-delivery pruning
            // must use that identical range; keeping only launch demand here caused every
            // successor decode to be cleared and immediately re-requested.
            val installableBounds = if (!rollingPixels) {
                transactionBitmapBounds ?: protectedNumericBitmapWindowBoundsForSession(
                    pageCount,
                    safeAnchor,
                    direction,
                    visibleFirst,
                    visibleLast,
                )
            } else {
                null
            }
            val retainedFirst = if (rollingPixels) {
                if (directWifiRolling) {
                    // Display indexes may be split views of one canonical source. On reverse,
                    // retain every display belonging to the visible source and at most three
                    // predecessor sources; never compare a source floor directly to a display
                    // index. Forward traversal keeps the exact physical window as before.
                    val physicalVisibleSources = synchronized(pagesLock) {
                        physicalVisibleRange.mapNotNull { index ->
                            pages.getOrNull(index)?.takeIf { page ->
                                page.transitionTitle == null && isStrictExactLaunchPage(page)
                            }?.sourceIndex
                        }
                    }
                    val visibleSourceFloor = physicalVisibleSources.minOrNull()
                        ?: visibleSources.minOrNull()
                        ?: 0
                    val retainedSourceFloor = if (direction < 0) {
                        maxOf(
                            admission.allowedFirstSource,
                            (visibleSourceFloor -
                                StrictRollingAdmission.REVERSE_PREDECESSOR_SOURCE_COUNT)
                                .coerceAtLeast(0),
                        )
                    } else {
                        visibleSourceFloor
                    }
                    val firstRetainedDisplay = synchronized(pagesLock) {
                        pages.withIndex().firstOrNull { (_, page) ->
                            page.transitionTitle == null && isStrictExactLaunchPage(page) &&
                                page.sourceIndex in retainedSourceFloor..visibleSourceFloor
                        }?.index
                    } ?: physicalVisibleRange.first
                    // Source-based reverse history is a useful extra cushion, but the compositor
                    // may still be holding a newer clean frame than the logical scroll anchor.
                    // Never let the direct-Wi-Fi specialization discard the continuous bridge
                    // that decode demand and protected ownership already require.
                    minOf(rollingDecodeCorridor.first, firstRetainedDisplay)
                } else {
                    // A missing reverse page makes the compositor deliberately preserve its
                    // last clean physical frame. The logical viewport can therefore already be
                    // several pages behind [physicalVisibleRange]. Decode demand and the
                    // protected publication snapshot use [rollingDecodeCorridor] to bridge that
                    // gap; retaining only the stale physical frame immediately recycled every
                    // successfully rehydrated bridge page and started an endless decode/install/
                    // retire loop. Pixel lifetime must cover the exact same continuous corridor.
                    maxOf(0, rollingDecodeCorridor.first - STRICT_OVERSIZED_BEHIND_PAGES)
                }
            } else {
                installableBounds?.get(0) ?: demandFirst
            }
            val retainedLast = if (rollingPixels) {
                minOf(
                    pageCount - 1,
                    rollingDecodeCorridor.last + ReaderStrictBitmapResidencyPolicy.forwardRetainAheadPages(
                        directWifiRolling = directWifiRolling,
                        ordinaryPages = STRICT_OVERSIZED_FORWARD_RUNWAY_PAGES,
                    ),
                )
            } else {
                installableBounds?.get(1) ?: demandLast
            }.coerceAtLeast(retainedFirst)
            if (rollingPixels && directWifiRolling && direction >= 0) {
                val compositorWarm = latestExactLaunchCompositorForwardWarm.get()
                val compositorWarmIndex = compositorWarm?.let { proof ->
                    synchronized(pagesLock) {
                        pageIndexLocked(proof.page, proof.page.pageIndex)
                    }
                } ?: -1
                if (compositorWarmIndex in retainedFirst..retainedLast &&
                    compositorWarm != null &&
                    admission.admitsSource(compositorWarm.page.sourceIndex) &&
                    isLatestExactLaunchCompositorForwardWarm(
                        compositorWarmIndex,
                        compositorWarm.page,
                    ) &&
                    !listener.isPageAuthoritativeDrawableCurrentlyInstalled(compositorWarmIndex)
                ) {
                    exactLaunchCompositorForwardWarmPage = compositorWarmIndex
                }
            }
            val physicalVisibleLast = physicalVisibleRange.last
            val ownsIdleForwardWarmGrant = directWifiRolling && !busy && direction >= 0 &&
                lastDirectWifiIdleForwardWarmVisibleLast.getAndSet(physicalVisibleLast) !=
                physicalVisibleLast
            if (ownsIdleForwardWarmGrant) {
                val residentForwardPages = HashSet<Int>()
                for (index in physicalVisibleLast + 1..retainedLast) {
                    if (listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)) {
                        residentForwardPages += index
                    }
                }
                directWifiForwardWarmPage = ReaderStrictBitmapResidencyPolicy
                    .nextIdleForwardWarmPage(
                        directWifiRolling = true,
                        busy = false,
                        direction = direction,
                        visibleLast = physicalVisibleLast,
                        retainedLast = retainedLast,
                        pageCount = pageCount,
                        residentPages = residentForwardPages,
                    )
                    ?.takeIf { index ->
                        synchronized(pagesLock) {
                            val page = pages.getOrNull(index)
                            page != null && page.transitionTitle == null &&
                                isStrictExactLaunchPage(page) &&
                                admission.admitsSource(page.sourceIndex)
                        }
                    }
                directWifiForwardWarmPage?.let { page ->
                    Log.d(
                        TAG,
                        "reader_direct_wifi_idle_forward_pixel_warm page=$page," +
                            "visibleLast=$physicalVisibleLast,retainedLast=$retainedLast",
                    )
                }
            }
            val commitRetainedWindow = {
                physicalDeliveryFirstPage = demandFirst
                physicalDeliveryLastPage = demandLast
                synchronized(deliveredBitmaps) {
                    retainedFirstPage = retainedFirst
                    retainedLastPage = retainedLast
                    retainedAnchorPage = safeAnchor.coerceIn(retainedFirst, retainedLast)
                }
                // The source admission window remains exact and bounded, but decoded pixels that
                // were just traversed are useful when the user reverses direction. Hard-evicting
                // every page outside the new demand range made a forward/reverse fling decode the
                // same original tiles repeatedly. Keep those stable-identity pages in the existing
                // access-ordered maps and retire only LRU entries when the production bitmap budget
                // requires it. ReaderSurfaceView still clears every page that budget trimming
                // actually releases, so a stale drawable cannot be rebound to another slot.
                if (directWifiRolling) {
                    trimDirectWifiLaunchPixelsOutsideWindow()
                }
                trimDeliveredBitmapsToBudget()
                trimPendingProtectedNumericBitmaps(retainedFirst, retainedLast)
            }
            val committed = if (protectedBitmapWindowTicket > 0L) {
                synchronized(pagesLock) {
                    if (!isProtectedBitmapWindowTransactionCurrent(
                            protectedBitmapWindowTicket,
                            protectedBitmapWindowStructureGeneration,
                            pageCount,
                        )
                    ) {
                        false
                    } else {
                        commitRetainedWindow()
                        true
                    }
                }
            } else {
                commitRetainedWindow()
                true
            }
            if (!committed) {
                retryRetainedWindowAfterFailedCommit(
                    retainedRedriveRevisionAtStart,
                    "strict-final-retained-commit",
                )
                return
            }
            acknowledgeRetainedWindowRedrive(retainedRedriveRevisionAtStart)
        }

        val order = buildList {
            addAll(windowOrder(demandFirst, demandLast, safeAnchor, direction))
            exactLaunchCompositorForwardWarmPage?.takeIf { it !in this }?.let(::add)
            directWifiForwardWarmPage?.takeIf { it !in this }?.let(::add)
        }
        for (index in order) {
            val physicalForwardWarm = index == directWifiForwardWarmPage
            if (!isStrictExactColdPageDemanded(index)) continue
            val visible = index in visibleFirst..visibleLast
            val physicallyVisible = HostExactHardwareTilePoolPressurePolicy
                .isPhysicalRehydrateEligible(
                    pageIndex = index,
                    physicalVisibleFirst = rollingDecodeCorridor.first,
                    physicalVisibleLast = rollingDecodeCorridor.last,
                )
            if (hostExactPoolPressureRetiredPages.contains(index)) {
                // The source admission can span the complete immutable chapter. A host-pressure
                // retirement must not therefore decode the same off-screen page again on the
                // next unchanged demand event and reclaim the slot it just freed. The reported
                // physical window is normally the re-entry authority; encoded bodies remain
                // resident. The one identity-bound physical-forward nominee is the exception:
                // waiting until it becomes visible turns its native allocation into a boundary
                // stall even though Surface nominated it several seconds earlier. This grant is
                // neither a retained-range wave nor a numeric look-ahead; exactly the same single
                // page selected above may reclaim its retired slot.
                if (!physicallyVisible && !physicalForwardWarm) continue
                // Pressure retirement records the marker under pagesLock, then clears the
                // listener slot asynchronously on main. Do not consume the marker while that
                // old authoritative drawable is still installed: requestPage() would adopt it,
                // and the queued clear would subsequently blank the physically visible page.
                if (listener.isPageAuthoritativeDrawableInstalled(index)) continue
                if (!hostExactPoolPressureRetiredPages.remove(index)) continue
            }
            if (strictExactColdRolling) {
                requestStrictExactSourcePage(
                    index = index,
                    anchor = index == safeAnchor,
                    generation = generation,
                    compositorForwardWarmIntent =
                        index == exactLaunchCompositorForwardWarmPage,
                    physicalForwardWarmIntent = physicalForwardWarm,
                )
            } else {
                requestPage(
                    index,
                    busy = visible || (busy && index == safeAnchor),
                    anchor = index == safeAnchor,
                    generation = generation,
                )
            }
        }
        trimDecodedWidth(safeAnchor, busy)
        if (sourceDemandChanged) {
            Log.d(
                TAG,
                "reader_ntk_strict_cold_demand generation=$generation,anchor=$safeAnchor," +
                    "epoch=${admission.epoch},sourceChanged=true,direction=$direction," +
                    "actual=${admission.physicalDrawPresented},visible=$visibleFirst-$visibleLast," +
                    "displayDemand=$demandFirst-$demandLast," +
                    "sourceDemand=${admission.allowedFirstSource}-${admission.allowedLastSource}"
            )
        }
    }

    private fun tryCommitStrictForwardSuffixWindow(
        launchSeal: StrictExactLaunchSeal,
        previous: StrictRollingAdmission,
        admission: StrictRollingAdmission,
        admissionChanged: Boolean,
        sourceDemandChanged: Boolean,
        pageCount: Int,
        retainWindow: Boolean,
        safeAnchor: Int,
        direction: Int,
        visibleFirst: Int,
        visibleLast: Int,
        physicalVisibleRange: IntRange,
        protectedBitmapWindowTicket: Long,
        protectedBitmapWindowStructureGeneration: Int,
        retainedRedriveRevisionAtStart: Long,
    ): Boolean {
        val rollingPixelResidency = strictExactRollingPixelResidency.get()
        val launchShapeBeforeSuffixProof = strictForwardSuffixLaunchShapeValid.get()
        val activeFloorBeforeSuffixProof = strictActiveSourceFloor.get()
        val suffixQueryEligible = launchShapeBeforeSuffixProof &&
            NtkStrictForwardSuffixFastPathPolicy.canQuery(
                rollingPixelResidency = rollingPixelResidency,
                physicalDrawPresented = admission.physicalDrawPresented,
                sourceDemandChanged = sourceDemandChanged,
                pageCount = pageCount,
                launchPageCount = launchSeal.pageCount,
                forwardSourceFloor = strictForwardSourceFloor,
                activeSourceFloorBeforeProof = activeFloorBeforeSuffixProof,
                allowedFirstSource = admission.allowedFirstSource,
                allowedLastSource = admission.allowedLastSource,
            )
        fun currentSuffixProofRevision(): Long =
            listener.currentStrictForwardSuffixProofRevision(
                episodePath = launchSeal.normalizedEpisodePath,
                discoveryGeneration = launchSeal.discoveryGeneration,
                manifestDigest = launchSeal.manifestDigest,
                pageCount = launchSeal.pageCount,
                firstSource = strictForwardSourceFloor,
                lastSource = launchSeal.pageCount - 1,
            )
        val suffixProofRevision = if (suffixQueryEligible) {
            currentSuffixProofRevision()
        } else {
            0L
        }
        val activeFloorAfterSuffixProof = strictActiveSourceFloor.get()
        val launchShapeAfterSuffixProof = strictForwardSuffixLaunchShapeValid.get()
        if (launchShapeBeforeSuffixProof && launchShapeAfterSuffixProof &&
            NtkStrictForwardSuffixFastPathPolicy.canCommit(
                    rollingPixelResidency = rollingPixelResidency,
                    physicalDrawPresented = admission.physicalDrawPresented,
                    sourceDemandChanged = sourceDemandChanged,
                    pageCount = pageCount,
                    launchPageCount = launchSeal.pageCount,
                    forwardSourceFloor = strictForwardSourceFloor,
                    activeSourceFloorBeforeProof = activeFloorBeforeSuffixProof,
                    activeSourceFloorAfterProof = activeFloorAfterSuffixProof,
                    allowedFirstSource = admission.allowedFirstSource,
                    allowedLastSource = admission.allowedLastSource,
                    suffixInstalled = suffixProofRevision > 0L,
            )
        ) {
                // Caller holds pagesLock. The Activity proof is revisioned so clear/reinstall of
                // the same identity cannot ABA-match the earlier O(1) query. Reverse-floor and
                // structure state are sampled at this final linearization point as well.
                fun isStrictForwardSuffixCommitProofCurrent(): Boolean {
                    if (pages.size != pageCount ||
                        indexedStateGeneration.get() != protectedBitmapWindowStructureGeneration
                    ) return false
                    return NtkStrictForwardSuffixFastPathPolicy.isCommitProofCurrent(
                        capturedProofRevision = suffixProofRevision,
                        currentProofRevision = currentSuffixProofRevision(),
                        forwardSourceFloor = strictForwardSourceFloor,
                        activeSourceFloor = strictActiveSourceFloor.get(),
                        launchShapeValid = strictForwardSuffixLaunchShapeValid.get(),
                        rollingPixelResidency = strictExactRollingPixelResidency.get(),
                    )
                }
                // The proof is published only for an unshifted one-display-per-source launch.
                // Its launch span is therefore 0..seal.last and can update the protected snapshot
                // without the full page-table scan used by the generic rolling structure path.
                val suffixBounds = if (retainWindow && protectedBitmapWindowTicket > 0L) {
                    strictExactScopedBitmapWindowBounds(
                        pageCount = pageCount,
                        anchor = safeAnchor,
                        direction = direction,
                        launchFirst = if (rollingPixelResidency) -1 else 0,
                        launchLast = if (rollingPixelResidency) -1 else launchSeal.pageCount - 1,
                    ).also { bounds ->
                        includePhysicalSpanInBitmapWindow(
                            bounds,
                            pageCount,
                            physicalVisibleRange.first,
                            physicalVisibleRange.last,
                        )
                        if (ntkInitialInteractiveSettleRemainingMs() > 0L) {
                            bounds[0] = minOf(
                                bounds[0],
                                currentStartPage().coerceIn(0, pageCount - 1),
                            )
                        }
                    }
                } else {
                    null
                }
                val committed = if (suffixBounds != null) {
                    synchronized(pagesLock) {
                        if (!isStrictForwardSuffixCommitProofCurrent() ||
                            !publishProtectedBitmapWindowSnapshot(
                                ticket = protectedBitmapWindowTicket,
                                expectedStructureGeneration =
                                    protectedBitmapWindowStructureGeneration,
                                pageCount = pageCount,
                                anchor = safeAnchor,
                                direction = direction,
                                first = suffixBounds[0],
                                last = suffixBounds[1],
                                sourceGeneration = windowGeneration.get(),
                            )
                        ) {
                            false
                        } else {
                            synchronized(deliveredBitmaps) {
                                retainedFirstPage = suffixBounds[0]
                                retainedLastPage = suffixBounds[1]
                                retainedAnchorPage = safeAnchor.coerceIn(
                                    suffixBounds[0],
                                    suffixBounds[1],
                                )
                            }
                            trimPendingProtectedNumericBitmaps(
                                suffixBounds[0],
                                suffixBounds[1],
                            )
                            val proofCurrent = isStrictForwardSuffixCommitProofCurrent()
                            if (proofCurrent && retainWindow) {
                                acknowledgeRetainedWindowRedrive(retainedRedriveRevisionAtStart)
                            }
                            proofCurrent
                        }
                    }
                } else {
                    synchronized(pagesLock) {
                        if (!isStrictForwardSuffixCommitProofCurrent()) {
                            false
                        } else {
                            if (retainWindow) {
                                synchronized(deliveredBitmaps) {
                                    retainedAnchorPage = if (
                                        retainedLastPage >= retainedFirstPage &&
                                        retainedFirstPage in 0 until pageCount
                                    ) {
                                        safeAnchor.coerceIn(
                                            retainedFirstPage,
                                            retainedLastPage.coerceAtMost(pageCount - 1),
                                        )
                                    } else {
                                        safeAnchor
                                    }
                                }
                            }
                            val proofCurrent = isStrictForwardSuffixCommitProofCurrent()
                            if (proofCurrent && retainWindow) {
                                acknowledgeRetainedWindowRedrive(retainedRedriveRevisionAtStart)
                            }
                            proofCurrent
                        }
                    }
                }
                if (!committed) {
                    retryRetainedWindowAfterFailedCommit(
                        retainedRedriveRevisionAtStart,
                        "strict-suffix-commit",
                    )
                    return true
                }
                if (admissionChanged) {
                    strictRollingAdmission.set(admission)
                    strictActiveSourceFloor.getAndUpdate { current ->
                        minOf(current, admission.allowedFirstSource)
                    }
                }
                if (strictExactDirectWifiRollingPixelResidency.get()) {
                    trimDirectWifiLaunchPixelsOutsideWindow()
                }
                return true
        }
        return false
    }

    private fun rehydrateSameStrictExactColdWindow(
        visibleFirst: Int,
        visibleLast: Int,
        safeAnchor: Int,
        admission: StrictRollingAdmission,
    ) {
        val generation = windowGeneration.get()
        val order = windowOrder(
            visibleFirst,
            visibleLast,
            safeAnchor,
            admission.direction,
        )
        for (index in order) {
            val rollingRetired = strictExactRollingRehydratePages.contains(index)
            val hostPressureRetired = hostExactPoolPressureRetiredPages.contains(index)
            if (!rollingRetired && !hostPressureRetired) continue
            if (!isStrictExactColdPageDemanded(index)) {
                strictExactRollingRehydratePages.remove(index)
                continue
            }
            // A release is recorded before the main-thread listener clears the Surface slot. An
            // unrelated same-window event can race that callback, so leave the pending index
            // intact while the exact drawable is still installed. The eviction callback's own
            // window request observes the cleared slot and becomes the sole re-decode claimant.
            if (listener.isPageAuthoritativeDrawableInstalled(index)) continue
            val claimed = if (hostPressureRetired) {
                hostExactPoolPressureRetiredPages.remove(index)
            } else {
                strictExactRollingRehydratePages.remove(index)
            }
            if (!claimed) continue
            strictExactRollingRehydratePages.remove(index)
            requestPage(
                index,
                busy = true,
                anchor = index == safeAnchor,
                generation = generation,
            )
        }
    }

    private fun requestActiveGeneratedScrollRunway(windowAnchor: Int, count: Int) {
        if (!isImmediateNtkGeneratedUx()) return
        if (count <= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return
        val anchor = windowAnchor.coerceIn(0, count - 1)
        val page = pageRef(anchor) ?: return
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return
        val now = SystemClock.elapsedRealtime()
        val previousAnchor = lastActiveGeneratedScrollRunwayAnchor.get()
        val previousAt = lastActiveGeneratedScrollRunwayAtMs.get()
        if (
            previousAnchor != Int.MIN_VALUE &&
            abs(anchor - previousAnchor) < NTK_ACTIVE_SCROLL_RUNWAY_ANCHOR_STEP &&
            now - previousAt < NTK_ACTIVE_SCROLL_RUNWAY_REPEAT_SUPPRESS_MS
        ) {
            return
        }
        lastActiveGeneratedScrollRunwayAnchor.set(anchor)
        lastActiveGeneratedScrollRunwayAtMs.set(now)
        requestGeneratedViewportProofAndRunwayBytes("active_scroll_window")
    }

    private fun startInteractiveFullSourcePrefetch(reason: String) {
        if (strictExactColdRolling) return
        if (!isImmediateNtkGeneratedUx()) return
        val count = synchronized(pagesLock) { pages.count { it.transitionTitle == null } }
        if (count <= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        val quietMs = interactiveFullSourceQuietRemainingMs()
        if (quietMs > 0L) {
            scheduleInteractiveFullSourcePrefetchAfterQuiet(reason, anchor, quietMs)
            if (!(reason == "scroll_window" && (isActiveGeneratedTouchOrQuiet() || viewportBusy.get()))) {
                logNtkPagePerf(
                    anchor.coerceIn(0, max(0, synchronized(pagesLock) { pages.size } - 1)),
                    "interactive_full_source_defer",
                    "reason=$reason,quietMs=$quietMs"
                )
            }
            return
        }
        val previous = lastInteractiveFullSourcePrefetchAnchor.get()
        if (previous != Int.MIN_VALUE && abs(anchor - previous) < NTK_INTERACTIVE_FULL_SOURCE_STEP) return
        lastInteractiveFullSourcePrefetchAnchor.set(anchor)
        runInteractiveFullSourcePrefetch(reason)
    }

    private fun interactiveFullSourceQuietRemainingMs(): Long {
        if (!isImmediateNtkGeneratedUx()) return 0L
        val now = SystemClock.uptimeMillis()
        if (isActiveGeneratedTouchOrQuiet() || viewportBusy.get()) {
            val activeQuiet = maxOf(
                readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS),
                readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS),
                ntkInitialInteractiveSettleRemainingMs()
            )
            return max(activeQuiet, NTK_INTERACTIVE_FULL_SOURCE_ACTIVE_QUIET_MS)
        }
        val touchQuiet = readerQuietRemainingMs(NTK_INTERACTIVE_FULL_SOURCE_IDLE_QUIET_MS)
        val firstDrawableAt = ntkFirstBitmapAtMs.get()
        val firstDrawableQuiet = if (firstDrawableAt > 0L) {
            (NTK_INTERACTIVE_FULL_SOURCE_IDLE_QUIET_MS - (now - firstDrawableAt)).coerceAtLeast(0L)
        } else {
            NTK_INTERACTIVE_FULL_SOURCE_IDLE_QUIET_MS
        }
        return max(touchQuiet, firstDrawableQuiet)
    }

    private fun scheduleInteractiveFullSourcePrefetchAfterQuiet(
        reason: String,
        anchor: Int,
        quietMs: Long
    ) {
        pendingInteractiveFullSourcePrefetchReason.set(reason)
        pendingInteractiveFullSourcePrefetchAnchor.set(anchor)
        if (!interactiveFullSourcePrefetchIdlePosted.compareAndSet(false, true)) return
        main.postDelayed({
            interactiveFullSourcePrefetchIdlePosted.set(false)
            if (cancelled.get()) return@postDelayed
            val pendingReason = pendingInteractiveFullSourcePrefetchReason.get() ?: return@postDelayed
            val pendingAnchor = pendingInteractiveFullSourcePrefetchAnchor.get()
            val remaining = interactiveFullSourceQuietRemainingMs()
            if (remaining > 0L) {
                scheduleInteractiveFullSourcePrefetchAfterQuiet(pendingReason, pendingAnchor, remaining)
                return@postDelayed
            }
            pendingInteractiveFullSourcePrefetchReason.set(null)
            pendingInteractiveFullSourcePrefetchAnchor.set(Int.MIN_VALUE)
            val previous = lastInteractiveFullSourcePrefetchAnchor.get()
            if (previous != Int.MIN_VALUE && abs(pendingAnchor - previous) < NTK_INTERACTIVE_FULL_SOURCE_STEP) {
                return@postDelayed
            }
            lastInteractiveFullSourcePrefetchAnchor.set(pendingAnchor)
            runInteractiveFullSourcePrefetch(pendingReason)
        }, max(64L, quietMs + NTK_INTERACTIVE_FULL_SOURCE_IDLE_EXTRA_DELAY_MS))
    }

    private fun runInteractiveFullSourcePrefetch(reason: String) {
        try {
            control.execute {
                if (!cancelled.get()) requestAllUndeliveredNtkPages("interactive_full_source_$reason")
            }
        } catch (_: RejectedExecutionException) {
            if (!cancelled.get()) requestAllUndeliveredNtkPages("interactive_full_source_$reason")
        }
    }

    private fun startImmediateGeneratedFullSourcePrefetch(reason: String, delayMs: Long = 0L) {
        if (strictExactColdRolling) return
        if (cancelled.get() || !isImmediateNtkGeneratedUx()) return
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty() || !isGeneratedOnlyNtkRefs(refs)) return
        if (!immediateGeneratedFullSourcePrefetchPosted.compareAndSet(false, true)) return
        main.postDelayed({
            immediateGeneratedFullSourcePrefetchPosted.set(false)
            if (!cancelled.get()) runImmediateGeneratedFullSourcePrefetchBatch(reason)
        }, delayMs)
    }

    private fun runImmediateGeneratedFullSourcePrefetchBatch(reason: String) {
        if (strictExactColdRolling) return
        if (cancelled.get() || !isImmediateNtkGeneratedUx()) return
        if (!firstDrawableDelivered.get()) {
            startImmediateGeneratedFullSourcePrefetch(
                reason,
                NTK_IMMEDIATE_GENERATED_SOURCE_PREFETCH_FIRST_DRAWABLE_POLL_MS
            )
            Log.d(
                TAG,
                "reader_ntk_immediate_full_source_wait_first_drawable reason=$reason"
            )
            return
        }
        val activeQuietMs = immediateGeneratedSourcePrefetchActiveQuietMs()
        if (activeQuietMs > 0L) {
            val delayMs = activeQuietMs.coerceIn(
                NTK_IMMEDIATE_GENERATED_SOURCE_PREFETCH_ACTIVE_RECHECK_MS,
                NTK_IMMEDIATE_GENERATED_SOURCE_PREFETCH_ACTIVE_MAX_RECHECK_MS
            )
            startImmediateGeneratedFullSourcePrefetch(reason, delayMs)
            Log.d(
                TAG,
                "reader_ntk_immediate_full_source_defer_active reason=$reason," +
                    "delayMs=$delayMs,quietMs=$activeQuietMs,anchor=${currentViewportAnchor.get()}"
            )
            return
        }
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty() || !isGeneratedOnlyNtkRefs(refs)) return
        val anchor = (currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage())
            .coerceIn(0, refs.lastIndex)
        val orderedIndexes = ArrayList<Int>(refs.size)
        for (index in anchor..refs.lastIndex) orderedIndexes.add(index)
        for (index in 0 until anchor) orderedIndexes.add(index)
        var scheduled = 0
        var active = 0
        var sourceReady = 0
        var needsMore = false
        val scheduledIndexes = ArrayList<Int>()
        for (index in orderedIndexes) {
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!isNtkGeneratedImageUrl(page.image.orEmpty())) continue
            if (skipKnownMissingNtkGeneratedPage(index, page, "immediate_full_source")) continue
            if (hasPageSourceReady(index, page)) {
                sourceReady++
                continue
            }
            if (scheduled >= NTK_IMMEDIATE_GENERATED_SOURCE_PREFETCH_BATCH_PAGES) {
                needsMore = true
                break
            }
            val image = page.image.orEmpty()
            if (
                fullEpisodeSourcePrefetching.contains(index) ||
                bytePrefetching.contains(index) ||
                initialInteractiveRunwayByteFetches.contains(index) ||
                ReaderImageCache.hasActiveInitialNtkGeneratedFetch(page.manga, image)
            ) {
                active++
                needsMore = true
                continue
            }
            forcePrefetchNtkPageSource(
                index,
                page,
                "immediate_full_source_$reason",
                allowDuringInitialInteractive = true
            )
            scheduled++
            needsMore = true
            if (scheduledIndexes.size < 32) scheduledIndexes.add(index)
        }
        Log.d(
            TAG,
            "reader_ntk_immediate_full_source_prefetch reason=$reason,anchor=$anchor," +
                "scheduled=$scheduled,active=$active,sourceReady=$sourceReady,total=${refs.size}," +
                "scheduledIndexes=${scheduledIndexes.joinToString("|")}"
        )
        if (!cancelled.get() && needsMore) {
            startImmediateGeneratedFullSourcePrefetch(
                reason,
                NTK_IMMEDIATE_GENERATED_SOURCE_PREFETCH_BATCH_DELAY_MS
            )
        }
    }

    private fun immediateGeneratedSourcePrefetchActiveQuietMs(): Long {
        if (!isImmediateNtkGeneratedUx()) return 0L
        return max(
            if (viewportBusy.get()) NTK_IMMEDIATE_GENERATED_SOURCE_PREFETCH_ACTIVE_RECHECK_MS else 0L,
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS)
        )
    }

    private fun shouldRestrictInitialGeneratedWindowForRealUx(busy: Boolean): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath) && manga.baseMode != MTitle.base_webtoon) {
            return false
        }
        if (!firstBitmapLogged.get()) return true
        if (isWithinFirstBitmapInputGrace()) return true
        return busy && shouldLimitImmediateGeneratedToViewport()
    }

    private fun isImmediateGeneratedShortPageRunway(): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkWebtoonSource(manga, title)) return false
        val drawHeight = ntkFirstDrawableDrawHeightPx.get()
        val height = max(1, viewerHeight)
        return drawHeight > 0 && drawHeight <= (height * 1.35f).toInt()
    }

    private fun isWithinFirstBitmapInputGrace(): Boolean {
        val firstBitmapAt = ntkFirstBitmapAtMs.get()
        if (firstBitmapAt <= 0L) return false
        return SystemClock.uptimeMillis() - firstBitmapAt < NTK_FIRST_BITMAP_FOLLOWUP_INPUT_GRACE_MS
    }

    private fun shouldLimitImmediateGeneratedToViewport(): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!firstBitmapLogged.get()) return true
        return false
    }

    private fun shouldThrottleGeneratedVisibleDuringFirstInput(
        index: Int,
        page: PageRef,
        visiblePriority: Boolean
    ): Boolean {
        if (!visiblePriority) return false
        if (!isWithinFirstBitmapInputGrace()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        if (hasDeliveredOrPendingDrawable(index)) return false
        if (ReaderImageCache.cachedFile(appContext, page.manga, page.image.orEmpty()) != null) return false
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        return index < anchor || index > anchor + 2
    }

    private fun shouldThrottleKpDescriptorVisibleBeforeFirstDrawable(
        index: Int,
        page: PageRef,
        visiblePriority: Boolean
    ): Boolean {
        if (!visiblePriority) return false
        if (firstBitmapLogged.get() || ntkFirstBitmapAtMs.get() > 0L) return false
        if (!isKpWebtoonSlugEpisodePath(manga.ntkEpisodePath)) return false
        if (!isNtkKpDescriptorImageUrl(page.image.orEmpty())) return false
        if (ReaderImageCache.cachedFile(appContext, page.manga, page.image.orEmpty()) != null) return false
        return index > 1
    }

    private fun beginStructurePublish() {
        structurePublishPending.incrementAndGet()
    }

    /** Caller owns [pagesLock] and has completed the current page-table mutation. */
    private fun capturePublishedPageIndexLocked() {
        check(Thread.holdsLock(pagesLock))
        val snapshot = pages.toTypedArray()
        if (isStructurePublishPending()) {
            pendingPublishedPageIndex.set(snapshot)
        } else {
            pendingPublishedPageIndex.set(null)
            publishedPageIndex.set(snapshot)
        }
    }

    private fun beginOwnedStructurePublish(): AtomicBoolean {
        beginStructurePublish()
        return AtomicBoolean(false)
    }

    private fun beginOwnedAppendOnlyStructurePublish(stablePrefixCount: Int): AtomicBoolean {
        check(stablePrefixCount >= 0)
        val owner = beginOwnedStructurePublish()
        appendOnlyStructurePublishStablePrefixCounts[owner] = stablePrefixCount
        return owner
    }

    private fun finishOwnedStructurePublish(owner: AtomicBoolean?) {
        if (owner?.compareAndSet(false, true) == true) {
            appendOnlyStructurePublishStablePrefixCounts.remove(owner)
            finishStructurePublish()
        }
    }

    private fun finishStructurePublish() {
        val remaining = structurePublishPending.updateAndGet { pending ->
            if (pending > 0) pending - 1 else 0
        }
        val progressCallbacks = synchronized(structureProgressCallbackLock) {
            if (structureProgressCallbacks.isEmpty()) {
                emptyList()
            } else {
                buildList(structureProgressCallbacks.size) {
                    while (structureProgressCallbacks.isNotEmpty()) {
                        add(structureProgressCallbacks.removeFirst())
                    }
                }
            }
        }
        if (progressCallbacks.isNotEmpty()) {
            main.post {
                progressCallbacks.forEach(Runnable::run)
            }
        }
        if (remaining == 0) {
            // The Surface callbacks for every overlapping structure owner have now completed.
            // Publishing is one atomic pointer swap and cannot reopen pagesLock on main.
            pendingPublishedPageIndex.getAndSet(null)?.let(publishedPageIndex::set)
            if (deliveryQueue.isNotEmpty()) scheduleDeliveryDrain()
            val stableCallbacks = synchronized(structureStableCallbackLock) {
                if (structureStableCallbacks.isEmpty()) {
                    emptyList()
                } else {
                    buildList(structureStableCallbacks.size) {
                        while (structureStableCallbacks.isNotEmpty()) {
                            add(structureStableCallbacks.removeFirst())
                        }
                    }
                }
            }
            if (stableCallbacks.isNotEmpty()) {
                main.post {
                    stableCallbacks.forEach(Runnable::run)
                }
            }
            scheduleRetainedWindowRedriveIfNeeded()
            redriveParkedAdjacentRemaindersAfterEvent()
        }
    }

    private fun isStructurePublishPending(): Boolean {
        return structurePublishPending.get() > 0
    }

    /**
     * Runs an Activity-owned reconciliation only after every queued Surface page-table mutation
     * has completed and [publishedPageIndex] exposes the matching numeric layout.  A removal
     * callback itself runs while the old public snapshot is intentionally still visible; reading
     * pageInfo() from that callback with a post-removal index can otherwise transiently adopt the
     * predecessor episode.
     */
    fun runAfterStructureStable(callback: Runnable) {
        if (cancelled.get()) return
        dispatchWhenStructureStable(
            Runnable {
                if (!cancelled.get()) callback.run()
            },
        )
    }

    /** Runs on main only after all queued Surface page-table mutations have completed. */
    private fun dispatchWhenStructureStable(callback: Runnable) {
        val deferred = synchronized(structureStableCallbackLock) {
            if (isStructurePublishPending()) {
                structureStableCallbacks.addLast(callback)
                true
            } else {
                false
            }
        }
        if (!deferred) {
            if (Looper.myLooper() === main.looper) {
                callback.run()
            } else {
                main.post(callback)
            }
        }
    }

    /** Rechecks a self-validating callback after the next structure owner completes. */
    private fun dispatchWhenStructureOwnerFinishes(callback: Runnable) {
        val deferred = synchronized(structureProgressCallbackLock) {
            if (isStructurePublishPending()) {
                structureProgressCallbacks.addLast(callback)
                true
            } else {
                false
            }
        }
        if (!deferred) {
            if (Looper.myLooper() === main.looper) {
                callback.run()
            } else {
                main.post(callback)
            }
        }
    }

    private data class AdjacentDrawableBatchPublication(
        val pageIdentities: Set<PageIdentity>,
    )

    private fun beginAdjacentDrawableBatchPublication(
        refs: List<PageRef>,
    ): AdjacentDrawableBatchPublication {
        val publication = AdjacentDrawableBatchPublication(
            refs.mapNotNull(::pageIdentity).toSet(),
        )
        publication.pageIdentities.forEach { identity ->
            adjacentDrawableBatchPublicationPages.compute(identity) { _, pending ->
                (pending ?: AtomicInteger(0)).also { it.incrementAndGet() }
            }
        }
        adjacentDrawableBatchPublicationPending.incrementAndGet()
        return publication
    }

    private fun finishAdjacentDrawableBatchPublication(
        publication: AdjacentDrawableBatchPublication,
    ) {
        publication.pageIdentities.forEach { identity ->
            adjacentDrawableBatchPublicationPages.computeIfPresent(identity) { _, pending ->
                pending.takeIf { it.decrementAndGet() > 0 }
            }
        }
        while (true) {
            val pending = adjacentDrawableBatchPublicationPending.get()
            if (pending <= 0) return
            val remaining = pending - 1
            if (!adjacentDrawableBatchPublicationPending.compareAndSet(pending, remaining)) {
                continue
            }
            if (remaining == 0 && !cancelled.get()) {
                // A viewport request can observe newly appended PageRefs before their atomic
                // drawable batch reaches Surface. It deliberately does not launch a duplicate
                // decode below; this redrive is the durable completion edge for either a commit
                // or rollback of that publication.
                requestRetainedWindowAfterStructureChange()
            }
            return
        }
    }

    private fun isAdjacentDrawableBatchPublicationPending(): Boolean {
        return adjacentDrawableBatchPublicationPending.get() > 0
    }

    private fun isAdjacentDrawableBatchPublicationPending(page: PageRef): Boolean {
        val identity = pageIdentity(page) ?: return false
        return (adjacentDrawableBatchPublicationPages[identity]?.get() ?: 0) > 0
    }

    private fun redriveParkedAdjacentRemaindersAfterEvent() {
        if (cancelled.get() || parkedAdjacentRemainderAppends.isEmpty()) return
        parkedAdjacentRemainderAppends.keys.toList().forEach(::wakeStrictRemainingAdjacentAppend)
    }

    private fun maybePrefetchNtkSourceAround(anchor: Int, busy: Boolean) {
        if (!isNtkSource(manga, title)) return
        if (!firstBitmapLogged.get()) return
        val previous = lastSourcePrefetchAnchor
        val generatedAnchor = busy && isNtkGeneratedPageRef(anchor)
        if (
            generatedAnchor &&
            isImmediateNtkGeneratedUx() &&
            isActiveGeneratedTouchOrQuiet()
        ) {
            return
        }
        val step = if (generatedAnchor) {
            NTK_GENERATED_BUSY_SOURCE_PREFETCH_STEP
        } else if (busy) {
            NTK_BUSY_SOURCE_PREFETCH_STEP
        } else {
            NTK_IDLE_SOURCE_PREFETCH_STEP
        }
        if (previous >= 0 && abs(anchor - previous) < step) return
        val after = if (generatedAnchor) {
            NTK_GENERATED_BUSY_SOURCE_PREFETCH_AFTER
        } else if (busy) {
            NTK_BUSY_SOURCE_PREFETCH_AFTER
        } else {
            NTK_IDLE_SOURCE_PREFETCH_AFTER
        }
        prefetchImageFilesAround(anchor, after)
    }

    private fun isNtkGeneratedPageRef(index: Int): Boolean {
        val page = pageRef(index) ?: return false
        return isNtkGeneratedDescriptorOrImagePage(page)
    }

    fun clearOutside(first: Int, last: Int) {
        val keep = if (usesProtectedNumericNtkPipeline()) protectedNumericBitmapWindow() else first..last
        decodedWidths.keys.removeAll { it < keep.first || it > keep.last }
        desiredWidths.keys.removeAll { it < keep.first || it > keep.last }
        sourceWidths.keys.removeAll { it < keep.first || it > keep.last }
        achievableWidths.keys.removeAll { it < keep.first || it > keep.last }
        evictDeliveredBitmaps(keep.first, keep.last)
        if (usesProtectedNumericNtkPipeline()) {
            trimPendingProtectedNumericBitmaps(keep.first, keep.last)
        }
    }

    fun cancel() {
        cancelInternal(null)
    }

    fun cancelPreservingNtkVolatileForPath(path: String?) {
        cancelInternal(path)
    }

    private fun cancelInternal(preserveNtkVolatilePath: String?) {
        if (!cancelled.compareAndSet(false, true)) return
        synchronized(hostLifecyclePixelLock) {
            hostLifecycleResumed = true
            hostLifecyclePixelLock.notifyAll()
        }
        strictExactInitialAnchorPixelsInstalled.countDown()
        strictExactInitialPhysicalFramePresented.countDown()
        NtkReaderTransferPacer.release(this)
        publishedWindowIngressGate.clear()
        hostExactPoolPressureSubscription?.close()
        hostExactPoolPressureTrimPosted.set(false)
        forwardPixelRetirementLedger.clear()
        releaseStrictRequiredEpisodePath("reader_session_cancel")
        strictExactResidentBodyBinding.getAndSet(null)?.close()
        strictExactSourceBinding.getAndSet(null)?.close()
        (strictExactSourceTransport.getAndSet(null) as? Closeable)?.close()
        strictExactBodyDescriptors.clear()
        adjacentExactP0Flights.values.toList().forEach { flight ->
            synchronized(flight) {
                adjacentExactP0Flights.remove(flight.owner.ownerToken, flight)
                if (!flight.headOwnedBySurface.get()) recycleAdjacentExactP0Delta(flight.head)
                // tailStarted reserves/submits the task, but shutdownNow() can discard an
                // accepted task before its Runnable enters. Only a worker that has actually
                // started owns terminal release; a queued task is still owned by cancel().
                if (!flight.tailWorkerStarted.get()) releaseAdjacentExactP0Flight(flight)
            }
        }
        adjacentStrictDescriptorBindingTokens.clear()
        adjacentStrictSourceClaims.values.forEach { claim ->
            synchronized(claim.terminalFailureObserved) {
                claim.terminalFailureObserved.set(true)
            }
            val watchdog = synchronized(claim) {
                claim.descriptorWaitWatchdogToken = null
                claim.descriptorWaitWatchdogWaiter = null
                claim.descriptorWaitWatchdogRunnable.also {
                    claim.descriptorWaitWatchdogRunnable = null
                }
            }
            watchdog?.let(main::removeCallbacks)
            runCatching { claim.sourceEventBinding.close() }
            runCatching { claim.residentBinding.close() }
            runCatching { (claim.transport as? Closeable)?.close() }
        }
        adjacentStrictSourceClaims.clear()
        adjacentStrictBodyDescriptors.clear()
        strictAdjacentRehydrateFlights.clear()
        strictAdjacentMotionDeferredWakePosted.set(false)
        main.removeCallbacks(strictAdjacentMotionDeferredWakeRunnable)
        waitingInitialAdjacentExactP0Appends.cancelAll()
        waitingInitialAdjacentManhwaRunwayAppends.cancelAll()
        initialAdjacentManhwaRunwayEventWakeKeys.clear()
        publishedExactAdjacentInitialRunwayCompletionPaths.clear()
        forwardAdjacentExactManifestSubscription.getAndSet(null)?.close()
        adjacentStrictRecoveryManifestSubscription.getAndSet(null)?.close()
        forwardAdjacentExactManifestAppendGate.clear()
        synchronized(forwardAdjacentCompletionTargetClaimLock) {
            forwardAdjacentCompletionTargetClaims.clear()
            forwardAdjacentValidatedRecoveryTombstones.clear()
            forwardAdjacentCompletionTargetHistory.clear()
        }
        adjacentStrictPredecessorPaths.clear()
        synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictRecoveryStates.clear()
        }
        strictExactDisplayIndexesBySource.clear()
        pendingStrictExactBounds.clear()
        strictExactBoundsDrainPosted.set(false)
        main.removeCallbacks(strictExactBoundsDrainRunnable)
        strictExactDecodeInFlight.clear()
        strictExactSplitSourceDecodeInFlight.clear()
        latestStrictExactPhysicalForwardWarmPage.set(null)
        strictExactRollingForwardWarmPromotedDecodes.clear()
        strictExactMotionDeferredPages.clear()
        strictExactMotionDeferredRetryPosted.set(false)
        main.removeCallbacks(strictExactMotionDeferredRetryRunnable)
        strictExactAuthoritativeHandoffPages.clear()
        strictExactRollingRehydratePages.clear()
        hostExactPoolPressureRetiredPages.clear()
        publishedExactOffscreenRunwayPaths.clear()
        enteredExactEpisodePixelCompletionPaths.clear()
        enteredExactEpisodePixelCompletionAuditPaths.clear()
        latestEnteredExactEpisodePath.set("")
        latestExactAdjacentCompositorForwardWarm.set(null)
        synchronized(pagesLock) {
            hostPressurePendingSurfaceRetirements.clear()
            hostPressureSurfaceRetirementsInFlight.clear()
        }
        strictExactBulkDecodeReleased.set(false)
        strictExactTerminalDecodeExpanded.set(false)
        strictExactOverlapDecodeAdmissions.set(0)
        strictExactDecodeAdmissions.set(0)
        strictExactDecodeTerminals.set(0)
        strictExactRequiredBitmapBytes.set(0L)
        earlyNtkImageUrlsUnregister?.invoke()
        earlyNtkImageUrlsUnregister = null
        viewportBusy.set(false)
        latestWindowIngressBusy.set(false)
        deliveryResumeAtMs.set(0L)
        lastUserInteractionMs.set(0L)
        lastPhysicalTouchMs.set(0L)
        urgentLoading.clear()
        visibleGeneratedByteHedges.clear()
        visibleGeneratedDecodeHedges.clear()
        initialAnchorAssetDecodeListenerKeys.clear()
        initialGeneratedAssetDecodeListeners.clear()
        strictInlineOriginalDecodeFlights.clear()
        visibleGeneratedCachedDecodeRetries.clear()
        initialGeneratedCachedDecodeInFlight.clear()
        initialGeneratedDirectDecodeInFlight.clear()
        initialInteractiveRunwayByteFetches.clear()
        initialAnchorDeliveryPosted.set(false)
        for (cancellation in repositoryCancellations.toList()) {
            cancellation.cancel()
        }
        imageCancellation.cancel()
        val preservePath = preserveNtkVolatilePath?.trim().orEmpty()
        if (
            preservePath.isNotEmpty() &&
            manga.ntkEpisodePath?.trim().equals(preservePath, ignoreCase = true)
        ) {
            Log.d(TAG, "reader_session_cancel_preserve_ntk_volatile path=$preservePath")
        } else {
            ReaderImageCache.cancelNtkEpisodeVolatile(manga)
        }
        MainApplication.getHttpClient().cancelNtkWebViewFallbacks()
        repositoryCancellations.clear()
        main.removeCallbacks(clearPreparedBitmapsRunnable)
        main.removeCallbacks(deliveryDrainRunnable)
        blockedForwardPendingAudits.values.forEach(main::removeCallbacks)
        blockedForwardPendingAudits.clear()
        recycleQueuedDeliveries()
        preparedInitialAdjacentRunways.values.forEach { prepared ->
            recycleAdjacentRunwayDrawableBatch(prepared.batch)
        }
        preparedInitialAdjacentRunways.clear()
        preparedAdjacentRemainderDrawables.values.forEach { prepared ->
            recycleDecodeResult(prepared.result)
        }
        preparedAdjacentRemainderDrawables.clear()
        parkedAdjacentRemainderAppends.clear()
        waitingStrictRemainingAdjacentAppends.clear()
        parkedInitialAdjacentRunwayRetries.values.forEach(main::removeCallbacks)
        parkedInitialAdjacentRunwayRetries.clear()
        parkedInitialAdjacentRunwayPathsByRetryKey.clear()
        parkedInitialAdjacentIdleWakePosted.set(false)
        scheduledRemainingAdjacentRunwayRetries.clear().forEach { scheduled ->
            main.removeCallbacks(scheduled.token)
        }
        scheduledAdjacentStrictRecoveryBindDeadlines.clear().forEach { scheduled ->
            main.removeCallbacks(scheduled.token)
        }
        strictRemainingAdjacentWakeLatch.clear()
        nearViewportParkedAdjacentWakePaths.clear()
        directWifiAdjacentInitialRunwayTailHandoffs.clear()
        preparedInitialAdjacentMetadata.values.forEach { prepared ->
            ReaderImageCache.releaseAdjacentNtkForegroundViewerPath(
                prepared.target.ntkEpisodePath,
                "reader_cancel"
            )
        }
        preparedInitialAdjacentMetadata.clear()
        initialAdjacentDocumentControlPaths.clear()
        initialAdjacentMetadataPrefetchPaths.clear()
        activeInitialAdjacentMetadataFetches.clear()
        preparedEntry?.removeListener(preparedListener)
        releaseDeliveredBitmaps()
        network.shutdownNow()
        decode.shutdownNow()
        anchorNetwork.shutdownNow()
        anchorDecode.shutdownNow()
        strictExactViewportBlockerDecode.shutdownNow()
        strictExactForwardWarmDecode.shutdownNow()
        strictExactAnchorTileDecode.shutdownNow()
        initialAnchorDecode.shutdownNow()
        anchorPoll.shutdownNow()
        adjacentNetwork.shutdownNow()
        initialAdjacentRunwayNetwork.shutdownNow()
        urgentNetwork.shutdownNow()
        urgentDecode.shutdownNow()
        strictExactOverlapDecode.shutdownNow()
        strictExactInitialRunwayDecode.shutdownNow()
        strictExactBulkDecode.shutdownNow()
        strictExactRollingDecode.shutdownNow()
        primeNetwork.shutdownNow()
        sourcePrefetchNetwork.shutdownNow()
        progressiveFarTailNetwork.shutdownNow()
        verifiedGeneratedFanout.shutdownNow()
        primeDecode.shutdownNow()
        initialRecovery.shutdownNow()
        cleanup.shutdown()
        control.shutdownNow()
    }

    private fun releaseStrictRequiredEpisodePath(reason: String) {
        if (!strictRequiredEpisodePathRetained.compareAndSet(true, false)) return
        ReaderImageCache.releaseRequiredNtkEpisodePath(
            strictExactLaunchSeal?.normalizedEpisodePath ?: manga.ntkEpisodePath,
            reason
        )
    }

    private fun repositoryCancellation(userVisible: Boolean = false): MangaRepository.Cancellation {
        val cancellation = MangaRepository.cancellation()
        if (userVisible) cancellation.userVisible()
        repositoryCancellations.add(cancellation)
        if (cancelled.get()) cancellation.cancel()
        return cancellation
    }

    private fun releaseRepositoryCancellation(cancellation: MangaRepository.Cancellation) {
        repositoryCancellations.remove(cancellation)
        if (cancelled.get()) cancellation.cancel()
    }

    private inline fun <T> withRepositoryCancellation(
        userVisible: Boolean = false,
        block: (MangaRepository.Cancellation) -> T
    ): T {
        val cancellation = repositoryCancellation(userVisible)
        try {
            return block(cancellation)
        } finally {
            releaseRepositoryCancellation(cancellation)
        }
    }

    fun prepareNextEpisode(anchor: Int) {
        if (isNtkSource(manga, title) && !firstBitmapLogged.get()) return
        if (isNtkSource(manga, title)) {
            val quietMs = ntkBackgroundWarmQuietRemainingMs()
            if (quietMs > 0L) {
                Log.d(TAG, "prepare_next_deferred_active_input anchor=$anchor path=${manga.ntkEpisodePath} quietMs=$quietMs")
                main.postDelayed({ prepareNextEpisode(anchor) }, quietMs)
                return
            }
        }
        if (cancelled.get() || nextLoading.getAndSet(true)) return
        network.execute {
            try {
                val anchorManga = pageRef(anchor)?.manga ?: manga
                val currentTitle = title ?: anchorManga.title ?: manga.title
                if (currentTitle == null) return@execute
                if (syncNtkTitlePathFromEpisode(currentTitle, anchorManga)) {
                    currentTitle.removeEps()
                }
                if (currentTitle.eps == null || currentTitle.eps.size <= 1) {
                    withRepositoryCancellation { imageRepository.fetchEpisodesForeground(currentTitle, it) }
                    if (cancelled.get()) return@execute
                }
                attachTitle()
                val episodes = Utils.snapshotEpisodes(currentTitle)
                if (episodes.isNotEmpty()) {
                    manga.setEps(episodes)
                    anchorManga.setEps(episodes)
                }
                anchorManga.title = currentTitle
                anchorManga.titleId = currentTitle.id
                val next = anchorManga.nextEp() ?: return@execute
                next.title = currentTitle
                next.titleId = currentTitle.id
                if (episodes.isNotEmpty()) next.setEps(episodes)
                if (imageRepository.imageUrls(next, appContext).isNullOrEmpty()) {
                    val result = withRepositoryCancellation {
                        imageRepository.fetchViewerInitial(next, it)
                    }
                    if (cancelled.get()) return@execute
                    if (result != Title.LOAD_OK) return@execute
                }
                val nextUrls = imageRepository.imageUrls(next, appContext)
                if (nextUrls.isNullOrEmpty()) return@execute
            } catch (e: Exception) {
                recordIfUnexpected(e)
            } finally {
                nextLoading.set(false)
            }
        }
    }

    fun prepareAdjacentEpisode(anchor: Int, direction: Int) {
        if (isNtkContinuousAdjacentCompletionPolicyActive()) {
            if (direction < 0) {
                Log.d(TAG, "reader_adjacent_previous_auto_prepare_disabled anchor=$anchor")
                return
            }
            if (direction > 0 &&
                !canPrepareForwardAdjacentNow(pageRef(anchor)?.manga?.ntkEpisodePath)
            ) {
                if (Log.isLoggable(TAG, Log.DEBUG)) {
                    Log.d(
                        TAG,
                        "reader_adjacent_prepare_wait_current_complete anchor=$anchor"
                    )
                }
                // ReaderSurfaceView emits the near-tail transition once. If that transition wins
                // the race with the final current-episode drawable, simply returning here loses
                // the only preparation signal: the coordinate can already be clamped at the end,
                // so no later scroll event is guaranteed. Keep one session-owned, lifecycle-bound
                // retry and revalidate the boundary on every turn.
                scheduleDeferredAdjacentPrepare(
                    anchor,
                    direction,
                    NTK_ADJACENT_COMPLETION_WAIT_RECHECK_MS,
                    silentMissing = true,
                )
                return
            }
        }
        val quietMs = ntkAdjacentAppendStartDelayMs()
        if (quietMs > 0L) {
            scheduleDeferredAdjacentPrepare(anchor, direction, quietMs, silentMissing = true)
            return
        }
        appendAdjacentEpisode(anchor, direction, silentMissing = true)
    }

    private fun scheduleDeferredAdjacentPrepare(
        anchor: Int,
        direction: Int,
        delayMs: Long,
        silentMissing: Boolean
    ) {
        deferredAdjacentPrepareMailbox.offer(anchor, direction, silentMissing)?.let { wakeup ->
            postDeferredAdjacentPrepareWakeup(wakeup, delayMs)
        }
    }

    private fun postDeferredAdjacentPrepareWakeup(
        wakeup: NtkDeferredAdjacentPrepareMailbox.Wakeup,
        delayMs: Long,
    ) {
        main.postDelayed(
            { flushDeferredAdjacentPrepare(wakeup.token) },
            delayMs.coerceAtLeast(0L),
        )
    }

    private fun flushDeferredAdjacentPrepare(wakeupToken: Long) {
        if (cancelled.get()) {
            deferredAdjacentPrepareMailbox.clear()
            return
        }
        val quietMs = ntkAdjacentAppendStartDelayMs()
        if (quietMs > 0L) {
            deferredAdjacentPrepareMailbox.defer(wakeupToken)?.let { wakeup ->
                postDeferredAdjacentPrepareWakeup(wakeup, quietMs)
            }
            return
        }
        val pending = deferredAdjacentPrepareMailbox.take(wakeupToken) ?: return
        val anchor = pending.anchor
        val direction = pending.direction
        val silentMissing = pending.silentMissing
        if (anchor >= 0 && direction != 0) {
            val effectiveAnchor = normalizedAdjacentBoundaryAnchor(anchor, direction)
            if (!isNtkSilentAdjacentStillNearBoundary(effectiveAnchor, direction)) {
                Log.d(
                    TAG,
                    "append_adjacent_deferred_boundary_not_near direction=$direction anchor=$anchor " +
                        "effective=$effectiveAnchor " +
                        "path=${manga.ntkEpisodePath}"
                )
                // An explicit boundary request may have installed a Surface hold before this
                // deferred turn. Retire that ownership when the user has moved away; silent
                // look-ahead has no Activity-owned boundary state to finish.
                if (!silentMissing) {
                    postBoundaryAppendFinished(
                        anchor,
                        direction,
                        silent = false,
                        suppressedCaptcha = false,
                    )
                }
                return
            }
            // Preserve the anchor that actually reached the boundary. appendAdjacentEpisode will
            // compare it with the now-current normalized tail and reject this deferred turn when
            // pages were published in between. Passing effectiveAnchor here erased that evidence
            // and could append the next-next episode before the viewport reached the new p5/p6.
            redriveDeferredAdjacentAppend(pending)
        }
    }

    /**
     * A deferred turn already owns the Activity/Surface boundary request.  Taking the mailbox and
     * then ignoring BUSY loses that only wakeup when a publish, loading flag, or recent-start
     * suppression overlaps this exact turn. Re-offer the same identity until it either starts or
     * becomes genuinely stale; explicit boundary ownership is finished exactly once on cancel.
     */
    private fun redriveDeferredAdjacentAppend(
        request: NtkDeferredAdjacentPrepareMailbox.Request,
    ) {
        val anchor = request.anchor
        val direction = request.direction
        val silentMissing = request.silentMissing
        when (appendAdjacentEpisode(
            anchor,
            direction,
            silentMissing = silentMissing,
            skipStartDelay = true,
        )) {
            AppendStartResult.STARTED -> Unit
            AppendStartResult.BUSY -> deferredAdjacentPrepareMailbox.reoffer(request)?.let { wakeup ->
                postDeferredAdjacentPrepareWakeup(
                    wakeup,
                    NTK_ADJACENT_COMPLETION_WAIT_RECHECK_MS,
                )
            }
            AppendStartResult.CANCELLED -> if (!silentMissing) {
                postBoundaryAppendFinished(
                    anchor,
                    direction,
                    silent = false,
                    suppressedCaptcha = false,
                )
            }
        }
    }

    private fun normalizedAdjacentBoundaryAnchor(anchor: Int, direction: Int): Int {
        if (!isNtkSource(manga, title)) return anchor
        return synchronized(pagesLock) {
            if (pages.isEmpty()) return@synchronized anchor
            val bounded = anchor.coerceIn(0, pages.lastIndex)
            val source = pages.getOrNull(bounded)?.manga ?: manga
            val indexes = pages.withIndex()
                .filter { item ->
                    item.value.transitionTitle == null &&
                        Manga.sameEpisodeIdentity(item.value.manga, source)
                }
                .map { it.index }
            if (indexes.isEmpty()) {
                bounded
            } else if (direction > 0) {
                var deliveredTail = bounded
                for (index in indexes.asSequence().filter { it > bounded }.sorted()) {
                    if (index != deliveredTail + 1) break
                    if (!hasListenerDrawableDelivery(index)) break
                    deliveredTail = index
                }
                deliveredTail
            } else {
                indexes.minOrNull() ?: bounded
            }
        }
    }

    private fun ntkCurrentGeneratedManifestDelayMs(source: Manga, anchor: Int, direction: Int): Long {
        if (direction <= 0 || !isImmediateNtkGeneratedUx()) return 0L
        if (!isNtkSource(source, title)) return 0L
        val path = source.ntkEpisodePath?.trim().orEmpty()
        if (!isNtkManhwaOrWebtoonEpisodePath(path)) return 0L
        val installed = installedDrawablePageCountForEpisode(source)
        if (installed <= 0 || anchor < installed - NTK_APPEND_CURRENT_TAIL_BOUNDARY_PAGES) return 0L
        val trusted = ReaderImageCache.trustedNtkImageApiCount(path, 0L)
        val cached = ReaderImageCache.earlyNtkAppendImageUrls(path, 0L).size
        val known = source.ntkImageCount
        val generatedRunway = ntkInitialGeneratedRecoveryPagesForTarget(source)
            .coerceAtLeast(NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)
        // A strict rolling session installs an exact, sealed manifest rather than a speculative
        // generated prefix. Its early-URL compatibility cache is intentionally empty, so waiting
        // for `cached >= installed` can never succeed. Once the sealed count is installed and its
        // real tail drawable has been delivered, the current episode is complete and adjacent
        // loading may start immediately.
        if (
            strictExactColdRolling &&
            known > 0 &&
            installed >= known &&
            isCurrentGeneratedTailReadyForAdjacent(source, anchor, installed)
        ) {
            maybeLogCurrentManifestBeforeAdjacent(
                path,
                "append_adjacent_current_exact_tail_ready",
                "anchor=$anchor,installed=$installed,cached=$cached,known=$known"
            )
            return 0L
        }
        if (cached >= installed && installed >= generatedRunway) {
            maybeLogCurrentManifestBeforeAdjacent(
                path,
                "append_adjacent_current_manifest_cached_prefix_ready",
                "anchor=$anchor,installed=$installed,cached=$cached,known=$known,runway=$generatedRunway"
            )
            return 0L
        }
        if (trusted > 0 || cached > installed || known > installed) return 0L
        val firstBitmapAt = ntkFirstBitmapAtMs.get()
        val ageMs = if (firstBitmapAt > 0L) {
            SystemClock.uptimeMillis() - firstBitmapAt
        } else {
            0L
        }
        if (ageMs > NTK_CURRENT_MANIFEST_BEFORE_ADJACENT_MAX_WAIT_MS) {
            maybeLogCurrentManifestBeforeAdjacent(
                path,
                "append_adjacent_current_manifest_timeout",
                "anchor=$anchor,installed=$installed,cached=$cached,known=$known,ageMs=$ageMs"
            )
            return 0L
        }
        source.startNtkEarlyViewerApiPrefetch(MainApplication.getHttpClient())
        requestAllUndeliveredNtkPages("current_manifest_before_next")
        maybeLogCurrentManifestBeforeAdjacent(
            path,
            "append_adjacent_wait_current_manifest",
            "anchor=$anchor,installed=$installed,cached=$cached,known=$known,ageMs=$ageMs"
        )
        return NTK_ADJACENT_CURRENT_INSTALL_RECHECK_MS
    }

    private fun maybeLogCurrentManifestBeforeAdjacent(path: String, stage: String, detail: String) {
        if (!shouldLogRateLimitedDiagnostic("current_manifest|$path")) return
        Log.d(TAG, "$stage path=$path,$detail")
    }

    private fun maybeLogAdjacentCurrentGate(stage: String, target: Manga, detail: String) {
        val path = manga.ntkEpisodePath?.trim().orEmpty()
        val key = "adjacent_current_gate|$stage|$path|${target.ntkEpisodePath?.trim().orEmpty()}"
        if (!shouldLogRateLimitedDiagnostic(key)) return
        logNtkRepositoryStage(manga, stage, detail)
    }

    /**
     * Hot reader state can be revisited for every decoded page and every retained-window publish.
     * Keep the first diagnostic and a periodic sample without making logd part of the scrolling
     * critical path. The compare-and-replace loop also prevents concurrent decode lanes from all
     * emitting the same sample.
     */
    private fun shouldLogRateLimitedDiagnostic(
        key: String,
        intervalMs: Long = NTK_HOT_PATH_DIAGNOSTIC_LOG_MS,
    ): Boolean {
        // This is a forensic text stream, not reader state. Avoid CHM updates and message
        // formatting from concurrent network/decode lanes unless a developer explicitly enables
        // it. In-memory correctness/performance telemetry remains fully collected.
        if (!Log.isLoggable(TAG, Log.DEBUG)) return false
        val now = SystemClock.elapsedRealtime()
        while (true) {
            val previous = rateLimitedDiagnosticLogAtMs[key]
            if (previous != null && now - previous < intervalMs) return false
            if (previous == null) {
                if (rateLimitedDiagnosticLogAtMs.putIfAbsent(key, now) == null) return true
            } else if (rateLimitedDiagnosticLogAtMs.replace(key, previous, now)) {
                return true
            }
        }
    }

    private fun ntkAdjacentCurrentInstallDelayMs(
        anchor: Int,
        direction: Int,
        sourceOverride: Manga? = null
    ): Long {
        if (!isNtkSource(manga, title)) return 0L
        if (direction == 0) return 0L
        if (isStructurePublishPending()) return NTK_ADJACENT_CURRENT_INSTALL_RECHECK_MS
        val source = sourceOverride ?: pageRef(anchor)?.manga ?: manga
        if (!isNtkManhwaOrWebtoonEpisodePath(source.ntkEpisodePath)) return 0L
        val manifestDelayMs = ntkCurrentGeneratedManifestDelayMs(source, anchor, direction)
        if (manifestDelayMs > 0L) return manifestDelayMs
        val sourcePath = source.ntkEpisodePath?.trim().orEmpty()
        val naverOriginalSource =
            sourcePath.contains("naver-", ignoreCase = true) ||
                sourcePath.contains("nv-", ignoreCase = true)
        val naverOriginalRepositoryCount = if (naverOriginalSource) {
            imageRepository.imageUrls(source, appContext).size
        } else {
            0
        }
        return synchronized(pagesLock) {
            if (pages.isEmpty()) return@synchronized NTK_ADJACENT_CURRENT_INSTALL_RECHECK_MS
            val matchingCount = pages.count { page ->
                page.transitionTitle == null && Manga.sameEpisodeIdentity(page.manga, source)
            }
            if (matchingCount <= 0) return@synchronized NTK_ADJACENT_CURRENT_INSTALL_RECHECK_MS
            val cachedCount = ReaderImageCache.earlyNtkAppendImageUrls(source.ntkEpisodePath, 0L).size
            val knownCount = ntkKnownOrAvailableGeneratedCountForAdjacent(source, matchingCount)
            if (direction > 0 && knownCount > matchingCount) {
                if (isInstalledGeneratedTailDrawableForAdjacentLocked(source, anchor)) {
                    updateNtkDisplayCountForEpisode(source, matchingCount)
                    Log.d(
                        TAG,
                        "append_adjacent_current_install_tail_drawable_allowed direction=$direction " +
                            "anchor=$anchor from=$knownCount to=$matchingCount path=${source.ntkEpisodePath}"
                    )
                    return@synchronized 0L
                }
                val generatedCurrent = pages.any { page ->
                    page.transitionTitle == null &&
                        Manga.sameEpisodeIdentity(page.manga, source) &&
                        isNtkGeneratedImageUrl(page.image.orEmpty())
                }
            val firstMissingGeneratedPage =
                ReaderImageCache.knownNtkGeneratedFirstNotFoundPage(source.ntkEpisodePath)
            val generatedTailConfirmed =
                generatedCurrent &&
                    firstMissingGeneratedPage > 1 &&
                    firstMissingGeneratedPage <= matchingCount + 1
            val trustedGeneratedKnownCount =
                ReaderImageCache.trustedNtkImageApiCount(source.ntkEpisodePath, 0L) >= knownCount
            val untrustedGeneratedTail =
                generatedCurrent &&
                    knownCount > NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD &&
                    !trustedGeneratedKnownCount
            if (untrustedGeneratedTail && cachedCount <= matchingCount && anchor >= matchingCount - 1) {
                updateNtkDisplayCountForEpisode(source, matchingCount)
                Log.d(
                    TAG,
                    "append_adjacent_current_install_untrusted_tail_corrected direction=$direction " +
                            "anchor=$anchor from=$knownCount to=$matchingCount " +
                            "missingPage=$firstMissingGeneratedPage path=${source.ntkEpisodePath}"
                )
                return@synchronized 0L
            }
            if (generatedCurrent &&
                !generatedTailConfirmed &&
                !trustedGeneratedKnownCount &&
                cachedCount <= matchingCount &&
                anchor >= matchingCount - 1
            ) {
                updateNtkDisplayCountForEpisode(source, matchingCount)
                Log.d(
                    TAG,
                    "append_adjacent_current_install_untrusted_boundary_corrected direction=$direction " +
                        "anchor=$anchor from=$knownCount to=$matchingCount " +
                        "missingPage=$firstMissingGeneratedPage path=${source.ntkEpisodePath}"
                )
                return@synchronized 0L
            }
            if (generatedCurrent && !generatedTailConfirmed) {
                Log.d(
                    TAG,
                    "append_adjacent_wait_generated_current_expand direction=$direction " +
                        "anchor=$anchor matching=$matchingCount known=$knownCount " +
                            "missingPage=$firstMissingGeneratedPage path=${source.ntkEpisodePath}"
                    )
                    return@synchronized NTK_ADJACENT_CURRENT_INSTALL_RECHECK_MS
                }
                if (anchor >= matchingCount - 1) {
                    updateNtkDisplayCountForEpisode(source, matchingCount)
                    Log.d(
                        TAG,
                        "append_adjacent_current_install_boundary_count_corrected direction=$direction " +
                            "anchor=$anchor from=$knownCount to=$matchingCount path=${source.ntkEpisodePath}"
                    )
                    return@synchronized 0L
                }
                if (knownCount - matchingCount <= 1 && anchor >= matchingCount - 2) {
                    updateNtkDisplayCountForEpisode(source, matchingCount)
                    Log.d(
                        TAG,
                        "append_adjacent_current_install_tail_count_corrected direction=$direction " +
                            "anchor=$anchor from=$knownCount to=$matchingCount path=${source.ntkEpisodePath}"
                    )
                    return@synchronized 0L
                }
                if (naverOriginalRepositoryCount > 0 &&
                    matchingCount >= naverOriginalRepositoryCount
                ) {
                    updateNtkDisplayCountForEpisode(source, matchingCount)
                    Log.d(
                        TAG,
                        "append_adjacent_current_install_naver_count_corrected direction=$direction " +
                            "anchor=$anchor from=$knownCount to=$matchingCount " +
                            "repository=$naverOriginalRepositoryCount path=${source.ntkEpisodePath}"
                    )
                    return@synchronized 0L
                }
                if (naverOriginalSource && anchor >= matchingCount - 2) {
                    updateNtkDisplayCountForEpisode(source, matchingCount)
                    Log.d(
                        TAG,
                        "append_adjacent_current_install_naver_tail_corrected direction=$direction " +
                            "anchor=$anchor from=$knownCount to=$matchingCount path=${source.ntkEpisodePath}"
                    )
                    return@synchronized 0L
                }
                Log.d(
                    TAG,
                    "append_adjacent_wait_current_install direction=$direction anchor=$anchor " +
                        "matching=$matchingCount known=$knownCount path=${source.ntkEpisodePath}"
                )
                return@synchronized NTK_ADJACENT_CURRENT_INSTALL_RECHECK_MS
            }
            0L
        }
    }

    private fun scheduleAdjacentCurrentInstallRetry(
        anchor: Int,
        direction: Int,
        delayMs: Long,
        silentMissing: Boolean
    ) {
        val source = pageRef(anchor)?.manga ?: manga
        maybeExpandCurrentNtkInstallForAdjacent(source, anchor)
        scheduleDeferredAdjacentPrepare(
            anchor,
            direction,
            delayMs.coerceAtLeast(NTK_ADJACENT_CURRENT_INSTALL_RECHECK_MS),
            silentMissing,
        )
    }

    private fun updateNtkDisplayCountForEpisode(source: Manga, displayTotalPages: Int) {
        if (displayTotalPages <= 0) return
        source.setNtkImageCount(displayTotalPages)
        if (source !== manga && Manga.sameEpisodeIdentity(source, manga)) {
            manga.setNtkImageCount(displayTotalPages)
        }
    }

    private fun ntkKnownOrAvailableGeneratedCountForAdjacent(source: Manga, installed: Int): Int {
        val path = source.ntkEpisodePath
        val known = source.ntkImageCount
        val cached = ReaderImageCache.earlyNtkAppendImageUrls(path, 0L).size
        val trusted = ReaderImageCache.trustedNtkImageApiCount(path, 0L)
        return maxOf(known, cached, trusted, installed)
    }

    private fun ntkCurrentGeneratedExpansionLimit(
        source: Manga,
        installed: Int,
        anchor: Int,
        available: Int
    ): Int {
        if (available <= 0) return 0
        val runway = ntkInitialGeneratedRecoveryPagesForTarget(source)
            .coerceAtLeast(NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)
        val anchorLimit = if (anchor >= 0) anchor + runway + 1 else 0
        val installedLimit = installed + runway
        return minOf(available, maxOf(runway, anchorLimit, installedLimit))
    }

    private fun generatedCurrentEpisodeUrlsFromInstalledSeed(source: Manga, count: Int): List<String> {
        if (count <= 0) return emptyList()
        val seed = synchronized(pagesLock) {
            pages.firstOrNull { page ->
                page.transitionTitle == null &&
                    Manga.sameEpisodeIdentity(page.manga, source) &&
                    isNtkGeneratedImageUrl(page.image.orEmpty())
            }?.image
        } ?: return emptyList()
        val generated = ArrayList<String>(count)
        for (page in 1..count) {
            val image = ntkGeneratedImageUrlForTarget(seed, source, page) ?: break
            generated.add(image)
        }
        return generated
    }

    private fun currentGeneratedUrlsForAdjacentExpansion(
        source: Manga,
        knownCount: Int,
        installed: Int
    ): List<String> {
        val path = source.ntkEpisodePath
        val cached = ReaderImageCache.earlyNtkAppendImageUrls(path, 0L)
        if (cached.size >= knownCount && cached.size > installed) return cached
        val derived = generatedCurrentEpisodeUrlsFromInstalledSeed(source, knownCount)
        if (derived.size >= knownCount && derived.size > installed) {
            logNtkRepositoryStage(
                source,
                "append_adjacent_derive_current_generated_urls",
                "installed=$installed,known=$knownCount,cached=${cached.size},derived=${derived.size}"
            )
            return derived
        }
        return cached
    }

    private fun maybeExpandCurrentNtkInstallForAdjacent(source: Manga, anchor: Int = -1) {
        if (!isNtkSource(source, title)) return
        val path = source.ntkEpisodePath ?: return
        val installed = installedDrawablePageCountForEpisode(source)
        val cachedCount = ReaderImageCache.earlyNtkAppendImageUrls(path, 0L).size
        val knownCount = ntkKnownOrAvailableGeneratedCountForAdjacent(source, installed)
        if (knownCount <= 0) return
        if (installed >= knownCount) return
        val verifiedApiUrls = ReaderImageCache.cachedNtkApiFallbackImages(source.ntkEpisodePath)
        if (verifiedApiUrls.isNotEmpty() && verifiedApiUrls.size < knownCount) {
            updateNtkDisplayCountForEpisode(source, verifiedApiUrls.size)
            ReaderImageCache.rememberAuthoritativeNtkImageUrlsFromBrowser(
                source.ntkEpisodePath,
                verifiedApiUrls,
                "verified-api-short-cap"
            )
            logNtkRepositoryStage(
                source,
                "append_adjacent_clamp_current_to_verified_api",
                "installed=$installed,known=$knownCount,verified=${verifiedApiUrls.size},anchor=$anchor,path=$path"
            )
            if (installed < verifiedApiUrls.size) {
                appendInitialNtkUrlsAfterEarlyInstall(
                    source,
                    verifiedApiUrls,
                    SystemClock.elapsedRealtime(),
                    allowFirstBitmapDefer = false,
                    minGeneratedLimit = verifiedApiUrls.size,
                    forceImmediatePublish = true
                )
                requestAllUndeliveredNtkPages("current_verified_api_before_next_retry")
            }
            return
        }
        val trustedGeneratedKnownCount =
            ReaderImageCache.trustedNtkImageApiCount(source.ntkEpisodePath, 0L) >= knownCount
        if (!trustedGeneratedKnownCount && cachedCount <= installed && installed > 0 && anchor >= installed - 1) {
            updateNtkDisplayCountForEpisode(source, installed)
            logNtkRepositoryStage(
                source,
                "append_adjacent_skip_untrusted_current_expand",
                "installed=$installed,known=$knownCount,anchor=$anchor,path=$path"
            )
            return
        }
        val latest = currentGeneratedUrlsForAdjacentExpansion(source, knownCount, installed)
        if (latest.size < knownCount || latest.size <= installed) return
        logNtkRepositoryStage(
            source,
            "append_adjacent_expand_current_before_retry",
            "from=$installed,to=${latest.size},known=$knownCount,path=$path"
        )
        val minGeneratedLimit = ntkCurrentGeneratedExpansionLimit(source, installed, anchor, latest.size)
        appendInitialNtkUrlsAfterEarlyInstall(
            source,
            latest,
            SystemClock.elapsedRealtime(),
            allowFirstBitmapDefer = false,
            minGeneratedLimit = minGeneratedLimit
        )
        requestAllUndeliveredNtkPages("current_full_before_next_retry")
    }

    fun appendAdjacentEpisode(
        anchor: Int,
        direction: Int,
        silentMissing: Boolean = false,
        skipStartDelay: Boolean = false
    ): AppendStartResult {
        if (cancelled.get()) return AppendStartResult.CANCELLED
        if (isNtkContinuousAdjacentCompletionPolicyActive()) {
            if (direction < 0) {
                Log.d(TAG, "reader_adjacent_previous_auto_append_disabled anchor=$anchor")
                return AppendStartResult.CANCELLED
            }
            if (direction > 0 &&
                !canPrepareForwardAdjacentNow(pageRef(anchor)?.manga?.ntkEpisodePath)
            ) {
                Log.d(
                    TAG,
                    "append_adjacent_wait_current_complete direction=$direction anchor=$anchor"
                )
                // This is a transient predecessor-completion race, not cancellation. Accept the
                // boundary request and retain it inside the Session; otherwise Activity clears its
                // edge intent and a reader already clamped at maxScroll has no event with which to
                // request the next episode again.
                scheduleDeferredAdjacentPrepare(
                    anchor,
                    direction,
                    NTK_ADJACENT_COMPLETION_WAIT_RECHECK_MS,
                    silentMissing,
                )
                return AppendStartResult.STARTED
            }
        }
        // The launch episode remains sealed and continues to use its immutable source transport.
        // Adjacent PageRefs have a different episode identity and are routed through the ordinary
        // append pipeline below; blocking the whole session here made continuous reading
        // structurally impossible after strict cold launch.
        // Strict rolling delivery can commit authoritative texture tiles without ever producing a
        // Java Bitmap.  Treat that physical drawable commit as the launch proof as well; otherwise
        // reaching the tail after a successful strict draw permanently cancels the next episode.
        if (
            isNtkSource(manga, title) &&
            !firstBitmapLogged.get() &&
            !firstDrawableDelivered.get() &&
            ntkFirstBitmapAtMs.get() <= 0L
        ) {
            // Native presentation can reach the physical edge one main-loop turn before the
            // Session mirrors its first-drawable proof. Preserve the request across that handoff.
            scheduleDeferredAdjacentPrepare(
                anchor,
                direction,
                NTK_ADJACENT_COMPLETION_WAIT_RECHECK_MS,
                silentMissing,
            )
            return AppendStartResult.STARTED
        }
        val effectiveAnchor = if (isNtkSource(manga, title) && direction != 0) {
            normalizedAdjacentBoundaryAnchor(anchor, direction)
        } else {
            anchor
        }
        if (effectiveAnchor != anchor) {
            val viewportAnchor = currentViewportAnchor.get()
            if (NtkAdjacentAdmissionPolicy.shouldRejectStaleForwardTail(
                    direction = direction,
                    requestedAnchor = anchor,
                    normalizedAnchor = effectiveAnchor,
                    viewportAnchor = viewportAnchor,
                )
            ) {
                Log.d(
                    TAG,
                    "append_adjacent_anchor_growth_stale direction=$direction anchor=$anchor " +
                        "effective=$effectiveAnchor viewport=$viewportAnchor path=${manga.ntkEpisodePath}"
                )
                return AppendStartResult.CANCELLED
            }
            Log.d(
                TAG,
                "append_adjacent_anchor_normalized direction=$direction anchor=$anchor " +
                    "effective=$effectiveAnchor path=${manga.ntkEpisodePath}"
            )
            return appendAdjacentEpisode(
                effectiveAnchor,
                direction,
                silentMissing = silentMissing,
                skipStartDelay = true
            )
        }
        val ntkTailBoundaryAppend =
            isNtkSource(manga, title) &&
                direction > 0 &&
                anchor >= synchronized(pagesLock) { pages.lastIndex }
        val anchorMangaForAppendGate = if (direction > 0) pageRef(anchor) ?: null else null
        val ntkChainedTailBoundaryAppend =
            ntkTailBoundaryAppend &&
                isImmediateNtkGeneratedUx() &&
                anchorMangaForAppendGate != null &&
                !Manga.sameEpisodeIdentity(anchorMangaForAppendGate.manga, manga)
        if (
            ntkChainedTailBoundaryAppend &&
            shouldDeferChainedAdjacentForActiveRemaining(anchorMangaForAppendGate?.manga, direction)
        ) {
            val delayMs = maxOf(
                readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS),
                readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS),
                NTK_ADJACENT_FOREGROUND_STREAM_RECHECK_MS
            )
            Log.d(
                TAG,
                "append_adjacent_chained_defer_active_remaining direction=$direction anchor=$anchor " +
                    "delayMs=$delayMs source=${anchorMangaForAppendGate?.manga?.ntkEpisodePath} " +
                    "active=${activeRemainingAdjacentRunwayTargetPaths.size}"
            )
            scheduleDeferredAdjacentPrepare(anchor, direction, delayMs, silentMissing)
            return AppendStartResult.STARTED
        }
        if (isNtkSource(manga, title) &&
            direction > 0 &&
            pendingAdjacentAppendPublishKeys.isNotEmpty()
        ) {
            Log.d(
                TAG,
                "append_adjacent_start_skip_pending_publish direction=$direction anchor=$anchor " +
                    "pending=${pendingAdjacentAppendPublishKeys.size} skipStartDelay=$skipStartDelay " +
                    "tailBoundary=$ntkTailBoundaryAppend path=${manga.ntkEpisodePath}"
            )
            return AppendStartResult.BUSY
        }
        if (isNtkSource(manga, title)) {
            val quietMs = if (isImmediateNtkGeneratedUx()) {
                if (skipStartDelay && ntkTailBoundaryAppend) {
                    0L
                } else {
                    ntkAdjacentAppendStartDelayMs()
                }
            } else if (skipStartDelay) {
                if (ntkTailBoundaryAppend) 0L else ntkBackgroundWarmQuietRemainingMs()
            } else {
                ntkAdjacentAppendStartDelayMs()
            }
            if (quietMs > 0L) {
                Log.d(
                    TAG,
                    "append_adjacent_start_defer_reader_busy direction=$direction anchor=$anchor " +
                        "quietMs=$quietMs skipStartDelay=$skipStartDelay " +
                        "tailBoundary=$ntkTailBoundaryAppend chainedTail=$ntkChainedTailBoundaryAppend " +
                        "path=${manga.ntkEpisodePath}"
                )
                scheduleDeferredAdjacentPrepare(anchor, direction, quietMs, silentMissing)
                return AppendStartResult.STARTED
            }
        }
        val currentInstallDelayMs = ntkAdjacentCurrentInstallDelayMs(anchor, direction)
        if (currentInstallDelayMs > 0L) {
            Log.d(
                TAG,
                "append_adjacent_start_defer_current_install direction=$direction anchor=$anchor " +
                    "delayMs=$currentInstallDelayMs path=${manga.ntkEpisodePath}"
            )
            scheduleAdjacentCurrentInstallRetry(anchor, direction, currentInstallDelayMs, silentMissing)
            return AppendStartResult.STARTED
        }
        val loadingFlag = if (direction < 0) previousAppendLoading else nextAppendLoading
        if (silentMissing && !isNtkSilentAdjacentStillNearBoundary(anchor, direction)) {
            Log.d(
                TAG,
                "append_adjacent_silent_stale_boundary direction=$direction anchor=$anchor " +
                    "path=${manga.ntkEpisodePath}"
            )
            return AppendStartResult.CANCELLED
        }
        if (loadingFlag.getAndSet(true)) {
            if (ntkTailBoundaryAppend) {
                Log.d(
                    TAG,
                    "append_adjacent_tail_busy direction=$direction anchor=$anchor " +
                        "path=${manga.ntkEpisodePath}"
                )
                return AppendStartResult.BUSY
            }
            return AppendStartResult.BUSY
        }
        val adjacentStartKey = adjacentAppendStartKey(anchor, direction)
        if (adjacentStartKey.isNotEmpty()) {
            val nowMs = SystemClock.elapsedRealtime()
            val previousMs = recentAdjacentAppendStartAtMs[adjacentStartKey]
            if (previousMs != null && nowMs - previousMs < NTK_ADJACENT_APPEND_START_SUPPRESS_MS) {
                loadingFlag.set(false)
                Log.d(
                    TAG,
                    "append_adjacent_start_skip_recent direction=$direction anchor=$anchor " +
                        "ageMs=${nowMs - previousMs} path=${manga.ntkEpisodePath}"
                )
                return AppendStartResult.BUSY
            }
            if (!activeAdjacentAppendStartKeys.add(adjacentStartKey)) {
                loadingFlag.set(false)
                Log.d(
                    TAG,
                    "append_adjacent_start_skip_active direction=$direction anchor=$anchor " +
                        "path=${manga.ntkEpisodePath}"
                )
                return AppendStartResult.BUSY
            }
            recentAdjacentAppendStartAtMs[adjacentStartKey] = nowMs
            trimRecentAdjacentAppendStarts(nowMs)
        }
        // Keep the identity-bearing PageRef, not just its global index. A consumed-prefix trim can
        // move this same tail page while the adjacent executor is queued. Looking it up again by
        // the old index would return null and incorrectly fall back to the launch episode.
        val appendAnchorPage = pageRef(anchor)
        if (direction > 0 && isNtkContinuousAdjacentCompletionPolicyActive()) {
            ViewerTelemetry.adjacentWorkStarted(
                appendAnchorPage?.manga?.ntkEpisodePath ?: manga.ntkEpisodePath
            )
        }
        try {
            val appendExecutor = if (isNtkSource(manga, title)) adjacentNetwork else network
            appendExecutor.execute {
            var captchaRequired = false
            var suppressedCaptcha = false
            var completionAnchor = anchor
            try {
                val currentAnchor = if (appendAnchorPage != null) {
                    currentPageIndex(appendAnchorPage, anchor).takeIf { it >= 0 }
                        ?: return@execute
                } else {
                    normalizedAdjacentBoundaryAnchor(anchor, direction)
                }
                completionAnchor = currentAnchor
                val anchorManga = appendAnchorPage?.manga
                    ?: pageRef(currentAnchor)?.manga
                    ?: return@execute
                val currentTitle = title ?: anchorManga.title ?: manga.title ?: return@execute
                Log.d(
                    TAG,
                    "append_adjacent_start direction=$direction anchor=$currentAnchor originalAnchor=$anchor " +
                        "sourceId=${anchorManga.id} " +
                        "sourceTitleId=${anchorManga.titleId} titleId=${currentTitle.id} " +
                        "sourcePath=${anchorManga.ntkEpisodePath} sourceName=${anchorManga.name}"
                )
                val installDelayMs = ntkAdjacentCurrentInstallDelayMs(
                    currentAnchor,
                    direction,
                    anchorManga
                )
                if (installDelayMs > 0L) {
                    Log.d(
                        TAG,
                        "append_adjacent_fetch_defer_current_install direction=$direction " +
                            "anchor=$currentAnchor originalAnchor=$anchor " +
                            "delayMs=$installDelayMs sourcePath=${anchorManga.ntkEpisodePath}"
                    )
                    main.post {
                        if (!cancelled.get()) {
                            scheduleAdjacentCurrentInstallRetry(
                                currentAnchor,
                                direction,
                                installDelayMs,
                                silentMissing
                            )
                        }
                    }
                    return@execute
                }
                if (isNtkAdjacentAppendBlockedByCurrentTail(
                        anchorManga,
                        currentAnchor,
                        direction
                    )
                ) {
                    if (adjacentStartKey.isNotEmpty()) {
                        recentAdjacentAppendStartAtMs.remove(adjacentStartKey)
                    }
                    return@execute
                }
                if (joinCompletionOwnedForwardExactAppend(anchorManga, direction)) {
                    return@execute
                }
                if (syncNtkTitlePathFromEpisode(currentTitle, anchorManga)) {
                    currentTitle.removeEps()
                }
                restoreNtkEpisodeSnapshotIfNeeded(currentTitle, anchorManga)
                if (currentTitle.eps == null || currentTitle.eps.size <= 1) {
                    val result = withRepositoryCancellation {
                        imageRepository.fetchEpisodesForeground(currentTitle, it)
                    }
                    if (cancelled.get()) return@execute
                    if (result != Title.LOAD_OK) {
                        if (result == Title.LOAD_CAPTCHA) {
                            if (silentMissing) {
                                suppressedCaptcha = true
                                return@execute
                            }
                            captchaRequired = true
                            postCaptchaRequired(anchorManga)
                            return@execute
                        }
                        postMessage(if (result == Title.LOAD_CAPTCHA) "캡차 확인이 필요합니다" else "회차를 불러오지 못했습니다")
                        return@execute
                    }
                }
                attachTitle()
                var episodes = Utils.snapshotEpisodes(currentTitle)
                if (episodes.isNotEmpty()) {
                    manga.setEps(episodes)
                    anchorManga.setEps(episodes)
                    persistNtkEpisodeSnapshot(currentTitle, episodes)
                }
                anchorManga.title = currentTitle
                anchorManga.titleId = currentTitle.id
                var target = nextUnloadedAdjacentEpisode(anchorManga, currentTitle, episodes, direction)
                if (target == null && hasLoadedImmediateWfwfAdjacentEpisode(
                        anchorManga,
                        currentTitle,
                        episodes,
                        direction,
                    )
                ) {
                    // WFWF primes exactly one neighbour. Reaching the boundary after that
                    // neighbour was installed is success, not evidence that the episode list is
                    // stale. Refreshing here can replace the launch list with an unrelated remote
                    // snapshot and disable the toolbar's otherwise valid next action.
                    Log.d(
                        TAG,
                        "append_adjacent_wfwf_immediate_already_present direction=$direction " +
                            "sourceId=${anchorManga.id}",
                    )
                    return@execute
                }
                if (target == null && anchorManga.isOnline) {
                    // Episode lists can legitimately grow after an initial tail prefetch. A
                    // session-lifetime negative cache poisoned every later explicit boundary
                    // request when the provider first returned [current] and later [current,next].
                    // Loading/active/recent-start gates already bound duplicate work, so refresh
                    // the authoritative list on each otherwise-unresolved turn.
                    val result = withRepositoryCancellation {
                        imageRepository.fetchEpisodesForeground(currentTitle, it)
                    }
                    if (cancelled.get()) return@execute
                    Log.d(TAG, "append_adjacent_refresh direction=$direction result=$result beforeEpisodes=${episodes.size}")
                    if (result == Title.LOAD_OK) {
                        attachTitle()
                        episodes = Utils.snapshotEpisodes(currentTitle)
                        if (episodes.isNotEmpty()) {
                            manga.setEps(episodes)
                            anchorManga.setEps(episodes)
                            persistNtkEpisodeSnapshot(currentTitle, episodes)
                        }
                        anchorManga.title = currentTitle
                        anchorManga.titleId = currentTitle.id
                        target = nextUnloadedAdjacentEpisode(anchorManga, currentTitle, episodes, direction)
                    } else {
                        if (result == Title.LOAD_CAPTCHA) {
                            if (silentMissing) {
                                suppressedCaptcha = true
                                return@execute
                            }
                            captchaRequired = true
                            postCaptchaRequired(anchorManga)
                            return@execute
                        }
                        if (!silentMissing) {
                            postMessage("Failed to load episode list")
                        }
                        return@execute
                    }
                }
                if (target == null) {
                    Log.d(
                        TAG,
                        "append_adjacent_target_missing direction=$direction episodes=${episodes.size} " +
                            "sourceKey=${Manga.episodeIdentityKey(anchorManga)}"
                    )
                    if (!silentMissing) {
                        postMessage(if (direction < 0) "이전 회차가 없습니다" else "다음 회차가 없습니다")
                    }
                    return@execute
                }
                var resolvedTarget: Manga? = null
                var resolvedUrls: List<String> = emptyList()
                var checkedCandidates = 0
                val exactForwardOnly = direction > 0 &&
                    isNtkContinuousAdjacentCompletionPolicyActive()
                val adjacentCandidates = adjacentEpisodeCandidates(
                    anchorManga,
                    episodes,
                    direction,
                ).let { candidates ->
                    if (exactForwardOnly) candidates.take(1) else candidates
                }
                for (candidate in adjacentCandidates) {
                    if (checkedCandidates >= ADJACENT_EXISTING_SKIP_LIMIT) break
                    candidate.title = currentTitle
                    candidate.titleId = currentTitle.id
                    candidate.mode = anchorManga.mode
                    if (episodes.isNotEmpty()) candidate.setEps(episodes)
                    val loaded = if (direction < 0) hasEpisodeFast(candidate) else hasEpisode(candidate)
                    if (loaded) {
                        if (exactForwardOnly) {
                            Log.d(
                                TAG,
                                "append_adjacent_exact_immediate_already_present " +
                                    "source=${anchorManga.ntkEpisodePath}," +
                                    "target=${candidate.ntkEpisodePath}",
                            )
                            return@execute
                        }
                        checkedCandidates++
                        continue
                    }
                    // A real next episode from the authoritative episode list must never become
                    // structurally complete from the conservative 12-page numeric seed. This race
                    // is observable when a fast reader reaches volume N+1 while its full runway
                    // publisher is still active: the seed can beat the metadata prefetch for N+2,
                    // after which the later 119-page manifest is rejected as a duplicate. Load the
                    // same authoritative manifest used by completed-current prefetch, through an
                    // isolated object, and reserve speculative seeding for synthetic discovery.
                    val useAuthoritativeManifest =
                        direction > 0 &&
                            checkedCandidates == 0 &&
                            isNtkManhwaOrWebtoonEpisodePath(candidate.ntkEpisodePath) &&
                            !isNtkSyntheticEpisodePath(candidate.ntkEpisodePath) &&
                            hasNtkResolvedAdjacentMetadataCandidate(
                                anchorManga,
                                currentTitle,
                                direction,
                            )
                    if (exactForwardOnly && !useAuthoritativeManifest) {
                        Log.d(
                            TAG,
                            "append_adjacent_exact_manifest_pending " +
                                "source=${anchorManga.ntkEpisodePath}," +
                                "target=${candidate.ntkEpisodePath}",
                        )
                        return@execute
                    }
                    val loadTarget = if (useAuthoritativeManifest) {
                        isolatedAdjacentPrefetchCandidate(
                            candidate,
                            anchorManga,
                            currentTitle,
                            episodes,
                        ) ?: candidate
                    } else {
                        candidate
                    }
                    inheritNtkAppendGeneratedHints(loadTarget, anchorManga, currentTitle)
                    if (!useAuthoritativeManifest) {
                        seedNtkAppendGeneratedUrlsFromNeighbor(
                            loadTarget,
                            anchorManga,
                            currentTitle,
                        )
                    }
                    Log.d(
                        TAG,
                        "append_adjacent_target direction=$direction targetId=${loadTarget.id} " +
                            "targetTitleId=${loadTarget.titleId} targetPath=${loadTarget.ntkEpisodePath} " +
                            "targetName=${loadTarget.name} authoritative=$useAuthoritativeManifest"
                    )
                    val appendLoad = if (useAuthoritativeManifest) {
                        loadAuthoritativeAdjacentUrlsForPrefetch(
                            loadTarget,
                            anchorManga,
                            currentTitle,
                            direction,
                        )
                    } else {
                        loadAppendUrlsForCandidate(
                            loadTarget,
                            anchorManga,
                            currentTitle,
                            direction,
                        )
                    }
                    if (cancelled.get()) return@execute
                    if (appendLoad.result == Title.LOAD_CAPTCHA) {
                        if (silentMissing) {
                            suppressedCaptcha = true
                            return@execute
                        }
                        captchaRequired = true
                        postCaptchaRequired(loadTarget)
                        return@execute
                    }
                    if (appendLoad.result == Title.LOAD_OK && appendLoad.urls.isNotEmpty()) {
                        if (shouldSkipLoadedNtkAdjacentCandidate(anchorManga, loadTarget, direction)) {
                            Log.d(
                                TAG,
                                "append_adjacent_candidate_skip_visible_mismatch direction=$direction " +
                                    "source=${anchorManga.ntkEpisodePath} target=${loadTarget.ntkEpisodePath} " +
                                    "sourceNo=${Manga.visibleEpisodeNumberKey(anchorManga)} " +
                                    "targetNo=${Manga.visibleEpisodeNumberKey(loadTarget)} " +
                                    "targetName=${loadTarget.name} images=${appendLoad.urls.size}"
                            )
                            loadTarget.setImgs(null)
                            checkedCandidates++
                            continue
                        }
                        resolvedTarget = loadTarget
                        resolvedUrls = appendLoad.urls
                        break
                    }
                    Log.d(
                        TAG,
                        "append_adjacent_candidate_skip direction=$direction targetId=${loadTarget.id} " +
                            "path=${loadTarget.ntkEpisodePath} result=${appendLoad.result} " +
                            "reason=${loadTarget.ntkViewerParseReason} images=${appendLoad.urls.size}"
                    )
                    loadTarget.setImgs(null)
                    checkedCandidates++
                    if (isWfwfSource(anchorManga, currentTitle) &&
                        WfwfAdjacentEpisodePolicy.isImmediateNumericCandidate(
                            anchorManga.id,
                            loadTarget.id,
                            direction,
                        )
                    ) {
                        break
                    }
                }
                if (resolvedTarget == null || resolvedUrls.isEmpty()) {
                    if (!silentMissing) postMessage("표시할 이미지가 없습니다")
                    return@execute
                }
                if (shouldRejectForwardAppendCompletionAfterSourceGrowth(
                        appendAnchorPage,
                        anchorManga,
                        direction,
                    )
                ) {
                    Log.d(
                        TAG,
                        "append_adjacent_completion_anchor_growth_stale direction=$direction " +
                            "source=${anchorManga.ntkEpisodePath} " +
                            "target=${resolvedTarget.ntkEpisodePath}",
                    )
                    return@execute
                }
                val publishUrls = completeKnownGeneratedAppendUrls(resolvedTarget, resolvedUrls)
                markForwardAdjacentBoundaryDemand(resolvedTarget, direction)
                val warmUrls = ntkBoundaryAppendWarmUrls(resolvedTarget, publishUrls, direction, silentMissing)
                if (shouldSkipActiveAdjacentPreStartForegroundStreams(resolvedTarget, direction)) {
                    Log.d(
                        TAG,
                        "append_adjacent_pre_stream_skip_active targetId=${resolvedTarget.id} " +
                            "path=${resolvedTarget.ntkEpisodePath} direction=$direction"
                    )
                } else {
                    startAdjacentForegroundStreams(resolvedTarget, warmUrls, direction)
                }
                appendResolvedEpisode(resolvedTarget, publishUrls, direction)
            } catch (e: Exception) {
                recordIfUnexpected(e)
            } finally {
                if (adjacentStartKey.isNotEmpty()) activeAdjacentAppendStartKeys.remove(adjacentStartKey)
                loadingFlag.set(false)
                if (!captchaRequired) {
                    postBoundaryAppendFinished(
                        completionAnchor,
                        direction,
                        silentMissing,
                        suppressedCaptcha
                    )
                }
            }
            }
        } catch (_: RejectedExecutionException) {
            if (adjacentStartKey.isNotEmpty()) activeAdjacentAppendStartKeys.remove(adjacentStartKey)
            loadingFlag.set(false)
            return AppendStartResult.CANCELLED
        }
        return AppendStartResult.STARTED
    }

    private fun appendImmediateGeneratedNumericAdjacentIfAvailable(
        source: Manga,
        currentTitle: Title,
        direction: Int,
        initialTailPreappend: Boolean = false,
        prefetchOnly: Boolean = false
    ): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(source, currentTitle)) return false
        if (!isNtkWebtoonSource(source, currentTitle) && !isNtkManhwaOrWebtoonEpisodePath(source.ntkEpisodePath)) {
            return false
        }
        // The reader's exact episode path is authoritative even when a legacy/recent Title object
        // still carries an app-local numeric id. Repair it before any adjacent episode-list fetch;
        // otherwise a valid /manhwa/u-*/u-* reader can accidentally request /manhwa/<local-id>.
        syncNtkTitlePathFromEpisode(currentTitle, source)
        if (direction > 0 && isNtkContinuousAdjacentCompletionPolicyActive() &&
            !hasNtkResolvedAdjacentMetadataCandidate(source, currentTitle, direction)
        ) {
            Log.d(
                TAG,
                "append_adjacent_immediate_exact_manifest_pending direction=$direction " +
                    "source=${source.ntkEpisodePath}",
            )
            return false
        }
        if (hasNtkResolvedAdjacentMetadataCandidate(source, currentTitle, direction)) {
            if (prefetchOnly) {
                return prefetchResolvedMetadataAdjacent(source, currentTitle, direction)
            }
            Log.d(
                TAG,
                "append_adjacent_immediate_generated_numeric_skip_metadata direction=$direction " +
                "source=${source.ntkEpisodePath}"
            )
            return false
        }
        var titleEpisodes = Utils.snapshotEpisodes(currentTitle)
        var authoritativeEpisodes = if (titleEpisodes.isNotEmpty()) {
            titleEpisodes
        } else {
            Utils.snapshotEpisodes(source)
        }
        if (authoritativeEpisodes.isEmpty() && source.isOnline) {
            val result = withRepositoryCancellation {
                imageRepository.fetchEpisodesForeground(currentTitle, it)
            }
            if (cancelled.get()) return false
            if (result == Title.LOAD_OK) {
                attachTitle()
                titleEpisodes = Utils.snapshotEpisodes(currentTitle)
                authoritativeEpisodes = if (titleEpisodes.isNotEmpty()) {
                    titleEpisodes
                } else {
                    Utils.snapshotEpisodes(source)
                }
                if (authoritativeEpisodes.isNotEmpty()) {
                    manga.setEps(authoritativeEpisodes)
                    source.setEps(authoritativeEpisodes)
                    persistNtkEpisodeSnapshot(currentTitle, authoritativeEpisodes)
                    source.title = currentTitle
                    source.titleId = currentTitle.id
                }
                if (hasNtkResolvedAdjacentMetadataCandidate(source, currentTitle, direction)) {
                    if (prefetchOnly) {
                        return prefetchResolvedMetadataAdjacent(source, currentTitle, direction)
                    }
                    Log.d(
                        TAG,
                        "append_adjacent_immediate_generated_numeric_skip_loaded_metadata " +
                            "direction=$direction source=${source.ntkEpisodePath} " +
                            "episodes=${authoritativeEpisodes.size}"
                    )
                    return false
                }
            } else {
                Log.d(
                    TAG,
                    "append_adjacent_numeric_synthetic_wait_metadata direction=$direction " +
                        "source=${source.ntkEpisodePath} result=$result"
                )
                return false
            }
        }
        if (!NtkAdjacentEpisodeAuthorityPolicy.maySynthesizeNumericCandidate(
                authoritativeEpisodes.size,
                source.isOnline
            )
        ) {
            Log.d(
                TAG,
                "append_adjacent_numeric_synthetic_block_authoritative direction=$direction " +
                    "source=${source.ntkEpisodePath} episodes=${authoritativeEpisodes.size} " +
                    "online=${source.isOnline}"
            )
            return false
        }
        val sourceParts = ntkNumericEpisodePathParts(source.ntkEpisodePath) ?: return false
        val step = if (direction > 0) 1L else if (direction < 0) -1L else return false
        val targetEpisodeId = sourceParts.third + step
        val target = ntkSyntheticNumericAdjacentCandidate(source, sourceParts, direction, targetEpisodeId)
            ?: return false
        target.title = currentTitle
        target.titleId = currentTitle.id
        target.mode = source.mode
        if (direction > 0) {
            rememberAdjacentStrictPredecessor(
                target.ntkEpisodePath,
                source.ntkEpisodePath,
            )
        }
        if (hasEpisode(target)) return false
        inheritNtkAppendGeneratedHints(target, source, currentTitle)
        val seeded = seedNtkAppendGeneratedUrlsFromNeighbor(target, source, currentTitle)
        if (seeded <= 0) return false
        val directUrls = target.getImgs(null)?.toList().orEmpty()
        val urls = directUrls.ifEmpty { imageRepository.imageUrls(target, appContext) }
        if (urls.isNullOrEmpty() || urls.none { isNtkGeneratedImageUrl(it) }) return false
        val publishUrls = completeKnownGeneratedAppendUrls(target, urls)
        if (publishUrls.isEmpty()) return false
        if (initialTailPreappend || prefetchOnly) {
            target.ntkEpisodePath?.trim()?.takeIf { it.isNotEmpty() }?.let {
                initialTailAdjacentPreappendTargetPaths.add(it)
            }
        }
        Log.d(
            TAG,
            "append_adjacent_immediate_generated_numeric direction=$direction source=${source.ntkEpisodePath} " +
                "target=${target.ntkEpisodePath} images=${publishUrls.size}"
        )
        val warmUrls = ntkBoundaryAppendWarmUrls(target, publishUrls, direction, silentMissing = true)
        if (!prefetchOnly) {
            if (shouldSkipActiveAdjacentPreStartForegroundStreams(target, direction)) {
                Log.d(
                    TAG,
                    "append_adjacent_numeric_pre_stream_skip_active target=${target.ntkEpisodePath} " +
                        "direction=$direction"
                )
            } else {
                startAdjacentForegroundStreams(target, warmUrls, direction, asyncLaunch = true)
            }
        }
        if (prefetchOnly) {
            val prepared = prepareInitialTailAdjacentRunway(target, publishUrls)
            if (!prepared) return false
            // Preparation may finish before the current tail becomes visible. Re-enter the
            // normal append path so its existing current-tail and atomic publish gates decide
            // when the already prepared runway can become part of the visible page structure.
            appendResolvedEpisode(target, publishUrls, direction)
            return true
        }
        appendResolvedEpisode(target, publishUrls, direction)
        return true
    }

    private fun prefetchResolvedMetadataAdjacent(
        source: Manga,
        currentTitle: Title,
        direction: Int,
        metadataOnly: Boolean = false,
    ): Boolean {
        val completionGatedForward =
            direction > 0 && isNtkContinuousAdjacentCompletionPolicyActive()
        if (completionGatedForward) {
            if (!isEpisodeFullyDrawableForAdjacent(source)) {
                Log.d(
                    TAG,
                    "append_adjacent_metadata_wait_current_complete " +
                        "direction=$direction path=${source.ntkEpisodePath}",
                )
                return false
            }
            NtkStrictEpisodeDiscoveryCoordinator
                .releaseAdjacentBodiesAfterPredecessorComplete(
                    source.ntkEpisodePath,
                    null,
                    strictExactForegroundViewerGenerationAtCreation,
                    strictExactViewerOwnerEpisodePathAtCreation,
                )
        }
        val titleEpisodes = Utils.snapshotEpisodes(currentTitle)
        val episodes = if (titleEpisodes.isNotEmpty()) titleEpisodes else Utils.snapshotEpisodes(source)
        val sourcePath = source.ntkEpisodePath?.trim().orEmpty()
        if (!metadataOnly && sourcePath.isNotEmpty()) {
            val prepared = preparedInitialAdjacentMetadata[sourcePath]
            val expected = adjacentEpisodeCandidates(source, episodes, direction).firstOrNull()
            val expectedPath = expected?.ntkEpisodePath?.trim().orEmpty()
            val preparedPath = prepared?.target?.ntkEpisodePath?.trim().orEmpty()
            if (
                prepared != null &&
                expectedPath.isNotEmpty() &&
                expectedPath == preparedPath &&
                preparedInitialAdjacentMetadata.remove(sourcePath, prepared)
            ) {
                var consumed = false
                try {
                    preparedPath.takeIf { it.isNotEmpty() }?.let {
                        initialTailAdjacentPreappendTargetPaths.add(it)
                    }
                    if (!prepareInitialTailAdjacentRunway(prepared.target, prepared.urls)) {
                        if (!cancelled.get()) {
                            preparedInitialAdjacentMetadata.putIfAbsent(sourcePath, prepared)
                        }
                        return false
                    }
                    Log.d(
                        TAG,
                        "append_adjacent_initial_metadata_take source=$sourcePath " +
                            "target=$preparedPath images=${prepared.urls.size} " +
                            "ageMs=${SystemClock.elapsedRealtime() - prepared.preparedAtMs}"
                    )
                    appendResolvedEpisode(prepared.target, prepared.urls, direction)
                    consumed = true
                    return true
                } finally {
                    if (!consumed && preparedInitialAdjacentMetadata[sourcePath] !== prepared) {
                        ReaderImageCache.releaseAdjacentNtkForegroundViewerPath(
                            preparedPath,
                            "initial_metadata_consume_failed"
                        )
                    }
                }
            }
        }
        // The immediate real neighbor is the only valid continuous-reader target. If its server
        // metadata is unavailable, stopping is safer than silently skipping a volume.
        for (sharedCandidate in adjacentEpisodeCandidates(source, episodes, direction).take(1)) {
            val candidate = isolatedAdjacentPrefetchCandidate(
                sharedCandidate,
                source,
                currentTitle,
                episodes,
            ) ?: continue
            if (hasEpisode(candidate)) continue
            inheritNtkAppendGeneratedHints(candidate, source, currentTitle)
            val candidatePath = candidate.ntkEpisodePath?.trim().orEmpty()
            // Tokenized `u-*` documents may join their first real body to the same fetch. On direct
            // Wi-Fi the completion gate above therefore precedes this untagged path grant; no
            // target document or joined body can compete with an unfinished current episode.
            // Open only the exact neighbor and revoke it on every unsuccessful exit.
            ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
                candidatePath,
                NTK_INITIAL_ADJACENT_PREFETCH_PATH_TTL_MS,
                "initial_tail_metadata_prefetch"
            )
            var keepAdjacentGrant = false
            try {
                if (metadataOnly && shouldYieldInitialAdjacentMetadata(source)) return false
                var appendLoad = loadAuthoritativeAdjacentUrlsForPrefetch(
                    candidate,
                    source,
                    currentTitle,
                    direction,
                    metadataSource = source.takeIf { metadataOnly },
                )
                if (
                    !cancelled.get() &&
                    !(metadataOnly && shouldYieldInitialAdjacentMetadata(source)) &&
                    (appendLoad.result != Title.LOAD_OK || appendLoad.urls.isEmpty())
                ) {
                    val cachedDocument = MainApplication.getHttpClient().cachedNtkViewerPayloadBody(
                        candidatePath,
                        NTK_ADJACENT_AUTHORITATIVE_DOCUMENT_MAX_AGE_MS
                    )
                    val cachedDocumentCount = Manga.ntkViewerPayloadPageCount(cachedDocument)
                    if (cachedDocumentCount > 0) {
                        // A document race can expose the authoritative page count before its
                        // complete direct-image manifest wins publication. Retrying once while
                        // the exact bounded path grant is still held is materially faster and
                        // safer than abandoning the runway until the user hits the boundary.
                        candidate.setImgs(null)
                        Log.d(
                            TAG,
                            "append_adjacent_authoritative_prefetch_retry source=${source.ntkEpisodePath} " +
                                "target=$candidatePath documentCount=$cachedDocumentCount"
                        )
                        appendLoad = loadAuthoritativeAdjacentUrlsForPrefetch(
                            candidate,
                            source,
                            currentTitle,
                            direction,
                            metadataSource = source.takeIf { metadataOnly },
                        )
                    }
                }
                if (cancelled.get()) return false
                if (metadataOnly && shouldYieldInitialAdjacentMetadata(source)) return false
                if (appendLoad.result != Title.LOAD_OK || appendLoad.urls.isEmpty()) continue
                if (shouldSkipLoadedNtkAdjacentCandidate(source, candidate, direction)) continue
                val publishUrls = completeKnownGeneratedAppendUrls(candidate, appendLoad.urls)
                if (
                    publishUrls.isEmpty() ||
                    publishUrls.none {
                        isNtkGeneratedImageUrl(it) ||
                            isNaverWebtoonPageImageUrl(it) ||
                            ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(it)
                    }
                ) {
                    continue
                }
                candidatePath.takeIf { it.isNotEmpty() }?.let {
                    initialTailAdjacentPreappendTargetPaths.add(it)
                }
                if (metadataOnly) {
                    val prepared = PreparedInitialAdjacentMetadata(
                        sourcePath = sourcePath,
                        target = candidate,
                        urls = publishUrls,
                        preparedAtMs = SystemClock.elapsedRealtime(),
                    )
                    preparedInitialAdjacentMetadata.put(sourcePath, prepared)?.let { previous ->
                        if (previous.target.ntkEpisodePath != candidate.ntkEpisodePath) {
                            ReaderImageCache.releaseAdjacentNtkForegroundViewerPath(
                                previous.target.ntkEpisodePath,
                                "initial_metadata_replaced"
                            )
                        }
                    }
                    keepAdjacentGrant = true
                    Log.d(
                        TAG,
                        "append_adjacent_initial_metadata_ready source=$sourcePath " +
                            "target=$candidatePath images=${publishUrls.size}"
                    )
                    return true
                }
                // prepareInitialTailAdjacentRunway owns the first four physical requests. The
                // grant above also lets the document's single joined first-body stream complete;
                // cached-file joining prevents a duplicate winning download.
                if (!prepareInitialTailAdjacentRunway(candidate, publishUrls)) return false
                keepAdjacentGrant = true
                Log.d(
                    TAG,
                    "append_adjacent_initial_prefetch_metadata source=${source.ntkEpisodePath} " +
                        "target=${candidate.ntkEpisodePath} images=${publishUrls.size}"
                )
                appendResolvedEpisode(candidate, publishUrls, direction)
                return true
            } finally {
                if (!keepAdjacentGrant) {
                    ReaderImageCache.releaseAdjacentNtkForegroundViewerPath(
                        candidatePath,
                        "initial_tail_metadata_prefetch_failed"
                    )
                }
            }
        }
        return false
    }

    /**
     * Episode-list Manga instances are shared by toolbar navigation, page-list refresh and both
     * boundary directions. Some volume lists reuse the visible volume number as `id`, so an older
     * and newer entry can even be Java-equal while their NTK paths differ. Never let a concurrent
     * metadata fetch mutate the object selected for the next-episode runway; freeze its resolved
     * path into an isolated fetch target first.
     */
    private fun isolatedAdjacentPrefetchCandidate(
        candidate: Manga,
        source: Manga,
        currentTitle: Title,
        episodes: List<Manga>,
    ): Manga? {
        val expectedPath = NtkStripDigests.normalizeEpisodePath(
            candidate.ntkEpisodePath?.trim().orEmpty()
        )
        if (expectedPath.isEmpty()) return null
        return Manga(
            candidate.id,
            candidate.name,
            candidate.date,
            candidate.baseMode,
        ).apply {
            mode = source.mode
            title = currentTitle
            titleId = currentTitle.id
            if (episodes.isNotEmpty()) setEps(episodes)
            // Set the path last so inferred duplicate volume IDs can never replace it.
            ntkEpisodePath = expectedPath
            ntkImageEpisodeId = candidate.ntkImageEpisodeId
            ntkImageWorkId = candidate.ntkImageWorkId
            ntkViewerPayloadHint = candidate.ntkViewerPayloadHint
            ntkImageCount = candidate.ntkImageCount
        }
    }

    private fun loadAuthoritativeAdjacentUrlsForPrefetch(
        target: Manga,
        source: Manga,
        currentTitle: Title,
        direction: Int,
        metadataSource: Manga? = null,
    ): AppendUrlLoad {
        // A real episode-list neighbor must not inherit the speculative generated
        // manifest used only for numeric discovery. Waiting for the episode metadata request is
        // cheaper than stalling the visible append on one guessed extension, and it preserves the
        // complete canonical page count for the remaining-runway publisher.
        val expectedPath = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath?.trim().orEmpty()
        )
        if (expectedPath.isEmpty()) return AppendUrlLoad(Title.LOAD_ERROR, emptyList())
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(
            source.ntkEpisodePath?.trim().orEmpty()
        )
        if (predecessorPath.isEmpty()) return AppendUrlLoad(Title.LOAD_ERROR, emptyList())
        rememberAdjacentStrictPredecessor(expectedPath, predecessorPath)
        target.ntkEpisodePath = expectedPath
        exactViewerApiAdjacentUrls(target)?.let {
            return AppendUrlLoad(Title.LOAD_OK, it)
        }
        if (
            direction > 0 &&
            isNtkContinuousAdjacentCompletionPolicyActive() &&
            isNtkSource(target, currentTitle) &&
            isNtkManhwaOrWebtoonEpisodePath(expectedPath)
        ) {
            if (!isEpisodeFullyDrawableForAdjacent(source)) {
                Log.d(
                    TAG,
                    "append_adjacent_wifi_exact_manifest_wait_current_complete " +
                        "direction=$direction path=$expectedPath",
                )
                return AppendUrlLoad(Title.LOAD_ERROR, emptyList())
            }
            // Completion warmup normally starts this exact owner before the physical boundary.
            // The last source can, however, become drawable through the blocker-rehydrate path
            // after the final viewport callback has already been coalesced.  In that legitimate
            // ordering the boundary task is the first observer that owns both facts: the exact
            // provider/list target and a fully drawable predecessor.  Start-or-join the same
            // completion claim here before waiting for its manifest.  Merely waiting left B -> C
            // permanently parked because no other component was responsible for launching C.
            // The claim linearizes concurrent tail-prefetch and boundary callers, and the
            // Activity listener still owns discovery plus native texture authorization.
            val selectedExactTargetPath = startForwardAdjacentExactDiscoveryAtCompletion(
                source,
                resolvedNext = target,
                onResolvedForwardPath = null,
            )
            if (!selectedExactTargetPath.equals(expectedPath, ignoreCase = true)) {
                Log.d(
                    TAG,
                    "append_adjacent_wifi_exact_manifest_owner_unavailable " +
                        "direction=$direction predecessor=$predecessorPath " +
                        "expected=$expectedPath selected=${selectedExactTargetPath.orEmpty()}",
                )
                return AppendUrlLoad(Title.LOAD_ERROR, emptyList())
            }
            releaseClaimedForwardAdjacentBodiesAfterPredecessorComplete(
                predecessorPath,
                selectedExactTargetPath,
            )
            releaseAdjacentStrictClaimsAfterPredecessorComplete(predecessorPath)
            NtkStrictEpisodeDiscoveryCoordinator
                .releaseAdjacentBodiesAfterPredecessorComplete(
                    source.ntkEpisodePath,
                    selectedExactTargetPath,
                    strictExactForegroundViewerGenerationAtCreation,
                    strictExactViewerOwnerEpisodePathAtCreation,
                )
            // Use the same isolated exact-manifest owner as a cold click, but only after every
            // current drawable is complete. This keeps document/grant/API work out of the current
            // episode's network budget as well as keeping image bodies and decode isolated.
            // A viewer document can authoritatively expose only the page count while the canonical
            // image API uses mixed extensions or opaque assets. Turning that count back into
            // pNNN.jpg guesses made real next episodes (for example an 80-page webtoon epilogue)
            // retry four 404s until the reader hit a permanent physical bottom.
            val exactUrls = waitForExactViewerApiAdjacentUrls(
                target,
                predecessorPath,
                NTK_APPEND_EXACT_MANIFEST_WAIT_MS,
            )
            Log.d(
                TAG,
                "append_adjacent_wifi_exact_manifest direction=$direction path=$expectedPath " +
                    "images=${exactUrls.size}",
            )
            return if (exactUrls.isNotEmpty()) {
                AppendUrlLoad(Title.LOAD_OK, exactUrls)
            } else {
                AppendUrlLoad(Title.LOAD_ERROR, emptyList())
            }
        }
        target.setImgs(null)
        if (isNtkSource(target, currentTitle) &&
            isNtkSyntheticEpisodePath(expectedPath)
        ) {
            // Tokenized `u-*` documents contain unrelated board-upload <img> elements (ads,
            // recommendations and thumbnails). Their count can coincidentally equal the real page
            // count, so document-count matching cannot turn them into a page manifest.
            if (metadataSource != null) {
                Log.d(
                    TAG,
                    "append_adjacent_slug_exact_defer_current_active path=$expectedPath"
                )
                return AppendUrlLoad(Title.LOAD_ERROR, emptyList())
            }
            val exactUrls = waitForExactViewerApiAdjacentUrls(
                target,
                predecessorPath,
                NTK_APPEND_EXACT_MANIFEST_WAIT_MS,
            )
            if (exactUrls.isEmpty()) {
                Log.w(
                    TAG,
                    "append_adjacent_slug_exact_manifest_unavailable path=$expectedPath"
                )
                return AppendUrlLoad(Title.LOAD_ERROR, emptyList())
            }
            return AppendUrlLoad(Title.LOAD_OK, exactUrls)
        }
        if (metadataSource != null && shouldYieldInitialAdjacentMetadata(metadataSource)) {
            return AppendUrlLoad(Title.LOAD_ERROR, emptyList())
        }
        val metadataSourcePath = metadataSource?.ntkEpisodePath?.trim().orEmpty()
        val cancellation = repositoryCancellation(userVisible = true)
        val activeFetch = metadataSource?.let {
            ActiveInitialAdjacentMetadataFetch(it, cancellation)
        }
        if (activeFetch != null && metadataSourcePath.isNotEmpty()) {
            activeInitialAdjacentMetadataFetches.put(metadataSourcePath, activeFetch)?.let { previous ->
                if (previous !== activeFetch) previous.cancellation.cancel()
            }
            // DOWN can race the registration above. Recheck after publication so a fetch that
            // became redundant in that window never survives into a physical moving frame.
            if (shouldYieldInitialAdjacentMetadata(metadataSource)) cancellation.cancel()
        }
        val result = try {
            if (cancellation.isCancelled) {
                Title.LOAD_ERROR
            } else if (shouldPreferVerifiedApiAppend(target, currentTitle)) {
                imageRepository.fetchViewerInitialWithMode(target, cancellation, "api-strict")
            } else {
                imageRepository.fetchViewerInitial(target, cancellation)
            }
        } catch (e: Exception) {
            if (!cancellation.isCancelled && !isExpectedCancellation(e)) recordIfUnexpected(e)
            Title.LOAD_ERROR
        } finally {
            if (activeFetch != null && metadataSourcePath.isNotEmpty()) {
                activeInitialAdjacentMetadataFetches.remove(metadataSourcePath, activeFetch)
            }
            releaseRepositoryCancellation(cancellation)
        }
        if (metadataSource != null && shouldYieldInitialAdjacentMetadata(metadataSource)) {
            target.setImgs(null)
            return AppendUrlLoad(Title.LOAD_ERROR, emptyList())
        }
        val path = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath?.trim().orEmpty()
        )
        if (!path.equals(expectedPath, ignoreCase = true)) {
            // A wrong-volume manifest must never be relabelled and attached as the requested next
            // episode. Fail closed, restore the frozen identity and let the next bounded attempt
            // fetch the correct path.
            Log.w(
                TAG,
                "append_adjacent_authoritative_path_changed direction=$direction " +
                    "expected=$expectedPath actual=$path targetId=${target.id}"
            )
            target.setImgs(null)
            target.ntkEpisodePath = expectedPath
            return AppendUrlLoad(Title.LOAD_ERROR, emptyList())
        }
        val freshDocumentBody = if (path.isNotEmpty()) {
            MainApplication.getHttpClient().cachedNtkViewerPayloadBody(
                path,
                NTK_ADJACENT_AUTHORITATIVE_DOCUMENT_MAX_AGE_MS
            )
        } else {
            ""
        }
        val clickPayloadCount = target.getExactNtkClickPayloadImageCount(path)
        val freshDocumentCount = Manga.ntkViewerPayloadPageCount(freshDocumentBody)
        val authoritativeCount = NtkAdjacentEpisodeAuthorityPolicy.matchedAuthoritativePageCount(
            clickPayloadCount = clickPayloadCount,
            freshViewerDocumentCount = freshDocumentCount,
            maximumPageCount = NTK_MAX_AUTHORITATIVE_ADJACENT_PAGES
        )
        if (authoritativeCount > 0) {
            // This count came from the freshly fetched viewer document (or its exact click
            // payload), not from the speculative generated-URL seed. Preserve that authority so
            // completeKnownGeneratedAppendUrls cannot collapse a real 180-page volume back to
            // the conservative 30-page unknown-manifest ceiling.
            ReaderImageCache.rememberTrustedNtkImageApiCount(path, authoritativeCount)
            target.setNtkImageCount(authoritativeCount)
            seedNtkAppendGeneratedUrlsFromNeighbor(
                target,
                source,
                currentTitle,
                allowSpeculativeExtension = false,
            )
            val seed = imageRepository.imageUrls(target, appContext)
                .firstOrNull { isNtkGeneratedImageUrl(it) }
            if (seed != null) {
                val fullManifest = ArrayList<String>(authoritativeCount)
                for (page in 1..authoritativeCount) {
                    val generated = ntkGeneratedImageUrlForTarget(seed, target, page) ?: break
                    fullManifest.add(generated)
                }
                if (fullManifest.size == authoritativeCount) {
                    target.setNtkImageCount(authoritativeCount)
                    target.setImgs(fullManifest)
                    Log.d(
                        TAG,
                        "append_adjacent_authoritative_document_manifest direction=$direction " +
                            "targetId=${target.id} path=$path images=${fullManifest.size} " +
                            "fetchResult=$result documentBytes=${freshDocumentBody.length}"
                    )
                    return AppendUrlLoad(Title.LOAD_OK, fullManifest)
                }
            }
        }
        val urls = imageRepository.imageUrls(target, appContext)
        Log.d(
            TAG,
            "append_adjacent_authoritative_prefetch direction=$direction targetId=${target.id} " +
                "path=$path result=$result images=${urls.size} clickCount=$clickPayloadCount " +
                "documentCount=$freshDocumentCount documentBytes=${freshDocumentBody.length}"
        )
        if (result != Title.LOAD_OK || urls.isEmpty()) {
            return AppendUrlLoad(result, emptyList())
        }
        return AppendUrlLoad(Title.LOAD_OK, completeKnownGeneratedAppendUrls(target, urls))
    }

    private fun fetchInitialAdjacentRunwayFile(
        target: Manga,
        page: PageRef,
        path: String,
        startedAt: Long,
    ): File {
        val image = page.image.orEmpty()
        if (image.isBlank()) throw java.io.IOException("Adjacent runway page has no image")
        var file = ReaderImageCache.cachedFile(appContext, target, image)
        var fetchAttempts = 0
        var fetchFailure: Exception? = null
        while (
            file == null &&
            NtkAdjacentRunwayPreparationPolicy.mayRetryFileFetch(
                fetchAttempts,
                startedAt,
                SystemClock.elapsedRealtime()
            )
        ) {
            fetchAttempts++
            try {
                file = withProtectedNumericNetworkPermit(target) {
                    ReaderImageCache.getOrFetchFileForeground(
                        appContext,
                        target,
                        image,
                        imageCancellation,
                        visiblePriority = true
                    )
                }
            } catch (e: Exception) {
                if (cancelled.get() || Thread.currentThread().isInterrupted) throw e
                fetchFailure = e
                file = ReaderImageCache.cachedFile(appContext, target, image)
                if (file == null) {
                    Log.d(
                        TAG,
                        "append_adjacent_initial_prefetch_retry path=$path " +
                            "page=${page.sourceIndex + 1} attempt=$fetchAttempts " +
                            "error=${e.javaClass.simpleName}:${e.message}"
                    )
                }
            }
        }
        return file ?: throw java.io.IOException(
            "Adjacent runway page fetch exhausted: page=${page.sourceIndex + 1}",
            fetchFailure
        )
    }

    private fun prepareInitialTailAdjacentRunway(target: Manga, urls: List<String>): Boolean {
        val path = target.ntkEpisodePath?.trim().orEmpty()
        if (path.isEmpty() || urls.isEmpty()) return false
        preparedInitialAdjacentRunways[path]?.let { prepared ->
            if (prepared.batch.deliveries.isNotEmpty()) return true
        }
        val preparation = InitialAdjacentRunwayPreparation(
            token = Any(),
            startedAtMs = SystemClock.elapsedRealtime()
        )
        if (preparingInitialAdjacentRunways.putIfAbsent(path, preparation) != null) return false
        ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
            path,
            NTK_INITIAL_ADJACENT_PREFETCH_PATH_TTL_MS,
            "initial_tail_prefetch"
        )
        val initialDrawablePages = directWifiInitialAttachedRunwayPages(target)
        val refs = pageRefsForEpisode(target, urls, ReaderSurfaceView.DIRECTION_NEXT)
            .filter { it.transitionTitle == null }
            .take(initialDrawablePages)
        if (refs.size < minOf(urls.size, initialDrawablePages)) {
            finishInitialAdjacentRunwayPreparation(path, preparation)
            return false
        }
        val predictedStart = synchronized(pagesLock) { pages.size }
        val startedAt = SystemClock.elapsedRealtime()
        val exactAuthority = exactViewerApiAdjacentAuthority(target)
        val strictExactManhwaLeaseRequired = refs.any(::requiresStrictAdjacentExactBody)
        if (exactAuthority != null && strictExactManhwaLeaseRequired &&
            !ensureAdjacentStrictSourceClaim(target, exactAuthority)
        ) {
            // A live exact manhwa manifest must never fall through to the generic cache merely
            // because its generation-bound source claim has not reached this session yet.
            holdOrRecoverAdjacentStrictSource(target)
            finishInitialAdjacentRunwayPreparation(path, preparation)
            return false
        }
        if (exactAuthority != null && ensureAdjacentStrictSourceClaim(target, exactAuthority)) {
            try {
                val deadline = startedAt + NtkAdjacentRunwayPreparationPolicy.MAX_JOIN_MS
                var strictBodiesReady = false
                while (!cancelled.get() && SystemClock.elapsedRealtime() < deadline) {
                    strictBodiesReady = refs.all { page ->
                        strictAdjacentBodyDescriptor(page) != null ||
                            (!requiresStrictAdjacentExactBody(page) &&
                                strictAdjacentPublishedBody(page) != null)
                    }
                    if (strictBodiesReady) break
                    holdOrRecoverAdjacentStrictSource(target)
                    preparation.residentBodySignal.tryAcquire(
                        NTK_APPEND_EARLY_GENERATED_POLL_MS,
                        TimeUnit.MILLISECONDS,
                    )
                }
                if (!strictBodiesReady) {
                    Log.d(
                        TAG,
                        "append_adjacent_initial_strict_source_wait_timeout path=$path " +
                            "pages=${refs.size} ms=${SystemClock.elapsedRealtime() - startedAt}",
                    )
                    return false
                }
                if (isDirectWifiStrictAdjacentRunwayProfile(target) &&
                    isNtkManhwaOrWebtoonEpisodePath(path) &&
                    refs.singleOrNull()?.sourceIndex == 0
                ) {
                    // The sparse exact publisher is the sole owner of direct-Wi-Fi p0. Starting
                    // the older private HardwareBuffer decode here races that publisher after the
                    // same descriptor becomes resident: the sparse software head is already on
                    // Surface while this task allocates a second p0 behind the structural-card
                    // allocator. On gfxstream that duplicate allocation serialized for 238 ms and
                    // stopped otherwise-ready physical frames. Hand off both /manhwa/ and
                    // /webtoon/ to the identity-bound sparse publisher; it installs p0 and then
                    // wakes the software p1 runway without skipping any source body or proof.
                    Log.d(TAG, "append_adjacent_exact_p0_prefetch_deferred_to_sparse_head path=$path")
                    // The resident p0 body is ready. Report preparation success so the caller
                    // continues into appendResolvedEpisode(), where the sparse head is decoded and
                    // published. Returning false here is a terminal handoff bug: every caller treats
                    // it as preparation failure and skips the publisher entirely.
                    return true
                }
                if (strictExactManhwaLeaseRequired) {
                    // Decode only the exact p0 head into private pooled storage while the current
                    // episode remains authoritative. Structure, scroll and metadata are untouched.
                    // Waiting until the clean-tail callback to allocate these same slots produced
                    // a measured 465 ms boundary wall on gfxstream. The prepared identity now
                    // includes path+manifest digest+count, so it cannot cross a refreshed route or
                    // generation before the atomic publisher consumes it.
                    val batch = prepareAdjacentRunwayDrawableBatch(
                        predictedStart,
                        refs,
                        NtkAdjacentExactDecodeMotionPolicy.PRIVATE_EXACT_HEAD_STAGING_REASON,
                        requireStrictDescriptor = true,
                    ) ?: return false
                    return publishPreparedInitialAdjacentRunway(
                        path,
                        preparation,
                        refs,
                        batch,
                        startedAt,
                        "strict_exact_head",
                    )
                }
                val batch = prepareAdjacentRunwayDrawableBatch(
                    predictedStart,
                    refs,
                    "initial_strict_source",
                    requireStrictDescriptor = strictExactManhwaLeaseRequired,
                ) ?: return false
                return publishPreparedInitialAdjacentRunway(
                    path,
                    preparation,
                    refs,
                    batch,
                    startedAt,
                    "strict_source",
                )
            } catch (e: Exception) {
                if (e is InterruptedException) Thread.currentThread().interrupt()
                if (!cancelled.get()) {
                    Log.d(
                        TAG,
                        "append_adjacent_initial_strict_source_error path=$path " +
                            "error=${e.javaClass.simpleName}:${e.message}",
                    )
                    if (!isExpectedCancellation(e)) recordIfUnexpected(e)
                }
                return false
            } finally {
                finishInitialAdjacentRunwayPreparation(path, preparation)
            }
        }

        val deliveries = ArrayList<Delivery>(refs.size)
        val fetchTasks = refs.map { page ->
            FutureTask<File> {
                fetchInitialAdjacentRunwayFile(target, page, path, startedAt)
            }
        }
        try {
            fetchTasks.forEach(initialAdjacentRunwayNetwork::execute)
            refs.forEachIndexed { offset, page ->
                if (cancelled.get()) throw java.io.IOException("Reader session cancelled")
                val file = try {
                    fetchTasks[offset].get()
                } catch (e: ExecutionException) {
                    val cause = e.cause
                    if (cause is Exception) throw cause
                    throw e
                }
                val requestedWidth = ntkProofTargetWidth()
                val result = decodePage(
                    predictedStart + offset,
                    page,
                    file,
                    requestedWidth,
                    proofDrawable = true
                )
                prepareDecodeResultForDraw(result)
                deliveries.add(
                    Delivery(
                        predictedStart + offset,
                        page,
                        result,
                        startedAt,
                        requestedWidth,
                        retainWhenBusy = false,
                        proofDrawable = true
                    )
                )
            }
            return publishPreparedInitialAdjacentRunway(
                path,
                preparation,
                refs,
                AdjacentRunwayDrawableBatch(deliveries),
                startedAt,
                "legacy_cache",
            )
        } catch (e: Exception) {
            if (e is InterruptedException) Thread.currentThread().interrupt()
            deliveries.forEach { recycleDecodeResult(it.result) }
            if (!cancelled.get()) {
                Log.d(
                    TAG,
                    "append_adjacent_initial_prefetch_error path=$path ready=${deliveries.size} " +
                        "error=${e.javaClass.simpleName}:${e.message}"
                )
                if (!isExpectedCancellation(e)) recordIfUnexpected(e)
            }
            return false
        } finally {
            fetchTasks.forEach { task ->
                if (!task.isDone) task.cancel(true)
            }
            finishInitialAdjacentRunwayPreparation(path, preparation)
        }
    }

    private fun publishPreparedInitialAdjacentRunway(
        path: String,
        preparation: InitialAdjacentRunwayPreparation,
        refs: List<PageRef>,
        batch: AdjacentRunwayDrawableBatch,
        startedAt: Long,
        source: String,
    ): Boolean {
        val prepared = PreparedAdjacentRunwayBatch(
            pageKeys = refs.map(::runwayPageRefIdentity),
            batch = batch,
            preparedAtMs = SystemClock.elapsedRealtime(),
        )
        if (cancelled.get()) {
            recycleAdjacentRunwayDrawableBatch(prepared.batch)
            return false
        }
        if (preparingInitialAdjacentRunways[path] !== preparation) {
            recycleAdjacentRunwayDrawableBatch(prepared.batch)
            Log.d(
                TAG,
                "append_adjacent_initial_prefetch_superseded path=$path " +
                    "pages=${batch.deliveries.size} source=$source",
            )
            return false
        }
        preparedInitialAdjacentRunways.put(path, prepared)?.let { previous ->
            recycleAdjacentRunwayDrawableBatch(previous.batch)
        }
        Log.d(
            TAG,
            "append_adjacent_initial_prefetch_ready path=$path pages=${batch.deliveries.size} " +
                "ms=${SystemClock.elapsedRealtime() - startedAt} source=$source",
        )
        return true
    }

    private fun hasNtkResolvedAdjacentMetadataCandidate(
        source: Manga,
        currentTitle: Title,
        direction: Int
    ): Boolean {
        if (!isNtkSource(source, currentTitle) || direction == 0) return false
        fun accepts(candidate: Manga?): Boolean {
            if (candidate == null) return false
            return isValidAdjacentEpisodeCandidate(source, candidate) &&
                !looseSameEpisodeForAppend(source, candidate)
        }
        if (accepts(ntkTrustedProvidedAdjacentCandidate(source, direction))) return true

        val titleEpisodes = Utils.snapshotEpisodes(currentTitle)
        val episodes = if (titleEpisodes.isNotEmpty()) titleEpisodes else Utils.snapshotEpisodes(source)
        if (episodes.isEmpty()) return false
        if (accepts(ntkVisibleNumberAdjacentCandidate(source, episodes, direction))) return true
        if (accepts(ntkNumericPathAdjacentCandidate(source, episodes, direction))) return true

        val sourceIndex = looseEpisodeIndexForAppend(episodes, source)
        if (sourceIndex >= 0) {
            var index = if (direction < 0) sourceIndex + 1 else sourceIndex - 1
            while (index >= 0 && index < episodes.size) {
                val candidate = episodes[index]
                if (accepts(candidate)) return true
                index += if (direction < 0) 1 else -1
            }
        }

        val matcher = ViewerEpisodeResolver.EpisodeMatcher { first, second ->
            looseSameEpisodeForAppend(first, second)
        }
        val resolved = if (direction < 0) {
            ViewerEpisodeResolver.previousCandidateFromList(source, episodes, null, source.title ?: title, matcher)
        } else {
            ViewerEpisodeResolver.nextCandidateFromList(source, episodes, null, source.title ?: title, matcher)
        }
        return accepts(resolved)
    }

    private fun adjacentAppendStartKey(anchor: Int, direction: Int): String {
        if (!isNtkSource(manga, title) || direction == 0) return ""
        val source = pageRef(anchor)?.manga ?: manga
        val identity = Manga.episodeIdentityKey(source)
        val path = source.ntkEpisodePath?.trim().orEmpty()
        return "$direction:$identity:$path"
    }

    private fun shouldDeferChainedAdjacentForActiveRemaining(source: Manga?, direction: Int): Boolean {
        if (source == null || direction <= 0) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isActiveGeneratedTouchOrQuiet() && !viewportBusy.get()) return false
        val sourcePath = activeRemainingAdjacentRunwayTargetPath(source)
        if (sourcePath.isEmpty()) return false
        return activeRemainingAdjacentRunwayTargetPaths.contains(sourcePath)
    }

    private fun shouldSkipActiveAdjacentPreStartForegroundStreams(target: Manga, direction: Int): Boolean {
        if (direction <= 0) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        if (hasForwardAdjacentBoundaryDemand(target, direction)) return false
        if (isCurrentEpisodeCompleteForImmediateAdjacentStream(target, direction)) return false
        val known = imageRepository.imageUrls(target, appContext).ifEmpty {
            target.getImgs(null)?.toList().orEmpty()
        }
        if (known.any { isNtkGeneratedImageUrl(it) }) return false
        return isActiveGeneratedTouchOrQuiet() || viewportBusy.get()
    }

    private fun isCurrentEpisodeCompleteForImmediateAdjacentStream(
        target: Manga,
        direction: Int,
    ): Boolean {
        if (direction <= 0) return false
        if (!isImmediateNtkGeneratedUx()) return false
        val enforceFullCurrentEpisode =
            isNtkContinuousAdjacentCompletionPolicyActive()
        if (!enforceFullCurrentEpisode &&
            hasForwardAdjacentBoundaryDemand(target, direction)
        ) return true
        val anchor = currentViewportAnchor.get()
        if (anchor < 0) return false
        val snapshot = synchronized(pagesLock) {
            if (pages.isEmpty()) return@synchronized false
            val boundedAnchor = anchor.coerceIn(0, pages.lastIndex)
            var sourcePageIndex = boundedAnchor
            while (sourcePageIndex >= 0 && pages[sourcePageIndex].transitionTitle != null) {
                sourcePageIndex--
            }
            val source = pages.getOrNull(sourcePageIndex)?.manga ?: return@synchronized false
            if (!isNtkSource(source, title) ||
                !isNtkManhwaOrWebtoonEpisodePath(source.ntkEpisodePath)
            ) {
                return@synchronized false
            }
            val differentEpisode = !looseSameEpisodeForAppend(source, target)
            val sourceRefs = pages.withIndex().filter { (_, page) ->
                page.transitionTitle == null && looseSameEpisodeForAppend(page.manga, source)
            }
            val authoritativeCount = canonicalEpisodeImageCount(
                source,
                sourceRefs.map { it.value },
            )
            AdjacentCurrentCompletionSnapshot(
                boundedAnchor = boundedAnchor,
                differentEpisode = differentEpisode,
                episode = source,
                authoritativeCount = authoritativeCount,
                sourceRefs = sourceRefs,
            )
        }
        if (snapshot !is AdjacentCurrentCompletionSnapshot) return false
        // Strict native drawables can be physically installed before the legacy delivery ledger
        // catches up. Inspecting the authoritative surface outside pagesLock avoids lock inversion
        // and prevents a completed current episode from being mistaken for incomplete.
        val sourceIndexes = snapshot.sourceRefs.map { it.value.sourceIndex }
        val drawableReady = snapshot.sourceRefs.map { (index, page) ->
            hasCanonicalDrawableCompletion(page) ||
                hasListenerDrawableDelivery(index, page) ||
                hasDeliveredBitmap(index)
        }
        val completeCurrentStructure = NtkCompletedForwardEpisodePolicy.isComplete(
            authoritativeCount = snapshot.authoritativeCount,
            sourceIndexes = sourceIndexes,
            drawableReady = List(sourceIndexes.size) { true },
        )
        val allCurrentDrawablesReady = NtkCompletedForwardEpisodePolicy.isComplete(
            authoritativeCount = snapshot.authoritativeCount,
            sourceIndexes = sourceIndexes,
            drawableReady = drawableReady,
            requiredFirstSource = requiredForwardFirstSource(
                snapshot.episode,
                snapshot.authoritativeCount,
            ),
        )
        if (enforceFullCurrentEpisode) {
            return snapshot.differentEpisode &&
                completeCurrentStructure &&
                allCurrentDrawablesReady
        }
        val currentTailDemandReady = completeCurrentStructure &&
            snapshot.sourceRefs.lastOrNull()?.let { (index, page) ->
                snapshot.boundedAnchor >= index &&
                    (hasDeliveredOrPendingDrawable(index) ||
                        hasListenerDrawableDelivery(index, page) ||
                        hasDeliveredBitmap(index))
            } == true
        return NtkAdjacentRunwayPreparationPolicy.shouldBypassAdjacentInputQuiet(
            direction = direction,
            differentEpisode = snapshot.differentEpisode,
            completeCurrentStructure = completeCurrentStructure,
            allCurrentDrawablesReady = allCurrentDrawablesReady,
            currentTailDemandReady = currentTailDemandReady,
        )
    }

    private data class AdjacentCurrentCompletionSnapshot(
        val boundedAnchor: Int,
        val differentEpisode: Boolean,
        val episode: Manga,
        val authoritativeCount: Int,
        val sourceRefs: List<IndexedValue<PageRef>>,
    )

    private fun requiredForwardFirstSource(source: Manga, authoritativeCount: Int): Int {
        if (strictForwardSourceFloor <= 0 || authoritativeCount <= 0 ||
            !looseSameEpisodeForAppend(source, manga)
        ) return 0
        return strictForwardSourceFloor.coerceIn(0, authoritativeCount - 1)
    }

    private fun isNtkContinuousAdjacentCompletionPolicyActive(): Boolean {
        // The shared HTTP client follows the currently selected home-site mode and can change
        // independently of an already-open reader.  Using that global bit here made a WFWF
        // episode inherit NTK's forward-only completion policy whenever the home screen happened
        // to be set to NTK, which disabled the physical previous-episode boundary entirely.
        // Bind the policy to this session's immutable source identity instead.
        return isNtkSource(manga, title)
    }

    private fun isDirectWifiStrictAdjacentTransportActive(): Boolean {
        val httpClient = MainApplication.getHttpClient()
        if (!isNtkContinuousAdjacentCompletionPolicyActive()) return false
        return runCatching {
            httpClient.isNtkWifiTransportActive() &&
                !httpClient.isNtkCellularResilientTransportActive()
        }.getOrDefault(false)
    }

    /**
     * Once an exact adjacent source is claimed, its transport profile is part of that immutable
     * source generation. The process-wide HTTP client can change while p0 is decoding (for
     * example when an unrelated WebView renderer is replaced); consulting only that mutable bit
     * used to publish p0 generically and strand the already-resident p1-p3 suffix offscreen.
     */
    private fun isDirectWifiStrictAdjacentRunwayProfile(
        target: Manga? = null,
        episodePath: String? = target?.ntkEpisodePath,
    ): Boolean {
        if (!isNtkContinuousAdjacentCompletionPolicyActive()) return false
        val path = NtkStripDigests.normalizeEpisodePath(episodePath.orEmpty())
        if (path.isNotEmpty()) {
            val claim = adjacentStrictSourceClaims[path]
            // Profile lookup is deliberately lock-free. Authority/liveness is revalidated by the
            // descriptor and publication gates; a terminal claim must remain fail-closed rather
            // than falling through to the generic cache during its retirement interval.
            if (claim?.directWifiRunwayProfile == true) {
                return true
            }
            if (NtkStrictEpisodeDiscoveryCoordinator.isDirectWifiAdjacentRouteProfile(
                    path,
                    claim?.episode?.value ?: 0L,
                )
            ) {
                return true
            }
        }
        return isDirectWifiStrictAdjacentTransportActive()
    }

    private fun isEpisodeFullyDrawableForAdjacent(source: Manga): Boolean {
        val snapshot = synchronized(pagesLock) {
            val refs = pages.withIndex().filter { (_, page) ->
                page.transitionTitle == null &&
                    looseSameEpisodeForAppend(page.manga, source)
            }
            if (refs.isEmpty()) return@synchronized null
            val authoritativeCount = canonicalEpisodeImageCount(
                source,
                refs.map { it.value },
            )
            refs to authoritativeCount
        } ?: return false
        return NtkCompletedForwardEpisodePolicy.isComplete(
            authoritativeCount = snapshot.second,
            sourceIndexes = snapshot.first.map { it.value.sourceIndex },
            drawableReady = snapshot.first.map { (index, page) ->
                hasCanonicalDrawableCompletion(page) ||
                    hasListenerDrawableDelivery(index, page) ||
                    hasDeliveredBitmap(index)
            },
            requiredFirstSource = requiredForwardFirstSource(source, snapshot.second),
        )
    }

    private fun markForwardAdjacentBoundaryDemand(target: Manga, direction: Int) {
        if (direction <= 0) return
        val key = activeRemainingAdjacentRunwayTargetPath(target)
        if (key.isEmpty()) return
        forwardAdjacentBoundaryDemandAtMs[key] = SystemClock.elapsedRealtime()
        Log.d(
            TAG,
            "append_adjacent_boundary_demand targetId=${target.id} " +
                "path=${target.ntkEpisodePath} direction=$direction"
        )
    }

    private fun hasForwardAdjacentBoundaryDemand(target: Manga, direction: Int): Boolean {
        if (direction <= 0) return false
        val key = activeRemainingAdjacentRunwayTargetPath(target)
        if (key.isEmpty()) return false
        val demandedAtMs = forwardAdjacentBoundaryDemandAtMs[key] ?: return false
        val ageMs = SystemClock.elapsedRealtime() - demandedAtMs
        if (ageMs in 0..NTK_FORWARD_ADJACENT_BOUNDARY_DEMAND_TTL_MS) return true
        forwardAdjacentBoundaryDemandAtMs.remove(key, demandedAtMs)
        return false
    }

    private fun trimRecentAdjacentAppendStarts(nowMs: Long) {
        for ((key, startedAtMs) in recentAdjacentAppendStartAtMs) {
            if (nowMs - startedAtMs > NTK_ADJACENT_APPEND_START_SUPPRESS_MS * 4L) {
                recentAdjacentAppendStartAtMs.remove(key, startedAtMs)
            }
        }
    }

    private fun ntkBoundaryAppendWarmUrls(
        target: Manga,
        urls: List<String>,
        direction: Int,
        silentMissing: Boolean
    ): List<String> {
        if (!silentMissing || !isNtkSource(target, title)) return urls
        if (isImmediateNtkGeneratedUx() && urls.any { isNtkGeneratedImageUrl(it) }) {
            val limited = urls.take(adjacentInitialForegroundStreamPages(target, urls, direction))
            Log.d(
                TAG,
                "append_adjacent_boundary_warm_limited_immediate path=${target.ntkEpisodePath} " +
                    "warm=${limited.size} original=${urls.size}"
            )
            return limited
        }
        if (urls.size <= NTK_APPEND_EARLY_PUBLISH_PAGES) return urls
        if (!urls.any { isNtkGeneratedImageUrl(it) }) return urls
        val limited = urls.take(NTK_APPEND_EARLY_PUBLISH_PAGES)
        Log.d(
            TAG,
            "append_adjacent_boundary_warm_limited path=${target.ntkEpisodePath} " +
                "warm=${limited.size} original=${urls.size}"
        )
        return limited
    }

    private fun completeKnownGeneratedAppendUrls(target: Manga, urls: List<String>): List<String> {
        if (!isNtkSource(target, title) || urls.isEmpty()) return urls
        if (urls.none { isNtkGeneratedImageUrl(it) }) return urls
        val knownCount = target.ntkImageCount
        val effectiveKnownCount = effectiveGeneratedAppendCount(target, knownCount)
        if (effectiveKnownCount != knownCount && effectiveKnownCount > 0) {
            target.setNtkImageCount(effectiveKnownCount)
        }
        if (effectiveKnownCount <= urls.size || effectiveKnownCount <= 0) return urls
        val seed = urls.firstOrNull { isNtkGeneratedImageUrl(it) } ?: return urls
        val expanded = ArrayList<String>(effectiveKnownCount)
        for (page in 1..effectiveKnownCount) {
            val generated = ntkGeneratedImageUrlForTarget(seed, target, page) ?: break
            if (ReaderImageCache.isKnownNtkGeneratedNotFound(target, generated)) break
            expanded.add(generated)
        }
        if (expanded.size <= urls.size) return urls
        target.setImgs(ArrayList(expanded))
        Log.d(
            TAG,
            "append_adjacent_generated_expand_to_known path=${target.ntkEpisodePath} " +
                "from=${urls.size} to=${expanded.size} known=$knownCount effective=$effectiveKnownCount"
        )
        return expanded
    }

    private fun effectiveGeneratedAppendCount(target: Manga, knownCount: Int): Int {
        if (knownCount <= 0) return knownCount
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return knownCount
        val trustedApiCount = ReaderImageCache.trustedNtkImageApiCount(target.ntkEpisodePath, 0L)
        if (trustedApiCount > 0) return minOf(knownCount, trustedApiCount)
        if (knownCount <= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD) return knownCount
        return minOf(knownCount, NTK_UNTRUSTED_GENERATED_APPEND_MAX_PAGES)
    }

    private fun ntkAdjacentAppendStartDelayMs(): Long {
        if (!isNtkSource(manga, title)) return 0L
        return maxOf(
            readerQuietRemainingMs(NTK_ADJACENT_APPEND_ACTIVE_SCROLL_QUIET_MS),
            ntkInitialInteractiveSettleRemainingMs(),
            if (viewportBusy.get()) NTK_ADJACENT_APPEND_ACTIVE_SCROLL_QUIET_MS else 0L
        )
    }

    private fun loadAppendUrlsForCandidate(
        target: Manga,
        predecessor: Manga,
        currentTitle: Title,
        direction: Int,
    ): AppendUrlLoad {
        if (direction > 0) {
            rememberAdjacentStrictPredecessor(
                target.ntkEpisodePath,
                predecessor.ntkEpisodePath,
            )
        }
        var urls = imageRepository.imageUrls(target, appContext)
        if (urls.isNullOrEmpty() && isNtkSource(target, currentTitle)) {
            val naverOriginalCount = installNtkNaverOriginalAppendUrlsIfAvailable(target)
            if (naverOriginalCount > 0) {
                urls = imageRepository.imageUrls(target, appContext)
            }
        }
        val earlyInstalled = if (isNtkSource(target, currentTitle)) {
            installEarlyGeneratedAppendUrlsIfAvailable(target) > 0
        } else {
            false
        }
        if (earlyInstalled) {
            urls = imageRepository.imageUrls(target, appContext)
        }
        val seededGeneratedUrls = !urls.isNullOrEmpty() && urls.any { isNtkGeneratedImageUrl(it) }
        if (seededGeneratedUrls && isNtkSource(target, currentTitle)) {
            Log.d(
                TAG,
                "append_adjacent_seeded_generated_direct direction=$direction targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} images=${urls?.size ?: 0}"
            )
            return AppendUrlLoad(Title.LOAD_OK, completeKnownGeneratedAppendUrls(target, urls ?: emptyList()))
        }
        val seededTrustedEarlyUrls =
            earlyInstalled ||
                (!urls.isNullOrEmpty() &&
                    isNtkSource(target, currentTitle) &&
                    isNtkSyntheticEpisodePath(target.ntkEpisodePath) &&
                    urls.none { isNtkGeneratedImageUrl(it) })
        val preferVerifiedApiAppend =
            shouldPreferVerifiedApiAppend(target, currentTitle) && !seededGeneratedUrls && !seededTrustedEarlyUrls
        if (isNtkSource(target, currentTitle)) {
            registerPendingAdjacentEarlyAppendTarget(target, direction)
        }
        if (!preferVerifiedApiAppend && !urls.isNullOrEmpty() &&
            isNtkSource(target, currentTitle) &&
            shouldRefreshNtkGeneratedAppendUrls(urls)
        ) {
            target.setImgs(null)
            val result = fetchGeneratedNtkAppendUrls(target, predecessor, currentTitle, direction)
            Log.d(TAG, "append_adjacent_fetch direction=$direction targetId=${target.id} result=$result")
            if (result != Title.LOAD_OK) return AppendUrlLoad(result, emptyList())
            urls = imageRepository.imageUrls(target, appContext)
        }
        if (urls.isNullOrEmpty() || preferVerifiedApiAppend) {
            if (preferVerifiedApiAppend) target.setImgs(null)
            val result = fetchGeneratedNtkAppendUrls(target, predecessor, currentTitle, direction)
            Log.d(TAG, "append_adjacent_fetch direction=$direction targetId=${target.id} result=$result")
            if (result != Title.LOAD_OK &&
                installEarlyGeneratedAppendUrlsIfAvailable(target) <= 0
            ) {
                return AppendUrlLoad(result, emptyList())
            }
            urls = imageRepository.imageUrls(target, appContext)
        }
        return AppendUrlLoad(Title.LOAD_OK, completeKnownGeneratedAppendUrls(target, urls ?: emptyList()))
    }

    private fun installNtkNaverOriginalAppendUrlsIfAvailable(target: Manga): Int {
        val path = target.ntkEpisodePath?.trim().orEmpty()
        if (!path.contains("/naver-", ignoreCase = true) &&
            !path.contains("/nv-", ignoreCase = true)
        ) {
            return 0
        }
        val urls = target.fetchNaverWebtoonOriginalImageUrlsForNtkPath(
            MainApplication.getHttpClient(),
            0
        )
        if (urls.isNullOrEmpty()) {
            Log.d(TAG, "append_adjacent_naver_original_miss path=$path")
            return 0
        }
        target.setImgs(ArrayList(urls))
        if (target.ntkImageCount <= 0 || target.ntkImageCount != urls.size) {
            target.setNtkImageCount(urls.size)
        }
        Log.d(
            TAG,
            "append_adjacent_naver_original_urls path=$path count=${urls.size} " +
                "first=${urls.firstOrNull()?.substringAfterLast('/').orEmpty()}"
        )
        return urls.size
    }

    private fun seedNtkAppendGeneratedUrlsFromNeighbor(
        target: Manga,
        source: Manga,
        currentTitle: Title,
        allowSpeculativeExtension: Boolean = true,
    ): Int {
        if (!isNtkSource(target, currentTitle) || !isNtkSource(source, currentTitle)) return 0
        if (isNtkSyntheticEpisodePath(target.ntkEpisodePath) &&
            (target.ntkImageWorkId.isNullOrBlank() ||
                !target.ntkImageEpisodeId.matches(Regex("\\d{1,12}")) ||
                target.ntkImageCount <= 0)
        ) {
            Log.d(
                TAG,
                "append_adjacent_seed_generated_skip_synthetic path=${target.ntkEpisodePath} " +
                    "sourcePath=${source.ntkEpisodePath}"
            )
            return 0
        }
        val path = target.ntkEpisodePath?.trim().orEmpty()
        val match = NTK_VIEWER_EPISODE_PATH.matchEntire(path) ?: return 0
        val segment = match.groupValues[1].lowercase(Locale.ROOT)
        val inferredExtension = generatedExtensionForAppendNeighbor(source)
        val extensionCandidates = generatedExtensionCandidatesForAppend(segment, inferredExtension)
        if (inferredExtension.isEmpty() && extensionCandidates.isNotEmpty()) {
            Log.d(
                TAG,
                "append_adjacent_seed_generated_default_extensions path=$path " +
                    "sourcePath=${source.ntkEpisodePath} extensions=${extensionCandidates.joinToString("|")}"
            )
        }
        if (extensionCandidates.isEmpty()) {
            return 0
        }
        val pathWorkId = match.groupValues[2].trim()
        val pathEpisodeToken = match.groupValues[3].trim()
        val neighborGeneratedWorkId = generatedWorkIdForAppendNeighbor(source)
        val neighborDeclaredWorkId = source.ntkImageWorkId.trim()
        val inheritedWorkId = target.ntkImageWorkId.trim()
        val imageWorkId = when {
            shouldUseNeighborAppendWorkId(segment, pathWorkId, inheritedWorkId, neighborGeneratedWorkId) ->
                neighborGeneratedWorkId
            inheritedWorkId.matches(Regex("\\d{1,12}")) -> inheritedWorkId
            shouldUseNeighborAppendWorkId(segment, pathWorkId, inheritedWorkId, neighborDeclaredWorkId) ->
                neighborDeclaredWorkId
            neighborGeneratedWorkId.isNotEmpty() -> neighborGeneratedWorkId
            neighborDeclaredWorkId.isNotEmpty() -> neighborDeclaredWorkId
            inheritedWorkId.isNotEmpty() -> inheritedWorkId
            else -> pathWorkId
        }
        val recordedImageEpisodeId = target.ntkImageEpisodeId.trim()
        val candidateImageEpisodeId = if (pathEpisodeToken.matches(Regex("\\d+"))) {
            canonicalWebtoonAppendImageEpisodeId(
                segment,
                pathWorkId,
                pathEpisodeToken,
                imageWorkId,
                recordedImageEpisodeId
            )
        } else {
            recordedImageEpisodeId
        }
        val declaredCount = target.ntkImageCount
        val count = effectiveGeneratedAppendCount(target, declaredCount)
            .takeIf { it > 0 }
            ?: NTK_APPEND_EARLY_PUBLISH_PAGES
        if (declaredCount > 0 && count != declaredCount) {
            target.setNtkImageCount(count)
        }
        val existingUrls = imageRepository.imageUrls(target, appContext)
        if (!existingUrls.isNullOrEmpty() && (count <= 0 || existingUrls.size >= count)) {
            return 0
        }
        if (!imageWorkId.matches(Regex("\\d{1,12}")) ||
            !candidateImageEpisodeId.matches(Regex("\\d{1,12}")) ||
            count <= 0
        ) {
            Log.d(
                TAG,
                "append_adjacent_seed_generated_skip_invalid path=$path " +
                    "workId=$imageWorkId imageEpisodeId=$candidateImageEpisodeId count=$count " +
                    "existing=${existingUrls?.size ?: 0} neighborWorkId=$neighborGeneratedWorkId " +
                    "neighborDeclaredWorkId=$neighborDeclaredWorkId inheritedWorkId=$inheritedWorkId " +
                    "sourcePath=${source.ntkEpisodePath}"
            )
            return 0
        }
        if (
            segment == "webtoon" &&
            shouldPreferNtkApiForCanonicalWebtoonPath(pathWorkId, pathEpisodeToken)
        ) {
            val extension = generatedExtensionForAppendNeighbor(source).ifBlank { "jpg" }
            val urls = ArrayList<String>(count)
            for (page in 1..count) {
                val pageName = "p%03d.%s".format(Locale.ROOT, page, extension)
                urls.add("http://fifa.worldcup73.xyz/black/episodes/$imageWorkId/$candidateImageEpisodeId/$pageName")
            }
            target.setImgs(urls)
            ReaderImageCache.rememberNtkGeneratedEpisodeExtensionHint(urls.firstOrNull())
            ReaderImageCache.rememberEarlyNtkImageUrls(path, urls.take(NTK_APPEND_EARLY_PUBLISH_PAGES))
            Log.d(
                TAG,
                "append_adjacent_seed_generated_canonical_fast_urls targetId=${target.id} path=$path " +
                    "workId=$imageWorkId imageEpisodeId=$candidateImageEpisodeId count=${urls.size} " +
                    "extension=$extension existing=${existingUrls?.size ?: 0} sourcePath=${source.ntkEpisodePath}"
            )
            return urls.size
        }
        // A click-owned current episode can race a speculative suffix because its strict source
        // stream replaces a losing candidate immediately. An adjacent runway has no visible
        // fallback yet: publishing a guessed suffix there can leave its four-page atomic gate
        // permanently stuck (for example, a .jpg volume followed by a .jpeg volume). Once the
        // adjacent viewer document has supplied an authoritative page count, resolve the finite
        // extension set before constructing that immutable manifest.
        val speculativeFirst =
            allowSpeculativeExtension &&
                shouldSpeculativelySeedAppendGeneratedUrls(inferredExtension)
        val verifiedCandidate = when {
            speculativeFirst -> speculativeAppendGeneratedImageCandidate(
                segment,
                imageWorkId,
                candidateImageEpisodeId,
                recordedImageEpisodeId,
                pathEpisodeToken,
                extensionCandidates,
                path
            ) ?: verifiedAppendGeneratedImageCandidate(
                segment,
                imageWorkId,
                candidateImageEpisodeId,
                recordedImageEpisodeId,
                pathEpisodeToken,
                extensionCandidates,
                path
            )
            allowSpeculativeExtension -> verifiedAppendGeneratedImageCandidate(
                segment,
                imageWorkId,
                candidateImageEpisodeId,
                recordedImageEpisodeId,
                pathEpisodeToken,
                extensionCandidates,
                path
            ) ?: speculativeAppendGeneratedImageCandidate(
                segment,
                imageWorkId,
                candidateImageEpisodeId,
                recordedImageEpisodeId,
                pathEpisodeToken,
                extensionCandidates,
                path
            )
            else -> verifiedAppendGeneratedImageCandidate(
                segment,
                imageWorkId,
                candidateImageEpisodeId,
                recordedImageEpisodeId,
                pathEpisodeToken,
                extensionCandidates,
                path
            )
        }
        if (verifiedCandidate == null) {
            if (!allowSpeculativeExtension) {
                Log.d(
                    TAG,
                    "append_adjacent_seed_generated_strict_extension_unresolved path=$path " +
                        "workId=$imageWorkId imageEpisodeId=$candidateImageEpisodeId " +
                        "extensions=${extensionCandidates.joinToString("|")}"
                )
            }
            return 0
        }
        val imageEpisodeId = verifiedCandidate.imageEpisodeId
        val extension = verifiedCandidate.extension
        val urls = ArrayList<String>(count)
        for (page in 1..count) {
            val pageName = "p%03d.%s".format(Locale.ROOT, page, extension)
            val url = if (segment == "webtoon") {
                "http://fifa.worldcup73.xyz/black/episodes/$imageWorkId/$imageEpisodeId/$pageName"
            } else if (segment == "manhwa") {
                "https://booktoki9.org/manhwa/$imageWorkId/$imageEpisodeId/$pageName"
            } else {
                "http://apihost93.com/$segment/$imageWorkId/$imageEpisodeId/$pageName"
            }
            urls.add(url)
        }
        target.setImgs(urls)
        ReaderImageCache.rememberNtkGeneratedEpisodeExtensionHint(urls.firstOrNull())
        ReaderImageCache.rememberEarlyNtkImageUrls(path, urls.take(NTK_APPEND_EARLY_PUBLISH_PAGES))
        Log.d(
            TAG,
                "append_adjacent_seed_generated_urls targetId=${target.id} path=$path " +
                "workId=$imageWorkId imageEpisodeId=$imageEpisodeId count=${urls.size} " +
                "extension=$extension existing=${existingUrls?.size ?: 0} " +
                "neighborWorkId=$neighborGeneratedWorkId neighborDeclaredWorkId=$neighborDeclaredWorkId " +
                "inheritedWorkId=$inheritedWorkId sourcePath=${source.ntkEpisodePath}"
        )
        return urls.size
    }

    private fun shouldSpeculativelySeedAppendGeneratedUrls(inferredExtension: String): Boolean {
        if (inferredExtension.trim().isNotEmpty()) return true
        if (isImmediateNtkGeneratedUx()) return true
        return viewportBusy.get() ||
            readerQuietRemainingMs(NTK_ADJACENT_APPEND_STRUCTURE_INSERT_QUIET_MS) > 0L ||
            ntkInitialInteractiveSettleRemainingMs() > 0L
    }

    private fun speculativeAppendGeneratedImageCandidate(
        segment: String,
        imageWorkId: String,
        candidateImageEpisodeId: String,
        recordedImageEpisodeId: String,
        pathEpisodeToken: String,
        extensions: List<String>,
        path: String
    ): AppendGeneratedCandidate? {
        if (segment != "manhwa" && segment != "webtoon") return null
        if (!imageWorkId.matches(Regex("\\d{1,12}"))) return null
        val imageEpisodeId = when {
            candidateImageEpisodeId.matches(Regex("\\d{1,12}")) -> candidateImageEpisodeId
            recordedImageEpisodeId.matches(Regex("\\d{1,12}")) -> recordedImageEpisodeId
            pathEpisodeToken.matches(Regex("\\d{1,12}")) -> pathEpisodeToken
            else -> return null
        }
        val extension = extensions
            .map { it.trim().lowercase(Locale.ROOT) }
            .firstOrNull { it.matches(Regex("jpg|jpeg|png|webp")) }
            ?: return null
        Log.d(
            TAG,
            "append_adjacent_seed_generated_speculative_urls path=$path " +
                "workId=$imageWorkId imageEpisodeId=$imageEpisodeId extension=$extension " +
                "candidate=$candidateImageEpisodeId recorded=$recordedImageEpisodeId " +
                "pathEpisodeId=$pathEpisodeToken"
        )
        return AppendGeneratedCandidate(imageEpisodeId, extension)
    }

    private fun shouldUseNeighborAppendWorkId(
        segment: String,
        pathWorkId: String,
        targetWorkId: String,
        neighborWorkId: String
    ): Boolean {
        val neighbor = neighborWorkId.trim()
        if (!neighbor.matches(Regex("\\d{1,12}"))) return false
        val target = targetWorkId.trim()
        if (target == neighbor) return false
        if (target.isEmpty()) return true
        if (!target.matches(Regex("\\d{1,12}"))) return true
        if (segment != "webtoon" && segment != "manhwa") return false
        return pathWorkId.matches(Regex("\\d{1,12}")) && target == pathWorkId
    }

    private fun generatedExtensionCandidatesForAppend(
        segment: String,
        inferredExtension: String
    ): List<String> {
        val out = LinkedHashSet<String>()
        val normalized = inferredExtension.trim().lowercase(Locale.ROOT)
        if (normalized.matches(Regex("jpg|jpeg|png|webp"))) out.add(normalized)
        if (segment == "webtoon" || segment == "manhwa") {
            out.add("jpeg")
            out.add("jpg")
        }
        return out.toList()
    }

    private fun verifiedAppendGeneratedImageCandidate(
        segment: String,
        imageWorkId: String,
        candidateImageEpisodeId: String,
        recordedImageEpisodeId: String,
        pathEpisodeToken: String,
        extensions: List<String>,
        path: String
    ): AppendGeneratedCandidate? {
        val candidates = LinkedHashSet<String>()
        if (candidateImageEpisodeId.matches(Regex("\\d{1,12}"))) candidates.add(candidateImageEpisodeId)
        if (recordedImageEpisodeId.matches(Regex("\\d{1,12}"))) candidates.add(recordedImageEpisodeId)
        if (pathEpisodeToken.matches(Regex("\\d{1,12}"))) candidates.add(pathEpisodeToken)
        val extensionCandidates = extensions
            .map { it.trim().lowercase(Locale.ROOT) }
            .filter { it.matches(Regex("jpg|jpeg|png|webp")) }
            .distinct()
        if (candidates.isEmpty() || extensionCandidates.isEmpty()) return null
        val hits = ConcurrentHashMap.newKeySet<String>()
        val latch = CountDownLatch(candidates.size * extensionCandidates.size)
        val startedAt = SystemClock.elapsedRealtime()
        for (episodeId in candidates) {
            for (extension in extensionCandidates) {
                Thread({
                    try {
                        if (cancelled.get()) return@Thread
                        val first = ntkGeneratedInitialUrl(segment, imageWorkId, episodeId, 1, extension)
                        if (isReachableNtkGeneratedProbe(first)) hits.add("$episodeId|$extension")
                    } catch (_: Exception) {
                    } finally {
                        latch.countDown()
                    }
                }, "ntk-append-generated-probe").apply {
                    isDaemon = true
                    start()
                }
            }
        }
        latch.await(NTK_GENERATED_INITIAL_PROBE_TOTAL_WAIT_MS, TimeUnit.MILLISECONDS)
        var hitEpisodeId: String? = null
        var hitExtension: String? = null
        for (episodeId in candidates) {
            for (extension in extensionCandidates) {
                if (hits.contains("$episodeId|$extension")) {
                    hitEpisodeId = episodeId
                    hitExtension = extension
                    break
                }
            }
            if (hitEpisodeId != null) break
        }
        val hit = hitEpisodeId
        if (hit == null) {
            Log.d(
                TAG,
                "append_adjacent_seed_generated_probe_miss path=$path workId=$imageWorkId " +
                    "candidate=$candidateImageEpisodeId recorded=$recordedImageEpisodeId " +
                    "pathEpisodeId=$pathEpisodeToken extensions=${extensionCandidates.joinToString("|")} " +
                    "ms=${SystemClock.elapsedRealtime() - startedAt}"
            )
            return null
        }
        if (hit != candidateImageEpisodeId) {
            Log.d(
                TAG,
                "append_adjacent_seed_generated_probe_reselect path=$path workId=$imageWorkId " +
                    "candidate=$candidateImageEpisodeId selected=$hit recorded=$recordedImageEpisodeId " +
                    "pathEpisodeId=$pathEpisodeToken extension=$hitExtension " +
                    "ms=${SystemClock.elapsedRealtime() - startedAt}"
            )
        }
        return AppendGeneratedCandidate(hit, hitExtension ?: extensionCandidates.first())
    }

    private fun generatedWorkIdForAppendNeighbor(source: Manga): String {
        val earlyUrls = ReaderImageCache.earlyNtkImageUrls(source.ntkEpisodePath, 0L)
        val early = earlyUrls.firstOrNull { isNtkGeneratedImageUrl(it) }
        val earlyWorkId = generatedImageWorkId(early)
        if (earlyWorkId.isNotEmpty()) return earlyWorkId
        val sourceUrls = imageRepository.imageUrls(source, appContext)
        return generatedImageWorkId(sourceUrls.firstOrNull { isNtkGeneratedImageUrl(it) })
    }

    private fun canonicalWebtoonAppendImageEpisodeId(
        segment: String,
        pathWorkId: String,
        pathEpisodeToken: String,
        imageWorkId: String,
        recordedImageEpisodeId: String
    ): String {
        if (segment != "webtoon") return recordedImageEpisodeId
        if (
            pathEpisodeToken.matches(Regex("\\d{1,12}")) &&
            recordedImageEpisodeId.matches(Regex("\\d{1,12}")) &&
            recordedImageEpisodeId != pathEpisodeToken
        ) {
            Log.d(
                TAG,
                "append_adjacent_seed_generated_path_episode_override pathWorkId=$pathWorkId " +
                    "imageWorkId=$imageWorkId recordedImageEpisodeId=$recordedImageEpisodeId " +
                    "pathEpisodeId=$pathEpisodeToken"
            )
            return pathEpisodeToken
        }
        if (recordedImageEpisodeId.matches(Regex("\\d{1,12}"))) return recordedImageEpisodeId
        val pathWork = pathWorkId.toLongOrNull() ?: return recordedImageEpisodeId
        if (pathWork < NTK_CANONICAL_WEBTOON_APPEND_MIN_WORK_ID) return recordedImageEpisodeId
        if (imageWorkId == pathWorkId) return recordedImageEpisodeId
        if (!pathEpisodeToken.matches(Regex("\\d{1,12}"))) return recordedImageEpisodeId
        if (recordedImageEpisodeId == pathEpisodeToken) return recordedImageEpisodeId
        Log.d(
            TAG,
            "append_adjacent_seed_generated_canonical_episode_fallback pathWorkId=$pathWorkId " +
                "imageWorkId=$imageWorkId recordedImageEpisodeId=$recordedImageEpisodeId " +
                "pathEpisodeId=$pathEpisodeToken"
        )
        return pathEpisodeToken
    }

    private fun shouldPreferNtkApiForCanonicalWebtoonPath(
        pathWorkId: String,
        pathEpisodeToken: String
    ): Boolean {
        if (!pathWorkId.matches(Regex("\\d{1,12}"))) return false
        if (!pathEpisodeToken.matches(Regex("\\d{1,12}"))) return false
        return pathWorkId.toLongOrNull()?.let {
            it >= NTK_CANONICAL_WEBTOON_API_FIRST_MIN_WORK_ID
        } ?: true
    }

    private fun isModernProtectedNumericNtkPath(path: String): Boolean {
        if (!isProtectedNumericNtkPathShape(path)) return false
        return try {
            MainApplication.getHttpClient().isModernNtkGuardRootForPath(path)
        } catch (_: Throwable) {
            false
        }
    }

    private fun usesProtectedNumericNtkPipeline(page: PageRef? = null): Boolean {
        val target = page?.manga ?: manga
        if (!isNtkSource(target, title)) return false
        return isModernProtectedNumericNtkPath(target.ntkEpisodePath?.trim().orEmpty())
    }

    private fun publishProtectedBitmapWindowSnapshot(
        ticket: Long,
        expectedStructureGeneration: Int,
        pageCount: Int,
        anchor: Int,
        direction: Int,
        first: Int,
        last: Int,
        sourceGeneration: Int,
    ): Boolean {
        if (ticket <= 0L || ticket != protectedBitmapWindowRevision.get() || pageCount <= 0) {
            return false
        }
        val safeFirst = first.coerceIn(0, pageCount - 1)
        val safeLast = last.coerceIn(safeFirst, pageCount - 1)
        val candidate = synchronized(pagesLock) {
            if (ticket != protectedBitmapWindowRevision.get() ||
                // Tail-only growth preserves every numeric index in this transaction. Indexed
                // mutations (prepend/remove/reorder) advance indexedStateGeneration and still
                // reject the commit. This prevents progressive p1..pN publication from forcing
                // the same physical window through an endless retry loop.
                pages.size < pageCount ||
                indexedStateGeneration.get() != expectedStructureGeneration
            ) {
                return@synchronized null
            }
            NtkProtectedBitmapWindowSnapshot(
                revision = ticket,
                sourceGeneration = sourceGeneration,
                structureGeneration = expectedStructureGeneration,
                pageCount = pageCount,
                anchor = anchor.coerceIn(0, pageCount - 1),
                direction = direction,
                first = safeFirst,
                last = safeLast,
            )
        } ?: return false
        val published = protectedBitmapWindowSnapshot.updateAndGet { current ->
            if (ticket != protectedBitmapWindowRevision.get()) {
                current
            } else if (current == null || current.revision <= ticket) {
                candidate
            } else {
                current
            }
        }
        return published === candidate
    }

    /** Caller owns pagesLock; prevents a stale window from committing numeric retained indexes. */
    private fun isProtectedBitmapWindowTransactionCurrent(
        ticket: Long,
        expectedStructureGeneration: Int,
        pageCount: Int,
    ): Boolean {
        if (ticket <= 0L || ticket != protectedBitmapWindowRevision.get()) return false
        if (pages.size < pageCount || indexedStateGeneration.get() != expectedStructureGeneration) {
            return false
        }
        return NtkProtectedBitmapWindowSnapshotPolicy.isCurrent(
            protectedBitmapWindowSnapshot.get(),
            ticket,
            expectedStructureGeneration,
            pageCount,
        )
    }

    private fun currentProtectedBitmapWindowSnapshot(
        pageCount: Int,
    ): NtkProtectedBitmapWindowSnapshot? {
        val snapshot = protectedBitmapWindowSnapshot.get()
        return snapshot.takeIf {
            NtkProtectedBitmapWindowSnapshotPolicy.isCurrent(
                it,
                protectedBitmapWindowRevision.get(),
                indexedStateGeneration.get(),
                pageCount,
            )
        }
    }

    private fun protectedNumericBitmapWindow(pageCount: Int = synchronized(pagesLock) { pages.size }): IntRange {
        if (pageCount <= 0) return IntRange.EMPTY
        val snapshot = currentProtectedBitmapWindowSnapshot(pageCount)
        // This helper also drives destructive outside-window eviction.  A structure handoff with
        // no current snapshot must keep pixels, never guess a mixed-generation narrow range.
        return snapshot?.let { it.first..it.last } ?: (0 until pageCount)
    }

    private fun protectedNumericBitmapWindowBoundsForSession(
        pageCount: Int,
        anchor: Int,
        direction: Int,
        physicalFirst: Int = anchor,
        physicalLast: Int = anchor,
    ): IntArray {
        val launchSpan = if (ReaderStrictBitmapResidencyPolicy.protectsFullLaunchSpan(
                strictColdSession = strictExactColdRolling,
                rollingPixelResidency = strictExactRollingPixelResidency.get(),
            )
        ) synchronized(pagesLock) {
            val anchorPage = pages.getOrNull(anchor)
            if (anchorPage == null || anchorPage.transitionTitle != null ||
                !isStrictExactLaunchPage(anchorPage)
            ) {
                null
            } else {
                var first = -1
                var last = -1
                pages.forEachIndexed { index, page ->
                    if (page.transitionTitle == null && isStrictExactLaunchPage(page)) {
                        if (first < 0) first = index
                        last = index
                    }
                }
                if (first >= 0 && last >= first) intArrayOf(first, last) else null
            }
        } else {
            null
        }
        val bounds = strictExactScopedBitmapWindowBounds(
            pageCount = pageCount,
            anchor = anchor,
            direction = direction,
            launchFirst = launchSpan?.get(0) ?: -1,
            launchLast = launchSpan?.get(1) ?: -1,
        )
        includePhysicalSpanInBitmapWindow(
            bounds,
            pageCount,
            physicalFirst,
            physicalLast,
        )
        if (pageCount > 0 && ntkInitialInteractiveSettleRemainingMs() > 0L) {
            bounds[0] = minOf(bounds[0], currentStartPage().coerceIn(0, pageCount - 1))
        }
        return bounds
    }

    private fun isInsideProtectedNumericBitmapWindow(index: Int, page: PageRef? = null): Boolean {
        // Adjacent p0/runway pages are installed before they enter the launch episode's viewport.
        // Keep their established page-scoped admission; applying the launch-session window to a
        // foreign adjacent PageRef clears p0 while it is still offscreen and permanently clamps the
        // forward boundary. The transaction reservation itself is session-scoped separately.
        if (!usesProtectedNumericNtkPipeline(page)) return true
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return index == currentStartPage()
        if (strictExactColdRolling && page != null && !isStrictExactLaunchPage(page)) {
            return NtkProtectedBitmapWindowSnapshotPolicy.admits(
                protectedBitmapWindowSnapshot.get(),
                protectedBitmapWindowRevision.get(),
                indexedStateGeneration.get(),
                count,
                index,
            )
        }
        return index in protectedNumericBitmapWindow(count)
    }

    private fun <T> withProtectedNumericNetworkPermit(target: Manga, block: () -> T): T {
        if (!isNtkSource(target, title) ||
            !isModernProtectedNumericNtkPath(target.ntkEpisodePath?.trim().orEmpty())
        ) {
            return block()
        }
        val depth = protectedNumericNetworkDepth.get() ?: 0
        if (depth > 0) {
            protectedNumericNetworkDepth.set(depth + 1)
            return try {
                block()
            } finally {
                protectedNumericNetworkDepth.set(depth)
            }
        }
        protectedNumericNetworkGate.acquire()
        protectedNumericNetworkDepth.set(1)
        return try {
            block()
        } finally {
            protectedNumericNetworkDepth.remove()
            protectedNumericNetworkGate.release()
        }
    }

    private fun <T> withProtectedNumericDecodePermit(
        page: PageRef,
        bypassSerialization: Boolean = false,
        block: () -> T,
    ): T {
        if (!usesProtectedNumericNtkPipeline(page) || bypassSerialization) return block()
        val depth = protectedNumericDecodeDepth.get() ?: 0
        if (depth > 0) {
            protectedNumericDecodeDepth.set(depth + 1)
            return try {
                block()
            } finally {
                protectedNumericDecodeDepth.set(depth)
            }
        }
        protectedNumericDecodeGate.acquire()
        protectedNumericDecodeDepth.set(1)
        return try {
            block()
        } finally {
            protectedNumericDecodeDepth.remove()
            protectedNumericDecodeGate.release()
        }
    }

    private fun generatedExtensionForAppendNeighbor(source: Manga): String {
        val recent = SystemClock.elapsedRealtime() - 30000L
        val successUrls = ReaderImageCache.earlyNtkGeneratedSuccessImageUrls(source.ntkEpisodePath, recent)
        generatedExtensionFromUrls(successUrls, preferNonJpg = true)?.let { return it }
        val sourceUrls = imageRepository.imageUrls(source, appContext).orEmpty()
        generatedExtensionFromUrls(sourceUrls, preferNonJpg = true)?.let { return it }
        val earlyUrls = ReaderImageCache.earlyNtkImageUrls(source.ntkEpisodePath, recent)
        generatedExtensionFromUrls(earlyUrls, preferNonJpg = true)?.let { return it }
        generatedExtensionFromUrls(successUrls, preferNonJpg = false)?.let { return it }
        generatedExtensionFromUrls(sourceUrls, preferNonJpg = false)?.let { return it }
        generatedExtensionFromUrls(earlyUrls, preferNonJpg = false)?.let { return it }
        return ""
    }

    private fun generatedExtensionFromUrls(urls: List<String>, preferNonJpg: Boolean): String? {
        val generated = urls.asSequence()
            .filter { isNtkGeneratedImageUrl(it) }
            .map { generatedImageExtension(it) }
            .filter { it.matches(Regex("jpg|jpeg|png|webp", RegexOption.IGNORE_CASE)) }
            .map { it.lowercase(Locale.ROOT) }
            .toList()
        if (generated.isEmpty()) return null
        if (preferNonJpg) {
            generated.firstOrNull { it != "jpg" }?.let { return it }
        }
        return generated.firstOrNull()
    }

    private fun generatedImageExtension(image: String?): String {
        if (image.isNullOrBlank()) return ""
        val match = NTK_GENERATED_IMAGE_EXTENSION.find(image) ?: return ""
        return match.groupValues[1].lowercase(Locale.ROOT)
    }

    private fun generatedImageWorkId(image: String?): String {
        if (image.isNullOrBlank()) return ""
        Regex("/black/episodes/(\\d+)/", RegexOption.IGNORE_CASE)
            .find(image)
            ?.groupValues
            ?.getOrNull(1)
            ?.let { return it }
        Regex("/blacktoon/episodes/(\\d+)/", RegexOption.IGNORE_CASE)
            .find(image)
            ?.groupValues
            ?.getOrNull(1)
            ?.let { return it }
        Regex("/wt/episodes/(\\d+)/", RegexOption.IGNORE_CASE)
            .find(image)
            ?.groupValues
            ?.getOrNull(1)
            ?.let { return it }
        Regex("/(?:manhwa|webtoon)/(\\d+)/", RegexOption.IGNORE_CASE)
            .find(image)
            ?.groupValues
            ?.getOrNull(1)
            ?.let { return it }
        return ""
    }

    private fun inheritNtkAppendGeneratedHints(target: Manga, source: Manga, currentTitle: Title) {
        if (!isNtkSource(target, currentTitle) || !isNtkSource(source, currentTitle)) return
        if (target.titleId != source.titleId && target.titleId != currentTitle.id) return
        var inherited = false
        val path = target.ntkEpisodePath?.trim().orEmpty()
        val match = NTK_VIEWER_EPISODE_PATH.matchEntire(path)
        val segment = match?.groupValues?.getOrNull(1)?.lowercase(Locale.ROOT).orEmpty()
        val pathWorkId = match?.groupValues?.getOrNull(2)?.trim().orEmpty()
        val targetWorkId = target.ntkImageWorkId.trim()
        val sourceGeneratedWorkId = generatedWorkIdForAppendNeighbor(source)
        val sourceDeclaredWorkId = source.ntkImageWorkId.trim()
        val sourceWorkId = if (sourceGeneratedWorkId.matches(Regex("\\d{1,12}"))) {
            sourceGeneratedWorkId
        } else {
            sourceDeclaredWorkId
        }
        if (shouldUseNeighborAppendWorkId(segment, pathWorkId, targetWorkId, sourceWorkId)) {
            target.ntkImageWorkId = sourceWorkId
            inherited = true
        }
        if (inherited) {
            Log.d(
                TAG,
                "append_adjacent_inherit_generated_hints targetId=${target.id} " +
                    "targetPath=${target.ntkEpisodePath} sourceId=${source.id} " +
                    "sourcePath=${source.ntkEpisodePath} imageWorkId=${target.ntkImageWorkId} " +
                    "previousWorkId=$targetWorkId sourceGeneratedWorkId=$sourceGeneratedWorkId " +
                    "sourceDeclaredWorkId=$sourceDeclaredWorkId pathWorkId=$pathWorkId " +
                    "imageEpisodeId=${target.ntkImageEpisodeId} imageCount=${target.ntkImageCount}"
            )
        }
    }

    private fun fetchGeneratedNtkAppendUrls(
        target: Manga,
        predecessor: Manga,
        currentTitle: Title,
        direction: Int,
    ): Int {
        val startedAt = SystemClock.elapsedRealtime()
        val adjacentGrantPath = target.ntkEpisodePath?.trim().orEmpty()
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(
            predecessor.ntkEpisodePath?.trim().orEmpty()
        )
        if (direction > 0 && predecessorPath.isNotEmpty()) {
            rememberAdjacentStrictPredecessor(adjacentGrantPath, predecessorPath)
        }
        if (isNtkSource(target, currentTitle) &&
            isNtkSyntheticEpisodePath(adjacentGrantPath)
        ) {
            if (predecessorPath.isEmpty()) return Title.LOAD_ERROR
            val exactUrls = exactViewerApiAdjacentUrls(target).orEmpty().ifEmpty {
                waitForExactViewerApiAdjacentUrls(
                    target,
                    predecessorPath,
                    NTK_APPEND_EXACT_MANIFEST_WAIT_MS,
                )
            }
            Log.d(
                TAG,
                "append_adjacent_slug_exact_fetch direction=$direction path=$adjacentGrantPath " +
                    "images=${exactUrls.size} ms=${SystemClock.elapsedRealtime() - startedAt}"
            )
            // Never fall through to HTML/generated parsing for a tokenized episode. Those
            // candidates are not page-authoritative and can consist entirely of ads.
            return if (exactUrls.isNotEmpty()) Title.LOAD_OK else Title.LOAD_ERROR
        }
        val adjacentGrantOpened =
            direction > 0 &&
                isNtkSource(target, currentTitle) &&
                isNtkManhwaOrWebtoonEpisodePath(adjacentGrantPath)
        if (adjacentGrantOpened) {
            // Boundary-driven fetches have the same document/first-body join as the idle
            // prefetch path. Open only the exact neighbor selected by the episode resolver before
            // its fetch begins; otherwise a user who reaches the boundary before idle preparation
            // can hit the same circular wait.
            ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
                adjacentGrantPath,
                NTK_ADJACENT_APPEND_FOREGROUND_PATH_TTL_MS,
                "adjacent_verified_fetch"
            )
        }
        Log.d(
            TAG,
            "append_adjacent_verified_fetch_start direction=$direction targetId=${target.id} " +
                "titleId=${currentTitle.id} path=${target.ntkEpisodePath}"
        )
        val result = try {
            val preferApiFirst = shouldPreferVerifiedApiAppend(target, currentTitle)
            val syntheticNtkPath = isNtkSyntheticEpisodePath(target.ntkEpisodePath)
            Log.d(
                TAG,
                "append_adjacent_verified_fetch_mode targetId=${target.id} path=${target.ntkEpisodePath} " +
                    "preferApiFirst=$preferApiFirst synthetic=$syntheticNtkPath " +
                    "isNtk=${isNtkSource(target, currentTitle)}"
            )
            val initialResult = if (isNtkSource(target, currentTitle) && preferApiFirst) {
                fetchGeneratedNtkAppendUrlsWithEarlyHandoff(target, "api-strict")
            } else if (isNtkSource(target, currentTitle) && !syntheticNtkPath) {
                fetchGeneratedNtkAppendUrlsWithEarlyHandoff(target)
            } else if (syntheticNtkPath) {
                fetchGeneratedNtkAppendUrlsWithEarlyHandoff(target, "api-strict")
            } else {
                withRepositoryCancellation(userVisible = true) { cancellation ->
                    if (preferApiFirst || syntheticNtkPath) {
                        imageRepository.fetchViewerInitialWithMode(target, cancellation, "api-strict")
                    } else {
                        imageRepository.fetchViewerInitial(target, cancellation)
                    }
                }
            }
            val initialImages = imageRepository.imageUrls(target, appContext).size
            val earlyGeneratedImages = installEarlyGeneratedAppendUrlsIfAvailable(target)
            if (earlyGeneratedImages > 0 ||
                (initialResult == Title.LOAD_OK && initialImages > 0) ||
                (initialResult == Title.LOAD_CAPTCHA && !syntheticNtkPath) ||
                cancelled.get()
            ) {
                if (earlyGeneratedImages > 0) Title.LOAD_OK else initialResult
            } else {
                if (target.ntkViewerParseReason == "unavailable") {
                    initialResult
                    } else {
                        restoreNtkEpisodeSnapshotIfNeeded(currentTitle, target)
                        target.setImgs(null)
                    val retryMode = if (isNtkSource(target, currentTitle) && !syntheticNtkPath) {
                        "generated"
                    } else {
                        "api-strict"
                    }
                    Log.d(
                        TAG,
                        "append_adjacent_verified_fetch_retry direction=$direction targetId=${target.id} " +
                            "initialResult=$initialResult initialImages=$initialImages retryMode=$retryMode " +
                            "path=${target.ntkEpisodePath}"
                    )
                    val retryResult = withRepositoryCancellation(userVisible = true) { retryCancellation ->
                        if (retryMode == "generated" && !syntheticNtkPath) {
                            imageRepository.fetchViewerInitial(target, retryCancellation)
                        } else {
                            imageRepository.fetchViewerInitialWithMode(target, retryCancellation, retryMode)
                        }
                    }
                    if (retryResult != Title.LOAD_OK &&
                        (installEarlyGeneratedAppendUrlsIfAvailable(target) > 0 ||
                            (retryMode == "api-strict" &&
                                waitForEarlyAppendUrlsIfAvailable(target, NTK_APPEND_EARLY_API_STRICT_LATE_WAIT_MS) > 0))
                    ) {
                        Title.LOAD_OK
                    } else {
                        retryResult
                    }
                }
            }.also {
                Log.d(
                    TAG,
                    "append_adjacent_verified_fetch direction=$direction targetId=${target.id} " +
                        "result=$it ms=${SystemClock.elapsedRealtime() - startedAt} " +
                        "reason=${target.ntkViewerParseReason} images=${imageRepository.imageUrls(target, appContext).size}"
                )
            }
        } catch (e: Exception) {
            recordIfUnexpected(e)
            Title.LOAD_ERROR
        }
        if (
            adjacentGrantOpened &&
            (result != Title.LOAD_OK || imageRepository.imageUrls(target, appContext).isEmpty())
        ) {
            ReaderImageCache.releaseAdjacentNtkForegroundViewerPath(
                adjacentGrantPath,
                "adjacent_verified_fetch_failed"
            )
        }
        return result
    }

    private fun exactViewerApiAdjacentUrls(target: Manga): List<String>? {
        val authority = exactViewerApiAdjacentAuthority(target) ?: return null
        val path = authority.seal.normalizedEpisodePath
        val urls = authority.seal.normalizedCanonicalAssets
        if (!ensureAdjacentStrictSourceClaim(target, authority)) return null
        target.setNtkImageCount(urls.size)
        target.setImgs(ArrayList(urls))
        Log.d(
            TAG,
            "append_adjacent_exact_manifest_adopted path=$path images=${urls.size} " +
                "digest=${authority.seal.digestSha256}"
        )
        return urls
    }

    private fun rememberAdjacentStrictPredecessor(
        targetEpisodePath: String?,
        predecessorEpisodePath: String?,
    ) {
        val targetPath = NtkStripDigests.normalizeEpisodePath(targetEpisodePath.orEmpty())
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(predecessorEpisodePath.orEmpty())
        if (targetPath.isEmpty() || predecessorPath.isEmpty() ||
            !NtkStrictEpisodeDiscoveryCoordinator.ntkAdjacentOwnerAllowsTarget(
                predecessorPath,
                targetPath,
            )
        ) {
            return
        }
        adjacentStrictPredecessorPaths[targetPath] = predecessorPath
    }

    /**
     * Adjacent discovery owns small exact bodies in its private resident transport. The launch
     * episode claims that transport while constructing this session, but a continuously appended
     * episode arrives later and therefore needs its own generation-bound claim. Without this
     * binding all bodies can finish in about a second while the append path sees only the
     * transition card and repeatedly attempts a duplicate network download that strict ownership
     * correctly rejects.
     */
    private fun ensureAdjacentStrictSourceClaim(
        target: Manga,
        authority: NtkAuthoritativeManifest,
    ): Boolean {
        if (cancelled.get()) return false
        val seal = authority.seal
        val path = seal.normalizedEpisodePath
        if (consumedStrictSourcePaths.contains(path)) return false
        if (path.isEmpty() || seal.revision <= 0L ||
            !path.equals(
                NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty()),
                ignoreCase = true,
            )
        ) return false
        synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictSourceClaims[path]?.let { existing ->
                return existing.manifestDigest == seal.digestSha256 &&
                    isAdjacentStrictSourceClaimLive(path, existing)
            }
            val predecessorPath = adjacentStrictPredecessorPaths[path]
                ?.takeIf(String::isNotBlank)
                ?: return false
            val recovery = adjacentStrictRecoveryStates[path]
            if (recovery?.retirementInProgress == true) return false
            if (recovery != null && recovery.expectedManifestDigest != seal.digestSha256) {
                recovery.exhausted = true
                recovery.networkRearmableTerminal = false
                recovery.pendingValidatedRedriveEpoch = 0L
                return false
            }
            val transport = NtkSourceSpoolRegistry.claim(
                path,
                seal.digestSha256,
            ) as? NtkStrictSourceTransport ?: return false
            if (!NtkSourceSpoolRegistry.markClaimPhase(
                    path,
                    seal.digestSha256,
                    NtkManifestClaimPhase.BINDING,
                )
            ) {
                (transport as? Closeable)?.close()
                return false
            }
            val episode = NtkEpisodeToken(seal.revision)
            val descriptorBindingToken = Any()
            adjacentStrictDescriptorBindingTokens[path] = descriptorBindingToken
            val terminalFailureObserved = AtomicBoolean(false)
            val binding = try {
                transport.bindResidentBodies(
                    episode,
                    seal,
                    NtkStrictResidentBodyListener { descriptor ->
                        acceptAdjacentStrictBodyDescriptor(
                            path,
                            seal,
                            descriptorBindingToken,
                            terminalFailureObserved,
                            descriptor,
                        )
                    },
                )
            } catch (failure: Exception) {
                adjacentStrictDescriptorBindingTokens.remove(path, descriptorBindingToken)
                (transport as? Closeable)?.close()
                recordIfUnexpected(failure)
                return false
            }
            val sourceEventBinding = try {
                transport.addSourceEventListener(
                    NtkSourceEventListener { event ->
                        when (event) {
                            is SourceEvent.BodyPublished ->
                                acceptAdjacentStrictBodyDescriptor(
                                    path,
                                    seal,
                                    descriptorBindingToken,
                                    terminalFailureObserved,
                                    event.descriptor,
                                )

                            is SourceEvent.TerminalFailure ->
                                invalidateAdjacentStrictDescriptorBinding(
                                    path = path,
                                    seal = seal,
                                    descriptorBindingToken = descriptorBindingToken,
                                    terminalFailureObserved = terminalFailureObserved,
                                    reason = "source_terminal_failure",
                                )

                            is SourceEvent.MetadataReady -> Unit
                        }
                    },
                )
            } catch (failure: Exception) {
                adjacentStrictDescriptorBindingTokens.remove(path, descriptorBindingToken)
                runCatching { binding.close() }
                (transport as? Closeable)?.close()
                recordIfUnexpected(failure)
                return false
            }
            val claim = AdjacentStrictSourceClaim(
                manifestDigest = seal.digestSha256,
                episode = episode,
                pageCount = seal.pageCount,
                transport = transport,
                directWifiRunwayProfile =
                    transport.directWifiAdjacentRunwayProfile ||
                        NtkStrictEpisodeDiscoveryCoordinator.isDirectWifiAdjacentRouteProfile(
                            path,
                            seal.revision,
                        ),
                residentBinding = binding,
                sourceEventBinding = sourceEventBinding,
                predecessorEpisodePath = predecessorPath,
                descriptorBindingToken = descriptorBindingToken,
                terminalFailureObserved = terminalFailureObserved,
            )
            val claimPublished = synchronized(terminalFailureObserved) {
                if (terminalFailureObserved.get() ||
                    adjacentStrictDescriptorBindingTokens[path] !== descriptorBindingToken
                ) {
                    false
                } else {
                    adjacentStrictSourceClaims[path] = claim
                    true
                }
            }
            if (!claimPublished) {
                adjacentStrictDescriptorBindingTokens.remove(path, descriptorBindingToken)
                runCatching { sourceEventBinding.close() }
                runCatching { binding.close() }
                runCatching { (transport as? Closeable)?.close() }
                adjacentStrictBodyDescriptors.keys.removeAll {
                    it.startsWith("$path|${seal.digestSha256}|")
                }
                Log.w(
                    TAG,
                    "append_adjacent_strict_source_claim_replay_rejected path=$path " +
                        "generation=${seal.revision} digest=${seal.digestSha256}",
                )
                wakeStrictRemainingAdjacentAppend(path)
                return false
            }
            val drawableProofKey = adjacentStrictDrawableRunwayProofKey(
                path,
                seal.digestSha256,
            )
            adjacentStrictDrawableRunwayProofs[drawableProofKey]?.let { committedSources ->
                synchronized(claim) {
                    claim.drawableRunwayCommittedSources.addAll(committedSources)
                }
            }
            cancelAdjacentStrictRecoveryBindDeadline(path)
            // Recovery can park before this replacement exists. Claim installation is therefore
            // itself an event edge: redrive that exact waiter so viewport activation, body replay,
            // registration recheck and its no-progress watchdog are all bound to this generation.
            if (waitingStrictRemainingAdjacentAppends[path] != null) {
                wakeStrictRemainingAdjacentAppend(path)
            }
            // A control-only discovery may now exist while the predecessor decode tail is still
            // finishing. Never infer body admission from manifest availability; only the frozen
            // coordinator full gate can release this exact transport.
            if (NtkStrictEpisodeDiscoveryCoordinator.isAdjacentBodyGateOpen(
                    path,
                    strictExactForegroundViewerGenerationAtCreation,
                )
            ) {
                if (!releaseAdjacentStrictClaimAfterPredecessorComplete(path, claim)) {
                    // The source may have failed or delivered a replayed terminal edge between
                    // claim publication and predecessor release. Do not publish that dead claim's
                    // canonical URLs: its invalidated map entry deliberately remains visible to
                    // holdOrRecoverAdjacentStrictSource so the exact generation can be retired.
                    return false
                }
            }
            val requiredRunwaySources = (0 until minOf(
                initialAdjacentRunwayPageLimit(path),
                seal.pageCount,
            )).toSet()
            val drawableRunwayAlreadyCommitted = synchronized(claim) {
                requiredRunwaySources.isNotEmpty() &&
                    claim.drawableRunwayCommittedSources.containsAll(requiredRunwaySources)
            }
            if (drawableRunwayAlreadyCommitted) {
                signalDirectWifiAdjacentDrawableRunwayCommitted(target)
            }
            recovery?.let {
                it.awaitingReplacement = false
                it.rediscoveryRequestCount = 0
                it.lastBindDeadlineAtMs = 0L
                it.pendingValidatedRedriveEpoch = 0L
            }
            Log.d(
                TAG,
                "append_adjacent_strict_source_claimed path=$path " +
                    "digest=${seal.digestSha256} pages=${seal.pageCount} " +
                    "directWifiRunway=${claim.directWifiRunwayProfile}",
            )
            return true
        }
    }

    /** Exactly one current binding may release its source workset after predecessor completion. */
    private fun releaseAdjacentStrictClaimAfterPredecessorComplete(
        path: String,
        claim: AdjacentStrictSourceClaim,
    ): Boolean {
        var releaseFailure: Exception? = null
        val accepted = synchronized(claim.terminalFailureObserved) {
            if (cancelled.get() || claim.terminalFailureObserved.get() ||
                adjacentStrictSourceClaims[path] !== claim ||
                adjacentStrictDescriptorBindingTokens[path] !== claim.descriptorBindingToken
            ) {
                false
            } else if (!claim.predecessorReleaseIssued.compareAndSet(false, true)) {
                true
            } else {
                try {
                    claim.transport.onAdjacentPredecessorComplete(claim.episode)
                    true
                } catch (failure: Exception) {
                    releaseFailure = failure
                    false
                }
            }
        }
        releaseFailure?.let { failure ->
            invalidateAdjacentStrictSourceClaim(
                path,
                claim,
                "predecessor_release_failed:${failure.javaClass.simpleName}",
            )
            if (!cancelled.get() && !isExpectedCancellation(failure)) {
                recordIfUnexpected(failure)
            }
        }
        return accepted
    }

    /**
     * Converges the physical resident channel and actor-ledger replay on one immutable descriptor
     * installation. Registration can race either publication channel, so only the first matching
     * capability owns wake side effects; an at-least-once duplicate is a validated no-op.
     */
    private fun acceptAdjacentStrictBodyDescriptor(
        path: String,
        seal: NtkEpisodeManifestSeal,
        descriptorBindingToken: Any,
        terminalFailureObserved: AtomicBoolean,
        descriptor: NtkStrictBodyDescriptor,
    ) {
        if (cancelled.get() || terminalFailureObserved.get() ||
            consumedStrictSourcePaths.contains(path) ||
            adjacentStrictDescriptorBindingTokens[path] !== descriptorBindingToken
        ) {
            return
        }
        val sourceIndex = descriptor.sourceKey.pageIndex
        val canonical = seal.normalizedCanonicalAssets.getOrNull(sourceIndex)
        if (canonical == null) {
            invalidateAdjacentStrictDescriptorBinding(
                path,
                seal,
                descriptorBindingToken,
                terminalFailureObserved,
                "descriptor_source_out_of_range:$sourceIndex",
            )
            return
        }
        if (descriptor.sourceKey.manifestDigest != seal.digestSha256 ||
            descriptor.metadata.canonicalAsset != canonical ||
            descriptor.sourceKey.canonicalAssetDigest !=
            NtkStripDigests.canonicalAssetDigestSha256(canonical)
        ) {
            invalidateAdjacentStrictDescriptorBinding(
                path,
                seal,
                descriptorBindingToken,
                terminalFailureObserved,
                "descriptor_authority_mismatch:$sourceIndex",
            )
            return
        }
        val key = adjacentStrictBodyDescriptorKey(
            path,
            seal.digestSha256,
            sourceIndex,
        )
        val previous = synchronized(terminalFailureObserved) {
            if (terminalFailureObserved.get() ||
                adjacentStrictDescriptorBindingTokens[path] !== descriptorBindingToken
            ) {
                return
            }
            adjacentStrictBodyDescriptors.putIfAbsent(key, descriptor)
        }
        if (previous != null) {
            val immutableDuplicate = previous.sourceKey == descriptor.sourceKey &&
                previous.metadata == descriptor.metadata &&
                previous.proof == descriptor.proof
            if (!immutableDuplicate) {
                invalidateAdjacentStrictDescriptorBinding(
                    path,
                    seal,
                    descriptorBindingToken,
                    terminalFailureObserved,
                    "descriptor_duplicate_mutated:$sourceIndex",
                )
            } else {
                // The resident replay and source-event channels are deliberately at-least-once.
                // A rehydrate owner can be registered after the first callback and finish its
                // bounded unavailable-body wave just before this replay arrives. Treat every
                // validated immutable publication as an idempotent condition edge: the
                // identity-bound single-flight owner below prevents duplicate decode work.
                wakeStrictAdjacentExactRehydrate(
                    path,
                    seal.digestSha256,
                    sourceIndex,
                )
                requestPublishedExactAdjacentInitialRunwayCompletion(path)
            }
            return
        }
        cancelAdjacentStrictDescriptorWaitWatchdog(path)
        preparingInitialAdjacentRunways[path]?.residentBodySignal?.release()
        // Body authority is sufficient to wake the exact page that was already requested by the
        // real viewport. Do not gate this edge on firstActualFramePresented: for a short p0 the
        // compositor needs p1 to form its first clean incoming viewport, while first-actual itself
        // requires that clean viewport. Waiting for either side creates a permanent p1/entry cycle.
        // The wake is source-identity scoped and the rehydrate route retains its protected-window,
        // motion and one-owner admission checks, so this does not predecode an offscreen suffix.
        wakeStrictAdjacentExactRehydrate(
            path,
            seal.digestSha256,
            sourceIndex,
        )
        wakeInitialAdjacentExactP0Append(
            path,
            seal.digestSha256,
            sourceIndex,
        )
        wakeInitialAdjacentManhwaRunwayAppend(
            path,
            seal.digestSha256,
            sourceIndex,
            seal.pageCount,
        )
        val firstActualFramePresented = adjacentStrictSourceClaims[path]
            ?.firstActualFramePresented
            ?.get() == true
        if (NtkAdjacentDescriptorWakePolicy.shouldWakeRemainder(firstActualFramePresented)) {
            // Before the compositor proves entry, p0 and the atomic p0..p4 runway have their own
            // dedicated wake channels above. A p5+ body is only offscreen authority; waking the
            // generic remainder owner for every EOF made it take page/surface locks merely to park
            // again during the predecessor's physical fling. onFirstActualFramePresented performs
            // the one required catch-up wake, so no already-resident descriptor can be stranded.
            wakeStrictRemainingAdjacentAppend(path)
            wakeStrictAdjacentExactRehydrate(
                path,
                seal.digestSha256,
                sourceIndex,
            )
            requestEnteredExactEpisodePixelCompletion(path)
        }
        requestPublishedExactAdjacentInitialRunwayCompletion(path)
    }

    /**
     * Source callbacks are total: corrupt capabilities never throw through a listener dispatcher
     * where runCatching could strand an event-only waiter. Only the exact current binding may
     * invalidate its generation, and every invalidation emits the terminal recovery edge.
     */
    private fun invalidateAdjacentStrictDescriptorBinding(
        path: String,
        seal: NtkEpisodeManifestSeal,
        descriptorBindingToken: Any,
        terminalFailureObserved: AtomicBoolean,
        reason: String,
    ) {
        if (cancelled.get() || consumedStrictSourcePaths.contains(path) ||
            adjacentStrictDescriptorBindingTokens[path] !== descriptorBindingToken
        ) {
            return
        }
        val invalidated = synchronized(terminalFailureObserved) {
            if (adjacentStrictDescriptorBindingTokens[path] !== descriptorBindingToken) {
                false
            } else {
                terminalFailureObserved.compareAndSet(false, true)
            }
        }
        if (!invalidated) return
        adjacentStrictDescriptorBindingTokens.remove(path, descriptorBindingToken)
        cancelAdjacentStrictDescriptorWaitWatchdog(path)
        Log.w(
            TAG,
            "append_adjacent_strict_source_invalidated path=$path " +
                "generation=${seal.revision} digest=${seal.digestSha256} reason=$reason",
        )
        wakeStrictRemainingAdjacentAppend(path)
    }

    private fun adjacentStrictBodyDescriptorKey(
        path: String,
        manifestDigest: String,
        sourceIndex: Int,
    ): String = "$path|$manifestDigest|$sourceIndex"

    private fun adjacentExactP0WakeKey(path: String, manifestDigest: String): String =
        "$path|$manifestDigest"

    private fun wakeInitialAdjacentExactP0Append(
        path: String,
        manifestDigest: String,
        sourceIndex: Int,
    ) {
        if (sourceIndex != 0 || !path.startsWith("/webtoon/")) return
        // This wake belongs to the immutable exact source generation. A later process-wide
        // network transition cannot revoke its already-admitted resident-body publication.
        if (!isDirectWifiStrictAdjacentRunwayProfile(episodePath = path)) return
        val wakeKey = adjacentExactP0WakeKey(path, manifestDigest)
        waitingInitialAdjacentExactP0Appends.wake(wakeKey)
    }

    private fun wakeInitialAdjacentManhwaRunwayAppend(
        path: String,
        manifestDigest: String,
        sourceIndex: Int,
        pageCount: Int,
    ) {
        if (!path.startsWith("/manhwa/") ||
            !isDirectWifiStrictAdjacentRunwayProfile(episodePath = path)
        ) return
        val requiredRunwayPages = minOf(initialAdjacentRunwayPageLimit(path), pageCount)
        // p0 can publish the structure before p1..pN finish decoding. Every body in the bounded
        // initial runway is therefore a meaningful condition edge; waking only on p0 strands the
        // already-registered atomic runway waiter when the remaining bodies arrive afterwards.
        if (requiredRunwayPages <= 0 || sourceIndex !in 0 until requiredRunwayPages) return
        val p0Ready = adjacentStrictBodyDescriptors.containsKey(
            adjacentStrictBodyDescriptorKey(path, manifestDigest, 0),
        )
        if (p0Ready) {
            val wakeKey = adjacentExactP0WakeKey(path, manifestDigest)
            initialAdjacentManhwaRunwayEventWakeKeys.add(wakeKey)
            if (!waitingInitialAdjacentManhwaRunwayAppends.wake(wakeKey)) {
                initialAdjacentManhwaRunwayEventWakeKeys.remove(wakeKey)
            }
        }
    }

    private fun strictAdjacentBodyDescriptor(ref: PageRef): NtkStrictBodyDescriptor? {
        if (ref.transitionTitle != null || ref.sourceIndex < 0) return null
        val authority = exactViewerApiAdjacentAuthority(ref.manga) ?: return null
        if (!ensureAdjacentStrictSourceClaim(ref.manga, authority)) return null
        val path = authority.seal.normalizedEpisodePath
        val descriptor = adjacentStrictBodyDescriptors[
            adjacentStrictBodyDescriptorKey(
                path,
                authority.seal.digestSha256,
                ref.sourceIndex,
            )
        ] ?: return null
        val canonical = authority.seal.normalizedCanonicalAssets.getOrNull(ref.sourceIndex)
            ?: return null
        return descriptor.takeIf {
            ref.manifestDigest == authority.seal.digestSha256 &&
                ref.manifestPageCount == authority.seal.pageCount &&
                ref.canonicalAsset == canonical &&
                it.metadata.canonicalAsset == canonical &&
                it.sourceKey.manifestDigest == authority.seal.digestSha256 &&
                it.sourceKey.canonicalAssetDigest ==
                NtkStripDigests.canonicalAssetDigestSha256(canonical)
        }
    }

    private fun exactViewerApiAdjacentAuthority(target: Manga): NtkAuthoritativeManifest? {
        val path = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath?.trim().orEmpty()
        )
        if (path.isEmpty()) return null
        val authority = NtkSourceSpoolRegistry.currentAuthoritativeManifest(path) ?: return null
        val snapshot = NtkSourceSpoolRegistry.currentSnapshot(path) ?: return null
        if (snapshot.generation != authority.seal.revision ||
            snapshot.manifestDigest != authority.seal.digestSha256 ||
            snapshot.state.ordinal < NtkSourceState.OWNED_PRECLAIM.ordinal ||
            snapshot.state.ordinal >= NtkSourceState.TERMINAL_CLOSING.ordinal
        ) {
            return null
        }
        val recoveryDigestMatches = synchronized(adjacentStrictSourceClaimLock) {
            val recovery = adjacentStrictRecoveryStates[path]
            if (recovery == null || recovery.expectedManifestDigest == authority.seal.digestSha256) {
                true
            } else {
                recovery.exhausted = true
                recovery.networkRearmableTerminal = false
                recovery.pendingValidatedRedriveEpoch = 0L
                false
            }
        }
        if (!recoveryDigestMatches) {
            Log.e(
                TAG,
                "append_adjacent_strict_recovery_identity_rejected path=$path " +
                    "digest=${authority.seal.digestSha256}",
            )
            return null
        }
        if (!NtkAdjacentEpisodeAuthorityPolicy.supportsStrictAdjacentManifest(authority, path)) {
            return null
        }
        val urls = authority.seal.normalizedCanonicalAssets
        if (urls.isEmpty() || urls.size != authority.seal.pageCount) return null
        return authority
    }

    private fun waitForExactViewerApiAdjacentUrls(
        target: Manga,
        predecessorEpisodePath: String,
        timeoutMs: Long,
    ): List<String> {
        val targetPath = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(predecessorEpisodePath)
        if (targetPath.isEmpty() || predecessorPath.isEmpty()) return emptyList()
        fun requestExactDiscovery(reason: String) {
            // The exact manifest joins its first body probes. Protect that one validated neighbor
            // before publishing the request so active input cannot classify those calls as
            // unrelated episode work and cancel the discovery that the boundary is awaiting.
            ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
                targetPath,
                NTK_ADJACENT_APPEND_FOREGROUND_PATH_TTL_MS,
                reason,
            )
            listener.onAdjacentExactManifestRequired(target, predecessorPath)
        }
        requestExactDiscovery("adjacent_exact_manifest_wait")
        val deadline = SystemClock.elapsedRealtime() + timeoutMs.coerceAtLeast(0L)
        while (!cancelled.get() && SystemClock.elapsedRealtime() < deadline) {
            exactViewerApiAdjacentUrls(target)?.let { return it }
            val replacedCancelledFlight = NtkStrictEpisodeDiscoveryCoordinator
                .retireCancelledAdjacentTargetForReplacement(
                    targetPath,
                    ViewerTelemetry.activeGeneration(),
                    "adjacent_exact_manifest_wait",
                )
            if (replacedCancelledFlight) {
                requestExactDiscovery("adjacent_exact_manifest_cancelled_retry")
                Log.d(
                    TAG,
                    "append_adjacent_exact_manifest_cancelled_retry path=$targetPath " +
                        "predecessor=$predecessorPath",
                )
            }
            // A terminal claimed generation can otherwise make every caller join its stale
            // authority until this timeout expires. Detach/retry only that exact identity while
            // the same bounded wait remains in progress.
            if (!replacedCancelledFlight) holdOrRecoverAdjacentStrictSource(target)
            SystemClock.sleep(NTK_APPEND_EARLY_GENERATED_POLL_MS)
        }
        return exactViewerApiAdjacentUrls(target).orEmpty()
    }

    private fun fetchGeneratedNtkAppendUrlsWithEarlyHandoff(target: Manga, mode: String? = null): Int {
        Log.d(
            TAG,
            "append_adjacent_early_handoff_start path=${target.ntkEpisodePath} mode=$mode " +
                "images=${imageRepository.imageUrls(target, appContext).size}"
        )
        val task = FutureTask {
            val appendCancellation = MangaRepository.cancellation()
            appendCancellation.userVisible()
            if (mode != null) {
                imageRepository.fetchViewerInitialWithMode(target, appendCancellation, mode)
            } else {
                imageRepository.fetchViewerInitial(target, appendCancellation)
            }
        }
        return try {
            val fetchThread = Thread({
                Process.setThreadPriority(Process.THREAD_PRIORITY_DEFAULT)
                task.run()
            }, "ntk-append-fetch")
            fetchThread.isDaemon = true
            fetchThread.start()
            val earlyWaitMs = if (mode == "api-strict") {
                NTK_APPEND_EARLY_API_STRICT_HANDOFF_WAIT_MS
            } else {
                NTK_APPEND_EARLY_GENERATED_WAIT_MS
            }
            val deadline = SystemClock.elapsedRealtime() + earlyWaitMs
            while (!cancelled.get() && !task.isDone && SystemClock.elapsedRealtime() < deadline) {
                if (installEarlyGeneratedAppendUrlsIfAvailable(target) > 0) {
                    Log.d(
                        TAG,
                        "append_adjacent_early_generated_handoff path=${target.ntkEpisodePath} " +
                            "images=${imageRepository.imageUrls(target, appContext).size}"
                    )
                    return Title.LOAD_OK
                }
                SystemClock.sleep(NTK_APPEND_EARLY_GENERATED_POLL_MS)
            }
            val result = try {
                task.get()
            } catch (e: ExecutionException) {
                val cause = e.cause
                if (cause is Exception) throw cause
                throw e
            }
            Log.d(
                TAG,
                "append_adjacent_api_strict_probe path=${target.ntkEpisodePath} mode=$mode " +
                    "result=$result images=${imageRepository.imageUrls(target, appContext).size} " +
                    "reason=${target.ntkViewerParseReason} cancelled=${cancelled.get()}"
            )
            if (installEarlyGeneratedAppendUrlsIfAvailable(target) > 0 ||
                (mode == "api-strict" &&
                    waitForEarlyAppendUrlsIfAvailable(target, NTK_APPEND_EARLY_API_STRICT_LATE_WAIT_MS) > 0)
            ) {
                Title.LOAD_OK
            } else if (
                mode == "api-strict" &&
                result != Title.LOAD_OK &&
                waitForStrictNtkAckProof(target, NTK_APPEND_API_STRICT_ACK_RETRY_WAIT_MS)
            ) {
                val retryResult = withRepositoryCancellation(userVisible = true) { retryCancellation ->
                    imageRepository.fetchViewerInitialWithMode(target, retryCancellation, mode)
                }
                if (installEarlyGeneratedAppendUrlsIfAvailable(target) > 0 ||
                    waitForEarlyAppendUrlsIfAvailable(target, NTK_APPEND_EARLY_API_STRICT_LATE_WAIT_MS) > 0
                ) {
                    Title.LOAD_OK
                } else {
                    retryResult
                }
            } else {
                result
            }
        } catch (e: Exception) {
            recordIfUnexpected(e)
            Log.d(
                TAG,
                "append_adjacent_early_handoff_error path=${target.ntkEpisodePath} mode=$mode " +
                    "cancelled=${cancelled.get()} error=${e.javaClass.simpleName}:${e.message}"
            )
            if (mode == "api-strict") {
                if (!cancelled.get() &&
                    waitForStrictNtkAckProof(target, NTK_APPEND_API_STRICT_ACK_RETRY_WAIT_MS)
                ) {
                    val retryResult = try {
                        withRepositoryCancellation(userVisible = true) { retryCancellation ->
                            imageRepository.fetchViewerInitialWithMode(target, retryCancellation, mode)
                        }
                    } catch (retryError: Exception) {
                        recordIfUnexpected(retryError)
                        Log.d(
                            TAG,
                            "append_adjacent_early_handoff_retry_error path=${target.ntkEpisodePath} " +
                                "error=${retryError.javaClass.simpleName}:${retryError.message}"
                        )
                        Title.LOAD_ERROR
                    }
                    if (installEarlyGeneratedAppendUrlsIfAvailable(target) > 0 ||
                        waitForEarlyAppendUrlsIfAvailable(target, NTK_APPEND_EARLY_API_STRICT_LATE_WAIT_MS) > 0
                    ) {
                        Title.LOAD_OK
                    } else {
                        retryResult
                    }
                } else if (waitForEarlyAppendUrlsIfAvailable(
                        target,
                        NTK_APPEND_EARLY_API_STRICT_LATE_WAIT_MS,
                        ignoreSessionCancelled = true
                    ) > 0) {
                    Title.LOAD_OK
                } else {
                    Title.LOAD_ERROR
                }
            } else {
                Title.LOAD_ERROR
            }
        }
    }

    private fun shouldPreferVerifiedApiAppend(target: Manga, currentTitle: Title): Boolean {
        if (!isNtkSource(target, currentTitle)) return false
        if (target.baseMode != ml.melun.mangaview.mangaview.MTitle.base_webtoon) return false
        return !Manga.shouldUseGeneratedAppendBeforeApi(
            target.baseMode,
            target.ntkEpisodePath,
            target.ntkImageCount
        )
    }

    private fun installEarlyGeneratedAppendUrlsIfAvailable(target: Manga): Int {
        if (!isNtkSource(target, title)) return 0
        val repositoryUrls = imageRepository.imageUrls(target, appContext)
        if (repositoryUrls.isNotEmpty()) {
            val completeUrls = completeKnownGeneratedAppendUrls(target, repositoryUrls)
            Log.d(
                TAG,
                "append_adjacent_repository_urls_installed targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} images=${completeUrls.size}"
            )
            return completeUrls.size
        }
        var earlyUrls = ReaderImageCache.earlyNtkAppendImageUrls(
            target.ntkEpisodePath,
            SystemClock.elapsedRealtime() - 30000L
        )
        if (earlyUrls.isEmpty()) {
            earlyUrls = ReaderImageCache.earlyNtkImageUrls(
                target.ntkEpisodePath,
                SystemClock.elapsedRealtime() - 30000L
            )
        }
        if (earlyUrls.isEmpty()) return 0
        val completeUrls = completeKnownGeneratedAppendUrls(target, earlyUrls)
        target.setImgs(ArrayList(completeUrls))
        Log.d(
            TAG,
            "append_adjacent_early_generated_installed targetId=${target.id} " +
                "path=${target.ntkEpisodePath} images=${completeUrls.size} early=${earlyUrls.size}"
        )
        return completeUrls.size
    }

    private fun waitForEarlyAppendUrlsIfAvailable(
        target: Manga,
        timeoutMs: Long,
        ignoreSessionCancelled: Boolean = false
    ): Int {
        val deadline = SystemClock.elapsedRealtime() + timeoutMs.coerceAtLeast(0L)
        while ((ignoreSessionCancelled || !cancelled.get()) && SystemClock.elapsedRealtime() < deadline) {
            val installed = installEarlyGeneratedAppendUrlsIfAvailable(target)
            if (installed > 0) {
                Log.d(
                    TAG,
                    "append_adjacent_early_api_handoff path=${target.ntkEpisodePath} images=$installed"
                )
                return installed
            }
            SystemClock.sleep(NTK_APPEND_EARLY_GENERATED_POLL_MS)
        }
        return installEarlyGeneratedAppendUrlsIfAvailable(target)
    }

    private fun waitForStrictNtkAckProof(target: Manga, timeoutMs: Long): Boolean {
        val path = target.ntkEpisodePath ?: return false
        val client = MainApplication.getHttpClient()
        val startedAt = SystemClock.elapsedRealtime()
        val deadline = SystemClock.elapsedRealtime() + timeoutMs.coerceAtLeast(0L)
        while (!cancelled.get() && SystemClock.elapsedRealtime() < deadline) {
            if (client.hasRecentStrictNtkAdAckProof(path)) {
                Log.d(
                    TAG,
                    "append_adjacent_api_strict_ack_ready path=$path ms=${SystemClock.elapsedRealtime() - startedAt}"
                )
                return true
            }
            SystemClock.sleep(NTK_APPEND_EARLY_GENERATED_POLL_MS)
        }
        val ready = client.hasRecentStrictNtkAdAckProof(path)
        Log.d(
            TAG,
            "append_adjacent_api_strict_ack_wait_done path=$path ready=$ready " +
                "cancelled=${cancelled.get()} ms=${SystemClock.elapsedRealtime() - startedAt}"
        )
        return ready
    }

    private fun primeForwardTimeline() {
        if (cancelled.get() || !timelinePrimeLoading.compareAndSet(false, true)) return
        try {
            control.execute {
            try {
                var current = manga
                val currentTitle = title ?: current.title ?: manga.title ?: return@execute
                if (syncNtkTitlePathFromEpisode(currentTitle, current)) {
                    currentTitle.removeEps()
                }
                if (currentTitle.eps == null || currentTitle.eps.size <= 1) {
                    val result = withRepositoryCancellation {
                        imageRepository.fetchEpisodesForeground(currentTitle, it)
                    }
                    if (cancelled.get()) return@execute
                    if (result != Title.LOAD_OK) return@execute
                }
                attachTitle()
                val episodes = Utils.snapshotEpisodes(currentTitle)
                if (episodes.isNotEmpty()) {
                    manga.setEps(episodes)
                    current.setEps(episodes)
                }
                current.title = currentTitle
                current.titleId = currentTitle.id
                val ntk = isNtkSource(manga, title)
                val primedRefs = ArrayList<PageRef>()
                val cardOffsets = ArrayList<Int>()
                var checked = 0
                val maxPrimeEpisodes = when {
                    ntk -> NTK_PRIME_FORWARD_EPISODES
                    isWfwfSource(current, currentTitle) -> 1
                    else -> PRIME_FORWARD_EPISODES
                }
                while (!cancelled.get() && checked < maxPrimeEpisodes) {
                    // Use the same direction-checked resolver as the boundary path. WFWF keeps a
                    // "first episode" action above the newest real row; raw nextEp() therefore
                    // used to prime 1183 -> 1184 -> episode 1 and publish that corrupt timeline
                    // long before the user reached the boundary.
                    val target = adjacentEpisodeCandidates(
                        current,
                        episodes,
                        ReaderSurfaceView.DIRECTION_NEXT,
                    ).firstOrNull() ?: break
                    target.title = currentTitle
                    target.titleId = currentTitle.id
                    target.mode = current.mode
                    if (episodes.isNotEmpty()) target.setEps(episodes)
                    if (!hasEpisode(target)) {
                        if (imageRepository.imageUrls(target, appContext).isNullOrEmpty()) {
                            val result = withRepositoryCancellation {
                                imageRepository.fetchViewerInitial(target, it)
                            }
                            if (cancelled.get()) return@execute
                            if (result != Title.LOAD_OK) break
                        }
                        val urls = imageRepository.imageUrls(target, appContext)
                        if (urls.isNullOrEmpty()) break
                        val episodeRefs = pageRefsForEpisode(target, urls, ReaderSurfaceView.DIRECTION_NEXT)
                        if (ntk) {
                            appendPrimedForwardRefs(episodeRefs, listOf(0), lightWarm = checked > 0)
                        } else {
                            cardOffsets.add(primedRefs.size)
                            primedRefs.addAll(episodeRefs)
                        }
                    }
                    checked++
                    current = target
                }
                if (!ntk) appendPrimedForwardRefs(primedRefs, cardOffsets)
            } catch (e: Exception) {
                recordIfUnexpected(e)
            } finally {
                timelinePrimeLoading.set(false)
            }
            }
        } catch (_: RejectedExecutionException) {
            timelinePrimeLoading.set(false)
        }
    }

    private fun pageRefsForEpisode(target: Manga, urls: List<String>, direction: Int): List<PageRef> {
        val episodeName = target.name ?: title?.name ?: "회차"
        val transitionTitle = if (direction < 0) "이전 회차: $episodeName" else "다음 회차: $episodeName"
        val pageRefs = pageRefsForImages(target, urls)
        val ntkGeneratedPrepend = direction < 0 &&
            isNtkSource(target, title) &&
            pageRefs.isNotEmpty() &&
            pageRefs.all { isNtkGeneratedImageUrl(it.image.orEmpty()) }
        if (ntkGeneratedPrepend) {
            Log.d(
                TAG,
                "reader_repository_stage stage=generated_prepend_skip_transition_card," +
                    "path=${target.ntkEpisodePath},count=${pageRefs.size},direction=$direction"
            )
            return pageRefs
        }
        if (isNtkSource(target, title) && pageRefs.any { isNtkBoardUploadImageUrl(it.image) }) {
            logNtkRepositoryStage(
                target,
                "board_uploads_keep_original_timeline",
                "count=${pageRefs.count { isNtkBoardUploadImageUrl(it.image) }}"
            )
        }
        val totalPages = pageRefs.size
        return ArrayList<PageRef>(pageRefs.size + 1).apply {
            if (direction < 0) {
                addAll(pageRefs)
                add(PageRef(target, null, transitionTitle, localPage = 0, totalPages = totalPages))
            } else {
                add(PageRef(target, null, transitionTitle, localPage = 0, totalPages = totalPages))
                addAll(pageRefs)
            }
        }
    }

    private fun pageRefsForImages(target: Manga, urls: List<String>): List<PageRef> {
        val normalizedEpisodePath = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath.orEmpty()
        )
        val canonicalAssets = urls.map(NtkStripDigests::canonicalAsset)
        val hasCandidateManifestIdentity =
            normalizedEpisodePath.isNotBlank() &&
                canonicalAssets.isNotEmpty() &&
                canonicalAssets.none { it.isBlank() }
        val ntkEpisode = isNtkSource(target, title)
        val exactAuthority = if (ntkEpisode && hasCandidateManifestIdentity) {
            NtkSourceSpoolRegistry.currentAuthoritativeManifest(normalizedEpisodePath)
        } else {
            null
        }
        val exactAuthorityPageCount = exactAuthority?.seal?.pageCount ?: 0
        val exactAuthorityAssetsMatch =
            exactAuthority?.isProductionClaimable == true &&
                exactAuthority.seal.normalizedEpisodePath.equals(
                    normalizedEpisodePath,
                    ignoreCase = true,
                ) &&
                exactAuthority.seal.normalizedCanonicalAssets == canonicalAssets
        val trustedExactPageCount = if (ntkEpisode && hasCandidateManifestIdentity) {
            ReaderImageCache.trustedNtkImageApiCount(normalizedEpisodePath, 0L)
        } else {
            0
        }
        val trustedExactAssets = if (trustedExactPageCount > 0) {
            ReaderImageCache.earlyNtkImageUrls(normalizedEpisodePath, 0L)
                .take(trustedExactPageCount)
                .map(NtkStripDigests::canonicalAsset)
        } else {
            emptyList()
        }
        val trustedExactAssetsMatch =
            trustedExactPageCount == canonicalAssets.size &&
                trustedExactAssets == canonicalAssets &&
                ReaderImageCache.hasAuthoritativeCompleteEarlyNtkImageUrls(
                    normalizedEpisodePath,
                    trustedExactPageCount,
                    0L,
                )
        val hasCompleteManifestIdentity =
            hasCandidateManifestIdentity &&
                NtkAdjacentPartialManifestPolicy.canPublishCompleteManifestIdentity(
                    ntkEpisode = ntkEpisode,
                    candidatePageCount = canonicalAssets.size,
                    declaredPageCount = target.ntkImageCount,
                    exactAuthorityPageCount = exactAuthorityPageCount,
                    exactAuthorityAssetsMatch = exactAuthorityAssetsMatch,
                    trustedExactPageCount = trustedExactPageCount,
                    trustedExactAssetsMatch = trustedExactAssetsMatch,
                )
        val manifestPageCount = if (hasCompleteManifestIdentity) canonicalAssets.size else 0
        val manifestDigest = if (hasCompleteManifestIdentity) {
            NtkEpisodeManifestSeal.computeDigestSha256(
                normalizedEpisodePath,
                manifestPageCount,
                canonicalAssets
            )
        } else {
            ""
        }
        if (!autoCut) {
            val totalPages = urls.size
            return urls.mapIndexed { index, url ->
                PageRef(
                    manga = target,
                    image = url,
                    sourceIndex = index,
                    pageIndex = index,
                    localPage = index + 1,
                    totalPages = totalPages,
                    manifestDigest = manifestDigest,
                    manifestPageCount = manifestPageCount
                )
            }
        }
        val splitPages = urls.mapIndexed { index, url -> shouldAutoSplitImage(target, url, index) }
        val totalPages: Int = splitPages.fold(0) { total, split -> total + if (split) 2 else 1 }
        val refs = ArrayList<PageRef>(totalPages)
        var localPage = 1
        for (index in urls.indices) {
            val url = urls[index]
            val split = splitPages[index]
            refs.add(
                PageRef(
                    target,
                    url,
                    sourceIndex = index,
                    localPage = localPage++,
                    totalPages = totalPages,
                    side = PAGE_SIDE_FIRST,
                    allowAutoSplit = split,
                    manifestDigest = manifestDigest,
                    manifestPageCount = manifestPageCount
                )
            )
            if (splitPages[index]) {
                refs.add(
                    PageRef(
                        target,
                        url,
                        sourceIndex = index,
                        localPage = localPage++,
                        totalPages = totalPages,
                        side = PAGE_SIDE_SECOND,
                        allowAutoSplit = split,
                        manifestDigest = manifestDigest,
                        manifestPageCount = manifestPageCount
                    )
                )
            }
        }
        return refs
    }

    private fun displayStartPage(sourcePage: Int, sourceSide: Int, refs: List<PageRef>): Int {
        if (refs.isEmpty()) return 0
        if (!autoCut) return sourcePage.coerceIn(0, refs.lastIndex)
        val side = sourceSide.coerceIn(PAGE_SIDE_FIRST, PAGE_SIDE_SECOND)
        val exact = refs.indexOfFirst { it.sourceIndex == sourcePage && it.side == side }
        if (exact >= 0) return exact
        val first = refs.indexOfFirst { it.sourceIndex == sourcePage }
        return if (first >= 0) first else sourcePage.coerceIn(0, refs.lastIndex)
    }

    private fun appendPrimedForwardRefs(refs: List<PageRef>, cardOffsets: List<Int>, lightWarm: Boolean = false) {
        if (cancelled.get() || refs.isEmpty()) return
        val startIndex: Int
        val total: Int
        val appendedCards = ArrayList<Pair<Int, String>>()
        synchronized(pagesLock) {
            val appendable = appendableNewEpisodeRefsLocked(refs)
            if (appendable.isEmpty()) return
            beginStructurePublish()
            startIndex = pages.size
            appendable.forEachIndexed { offset, page -> page.pageIndex = startIndex + offset }
            pages.addAll(appendable)
            total = pages.size
            for (offset in cardOffsets) {
                val card = refs.getOrNull(offset) ?: continue
                val appendedOffset = appendable.indexOf(card)
                if (appendedOffset >= 0 && card.transitionTitle != null) {
                    appendedCards.add(Pair(startIndex + appendedOffset, card.transitionTitle))
                }
            }
            capturePublishedPageIndexLocked()
        }
        val posted = main.post {
            var shouldWarm = false
            try {
                if (!cancelled.get()) {
                    listener.onPagesAppended(total)
                    for ((index, title) in appendedCards) {
                        listener.onPageCard(index, title)
                    }
                    shouldWarm = true
                }
            } finally {
                finishStructurePublish()
            }
            if (shouldWarm) warmPrimedForwardRefs(appendedCards.map { it.first }, total, lightWarm)
        }
        if (!posted) finishStructurePublish()
    }

    private fun warmPrimedForwardRefs(cardIndexes: List<Int>, total: Int, lightWarm: Boolean = false) {
        if (cancelled.get() || cardIndexes.isEmpty()) return
        val generation = if (isNtkSource(manga, title)) PRIME_WARM_GENERATION else windowGeneration.get()
        val ntk = isNtkSource(manga, title)
        val busy = if (ntk) true else viewportBusy.get()
        val decodeAhead = if (ntk) {
            if (lightWarm) NTK_LIGHT_PRIMED_EPISODE_DECODE_AHEAD_PAGES else NTK_PRIMED_EPISODE_DECODE_AHEAD_PAGES
        } else {
            BOUNDARY_DECODE_AHEAD_PAGES
        }
        val byteAhead = if (ntk) {
            if (lightWarm) NTK_LIGHT_PRIMED_EPISODE_BYTE_AHEAD_PAGES else NTK_PRIMED_EPISODE_BYTE_AHEAD_PAGES
        } else {
            BOUNDARY_BYTE_AHEAD_PAGES
        }
        for (cardIndex in cardIndexes) {
            requestPage(cardIndex, busy = busy, anchor = false, generation = generation)
            val decodeLast = minOf(total - 1, cardIndex + decodeAhead)
            for (index in (cardIndex + 1)..decodeLast) {
                val priority = ntk && index <= cardIndex + NTK_PRIMED_EPISODE_PRIORITY_PAGES
                val requestGeneration = if (priority) FOREGROUND_PRIME_WARM_GENERATION else generation
                requestPage(index, busy = busy, anchor = false, generation = requestGeneration)
            }
            val byteLast = minOf(total - 1, cardIndex + byteAhead)
            for (index in (decodeLast + 1)..byteLast) {
                val page = pageRef(index) ?: continue
                try {
                    network.execute { prefetchImageFileQuietly(index, page) }
                } catch (_: RejectedExecutionException) {
                    return
                }
            }
        }
    }

    private fun appendResolvedEpisode(target: Manga, urls: List<String>, direction: Int, warm: Boolean = true) {
        val useInitialRunway = shouldUseAdjacentInitialAppendRunway(target, urls, direction)
        val structureDelayMs = if (useInitialRunway) {
            0L
        } else {
            ntkForwardAppendStructureInsertDelayMs(target, urls, direction)
        }
        if (structureDelayMs > 0L) {
            val publishKey = episodeAppendKey(target)
            if (publishKey.isNotEmpty()) pendingAdjacentAppendPublishKeys.add(publishKey)
            Log.d(
                TAG,
                "append_adjacent_structure_insert_defer targetId=${target.id} path=${target.ntkEpisodePath} " +
                    "direction=$direction delayMs=$structureDelayMs anchor=${currentViewportAnchor.get()}"
            )
            main.postDelayed({
                if (cancelled.get()) {
                    if (publishKey.isNotEmpty()) pendingAdjacentAppendPublishKeys.remove(publishKey)
                    return@postDelayed
                }
                try {
                    control.execute { appendResolvedEpisode(target, urls, direction, warm) }
                } catch (_: RejectedExecutionException) {
                    if (publishKey.isNotEmpty()) pendingAdjacentAppendPublishKeys.remove(publishKey)
                }
            }, structureDelayMs)
            return
        }
        if (direction > 0 && isNtkSource(target, title)) {
            ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
                target.ntkEpisodePath,
                NTK_ADJACENT_APPEND_FOREGROUND_PATH_TTL_MS,
                "append_resolved_episode"
            )
        }
        val refs = pageRefsForEpisode(target, urls, direction)
        val cardOffset = refs.indexOfFirst { it.transitionTitle != null }
        val transitionTitle = refs.getOrNull(cardOffset)?.transitionTitle ?: ""
        val inserted = refs.size
        val publishKey = episodeAppendKey(target)
        val total: Int
        if (inserted <= 0) {
            Log.d(TAG, "append_adjacent_resolved_empty direction=$direction targetId=${target.id} path=${target.ntkEpisodePath} urls=${urls.size}")
            return
        }
        target.ntkEpisodePath?.trim()?.takeIf { it.isNotEmpty() }?.let {
            pendingAdjacentEarlyAppendTargets.remove(it)
        }
        if (
            direction > 0 &&
            appendResolvedEpisodeInitialRunway(target, refs, publishKey, warm)
        ) {
            return
        }
        if (direction < 0) {
            var structurePublishOwner: AtomicBoolean? = null
            synchronized(pagesLock) {
                if (containsEpisodeForAppendLocked(target)) {
                    Log.d(TAG, "append_adjacent_resolved_duplicate direction=$direction targetId=${target.id} path=${target.ntkEpisodePath} pages=${pages.size}")
                    return
                }
                structurePublishOwner = beginOwnedStructurePublish()
                for (page in pages) page.pageIndex += inserted
                refs.forEachIndexed { index, page -> page.pageIndex = index }
                pages.addAll(0, refs)
                total = pages.size
                shiftPageStateForPrepend(inserted)
                capturePublishedPageIndexLocked()
            }
            val holdUntilReady = prependedHoldUntilReadyCount(target, refs)
            val gateNtkPrependNotify =
                shouldGateAdjacentPrependNotifyUntilNearReady(target, inserted, holdUntilReady)
            val posted = main.post {
                try {
                    finishOwnedStructurePublish(structurePublishOwner)
                    if (cancelled.get()) return@post
                    if (warm) {
                        warmPrependedEpisode(inserted)
                        warmPrependedEpisodeStart(inserted)
                    }
                    if (gateNtkPrependNotify) {
                        notifyAdjacentPrependWhenNearReady(target, inserted, total, cardOffset, transitionTitle, holdUntilReady)
                    } else {
                        listener.onPagesPrepended(total, inserted, holdUntilReady)
                        if (cardOffset >= 0) listener.onPageCard(cardOffset, transitionTitle)
                        redeliverReadyPrependedStart(inserted)
                    }
                } finally {
                    finishOwnedStructurePublish(structurePublishOwner)
                }
            }
            if (!posted) finishOwnedStructurePublish(structurePublishOwner)
        } else {
            val cardIndex: Int
            var structurePublishOwner: AtomicBoolean? = null
            val pageReferenceSnapshot = synchronized(pagesLock) { pages.toList() }
            val skipOutOfOrder = shouldSkipForwardNtkOutOfOrderAppend(
                target,
                pageReferenceSnapshot,
            )
            val structurePublicationContext =
                prepareForwardAdjacentStructurePublication(target)
            synchronized(pagesLock) {
                if (!pageReferenceSnapshotStillCurrentLocked(pageReferenceSnapshot)) {
                    if (publishKey.isNotEmpty()) {
                        pendingAdjacentAppendPublishKeys.remove(publishKey)
                    }
                    return
                }
                if (skipOutOfOrder) {
                    Log.d(
                        TAG,
                        "append_adjacent_resolved_skip_out_of_order direction=$direction " +
                            "targetId=${target.id} path=${target.ntkEpisodePath} pages=${pages.size}"
                    )
                    if (publishKey.isNotEmpty()) pendingAdjacentAppendPublishKeys.remove(publishKey)
                    return
                }
                if (containsEpisodeForAppendLocked(target)) {
                    Log.d(TAG, "append_adjacent_resolved_duplicate direction=$direction targetId=${target.id} path=${target.ntkEpisodePath} pages=${pages.size}")
                    if (publishKey.isNotEmpty()) pendingAdjacentAppendPublishKeys.remove(publishKey)
                    return
                }
                if (structurePublicationContext == null ||
                    !claimForwardAdjacentStructurePublication(target, structurePublicationContext)
                ) {
                    if (publishKey.isNotEmpty()) pendingAdjacentAppendPublishKeys.remove(publishKey)
                    return
                }
                if (publishKey.isNotEmpty()) pendingAdjacentAppendPublishKeys.add(publishKey)
                structurePublishOwner = beginOwnedStructurePublish()
                cardIndex = pages.size
                refs.forEachIndexed { offset, page -> page.pageIndex = cardIndex + offset }
                pages.addAll(refs)
                total = pages.size
                capturePublishedPageIndexLocked()
            }
            clearPageStateFromIndex(cardIndex, appendOnlyTail = true)
            Log.d(TAG, "append_adjacent_resolved_inserted direction=$direction targetId=${target.id} path=${target.ntkEpisodePath} inserted=$inserted total=$total")
            val gateNtkGeneratedNotify =
                shouldGateAdjacentAppendNotifyUntilNearReady(target, cardIndex, total)
            if (gateNtkGeneratedNotify) {
                rememberPendingAdjacentAppendPublish(publishKey, target, cardIndex, total)
            } else {
                clearPendingAdjacentAppendPublish(publishKey)
            }
            val posted = main.post {
                try {
                    finishOwnedStructurePublish(structurePublishOwner)
                    if (cancelled.get()) return@post
                    if (gateNtkGeneratedNotify) {
                        if (warm && shouldWarmAppendedEpisode(cardIndex)) {
                            if (isImmediateNtkGeneratedUx()) {
                                warmAppendedVisibleRunway(cardIndex, total, "append_visible_generated_gate")
                                scheduleAppendSourcePrefetchAfterQuiet(
                                    cardIndex + generatedAppendVisibleRunwayPageLimit(target),
                                    total,
                                    "append_source_generated_gate"
                                )
                            } else {
                                warmAppendedEpisode(cardIndex, total)
                            }
                        }
                        Log.d(
                            TAG,
                            "append_adjacent_publish_defer_until_near_ready targetId=${target.id} " +
                                "path=${target.ntkEpisodePath} cardIndex=$cardIndex ready=" +
                                "${generatedAppendNearReadyCount(cardIndex, total)} " +
                                "required=${requiredGeneratedAppendReadyPages(target, cardIndex, total)} total=$total"
                        )
                        notifyAdjacentAppendWhenNearReady(
                            target,
                            cardIndex,
                            total,
                            cardOffset,
                            transitionTitle
                        )
                    } else {
                        listener.onPagesAppended(total)
                        if (cardOffset >= 0) listener.onPageCard(cardIndex + cardOffset, transitionTitle)
                        clearPendingAdjacentAppendPublish(publishKey)
                        if (warm && shouldWarmAppendedEpisode(cardIndex)) {
                            if (isImmediateNtkGeneratedUx()) {
                                scheduleWarmAppendedVisibleRunwayAfterNotify(
                                    cardIndex,
                                    total,
                                    "append_visible_after_notify"
                                )
                            } else {
                                warmAppendedEpisode(cardIndex, total)
                            }
                        }
                        if (isImmediateNtkGeneratedUx()) {
                            scheduleAppendSourcePrefetchAfterQuiet(
                                cardIndex + generatedAppendVisibleRunwayPageLimit(target),
                                total,
                                "append_source_after_notify"
                            )
                        } else if (!isNtkSource(target, title)) {
                            warmFullNtkAppendEpisode(cardIndex, total, "append_full_after_notify")
                        }
                    }
                } finally {
                    finishOwnedStructurePublish(structurePublishOwner)
                }
            }
            if (!posted) {
                clearPendingAdjacentAppendPublish(publishKey)
                finishOwnedStructurePublish(structurePublishOwner)
            }
        }
    }

    private fun shouldUseAdjacentInitialAppendRunway(target: Manga, urls: List<String>, direction: Int): Boolean {
        if (direction <= 0 || urls.isEmpty()) return false
        if (!isNtkSource(target, title) || !firstBitmapLogged.get()) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        return urls.all { it.isNotBlank() }
    }

    private fun isInitialTailAdjacentPreappendTarget(target: Manga): Boolean {
        val path = target.ntkEpisodePath?.trim().orEmpty()
        return path.isNotEmpty() && initialTailAdjacentPreappendTargetPaths.contains(path)
    }

    private fun strictExactInitialManhwaRunwayAuthority(
        target: Manga?,
    ): NtkAuthoritativeManifest? {
        if (target == null || !requiresStrictExactInitialManhwaRunway(target)) return null
        return exactViewerApiAdjacentAuthority(target)
    }

    /**
     * The host/direct-Wi-Fi manhwa path is fail-closed exact authority.  A generic cached p0 may
     * become ready while exact discovery is still publishing its manifest; allowing that older
     * turn to win structure ownership strands the generation-bound p1-p3 resident-body wake.
     */
    private fun requiresStrictExactInitialManhwaRunway(target: Manga): Boolean {
        if (!hostGpuEmulatorRuntime || !isDirectWifiStrictAdjacentRunwayProfile(target)) return false
        return NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
            .startsWith("/manhwa/")
    }

    private fun initialAdjacentRunwayPageLimit(episodePath: String?): Int {
        val path = NtkStripDigests.normalizeEpisodePath(episodePath.orEmpty())
        return if (
            hostGpuEmulatorRuntime &&
            isDirectWifiStrictAdjacentRunwayProfile(episodePath = path) &&
            (path.startsWith("/webtoon/") || path.startsWith("/manhwa/"))
        ) {
            NTK_HOST_GPU_DIRECT_WIFI_ADJACENT_RUNWAY_PAGES
        } else {
            NTK_APPEND_INITIAL_RUNWAY_PAGES
        }
    }

    private fun requiredInitialAdjacentRunwayPages(target: Manga): Int {
        val limit = initialAdjacentRunwayPageLimit(target.ntkEpisodePath)
        return minOf(target.ntkImageCount.takeIf { it > 0 } ?: limit, limit)
    }

    private fun initialAdjacentAppendRunwayRefCount(refs: List<PageRef>): Int {
        val target = refs.firstOrNull { it.transitionTitle == null }?.manga
        return initialAdjacentAppendRunwayRefCount(
            refs,
            strictExactInitialManhwaRunwayAuthority(target) != null,
        )
    }

    private fun initialAdjacentAppendRunwayRefCount(
        refs: List<PageRef>,
        strictExactDescriptorOnly: Boolean,
    ): Int {
        if (refs.isEmpty()) return 0
        val cardOffset = refs.indexOfFirst { it.transitionTitle != null }
        val target = refs.firstOrNull { it.transitionTitle == null }?.manga
        val initialRunwayPageLimit = initialAdjacentRunwayPageLimit(target?.ntkEpisodePath)
        val imageRunway = if (isDirectWifiStrictAdjacentRunwayProfile(target)) {
            val normalizedPath = NtkStripDigests.normalizeEpisodePath(
                target?.ntkEpisodePath.orEmpty(),
            )
            if (normalizedPath.startsWith("/webtoon/")) {
                // Tall webtoon publication is always transition+p0. The atomic policy below also
                // returns one, but eagerly building its Boolean list probes every p1..tail cache
                // sidecar even though none can affect the result. Keep the exact output and avoid
                // that FUSE/Binder work on the p0 EOF-to-visible critical path.
                NTK_DIRECT_WIFI_INITIAL_ATTACHED_RUNWAY_PAGES
            } else {
                val allImageRefs = refs.asSequence()
                    .filter { it.transitionTitle == null }
                    .toList()
                val requiredRunwaySources = target?.let(::requiredInitialAdjacentRunwayPages)
                    ?: initialRunwayPageLimit
                val boundedRefCount = NtkAdjacentRunwaySourceCohortPolicy.leadingRefCount(
                    allImageRefs.map { it.sourceIndex },
                    requiredRunwaySources,
                )
                val imageRefs = allImageRefs.take(
                    boundedRefCount.takeIf { it > 0 }
                        ?: minOf(allImageRefs.size, initialRunwayPageLimit)
                )
                val publishable = if (strictExactDescriptorOnly) {
                    // The profile was frozen before this append turn. Do not let a concurrent
                    // transport transition reclassify exact pages as generic-cache candidates.
                    imageRefs.map { strictAdjacentBodyDescriptor(it) != null }
                } else {
                    imageRefs.map(::isAdjacentRunwayRefPublishable)
                }
                NtkDirectWifiAdjacentInitialAtomicRunwayPolicy.attachedImagePageCount(
                    directWifiStrictAdjacent = true,
                    episodePath = normalizedPath,
                    sourceIndexes = imageRefs.map { it.sourceIndex },
                    publishable = publishable,
                    maximumRunwayPages = requiredRunwaySources,
                    strictExactDescriptorOnly = strictExactDescriptorOnly,
                    sourceSides = imageRefs.map { it.side },
                )
            }
        } else if (target != null && isInitialTailAdjacentPreappendTarget(target)) {
            initialRunwayPageLimit
        } else {
            initialRunwayPageLimit
                .coerceAtLeast(NTK_APPEND_INITIAL_RUNWAY_READY_PAGES)
        }
        if (strictExactDescriptorOnly && imageRunway <= 0) return 0
        val runway = if (cardOffset == 0) imageRunway + 1 else imageRunway
        return minOf(refs.size, runway)
    }

    private fun directWifiInitialAttachedRunwayPages(target: Manga): Int =
        if (isDirectWifiStrictAdjacentRunwayProfile(target)) {
            NTK_DIRECT_WIFI_INITIAL_ATTACHED_RUNWAY_PAGES
        } else {
            NTK_APPEND_INITIAL_RUNWAY_PAGES
        }

    private fun shouldDeferAdjacentRunwayForCurrentGeneratedTail(target: Manga): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(manga, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) return false
        if (Manga.sameEpisodeIdentity(manga, target)) return false
        val installed = installedDrawablePageCountForEpisode(manga)
        if (installed <= 0) return false
        val available = ntkKnownOrAvailableGeneratedCountForAdjacent(manga, installed)
        if (
            isCurrentEpisodeCompleteForImmediateAdjacentStream(
                target,
                ReaderSurfaceView.DIRECTION_NEXT,
            )
        ) {
            maybeLogAdjacentCurrentGate(
                "append_adjacent_runway_allow_current_complete",
                target,
                "installed=$installed,available=$available,target=${target.ntkEpisodePath}"
            )
            return false
        }
        if (isNtkContinuousAdjacentCompletionPolicyActive()) {
            requestAllUndeliveredNtkPages("current_complete_before_next")
            maybeLogAdjacentCurrentGate(
                "append_adjacent_runway_defer_current_incomplete",
                target,
                "installed=$installed,available=$available,target=${target.ntkEpisodePath}"
            )
            return true
        }
        val anchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?: currentStartPage()
        val tailReady = isCurrentGeneratedTailReadyForAdjacent(manga, anchor, installed)
        if (available > installed) {
            maybeExpandCurrentNtkInstallForAdjacent(manga, anchor)
            if (tailReady) {
                maybeLogAdjacentCurrentGate(
                    "append_adjacent_runway_allow_current_tail_ready",
                    target,
                    "installed=$installed,available=$available,target=${target.ntkEpisodePath},anchor=$anchor"
                )
                return false
            }
            requestAllUndeliveredNtkPages("current_full_before_next")
            maybeLogAdjacentCurrentGate(
                "append_adjacent_runway_defer_current_tail",
                target,
                "installed=$installed,available=$available,target=${target.ntkEpisodePath},anchor=$anchor"
            )
            return true
        }
        if (tailReady) return false
        requestAllUndeliveredNtkPages("current_ready_before_next")
        maybeLogAdjacentCurrentGate(
            "append_adjacent_runway_defer_current_ready",
            target,
            "tailReady=false,installed=$installed,available=$available," +
                "target=${target.ntkEpisodePath},anchor=$anchor"
        )
        return true
    }

    private fun currentGeneratedReadyRequiredBeforeAdjacent(installed: Int, available: Int): Int {
        if (installed <= 0) return 0
        val known = available.takeIf { it > 0 } ?: installed
        return minOf(installed, known).coerceAtLeast(NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)
    }

    private fun currentGeneratedReadyPrefixForAdjacent(source: Manga, limit: Int): Int {
        if (limit <= 0) return 0
        return synchronized(pagesLock) {
            var ready = 0
            for ((index, page) in pages.withIndex()) {
                if (page.transitionTitle != null) continue
                if (!looseSameEpisodeForAppend(page.manga, source)) continue
                if (!hasDeliveredOrPendingDrawable(index) && !hasListenerDrawableDelivery(index, page)) {
                    return@synchronized ready
                }
                ready++
                if (ready >= limit) return@synchronized ready
            }
            ready
        }
    }

    private fun isCurrentGeneratedTailReadyForAdjacent(source: Manga, anchor: Int, installed: Int): Boolean {
        if (installed <= 0) return false
        return synchronized(pagesLock) {
            if (isInstalledGeneratedTailDrawableForAdjacentLocked(source, anchor)) {
                return@synchronized true
            }
            val indexes = pages.withIndex()
                .filter { item ->
                    item.value.transitionTitle == null &&
                        looseSameEpisodeForAppend(item.value.manga, source)
                }
                .map { it.index }
            if (indexes.isEmpty()) return@synchronized false
            val tailEndIndex = indexes.last()
            if (anchor >= tailEndIndex) {
                val tailPage = pages.getOrNull(tailEndIndex) ?: return@synchronized false
                if (hasDeliveredOrPendingDrawable(tailEndIndex) || hasListenerDrawableDelivery(tailEndIndex, tailPage)) {
                    return@synchronized true
                }
            }
            val tailStartPosition = (indexes.size - NTK_APPEND_CURRENT_TAIL_BOUNDARY_PAGES).coerceAtLeast(0)
            val tailStartIndex = indexes.getOrNull(tailStartPosition) ?: return@synchronized false
            if (anchor < tailStartIndex) return@synchronized false
            for (position in tailStartPosition until indexes.size) {
                val index = indexes[position]
                val page = pages.getOrNull(index) ?: return@synchronized false
                if (!hasDeliveredOrPendingDrawable(index) && !hasListenerDrawableDelivery(index, page)) {
                    return@synchronized false
                }
            }
            true
        }
    }

    private fun isInstalledGeneratedTailDrawableForAdjacentLocked(source: Manga, anchor: Int): Boolean {
        var tailEndIndex = -1
        for ((index, page) in pages.withIndex()) {
            if (page.transitionTitle != null) continue
            if (!looseSameEpisodeForAppend(page.manga, source)) continue
            tailEndIndex = index
        }
        if (tailEndIndex < 0 || anchor < tailEndIndex) return false
        val tailPage = pages.getOrNull(tailEndIndex) ?: return false
        return hasDeliveredOrPendingDrawable(tailEndIndex) ||
            hasListenerDrawableDelivery(tailEndIndex, tailPage)
    }

    private fun initialAdjacentRunwayAppendRetryDelayMs(target: Manga): Long {
        val baseDelayMs = maxOf(
            initialAdjacentRunwayAppendDelayMs(),
            NTK_GENERATED_APPEND_NOTIFY_NEAR_READY_POLL_MS
        )
        if (!isImmediateNtkGeneratedUx()) return baseDelayMs
        if (!isNtkSource(manga, title)) return baseDelayMs
        if (!isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) return baseDelayMs
        if (Manga.sameEpisodeIdentity(manga, target)) return baseDelayMs
        val installed = installedDrawablePageCountForEpisode(manga)
        if (installed <= 0) return baseDelayMs
        val available = ntkKnownOrAvailableGeneratedCountForAdjacent(manga, installed)
        val anchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?: currentStartPage()
        val tailReady = isCurrentGeneratedTailReadyForAdjacent(manga, anchor, installed)
        if (available > installed && !tailReady) return maxOf(baseDelayMs, NTK_ADJACENT_CURRENT_INSTALL_RECHECK_MS)
        if (!tailReady) {
            return maxOf(baseDelayMs, NTK_ADJACENT_CURRENT_INSTALL_RECHECK_MS)
        }
        if (isActiveGeneratedTouchOrQuiet() || viewportBusy.get()) {
            return maxOf(baseDelayMs, NTK_ADJACENT_FOREGROUND_STREAM_RECHECK_MS)
        }
        return baseDelayMs
    }

    private fun appendResolvedEpisodeInitialRunway(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String,
        warm: Boolean
    ): Boolean {
        if (!isImmediateNtkGeneratedUx() || !isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        if (isAdjacentStrictRecoveryExhausted(target)) {
            clearActiveRemainingAdjacentRunwayTarget(target)
            clearPendingAdjacentAppendPublish(publishKey)
            return true
        }
        if (shouldDeferAdjacentRunwayBehindActiveRemaining(target)) {
            scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
            Log.d(
                TAG,
                "append_adjacent_runway_defer_active_remaining targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} active=${activeRemainingAdjacentRunwayTargetPaths.size}"
            )
            return true
        }
        if (shouldDeferAdjacentRunwayForCurrentGeneratedTail(target)) {
            scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
            return true
        }
        // Freeze the live exact cohort decision for this append turn. Every failure below remains
        // on the strict retry path; it must never escape to a generic cache/network publisher.
        val strictExactAuthority = strictExactInitialManhwaRunwayAuthority(target)
        if (requiresStrictExactInitialManhwaRunway(target) && strictExactAuthority == null) {
            // Exact discovery/claim installation is asynchronous.  Do not let a generic cached
            // p0 publish in that interval: it would own the page table without the strict tail
            // waiter that turns resident p1-p3 bodies into drawables.
            scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
            Log.d(
                TAG,
                "append_adjacent_exact_manhwa_wait_authority path=${target.ntkEpisodePath}",
            )
            return true
        }
        // Revalidate the live registry immediately before runway admission. If the generation was
        // retired after the first claim snapshot, remain on the strict retry path instead of
        // reclassifying the same immutable refs as generic-cache candidates.
        val strictExactDescriptorOnly =
            strictExactInitialManhwaRunwayAuthority(target) != null
        if (strictExactAuthority != null && !strictExactDescriptorOnly) {
            scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
            return true
        }
        val runwayCount = initialAdjacentAppendRunwayRefCount(
            refs,
            strictExactDescriptorOnly,
        )
        if (runwayCount <= 0) {
            if (!strictExactDescriptorOnly) return false
            holdOrRecoverAdjacentStrictSource(target)
            if (!isAdjacentStrictRecoveryExhausted(target)) {
                scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
            } else {
                clearPendingAdjacentAppendPublish(publishKey)
            }
            return true
        }
        val insertDelayMs = initialAdjacentRunwayAppendDelayMs()
        if (insertDelayMs > 0L) {
            scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
            Log.d(
                TAG,
                "append_adjacent_runway_insert_defer targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} delayMs=$insertDelayMs runway=$runwayCount total=${refs.size}"
            )
            return true
        }
        val runwayRefs = refs.take(runwayCount)
        val readyRunwayCount = adjacentRunwayPublishablePrefixCount(runwayRefs)
        val exactP0Shape = isDirectWifiAdjacentExactP0HeadCandidate(target, runwayRefs)
        if (exactP0Shape) {
            runwayRefs.firstOrNull { it.transitionTitle != null }
                ?.transitionTitle
                ?.let(listener::onPageCardPreparationRequested)
            val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
            if (shouldLogRateLimitedDiagnostic("append_adjacent_exact_p0_candidate|$path")) {
                val p0 = runwayRefs.getOrNull(1)
                val claim = adjacentStrictSourceClaims[path]
                val descriptorReady = p0?.let(::strictAdjacentBodyDescriptor) != null
                // A resident descriptor is already the authoritative body source used below. Do
                // not re-open proof sidecars and parse the encoded file header merely to populate
                // a debug field; that diagnostic disk path sat directly between p0 EOF and visible
                // decode.
                val publishedFallbackReady = !descriptorReady &&
                    p0?.let(::strictAdjacentPublishedBody) != null
                Log.d(
                    TAG,
                    "append_adjacent_exact_p0_candidate path=$path ready=$readyRunwayCount " +
                        "required=${runwayRefs.size} refs=${runwayRefs.size}/${refs.size} " +
                        "descriptor=$descriptorReady publishedFallback=$publishedFallbackReady " +
                        "claim=${claim != null} " +
                        "claimLive=${claim?.let { isAdjacentStrictSourceClaimLive(path, it) } == true}",
                )
            }
        }
        // Never expose a partial publication unit. Direct Wi-Fi deliberately defines that unit as
        // transition+p0; its remaining three runway pages use the ordered remainder publisher.
        val minimumReadyRunwayCount = runwayRefs.size
        if (readyRunwayCount < minimumReadyRunwayCount) {
            if (strictExactDescriptorOnly) {
                holdOrRecoverAdjacentStrictSource(target)
                if (!isAdjacentStrictRecoveryExhausted(target)) {
                    scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
                } else {
                    clearPendingAdjacentAppendPublish(publishKey)
                }
                return true
            }
            if (holdOrRecoverAdjacentStrictSource(target)) {
                if (exactP0Shape) {
                    Log.d(
                        TAG,
                        "append_adjacent_exact_p0_wait_ready path=${target.ntkEpisodePath} " +
                            "ready=$readyRunwayCount required=$minimumReadyRunwayCount strictOwned=true",
                    )
                }
                if (!isAdjacentStrictRecoveryExhausted(target)) {
                    scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
                } else {
                    clearPendingAdjacentAppendPublish(publishKey)
                }
                return true
            }
            if (!strictExactDescriptorOnly) {
                startAdjacentForegroundStreamsForRefs(
                    target,
                    refs,
                    ReaderSurfaceView.DIRECTION_NEXT,
                    asyncLaunch = true
                )
            }
            scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
            Log.d(
                TAG,
                "append_adjacent_runway_wait_ready targetId=${target.id} path=${target.ntkEpisodePath} " +
                    "ready=$readyRunwayCount required=$minimumReadyRunwayCount runway=$runwayCount total=${refs.size}"
            )
            return true
        }
        val initialRefs = runwayRefs
        val remainingRefs = refs.drop(runwayCount)
        if (shouldDeferDirectWifiAdjacentStructurePublication(target)) {
            // The exact body may reach EOF during the gesture that is consuming the predecessor.
            // Keep it privately resident and retry from the physical idle edge; publishing here
            // would invalidate the native producer scene for several visible frames.
            scheduleInitialAdjacentRunwayAppendRetry(
                target,
                refs,
                publishKey,
                warm,
                forceDelayedPolling = true,
            )
            if (shouldLogRateLimitedDiagnostic(
                    "adjacent_initial_structure_deferred_motion|${target.ntkEpisodePath}",
                )
            ) {
                Log.d(
                    TAG,
                    "append_adjacent_initial_structure_deferred_motion path=${target.ntkEpisodePath}",
                )
            }
            return true
        }
        // A completion-idle flight and a boundary-demand flight may join the same exact manifest.
        // Recheck structure before any decode: the first flight can publish transition+p0 while
        // the second is still leaving its metadata task. The final in-lock duplicate fence below
        // remains authoritative for the narrow race after this fast path.
        val existingPageCount = synchronized(pagesLock) {
            pages.size.takeIf { containsEpisodeForAppendLocked(target) } ?: -1
        }
        if (existingPageCount >= 0) {
            clearPendingAdjacentAppendPublish(publishKey)
            Log.d(
                TAG,
                "append_adjacent_runway_duplicate_before_decode targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} pages=$existingPageCount",
            )
            return true
        }
        if (!isForwardAdjacentStructurePublicationCandidateCurrent(target)) {
            clearPendingAdjacentAppendPublish(publishKey)
            Log.d(
                TAG,
                "append_adjacent_runway_stale_target_before_decode targetId=${target.id} " +
                    "path=${target.ntkEpisodePath}",
            )
            return true
        }
        val cardOffset = initialRefs.indexOfFirst { it.transitionTitle != null }
        val transitionTitle = initialRefs.getOrNull(cardOffset)?.transitionTitle ?: ""
        data class AdjacentPlacement(
            val predictedStart: Int,
            val predecessorIsLaunchEpisode: Boolean,
            val predecessorHasPhysicalEntryProof: Boolean,
            val physicalForwardEdge: Int,
        )
        val adjacentPlacement = synchronized(pagesLock) {
            val predecessor = pages.asReversed().firstOrNull { page ->
                page.transitionTitle == null
            }
            val boundedAnchor = if (pages.isEmpty()) {
                -1
            } else {
                currentViewportAnchor.get().coerceIn(0, pages.lastIndex)
            }
            val physicalForwardEdge = if (boundedAnchor < 0) {
                boundedAnchor
            } else {
                reportedPhysicalWindowLocked(
                    fallbackAnchor = boundedAnchor,
                    fallbackFirst = boundedAnchor,
                    fallbackLast = boundedAnchor,
                ).last
            }
            val physicalWindow = if (boundedAnchor < 0) {
                IntRange.EMPTY
            } else {
                reportedPhysicalWindowLocked(
                    fallbackAnchor = boundedAnchor,
                    fallbackFirst = boundedAnchor,
                    fallbackLast = boundedAnchor,
                )
            }
            val predecessorHasPhysicalEntryProof = predecessor?.manga?.let { episode ->
                physicalWindow.any { index ->
                    val physicalPage = pages.getOrNull(index) ?: return@any false
                    physicalPage.transitionTitle == null &&
                        Manga.sameEpisodeIdentity(physicalPage.manga, episode) &&
                        listener.isPageDrawableInstalled(index)
                }
            } == true
            AdjacentPlacement(
                predictedStart = pages.size,
                predecessorIsLaunchEpisode = predecessor?.manga?.let { episode ->
                    Manga.sameEpisodeIdentity(episode, manga)
                } == true,
                predecessorHasPhysicalEntryProof = predecessorHasPhysicalEntryProof,
                physicalForwardEdge = maxOf(boundedAnchor, physicalForwardEdge),
            )
        }
        val predictedStart = adjacentPlacement.predictedStart
        val predecessorIsLaunchEpisode = adjacentPlacement.predecessorIsLaunchEpisode
        val physicalForwardEdge = adjacentPlacement.physicalForwardEdge
        if (HostExactHardwareTilePoolPressurePolicy.shouldDeferOffscreenAdjacentRunwayDecode(
                hostGpuRuntime = hostGpuEmulatorRuntime,
                directWifiStrictAdjacent = isDirectWifiStrictAdjacentRunwayProfile(target),
                predecessorIsLaunchEpisode = predecessorIsLaunchEpisode,
                predecessorHasPhysicalEntryProof =
                    adjacentPlacement.predecessorHasPhysicalEntryProof,
                viewportAnchor = physicalForwardEdge,
                adjacentStart = predictedStart,
                nearBoundaryPages = NTK_APPEND_WARM_BOUNDARY_PAGES,
            )
        ) {
            // Keep exact discovery and its encoded bodies warm, but do not let a far-future wide
            // chapter consume pooled HardwareBuffers and evict the chapter under the finger. The
            // bounded poll is re-evaluated against real Surface window reports and begins the
            // unchanged atomic runway decode four display pages before the boundary.
            scheduleInitialAdjacentRunwayAppendRetry(
                target,
                refs,
                publishKey,
                warm,
                forceDelayedPolling = true,
            )
            if (shouldLogRateLimitedDiagnostic(
                    "adjacent_runway_offscreen_decode_defer|${target.ntkEpisodePath}",
                )
            ) {
                Log.d(
                    TAG,
                    "append_adjacent_runway_offscreen_decode_defer targetId=${target.id} " +
                        "path=${target.ntkEpisodePath} start=$predictedStart " +
                        "physicalForwardEdge=$physicalForwardEdge " +
                        "predecessorLaunch=$predecessorIsLaunchEpisode " +
                        "predecessorEntered=${adjacentPlacement.predecessorHasPhysicalEntryProof}",
                )
            }
            return true
        }
        if (exactP0Shape) {
            val exactPath = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
            if (!adjacentExactP0PreparePaths.add(exactPath)) {
                // The in-flight owner publishes on success and schedules the one delayed retry on
                // failure. Registering another resident-body wake here observes an already-true
                // descriptor immediately and recursively re-enters this branch; one p0 copy then
                // generated hundreds of 1 ms join turns on the renderer's host cores. Joining is
                // deliberately passive and identity-bound to the existing path owner.
                if (shouldLogRateLimitedDiagnostic("adjacent_exact_p0_prepare_join|$exactPath")) {
                    Log.d(
                        TAG,
                        "append_adjacent_exact_p0_prepare_join path=$exactPath",
                    )
                }
                return true
            }
            try {
                val flight = prepareDirectWifiAdjacentExactP0Head(target, initialRefs)
                if (flight == null) {
                    Log.d(
                        TAG,
                        "append_adjacent_exact_p0_prepare_deferred path=${target.ntkEpisodePath}",
                    )
                    startAdjacentForegroundStreamsForRefs(
                        target,
                        initialRefs,
                        ReaderSurfaceView.DIRECTION_NEXT,
                        asyncLaunch = true,
                    )
                    // The descriptor event that brought us here may remain resident after a
                    // transient lease/decode failure. Re-registering that already-true event
                    // would synchronously wake the same append again and spin the runway
                    // executor. Re-evaluate from one bounded timer edge instead.
                    scheduleInitialAdjacentRunwayAppendRetry(
                        target,
                        refs,
                        publishKey,
                        warm,
                        forceDelayedPolling = true,
                    )
                    return true
                }
                return publishDirectWifiAdjacentExactP0Head(
                    target = target,
                    allRefs = refs,
                    initialRefs = initialRefs,
                    remainingRefs = remainingRefs,
                    publishKey = publishKey,
                    warm = warm,
                    cardOffset = cardOffset,
                    transitionTitle = transitionTitle,
                    flight = flight,
                )
            } finally {
                check(adjacentExactP0PreparePaths.remove(exactPath))
            }
        }
        var preparedBatch = takePreparedInitialAdjacentRunwayBatch(
            target,
            predictedStart,
            initialRefs,
        )
        val targetPath = target.ntkEpisodePath?.trim().orEmpty()
        var appendDecodePreparation: InitialAdjacentRunwayPreparation? = null
        while (preparedBatch == null && appendDecodePreparation == null) {
            val activePreparation = preparingInitialAdjacentRunways[targetPath]
            if (activePreparation != null) {
                val nowMs = SystemClock.elapsedRealtime()
                if (NtkAdjacentRunwayPreparationPolicy.shouldJoin(activePreparation.startedAtMs, nowMs)) {
                    // p0 can already be resident while the metadata owner is still dropping its
                    // preparation key. Registering the same resident-body event here wakes
                    // immediately and can spin several runway workers until that key disappears.
                    // The preparation is already in progress, so one bounded delayed recheck is
                    // the only useful successor owner.
                    scheduleInitialAdjacentRunwayAppendRetry(
                        target,
                        refs,
                        publishKey,
                        warm,
                        waitForPreparation = activePreparation,
                    )
                    Log.d(
                        TAG,
                        "append_adjacent_runway_join_prefetch targetId=${target.id} " +
                            "path=${target.ntkEpisodePath} runway=${initialRefs.size} " +
                            "ageMs=${nowMs - activePreparation.startedAtMs}"
                    )
                    return true
                }
                if (finishInitialAdjacentRunwayPreparation(targetPath, activePreparation)) {
                    Log.d(
                        TAG,
                        "append_adjacent_runway_prefetch_join_expired targetId=${target.id} " +
                            "path=${target.ntkEpisodePath} runway=${initialRefs.size} " +
                            "ageMs=${nowMs - activePreparation.startedAtMs}"
                    )
                }
                continue
            }
            val candidate = InitialAdjacentRunwayPreparation(
                token = Any(),
                startedAtMs = SystemClock.elapsedRealtime(),
            )
            if (preparingInitialAdjacentRunways.putIfAbsent(targetPath, candidate) != null) {
                continue
            }
            appendDecodePreparation = candidate
            // Close the publication-before-claim race: a prefetch owner publishes its batch before
            // dropping the preparation key. If that happened after our first take, consume the
            // batch now instead of decoding the same exact runway again.
            val racedPreparedBatch = takePreparedInitialAdjacentRunwayBatch(
                target,
                predictedStart,
                initialRefs,
            )
            preparedBatch = if (strictExactDescriptorOnly) {
                racedPreparedBatch?.also(::recycleAdjacentRunwayDrawableBatch)
                null
            } else {
                racedPreparedBatch
            }
        }
        try {
            if (preparedBatch == null) {
                preparedBatch = prepareAdjacentRunwayDrawableBatch(
                    predictedStart,
                    initialRefs,
                    "append_initial_runway_prepare_before_publish",
                    requireStrictDescriptor = strictExactDescriptorOnly,
                )
            }
            if (preparedBatch == null) {
                if (!strictExactDescriptorOnly) {
                    startAdjacentForegroundStreamsForRefs(
                        target,
                        initialRefs,
                        ReaderSurfaceView.DIRECTION_NEXT,
                        asyncLaunch = true
                    )
                }
                if (!strictExactDescriptorOnly || !isAdjacentStrictRecoveryExhausted(target)) {
                    scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
                } else {
                    clearPendingAdjacentAppendPublish(publishKey)
                }
                Log.d(
                    TAG,
                    "append_adjacent_runway_wait_drawable_batch targetId=${target.id} " +
                        "path=${target.ntkEpisodePath} runway=${initialRefs.size}"
                )
                return true
            }
            val readyBatch = preparedBatch
            if (shouldDeferDirectWifiAdjacentStructurePublication(target)) {
                // Motion can begin while a file decode that was admitted at idle is finishing.
                // The batch owns no public structure yet, so release it and let the sealed exact
                // source be decoded again at the next idle edge instead of mutating the scene.
                recycleAdjacentRunwayDrawableBatch(readyBatch)
                preparedBatch = null
                scheduleInitialAdjacentRunwayAppendRetry(
                    target,
                    refs,
                    publishKey,
                    warm,
                    forceDelayedPolling = true,
                )
                if (shouldLogRateLimitedDiagnostic(
                        "adjacent_initial_decoded_batch_deferred_motion|${target.ntkEpisodePath}",
                    )
                ) {
                    Log.d(
                        TAG,
                        "append_adjacent_initial_decoded_batch_deferred_motion " +
                            "path=${target.ntkEpisodePath}",
                    )
                }
                return true
            }
            val cardIndex: Int
            val total: Int
            val drawablePublication: AdjacentDrawableBatchPublication
            val publishCompleteExactStructure =
                isDirectWifiStrictAdjacentRunwayProfile(target) &&
                    exactViewerApiAdjacentAuthority(target) != null &&
                    isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)
            val structureRefs = if (publishCompleteExactStructure) refs else initialRefs
            var structurePublishOwner: AtomicBoolean? = null
            val pageReferenceSnapshot = synchronized(pagesLock) { pages.toList() }
            val skipOutOfOrder = shouldSkipForwardNtkOutOfOrderAppend(
                target,
                pageReferenceSnapshot,
            )
            val directWifiTransportActive =
                !strictExactDescriptorOnly || isDirectWifiStrictAdjacentTransportActive()
            val structurePublicationContext =
                prepareForwardAdjacentStructurePublication(target)
            synchronized(pagesLock) {
                if (!pageReferenceSnapshotStillCurrentLocked(pageReferenceSnapshot)) {
                    recycleAdjacentRunwayDrawableBatch(readyBatch)
                    scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
                    return true
                }
                if (!directWifiTransportActive) {
                    recycleAdjacentRunwayDrawableBatch(readyBatch)
                    scheduleInitialAdjacentRunwayAppendRetry(target, refs, publishKey, warm)
                    return true
                }
                if (skipOutOfOrder) {
                    Log.d(
                        TAG,
                        "append_adjacent_runway_skip_out_of_order targetId=${target.id} " +
                            "path=${target.ntkEpisodePath} pages=${pages.size}"
                    )
                    recycleAdjacentRunwayDrawableBatch(readyBatch)
                    clearPendingAdjacentAppendPublish(publishKey)
                    return true
                }
                if (containsEpisodeForAppendLocked(target)) {
                    Log.d(
                        TAG,
                        "append_adjacent_runway_duplicate targetId=${target.id} " +
                            "path=${target.ntkEpisodePath} pages=${pages.size}"
                    )
                    recycleAdjacentRunwayDrawableBatch(readyBatch)
                    clearPendingAdjacentAppendPublish(publishKey)
                    return true
                }
                if (structurePublicationContext == null ||
                    !claimForwardAdjacentStructurePublication(target, structurePublicationContext)
                ) {
                    recycleAdjacentRunwayDrawableBatch(readyBatch)
                    clearPendingAdjacentAppendPublish(publishKey)
                    return true
                }
                if (publishKey.isNotEmpty()) pendingAdjacentAppendPublishKeys.add(publishKey)
                structurePublishOwner = beginOwnedStructurePublish()
                drawablePublication = beginAdjacentDrawableBatchPublication(initialRefs)
                cardIndex = pages.size
                structureRefs.forEachIndexed { offset, page -> page.pageIndex = cardIndex + offset }
                pages.addAll(structureRefs)
                total = pages.size
                capturePublishedPageIndexLocked()
            }
            clearPageStateFromIndex(cardIndex, appendOnlyTail = true)
            val drawableBatch = rebindAdjacentRunwayDrawableBatch(readyBatch, cardIndex, initialRefs)
            if (remainingRefs.isNotEmpty()) {
                startAdjacentForegroundStreamsForRefs(
                    target,
                    remainingRefs,
                    ReaderSurfaceView.DIRECTION_NEXT,
                    asyncLaunch = true
                )
            }
            Log.d(
                TAG,
                "append_adjacent_runway_inserted targetId=${target.id} path=${target.ntkEpisodePath} " +
                    "runway=${initialRefs.size} ready=$readyRunwayCount " +
                    "remaining=${remainingRefs.size} total=$total"
            )
            val posted = main.post {
                try {
                    if (cancelled.get()) {
                        recycleAdjacentRunwayDrawableBatch(drawableBatch)
                        clearPendingAdjacentAppendPublish(publishKey)
                        return@post
                    }
                    if (shouldDeferDirectWifiAdjacentStructurePublication(target)) {
                        // ReaderSession has claimed only private structure at this point; the
                        // Activity/Surface has not observed it. Roll it back before publication so
                        // a DOWN racing this main-loop turn retains the old native scene exactly.
                        rollbackAdjacentRunwayStructure(cardIndex, structureRefs)
                        recycleAdjacentRunwayDrawableBatch(drawableBatch)
                        clearPendingAdjacentAppendPublish(publishKey)
                        scheduleInitialAdjacentRunwayAppendRetry(
                            target,
                            refs,
                            publishKey,
                            warm,
                            forceDelayedPolling = true,
                        )
                        if (shouldLogRateLimitedDiagnostic(
                                "adjacent_initial_main_publish_deferred_motion|${target.ntkEpisodePath}",
                            )
                        ) {
                            Log.d(
                                TAG,
                                "append_adjacent_initial_main_publish_deferred_motion " +
                                    "path=${target.ntkEpisodePath}",
                            )
                        }
                        return@post
                    }
                    // Publish the complete page table before any decoded callback reaches the
                    // Activity. A callback for an index beyond ReaderSurfaceView's old count is
                    // otherwise parked as a partial "ready runway" and can expose an intermediate
                    // count (for example 37 -> 38 -> 45). Keeping the structure expansion and all
                    // drawable installs in this one main-loop turn makes the append atomic to draw.
                    finishOwnedStructurePublish(structurePublishOwner)
                    listener.onPreparedAdjacentPagesAppended(total)
                    if (cardOffset >= 0) listener.onPageCard(cardIndex + cardOffset, transitionTitle)
                    commitAdjacentRunwayDrawableBatch(drawableBatch)
                    markExactAdjacentRunwayTelemetryIfReady(
                        target,
                        refs.count { it.transitionTitle == null },
                    )
                    if (warm && shouldWarmAppendedEpisode(cardIndex)) {
                        warmAppendedVisibleRunway(cardIndex, total, "append_initial_runway")
                    }
                    scheduleAppendSourcePrefetchAfterQuiet(
                        cardIndex + generatedAppendVisibleRunwayPageLimit(target),
                        total,
                        "append_initial_runway_source"
                    )
                    if (publishCompleteExactStructure) {
                        NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
                            .takeIf(String::isNotEmpty)
                            ?.let { path ->
                                publishedExactOffscreenRunwayPaths.add(path)
                                requestPublishedExactAdjacentInitialRunwayCompletion(path)
                            }
                        warmPublishedLaunchSuccessorInitialTail(
                            target = target,
                            allRefs = refs,
                            firstPublishedIndex = cardIndex,
                        )
                        clearActiveRemainingAdjacentRunwayTarget(target)
                        clearPendingAdjacentAppendPublish(publishKey)
                    } else if (!tryHandoffDirectWifiAdjacentInitialRunwayTail(
                            target,
                            remainingRefs,
                            publishKey,
                            warm,
                        )
                    ) {
                        scheduleRemainingAdjacentRunwayAppend(target, remainingRefs, publishKey, warm)
                    }
                } finally {
                    finishOwnedStructurePublish(structurePublishOwner)
                    finishAdjacentDrawableBatchPublication(drawablePublication)
                }
            }
            if (!posted) {
                rollbackAdjacentRunwayStructure(cardIndex, structureRefs)
                recycleAdjacentRunwayDrawableBatch(drawableBatch)
                clearPendingAdjacentAppendPublish(publishKey)
                finishOwnedStructurePublish(structurePublishOwner)
                finishAdjacentDrawableBatchPublication(drawablePublication)
            }
            return true
        } finally {
            appendDecodePreparation?.let { preparation ->
                finishInitialAdjacentRunwayPreparation(targetPath, preparation)
            }
        }
    }

    private fun scheduleInitialAdjacentRunwayAppendRetry(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String,
        warm: Boolean,
        forceDelayedPolling: Boolean = false,
        waitForPreparation: InitialAdjacentRunwayPreparation? = null,
    ) {
        val retryKey = publishKey.ifEmpty { episodeAppendKey(target) }
        if (cancelled.get()) {
            clearPendingAdjacentAppendPublish(publishKey)
            if (retryKey.isNotEmpty()) scheduledInitialAdjacentRunwayRetryKeys.remove(retryKey)
            return
        }
        if (publishKey.isNotEmpty()) pendingAdjacentAppendPublishKeys.add(publishKey)
        if (retryKey.isNotEmpty() && !scheduledInitialAdjacentRunwayRetryKeys.add(retryKey)) {
            return
        }
        val exactP0WakePath = initialAdjacentExactP0WakePath(target, refs)
        val exactWakeRegistry = if (exactP0WakePath.startsWith("/manhwa/")) {
            waitingInitialAdjacentManhwaRunwayAppends
        } else {
            waitingInitialAdjacentExactP0Appends
        }
        var exactP0WakeKey = ""
        val retryStarted = AtomicBoolean(false)
        lateinit var retry: Runnable
        retry = Runnable {
            if (!retryStarted.compareAndSet(false, true)) return@Runnable
            if (exactP0WakePath.isNotEmpty()) {
                parkedInitialAdjacentRunwayRetries.remove(exactP0WakePath, retry)
                if (retryKey.isNotEmpty()) {
                    parkedInitialAdjacentRunwayPathsByRetryKey.remove(retryKey, exactP0WakePath)
                }
            }
            main.removeCallbacks(retry)
            if (exactP0WakeKey.isNotEmpty()) {
                exactWakeRegistry.unregister(exactP0WakeKey, retry)
            }
            val directWebtoonEventWake = exactP0WakeKey.isNotEmpty() &&
                initialAdjacentWebtoonP0EventWakeLane.get() == true
            val directManhwaEventWake = exactP0WakeKey.isNotEmpty() &&
                initialAdjacentManhwaRunwayEventWakeKeys.remove(exactP0WakeKey)
            if (retryKey.isNotEmpty()) scheduledInitialAdjacentRunwayRetryKeys.remove(retryKey)
            if (cancelled.get()) {
                clearPendingAdjacentAppendPublish(publishKey)
                return@Runnable
            }
            try {
                val retryExecutor = if (
                    isImmediateNtkGeneratedUx() &&
                    isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)
                ) {
                    adjacentNetwork
                } else {
                    control
                }
                val appendWork = Runnable {
                    if (!appendResolvedEpisodeInitialRunway(target, refs, publishKey, warm)) {
                        appendResolvedEpisode(
                            target,
                            refs.mapNotNull { it.image },
                            ReaderSurfaceView.DIRECTION_NEXT,
                            warm
                        )
                    }
                }
                if (directWebtoonEventWake || directManhwaEventWake) {
                    // Both exact resident-body registries dispatch their authoritative completion
                    // on the dedicated runway executor. Avoid a second background queue hop;
                    // structure and drawable publication still cross the unchanged atomic main
                    // callback. The webtoon marker is host-emulator-only, so physical Wi-Fi and
                    // cellular/SNI retain their original executor path.
                    appendWork.run()
                } else {
                    retryExecutor.execute(appendWork)
                }
            } catch (_: RejectedExecutionException) {
                clearPendingAdjacentAppendPublish(publishKey)
                if (retryKey.isNotEmpty()) scheduledInitialAdjacentRunwayRetryKeys.remove(retryKey)
            }
        }
        // Preserve the legacy listener-vs-poll selection for every transport. Only the event-wake
        // registry below is scoped to the direct-Wi-Fi exact-p0 candidate.
        val strictAdjacentAuthority = exactViewerApiAdjacentAuthority(target)
        val strictAdjacentAuthorityReady = strictAdjacentAuthority != null
        val exactP0WakeAuthority = strictAdjacentAuthority?.takeIf {
            exactP0WakePath.isNotEmpty() && !forceDelayedPolling && waitForPreparation == null
        }
        if (exactP0WakeAuthority != null) {
            val authority = exactP0WakeAuthority
            exactP0WakeKey = adjacentExactP0WakeKey(
                exactP0WakePath,
                authority.seal.digestSha256,
            )
            if (exactWakeRegistry.register(
                    exactP0WakeKey,
                    retry,
                    initialAdjacentRunwayAppendRetryDelayMs(target),
                )
            ) {
                // Close registration-vs-callback ordering: if p0 became resident immediately
                // before putIfAbsent, consume the already-published descriptor as the same event.
                val descriptorKey = adjacentStrictBodyDescriptorKey(
                    exactP0WakePath,
                    authority.seal.digestSha256,
                    0,
                )
                if (adjacentStrictBodyDescriptors.containsKey(descriptorKey)) {
                    wakeInitialAdjacentExactP0Append(
                        exactP0WakePath,
                        authority.seal.digestSha256,
                        0,
                    )
                    wakeInitialAdjacentManhwaRunwayAppend(
                        exactP0WakePath,
                        authority.seal.digestSha256,
                        0,
                        authority.seal.pageCount,
                    )
                }
            }
        }
        val listenerRegistered = if (
            !strictAdjacentAuthorityReady &&
            isImmediateNtkGeneratedUx() &&
            isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)
        ) {
            val runwayCount = initialAdjacentAppendRunwayRefCount(refs)
            refs.take(runwayCount)
                .asSequence()
                .filter { it.transitionTitle == null }
                .filter { ref ->
                    val image = ref.image.orEmpty()
                    image.isNotEmpty() && ReaderImageCache.cachedFile(appContext, target, image) == null
                }
                .map { ref ->
                    ReaderImageCache.runWhenNtkInitialGeneratedAssetReady(
                        appContext,
                        target,
                        ref.image.orEmpty(),
                        retry
                    )
                }
                .any { it }
        } else {
            false
        }
        if (waitForPreparation != null) {
            // Join the one generation-specific preparation edge. A single deadline callback is
            // retained only to expire a genuinely wedged owner; normal completion removes it and
            // retries immediately. This replaces the former 32 ms recursive poll that could run
            // hundreds of append/actor turns while p0 was already resident.
            val remainingJoinMs = (
                waitForPreparation.startedAtMs + NtkAdjacentRunwayPreparationPolicy.MAX_JOIN_MS -
                    SystemClock.elapsedRealtime()
                ).coerceAtLeast(1L)
            main.postDelayed(retry, remainingJoinMs)
            waitForPreparation.completion.whenComplete { _, _ ->
                main.removeCallbacks(retry)
                retry.run()
            }
        } else if (forceDelayedPolling) {
            // Direct exact p0 is already resident. Only physical quiet/viewport movement can make
            // structure publication legal now, so park one owner on that event instead of polling
            // the same descriptor from several executor lanes every 32-128 ms. A long watchdog is
            // liveness insurance for a lost Android lifecycle edge, not the normal wake path.
            if (exactP0WakePath.isNotEmpty() && strictAdjacentAuthorityReady) {
                parkedInitialAdjacentRunwayRetries[exactP0WakePath] = retry
                if (retryKey.isNotEmpty()) {
                    parkedInitialAdjacentRunwayPathsByRetryKey[retryKey] = exactP0WakePath
                }
                val posted = main.postDelayed(
                    retry,
                    NTK_INITIAL_ADJACENT_EVENT_WAIT_WATCHDOG_MS,
                )
                if (!posted) {
                    parkedInitialAdjacentRunwayRetries.remove(exactP0WakePath, retry)
                    if (retryKey.isNotEmpty()) {
                        parkedInitialAdjacentRunwayPathsByRetryKey.remove(
                            retryKey,
                            exactP0WakePath,
                        )
                    }
                    retry.run()
                } else if (!viewportBusy.get() &&
                    physicalTouchQuietRemainingMs(
                        NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS,
                    ) > 0L
                ) {
                    // Close the worker-vs-UP race once. A fully quiet offscreen park deliberately
                    // waits for the next gesture instead of turning this edge back into polling.
                    scheduleParkedInitialAdjacentRunwayWakeAfterPhysicalIdle()
                }
            } else {
                main.postDelayed(retry, initialAdjacentRunwayAppendRetryDelayMs(target))
            }
        } else if (exactP0WakeAuthority != null) {
            // The wake registry owns both the strict event and its one delayed fail-safe.
        } else if (listenerRegistered) {
            main.postDelayed(retry, NTK_ADJACENT_ASSET_LISTENER_RETRY_TIMEOUT_MS)
        } else {
            main.postDelayed(retry, initialAdjacentRunwayAppendRetryDelayMs(target))
        }
    }

    private fun initialAdjacentExactP0WakePath(target: Manga, refs: List<PageRef>): String {
        if (Manga.sameEpisodeIdentity(manga, target)) return ""
        val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        if (isDirectWifiStrictAdjacentRunwayProfile(target) && path.startsWith("/manhwa/") &&
            refs.firstOrNull { it.transitionTitle == null }?.sourceIndex == 0
        ) {
            return path
        }
        val runwayCount = initialAdjacentAppendRunwayRefCount(refs)
        if (runwayCount <= 0) return ""
        val runwayRefs = refs.take(runwayCount)
        if (!isDirectWifiAdjacentExactP0HeadCandidate(target, runwayRefs)) return ""
        return path
    }

    private fun scheduleRemainingAdjacentRunwayAppend(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String,
        warm: Boolean
    ) {
        if (refs.isEmpty()) {
            clearActiveRemainingAdjacentRunwayTarget(target)
            clearPendingAdjacentAppendPublish(publishKey)
            return
        }
        markActiveRemainingAdjacentRunwayTarget(target)
        val targetPath = activeRemainingAdjacentRunwayTargetPath(target)
        if (targetPath.isNotEmpty()) {
            pendingRemainingAdjacentRunwayAppends[targetPath] =
                ParkedAdjacentRemainderAppend(target, refs, publishKey, warm)
        }
        val retryKey = remainingAdjacentRunwayRetryKey(target, refs, publishKey)
        val delayMs = remainingAdjacentRunwayAppendDelayMs()
        lateinit var retry: Runnable
        lateinit var retryOwner: NtkPathScheduledRetryRegistry.Owner<Runnable>
        retry = Runnable {
            if (!scheduledRemainingAdjacentRunwayRetries.claim(retryOwner)) return@Runnable
            if (cancelled.get()) {
                clearActiveRemainingAdjacentRunwayTarget(target)
                clearPendingAdjacentAppendPublish(publishKey)
                return@Runnable
            }
            val nextDelayMs = remainingAdjacentRunwayAppendDelayMs()
            if (nextDelayMs > 0L) {
                scheduleRemainingAdjacentRunwayAppend(target, refs, publishKey, warm)
                return@Runnable
            }
            try {
                control.execute {
                    appendRemainingAdjacentRunwayRefs(target, refs, publishKey, warm)
                }
            } catch (_: RejectedExecutionException) {
                clearActiveRemainingAdjacentRunwayTarget(target)
                clearPendingAdjacentAppendPublish(publishKey)
            }
        }
        val ownerPath = targetPath.ifEmpty { retryKey }
        val registration = scheduledRemainingAdjacentRunwayRetries.register(
            ownerPath,
            retryKey,
            retry,
        ) ?: return
        retryOwner = registration.owner
        registration.replaced?.let { replaced -> main.removeCallbacks(replaced.token) }
        val posted = main.postDelayed(
            retry,
            delayMs.coerceAtLeast(remainingAdjacentRunwayAppendMinRetryMs(target)),
        )
        if (!posted) {
            scheduledRemainingAdjacentRunwayRetries.cancel(retryOwner)
        }
    }

    private data class DirectWifiAdjacentRunwayTailHandoffSnapshot(
        val requiredRunwayPageCount: Int,
        val installedSourceIndexes: Set<Int>,
        val firstReadySourceIndex: Int,
    )

    /**
     * Own both sides of the p1-p3 resident-body race. The previous one-shot handoff registered a
     * source wake only after observing zero ready bodies; when p3 reached EOF a few milliseconds
     * after the p1+p2 main commit, its callback saw no waiter and the drawable paid the full input
     * retry timer. Register the bounded fallback and waiter first, then recheck readiness. A body
     * arriving before registration is caught by the recheck; one arriving afterwards wakes the
     * waiter. This exception is limited to the direct-Wi-Fi strict adjacent webtoon/manhwa p0-p3
     * runway; it publishes already-resident pixels and starts no new network work.
     */
    private fun tryHandoffDirectWifiAdjacentInitialRunwayTail(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String,
        warm: Boolean,
    ): Boolean {
        val path = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath?.trim().orEmpty(),
        )
        val initialSnapshot = directWifiAdjacentInitialRunwayTailSnapshot(
            target,
            refs,
            path,
        ) ?: return false
        if (!NtkDirectWifiAdjacentRunwayTailHandoffPolicy.shouldOwnWait(
                cancelled = cancelled.get(),
                directWifiStrictAdjacent = true,
                episodePath = path,
                requiredRunwayPageCount = initialSnapshot.requiredRunwayPageCount,
                installedSourceIndexes = initialSnapshot.installedSourceIndexes,
            )
        ) return false
        if (!directWifiAdjacentInitialRunwayTailHandoffs.add(path)) return true

        return try {
            val waiting = ParkedAdjacentRemainderAppend(target, refs, publishKey, warm)
            // Install the normal bounded retry first. It remains the backstop if the strict claim
            // retires without another resident-body callback.
            scheduleRemainingAdjacentRunwayAppend(target, refs, publishKey, warm)
            pendingRemainingAdjacentRunwayAppends[path] = waiting
            waitingStrictRemainingAdjacentAppends[path] = waiting
            if (isDirectWifiAdjacentInitialRunwayTailReady(target, refs, path)) {
                Log.d(
                    TAG,
                    "append_adjacent_runway_initial_tail_handoff targetId=${target.id} path=$path",
                )
                wakeStrictRemainingAdjacentAppend(path)
            }
            true
        } finally {
            directWifiAdjacentInitialRunwayTailHandoffs.remove(path)
        }
    }

    private fun isDirectWifiAdjacentInitialRunwayTailReady(
        target: Manga,
        refs: List<PageRef>,
        path: String,
    ): Boolean {
        val snapshot = directWifiAdjacentInitialRunwayTailSnapshot(
            target,
            refs,
            path,
        ) ?: return false
        return NtkDirectWifiAdjacentRunwayTailHandoffPolicy.shouldHandoff(
            cancelled = cancelled.get(),
            directWifiStrictAdjacent = true,
            episodePath = path,
            requiredRunwayPageCount = snapshot.requiredRunwayPageCount,
            installedSourceIndexes = snapshot.installedSourceIndexes,
            firstReadySourceIndex = snapshot.firstReadySourceIndex,
        )
    }

    private fun directWifiAdjacentInitialRunwayTailSnapshot(
        target: Manga,
        refs: List<PageRef>,
        path: String,
    ): DirectWifiAdjacentRunwayTailHandoffSnapshot? {
        if (path.isEmpty() || !isDirectWifiStrictAdjacentRunwayProfile(target, path)) return null
        val claim = adjacentStrictSourceClaims[path] ?: return null
        if (!isAdjacentStrictSourceClaimLive(path, claim)) return null
        val requiredRunwayPageCount = requiredInitialAdjacentRunwayPages(target)
        val (installedSourceIndexes, candidates) = synchronized(pagesLock) {
            val installed = pages.asSequence()
                .filter { page ->
                    page.transitionTitle == null &&
                        page.sourceIndex in 0 until requiredRunwayPageCount &&
                        looseSameEpisodeForAppend(page.manga, target)
                }
                .map { it.sourceIndex }
                .toSet()
            installed to appendableRemainingAdjacentRunwayRefsLocked(target, refs).refs
        }
        val firstReadySourceIndex = candidates.firstOrNull()
            ?.takeIf(::isAdjacentRunwayRefPublishable)
            ?.sourceIndex
            ?: -1
        return DirectWifiAdjacentRunwayTailHandoffSnapshot(
            requiredRunwayPageCount = requiredRunwayPageCount,
            installedSourceIndexes = installedSourceIndexes,
            firstReadySourceIndex = firstReadySourceIndex,
        )
    }

    private fun wakeStrictRemainingAdjacentAppend(path: String) {
        if (parkedAdjacentRemainderAppends[path] == null &&
            waitingStrictRemainingAdjacentAppends[path] == null &&
            pendingRemainingAdjacentRunwayAppends[path] == null
        ) return
        // Acquire and retain a raced event atomically. Two independent concurrent sets leave a
        // gap where release can observe no pending edge immediately before the failed acquirer
        // records one, permanently stranding a freshly parked suffix.
        if (!strictRemainingAdjacentWakeLatch.tryAcquire(path)) return
        try {
            control.execute {
                try {
                    val waiting = parkedAdjacentRemainderAppends[path]
                        ?: waitingStrictRemainingAdjacentAppends[path]
                        ?: pendingRemainingAdjacentRunwayAppends[path]
                        ?: return@execute
                    val removedParked = parkedAdjacentRemainderAppends.remove(path, waiting)
                    val removedStrict = waitingStrictRemainingAdjacentAppends.remove(path, waiting)
                    val removedPending = pendingRemainingAdjacentRunwayAppends.remove(path, waiting)
                    if (!removedParked && !removedStrict && !removedPending) return@execute
                    cancelAdjacentStrictRecoveryBindDeadline(path)
                    scheduledRemainingAdjacentRunwayRetries.cancelPath(path)?.let { scheduled ->
                        main.removeCallbacks(scheduled.token)
                    }
                    if (cancelled.get()) return@execute
                    appendRemainingAdjacentRunwayRefs(
                        waiting.target,
                        waiting.refs,
                        waiting.publishKey,
                        waiting.warm,
                    )
                } finally {
                    // appendRemainingAdjacentRunwayRefs may have registered a fresh parked owner
                    // while a viewport/body event raced this turn. Drain that retained edge only;
                    // a normally parked offscreen suffix remains event-driven and timer-free.
                    if (strictRemainingAdjacentWakeLatch.release(path)) {
                        wakeStrictRemainingAdjacentAppend(path)
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            strictRemainingAdjacentWakeLatch.cancel(path)
        }
    }

    /**
     * Closes the second half of the resident-body registration race. A body callback can remove
     * the old waiter while [appendRemainingAdjacentRunwayRefs] is taking its readiness snapshot,
     * then publish before that method parks the replacement. Recheck the initial p0-p3 handoff or
     * the exact suffix identity selected by the caller, then queue its wake behind the current
     * control turn where the prior in-flight wake marker has already been released.
     */
    private fun deferStrictRemainingAdjacentWakeAfterRegistration(
        path: String,
        waiting: ParkedAdjacentRemainderAppend,
        target: Manga,
        refs: List<PageRef>,
        exactDescriptorWait: Boolean = false,
    ) {
        fun readyOrInvalidated(): Boolean = if (exactDescriptorWait) {
            shouldWakeStrictExactDescriptorWaitAfterRegistration(
                target,
                refs,
                path,
                waiting.expectedFirstMissingPageIdentity,
            )
        } else {
            isDirectWifiAdjacentInitialRunwayTailReady(target, refs, path)
        }
        if (!readyOrInvalidated()) return
        try {
            control.execute {
                if (waitingStrictRemainingAdjacentAppends[path] === waiting &&
                    readyOrInvalidated()
                ) {
                    wakeStrictRemainingAdjacentAppend(path)
                }
            }
        } catch (_: RejectedExecutionException) {
            // Session retirement owns executor shutdown and clears the parked waiter.
        }
    }

    /**
     * Rechecks both halves of the exact descriptor registration race. A descriptor that beat the
     * waiter is consumed immediately; a claim/identity that stopped being exact is redriven into
     * the existing recovery or generic-fallback decision instead of being left parked forever.
     */
    private fun shouldWakeStrictExactDescriptorWaitAfterRegistration(
        target: Manga,
        refs: List<PageRef>,
        path: String,
        expectedFirstMissingPageIdentity: String?,
    ): Boolean {
        val claim = adjacentStrictSourceClaims[path] ?: return true
        if (!isAdjacentStrictSourceClaimLive(path, claim)) return true
        val candidates = synchronized(pagesLock) {
            appendableRemainingAdjacentRunwayRefsLocked(target, refs).refs
        }
        if (candidates.isEmpty() ||
            !requiresStrictExactRemainingAdjacentRunway(candidates)
        ) {
            return true
        }
        val expectedIdentity = expectedFirstMissingPageIdentity ?: return true
        val expected = candidates.firstOrNull {
            runwayPageRefIdentity(it) == expectedIdentity
        } ?: return true
        return strictAdjacentBodyDescriptor(expected) != null
    }

    /** Captures the exact first physical page whose strict descriptor is not published yet. */
    private fun firstMissingStrictAdjacentDescriptorIdentity(
        target: Manga,
        refs: List<PageRef>,
    ): String? {
        val candidates = synchronized(pagesLock) {
            appendableRemainingAdjacentRunwayRefsLocked(target, refs).refs
        }
        return candidates.firstOrNull { strictAdjacentBodyDescriptor(it) == null }
            ?.let(::runwayPageRefIdentity)
    }

    private fun adjacentStrictDescriptorWaitProgress(
        path: String,
        claim: AdjacentStrictSourceClaim,
    ): AdjacentStrictDescriptorWaitProgress? {
        val snapshot = NtkSourceSpoolRegistry.currentSnapshot(path) ?: return null
        if (snapshot.generation != claim.episode.value ||
            snapshot.manifestDigest != claim.manifestDigest
        ) {
            return null
        }
        val exactActiveCalls = NtkStrictSourceOwnershipRegistry.activeOperationCount(
            path,
            claim.manifestDigest,
            snapshot.sessionId,
        )
        // quarantineDebugSnapshot is actor-published. A body Call is admitted on its worker and
        // may remain in the process-wide quarantine ledger while the actor view still reports the
        // preceding zero-active snapshot. The no-progress watchdog must read that live ownership
        // or it can cancel a healthy final body immediately before its normal read timeout.
        val liveQuarantine = NtkQuarantineSourceOwnershipRegistry.snapshot(
            path,
            snapshot.generation,
            snapshot.sessionId,
        )
        val activeCalls = NtkStrictDescriptorWaitProgressPolicy.activeCalls(
            cachedQuarantineCalls = snapshot.quarantineActiveCalls,
            liveQuarantineCalls = liveQuarantine?.activeCalls,
            exactCalls = exactActiveCalls,
            unresolvedStreamedExactBodies = claim.transport.unresolvedStreamedExactBodyCount(),
        )
        return AdjacentStrictDescriptorWaitProgress(
            physicalCallsStarted = liveQuarantine?.physicalCallCount
                ?: snapshot.quarantinePhysicalCallsStarted,
            exactAdoptedBodies = snapshot.exactAdoptedBodies,
            // ExactOpen suffix bodies move from the quarantine ledger to the strict owner ledger.
            // Count both; overlap during promotion is harmless because this field is a liveness
            // predicate, while omitting exact operations cancels healthy active HTTP bodies.
            activeCalls = activeCalls,
        )
    }

    /**
     * A strict source intentionally parks its suffix until viewport demand. Once demand has been
     * released, callbacks own readiness and this single no-progress deadline owns their missing
     * terminal edge. Physical/adoption/call progress refreshes the 15 s interval; a new append
     * waiter at the same progress inherits the remaining interval instead of resetting it.
     */
    private fun armAdjacentStrictDescriptorWaitWatchdog(
        path: String,
        waiter: ParkedAdjacentRemainderAppend,
    ) {
        if (cancelled.get()) return
        val normalizedPath = NtkStripDigests.normalizeEpisodePath(path)
        val claim = adjacentStrictSourceClaims[normalizedPath] ?: return
        if (!claim.viewportActivated.get() || !isAdjacentStrictSourceClaimLive(normalizedPath, claim)) {
            return
        }
        val progress = adjacentStrictDescriptorWaitProgress(normalizedPath, claim) ?: return
        val bindingToken = claim.descriptorBindingToken
        val watchdogToken = Any()
        val now = SystemClock.elapsedRealtime()
        var replaced: Runnable? = null
        var delayMs = NTK_STRICT_SUFFIX_EVENT_NO_PROGRESS_MS
        lateinit var watchdog: Runnable
        watchdog = Runnable {
            fireAdjacentStrictDescriptorWaitWatchdog(
                path = path,
                normalizedPath = normalizedPath,
                claim = claim,
                waiter = waiter,
                bindingToken = bindingToken,
                baseline = progress,
                watchdogToken = watchdogToken,
            )
        }
        synchronized(claim) {
            if (cancelled.get() || adjacentStrictSourceClaims[normalizedPath] !== claim ||
                adjacentStrictDescriptorBindingTokens[normalizedPath] !== bindingToken ||
                waitingStrictRemainingAdjacentAppends[path] !== waiter ||
                claim.terminalFailureObserved.get()
            ) {
                return
            }
            if (claim.descriptorWaitProgress != progress) {
                claim.descriptorWaitProgress = progress
                claim.descriptorWaitProgressAtMs = now
            } else if (claim.descriptorWaitProgressAtMs <= 0L) {
                claim.descriptorWaitProgressAtMs = now
            }
            if (claim.descriptorWaitWatchdogWaiter === waiter &&
                claim.descriptorWaitWatchdogRunnable != null
            ) {
                return
            }
            delayMs = (
                NTK_STRICT_SUFFIX_EVENT_NO_PROGRESS_MS -
                    (now - claim.descriptorWaitProgressAtMs).coerceAtLeast(0L)
                ).coerceAtLeast(1L)
            replaced = claim.descriptorWaitWatchdogRunnable
            claim.descriptorWaitWatchdogToken = watchdogToken
            claim.descriptorWaitWatchdogRunnable = watchdog
            claim.descriptorWaitWatchdogWaiter = waiter
        }
        replaced?.let(main::removeCallbacks)
        if (!main.postDelayed(watchdog, delayMs)) {
            synchronized(claim) {
                if (claim.descriptorWaitWatchdogToken === watchdogToken) {
                    claim.descriptorWaitWatchdogToken = null
                    claim.descriptorWaitWatchdogRunnable = null
                    claim.descriptorWaitWatchdogWaiter = null
                }
            }
        }
    }

    private fun fireAdjacentStrictDescriptorWaitWatchdog(
        path: String,
        normalizedPath: String,
        claim: AdjacentStrictSourceClaim,
        waiter: ParkedAdjacentRemainderAppend,
        bindingToken: Any,
        baseline: AdjacentStrictDescriptorWaitProgress,
        watchdogToken: Any,
    ) {
        synchronized(claim) {
            if (claim.descriptorWaitWatchdogToken !== watchdogToken) return
            claim.descriptorWaitWatchdogToken = null
            claim.descriptorWaitWatchdogRunnable = null
            claim.descriptorWaitWatchdogWaiter = null
        }
        val bindingCurrent = adjacentStrictSourceClaims[normalizedPath] === claim &&
            adjacentStrictDescriptorBindingTokens[normalizedPath] === bindingToken
        val waiterPresent = waitingStrictRemainingAdjacentAppends[path] === waiter
        val claimLive = bindingCurrent && isAdjacentStrictSourceClaimLive(normalizedPath, claim)
        val descriptorReadyOrIdentityChanged = bindingCurrent && waiterPresent &&
            shouldWakeStrictExactDescriptorWaitAfterRegistration(
                waiter.target,
                waiter.refs,
                normalizedPath,
                waiter.expectedFirstMissingPageIdentity,
            )
        val progress = if (bindingCurrent) {
            adjacentStrictDescriptorWaitProgress(normalizedPath, claim)
        } else {
            null
        }
        when (NtkStrictRemainingAdjacentWatchdogPolicy.decide(
            cancelled = cancelled.get(),
            bindingCurrent = bindingCurrent,
            waiterPresent = waiterPresent,
            claimLive = claimLive,
            descriptorReadyOrIdentityChanged = descriptorReadyOrIdentityChanged,
            sourceProgressed = progress != null && progress != baseline,
            sourceCallsActive = progress?.activeCalls?.let { it > 0 } == true,
        )) {
            NtkStrictRemainingAdjacentWatchdogPolicy.Decision.NONE -> Unit
            NtkStrictRemainingAdjacentWatchdogPolicy.Decision.WAKE ->
                wakeStrictRemainingAdjacentAppend(path)

            NtkStrictRemainingAdjacentWatchdogPolicy.Decision.REARM_AFTER_PROGRESS -> {
                // A topology-identical active body is still objective source ownership. Renew
                // this interval explicitly; otherwise arm() inherits the expired timestamp and
                // reposts every millisecond while the read timeout is still running.
                if (progress != null && progress == baseline && progress.activeCalls > 0) {
                    synchronized(claim) {
                        if (claim.descriptorWaitWatchdogToken == null &&
                            adjacentStrictSourceClaims[normalizedPath] === claim
                        ) {
                            claim.descriptorWaitProgressAtMs = SystemClock.elapsedRealtime()
                        }
                    }
                }
                armAdjacentStrictDescriptorWaitWatchdog(path, waiter)
            }

            NtkStrictRemainingAdjacentWatchdogPolicy.Decision.INVALIDATE_AND_WAKE -> {
                invalidateAdjacentStrictSourceClaim(
                    normalizedPath,
                    claim,
                    "descriptor_event_no_progress",
                )
            }
        }
    }

    private fun cancelAdjacentStrictDescriptorWaitWatchdog(
        path: String,
        expectedClaim: AdjacentStrictSourceClaim? = null,
    ) {
        val normalizedPath = NtkStripDigests.normalizeEpisodePath(path)
        val claim = expectedClaim ?: adjacentStrictSourceClaims[normalizedPath] ?: return
        val watchdog = synchronized(claim) {
            claim.descriptorWaitWatchdogToken = null
            claim.descriptorWaitWatchdogWaiter = null
            claim.descriptorWaitWatchdogRunnable.also {
                claim.descriptorWaitWatchdogRunnable = null
            }
        }
        watchdog?.let(main::removeCallbacks)
    }

    private fun cancelAdjacentStrictRecoveryBindDeadline(path: String) {
        val normalizedPath = NtkStripDigests.normalizeEpisodePath(path)
        if (normalizedPath.isEmpty()) return
        scheduledAdjacentStrictRecoveryBindDeadlines.cancelPath(normalizedPath)
            ?.let { scheduled -> main.removeCallbacks(scheduled.token) }
    }

    /**
     * Owns the terminal edge for a replacement manifest whose strict transport could not bind.
     * The key is waiter/generation-bound, while the delay inherits the recovery request epoch so
     * lifecycle wakes cannot postpone it forever.
     */
    private fun armAdjacentStrictRecoveryBindDeadline(
        path: String,
        waiter: ParkedAdjacentRemainderAppend,
    ) {
        if (cancelled.get()) return
        val normalizedPath = NtkStripDigests.normalizeEpisodePath(path)
        if (normalizedPath.isEmpty() ||
            waitingStrictRemainingAdjacentAppends[normalizedPath] !== waiter
        ) return
        val recoverySnapshot = synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictRecoveryStates[normalizedPath]?.takeIf { state ->
                state.awaitingReplacement && !state.exhausted
            }?.let { state ->
                Triple(
                    state.expectedManifestDigest,
                    state.lastRequestAtMs,
                    state.lastBindDeadlineAtMs,
                )
            }
        } ?: return
        val observedRevision = NtkSourceSpoolRegistry.currentAuthoritativeManifest(normalizedPath)
            ?.takeIf { manifest ->
                manifest.isProductionClaimable &&
                    manifest.seal.digestSha256 == recoverySnapshot.first
            }
            ?.seal
            ?.revision
            ?: 0L
        val retryKey = buildString {
            append("strict_recovery_bind|")
            append(normalizedPath)
            append('|')
            append(recoverySnapshot.first)
            append('|')
            append(observedRevision)
            append('|')
            append(waiter.identityToken.hashCode())
        }
        lateinit var deadline: Runnable
        lateinit var deadlineOwner: NtkPathScheduledRetryRegistry.Owner<Runnable>
        deadline = Runnable {
            if (!scheduledAdjacentStrictRecoveryBindDeadlines.claim(deadlineOwner)) {
                return@Runnable
            }
            try {
                control.execute {
                    fireAdjacentStrictRecoveryBindDeadline(
                        normalizedPath,
                        waiter,
                        recoverySnapshot.first,
                        observedRevision,
                    )
                }
            } catch (_: RejectedExecutionException) {
                // Session cancellation owns waiter cleanup.
            }
        }
        val registration = scheduledAdjacentStrictRecoveryBindDeadlines.register(
            normalizedPath,
            retryKey,
            deadline,
        ) ?: return
        deadlineOwner = registration.owner
        registration.replaced?.let { replaced -> main.removeCallbacks(replaced.token) }

        val stillCurrent = waitingStrictRemainingAdjacentAppends[normalizedPath] === waiter &&
            synchronized(adjacentStrictSourceClaimLock) {
                adjacentStrictRecoveryStates[normalizedPath]?.let { state ->
                    state.awaitingReplacement && !state.exhausted &&
                        state.expectedManifestDigest == recoverySnapshot.first
                } == true
            }
        if (!stillCurrent) {
            scheduledAdjacentStrictRecoveryBindDeadlines.cancel(deadlineOwner)
            return
        }
        val delayMs = NtkStrictRecoveryBindDeadlinePolicy.remainingDelayMs(
            nowMs = SystemClock.elapsedRealtime(),
            lastRecoveryRequestAtMs = recoverySnapshot.second,
            lastDeadlineFireAtMs = recoverySnapshot.third,
        )
        if (!main.postDelayed(deadline, delayMs)) {
            scheduledAdjacentStrictRecoveryBindDeadlines.cancel(deadlineOwner)
        }
    }

    private fun fireAdjacentStrictRecoveryBindDeadline(
        path: String,
        waiter: ParkedAdjacentRemainderAppend,
        expectedManifestDigest: String,
        observedRevision: Long,
    ) {
        if (cancelled.get() || waitingStrictRemainingAdjacentAppends[path] !== waiter) return
        val recoveryCurrent = synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictRecoveryStates[path]?.let { state ->
                if (state.awaitingReplacement && !state.exhausted &&
                    state.expectedManifestDigest == expectedManifestDigest
                ) {
                    state.lastBindDeadlineAtMs = SystemClock.elapsedRealtime()
                    true
                } else {
                    false
                }
            } == true
        }
        if (!recoveryCurrent) return

        // observedRevision is deliberately diagnostic only. A missing manifest must request a new
        // one, and a newer revision must be allowed to bind instead of being rejected by this old
        // deadline owner.
        val recoveryOwned = holdOrRecoverAdjacentStrictSource(waiter.target)
        val claim = adjacentStrictSourceClaims[path]
        if (claim != null && isAdjacentStrictSourceClaimLive(path, claim)) {
            Log.d(
                TAG,
                "append_adjacent_strict_recovery_bind_deadline_joined path=$path " +
                    "observedRevision=$observedRevision generation=${claim.episode.value}",
            )
            wakeStrictRemainingAdjacentAppend(path)
            return
        }
        val recoveryState = synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictRecoveryStates[path]?.let { state ->
                Triple(
                    state.awaitingReplacement,
                    state.exhausted,
                    state.networkRearmableTerminal,
                )
            }
        }
        if (recoveryState?.second == true && recoveryState.third) {
            // Keep this bounded waiter as the capability which a later real VALIDATED epoch can
            // rearm. It owns no polling runnable while terminal.
            Log.d(TAG, "append_adjacent_strict_recovery_wait_network path=$path")
            return
        }
        if (!recoveryOwned || recoveryState == null || recoveryState.second) {
            if (waitingStrictRemainingAdjacentAppends.remove(path, waiter)) {
                clearActiveRemainingAdjacentRunwayTarget(waiter.target)
                clearPendingAdjacentAppendPublish(waiter.publishKey)
            }
            return
        }
        if (recoveryState.first) {
            armAdjacentStrictRecoveryBindDeadline(path, waiter)
        } else {
            wakeStrictRemainingAdjacentAppend(path)
        }
    }

    /**
     * A committed incoming real-image frame is stronger entry evidence than the coalesced logical
     * anchor. During one continuous fling that anchor can remain on the retiring episode's final
     * page even though the physical Surface already shows the next episode. Promote the existing
     * suffix snapshot immediately from that exact proof; never mutate the scroll coordinate and
     * never create new network work here.
     */
    private fun wakeRemainingAdjacentAppendAfterExactFirstActual(path: String) {
        wakeStrictRemainingAdjacentAppend(path)
        requestEnteredExactEpisodePixelCompletion(path)
    }

    /**
     * Full exact structure is published before its offscreen pixels so indexes remain canonical.
     * That intentionally bypasses the old structural tail appender; finish only the bounded
     * p0..runway pixel cohort here as its descriptors arrive, even before the episode is entered.
     */
    private fun requestPublishedExactAdjacentInitialRunwayCompletion(path: String) {
        val normalizedPath = NtkStripDigests.normalizeEpisodePath(path)
        if (cancelled.get() || normalizedPath.isEmpty() ||
            normalizedPath !in publishedExactOffscreenRunwayPaths ||
            !normalizedPath.startsWith("/manhwa/")
        ) {
            return
        }
        if (!publishedExactAdjacentInitialRunwayCompletionPaths.add(normalizedPath)) return
        try {
            decode.execute {
                drainPublishedExactAdjacentInitialRunwayCompletion(normalizedPath)
            }
        } catch (_: RejectedExecutionException) {
            publishedExactAdjacentInitialRunwayCompletionPaths.remove(normalizedPath)
        }
    }

    private fun drainPublishedExactAdjacentInitialRunwayCompletion(path: String) {
        val claim = adjacentStrictSourceClaims[path]
        if (cancelled.get() || claim == null || !claim.directWifiRunwayProfile ||
            !isAdjacentStrictSourceClaimLive(path, claim)
        ) {
            publishedExactAdjacentInitialRunwayCompletionPaths.remove(path)
            return
        }
        // The exact next chapter owns one bounded entry runway while the foreground is idle. p0
        // alone is not enough for short images or a fast fling, and the ordinary offscreen policy
        // intentionally rejects p1+. Complete only the product's fixed initial runway here; the
        // rolling launch window has already returned distant slots and p4+ remains encoded until
        // real entry advances the viewport.
        val requiredSourceCount = minOf(
            initialAdjacentRunwayPageLimit(path),
            claim.pageCount,
        )
        val descriptorsReady = publishedInitialRunwayDescriptorsReady(
            path,
            claim,
            requiredSourceCount,
        )
        if (!descriptorsReady) {
            // Descriptor installation invokes the request again. Release first, then recheck the
            // exact registry to close this race: the final descriptor callback can observe this
            // owner and join just before the owner observes the old incomplete set. Without the
            // post-release probe both sides return and the fixed runway loses its only wake edge.
            publishedExactAdjacentInitialRunwayCompletionPaths.remove(path)
            if (publishedInitialRunwayDescriptorsReady(path, claim, requiredSourceCount)) {
                requestPublishedExactAdjacentInitialRunwayCompletion(path)
            }
            return
        }
        val missingCohort = synchronized(pagesLock) {
            val candidates = pages.withIndex().filter { (index, page) ->
                page.transitionTitle == null && page.sourceIndex in 0 until requiredSourceCount &&
                    NtkStripDigests.normalizeEpisodePath(
                        page.manga.ntkEpisodePath?.trim().orEmpty(),
                    ) == path &&
                    !hasCanonicalDrawableCompletion(page) &&
                    !hasListenerDrawableDelivery(index, page) &&
                    !hasDeliveredBitmap(index)
            }
            // Publish no partially prepared prefix. Once p0 has attached, exposing p1..p3 one at
            // a time lets a real swipe observe four ready sources and then forces p4's
            // HardwareBuffer write into that same motion interval. Decode the largest contiguous
            // missing suffix of the fixed p0..p4 runway privately, then install it in one main
            // turn. A non-contiguous candidate set can arise only from a concurrent delivery; stop
            // before that gap and re-evaluate after the atomic commit.
            val cohort = ArrayList<IndexedValue<PageRef>>(candidates.size)
            var nextIndex = candidates.firstOrNull()?.index ?: -1
            for (candidate in candidates) {
                if (candidate.index != nextIndex) break
                cohort.add(candidate)
                nextIndex++
            }
            cohort
        }
        if (missingCohort.isEmpty()) {
            publishedExactAdjacentInitialRunwayCompletionPaths.remove(path)
            val target = synchronized(pagesLock) {
                pages.firstOrNull { page ->
                    page.transitionTitle == null && page.sourceIndex == 0 &&
                        NtkStripDigests.normalizeEpisodePath(
                            page.manga.ntkEpisodePath?.trim().orEmpty(),
                        ) == path
                }?.manga
            }
            if (target != null) markExactAdjacentRunwayTelemetryIfReady(target, claim.pageCount)
            // p0 can become physically visible in the same structure-publish frame. Keep this
            // bounded owner through that race and release it only after every required p0..pN
            // drawable has crossed the canonical Session/Surface readiness boundary.
            publishedExactOffscreenRunwayPaths.remove(path)
            return
        }
        val missingIndex = missingCohort.first().index
        val missingPages = missingCohort.map { it.value }
        val failure = AtomicReference<Throwable?>(null)
        val batch = prepareAdjacentRunwayDrawableBatch(
            startIndex = missingIndex,
            refs = missingPages,
            reason = "published_exact_initial_runway_completion",
            requireStrictDescriptor = true,
            offscreenInitialRunwayCompletionIntent = true,
            failureSink = failure,
        )
        if (batch == null) {
            val retryDelay = if (failure.get() is NtkPhysicalMotionDecodeDeferredException) {
                NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS
            } else {
                NTK_ENTERED_EXACT_PIXEL_COMPLETION_STEP_MS
            }
            // Keep the path owner while input is active. Releasing it before the delayed turn lets
            // every descriptor/window callback start another decode immediately, producing an
            // unbounded retry burst on the same offscreen page. The delayed turn atomically hands
            // ownership back to request(); callbacks in the meantime only join this one waiter.
            val posted = main.postDelayed(
                {
                    if (publishedExactAdjacentInitialRunwayCompletionPaths.remove(path)) {
                        requestPublishedExactAdjacentInitialRunwayCompletion(path)
                    }
                },
                retryDelay,
            )
            if (!posted) {
                publishedExactAdjacentInitialRunwayCompletionPaths.remove(path)
            }
            return
        }
        val posted = main.post {
            val currentIndex = currentPageIndex(missingPages.first(), missingIndex)
            val currentPages = if (currentIndex >= 0) {
                missingPages.indices.mapNotNull { offset -> pageRef(currentIndex + offset) }
            } else {
                emptyList()
            }
            val sameContiguousCohort = currentPages.size == missingPages.size &&
                currentPages.indices.all { offset -> currentPages[offset] === missingPages[offset] }
            if (!cancelled.get() && sameContiguousCohort && currentPages.all { currentPage ->
                    NtkStripDigests.normalizeEpisodePath(
                        currentPage.manga.ntkEpisodePath?.trim().orEmpty(),
                    ) == path
                }
            ) {
                commitAdjacentRunwayDrawableBatch(
                    rebindAdjacentRunwayDrawableBatch(
                        batch,
                        currentIndex,
                        currentPages,
                    ),
                )
                markExactAdjacentRunwayTelemetryIfReady(currentPages.first().manga, claim.pageCount)
                if (Log.isLoggable(TAG, Log.DEBUG) &&
                    shouldLogRateLimitedDiagnostic(
                        "published_exact_initial_runway_surface_audit|$path",
                        5_000L,
                    )
                ) {
                    main.postDelayed(
                        {
                            if (!cancelled.get()) {
                                Log.d(
                                    TAG,
                                    "append_adjacent_initial_runway_surface_audit path=$path " +
                                        pipelineLivenessDiagnosticForTest(),
                                )
                            }
                        },
                        250L,
                    )
                }
            } else {
                recycleAdjacentRunwayDrawableBatch(batch)
            }
            publishedExactAdjacentInitialRunwayCompletionPaths.remove(path)
            requestPublishedExactAdjacentInitialRunwayCompletion(path)
        }
        if (!posted) {
            recycleAdjacentRunwayDrawableBatch(batch)
            publishedExactAdjacentInitialRunwayCompletionPaths.remove(path)
        }
    }

    private fun publishedInitialRunwayDescriptorsReady(
        path: String,
        claim: AdjacentStrictSourceClaim,
        requiredSourceCount: Int,
    ): Boolean = requiredSourceCount > 0 &&
        (0 until requiredSourceCount).all { sourceIndex ->
            adjacentStrictBodyDescriptors.containsKey(
                adjacentStrictBodyDescriptorKey(path, claim.manifestDigest, sourceIndex),
            )
        }

    /**
     * Completes pixels for an already-published exact episode after real entry. The structural
     * append owner is intentionally not used here: every PageRef is already present. Work advances
     * one canonical page per turn, is motion-gated by the same exact decode admission as normal
     * adjacent work, and stops as soon as a newer compositor-proven episode owns the viewport.
     */
    private fun requestEnteredExactEpisodePixelCompletion(path: String) {
        val normalizedPath = NtkStripDigests.normalizeEpisodePath(path)
        if (cancelled.get() || normalizedPath.isEmpty() ||
            latestEnteredExactEpisodePath.get() != normalizedPath
        ) return
        val claim = adjacentStrictSourceClaims[normalizedPath] ?: return
        if (!claim.firstActualFramePresented.get() ||
            !isAdjacentStrictSourceClaimLive(normalizedPath, claim)
        ) return
        if (!enteredExactEpisodePixelCompletionPaths.add(normalizedPath)) return
        postEnteredExactEpisodePixelCompletion(normalizedPath, 0L)
    }

    private fun postEnteredExactEpisodePixelCompletion(path: String, delayMs: Long) {
        val posted = main.postDelayed(
            { drainEnteredExactEpisodePixelCompletion(path) },
            delayMs.coerceAtLeast(0L),
        )
        if (!posted) enteredExactEpisodePixelCompletionPaths.remove(path)
    }

    private fun scheduleEnteredExactEpisodePixelCompletionAudit(path: String) {
        if (cancelled.get() || latestEnteredExactEpisodePath.get() != path ||
            !enteredExactEpisodePixelCompletionAuditPaths.add(path)
        ) return
        val posted = main.postDelayed(
            {
                enteredExactEpisodePixelCompletionAuditPaths.remove(path)
                if (!cancelled.get() && latestEnteredExactEpisodePath.get() == path) {
                    requestEnteredExactEpisodePixelCompletion(path)
                }
            },
            NTK_ENTERED_EXACT_PIXEL_COMPLETION_AUDIT_MS,
        )
        if (!posted) enteredExactEpisodePixelCompletionAuditPaths.remove(path)
    }

    private fun drainEnteredExactEpisodePixelCompletion(path: String) {
        if (cancelled.get() || latestEnteredExactEpisodePath.get() != path) {
            enteredExactEpisodePixelCompletionPaths.remove(path)
            return
        }
        val claim = adjacentStrictSourceClaims[path]
        if (claim == null || !claim.firstActualFramePresented.get() ||
            !isAdjacentStrictSourceClaimLive(path, claim)
        ) {
            enteredExactEpisodePixelCompletionPaths.remove(path)
            return
        }
        val quietMs = maxOf(
            physicalTouchQuietRemainingMs(NTK_ENTERED_EXACT_PIXEL_COMPLETION_IDLE_MS),
            if (viewportBusy.get() || NtkReaderTransferPacer.isPhysicalMotionActive()) {
                NTK_ENTERED_EXACT_PIXEL_COMPLETION_IDLE_MS
            } else {
                0L
            },
        )
        if (quietMs > 0L) {
            // A strict body can become resident through the physical published-body registry
            // after its descriptor callback observed the previous compositor proof. In that
            // ordering no further body event exists, while a blocked passive fling keeps this
            // episode-completion owner behind motion grace forever. Re-probe only the already-
            // resident, compositor-proven next source here. The helper never starts network work
            // and the identity-bound flight admits at most that one forward page, so real touch
            // still retains the broader offscreen decode fence.
            requestLatestExactAdjacentCompositorForwardWarm()
            latestPhysicalForwardIntentPage.get()?.takeIf { blockedPage ->
                blockedPage.sourceIndex >= 0 &&
                    NtkStripDigests.normalizeEpisodePath(
                        blockedPage.manga.ntkEpisodePath.orEmpty(),
                    ) == path &&
                    strictAdjacentRehydrateIdentity(blockedPage) != null
            }?.let { blockedPage ->
                claim.transport.onPhysicalBlockedPageRequested(
                    claim.episode,
                    blockedPage.sourceIndex,
                )
            }
            postEnteredExactEpisodePixelCompletion(path, quietMs)
            return
        }

        // p0..p4 can be streamed by the click-owned boundary wave while the strict source owns
        // the immutable suffix. If the user stops immediately after entering a short chapter,
        // compositor demand may never move far enough to admit that suffix. The physical-entry
        // and quiet-input proof above is the production completion edge: let the same exact source
        // actor finish its remaining table, then descriptor callbacks resume this pixel drain.
        // A late committed callback for the predecessor can rewrite the process-wide transfer
        // owner after this episode's first-actual edge. This drain is still guarded by the latest
        // compositor-entered path above, so reassert that exact authority before asking the source
        // actor to release its already-open optional suffix streams.
        NtkReaderTransferPacer.notePhysicalForegroundEpisode(this, path)
        claim.transport.onForegroundIdleCompletionRequested(claim.episode)

        val indexedPages = synchronized(pagesLock) {
            pages.withIndex().filter { (_, page) ->
                page.transitionTitle == null && page.sourceIndex >= 0 &&
                    NtkStripDigests.normalizeEpisodePath(
                        page.manga.ntkEpisodePath?.trim().orEmpty(),
                    ) == path
            }
        }
        if (indexedPages.isEmpty()) {
            enteredExactEpisodePixelCompletionPaths.remove(path)
            return
        }
        val missing = indexedPages.firstOrNull { (index, page) ->
            !hasCanonicalDrawableCompletion(page) &&
                !hasListenerDrawableDelivery(index, page) &&
                !hasDeliveredBitmap(index)
        }
        if (missing == null) {
            enteredExactEpisodePixelCompletionPaths.remove(path)
            val completedEpisode = indexedPages.last().value.manga
            maybeWarmCompletedForwardEpisode(indexedPages.last().index, completedEpisode)
            // Completion can become observable on the final registry write after its descriptor
            // callback already tried (and relinquished) this owner. If an exact next pair exists
            // but its structure is still absent, re-enter once per second until the ordinary
            // completion path opens that gate. This is current-episode-only, single-posted and
            // stops as soon as the runway is attached or the viewport changes.
            if (currentForwardAdjacentCompletionTargetClaim(path) != null &&
                !hasForwardNtkEpisodeAfterSource(completedEpisode)
            ) {
                scheduleEnteredExactEpisodePixelCompletionAudit(path)
            }
            return
        }
        val missingIndex = missing.index
        val missingPage = missing.value
        val missingRehydrateIdentity = strictAdjacentRehydrateIdentity(missingPage).orEmpty()
        val missingRehydrateFlight = strictAdjacentRehydrateFlights[missingRehydrateIdentity]
        val pendingDelivery = (pendingDeliveryWidths[missingIndex] ?: 0) > 0
        if (pendingDelivery ||
            missingRehydrateFlight != null
        ) {
            // Descriptor publication and the bounded poll's final park can cross on different
            // executors. The callback normally wakes the flight, but a descriptor that won just
            // before the tombstone was installed has no future edge to repeat. This condition-
            // based drain is already the single current-episode completion owner; if the exact
            // body is now visible, idempotently reopen that same identity-bound decoder.
            if (missingRehydrateFlight != null &&
                (strictAdjacentBodyDescriptor(missingPage) != null ||
                    strictAdjacentPublishedBody(missingPage) != null)
            ) {
                // Ordinary direct-adjacent admission deliberately keeps idle pixels within a
                // short forward runway. This compositor-entered, input-quiet completion owner is
                // different: it validates the rest of the immutable episode one source at a time
                // so a later physical scroll never discovers a corrupt/undecodable tail. Promote
                // the existing identity owner instead of racing it with a second decoder.
                missingRehydrateFlight.enteredIdleCompletionIntent.set(true)
                wakeStrictAdjacentExactRehydrate(
                    path,
                    missingPage.manifestDigest,
                    missingPage.sourceIndex,
                )
            }
            if (pendingDelivery && missingRehydrateIdentity.isNotEmpty()) {
                // postDecodeResult owns the pending-width marker before its main publication.
                // If lifecycle/motion invalidates that publication after the decode owner has
                // retired, no rehydrate flight remains and the marker is only a tombstone. The
                // physical blocker path already audits this ordering; idle entered-episode
                // completion needs the same condition edge or one slow source can leave every
                // later pixel parked forever despite all exact bytes being resident.
                scheduleBlockedForwardPendingDeliveryAudit(
                    missingIndex,
                    missingPage,
                    missingRehydrateIdentity,
                    enteredCompletionPath = path,
                )
            }
            postEnteredExactEpisodePixelCompletion(
                path,
                NTK_ENTERED_EXACT_PIXEL_COMPLETION_STEP_MS,
            )
            return
        }
        if (strictAdjacentBodyDescriptor(missingPage) == null) {
            // Normally the descriptor callback re-enters this drain. Its callback can, however,
            // run just before the final registry publication becomes visible, leaving no later
            // event. Relinquish the fast owner and retain one slow, deduplicated audit edge.
            enteredExactEpisodePixelCompletionPaths.remove(path)
            scheduleEnteredExactEpisodePixelCompletionAudit(path)
            return
        }

        try {
            decode.execute {
                val failure = AtomicReference<Throwable?>(null)
                val batch = prepareAdjacentRunwayDrawableBatch(
                    startIndex = missingIndex,
                    refs = listOf(missingPage),
                    reason = "entered_exact_episode_pixel_completion",
                    requireStrictDescriptor = true,
                    enteredIdleCompletionIntent = true,
                    failureSink = failure,
                )
                if (batch == null) {
                    if (failure.get() is NtkPhysicalMotionDecodeDeferredException) {
                        postEnteredExactEpisodePixelCompletion(
                            path,
                            NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS,
                        )
                    } else {
                        enteredExactEpisodePixelCompletionPaths.remove(path)
                        holdOrRecoverAdjacentStrictSource(missingPage.manga)
                    }
                    return@execute
                }
                val posted = main.post {
                    val currentIndex = currentPageIndex(missingPage, missingIndex)
                    val currentPage = pageRef(currentIndex)
                    if (!cancelled.get() && latestEnteredExactEpisodePath.get() == path &&
                        currentIndex >= 0 && currentPage === missingPage
                    ) {
                        commitAdjacentRunwayDrawableBatch(
                            rebindAdjacentRunwayDrawableBatch(
                                batch,
                                currentIndex,
                                listOf(currentPage),
                            ),
                        )
                        postEnteredExactEpisodePixelCompletion(
                            path,
                            NTK_ENTERED_EXACT_PIXEL_COMPLETION_STEP_MS,
                        )
                    } else {
                        recycleAdjacentRunwayDrawableBatch(batch)
                        enteredExactEpisodePixelCompletionPaths.remove(path)
                    }
                }
                if (!posted) {
                    recycleAdjacentRunwayDrawableBatch(batch)
                    enteredExactEpisodePixelCompletionPaths.remove(path)
                }
            }
        } catch (_: RejectedExecutionException) {
            enteredExactEpisodePixelCompletionPaths.remove(path)
        }
    }

    private fun remainingAdjacentRunwayRetryKey(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String
    ): String {
        val key = publishKey.ifEmpty { episodeAppendKey(target) }
        return "remaining|$key|${refs.size}"
    }

    private fun shouldDeferAdjacentRunwayBehindActiveRemaining(target: Manga): Boolean {
        val targetPath = activeRemainingAdjacentRunwayTargetPath(target)
        if (targetPath.isEmpty()) return false
        // Episode structure must stay canonical even while input is idle. If A's first four
        // images are visible and A still owns a remaining suffix, inserting B's runway first
        // interleaves A/B/A. The viewport then sits inside B and A's suffix is classified as
        // offscreen forever. Metadata for B may still be resolved independently, but no B page is
        // published until A's complete suffix has been appended.
        for (path in activeRemainingAdjacentRunwayTargetPaths) {
            if (path.isNotEmpty() && path != targetPath) return true
        }
        return false
    }

    private fun markActiveRemainingAdjacentRunwayTarget(target: Manga) {
        val path = activeRemainingAdjacentRunwayTargetPath(target)
        if (path.isNotEmpty()) activeRemainingAdjacentRunwayTargetPaths.add(path)
    }

    private fun clearActiveRemainingAdjacentRunwayTarget(target: Manga) {
        val path = activeRemainingAdjacentRunwayTargetPath(target)
        if (path.isNotEmpty()) {
            cancelAdjacentStrictDescriptorWaitWatchdog(path)
            cancelAdjacentStrictRecoveryBindDeadline(path)
            activeRemainingAdjacentRunwayTargetPaths.remove(path)
            parkedAdjacentRemainderAppends.remove(path)
            pendingRemainingAdjacentRunwayAppends.remove(path)
            waitingStrictRemainingAdjacentAppends.remove(path)
            strictRemainingAdjacentWakeLatch.cancel(path)
            nearViewportParkedAdjacentWakePaths.remove(path)
            scheduledRemainingAdjacentRunwayRetries.cancelPath(path)?.let { scheduled ->
                main.removeCallbacks(scheduled.token)
            }
        }
    }

    private fun activeRemainingAdjacentRunwayTargetPath(target: Manga): String {
        return target.ntkEpisodePath?.trim().orEmpty().ifEmpty { episodeAppendKey(target) }
    }

    private fun remainingAdjacentRunwayAppendMinRetryMs(target: Manga): Long {
        return if (
            isImmediateNtkGeneratedUx() &&
            isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)
        ) {
            if (isDirectWifiStrictAdjacentRunwayProfile(target)) {
                val requiredInitialRunway = requiredInitialAdjacentRunwayPages(target)
                val installedSourceCount = installedAdjacentRunwaySourceIndexes(target).size
                if (installedSourceCount in 1 until requiredInitialRunway &&
                    !NtkReaderTransferPacer.isPhysicalMotionActive() &&
                    !viewportBusy.get() &&
                    physicalTouchQuietRemainingMs(
                        NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS
                    ) <= 0L
                ) {
                    // The predecessor is already fully drawable and page zero of B is attached.
                    // Retain the normal 128 ms foreground grace only after physical input is
                    // quiet. An active fling/touch keeps the existing 180 ms protection so this
                    // bounded adjacent decode cannot change current-episode scroll response.
                    return NTK_ADJACENT_FOREGROUND_STREAM_RECHECK_MS
                }
            }
            if (isViewportInsideEpisode(target) &&
                !NtkReaderTransferPacer.isPhysicalMotionActive() &&
                !viewportBusy.get() &&
                physicalTouchQuietRemainingMs(
                    NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS
                ) <= 0L
            ) {
                return NTK_ADJACENT_FOREGROUND_STREAM_RECHECK_MS
            }
            val physicalQuietMs =
                physicalTouchQuietRemainingMs(NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS)
            if (NtkReaderTransferPacer.isPhysicalMotionActive() ||
                viewportBusy.get() || physicalQuietMs > 0L
            ) {
                return maxOf(
                    NTK_APPEND_REMAINING_RUNWAY_ACTIVE_RETRY_MS,
                    physicalQuietMs
                )
            }
            NTK_ADJACENT_FOREGROUND_STREAM_RECHECK_MS
        } else {
            NTK_ADJACENT_APPEND_STRUCTURE_INSERT_RECHECK_MS
        }
    }

    private fun remainingAdjacentRunwayPublishPages(
        target: Manga,
        atomicTailReadyRefCount: Int,
        nextSourceRefCount: Int,
    ): Int {
        if (isDirectWifiStrictAdjacentRunwayProfile(target)) {
            val requiredInitialRunway = requiredInitialAdjacentRunwayPages(target)
            val installedSourceCount = installedAdjacentRunwaySourceIndexes(target).size
            if (installedSourceCount in 1 until requiredInitialRunway) {
                // Source zero can own two auto-cut display refs. Keep the initial source-page
                // runway bounded without truncating either side of its next source cohort. Manhwa
                // sources are paced one cohort at a time; webtoon retains its native atomic tail.
                return if (NtkStripDigests.normalizeEpisodePath(
                        target.ntkEpisodePath.orEmpty(),
                    ).startsWith("/manhwa/")
                ) {
                    nextSourceRefCount.coerceAtLeast(1)
                } else {
                    atomicTailReadyRefCount
                }
            }
            if (hostExactNativeSurfaceStorageEnabled) {
                // The fixed host pool can reclaim only identities which have crossed the
                // Session-to-Surface ownership seam. Decoding several source pages into one
                // unpublished batch makes every completed page invisible to pressure while a
                // later page in that same batch waits for their slots: neither side can advance.
                // Publish one complete source cohort at a time (including all auto-cut display
                // refs for that source), then let the ordinary exact Surface lifecycle retire it
                // before the next cohort reserves storage. This is a pool ownership invariant,
                // independent of input activity, chapter length, or any title-specific shape.
                return nextSourceRefCount.coerceAtLeast(1)
            }
        }
        return if (isActiveGeneratedTouchOrQuiet() || viewportBusy.get()) {
            // The initial p0-p4 cohort is already attached atomically.  Once the viewport enters
            // that episode, publish at most one additional decoded page per moving-input turn.
            // Multi-page suffix batches can expose structure ahead of exact pixels during a fast
            // traversal, so coalescing belongs at the offscreen view-publication boundary.
            NTK_APPEND_REMAINING_RUNWAY_ACTIVE_PUBLISH_PAGES
        } else if (isInitialTailAdjacentPreappendTarget(target)) {
            NTK_APPEND_REMAINING_RUNWAY_PUBLISH_PAGES
        } else {
            NTK_APPEND_REMAINING_RUNWAY_PUBLISH_PAGES
        }
    }

    private fun remainingAdjacentRunwayAppendDelayMs(): Long {
        if (!isNtkSource(manga, title)) return 0L
        if (isImmediateNtkGeneratedUx()) {
            return 0L
        }
        return maxOf(
            readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS),
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS),
            if (viewportBusy.get()) NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS else 0L
        )
            .coerceAtLeast(0L)
    }

    private fun initialAdjacentRunwayAppendDelayMs(): Long {
        if (!isImmediateNtkGeneratedUx()) return remainingAdjacentRunwayAppendDelayMs()
        return 0L
    }

    private fun shouldDeferDirectWifiAdjacentStructurePublication(target: Manga): Boolean {
        val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        // Once Surface has reported the real clamped end of this target's exact predecessor, the
        // minimum entry runway is no longer speculative structure. Repeated forward swipes cannot
        // create a motion-idle gap at that coordinate, so retaining the generic motion deferral
        // would keep a verified next episode private forever. Identity, claim revision, body
        // authority and atomic publication checks remain unchanged below this scheduling gate.
        if (isPhysicalBoundaryDemandingAdjacentTarget(target)) return false
        return NtkAdjacentRunwayPreparationPolicy.shouldDeferAtomicStructurePublication(
            hostGpuEmulatorRuntime = hostGpuEmulatorRuntime,
            directWifiStrictAdjacent = isDirectWifiStrictAdjacentRunwayProfile(target),
            supportedEpisodePath = path.startsWith("/manhwa/") || path.startsWith("/webtoon/"),
            foregroundMotionActive = NtkReaderTransferPacer.isPhysicalMotionActive(),
            viewportBusy = viewportBusy.get(),
            physicalQuietRemainingMs = physicalTouchQuietRemainingMs(
                NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS,
            ),
        )
    }

    fun isPhysicalBoundaryDemandingForwardAdjacent(target: Manga?): Boolean =
        isPhysicalBoundaryDemandingAdjacentTarget(target)

    private fun isPhysicalBoundaryDemandingAdjacentTarget(target: Manga?): Boolean {
        if (target == null || cancelled.get()) return false
        val targetPath = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath.orEmpty(),
        )
        if (targetPath.isEmpty()) return false
        val predecessorPath = forwardAdjacentCompletionTargetHistory[targetPath]
            ?: adjacentStrictPredecessorPaths[targetPath]
            ?: return false
        val selected = currentForwardAdjacentCompletionTargetClaim(predecessorPath)
            ?: return false
        if (!selected.targetEpisodePath.equals(targetPath, ignoreCase = true)) return false
        val boundary = latestPhysicalForwardBoundaryPage.get() ?: return false
        if (boundary.transitionTitle != null || boundary.sourceIndex < 0) return false
        val boundaryPath = NtkStripDigests.normalizeEpisodePath(
            boundary.manga.ntkEpisodePath.orEmpty(),
        )
        if (!boundaryPath.equals(predecessorPath, ignoreCase = true)) return false
        val predecessorPageCount = strictExactLaunchSeal
            ?.takeIf { seal -> seal.matchesEpisodePath(predecessorPath) }
            ?.pageCount
            ?: adjacentStrictSourceClaims[predecessorPath]?.pageCount
            ?: return false
        // A drawable-prefix clamp on any ordinary current page also records a physical forward
        // intent. Only the exact canonical tail can authorize adjacent p0 to bypass pointer quiet;
        // otherwise source 3 can accidentally promote the next chapter under active input.
        if (boundary.sourceIndex != predecessorPageCount - 1) return false
        return publishedPageIndex.get().any { current -> current === boundary }
    }

    private fun appendRemainingAdjacentRunwayRefs(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String,
        warm: Boolean
    ) {
        val activePath = activeRemainingAdjacentRunwayTargetPath(target)
        waitingStrictRemainingAdjacentAppends.remove(activePath)
        pendingRemainingAdjacentRunwayAppends.remove(activePath)
        parkedAdjacentRemainderAppends.remove(activePath)
        scheduledRemainingAdjacentRunwayRetries.cancelPath(activePath)?.let { scheduled ->
            main.removeCallbacks(scheduled.token)
        }
        cancelAdjacentStrictDescriptorWaitWatchdog(activePath)
        cancelAdjacentStrictRecoveryBindDeadline(activePath)
        val activeRefs = refreshRemainingAdjacentRunwayRefs(target, refs)
        if (cancelled.get() || activeRefs.isEmpty()) {
            clearActiveRemainingAdjacentRunwayTarget(target)
            clearPendingAdjacentAppendPublish(publishKey)
            return
        }
        if (isAdjacentDrawableBatchPublicationPending()) {
            // A source-ready event can enter this method while the preceding decoded cohort is
            // waiting on main for its Session -> Activity -> Surface transaction. Appending the
            // next cohort now changes structuralPageCount underneath that transaction: Activity
            // correctly rejects both snapshots and the episode is left with a permanent source
            // gap. Keep only the latest identity-equivalent redrive for this episode and run it
            // after the current structure owner has completed its external publication.
            val path = activeRemainingAdjacentRunwayTargetPath(target)
            if (path.isNotEmpty()) {
                pendingRemainingAdjacentRunwayAppends[path] =
                    ParkedAdjacentRemainderAppend(target, activeRefs, publishKey, warm)
                dispatchWhenStructureStable(
                    Runnable {
                        val waiting = pendingRemainingAdjacentRunwayAppends.remove(path)
                            ?: return@Runnable
                        scheduleRemainingAdjacentRunwayAppend(
                            waiting.target,
                            waiting.refs,
                            waiting.publishKey,
                            waiting.warm,
                        )
                    },
                )
            } else {
                scheduleRemainingAdjacentRunwayAppend(target, activeRefs, publishKey, warm)
            }
            return
        }
        if (isAdjacentStrictRecoveryExhausted(target)) {
            // Terminal exact recovery is a retained fail-closed state, not permission to adopt a
            // generic cached prefix on a stale lifecycle/control redrive.
            clearActiveRemainingAdjacentRunwayTarget(target)
            clearPendingAdjacentAppendPublish(publishKey)
            return
        }
        val entryStrictPath = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath.orEmpty(),
        )
        val entryStrictClaim = adjacentStrictSourceClaims[entryStrictPath]
        if (entryStrictClaim != null &&
            !isAdjacentStrictSourceClaimLive(entryStrictPath, entryStrictClaim)
        ) {
            // A terminal/token-invalid tombstone must reach exact retirement before offscreen or
            // active-input gates can park this turn under a generic timer.
            recoverAdjacentStrictDescriptorFailure(
                target = target,
                refs = activeRefs,
                publishKey = publishKey,
                warm = warm,
                owner = AdjacentStrictDecodeFailureOwner(entryStrictPath, entryStrictClaim),
                reason = "descriptor_wait_dead_claim",
            )
            return
        }
        if (parkAdjacentStrictRecoveryAwaitingReplacement(
                target = target,
                refs = activeRefs,
                publishKey = publishKey,
                warm = warm,
            )
        ) {
            return
        }
        if (parkStrictOwnedOffscreenAdjacentRemainder(
                target = target,
                refs = activeRefs,
                publishKey = publishKey,
                warm = warm,
            )
        ) {
            return
        }
        if (parkImmutableStrictOffscreenAdjacentRemainder(
                target = target,
                refs = activeRefs,
                publishKey = publishKey,
                warm = warm,
            )
        ) {
            return
        }
        val boundedDecodedRunwayReady = shouldParkHostGpuAdjacentWebtoonRemainder(target)
        if (boundedDecodedRunwayReady ||
            shouldDeferRemainingAdjacentRunwayForActiveInput(target, activeRefs)
        ) {
            if (boundedDecodedRunwayReady) {
                parkHostGpuAdjacentWebtoonRemainder(
                    target,
                    activeRefs,
                    publishKey,
                    warm,
                )
                return
            }
            val preparedAndParked = prepareAndParkOffscreenAdjacentRemainderIfIdle(
                target,
                activeRefs,
                publishKey,
                warm,
            )
            if (!preparedAndParked) {
                scheduleRemainingAdjacentRunwayAppend(target, activeRefs, publishKey, warm)
            }
            maybeLogAdjacentCurrentGate(
                "append_adjacent_runway_remaining_defer_offscreen_active",
                target,
                "anchor=${currentViewportAnchor.get()},refs=${activeRefs.size}," +
                    "preparedAndParked=$preparedAndParked",
            )
            return
        }
        var appendable: List<PageRef> = emptyList()
        var remainingCandidates: List<PageRef> = emptyList()
        var startIndex = -1
        var total = 0
        var waitingCandidates: List<PageRef>? = null
        var candidateSnapshot: List<PageRef> = emptyList()
        var candidateSourceGapFirst = -1
        var candidateInstalledMax = -1
        var structurePublishOwner: AtomicBoolean? = null
        var drawablePublication: AdjacentDrawableBatchPublication? = null
        synchronized(pagesLock) {
            if (!containsEpisodeForAppendLocked(target)) {
                Log.d(
                    TAG,
                    "append_adjacent_runway_remaining_skip_missing targetId=${target.id} " +
                        "path=${target.ntkEpisodePath}"
                )
                clearActiveRemainingAdjacentRunwayTarget(target)
                clearPendingAdjacentAppendPublish(publishKey)
                return
            }
            val snapshot = appendableRemainingAdjacentRunwayRefsLocked(target, activeRefs)
            candidateSnapshot = snapshot.refs
            candidateSourceGapFirst = snapshot.sourceGapFirst
            candidateInstalledMax = snapshot.maxInstalledSourceIndex
        }
        if (candidateSnapshot.isEmpty()) {
            if (candidateSourceGapFirst >= 0) {
                // A dead strict source can leave a refreshed suffix whose first canonical slot is
                // beyond the missing body. Recover/retire that exact generation before requeueing;
                // otherwise the source-gap loop itself becomes a permanent livelock.
                val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
                val claim = adjacentStrictSourceClaims[path]
                val strictRecoveryKnown = claim != null ||
                    synchronized(adjacentStrictSourceClaimLock) {
                        adjacentStrictRecoveryStates[path] != null
                    }
                if (strictRecoveryKnown) {
                    recoverAdjacentStrictDescriptorFailure(
                        target = target,
                        refs = refs,
                        publishKey = publishKey,
                        warm = warm,
                        owner = claim?.let { AdjacentStrictDecodeFailureOwner(path, it) },
                        reason = "descriptor_source_gap:$candidateSourceGapFirst",
                    )
                } else {
                    // A genuinely generic suffix retains its existing bounded cache/network retry.
                    scheduleRemainingAdjacentRunwayAppend(target, refs, publishKey, warm)
                }
                Log.d(
                    TAG,
                    "append_adjacent_runway_remaining_retry_source_gap targetId=${target.id} " +
                        "path=${target.ntkEpisodePath} installedMax=$candidateInstalledMax " +
                        "candidateFirst=$candidateSourceGapFirst refs=${refs.size}"
                )
                return
            }
            clearActiveRemainingAdjacentRunwayTarget(target)
            clearPendingAdjacentAppendPublish(publishKey)
            return
        }
        // Once an exact adjacent tail has been identified, keep that decision immutable for this
        // append turn. A terminal source can retire its live authority while an already queued
        // append is waking up; re-evaluating the mutable authority at that point used to let the
        // stale turn consume a generic cached drawable and pair it with the new exact manifest.
        // Besides losing ownership, that mixed proof used to throw from the publication data class
        // and kill the reader process. Exact refs therefore remain descriptor-only until this turn
        // either publishes one coherent batch or rolls back and joins strict recovery.
        val strictExactDescriptorWaitOwned =
            requiresStrictExactRemainingAdjacentRunway(candidateSnapshot)
        if (!strictExactDescriptorWaitOwned) {
            val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
            val rejectedClaim = adjacentStrictSourceClaims[path]
            if (rejectedClaim != null) {
                // Any retained strict claim is fail-closed. A live claim means these refs failed
                // its exact identity gate; a dead terminal/token-invalid claim is the tombstone
                // needed by holdOrRecoverAdjacentStrictSource to retire that exact generation.
                // Neither state permits this turn to consume a generic cached body.
                val rejectionReason = if (
                    isAdjacentStrictSourceClaimLive(path, rejectedClaim)
                ) {
                    "descriptor_wait_identity_rejected"
                } else {
                    "descriptor_wait_dead_claim"
                }
                recoverAdjacentStrictDescriptorFailure(
                    target = target,
                    refs = activeRefs,
                    publishKey = publishKey,
                    warm = warm,
                    owner = AdjacentStrictDecodeFailureOwner(path, rejectedClaim),
                    reason = rejectionReason,
                )
                return
            }
            if (parkAdjacentStrictRecoveryAwaitingReplacement(
                    target = target,
                    refs = activeRefs,
                    publishKey = publishKey,
                    warm = warm,
                )
            ) {
                // A removed claim plus awaiting exact recovery is still strict-owned. This check
                // must precede readyCount so a generic cached prefix cannot escape in the gap.
                return
            }
            if (isAdjacentStrictRecoveryExhausted(target)) {
                clearActiveRemainingAdjacentRunwayTarget(target)
                clearPendingAdjacentAppendPublish(publishKey)
                return
            }
        }
        // Descriptor authority remains sticky for the entire admitted turn on every transport.
        // Direct-Wi-Fi only affects native batch publication, not whether a generic cache may
        // replace a generation-bound body after the readiness snapshot.
        val strictExactDescriptorOnly = strictExactDescriptorWaitOwned
        val directWifiNativeExactRendering = strictExactDescriptorWaitOwned &&
            isDirectWifiStrictAdjacentRunwayProfile(target)
        val readyCount = if (strictExactDescriptorWaitOwned) {
            candidateSnapshot.takeWhile { strictAdjacentBodyDescriptor(it) != null }.size
        } else {
            adjacentRunwayPublishablePrefixCount(candidateSnapshot)
        }
        val atomicTailReadyRefCount = directWifiAdjacentAtomicRunwayTailReadyRefCount(
            target,
            candidateSnapshot,
        )
        val nextSourceRefCount = candidateSnapshot.firstOrNull()?.sourceIndex?.let { sourceIndex ->
            candidateSnapshot.takeWhile { it.sourceIndex == sourceIndex }.size
        } ?: 1
        if (readyCount < atomicTailReadyRefCount) {
            waitingCandidates = candidateSnapshot
        } else {
            // Publish only a contiguous, already cached prefix in bounded atomic batches. Waiting
            // for every remaining page of a large volume made the physical list stop after its
            // three-page runway even though many following pages were already drawable.
            val publishCount = if (isImmediateNtkGeneratedUx()) {
                minOf(
                    readyCount,
                    remainingAdjacentRunwayPublishPages(
                        target,
                        atomicTailReadyRefCount,
                        nextSourceRefCount,
                    ),
                )
            } else {
                readyCount
            }
            val wantedIdentities = HashSet<String>(publishCount)
            candidateSnapshot.take(publishCount).forEach { wantedIdentities.add(runwayPageRefIdentity(it)) }
            synchronized(pagesLock) {
                if (!containsEpisodeForAppendLocked(target)) {
                    Log.d(
                        TAG,
                        "append_adjacent_runway_remaining_skip_missing_after_ready targetId=${target.id} " +
                            "path=${target.ntkEpisodePath}"
                    )
                    clearActiveRemainingAdjacentRunwayTarget(target)
                    clearPendingAdjacentAppendPublish(publishKey)
                    return
                }
                val activeCandidates =
                    appendableRemainingAdjacentRunwayRefsLocked(target, activeRefs).refs
                if (activeCandidates.isEmpty()) {
                    clearActiveRemainingAdjacentRunwayTarget(target)
                    clearPendingAdjacentAppendPublish(publishKey)
                    return
                }
                appendable = activeCandidates
                    .filter { wantedIdentities.contains(runwayPageRefIdentity(it)) }
                    .take(publishCount)
                if (appendable.isEmpty()) {
                    waitingCandidates = activeCandidates
                    return@synchronized
                }
                val appended = appendable.mapTo(HashSet()) { runwayPageRefIdentity(it) }
                remainingCandidates = activeCandidates.filter { runwayPageRefIdentity(it) !in appended }
                startIndex = pages.size
                structurePublishOwner = beginOwnedAppendOnlyStructurePublish(startIndex)
                drawablePublication = beginAdjacentDrawableBatchPublication(appendable)
                appendable.forEachIndexed { offset, page -> page.pageIndex = startIndex + offset }
                pages.addAll(appendable)
                total = pages.size
                capturePublishedPageIndexLocked()
            }
        }
        if (startIndex >= 0) clearPageStateFromIndex(startIndex, appendOnlyTail = true)
        waitingCandidates?.let { candidates ->
            if (strictExactDescriptorWaitOwned) {
                // A descriptor-only candidate is still an unstarted physical source page.  The
                // adjacent strict transport deliberately owns only the p0..p4 runway until the
                // reader actually enters that episode.  Merely polling strictAdjacentBodyDescriptor
                // here never tells that transport that the viewport crossed the boundary, so its
                // p5+ workset stays sealed forever and the bottom remains clamped at p4. Route the
                // wait through the normal strict-owner fetch seam: it preserves exact ownership,
                // emits the one-shot viewport activation, and refills the already-bound source
                // session without launching a generic duplicate.
                startRemainingAdjacentRunwayFileFetches(
                    target,
                    candidates,
                    activeRefs,
                    publishKey,
                    warm,
                )
                if (!isAdjacentStrictRecoveryExhausted(target)) {
                    // Re-arm the body-publication wake after every failed descriptor snapshot.
                    // Registration followed by an exact readiness/identity recheck closes both
                    // sides of the callback race, so a live source has no periodic retry owner.
                    // Source terminal events use this same wake and enter bounded claim recovery.
                    val waitingPath = activeRemainingAdjacentRunwayTargetPath(target)
                    if (waitingPath.isNotEmpty()) {
                        pendingRemainingAdjacentRunwayAppends.remove(waitingPath)
                        scheduledRemainingAdjacentRunwayRetries.cancelPath(waitingPath)
                            ?.let { scheduled -> main.removeCallbacks(scheduled.token) }
                        val waiting = ParkedAdjacentRemainderAppend(
                            target = target,
                            refs = activeRefs,
                            publishKey = publishKey,
                            warm = warm,
                            expectedFirstMissingPageIdentity = candidates
                                .getOrNull(readyCount)
                                ?.let(::runwayPageRefIdentity),
                        )
                        waitingStrictRemainingAdjacentAppends[waitingPath] = waiting
                        armAdjacentStrictDescriptorWaitWatchdog(waitingPath, waiting)
                        deferStrictRemainingAdjacentWakeAfterRegistration(
                            waitingPath,
                            waiting,
                            target,
                            activeRefs,
                            exactDescriptorWait = true,
                        )
                    }
                } else {
                    clearActiveRemainingAdjacentRunwayTarget(target)
                    clearPendingAdjacentAppendPublish(publishKey)
                }
                Log.d(
                    TAG,
                    "append_adjacent_exact_runway_wait_descriptor path=${target.ntkEpisodePath} " +
                        "ready=$readyCount required=$atomicTailReadyRefCount candidates=${candidates.size}",
                )
                return
            }
            val waitingPath = activeRemainingAdjacentRunwayTargetPath(target)
            if (waitingPath.isNotEmpty() && adjacentStrictSourceClaims.containsKey(waitingPath)) {
                val waiting = ParkedAdjacentRemainderAppend(
                    target = target,
                    refs = activeRefs,
                    publishKey = publishKey,
                    warm = warm,
                )
                waitingStrictRemainingAdjacentAppends[waitingPath] = waiting
                deferStrictRemainingAdjacentWakeAfterRegistration(
                    waitingPath,
                    waiting,
                    target,
                    activeRefs,
                )
            }
            val fetchScheduled = startRemainingAdjacentRunwayFileFetches(
                target,
                candidates,
                activeRefs,
                publishKey,
                warm
            )
            if (isAdjacentStrictRecoveryExhausted(target)) {
                clearActiveRemainingAdjacentRunwayTarget(target)
                clearPendingAdjacentAppendPublish(publishKey)
                return
            }
            if (!fetchScheduled && !hasPendingRemainingAdjacentRunwayFileFetch(target, candidates, publishKey)) {
                startAdjacentForegroundStreamsForRefs(
                    target,
                    candidates,
                    ReaderSurfaceView.DIRECTION_NEXT,
                    asyncLaunch = true
                )
            }
            if (parkAdjacentStrictRecoveryAwaitingReplacement(
                    target = target,
                    refs = activeRefs,
                    publishKey = publishKey,
                    warm = warm,
                )
            ) {
                return
            }
            scheduleRemainingAdjacentRunwayAppend(target, activeRefs, publishKey, warm)
            maybeLogAdjacentCurrentGate(
                "append_adjacent_runway_remaining_wait_ready",
                target,
                "candidates=${candidates.size}",
            )
            return
        }
        if (appendable.isEmpty()) {
            clearActiveRemainingAdjacentRunwayTarget(target)
            clearPendingAdjacentAppendPublish(publishKey)
            return
        }
        val activeDrawablePublication = checkNotNull(drawablePublication)
        val remainingRefs = remainingCandidates
        val strictDecodeFailureOwner = if (strictExactDescriptorWaitOwned) {
            val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
            adjacentStrictSourceClaims[path]?.takeIf { claim ->
                adjacentStrictDescriptorBindingTokens[path] === claim.descriptorBindingToken &&
                    isAdjacentStrictSourceClaimLive(path, claim)
            }?.let { claim ->
                AdjacentStrictDecodeFailureOwner(path, claim)
            }
        } else {
            null
        }
        val drawablePreparationFailure = AtomicReference<Throwable?>(null)
        val drawableBatch = prepareAdjacentRunwayDrawableBatch(
            startIndex,
            appendable,
            "append_runway_remaining_publish",
            requireStrictDescriptor = strictExactDescriptorOnly,
            failureSink = drawablePreparationFailure,
        )
        if (drawableBatch == null) {
            rollbackAdjacentRunwayStructure(startIndex, appendable)
            finishOwnedStructurePublish(structurePublishOwner)
            finishAdjacentDrawableBatchPublication(activeDrawablePublication)
            if (drawablePreparationFailure.get() is NtkPhysicalMotionDecodeDeferredException) {
                // This is scheduler backpressure, not a body/descriptor failure. Returning the
                // owner to the normal retry registry lets the queued busy->idle WindowEvent run;
                // blocking ReaderControl here would put the release edge behind its own waiter.
                scheduleRemainingAdjacentRunwayAppend(target, activeRefs, publishKey, warm)
                Log.d(
                    TAG,
                    "append_adjacent_exact_decode_deferred_motion path=${target.ntkEpisodePath} " +
                        "refs=${appendable.size}",
                )
                return
            }
            if (strictExactDescriptorWaitOwned) {
                val failure = drawablePreparationFailure.get()
                if (cancelled.get()) {
                    clearActiveRemainingAdjacentRunwayTarget(target)
                    clearPendingAdjacentAppendPublish(publishKey)
                } else {
                    recoverAdjacentStrictDescriptorFailure(
                        target = target,
                        refs = activeRefs,
                        publishKey = publishKey,
                        warm = warm,
                        owner = strictDecodeFailureOwner.takeUnless {
                            isExpectedCancellation(failure)
                        },
                        reason = if (isExpectedCancellation(failure)) {
                            "descriptor_decode_cancelled"
                        } else {
                            "descriptor_decode_failed:${failure?.javaClass?.simpleName.orEmpty()}"
                        },
                    )
                }
            } else {
                startAdjacentForegroundStreamsForRefs(
                    target,
                    appendable,
                    ReaderSurfaceView.DIRECTION_NEXT,
                    asyncLaunch = true
                )
                scheduleRemainingAdjacentRunwayAppend(target, activeRefs, publishKey, warm)
            }
            Log.d(
                TAG,
                "append_adjacent_runway_remaining_wait_drawable_batch targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} candidates=${appendable.size}"
            )
            return
        }
        val exactRunwayPublication = directWifiAdjacentExactRunwayPublication(
            startIndex,
            total,
            drawableBatch,
        )
        val nativeExactBatchRequired =
            NtkStrictRemainingAdjacentDescriptorWaitPolicy.requiresNativeExactBatch(
                descriptorWaitOwned = directWifiNativeExactRendering,
                normalizedEpisodePath = NtkStripDigests.normalizeEpisodePath(
                    target.ntkEpisodePath.orEmpty(),
                ),
            )
        if (nativeExactBatchRequired && exactRunwayPublication == null) {
            rollbackAdjacentRunwayStructure(startIndex, appendable)
            recycleAdjacentRunwayDrawableBatch(drawableBatch)
            finishOwnedStructurePublish(structurePublishOwner)
            finishAdjacentDrawableBatchPublication(activeDrawablePublication)
            if (strictDecodeFailureOwner?.claim?.nativeExactPublicationRetrySpent
                    ?.compareAndSet(false, true) == true
            ) {
                scheduleRemainingAdjacentRunwayAppend(target, activeRefs, publishKey, warm)
            } else {
                val terminal = terminateAdjacentStrictLocalPublicationFailure(
                    target = target,
                    owner = strictDecodeFailureOwner,
                    reason = "native_exact_publication_invalid",
                )
                if (terminal) {
                    clearActiveRemainingAdjacentRunwayTarget(target)
                    clearPendingAdjacentAppendPublish(publishKey)
                } else {
                    scheduleRemainingAdjacentRunwayAppend(target, activeRefs, publishKey, warm)
                }
            }
            Log.w(
                TAG,
                "append_adjacent_exact_runway_invalid_publication path=${target.ntkEpisodePath} " +
                    "start=$startIndex refs=${appendable.size}",
            )
            return
        }
        if (
            remainingRefs.isNotEmpty() &&
            !(isImmediateNtkGeneratedUx() && (isActiveGeneratedTouchOrQuiet() || viewportBusy.get()))
        ) {
            startAdjacentForegroundStreamsForRefs(
                target,
                remainingRefs,
                ReaderSurfaceView.DIRECTION_NEXT,
                asyncLaunch = true
            )
        }
        if (shouldLogRateLimitedDiagnostic("append_adjacent_runway_remaining_inserted")) {
            Log.d(
                TAG,
                "append_adjacent_runway_remaining_inserted targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} inserted=${appendable.size} " +
                    "remaining=${remainingRefs.size} total=$total"
            )
        }
        val posted = main.post {
            try {
                if (cancelled.get()) {
                    recycleAdjacentRunwayDrawableBatch(drawableBatch)
                    return@post
                }
                val drawableCommitted = if (exactRunwayPublication != null) {
                    val externalClaim = claimDecodeResultsExternallyOwned(
                        drawableBatch.deliveries.map { it.result },
                    )
                    if (externalClaim == null) {
                        false
                    } else {
                        val accepted = try {
                            listener.onAdjacentExactRunwayBatchReady(exactRunwayPublication)
                        } catch (failure: Throwable) {
                            throw failure
                        }
                        if (accepted) {
                            commitAdjacentExactRunwayDrawableBatch(drawableBatch)
                        }
                        Log.d(
                            TAG,
                            "append_adjacent_exact_runway_publish path=${target.ntkEpisodePath} " +
                                "accepted=$accepted start=$startIndex total=$total " +
                                "sources=${exactRunwayPublication.pages.joinToString(",") { it.sourcePageIndex.toString() }}",
                        )
                        accepted
                    }
                } else {
                    listener.onPreparedAdjacentPagesAppended(total)
                    commitAdjacentRunwayDrawableBatch(drawableBatch)
                    true
                }
                if (!drawableCommitted) {
                    rollbackAdjacentRunwayStructure(startIndex, appendable)
                    recycleAdjacentRunwayDrawableBatch(drawableBatch)
                    if (!cancelled.get()) {
                        // Activity rejection is transactional: neither the exact tile batch nor
                        // its page-table suffix became authoritative. A concurrent lifecycle or
                        // structure turn may legitimately make the captured snapshot stale, so
                        // rebuild it after rollback instead of clearing the only remainder owner.
                        scheduleRemainingAdjacentRunwayAppend(
                            target,
                            activeRefs,
                            publishKey,
                            warm,
                        )
                    } else {
                        clearActiveRemainingAdjacentRunwayTarget(target)
                        clearPendingAdjacentAppendPublish(publishKey)
                    }
                    return@post
                }
                markExactAdjacentRunwayTelemetryIfReady(target)
                if (remainingRefs.isEmpty()) {
                    clearActiveRemainingAdjacentRunwayTarget(target)
                    clearPendingAdjacentAppendPublish(publishKey)
                    val activeAnchor = currentViewportAnchor.get()
                        .takeIf { it >= 0 }
                        ?: currentStartPage()
                    if (activeAnchor >= 0 && isViewportInsideEpisode(target)) {
                        // The appended episode has just become fully drawable. Do not wait for a
                        // later scroll callback to notice that completion; during ordinary
                        // reading that stale signal creates a multi-second blank boundary before
                        // the following episode.
                        maybeWarmCompletedForwardEpisode(activeAnchor, target)
                    }
                } else {
                    if (!tryHandoffDirectWifiAdjacentInitialRunwayTail(
                            target,
                            remainingRefs,
                            publishKey,
                            warm,
                        )
                    ) {
                        scheduleRemainingAdjacentRunwayAppend(target, remainingRefs, publishKey, warm)
                    }
                }
                if (warm && shouldWarmAppendedEpisode(startIndex)) {
                    if (isImmediateNtkGeneratedUx()) {
                        scheduleAppendSourcePrefetchAfterQuiet(
                            startIndex,
                            total,
                            "append_runway_remaining_source"
                        )
                    } else {
                        warmAppendedEpisode(startIndex, total)
                    }
                }
            } finally {
                finishOwnedStructurePublish(structurePublishOwner)
                finishAdjacentDrawableBatchPublication(activeDrawablePublication)
            }
        }
        if (!posted) {
            recycleAdjacentRunwayDrawableBatch(drawableBatch)
            clearActiveRemainingAdjacentRunwayTarget(target)
            clearPendingAdjacentAppendPublish(publishKey)
            finishOwnedStructurePublish(structurePublishOwner)
            finishAdjacentDrawableBatchPublication(activeDrawablePublication)
        }
    }

    private fun installedAdjacentRunwaySourceIndexes(target: Manga): Set<Int> =
        synchronized(pagesLock) {
            pages.asSequence()
                .filter { page ->
                    page.transitionTitle == null &&
                        page.sourceIndex >= 0 &&
                        looseSameEpisodeForAppend(page.manga, target) &&
                        (hasListenerDrawableDelivery(page.pageIndex) ||
                            hasDeliveredOrPendingDrawable(page.pageIndex))
                }
                .map { it.sourceIndex }
                .toSet()
        }

    private fun directWifiAdjacentAtomicRunwayTailReadyRefCount(
        target: Manga,
        candidates: List<PageRef>,
    ): Int {
        val requiredInitialRunway = requiredInitialAdjacentRunwayPages(target)
        val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        val installedSourceIndexes = installedAdjacentRunwaySourceIndexes(target)
        val requiredSourceCount = NtkDirectWifiAdjacentAtomicRunwayTailPolicy.requiredReadyCount(
            directWifiStrictAdjacent = isDirectWifiStrictAdjacentRunwayProfile(target),
            episodePath = path,
            requiredRunwayPageCount = requiredInitialRunway,
            installedSourceIndexes = installedSourceIndexes,
        )
        val requiredRefCount = NtkAdjacentRunwaySourceCohortPolicy.leadingRefCount(
            candidates.map { it.sourceIndex },
            requiredSourceCount,
        )
        // A truncated/stale candidate suffix cannot satisfy a source-count requirement merely
        // because it happens to contain that many display refs.
        return requiredRefCount.takeIf { it > 0 } ?: candidates.size + 1
    }

    private fun refreshRemainingAdjacentRunwayRefs(
        target: Manga,
        refs: List<PageRef>
    ): List<PageRef> {
        if (refs.isEmpty()) return refs
        if (!isImmediateNtkGeneratedUx()) return refs
        if (!isNtkSource(target, title)) return refs
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return refs
        val path = target.ntkEpisodePath?.trim().orEmpty()
        if (path.isEmpty()) return refs
        val firstKnownMissingPage = ReaderImageCache.knownNtkGeneratedFirstNotFoundPage(path)
        val knownValidCount = if (firstKnownMissingPage > 1) firstKnownMissingPage - 1 else Int.MAX_VALUE
        if (knownValidCount != Int.MAX_VALUE && target.ntkImageCount <= 0) {
            target.ntkImageCount = knownValidCount
            ReaderImageCache.rememberTrustedNtkImageApiCount(path, knownValidCount)
        }
        val cachedLatest = ReaderImageCache.earlyNtkImageUrls(path, 0L)
            .ifEmpty { ReaderImageCache.earlyNtkAppendImageUrls(path, 0L) }
        val latest = if (cachedLatest.isNotEmpty()) {
            cachedLatest
        } else if (isActiveGeneratedTouchOrQuiet() || viewportBusy.get()) {
            refs.mapNotNull { it.image }.filter { isNtkGeneratedImageUrl(it) }
        } else {
            target.getImgs(null)?.toList().orEmpty()
        }
        if (latest.isEmpty()) return refs
        val boundedLatest = if (knownValidCount == Int.MAX_VALUE) latest else latest.take(knownValidCount)
        val oldRefs = refs
            .filter { it.transitionTitle == null && it.sourceIndex >= 0 }
            .sortedWith(compareBy<PageRef> { it.sourceIndex }.thenBy { it.side })
        val sourceRepresentatives = oldRefs.groupBy { it.sourceIndex }
            .entries
            .sortedBy { it.key }
            .map { (_, sourceRefs) -> sourceRefs.first() }
        val refreshAssignments = NtkAdjacentRunwayRefreshPolicy.reconcile(
            existing = sourceRepresentatives.map { ref ->
                NtkAdjacentRunwayRefreshPolicy.Assignment(
                    sourceIndex = ref.sourceIndex,
                    image = ref.image.orEmpty(),
                )
            },
            latestImages = boundedLatest,
        )
        // Never rebuild a partial cache suffix as a fresh zero-based manifest. Keep the immutable
        // source slot, full-manifest identity and every unmentioned source carried by the original
        // PageRef, replacing only transport URLs with verified page-number mappings. Returning
        // only the partial replacement set lets a later callback publish p172 before a still
        // pending p166, permanently corrupting the physical page order.
        val refreshImagesBySource = refreshAssignments.associate { assignment ->
            assignment.sourceIndex to assignment.image
        }
        val refreshedAll = oldRefs.map { ref ->
            ref.copy(image = refreshImagesBySource[ref.sourceIndex] ?: ref.image)
        }
        if (refreshedAll.isEmpty()) return refs
        val installedRefIdentities = synchronized(pagesLock) {
            pages.asSequence()
                .filter { page ->
                    page.transitionTitle == null &&
                        page.sourceIndex >= 0 &&
                        looseSameEpisodeForAppend(page.manga, target)
                }
                .map { it.sourceIndex to it.side }
                .toHashSet()
        }
        val refreshed = refreshedAll.filter { (it.sourceIndex to it.side) !in installedRefIdentities }
        if (refreshed.isEmpty()) {
            Log.d(
                TAG,
                "append_adjacent_runway_remaining_refresh_complete targetId=${target.id} " +
                    "path=$path old=${refs.size} latest=${latest.size} " +
                    "installed=${installedRefIdentities.size}"
            )
            return emptyList()
        }
        val oldByIdentity = oldRefs.associateBy { it.sourceIndex to it.side }
        val changed = refreshed.any { ref ->
            oldByIdentity[ref.sourceIndex to ref.side]?.image != ref.image
        }
        if (!changed) return refs
        Log.d(
            TAG,
            "append_adjacent_runway_remaining_refresh_refs targetId=${target.id} " +
                "path=$path old=${refs.size} latest=${latest.size} refreshed=${refreshed.size} " +
                "first=${refreshed.firstOrNull()?.image?.substringAfterLast('/')}"
        )
        return refreshed
    }

    private fun shouldDeferRemainingAdjacentRunwayForActiveInput(
        target: Manga,
        refs: List<PageRef>,
    ): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        if (isDirectWifiStrictAdjacentRunwayProfile(target)) {
            val requiredProgressiveRunway = requiredInitialAdjacentRunwayPages(target)
            val installedSourceCount = installedAdjacentRunwaySourceIndexes(target).size
            if (installedSourceCount in 1 until requiredProgressiveRunway) {
                // p0 is the only structure the offscreen episode owns. Keep p1+ in the exact
                // encoded store until a real viewport anchor/first-frame proves episode entry;
                // an idle-looking app cannot observe an ACTION_DOWN still queued in Android.
                return NtkStrictAdjacentProgressiveRunwayPolicy.shouldParkIncompleteInitialTail(
                    viewportInsideEpisode = isViewportInsideEpisode(target),
                    foregroundMotionActive = NtkReaderTransferPacer.isPhysicalMotionActive() ||
                        viewportBusy.get() ||
                        physicalTouchQuietRemainingMs(
                            NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS,
                        ) > 0L,
                    physicalScrollEverStarted = physicalScrollEverStarted.get(),
                )
            }
        }
        // A live strict-claim snapshot normally enforces this same bound in
        // parkStrictOwnedOffscreenAdjacentRemainder(). Once a fully adopted exact source retires
        // that claim, however, its remaining descriptor callbacks can still arrive here. Preserve
        // the product invariant independently of claim lifetime: active input may advance the
        // current chapter, but never decode more than four canonical sources ahead in one burst.
        // Boundary callbacks wake the retained owner as the physical source frontier advances.
        if (isViewportInsideEpisode(target)) {
            val firstMissingSource = refs.firstOrNull { page ->
                page.transitionTitle == null && page.sourceIndex >= 0
            }?.sourceIndex ?: -1
            // This is a sliding source window, not idle completion work. A pause between real
            // swipes must not release the entire suffix; anchor changes wake the retained owner.
            return NtkStrictAdjacentProgressiveRunwayPolicy.shouldPark(
                viewportInsideEpisode = true,
                foregroundMotionActive = NtkReaderTransferPacer.isPhysicalMotionActive() ||
                    viewportBusy.get() ||
                    physicalTouchQuietRemainingMs(
                        NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS,
                    ) > 0L,
                currentSourceIndex = currentViewportSourceIndexForEpisode(target),
                firstMissingSourceIndex = firstMissingSource,
                forwardSourceRunway = NTK_STRICT_ACTIVE_FORWARD_SOURCE_RUNWAY,
            )
        }
        // Never extend the physical list underneath a real gesture/fling after the bounded initial
        // runway is complete. Waiting for input retirement prevents one fling from skipping an
        // episode that the viewport has not reached yet.
        if (NtkReaderTransferPacer.isPhysicalMotionActive() || viewportBusy.get()) return true
        if (physicalTouchQuietRemainingMs(NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS) > 0L) {
            return true
        }
        // Offscreen structure remains bounded to the atomic four-page runway. Its remaining pixels
        // may be prepared separately during idle, but pages must not become scrollable until the
        // user has actually entered this episode.
        return true
    }

    private fun parkStrictOwnedOffscreenAdjacentRemainder(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String,
        warm: Boolean,
    ): Boolean {
        if (!isDirectWifiStrictAdjacentRunwayProfile(target)) return false
        val viewportInsideEpisode = isViewportInsideEpisode(target)
        val requiredRunwayPages = NTK_STRICT_OFFSCREEN_PREPARED_RUNWAY_PAGES
        val prepared = strictAdjacentPreparedRunwaySnapshot(target, requiredRunwayPages)
            ?: return false
        val shouldPark = if (viewportInsideEpisode) {
            NtkStrictAdjacentProgressiveRunwayPolicy.shouldPark(
                    viewportInsideEpisode = true,
                    foregroundMotionActive = viewportBusy.get() ||
                        physicalTouchQuietRemainingMs(
                            NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS,
                        ) > 0L,
                    currentSourceIndex = currentViewportSourceIndexForEpisode(target),
                    firstMissingSourceIndex = refs.firstOrNull { page ->
                        page.transitionTitle == null && page.sourceIndex >= 0
                    }?.sourceIndex ?: -1,
                    forwardSourceRunway = NTK_STRICT_ACTIVE_FORWARD_SOURCE_RUNWAY,
                )
        } else {
            NtkStrictOffscreenRemainderParkPolicy.shouldPark(
                cancelled = cancelled.get(),
                directWifiStrictAdjacent = true,
                viewportInsideEpisode = false,
                episodePath = prepared.normalizedPath,
                claimLive = prepared.claimLive,
                requiredRunwayPages = requiredRunwayPages,
                orderedAttachedSourceIndexes = prepared.orderedAttachedSourceIndexes,
                liveSourceIndexes = prepared.liveSourceIndexes,
                recoverableSourceIndexes = prepared.recoverableSourceIndexes,
            )
        }
        if (!shouldPark) {
            return false
        }

        val path = prepared.normalizedPath
        val parked = ParkedAdjacentRemainderAppend(target, refs, publishKey, warm)
        val firstPark = parkedAdjacentRemainderAppends.put(path, parked) == null
        pendingRemainingAdjacentRunwayAppends.remove(path)
        waitingStrictRemainingAdjacentAppends.remove(path)
        scheduledRemainingAdjacentRunwayRetries.cancelPath(path)?.let { scheduled ->
            main.removeCallbacks(scheduled.token)
        }
        if (firstPark) {
            Log.d(
                TAG,
                "append_adjacent_strict_remainder_parked path=$path " +
                    "refs=${refs.size} runway=$requiredRunwayPages " +
                    "viewportInside=$viewportInsideEpisode " +
                    "viewportSource=${currentViewportSourceIndexForEpisode(target)}",
            )
        }
        // Register first, then recheck every state that could have changed while the proof and map
        // entry were being built. dispatchWhenStructureStable closes the pending->stable race; the
        // other event sources converge on the same one-owner wake below.
        if (isStructurePublishPending()) {
            dispatchWhenStructureStable(
                Runnable { wakeStrictRemainingAdjacentAppend(path) },
            )
        }
        val claim = adjacentStrictSourceClaims[path]
        val preparedStillCurrent = strictAdjacentPreparedRunwaySnapshot(
            target,
            requiredRunwayPages,
        ) != null
        if (claim == null || !isAdjacentStrictSourceClaimLive(path, claim) ||
            !preparedStillCurrent
        ) {
            wakeStrictRemainingAdjacentAppend(path)
        }
        return true
    }

    /**
     * A fully adopted strict transport may retire its mutable claim before the viewport reaches the
     * episode. Its PageRefs still carry the immutable manifest identity that created them. Never
     * reinterpret that exact suffix as a generic cache miss: doing so repeatedly leases the same
     * bounded source pages while the offscreen workset is intentionally sealed. Park the structural
     * owner without a timer; the viewport-near event resumes it and rebinds the exact source.
     */
    private fun parkImmutableStrictOffscreenAdjacentRemainder(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String,
        warm: Boolean,
    ): Boolean {
        if (isViewportInsideEpisode(target) || !hasImmutableStrictAdjacentManifestIdentity(refs)) {
            return false
        }
        val requiredInitialRunway = requiredInitialAdjacentRunwayPages(target)
        val installedInitialSources = installedAdjacentRunwaySourceIndexes(target)
            .count { sourceIndex -> sourceIndex in 0 until requiredInitialRunway }
        if (installedInitialSources < requiredInitialRunway) return false
        val path = activeRemainingAdjacentRunwayTargetPath(target)
        if (path.isEmpty()) return false
        val parked = ParkedAdjacentRemainderAppend(target, refs, publishKey, warm)
        val firstPark = parkedAdjacentRemainderAppends.put(path, parked) == null
        pendingRemainingAdjacentRunwayAppends.remove(path)
        waitingStrictRemainingAdjacentAppends.remove(path)
        scheduledRemainingAdjacentRunwayRetries.cancelPath(path)?.let { scheduled ->
            main.removeCallbacks(scheduled.token)
        }
        if (firstPark) {
            Log.d(
                TAG,
                "append_adjacent_exact_suffix_parked_by_manifest_identity path=$path refs=${refs.size}",
            )
        }
        return true
    }

    private fun hasImmutableStrictAdjacentManifestIdentity(refs: List<PageRef>): Boolean {
        val pages = refs.filter { page -> page.transitionTitle == null }
        val first = pages.firstOrNull() ?: return false
        val path = NtkStripDigests.normalizeEpisodePath(
            first.manga.ntkEpisodePath?.trim().orEmpty(),
        )
        val digest = first.manifestDigest
        val pageCount = first.manifestPageCount
        if (path.isEmpty() || digest.isNullOrBlank() || pageCount <= 0) return false
        return pages.all { page ->
            NtkStripDigests.normalizeEpisodePath(
                page.manga.ntkEpisodePath?.trim().orEmpty(),
            ) == path &&
                page.manifestDigest == digest &&
                page.manifestPageCount == pageCount &&
                page.sourceIndex in 0 until pageCount &&
                !page.canonicalAsset.isNullOrBlank()
        }
    }

    private fun currentViewportSourceIndexForEpisode(target: Manga): Int {
        val targetPath = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath?.trim().orEmpty(),
        )
        val targetClaim = targetPath.takeIf(String::isNotEmpty)
            ?.let(adjacentStrictSourceClaims::get)
        val hasPresentedExactAnchorProof = targetClaim != null &&
            targetClaim.firstActualFramePresented.get() &&
            isAdjacentStrictSourceClaimLive(targetPath, targetClaim)
        val snapshot = synchronized(pagesLock) {
            if (pages.isEmpty()) {
                return@synchronized Pair(
                    Triple(emptyList(), emptyList(), null),
                    -1,
                )
            }
            val anchor = currentViewportAnchor.get().coerceIn(0, pages.lastIndex)
            val physical = reportedPhysicalWindowLocked(
                fallbackAnchor = anchor,
                fallbackFirst = anchor,
                fallbackLast = anchor,
            )
            val physicalPages = physical.asSequence()
                .mapNotNull { index -> pages.getOrNull(index)?.let { page -> index to page } }
                .toList()
            val transitionCards = physicalPages.filter { (_, page) ->
                page.transitionTitle != null && looseSameEpisodeForAppend(page.manga, target)
            }
            val reportedPages = physicalPages.filter { (_, page) ->
                    page.transitionTitle == null && page.sourceIndex >= 0 &&
                        looseSameEpisodeForAppend(page.manga, target)
                }
            val boundary = latestPhysicalForwardBoundaryPage.get()
                ?.takeIf { page ->
                    page.transitionTitle == null && page.sourceIndex >= 0 &&
                        looseSameEpisodeForAppend(page.manga, target) &&
                        pages.any { current -> current === page }
                }
            val anchorPage = pages.getOrNull(anchor)
            val previouslyPresentedPhysicalAnchorSource = anchorPage
                ?.sourceIndex
                ?.takeIf { sourceIndex ->
                    hasPresentedExactAnchorProof &&
                        sourceIndex >= 0 &&
                        anchor in physical &&
                        anchorPage.transitionTitle == null &&
                        looseSameEpisodeForAppend(anchorPage.manga, target)
                }
                ?: -1
            Pair(
                Triple(reportedPages, transitionCards, boundary),
                previouslyPresentedPhysicalAnchorSource,
            )
        }
        // Reported geometry may include several unresolved placeholders whose guessed heights fit
        // in one viewport. They are not physical source progress. Consult Surface installation only
        // after releasing pagesLock, then use the highest exact drawable actually present.
        val reportedSource = snapshot.first.first.asSequence()
            .filter { (index, page) ->
                pageRef(index) === page &&
                    listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)
            }
            .maxOfOrNull { (_, page) -> page.sourceIndex }
            ?: 0.takeIf { snapshot.first.second.isNotEmpty() }
            ?: -1
        val boundarySource = snapshot.first.third
            ?.let { page ->
                val index = currentPageIndex(page, -1)
                page.sourceIndex.takeIf {
                    index >= 0 && listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)
                }
            }
            ?: -1
        return NtkDirectAdjacentViewportSourcePolicy.resolve(
            installedPhysicalSource = reportedSource,
            installedBoundarySource = boundarySource,
            previouslyPresentedPhysicalAnchorSource = snapshot.second,
        )
    }

    /**
     * Accepts the first exact compositor acknowledgement of an episode's physical tail. This is
     * earlier than a subsequent overscroll boundary callback, but stronger than speculative
     * retained/decode state: Surface has verified the immutable final-source identity, real bottom
     * pixels and defect-free native presentation. It may release only the already-bounded adjacent
     * gate; it never changes scroll or chooses a target.
     */
    fun onCleanPhysicalEpisodeTailAcknowledged(displayPageIndex: Int) {
        recordPhysicalForwardBoundaryEvidence(displayPageIndex)
    }

    /**
     * Accepts Surface's real clamped boundary callback. This lets a parked exact suffix advance
     * even when the numeric WindowEvent stops changing at the old list maximum. The PageRef
     * identity survives prefix compaction; stale evidence from another episode cannot match a
     * later target.
     */
    fun onPhysicalBoundaryReached(anchorPage: Int, direction: Int) {
        if (direction != ReaderSurfaceView.DIRECTION_NEXT) return
        recordPhysicalForwardBoundaryEvidence(anchorPage)
    }

    private fun recordPhysicalForwardBoundaryEvidence(anchorPage: Int) {
        if (cancelled.get()) return
        val evidence = publishedPageIndex.get().getOrNull(anchorPage)?.takeIf { page ->
            page.transitionTitle == null && page.sourceIndex >= 0
        } ?: return
        latestPhysicalForwardBoundaryPage.set(evidence)
        val path = NtkStripDigests.normalizeEpisodePath(
            evidence.manga.ntkEpisodePath.orEmpty(),
        )
        if (path.isNotEmpty()) {
            val selectedTarget = currentForwardAdjacentCompletionTargetClaim(path)
                ?.targetEpisodePath
            NtkStrictEpisodeDiscoveryCoordinator.releaseAdjacentPhysicalBoundaryDemand(
                path,
                selectedTarget,
                strictExactForegroundViewerGenerationAtCreation,
                strictExactViewerOwnerEpisodePathAtCreation,
            )
            // Continuous input deliberately keeps the entered-episode completion drain behind
            // the physical-motion fence.  The real Surface tail acknowledgement can therefore
            // be the first observer after every immutable source has already become drawable.
            // Boundary demand alone remains unable to open target network work; combine it with
            // the same all-source drawable proof used by the ordinary completion owner and the
            // already-reconciled exact target before releasing that one identity-bound flight.
            // This closes the HOME/resume lost-edge without relaxing the completion contract or
            // starting a numeric/list fallback during motion.
            if (selectedTarget != null && isEpisodeFullyDrawableForAdjacent(evidence.manga)) {
                val released = NtkStrictEpisodeDiscoveryCoordinator
                    .releaseAdjacentBodiesAfterPredecessorComplete(
                        path,
                        selectedTarget,
                        strictExactForegroundViewerGenerationAtCreation,
                        strictExactViewerOwnerEpisodePathAtCreation,
                    )
                releaseAdjacentStrictClaimsAfterPredecessorComplete(path)
                Log.d(
                    TAG,
                    "ntk_physical_tail_completed_body_gate_release predecessor=$path," +
                        "target=$selectedTarget,released=$released",
                )
            }
            wakeStrictRemainingAdjacentAppend(path)
        }
    }

    /**
     * Surface calls this only for the first missing body that stopped a real forward drag/fling.
     * Keep it outside the latest-only viewport mailbox: coalescing an ordinary frame must never
     * revoke the exact PageRef whose absence is currently holding the drawable-prefix fence.
     */
    fun onBlockedForwardPageRequested(index: Int) {
        if (cancelled.get() || index < 0) return
        val published = publishedPageIndex.get()
        val candidate = published.getOrNull(index)
        val adjacentIdentity = candidate?.let(::strictAdjacentRehydrateIdentity)
        val exactLaunch = candidate?.let(::isStrictExactLaunchPage) == true
        val page = candidate?.takeIf {
            it.transitionTitle == null && (adjacentIdentity != null || exactLaunch)
        } ?: return
        val currentLaunchBlocker = isStrictExactLaunchPage(page)
        val normalizedPath = NtkStripDigests.normalizeEpisodePath(
            page.manga.ntkEpisodePath.orEmpty(),
        )
        val claim = adjacentStrictSourceClaims[normalizedPath]
        if (claim != null && isAdjacentStrictSourceClaimLive(normalizedPath, claim)) {
            // The first unresolved PageRef is stronger physical demand than the most recent
            // committed viewport: the Surface has already clamped the user's real forward drag
            // immediately before this exact source. Feed that identity into the same bounded
            // source window used by committed frames. Otherwise the compositor cannot display N
            // until the source actor admits N, while the actor waits for a frame containing N --
            // a closed loop that strands a chapter tail during continuous input. This admits only
            // the blocker plus the same bounded directional runway; background pages stay closed.
            //
            // A late predecessor presentation can rewrite the process-wide byte owner after this
            // episode's first-actual frame. Idle completion repairs that ordering, but continuous
            // swipes deliberately keep the idle owner fenced. Reassert the exact PageRef path at
            // this stronger physical blocker edge before the source actor checks it; otherwise the
            // actor silently rejects the one-source redrive and the pixel flight parks forever.
            NtkReaderTransferPacer.notePhysicalForegroundEpisode(this, normalizedPath)
            applyAdjacentStrictViewportSourceDemand(
                normalizedPath = normalizedPath,
                claim = claim,
                firstVisibleSourceIndex = page.sourceIndex,
                lastVisibleSourceIndex = page.sourceIndex,
                direction = ReaderSurfaceView.DIRECTION_NEXT,
            )
            claim.transport.onPhysicalBlockedPageRequested(
                claim.episode,
                page.sourceIndex,
            )
        }
        if (currentLaunchBlocker) {
            latestCurrentLaunchBlockedForwardPage.set(page)
            // Surface has already proved that this exact immutable PageRef is the first missing
            // body holding a real forward gesture at the drawable-prefix fence. ReaderControl is
            // intentionally a background, single-thread ownership lane and may still be draining
            // rolling-window/retirement work. Queuing the first decode attempt there creates a
            // closed loop: Surface keeps physical input active while waiting for this drawable,
            // while ordinary rehydrate work waits for that input to become quiet. Admit only this
            // identity-bound blocker directly into the existing decode scheduler. The scheduler's
            // single-flight sets, admission epoch and Surface-installed proof still reject stale or
            // duplicate work; the control-lane request below remains an idempotent fallback.
            val currentIndex = currentPageIndex(page, index)
            val admission = strictRollingAdmission.get()
            if (currentIndex >= 0 && admission != null &&
                admission.admitsSource(page.sourceIndex)
            ) {
                requestStrictExactSourcePage(
                    currentIndex,
                    anchor = false,
                    generation = admission.epoch.toInt(),
                )
            }
        } else {
            latestPhysicalForwardIntentPage.set(page)
            // This callback already runs on the Activity's main turn and the rehydrate router is
            // an identity-bound single-flight scheduler. Do not enqueue this urgent blocker behind
            // ReaderControl's rolling-window/retirement backlog: under continuous input that queue
            // delayed each appended-episode source by 3-6 seconds even though its exact descriptor
            // was resident. The router performs no decode here; it only promotes/enqueues one
            // immutable PageRef on the urgent decode lane.
            val currentIndex = currentPageIndex(page, index)
            if (currentIndex >= 0) {
                routeStrictAdjacentExactRehydrate(
                    currentIndex,
                    page,
                    visibleIntent = true,
                )
            }
        }
        val now = SystemClock.elapsedRealtime()
        val previousPage = lastBlockedForwardRedrivePage.get()
        val previousAt = lastBlockedForwardRedriveAtMs.get()
        if (previousPage === page &&
            now - previousAt < BLOCKED_FORWARD_REDRIVE_MIN_INTERVAL_MS
        ) {
            return
        }
        lastBlockedForwardRedrivePage.set(page)
        lastBlockedForwardRedriveAtMs.set(now)
        try {
            control.execute {
                if (cancelled.get()) return@execute
                val currentIndex = currentPageIndex(page, index)
                if (currentIndex >= 0 && currentLaunchBlocker) {
                    val admission = strictRollingAdmission.get()
                    if (admission != null && admission.admitsSource(page.sourceIndex)) {
                        // The same exact decode may already be waiting behind the background
                        // post-scroll gate. Its timed acquisition observes
                        // latestCurrentLaunchBlockedForwardPage and promotes itself; this request
                        // is the idempotent fallback when no worker exists yet.
                        requestStrictExactSourcePage(
                            currentIndex,
                            anchor = false,
                            generation = admission.epoch.toInt(),
                        )
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            // Session teardown owns cancellation. A following physical window repeats the signal.
        }
    }

    private fun shouldParkHostGpuAdjacentWebtoonRemainder(target: Manga): Boolean {
        val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        val requiredRunwayPages = requiredInitialAdjacentRunwayPages(target)
        val anchor = currentViewportAnchor.get().coerceAtLeast(0)
        val drawablePagesAtOrAhead = synchronized(pagesLock) {
            val firstTargetIndex = pages.indexOfFirst { page ->
                looseSameEpisodeForAppend(page.manga, target)
            }
            if (firstTargetIndex < 0) {
                0
            } else {
                val runwayStart = maxOf(anchor, firstTargetIndex)
                pages.asSequence()
                    .drop(runwayStart)
                    .filter { page ->
                        page.transitionTitle == null &&
                            looseSameEpisodeForAppend(page.manga, target) &&
                            hasDeliveredOrPendingDrawable(page.pageIndex)
                    }
                    .count()
            }
        }
        return NtkAdjacentDecodedRunwayPolicy.shouldParkRemainder(
            hostGpuEmulatorRuntime = hostGpuEmulatorRuntime,
            directWifi = isDirectWifiStrictAdjacentRunwayProfile(target),
            episodePath = path,
            requiredRunwayPages = requiredRunwayPages,
            drawablePagesAtOrAhead = drawablePagesAtOrAhead,
        )
    }

    private fun parkHostGpuAdjacentWebtoonRemainder(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String,
        warm: Boolean,
    ) {
        val path = NtkStripDigests.normalizeEpisodePath(
            activeRemainingAdjacentRunwayTargetPath(target),
        )
        if (path.isEmpty()) return
        val parked = ParkedAdjacentRemainderAppend(target, refs, publishKey, warm)
        val firstPark = parkedAdjacentRemainderAppends.put(path, parked) == null
        pendingRemainingAdjacentRunwayAppends.remove(path)
        waitingStrictRemainingAdjacentAppends.remove(path)
        scheduledRemainingAdjacentRunwayRetries.cancelPath(path)?.let { scheduled ->
            main.removeCallbacks(scheduled.token)
        }
        if (firstPark) {
            Log.d(
                TAG,
                "append_adjacent_webtoon_decoded_runway_parked path=$path refs=${refs.size}",
            )
        }
    }

    /**
     * Prepares only immutable pixels, never list structure. The active chapter must already be
     * complete and real input must be retired. This moves file validation/decode/prepareToDraw out
     * of the next scroll without increasing the scrollable distance or allowing a fling to skip a
     * chapter.
     */
    private fun prepareAndParkOffscreenAdjacentRemainderIfIdle(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String,
        warm: Boolean,
    ): Boolean {
        if (NtkReaderTransferPacer.isPhysicalMotionActive() || viewportBusy.get()) return false
        if (physicalTouchQuietRemainingMs(NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS) > 0L) {
            return false
        }
        if (!isCurrentEpisodeCompleteForImmediateAdjacentStream(
                target,
                ReaderSurfaceView.DIRECTION_NEXT,
            )
        ) {
            return false
        }
        val path = activeRemainingAdjacentRunwayTargetPath(target)
        if (path.isEmpty()) return false
        val candidates = synchronized(pagesLock) {
            appendableRemainingAdjacentRunwayRefsLocked(target, refs).refs
        }
        if (candidates.isEmpty()) return false
        if (hostGpuEmulatorRuntime && !isViewportInsideEpisode(target)) {
            // The attached p0 already proves that this episode can be entered. Decoding its
            // offscreen p1+ tail here retains tens of MiB of native pixel storage and
            // reports that pressure to ART, which can stop the Java frame producer for a
            // NativeAlloc collection during the predecessor's physical scroll. Keep only the
            // exact sealed files/manifest while offscreen. Body ownership may continue filling
            // those files, but pixels are decoded only after the viewport enters this episode;
            // the normal host-exact cohort path below then publishes one source at a time.
            parkedAdjacentRemainderAppends[path] = ParkedAdjacentRemainderAppend(
                target = target,
                refs = refs,
                publishKey = publishKey,
                warm = warm,
            )
            val firstMissing = candidates.indexOfFirst { page ->
                page.transitionTitle == null && page.image.orEmpty().let { image ->
                    image.isNotEmpty() &&
                        ReaderImageCache.cachedFile(appContext, page.manga, image) == null
                }
            }
            if (firstMissing >= 0) {
                startRemainingAdjacentRunwayFileFetches(
                    target,
                    candidates.drop(firstMissing),
                    refs,
                    publishKey,
                    warm,
                )
            }
            Log.d(
                TAG,
                "append_adjacent_runway_remaining_encoded_parked targetId=${target.id} " +
                    "path=$path pages=${candidates.size} firstMissing=$firstMissing",
            )
            return true
        }
        val predictedStart = synchronized(pagesLock) { pages.size }
        var preparedNow = 0
        var firstMissing = -1
        for ((offset, page) in candidates.withIndex()) {
            // Idle preparation may overlap the first DOWN by a few milliseconds. Yield between
            // immutable pages so an offscreen decode wave cannot occupy the host CPUs throughout
            // a real moving-frame interval. Already staged pages remain reusable on the retry.
            if (NtkReaderTransferPacer.isPhysicalMotionActive() || viewportBusy.get() ||
                physicalTouchQuietRemainingMs(
                    NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS
                ) > 0L
            ) {
                return false
            }
            if (page.transitionTitle != null) continue
            val pageKey = preparedAdjacentRemainderDrawableKey(page) ?: continue
            if (preparedAdjacentRemainderDrawables.containsKey(pageKey)) continue
            val image = page.image.orEmpty()
            val cached = if (image.isNotEmpty()) {
                ReaderImageCache.cachedFile(appContext, page.manga, image)
            } else {
                null
            }
            if (cached == null) {
                firstMissing = offset
                break
            }
            val requestedWidth = ntkProofTargetWidth()
            val result = try {
                decodePage(
                    predictedStart + offset,
                    page,
                    cached,
                    requestedWidth,
                    proofDrawable = true,
                ).also(::prepareDecodeResultForDraw)
            } catch (e: Exception) {
                if (!isExpectedCancellation(e)) recordIfUnexpected(e)
                firstMissing = offset
                break
            }
            val prepared = PreparedAdjacentRemainderDrawable(
                pageKey = pageKey,
                result = result,
                preparedAtMs = SystemClock.elapsedRealtime(),
            )
            val previous = preparedAdjacentRemainderDrawables.putIfAbsent(pageKey, prepared)
            if (previous != null) {
                recycleDecodeResult(result)
            } else {
                preparedNow++
            }
        }
        val allPrepared = candidates
            .asSequence()
            .filter { it.transitionTitle == null }
            .all { page ->
                preparedAdjacentRemainderDrawableKey(page)?.let(
                    preparedAdjacentRemainderDrawables::containsKey
                ) == true
            }
        if (allPrepared) {
            parkedAdjacentRemainderAppends[path] = ParkedAdjacentRemainderAppend(
                target = target,
                refs = refs,
                publishKey = publishKey,
                warm = warm,
            )
            Log.d(
                TAG,
                "append_adjacent_runway_remaining_pixels_parked targetId=${target.id} " +
                    "path=$path pages=${candidates.size} preparedNow=$preparedNow"
            )
            return true
        }
        if (firstMissing >= 0) {
            startRemainingAdjacentRunwayFileFetches(
                target,
                candidates.drop(firstMissing),
                refs,
                publishKey,
                warm,
            )
        }
        if (preparedNow > 0) {
            Log.d(
                TAG,
                "append_adjacent_runway_remaining_pixels_progress targetId=${target.id} " +
                    "path=$path pages=${candidates.size} preparedNow=$preparedNow " +
                    "preparedTotal=${candidates.count { page ->
                        preparedAdjacentRemainderDrawableKey(page)?.let(
                            preparedAdjacentRemainderDrawables::containsKey
                        ) == true
                    }}"
            )
        }
        return false
    }

    private fun preparedAdjacentRemainderDrawableKey(page: PageRef): String? {
        if (page.transitionTitle != null) return null
        val path = activeRemainingAdjacentRunwayTargetPath(page.manga)
        if (path.isEmpty()) return null
        val asset = ReaderPreparedStore.canonicalOriginalAssetIdentity(page.image)
        if (asset.isEmpty()) return null
        return "$path|${page.sourceIndex}|${page.side}|$asset"
    }

    private fun resumeParkedAdjacentRemainder(activeViewportPath: String) {
        if (activeViewportPath.isEmpty()) return
        val parked = parkedAdjacentRemainderAppends[activeViewportPath] ?: return
        nearViewportParkedAdjacentWakePaths.remove(activeViewportPath)
        if (shouldLogRateLimitedDiagnostic(
                "adjacent_runway_remaining_pixels_resume|$activeViewportPath",
            )
        ) {
            Log.d(
                TAG,
                "append_adjacent_runway_remaining_pixels_resume targetId=${parked.target.id} " +
                    "path=$activeViewportPath refs=${parked.refs.size}"
            )
        }
        wakeStrictRemainingAdjacentAppend(activeViewportPath)
    }

    private fun redriveParkedAdjacentRemaindersNearViewport(first: Int, last: Int) {
        if (parkedAdjacentRemainderAppends.isEmpty() || last < 0) return
        val nearLast = last + NTK_PARKED_ADJACENT_VIEWPORT_NEAR_PAGES
        val nearPaths = synchronized(pagesLock) {
            parkedAdjacentRemainderAppends.keys.filter { path ->
                val firstTargetIndex = pages.indexOfFirst { page ->
                    NtkStripDigests.normalizeEpisodePath(
                        page.manga.ntkEpisodePath?.trim().orEmpty(),
                    ) == path
                }
                firstTargetIndex >= first.coerceAtLeast(0) && firstTargetIndex <= nearLast
            }
        }
        nearPaths.forEach { path ->
            if (nearViewportParkedAdjacentWakePaths.add(path)) {
                wakeStrictRemainingAdjacentAppend(path)
            }
        }
    }

    private fun isViewportInsideEpisode(target: Manga): Boolean {
        val targetPath = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath?.trim().orEmpty()
        )
        if (targetPath.isNotEmpty() &&
            adjacentStrictSourceClaims[targetPath]?.firstActualFramePresented?.get() == true
        ) {
            return true
        }
        val anchor = currentViewportAnchor.get()
        if (anchor < 0) return false
        return synchronized(pagesLock) {
            val boundedAnchor = anchor.coerceIn(0, pages.lastIndex.coerceAtLeast(0))
            val page = pages.getOrNull(boundedAnchor)
                ?: return@synchronized false
            // The forward transition card belongs to the incoming episode. Once its boundary
            // label is the viewport anchor, the old episode is already behind the reader and the
            // incoming suffix may be promoted without competing with foreground content.
            if (looseSameEpisodeForAppend(page.manga, target)) return@synchronized true

            // Page-table publication and the depth-one viewport mailbox are intentionally
            // independent. At an adjacent boundary the physical model can move to the incoming
            // runway before the queued anchor is re-resolved against the newly extended table.
            // Treat an anchor at or beyond the first canonical incoming page as entered even when
            // that one stale PageRef still carries the retiring Manga instance. This does not
            // promote an offscreen chapter: its first real/card index must already exist in the
            // scrollable table and the user's real anchor must have reached it.
            val firstIncomingIndex = pages.indexOfFirst { candidate ->
                looseSameEpisodeForAppend(candidate.manga, target)
            }
            firstIncomingIndex >= 0 && boundedAnchor >= firstIncomingIndex
        }
    }

    private fun isAdjacentStrictSourceClaimLive(
        path: String,
        claim: AdjacentStrictSourceClaim,
    ): Boolean {
        val snapshot = NtkSourceSpoolRegistry.currentSnapshot(path) ?: return false
        return !claim.terminalFailureObserved.get() &&
            snapshot.generation == claim.episode.value &&
            snapshot.manifestDigest == claim.manifestDigest &&
            snapshot.state.ordinal >= NtkSourceState.OWNED_BINDING.ordinal &&
            snapshot.state.ordinal < NtkSourceState.TERMINAL_CLOSING.ordinal
    }

    /**
     * Proves an attached exact runway without requiring its decoded pixels to remain in the live
     * bitmap window. The manifest, source generation, source index and canonical asset all have to
     * agree with the currently bound strict owner. A bare claim or a generic cached file is never
     * accepted as recoverability evidence.
     */
    private fun strictAdjacentPreparedRunwaySnapshot(
        target: Manga,
        minimumReadyImages: Int,
    ): StrictAdjacentPreparedRunwaySnapshot? {
        if (minimumReadyImages <= 0) return null
        val path = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath?.trim().orEmpty(),
        )
        if (!path.startsWith("/manhwa/") && !path.startsWith("/webtoon/")) return null
        val authority = exactViewerApiAdjacentAuthority(target) ?: return null
        val seal = authority.seal
        if (seal.normalizedEpisodePath != path || minimumReadyImages > seal.pageCount) return null
        val claim = adjacentStrictSourceClaims[path] ?: return null
        val claimLive = claim.manifestDigest == seal.digestSha256 &&
            claim.episode.value == seal.revision &&
            isAdjacentStrictSourceClaimLive(path, claim)
        if (!claimLive) return null

        val expectedSources = (0 until minimumReadyImages).toList()
        val runway = synchronized(pagesLock) {
            val episodePages = pages.withIndex()
                .filter { (_, page) ->
                    page.transitionTitle == null &&
                        looseSameEpisodeForAppend(page.manga, target)
                }
            val allSources = episodePages.map { it.value.sourceIndex }
            val runwayEnd = allSources.indexOf(minimumReadyImages - 1)
            if (runwayEnd < 0) return@synchronized null
            val runwaySources = allSources.take(runwayEnd + 1)
            val canonicalOrder = runwaySources.firstOrNull() == 0 &&
                runwaySources.zipWithNext().all { (previous, next) ->
                    next >= previous && next <= previous + 1
                } &&
                runwaySources.distinct() == expectedSources
            if (!canonicalOrder) return@synchronized null
            expectedSources.map { sourceIndex ->
                episodePages.firstOrNull { it.value.sourceIndex == sourceIndex }
                    ?: return@synchronized null
            }
        } ?: return null

        val liveSources = HashSet<Int>(minimumReadyImages)
        val recoverableSources = HashSet<Int>(minimumReadyImages)
        for ((index, page) in runway) {
            val sourceIndex = page.sourceIndex
            val canonical = seal.normalizedCanonicalAssets.getOrNull(sourceIndex) ?: return null
            val pagePath = NtkStripDigests.normalizeEpisodePath(
                page.manga.ntkEpisodePath?.trim().orEmpty(),
            )
            if (pagePath != path || page.pageIndex != index ||
                page.manifestDigest != seal.digestSha256 ||
                page.manifestPageCount != seal.pageCount ||
                page.canonicalAsset != canonical ||
                !NtkStripDigests.isSha256(page.manifestDigest)
            ) {
                return null
            }
            val live = hasListenerDrawableDelivery(index, page) || hasDeliveredBitmap(index)
            if (live) liveSources.add(sourceIndex)
            val descriptor = adjacentStrictBodyDescriptors[
                adjacentStrictBodyDescriptorKey(path, seal.digestSha256, sourceIndex)
            ]
            val descriptorRecoverable = descriptor?.let {
                canReopenStrictAdjacentBody(
                    descriptor = it,
                    sourceIndex = sourceIndex,
                    manifestDigest = seal.digestSha256,
                    canonicalAsset = canonical,
                )
            } == true
            // Decoded residency can disappear immediately after this snapshot. Offscreen parking
            // therefore requires an independently reopenable exact body for every source even
            // when that source currently has live pixels.
            if (!descriptorRecoverable) return null
            recoverableSources.add(sourceIndex)
        }

        val structureStillCurrent = synchronized(pagesLock) {
            runway.all { (index, page) ->
                pages.getOrNull(index) === page && page.pageIndex == index
            }
        }
        val authorityStillCurrent = exactViewerApiAdjacentAuthority(target)?.seal?.let { current ->
            current.revision == seal.revision && current.digestSha256 == seal.digestSha256
        } == true
        if (!structureStillCurrent || !authorityStillCurrent ||
            !isAdjacentStrictSourceClaimLive(path, claim)
        ) {
            return null
        }
        return StrictAdjacentPreparedRunwaySnapshot(
            normalizedPath = path,
            claimLive = true,
            orderedAttachedSourceIndexes = expectedSources,
            liveSourceIndexes = liveSources,
            recoverableSourceIndexes = recoverableSources,
        )
    }

    private fun canReopenStrictAdjacentBody(
        descriptor: NtkStrictBodyDescriptor,
        sourceIndex: Int,
        manifestDigest: String,
        canonicalAsset: String,
    ): Boolean {
        val canonicalDigest = NtkStripDigests.canonicalAssetDigestSha256(canonicalAsset)
        if (descriptor.sourceKey.pageIndex != sourceIndex ||
            descriptor.sourceKey.manifestDigest != manifestDigest ||
            descriptor.sourceKey.canonicalAssetDigest != canonicalDigest ||
            descriptor.metadata.canonicalAsset != canonicalAsset ||
            descriptor.proof.encodedLength <= 0L
        ) {
            return false
        }
        val lease = try {
            descriptor.openLease()
        } catch (failure: Exception) {
            if (!isExpectedCancellation(failure)) recordIfUnexpected(failure)
            return false
        }
        return try {
            val bytesAvailable = lease.encodedBytes?.size?.toLong() == lease.proof.encodedLength
            val fileAvailable = lease.file.isFile &&
                lease.file.length() == lease.proof.encodedLength
            lease.sourceKey == descriptor.sourceKey &&
                lease.metadata == descriptor.metadata &&
                lease.proof == descriptor.proof &&
                lease.sourceKey.pageIndex == sourceIndex &&
                lease.sourceKey.manifestDigest == manifestDigest &&
                lease.sourceKey.canonicalAssetDigest == canonicalDigest &&
                lease.metadata.canonicalAsset == canonicalAsset &&
                lease.proof.encodedLength > 0L &&
                (bytesAvailable || fileAvailable)
        } finally {
            runCatching(lease.release)
        }
    }

    private fun invalidateAdjacentStrictSourceClaim(
        path: String,
        expected: AdjacentStrictSourceClaim,
        reason: String,
    ): Boolean {
        val invalidated = synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictSourceClaims[path] === expected &&
                adjacentStrictDescriptorBindingTokens[path] === expected.descriptorBindingToken &&
                synchronized(expected.terminalFailureObserved) {
                    expected.terminalFailureObserved.compareAndSet(false, true)
                }
        }
        if (!invalidated) return false
        adjacentStrictDescriptorBindingTokens.remove(path, expected.descriptorBindingToken)
        cancelAdjacentStrictDescriptorWaitWatchdog(path)
        Log.w(
            TAG,
            "append_adjacent_strict_source_invalidated path=$path " +
                "generation=${expected.episode.value} digest=${expected.manifestDigest} reason=$reason",
        )
        wakeStrictRemainingAdjacentAppend(path)
        return true
    }

    /** Parks a claimless exact-recovery gap before any generic readiness/cache decision. */
    private fun parkAdjacentStrictRecoveryAwaitingReplacement(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String,
        warm: Boolean,
    ): Boolean {
        val path = NtkStripDigests.normalizeEpisodePath(
            activeRemainingAdjacentRunwayTargetPath(target),
        )
        if (path.isEmpty()) return false
        val recoveryAwaiting = synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictSourceClaims[path] == null &&
                adjacentStrictRecoveryStates[path]?.let { state ->
                    state.awaitingReplacement && !state.exhausted
                } == true
        }
        if (!recoveryAwaiting) return false

        pendingRemainingAdjacentRunwayAppends.remove(path)
        scheduledRemainingAdjacentRunwayRetries.cancelPath(path)
            ?.let { scheduled -> main.removeCallbacks(scheduled.token) }
        cancelAdjacentStrictDescriptorWaitWatchdog(path)
        cancelAdjacentStrictRecoveryBindDeadline(path)
        val waiter = ParkedAdjacentRemainderAppend(
            target = target,
            refs = refs,
            publishKey = publishKey,
            warm = warm,
            expectedFirstMissingPageIdentity =
                firstMissingStrictAdjacentDescriptorIdentity(target, refs),
        )
        waitingStrictRemainingAdjacentAppends[path] = waiter
        ensureAdjacentStrictRecoveryManifestSubscription()
        // Arm before the snapshot recheck. This remains the terminal edge even when discovery
        // produces no manifest at all; a successful binding cancels it before waking the waiter.
        armAdjacentStrictRecoveryBindDeadline(path, waiter)
        NtkSourceSpoolRegistry.currentAuthoritativeManifest(path)?.let { manifest ->
            onAdjacentStrictRecoveryManifestInstalled(path, manifest)
        }
        Log.d(
            TAG,
            "append_adjacent_strict_recovery_wait_parked path=$path refs=${refs.size}",
        )
        return true
    }

    /**
     * An admitted descriptor batch can fail only after exact capabilities were retained for this
     * turn. Retire that captured generation, request bounded exact rediscovery, and park on source
     * events; a 128/180 ms generic timer would only reopen the same broken lease in a hot loop.
     */
    private fun recoverAdjacentStrictDescriptorFailure(
        target: Manga,
        refs: List<PageRef>,
        publishKey: String,
        warm: Boolean,
        owner: AdjacentStrictDecodeFailureOwner?,
        reason: String,
    ) {
        owner?.let { invalidateAdjacentStrictSourceClaim(it.normalizedPath, it.claim, reason) }
        if (!holdOrRecoverAdjacentStrictSource(target)) {
            clearActiveRemainingAdjacentRunwayTarget(target)
            clearPendingAdjacentAppendPublish(publishKey)
            return
        }
        if (isAdjacentStrictRecoveryExhausted(target)) {
            clearActiveRemainingAdjacentRunwayTarget(target)
            clearPendingAdjacentAppendPublish(publishKey)
            return
        }
        val path = NtkStripDigests.normalizeEpisodePath(
            activeRemainingAdjacentRunwayTargetPath(target),
        )
        if (path.isEmpty()) return
        pendingRemainingAdjacentRunwayAppends.remove(path)
        scheduledRemainingAdjacentRunwayRetries.cancelPath(path)?.let { scheduled ->
            main.removeCallbacks(scheduled.token)
        }
        cancelAdjacentStrictRecoveryBindDeadline(path)
        val waiter = ParkedAdjacentRemainderAppend(
            target = target,
            refs = refs,
            publishKey = publishKey,
            warm = warm,
            expectedFirstMissingPageIdentity =
                firstMissingStrictAdjacentDescriptorIdentity(target, refs),
        )
        waitingStrictRemainingAdjacentAppends[path] = waiter
        ensureAdjacentStrictRecoveryManifestSubscription()

        // Exact rediscovery may have completed between the recovery request and waiter install.
        // Bind the replacement's event deadline only when it is already live; otherwise its body
        // replay/terminal event wakes this waiter as soon as ensureAdjacentStrictSourceClaim binds.
        val replacement = adjacentStrictSourceClaims[path]
        if (replacement != null && isAdjacentStrictSourceClaimLive(path, replacement)) {
            armAdjacentStrictDescriptorWaitWatchdog(path, waiter)
            deferStrictRemainingAdjacentWakeAfterRegistration(
                path,
                waiter,
                target,
                refs,
                exactDescriptorWait = true,
            )
        } else {
            // The deadline also owns discovery that produces no manifest. Arm it before the
            // snapshot recheck so manifest publication cannot fall between the two registrations.
            armAdjacentStrictRecoveryBindDeadline(path, waiter)
            NtkSourceSpoolRegistry.currentAuthoritativeManifest(path)?.let { manifest ->
                onAdjacentStrictRecoveryManifestInstalled(path, manifest)
            }
        }
    }

    private fun ensureAdjacentStrictRecoveryManifestSubscription() {
        if (adjacentStrictRecoveryManifestSubscription.get() != null || cancelled.get()) return
        val created = NtkSourceSpoolRegistry.addAuthoritativeManifestListener(
            NtkAuthoritativeManifestListener { changedPath, manifest ->
                onAdjacentStrictRecoveryManifestInstalled(changedPath, manifest)
            },
        )
        if (!adjacentStrictRecoveryManifestSubscription.compareAndSet(null, created)) {
            created.close()
        }
    }

    private fun onAdjacentStrictRecoveryManifestInstalled(
        changedPath: String,
        manifest: NtkAuthoritativeManifest,
    ) {
        val path = NtkStripDigests.normalizeEpisodePath(changedPath)
        val waiter = waitingStrictRemainingAdjacentAppends[path] ?: return
        val recoveryCurrent = synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictRecoveryStates[path]?.let { state ->
                state.awaitingReplacement && !state.exhausted &&
                    state.expectedManifestDigest == manifest.seal.digestSha256
            } == true
        }
        if (cancelled.get() || !recoveryCurrent || !manifest.isProductionClaimable ||
            manifest.seal.normalizedEpisodePath != path
        ) {
            return
        }
        try {
            control.execute {
                if (cancelled.get() || waitingStrictRemainingAdjacentAppends[path] !== waiter) {
                    return@execute
                }
                val stillRecovering = synchronized(adjacentStrictSourceClaimLock) {
                    adjacentStrictRecoveryStates[path]?.let { state ->
                        state.awaitingReplacement && !state.exhausted &&
                            state.expectedManifestDigest == manifest.seal.digestSha256
                    } == true
                }
                if (!stillRecovering) return@execute
                if (ensureAdjacentStrictSourceClaim(waiter.target, manifest)) {
                    cancelAdjacentStrictRecoveryBindDeadline(path)
                    wakeStrictRemainingAdjacentAppend(path)
                } else {
                    // bindResidentBodies/addSourceEventListener/claim-phase close races are not
                    // required to emit TerminalFailure. Preserve one bounded future recovery edge.
                    armAdjacentStrictRecoveryBindDeadline(path, waiter)
                }
            }
        } catch (_: RejectedExecutionException) {
            // Session cancellation owns listener shutdown and waiter cleanup.
        }
    }

    private fun terminateAdjacentStrictLocalPublicationFailure(
        target: Manga,
        owner: AdjacentStrictDecodeFailureOwner?,
        reason: String,
    ): Boolean {
        val exactOwner = owner ?: return false
        if (!invalidateAdjacentStrictSourceClaim(
            exactOwner.normalizedPath,
            exactOwner.claim,
            reason,
        )) return false
        synchronized(adjacentStrictSourceClaimLock) {
            val state = adjacentStrictRecoveryStates[exactOwner.normalizedPath]
                ?: AdjacentStrictRecoveryState(
                    expectedManifestDigest = exactOwner.claim.manifestDigest,
                    predecessorEpisodePath = exactOwner.claim.predecessorEpisodePath,
                    target = target,
                ).also { adjacentStrictRecoveryStates[exactOwner.normalizedPath] = it }
            state.exhausted = true
            state.networkRearmableTerminal = false
            state.pendingValidatedRedriveEpoch = 0L
        }
        holdOrRecoverAdjacentStrictSource(target)
        return true
    }

    /**
     * Keeps a missing exact-adjacent body fail-closed while replacing only its dead strict
     * generation. Returning true means the generic loader must not claim this page.
     */
    private fun holdOrRecoverAdjacentStrictSource(target: Manga): Boolean {
        val path = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath?.trim().orEmpty(),
        )
        if (path.isEmpty()) return false
        val validatedCatchUpBoundaryPath = currentAdjacentValidatedBoundaryEvidence()
            .normalizedEpisodePath
        val needsReplacementClaim = synchronized(adjacentStrictSourceClaimLock) {
            val recovery = adjacentStrictRecoveryStates[path]
            adjacentStrictSourceClaims[path] == null &&
                recovery != null &&
                !recovery.exhausted &&
                !recovery.retirementInProgress
        }
        var replacementClaimRejected = false
        var replacementAuthorityUsable = false
        if (needsReplacementClaim) {
            exactViewerApiAdjacentAuthority(target)?.let { authority ->
                replacementAuthorityUsable = true
                replacementClaimRejected = !ensureAdjacentStrictSourceClaim(target, authority)
            }
        }
        val now = SystemClock.elapsedRealtime()
        val snapshot = NtkSourceSpoolRegistry.currentSnapshot(path)
        val replacementInFlight = NtkStrictEpisodeDiscoveryCoordinator.isInFlight(path)
        var claimToRetire: AdjacentStrictSourceClaim? = null
        var generationToRetire = 0L
        var digestToRetire = ""
        var rediscoveryPredecessor = ""
        var terminal = false
        var validatedRearmEpoch = 0L
        var retirementOwner: AdjacentStrictRecoveryState? = null

        synchronized(adjacentStrictSourceClaimLock) {
            val claim = adjacentStrictSourceClaims[path]
            val recovery = adjacentStrictRecoveryStates[path]
            if (claim == null && recovery == null) return false
            // Retirement clears a path-scoped deadline and every descriptor for the retiring
            // digest. A concurrent recovery turn must not bind a replacement until that cleanup
            // has finished, otherwise the old cleanup can erase the new generation's wake.
            if (recovery?.retirementInProgress == true) return true
            val terminalCatchUp = recovery != null && recovery.exhausted &&
                recovery.networkRearmableTerminal
            val activeCatchUp = recovery != null && !recovery.exhausted &&
                recovery.awaitingReplacement
            if (claim == null && recovery != null && (terminalCatchUp || activeCatchUp)) {
                val catchUpEpoch = NtkAdjacentValidatedEpochCatchUpPolicy.consume(
                    recovery.pendingValidatedRedriveEpoch,
                    recovery.lastValidatedRedriveEpoch,
                    exactBoundary = ViewerTelemetry.isActiveViewer(
                        strictExactForegroundViewerGenerationAtCreation,
                        strictExactViewerOwnerEpisodePathAtCreation,
                    ) &&
                        NtkAdjacentValidatedEpochCatchUpPolicy.exactBoundaryMatches(
                            validatedCatchUpBoundaryPath,
                            recovery.predecessorEpisodePath,
                            path,
                        ),
                )
                if (catchUpEpoch > 0L) {
                    // This exact target has finally reached its physical boundary. A terminal
                    // owner opens one bounded request generation; an already-active owner keeps
                    // its counters only while its physical Flight still exists. A claimless state
                    // with no Flight must open a bounded generation or an already-spent request
                    // counter would terminalize this edge before making one request.
                    val resetRequestGeneration =
                        NtkAdjacentValidatedEpochCatchUpPolicy.shouldResetRequestGeneration(
                            terminalCatchUp,
                            activeCatchUp,
                            replacementInFlight,
                        )
                    if (resetRequestGeneration) {
                        recovery.exhausted = false
                        recovery.awaitingReplacement = true
                        recovery.rediscoveryRequestCount = 1
                        recovery.lastRequestAtMs = now
                        recovery.lastBindDeadlineAtMs = 0L
                        recovery.terminalReported = false
                        recovery.networkRearmableTerminal = false
                    }
                    recovery.lastValidatedRedriveEpoch = catchUpEpoch
                    recovery.lastValidatedRedriveAtMs = now
                    recovery.pendingValidatedRedriveEpoch = 0L
                    validatedRearmEpoch = catchUpEpoch
                    rediscoveryPredecessor = recovery.predecessorEpisodePath
                }
            }
            val claimLive = claim?.let { isAdjacentStrictSourceClaimLive(path, it) } == true
            val matchingAuthorityAvailable = recovery != null && snapshot != null &&
                replacementAuthorityUsable &&
                !replacementClaimRejected &&
                snapshot.manifestDigest == recovery.expectedManifestDigest &&
                snapshot.state.ordinal >= NtkSourceState.OWNED_PRECLAIM.ordinal &&
                snapshot.state.ordinal < NtkSourceState.TERMINAL_CLOSING.ordinal
            val elapsedSinceRequest = recovery?.lastRequestAtMs
                ?.takeIf { it > 0L }
                ?.let { (now - it).coerceAtLeast(0L) }
                ?: Long.MAX_VALUE
            val decision = if (recovery?.exhausted == true) {
                NtkAdjacentStrictClaimRecoveryPolicy.Decision.TERMINAL_RETIREMENT
            } else {
                NtkAdjacentStrictClaimRecoveryPolicy.decide(
                    claimPresent = claim != null,
                    claimIdentityLive = claimLive,
                    recoveryActive = recovery?.awaitingReplacement == true,
                    retiredGenerationCount = recovery?.retiredGenerationCount ?: 0,
                    rediscoveryRequestCount = recovery?.rediscoveryRequestCount ?: 0,
                    elapsedSinceRequestMs = elapsedSinceRequest,
                    replacementInFlight = replacementInFlight,
                    matchingAuthorityAvailable = matchingAuthorityAvailable,
                )
            }
            when (decision) {
                NtkAdjacentStrictClaimRecoveryPolicy.Decision.ALLOW_GENERIC -> return false
                NtkAdjacentStrictClaimRecoveryPolicy.Decision.HOLD_LIVE_CLAIM,
                NtkAdjacentStrictClaimRecoveryPolicy.Decision.WAIT_FOR_REPLACEMENT -> Unit

                NtkAdjacentStrictClaimRecoveryPolicy.Decision.RETIRE_AND_REDISCOVER -> {
                    val failedClaim = checkNotNull(claim)
                    val state = recovery ?: AdjacentStrictRecoveryState(
                        expectedManifestDigest = failedClaim.manifestDigest,
                        predecessorEpisodePath = failedClaim.predecessorEpisodePath,
                        target = target,
                    ).also { adjacentStrictRecoveryStates[path] = it }
                    state.retiredGenerationCount++
                    state.rediscoveryRequestCount = 1
                    state.lastRequestAtMs = now
                    state.awaitingReplacement = true
                    state.retirementInProgress = true
                    retirementOwner = state
                    claimToRetire = failedClaim
                    generationToRetire = failedClaim.episode.value
                    digestToRetire = failedClaim.manifestDigest
                    rediscoveryPredecessor = state.predecessorEpisodePath
                    adjacentStrictSourceClaims.remove(path, failedClaim)
                }

                NtkAdjacentStrictClaimRecoveryPolicy.Decision.REQUEST_REDISCOVERY -> {
                    val state = checkNotNull(recovery)
                    state.rediscoveryRequestCount++
                    state.lastRequestAtMs = now
                    rediscoveryPredecessor = state.predecessorEpisodePath
                }

                NtkAdjacentStrictClaimRecoveryPolicy.Decision.TERMINAL_RETIREMENT -> {
                    recovery?.let { state ->
                        // Do not publish a replacement claim until the old generation has closed
                        // its descriptors and deadline. A validated edge which races this cleanup
                        // is recorded globally and consumed immediately after retirement finishes.
                        state.exhausted = true
                        state.networkRearmableTerminal = true
                        state.retirementInProgress = true
                        retirementOwner = state
                        terminal = true
                    }
                    claim?.let {
                        claimToRetire = it
                        generationToRetire = it.episode.value
                        digestToRetire = it.manifestDigest
                        adjacentStrictSourceClaims.remove(path, it)
                    }
                    if (generationToRetire <= 0L) generationToRetire = snapshot?.generation ?: 0L
                    if (digestToRetire.isEmpty()) {
                        digestToRetire = recovery?.expectedManifestDigest.orEmpty()
                    }
                    if (recovery == null) terminal = true
                }
            }
        }

        if (retirementOwner != null) {
            retireAdjacentStrictSourceGeneration(
                path = path,
                generation = generationToRetire,
                manifestDigest = digestToRetire,
                claim = claimToRetire,
                terminal = terminal,
            )
        }
        if (retirementOwner != null) {
            val rearmAfterRetirement = synchronized(adjacentStrictSourceClaimLock) {
                val state = retirementOwner
                    ?.takeIf { adjacentStrictRecoveryStates[path] === it }
                    ?: return@synchronized null
                state.retirementInProgress = false
                val observedEpoch = lastObservedAdjacentValidatedNetworkEpoch
                val observedPath = lastObservedAdjacentValidatedNetworkPath
                val pendingEpoch = NtkAdjacentValidatedEpochCatchUpPolicy.consume(
                    state.pendingValidatedRedriveEpoch,
                    state.lastValidatedRedriveEpoch,
                    exactBoundary = ViewerTelemetry.isActiveViewer(
                        strictExactForegroundViewerGenerationAtCreation,
                        strictExactViewerOwnerEpisodePathAtCreation,
                    ) &&
                        NtkAdjacentValidatedEpochCatchUpPolicy.exactBoundaryMatches(
                            validatedCatchUpBoundaryPath,
                            state.predecessorEpisodePath,
                            path,
                        ),
                )
                val edgeAlreadyLatchedOnExactState =
                    state.pendingValidatedRedriveEpoch > state.lastValidatedRedriveEpoch
                val boundaryObservedEpoch = observedEpoch.takeIf {
                    !edgeAlreadyLatchedOnExactState &&
                        NtkAdjacentValidatedEpochCatchUpPolicy.consume(
                        it,
                        state.lastValidatedRedriveEpoch,
                        ViewerTelemetry.isActiveViewer(
                            strictExactForegroundViewerGenerationAtCreation,
                            strictExactViewerOwnerEpisodePathAtCreation,
                        ) &&
                            (observedPath.isEmpty() ||
                                observedPath.equals(path, ignoreCase = true) ||
                                observedPath.equals(
                                    state.predecessorEpisodePath,
                                    ignoreCase = true,
                                )),
                    ) > 0L
                } ?: 0L
                val catchUpEpoch = max(pendingEpoch, boundaryObservedEpoch)
                val terminalCanConsume = terminal && state.exhausted &&
                    state.networkRearmableTerminal &&
                    catchUpEpoch > state.lastValidatedRedriveEpoch
                val activeCanConsume = !terminal && !state.exhausted &&
                    state.awaitingReplacement &&
                    catchUpEpoch > state.lastValidatedRedriveEpoch
                if (!terminalCanConsume && !activeCanConsume) return@synchronized null
                if (terminalCanConsume) {
                    state.exhausted = false
                    state.awaitingReplacement = true
                    state.rediscoveryRequestCount = 1
                    state.lastRequestAtMs = now
                    state.lastBindDeadlineAtMs = 0L
                    state.terminalReported = false
                    state.networkRearmableTerminal = false
                }
                state.lastValidatedRedriveEpoch = catchUpEpoch
                state.lastValidatedRedriveAtMs = now
                state.pendingValidatedRedriveEpoch = 0L
                Triple(catchUpEpoch, state.predecessorEpisodePath, state.target)
            }
            if (rearmAfterRetirement != null) {
                terminal = false
                validatedRearmEpoch = rearmAfterRetirement.first
                rediscoveryPredecessor = rearmAfterRetirement.second
            }
        }
        if (validatedRearmEpoch > 0L) {
            adjacentStrictPredecessorPaths[path] = rediscoveryPredecessor
            ensureAdjacentStrictRecoveryManifestSubscription()
            waitingStrictRemainingAdjacentAppends[path]?.let { waiter ->
                armAdjacentStrictRecoveryBindDeadline(path, waiter)
            }
            ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
                path,
                NTK_ADJACENT_APPEND_FOREGROUND_PATH_TTL_MS,
                "validated_network_recovery_deferred_terminal",
            )
        }
        if (rediscoveryPredecessor.isNotEmpty()) {
            Log.d(
                TAG,
                "append_adjacent_strict_recovery_request path=$path " +
                    "predecessor=$rediscoveryPredecessor generation=$generationToRetire",
            )
            listener.onAdjacentExactManifestRequired(target, rediscoveryPredecessor)
        }
        if (validatedRearmEpoch > 0L) {
            scheduleDeferredAdjacentPrepare(
                currentViewportAnchor.get().coerceAtLeast(0),
                ReaderSurfaceView.DIRECTION_NEXT,
                0L,
                silentMissing = false,
            )
        }
        if (terminal) reportAdjacentStrictRecoveryTerminal(path)
        return true
    }

    private fun retireAdjacentStrictSourceGeneration(
        path: String,
        generation: Long,
        manifestDigest: String,
        claim: AdjacentStrictSourceClaim?,
        terminal: Boolean,
    ) {
        runCatching { cancelAdjacentStrictRecoveryBindDeadline(path) }
            .onFailure { failure ->
                Log.w(TAG, "append_adjacent_strict_deadline_cancel_failed path=$path", failure)
            }
        val reason = if (terminal) {
            "adjacent_body_recovery_exhausted"
        } else {
            "adjacent_body_terminal_retry"
        }
        val viewerGeneration = ViewerTelemetry.activeGeneration()
        var coordinatorRetired = false
        if (generation > 0L) {
            runCatching {
                coordinatorRetired = NtkStrictEpisodeDiscoveryCoordinator
                    .retireAdjacentTargetForReplacement(
                        path,
                        generation,
                        viewerGeneration,
                        reason,
                    )
                if (!coordinatorRetired) {
                    NtkSourceSpoolRegistry.retireDiscoveryGenerationForReplacement(
                        path,
                        generation,
                        reason,
                    )
                }
            }.onFailure { failure ->
                // Local descriptor/binding cleanup below must still complete. Keeping this helper
                // total ensures retirementInProgress can be released only after every local
                // path-scoped owner has been detached.
                Log.w(
                    TAG,
                    "append_adjacent_strict_source_generation_retire_failed " +
                        "path=$path generation=$generation",
                    failure,
                )
            }
        }
        claim?.let {
            runCatching { cancelAdjacentStrictDescriptorWaitWatchdog(path, it) }
            runCatching {
                synchronized(it.terminalFailureObserved) {
                    it.terminalFailureObserved.set(true)
                    adjacentStrictDescriptorBindingTokens.remove(path, it.descriptorBindingToken)
                }
            }
            runCatching { it.sourceEventBinding.close() }
            runCatching { it.residentBinding.close() }
            runCatching { (it.transport as? Closeable)?.close() }
        }
        if (manifestDigest.isNotEmpty()) {
            val prefix = "$path|$manifestDigest|"
            runCatching {
                adjacentStrictBodyDescriptors.keys.removeAll { it.startsWith(prefix) }
            }.onFailure { failure ->
                Log.w(TAG, "append_adjacent_strict_descriptor_clear_failed path=$path", failure)
            }
        }
        Log.d(
            TAG,
            "append_adjacent_strict_source_generation_retired path=$path " +
                "generation=$generation digest=$manifestDigest terminal=$terminal " +
                "coordinator=$coordinatorRetired",
        )
    }

    private fun isAdjacentStrictRecoveryExhausted(target: Manga): Boolean {
        val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        if (path.isEmpty()) return false
        return synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictRecoveryStates[path]?.exhausted == true
        }
    }

    private fun isAdjacentStrictRecoveryAwaitingReplacement(target: Manga): Boolean {
        val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        if (path.isEmpty()) return false
        return synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictRecoveryStates[path]?.let { state ->
                state.awaitingReplacement && !state.exhausted
            } == true
        }
    }

    /**
     * Snapshot physical reading evidence before an adjacent-owner lock; pagesLock must never nest
     * inside those locks. A rolling WindowEvent can advance currentViewportAnchor to a prefetched
     * p6 while Activity still reports visible p3, so only the identity-bearing reading PageRef is
     * authoritative after the first report. Before that report, the immutable launch page is the
     * sole conservative fallback.
     */
    private fun currentAdjacentValidatedBoundaryEvidence(): AdjacentValidatedBoundaryEvidence {
        return synchronized(pagesLock) {
            val readingPage = latestReportedReadingPage.get()
            val boundaryIndex = if (readingPage == null) {
                currentStartPage().takeIf { it in pages.indices } ?: -1
            } else {
                pageIndexLocked(readingPage, readingPage.pageIndex)
            }
            val normalizedPath = pages.getOrNull(boundaryIndex)
                ?.takeIf { it.transitionTitle == null }
                ?.let { page ->
                    NtkStripDigests.normalizeEpisodePath(page.manga.ntkEpisodePath.orEmpty())
                }
                .orEmpty()
            AdjacentValidatedBoundaryEvidence(
                normalizedEpisodePath = normalizedPath,
                pageIndex = boundaryIndex.takeIf { normalizedPath.isNotEmpty() } ?: -1,
            )
        }
    }

    /**
     * Re-arms an initial forward-adjacent manifest owner once for one real validated-network edge.
     *
     * The ordinary completion watchdog deliberately retires an exhausted live revision so the
     * provider-list fallback can select a stronger target. It leaves an immutable tombstone for
     * this method. Restoration always allocates a new revision and runs the normal activation path;
     * callbacks queued by the retired revision therefore remain stale.
     */
    fun redriveCurrentForwardAdjacentExactManifestAfterValidated(
        validatedEpoch: Long,
    ): Boolean {
        val viewerGeneration = strictExactForegroundViewerGenerationAtCreation
        val viewerOwnerPath = strictExactViewerOwnerEpisodePathAtCreation
        if (validatedEpoch <= 0L || cancelled.get() || viewerGeneration <= 0L ||
            !ViewerTelemetry.isActiveViewer(viewerGeneration, viewerOwnerPath)
        ) return false
        val activePath = currentAdjacentValidatedBoundaryEvidence().normalizedEpisodePath
        val now = SystemClock.elapsedRealtime()

        fun boundaryMatches(predecessorPath: String, targetPath: String): Boolean =
            activePath.equals(predecessorPath, ignoreCase = true) ||
                activePath.equals(targetPath, ignoreCase = true)

        val selected = synchronized(forwardAdjacentCompletionTargetClaimLock) {
            if (cancelled.get() ||
                !ViewerTelemetry.isActiveViewer(viewerGeneration, viewerOwnerPath)
            ) return@synchronized null
            if (validatedEpoch > lastObservedForwardAdjacentValidatedNetworkEpoch) {
                lastObservedForwardAdjacentValidatedNetworkEpoch = validatedEpoch
                lastObservedForwardAdjacentValidatedNetworkPath = activePath
            } else if (validatedEpoch == lastObservedForwardAdjacentValidatedNetworkEpoch &&
                lastObservedForwardAdjacentValidatedNetworkPath.isEmpty() &&
                activePath.isNotEmpty()
            ) {
                // The edge can arrive before the first page-table transaction. If a later turn of
                // the same still-pending ticket has an exact viewport, narrow the blank evidence.
                lastObservedForwardAdjacentValidatedNetworkPath = activePath
            }
            // One ticket must also reach exact future boundaries already known by this Session.
            // Do not launch them offscreen: retain only the epoch on their immutable identity and
            // let claimForwardAdjacentCompletionTarget consume it when that boundary is selected.
            for (claim in forwardAdjacentCompletionTargetClaims.values) {
                if (!claim.structureCommitted) {
                    claim.pendingValidatedRedriveEpoch =
                        NtkAdjacentValidatedEpochCatchUpPolicy.latch(
                            validatedEpoch,
                            claim.lastValidatedRedriveEpoch,
                            claim.pendingValidatedRedriveEpoch,
                        )
                }
            }
            for ((predecessorPath, tombstone) in
                forwardAdjacentValidatedRecoveryTombstones.toList()
            ) {
                val pendingEpoch = NtkAdjacentValidatedEpochCatchUpPolicy.latch(
                    validatedEpoch,
                    tombstone.lastValidatedRedriveEpoch,
                    tombstone.pendingValidatedRedriveEpoch,
                )
                if (pendingEpoch != tombstone.pendingValidatedRedriveEpoch) {
                    forwardAdjacentValidatedRecoveryTombstones[predecessorPath] =
                        tombstone.copy(pendingValidatedRedriveEpoch = pendingEpoch)
                }
            }
            if (activePath.isEmpty()) return@synchronized null

            // Prefer the claim which starts at the active episode. A previous A -> B claim can
            // coexist briefly with the next B -> C completion owner while the viewport enters B.
            val live = forwardAdjacentCompletionTargetClaims.values.firstOrNull { claim ->
                activePath.equals(claim.predecessorEpisodePath, ignoreCase = true)
            } ?: forwardAdjacentCompletionTargetClaims.values.firstOrNull { claim ->
                activePath.equals(claim.targetEpisodePath, ignoreCase = true)
            }
            if (live != null) {
                // A newer live claim always wins over an older retired candidate for this source.
                forwardAdjacentValidatedRecoveryTombstones.remove(live.predecessorEpisodePath)
                if (!NtkForwardAdjacentValidatedRecoveryPolicy.shouldRearm(
                        validatedEpoch = validatedEpoch,
                        lastValidatedRedriveEpoch = live.lastValidatedRedriveEpoch,
                        boundaryMatches = boundaryMatches(
                            live.predecessorEpisodePath,
                            live.targetEpisodePath,
                        ),
                        structureCommitted = live.structureCommitted,
                    )
                ) return@synchronized null
                live.discoveryLaunchAttempts.set(0)
                live.lastValidatedRedriveEpoch = validatedEpoch
                live.lastValidatedRedriveAtMs = now
                live.pendingValidatedRedriveEpoch = 0L
                lastObservedForwardAdjacentValidatedNetworkPath = ""
                live to false
            } else {
                val tombstone =
                    forwardAdjacentValidatedRecoveryTombstones.values.firstOrNull { retired ->
                        activePath.equals(retired.predecessorEpisodePath, ignoreCase = true)
                    } ?: forwardAdjacentValidatedRecoveryTombstones.values.firstOrNull { retired ->
                        activePath.equals(retired.targetEpisodePath, ignoreCase = true)
                    } ?: return@synchronized null
                if (!NtkForwardAdjacentValidatedRecoveryPolicy.shouldRearm(
                        validatedEpoch = validatedEpoch,
                        lastValidatedRedriveEpoch = tombstone.lastValidatedRedriveEpoch,
                        boundaryMatches = boundaryMatches(
                            tombstone.predecessorEpisodePath,
                            tombstone.targetEpisodePath,
                        ),
                        structureCommitted = false,
                    )
                ) return@synchronized null
                // A fresh-list resolver can install a new target between retirement and this
                // network edge. Never replace that newer owner with the tombstoned candidate.
                if (forwardAdjacentCompletionTargetClaims[tombstone.predecessorEpisodePath] != null) {
                    forwardAdjacentValidatedRecoveryTombstones.remove(
                        tombstone.predecessorEpisodePath,
                        tombstone,
                    )
                    return@synchronized null
                }
                val restored = ForwardAdjacentCompletionTargetClaim(
                    target = tombstone.target,
                    predecessorEpisodePath = tombstone.predecessorEpisodePath,
                    targetEpisodePath = tombstone.targetEpisodePath,
                    authority = tombstone.authority,
                    revision = forwardAdjacentCompletionTargetClaimSequence.getAndIncrement(),
                    lastValidatedRedriveEpoch = validatedEpoch,
                    lastValidatedRedriveAtMs = now,
                    pendingValidatedRedriveEpoch = 0L,
                )
                forwardAdjacentCompletionTargetClaims[tombstone.predecessorEpisodePath] = restored
                forwardAdjacentCompletionTargetHistory[tombstone.targetEpisodePath] =
                    tombstone.predecessorEpisodePath
                forwardAdjacentValidatedRecoveryTombstones.remove(
                    tombstone.predecessorEpisodePath,
                    tombstone,
                )
                lastObservedForwardAdjacentValidatedNetworkPath = ""
                restored to true
            }
        } ?: return false

        val (claim, restoredFromTombstone) = selected
        if (!ViewerTelemetry.isActiveViewer(viewerGeneration, viewerOwnerPath) ||
            !NtkStrictEpisodeDiscoveryCoordinator.ntkAdjacentOwnerAllowsTarget(
                viewerOwnerPath,
                claim.targetEpisodePath,
            ) ||
            activateForwardAdjacentCompletionTargetClaim(
                claim,
                onResolvedForwardPath = null,
                controlOnly = false,
            ) == null
        ) return false
        Log.d(
            TAG,
            "append_adjacent_exact_manifest_validated_redrive " +
                "predecessor=${claim.predecessorEpisodePath},target=${claim.targetEpisodePath}," +
                "epoch=$validatedEpoch,revision=${claim.revision}," +
                "restored=$restoredFromTombstone",
        )
        return true
    }

    /**
     * A real default-network regain is the only external event allowed to reopen a recovery which
     * exhausted while its exact source was unavailable. Local decode/publication failures remain
     * terminal: replaying those on every connectivity callback would create an endless hot loop.
     */
    fun redriveCurrentForwardAdjacentExactRecoveryAfterValidated(
        validatedEpoch: Long,
    ): Boolean {
        val viewerGeneration = strictExactForegroundViewerGenerationAtCreation
        val viewerOwnerPath = strictExactViewerOwnerEpisodePathAtCreation
        if (validatedEpoch <= 0L || cancelled.get() || viewerGeneration <= 0L ||
            !ViewerTelemetry.isActiveViewer(viewerGeneration, viewerOwnerPath)
        ) return false
        val boundaryEvidence = currentAdjacentValidatedBoundaryEvidence()
        val anchor = boundaryEvidence.pageIndex
        val activePath = boundaryEvidence.normalizedEpisodePath
        val now = SystemClock.elapsedRealtime()
        var rediscoveryRequired = false
        val selected = synchronized(adjacentStrictSourceClaimLock) {
            if (validatedEpoch > lastObservedAdjacentValidatedNetworkEpoch) {
                lastObservedAdjacentValidatedNetworkEpoch = validatedEpoch
                lastObservedAdjacentValidatedNetworkPath = activePath
            } else if (validatedEpoch == lastObservedAdjacentValidatedNetworkEpoch &&
                lastObservedAdjacentValidatedNetworkPath.isEmpty() && activePath.isNotEmpty()
            ) {
                lastObservedAdjacentValidatedNetworkPath = activePath
            }
            // Preserve this real edge for every exact future body owner, but launch only the one
            // at the current physical boundary. A later boundary turn consumes the retained epoch
            // once from holdOrRecoverAdjacentStrictSource.
            for (state in adjacentStrictRecoveryStates.values) {
                if (state.awaitingReplacement &&
                    (!state.exhausted || state.networkRearmableTerminal)
                ) {
                    state.pendingValidatedRedriveEpoch =
                        NtkAdjacentValidatedEpochCatchUpPolicy.latch(
                            validatedEpoch,
                            state.lastValidatedRedriveEpoch,
                            state.pendingValidatedRedriveEpoch,
                        )
                }
            }
            fun terminalEligible(state: AdjacentStrictRecoveryState): Boolean =
                !state.retirementInProgress && state.exhausted &&
                    state.networkRearmableTerminal &&
                    state.lastValidatedRedriveEpoch < validatedEpoch
            fun activeEligible(state: AdjacentStrictRecoveryState): Boolean =
                !state.retirementInProgress && !state.exhausted &&
                    state.awaitingReplacement &&
                    state.lastValidatedRedriveEpoch < validatedEpoch
            fun predecessorMatches(entry: Map.Entry<String, AdjacentStrictRecoveryState>): Boolean =
                activePath.equals(entry.value.predecessorEpisodePath, ignoreCase = true)
            fun targetMatches(entry: Map.Entry<String, AdjacentStrictRecoveryState>): Boolean =
                activePath.equals(entry.key, ignoreCase = true)

            // At a B boundary, B -> C is the actionable tail owner while an older A -> B state can
            // still name B as its target. Preserve this deterministic predecessor-first ordering
            // for both terminal rearm and an already-active validated Flight window.
            val entries = adjacentStrictRecoveryStates.entries
            val selectedEntry = entries.firstOrNull { entry ->
                predecessorMatches(entry) && terminalEligible(entry.value)
            } ?: entries.firstOrNull { entry ->
                predecessorMatches(entry) && activeEligible(entry.value)
            } ?: entries.firstOrNull { entry ->
                targetMatches(entry) && terminalEligible(entry.value)
            } ?: entries.firstOrNull { entry ->
                targetMatches(entry) && activeEligible(entry.value)
            } ?: return@synchronized null

            val state = selectedEntry.value
            if (terminalEligible(state)) {
                state.exhausted = false
                state.awaitingReplacement = true
                state.rediscoveryRequestCount = 1
                state.lastRequestAtMs = now
                state.lastBindDeadlineAtMs = 0L
                state.terminalReported = false
                state.networkRearmableTerminal = false
                state.lastValidatedRedriveEpoch = validatedEpoch
                state.lastValidatedRedriveAtMs = now
                state.pendingValidatedRedriveEpoch = 0L
                rediscoveryRequired = true
                return@synchronized Triple(
                    selectedEntry.key,
                    state.predecessorEpisodePath,
                    state.target,
                )
            }
            // A regain may arrive while the exact replacement Flight is still present. Preserve
            // that epoch as a bounded replacement window without launching a duplicate now; the
            // target-scoped Activity watchdog may retire only this entered Flight once the window
            // expires. Intentional predecessor-gate waits are excluded by the Coordinator.
            state.lastValidatedRedriveEpoch = validatedEpoch
            state.lastValidatedRedriveAtMs = now
            state.pendingValidatedRedriveEpoch = 0L
            Triple(
                selectedEntry.key,
                state.predecessorEpisodePath,
                state.target,
            )
        } ?: return false

        val (path, predecessorPath, target) = selected
        if (!rediscoveryRequired) {
            Log.d(
                TAG,
                "append_adjacent_strict_validated_flight_observed path=$path," +
                    "predecessor=$predecessorPath,epoch=$validatedEpoch",
            )
        }
        adjacentStrictPredecessorPaths[path] = predecessorPath
        ensureAdjacentStrictRecoveryManifestSubscription()
        waitingStrictRemainingAdjacentAppends[path]?.let { waiter ->
            armAdjacentStrictRecoveryBindDeadline(path, waiter)
        }
        ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
            path,
            NTK_ADJACENT_APPEND_FOREGROUND_PATH_TTL_MS,
            "validated_network_recovery",
        )
        listener.onAdjacentExactManifestRequired(target, predecessorPath)
        scheduleDeferredAdjacentPrepare(
            anchor.coerceAtLeast(0),
            ReaderSurfaceView.DIRECTION_NEXT,
            0L,
            silentMissing = false,
        )
        Log.d(
            TAG,
            "append_adjacent_strict_validated_redrive path=$path," +
                "predecessor=$predecessorPath,epoch=$validatedEpoch",
        )
        return true
    }

    /**
     * Returns the one validated-network window which currently owns an exact adjacent Flight.
     * The Coordinator still performs the final generation/gate-phase check; this Session proof
     * only binds the external edge to the exact predecessor/target work item.
     */
    fun adjacentValidatedFlightRecoveryWindow(
        rawPredecessorPath: String,
        rawTargetPath: String,
    ): AdjacentValidatedFlightRecoveryWindow? {
        if (cancelled.get() ||
            !ViewerTelemetry.isActiveViewer(
                strictExactForegroundViewerGenerationAtCreation,
                strictExactViewerOwnerEpisodePathAtCreation,
            )
        ) return null
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(rawPredecessorPath)
        val targetPath = NtkStripDigests.normalizeEpisodePath(rawTargetPath)
        if (predecessorPath.isEmpty() || targetPath.isEmpty()) return null
        val initialWindow = synchronized(forwardAdjacentCompletionTargetClaimLock) {
            forwardAdjacentCompletionTargetClaims[predecessorPath]?.takeIf { claim ->
                !claim.structureCommitted &&
                    claim.targetEpisodePath.equals(targetPath, ignoreCase = true) &&
                    claim.lastValidatedRedriveEpoch > 0L &&
                    claim.lastValidatedRedriveAtMs > 0L
            }?.let { claim ->
                AdjacentValidatedFlightRecoveryWindow(
                    claim.lastValidatedRedriveEpoch,
                    claim.lastValidatedRedriveAtMs,
                )
            }
        }
        val bodyWindow = synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictRecoveryStates[targetPath]?.takeIf { state ->
                !state.retirementInProgress && !state.exhausted && state.awaitingReplacement &&
                    state.predecessorEpisodePath.equals(predecessorPath, ignoreCase = true) &&
                    state.lastValidatedRedriveEpoch > 0L &&
                    state.lastValidatedRedriveAtMs > 0L
            }?.let { state ->
                AdjacentValidatedFlightRecoveryWindow(
                    state.lastValidatedRedriveEpoch,
                    state.lastValidatedRedriveAtMs,
                )
            }
        }
        return when {
            initialWindow == null -> bodyWindow
            bodyWindow == null -> initialWindow
            bodyWindow.epoch > initialWindow.epoch -> bodyWindow
            bodyWindow.epoch < initialWindow.epoch -> initialWindow
            bodyWindow.observedAtMs >= initialWindow.observedAtMs -> bodyWindow
            else -> initialWindow
        }
    }

    /** Excludes HOME/background time from the adjacent validated-flight stall window. */
    fun resumeAdjacentValidatedFlightRecoveryWindows(
        pausedAtMs: Long,
        resumedAtMs: Long,
    ) {
        if (pausedAtMs <= 0L || resumedAtMs <= pausedAtMs) return
        val pausedDurationMs = resumedAtMs - pausedAtMs
        fun resumedTimestamp(observedAtMs: Long): Long = when {
            observedAtMs <= 0L || observedAtMs > resumedAtMs -> observedAtMs
            observedAtMs <= pausedAtMs -> observedAtMs + pausedDurationMs
            else -> resumedAtMs
        }
        synchronized(forwardAdjacentCompletionTargetClaimLock) {
            for (claim in forwardAdjacentCompletionTargetClaims.values) {
                claim.lastValidatedRedriveAtMs =
                    resumedTimestamp(claim.lastValidatedRedriveAtMs)
            }
        }
        synchronized(adjacentStrictSourceClaimLock) {
            for (state in adjacentStrictRecoveryStates.values) {
                state.lastValidatedRedriveAtMs =
                    resumedTimestamp(state.lastValidatedRedriveAtMs)
            }
        }
    }

    private fun reportAdjacentStrictRecoveryTerminal(path: String) {
        val shouldReport = synchronized(adjacentStrictSourceClaimLock) {
            val state = adjacentStrictRecoveryStates[path] ?: return@synchronized false
            if (!state.exhausted || !state.networkRearmableTerminal ||
                state.retirementInProgress || state.terminalReported
            ) {
                false
            } else {
                state.terminalReported = true
                // Linearize this removal with validated rearm. If rearm wins first the state check
                // above rejects the stale report; if reporting wins first, rearm republishes its
                // predecessor only after acquiring and releasing this same lock.
                adjacentStrictPredecessorPaths.remove(path)
                true
            }
        }
        if (!shouldReport) return
        Log.e(TAG, "append_adjacent_strict_recovery_terminal path=$path")
        main.post {
            val stillTerminal = synchronized(adjacentStrictSourceClaimLock) {
                adjacentStrictRecoveryStates[path]?.let { state ->
                    state.exhausted && state.networkRearmableTerminal &&
                        !state.retirementInProgress && state.terminalReported
                } == true
            }
            if (!cancelled.get() && stillTerminal) {
                listener.onMessage("다음 화 원본을 다시 불러오지 못했습니다.")
            }
        }
    }

    private fun remainingAdjacentRunwayBoundaryLocked(target: Manga): Pair<Int, Int> {
        var firstTargetIndex = -1
        var lastTargetIndex = -1
        for ((index, page) in pages.withIndex()) {
            if (page.transitionTitle != null || !looseSameEpisodeForAppend(page.manga, target)) continue
            if (firstTargetIndex < 0) firstTargetIndex = index
            lastTargetIndex = index
        }
        return firstTargetIndex to lastTargetIndex
    }

    private fun startRemainingAdjacentRunwayFileFetches(
        target: Manga,
        candidates: List<PageRef>,
        allRefs: List<PageRef>,
        publishKey: String,
        warm: Boolean
    ): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(target, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        val strictPath = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath?.trim().orEmpty()
        )
        val strictClaim = adjacentStrictSourceClaims[strictPath]
        if (strictClaim != null) {
            if (!isAdjacentStrictSourceClaimLive(strictPath, strictClaim)) {
                return holdOrRecoverAdjacentStrictSource(target)
            }
            if (isViewportInsideEpisode(target) &&
                strictClaim.viewportActivated.compareAndSet(false, true)
            ) {
                try {
                    strictClaim.transport.onAdjacentViewportActivated(strictClaim.episode)
                } catch (failure: Exception) {
                    if (cancelled.get()) {
                        strictClaim.viewportActivated.set(false)
                        return true
                    }
                    invalidateAdjacentStrictSourceClaim(
                        strictPath,
                        strictClaim,
                        "viewport_activation_failed:${failure.javaClass.simpleName}",
                    )
                    holdOrRecoverAdjacentStrictSource(target)
                    if (!isExpectedCancellation(failure)) recordIfUnexpected(failure)
                    return true
                }
                Log.d(
                    TAG,
                    "append_adjacent_strict_source_viewport_release path=$strictPath " +
                        "digest=${strictClaim.manifestDigest}",
                )
            }
            // The strict owner is either holding its proven five-body runway or has just resumed
            // the remaining workset. Never launch a generic duplicate against that ownership.
            return true
        }
        // A terminal strict generation is detached synchronously, while its exact replacement is
        // asynchronous. Keep the old canonical PageRefs fail-closed during that interval; allowing
        // the generic loader here would either collide with the new strict owner or accept a
        // foreign/non-authoritative manifest.
        if (holdOrRecoverAdjacentStrictSource(target)) return true
        val fetchLimit = remainingAdjacentRunwayFileFetchLimit(target)
        val fetchRefs = candidates
            .asSequence()
            .filter { it.transitionTitle == null }
            .filter { !it.image.isNullOrBlank() }
            .filterNot { isAdjacentRunwayRefPublishable(it) }
            .take(fetchLimit)
            .toList()
        if (fetchRefs.isEmpty()) return false
        var scheduled = 0
        for (ref in fetchRefs) {
            val image = ref.image ?: continue
            val visiblePriority = shouldFetchRemainingAdjacentRunwayAsVisiblePriority(target, ref)
            val sourceIndex = adjacentForegroundStreamRefIndex(ref, image)
            val fetchKey = "remaining-runway|${publishKey.ifEmpty { episodeAppendKey(target) }}|" +
                adjacentForegroundStreamKey(target, image, sourceIndex)
            if (!pendingRemainingAdjacentRunwayFileFetchKeys.add(fetchKey)) continue
            scheduled++
            try {
                sourcePrefetchNetwork.execute {
                    var ready = false
                    try {
                        withProtectedNumericNetworkPermit(ref.manga) {
                            ReaderImageCache.getOrFetchFileForeground(
                                appContext,
                                ref.manga,
                                image,
                                imageCancellation,
                                visiblePriority = visiblePriority
                            )
                        }
                        ready = ReaderImageCache.cachedFile(appContext, ref.manga, image) != null
                    } catch (e: Exception) {
                        if (!isExpectedCancellation(e)) {
                            Log.d(
                                TAG,
                                "append_adjacent_runway_remaining_file_fetch_error targetId=${target.id} " +
                                    "path=${target.ntkEpisodePath} image=${image.substringAfterLast('/')} " +
                                    "error=${e.javaClass.simpleName}:${e.message}"
                            )
                            recordIfUnexpected(e)
                        }
                    } finally {
                        pendingRemainingAdjacentRunwayFileFetchKeys.remove(fetchKey)
                    }
                    if (ready && !cancelled.get()) {
                        scheduleRemainingAdjacentRunwayAppend(target, allRefs, publishKey, warm)
                    }
                }
            } catch (_: RejectedExecutionException) {
                pendingRemainingAdjacentRunwayFileFetchKeys.remove(fetchKey)
            }
        }
        if (scheduled > 0) {
            Log.d(
                TAG,
                "append_adjacent_runway_remaining_file_fetch targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} scheduled=$scheduled candidates=${candidates.size} limit=$fetchLimit"
            )
        }
        return scheduled > 0
    }

    private fun remainingAdjacentRunwayFileFetchLimit(target: Manga): Int {
        if (isViewportInsideEpisode(target)) {
            return NTK_APPEND_REMAINING_RUNWAY_FOREGROUND_FILE_FETCH_PAGES
        }
        return if (
            isImmediateNtkGeneratedUx() &&
            (isActiveGeneratedTouchOrQuiet() || viewportBusy.get())
        ) {
            NTK_APPEND_REMAINING_RUNWAY_ACTIVE_FILE_FETCH_PAGES
        } else {
            NTK_APPEND_REMAINING_RUNWAY_FILE_FETCH_PAGES
        }
    }

    private fun shouldFetchRemainingAdjacentRunwayAsVisiblePriority(target: Manga, ref: PageRef): Boolean {
        if (!isImmediateNtkGeneratedUx()) return true
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return true
        if (!isActiveGeneratedTouchOrQuiet() && !viewportBusy.get()) return true
        val anchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?: currentStartPage()
        if (anchor < 0) return false
        val predictedIndex = synchronized(pagesLock) {
            predictedRemainingAdjacentRunwayGlobalIndexLocked(target, ref)
        }
        if (predictedIndex < 0) return false
        return predictedIndex <= anchor + NTK_APPEND_REMAINING_ACTIVE_VISIBLE_PRIORITY_AHEAD_PAGES
    }

    private fun predictedRemainingAdjacentRunwayGlobalIndexLocked(target: Manga, ref: PageRef): Int {
        val sourceIndex = ref.sourceIndex.takeIf { it >= 0 }
            ?: ntkImagePageNumber(ref.image.orEmpty())?.minus(1)
            ?: return pages.size
        var firstGlobal = -1
        var firstSource = Int.MAX_VALUE
        for ((globalIndex, page) in pages.withIndex()) {
            if (page.transitionTitle != null) continue
            if (!looseSameEpisodeForAppend(page.manga, target)) continue
            val localSource = page.sourceIndex.takeIf { it >= 0 }
                ?: ntkImagePageNumber(page.image.orEmpty())?.minus(1)
                ?: continue
            if (localSource < firstSource) {
                firstSource = localSource
                firstGlobal = globalIndex
            }
        }
        if (firstGlobal < 0 || firstSource == Int.MAX_VALUE) return pages.size
        return firstGlobal + (sourceIndex - firstSource).coerceAtLeast(0)
    }

    private fun hasPendingRemainingAdjacentRunwayFileFetch(
        target: Manga,
        candidates: List<PageRef>,
        publishKey: String
    ): Boolean {
        val keyPrefix = "remaining-runway|${publishKey.ifEmpty { episodeAppendKey(target) }}|"
        for (ref in candidates.take(remainingAdjacentRunwayFileFetchLimit(target))) {
            val image = ref.image ?: continue
            val sourceIndex = adjacentForegroundStreamRefIndex(ref, image)
            val fetchKey = keyPrefix + adjacentForegroundStreamKey(target, image, sourceIndex)
            if (pendingRemainingAdjacentRunwayFileFetchKeys.contains(fetchKey)) return true
        }
        return false
    }

    private data class AdjacentRunwayAppendableSnapshot(
        val refs: List<PageRef>,
        val maxInstalledSourceIndex: Int = -1,
        val sourceGapFirst: Int = -1,
    )

    private fun appendableRemainingAdjacentRunwayRefsLocked(
        target: Manga,
        refs: List<PageRef>
    ): AdjacentRunwayAppendableSnapshot {
        val targetKey = episodeAppendKey(target)
        val existing = HashSet<String>()
        var maxInstalledSourceIndex = -1
        for (page in pages) {
            val same = if (targetKey.isNotEmpty()) {
                episodeAppendKey(page.manga) == targetKey
            } else {
                Manga.sameEpisodeIdentity(page.manga, target)
            }
            if (same) {
                existing.add(runwayPageRefIdentity(page))
                if (page.transitionTitle == null && page.sourceIndex >= 0) {
                    maxInstalledSourceIndex = maxOf(maxInstalledSourceIndex, page.sourceIndex)
                }
            }
        }
        val remaining = refs.filter { existing.add(runwayPageRefIdentity(it)) }
        if (!isImmediateNtkGeneratedUx() ||
            !isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath) ||
            remaining.any { it.transitionTitle != null || it.sourceIndex < 0 }
        ) {
            return AdjacentRunwayAppendableSnapshot(remaining)
        }
        // Completion callbacks can enqueue stale remaining-ref snapshots in different orders.
        // The control lane serializes publication, but it cannot repair a stale list that was
        // already a partial suffix. Canonical source order and a no-gap prefix are the final
        // structure-publish fence.
        val ordered = remaining.sortedWith(
            compareBy<PageRef> { it.sourceIndex }
                .thenBy { it.side }
        )
        val contiguousCount = NtkAdjacentRunwayRefreshPolicy.contiguousPrefixLength(
            maxInstalledSourceIndex,
            ordered.map { it.sourceIndex },
        )
        if (contiguousCount == 0 && ordered.isNotEmpty()) {
            Log.d(
                TAG,
                "append_adjacent_runway_remaining_wait_source_gap targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} installedMax=$maxInstalledSourceIndex " +
                    "candidateFirst=${ordered.first().sourceIndex} candidates=${ordered.size}"
            )
        }
        return AdjacentRunwayAppendableSnapshot(
            refs = ordered.take(contiguousCount),
            maxInstalledSourceIndex = maxInstalledSourceIndex,
            sourceGapFirst = ordered.firstOrNull()
                ?.sourceIndex
                ?.takeIf { contiguousCount == 0 && it > maxInstalledSourceIndex + 1 }
                ?: -1,
        )
    }

    private fun runwayPageRefIdentity(ref: PageRef): String {
        ref.transitionTitle?.let { return "card:$it" }
        if (
            ref.sourceIndex >= 0 &&
            isNtkSource(ref.manga, title) &&
            isNtkManhwaOrWebtoonEpisodePath(ref.manga.ntkEpisodePath)
        ) {
            // The transport URL can be refreshed while one immutable source slot stays the same,
            // so URL is deliberately excluded. Path plus exact manifest identity prevents a
            // privately staged boundary head from crossing an adjacent-target refresh or source
            // generation while retaining idempotence for replica/URL updates of the same body.
            val path = NtkStripDigests.normalizeEpisodePath(
                ref.manga.ntkEpisodePath.orEmpty(),
            )
            return "image:$path:${ref.manifestDigest.orEmpty()}:" +
                "${ref.manifestPageCount}:${ref.sourceIndex}:${ref.side}"
        }
        return "image:${ref.sourceIndex}:${ref.side}:${ref.image.orEmpty()}"
    }

    private fun adjacentRunwayPublishablePrefixCount(refs: List<PageRef>): Int {
        var count = 0
        for (ref in refs) {
            if (!isAdjacentRunwayRefPublishable(ref)) break
            count++
        }
        return count
    }

    private fun isAdjacentRunwayRefPublishable(ref: PageRef): Boolean {
        if (ref.transitionTitle != null) return true
        if (!isImmediateNtkGeneratedUx()) return true
        if (!isNtkSource(ref.manga, title)) return true
        if (!isNtkManhwaOrWebtoonEpisodePath(ref.manga.ntkEpisodePath)) return true
        val image = ref.image.orEmpty()
        if (image.isBlank()) return false
        val strictManifestAuthority = requiresStrictAdjacentExactBody(ref)
        if (strictAdjacentBodyDescriptor(ref) != null) {
            return NtkAdjacentRunwayBodyAuthorityPolicy.isPublishable(
                strictManifestAuthority = strictManifestAuthority,
                descriptorReady = true,
                strictBodyReady = false,
                genericCacheReady = false,
            )
        }
        // The emulator-only direct-Wi-Fi manhwa runway is one atomic p0..p3 publication. Once an
        // exact manifest owns it, every page must still own its live generation-bound descriptor;
        // a disk body from an old strict claim is not sufficient proof for this batch.
        if (strictManifestAuthority) return false
        if (strictAdjacentPublishedBody(ref) != null) {
            return NtkAdjacentRunwayBodyAuthorityPolicy.isPublishable(
                strictManifestAuthority = strictManifestAuthority,
                descriptorReady = false,
                strictBodyReady = true,
                genericCacheReady = false,
            )
        }
        return NtkAdjacentRunwayBodyAuthorityPolicy.isPublishable(
            strictManifestAuthority = false,
            descriptorReady = false,
            strictBodyReady = false,
            genericCacheReady =
                ReaderImageCache.cachedFile(appContext, ref.manga, image) != null,
        )
    }

    private fun requiresStrictAdjacentExactBody(ref: PageRef): Boolean {
        if (ref.transitionTitle != null || ref.sourceIndex < 0) return false
        if (!hostGpuEmulatorRuntime ||
            !isDirectWifiStrictAdjacentTransportActive() ||
            !isDirectWifiStrictAdjacentRunwayProfile(ref.manga)
        ) return false
        val path = NtkStripDigests.normalizeEpisodePath(
            ref.manga.ntkEpisodePath?.trim().orEmpty(),
        )
        if (!path.startsWith("/manhwa/")) return false
        // This is an immutable PageRef proof, not a live-registry lookup. If its authority retires
        // between admission and decode, the final descriptor lookup must fail closed instead of
        // reclassifying the same exact page as a generic-cache candidate.
        return ref.manifestDigest.isNotBlank() && ref.manifestPageCount > 0
    }

    /**
     * Adjacent exact discovery owns its bodies in the strict source store, not the generic image
     * cache. Treating only [ReaderImageCache.cachedFile] as ready leaves the transition card as
     * the sole publishable runway item even after every exact body has completed.
     */
    private fun strictAdjacentPublishedBody(
        ref: PageRef
    ): ReaderImageCache.NtkStrictPublishedBody? {
        if (ref.transitionTitle != null || ref.sourceIndex < 0) return null
        val path = NtkStripDigests.normalizeEpisodePath(
            ref.manga.ntkEpisodePath?.trim().orEmpty()
        )
        if (path.isEmpty()) return null
        val authority = NtkSourceSpoolRegistry.currentAuthoritativeManifest(path) ?: return null
        val seal = authority.seal
        if (!NtkAdjacentEpisodeAuthorityPolicy.supportsStrictAdjacentManifest(authority, path) ||
            ref.sourceIndex !in seal.normalizedCanonicalAssets.indices ||
            ref.manifestDigest != seal.digestSha256 ||
            ref.manifestPageCount != seal.pageCount ||
            ref.canonicalAsset != seal.normalizedCanonicalAssets[ref.sourceIndex]
        ) {
            return null
        }
        val image = ref.image.orEmpty()
        if (image.isBlank()) return null
        val published = ReaderImageCache.strictCachedPublishedBody(
            appContext,
            ref.manga,
            image,
            seal,
            ref.sourceIndex,
        )
        val current = NtkSourceSpoolRegistry.currentAuthoritativeManifest(path)
        return published?.takeIf {
            current?.seal?.revision == seal.revision &&
                current.seal.digestSha256 == seal.digestSha256 &&
                it.metadata.canonicalAsset == ref.canonicalAsset &&
                it.proof.encodedLength > 0L
        }
    }

    private fun isStrictAdjacentExactPage(ref: PageRef): Boolean {
        if (!strictExactColdRolling || Manga.sameEpisodeIdentity(ref.manga, manga)) return false
        if (ref.transitionTitle != null || ref.sourceIndex < 0 ||
            ref.manifestDigest.isBlank() || ref.manifestPageCount <= 0
        ) return false
        val path = NtkStripDigests.normalizeEpisodePath(
            ref.manga.ntkEpisodePath?.trim().orEmpty(),
        )
        if (path.isEmpty()) return false
        adjacentStrictSourceClaims[path]?.let { claim ->
            if (claim.manifestDigest == ref.manifestDigest) return true
        }
        val recovering = synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictRecoveryStates[path]
                ?.expectedManifestDigest
                ?.equals(ref.manifestDigest, ignoreCase = true) == true
        }
        return recovering
    }

    private fun strictAdjacentRehydrateIdentity(ref: PageRef): String? {
        if (!isStrictAdjacentExactPage(ref)) return null
        val path = NtkStripDigests.normalizeEpisodePath(
            ref.manga.ntkEpisodePath?.trim().orEmpty(),
        )
        if (path.isEmpty() || ref.sourceIndex < 0 || ref.canonicalAsset.isBlank()) return null
        return buildString {
            append(path)
            append('|')
            append(ref.manifestDigest)
            append('|')
            append(ref.manifestPageCount)
            append('|')
            append(ref.sourceIndex)
            append('|')
            append(NtkStripDigests.canonicalAssetDigestSha256(ref.canonicalAsset))
        }
    }

    private fun wakeStrictAdjacentExactRehydrate(
        path: String,
        manifestDigest: String,
        sourceIndex: Int,
    ) {
        strictAdjacentRehydrateFlights.values.forEach { flight ->
            val page = flight.page
            if (page.sourceIndex != sourceIndex ||
                page.manifestDigest != manifestDigest ||
                NtkStripDigests.normalizeEpisodePath(
                    page.manga.ntkEpisodePath?.trim().orEmpty(),
                ) != path
            ) return@forEach
            flight.wakeVersion.incrementAndGet()
            flight.retryCount.set(0)
            flight.parked.set(false)
            scheduleStrictAdjacentExactRehydrate(
                flight,
                flight.visibleIntent || flight.compositorForwardWarmIntent.get(),
            )
        }
        requestLatestExactAdjacentCompositorForwardWarm()
    }

    /**
     * An attached strict-adjacent page must never fall back to the generic foreground ByteFlight.
     * That flight is intentionally rejected while the strict source owns the canonical body. The
     * old path released its per-frame marker after each rejection, causing thousands of retries
     * and leaving an evicted page blank until the reader was recreated. Keep one identity-bound
     * owner and re-decode the already-published exact body instead.
     */
    private fun shouldKeepHostPressureRetiredExactPageParked(
        index: Int,
        page: PageRef,
    ): Boolean {
        if (hostExactPoolPressureRetiredPages.isEmpty()) return false
        val retiredState = synchronized(pagesLock) {
            val currentIndex = pageIndexLocked(page, index)
            if (currentIndex !in pages.indices ||
                !hostExactPoolPressureRetiredPages.contains(currentIndex)
            ) {
                return@synchronized null
            }
            val anchor = currentViewportAnchor.get()
                .takeIf { it in pages.indices }
                ?: currentStartPage().coerceIn(0, pages.lastIndex)
            val physicalWindow = reportedHostPressureRehydrateWindowLocked(anchor)
            val physicallyVisible = HostExactHardwareTilePoolPressurePolicy
                .isPhysicalRehydrateEligible(
                    pageIndex = currentIndex,
                    physicalVisibleFirst = physicalWindow.first,
                    physicalVisibleLast = physicalWindow.last,
                ) || latestPhysicalForwardIntentPage.get() === page
            currentIndex to physicallyVisible
        } ?: return false
        if (!retiredState.second) {
            // The canonical encoded body remains ready. Treat this pixel request as joined so
            // proof/runway callers do not fall through to another exact route, and leave the
            // park bit intact until a real Surface viewport intersects the page.
            return true
        }
        // The pressure marker is published before the main-thread Surface clear. Leaving it
        // parked until that clear is observable prevents adopting the old drawable immediately
        // before the queued clear blanks it. Never call the listener while holding pagesLock.
        return listener.isPageAuthoritativeDrawableCurrentlyInstalled(retiredState.first)
    }

    private fun canAccessAppendOnlyStablePrefix(index: Int): Boolean {
        val pendingStructurePublishes = structurePublishPending.get()
        if (pendingStructurePublishes <= 0) return true
        return HostExactHardwareTilePoolPressurePolicy.canPublishStablePrefixRetirement(
            pendingStructurePublishes = pendingStructurePublishes,
            appendOnlyStablePrefixCounts =
                appendOnlyStructurePublishStablePrefixCounts.values.toIntArray(),
            targetIndexes = intArrayOf(index),
        )
    }

    private fun requestHostPressureStablePrefixDuringAppendOnlyPublish(
        fallbackAnchor: Int,
    ) {
        if (hostExactPoolPressureRetiredPages.isEmpty()) return
        val candidates = synchronized(pagesLock) {
            val physicalWindow =
                reportedHostPressureRehydrateWindowLocked(fallbackAnchor)
            if (physicalWindow.isEmpty()) return@synchronized emptyList()
            hostExactPoolPressureRetiredPages.asSequence()
                .filter { index -> index in physicalWindow && index in pages.indices }
                .filter(::canAccessAppendOnlyStablePrefix)
                .mapNotNull { index ->
                    pages[index].takeIf { page ->
                        strictAdjacentRehydrateIdentity(page) != null
                    }?.let { page -> index to page }
                }
                .toList()
        }
        candidates.forEach { (index, page) ->
            routeStrictAdjacentExactRehydrate(index, page, visibleIntent = true)
        }
    }

    private fun routeStrictAdjacentExactRehydrate(
        index: Int,
        page: PageRef,
        visibleIntent: Boolean,
        compositorForwardWarmIntent: Boolean = false,
    ): Boolean {
        val identity = strictAdjacentRehydrateIdentity(page) ?: return false
        val compositorForwardWarmEligible = compositorForwardWarmIntent &&
            isLatestExactAdjacentCompositorForwardWarm(index, page)
        if (compositorForwardWarmIntent && !compositorForwardWarmEligible) return true
        if (shouldKeepHostPressureRetiredExactPageParked(index, page)) return true
        if ((pendingDeliveryWidths[index] ?: 0) > 0) {
            val physicalPendingIntent = visibleIntent &&
                (latestPhysicalForwardIntentPage.get() === page ||
                    isStrictAdjacentPageInReportedPhysicalIntent(index, page))
            if (physicalPendingIntent || compositorForwardWarmEligible) {
                scheduleBlockedForwardPendingDeliveryAudit(
                    index,
                    page,
                    identity,
                    compositorForwardWarmIntent =
                        compositorForwardWarmEligible && !physicalPendingIntent,
                )
            }
            return true
        }
        if (listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)) {
            adoptAuthoritativeListenerDrawable(index, page, "strict_adjacent_rehydrate_route")
            retireSettledStrictAdjacentRehydrateFlight(index, page)
            return true
        }
        // deliveredBitmaps/deliveredTiles are Session-side lifetime ledgers, not proof that the
        // Surface still owns pixels. A pending install can be retired or structurally invalidated
        // after Session tracking succeeds. If the current Surface disagrees, continue through the
        // generation-bound body route and repair it with the same canonical original.
        if (isAdjacentDrawableBatchPublicationPending(page)) {
            // Remaining-runway publication exposes the immutable PageRef under pagesLock before
            // its already-decoded bitmap is installed on main. Starting a rehydrate in that gap
            // allocates a second full original; a wide visible page can then wait for the first
            // copy to retire even though that first copy is exactly the one about to be shown.
            // A different appended page may spend much longer decoding, however, and must not
            // block recovery of this already-published stable-prefix page. The final publication
            // owner above always redrives the retained viewport for this exact PageRef.
            return true
        }
        val pressureClaim = claimHostPressureRetiredExactPageForRehydrate(index, page)
        if (pressureClaim == HostPressureRehydrateClaim.BLOCKED) return true
        val exactAdjacentPhysicalIntent =
            pressureClaim == HostPressureRehydrateClaim.CLAIMED ||
                isStrictAdjacentPageInReportedPhysicalIntent(index, page)
        // A strict-launch bitmap snapshot intentionally fails closed after the physical viewport
        // enters an appended episode: that window has no launch sources from which to publish a
        // new launch admission. A pressure marker, however, was created from this exact PageRef
        // and [CLAIMED] proves that the current real-input frontier now intersects it. That
        // identity-bound physical claim is the adjacent page's one-shot bitmap admission; every
        // non-pressure request must still satisfy the ordinary protected snapshot below.
        if (pressureClaim == HostPressureRehydrateClaim.NOT_RETIRED &&
            !exactAdjacentPhysicalIntent &&
            !compositorForwardWarmEligible &&
            !isInsideProtectedNumericBitmapWindow(index, page)
        ) {
            return true
        }
        if (compositorForwardWarmEligible &&
            strictAdjacentBodyDescriptor(page) == null &&
            strictAdjacentPublishedBody(page) == null
        ) {
            // Byte acquisition remains solely owned by compositor source demand. A descriptor
            // publication edge re-enters requestLatestExactAdjacentCompositorForwardWarm().
            return true
        }
        val flight = StrictAdjacentRehydrateFlight(
            identity = identity,
            page = page,
            initialIndex = index,
            startedAtMs = SystemClock.elapsedRealtime(),
            visibleIntent = visibleIntent,
            hostPressurePhysicalReentry = AtomicBoolean(
                pressureClaim == HostPressureRehydrateClaim.CLAIMED,
            ),
            exactAdjacentPhysicalIntent = AtomicBoolean(exactAdjacentPhysicalIntent),
            compositorForwardWarmIntent = AtomicBoolean(compositorForwardWarmEligible),
        )
        while (true) {
            val owner = strictAdjacentRehydrateFlights.putIfAbsent(identity, flight)
            if (owner == null) {
                scheduleStrictAdjacentExactRehydrate(flight, visibleIntent)
                break
            }
            val ownerStillPublished = synchronized(pagesLock) {
                pageIndexLocked(owner.page, owner.initialIndex) >= 0
            }
            if (!ownerStillPublished &&
                strictAdjacentRehydrateFlights.remove(identity, owner)
            ) {
                // A deferred initial append may publish, roll back during physical motion, and
                // then publish fresh PageRefs for the same immutable source identity. The old
                // flight cannot resolve by object identity; replace it atomically instead of
                // letting that tombstone consume every request for the new PageRef.
                continue
            }
            val promotedPressureIntent =
                pressureClaim == HostPressureRehydrateClaim.CLAIMED &&
                    owner.hostPressurePhysicalReentry.compareAndSet(false, true)
            val promotedPhysicalIntent = exactAdjacentPhysicalIntent &&
                owner.exactAdjacentPhysicalIntent.compareAndSet(false, true)
            val promotedCompositorForwardWarm = compositorForwardWarmEligible &&
                owner.compositorForwardWarmIntent.compareAndSet(false, true)
            val repeatedPhysicalWake = visibleIntent && exactAdjacentPhysicalIntent &&
                owner.parked.compareAndSet(true, false)
            val repeatedCompositorForwardWarmWake = compositorForwardWarmEligible &&
                owner.parked.compareAndSet(true, false)
            val idlePhysicalOwnerWake =
                NtkAdjacentExactRehydrateLivenessPolicy.shouldRedriveIdleOwner(
                    exactPhysicalIntent = exactAdjacentPhysicalIntent,
                    parked = owner.parked.get(),
                    scheduledOrRunning = owner.ownerScheduledOrRunning.get(),
                )
            if (promotedPressureIntent || promotedPhysicalIntent || repeatedPhysicalWake ||
                promotedCompositorForwardWarm || repeatedCompositorForwardWarmWake ||
                idlePhysicalOwnerWake
            ) {
                // A speculative flight can be registered before its PageRef reaches the real
                // drawable-prefix fence. Physical intent belongs to the immutable PageRef, not
                // to the moment the worker was created, so promote that existing owner instead of
                // leaving it parked behind an idle-only decode gate. The identity map still keeps
                // exactly one decoder and the next page cannot be promoted until Surface reports
                // its own blocker.
                //
                // A promoted owner keeps its physical bit after a bounded body-unavailable wave.
                // Therefore compareAndSet(false, true) is not a later wake edge. A new real
                // drawable-prefix callback for the same still-parked identity must reopen exactly
                // one bounded wave; otherwise a source body published after the first twenty
                // probes can leave the pipeline IDLE behind a permanent forward cap.
                // Surface physical intersection is the authoritative visibility proof here. Its
                // window can contain two partial pages while the priority heuristic chooses only
                // one anchor, so requiring visibleIntent would strand the other on-screen page.
                owner.wakeVersion.incrementAndGet()
                owner.retryCount.set(0)
                owner.motionDeferred.set(false)
                owner.parked.set(false)
                scheduleStrictAdjacentExactRehydrate(owner, true)
            }
            if (owner.parked.get() && !owner.motionDeferred.get() &&
                (strictAdjacentBodyDescriptor(owner.page) != null ||
                    strictAdjacentPublishedBody(owner.page) != null)
            ) {
                // Body publication is allowed to precede PageRef/flight registration. If that
                // edge was already emitted, a later real viewport request is itself a durable
                // wake: re-probe the currently published exact body instead of waiting for an
                // event that cannot repeat.
                owner.wakeVersion.incrementAndGet()
                owner.retryCount.set(0)
                owner.parked.set(false)
                scheduleStrictAdjacentExactRehydrate(owner, owner.visibleIntent || visibleIntent)
            }
            break
        }
        return true
    }

    /**
     * An atomic adjacent batch or another retained delivery can satisfy a pending exact flight
     * before its own worker runs. Once Surface proves this immutable page is installed, keeping
     * the old coordination owner serves no lifetime purpose and can suppress a later rehydrate.
     */
    private fun retireSettledStrictAdjacentRehydrateFlight(index: Int, page: PageRef) {
        val identity = strictAdjacentRehydrateIdentity(page) ?: return
        val settled = strictAdjacentRehydrateFlights[identity] ?: return
        // Surface can be satisfied by another exact publisher while this owner is genuinely
        // decoding. Leave that worker registered until its normal completion path observes the
        // installed identity; only a parked/idle coordination tombstone is redundant here.
        if (settled.ownerScheduledOrRunning.get() ||
            !strictAdjacentRehydrateFlights.remove(identity, settled)
        ) return
        initialInteractiveRunwayByteFetches.remove(settled.initialIndex)
        initialInteractiveRunwayByteFetches.remove(index)
    }

    /**
     * A pending-width entry is only an ownership claim; it is not proof that Surface received the
     * pixels. The physical drawable-prefix blocker is stronger evidence. Promote a real queued
     * owner immediately. If the claim has no queue/backlog owner after an ordered main-loop grace
     * turn, clear only that observed value and re-enter the exact-body route. This closes the
     * decode-finished / busy-discard / blocked-window race without starting a duplicate while a
     * legitimate main publication is still queued.
     */
    private fun scheduleBlockedForwardPendingDeliveryAudit(
        fallbackIndex: Int,
        page: PageRef,
        identity: String,
        compositorForwardWarmIntent: Boolean = false,
        enteredCompletionPath: String? = null,
    ) {
        if (blockedForwardPendingAudits.containsKey(identity)) return
        val audit = object : Runnable {
            override fun run() {
                if (blockedForwardPendingAudits.remove(identity, this).not()) return
                if (cancelled.get()) return
                val currentIndex = currentPageIndex(page, fallbackIndex)
                if (currentIndex < 0 || pageRef(currentIndex) !== page) return
                if (listener.isPageAuthoritativeDrawableCurrentlyInstalled(currentIndex)) {
                    pendingDeliveryWidths.remove(currentIndex)
                    adoptAuthoritativeListenerDrawable(
                        currentIndex,
                        page,
                        "blocked_forward_pending_surface",
                    )
                    return
                }
                val queued = takeQueuedVisibleDelivery(currentIndex)
                if (queued != null) {
                    deliverDecodeResultOnMain(
                        queued.copy(
                            index = currentIndex,
                            retainWhenBusy = true,
                            authoritativeAdjacentRehydrate = true,
                            exactAdjacentPhysicalIntent =
                                queued.exactAdjacentPhysicalIntent ||
                                    !compositorForwardWarmIntent,
                            compositorForwardWarmIntent =
                                queued.compositorForwardWarmIntent ||
                                    compositorForwardWarmIntent,
                        ),
                        busy = true,
                    )
                    return
                }
                val pending = pendingDeliveryWidths[currentIndex] ?: return
                if (!pendingDeliveryWidths.remove(currentIndex, pending)) return
                Log.d(
                    TAG,
                    "reader_blocked_forward_stale_pending_released page=$currentIndex " +
                        "source=${page.sourceIndex} width=$pending " +
                        "enteredCompletion=${enteredCompletionPath != null}",
                )
                if (enteredCompletionPath != null) {
                    // We are already on main. Relinquish the currently looping completion owner
                    // before re-entering it so the now-unclaimed exact descriptor is decoded by
                    // the ordinary one-page idle-completion path, not a new generic image owner.
                    enteredExactEpisodePixelCompletionPaths.remove(enteredCompletionPath)
                    requestEnteredExactEpisodePixelCompletion(enteredCompletionPath)
                    return
                }
                try {
                    control.execute {
                        if (cancelled.get()) return@execute
                        val remapped = currentPageIndex(page, currentIndex)
                        if (remapped >= 0) {
                            routeStrictAdjacentExactRehydrate(
                                remapped,
                                page,
                                visibleIntent = true,
                                compositorForwardWarmIntent =
                                    compositorForwardWarmIntent,
                            )
                        }
                    }
                } catch (_: RejectedExecutionException) {
                    // Session teardown owns cancellation.
                }
            }
        }
        if (blockedForwardPendingAudits.putIfAbsent(identity, audit) != null) return
        val promote = Runnable {
            if (cancelled.get() || blockedForwardPendingAudits[identity] !== audit) return@Runnable
            val currentIndex = currentPageIndex(page, fallbackIndex)
            if (currentIndex < 0 || pageRef(currentIndex) !== page) {
                blockedForwardPendingAudits.remove(identity, audit)
                return@Runnable
            }
            val queued = takeQueuedVisibleDelivery(currentIndex)
            if (queued != null) {
                blockedForwardPendingAudits.remove(identity, audit)
                deliverDecodeResultOnMain(
                    queued.copy(
                        index = currentIndex,
                        retainWhenBusy = true,
                        authoritativeAdjacentRehydrate = true,
                        exactAdjacentPhysicalIntent =
                            queued.exactAdjacentPhysicalIntent ||
                                !compositorForwardWarmIntent,
                        compositorForwardWarmIntent =
                            queued.compositorForwardWarmIntent ||
                                compositorForwardWarmIntent,
                    ),
                    busy = true,
                )
            } else if (!main.postDelayed(audit, BLOCKED_FORWARD_PENDING_AUDIT_DELAY_MS)) {
                blockedForwardPendingAudits.remove(identity, audit)
            }
        }
        if (!main.post(promote)) blockedForwardPendingAudits.remove(identity, audit)
    }

    /**
     * Maps the Surface's immutable PageRef-based report through any prefix compaction. The
     * Surface deliberately places the first drawable-prefix blocker in this physical interval,
     * so this is real input demand rather than a speculative decode-ahead permission.
     */
    private fun isStrictAdjacentPageInReportedPhysicalIntent(
        index: Int,
        page: PageRef,
    ): Boolean {
        if (latestPhysicalForwardIntentPage.get() === page) return true
        if (latestReportedWindow.get() == null) return false
        return synchronized(pagesLock) {
            val currentIndex = pageIndexLocked(page, index)
            if (currentIndex !in pages.indices ||
                strictAdjacentRehydrateIdentity(pages[currentIndex]) == null
            ) {
                return@synchronized false
            }
            val fallbackAnchor = currentViewportAnchor.get()
                .takeIf { it in pages.indices }
                ?: currentIndex
            currentIndex in reportedPhysicalWindowLocked(
                fallbackAnchor = fallbackAnchor,
                fallbackFirst = fallbackAnchor,
                fallbackLast = fallbackAnchor,
            )
        }
    }

    private fun claimHostPressureRetiredExactPageForRehydrate(
        index: Int,
        page: PageRef,
    ): HostPressureRehydrateClaim {
        if (hostExactPoolPressureRetiredPages.isEmpty()) {
            return HostPressureRehydrateClaim.NOT_RETIRED
        }
        return synchronized(pagesLock) {
            val currentIndex = pageIndexLocked(page, index)
            if (currentIndex !in pages.indices) {
                return@synchronized HostPressureRehydrateClaim.BLOCKED
            }
            if (!hostExactPoolPressureRetiredPages.contains(currentIndex)) {
                return@synchronized HostPressureRehydrateClaim.NOT_RETIRED
            }
            val anchor = currentViewportAnchor.get()
                .takeIf { it in pages.indices }
                ?: currentStartPage().coerceIn(0, pages.lastIndex)
            val physicalWindow = reportedHostPressureRehydrateWindowLocked(anchor)
            val physicallyVisible = HostExactHardwareTilePoolPressurePolicy
                .isPhysicalRehydrateEligible(
                    pageIndex = currentIndex,
                    physicalVisibleFirst = physicalWindow.first,
                    physicalVisibleLast = physicalWindow.last,
                ) || latestPhysicalForwardIntentPage.get() === page
            if (!physicallyVisible) {
                return@synchronized HostPressureRehydrateClaim.BLOCKED
            }
            // Every pending/listener/publication check in the route has passed, including proof
            // that the asynchronous Surface clear completed. Exactly one claimant may now decode.
            if (hostExactPoolPressureRetiredPages.remove(currentIndex)) {
                HostPressureRehydrateClaim.CLAIMED
            } else {
                HostPressureRehydrateClaim.BLOCKED
            }
        }
    }

    private fun requestLatestPhysicalForwardIntentPage() {
        val intent = latestPhysicalForwardIntentPage.get() ?: return
        val current = synchronized(pagesLock) {
            val index = pageIndexLocked(intent, -1)
            if (index !in pages.indices || pages[index] !== intent) null else index to intent
        }
        if (current == null) {
            latestPhysicalForwardIntentPage.compareAndSet(intent, null)
            return
        }
        routeStrictAdjacentExactRehydrate(
            current.first,
            current.second,
            visibleIntent = true,
        )
    }

    private fun scheduleStrictAdjacentExactRehydrate(
        flight: StrictAdjacentRehydrateFlight,
        visibleIntent: Boolean,
    ) {
        if (cancelled.get() || strictAdjacentRehydrateFlights[flight.identity] !== flight) return
        if (flight.parked.get() ||
            !flight.ownerScheduledOrRunning.compareAndSet(false, true)
        ) return
        val effectiveVisibleIntent = visibleIntent ||
            flight.hostPressurePhysicalReentry.get() ||
            flight.exactAdjacentPhysicalIntent.get() ||
            flight.compositorForwardWarmIntent.get()
        val executor = if (effectiveVisibleIntent) urgentDecode else decode
        val ownerAttemptVersion = flight.ownerAttemptVersion.incrementAndGet()
        try {
            executor.execute {
                try {
                    runStrictAdjacentExactRehydrate(flight, effectiveVisibleIntent)
                } finally {
                    // Every executor exit, including an unchecked native/JVM failure or a stale
                    // early return, must retire its running claim. A retry can already have
                    // scheduled a newer attempt from inside this worker, so only the generation
                    // which acquired this claim may clear it.
                    if (flight.ownerAttemptVersion.get() == ownerAttemptVersion) {
                        flight.ownerScheduledOrRunning.compareAndSet(true, false)
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            if (flight.ownerAttemptVersion.get() == ownerAttemptVersion) {
                flight.ownerScheduledOrRunning.compareAndSet(true, false)
            }
            postStrictAdjacentExactRehydrateRetry(flight, visibleIntent)
        }
    }

    private fun runStrictAdjacentExactRehydrate(
        flight: StrictAdjacentRehydrateFlight,
        visibleIntent: Boolean,
    ) {
        if (cancelled.get() || strictAdjacentRehydrateFlights[flight.identity] !== flight) return
        val currentIndex = currentPageIndex(flight.page, flight.initialIndex)
        val currentPage = pageRef(currentIndex)
        val compositorForwardWarmEligible = currentPage != null &&
            flight.compositorForwardWarmIntent.get() &&
            isLatestExactAdjacentCompositorForwardWarm(currentIndex, currentPage)
        // Physical intent is an admission captured for one worker/post/main hand-off, not a
        // lifetime pin on this PageRef. If the queued worker has not begun decoding before the
        // real Surface window moves elsewhere, no hand-off exists to preserve. Downgrade that
        // stale bit before the normal protected-window check below. Keeping it forever made old
        // pages repeatedly decode, attach, lose a host-pool slot, and decode again while the
        // reader was completely idle.
        if (currentPage != null && flight.exactAdjacentPhysicalIntent.get() &&
            !isStrictAdjacentPageInReportedPhysicalIntent(currentIndex, currentPage)
        ) {
            flight.exactAdjacentPhysicalIntent.compareAndSet(true, false)
        }
        if (currentIndex < 0 || currentPage == null ||
            strictAdjacentRehydrateIdentity(currentPage) != flight.identity ||
            (!flight.hostPressurePhysicalReentry.get() &&
                !flight.exactAdjacentPhysicalIntent.get() &&
                !compositorForwardWarmEligible &&
                !flight.enteredIdleCompletionIntent.get() &&
                !isInsideProtectedNumericBitmapWindow(currentIndex, currentPage))
        ) {
            strictAdjacentRehydrateFlights.remove(flight.identity, flight)
            initialInteractiveRunwayByteFetches.remove(flight.initialIndex)
            requestLatestExactAdjacentCompositorForwardWarm()
            return
        }
        if (listener.isPageAuthoritativeDrawableCurrentlyInstalled(currentIndex)) {
            adoptAuthoritativeListenerDrawable(
                currentIndex,
                currentPage,
                "strict_adjacent_rehydrate_existing",
            )
            strictAdjacentRehydrateFlights.remove(flight.identity, flight)
            initialInteractiveRunwayByteFetches.remove(flight.initialIndex)
            initialInteractiveRunwayByteFetches.remove(currentIndex)
            return
        }
        val wakeVersionAtBodyProbe = flight.wakeVersion.get()
        val descriptor = strictAdjacentBodyDescriptor(currentPage)
        val publishedBody = if (descriptor == null) {
            strictAdjacentPublishedBody(currentPage)
        } else {
            null
        }
        if (descriptor == null && publishedBody == null) {
            if (compositorForwardWarmEligible &&
                !flight.hostPressurePhysicalReentry.get() &&
                !flight.exactAdjacentPhysicalIntent.get()
            ) {
                // A compositor warm never reopens network/recovery. Park the single identity until
                // the already-demanded strict source publishes a new resident body edge.
                parkStrictAdjacentExactRehydrate(
                    flight,
                    visibleIntent,
                    wakeVersionAtBodyProbe,
                    resumeIfBodyReady = true,
                )
                return
            }
            handleStrictAdjacentRehydrateBodyUnavailable(
                flight,
                currentIndex,
                currentPage,
                visibleIntent,
                wakeVersionAtBodyProbe,
            )
            return
        }
        try {
            if (compositorForwardWarmEligible && shouldLogRateLimitedDiagnostic(
                    "compositor_forward_warm_decode|${currentPage.manga.ntkEpisodePath}|" +
                        currentPage.sourceIndex,
                    60_000L,
                )
            ) {
                Log.d(
                    TAG,
                    "reader_compositor_forward_warm_decode path=" +
                        "${currentPage.manga.ntkEpisodePath} source=${currentPage.sourceIndex} " +
                        "index=$currentIndex",
                )
            }
            val delivery = prepareAdjacentRunwayDelivery(
                startIndex = currentIndex,
                offset = 0,
                page = currentPage,
                startedAt = flight.startedAtMs,
                allowCurrentPublishedStrictBodyForRehydrate = true,
                // Speculative/protected-window work stays outside a physical motion interval.
                // The Surface's exact first blocker is different: its drawable-prefix fence has
                // already stopped forward progress, and continuous swipes may never expose an
                // idle edge. Admit only that identity-bound frontier (or the equivalent one-shot
                // pressure reentry) on the urgent serial path. The next page cannot acquire this
                // claim until the current one is installed, so this does not reopen an offscreen
                // decode wave underneath scrolling.
                deferDecodeWhilePhysicalMotion = hostExactNativeSurfaceStorageEnabled &&
                    !flight.exactAdjacentPhysicalIntent.get() &&
                    !flight.hostPressurePhysicalReentry.get() &&
                    !compositorForwardWarmEligible,
                enteredIdleCompletionIntent = flight.enteredIdleCompletionIntent.get(),
                compositorForwardWarmIntent = compositorForwardWarmEligible,
            ).copy(
                // A request may have started as speculative runway work and then become the
                // Surface's exact blocked-forward page before its decode finishes.  The
                // identity-bound physical claims below are stronger than the caller's stale
                // visibleIntent snapshot: discarding that immutable original in the busy drain
                // leaves the forward cap waiting for the very page the drain just recycled.
                retainWhenBusy = visibleIntent ||
                    flight.hostPressurePhysicalReentry.get() ||
                    flight.exactAdjacentPhysicalIntent.get() ||
                    compositorForwardWarmEligible,
                authoritativeAdjacentRehydrate = true,
                hostPressurePhysicalReentry = flight.hostPressurePhysicalReentry.get(),
                exactAdjacentPhysicalIntent = flight.exactAdjacentPhysicalIntent.get(),
                compositorForwardWarmIntent = compositorForwardWarmEligible,
            )
            // postDecodeResult claims pendingDeliveryWidths synchronously. Only then release this
            // owner, so a frame arriving before the main delivery cannot start a duplicate decode.
            // Auto-cut sibling delivery is posted to main from the decoder. Keep the source-wide
            // owner through that earlier FIFO turn too; otherwise the other half can start a
            // second full-source decode while its sibling bitmap is merely queued.
            postDecodeResult(delivery)
            completeStrictAdjacentRehydrateDelivery(
                flight,
                currentIndex,
                currentPage,
            )
        } catch (failure: Exception) {
            val wakeVersionAtCatchProbe = flight.wakeVersion.get()
            if (failure is NtkPhysicalMotionDecodeDeferredException) {
                // Motion admission is scheduler backpressure, not an image failure. In
                // particular, do not consume the bounded descriptor-recovery retry count or park
                // this still-visible identity. Surface has already clamped before the missing
                // page, so one coalesced owner can retry after the active fling/idle grace ends.
                postStrictAdjacentExactRehydrateMotionRetry(flight, visibleIntent)
                return
            }
            // The descriptor can retire between the readiness probe and openLease(). That is an
            // exact-generation handoff, not a generic image failure: keep the same owner and let
            // the strict recovery path replace/wake it without mutating the immutable PageRef.
            if (strictAdjacentRehydrateIdentity(currentPage) == flight.identity &&
                strictAdjacentBodyDescriptor(currentPage) == null &&
                strictAdjacentPublishedBody(currentPage) == null
            ) {
                if (compositorForwardWarmEligible &&
                    !flight.hostPressurePhysicalReentry.get() &&
                    !flight.exactAdjacentPhysicalIntent.get()
                ) {
                    parkStrictAdjacentExactRehydrate(
                        flight,
                        visibleIntent,
                        wakeVersionAtCatchProbe,
                        resumeIfBodyReady = true,
                    )
                } else {
                    handleStrictAdjacentRehydrateBodyUnavailable(
                        flight,
                        currentIndex,
                        currentPage,
                        visibleIntent,
                        wakeVersionAtCatchProbe,
                    )
                }
                return
            }
            val replacementDescriptor = strictAdjacentBodyDescriptor(currentPage)
            val replacementBody = if (replacementDescriptor == null) {
                strictAdjacentPublishedBody(currentPage)
            } else {
                null
            }
            val exactReplacementAvailable =
                replacementDescriptor != null && replacementDescriptor !== descriptor ||
                    replacementBody != null &&
                    (publishedBody == null || replacementBody.proof != publishedBody.proof)
            if (strictAdjacentRehydrateIdentity(currentPage) == flight.identity &&
                exactReplacementAvailable
            ) {
                flight.retryCount.set(0)
                postStrictAdjacentExactRehydrateRetry(
                    flight,
                    visibleIntent,
                    wakeVersionAtCatchProbe,
                )
                return
            }
            initialInteractiveRunwayByteFetches.remove(flight.initialIndex)
            initialInteractiveRunwayByteFetches.remove(currentIndex)
            recordIfUnexpected(failure)
            if (strictAdjacentRehydrateIdentity(currentPage) == flight.identity) {
                // Corrupt bytes or a lease race must not release the exact owner and recreate the
                // same decode on every frame. Park this identity; a replacement descriptor event
                // can still wake it, while the current failure is surfaced exactly once.
                parkStrictAdjacentExactRehydrate(
                    flight,
                    visibleIntent,
                    wakeVersionAtCatchProbe,
                    resumeIfBodyReady = false,
                )
            } else {
                strictAdjacentRehydrateFlights.remove(flight.identity, flight)
            }
            if (!cancelled.get() && failedPages.add(currentIndex)) {
                main.post {
                    if (!cancelled.get() && pageRef(currentIndex) == currentPage) {
                        listener.onPageError(currentIndex, "Image decode failed")
                    }
                }
            }
        }
    }

    private fun postStrictAdjacentExactRehydrateMotionRetry(
        flight: StrictAdjacentRehydrateFlight,
        visibleIntent: Boolean,
    ) {
        if (cancelled.get() || strictAdjacentRehydrateFlights[flight.identity] !== flight) return
        // Optional/offscreen exact decode waits for a lifecycle edge, not one timer per page.
        // Polling every 48 ms made a long reader run thousands of no-op executor tasks while the
        // finger was moving and kept the native pipeline from ever remaining idle for one second.
        flight.ownerScheduledOrRunning.set(false)
        flight.motionDeferred.set(true)
        flight.parked.set(true)
        scheduleStrictAdjacentMotionDeferredWake()
    }

    private fun scheduleStrictAdjacentMotionDeferredWake() {
        if (cancelled.get() ||
            strictAdjacentRehydrateFlights.values.none { it.motionDeferred.get() } ||
            !strictAdjacentMotionDeferredWakePosted.compareAndSet(false, true)
        ) return
        val posted = main.postDelayed(
            strictAdjacentMotionDeferredWakeRunnable,
            NTK_STRICT_ADJACENT_REHYDRATE_IDLE_WAKE_MS,
        )
        if (!posted) strictAdjacentMotionDeferredWakePosted.set(false)
    }

    private fun wakeStrictAdjacentMotionDeferredFlights() {
        if (cancelled.get() || viewportBusy.get() ||
            NtkReaderTransferPacer.isPhysicalMotionActive()
        ) return
        strictAdjacentRehydrateFlights.values.toList().forEach { flight ->
            if (strictAdjacentRehydrateFlights[flight.identity] === flight &&
                flight.motionDeferred.compareAndSet(true, false)
            ) {
                flight.retryCount.set(0)
                flight.parked.set(false)
                scheduleStrictAdjacentExactRehydrate(flight, flight.visibleIntent)
            }
        }
    }

    private fun handleStrictAdjacentRehydrateBodyUnavailable(
        flight: StrictAdjacentRehydrateFlight,
        currentIndex: Int,
        currentPage: PageRef,
        visibleIntent: Boolean,
        observedWakeVersion: Long,
    ) {
        val heldForStrictRecovery = holdOrRecoverAdjacentStrictSource(currentPage.manga)
        if (isAdjacentStrictRecoveryExhausted(currentPage.manga)) {
            // Keep the identity owner as a terminal tombstone until the page/session changes.
            // Releasing it here would recreate the same failed task on every viewport frame.
            initialInteractiveRunwayByteFetches.remove(flight.initialIndex)
            initialInteractiveRunwayByteFetches.remove(currentIndex)
            parkStrictAdjacentExactRehydrate(
                flight,
                visibleIntent,
                observedWakeVersion,
                resumeIfBodyReady = true,
            )
            return
        }
        if (!heldForStrictRecovery &&
            strictAdjacentRehydrateIdentity(currentPage) == null
        ) {
            strictAdjacentRehydrateFlights.remove(flight.identity, flight)
            initialInteractiveRunwayByteFetches.remove(flight.initialIndex)
            initialInteractiveRunwayByteFetches.remove(currentIndex)
            main.post {
                if (!cancelled.get()) {
                    val latest = pageRef(currentIndex)
                    if (latest != null && strictAdjacentRehydrateIdentity(latest) == null) {
                        requestPage(
                            currentIndex,
                            busy = visibleIntent,
                            anchor = false,
                            generation = windowGeneration.get(),
                        )
                    }
                }
            }
            return
        }
        postStrictAdjacentExactRehydrateRetry(
            flight,
            visibleIntent,
            observedWakeVersion,
        )
    }

    private fun parkStrictAdjacentExactRehydrate(
        flight: StrictAdjacentRehydrateFlight,
        visibleIntent: Boolean,
        observedWakeVersion: Long,
        resumeIfBodyReady: Boolean,
    ) {
        flight.motionDeferred.set(false)
        flight.parked.set(true)
        flight.ownerScheduledOrRunning.set(false)
        val currentIndex = currentPageIndex(flight.page, flight.initialIndex)
        val exactPage = pageRef(currentIndex)?.takeIf { currentPage ->
            currentIndex >= 0 && strictAdjacentRehydrateIdentity(currentPage) == flight.identity
        }
        val bodyReady = resumeIfBodyReady && exactPage != null &&
            (strictAdjacentBodyDescriptor(exactPage) != null ||
                strictAdjacentPublishedBody(exactPage) != null)
        if (flight.wakeVersion.get() != observedWakeVersion || bodyReady) {
            flight.retryCount.set(0)
            flight.parked.set(false)
            scheduleStrictAdjacentExactRehydrate(flight, visibleIntent)
        }
    }

    private fun completeStrictAdjacentRehydrateDelivery(
        flight: StrictAdjacentRehydrateFlight,
        currentIndex: Int,
        currentPage: PageRef,
    ) {
        val sibling = autoSplitSiblingPage(currentIndex, currentPage)
        if (sibling == null) {
            strictAdjacentRehydrateFlights.remove(flight.identity, flight)
            initialInteractiveRunwayByteFetches.remove(flight.initialIndex)
            initialInteractiveRunwayByteFetches.remove(currentIndex)
            requestLatestExactAdjacentCompositorForwardWarm()
            return
        }
        // deliverAutoSplitSiblingFromDecoded() enqueued its main turn before this one. Waiting for
        // that FIFO boundary makes its tracked bitmap/pending ownership visible before the shared
        // source flight can be released. If delivery was invalidated meanwhile, re-drive only the
        // still-current exact sibling after releasing the stale owner.
        main.post {
            if (strictAdjacentRehydrateFlights[flight.identity] !== flight) return@post
            val siblingIndex = currentPageIndex(sibling.second, sibling.first)
            val siblingPage = pageRef(siblingIndex)
            val siblingSettled = siblingIndex >= 0 &&
                ((pendingDeliveryWidths[siblingIndex] ?: 0) > 0 ||
                    listener.isPageAuthoritativeDrawableCurrentlyInstalled(siblingIndex) ||
                    (hasDeliveredBitmap(siblingIndex) &&
                        listener.isPageDrawableInstalled(siblingIndex)))
            strictAdjacentRehydrateFlights.remove(flight.identity, flight)
            initialInteractiveRunwayByteFetches.remove(flight.initialIndex)
            initialInteractiveRunwayByteFetches.remove(currentIndex)
            initialInteractiveRunwayByteFetches.remove(siblingIndex)
            if (!siblingSettled && siblingIndex >= 0 && siblingPage != null &&
                strictAdjacentRehydrateIdentity(siblingPage) == flight.identity
            ) {
                routeStrictAdjacentExactRehydrate(
                    siblingIndex,
                    siblingPage,
                    visibleIntent = flight.visibleIntent,
                    compositorForwardWarmIntent =
                        flight.compositorForwardWarmIntent.get(),
                )
            }
            requestLatestExactAdjacentCompositorForwardWarm()
        }
    }

    private fun postStrictAdjacentExactRehydrateRetry(
        flight: StrictAdjacentRehydrateFlight,
        visibleIntent: Boolean,
        observedWakeVersion: Long = flight.wakeVersion.get(),
    ) {
        if (cancelled.get() || strictAdjacentRehydrateFlights[flight.identity] !== flight) return
        val attempt = flight.retryCount.incrementAndGet()
        if (attempt >= NTK_STRICT_ADJACENT_REHYDRATE_MAX_POLLS) {
            parkStrictAdjacentExactRehydrate(
                flight,
                visibleIntent,
                observedWakeVersion,
                resumeIfBodyReady = true,
            )
            Log.d(
                TAG,
                "reader_strict_adjacent_rehydrate_parked page=${flight.initialIndex} " +
                    "source=${flight.page.sourceIndex} attempts=$attempt",
            )
            return
        }
        // Relinquish this attempt before publishing its delayed retry. A physical viewport wake
        // may legitimately schedule a newer attempt during the delay. Clearing the flag inside
        // the delayed callback used to clobber that newer attempt's running claim, leaving the
        // identity registered with neither a worker nor a parked wake edge after it completed.
        // ownerAttemptVersion makes this worker's finally block generation-safe as well.
        flight.ownerScheduledOrRunning.set(false)
        val delayMs = (
            NTK_STRICT_ADJACENT_REHYDRATE_RETRY_BASE_MS * attempt.coerceAtMost(4)
            ).coerceAtMost(NTK_STRICT_ADJACENT_REHYDRATE_RETRY_MAX_MS)
        main.postDelayed({
            if (!cancelled.get() && strictAdjacentRehydrateFlights[flight.identity] === flight) {
                scheduleStrictAdjacentExactRehydrate(flight, visibleIntent)
            }
        }, delayMs)
    }

    private fun prepareAdjacentRunwayDrawableBatch(
        startIndex: Int,
        refs: List<PageRef>,
        reason: String,
        requireStrictDescriptor: Boolean = false,
        enteredIdleCompletionIntent: Boolean = false,
        offscreenInitialRunwayCompletionIntent: Boolean = false,
        failureSink: AtomicReference<Throwable?>? = null,
    ): AdjacentRunwayDrawableBatch? {
        if (!isImmediateNtkGeneratedUx()) return AdjacentRunwayDrawableBatch(emptyList())
        val deliveries = ArrayList<Delivery>(refs.size)
        val startedAt = SystemClock.elapsedRealtime()
        try {
            val indexedPages = refs.mapIndexedNotNull { offset, page ->
                if (page.transitionTitle == null) offset to page else null
            }
            val atomicRunwayPageLimit = initialAdjacentRunwayPageLimit(
                indexedPages.firstOrNull()?.second?.manga?.ntkEpisodePath,
            )
            val directWifiRunwayProfile = indexedPages.firstOrNull()?.second?.manga?.let {
                isDirectWifiStrictAdjacentRunwayProfile(it)
            } == true
            val directWifiAtomicRunwayTail =
                reason == "append_runway_remaining_publish" &&
                    directWifiRunwayProfile &&
                    indexedPages.all {
                        it.second.manga.ntkEpisodePath?.startsWith("/webtoon/") == true
                    } &&
                    indexedPages.size in 2 until atomicRunwayPageLimit &&
                    indexedPages.map { it.second.sourceIndex } ==
                        (1..indexedPages.size).toList()
            val directWifiAtomicInitialManhwaRunway =
                directWifiRunwayProfile &&
                    indexedPages.all {
                        it.second.manga.ntkEpisodePath?.startsWith("/manhwa/") == true
                    } &&
                    indexedPages.size in 2..atomicRunwayPageLimit &&
                    when (reason) {
                        "append_initial_runway_prepare_before_publish" ->
                            indexedPages.map { it.second.sourceIndex } ==
                                (0 until indexedPages.size).toList()
                        "published_exact_initial_runway_completion" -> {
                            val firstSource = indexedPages.first().second.sourceIndex
                            firstSource in 1 until atomicRunwayPageLimit &&
                                indexedPages.map { it.second.sourceIndex } ==
                                    (firstSource until firstSource + indexedPages.size).toList()
                        }
                        else -> false
                    }
            val adjacentManhwaPages = indexedPages.isNotEmpty() && indexedPages.all {
                it.second.manga.ntkEpisodePath?.startsWith("/manhwa/") == true
            }
            // A host exact decode writes the reusable CPU store and refreshes its HardwareBuffer
            // mirror. Even on a background-nice worker that 100-400 ms memory/gfxstream burst can
            // deschedule the display producer. The append callers below already roll structure
            // back and register a busy->idle retry for NtkPhysicalMotionDecodeDeferredException,
            // so manga no longer needs to perform offscreen decode during a real fling. The next
            // quiet edge decodes the same manifest-bound body; a page near the boundary remains
            // protected by the existing drawable-prefix cap. Webtoon remainder policy is unchanged.
            val deferDecodeWhilePhysicalMotion =
                NtkAdjacentExactDecodeMotionPolicy.shouldDefer(
                    directWifiRunwayProfile = directWifiRunwayProfile,
                    reason = reason,
                    adjacentManhwaPages = adjacentManhwaPages,
                ) && !isPhysicalBoundaryDemandingAdjacentTarget(
                    indexedPages.firstOrNull()?.second?.manga,
                )
            if ((reason == "initial_strict_source" || directWifiAtomicRunwayTail ||
                    directWifiAtomicInitialManhwaRunway) &&
                indexedPages.size > 1
            ) {
                // Non-progressive initial cohorts decode independent pages on the bounded overlap
                // pool. The direct-Wi-Fi p1..p3 tail is also one atomic UI publication and its
                // measured pages are ordinary short strips; decoding the fixed p1..p4 completion
                // together removes the serial final-EOF tail and prevents p4 from entering a real
                // swipe after p0..p3 have already become observable. A fully resident adjacent
                // manhwa p0..p4 cohort uses the same atomic decode/publication turn. Larger suffix
                // batches and every mobile/SNI path retain the sequential branch below.
                val tasks = indexedPages.map { (offset, page) ->
                    FutureTask {
                        prepareAdjacentRunwayDelivery(
                            startIndex,
                            offset,
                            page,
                            startedAt,
                            requireStrictDescriptor,
                            deferDecodeWhilePhysicalMotion = deferDecodeWhilePhysicalMotion,
                            enteredIdleCompletionIntent = enteredIdleCompletionIntent,
                            offscreenInitialRunwayCompletionIntent =
                                offscreenInitialRunwayCompletionIntent,
                        )
                    }
                }
                tasks.forEach(strictExactOverlapDecode::execute)
                var firstFailure: Throwable? = null
                tasks.forEach { task ->
                    try {
                        deliveries += task.get()
                    } catch (failure: ExecutionException) {
                        if (firstFailure == null) firstFailure = failure.cause ?: failure
                    }
                }
                firstFailure?.let { failure ->
                    if (failure is Exception) throw failure
                    throw java.io.IOException("Adjacent runway parallel decode failed", failure)
                }
            } else {
                indexedPages.forEach { (offset, page) ->
                    deliveries += prepareAdjacentRunwayDelivery(
                        startIndex,
                        offset,
                        page,
                        startedAt,
                        requireStrictDescriptor,
                        deferDecodeWhilePhysicalMotion = deferDecodeWhilePhysicalMotion,
                        enteredIdleCompletionIntent = enteredIdleCompletionIntent,
                        offscreenInitialRunwayCompletionIntent =
                            offscreenInitialRunwayCompletionIntent,
                    )
                }
            }
            if (shouldLogRateLimitedDiagnostic("append_adjacent_runway_drawable_batch_ready")) {
                Log.d(
                    TAG,
                    "append_adjacent_runway_drawable_batch_ready reason=$reason start=$startIndex " +
                        "refs=${refs.size} drawables=${deliveries.size} " +
                        "decodeMs=${SystemClock.elapsedRealtime() - startedAt} " +
                        "stagedRemaining=${preparedAdjacentRemainderDrawables.size}"
                )
            }
            return AdjacentRunwayDrawableBatch(deliveries)
        } catch (e: Exception) {
            failureSink?.compareAndSet(null, e)
            deliveries.forEach { recycleDecodeResult(it.result) }
            if (e !is NtkPhysicalMotionDecodeDeferredException) {
                Log.d(
                    TAG,
                    "append_adjacent_runway_drawable_batch_error reason=$reason start=$startIndex " +
                        "refs=${refs.size} ready=${deliveries.size} " +
                        "error=${e.javaClass.simpleName}:${e.message}"
                )
                recordIfUnexpected(e)
            }
            return null
        }
    }

    private fun prepareAdjacentRunwayDelivery(
        startIndex: Int,
        offset: Int,
        page: PageRef,
        startedAt: Long,
        requireStrictDescriptor: Boolean = false,
        allowCurrentPublishedStrictBodyForRehydrate: Boolean = false,
        deferDecodeWhilePhysicalMotion: Boolean = false,
        enteredIdleCompletionIntent: Boolean = false,
        offscreenInitialRunwayCompletionIntent: Boolean = false,
        compositorForwardWarmIntent: Boolean = false,
    ): Delivery {
        val image = page.image.orEmpty()
        if (image.isBlank()) throw java.io.IOException("Adjacent runway page has no image")
        val index = startIndex + offset
        val requestedWidth = ntkProofTargetWidth()
        val pageKey = preparedAdjacentRemainderDrawableKey(page)
        val strictExactBodyRequired =
            requireStrictDescriptor || allowCurrentPublishedStrictBodyForRehydrate ||
                requiresStrictAdjacentExactBody(page)
        val boundedDirectNativePool = hostExactNativeSurfaceStorageEnabled &&
            isDirectWifiStrictAdjacentRunwayProfile(page.manga)
        if (boundedDirectNativePool) {
            val viewportInside = isViewportInsideEpisode(page.manga)
            val physicalIntent = isStrictAdjacentPageInReportedPhysicalIntent(index, page)
            val foregroundMotion = NtkReaderTransferPacer.isPhysicalMotionActive() ||
                viewportBusy.get() ||
                physicalTouchQuietRemainingMs(
                    NTK_DIRECT_ADJACENT_PIXEL_INPUT_QUIET_MS,
                ) > 0L
            val normalizedPath = NtkStripDigests.normalizeEpisodePath(
                page.manga.ntkEpisodePath.orEmpty(),
            )
            val claim = adjacentStrictSourceClaims[normalizedPath]
            val compositorForwardWarmEligible = compositorForwardWarmIntent &&
                isLatestExactAdjacentCompositorForwardWarm(index, page)
            val enteredIdleCompletionEligible = enteredIdleCompletionIntent &&
                !foregroundMotion &&
                normalizedPath.isNotEmpty() &&
                latestEnteredExactEpisodePath.get() == normalizedPath &&
                claim?.firstActualFramePresented?.get() == true &&
                isAdjacentStrictSourceClaimLive(normalizedPath, claim)
            val offscreenInitialRunwayCompletionEligible =
                offscreenInitialRunwayCompletionIntent &&
                    !foregroundMotion &&
                    normalizedPath.isNotEmpty() &&
                    normalizedPath in publishedExactOffscreenRunwayPaths &&
                    claim != null &&
                    NtkPublishedInitialRunwayCompletionPolicy.stillOwnsPixelCompletion(
                        firstActualFramePresented = claim.firstActualFramePresented.get(),
                        latestEnteredEpisodeMatches =
                            latestEnteredExactEpisodePath.get() == normalizedPath,
                    ) &&
                    page.sourceIndex in 0 until minOf(
                        initialAdjacentRunwayPageLimit(normalizedPath),
                        claim.pageCount,
                    ) &&
                    isAdjacentStrictSourceClaimLive(normalizedPath, claim)
            if ((enteredIdleCompletionIntent && !enteredIdleCompletionEligible) ||
                (offscreenInitialRunwayCompletionIntent &&
                    !offscreenInitialRunwayCompletionEligible) ||
                (compositorForwardWarmIntent && !compositorForwardWarmEligible) ||
                (!enteredIdleCompletionEligible &&
                    !offscreenInitialRunwayCompletionEligible &&
                    !compositorForwardWarmEligible &&
                    NtkDirectAdjacentPixelAdmissionPolicy.shouldDefer(
                    viewportInsideEpisode = viewportInside,
                    sourceIndex = page.sourceIndex,
                    currentSourceIndex = currentViewportSourceIndexForEpisode(page.manga),
                    physicalIntent = physicalIntent,
                    foregroundMotionActive = foregroundMotion,
                    idleForwardRunway = NTK_STRICT_ACTIVE_FORWARD_SOURCE_RUNWAY,
                    ))
            ) {
                throw NtkPhysicalMotionDecodeDeferredException()
            }
        }
        val prepared = pageKey?.let { key ->
            preparedAdjacentRemainderDrawables.remove(key)
        }
        val mayConsumeUnprovenCache =
            NtkAdjacentRunwayBodyAuthorityPolicy.mayConsumeUnprovenPreparedOrGenericCache(
                strictExactBodyRequired,
            )
        val result = if (prepared != null && prepared.pageKey == pageKey && mayConsumeUnprovenCache) {
            prepared.result
        } else {
            prepared?.let { recycleDecodeResult(it.result) }
            if (deferDecodeWhilePhysicalMotion &&
                (NtkReaderTransferPacer.isPhysicalMotionActive() || viewportBusy.get() ||
                    physicalTouchQuietRemainingMs(
                        NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS,
                    ) > 0L)
            ) {
                if (cancelled.get() || Thread.currentThread().isInterrupted) {
                    throw InterruptedException("Adjacent exact decode admission cancelled")
                }
                throw NtkPhysicalMotionDecodeDeferredException()
            }
            val strictDescriptor = strictAdjacentBodyDescriptor(page)
            val strictBody = if (
                strictExactBodyRequired && !allowCurrentPublishedStrictBodyForRehydrate
            ) {
                null
            } else {
                strictAdjacentPublishedBody(page)
            }
            val strictExactAdjacent = strictDescriptor != null || strictBody != null
            val decoded = when {
                strictDescriptor != null -> {
                    val lease = strictDescriptor.openLease()
                    try {
                        check(lease.sourceKey == strictDescriptor.sourceKey &&
                            lease.metadata == strictDescriptor.metadata &&
                            lease.proof == strictDescriptor.proof
                        ) {
                            "Adjacent strict body lease authority changed"
                        }
                        if (hasHostExactSealedSource(lease.file, lease.proof.encodedLength)) {
                            decodeStrictExactPageFile(
                                index,
                                page,
                                lease.file,
                                requestedWidth,
                                lease.sourceWidth,
                                lease.sourceHeight,
                                lease.metadata.canonicalAsset,
                                proofDrawable = true,
                                deferWhilePhysicalMotion = deferDecodeWhilePhysicalMotion,
                                allowTransientHostExactPoolOvercommit = !boundedDirectNativePool,
                                settledHostExactPoolOnly = false,
                                exactLaunchCompositorForwardWarmIntent =
                                    compositorForwardWarmIntent,
                            )
                        } else {
                            lease.predecodedOriginal
                                ?.takeIf { !boundedDirectNativePool }
                                ?.takeIfReadyOrAbandon(
                                    lease.sourceWidth,
                                    lease.sourceHeight,
                                )
                                ?.let { bitmap ->
                                    adoptPrivateStrictExactBitmapForPage(
                                        index,
                                        page,
                                        bitmap,
                                        lease.sourceWidth,
                                        lease.sourceHeight,
                                        lease.metadata.canonicalAsset,
                                    )
                                } ?: when {
                                lease.encodedBytes != null -> decodeStrictExactPageBytes(
                                    index,
                                    page,
                                    lease.encodedBytes,
                                    lease.sourceWidth,
                                    lease.sourceHeight,
                                    lease.metadata.canonicalAsset,
                                    parallelOversizedResidentTiles =
                                        shouldParallelDecodeDirectWifiAdjacentResidentTiles(page),
                                    deferWhilePhysicalMotion = deferDecodeWhilePhysicalMotion,
                                    allowTransientHostExactPoolOvercommit = !boundedDirectNativePool,
                                    settledHostExactPoolOnly = false,
                                    exactLaunchCompositorForwardWarmIntent =
                                        compositorForwardWarmIntent,
                                )
                                lease.file.isFile -> decodeStrictExactPageFile(
                                    index,
                                    page,
                                    lease.file,
                                    requestedWidth,
                                    lease.sourceWidth,
                                    lease.sourceHeight,
                                    lease.metadata.canonicalAsset,
                                    proofDrawable = true,
                                    deferWhilePhysicalMotion = deferDecodeWhilePhysicalMotion,
                                    allowTransientHostExactPoolOvercommit = !boundedDirectNativePool,
                                    settledHostExactPoolOnly = false,
                                    exactLaunchCompositorForwardWarmIntent =
                                        compositorForwardWarmIntent,
                                )
                                else -> throw java.io.IOException(
                                    "Adjacent strict body lease has no encoded original"
                                )
                            }
                        }
                    } finally {
                        lease.predecodedOriginal?.close()
                        lease.release()
                    }
                }
                strictBody != null && hasHostExactSealedSource(
                    strictBody.file,
                    strictBody.proof.encodedLength,
                ) -> decodeStrictExactPageFile(
                    index,
                    page,
                    strictBody.file,
                    requestedWidth,
                    strictBody.metadata.sourceWidth,
                    strictBody.metadata.sourceHeight,
                    strictBody.metadata.canonicalAsset,
                    proofDrawable = true,
                    deferWhilePhysicalMotion = deferDecodeWhilePhysicalMotion,
                    allowTransientHostExactPoolOvercommit = !boundedDirectNativePool,
                    settledHostExactPoolOnly = false,
                    exactLaunchCompositorForwardWarmIntent = compositorForwardWarmIntent,
                )
                strictBody?.encodedBytes != null -> decodeStrictExactPageBytes(
                    index,
                    page,
                    strictBody.encodedBytes,
                    strictBody.metadata.sourceWidth,
                    strictBody.metadata.sourceHeight,
                    strictBody.metadata.canonicalAsset,
                    parallelOversizedResidentTiles =
                        shouldParallelDecodeDirectWifiAdjacentResidentTiles(page),
                    deferWhilePhysicalMotion = deferDecodeWhilePhysicalMotion,
                    allowTransientHostExactPoolOvercommit = !boundedDirectNativePool,
                    settledHostExactPoolOnly = false,
                    exactLaunchCompositorForwardWarmIntent = compositorForwardWarmIntent,
                )
                strictBody?.file?.isFile == true -> decodeStrictExactPageFile(
                    index,
                    page,
                    strictBody.file,
                    requestedWidth,
                    strictBody.metadata.sourceWidth,
                    strictBody.metadata.sourceHeight,
                    strictBody.metadata.canonicalAsset,
                    proofDrawable = true,
                    deferWhilePhysicalMotion = deferDecodeWhilePhysicalMotion,
                    allowTransientHostExactPoolOvercommit = !boundedDirectNativePool,
                    settledHostExactPoolOnly = false,
                    exactLaunchCompositorForwardWarmIntent = compositorForwardWarmIntent,
                )
                else -> {
                    if (!mayConsumeUnprovenCache) {
                        throw java.io.IOException(
                            "Adjacent exact body has no generation-bound descriptor",
                        )
                    }
                    val cached = ReaderImageCache.cachedFile(
                        appContext,
                        page.manga,
                        image,
                    ) ?: throw java.io.IOException("Adjacent runway image body is not ready")
                    decodePage(
                        index,
                        page,
                        cached,
                        requestedWidth,
                        proofDrawable = true,
                    )
                }
            }
            if (shouldPrepareAdjacentRunwayDecodeResultForDraw(strictExactAdjacent, page)) {
                prepareDecodeResultForDraw(decoded)
            } else {
                // prepareToDraw() is a real HWUI/gfxstream texture upload. The direct-Wi-Fi exact
                // adjacent body remains fully decoded and is installed unchanged, but a chained
                // physical scroll must not upload the same 2000 px original to HWUI before the
                // native Surface renderer uploads it for first visibility at the chapter edge.
                if (
                    shouldLogRateLimitedDiagnostic(
                        "adjacent_prepare_to_draw_skip|${page.manga.ntkEpisodePath}",
                    )
                ) {
                    Log.d(
                        TAG,
                        "append_adjacent_exact_prepare_to_draw_skip path=${page.manga.ntkEpisodePath} " +
                            "source=${page.sourceIndex} busy=${viewportBusy.get()}",
                    )
                }
            }
            decoded
        }
        return Delivery(
            index,
            page,
            result,
            startedAt,
            requestedWidth,
            retainWhenBusy = false,
            proofDrawable = true,
            compositorForwardWarmIntent = compositorForwardWarmIntent,
        )
    }

    private fun shouldPrepareAdjacentRunwayDecodeResultForDraw(
        strictExactAdjacent: Boolean,
        page: PageRef,
    ): Boolean {
        if (!strictExactAdjacent ||
            !isDirectWifiStrictAdjacentRunwayProfile(page.manga)
        ) return true
        // Keep cellular/SNI and every non-exact route on their established preparation path.
        // A direct-Wi-Fi adjacent exact original is only a speculative GPU hint until it becomes
        // visible, so suppress that hint throughout a real gesture and its input-quiet interval.
        // CPU decode, exact-original identity, listener delivery, and four-page attachment are
        // deliberately unaffected.
        return !viewportBusy.get() && !isActiveGeneratedTouchOrQuiet()
    }

    private fun shouldParallelDecodeDirectWifiAdjacentResidentTiles(page: PageRef): Boolean {
        if (page.sourceIndex !in
            0 until initialAdjacentRunwayPageLimit(page.manga.ntkEpisodePath)
        ) return false
        val path = NtkStripDigests.normalizeEpisodePath(
            page.manga.ntkEpisodePath?.trim().orEmpty(),
        )
        return path.startsWith("/webtoon/") &&
            isDirectWifiStrictAdjacentRunwayProfile(page.manga)
    }

    private fun takePreparedInitialAdjacentRunwayBatch(
        target: Manga,
        startIndex: Int,
        refs: List<PageRef>
    ): AdjacentRunwayDrawableBatch? {
        val path = target.ntkEpisodePath?.trim().orEmpty()
        if (path.isEmpty()) return null
        val prepared = preparedInitialAdjacentRunways.remove(path) ?: return null
        val pageKeys = refs
            .filter { it.transitionTitle == null }
            .map(::runwayPageRefIdentity)
        if (pageKeys != prepared.pageKeys || prepared.batch.deliveries.size != pageKeys.size) {
            recycleAdjacentRunwayDrawableBatch(prepared.batch)
            Log.d(
                TAG,
                "append_adjacent_initial_prefetch_mismatch path=$path prepared=${prepared.pageKeys.size} " +
                    "requested=${pageKeys.size}"
            )
            return null
        }
        Log.d(
            TAG,
            "append_adjacent_initial_prefetch_take path=$path pages=${pageKeys.size} " +
                "ageMs=${SystemClock.elapsedRealtime() - prepared.preparedAtMs}"
        )
        return rebindAdjacentRunwayDrawableBatch(prepared.batch, startIndex, refs)
    }

    private fun rebindAdjacentRunwayDrawableBatch(
        batch: AdjacentRunwayDrawableBatch,
        startIndex: Int,
        refs: List<PageRef>
    ): AdjacentRunwayDrawableBatch {
        var deliveryOffset = 0
        val rebound = ArrayList<Delivery>(batch.deliveries.size)
        refs.forEachIndexed { offset, page ->
            if (page.transitionTitle != null) return@forEachIndexed
            val delivery = batch.deliveries[deliveryOffset++]
            rebound.add(delivery.copy(index = startIndex + offset, page = page))
        }
        return AdjacentRunwayDrawableBatch(rebound)
    }

    private fun isDirectWifiAdjacentExactP0HeadCandidate(
        target: Manga,
        initialRefs: List<PageRef>,
    ): Boolean {
        if (!isDirectWifiStrictAdjacentRunwayProfile(target)) return false
        val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        if (!path.startsWith("/webtoon/") &&
            !(hostGpuEmulatorRuntime && path.startsWith("/manhwa/"))
        ) return false
        if (initialRefs.size != 2 || initialRefs[0].transitionTitle == null) return false
        val p0 = initialRefs[1]
        return p0.transitionTitle == null && p0.sourceIndex == 0 &&
            NtkStripDigests.normalizeEpisodePath(p0.manga.ntkEpisodePath.orEmpty()) == path
    }

    private fun prepareDirectWifiAdjacentExactP0Head(
        target: Manga,
        initialRefs: List<PageRef>,
    ): AdjacentExactP0Flight? {
        val pathForLog = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        val p0 = initialRefs.getOrNull(1) ?: run {
            Log.d(TAG, "append_adjacent_exact_p0_prepare_skip path=$pathForLog reason=p0_missing")
            return null
        }
        val authority = exactViewerApiAdjacentAuthority(target) ?: run {
            Log.d(TAG, "append_adjacent_exact_p0_prepare_skip path=$pathForLog reason=authority_missing")
            return null
        }
        if (!ensureAdjacentStrictSourceClaim(target, authority)) {
            Log.d(TAG, "append_adjacent_exact_p0_prepare_skip path=$pathForLog reason=claim_rejected")
            return null
        }
        val path = authority.seal.normalizedEpisodePath
        val claim = adjacentStrictSourceClaims[path] ?: run {
            Log.d(TAG, "append_adjacent_exact_p0_prepare_skip path=$path reason=claim_missing")
            return null
        }
        if (!isAdjacentStrictSourceClaimLive(path, claim)) {
            Log.d(TAG, "append_adjacent_exact_p0_prepare_skip path=$path reason=claim_dead")
            return null
        }
        val descriptor = strictAdjacentBodyDescriptor(p0) ?: run {
            Log.d(TAG, "append_adjacent_exact_p0_prepare_skip path=$path reason=descriptor_missing")
            return null
        }
        if (descriptor.metadata.pageIndex != 0 ||
            descriptor.metadata.manifestDigest != authority.seal.digestSha256 ||
            descriptor.metadata.canonicalAsset != p0.canonicalAsset
        ) {
            Log.d(
                TAG,
                "append_adjacent_exact_p0_prepare_skip path=$path reason=descriptor_mismatch " +
                    "page=${descriptor.metadata.pageIndex} " +
                    "digest=${descriptor.metadata.manifestDigest == authority.seal.digestSha256} " +
                    "asset=${descriptor.metadata.canonicalAsset == p0.canonicalAsset}",
            )
            return null
        }
        val lease = try {
            descriptor.openLease()
        } catch (failure: Exception) {
            Log.d(
                TAG,
                "append_adjacent_exact_p0_prepare_skip path=$path reason=lease_error " +
                    "error=${failure.javaClass.simpleName}:${failure.message}",
            )
            if (!cancelled.get()) recordIfUnexpected(failure)
            return null
        }
        var success = false
        try {
            check(lease.sourceKey == descriptor.sourceKey &&
                lease.metadata == descriptor.metadata && lease.proof == descriptor.proof
            ) { "Adjacent exact p0 lease authority changed" }
            val plan = NtkSourceTileLayout.create(claim.episode, descriptor.metadata)
            val ownerToken = adjacentExactP0OwnerSequence.getAndIncrement()
            val owner = NtkAdjacentExactP0Owner(
                ownerToken = ownerToken,
                episode = claim.episode,
                normalizedEpisodePath = path,
                manifestRevision = descriptor.metadata.manifestRevision,
                manifestDigest = descriptor.metadata.manifestDigest,
                manifestPageCount = authority.seal.pageCount,
                canonicalAsset = descriptor.metadata.canonicalAsset,
                sourceKey = descriptor.sourceKey,
                metadataBindingDigest = descriptor.metadata.metadataBindingDigest,
                planDigest = plan.planDigest,
                descriptorId = descriptor.descriptorId,
            )
            val proof = ReaderPreparedStore.PreparedOriginalProof(
                canonicalAsset = ReaderPreparedStore.canonicalOriginalAssetIdentity(
                    descriptor.metadata.canonicalAsset,
                ),
                variant = ReaderPreparedStore.PreparedAssetVariant.ORIGINAL,
                originalWidth = descriptor.metadata.sourceWidth,
                originalHeight = descriptor.metadata.sourceHeight,
                inSampleSize = 1,
                postDecodeResized = false,
            )
            val headSlots = (0 until minOf(2, plan.tiles.size)).toList()
            awaitDirectWifiAdjacentP0PromotionInputQuiet(p0.manga)
            // The predecessor-complete/body gates have already admitted this exact adjacent p0.
            // Decode its two visible head rows concurrently so renderer ownership is not delayed
            // by two independent region decodes. This branch covers direct-Wi-Fi webtoon p0 and
            // the host-emulator manhwa p0; cellular/SNI, real-device manhwa and current-episode
            // decode scheduling are unchanged.
            val headTiles = promoteAdjacentExactTilesForDirectPresenter(
                decodeAdjacentExactSoftwareSlots(lease, plan, headSlots, parallel = true),
                p0.manga,
            )
            val head = NtkAdjacentExactP0Delta(
                owner = owner,
                plan = plan,
                proof = proof,
                installs = adjacentExactP0Installs(owner, plan, headTiles),
                complete = headSlots.size == plan.tiles.size,
            )
            success = true
            Log.d(
                TAG,
                "append_adjacent_exact_p0_prepare_ready path=$path owner=$ownerToken " +
                    "head=${headTiles.size}/${plan.tiles.size} source=${plan.sourceWidth}x${plan.sourceHeight}",
            )
            return AdjacentExactP0Flight(owner, p0, lease, plan, proof, head)
        } catch (failure: Exception) {
            Log.d(
                TAG,
                "append_adjacent_exact_p0_prepare_skip path=$path reason=decode_error " +
                    "error=${failure.javaClass.simpleName}:${failure.message}",
            )
            if (!cancelled.get() && !isExpectedCancellation(failure)) recordIfUnexpected(failure)
            return null
        } finally {
            if (!success) {
                lease.predecodedOriginal?.close()
                lease.release()
            }
        }
    }

    /**
     * A verified sealed source is the lowest-allocation exact input on the host emulator. The
     * length check binds this preference to the same accepted proof; a stale placeholder never
     * outranks authoritative resident bytes on other runtimes.
     */
    private fun hasHostExactSealedSource(file: File, encodedLength: Long): Boolean =
        hostExactNativeSurfaceStorageEnabled &&
            encodedLength > 0L && file.isFile && file.length() == encodedLength

    private fun publishDirectWifiAdjacentExactP0Head(
        target: Manga,
        allRefs: List<PageRef>,
        initialRefs: List<PageRef>,
        remainingRefs: List<PageRef>,
        publishKey: String,
        warm: Boolean,
        cardOffset: Int,
        transitionTitle: String,
        flight: AdjacentExactP0Flight,
    ): Boolean {
        if (shouldDeferDirectWifiAdjacentStructurePublication(target)) {
            recycleAdjacentExactP0Delta(flight.head)
            releaseAdjacentExactP0Flight(flight)
            scheduleInitialAdjacentRunwayAppendRetry(
                target,
                allRefs,
                publishKey,
                warm,
                forceDelayedPolling = true,
            )
            if (shouldLogRateLimitedDiagnostic(
                    "adjacent_exact_p0_publish_deferred_motion|${target.ntkEpisodePath}",
                )
            ) {
                Log.d(
                    TAG,
                    "append_adjacent_exact_p0_publish_deferred_motion " +
                        "path=${target.ntkEpisodePath}",
                )
            }
            return true
        }
        val cardIndex: Int
        val total: Int
        val drawablePublication: AdjacentDrawableBatchPublication
        var structurePublishOwner: AtomicBoolean? = null
        val pageReferenceSnapshot = synchronized(pagesLock) { pages.toList() }
        val skipOutOfOrder = shouldSkipForwardNtkOutOfOrderAppend(
            target,
            pageReferenceSnapshot,
        )
        val structurePublicationContext =
            prepareForwardAdjacentStructurePublication(target)
        synchronized(pagesLock) {
            val structureChanged =
                !pageReferenceSnapshotStillCurrentLocked(pageReferenceSnapshot)
            if (cancelled.get() || structureChanged || skipOutOfOrder ||
                containsEpisodeForAppendLocked(target)
            ) {
                Log.d(
                    TAG,
                    "append_adjacent_exact_p0_publish_skip path=${target.ntkEpisodePath} " +
                        "cancelled=${cancelled.get()} " +
                        "structureChanged=$structureChanged " +
                        "outOfOrder=$skipOutOfOrder " +
                        "duplicate=${containsEpisodeForAppendLocked(target)}",
                )
                recycleAdjacentExactP0Delta(flight.head)
                releaseAdjacentExactP0Flight(flight)
                clearPendingAdjacentAppendPublish(publishKey)
                return true
            }
            if (structurePublicationContext == null ||
                !claimForwardAdjacentStructurePublication(target, structurePublicationContext)
            ) {
                recycleAdjacentExactP0Delta(flight.head)
                releaseAdjacentExactP0Flight(flight)
                clearPendingAdjacentAppendPublish(publishKey)
                return true
            }
            if (publishKey.isNotEmpty()) pendingAdjacentAppendPublishKeys.add(publishKey)
            structurePublishOwner = beginOwnedStructurePublish()
            drawablePublication = beginAdjacentDrawableBatchPublication(initialRefs)
            cardIndex = pages.size
            // Page identity is immutable episode metadata, not pixel readiness. Publish the whole
            // exact episode table once with p0; ReaderSurfaceView already caps physical input at
            // the contiguous drawable prefix. Later bodies can therefore hydrate their existing
            // slots without rebuilding the page table/native scene on every source page.
            allRefs.forEachIndexed { offset, page -> page.pageIndex = cardIndex + offset }
            pages.addAll(allRefs)
            total = pages.size
            capturePublishedPageIndexLocked()
            check(adjacentExactP0Flights.putIfAbsent(flight.owner.ownerToken, flight) == null)
            Log.d(
                TAG,
                "append_adjacent_exact_p0_structure_inserted path=${target.ntkEpisodePath} " +
                "owner=${flight.owner.ownerToken} previous=$cardIndex total=$total card=${cardIndex + cardOffset}",
            )
        }
        clearPageStateFromIndex(cardIndex, appendOnlyTail = true)
        val publication = NtkAdjacentExactP0HeadPublication(
            previousPageCount = cardIndex,
            totalPageCount = total,
            cardIndex = cardIndex + cardOffset,
            cardTitle = transitionTitle,
            delta = flight.head,
        )
        val posted = main.post {
            Log.d(
                TAG,
                "append_adjacent_exact_p0_main_callback path=${target.ntkEpisodePath} " +
                    "owner=${flight.owner.ownerToken} cancelled=${cancelled.get()} " +
                    "flightPresent=${adjacentExactP0Flights[flight.owner.ownerToken] === flight}",
            )
            var accepted = false
            try {
                if (shouldDeferDirectWifiAdjacentStructurePublication(target)) {
                    rollbackAdjacentRunwayStructure(cardIndex, allRefs)
                    recycleAdjacentExactP0Delta(flight.head)
                    adjacentExactP0Flights.remove(flight.owner.ownerToken, flight)
                    releaseAdjacentExactP0Flight(flight)
                    clearPendingAdjacentAppendPublish(publishKey)
                    scheduleInitialAdjacentRunwayAppendRetry(
                        target,
                        allRefs,
                        publishKey,
                        warm,
                        forceDelayedPolling = true,
                    )
                    if (shouldLogRateLimitedDiagnostic(
                            "adjacent_exact_p0_main_publish_deferred_motion|${target.ntkEpisodePath}",
                        )
                    ) {
                        Log.d(
                            TAG,
                            "append_adjacent_exact_p0_main_publish_deferred_motion " +
                                "path=${target.ntkEpisodePath}",
                        )
                    }
                    return@post
                }
                synchronized(flight) {
                    if (!cancelled.get() &&
                        adjacentExactP0Flights[flight.owner.ownerToken] === flight
                    ) {
                        finishOwnedStructurePublish(structurePublishOwner)
                        val externalClaim = claimBitmapIdentitiesExternallyOwned(
                            flight.head.installs.map { install -> install.tile.bitmap },
                        )
                        accepted = externalClaim != null &&
                            listener.onAdjacentExactP0HeadReady(publication)
                        if (accepted) flight.headOwnedBySurface.set(true)
                    }
                }
                if (!accepted) {
                    rollbackAdjacentRunwayStructure(cardIndex, allRefs)
                    recycleAdjacentExactP0Delta(flight.head)
                    adjacentExactP0Flights.remove(flight.owner.ownerToken, flight)
                    releaseAdjacentExactP0Flight(flight)
                    clearPendingAdjacentAppendPublish(publishKey)
                    return@post
                }
                signalDirectWifiAdjacentHeadPixelsInstalled(target, flight.owner)
                if (flight.head.complete) {
                    completeAdjacentExactP0Flight(flight, flight.head.installs)
                } else {
                    scheduleDirectWifiAdjacentExactP0Tail(flight, target)
                }
                if (remainingRefs.isNotEmpty()) {
                    startAdjacentForegroundStreamsForRefs(
                        target,
                        remainingRefs,
                        ReaderSurfaceView.DIRECTION_NEXT,
                        asyncLaunch = true,
                    )
                }
                val publishedPath = NtkStripDigests.normalizeEpisodePath(
                    target.ntkEpisodePath.orEmpty(),
                )
                if (publishedPath.isNotEmpty()) {
                    publishedExactOffscreenRunwayPaths.add(publishedPath)
                    // All p0..p4 descriptors can precede structural publication. Re-drive the
                    // initial pixel owner from the new structure edge itself; waiting for another
                    // descriptor callback starts p1 only after the user has already hit its cap.
                    requestPublishedExactAdjacentInitialRunwayCompletion(publishedPath)
                }
                warmPublishedLaunchSuccessorInitialTail(
                    target = target,
                    allRefs = allRefs,
                    firstPublishedIndex = cardIndex,
                )
                if (warm && shouldWarmAppendedEpisode(cardIndex)) {
                    warmAppendedVisibleRunway(cardIndex, total, "append_exact_p0_head")
                }
                scheduleAppendSourcePrefetchAfterQuiet(
                    cardIndex + generatedAppendVisibleRunwayPageLimit(target),
                    total,
                    "append_exact_p0_head_source",
                )
                // Every PageRef is already present. Pixel readiness now follows viewport/source
                // ownership and must never call the structural remainder publisher again.
                clearActiveRemainingAdjacentRunwayTarget(target)
                clearPendingAdjacentAppendPublish(publishKey)
            } catch (failure: Exception) {
                Log.e(
                    TAG,
                    "append_adjacent_exact_p0_publish_error path=${target.ntkEpisodePath} " +
                        "owner=${flight.owner.ownerToken} accepted=$accepted " +
                        "error=${failure.javaClass.simpleName}:${failure.message}",
                    failure,
                )
                if (!accepted) {
                    rollbackAdjacentRunwayStructure(cardIndex, allRefs)
                    recycleAdjacentExactP0Delta(flight.head)
                    adjacentExactP0Flights.remove(flight.owner.ownerToken, flight)
                    releaseAdjacentExactP0Flight(flight)
                    clearPendingAdjacentAppendPublish(publishKey)
                }
                if (!cancelled.get()) recordIfUnexpected(failure)
            } finally {
                finishOwnedStructurePublish(structurePublishOwner)
                finishAdjacentDrawableBatchPublication(drawablePublication)
            }
        }
        Log.d(
            TAG,
            "append_adjacent_exact_p0_main_post path=${target.ntkEpisodePath} " +
                "owner=${flight.owner.ownerToken} posted=$posted",
        )
        if (!posted) {
            rollbackAdjacentRunwayStructure(cardIndex, allRefs)
            recycleAdjacentExactP0Delta(flight.head)
            adjacentExactP0Flights.remove(flight.owner.ownerToken, flight)
            releaseAdjacentExactP0Flight(flight)
            clearPendingAdjacentAppendPublish(publishKey)
            finishOwnedStructurePublish(structurePublishOwner)
            finishAdjacentDrawableBatchPublication(drawablePublication)
        }
        return true
    }

    /**
     * Completes only the launch successor's required p1..p3 drawable runway. This work is legal
     * only before the first reader DOWN; after that monotonic boundary, normal physical-window
     * rehydration owns every already-published slot. Structure was published above and is never
     * touched here.
     */
    private fun warmPublishedLaunchSuccessorInitialTail(
        target: Manga,
        allRefs: List<PageRef>,
        firstPublishedIndex: Int,
    ) {
        if (cancelled.get() || physicalScrollEverStarted.get()) return
        val requiredSources = requiredInitialAdjacentRunwayPages(target)
        val indexed = allRefs.withIndex().filter { (_, page) ->
            page.transitionTitle == null && page.sourceIndex in 1 until requiredSources
        }
        if (indexed.isEmpty()) return
        val firstOffset = indexed.first().index
        if (indexed.map { it.index } !=
            (firstOffset until firstOffset + indexed.size).toList()
        ) {
            return
        }
        val runwayRefs = indexed.map { it.value }
        val descriptorsReady = runwayRefs.all { page ->
            strictAdjacentBodyDescriptor(page) != null
        }
        if (!descriptorsReady) {
            holdOrRecoverAdjacentStrictSource(target)
            if (!cancelled.get() && !physicalScrollEverStarted.get() &&
                !isAdjacentStrictRecoveryExhausted(target)
            ) {
                main.postDelayed(
                    {
                        warmPublishedLaunchSuccessorInitialTail(
                            target,
                            allRefs,
                            firstPublishedIndex,
                        )
                    },
                    NTK_APPEND_EARLY_GENERATED_POLL_MS,
                )
            }
            return
        }
        try {
            initialAdjacentRunwayNetwork.execute {
                if (cancelled.get() || physicalScrollEverStarted.get()) return@execute
                val batch = prepareAdjacentRunwayDrawableBatch(
                    startIndex = firstPublishedIndex + firstOffset,
                    refs = runwayRefs,
                    reason = "initial_strict_source",
                    requireStrictDescriptor = true,
                )
                if (batch == null) {
                    if (!cancelled.get() && !physicalScrollEverStarted.get() &&
                        !isAdjacentStrictRecoveryExhausted(target)
                    ) {
                        main.postDelayed(
                            {
                                warmPublishedLaunchSuccessorInitialTail(
                                    target,
                                    allRefs,
                                    firstPublishedIndex,
                                )
                            },
                            NTK_APPEND_EARLY_GENERATED_POLL_MS,
                        )
                    }
                    return@execute
                }
                if (cancelled.get() || physicalScrollEverStarted.get()) {
                    recycleAdjacentRunwayDrawableBatch(batch)
                    return@execute
                }
                batch.deliveries.forEach { delivery ->
                    postDecodeResult(delivery.copy(startupAdjacentRunway = true))
                }
            }
        } catch (_: RejectedExecutionException) {
            // Session shutdown owns cancellation; no structural retry is required.
        }
    }

    private fun signalDirectWifiAdjacentHeadPixelsInstalled(
        target: Manga,
        owner: NtkAdjacentExactP0Owner,
    ) {
        val claim = adjacentStrictSourceClaims[owner.normalizedEpisodePath] ?: return
        if (claim.episode != owner.episode || claim.manifestDigest != owner.manifestDigest ||
            !isAdjacentStrictSourceClaimLive(owner.normalizedEpisodePath, claim) ||
            !claim.headPixelsInstalled.compareAndSet(false, true)
        ) return
        try {
            claim.transport.onAdjacentHeadPixelsInstalled(claim.episode)
            Log.d(
                TAG,
                "append_adjacent_exact_p0_renderer_ack path=${owner.normalizedEpisodePath} " +
                    "generation=${owner.episode.value} digest=${owner.manifestDigest}",
            )
        } catch (failure: Exception) {
            claim.headPixelsInstalled.set(false)
            if (!cancelled.get()) {
                recordIfUnexpected(failure)
                main.postDelayed(
                    { signalDirectWifiAdjacentHeadPixelsInstalled(target, owner) },
                    NTK_APPEND_EARLY_GENERATED_POLL_MS,
                )
            }
        }
    }

    private fun scheduleDirectWifiAdjacentExactP0Tail(
        flight: AdjacentExactP0Flight,
        target: Manga,
    ) {
        if (!flight.tailStarted.compareAndSet(false, true)) return
        try {
            strictExactOverlapDecode.execute {
                // This must be the first worker action. cancel() may release a submitted-but-
                // queued flight before shutdownNow() discards its Runnable; after this mark the
                // worker's finally block is the terminal lease owner.
                flight.tailWorkerStarted.set(true)
                val tailSlots = (2 until flight.plan.tiles.size).toList()
                var tail: NtkAdjacentExactP0Delta? = null
                try {
                    if (cancelled.get() || adjacentExactP0Flights[flight.owner.ownerToken] !== flight) {
                        return@execute
                    }
                    val tiles = promoteAdjacentExactTilesForDirectPresenter(
                        decodeAdjacentExactSoftwareSlots(
                            flight.lease,
                            flight.plan,
                            tailSlots,
                            parallel = true,
                        ),
                        target,
                    )
                    tail = NtkAdjacentExactP0Delta(
                        owner = flight.owner,
                        plan = flight.plan,
                        proof = flight.proof,
                        installs = adjacentExactP0Installs(flight.owner, flight.plan, tiles),
                        complete = true,
                    )
                    val completedTail = tail
                    val posted = main.post {
                        synchronized(flight) {
                            val externalClaim = claimBitmapIdentitiesExternallyOwned(
                                completedTail.installs.map { install -> install.tile.bitmap },
                            )
                            val accepted = !cancelled.get() &&
                                adjacentExactP0Flights[flight.owner.ownerToken] === flight &&
                                externalClaim != null &&
                                listener.onAdjacentExactP0TailReady(completedTail)
                            if (accepted) {
                                completeAdjacentExactP0Flight(
                                    flight,
                                    flight.head.installs + completedTail.installs,
                                )
                                markExactAdjacentRunwayTelemetryIfReady(
                                    target,
                                    target.ntkImageCount,
                                )
                            } else {
                                recycleAdjacentExactP0Delta(completedTail)
                                adjacentExactP0Flights.remove(flight.owner.ownerToken, flight)
                                releaseAdjacentExactP0Flight(flight)
                            }
                        }
                    }
                    if (!posted) {
                        recycleAdjacentExactP0Delta(completedTail)
                        adjacentExactP0Flights.remove(flight.owner.ownerToken, flight)
                        releaseAdjacentExactP0Flight(flight)
                    }
                } catch (failure: Exception) {
                    tail?.let(::recycleAdjacentExactP0Delta)
                    adjacentExactP0Flights.remove(flight.owner.ownerToken, flight)
                    releaseAdjacentExactP0Flight(flight)
                    if (!cancelled.get() && !isExpectedCancellation(failure)) {
                        recordIfUnexpected(failure)
                    }
                } finally {
                    // cancel() cannot close a lease while tail decoding is still using it. The
                    // worker therefore owns the terminal release, including its early-cancel and
                    // owner-mismatch returns. Other completion paths are idempotent through the
                    // flight's released CAS.
                    releaseAdjacentExactP0Flight(flight)
                }
            }
        } catch (_: RejectedExecutionException) {
            adjacentExactP0Flights.remove(flight.owner.ownerToken, flight)
            releaseAdjacentExactP0Flight(flight)
        }
    }

    private fun completeAdjacentExactP0Flight(
        flight: AdjacentExactP0Flight,
        installs: List<NtkAdjacentExactP0TileInstall>,
    ) {
        if (!adjacentExactP0Flights.remove(flight.owner.ownerToken, flight)) return
        val currentIndex = synchronized(pagesLock) {
            pages.indexOfFirst { page ->
                page === flight.page && page.transitionTitle == null && page.sourceIndex == 0 &&
                    page.manifestDigest == flight.owner.manifestDigest &&
                    page.canonicalAsset == flight.owner.canonicalAsset
            }
        }
        if (currentIndex >= 0) {
            val tiles = installs.sortedBy { it.slotIndex }.map { it.tile }
            if (trackDeliveredTiles(currentIndex, flight.page, tiles, owned = false) >= 0) {
                markDecodedDrawableReady(currentIndex, flight.page, flight.plan.sourceWidth)
            } else {
                rollbackPublishedBitmapConflict(
                    currentIndex,
                    flight.page,
                    flight.plan.sourceWidth,
                    "adjacent_exact_p0",
                )
            }
        }
        releaseAdjacentExactP0Flight(flight)
    }

    private fun releaseAdjacentExactP0Flight(flight: AdjacentExactP0Flight) {
        if (!flight.released.compareAndSet(false, true)) return
        flight.lease.predecodedOriginal?.close()
        flight.lease.release()
    }

    private fun recycleAdjacentExactP0Delta(delta: NtkAdjacentExactP0Delta) {
        val recycled = java.util.Collections.newSetFromMap(IdentityHashMap<Bitmap, Boolean>())
        delta.installs.forEach { install ->
            val bitmap = install.tile.bitmap
            if (recycled.add(bitmap) && !isBitmapProtectedFromRecycle(bitmap)) {
                recycleBitmapAsync(bitmap)
            }
        }
    }

    private fun adjacentExactP0Installs(
        owner: NtkAdjacentExactP0Owner,
        plan: NtkPreGeometryPagePlan,
        tiles: Map<Int, ReaderTile>,
    ): List<NtkAdjacentExactP0TileInstall> = tiles.entries
        .sortedBy { it.key }
        .map { (slot, tile) ->
            NtkAdjacentExactP0TileInstall(
                slotIndex = slot,
                resourceRevision = owner.descriptorId,
                installLease = Math.addExact(Math.multiplyExact(owner.ownerToken, 1024L), slot + 1L),
                rgbaBytes = plan.tiles[slot].rgbaBytes,
                tile = tile,
            )
        }

    @Suppress("DEPRECATION")
    private fun decodeAdjacentExactSoftwareSlots(
        lease: NtkStrictBodyLease,
        plan: NtkPreGeometryPagePlan,
        slots: List<Int>,
        parallel: Boolean,
    ): Map<Int, ReaderTile> {
        if (slots.isEmpty()) return emptyMap()
        check(slots.distinct().size == slots.size && slots.all { it in plan.tiles.indices })
        if (slots.size == 1 && slots.single() == 0 && plan.tiles.size == 1) {
            val tilePlan = plan.tiles.single()
            if (tilePlan.sourceTop == 0 && tilePlan.sourceBottom == plan.sourceHeight) {
                val waitStartedAt = SystemClock.elapsedRealtimeNanos()
                val predecodedOriginal = lease.predecodedOriginal
                val bitmap = predecodedOriginal?.takeIfReadyOrAwaitStarted(
                    plan.sourceWidth,
                    plan.sourceHeight,
                    HOST_GPU_ADJACENT_P0_PREDECODE_WAIT_MS,
                )
                if (bitmap != null) {
                    Log.d(
                        TAG,
                        "append_adjacent_exact_p0_predecode_hit waitMs=" +
                            ((SystemClock.elapsedRealtimeNanos() - waitStartedAt) / 1_000_000L),
                    )
                    return mapOf(
                        0 to ReaderTile(
                            0,
                            plan.sourceHeight,
                            plan.sourceWidth,
                            plan.sourceHeight,
                            bitmap,
                        )
                    )
                }
                if (predecodedOriginal != null) {
                    Log.d(
                        TAG,
                        "append_adjacent_exact_p0_predecode_miss waitMs=" +
                            ((SystemClock.elapsedRealtimeNanos() - waitStartedAt) / 1_000_000L),
                    )
                }
            }
        }
        val decoded = ConcurrentHashMap<Int, ReaderTile>()
        val abandoned = AtomicBoolean(false)
        fun decodePartition(partitionSlots: List<Int>) {
            if (partitionSlots.isEmpty()) return
            val decoder = lease.encodedBytes?.let { bytes ->
                BitmapRegionDecoder.newInstance(bytes, 0, bytes.size, false)
            } ?: BitmapRegionDecoder.newInstance(lease.file.absolutePath, false)
                ?: throw java.io.IOException("Adjacent exact p0 region decoder failed")
            try {
                for (slot in partitionSlots) {
                    if (abandoned.get() || cancelled.get() || Thread.currentThread().isInterrupted) {
                        throw InterruptedException("Adjacent exact p0 decode cancelled")
                    }
                    val tilePlan = plan.tiles[slot]
                    val bitmap = decoder.decodeRegion(
                        Rect(0, tilePlan.sourceTop, plan.sourceWidth, tilePlan.sourceBottom),
                        BitmapFactory.Options().apply {
                            inPreferredConfig = Bitmap.Config.ARGB_8888
                            inSampleSize = 1
                            inScaled = false
                            inMutable = false
                        },
                    ) ?: throw java.io.IOException("Adjacent exact p0 tile decode failed")
                    check(bitmap.width == plan.sourceWidth &&
                        bitmap.height == tilePlan.sourceBottom - tilePlan.sourceTop &&
                        bitmap.config == Bitmap.Config.ARGB_8888 && !bitmap.isMutable
                    ) { "Adjacent exact p0 tile storage changed" }
                    if (abandoned.get() || decoded.putIfAbsent(
                            slot,
                            ReaderTile(
                                tilePlan.sourceTop,
                                tilePlan.sourceBottom,
                                plan.sourceWidth,
                                plan.sourceHeight,
                                bitmap,
                            ),
                        ) != null
                    ) {
                        bitmap.recycle()
                        throw java.io.IOException("Adjacent exact p0 duplicate tile decode")
                    }
                }
            } finally {
                decoder.recycle()
            }
        }
        val tasks = if (parallel && slots.size > 1) {
            (0 until minOf(3, slots.size)).map { partition ->
                FutureTask { decodePartition(slots.filterIndexed { index, _ -> index % 3 == partition }) }
            }
        } else {
            emptyList()
        }
        try {
            if (tasks.isEmpty()) {
                decodePartition(slots)
            } else {
                tasks.forEach(strictExactAnchorTileDecode::execute)
                tasks.forEach { task ->
                    try {
                        task.get()
                    } catch (wrapped: ExecutionException) {
                        abandoned.set(true)
                        throw (wrapped.cause as? Exception ?: wrapped)
                    }
                }
            }
            check(decoded.size == slots.size)
            return decoded
        } catch (failure: Exception) {
            abandoned.set(true)
            tasks.forEach { it.cancel(true) }
            decoded.values.forEach { tile ->
                if (!tile.bitmap.isRecycled) tile.bitmap.recycle()
            }
            throw failure
        }
    }

    /**
     * The sparse p0 decoder intentionally works from an already-open exact lease, but the active
     * direct presenter cannot consume its ordinary ARGB_8888 Bitmaps. Promote every private tile
     * before it can enter Surface ownership. Pointer-quiet admission surrounds each non-preemptible
     * write; the pool remains reuse-first and uses only its bounded rolling envelope when every
     * settled slot still belongs to the predecessor.
     */
    private fun promoteAdjacentExactTilesForDirectPresenter(
        softwareTiles: Map<Int, ReaderTile>,
        target: Manga,
    ): Map<Int, ReaderTile> {
        if (!hostExactNativeSurfaceStorageEnabled) return softwareTiles
        val promoted = LinkedHashMap<Int, ReaderTile>(softwareTiles.size)
        try {
            for ((slot, tile) in softwareTiles.entries.sortedBy { it.key }) {
                val software = tile.bitmap
                // The initial admission above protects software decode. Recheck at the exact
                // non-preemptible HardwareBuffer write and between tiles: another DOWN can arrive
                // while the region decoders are running.
                awaitDirectWifiAdjacentP0PromotionInputQuiet(target)
                val token = HostExactHardwareTilePool.copyExactTileBitmap(software)
                    ?: throw java.io.IOException(
                        "Adjacent exact tile has no reusable direct-presenter storage",
                    )
                if (!HostExactHardwareTilePool.hasExactStorage(
                        token,
                        tile.sourceWidth,
                        tile.sourceSpan,
                    )
                ) {
                    HostExactHardwareTilePool.retire(token)
                    throw java.io.IOException("Adjacent exact tile promotion changed geometry")
                }
                promoted[slot] = tile.copy(bitmap = token)
                if (!software.isRecycled) software.recycle()
            }
            return promoted
        } catch (failure: Exception) {
            HostExactHardwareTilePool.retireAll(promoted.values.map { it.bitmap })
            softwareTiles.values.forEach { tile ->
                if (!tile.bitmap.isRecycled) tile.bitmap.recycle()
            }
            throw failure
        }
    }

    /**
     * HostExact promotion writes an AHardwareBuffer and can hold the emulator's process-wide
     * gfxstream lock for more than one display frame. Keep verified p0 bytes and their lease open,
     * but begin that non-preemptible write only after a real pointer-quiet interval. A Surface-
     * proven boundary demand bypasses the wait so continuous tail input can never deadlock.
     */
    private fun awaitDirectWifiAdjacentP0PromotionInputQuiet(target: Manga) {
        while (!cancelled.get() && !Thread.currentThread().isInterrupted) {
            if (isPhysicalBoundaryDemandingAdjacentTarget(target)) return
            val remaining = physicalTouchQuietRemainingMs(
                NTK_DIRECT_ADJACENT_PIXEL_INPUT_QUIET_MS,
            )
            if (!physicalTouchActive.get() && remaining <= 0L) return
            Thread.sleep(minOf(16L, maxOf(1L, remaining)))
        }
        throw InterruptedException("Adjacent p0 promotion admission cancelled")
    }

    private fun commitAdjacentRunwayDrawableBatch(batch: AdjacentRunwayDrawableBatch) {
        batch.deliveries.forEach { delivery ->
            deliverDecodeResultOnMain(
                delivery,
                busy = false,
                pagesReadyBeforeDrawable = true,
                allowDuringStructurePublish = true,
                authoritativePrepared = true
            )
        }
    }

    private fun directWifiAdjacentExactRunwayPublication(
        startIndex: Int,
        totalPageCount: Int,
        batch: AdjacentRunwayDrawableBatch,
    ): NtkAdjacentExactRunwayBatchPublication? {
        val firstTarget = batch.deliveries.firstOrNull()?.page?.manga ?: return null
        if (!isDirectWifiStrictAdjacentRunwayProfile(firstTarget)) return null
        val pages = ArrayList<NtkAdjacentExactRunwayTilePage>(batch.deliveries.size)
        for ((offset, delivery) in batch.deliveries.withIndex()) {
            val result = delivery.result as? PageDecodeResult.Tiles ?: return null
            val proof = result.originalProof ?: return null
            val page = delivery.page
            val path = NtkStripDigests.normalizeEpisodePath(page.manga.ntkEpisodePath.orEmpty())
            if ((!path.startsWith("/webtoon/") && !path.startsWith("/manhwa/")) ||
                page.sourceIndex < 1 ||
                delivery.index != startIndex + offset || page.manifestPageCount <= page.sourceIndex ||
                !NtkStripDigests.isSha256(page.manifestDigest) || page.canonicalAsset.isBlank()
            ) return null
            if (!ReaderPreparedStore.isCanonicalOriginalProof(
                    proof,
                    page.canonicalAsset,
                    result.pageWidth,
                    result.pageHeight,
                )
            ) {
                Log.w(
                    TAG,
                    "append_adjacent_exact_runway_proof_mismatch path=$path " +
                        "source=${page.sourceIndex} result=${result.pageWidth}x${result.pageHeight} " +
                        "proof=${proof.originalWidth}x${proof.originalHeight}",
                )
                return null
            }
            pages += NtkAdjacentExactRunwayTilePage(
                displayPageIndex = delivery.index,
                normalizedEpisodePath = path,
                sourcePageIndex = page.sourceIndex,
                canonicalAsset = page.canonicalAsset,
                manifestDigest = page.manifestDigest,
                manifestPageCount = page.manifestPageCount,
                pageWidth = result.pageWidth,
                pageHeight = result.pageHeight,
                tiles = result.tiles,
                proof = proof,
            )
        }
        return NtkAdjacentExactRunwayBatchPublication(
            previousPageCount = startIndex,
            totalPageCount = totalPageCount,
            pages = pages,
        )
    }

    private fun requiresStrictExactRemainingAdjacentRunway(refs: List<PageRef>): Boolean {
        if (refs.isEmpty()) return false
        val first = refs.first()
        val path = NtkStripDigests.normalizeEpisodePath(
            first.manga.ntkEpisodePath?.trim().orEmpty(),
        )
        val claim = adjacentStrictSourceClaims[path] ?: return false
        val authority = exactViewerApiAdjacentAuthority(first.manga)?.seal ?: return false
        return NtkStrictRemainingAdjacentDescriptorWaitPolicy.shouldOwnWait(
            // Every adjacent strict claim is constructed with resident + source-event bindings.
            // Readiness ownership is transport-neutral; exact decode/native publication remains a
            // separate direct-Wi-Fi rendering decision at the append call site.
            sourceEventChannelBound = true,
            claimLive = isAdjacentStrictSourceClaimLive(path, claim),
            claimPath = path,
            claimManifestDigest = claim.manifestDigest,
            claimRevision = claim.episode.value,
            authoritativePath = authority.normalizedEpisodePath,
            authoritativeManifestDigest = authority.digestSha256,
            authoritativeRevision = authority.revision,
            authoritativeAssets = authority.normalizedCanonicalAssets,
            pages = refs.map { page ->
                NtkStrictRemainingAdjacentDescriptorWaitPolicy.PageIdentity(
                    normalizedEpisodePath = NtkStripDigests.normalizeEpisodePath(
                        page.manga.ntkEpisodePath?.trim().orEmpty(),
                    ),
                    sourceIndex = page.sourceIndex,
                    manifestDigest = page.manifestDigest,
                    manifestPageCount = page.manifestPageCount,
                    canonicalAsset = page.canonicalAsset,
                )
            },
        )
    }

    private fun commitAdjacentExactRunwayDrawableBatch(batch: AdjacentRunwayDrawableBatch) {
        batch.deliveries.forEach { delivery ->
            if (trackDeliveredResult(
                    delivery.index,
                    delivery.page,
                    delivery.result,
                    owned = false,
                ) < 0
            ) {
                rollbackPublishedBitmapConflict(
                    delivery.index,
                    delivery.page,
                    delivery.result.width,
                    "adjacent_runway_batch",
                )
                return@forEach
            }
            pendingDeliveryWidths.remove(delivery.index)
            loading.remove(delivery.index)
            loadingPages.remove(delivery.index)
            urgentLoading.remove(delivery.index)
            urgentLoadingPages.remove(delivery.index)
            markDecodedDrawableReady(delivery.index, delivery.page, delivery.result.width)
            recordAdjacentStrictDrawableCommit(delivery.page)
        }
    }

    private fun recordAdjacentStrictDrawableCommit(page: PageRef) {
        if (page.transitionTitle != null || page.sourceIndex < 0 ||
            !isDirectWifiStrictAdjacentRunwayProfile(page.manga)
        ) return
        val path = NtkStripDigests.normalizeEpisodePath(
            page.manga.ntkEpisodePath?.trim().orEmpty(),
        )
        val claim = adjacentStrictSourceClaims[path] ?: return
        if (!isAdjacentStrictSourceClaimLive(path, claim) ||
            (page.manifestDigest.isNotBlank() && page.manifestDigest != claim.manifestDigest)
        ) return
        val requiredSources = (0 until requiredInitialAdjacentRunwayPages(page.manga)).toSet()
        adjacentStrictDrawableRunwayProofs.computeIfAbsent(
            adjacentStrictDrawableRunwayProofKey(path, claim.manifestDigest),
        ) { ConcurrentHashMap.newKeySet() }.add(page.sourceIndex)
        val complete = synchronized(claim) {
            claim.drawableRunwayCommittedSources.add(page.sourceIndex)
            claim.drawableRunwayCommittedSources.containsAll(requiredSources)
        }
        if (complete) signalDirectWifiAdjacentDrawableRunwayCommitted(page.manga)
    }

    private fun markExactAdjacentRunwayTelemetryIfReady(
        target: Manga,
        knownTotalPageCount: Int = 0,
    ) {
        if (!isNtkContinuousAdjacentCompletionPolicyActive()) return
        val snapshot = synchronized(pagesLock) {
            val refs = pages.withIndex().filter { (_, page) ->
                page.transitionTitle == null && looseSameEpisodeForAppend(page.manga, target)
            }
            if (refs.isEmpty()) return@synchronized null
            val totalPageCount = maxOf(
                knownTotalPageCount,
                target.ntkImageCount,
                canonicalEpisodeImageCount(target, refs.map { it.value }),
            )
            val requiredPageCount = minOf(
                initialAdjacentRunwayPageLimit(target.ntkEpisodePath),
                totalPageCount,
            )
            if (requiredPageCount <= 0) return@synchronized null
            val requiredSources = (0 until requiredPageCount).toSet()
            val runway = refs
                .filter { it.value.sourceIndex in requiredSources }
                .distinctBy { it.value.sourceIndex }
            if (runway.mapTo(HashSet()) { it.value.sourceIndex } != requiredSources) {
                return@synchronized null
            }
            Triple(runway, requiredPageCount, totalPageCount)
        } ?: return
        val readySources = snapshot.first
            .asSequence()
            .filter { (index, page) ->
                hasListenerDrawableDelivery(index, page) || hasDeliveredBitmap(index)
            }
            .mapTo(HashSet()) { (_, page) -> page.sourceIndex }
        val requiredSources = (0 until snapshot.second).toSet()
        val allReady = if (isDirectWifiStrictAdjacentRunwayProfile(target)) {
            val path = NtkStripDigests.normalizeEpisodePath(
                target.ntkEpisodePath?.trim().orEmpty(),
            )
            val claim = adjacentStrictSourceClaims[path]
            if (claim != null && isAdjacentStrictSourceClaimLive(path, claim)) {
                adjacentStrictDrawableRunwayProofs.computeIfAbsent(
                    adjacentStrictDrawableRunwayProofKey(path, claim.manifestDigest),
                ) { ConcurrentHashMap.newKeySet() }.addAll(readySources)
                synchronized(claim) {
                    // Pool pressure may legitimately retire p0 after it has been displayed while
                    // a large p4 is still decoding. Requiring all five bitmaps to be resident in
                    // one instantaneous snapshot then leaves the exact p5+ source admissions
                    // sealed forever. The claim is generation/manifest-bound, so retain the
                    // stronger monotonic fact that every runway source committed at least once.
                    claim.drawableRunwayCommittedSources.addAll(readySources)
                    claim.drawableRunwayCommittedSources.containsAll(requiredSources)
                }
            } else {
                false
            }
        } else {
            readySources.containsAll(requiredSources)
        }
        if (!allReady) return
        signalDirectWifiAdjacentDrawableRunwayCommitted(target)
        ViewerTelemetry.adjacentRunwayReady(
            target.ntkEpisodePath,
            snapshot.second,
            snapshot.third,
        )
    }

    private fun signalDirectWifiAdjacentDrawableRunwayCommitted(target: Manga) {
        if (cancelled.get() || !isDirectWifiStrictAdjacentRunwayProfile(target)) return
        val path = NtkStripDigests.normalizeEpisodePath(
            target.ntkEpisodePath?.trim().orEmpty(),
        )
        if (!path.startsWith("/webtoon/") && !path.startsWith("/manhwa/")) return
        val claim = adjacentStrictSourceClaims[path] ?: return
        if (!isAdjacentStrictSourceClaimLive(path, claim) ||
            !claim.drawableRunwayCommitted.compareAndSet(false, true)
        ) return
        try {
            claim.transport.onAdjacentDrawableRunwayCommitted(claim.episode)
            Log.d(
                TAG,
                "append_adjacent_strict_source_drawable_runway_committed path=$path " +
                    "digest=${claim.manifestDigest}",
            )
        } catch (failure: Exception) {
            claim.drawableRunwayCommitted.set(false)
            if (!cancelled.get()) recordIfUnexpected(failure)
        }
    }

    private fun adjacentStrictDrawableRunwayProofKey(
        normalizedPath: String,
        manifestDigest: String,
    ): String = "$normalizedPath|$manifestDigest"

    private fun recycleAdjacentRunwayDrawableBatch(batch: AdjacentRunwayDrawableBatch) {
        batch.deliveries.forEach { delivery -> recycleDecodeResult(delivery.result) }
    }

    private fun rollbackAdjacentRunwayStructure(startIndex: Int, refs: List<PageRef>) {
        synchronized(pagesLock) {
            val exactRange = refs.indices.all { offset -> pages.getOrNull(startIndex + offset) === refs[offset] }
            if (!exactRange) return@synchronized
            repeat(refs.size) { pages.removeAt(startIndex) }
            pages.forEachIndexed { index, page -> page.pageIndex = index }
            clearPageStateFromIndex(startIndex)
            capturePublishedPageIndexLocked()
        }
    }

    private fun ntkForwardAppendStructureInsertDelayMs(
        target: Manga,
        urls: List<String>,
        direction: Int
    ): Long {
        if (direction <= 0) return 0L
        if (!isNtkSource(target, title) || !firstBitmapLogged.get()) return 0L
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return 0L
        val anchor = currentViewportAnchor.get()
        if (anchor < 0) return 0L
        val tail = synchronized(pagesLock) { pages.lastIndex }
        if (tail < 0) return 0L
        if (anchor >= tail) {
            val installed = installedDrawablePageCountForEpisode(manga)
            val currentTailReady = installed > 0 &&
                isCurrentGeneratedTailReadyForAdjacent(manga, anchor, installed)
            if (currentTailReady) {
                val required = minOf(2, urls.size)
                val nextRunwayReady = required > 0 && urls.take(required).all { image ->
                    ReaderImageCache.cachedFile(appContext, target, image) != null
                }
                if (nextRunwayReady) return 0L
                return NTK_ADJACENT_FOREGROUND_STREAM_RECHECK_MS
            }
        }
        val activeInputQuietMs = maxOf(
            readerQuietRemainingMs(NTK_ADJACENT_APPEND_ACTIVE_SCROLL_QUIET_MS),
            readerQuietRemainingMs(NTK_ADJACENT_APPEND_STRUCTURE_INSERT_QUIET_MS),
            readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS),
            if (viewportBusy.get()) NTK_ADJACENT_APPEND_ACTIVE_SCROLL_QUIET_MS else 0L
        )
        if (anchor >= tail) {
            if (activeInputQuietMs <= 0L) return 0L
            return activeInputQuietMs
                .coerceAtLeast(NTK_ADJACENT_APPEND_STRUCTURE_INSERT_RECHECK_MS)
                .coerceAtMost(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS)
        }
        val quietMs = maxOf(
            activeInputQuietMs,
            ntkInitialInteractiveSettleRemainingMs(),
        )
        if (quietMs <= 0L) return 0L
        return quietMs
            .coerceAtLeast(NTK_ADJACENT_APPEND_STRUCTURE_INSERT_RECHECK_MS)
            .coerceAtMost(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS)
    }

    private fun redeliverReadyPrependedStart(inserted: Int) {
        if (cancelled.get() || inserted <= 0) return
        val limit = minOf(inserted, NTK_PREPENDED_EPISODE_START_DECODE_PAGES)
        var redelivered = 0
        for (index in 0 until limit) {
            val page = pageRef(index) ?: continue
            if (page.transitionTitle != null) continue
            val bitmap: Bitmap?
            val tiles: List<ReaderTile>?
            synchronized(deliveredBitmaps) {
                bitmap = deliveredBitmaps[index]?.takeIf { !it.isRecycled }
                tiles = if (bitmap == null) {
                    deliveredTiles[index]?.takeIf { list -> list.any { !it.bitmap.isRecycled } }
                } else {
                    null
                }
            }
            if (bitmap != null) {
                listener.onPageReady(index, bitmap)
                markListenerDrawableDelivery(index)
                markCanonicalDrawableCompletion(index, page)
                redelivered++
            } else if (!tiles.isNullOrEmpty()) {
                val first = tiles.first()
                listener.onPageTilesReady(index, first.sourceWidth, first.sourceHeight, tiles)
                markListenerDrawableDelivery(index)
                markCanonicalDrawableCompletion(index, page)
                redelivered++
            } else {
                requestPage(
                    index,
                    busy = true,
                    anchor = index == 0,
                    generation = FOREGROUND_PRIME_WARM_GENERATION
                )
            }
        }
        if (redelivered > 0) {
            Log.d(TAG, "append_adjacent_prepend_redeliver_ready inserted=$inserted,count=$redelivered")
        }
    }

    private fun tryRedeliverRetainedGeneratedDrawable(index: Int, page: PageRef, reason: String): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (cancelled.get() || pageRef(index) != page) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (!isActiveGeneratedTouchOrQuiet() && !viewportBusy.get() && !isWithinFirstBitmapInputGrace()) return false
        // A retained drawable is normally redelivered only after a surface/structure hand-off.
        // The live reader already owns the exact immutable tiles in the common case.  Posting
        // them again at the front of the main queue rebuilds geometry and can collide with the
        // first physical gesture without adding a single pixel.
        if (listener.isPageDrawableInstalled(index)) return false
        val bitmap: Bitmap?
        val tiles: List<ReaderTile>?
        synchronized(deliveredBitmaps) {
            bitmap = deliveredBitmaps[index]?.takeIf { !it.isRecycled }
            tiles = if (bitmap == null) {
                deliveredTiles[index]?.takeIf { list ->
                    list.isNotEmpty() && list.none { it.bitmap.isRecycled }
                }
            } else {
                null
            }
        }
        if (bitmap == null && tiles.isNullOrEmpty()) return false
        val deliver = Runnable {
            if (cancelled.get() || pageRef(index) != page) {
                return@Runnable
            }
            val retainedBitmap = bitmap
            val retainedTiles = tiles
            if (retainedBitmap != null && !retainedBitmap.isRecycled) {
                listener.onPageProofReady(index, retainedBitmap)
                markDecodedDrawableReady(index, page, retainedBitmap.width)
                if (!isActiveGeneratedTouchOrQuiet() && !viewportBusy.get()) {
                    Log.d(TAG, "reader_retained_generated_redeliver index=$index,reason=$reason,width=${retainedBitmap.width}")
                }
            } else if (!retainedTiles.isNullOrEmpty() && retainedTiles.none { it.bitmap.isRecycled }) {
                val first = retainedTiles.first()
                listener.onPageProofTilesReady(index, first.sourceWidth, first.sourceHeight, retainedTiles)
                markDecodedDrawableReady(index, page, first.sourceWidth)
                if (!isActiveGeneratedTouchOrQuiet() && !viewportBusy.get()) {
                    Log.d(
                        TAG,
                        "reader_retained_generated_redeliver index=$index,reason=$reason," +
                            "width=${first.sourceWidth},tiles=${retainedTiles.size}"
                    )
                }
            }
        }
        return if (Looper.myLooper() == Looper.getMainLooper()) {
            deliver.run()
            true
        } else {
            mainImmediate.post(deliver)
        }
    }

    private fun prependedHoldUntilReadyCount(target: Manga, refs: List<PageRef>): Int {
        val drawableCount = refs.count { it.transitionTitle == null }
        if (drawableCount <= 0) return 0
        // Ordinary manga used to reveal the prepend card immediately and let another reverse
        // gesture run into an unrendered page 0. Hold at the card until at least one adjacent image
        // is drawable; ReaderSurfaceView separately prevents a new PREVIOUS boundary while page 0
        // is still empty.
        if (!isNtkSource(target, title)) return 1
        if (!firstBitmapLogged.get()) return 0
        if (!isNtkManhwaEpisodePath(target.ntkEpisodePath)) return 0
        val knownCount = when {
            target.ntkImageCount > 1 -> target.ntkImageCount
            drawableCount > 1 -> drawableCount
            else -> 0
        }
        if (knownCount <= 1) return 1
        return minOf(NTK_OBSERVED_MANHWA_APPEND_READY_PAGES, knownCount, drawableCount)
    }

    private fun shouldGateAdjacentPrependNotifyUntilNearReady(
        target: Manga,
        inserted: Int,
        requiredReady: Int
    ): Boolean {
        if (!isNtkSource(manga, title) || !firstBitmapLogged.get()) return false
        if (!isNtkManhwaEpisodePath(target.ntkEpisodePath)) return false
        if (inserted <= 0 || requiredReady <= 0) return false
        return generatedPrependNearReadyCount(inserted, requiredReady) < requiredReady
    }

    private fun notifyAdjacentPrependWhenNearReady(
        target: Manga,
        inserted: Int,
        total: Int,
        cardOffset: Int,
        transitionTitle: String,
        requiredReady: Int
    ) {
        val notify = object : Runnable {
            override fun run() {
                if (cancelled.get()) return
                val ready = generatedPrependNearReadyCount(inserted, requiredReady)
                if (ready < requiredReady) {
                    main.postDelayed(this, NTK_GENERATED_APPEND_NOTIFY_NEAR_READY_POLL_MS)
                    return
                }
                Log.d(
                    TAG,
                    "append_adjacent_prepend_notify_near_ready targetId=${target.id} path=${target.ntkEpisodePath} " +
                        "ready=$ready required=$requiredReady inserted=$inserted total=$total"
                )
                val publishDelayMs = ntkAdjacentPrependPublishDelayMs()
                if (publishDelayMs > 0L) {
                    Log.d(
                        TAG,
                        "append_adjacent_prepend_notify_defer_active_view path=${target.ntkEpisodePath} " +
                            "delayMs=$publishDelayMs viewportAnchor=${currentViewportAnchor.get()}"
                    )
                    main.postDelayed(this, publishDelayMs)
                    return
                }
                listener.onPagesPrepended(total, inserted, requiredReady)
                if (cardOffset >= 0) listener.onPageCard(cardOffset, transitionTitle)
                redeliverReadyPrependedStart(inserted)
            }
        }
        notify.run()
    }

    private fun ntkAdjacentPrependPublishDelayMs(): Long {
        if (!isNtkSource(manga, title) || !firstBitmapLogged.get()) return 0L
        val backgroundQuietMs = ntkBackgroundPrepareQuietRemainingMs()
        val touchQuietMs = readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS)
        val quietMs = maxOf(backgroundQuietMs, touchQuietMs)
        if (quietMs > 0L) return quietMs.coerceAtLeast(NTK_GENERATED_APPEND_NOTIFY_NEAR_READY_POLL_MS)
        val viewportAnchor = currentViewportAnchor.get()
        if (viewportAnchor > 0) return NTK_PREPEND_NOTIFY_BOUNDARY_RECHECK_MS
        return 0L
    }

    private fun generatedPrependNearReadyCount(inserted: Int, requiredReady: Int): Int = synchronized(pagesLock) {
        if (inserted <= 0 || pages.isEmpty()) return@synchronized 0
        val last = minOf(inserted - 1, pages.lastIndex)
        var ready = 0
        for (index in 0..last) {
            val page = pages.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!hasListenerDrawableDelivery(index, page)) break
            ready++
            if (ready >= requiredReady) break
        }
        ready
    }

    private fun shouldGateAdjacentAppendNotifyUntilNearReady(target: Manga, cardIndex: Int, total: Int): Boolean {
        if (!isNtkSource(manga, title) || !firstBitmapLogged.get()) return false
        if (isImmediateNtkGeneratedUx() && isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) {
            Log.d(
                TAG,
                "append_adjacent_publish_gate_immediate_generated_ux targetId=${target.id} " +
                    "path=${target.ntkEpisodePath} cardIndex=$cardIndex total=$total"
            )
        }
        val firstNearDrawable = firstGeneratedAppendDrawableIndex(cardIndex, total) ?: return false
        val firstPage = pageRef(firstNearDrawable) ?: return true
        return !hasGeneratedAppendNearReady(target, cardIndex, total) ||
            !hasListenerDrawableDelivery(firstNearDrawable, firstPage)
    }

    private fun rememberPendingAdjacentAppendPublish(
        publishKey: String,
        target: Manga,
        start: Int,
        total: Int
    ) {
        if (publishKey.isEmpty()) return
        pendingAdjacentAppendPublishes[publishKey] = PendingAdjacentAppendPublish(
            path = target.ntkEpisodePath?.trim().orEmpty(),
            start = start,
            total = total,
            targetId = target.id
        )
    }

    private fun clearPendingAdjacentAppendPublish(publishKey: String) {
        if (publishKey.isEmpty()) return
        pendingAdjacentAppendPublishes.remove(publishKey)
        pendingAdjacentAppendPublishKeys.remove(publishKey)
        scheduledInitialAdjacentRunwayRetryKeys.remove(publishKey)
        parkedInitialAdjacentRunwayPathsByRetryKey.remove(publishKey)?.let { path ->
            parkedInitialAdjacentRunwayRetries.remove(path)?.let(main::removeCallbacks)
        }
    }

    private fun shouldPublishPendingAdjacentAppend(
        publishKey: String,
        target: Manga,
        total: Int,
        reason: String
    ): Boolean {
        if (publishKey.isEmpty()) return true
        // A cleared token is a cancellation, never permission for an older polling Runnable to
        // publish its captured page count.  Removal/replacement can retire the structure while a
        // 32 ms readiness callback is already queued on main; treating absence as success lets
        // that stale callback resurrect the retired boundary.
        val pending = pendingAdjacentAppendPublishes[publishKey] ?: return false
        val valid = synchronized(pagesLock) {
            pages.size >= pending.total &&
                total >= pending.total &&
                pending.start in pages.indices &&
                pages.subList(pending.start, minOf(pending.total, pages.size)).any {
                    it.transitionTitle == null && Manga.sameEpisodeIdentity(it.manga, target)
                }
        }
        if (!valid) {
            clearPendingAdjacentAppendPublish(publishKey)
            Log.d(
                TAG,
                "append_adjacent_publish_skip_removed targetId=${target.id} path=${target.ntkEpisodePath} " +
                    "reason=$reason start=${pending.start} total=${pending.total} current=${pagesLastIndex() + 1}"
            )
            return false
        }
        clearPendingAdjacentAppendPublish(publishKey)
        return true
    }

    private fun consumeUnpublishedAdjacentAppendRemoval(page: PageRef, start: Int, count: Int): Boolean {
        val publishKey = episodeAppendKey(page.manga)
        if (publishKey.isEmpty()) return false
        val pending = pendingAdjacentAppendPublishes[publishKey] ?: return false
        val endExclusive = start + count
        val pendingEndExclusive = pending.total
        val overlaps = start < pendingEndExclusive && endExclusive > pending.start
        if (!overlaps) return false
        clearPendingAdjacentAppendPublish(publishKey)
        Log.d(
            TAG,
            "append_adjacent_unpublished_remove_suppressed targetId=${pending.targetId} " +
                "path=${pending.path} start=$start count=$count pendingStart=${pending.start} " +
                "pendingTotal=${pending.total}"
        )
        return true
    }

    private fun notifyAdjacentAppendWhenNearReady(
        target: Manga,
        cardIndex: Int,
        total: Int,
        cardOffset: Int,
        transitionTitle: String
    ) {
        val firstNearDrawable = firstGeneratedAppendDrawableIndex(cardIndex, total) ?: run {
            val publishDelayMs = ntkAdjacentAppendPublishDelayMs(target)
            if (publishDelayMs > 0L) {
                main.postDelayed({
                    if (!cancelled.get()) notifyAdjacentAppendWhenNearReady(target, cardIndex, total, cardOffset, transitionTitle)
                }, publishDelayMs)
            } else {
                val publishKey = episodeAppendKey(target)
                if (!shouldPublishPendingAdjacentAppend(publishKey, target, total, "no_near_drawable")) return
                listener.onPagesAppended(total)
                if (cardOffset >= 0) listener.onPageCard(cardIndex + cardOffset, transitionTitle)
            }
            return
        }
        val publishKey = episodeAppendKey(target)
        val notify = object : Runnable {
            override fun run() {
                if (cancelled.get()) return
                // clearPendingAdjacentAppendPublish owns cancellation. Stop this polling owner
                // immediately when another recovery/removal path retires the token; otherwise a
                // permanently missing drawable leaves a main-thread Runnable alive for the
                // entire Session and can later publish a stale total.
                if (publishKey.isNotEmpty() &&
                    pendingAdjacentAppendPublishes[publishKey] == null
                ) return
                if (!hasGeneratedAppendNearReady(target, cardIndex, total)) {
                    main.postDelayed(this, NTK_GENERATED_APPEND_NOTIFY_NEAR_READY_POLL_MS)
                    return
                }
                val ready = generatedAppendNearReadyCount(cardIndex, total)
                val required = requiredGeneratedAppendReadyPages(target, cardIndex, total)
                Log.d(
                    TAG,
                    "append_adjacent_notify_near_ready targetId=${target.id} path=${target.ntkEpisodePath} " +
                        "firstNear=$firstNearDrawable ready=$ready required=$required total=$total"
                )
                val publishDelayMs = ntkAdjacentAppendPublishDelayMs(target)
                if (publishDelayMs > 0L) {
                    Log.d(
                        TAG,
                        "append_adjacent_notify_defer_input_quiet targetId=${target.id} " +
                            "path=${target.ntkEpisodePath} delayMs=$publishDelayMs total=$total"
                    )
                    main.postDelayed(this, publishDelayMs)
                    return
                }
                if (!shouldPublishPendingAdjacentAppend(publishKey, target, total, "near_ready")) return
                listener.onPagesAppended(total)
                if (cardOffset >= 0) listener.onPageCard(cardIndex + cardOffset, transitionTitle)
            }
        }
        notify.run()
    }

    private fun ntkAdjacentAppendPublishDelayMs(target: Manga? = null): Long {
        if (!isNtkSource(manga, title) || !firstBitmapLogged.get()) return 0L
        if (
            target != null &&
            isImmediateNtkGeneratedUx() &&
            isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)
        ) {
            return 0L
        }
        return maxOf(
            readerQuietRemainingMs(NTK_ADJACENT_APPEND_NOTIFY_INPUT_QUIET_MS),
            if (isImmediateNtkGeneratedUx()) {
                readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS)
            } else {
                0L
            },
            if (viewportBusy.get()) NTK_ADJACENT_APPEND_ACTIVE_SCROLL_QUIET_MS else 0L
        )
            .coerceAtLeast(0L)
    }

    private fun hasGeneratedAppendNearReady(target: Manga, start: Int, total: Int): Boolean {
        return generatedAppendNearReadyCount(start, total) >= requiredGeneratedAppendReadyPages(target, start, total)
    }

    private fun requiredGeneratedAppendReadyPages(target: Manga): Int {
        val base = if (isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) {
            NTK_APPEND_READY_VIEWPORT_PAGES
        } else {
            1
        }
        val declared = target.ntkImageCount
        return if (declared > 0) minOf(base, declared) else base
    }

    private fun requiredGeneratedAppendReadyPages(target: Manga, start: Int, total: Int): Int {
        val base = requiredGeneratedAppendReadyPages(target)
        val available = synchronized(pagesLock) {
            val last = minOf(total - 1, pages.lastIndex)
            if (start > last) return@synchronized 0
            var count = 0
            for (index in start..last) {
                val page = pages.getOrNull(index) ?: continue
                if (page.transitionTitle != null) continue
                if (!Manga.sameEpisodeIdentity(page.manga, target)) continue
                count++
            }
            count
        }
        return if (available > 0) minOf(base, available) else base
    }

    private fun generatedAppendNearReadyCount(start: Int, total: Int): Int = synchronized(pagesLock) {
        val first = firstGeneratedAppendDrawableIndex(start, total) ?: return@synchronized 0
        val last = minOf(total - 1, pages.lastIndex)
        val firstPage = pages.getOrNull(first)?.manga
        val required = if (firstPage != null) {
            requiredGeneratedAppendReadyPages(firstPage, start, total)
        } else {
            1
        }
        var ready = 0
        for (index in first..last) {
            val page = pages.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!hasListenerDrawableDelivery(index, page)) break
            ready++
            if (ready >= required) break
        }
        ready
    }

    private fun shouldWarmAppendedEpisode(cardIndex: Int): Boolean {
        if (!isNtkSource(manga, title)) return true
        val anchor = currentViewportAnchor.get()
        if (anchor < 0) return false
        val physicalForwardEdge = synchronized(pagesLock) {
            reportedPhysicalWindowLocked(
                fallbackAnchor = anchor,
                fallbackFirst = anchor,
                fallbackLast = anchor,
            ).last
        }
        val forwardEdge = maxOf(anchor, physicalForwardEdge)
        // cardIndex is the boundary itself. If four current pages (not five index
        // positions) sit between the physical edge and that card, this is already the
        // four-page warm zone.
        val near = HostExactHardwareTilePoolPressurePolicy
            .pagesStrictlyBeforeAdjacentBoundary(forwardEdge, cardIndex) <=
            NTK_APPEND_WARM_BOUNDARY_PAGES
        if (!near) {
            Log.d(
                TAG,
                "append_adjacent_warm_deferred_offscreen cardIndex=$cardIndex," +
                    "anchor=$anchor,physicalForwardEdge=$physicalForwardEdge," +
                    "path=${manga.ntkEpisodePath}"
            )
        }
        return near
    }

    private fun generatedAppendVisibleRunwayPageLimit(target: Manga): Int {
        val base = requiredGeneratedAppendReadyPages(target)
        val extra = if (isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) {
            if (isActiveGeneratedTouchOrQuiet() || viewportBusy.get()) {
                NTK_ACTIVE_SCROLL_FOREGROUND_RADIUS
            } else {
                maxOf(
                    NTK_ACTIVE_SCROLL_FOREGROUND_RADIUS,
                    initialAdjacentRunwayPageLimit(target.ntkEpisodePath),
                )
            }
        } else {
            0
        }
        return (base + extra).coerceAtLeast(1)
    }

    private fun warmAppendedVisibleRunway(cardIndex: Int, total: Int, reason: String) {
        if (cancelled.get() || cardIndex < 0 || total <= cardIndex) return
        if (!isImmediateNtkGeneratedUx()) {
            warmAppendedEpisode(cardIndex, total)
            return
        }
        val quietMs = appendVisibleRunwayWarmDelayMs()
        if (quietMs > 0L) {
            Log.d(
                TAG,
                "append_visible_runway_warm_defer reason=$reason,cardIndex=$cardIndex,total=$total,quietMs=$quietMs"
            )
            main.postDelayed({
                if (!cancelled.get()) warmAppendedVisibleRunway(cardIndex, total, reason)
            }, quietMs.coerceAtLeast(NTK_BACKGROUND_WARM_RECHECK_MS))
            return
        }
        val refs = synchronized(pagesLock) { pages.toList() }
        if (cardIndex !in refs.indices) return
        val target = refs.getOrNull(cardIndex)?.manga ?: manga
        val limit = if (isActiveGeneratedTouchOrQuiet()) {
            requiredGeneratedAppendReadyPages(target)
        } else {
            generatedAppendVisibleRunwayPageLimit(target)
        }
        val last = minOf(refs.lastIndex, total - 1, cardIndex + limit - 1)
        var requested = 0
        for (index in cardIndex..last) {
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!isNtkGeneratedImageUrl(page.image.orEmpty())) continue
            if (hasDeliveredOrPendingDrawable(index)) continue
            if (index < cardIndex + requiredGeneratedAppendReadyPages(target)) {
                immediateFullSurfacePrimeKeys.add(immediateFullSurfacePrimeKey(page))
            }
            if (
                !reason.contains("after_notify", ignoreCase = true) &&
                !reason.contains("generated_gate", ignoreCase = true) &&
                hasRecentAdjacentForegroundStream(page.manga, page.image, index)
            ) {
                Log.d(
                    TAG,
                    "append_visible_runway_warm_skip_recent_stream reason=$reason,index=$index," +
                        "path=${page.manga.ntkEpisodePath},image=${page.image?.substringAfterLast('/')}"
                )
                continue
            }
            requestPage(
                index,
                busy = true,
                anchor = index == cardIndex,
                generation = FOREGROUND_PRIME_WARM_GENERATION
            )
            requested++
        }
        Log.d(
            TAG,
            "append_visible_runway_warm reason=$reason,cardIndex=$cardIndex,last=$last," +
                "limit=$limit,requested=$requested,total=$total"
        )
    }

    private fun scheduleWarmAppendedVisibleRunwayAfterNotify(cardIndex: Int, total: Int, reason: String) {
        if (cancelled.get()) return
        main.postDelayed({
            if (!cancelled.get()) warmAppendedVisibleRunway(cardIndex, total, reason)
        }, NTK_APPEND_VISIBLE_RUNWAY_AFTER_NOTIFY_MS)
    }

    private fun scheduleAppendSourcePrefetchAfterQuiet(startIndex: Int, total: Int, reason: String) {
        if (cancelled.get() || !isImmediateNtkGeneratedUx() || startIndex >= total) return
        val delayMs = appendSourcePrefetchQuietDelayMs()
        main.postDelayed({
            if (cancelled.get()) return@postDelayed
            val nextDelayMs = appendSourcePrefetchQuietDelayMs()
            if (nextDelayMs > 0L) {
                scheduleAppendSourcePrefetchAfterQuiet(startIndex, total, reason)
                return@postDelayed
            }
            runAppendSourcePrefetchBatch(startIndex, total, reason)
        }, delayMs.coerceAtLeast(NTK_BACKGROUND_WARM_RECHECK_MS))
    }

    private fun appendSourcePrefetchQuietDelayMs(): Long {
        if (!isNtkSource(manga, title)) return 0L
        return maxOf(
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS),
            readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS),
            if (viewportBusy.get()) NTK_BACKGROUND_WARM_RECHECK_MS else 0L
        )
    }

    private fun appendVisibleRunwayWarmDelayMs(): Long {
        if (!isNtkSource(manga, title)) return 0L
        if (isImmediateNtkGeneratedUx()) return 0L
        return appendSourcePrefetchQuietDelayMs()
    }

    private fun runAppendSourcePrefetchBatch(startIndex: Int, total: Int, reason: String) {
        val refs = synchronized(pagesLock) { pages.toList() }
        if (startIndex !in 0..refs.size || startIndex >= total) return
        var scheduled = 0
        var nextIndex = startIndex
        val endExclusive = minOf(total, refs.size)
        while (nextIndex < endExclusive && scheduled < NTK_GENERATED_FULL_BYTE_PREFETCH_BATCH_PAGES) {
            val index = nextIndex
            nextIndex++
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!isNtkGeneratedImageUrl(page.image.orEmpty())) continue
            if (hasPageSourceReady(index, page)) continue
            sourcePrefetchNetwork.execute {
                prefetchImageFileQuietly(index, page)
            }
            scheduled++
        }
        Log.d(
            TAG,
            "append_source_prefetch_batch reason=$reason,from=$startIndex,next=$nextIndex," +
                "scheduled=$scheduled,total=$total"
        )
        if (nextIndex < endExclusive) {
            scheduleAppendSourcePrefetchAfterQuiet(nextIndex, total, "${reason}_next")
        }
    }

    private fun warmFullNtkAppendEpisode(cardIndex: Int, total: Int, reason: String) {
        if (cancelled.get() || !isNtkSource(manga, title) || cardIndex < 0 || total <= cardIndex) return
        if (!ntkAppendFullWarmBatches.add(cardIndex)) {
            Log.d(
                TAG,
                "append_full_warm_skip_active cardIndex=$cardIndex,total=$total,reason=$reason"
            )
            return
        }
        requestAllUndeliveredNtkPages(reason, cardIndex)
        scheduleNtkAppendFullWarmRetry(cardIndex, 1)
    }

    private fun scheduleNtkAppendFullWarmRetry(cardIndex: Int, attempt: Int) {
        if (attempt > NTK_APPEND_FULL_WARM_RETRY_MAX) {
            ntkAppendFullWarmBatches.remove(cardIndex)
            return
        }
        val delayMs = NTK_APPEND_FULL_WARM_RETRY_MS * attempt
        main.postDelayed({
            if (cancelled.get() || !isNtkSource(manga, title)) {
                ntkAppendFullWarmBatches.remove(cardIndex)
                return@postDelayed
            }
            if (isNtkAppendTailReady(cardIndex)) {
                ntkAppendFullWarmBatches.remove(cardIndex)
                return@postDelayed
            }
            if (isNtkAppendTailActivelyLoading(cardIndex)) {
                Log.d(
                    TAG,
                    "append_full_retry_defer_active cardIndex=$cardIndex,attempt=$attempt"
                )
                scheduleNtkAppendFullWarmRetry(cardIndex, attempt + 1)
                return@postDelayed
            }
            requestAllUndeliveredNtkPages("append_full_retry_$attempt", cardIndex)
            if (!isNtkAppendTailReady(cardIndex)) {
                scheduleNtkAppendFullWarmRetry(cardIndex, attempt + 1)
            } else {
                ntkAppendFullWarmBatches.remove(cardIndex)
            }
        }, delayMs)
    }

    private fun isNtkAppendTailReady(cardIndex: Int): Boolean {
        val refs = synchronized(pagesLock) { pages.toList() }
        if (cardIndex < 0 || cardIndex >= refs.size) return true
        for (index in cardIndex until refs.size) {
            val page = refs[index]
            if (page.transitionTitle != null) continue
            if (!isNtkSource(page.manga, title)) continue
            if (!hasDeliveredBitmap(index)) return false
        }
        return true
    }

    private fun isNtkAppendTailActivelyLoading(cardIndex: Int): Boolean {
        val refs = synchronized(pagesLock) { pages.toList() }
        if (cardIndex < 0 || cardIndex >= refs.size) return false
        for (index in cardIndex until refs.size) {
            val page = refs[index]
            if (page.transitionTitle != null) continue
            if (!isNtkSource(page.manga, title)) continue
            if (loading.contains(index) ||
                loadingPages.containsKey(index) ||
                urgentLoading.contains(index) ||
                urgentLoadingPages.containsKey(index) ||
                inFlightWidths.containsKey(index) ||
                pendingDeliveryWidths.containsKey(index) ||
                primedDeliveryBacklog.containsKey(index)
            ) {
                return true
            }
        }
        return false
    }

    private fun warmAppendedEpisode(cardIndex: Int, total: Int) {
        if (cancelled.get() || cardIndex < 0 || total <= cardIndex) return
        val ntk = isNtkSource(manga, title)
        val generation = if (ntk) FOREGROUND_PRIME_WARM_GENERATION else windowGeneration.get()
        val busy = ntk || viewportBusy.get()
        val activeNtkInput = ntk && (viewportBusy.get() || ntkInitialInteractiveSettleRemainingMs() > 0L)
        val decodeAhead = if (ntk) {
            if (activeNtkInput) NTK_ACTIVE_APPEND_DECODE_AHEAD_PAGES else NTK_PRIMED_EPISODE_DECODE_AHEAD_PAGES
        } else if (busy) {
            BOUNDARY_BUSY_DECODE_AHEAD_PAGES
        } else {
            BOUNDARY_DECODE_AHEAD_PAGES
        }
        val byteAhead = if (ntk) {
            if (activeNtkInput) NTK_ACTIVE_APPEND_BYTE_AHEAD_PAGES else NTK_PRIMED_EPISODE_BYTE_AHEAD_PAGES
        } else if (busy) {
            BOUNDARY_BUSY_BYTE_AHEAD_PAGES
        } else {
            BOUNDARY_BYTE_AHEAD_PAGES
        }
        requestPage(cardIndex, busy = busy, anchor = false, generation = generation)
        val last = minOf(total - 1, cardIndex + decodeAhead)
        for (index in (cardIndex + 1)..last) {
            val priorityGeneration = if (ntk && index <= cardIndex + NTK_PRIMED_EPISODE_PRIORITY_PAGES) {
                FOREGROUND_PRIME_WARM_GENERATION
            } else {
                generation
            }
            requestPage(index, busy = busy, anchor = false, generation = priorityGeneration)
        }
        val byteLast = minOf(total - 1, cardIndex + byteAhead)
        for (index in (last + 1)..byteLast) {
            val page = pageRef(index) ?: continue
            network.execute { prefetchImageFileQuietly(index, page) }
        }
    }

    private fun warmPrependedEpisode(inserted: Int) {
        if (cancelled.get() || inserted <= 0) return
        val ntk = isNtkSource(manga, title)
        val generation = if (ntk) FOREGROUND_PRIME_WARM_GENERATION else windowGeneration.get()
        val busy = ntk || viewportBusy.get()
        val decodeAhead = if (ntk) {
            NTK_PREPENDED_EPISODE_DECODE_AHEAD_PAGES
        } else if (busy) {
            BOUNDARY_BUSY_DECODE_AHEAD_PAGES
        } else {
            BOUNDARY_DECODE_AHEAD_PAGES
        }
        val byteAhead = if (ntk) {
            NTK_PREPENDED_EPISODE_BYTE_AHEAD_PAGES
        } else if (busy) {
            BOUNDARY_BUSY_BYTE_AHEAD_PAGES
        } else {
            BOUNDARY_BYTE_AHEAD_PAGES
        }
        val cardIndex = inserted - 1
        requestPage(cardIndex, busy = busy, anchor = false, generation = generation)
        val firstImageIndex = if (pageRef(cardIndex)?.transitionTitle != null) cardIndex - 1 else cardIndex
        if (firstImageIndex >= 0) {
            requestPage(
                firstImageIndex,
                busy = busy,
                anchor = ntk,
                generation = if (ntk) FOREGROUND_PRIME_WARM_GENERATION else generation
            )
        }
        // Index 0 is a real image for prepend layouts. Excluding it left the absolute beginning of
        // every previous episode as a permanent white page after the user scrolled back far enough.
        val firstDecoded = max(0, inserted - decodeAhead)
        if (firstImageIndex - 1 >= firstDecoded) {
            for (index in (firstImageIndex - 1) downTo firstDecoded) {
                requestPage(index, busy = busy, anchor = false, generation = generation)
            }
        }
        val firstByte = max(0, inserted - byteAhead)
        for (index in (firstDecoded - 1) downTo firstByte) {
            val page = pageRef(index) ?: continue
            network.execute { prefetchImageFileQuietly(index, page) }
        }
    }

    private fun warmPrependedEpisodeStart(inserted: Int) {
        if (cancelled.get() || inserted <= 0) return
        val ntk = isNtkSource(manga, title)
        if (!ntk) return
        val decodeLast = minOf(inserted - 1, NTK_PREPENDED_EPISODE_START_DECODE_PAGES - 1)
        for (index in 0..decodeLast) {
            val page = pageRef(index) ?: continue
            if (page.transitionTitle != null) continue
            requestPage(
                index,
                busy = false,
                anchor = index == 0,
                generation = FOREGROUND_PRIME_WARM_GENERATION
            )
        }
        val byteLast = minOf(inserted - 1, NTK_PREPENDED_EPISODE_START_BYTE_PAGES - 1)
        for (index in (decodeLast + 1)..byteLast) {
            val page = pageRef(index) ?: continue
            if (page.transitionTitle != null) continue
            network.execute { prefetchImageFileQuietly(index, page) }
        }
    }

    private fun hasEpisode(target: Manga): Boolean = synchronized(pagesLock) {
        containsEpisodeForAppendLocked(target)
    }

    private fun hasEpisodeFast(target: Manga): Boolean = synchronized(pagesLock) {
        containsEpisodeFastLocked(target)
    }

    /**
     * The completion edge may already own the exact forward target while a boundary callback is
     * queued. Join that owner instead of resolving the episode list a second time. NTK's final
     * numeric path segment is an opaque database key, so a parallel resolver can otherwise pick
     * the opposite neighbor, enter another strict network owner, and cancel the correct p0 flight.
     * Multiple targets for one predecessor are an ownership conflict and fail closed; neither
     * branch falls back to an inferred numeric episode.
     */
    private fun joinCompletionOwnedForwardExactAppend(source: Manga, direction: Int): Boolean {
        if (direction <= 0 || !isNtkContinuousAdjacentCompletionPolicyActive()) return false
        val sourcePath = NtkStripDigests.normalizeEpisodePath(
            source.ntkEpisodePath?.trim().orEmpty(),
        )
        if (sourcePath.isEmpty()) return false
        val forwardAdjacentExactManifestAppends =
            forwardAdjacentExactManifestAppendGate.snapshot()
        val pending = forwardAdjacentExactManifestAppends.entries.filter { entry ->
            val predecessorMatches =
                NtkStripDigests.normalizeEpisodePath(entry.value.predecessorEpisodePath)
                    .equals(sourcePath, ignoreCase = true)
            if (!predecessorMatches) {
                false
            } else if (isForwardAdjacentCompletionTargetCurrent(
                    entry.value.predecessorEpisodePath,
                    entry.key,
                    entry.value.claimRevision,
                )
            ) {
                true
            } else {
                // Never let an orphan pending value suppress the ordinary provider-list path.
                forwardAdjacentExactManifestAppendGate.removePending(entry.key, entry.value)
                false
            }
        }
        if (pending.isEmpty()) return false
        if (pending.size != 1) {
            Log.e(
                TAG,
                "append_adjacent_completion_owner_conflict predecessor=$sourcePath," +
                    "targets=${pending.map { it.key }.sorted().joinToString("|")}",
            )
            return true
        }
        val pendingEntry = pending.single()
        val targetPath = pendingEntry.key
        Log.d(
            TAG,
            "append_adjacent_completion_owner_join predecessor=$sourcePath,target=$targetPath",
        )
        val manifest = NtkSourceSpoolRegistry.currentAuthoritativeManifest(targetPath)
        if (manifest != null) {
            onForwardAdjacentExactManifestInstalled(targetPath, manifest)
        } else if (!NtkStrictEpisodeDiscoveryCoordinator.isInFlight(targetPath)) {
            // A discovery can join successfully and then retire without publishing a manifest.
            // The pending completion claim must not make every later physical boundary a no-op.
            // Re-notify the lifecycle owner; its token-scoped watchdog will start or join exactly
            // one fresh flight while this exact target remains current.
            listener.onAdjacentExactManifestRequired(
                pendingEntry.value.target,
                pendingEntry.value.predecessorEpisodePath,
            )
        }
        return true
    }

    /**
     * Retires only the still-current completion claim after repeated discovery launches ended
     * without a manifest. A stale/404 target must not make every later physical boundary join an
     * empty owner forever. The exact revision is compare-removed, then the same boundary is
     * re-driven through the ordinary fresh-list resolver without requiring another gesture.
     */
    fun retireStalledForwardAdjacentExactManifestClaim(
        rawPredecessorPath: String,
        rawTargetPath: String,
    ): Boolean {
        if (cancelled.get()) return false
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(rawPredecessorPath)
        val targetPath = NtkStripDigests.normalizeEpisodePath(rawTargetPath)
        if (predecessorPath.isEmpty() || targetPath.isEmpty() ||
            NtkSourceSpoolRegistry.currentAuthoritativeManifest(targetPath) != null ||
            NtkStrictEpisodeDiscoveryCoordinator.isInFlight(targetPath)
        ) return false
        var retiredRevision = 0L
        var consumedValidatedEpoch = 0L
        val removed = synchronized(forwardAdjacentCompletionTargetClaimLock) {
            val selected = forwardAdjacentCompletionTargetClaims[predecessorPath]
            if (selected != null &&
                !selected.structureCommitted &&
                selected.targetEpisodePath.equals(targetPath, ignoreCase = true)
            ) {
                retiredRevision = selected.revision
                val observedEpoch = lastObservedForwardAdjacentValidatedNetworkEpoch
                val observedPath = lastObservedForwardAdjacentValidatedNetworkPath
                if (NtkForwardAdjacentValidatedRecoveryPolicy.shouldRearm(
                        validatedEpoch = observedEpoch,
                        lastValidatedRedriveEpoch = selected.lastValidatedRedriveEpoch,
                        boundaryMatches = selected.pendingValidatedRedriveEpoch <=
                            selected.lastValidatedRedriveEpoch &&
                            NtkForwardAdjacentValidatedRecoveryPolicy.observedBoundaryMatches(
                                observedPath,
                                predecessorPath,
                                targetPath,
                            ),
                        structureCommitted = false,
                    )
                ) {
                    // The edge can precede both target claim creation and terminal observation.
                    // Consume it here, keep the same current revision, and let the Activity's
                    // compare-current watchdog schedule the next bounded launch turn.
                    selected.discoveryLaunchAttempts.set(0)
                    selected.lastValidatedRedriveEpoch = observedEpoch
                    selected.lastValidatedRedriveAtMs = SystemClock.elapsedRealtime()
                    selected.pendingValidatedRedriveEpoch = 0L
                    lastObservedForwardAdjacentValidatedNetworkPath = ""
                    consumedValidatedEpoch = observedEpoch
                    false
                } else {
                    // Preserve only immutable target identity after the ordinary launch budget is
                    // exhausted. The live revision and its queued callbacks are still retired
                    // below; a later real validated-network epoch must allocate a new revision
                    // before it can re-arm this target, so an old callback cannot ABA-join.
                    forwardAdjacentValidatedRecoveryTombstones[predecessorPath] =
                        ForwardAdjacentValidatedRecoveryTombstone(
                            target = selected.target,
                            predecessorEpisodePath = selected.predecessorEpisodePath,
                            targetEpisodePath = selected.targetEpisodePath,
                            authority = selected.authority,
                            retiredRevision = selected.revision,
                            lastValidatedRedriveEpoch = selected.lastValidatedRedriveEpoch,
                            pendingValidatedRedriveEpoch =
                                selected.pendingValidatedRedriveEpoch,
                        )
                    // Path-global cleanup must precede claim removal while the claim lock still
                    // excludes a same-path JOIN. Otherwise a new activation can reinstall these
                    // entries after unlock and the retiring revision can erase the new state.
                    forwardAdjacentCompletionTargetHistory.remove(targetPath, predecessorPath)
                    adjacentStrictPredecessorPaths.remove(targetPath, predecessorPath)
                    completionAdjacentEpisodeResolutionPaths.remove(predecessorPath)
                    initialTailAdjacentPreappendTargetPaths.remove(targetPath)
                    ReaderImageCache.releaseAdjacentNtkForegroundViewerPath(
                        targetPath,
                        "manifest_watchdog_exhausted",
                    )
                    forwardAdjacentCompletionTargetClaims.remove(predecessorPath)
                    // Keep claim removal and revision-wide pending removal under one lock. A
                    // same-path JOIN may reuse the claim revision; installing between two lock
                    // turns otherwise leaves an orphan pending value after retirement.
                    forwardAdjacentExactManifestAppendGate.removePendingRevision(
                        targetPath,
                        selected.revision,
                    )
                    true
                }
            } else {
                false
            }
        }
        if (consumedValidatedEpoch > 0L) {
            Log.d(
                TAG,
                "append_adjacent_exact_manifest_validated_edge_consumed_at_terminal " +
                    "predecessor=$predecessorPath,target=$targetPath," +
                    "revision=$retiredRevision,epoch=$consumedValidatedEpoch",
            )
            return false
        }
        if (!removed) return false
        val anchor = synchronized(pagesLock) {
            pages.indexOfLast { page ->
                page.transitionTitle == null &&
                    NtkStripDigests.normalizeEpisodePath(page.manga.ntkEpisodePath.orEmpty())
                        .equals(predecessorPath, ignoreCase = true)
            }
        }.takeIf { it >= 0 } ?: currentViewportAnchor.get().coerceAtLeast(0)
        Log.w(
            TAG,
            "append_adjacent_exact_manifest_watchdog_retired predecessor=$predecessorPath," +
                "target=$targetPath,revision=$retiredRevision,anchor=$anchor",
        )
        scheduleDeferredAdjacentPrepare(
            anchor,
            ReaderSurfaceView.DIRECTION_NEXT,
            0L,
            silentMissing = false,
        )
        return true
    }

    fun reserveForwardAdjacentExactManifestDiscoveryLaunch(
        rawPredecessorPath: String,
        rawTargetPath: String,
        maximumLaunches: Int,
    ): ForwardAdjacentExactManifestLaunchReservation? {
        if (maximumLaunches <= 0 || cancelled.get()) return null
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(rawPredecessorPath)
        val targetPath = NtkStripDigests.normalizeEpisodePath(rawTargetPath)
        if (predecessorPath.isEmpty() || targetPath.isEmpty()) return null
        return synchronized(forwardAdjacentCompletionTargetClaimLock) {
            val selected = forwardAdjacentCompletionTargetClaims[predecessorPath]
                ?: return@synchronized null
            if (selected.structureCommitted ||
                !selected.targetEpisodePath.equals(targetPath, ignoreCase = true) ||
                selected.discoveryLaunchAttempts.get() >= maximumLaunches
            ) return@synchronized null
            val token = Any()
            if (!selected.discoveryLaunchReservation.compareAndSet(null, token)) {
                return@synchronized null
            }
            ForwardAdjacentExactManifestLaunchReservation(
                predecessorPath,
                targetPath,
                selected.revision,
                token,
            )
        }
    }

    fun commitForwardAdjacentExactManifestDiscoveryLaunch(
        reservation: ForwardAdjacentExactManifestLaunchReservation,
        admittedOrJoined: Boolean,
    ): Boolean = synchronized(forwardAdjacentCompletionTargetClaimLock) {
        val selected = forwardAdjacentCompletionTargetClaims[reservation.predecessorPath]
            ?: return@synchronized false
        if (selected.structureCommitted || selected.revision != reservation.claimRevision ||
            !selected.targetEpisodePath.equals(reservation.targetPath, ignoreCase = true) ||
            !selected.discoveryLaunchReservation.compareAndSet(reservation.token, null)
        ) return@synchronized false
        if (admittedOrJoined) selected.discoveryLaunchAttempts.incrementAndGet()
        true
    }

    fun isForwardAdjacentExactManifestClaimCurrent(
        rawPredecessorPath: String,
        rawTargetPath: String,
    ): Boolean {
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(rawPredecessorPath)
        val targetPath = NtkStripDigests.normalizeEpisodePath(rawTargetPath)
        if (predecessorPath.isEmpty() || targetPath.isEmpty() || cancelled.get()) return false
        return synchronized(forwardAdjacentCompletionTargetClaimLock) {
            val selected = forwardAdjacentCompletionTargetClaims[predecessorPath]
            selected != null &&
                !selected.structureCommitted &&
                selected.targetEpisodePath.equals(targetPath, ignoreCase = true)
        }
    }

    /**
     * Authorizes a replacement discovery after the initial adjacent runway has already committed
     * structure. The pre-append manifest claim deliberately becomes false at that point, so body
     * recovery needs this narrower exact predecessor/target proof instead of reusing its gate.
     */
    fun isAdjacentStrictReplacementDiscoveryCurrent(
        rawPredecessorPath: String,
        rawTargetPath: String,
    ): Boolean {
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(rawPredecessorPath)
        val targetPath = NtkStripDigests.normalizeEpisodePath(rawTargetPath)
        if (predecessorPath.isEmpty() || targetPath.isEmpty() || cancelled.get()) return false
        return synchronized(adjacentStrictSourceClaimLock) {
            adjacentStrictRecoveryStates[targetPath]?.let { state ->
                state.awaitingReplacement && !state.exhausted &&
                    !state.retirementInProgress &&
                    NtkStripDigests.normalizeEpisodePath(state.predecessorEpisodePath)
                        .equals(predecessorPath, ignoreCase = true)
            } == true
        }
    }

    private fun nextUnloadedAdjacentEpisode(
        source: Manga,
        currentTitle: Title,
        episodes: List<Manga>,
        direction: Int
    ): Manga? {
        var checked = 0
        val wfwf = isWfwfSource(source, source.title ?: currentTitle)
        for (candidate in adjacentEpisodeCandidates(source, episodes, direction)) {
            if (checked >= ADJACENT_EXISTING_SKIP_LIMIT) break
            candidate.title = currentTitle
            candidate.titleId = currentTitle.id
            candidate.mode = source.mode
            if (episodes.isNotEmpty()) candidate.setEps(episodes)
            val loaded = if (direction < 0) hasEpisodeFast(candidate) else hasEpisode(candidate)
            if (!loaded) return candidate
            // One prepared WFWF neighbour is enough. Searching beyond an already-loaded direct
            // neighbour turns the newest episode into a chain of doomed synthetic network probes.
            if (wfwf && WfwfAdjacentEpisodePolicy.isImmediateNumericCandidate(
                    source.id,
                    candidate.id,
                    direction,
                )
            ) {
                return null
            }
            checked++
        }
        return null
    }

    private fun hasLoadedImmediateWfwfAdjacentEpisode(
        source: Manga,
        currentTitle: Title,
        episodes: List<Manga>,
        direction: Int,
    ): Boolean {
        if (!isWfwfSource(source, source.title ?: currentTitle)) return false
        val candidate = adjacentEpisodeCandidates(source, episodes, direction).firstOrNull {
            WfwfAdjacentEpisodePolicy.isImmediateNumericCandidate(source.id, it.id, direction)
        } ?: return false
        candidate.title = currentTitle
        candidate.titleId = currentTitle.id
        candidate.mode = source.mode
        if (episodes.isNotEmpty()) candidate.setEps(episodes)
        return if (direction < 0) hasEpisodeFast(candidate) else hasEpisode(candidate)
    }

    private fun adjacentEpisodeCandidates(source: Manga, episodes: List<Manga>, direction: Int): List<Manga> {
        val candidates = ArrayList<Manga>()
        val matcher = ViewerEpisodeResolver.EpisodeMatcher { first, second ->
            looseSameEpisodeForAppend(first, second)
        }
        fun addCandidate(candidate: Manga?) {
            if (candidate == null) return
            if (!isValidAdjacentEpisodeCandidate(source, candidate)) return
            if (isWfwfSource(candidate, candidate.title ?: source.title ?: title) &&
                !WfwfAdjacentEpisodePolicy.isDirectionallyConsistent(
                    source.id,
                    candidate.id,
                    direction,
                )
            ) {
                return
            }
            // WFWF exposes "first episode" as a navigation shortcut at the top of a newest-first
            // list. It is not the chronological successor of the latest episode. Treating it as
            // one replaces a correctly opened recent episode with episode 1 at the forward tail.
            if (direction > 0 &&
                isWfwfSource(candidate, candidate.title ?: source.title ?: title) &&
                WfwfAdjacentEpisodePolicy.isFirstEpisodeShortcut(candidate.id, candidate.name)
            ) {
                return
            }
            if (looseSameEpisodeForAppend(source, candidate)) return
            if (candidates.any { looseSameEpisodeForAppend(it, candidate) }) return
            candidates.add(candidate)
        }
        val wfwf = isWfwfSource(source, source.title ?: title)
        val trustedAuthority = ntkTrustedProvidedAdjacentCandidate(source, direction)
        if (wfwf && trustedAuthority != null &&
            (WfwfAdjacentEpisodePolicy.isImmediateNumericCandidate(
                source.id,
                trustedAuthority.id,
                direction,
            ) || WfwfAdjacentEpisodePolicy.isImmediateVisibleCandidate(
                Manga.visibleEpisodeNumberKey(source),
                Manga.visibleEpisodeNumberKey(trustedAuthority),
                direction,
            ))
        ) {
            addCandidate(trustedAuthority)
        }
        if (wfwf) {
            WfwfAdjacentEpisodePolicy.syntheticCandidateIds(source.id, direction, 1)
                .firstOrNull()
                ?.let { candidateId ->
                    val candidate = Manga(candidateId, "", source.date ?: "", source.baseMode)
                    candidate.mode = source.mode
                    candidate.title = source.title ?: title
                    candidate.titleId = source.titleId
                    addCandidate(candidate)
                }
        }
        // Override legacy list order only when two independent authorities agree. If one is
        // absent or they conflict, preserve the long-standing nextEp()/prevEp() behavior and use
        // the individual authorities only as later recovery candidates.
        val visibleAuthority = ntkVisibleNumberAdjacentCandidate(source, episodes, direction)
        val canonicalAuthority = ntkNumericPathAdjacentCandidate(source, episodes, direction)
        val consensusAuthority = NtkAdjacentAuthorityConsensusPolicy.agreedCandidate(
            visibleAuthority,
            canonicalAuthority,
            ::looseSameEpisodeForAppend,
        )
        addCandidate(consensusAuthority)
        addCandidate(trustedAuthority)
        addCandidate(visibleAuthority)
        addCandidate(canonicalAuthority)
        val sourceIndex = looseEpisodeIndexForAppend(episodes, source)
        if (sourceIndex >= 0) {
            var index = if (direction < 0) sourceIndex + 1 else sourceIndex - 1
            while (index >= 0 && index < episodes.size && candidates.size < ADJACENT_EXISTING_SKIP_LIMIT) {
                addCandidate(episodes[index])
                index += if (direction < 0) 1 else -1
            }
        }
        val resolved = if (direction < 0) {
            ViewerEpisodeResolver.previousCandidateFromList(source, episodes, null, source.title ?: title, matcher)
        } else {
            ViewerEpisodeResolver.nextCandidateFromList(source, episodes, null, source.title ?: title, matcher)
        }
        addCandidate(resolved)
        if (wfwf) {
            for (candidateId in WfwfAdjacentEpisodePolicy.syntheticCandidateIds(
                sourceEpisodeId = source.id,
                direction = direction,
                limit = ADJACENT_EXISTING_SKIP_LIMIT,
            )) {
                val candidate = Manga(candidateId, "", source.date ?: "", source.baseMode)
                candidate.mode = source.mode
                candidate.title = source.title ?: title
                candidate.titleId = source.titleId
                addCandidate(candidate)
            }
        }
        if (NtkAdjacentEpisodeAuthorityPolicy.maySynthesizeNumericCandidate(
                episodes.size,
                source.isOnline
            )
        ) {
            for (candidate in ntkSyntheticNumericAdjacentCandidates(source, direction)) {
                addCandidate(candidate)
            }
        }
        return candidates
    }

    private fun ntkTrustedProvidedAdjacentCandidate(source: Manga, direction: Int): Manga? {
        // nextEp()/prevEp() already encode the server episode-list direction. Database ids are
        // opaque record keys and legitimately decrease between chronological episodes. Numeric
        // NTK viewer paths are different: for one work they are a second, explicit direction
        // authority. Never let a reversed list make forward continuation select the previous path.
        val candidate = if (direction < 0) source.prevEp() else source.nextEp()
        if (candidate == null) return null
        if (!NtkAdjacentEpisodeAuthorityPolicy.isTrustedCandidateDirectionallyConsistent(
                source.ntkEpisodePath,
                candidate.ntkEpisodePath,
                direction,
                Manga.visibleEpisodeNumberKey(source),
                Manga.visibleEpisodeNumberKey(candidate),
            )
        ) {
            Log.d(
                TAG,
                "append_adjacent_trusted_candidate_reject_direction direction=$direction " +
                    "source=${source.ntkEpisodePath} target=${candidate.ntkEpisodePath}",
            )
            return null
        }
        return candidate
    }

    private fun shouldSkipLoadedNtkAdjacentCandidate(source: Manga, candidate: Manga, direction: Int): Boolean {
        if (ntkNumericEpisodePathParts(source.ntkEpisodePath) == null) return false
        if (ntkNumericEpisodePathParts(candidate.ntkEpisodePath) == null) return false
        val provided = if (direction < 0) source.prevEp() else source.nextEp()
        if (provided != null && looseSameEpisodeForAppend(provided, candidate)) return false
        val sourceNumber = Manga.visibleEpisodeNumberKey(source).toDoubleOrNull() ?: return false
        val candidateNumber = Manga.visibleEpisodeNumberKey(candidate).toDoubleOrNull() ?: return true
        val expected = sourceNumber + if (direction > 0) 1.0 else -1.0
        return kotlin.math.abs(candidateNumber - expected) > 0.0001
    }

    private fun ntkVisibleNumberAdjacentCandidate(source: Manga, episodes: List<Manga>, direction: Int): Manga? {
        val sourceParts = ntkNumericEpisodePathParts(source.ntkEpisodePath) ?: return null
        val sourceNumber = Manga.visibleEpisodeNumberKey(source).toDoubleOrNull() ?: return null
        val expectedNumber = sourceNumber + if (direction > 0) 1.0 else -1.0
        val sameSeries = episodes.filter { candidate ->
            val parts = ntkNumericEpisodePathParts(candidate.ntkEpisodePath) ?: return@filter false
            parts.first.equals(sourceParts.first, ignoreCase = true) && parts.second == sourceParts.second
        }
        val best = sameSeries.firstOrNull { candidate ->
            val candidateNumber = Manga.visibleEpisodeNumberKey(candidate).toDoubleOrNull()
            candidateNumber != null && kotlin.math.abs(candidateNumber - expectedNumber) <= 0.0001
        }
        if (best != null) {
            Log.d(
                TAG,
                "append_adjacent_visible_number_candidate direction=$direction source=${source.ntkEpisodePath} " +
                    "sourceNo=${Manga.visibleEpisodeNumberKey(source)} " +
                    "targetNo=${Manga.visibleEpisodeNumberKey(best)} target=${best.ntkEpisodePath}"
            )
        }
        return best
    }

    private fun ntkNumericPathAdjacentCandidate(source: Manga, episodes: List<Manga>, direction: Int): Manga? {
        val sourceParts = ntkNumericEpisodePathParts(source.ntkEpisodePath) ?: return null
        var best: Manga? = null
        var bestDelta = Long.MAX_VALUE
        for (candidate in episodes) {
            val parts = ntkNumericEpisodePathParts(candidate.ntkEpisodePath) ?: continue
            if (!parts.first.equals(sourceParts.first, ignoreCase = true)) continue
            if (parts.second != sourceParts.second) continue
            val delta = parts.third - sourceParts.third
            val matchesDirection = if (direction > 0) delta > 0 else delta < 0
            if (!matchesDirection) continue
            val distance = kotlin.math.abs(delta)
            if (distance < bestDelta) {
                best = candidate
                bestDelta = distance
            }
        }
        if (best != null) {
            Log.d(
                TAG,
                "append_adjacent_numeric_candidate direction=$direction source=${source.ntkEpisodePath} " +
                    "target=${best.ntkEpisodePath} distance=$bestDelta"
            )
        } else {
            Log.d(
                TAG,
                "append_adjacent_numeric_candidate_missing direction=$direction source=${source.ntkEpisodePath} " +
                    "episodes=${episodes.size}"
            )
        }
        return best
    }

    private fun ntkSyntheticNumericAdjacentCandidates(source: Manga, direction: Int): List<Manga> {
        val sourceParts = ntkNumericEpisodePathParts(source.ntkEpisodePath) ?: return emptyList()
        val result = ArrayList<Manga>()
        for (distance in 1L..6L) {
            val targetEpisodeId = sourceParts.third + if (direction > 0) distance else -distance
            ntkSyntheticNumericAdjacentCandidate(source, sourceParts, direction, targetEpisodeId)?.let {
                result.add(it)
            }
        }
        return result
    }

    private fun ntkSyntheticNumericAdjacentCandidate(
        source: Manga,
        sourceParts: Triple<String, Long, Long>,
        direction: Int,
        targetEpisodeId: Long
    ): Manga? {
        if (targetEpisodeId <= 0L || targetEpisodeId > Int.MAX_VALUE) return null
        val baseMode = if (sourceParts.first.equals("webtoon", ignoreCase = true)) {
            MTitle.base_webtoon
        } else {
            MTitle.base_comic
        }
        val targetPath = "/${sourceParts.first}/${sourceParts.second}/$targetEpisodeId"
        val sourceNumber = Manga.visibleEpisodeNumberKey(source).toDoubleOrNull()
        val syntheticName = if (sourceNumber != null) {
            val expected = sourceNumber + if (direction > 0) 1.0 else -1.0
            val formatted = if (kotlin.math.abs(expected - expected.toLong()) <= 0.0001) {
                expected.toLong().toString()
            } else {
                String.format(Locale.US, "%.1f", expected).trimEnd('0').trimEnd('.')
            }
            "${formatted}화"
        } else {
            Manga.cleanViewerEpisodeName(source.name ?: "")
        }
        val candidate = Manga(
            targetEpisodeId.toInt(),
            syntheticName,
            source.date ?: "",
            baseMode
        )
        candidate.setTitle(source.title ?: title)
        candidate.setTitleId(sourceParts.second.toInt())
        candidate.setMode(source.mode)
        candidate.setNtkEpisodePath(targetPath)
        candidate.setNtkImageWorkId(sourceParts.second.toString())
        candidate.setNtkImageEpisodeId(targetEpisodeId.toString())
        candidate.setNtkImageCount(source.ntkImageCount)
        Log.d(
            TAG,
            "append_adjacent_numeric_synthetic direction=$direction source=${source.ntkEpisodePath} " +
                "target=$targetPath"
        )
        return candidate
    }

    private fun ntkNumericEpisodePathParts(path: String?): Triple<String, Long, Long>? {
        val value = path?.trim().orEmpty()
        if (value.isEmpty()) return null
        numericEpisodePathPartsCache[value]?.let { return it }
        val segment: String
        val titleStart: Int
        when {
            value.length > 8 && value.regionMatches(1, "manhwa/", 0, 7, ignoreCase = true) -> {
                segment = "manhwa"
                titleStart = 8
            }

            value.length > 9 && value.regionMatches(1, "webtoon/", 0, 8, ignoreCase = true) -> {
                segment = "webtoon"
                titleStart = 9
            }

            else -> return null
        }
        var titleEnd = titleStart
        while (titleEnd < value.length && value[titleEnd] in '0'..'9') titleEnd++
        if (titleEnd == titleStart || titleEnd - titleStart > 12 ||
            titleEnd >= value.length || value[titleEnd] != '/'
        ) return null
        val episodeStart = titleEnd + 1
        var episodeEnd = episodeStart
        while (episodeEnd < value.length && value[episodeEnd] in '0'..'9') episodeEnd++
        if (episodeEnd == episodeStart || episodeEnd - episodeStart > 12) return null
        if (episodeEnd < value.length && value[episodeEnd] != '/' &&
            value[episodeEnd] != '?' && value[episodeEnd] != '#'
        ) return null
        val titleId = asciiDecimalLong(value, titleStart, titleEnd) ?: return null
        val episodeId = asciiDecimalLong(value, episodeStart, episodeEnd) ?: return null
        return Triple(segment, titleId, episodeId).also { parsed ->
            numericEpisodePathPartsCache.putIfAbsent(value, parsed)
        }
    }

    private fun asciiDecimalLong(value: String, start: Int, end: Int): Long? {
        if (start < 0 || end <= start || end > value.length || end - start > 12) return null
        var result = 0L
        for (index in start until end) {
            val digit = value[index] - '0'
            if (digit !in 0..9) return null
            result = result * 10L + digit
        }
        return result
    }

    private fun isAsciiDecimalId(value: String, maxDigits: Int = 12): Boolean {
        if (value.isEmpty() || value.length > maxDigits) return false
        for (character in value) if (character !in '0'..'9') return false
        return true
    }

    private fun isValidAdjacentEpisodeCandidate(source: Manga, candidate: Manga): Boolean {
        val ntk = isNtkSource(source, source.title) || isNtkSource(candidate, candidate.title)
        if (!ntk) return true
        val path = candidate.ntkEpisodePath?.trim().orEmpty()
        val candidatePath = if (path.isNotEmpty()) path else candidate.url?.trim().orEmpty()
        val valid = candidatePath.isNotEmpty() && isNtkViewerEpisodePath(candidatePath)
        if (!valid) {
            Log.d(
                TAG,
                "append_adjacent_skip_non_episode path=$candidatePath id=${candidate.id} name=${candidate.name}"
            )
        }
        return valid
    }

    private fun isNtkViewerEpisodePath(path: String): Boolean {
        val parts = path
            .substringBefore('#')
            .substringBefore('?')
            .trim()
            .trimEnd('/')
            .split('/')
            .filter { it.isNotEmpty() }
        if (parts.size < 3) return false
        return (parts[0] == "manhwa" || parts[0] == "webtoon") &&
            parts[1].isNotBlank() &&
            parts[2].isNotBlank()
    }

    private fun isNtkSyntheticEpisodePath(path: String?): Boolean {
        val match = NTK_VIEWER_EPISODE_PATH.matchEntire(path?.trim().orEmpty()) ?: return false
        return (match.groupValues[1].equals("webtoon", ignoreCase = true) &&
            !match.groupValues[2].matches(Regex("\\d+"))) ||
            !match.groupValues[3].matches(Regex("\\d+"))
    }

    private fun looseEpisodeIndexForAppend(episodes: List<Manga>, source: Manga): Int {
        for (index in episodes.indices) {
            if (looseSameEpisodeForAppend(source, episodes[index])) return index
        }
        return -1
    }

    private fun looseSameEpisodeForAppend(first: Manga?, second: Manga?): Boolean {
        if (Manga.sameEpisodeIdentity(first, second)) return true
        if (first == null || second == null || first.baseMode != second.baseMode) return false
        if (!isNtkSource(first, first.title) && !isNtkSource(second, second.title)) return false
        val firstPath = first.ntkEpisodePath?.trim().orEmpty()
        val secondPath = second.ntkEpisodePath?.trim().orEmpty()
        if (firstPath.isNotEmpty() && secondPath.isNotEmpty()) return firstPath == secondPath
        val firstNumber = Manga.visibleEpisodeNumberKey(first)
        val secondNumber = Manga.visibleEpisodeNumberKey(second)
        return firstNumber.isNotEmpty()
            && secondNumber.isNotEmpty()
            && firstNumber == secondNumber
            && first.id > 0
            && first.id == second.id
    }

    private fun containsEpisodeLocked(target: Manga): Boolean {
        return pages.any { sameEpisode(it.manga, target) }
    }

    private fun containsEpisodeFastLocked(target: Manga): Boolean {
        return pages.any { Manga.sameEpisodeIdentity(it.manga, target) }
    }

    private fun containsEpisodeForAppendLocked(target: Manga): Boolean {
        val key = episodeAppendKey(target)
        if (key.isNotEmpty())
            return pages.any { episodeAppendKey(it.manga) == key }
        return containsEpisodeLocked(target)
    }

    private fun appendableNewEpisodeRefsLocked(refs: List<PageRef>): List<PageRef> {
        if (refs.isEmpty()) return emptyList()
        val accepted = ArrayList<PageRef>(refs.size)
        val acceptedMangas = ArrayList<Manga>()
        val existingKeys = HashSet<String>()
        for (page in pages) {
            val key = episodeAppendKey(page.manga)
            if (key.isNotEmpty()) existingKeys.add(key)
        }
        val acceptedKeys = HashSet<String>()
        for (ref in refs) {
            val key = episodeAppendKey(ref.manga)
            val existing = if (key.isNotEmpty()) existingKeys.contains(key) else containsEpisodeLocked(ref.manga)
            val alreadyAccepted = if (key.isNotEmpty()) acceptedKeys.contains(key) else acceptedMangas.any { sameEpisode(it, ref.manga) }
            if (!existing && !alreadyAccepted) {
                if (key.isNotEmpty()) acceptedKeys.add(key) else acceptedMangas.add(ref.manga)
            }
            if (!existing || alreadyAccepted) accepted.add(ref)
        }
        return accepted
    }

    private fun shiftPageStateForPrepend(delta: Int) {
        if (delta <= 0) return
        strictForwardSuffixLaunchShapeValid.set(false)
        synchronized(indexedStateLock) {
            indexedStateGeneration.incrementAndGet()
            shiftConcurrentMap(decodedWidths, delta)
            shiftConcurrentMap(desiredWidths, delta)
            shiftConcurrentMap(pendingDeliveryWidths, delta)
            shiftConcurrentMap(sourceWidths, delta)
            shiftConcurrentMap(achievableWidths, delta)
            shiftConcurrentMap(transientGeneratedRetries, delta)
            shiftConcurrentMap(transientGeneratedVisibleRetries, delta)
            shiftConcurrentMap(bytePrefetchCompletedAtMs, delta)
            shiftConcurrentMap(earlyPreparedBitmaps, delta)
            shiftConcurrentMap(deliveredDrawableProofWidths, delta)
            shiftConcurrentMap(authoritativeTileInstallRetryCounts, delta)
            shiftConcurrentMap(authoritativeTileInstallRetryAtMs, delta)
            shiftConcurrentMap(strictInlineTileRedecodeAttempts, delta)
            shiftConcurrentSet(failedPages, delta)
            shiftConcurrentSet(authoritativeTileInstallRetryPosted, delta)
            shiftConcurrentSet(strictInlineTileRedecodePosted, delta)
            shiftConcurrentSet(terminalBitmapRedrivePosted, delta)
            shiftConcurrentSet(strictInlineProofDeliveryIntents, delta)
            shiftConcurrentSet(listenerDrawableDeliveries, delta)
            shiftConcurrentSet(drawableReadyHistory, delta)
            shiftConcurrentSet(preRenderedInitialDeliveries, delta)
            shiftConcurrentSet(preRenderedInitialContinuousDeliveries, delta)
            shiftConcurrentSet(preRenderedCommittedDeliveries, delta)
            shiftConcurrentSet(protectedNumericSourceReadyIndexes, delta)
            shiftConcurrentSet(postInitialContinuousDeferredRequests, delta)
            shiftPreparedMapForPrepend(initialPreparedBacklog, delta)
            indexedStateGeneration.incrementAndGet()
        }
        inFlightWidths.clear()
        loading.clear()
        loadingPages.clear()
        loadingStartedAtMs.clear()
        urgentLoading.clear()
        urgentLoadingPages.clear()
        bytePrefetching.clear()
        fullEpisodeSourcePrefetching.clear()
        immediateGeneratedFullSourcePrefetchPosted.set(false)
        preAnchorFallbackRetries.clear()
        initialAdjacentDecodeRetries.clear()
        visibleGeneratedByteHedges.clear()
        visibleGeneratedDecodeHedges.clear()
        initialAnchorAssetDecodeListenerKeys.clear()
        initialGeneratedAssetDecodeListeners.clear()
        pendingAdjacentEarlyAppendTargets.clear()
        visibleGeneratedCachedDecodeRetries.clear()
        initialGeneratedCachedDecodeInFlight.clear()
        initialGeneratedDirectDecodeInFlight.clear()
        initialInteractiveRunwayByteFetches.clear()
        initialAnchorDeliveryPosted.set(false)
        idleFullWidthUpgradeScheduled.clear()
        synchronized(deliveredBitmaps) {
            val oldEntries = deliveredBitmaps.entries.toList()
            deliveredBitmaps.clear()
            for (entry in oldEntries) deliveredBitmaps[entry.key + delta] = entry.value
            val oldTileEntries = deliveredTiles.entries.toList()
            deliveredTiles.clear()
            for (entry in oldTileEntries) deliveredTiles[entry.key + delta] = entry.value
            val oldOwned = deliveredOwned.toList()
            deliveredOwned.clear()
            for (index in oldOwned) deliveredOwned.add(index + delta)
            retainedFirstPage += delta
            retainedLastPage += delta
            retainedAnchorPage += delta
        }
        physicalDeliveryFirstPage += delta
        if (physicalDeliveryLastPage >= 0) physicalDeliveryLastPage += delta
        synchronized(windowLock) {
            if (lastWindowAnchor >= 0) lastWindowAnchor += delta
            windowGeneration.incrementAndGet()
        }
    }

    private fun <T> shiftConcurrentMap(map: ConcurrentHashMap<Int, T>, delta: Int) {
        if (map.isEmpty()) return
        val entries = map.entries.toList()
        map.clear()
        for (entry in entries) map[entry.key + delta] = entry.value
    }

    private fun shiftConcurrentSet(set: MutableSet<Int>, delta: Int) {
        if (set.isEmpty()) return
        val entries = set.toList()
        set.clear()
        for (index in entries) set.add(index + delta)
    }

    private fun applyHintedNtkGeneratedImage(index: Int, page: PageRef, reason: String): Boolean {
        if (strictExactColdRolling) return false
        if (!isNtkSource(page.manga, title)) return false
        val originalImage = page.image ?: return false
        if (!isNtkGeneratedImageUrl(originalImage)) return false
        val replacement = ReaderImageCache.hintedNtkGeneratedImageUrl(originalImage) ?: return false
        if (shouldKeepCurrentGeneratedImageOverHint(page, originalImage, replacement)) return false
        var changed = false
        synchronized(pagesLock) {
            if (index !in pages.indices || pages[index] !== page) return false
            for (ref in pages) {
                if (
                    ref.transitionTitle == null &&
                    ref.sourceIndex == page.sourceIndex &&
                    ref.image == originalImage &&
                    Manga.sameEpisodeIdentity(ref.manga, page.manga)
                ) {
                    ref.image = replacement
                    changed = true
                }
            }
        }
        if (!changed) return false
        failedPages.remove(index)
        decodedWidths.remove(index)
        desiredWidths.remove(index)
        pendingDeliveryWidths.remove(index)
        sourceWidths.remove(index)
        achievableWidths.remove(index)
        inFlightWidths.remove(index)
        if (loadingPages[index] === page) {
            loadingPages.remove(index, page)
            loading.remove(index)
        }
        if (urgentLoadingPages[index] === page) {
            urgentLoadingPages.remove(index, page)
            urgentLoading.remove(index)
        }
        Log.d(
            TAG,
            "reader_ntk_generated_hint_apply index=$index,source=${page.sourceIndex}," +
                "reason=$reason,from=${originalImage.substringAfterLast('/')},to=${replacement.substringAfterLast('/')}"
        )
        ViewerWarmupManager.logMetric("reader_ntk_generated_hint_apply", index.toLong())
        return true
    }

    private fun shouldKeepCurrentGeneratedImageOverHint(
        page: PageRef,
        originalImage: String,
        replacement: String
    ): Boolean {
        val originalExt = ntkImageExtension(originalImage)
        val replacementExt = ntkImageExtension(replacement)
        if (originalExt.isEmpty() || replacementExt.isEmpty()) return false
        if (
            page.manga.ntkEpisodePath.orEmpty().startsWith("/webtoon/", ignoreCase = true) &&
            replacementExt == "jpg" &&
            originalExt != "jpg" &&
            page.sourceIndex in 0 until NTK_GENERATED_INITIAL_RECOVERY_PAGES
        ) {
            val hasVerifiedOriginal = ReaderImageCache
                .earlyNtkGeneratedSuccessImageUrls(
                    page.manga.ntkEpisodePath,
                    SystemClock.elapsedRealtime() - 30000L
                )
                .any { it == originalImage }
            if (!hasVerifiedOriginal) return false
        }
        if (originalExt == "jpg" || replacementExt != "jpg") return false
        if (ReaderImageCache.isKnownNtkGeneratedNotFound(page.manga, originalImage)) return false
        Log.d(
            TAG,
            "reader_ntk_generated_hint_preserve_current source=${page.sourceIndex}," +
                "from=${originalImage.substringAfterLast('/')},to=${replacement.substringAfterLast('/')}"
        )
        return true
    }

    private fun ntkImageExtension(image: String): String {
        return Regex("(?i)\\.(jpg|jpeg|png|webp)(?:[?#].*)?$")
            .find(image)
            ?.groupValues
            ?.getOrNull(1)
            ?.lowercase(Locale.ROOT)
            .orEmpty()
    }

    private fun shiftPreparedMapForPrepend(
        map: ConcurrentHashMap<Int, PreparedDelivery>,
        delta: Int
    ) {
        if (map.isEmpty()) return
        val entries = map.entries.toList()
        map.clear()
        for (entry in entries) map[entry.key + delta] = entry.value
    }

    private fun isActiveGeneratedTouchOrQuiet(): Boolean {
        if (!firstBitmapLogged.get() &&
            ntkFirstBitmapAtMs.get() <= 0L &&
            !firstDrawableDelivered.get()
        ) return false
        if (!isImmediateNtkGeneratedUx()) return false
        return viewportBusy.get() ||
            ntkInitialInteractiveSettleRemainingMs() > 0L ||
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L ||
            readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS) > 0L
    }

    private fun initialInteractiveRunwayLastIndex(count: Int = synchronized(pagesLock) { pages.size }): Int {
        if (count <= 0) return -1
        val start = currentStartPage().coerceIn(0, count - 1)
        val viewportAnchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?.coerceIn(0, count - 1)
            ?: start
        return minOf(
            count - 1,
            maxOf(
                start + NTK_INITIAL_INTERACTIVE_RUNWAY_PAGES - 1,
                viewportAnchor + NTK_INITIAL_INTERACTIVE_RUNWAY_PAGES - 1
            )
        )
    }

    private fun activeGeneratedProofLastIndex(count: Int): Int {
        if (count <= 0) return -1
        val start = currentStartPage().coerceIn(0, count - 1)
        val viewportAnchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?.coerceIn(0, count - 1)
            ?: start
        if (!viewportBusy.get() &&
            (ntkInitialInteractiveSettleRemainingMs() > 0L || isWithinFirstBitmapInputGrace()) &&
            viewportAnchor <= start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
        ) {
            return minOf(count - 1, start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1)
        }
        if (isKnownFullGeneratedEpisodeInstalled()) {
            if (!firstBitmapLogged.get()) {
                return start
            }
            val earlyInitialWindow =
                ntkInitialInteractiveSettleRemainingMs() > 0L &&
                    viewportAnchor <= start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
            if (earlyInitialWindow) {
                return minOf(
                    count - 1,
                    maxOf(start, viewportAnchor) + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
                )
            }
            if (isActiveGeneratedTouchOrQuiet() || viewportBusy.get()) {
                return minOf(count - 1, viewportAnchor + activeGeneratedProofAheadPages())
            }
        }
        val proofLast = viewportAnchor + activeGeneratedProofAheadPages()
        val fullLast = start + NTK_INITIAL_INTERACTIVE_FULL_PAGES - 1
        return minOf(count - 1, initialInteractiveRunwayLastIndex(count), maxOf(proofLast, fullLast))
    }

    private fun interactiveProofAheadPages(): Int {
        if (isImmediateNtkGeneratedUx()) {
            if (isActiveGeneratedTouchOrQuiet() || viewportBusy.get()) {
                return activeGeneratedProofAheadPages()
            }
            return max(0, NTK_INITIAL_INTERACTIVE_RUNWAY_PAGES - 1)
        }
        return if (isWithinFirstBitmapInputGrace()) 0 else NTK_INTERACTIVE_PROOF_AHEAD_PAGES
    }

    private fun initialContinuousViewportAheadPages(): Int {
        val baseAhead = maxOf(
            NTK_INITIAL_INTERACTIVE_VIEWPORT_AHEAD_PAGES,
            NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        )
        if (
            isImmediateNtkGeneratedUx() &&
            firstBitmapLogged.get() &&
            isActiveGeneratedTouchOrQuiet() &&
            isKnownFullGeneratedEpisodeInstalled()
        ) {
            return NTK_ACTIVE_GENERATED_VIEWPORT_AHEAD_PAGES
        }
        if (
            isImmediateNtkGeneratedUx() &&
            isNtkWebtoonEpisodePath(manga.ntkEpisodePath)
        ) {
            return maxOf(baseAhead, NTK_INITIAL_WEBTOON_FAST_SCROLL_AHEAD_PAGES)
        }
        return baseAhead
    }

    private fun startActiveGeneratedProofPreview(index: Int, page: PageRef, image: String, reason: String): Boolean {
        val now = SystemClock.elapsedRealtime()
        val key = "$index|$image"
        val last = activeGeneratedProofPreviewAttempts[key] ?: 0L
        if (now - last < NTK_ACTIVE_PROOF_PREVIEW_RETRY_SUPPRESS_MS) {
            logNtkPagePerf(
                index,
                "visible_generated_active_proof_preview_suppressed",
                "reason=$reason,elapsedMs=${now - last}"
            )
            return false
        }
        activeGeneratedProofPreviewAttempts[key] = now
        return ReaderImageCache.startVisibleInitialGeneratedPreviewFetch(
            appContext,
            page.manga,
            image,
            imageCancellation,
            index
        )
    }

    private fun activeRollingRunwayByteAheadPages(anchor: Int): Int {
        return NTK_ACTIVE_ROLLING_RUNWAY_BYTE_AHEAD_PAGES
    }

    private fun routeActiveGeneratedRequestToProofOrBytes(
        index: Int,
        page: PageRef,
        busy: Boolean,
        anchor: Boolean,
        generation: Int
    ): Boolean {
        if (isImmediateGeneratedFullSurfacePrimeRequest(index, page, busy, generation)) return false
        val activeGeneratedRequest = isActiveGeneratedTouchOrQuiet() ||
            (isImmediateNtkGeneratedUx() && busy)
        if (!activeGeneratedRequest) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        if (hasDeliveredOrPendingDrawable(index)) return false
        if (anchor && index != currentStartPage()) {
            scheduleBlockedGeneratedProofDecode(index, page, "active_anchor")
            return true
        }
        if (index == currentStartPage()) return false
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return false
        val runwayLast = initialInteractiveRunwayLastIndex(count)
        if (index > runwayLast) {
            logNtkPagePerf(
                index,
                "generated_decode_skip_active_far_request",
                "busy=$busy,anchor=$anchor,generation=$generation,runwayLast=$runwayLast"
            )
            return true
        }
        val proofLast = activeGeneratedProofLastIndex(count)
        if (index <= proofLast) {
            val scheduled = scheduleVisibleGeneratedCachedDecode(
                index,
                page,
                "active_generated_route_proof",
                SystemClock.elapsedRealtime(),
                forceRequeue = true,
                proofDrawable = true
            )
            if (scheduled) {
                logNtkPagePerf(
                    index,
                    "generated_decode_route_active_proof",
                    "busy=$busy,anchor=$anchor,generation=$generation,proofLast=$proofLast,runwayLast=$runwayLast"
                )
            } else {
                startInitialInteractiveRunwayByteFetch(index, page, "active_generated_proof_miss")
            }
            return true
        }
        logNtkPagePerf(
            index,
            "generated_decode_skip_active_runway_bytes",
            "busy=$busy,anchor=$anchor,generation=$generation,proofLast=$proofLast,runwayLast=$runwayLast"
        )
        return true
    }

    private fun isImmediateGeneratedFullSurfacePrimeRequest(
        index: Int,
        page: PageRef,
        busy: Boolean,
        generation: Int
    ): Boolean {
        if (!busy || generation != FOREGROUND_PRIME_WARM_GENERATION) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        return immediateFullSurfacePrimeKeys.contains(immediateFullSurfacePrimeKey(page))
    }

    private fun immediateFullSurfacePrimeKey(page: PageRef): String {
        return "${page.manga.ntkEpisodePath.orEmpty()}|${page.sourceIndex}"
    }

    private fun immediateFullSurfacePrimeTargetWidth(): Int {
        val view = max(1, viewerWidth)
        val readable = max(384, view * NTK_PROOF_WIDTH_PERMILLE / 1000)
        return minOf(view, minOf(readable, NTK_PROOF_MAX_WIDTH))
    }

    private fun scheduleBlockedGeneratedProofDecode(
        index: Int,
        page: PageRef,
        reason: String,
        byteStartedAt: Long = SystemClock.elapsedRealtime()
    ): Boolean {
        if (strictExactColdRolling) return false
        if (cancelled.get() || pageRef(index) != page) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        if (hasDeliveredOrPendingDrawable(index)) return false
        val blockedReason = "blocked_$reason"
        val scheduled = scheduleVisibleGeneratedCachedDecode(
            index,
            page,
            blockedReason,
            byteStartedAt,
            forceRequeue = true,
            proofDrawable = true,
            allowOutsideProofWindow = true
        )
        if (scheduled) {
            logNtkPagePerf(index, "blocked_generated_proof_decode", "reason=$reason,scheduled=true")
            return true
        }
        val byteStarted = startInitialInteractiveRunwayByteFetch(
            index,
            page,
            "${blockedReason}_proof",
            forceProofDrawable = true,
            allowOutsideProofWindow = true
        )
        logNtkPagePerf(
            index,
            "blocked_generated_proof_decode",
            "reason=$reason,scheduled=false,byteStarted=$byteStarted"
        )
        return byteStarted
    }

    private fun isStrictExactColdPageDemanded(index: Int): Boolean {
        if (!strictExactColdRolling || index < 0) return !strictExactColdRolling
        val page = pageRef(index) ?: return false
        if (!isStrictExactLaunchPage(page)) return false
        val admission = strictRollingAdmission.get() ?: return false
        return admission.admitsSource(page.sourceIndex)
    }

    private fun isStrictExactLaunchPage(page: PageRef): Boolean {
        if (!strictExactColdRolling) return false
        val launchSeal = strictExactLaunchSeal ?: return false
        return launchSeal.matchesEpisodePath(page.manga.ntkEpisodePath) &&
            launchSeal.matchesSource(page.sourceIndex, page.image)
    }

    private fun isStrictExactIdentityValid(index: Int, page: PageRef): Boolean {
        val launchSeal = strictExactLaunchSeal ?: return false
        // startStrictExactColdSession already claimed and authority-checked this immutable seal.
        // Re-entering the global spool registry from every one of the parallel decode workers
        // serialized 100+ otherwise independent images on its path lock. The live claimed port,
        // immutable page object and source identity are the complete in-session lifetime fence.
        return launchSeal.matchesEpisodePath(page.manga.ntkEpisodePath) &&
            launchSeal.matchesSource(page.sourceIndex, page.image) &&
            strictExactSourceTransport.get() != null &&
            synchronized(pagesLock) { pages.getOrNull(index) === page }
    }

    /**
     * Returns whether [sourceIndex] is still needed to fill the initial viewport, or null while an
     * earlier source's exact bounds have not arrived. This is geometry, not a guessed page count:
     * a tall webtoon p0 can publish alone, while landscape/short pages admit exactly as many
     * ordered sources as the physical viewport needs.
     */
    private fun strictInitialViewportRequiresSource(sourceIndex: Int): Boolean? {
        val anchorPage = pageRef(currentStartPage()) ?: return null
        val anchorSource = anchorPage.sourceIndex
        if (anchorSource < 0 || sourceIndex < anchorSource) return null
        if (sourceIndex == anchorSource) return true
        val requiredHeight = max(1, viewerHeight).toLong()
        val targetWidth = max(1, viewerWidth).toLong()
        var coveredHeight = 0L
        for (source in anchorSource until sourceIndex) {
            val metadata = strictExactBodyDescriptors[source]?.metadata ?: return null
            if (metadata.sourceWidth <= 0 || metadata.sourceHeight <= 0) return null
            val drawHeight = targetWidth * metadata.sourceHeight.toLong() /
                metadata.sourceWidth.toLong()
            coveredHeight = (coveredHeight + max(1L, drawHeight)).coerceAtMost(Long.MAX_VALUE)
            if (coveredHeight >= requiredHeight) return false
        }
        return true
    }

    /** Only the finite pages a real pre-content swipe can reach may decode before first latch. */
    private fun strictInitialScrollRunwayContainsSource(sourceIndex: Int): Boolean {
        val anchorSource = pageRef(currentStartPage())?.sourceIndex ?: return false
        if (anchorSource < 0 || sourceIndex < anchorSource) return false
        return sourceIndex < anchorSource +
            NtkHostGpuEmulatorCurrentWebtoonLanePolicy.INITIAL_SCROLL_RUNWAY_BODIES
    }

    /**
     * Returns true only for the immutable current-launch PageRef that Surface reported as the
     * first missing body in a real forward gesture. Once its authoritative drawable is installed,
     * consume the grant so a later reverse pressure rehydrate cannot inherit stale urgency.
     */
    private fun isCurrentLaunchBlockedForwardPage(
        index: Int,
        page: PageRef,
    ): Boolean {
        if (latestCurrentLaunchBlockedForwardPage.get() !== page) return false
        val currentIndex = currentPageIndex(page, index)
        if (currentIndex < 0 || pageRef(currentIndex) !== page || !isStrictExactLaunchPage(page)) {
            latestCurrentLaunchBlockedForwardPage.compareAndSet(page, null)
            return false
        }
        if (listener.isPageAuthoritativeDrawableCurrentlyInstalled(currentIndex)) {
            latestCurrentLaunchBlockedForwardPage.compareAndSet(page, null)
            return false
        }
        return true
    }

    /**
     * Keeps the finite launch runway urgent and also admits the one immutable page identity that
     * the Surface has proved is blocking a real forward gesture. The latter is essential after
     * the launch runway: treating that page as ordinary mirror work makes it wait for physical
     * motion to stop, while the clamped Surface keeps reporting motion because those exact pixels
     * are not yet drawable. Far-offscreen publications remain parked on the ordinary lane.
     */
    private fun shouldPrioritizeStrictExactMirrorPublication(
        index: Int,
        page: PageRef,
    ): Boolean =
        strictInitialScrollRunwayContainsSource(page.sourceIndex) ||
            isCurrentLaunchBlockedForwardPage(index, page) ||
            latestPhysicalForwardIntentPage.get() === page ||
            isStrictAdjacentPageInReportedPhysicalIntent(index, page)

    /**
     * Re-evaluates urgency on the single mirror-publication lane. A page can be decoded just
     * before a HOME restore or viewport rebase makes it physically visible; capturing only the
     * decode-time priority leaves its compositor mirror behind the 500 ms input-idle fence. At an
     * exact episode tail that creates a closed loop: the Surface waits for a clean tail frame while
     * repeated forward input keeps the visible page's ordinary mirror deferred forever.
     */
    private fun isStrictExactMirrorPublicationRequiredNow(
        index: Int,
        page: PageRef,
    ): Boolean {
        if (cancelled.get()) return false
        if (isCurrentLaunchBlockedForwardPage(index, page) ||
            latestPhysicalForwardIntentPage.get() === page ||
            latestStrictExactPhysicalForwardWarmPage.get() === page ||
            isStrictAdjacentPageInReportedPhysicalIntent(index, page)
        ) return true
        val currentIndex = currentPageIndex(page, index)
        if (currentIndex < 0 || pageRef(currentIndex) !== page) return false
        // Once Session has handed this exact token to the Surface, the mirror is no longer
        // speculative offscreen work. Surface's drawable ledger cannot observe the asynchronous
        // native flag and would otherwise call the page complete while the direct presenter is
        // still waiting for its HardwareBuffer. Continuous real input then keeps the ordinary
        // 500 ms mirror-idle fence closed forever. Promote only this identity-bound pending or
        // delivered page; decoded bodies that have not entered UI ownership remain deferrable.
        return (pendingDeliveryWidths[currentIndex] ?: 0) > 0 ||
            hasDeliveredBitmap(currentIndex)
    }

    /**
     * Waits for the preceding canonical source rather than semaphore-arrival order. Network EOF
     * is intentionally out of order; letting whichever body finished first own the serial gate
     * decoded p4 before p1 and left the physical scroll cap at the first gap.
     */
    private fun awaitStrictInitialDecodeRunwayTurn(sourceIndex: Int): Boolean {
        val anchorSource = pageRef(currentStartPage())?.sourceIndex ?: return false
        if (anchorSource < 0 || sourceIndex <= anchorSource) return false
        strictExactInitialDecodeRunwayNextSource.compareAndSet(-1, anchorSource + 1)
        while (!cancelled.get()) {
            val next = strictExactInitialDecodeRunwayNextSource.get()
            if (next == sourceIndex) return true
            if (next > sourceIndex) return false
            Thread.sleep(8L)
        }
        return false
    }

    /**
     * Keeps at most the next two canonical followers eligible for private native preparation.
     * Network EOF is out of order, so a plain two-permit semaphore can otherwise admit p3 before
     * p2 and leave the second drawable blocked behind pixels that cannot yet be exposed.
     */
    private fun awaitStrictInitialDecodePreparationWindow(sourceIndex: Int): Boolean {
        val anchorSource = pageRef(currentStartPage())?.sourceIndex ?: return false
        if (anchorSource < 0 || sourceIndex <= anchorSource) return false
        strictExactInitialDecodeRunwayNextSource.compareAndSet(-1, anchorSource + 1)
        while (!cancelled.get()) {
            val next = strictExactInitialDecodeRunwayNextSource.get()
            if (sourceIndex < next) return false
            if (sourceIndex <= next + 1) return true
            Thread.sleep(8L)
        }
        return false
    }

    private fun requestStrictExactSourcePage(
        index: Int,
        anchor: Boolean,
        generation: Int,
        overlap: Boolean = false,
        compositorForwardWarmIntent: Boolean = false,
        physicalForwardWarmIntent: Boolean = false,
    ) {
        if (cancelled.get()) return
        val page = pageRef(index) ?: return
        val admission = strictRollingAdmission.get() ?: return
        if (!admission.admitsSource(page.sourceIndex) || !isStrictExactIdentityValid(index, page)) {
            Log.d(
                TAG,
                "reader_ntk_strict_cold_request_drop page=$index,source=${page.sourceIndex}," +
                    "generation=$generation,epoch=${admission.epoch}," +
                    "demand=${admission.allowedFirstSource}-${admission.allowedLastSource}"
            )
            return
        }
        val descriptor = strictExactBodyDescriptors[page.sourceIndex]
        if (descriptor == null) {
            if (shouldLogRateLimitedDiagnostic(
                    "strict_request_body_absent|$index",
                    1_000L,
                )
            ) {
                Log.d(
                    TAG,
                    "reader_ntk_strict_request_body_absent page=$index," +
                        "source=${page.sourceIndex},anchor=${currentViewportAnchor.get()}," +
                        "descriptorCount=${strictExactBodyDescriptors.size}," +
                        "publishedFallback=${strictAdjacentPublishedBody(page) != null}",
                )
            }
            if (loading.add(index)) {
                loadingPages[index] = page
                main.post {
                    if (!cancelled.get() && isStrictExactIdentityValid(index, page)) {
                        listener.onPageLoading(index)
                    }
                }
            }
            return
        }
        loading.remove(index)
        loadingPages.remove(index, page)
        if (physicalForwardWarmIntent) {
            latestStrictExactPhysicalForwardWarmPage.set(page)
        }
        fun isPhysicalForwardWarmNow(): Boolean =
            latestStrictExactPhysicalForwardWarmPage.get() === page
        val exactCurrentLaunchBlocker = isCurrentLaunchBlockedForwardPage(index, page)
        val exactCompositorForwardWarm = compositorForwardWarmIntent &&
            isLatestExactLaunchCompositorForwardWarm(index, page)
        val hostExactDirectWifiCurrentEpisode = hostGpuEmulatorRuntime &&
            strictExactLaunchSeal?.normalizedEpisodePath
                ?.let(::isNtkManhwaOrWebtoonEpisodePath) == true &&
            NtkSourceSpoolRegistry.isCurrentDirectWifiRendererProfile(
                strictExactLaunchSeal?.normalizedEpisodePath,
                strictExactForegroundViewerGenerationAtCreation,
            ) &&
            isStrictExactCurrentForegroundEpisode()
        val launchAnchorSource = pageRef(currentStartPage())?.sourceIndex ?: -1
        val nextInitialRunwaySource = strictExactInitialDecodeRunwayNextSource.get()
        val initialHostExactScrollRunwayDecode = hostExactDirectWifiCurrentEpisode &&
            strictInitialScrollRunwayContainsSource(page.sourceIndex) &&
            // The ordered runway is a one-time launch preparation path. Once its counter has
            // advanced beyond a source, a later pixel eviction must use the ordinary visible
            // rehydrate path; sending it back through the one-shot gate rejects it forever.
            (page.sourceIndex == launchAnchorSource ||
                nextInitialRunwaySource < 0 ||
                page.sourceIndex >= nextInitialRunwaySource)
        if (isPhysicalForwardWarmNow() &&
            hostExactPoolPressureRetiredPages.contains(index)
        ) {
            // Pressure retirement publishes its marker before the asynchronous Surface clear.
            // A two-page physical warm nomination may reclaim that exact page early, but only
            // after the old drawable has actually left Surface ownership. This is deliberately
            // narrower than the full retained source/body window: one immutable immediate
            // follower becomes the single claimant, so the old p12 decode/evict cycle cannot
            // return while a real reader no longer reaches each boundary before its pixels.
            if (listener.isPageAuthoritativeDrawableInstalled(index)) return
            if (!hostExactPoolPressureRetiredPages.remove(index)) return
        }
        if (!NtkStrictRollingDecodeRequestPolicy.allows(
                rollingPixelResidency = strictExactRollingPixelResidency.get(),
                completionSpanPageCount =
                    page.manifestPageCount - strictForwardSourceFloor,
                insideRollingPixelWindow = isInsideStrictExactRollingPixelWindow(index),
                initialScrollRunway = initialHostExactScrollRunwayDecode,
                viewportBlocker = exactCurrentLaunchBlocker,
                compositorForwardWarm = exactCompositorForwardWarm,
                physicalForwardWarm = isPhysicalForwardWarmNow(),
            )
        ) {
            if (shouldLogRateLimitedDiagnostic("strict_request_outside_rolling_pixels|$index", 1_000L)) {
                Log.d(
                    TAG,
                    "reader_ntk_strict_request_outside_rolling_pixels page=$index," +
                        "source=${page.sourceIndex},anchor=${currentViewportAnchor.get()}",
                )
            }
            return
        }
        if (strictExactRollingPixelResidency.get() &&
            strictExactAuthoritativeHandoffPages.contains(index) &&
            !isInsideStrictExactRollingPixelWindow(index) &&
            !exactCurrentLaunchBlocker &&
            !exactCompositorForwardWarm &&
            !isPhysicalForwardWarmNow()
        ) {
            if (shouldLogRateLimitedDiagnostic("strict_request_outside_pixels|$index", 1_000L)) {
                Log.d(
                    TAG,
                    "reader_ntk_strict_request_outside_pixels page=$index," +
                        "source=${page.sourceIndex},anchor=${currentViewportAnchor.get()}",
                )
            }
            return
        }
        var requiresRollingReinstall = false
        if (strictExactAuthoritativeHandoffPages.contains(index)) {
            if (listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)) {
                if (shouldLogRateLimitedDiagnostic(
                        "strict_request_installed|$index",
                        1_000L,
                    )
                ) {
                    Log.d(
                        TAG,
                        "reader_ntk_strict_request_installed page=$index," +
                            "source=${page.sourceIndex}",
                    )
                }
                return
            }
            // The Surface is the current-state authority. A historic handoff bit must not make a
            // recycled or superseded page permanently undecodable during a long forward fling.
            strictExactAuthoritativeHandoffPages.remove(index)
            requiresRollingReinstall = true
        }
        if (!requiresRollingReinstall && !exactCurrentLaunchBlocker &&
            hasDeliveredOrPendingDrawable(index)
        ) {
            if (shouldLogRateLimitedDiagnostic("strict_request_delivered|$index", 1_000L)) {
                Log.d(
                    TAG,
                    "reader_ntk_strict_request_delivered page=$index," +
                        "source=${page.sourceIndex}",
                )
            }
            return
        }
        if (!exactCurrentLaunchBlocker &&
            !isPhysicalForwardWarmNow() &&
            shouldSkipDecodeOutsideProtectedNumericWindow(
                index,
                page,
                "strict_exact_request"
            )
        ) {
            if (shouldLogRateLimitedDiagnostic("strict_request_protected_skip|$index", 1_000L)) {
                Log.d(
                    TAG,
                    "reader_ntk_strict_request_protected_skip page=$index," +
                        "source=${page.sourceIndex},anchor=${currentViewportAnchor.get()}," +
                        "window=${protectedNumericBitmapWindow()}",
                )
            }
            return
        }
        val splitSourceSingleFlight = shouldSplitPreparedBitmapForPage(
            autoCut,
            page.allowAutoSplit,
            descriptor.metadata.sourceWidth,
            descriptor.metadata.sourceHeight
        )
        val decodeClaimed = if (splitSourceSingleFlight) {
            strictExactSplitSourceDecodeInFlight.add(strictExactSplitSourceDecodeKey(page))
        } else {
            strictExactDecodeInFlight.add(index)
        }
        if (!decodeClaimed) {
            if (shouldLogRateLimitedDiagnostic("strict_request_claimed|$index", 1_000L)) {
                Log.d(
                    TAG,
                    "reader_ntk_strict_request_claimed page=$index," +
                        "source=${page.sourceIndex}",
                )
            }
            if (isPhysicalForwardWarmNow()) {
                promoteQueuedStrictExactPhysicalForwardWarm(index, page)
            }
            promoteQueuedStrictExactViewportBlocker(index, page)
            return
        }
        strictExactDecodeAdmissions.incrementAndGet()
        val admittedEpoch = admission.epoch
        val targetWidth = max(1, viewerWidth)
        val effectiveDecodeAnchor = NtkStrictLaunchDecodeAnchorPolicy.resolve(
            initialRunwayDecode = initialHostExactScrollRunwayDecode,
            sourceIndex = page.sourceIndex,
            launchSourceIndex = launchAnchorSource,
            requestedAnchor = anchor,
        )
        val initialHostExactScrollRunwayFollowerDecode =
            initialHostExactScrollRunwayDecode &&
                page.sourceIndex > launchAnchorSource
        val oversizedDirectWifiCurrentEpisode = hostExactDirectWifiCurrentEpisode &&
            !ReaderExactDecodeStoragePolicy.useSharedFullPageBitmap(
                forceOriginal = true,
                sourceWidth = descriptor.metadata.sourceWidth,
                sourceHeight = descriptor.metadata.sourceHeight,
            )
        val waitForOversizedDirectWifiAnchor = !effectiveDecodeAnchor &&
            oversizedDirectWifiCurrentEpisode
        val parallelOversizedDirectWifiAnchor = effectiveDecodeAnchor &&
            oversizedDirectWifiCurrentEpisode
        val executor = when {
            exactCurrentLaunchBlocker -> strictExactViewportBlockerDecode
            effectiveDecodeAnchor -> anchorDecode
            initialHostExactScrollRunwayFollowerDecode -> strictExactInitialRunwayDecode
            overlap -> strictExactOverlapDecode
            strictExactRollingPixelResidency.get() -> strictExactRollingDecode
            else -> strictExactBulkDecode
        }
        if (initialHostExactScrollRunwayDecode) {
            Log.d(
                TAG,
                "reader_ntk_initial_runway_decode_admitted page=$index," +
                    "source=${page.sourceIndex},requestedAnchor=$anchor," +
                    "effectiveAnchor=$effectiveDecodeAnchor,overlap=$overlap,activeInput=" +
                    physicalScrollEverStarted.get(),
            )
        }
        lateinit var decodeTask: Runnable
        decodeTask = Runnable execute@ {
                strictExactRollingQueuedDecodes.remove(index, decodeTask)
                val promotedViewportBlocker =
                    strictExactRollingPromotedDecodes.remove(index)
                val promotedPhysicalForwardWarm =
                    strictExactRollingForwardWarmPromotedDecodes.remove(index)
                var decodeClaimActive = true
                var motionDeferred = false
                var terminalStage = "task-entered"
                // Source EOF/hash work and JPEG decode share the six host cores. Stay background
                // while any canonical body is missing, then restore normal priority per task so
                // the finite decode tail does not remain artificially throttled after the network
                // wave is complete.
                runCatching {
                    Process.setThreadPriority(
                        if (promotedViewportBlocker ||
                            exactCurrentLaunchBlocker ||
                            parallelOversizedDirectWifiAnchor ||
                            initialHostExactScrollRunwayDecode
                        ) {
                            // Resume can request only the one visible oversized source, so the
                            // descriptor count never reaches the full manifest page count. Do not
                            // demote that sole post-EOF anchor partition to background while the
                            // user is looking at a blank scene; helper partitions already run at
                            // default priority and adjacent work is completion-gated.
                            Process.THREAD_PRIORITY_DEFAULT
                        } else if (!hostGpuEmulatorRuntime &&
                            !strictExactRollingPixelResidency.get() &&
                            strictExactBodyDescriptors.size >=
                            (strictExactLaunchSeal?.pageCount ?: Int.MAX_VALUE)
                        ) {
                            Process.THREAD_PRIORITY_DEFAULT
                        } else {
                            Process.THREAD_PRIORITY_BACKGROUND
                        }
                    )
                }
                // The overlap executor stays deliberately bounded while HTTP bodies are
                // arriving. Once the manifest is fully resident, queued (not yet executing)
                // overlap work must join the full bulk stage; otherwise a 40-page FIFO tail
                // would remain pinned to the smaller pool and dominate all-images-ready time.
                if (overlap && strictExactBulkDecodeReleased.get() &&
                    !initialHostExactScrollRunwayDecode
                ) {
                    // Bulk release is a throughput transition, not permission to demote pixels
                    // already demanded by a physical gesture. Re-enqueuing p3/p4 behind the
                    // complete-scene FIFO left their verified bodies idle while p69/p8 decoded
                    // first and held the real viewport at p2.
                    releaseStrictExactDecodeClaim(index, page, splitSourceSingleFlight)
                    decodeClaimActive = false
                    requestStrictExactSourcePage(
                        index,
                        anchor = anchor,
                        generation = generation,
                        overlap = false,
                        compositorForwardWarmIntent = exactCompositorForwardWarm,
                        physicalForwardWarmIntent = isPhysicalForwardWarmNow(),
                    )
                    return@execute
                }
                var lease: NtkStrictBodyLease? = null
                var activeScrollDecodeGate: Semaphore? = null
                var initialViewportDecodeGateAcquired = false
                var initialRunwayNativeDecodePermitAcquired = false
                try {
                    terminalStage = "anchor-wait"
                    while (waitForOversizedDirectWifiAnchor &&
                        !cancelled.get() &&
                        !strictExactInitialAnchorPixelsInstalled.await(50L, TimeUnit.MILLISECONDS)
                    ) {
                        // Keep verified bodies resident without making their 100+ MiB pixel work
                        // compete with the only immediately visible decode.
                    }
                    if (cancelled.get()) return@execute
                    terminalStage = "admission-recheck"
                    val currentAdmission = strictRollingAdmission.get() ?: return@execute
                    if (!currentAdmission.admitsSource(page.sourceIndex) ||
                        !isStrictExactIdentityValid(index, page)
                    ) return@execute
                    // The request-level window check and this worker-level recheck must use the
                    // same Surface-owned liveness exception. A page can be admitted while it is
                    // still just outside the numeric window and become the exact physical prefix
                    // blocker before its worker starts. Rejecting it here leaves verified bytes
                    // resident but makes the forward fence impossible to clear.
                    if (!exactCurrentLaunchBlocker &&
                        !promotedViewportBlocker &&
                        !isCurrentLaunchBlockedForwardPage(index, page) &&
                        !isPhysicalForwardWarmNow() &&
                        shouldSkipDecodeOutsideProtectedNumericWindow(
                            index,
                            page,
                            "strict_exact_worker"
                        )
                    ) return@execute
                    if (hostExactDirectWifiCurrentEpisode && !viewerActivated.get() &&
                        (!effectiveDecodeAnchor || initialHostExactScrollRunwayFollowerDecode)
                    ) {
                        while (!cancelled.get() && !viewerActivated.get()) {
                            if (initialHostExactScrollRunwayFollowerDecode) {
                                // Bodies p1..p4 may finish before viewer activation. Let their
                                // dedicated waiters reach the canonical gate below; only its winner
                                // may enter native decode, so out-of-order EOF cannot create a
                                // four-wide gfxstream upload storm behind the visible anchor.
                                break
                            }
                            when (strictInitialViewportRequiresSource(page.sourceIndex)) {
                                null -> Thread.sleep(16L)
                                false -> {
                                    if (physicalScrollEverStarted.get() &&
                                        strictInitialScrollRunwayContainsSource(page.sourceIndex)
                                    ) {
                                        // Non-follower compatibility path: retain its original
                                        // p0 ownership fence. Current launch followers take the
                                        // private predecode path above.
                                        if (!strictExactInitialAnchorPixelsInstalled.await(
                                                50L,
                                                TimeUnit.MILLISECONDS,
                                            )
                                        ) continue
                                        if (!awaitStrictInitialDecodeRunwayTurn(
                                                page.sourceIndex,
                                            )
                                        ) {
                                            // A pre-rendered anchor can be rediscovered after the
                                            // follower counter has already advanced to p1. That
                                            // duplicate p0 is stale, not a reason to poll forever
                                            // while occupying the bounded overlap decoder.
                                            return@execute
                                        }
                                        initialHostExactViewportDecodeGate.acquire()
                                        initialViewportDecodeGateAcquired = true
                                        break
                                    }
                                    strictExactInitialPhysicalFramePresented.await(
                                        50L,
                                        TimeUnit.MILLISECONDS,
                                    )
                                }
                                true -> {
                                    if (!strictExactInitialAnchorPixelsInstalled.await(
                                            50L,
                                            TimeUnit.MILLISECONDS,
                                        )
                                    ) continue
                                    if (!awaitStrictInitialDecodeRunwayTurn(page.sourceIndex)) {
                                        // The ordered source has already crossed this slot (or the
                                        // slot is the launch anchor). Drop the duplicate worker so
                                        // the next canonical follower can enter the small pool.
                                        return@execute
                                    }
                                    initialHostExactViewportDecodeGate.acquire()
                                    initialViewportDecodeGateAcquired = true
                                    break
                                }
                            }
                        }
                        if (cancelled.get() || !isStrictExactIdentityValid(index, page)) {
                            return@execute
                        }
                    }
                    val exactViewportBlockerBeforeInitialRunwayTurn =
                        exactCurrentLaunchBlocker ||
                            promotedViewportBlocker ||
                            isCurrentLaunchBlockedForwardPage(index, page)
                    if (!exactViewportBlockerBeforeInitialRunwayTurn &&
                        !isPhysicalForwardWarmNow() &&
                        hostExactDirectWifiCurrentEpisode &&
                        strictInitialScrollRunwayContainsSource(page.sourceIndex) &&
                        !initialHostExactScrollRunwayFollowerDecode &&
                        !effectiveDecodeAnchor &&
                        !initialViewportDecodeGateAcquired
                    ) {
                        // Use one canonical p1->p5 state machine regardless of whether physical
                        // DOWN races just before or after p1/p2 EOF. Mixing unordered idle decode
                        // with ordered active decode left the counter at p1 after those sources
                        // had already completed, permanently parking p3/p4. This gate is one-shot:
                        // once Surface reports an evicted page as the exact drawable-prefix
                        // blocker, it must use ordinary rehydrate ownership rather than being
                        // rejected because the initial counter has already advanced past it. The
                        // same applies to the one identity-bound physical-forward warm nominee:
                        // it is a pressure rehydrate, not a second pass through the launch runway.
                        if (!strictExactInitialAnchorPixelsInstalled.await(
                                50L,
                                TimeUnit.MILLISECONDS,
                            )
                        ) return@execute
                        if (!awaitStrictInitialDecodeRunwayTurn(page.sourceIndex)) return@execute
                        initialHostExactViewportDecodeGate.acquire()
                        initialViewportDecodeGateAcquired = true
                    }
                    if (initialHostExactScrollRunwayFollowerDecode &&
                        !initialViewportDecodeGateAcquired
                    ) {
                        // Bodies p1..p4 keep downloading beside p0, but p0 is the only page that
                        // can remove the initial blank. Let its native decode finish first; the
                        // previous three-way overlap stretched it from ~0.25 s to ~0.85 s. Then
                        // prepare pN and pN+1 together without letting out-of-order EOF spend the
                        // second native lane on pN+2. Public ownership remains canonical below.
                        while (!cancelled.get() &&
                            !strictExactInitialAnchorPixelsInstalled.await(
                                50L,
                                TimeUnit.MILLISECONDS,
                            )
                        ) {
                            // Keep the verified encoded body resident without native allocation.
                        }
                        Log.d(
                            TAG,
                            "reader_ntk_initial_runway_gate page=$index," +
                                "source=${page.sourceIndex},stage=anchor-installed",
                        )
                        if (cancelled.get() || !isStrictExactIdentityValid(index, page)) {
                            return@execute
                        }
                        if (!awaitStrictInitialDecodePreparationWindow(page.sourceIndex)) {
                            Log.d(
                                TAG,
                                "reader_ntk_initial_runway_gate page=$index," +
                                    "source=${page.sourceIndex},stage=preparation-rejected",
                            )
                            return@execute
                        }
                        Log.d(
                            TAG,
                            "reader_ntk_initial_runway_gate page=$index," +
                                "source=${page.sourceIndex},stage=preparation-admitted",
                        )
                        initialHostExactRunwayNativeDecodePermits.acquire()
                        initialRunwayNativeDecodePermitAcquired = true
                        Log.d(
                            TAG,
                            "reader_ntk_initial_runway_gate page=$index," +
                                "source=${page.sourceIndex},stage=native-permit",
                        )
                        if (cancelled.get() || !isStrictExactIdentityValid(index, page)) {
                            return@execute
                        }
                    }
                    while (!cancelled.get() &&
                        !isCurrentLaunchBlockedForwardPage(index, page) &&
                        !isPhysicalForwardWarmNow() &&
                        NtkStrictActiveScrollDecodePolicy
                            .shouldHoldHostOffscreenBeforeFirstInteraction(
                                hostSurfaceRuntime = hostGpuEmulatorRuntime,
                                currentForegroundEpisode =
                                    isStrictExactCurrentForegroundEpisode(),
                                anchor = effectiveDecodeAnchor,
                                initialScrollRunway = initialHostExactScrollRunwayDecode,
                                initialViewportRequired =
                                    strictInitialViewportRequiresSource(page.sourceIndex) == true,
                                physicalScrollEverStarted = physicalScrollEverStarted.get(),
                                firstPhysicalFrameAtMs =
                                    strictExactInitialPhysicalFramePresentedAtMs.get(),
                                firstAnchorPixelsAtMs =
                                    strictExactInitialAnchorPixelsInstalledAtMs.get(),
                                nowMs = SystemClock.elapsedRealtime(),
                            )
                    ) {
                        Thread.sleep(16L)
                    }
                    if (cancelled.get() || !isStrictExactIdentityValid(index, page)) {
                        return@execute
                    }
                    val deferHostOffscreenUntilQuiet =
                        !initialHostExactScrollRunwayFollowerDecode &&
                            !initialViewportDecodeGateAcquired && !exactCompositorForwardWarm &&
                            !promotedPhysicalForwardWarm && !isPhysicalForwardWarmNow() &&
                            NtkStrictActiveScrollDecodePolicy
                                .shouldDeferHostOffscreenUntilQuiet(
                                    hostSurfaceRuntime = hostGpuEmulatorRuntime,
                                    physicalScrollEverStarted = physicalScrollEverStarted.get(),
                                    currentForegroundEpisode =
                                        isStrictExactCurrentForegroundEpisode(),
                                    anchor = effectiveDecodeAnchor,
                                )
                    if (deferHostOffscreenUntilQuiet) {
                        terminalStage = "input-quiet-wait"
                        // Protect real pointer input and its short quiet edge completely. A fling
                        // can remain busy for many seconds (and some Surface backends retain the
                        // final busy bit until the next lifecycle edge), so it must not become an
                        // unbounded all-scene decode lock. After pointer quiet, drain one exact
                        // original at a time while motion remains active; genuine idle restores
                        // the fixed rolling executor's parallelism. A physical blocker bypasses
                        // both waits and gates.
                        while (!cancelled.get() &&
                            !isCurrentLaunchBlockedForwardPage(index, page) &&
                            !isPhysicalForwardWarmNow()
                        ) {
                            if (isHostExactOffscreenDecodeInputProtected()) {
                                Thread.sleep(16L)
                                continue
                            }
                            if (NtkReaderTransferPacer.isPhysicalMotionActive() ||
                                viewportBusy.get()
                            ) {
                                val decodeGate = if (
                                    NtkReaderTransferPacer.isPhysicalInputPriorityActive()
                                ) {
                                    activeVisibleDecodeGate
                                } else if (NtkReaderTransferPacer.isPhysicalMotionActive()) {
                                    passiveMotionDecodeGate
                                } else {
                                    blockedMotionDecodeGate
                                }
                                if (decodeGate.tryAcquire(
                                        16L,
                                        TimeUnit.MILLISECONDS,
                                    )
                                ) {
                                    if (isHostExactOffscreenDecodeInputProtected()) {
                                        decodeGate.release()
                                        continue
                                    }
                                    activeScrollDecodeGate = decodeGate
                                    break
                                }
                                continue
                            }
                            break
                        }
                        if (cancelled.get() || !isStrictExactIdentityValid(index, page)) {
                            return@execute
                        }
                    } else if (!initialHostExactScrollRunwayFollowerDecode &&
                        !initialViewportDecodeGateAcquired &&
                        NtkStrictActiveScrollDecodePolicy.shouldShareVisibleDecodeGate(
                            hostSurfaceRuntime = hostGpuEmulatorRuntime,
                            physicalScrollEverStarted = physicalScrollEverStarted.get(),
                            directWifi = isDirectWifiStrictAdjacentTransportActive(),
                            currentForegroundEpisode = isStrictExactCurrentForegroundEpisode(),
                            activeInput = isActiveGeneratedInputOrQuietForDelivery(),
                            anchor = effectiveDecodeAnchor,
                            manhwa = strictExactLaunchSeal?.normalizedEpisodePath
                                ?.startsWith("/manhwa/", ignoreCase = true) == true,
                        )
                    ) {
                        terminalStage = "visible-gate-wait"
                        // Background pages stay one-at-a-time after physical scrolling starts.
                        // The exact page currently holding the real drawable-prefix fence gets
                        // one independent visible lane; otherwise continuous input can keep that
                        // page behind unrelated work forever. Timed acquisition lets an already
                        // waiting worker observe the later Surface blocker signal.
                        while (!cancelled.get()) {
                            if (isCurrentLaunchBlockedForwardPage(index, page) ||
                                isPhysicalForwardWarmNow()
                            ) break
                            if (activeVisibleDecodeGate.tryAcquire(16L, TimeUnit.MILLISECONDS)) {
                                activeScrollDecodeGate = activeVisibleDecodeGate
                                break
                            }
                            // Recheck the immutable PageRef blocker without polling main state.
                        }
                        if (cancelled.get() || !isStrictExactIdentityValid(index, page)) {
                            return@execute
                        }
                    }
                    if (initialHostExactScrollRunwayFollowerDecode &&
                        !initialViewportDecodeGateAcquired
                    ) {
                        // Encoded bodies and their cheap lease preparation may overlap two-wide,
                        // but native slot allocation, decode and mirror publication must enter in
                        // canonical source order. Letting pN+1 allocate first can consume the last
                        // reusable HardwareBuffer and then wait for pN's public handoff while pN
                        // itself waits for that slot: neither side can release the other's fence.
                        terminalStage = "initial-runway-turn-wait"
                        if (!awaitStrictInitialDecodeRunwayTurn(page.sourceIndex)) return@execute
                        initialHostExactViewportDecodeGate.acquire()
                        initialViewportDecodeGateAcquired = true
                    }
                    terminalStage = "lease-open"
                    if (initialHostExactScrollRunwayFollowerDecode) {
                        Log.d(
                            TAG,
                            "reader_ntk_initial_runway_gate page=$index," +
                                "source=${page.sourceIndex},stage=lease-opening",
                        )
                    }
                    lease = descriptor.openLease()
                    val opened = checkNotNull(lease)
                    terminalStage = "lease-opened"
                    if (initialHostExactScrollRunwayFollowerDecode) {
                        Log.d(
                            TAG,
                            "reader_ntk_initial_runway_gate page=$index," +
                                "source=${page.sourceIndex},stage=lease-opened",
                        )
                    }
                    if (opened.sourceKey != descriptor.sourceKey ||
                        opened.sourceKey.pageIndex != page.sourceIndex ||
                        opened.sourceKey.manifestDigest != strictExactLaunchSeal?.manifestDigest
                    ) throw NtkSourceIdentityException("Strict rolling body lease identity changed")
                    val startedAt = SystemClock.elapsedRealtime()
                    if (initialHostExactScrollRunwayDecode) {
                        Log.d(
                            TAG,
                            "reader_ntk_initial_runway_decode_started page=$index," +
                                "source=${page.sourceIndex}",
                        )
                    }
                    val canonicalAsset = strictExactLaunchSeal
                        ?.canonicalAssets
                        ?.getOrNull(page.sourceIndex)
                        .orEmpty()
                    // The admission loop above is a queue-level fence. Recheck at the actual pool
                    // allocation and native JPEG edge as well: a new ACTION_DOWN can arrive after
                    // the loop observed idle but before this worker reaches either expensive call.
                    // The exact physical blocker and the ordered p0..p5 runway remain admissible.
                    val fenceNativeExactDecodeForPhysicalInput =
                        deferHostOffscreenUntilQuiet &&
                            !isCurrentLaunchBlockedForwardPage(index, page) &&
                            !exactCompositorForwardWarm &&
                            !isPhysicalForwardWarmNow()
                    val exactViewportBlockerAtDecode =
                        exactCurrentLaunchBlocker ||
                            promotedViewportBlocker ||
                            isCurrentLaunchBlockedForwardPage(index, page)
                    val result = if (
                        hasHostExactSealedSource(opened.file, opened.proof.encodedLength)
                    ) {
                        decodeStrictExactPageFile(
                            index,
                            page,
                            opened.file,
                            targetWidth,
                            opened.sourceWidth,
                            opened.sourceHeight,
                            canonicalAsset,
                            deferWhilePhysicalInput =
                                fenceNativeExactDecodeForPhysicalInput,
                            bypassProtectedNumericSerialization =
                                exactViewportBlockerAtDecode,
                            allowTransientHostExactPoolOvercommit =
                                exactViewportBlockerAtDecode,
                            exactLaunchCompositorForwardWarmIntent =
                                exactCompositorForwardWarm,
                        )
                    } else {
                        opened.predecodedOriginal
                            ?.takeIfReadyOrAbandon(opened.sourceWidth, opened.sourceHeight)
                            ?.let { bitmap ->
                                adoptPrivateStrictExactBitmapForPage(
                                    index,
                                    page,
                                    bitmap,
                                    opened.sourceWidth,
                                    opened.sourceHeight,
                                    canonicalAsset,
                                )
                            } ?: opened.encodedBytes?.let { bytes ->
                            decodeStrictExactPageBytes(
                                index,
                                page,
                                bytes,
                                opened.sourceWidth,
                                opened.sourceHeight,
                                canonicalAsset,
                                parallelOversizedDirectWifiAnchor,
                                deferWhilePhysicalInput =
                                    fenceNativeExactDecodeForPhysicalInput,
                                bypassProtectedNumericSerialization =
                                    exactViewportBlockerAtDecode,
                                allowTransientHostExactPoolOvercommit =
                                    exactViewportBlockerAtDecode,
                                exactLaunchCompositorForwardWarmIntent =
                                    exactCompositorForwardWarm,
                            )
                        } ?: decodeStrictExactPageFile(
                            index,
                            page,
                            opened.file,
                            targetWidth,
                            opened.sourceWidth,
                            opened.sourceHeight,
                            canonicalAsset,
                            deferWhilePhysicalInput =
                                fenceNativeExactDecodeForPhysicalInput,
                            bypassProtectedNumericSerialization =
                                exactViewportBlockerAtDecode,
                            allowTransientHostExactPoolOvercommit =
                                exactViewportBlockerAtDecode,
                            exactLaunchCompositorForwardWarmIntent =
                                exactCompositorForwardWarm,
                        )
                    }
                    terminalStage = "decoded"
                    if (initialRunwayNativeDecodePermitAcquired) {
                        initialHostExactRunwayNativeDecodePermits.release()
                        initialRunwayNativeDecodePermitAcquired = false
                    }
                    val latest = strictRollingAdmission.get()
                    if (initialHostExactScrollRunwayDecode) {
                        Log.d(
                            TAG,
                            "reader_ntk_initial_runway_decode_completed page=$index," +
                                "source=${page.sourceIndex},ms=" +
                                (SystemClock.elapsedRealtime() - startedAt),
                        )
                    }
                    if (cancelled.get() || latest == null ||
                        !latest.admitsSource(page.sourceIndex) ||
                        !isStrictExactIdentityValid(index, page)
                    ) {
                        recycleDecodeResult(result)
                        Log.d(
                            TAG,
                            "reader_ntk_strict_cold_decode_stale_drop page=$index," +
                                "source=${page.sourceIndex},fromEpoch=$admittedEpoch," +
                                "toEpoch=${latest?.epoch ?: -1L}"
                        )
                        return@execute
                    }
                    val decodedTiles = result as? PageDecodeResult.Tiles
                    val canonicalOriginal = decodedTiles != null &&
                        isCanonicalOriginalTileResult(result, page.image)
                    var handedOff = false
                    if (decodedTiles != null && canonicalOriginal) {
                        handedOff = (
                            initialHostExactScrollRunwayDecode ||
                                listener.isStrictAuthoritativeWorkerHandoffActive()
                            ) &&
                            handOffStrictExactAuthoritativeTiles(index, page, decodedTiles, result)
                        if (handedOff && index == currentStartPage()) {
                            // The anchor used to bypass the authoritative worker handoff and was
                            // delivered through the legacy tile API. That API intentionally drops
                            // original provenance, leaving an otherwise complete 112-page scene
                            // permanently one page short of the full-scene GPU handoff. The exact
                            // Surface install above already schedules the physical frame; retain
                            // the normal first-draw state transition without a second pixel bind.
                            // The native authoritative API consumed the exact pixels directly, so
                            // this branch never reaches postDecodeResult(), where ordinary paths
                            // advance firstBitmapLogged. Leaving the two state machines split keeps
                            // every later p1+ result in the pre-first private backlog even though p0
                            // is already on screen. Publish the matching preparation fact only after
                            // the Surface ACK above has succeeded.
                            markFirstPreparedBitmapDelivered(resultDrawHeightPx(result))
                            markFirstDrawableCommitted(index, "strict_authoritative_handoff")
                            postReleaseInitialFanoutIfPending(index)
                        }
                        if (!handedOff && !listener.onPageDecodedRenderReady(
                                index,
                                decodedTiles.pageWidth,
                                decodedTiles.pageHeight,
                                decodedTiles.tiles
                            )
                        ) {
                            Log.d(
                                TAG,
                                "reader_ntk_strict_cold_render_ready_rejected page=$index," +
                                    "source=${page.sourceIndex}"
                            )
                        }
                    }
                    if (!handedOff) {
                        postDecodeResult(
                            Delivery(
                                index,
                                page,
                                result,
                                startedAt,
                                targetWidth,
                                retainWhenBusy = true
                            )
                        )
                    }
                    terminalStage = if (handedOff) {
                        "authoritative-handoff"
                    } else {
                        "legacy-delivery-posted"
                    }
                    if (initialViewportDecodeGateAcquired) {
                        // Queue acceptance above is the ownership boundary. Advance only after
                        // pN has been decoded and handed off (or its ordered legacy delivery was
                        // posted), so pN+1 can neither contend for native pixels nor overtake it.
                        strictExactInitialDecodeRunwayNextSource.compareAndSet(
                            page.sourceIndex,
                            page.sourceIndex + 1,
                        )
                        initialHostExactViewportDecodeGate.release()
                        initialViewportDecodeGateAcquired = false
                    }
                } catch (failure: Exception) {
                    if (failure is NtkPhysicalMotionDecodeDeferredException) {
                        terminalStage = "motion-deferred"
                        motionDeferred = true
                        if (shouldLogRateLimitedDiagnostic(
                                "strict_decode_motion_deferred|$index",
                                1_000L,
                            )
                        ) {
                            Log.d(
                                TAG,
                                "reader_ntk_strict_decode_motion_deferred page=$index," +
                                    "source=${page.sourceIndex},touchActive=" +
                                    physicalTouchActive.get() + ",touchQuietMs=" +
                                    physicalTouchQuietRemainingMs(
                                        HOST_EXACT_OFFSCREEN_DECODE_INPUT_QUIET_MS,
                                    ) + ",transferMotion=" +
                                    NtkReaderTransferPacer.isPhysicalMotionActive() +
                                    ",transferInput=" +
                                    NtkReaderTransferPacer.isPhysicalInputPriorityActive() +
                                    ",viewportBusy=${viewportBusy.get()}",
                            )
                        }
                    } else {
                        terminalStage = "failure-${failure.javaClass.simpleName}"
                        recordIfUnexpected(failure)
                        postPageError(index, page, failure)
                    }
                } finally {
                    lease?.release?.invoke()
                    activeScrollDecodeGate?.release()
                    if (initialRunwayNativeDecodePermitAcquired) {
                        initialHostExactRunwayNativeDecodePermits.release()
                    }
                    if (initialViewportDecodeGateAcquired) {
                        // A failed or stale pN must remain the next canonical source so its retry
                        // can repair the drawable prefix. Advancing here would permanently strand
                        // that hole while allowing pN+1 to consume native memory offscreen.
                        initialHostExactViewportDecodeGate.release()
                    }
                    if (decodeClaimActive) {
                        releaseStrictExactDecodeClaim(index, page, splitSourceSingleFlight)
                    }
                    strictExactDecodeTerminals.incrementAndGet()
                    if (shouldLogRateLimitedDiagnostic(
                            "strict_decode_terminal|$index|$terminalStage",
                            1_000L,
                        )
                    ) {
                        Log.d(
                            TAG,
                            "reader_ntk_strict_decode_terminal page=$index," +
                                "source=${page.sourceIndex},stage=$terminalStage," +
                                "cancelled=${cancelled.get()},identity=" +
                                isStrictExactIdentityValid(index, page) +
                                ",generation=$generation,admittedEpoch=$admittedEpoch," +
                                "currentEpoch=${strictRollingAdmission.get()?.epoch ?: -1L}",
                        )
                    }
                    if (motionDeferred) {
                        parkStrictExactMotionDeferredPage(index, page)
                    } else {
                        latestStrictExactPhysicalForwardWarmPage.compareAndSet(page, null)
                    }
                }
            }
        if (executor === strictExactRollingDecode) {
            strictExactRollingQueuedDecodes[index] = decodeTask
        }
        try {
            executor.execute(decodeTask)
        } catch (_: RejectedExecutionException) {
            strictExactRollingQueuedDecodes.remove(index, decodeTask)
            strictExactRollingPromotedDecodes.remove(index)
            releaseStrictExactDecodeClaim(index, page, splitSourceSingleFlight)
            strictExactDecodeTerminals.incrementAndGet()
        }
    }

    /**
     * A rolling webtoon can publish p69 before p9. Once p9 becomes the exact physical prefix
     * blocker, leaving its already-verified decode behind that offscreen FIFO produces a visible
     * loading wall even though no network work remains. Transfer only the queued blocker to the
     * dedicated single-thread liveness lane. Queue removal must succeed first, so a task which
     * has already started is never duplicated and its original single-flight claim stays intact.
     */
    private fun promoteQueuedStrictExactViewportBlocker(index: Int, page: PageRef): Boolean {
        if (!isCurrentLaunchBlockedForwardPage(index, page)) return false
        val task = strictExactRollingQueuedDecodes[index] ?: return false
        if (!strictExactRollingDecode.removeQueued(task)) return false
        if (!strictExactRollingQueuedDecodes.remove(index, task)) {
            // The task cannot have started after a successful queue removal. Restore it rather
            // than silently losing the single-flight owner if an unexpected map race occurs.
            return runCatching {
                strictExactRollingDecode.execute(task)
                false
            }.getOrDefault(false)
        }
        strictExactRollingPromotedDecodes.add(index)
        return try {
            strictExactViewportBlockerDecode.execute(task)
            Log.d(
                TAG,
                "reader_ntk_strict_rolling_decode_promoted page=$index," +
                    "source=${page.sourceIndex}",
            )
            true
        } catch (_: RejectedExecutionException) {
            strictExactRollingPromotedDecodes.remove(index)
            if (!cancelled.get()) {
                strictExactRollingQueuedDecodes[index] = task
                runCatching { strictExactRollingDecode.execute(task) }
            }
            false
        }
    }

    /** Moves only the physical viewport's immediate canonical follower out of the scene FIFO. */
    private fun promoteQueuedStrictExactPhysicalForwardWarm(
        index: Int,
        page: PageRef,
    ): Boolean {
        if (latestStrictExactPhysicalForwardWarmPage.get() !== page) return false
        val task = strictExactRollingQueuedDecodes[index] ?: return false
        if (!strictExactRollingDecode.removeQueued(task)) return false
        if (!strictExactRollingQueuedDecodes.remove(index, task)) {
            return runCatching {
                strictExactRollingDecode.execute(task)
                false
            }.getOrDefault(false)
        }
        strictExactRollingForwardWarmPromotedDecodes.add(index)
        return try {
            strictExactForwardWarmDecode.execute(task)
            Log.d(
                TAG,
                "reader_ntk_strict_rolling_forward_warm_promoted page=$index," +
                    "source=${page.sourceIndex}",
            )
            true
        } catch (_: RejectedExecutionException) {
            strictExactRollingForwardWarmPromotedDecodes.remove(index)
            if (!cancelled.get()) {
                strictExactRollingQueuedDecodes[index] = task
                runCatching { strictExactRollingDecode.execute(task) }
            }
            false
        }
    }

    private fun releaseStrictExactDecodeClaim(
        index: Int,
        page: PageRef,
        splitSourceSingleFlight: Boolean
    ) {
        if (splitSourceSingleFlight) {
            strictExactSplitSourceDecodeInFlight.remove(strictExactSplitSourceDecodeKey(page))
        } else {
            strictExactDecodeInFlight.remove(index)
        }
    }

    private fun strictExactSplitSourceDecodeKey(page: PageRef): String {
        val episode = page.manga.ntkEpisodePath.orEmpty().trim()
        val source = page.image.orEmpty().trim()
        return "$episode#$source#${page.sourceIndex}"
    }

    private fun isInsideStrictExactRollingPixelWindow(index: Int): Boolean =
        synchronized(pagesLock) {
            if (index !in pages.indices) return@synchronized false
            val anchor = currentViewportAnchor.get()
                .takeIf { it in pages.indices }
                ?: currentStartPage().coerceIn(0, pages.lastIndex)
            // retainedFirstPage..retainedLastPage is a source/body lifetime window. During the
            // sealed launch wave it can intentionally cover the complete episode so every body is
            // verified once, even though the hardware tile pool holds only a small rolling pixel
            // set. Treating that range as current pixel demand made a pressure-retired offscreen
            // tail decode again immediately. A 13-page episode on a 12-slot pool then cycled p12
            // forever, evicted the middle runway and left physical scroll capped before the tail.
            //
            // The compositor deliberately keeps its last complete frame while a reverse/forward
            // page is being rehydrated.  Consequently its proven span can remain p8..p9 after the
            // real logical viewport has already moved to p5.  Treating only that stale span as
            // pixel demand returned here before the historic handoff bit could be invalidated,
            // permanently suppressing the one decode capable of replacing the held frame.  Use
            // the same continuous physical-to-logical bridge as finishStrictExactColdWindowDemand;
            // it is still bounded by a real viewport anchor and never opens the full source/body
            // admission range as decoded-pixel demand.
            val compositorWindow = compositorProvenStrictExactPixelWindowLocked(
                fallbackAnchor = anchor,
                fallbackFirst = anchor,
                fallbackLast = anchor,
            )
            index in NtkStrictRollingDecodeDemandPolicy.bridgePhysicalFrameToLogicalAnchor(
                physicalVisibleRange = compositorWindow,
                logicalAnchor = anchor,
                pageCount = pages.size,
            )
        }

    /**
     * Transfers an immutable offscreen original directly from its decode worker to the Activity's
     * generation-qualified install queue. The former one-main-post-per-page handoff outlived a
     * 100+ page decode wave and allowed viewport updates to decode its final cohort again. The
     * install queue remains the lifecycle and identity authority; only that redundant main-thread
     * pixel hop is removed.
     */
    private fun handOffStrictExactAuthoritativeTiles(
        index: Int,
        page: PageRef,
        tiles: PageDecodeResult.Tiles,
        result: PageDecodeResult
    ): Boolean {
        val proof = tiles.originalProof ?: return false
        // Protect this exact immutable resource before the listener queues/installs it. Delayed
        // replacement cleanup can otherwise recycle the Bitmap in the narrow interval between
        // Surface acceptance and the old post-ACK ownership mark below.
        if (claimDecodeResultsExternallyOwned(listOf(result)) == null) {
            val identities = decodeResultBitmapIdentities(listOf(result))
            val transferred = synchronized(externallyOwnedBitmaps) {
                identities.count(surfaceRetirementTransferredBitmaps::contains)
            }
            Log.e(
                TAG,
                "reader_authoritative_worker_handoff_reject page=$index,source=${page.sourceIndex}," +
                    "reason=external_claim,recycled=${identities.count(Bitmap::isRecycled)}," +
                    "transferred=$transferred,activeTokens=" +
                    identities.count(HostExactHardwareTilePool::isActiveToken),
            )
            return false
        }
        val acceptedByInstallOwner = try {
            listener.onPageAuthoritativeTilesReady(
                index,
                page.sourceIndex,
                tiles.pageWidth,
                tiles.pageHeight,
                tiles.tiles,
                proof
            )
        } catch (failure: Throwable) {
            throw failure
        }
        if (!acceptedByInstallOwner) {
            Log.e(
                TAG,
                "reader_authoritative_worker_handoff_reject page=$index,source=${page.sourceIndex}," +
                    "reason=listener_rejected,activeTokens=" +
                    tiles.tiles.count { HostExactHardwareTilePool.isActiveToken(it.bitmap) },
            )
            return false
        }

        // Queue acceptance is the ownership ACK for this worker path. Offscreen pages are
        // intentionally installed by the Activity's next main-loop drain, so requiring an
        // immediate Surface lookup here falsely rejects every valid queued page and sends the
        // same immutable original through the legacy delivery path a second time. The Activity
        // publishes render readiness only after the queued Surface install succeeds.
        //
        // The Surface or its immutable install queue now owns these precise Bitmap identities.
        // Protect them before consulting the historical page bit: a
        // duplicate callback for the same winner must not fall through a pre-existing bit and
        // later let generic delivery cleanup recycle the Surface-owned pixels.
        if (index == currentStartPage()) {
            strictExactInitialAnchorPixelsInstalledAtMs.compareAndSet(
                0L,
                SystemClock.elapsedRealtime(),
            )
            strictExactInitialAnchorPixelsInstalled.countDown()
        }
        strictExactRollingRehydratePages.remove(index)
        // Do not clear the host-pressure marker here. A newer pressure trim can retire this page
        // after its physical claim but before this worker handoff. Clearing that newer marker is
        // an ABA race which immediately admits another off-screen decode. Only physical re-entry
        // claims the marker in claimHostPressureRetiredExactPageForRehydrate().
        if (!strictExactAuthoritativeHandoffPages.add(index)) return true
        if (trackDeliveredResult(index, page, result, owned = false) < 0) {
            rollbackPublishedBitmapConflict(
                index,
                page,
                result.width,
                "authoritative_handoff",
            )
            return false
        }
        loading.remove(index)
        loadingPages.remove(index, page)
        loadingStartedAtMs.remove(index)
        urgentLoading.remove(index)
        urgentLoadingPages.remove(index)
        pendingDeliveryWidths.remove(index)
        failedPages.remove(index)
        markDecodedDrawableReady(index, page, result.width)
        scheduleDirectWifiIdleForwardWarmPump()
        return true
    }

    /**
     * Keeps a two-page exact-pixel runway ahead of the physical viewport, one completed page at a
     * time. This is not generic offscreen completion: each turn nominates exactly one immutable
     * immediate follower for [strictExactForwardWarmDecode], whose identity-bound lane is already
     * fenced from the scene FIFO and from the urgent blocker. Limiting the candidate ceiling to
     * two pages prevents a suffix wave while allowing a successful handoff to prepare the next
     * page during continuous reading instead of waiting for a 750 ms input-quiet gap that may
     * never occur between real swipes.
     */
    private fun scheduleDirectWifiIdleForwardWarmPump() {
        if (cancelled.get() || !strictExactDirectWifiRollingPixelResidency.get() ||
            !directWifiIdleForwardWarmPumpScheduled.compareAndSet(false, true)
        ) return
        main.postDelayed({
            directWifiIdleForwardWarmPumpScheduled.set(false)
            if (cancelled.get()) return@postDelayed
            val direction = synchronized(windowLock) { lastWindowDirection }
            if (direction < 0) return@postDelayed
            val retained = synchronized(deliveredBitmaps) {
                retainedFirstPage..retainedLastPage
            }
            if (retained.isEmpty()) return@postDelayed
            val visibleLast = physicalDeliveryLastPage
            if (visibleLast < 0) return@postDelayed
            val warmLast = minOf(
                retained.last,
                visibleLast + DIRECT_WIFI_FORWARD_WARM_AHEAD_PAGES,
            )
            if (warmLast <= visibleLast) return@postDelayed
            val unavailable = HashSet<Int>()
            for (candidate in maxOf(retained.first, visibleLast + 1)..warmLast) {
                if (hasDeliveredOrPendingDrawable(candidate) ||
                    listener.isPageAuthoritativeDrawableCurrentlyInstalled(candidate)
                ) unavailable += candidate
            }
            val next = ReaderStrictBitmapResidencyPolicy.nextIdleForwardWarmPage(
                directWifiRolling = true,
                busy = false,
                direction = direction,
                visibleLast = visibleLast,
                retainedLast = warmLast,
                pageCount = synchronized(pagesLock) { pages.size },
                residentPages = unavailable,
            ) ?: return@postDelayed
            val page = pageRef(next) ?: return@postDelayed
            val admission = strictRollingAdmission.get() ?: return@postDelayed
            if (page.transitionTitle != null || !isStrictExactLaunchPage(page) ||
                !admission.admitsSource(page.sourceIndex) ||
                strictExactBodyDescriptors[page.sourceIndex] == null
            ) return@postDelayed
            Log.d(
                TAG,
                "reader_direct_wifi_idle_forward_pixel_pump page=$next," +
                    "visibleLast=$visibleLast,warmLast=$warmLast," +
                    "retainedLast=${retained.last}",
            )
            requestStrictExactSourcePage(
                index = next,
                anchor = false,
                generation = windowGeneration.get(),
                physicalForwardWarmIntent = true,
            )
        }, DIRECT_WIFI_IDLE_FORWARD_WARM_PUMP_STEP_MS)
    }

    private fun requestPage(index: Int, busy: Boolean, anchor: Boolean, generation: Int = windowGeneration.get()) {
        if (cancelled.get()) return
        val initialPage = pageRef(index) ?: return
        if (strictExactColdRolling && isStrictExactLaunchPage(initialPage)) {
            requestStrictExactSourcePage(index, anchor, generation)
            return
        }
        val visibleIntent = busy || anchor
        var page = initialPage
        if (
            isStructurePublishPending() &&
            !shouldAllowInitialRequestDuringStructurePublish(index, page, visibleIntent)
        ) {
            if (visibleIntent && isNtkSource(manga, title)) {
                Log.d(TAG, "reader_visible_request_skip_structure page=$index,busy=$busy,anchor=$anchor,generation=$generation")
            }
            return
        }
        // An appended strict PageRef already has one manifest-bound source owner. It must reach
        // that identity route before launch-runway cold holds, generated URL replacement, or
        // remembered 404/tail policies can consume the physical request. Those generic policies
        // are neither pixel-ownership evidence nor a valid wake edge for an idle rehydrate flight.
        if (routeStrictAdjacentExactRehydrate(index, page, visibleIntent)) return
        if (shouldKeepPreparedRunwayDecodeColdUntilInput(index, page)) return
        if (applyHintedNtkGeneratedImage(index, page, "request_page")) {
            page = pageRef(index) ?: return
        }
        if (shouldSuppressTrustedManifestGeneratedFallback(index, page, "request_page")) return
        if (trimRecordedKnownMissingNtkGeneratedTail(page.manga, "request_page")) return
        if (skipKnownMissingNtkGeneratedPage(index, page, "request_page")) return
        if (adoptAuthoritativeListenerDrawable(index, page, "request_page")) return
        if (joinExistingPagePipelineOwner(index, page, visibleIntent)) return
        if (routeActiveGeneratedRequestToProofOrBytes(index, page, busy, anchor, generation)) return
        if (isNtkSource(page.manga, title) &&
            shouldHoldNtkGeneratedTailForInitialContinuous() &&
            index > currentStartPage() + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1 &&
            !(isImmediateNtkGeneratedUx() && generation == FOREGROUND_PRIME_WARM_GENERATION) &&
            generation != windowGeneration.get()
        ) {
            logNtkPagePerf(index, "generated_tail_hold_initial_continuous", "generation=$generation")
            return
        }
        if (shouldDeferPostInitialContinuousNtkRequest(index, page, busy, anchor, generation)) return
        if (shouldDeferNtkPreAnchorPageRequest(index, page, anchor, generation)) return
        failedPages.remove(index)
        if (page.transitionTitle != null) {
            decodedWidths[index] = Int.MAX_VALUE
            desiredWidths.remove(index)
            inFlightWidths.remove(index)
            loading.remove(index)
            main.post {
                if (!cancelled.get()) listener.onPageCard(index, page.transitionTitle)
            }
            return
        }
        if (usesProtectedNumericNtkPipeline(page) && !isInsideProtectedNumericBitmapWindow(index, page)) {
            if (!hasPageSourceReady(index, page)) {
                forcePrefetchNtkPageSource(
                    index,
                    page,
                    "immediate_full_source_bounded_window",
                    allowDuringInitialInteractive = true
                )
            } else {
                markProtectedNumericSourceReady(index, page, "request_outside_bitmap_window")
            }
            logNtkPagePerf(index, "decode_skip_outside_bounded_window", "anchor=${currentViewportAnchor.get()}")
            return
        }
        val fullTargetWidth = max(1, viewerWidth)
        if (shouldDeferActiveGeneratedFullWidthUpgrade(index, page, fullTargetWidth)) {
            val deliveredWidth = deliveredLowResGeneratedDrawableWidth(index, page, fullTargetWidth)
            logNtkPagePerf(
                index,
                "generated_full_upgrade_defer_active_proof",
                "delivered=$deliveredWidth,target=$fullTargetWidth,busy=$busy,anchor=$anchor,generation=$generation"
            )
            scheduleIdleFullWidthUpgrade(index, fullTargetWidth)
            return
        }
        val requestedTargetWidth = if (
            isImmediateGeneratedFullSurfacePrimeRequest(index, page, busy, generation)
        ) {
            immediateFullSurfacePrimeTargetWidth()
        } else {
            targetWidth(page, busy)
        }
        val targetWidth = if (
            shouldUseInitialGeneratedCachedDecodeGuard(index, page) &&
            isNtkGeneratedDescriptorOrImagePage(page) &&
            index != currentStartPage() &&
            (!firstBitmapLogged.get() || isActiveGeneratedTouchOrQuiet())
        ) {
            minOf(requestedTargetWidth, ntkProofTargetWidth())
        } else {
            requestedTargetWidth
        }
        rememberDesiredWidth(index, targetWidth)
        val effectiveTargetWidth = achievableWidth(index, targetWidth)
        clearStaleLoadStateForIndex(index, page)
        val decodedWidth = decodedWidths[index] ?: 0
        if (decodedWidth >= effectiveTargetWidth) {
            if (hasDeliveredBitmap(index)) return
            decodedWidths.remove(index)
        }
        val preAnchorFallbackVisible = busy &&
            generation == FOREGROUND_PRIME_WARM_GENERATION &&
            !firstBitmapLogged.get() &&
            isNtkSource(page.manga, title) &&
            ntkCoordinator?.allowsPreAnchorFallback(index, page.image, "requestPage.visiblePriority") == true
        val ntkInitialNearPrimeVisible = busy &&
            generation == FOREGROUND_PRIME_WARM_GENERATION &&
            firstBitmapLogged.get() &&
            isNtkSource(page.manga, title) &&
            index <= currentStartPage() + NTK_FOREGROUND_STREAM_AHEAD_PAGES
        val ntkInitialContinuousPrimeVisible = busy &&
            generation == FOREGROUND_PRIME_WARM_GENERATION &&
            isNtkSource(page.manga, title) &&
            index in currentStartPage() until
                (currentStartPage() + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)
        val ntkInitialRapidGeneratedVisible = isInitialRapidGeneratedUrgent(index, page, busy, generation)
        val ntkInitialRunwayDuringInput =
            isImmediateNtkGeneratedUx() &&
                isNtkGeneratedDescriptorOrImagePage(page) &&
                index in currentStartPage() until
                    (currentStartPage() + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)
        val actualWindowVisible = anchor || (busy && generation >= 0) ||
            preAnchorFallbackVisible || ntkInitialNearPrimeVisible || ntkInitialRunwayDuringInput ||
            ntkInitialContinuousPrimeVisible || ntkInitialRapidGeneratedVisible
        val visiblePriority = actualWindowVisible && !hasDeliveredOrPendingDrawable(index)
        if (
            !visiblePriority &&
            isImmediateNtkGeneratedUx() &&
            isNtkGeneratedDescriptorOrImagePage(page) &&
            !isImmediateGeneratedFullSurfacePrimeRequest(index, page, busy, generation) &&
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L
        ) {
            logNtkPagePerf(
                index,
                "generated_decode_skip_active_nonvisible",
                "busy=$busy,anchor=$anchor,generation=$generation"
            )
            return
        }
        if (shouldThrottleGeneratedVisibleDuringFirstInput(index, page, visiblePriority)) {
            promoteVisibleGeneratedCachedDecode(index, page, "first_input_throttle")
            logNtkPagePerf(
                index,
                "visible_generated_first_input_throttle",
                "anchor=${currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()},generation=$generation"
            )
            return
        }
        if (shouldThrottleKpDescriptorVisibleBeforeFirstDrawable(index, page, visiblePriority)) {
            logNtkPagePerf(
                index,
                "visible_kp_descriptor_pre_first_throttle",
                "start=${currentStartPage()},anchor=${currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()},generation=$generation"
            )
            return
        }
        if (visiblePriority && shouldRouteActiveGeneratedToProof(index, page)) {
            val scheduled = scheduleVisibleGeneratedCachedDecode(
                index,
                page,
                if (anchor) "visible_anchor_proof" else "visible_window_proof",
                SystemClock.elapsedRealtime(),
                forceRequeue = true,
                proofDrawable = true
            )
            if (scheduled) {
                logNtkPagePerf(
                    index,
                    "visible_generated_route_proof",
                    "anchor=${currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()},generation=$generation"
                )
                return
            }
        }
        val pendingWidth = pendingDeliveryWidths[index] ?: 0
        if (pendingWidth >= effectiveTargetWidth) {
            if (visiblePriority && isNtkSource(page.manga, title)) {
                Log.d(
                    TAG,
                    "reader_visible_request_skip_pending page=$index,pending=$pendingWidth," +
                        "target=$effectiveTargetWidth,busy=$busy,anchor=$anchor,generation=$generation"
                )
                promoteVisiblePendingDelivery(index)
                return
            }
            return
        }
        val activeWidth = inFlightWidths[index] ?: 0
        if (activeWidth >= effectiveTargetWidth && loading.contains(index)) {
            var restartedActiveRequest = false
            if (visiblePriority && isNtkSource(page.manga, title)) {
                val activeStartedAt = loadingStartedAtMs[index] ?: 0L
                Log.d(
                    TAG,
                    "reader_visible_request_skip_active page=$index,active=$activeWidth," +
                        "target=$effectiveTargetWidth,urgent=${urgentLoading.contains(index)},generation=$generation"
                )
                val activeAgeMs = if (activeStartedAt > 0L) {
                    SystemClock.elapsedRealtime() - activeStartedAt
                } else {
                    Long.MAX_VALUE
                }
                if (
                    (shouldUseInitialGeneratedAnchorDirectDecode(index, page) ||
                        shouldUseInitialGeneratedCachedDecodeGuard(index, page)) &&
                    !shouldSuppressFarInitialGeneratedVisibleActiveDecode(index, page) &&
                    !hasDeliveredOrPendingDrawable(index)
                ) {
                    val cachedScheduled = promoteVisibleGeneratedCachedDecode(index, page, "active_skip")
                    if (!cachedScheduled) {
                        hedgeVisibleGeneratedByteFetch(index, page, "active_skip")
                    }
                    logNtkPagePerf(
                        index,
                        "visible_active_skip_attach_cached_listener",
                        "target=$effectiveTargetWidth,ageMs=$activeAgeMs"
                    )
                }
                if (!urgentLoading.contains(index) &&
                    loadingPages[index] === page &&
                    shouldRestartVisibleActiveRequest(index, page, anchor, activeAgeMs)
                ) {
                    loading.remove(index)
                    loadingPages.remove(index, page)
                    loadingStartedAtMs.remove(index)
                    inFlightWidths.remove(index)
                    restartedActiveRequest = true
                    Log.d(
                        TAG,
                        "reader_visible_request_promote_active page=$index,target=$effectiveTargetWidth," +
                            "ageMs=$activeAgeMs,image=${page.image?.substringAfterLast('/')}"
                    )
                } else {
                    return
                }
            }
            if (!restartedActiveRequest) return
        }
        val ownsLoading = loading.add(index)
        val urgent = !ownsLoading &&
            visiblePriority &&
            urgentLoading.add(index)
        if (!ownsLoading && !urgent) {
            if (targetWidth > activeWidth)
                ViewerWarmupManager.logMetric("busy_to_idle_upgrade_pending", targetWidth.toLong())
            return
        }
        if (ownsLoading) {
            loadingPages[index] = page
            inFlightWidths[index] = targetWidth
            loadingStartedAtMs[index] = SystemClock.elapsedRealtime()
        }
        if (urgent) {
            urgentLoadingPages[index] = page
        }
        if (ownsLoading && shouldPostPageLoadingState(index, page, busy, anchor, generation)) {
            main.post { if (!cancelled.get()) listener.onPageLoading(index) }
        }
        if (visiblePriority) {
            ViewerWarmupManager.logMetric("reader_urgent_visible_decode", index.toLong())
            if (isNtkSource(page.manga, title)) {
                Log.d(
                    TAG,
                    "reader_visible_request_start page=$index,owns=$ownsLoading,urgent=$urgent," +
                        "busy=$busy,anchor=$anchor,generation=$generation,image=${page.image?.substringAfterLast('/')}"
                )
                hedgeVisibleGeneratedByteFetch(
                    index,
                    page,
                    if (anchor) "anchor" else "visible",
                    delayMs = if (
                        (!firstBitmapLogged.get() && index == currentStartPage()) ||
                        shouldUseInitialGeneratedCachedDecodeGuard(index, page)
                    ) {
                        0L
                    } else {
                        NTK_VISIBLE_GENERATED_BYTE_HEDGE_DELAY_MS
                    }
                )
                if (anchor && index == currentStartPage()) {
                    val anchorDirectStarted = scheduleInitialGeneratedDirectDecode(
                        index,
                        page,
                        targetWidth,
                        "anchor_visible_start",
                        SystemClock.elapsedRealtime(),
                        allowAnchor = true
                    )
                    logNtkPagePerf(
                        index,
                        "anchor_visible_direct_decode",
                        "started=$anchorDirectStarted,target=$targetWidth"
                    )
                    primeInitialContinuousGeneratedAlongsideAnchor(index, "anchor_visible_start")
                }
            }
        }
        val foregroundPrime = generation == FOREGROUND_PRIME_WARM_GENERATION
        val primeWarm = generation == PRIME_WARM_GENERATION
        if (foregroundPrime && ownsLoading && shouldHedgeForegroundPrime(index)) {
            scheduleForegroundPrimeHedge(index)
        }
        val retainWhenBusy = generation == PRIME_WARM_GENERATION ||
            foregroundPrime ||
            (visiblePriority && isNtkSource(page.manga, title))
        val networkExecutor = when {
            anchor -> anchorNetwork
            visiblePriority -> urgentNetwork
            foregroundPrime || primeWarm -> primeNetwork
            else -> network
        }
        val decodeExecutor = when {
            anchor -> anchorDecode
            visiblePriority -> urgentDecode
            foregroundPrime || primeWarm -> primeDecode
            else -> decode
        }
        try {
            networkExecutor.execute {
            try {
                if (shouldSkipStalePage(index, generation, anchor)) {
                    clearPageLoadState(index, page, ownsLoading, urgent)
                    return@execute
                }
                val originalPage = page
                if (adoptAuthoritativeListenerDrawable(index, originalPage, "network_worker")) {
                    clearPageLoadState(index, page, ownsLoading, urgent)
                    return@execute
                }
                val allowPreviewCache = shouldUsePreviewDecodedCache(index, targetWidth)
                cachedDecodedResult(index, originalPage, targetWidth, allowPreviewCache)?.let { cached ->
                    logNtkPagePerf(index, "cache_hit", "target=$targetWidth,width=${cached.width}")
                    clearPageLoadState(index, page, ownsLoading, urgent)
                    postDecodeResult(Delivery(index, originalPage, cached, SystemClock.elapsedRealtime(), targetWidth, retainWhenBusy))
                    ViewerWarmupManager.logMetric("reader_decoded_cache_hit", index.toLong())
                    return@execute
                }
                if (!anchor && !urgent && !foregroundPrime && !visiblePriority) {
                    prefetchImageFile(index, originalPage)
                }
                val adjacentYieldMs = initialAdjacentGeneratedDecodeYieldMs(index, originalPage, anchor)
                if (adjacentYieldMs > 0L) {
                    Log.d(
                        TAG,
                        "reader_ntk_initial_adjacent_decode_yield page=$index,start=${currentStartPage()}," +
                            "delayMs=$adjacentYieldMs,image=${originalPage.image?.substringAfterLast('/')}"
                    )
                    scheduleInitialAdjacentGeneratedDecodeRetry(index, originalPage, generation, adjacentYieldMs)
                    clearPageLoadState(index, page, ownsLoading, urgent)
                    return@execute
                }
                if (visiblePriority &&
                    shouldUseInitialGeneratedCachedDecodeGuard(index, originalPage) &&
                    !hasDeliveredOrPendingDrawable(index)
                ) {
                    val initialContinuousProof =
                        shouldUseImmediateGeneratedProofDrawable(originalPage)
                    if (shouldSuppressFarInitialGeneratedVisibleActiveDecode(index, originalPage)) {
                        logNtkPagePerf(
                            index,
                            "initial_continuous_visible_suppressed_active_far",
                            "anchor=${currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()}"
                        )
                        clearPageLoadState(index, page, ownsLoading, urgent)
                        return@execute
                    }
                    val byteStartedAt = SystemClock.elapsedRealtime()
                    if (
                        readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L &&
                        ReaderImageCache.cachedFile(appContext, originalPage.manga, originalPage.image.orEmpty()) != null
                    ) {
                        scheduleVisibleGeneratedCachedDecode(
                            index,
                            originalPage,
                            "initial_continuous_visible_cached_active",
                            byteStartedAt,
                            forceRequeue = true,
                            proofDrawable = initialContinuousProof,
                            allowOutsideProofWindow = initialContinuousProof
                        )
                        logNtkPagePerf(
                            index,
                            "initial_continuous_visible_cached_active",
                            "target=$targetWidth,proof=$initialContinuousProof"
                        )
                        clearPageLoadState(index, page, ownsLoading, urgent)
                        return@execute
                    }
                    var directStarted = false
                    var cachedScheduled = false
                    if (initialContinuousProof) {
                        cachedScheduled = scheduleVisibleGeneratedCachedDecode(
                            index,
                            originalPage,
                            "initial_continuous_visible_wait",
                            byteStartedAt,
                            forceRequeue = true,
                            proofDrawable = true,
                            allowOutsideProofWindow = true
                        )
                        if (!cachedScheduled) {
                            cachedScheduled = startInitialInteractiveRunwayByteFetch(
                                index,
                                originalPage,
                                "initial_continuous_visible_wait",
                                forceProofDrawable = true,
                                allowOutsideProofWindow = true
                            )
                        }
                    } else {
                        directStarted = scheduleInitialGeneratedDirectDecode(
                            index,
                            originalPage,
                            targetWidth,
                            "initial_continuous_visible_wait",
                            byteStartedAt
                        )
                    }
                    if (!directStarted && !cachedScheduled) {
                        val cachedScheduled = scheduleVisibleGeneratedCachedDecode(
                            index,
                            originalPage,
                            "initial_continuous_visible_wait",
                            byteStartedAt,
                            forceRequeue = true
                        )
                        if (!cachedScheduled) {
                            hedgeVisibleGeneratedByteFetch(
                                index,
                                originalPage,
                                "initial_continuous_visible_preview",
                                0L
                            )
                        }
                    }
                    logNtkPagePerf(
                        index,
                        "initial_continuous_preview_only",
                        "target=$targetWidth,directStarted=$directStarted,proof=$initialContinuousProof"
                    )
                    clearPageLoadState(index, page, ownsLoading, urgent)
                    return@execute
                }
                try {
                    decodeExecutor.execute {
                    val gate = if (
                        visiblePriority &&
                        busy &&
                        isNtkSource(originalPage.manga, title) &&
                        isNtkManhwaOrWebtoonEpisodePath(originalPage.manga.ntkEpisodePath) &&
                        isActiveGeneratedInputOrQuietForDelivery()
                    ) {
                        activeVisibleDecodeGate
                    } else if (visiblePriority) {
                        null
                    } else if (busy) {
                        busyDecodeGate
                    } else {
                        idleDecodeGate
                    }
                    var acquired = false
                    var delivered = false
                    var strictOriginalFlight: String? = ""
                    try {
                        if (gate != null) {
                            gate.acquire()
                            acquired = true
                        }
                        if (cancelled.get() || shouldSkipStalePage(index, generation, anchor)) return@execute
                        if (shouldKeepPreparedRunwayDecodeColdUntilInput(index, originalPage)) {
                            return@execute
                        }
                        if (adoptAuthoritativeListenerDrawable(index, originalPage, "decode_worker")) {
                            return@execute
                        }
                        if (shouldSkipDecodeOutsideProtectedNumericWindow(
                                index,
                                originalPage,
                                "request_page_pre"
                            )
                        ) {
                            return@execute
                        }
                        if (shouldUseNtkInitialGeneratedDisplayDecode(index, originalPage) &&
                            hasDeliveredOrPendingDrawable(index)
                        ) {
                            if (hasDeliveredBitmap(index)) {
                                logNtkPagePerf(index, "decode_skip_pending_initial_generated", "target=$targetWidth")
                                return@execute
                            }
                            if (!visiblePriority) {
                                logNtkPagePerf(index, "decode_skip_pending_initial_generated", "target=$targetWidth")
                                return@execute
                            }
                            promoteVisiblePendingDelivery(index)
                            if (hasDeliveredBitmap(index)) {
                                logNtkPagePerf(index, "decode_skip_promoted_initial_generated", "target=$targetWidth")
                                return@execute
                            }
                            logNtkPagePerf(index, "decode_continue_pending_visible_generated", "target=$targetWidth")
                        }
                        val startedAt = SystemClock.elapsedRealtime()
                        val foregroundFetch = shouldUseForegroundFetch(
                            index,
                            originalPage,
                            anchor,
                            urgent || visiblePriority,
                            busy,
                            generation
                        )
                        val foregroundPermit = if (foregroundFetch) {
                            ntkCoordinator?.imagePermit(
                                index,
                                originalPage.manga,
                                originalPage.image,
                                if (index == currentStartPage()) NtkImageLane.FIRST_IMAGE else NtkImageLane.FOLLOWING_VISIBLE,
                                "requestPage.decode"
                            )
                        } else {
                            null
                        }
                        if (foregroundFetch && isNtkSource(originalPage.manga, title) &&
                            !ntkCoordinatorAllowsStream(index, originalPage, foregroundPermit, "requestPage.decode")
                        ) {
                            clearPageLoadState(index, page, ownsLoading, urgent)
                            return@execute
                        }
                        if (shouldDeferActiveGeneratedFullWidthUpgrade(index, originalPage, targetWidth)) {
                            logNtkPagePerf(
                                index,
                                "generated_full_upgrade_defer_before_decode",
                                "target=$targetWidth,delivered=${deliveredLowResGeneratedDrawableWidth(index, originalPage, targetWidth)}"
                            )
                            scheduleIdleFullWidthUpgrade(index, targetWidth)
                            return@execute
                        }
                        if (requiresAuthoritativeInlineTilePage(originalPage) &&
                            ReaderImageCache.cachedFile(
                                appContext,
                                originalPage.manga,
                                originalPage.image.orEmpty()
                            ) == null
                        ) {
                            scheduleVisibleGeneratedCachedDecode(
                                index,
                                originalPage,
                                "request_page_wait_complete_asset",
                                SystemClock.elapsedRealtime(),
                                forceRequeue = true,
                                proofDrawable = false,
                                allowOutsideProofWindow = true,
                                allowFullDuringActiveProof = true
                            )
                            return@execute
                        }
                        strictOriginalFlight = claimStrictInlineOriginalDecode(
                            index,
                            originalPage,
                            "request_page"
                        )
                        if (requiresAuthoritativeInlineTilePage(originalPage) && strictOriginalFlight == null) {
                            return@execute
                        }
                        val result = decodePageWithLease(
                            index,
                            originalPage,
                            targetWidth,
                            foregroundFetch,
                            allowPreviewCache,
                            visiblePriority || anchor,
                            foregroundPermit
                        )
                        if (
                            cancelled.get() ||
                            shouldSkipStalePage(index, generation, anchor) ||
                            currentPageIndexForDelivery(originalPage, index) < 0
                        ) {
                            recycleDecodeResult(result)
                            return@execute
                        }
                        delivered = true
                        postDecodeResult(Delivery(index, originalPage, result, startedAt, targetWidth, retainWhenBusy))
                    } catch (e: Exception) {
                        recordIfUnexpected(e)
                        postPageError(index, originalPage, e)
                    } finally {
                        releaseStrictInlineOriginalDecode(strictOriginalFlight)
                        if (acquired) gate?.release()
                        clearPageLoadState(index, page, ownsLoading, urgent)
                        if (delivered) ViewerWarmupManager.logMetric("reader_delivery_posted", index.toLong())
                    }
                }
                } catch (_: RejectedExecutionException) {
                    clearPageLoadState(index, page, ownsLoading, urgent)
                }
            } catch (e: Exception) {
                clearPageLoadState(index, page, ownsLoading, urgent)
                recordIfUnexpected(e)
                postPageError(index, page, e)
            }
            }
        } catch (_: RejectedExecutionException) {
            clearPageLoadState(index, page, ownsLoading, urgent)
        }
    }

    private fun shouldDeferNtkPreAnchorPageRequest(
        index: Int,
        page: PageRef,
        anchor: Boolean,
        generation: Int
    ): Boolean {
        if (firstBitmapLogged.get()) return false
        if (!isNtkSource(page.manga, title)) return false
        val start = currentStartPage()
        if (index == start) return false
        if (index in (start + 1) until (start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) &&
            isInitialContinuousNtkImage(page)
        ) {
            Log.d(
                TAG,
                "reader_ntk_pre_anchor_request_allowed_initial_continuous page=$index,start=$start," +
                    "anchor=$anchor,generation=$generation,image=${page.image?.substringAfterLast('/')}"
            )
            ViewerWarmupManager.logMetric(
                "reader_ntk_pre_anchor_request_allowed_initial_continuous",
                index.toLong()
            )
            return false
        }
        if (shouldHoldInitialGeneratedAnchorExclusive(index, page, start)) {
            Log.d(
                TAG,
                "reader_ntk_pre_anchor_request_deferred_anchor_exclusive page=$index,start=$start," +
                    "anchor=$anchor,generation=$generation,image=${page.image?.substringAfterLast('/')}"
            )
            ViewerWarmupManager.logMetric("reader_ntk_pre_anchor_request_deferred_anchor_exclusive", index.toLong())
            schedulePreAnchorFallbackRetry(index, page, generation)
            return true
        }
        if (isNtkGeneratedDescriptorOrImagePage(page) &&
            !ReaderImageCache.hasNtkAnchorAssetForEpisode(page.manga)
        ) {
            if (shouldUseInitialGeneratedStreamRunwayGuard(index, page)) {
                Log.d(
                    TAG,
                    "reader_ntk_pre_anchor_request_allowed_generated_runway page=$index,start=$start," +
                        "anchor=$anchor,generation=$generation,image=${page.image?.substringAfterLast('/')}"
                )
                ViewerWarmupManager.logMetric(
                    "reader_ntk_pre_anchor_request_allowed_generated_runway",
                    index.toLong()
                )
                return false
            }
            if (shouldAllowVerifiedNearGeneratedBeforeAnchorAsset(index, page, start, anchor, generation)) {
                Log.d(
                    TAG,
                    "reader_ntk_pre_anchor_request_allowed_before_anchor_asset page=$index,start=$start," +
                        "anchor=$anchor,generation=$generation,image=${page.image?.substringAfterLast('/')}"
                )
                ViewerWarmupManager.logMetric(
                    "reader_ntk_pre_anchor_request_allowed_before_anchor_asset",
                    index.toLong()
                )
                return false
            }
            Log.d(
                TAG,
                "reader_ntk_pre_anchor_request_deferred_until_anchor_asset page=$index,start=$start," +
                    "anchor=$anchor,generation=$generation,image=${page.image?.substringAfterLast('/')}"
            )
            ViewerWarmupManager.logMetric("reader_ntk_pre_anchor_request_deferred_until_anchor_asset", index.toLong())
            schedulePreAnchorFallbackRetry(index, page, generation)
            return true
        }
        if (ntkCoordinator?.allowsPreAnchorFallback(index, page.image, "shouldDeferNtkPreAnchorPageRequest") == true) {
            Log.d(
                TAG,
                "reader_ntk_pre_anchor_request_allowed page=$index,start=$start," +
                    "anchor=$anchor,generation=$generation,image=${page.image?.substringAfterLast('/')}"
            )
            ViewerWarmupManager.logMetric("reader_ntk_pre_anchor_request_allowed", index.toLong())
            return false
        }
        if (index > start + NTK_PRE_ANCHOR_FALLBACK_MAX_AHEAD) {
            Log.d(
                TAG,
                "reader_ntk_pre_anchor_request_skip_far page=$index,start=$start," +
                    "maxAhead=$NTK_PRE_ANCHOR_FALLBACK_MAX_AHEAD,image=${page.image?.substringAfterLast('/')}"
            )
            ViewerWarmupManager.logMetric("reader_ntk_pre_anchor_request_skip_far", index.toLong())
            return true
        }
        schedulePreAnchorFallbackRetry(index, page, generation)
        Log.d(
            TAG,
            "reader_ntk_pre_anchor_request_deferred page=$index,start=$start," +
                "anchor=$anchor,generation=$generation"
        )
        ViewerWarmupManager.logMetric("reader_ntk_pre_anchor_request_deferred", index.toLong())
        return true
    }

    private fun shouldHoldInitialGeneratedAnchorExclusive(index: Int, page: PageRef, start: Int): Boolean {
        if (firstBitmapLogged.get()) return false
        if (index == start) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (shouldUseInitialGeneratedStreamRunwayGuard(index, page)) return false
        return true
    }

    private fun shouldAllowVerifiedNearGeneratedBeforeAnchorAsset(
        index: Int,
        page: PageRef,
        start: Int,
        anchor: Boolean,
        generation: Int
    ): Boolean {
        if (anchor) return false
        if (!ReaderImageCache.hasNtkAnchorAssetForEpisode(page.manga)) return false
        val minNearVisible = (start - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES).coerceAtLeast(0)
        val initialContinuousLast = start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        val maxAhead = if (
            index <= initialContinuousLast &&
            isNtkWebtoonEpisodePath(page.manga.ntkEpisodePath)
        ) {
            NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        } else {
            NTK_PRE_ANCHOR_VERIFIED_GENERATED_AHEAD
        }
        if (index < minNearVisible || index > start + maxAhead) return false
        if (index == start) return false
        val image = page.image.orEmpty()
        if (!isNtkGeneratedImageUrl(image)) return false
        if (isFreshExactEarlyNtkImageUrl(page.manga, image)) return true
        if (hasFreshEarlyNtkImageUrlFor(page.manga, image, requireExact = false)) return true
        if (ntkCoordinator?.allowsPreAnchorFallback(index, page.image, "verifiedNearGeneratedBeforeAnchorAsset") != true) return false
        return hasFreshEarlyNtkImageUrlFor(page.manga, image, requireExact = false)
    }

    private fun isFreshExactEarlyNtkImageUrl(target: Manga, image: String?): Boolean {
        return hasFreshEarlyNtkImageUrlFor(target, image, requireExact = true)
    }

    private fun hasFreshEarlyNtkImageUrlFor(target: Manga, image: String?, requireExact: Boolean): Boolean {
        val requestImage = image.orEmpty()
        if (requestImage.isBlank()) return false
        val earlyUrls = ReaderImageCache.earlyNtkImageUrls(
            target.ntkEpisodePath,
            SystemClock.elapsedRealtime() - 30000L
        )
        if (earlyUrls.isEmpty()) return false
        val normalizedImage = Utils.viewerImageRequestUrl(requestImage, target.baseMode)
        val exactMatch = earlyUrls.any {
            it == requestImage || Utils.viewerImageRequestUrl(it, target.baseMode) == normalizedImage
        }
        if (exactMatch) return true
        val requestPage = ntkImagePageNumber(requestImage) ?: ntkGeneratedPageNumber(requestImage)
        if (requestPage != null && isNtkGeneratedImageUrl(requestImage)) {
            val pageMatch = earlyUrls.any { early ->
                (ntkImagePageNumber(early) ?: ntkGeneratedPageNumber(early)) == requestPage
            }
            if (pageMatch) return true
        }
        return !requireExact
    }

    private fun schedulePreAnchorFallbackRetry(index: Int, page: PageRef, generation: Int) {
        if (generation != FOREGROUND_PRIME_WARM_GENERATION) return
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return
        if (!preAnchorFallbackRetries.add(index)) return
        val delayMs = ntkCoordinator
            ?.preAnchorFallbackRetryDelayMs(index, page.image)
            ?.let { remaining ->
                if (remaining > 0L) {
                    remaining.coerceAtMost(NTK_PRE_ANCHOR_FALLBACK_RETRY_MAX_MS)
                } else {
                    NTK_PRE_ANCHOR_FALLBACK_RETRY_MS
                }
            }
            ?: NTK_PRE_ANCHOR_FALLBACK_RETRY_MS
        main.postDelayed({
            preAnchorFallbackRetries.remove(index)
            if (cancelled.get() || firstBitmapLogged.get()) return@postDelayed
            val latest = pageRef(index) ?: return@postDelayed
            if (!sameNtkSourceSlot(page, latest)) return@postDelayed
            Log.d(
                TAG,
                "reader_ntk_pre_anchor_request_retry page=$index,start=${currentStartPage()}," +
                    "generation=$generation,image=${latest.image?.substringAfterLast('/')}"
            )
            ViewerWarmupManager.logMetric("reader_ntk_pre_anchor_request_retry", index.toLong())
            requestPage(index, busy = true, anchor = false, generation = generation)
        }, delayMs)
    }

    private fun ntkCoordinatorAllowsStream(
        index: Int,
        page: PageRef,
        permit: NtkImagePermit?,
        source: String
    ): Boolean {
        return ntkCoordinatorAllowsStream(index, page.manga, page.image, permit, source)
    }

    private fun ntkCoordinatorAllowsStream(
        index: Int,
        target: Manga,
        image: String?,
        permit: NtkImagePermit?,
        source: String
    ): Boolean {
        if (!isNtkSource(target, title)) return true
        val start = currentStartPage()
        if (!firstBitmapLogged.get() &&
            index < start &&
            isNtkGeneratedImageUrl(image.orEmpty()) &&
            !ReaderImageCache.hasNtkAnchorAssetForEpisode(target)
        ) {
            Log.d(
                TAG,
                "reader_ntk_pre_anchor_stream_deferred_previous_until_anchor_asset page=$index,start=$start," +
                    "source=$source,image=${image.orEmpty().substringAfterLast('/')}"
            )
            ViewerWarmupManager.logMetric(
                "reader_ntk_pre_anchor_stream_deferred_previous_until_anchor_asset",
                index.toLong()
            )
            return false
        }
        if (!firstBitmapLogged.get() &&
            index in (start - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)..(start + NTK_PRE_ANCHOR_VERIFIED_GENERATED_AHEAD) &&
            isNtkGeneratedImageUrl(image.orEmpty()) &&
            hasFreshEarlyNtkImageUrlFor(target, image, requireExact = false)
        ) {
            Log.d(
                TAG,
                "reader_ntk_pre_anchor_stream_allowed_by_verified_run page=$index,start=$start," +
                    "source=$source,image=${image.orEmpty().substringAfterLast('/')}"
            )
            ViewerWarmupManager.logMetric("reader_ntk_pre_anchor_stream_allowed_by_verified_run", index.toLong())
            return true
        }
        if (!firstBitmapLogged.get() &&
            isFreshExactEarlyNtkImageUrl(target, image) &&
            index in (start - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)..(start + NTK_PRE_ANCHOR_VERIFIED_GENERATED_AHEAD)
        ) {
            Log.d(
                TAG,
                "reader_ntk_pre_anchor_stream_allowed_by_early_url page=$index,start=$start," +
                    "source=$source,image=${image.orEmpty().substringAfterLast('/')}"
            )
            ViewerWarmupManager.logMetric("reader_ntk_pre_anchor_stream_allowed_by_early_url", index.toLong())
            return true
        }
        return ntkCoordinator?.assertForegroundStreamPermit(index, permit, image, source) ?: true
    }

    private fun initialAdjacentGeneratedDecodeYieldMs(index: Int, page: PageRef, anchor: Boolean): Long {
        if (anchor) return 0L
        if (!isNtkSource(page.manga, title)) return 0L
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return 0L
        val start = currentStartPage()
        if (index !in (start + 1)..(start + NTK_INITIAL_DIRECT_DELIVERY_PAGES)) return 0L
        if (
            isImmediateNtkGeneratedUx() &&
            !firstBitmapLogged.get() &&
            isNtkManhwaEpisodePath(page.manga.ntkEpisodePath) &&
            index <= start + NTK_INITIAL_PRE_FIRST_MANHWA_DECODE_PAGES
        ) {
            return 0L
        }
        if (
            index < start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES &&
            (isFreshExactEarlyNtkImageUrl(page.manga, page.image) ||
                hasFreshEarlyNtkImageUrlFor(page.manga, page.image, requireExact = false) ||
                ReaderImageCache.hasActiveInitialNtkGeneratedFetch(page.manga, page.image))
        ) {
            return 0L
        }
        page.image?.let { image ->
            if (ReaderImageCache.cachedFile(appContext, page.manga, image) != null) return 0L
        }
        val firstBitmapAt = ntkFirstBitmapAtMs.get()
        if (firstBitmapLogged.get() && firstBitmapAt > 0L) {
            if (isNtkManhwaEpisodePath(page.manga.ntkEpisodePath)) return 0L
            if (isNtkWebtoonEpisodePath(page.manga.ntkEpisodePath)) return 0L
            val quietMs = readerQuietRemainingMs(NTK_INITIAL_ADJACENT_DECODE_TOUCH_QUIET_MS)
            val initialQuietMs = (
                NTK_INITIAL_ADJACENT_DECODE_AFTER_FIRST_QUIET_MS -
                    (SystemClock.uptimeMillis() - firstBitmapAt)
                ).coerceAtLeast(0L)
            return max(quietMs, initialQuietMs)
        }
        if (hasDeliveredBitmap(start) || (pendingDeliveryWidths[start] ?: 0) > 0) return 0L
        return if (loading.contains(start) || urgentLoading.contains(start)) {
            NTK_PRE_ANCHOR_FALLBACK_RETRY_MS
        } else {
            0L
        }
    }

    private fun scheduleInitialAdjacentGeneratedDecodeRetry(
        index: Int,
        page: PageRef,
        generation: Int,
        delayMs: Long
    ) {
        if (!initialAdjacentDecodeRetries.add(index)) return
        main.postDelayed({
            initialAdjacentDecodeRetries.remove(index)
            if (cancelled.get()) return@postDelayed
            val latest = pageRef(index) ?: return@postDelayed
            if (!sameNtkSourceSlot(page, latest)) return@postDelayed
            requestPage(index, busy = true, anchor = false, generation = generation)
        }, delayMs.coerceIn(NTK_PRE_ANCHOR_FALLBACK_RETRY_MS, NTK_INITIAL_ADJACENT_DECODE_RETRY_MAX_MS))
    }

    private fun sameNtkSourceSlot(expected: PageRef, actual: PageRef): Boolean {
        if (expected.transitionTitle != actual.transitionTitle) return false
        if (expected.sourceIndex != actual.sourceIndex) return false
        return Manga.sameEpisodeIdentity(expected.manga, actual.manga)
    }

    private fun scheduleForegroundPrimeHedge(index: Int) {
        main.postDelayed({
            if (cancelled.get()) return@postDelayed
            if (!loading.contains(index) || hasDeliveredBitmap(index)) return@postDelayed
            requestPage(index, busy = true, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
        }, NTK_FOREGROUND_PRIME_HEDGE_DELAY_MS)
    }

    private fun shouldHedgeForegroundPrime(index: Int): Boolean {
        if (!isNtkSource(manga, title)) return false
        val first = currentStartPage()
        val hedgeFirst = first + NTK_INITIAL_PRIORITY_PAGES + 1
        val hedgeLast = minOf(
            first + NTK_INITIAL_DECODE_AHEAD_PAGES,
            first + NTK_INITIAL_PRIORITY_PAGES + NTK_PRIMED_EPISODE_PRIORITY_PAGES
        )
        return index in hedgeFirst..hedgeLast
    }

    private fun clearStaleLoadStateForIndex(index: Int, page: PageRef) {
        loadingPages[index]?.let { loadingPage ->
            if (loadingPage !== page) {
                loadingPages.remove(index, loadingPage)
                loading.remove(index)
                inFlightWidths.remove(index)
                loadingStartedAtMs.remove(index)
            }
        }
        urgentLoadingPages[index]?.let { urgentPage ->
            if (urgentPage !== page) {
                urgentLoadingPages.remove(index, urgentPage)
                urgentLoading.remove(index)
            }
        }
    }

    private fun shouldRestartVisibleActiveRequest(
        index: Int,
        page: PageRef,
        anchor: Boolean,
        activeAgeMs: Long
    ): Boolean {
        if (!isNtkSource(page.manga, title)) return true
        if (isImmediateNtkGeneratedUx() &&
            isNtkGeneratedImageUrl(page.image.orEmpty()) &&
            isActiveGeneratedTouchOrQuiet()
        ) {
            logNtkPagePerf(
                index,
                "visible_active_restart_defer_active_input",
                "anchor=$anchor,ageMs=$activeAgeMs"
            )
            return false
        }
        if (anchor || index == currentStartPage()) return activeAgeMs >= NTK_VISIBLE_ANCHOR_RESTART_MIN_MS
        if (shouldUseInitialGeneratedCachedDecodeGuard(index, page)) {
            return activeAgeMs >= NTK_VISIBLE_INITIAL_CONTINUOUS_RESTART_MIN_MS
        }
        return activeAgeMs >= NTK_VISIBLE_ACTIVE_RESTART_MIN_MS
    }

    private fun clearPageLoadState(index: Int, page: PageRef, ownsLoading: Boolean, urgent: Boolean) {
        if (ownsLoading && loadingPages[index] === page) {
            loadingPages.remove(index, page)
            loading.remove(index)
            inFlightWidths.remove(index)
            loadingStartedAtMs.remove(index)
        }
        if (urgent && urgentLoadingPages[index] === page) {
            urgentLoadingPages.remove(index, page)
            urgentLoading.remove(index)
        }
    }

    private fun prefetchBusyPage(index: Int, page: PageRef, generation: Int) {
        if (skipKnownMissingNtkGeneratedPage(index, page, "byte_prefetch")) return
        if (
            isImmediateNtkGeneratedUx() &&
            isNtkGeneratedDescriptorOrImagePage(page) &&
            isActiveGeneratedTouchOrQuiet()
        ) {
            val activeAnchor = currentViewportAnchor.get()
                .takeIf { it >= 0 }
                ?: currentStartPage()
            if (index !in activeAnchor..(activeAnchor + NTK_ACTIVE_GENERATED_SOURCE_PREFETCH_AFTER)) {
                return
            }
        }
        if (isImmediateNtkGeneratedUx() &&
            isNtkGeneratedImageUrl(page.image.orEmpty()) &&
            ntkBackgroundWarmQuietRemainingMs() > 0L
        ) {
            logNtkPagePerf(index, "byte_prefetch_defer_scroll_quiet", "generation=$generation")
            return
        }
        if (
            hasDeliveredBitmap(index) ||
            loading.contains(index) ||
            urgentLoading.contains(index) ||
            (pendingDeliveryWidths[index] ?: 0) > 0
        ) {
            return
        }
        if (shouldDeferInitialInteractiveGeneratedBackground(index, page, generation)) return
        if (isNtkSource(page.manga, title) && isNtkGeneratedImageUrl(page.image.orEmpty())) {
            if (hasPageSourceReady(index, page)) {
                decodeInitialContinuousCachedAfterSource(index, page, "byte_prefetch_cached", SystemClock.elapsedRealtime())
                logNtkPagePerf(index, "byte_prefetch_skip_source_ready", "generation=$generation")
                return
            }
            val lastDoneAt = bytePrefetchCompletedAtMs[index] ?: 0L
            if (lastDoneAt > 0L &&
                SystemClock.elapsedRealtime() - lastDoneAt < NTK_BYTE_PREFETCH_REPEAT_SUPPRESS_MS
            ) {
                logNtkPagePerf(
                    index,
                    "byte_prefetch_skip_recent",
                    "generation=$generation,ageMs=${SystemClock.elapsedRealtime() - lastDoneAt}"
                )
                return
            }
        }
        if (!bytePrefetching.add(index)) return
        try {
            network.execute {
                val startedAt = SystemClock.elapsedRealtime()
                try {
                    if (!shouldSkipStalePage(index, generation, false)) {
                        prefetchImageFile(
                            index,
                            page,
                            foreground = false,
                            visiblePriority = false
                        )
                        bytePrefetchCompletedAtMs[index] = SystemClock.elapsedRealtime()
                        logNtkPagePerf(index, "byte_prefetch_done", "ms=${SystemClock.elapsedRealtime() - startedAt}")
                        decodeInitialContinuousCachedAfterSource(index, page, "byte_prefetch", startedAt)
                        decodeFullSurfaceCachedAfterSource(index, page, "byte_prefetch", startedAt)
                    }
                } catch (e: Exception) {
                    if (isExpectedCancellation(e)) {
                        logNtkPagePerf(index, "byte_prefetch_cancelled", "ms=${SystemClock.elapsedRealtime() - startedAt}")
                    } else {
                        logNtkPagePerf(index, "byte_prefetch_error", "ms=${SystemClock.elapsedRealtime() - startedAt},error=${e.javaClass.simpleName}")
                        if (isNtkGeneratedImageUrl(page.image.orEmpty()) && isImageNotFoundError(e)) {
                            postPageError(index, page, e)
                        }
                        recordIfUnexpected(e)
                    }
                } finally {
                    bytePrefetching.remove(index)
                }
            }
        } catch (_: RejectedExecutionException) {
            bytePrefetching.remove(index)
        }
    }

    private fun decodeInitialContinuousCachedAfterSource(
        index: Int,
        page: PageRef,
        reason: String,
        sourceStartedAt: Long
    ) {
        if (!isNtkSource(page.manga, title)) return
        if (pageRef(index) != page) return
        if (hasDeliveredBitmap(index) || (pendingDeliveryWidths[index] ?: 0) > 0) return
        val start = currentStartPage()
        if (index !in (start + 1)..(start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1)) return
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return
        Log.d(
            TAG,
            "reader_initial_continuous_cached_decode_after_source page=$index," +
                "start=$start,reason=$reason"
        )
        val proofDrawable = shouldUseImmediateGeneratedProofDrawable(page)
        scheduleVisibleGeneratedCachedDecode(
            index,
            page,
            "initial_continuous_$reason",
            sourceStartedAt,
            forceRequeue = proofDrawable,
            proofDrawable = proofDrawable,
            allowOutsideProofWindow = proofDrawable
        )
    }

    private fun decodeFullSurfaceCachedAfterSource(
        index: Int,
        page: PageRef,
        reason: String,
        sourceStartedAt: Long
    ) {
        if (!isNtkSource(page.manga, title)) return
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return
        if (pageRef(index) != page) return
        if (hasDeliveredBitmap(index) || (pendingDeliveryWidths[index] ?: 0) > 0) return
        val count = synchronized(pagesLock) { pages.size }
        if (count <= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES || count > NTK_FULL_SURFACE_WARM_MAX_PAGES) return
        if (
            isImmediateNtkGeneratedUx() &&
            (
                reason == "byte_prefetch" ||
                    reason.startsWith("generated_full_decode") ||
                    reason.startsWith("interactive_full_source") ||
                    reason.startsWith("current_full_before_next") ||
                    reason.contains("runway", ignoreCase = true)
            )
        ) {
            logNtkPagePerf(index, "full_surface_cached_decode_skip_source_only", "reason=$reason")
            return
        }
        if (reason.startsWith("append_full") || reason.startsWith("append_source")) {
            logNtkPagePerf(index, "full_surface_cached_decode_skip_append_source", "reason=$reason")
            return
        }
        if (isImmediateNtkGeneratedUx() && isActiveGeneratedTouchOrQuiet()) {
            logNtkPagePerf(index, "full_surface_cached_decode_defer_active", "reason=$reason")
            return
        }
        if (reason == "byte_prefetch" && ntkBackgroundWarmQuietRemainingMs() > 0L) {
            logNtkPagePerf(index, "full_surface_cached_decode_defer_scroll_quiet", "reason=$reason")
            return
        }
        if (shouldDeferGeneratedFullSurfaceWorkForInitialContinuous()) {
            val start = currentStartPage()
            if (index !in start until start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) {
                logNtkPagePerf(index, "full_surface_cached_decode_defer_initial_continuous", "reason=$reason")
                return
            }
        }
        Log.d(
            TAG,
            "reader_full_surface_cached_decode_after_source page=$index,total=$count,reason=$reason"
        )
        scheduleVisibleGeneratedCachedDecode(index, page, "full_surface_$reason", sourceStartedAt)
    }

    private fun decodeInteractiveGeneratedProofAfterSource(
        index: Int,
        page: PageRef,
        reason: String,
        sourceStartedAt: Long
    ) {
        if (!isInInteractiveProofWindow(index, page)) return
        if (hasDeliveredBitmap(index) && (decodedWidths[index] ?: 0) >= ntkProofTargetWidth()) return
        scheduleVisibleGeneratedCachedDecode(
            index,
            page,
            "interactive_full_$reason",
            sourceStartedAt,
            forceRequeue = true,
            proofDrawable = true
        )
    }

    private fun shouldDecodeAfterNtkSourcePrefetch(index: Int, reason: String): Boolean {
        if (!reason.startsWith("interactive_full_source")) return true
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        val radius = if (
            isImmediateNtkGeneratedUx() &&
            firstBitmapLogged.get() &&
            isActiveGeneratedTouchOrQuiet()
        ) {
            NTK_INTERACTIVE_FULL_SOURCE_ACTIVE_DECODE_RADIUS
        } else if (isKnownFullGeneratedEpisodeInstalled()) {
            NTK_INTERACTIVE_FULL_SOURCE_KNOWN_DECODE_RADIUS
        } else {
            NTK_INTERACTIVE_FULL_SOURCE_DECODE_RADIUS
        }
        return index in max(0, anchor - radius)..(anchor + radius)
    }

    private fun isKnownFullGeneratedEpisodeInstalled(): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        val known = manga.ntkImageCount
        if (known <= NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return false
        val currentPath = manga.ntkEpisodePath?.trim().orEmpty()
        return synchronized(pagesLock) {
            pages.count { ref ->
                if (ref.transitionTitle != null) {
                    false
                } else if (Manga.sameEpisodeIdentity(ref.manga, manga)) {
                    true
                } else {
                    val refPath = ref.manga.ntkEpisodePath?.trim().orEmpty()
                    currentPath.isNotEmpty() && currentPath == refPath
                }
            } >= known
        }
    }

    private fun promoteVisibleGeneratedCachedDecode(index: Int, page: PageRef, reason: String): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedPageRef(index)) return false
        if (hasDeliveredOrPendingDrawable(index) || hasListenerDrawableDelivery(index, page)) return false
        if (!isVisibleGeneratedDecodeEligible(index, page)) return false
        return scheduleVisibleGeneratedCachedDecode(
            index,
            page,
            "visible_$reason",
            SystemClock.elapsedRealtime(),
            forceRequeue = true
        )
    }

    private fun isVisibleGeneratedDecodeEligible(index: Int, page: PageRef): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return false
        val start = currentStartPage().coerceIn(0, count - 1)
        val viewportAnchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?.coerceIn(0, count - 1)
            ?: start
        val activeInput = firstBitmapLogged.get() &&
            isImmediateNtkGeneratedUx() &&
            (viewportBusy.get() ||
                ntkInitialInteractiveSettleRemainingMs() > 0L ||
                readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L)
        val firstEligible = if (activeInput) {
            max(0, viewportAnchor - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)
        } else {
            start
        }
        val lastEligible = if (activeInput) {
            minOf(count - 1, viewportAnchor + initialContinuousViewportAheadPages())
        } else {
            minOf(count - 1, start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1)
        }
        return index in firstEligible..lastEligible
    }

    private fun shouldUseImmediateGeneratedProofDrawable(page: PageRef): Boolean {
        return isImmediateNtkGeneratedUx() &&
            isNtkSource(page.manga, title) &&
            isNtkGeneratedDescriptorOrImagePage(page) &&
            isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)
    }

    private fun ntkProofTargetWidth(): Int {
        val view = max(1, viewerWidth)
        if (isImmediateNtkGeneratedUx()) return view
        val readable = max(384, view * NTK_PROOF_WIDTH_PERMILLE / 1000)
        return minOf(view, minOf(readable, NTK_PROOF_MAX_WIDTH))
    }

    private fun isInInteractiveProofWindow(index: Int, page: PageRef): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (!firstBitmapLogged.get()) {
            val count = synchronized(pagesLock) { pages.size }
            if (count <= 0) return false
            val start = currentStartPage().coerceIn(0, count - 1)
            val ahead = NTK_INITIAL_PRE_FIRST_MANHWA_DECODE_PAGES
            val first = max(0, start - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)
            return index in first..minOf(count - 1, start + ahead)
        }
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return false
        val start = currentStartPage().coerceIn(0, count - 1)
        val initialFirst = max(0, start - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)
        if (!initialContinuousDrawableDelivered(start)) {
            val preinputLast = minOf(count - 1, start + NTK_INITIAL_PREINPUT_PROOF_AHEAD_PAGES)
            if (index in initialFirst..preinputLast) return true
        }
        val active = viewportBusy.get() ||
            ntkInitialInteractiveSettleRemainingMs() > 0L ||
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L
        if (!active) return false
        val initialLast = minOf(count - 1, start + initialContinuousViewportAheadPages())
        if (index in initialFirst..initialLast) return true
        val anchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?.coerceIn(0, count - 1)
            ?: start
        return index in max(0, anchor - NTK_INTERACTIVE_PROOF_BEHIND_PAGES)..
            minOf(count - 1, anchor + activeGeneratedProofAheadPages())
    }

    private fun shouldRouteActiveGeneratedToProof(index: Int, page: PageRef): Boolean {
        if (!isInInteractiveProofWindow(index, page)) return false
        val proofWidth = ntkProofTargetWidth()
        if ((decodedWidths[index] ?: 0) >= proofWidth && hasDeliveredOrPendingDrawable(index)) return false
        return !hasDeliveredOrPendingDrawable(index) && !hasListenerDrawableDelivery(index, page)
    }

    private fun startInitialInteractiveRunwayByteFetch(
        index: Int,
        page: PageRef,
        reason: String,
        forceProofDrawable: Boolean = false,
        allowOutsideProofWindow: Boolean = false
    ): Boolean {
        if (cancelled.get() || pageRef(index) != page) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(page.manga, title)) return false
        val image = page.image ?: return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        if (routeStrictAdjacentExactRehydrate(index, page, visibleIntent = true)) return true
        val proofDrawable = forceProofDrawable ||
            allowOutsideProofWindow ||
            reason.contains("blocked", ignoreCase = true) ||
            reason.contains("forward_cap", ignoreCase = true) ||
            reason.contains("proof", ignoreCase = true) ||
            (
                firstBitmapLogged.get() &&
                    isInInteractiveProofWindow(index, page) &&
                    !reason.contains("runway", ignoreCase = true) &&
                    !reason.contains("source", ignoreCase = true)
                )
        val sourceOnlyRunway = !proofDrawable &&
            (
                reason.contains("runway", ignoreCase = true) ||
                    reason.contains("source", ignoreCase = true) ||
                    reason.contains("byte_prefetch", ignoreCase = true) ||
                    reason.contains("input_grace", ignoreCase = true)
                )
        if (sourceOnlyRunway && shouldSkipImmediateGeneratedSourceOnlyRunway(reason)) {
            logNtkPagePerf(index, "initial_interactive_runway_source_only_skip", "reason=$reason")
            return false
        }
        if (hasPageSourceReady(index, page)) {
            if (!forceProofDrawable) return true
            return scheduleVisibleGeneratedCachedDecode(
                index,
                page,
                reason,
                SystemClock.elapsedRealtime(),
                forceRequeue = true,
                proofDrawable = true,
                allowOutsideProofWindow = allowOutsideProofWindow
            )
        }
        if (ReaderImageCache.hasActiveInitialNtkGeneratedFetch(page.manga, image)) {
            val startedAt = SystemClock.elapsedRealtime()
            val previewStarted = if (proofDrawable) {
                ReaderImageCache.startVisibleInitialGeneratedPreviewFetch(
                    appContext,
                    page.manga,
                    image,
                    imageCancellation,
                    index
                )
            } else {
                false
            }
            val joinReason = if (previewStarted) {
                "${reason}_join_active_fetch_preview"
            } else {
                "${reason}_join_active_fetch"
            }
            if (!sourceOnlyRunway) {
                registerInitialGeneratedAssetCachedDecode(
                    index,
                    page,
                    joinReason,
                    startedAt,
                    proofDrawable = proofDrawable,
                    allowOutsideProofWindow = allowOutsideProofWindow
                )
                scheduleVisibleGeneratedCachedDecodeRetry(
                    index,
                    page,
                    joinReason,
                    startedAt,
                    proofDrawable,
                    allowOutsideProofWindow = allowOutsideProofWindow
                )
            }
            logNtkPagePerf(
                index,
                "initial_interactive_runway_join_active_fetch",
                "reason=$reason,proof=$proofDrawable,previewStarted=$previewStarted"
            )
            return true
        }
        if (!initialInteractiveRunwayByteFetches.add(index)) {
            if (!forceProofDrawable) return false
            val startedAt = SystemClock.elapsedRealtime()
            val registered = registerInitialGeneratedAssetCachedDecode(
                index,
                page,
                "${reason}_join",
                startedAt,
                proofDrawable = true,
                allowOutsideProofWindow = allowOutsideProofWindow
            )
            scheduleVisibleGeneratedCachedDecodeRetry(
                index,
                page,
                "${reason}_join",
                startedAt,
                proofDrawable = true,
                allowOutsideProofWindow = allowOutsideProofWindow
            )
            return registered
        }
        val permit = ntkCoordinator?.imagePermit(
            index,
            page.manga,
            image,
            NtkImageLane.FOLLOWING_VISIBLE,
            "initialInteractiveRunwayByteFetch"
        )
        if (!ntkCoordinatorAllowsStream(index, page, permit, "initialInteractiveRunwayByteFetch")) {
            initialInteractiveRunwayByteFetches.remove(index)
            return false
        }
        val started = startBoundedForegroundStreamFetch(
            appContext,
            page.manga,
            image,
            imageCancellation,
            false,
            permit,
            index,
            true
        )
        logNtkPagePerf(
            index,
            "initial_interactive_runway_byte_fetch",
            "reason=$reason,started=$started,image=${image.substringAfterLast('/')}"
        )
        if (started) {
            val startedAt = SystemClock.elapsedRealtime()
            if (sourceOnlyRunway) {
                logNtkPagePerf(index, "initial_interactive_runway_source_only", "reason=$reason")
            } else {
                registerInitialGeneratedAssetCachedDecode(
                    index,
                    page,
                    "${reason}_runway_bytes",
                    startedAt,
                    proofDrawable = proofDrawable,
                    allowOutsideProofWindow = allowOutsideProofWindow
                )
                scheduleVisibleGeneratedCachedDecodeRetry(
                    index,
                    page,
                    "${reason}_runway_bytes",
                    startedAt,
                    proofDrawable,
                    allowOutsideProofWindow = allowOutsideProofWindow
                )
            }
        } else {
            initialInteractiveRunwayByteFetches.remove(index)
        }
        return started
    }

    private fun shouldSkipImmediateGeneratedSourceOnlyRunway(reason: String): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        val urgentVisibleRunway =
            reason.contains("forward_cap", ignoreCase = true) ||
                reason.contains("blocked", ignoreCase = true) ||
                reason.contains("throttled_source", ignoreCase = true) ||
                reason.contains("active_scroll_window", ignoreCase = true) ||
                reason.contains("rolling_runway", ignoreCase = true) ||
                reason.contains("generated_limited_warm_active", ignoreCase = true)
        if (urgentVisibleRunway) return false
        if (viewportBusy.get()) return true
        if (ntkInitialInteractiveSettleRemainingMs() > 0L) return true
        if (readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L) return true
        return reason.startsWith("first_bitmap_followups_immediate", ignoreCase = true) ||
            reason.startsWith("generated_full", ignoreCase = true) ||
            reason.contains("active_source", ignoreCase = true) ||
            reason.contains("rolling_runway", ignoreCase = true) ||
            reason.contains("input_grace", ignoreCase = true) ||
            reason.contains("byte_prefetch", ignoreCase = true)
    }

    private fun primeInitialInteractiveRunwayBytes(reason: String) {
        if (!isImmediateNtkGeneratedUx()) return
        val activeInputGrace = reason.contains("input_grace", ignoreCase = true)
        val activeTouch = isActiveGeneratedTouchOrQuiet()
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty()) return
        val start = currentStartPage().coerceIn(0, refs.lastIndex)
        val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 }?.coerceIn(0, refs.lastIndex) ?: start
        val runwayStart = if (activeInputGrace && activeTouch) viewportAnchor else start
        if (activeInputGrace && activeTouch) {
            Log.d(
                TAG,
                "reader_initial_interactive_runway_bytes_active_input reason=$reason," +
                    "start=$start,viewport=$viewportAnchor,runwayStart=$runwayStart,busy=${viewportBusy.get()}"
            )
        }
        val reasonKey = "${initialContinuousFollowupBaseReason(reason)}@$runwayStart"
        val now = SystemClock.elapsedRealtime()
        val lastKey = lastInitialInteractiveRunwayReasonKey.get()
        val lastAt = lastInitialInteractiveRunwayAtMs.get()
        if (reasonKey == lastKey && now - lastAt < NTK_INITIAL_INTERACTIVE_RUNWAY_REPEAT_SUPPRESS_MS) {
            return
        }
        lastInitialInteractiveRunwayReasonKey.set(reasonKey)
        lastInitialInteractiveRunwayAtMs.set(now)
        if (
            activeInputGrace &&
            (isWithinFirstBitmapInputGrace() || activeTouch)
        ) {
            Log.d(
                TAG,
                "reader_initial_interactive_runway_bytes_run_during_input_grace reason=$reason," +
                    "start=$start,viewport=$viewportAnchor,runwayStart=$runwayStart,busy=${viewportBusy.get()}"
            )
        }
        val runwayPages = if (activeInputGrace) {
            interactiveProofAheadPages() + 1
        } else {
            NTK_INITIAL_INTERACTIVE_RUNWAY_PAGES
        }
        val last = minOf(refs.lastIndex, runwayStart + runwayPages - 1)
        if (last < runwayStart) return
        var started = 0
        for (index in runwayStart..last) {
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!isNtkGeneratedImageUrl(page.image.orEmpty())) continue
            val inputGraceProof =
                activeInputGrace &&
                    index <= runwayStart + interactiveProofAheadPages()
            if (hasDeliveredBitmap(index)) {
                if (inputGraceProof && tryRedeliverRetainedGeneratedDrawable(index, page, reason)) {
                    started++
                }
                continue
            }
            if (hasPageSourceReady(index, page)) {
                if (inputGraceProof &&
                    scheduleVisibleGeneratedCachedDecode(
                        index,
                        page,
                        reason,
                        now,
                        forceRequeue = true,
                        proofDrawable = true,
                        allowOutsideProofWindow = true
                    )
                ) {
                    started++
                }
                continue
            }
            if (startInitialInteractiveRunwayByteFetch(
                    index,
                    page,
                    reason,
                    forceProofDrawable = inputGraceProof,
                    allowOutsideProofWindow = inputGraceProof
                )
            ) {
                started++
            }
        }
        Log.d(
            TAG,
            "reader_initial_interactive_runway_bytes reason=$reason,start=$start," +
                "viewport=$viewportAnchor,runwayStart=$runwayStart,last=$last,started=$started"
        )
    }

    private fun hedgeVisibleGeneratedByteFetch(index: Int, page: PageRef, reason: String, delayMs: Long = 0L) {
        if (routeStrictAdjacentExactRehydrate(index, page, visibleIntent = true)) return
        if (shouldSuppressTrustedManifestGeneratedFallback(index, page, "visible_byte_hedge_$reason")) return
        val initialAnchor = !firstBitmapLogged.get() && index == currentStartPage()
        val initialContinuousVisible =
            shouldUseInitialGeneratedCachedDecodeGuard(index, page) ||
                shouldUseInitialGeneratedStreamRunwayGuard(index, page)
        if (!firstBitmapLogged.get() &&
            !initialAnchor &&
            !initialContinuousVisible &&
            isNtkGeneratedImageUrl(page.image.orEmpty())
        ) {
            logNtkPagePerf(index, "visible_generated_byte_hedge_defer_anchor_exclusive", "reason=$reason")
            return
        }
        if (!firstBitmapLogged.get() && !initialAnchor && !initialContinuousVisible) return
        if (!isNtkSource(page.manga, title)) return
        if (!isNtkGeneratedPageRef(index)) return
        if (skipKnownMissingNtkGeneratedPage(index, page, "visible_byte_hedge_$reason")) return
        if (shouldSuppressFarInitialGeneratedVisibleActiveDecode(index, page)) {
            logNtkPagePerf(
                index,
                "visible_generated_byte_hedge_suppressed_active_far",
                "reason=$reason,anchor=${currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()}"
            )
            return
        }
        if (hasDeliveredBitmap(index) || (pendingDeliveryWidths[index] ?: 0) > 0) return
        if (!firstBitmapLogged.get() && !initialAnchor && isImmediateNtkGeneratedUx()) {
            val preFirstLast = currentStartPage() + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
            if (index > preFirstLast) {
                logNtkPagePerf(
                    index,
                    "visible_generated_byte_hedge_defer_pre_first_window",
                    "reason=$reason,last=$preFirstLast"
                )
                return
            }
        }
        if (!initialAnchor && initialContinuousVisible && shouldLimitImmediateGeneratedToViewport() &&
            !isImmediateNtkGeneratedUx()
        ) {
            logNtkPagePerf(index, "visible_generated_byte_hedge_defer_input_viewport", "reason=$reason")
            return
        }
        if (
            initialContinuousVisible &&
            (initialGeneratedDirectDecodeInFlight.contains(index) ||
                initialGeneratedCachedDecodeInFlight.contains(index) ||
                visibleGeneratedDecodeHedges.contains(index) ||
                (loading.contains(index) && loadingPages[index] === page))
        ) {
            registerInitialGeneratedAssetCachedDecode(
                index,
                page,
                "${reason}_active_owner",
                SystemClock.elapsedRealtime()
            )
            if (firstBitmapLogged.get() && isVisibleGeneratedDeliveryTarget(index)) {
                val previewStarted = startActiveGeneratedProofPreview(
                    index,
                    page,
                    page.image.orEmpty(),
                    "${reason}_active_owner"
                )
                logNtkPagePerf(
                    index,
                    "visible_generated_active_owner_preview_race",
                    "reason=$reason,started=$previewStarted"
                )
            }
            logNtkPagePerf(index, "visible_generated_byte_hedge_skip_active_owner", "reason=$reason")
            return
        }
        if (!initialAnchor && !initialContinuousVisible && (loading.contains(index) || urgentLoading.contains(index))) return
        if (!visibleGeneratedByteHedges.add(index)) return
        if (delayMs > 0L) {
            main.postDelayed({
                if (cancelled.get() ||
                    pageRef(index) != page ||
                    hasDeliveredBitmap(index) ||
                    (pendingDeliveryWidths[index] ?: 0) > 0
                ) {
                    visibleGeneratedByteHedges.remove(index)
                    return@postDelayed
                }
                runVisibleGeneratedByteHedge(index, page, reason, delayMs)
            }, delayMs)
            return
        }
        runVisibleGeneratedByteHedge(index, page, reason, delayMs)
    }

    private fun runVisibleGeneratedByteHedge(index: Int, page: PageRef, reason: String, delayMs: Long) {
        try {
            urgentNetwork.execute {
                val startedAt = SystemClock.elapsedRealtime()
                try {
                    if (!cancelled.get() && pageRef(index) == page && !hasDeliveredBitmap(index)) {
                        if (!isVisibleGeneratedDecodeEligible(index, page)) {
                            logNtkPagePerf(index, "visible_generated_byte_hedge_skip", "reason=$reason,outside_visible_gate=true")
                            visibleGeneratedByteHedges.remove(index)
                            return@execute
                        }
                        if (
                            initialGeneratedDirectDecodeInFlight.contains(index) ||
                            initialGeneratedCachedDecodeInFlight.contains(index) ||
                            visibleGeneratedDecodeHedges.contains(index)
                        ) {
                            logNtkPagePerf(index, "visible_generated_byte_hedge_skip", "reason=$reason,decode_owner_exists=true")
                            visibleGeneratedByteHedges.remove(index)
                            return@execute
                        }
                        if (shouldSuppressFarInitialGeneratedVisibleActiveDecode(index, page)) {
                            logNtkPagePerf(
                                index,
                                "visible_generated_byte_hedge_run_suppressed_active_far",
                                "reason=$reason,anchor=${currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()}"
                            )
                            visibleGeneratedByteHedges.remove(index)
                            return@execute
                        }
                        if (shouldUseInitialGeneratedCachedDecodeGuard(index, page) ||
                            shouldUseInitialGeneratedStreamRunwayGuard(index, page)
                        ) {
                            val image = page.image
                            if (image.isNullOrBlank()) {
                                visibleGeneratedByteHedges.remove(index)
                                return@execute
                            }
                            val permit = ntkCoordinator?.imagePermit(
                                index,
                                page.manga,
                                image,
                                NtkImageLane.FOLLOWING_VISIBLE,
                                "visibleGeneratedByteHedge"
                            )
                            if (ReaderImageCache.hasActiveInitialNtkGeneratedFetch(page.manga, image)) {
                                val proofDrawable = shouldUseImmediateGeneratedProofDrawable(page)
                                registerInitialGeneratedAssetCachedDecode(
                                    index,
                                    page,
                                    "${reason}_active_fetch_join",
                                    startedAt,
                                    proofDrawable = proofDrawable,
                                    allowOutsideProofWindow = proofDrawable
                                )
                                scheduleVisibleGeneratedCachedDecodeRetry(
                                    index,
                                    page,
                                    "${reason}_active_fetch_join",
                                    startedAt,
                                    proofDrawable,
                                    allowOutsideProofWindow = proofDrawable
                                )
                                visibleGeneratedByteHedges.remove(index)
                                logNtkPagePerf(index, "visible_generated_preview_join_active_fetch", "reason=$reason")
                                return@execute
                            }
                            val started = startBoundedForegroundStreamFetch(
                                appContext,
                                page.manga,
                                image,
                                imageCancellation,
                                false,
                                permit,
                                index,
                                true
                            )
                            logNtkPagePerf(
                                index,
                                "visible_generated_preview_stream_start",
                                "reason=$reason,started=$started,delayMs=$delayMs,ms=${SystemClock.elapsedRealtime() - startedAt}"
                            )
                            if (started && firstBitmapLogged.get()) {
                                registerInitialGeneratedAssetCachedDecode(
                                    index,
                                    page,
                                    "${reason}_stream_asset",
                                    startedAt
                                )
                            }
                            if (!started) {
                                val previewStarted = ReaderImageCache.startVisibleInitialGeneratedPreviewFetch(
                                    appContext,
                                    page.manga,
                                    image,
                                    imageCancellation,
                                    index
                                )
                                logNtkPagePerf(
                                    index,
                                    "visible_generated_preview_range_start",
                                    "reason=$reason,started=$previewStarted,delayMs=$delayMs,ms=${SystemClock.elapsedRealtime() - startedAt}"
                                )
                                visibleGeneratedByteHedges.remove(index)
                                val cachedScheduled = scheduleVisibleGeneratedCachedDecode(
                                    index,
                                    page,
                                    if (previewStarted) "${reason}_range_preview" else reason,
                                    startedAt
                                )
                                if (!cachedScheduled) visibleGeneratedByteHedges.remove(index)
                            }
                            return@execute
                        }
                        prefetchImageFile(index, page, foreground = true, visiblePriority = true)
                        logNtkPagePerf(
                            index,
                            "visible_generated_byte_hedge_done",
                            "reason=$reason,delayMs=$delayMs,ms=${SystemClock.elapsedRealtime() - startedAt}"
                        )
                        val cachedScheduled = scheduleVisibleGeneratedCachedDecode(index, page, reason, startedAt)
                        if (!cachedScheduled) visibleGeneratedByteHedges.remove(index)
                    }
                } catch (e: Exception) {
                    if (isExpectedCancellation(e)) {
                        logNtkPagePerf(
                            index,
                            "visible_generated_byte_hedge_cancelled",
                            "reason=$reason,delayMs=$delayMs,ms=${SystemClock.elapsedRealtime() - startedAt}"
                        )
                    } else {
                        visibleGeneratedByteHedges.remove(index)
                        logNtkPagePerf(
                            index,
                            "visible_generated_byte_hedge_error",
                            "reason=$reason,delayMs=$delayMs,ms=${SystemClock.elapsedRealtime() - startedAt},error=${e.javaClass.simpleName}"
                        )
                        if (isNtkGeneratedImageUrl(page.image.orEmpty()) && isImageNotFoundError(e)) {
                            postPageError(index, page, e)
                        }
                        recordIfUnexpected(e)
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            visibleGeneratedByteHedges.remove(index)
        }
    }

    private fun scheduleVisibleGeneratedCachedDecode(
        index: Int,
        page: PageRef,
        reason: String,
        byteStartedAt: Long,
        forceRequeue: Boolean = false,
        proofDrawable: Boolean = false,
        allowOutsideProofWindow: Boolean = false,
        allowFullDuringActiveProof: Boolean = false
    ): Boolean {
        if (routeStrictAdjacentExactRehydrate(index, page, visibleIntent = true)) return true
        if (strictExactColdRolling) return false
        if (shouldSuppressTrustedManifestGeneratedFallback(index, page, "visible_cached_decode_$reason")) return false
        if (cancelled.get() || pageRef(index) != page) return false
        if (shouldKeepPreparedRunwayDecodeColdUntilInput(index, page)) return false
        if (adoptAuthoritativeListenerDrawable(index, page, "visible_cached_$reason")) return false
        if (joinActivePagePipelineProducer(index, page, "visible_cached_$reason")) return true
        if (usesProtectedNumericNtkPipeline(page) && !isInsideProtectedNumericBitmapWindow(index, page)) {
            if (!hasPageSourceReady(index, page)) {
                forcePrefetchNtkPageSource(
                    index,
                    page,
                    "immediate_full_source_bounded_cached_decode",
                    allowDuringInitialInteractive = true
                )
            }
            logNtkPagePerf(index, "visible_generated_cached_decode_skip", "reason=$reason,outside_bounded_window=true")
            return false
        }
        if (viewerActivated.get() && requiresAuthoritativeInlineTilePage(page) &&
            (physicalDeliveryLastPage < physicalDeliveryFirstPage ||
                index !in physicalDeliveryFirstPage..physicalDeliveryLastPage)
        ) {
            if (!hasPageSourceReady(index, page)) {
                forcePrefetchNtkPageSource(
                    index,
                    page,
                    "active_off_physical_byte_only",
                    allowDuringInitialInteractive = true
                )
            }
            logNtkPagePerf(index, "visible_generated_cached_decode_skip", "reason=$reason,off_physical=true")
            return false
        }
        val deliveredFullUpgrade =
            hasDeliveredBitmap(index) &&
                forceRequeue &&
                !proofDrawable &&
                deliveredLowResGeneratedDrawableWidth(index, page, targetWidth(page, false)).let {
                    it in 1 until ntkProofTargetWidth()
                }
        if (
            forceRequeue &&
            proofDrawable &&
            hasDeliveredBitmap(index) &&
            tryRedeliverRetainedGeneratedDrawable(index, page, "visible_cached_decode_$reason")
        ) {
            return true
        }
        if (hasDeliveredBitmap(index) && !deliveredFullUpgrade) return false
        val initialAnchor = !firstBitmapLogged.get() && index == currentStartPage()
        val initialContinuousGenerated = shouldUseInitialGeneratedCachedDecodeGuard(index, page)
        val activeGeneratedProofDecode =
            !proofDrawable &&
                !allowFullDuringActiveProof &&
                isActiveGeneratedTouchOrQuiet() &&
                isNtkGeneratedDescriptorOrImagePage(page) &&
                isInInteractiveProofWindow(index, page)
        val preFirstInitialContinuousProofDecode =
            !proofDrawable &&
                !allowFullDuringActiveProof &&
                initialContinuousGenerated &&
                !firstBitmapLogged.get() &&
                index > currentStartPage()
        val effectiveProofDrawable = proofDrawable ||
            activeGeneratedProofDecode ||
            preFirstInitialContinuousProofDecode
        if (effectiveProofDrawable &&
            requiresAuthoritativeInlineTilePage(page) &&
            !hasDeliveredBitmap(index)
        ) {
            // Monotonic until the exact authoritative tiles are installed. A proof request may
            // arrive while the same original decode is running or between queue insertion and
            // promotion; preserving this intent closes both races without a duplicate decode.
            synchronized(indexedStateLock) {
                strictInlineProofDeliveryIntents.add(index)
            }
        }
        val activeDecodeWidth = inFlightWidths[index] ?: 0
        if (
            effectiveProofDrawable &&
            loading.contains(index) &&
            loadingPages[index] === page &&
            activeDecodeWidth >= ntkProofTargetWidth()
        ) {
            // A full-quality decode for this exact page is already running. Starting the proof
            // path as well creates the same native-width tiles twice and puts both deliveries on
            // the main queue during the gesture. Join the real in-flight decode; it remains free
            // to commit as soon as it completes and scrolling is never gated.
            logNtkPagePerf(
                index,
                "visible_generated_cached_decode_join_full",
                "reason=$reason,active=$activeDecodeWidth,target=${ntkProofTargetWidth()}"
            )
            return true
        }
        val pendingWidth = pendingDeliveryWidths[index] ?: 0
        if (pendingWidth > 0) {
            if (strictInlineProofJoinsPendingOriginalPolicy(
                    requiresAuthoritativeInlineTilePage(page),
                    effectiveProofDrawable,
                    pendingWidth
                )
            ) {
                // Strict inline proof/full requests both resolve to the same immutable
                // sample-1/original-source-tile identity. Join the queued winner instead of spending
                // the two-thread protected decode gate on a duplicate page, but promote its
                // scheduling intent so already-decoded pixels cannot remain behind the finger.
                val promoted = promotePendingStrictInlineOriginalToProof(index, page, reason)
                logNtkPagePerf(
                    index,
                    "strict_inline_proof_join_pending_original",
                    "reason=$reason,pending=$pendingWidth,promoted=$promoted"
                )
                return true
            }
            val allowProofOverPendingFull =
                effectiveProofDrawable &&
                    !hasDeliveredBitmap(index) &&
                    pendingWidth > ntkProofTargetWidth()
            if (!allowProofOverPendingFull) return false
        }
        val gatedGenerated = initialAnchor || initialContinuousGenerated
        val initialSurfaceGenerated = isInitialSurfaceGeneratedPage(index, page)
        val inCurrentPhysicalWindow = physicalDeliveryLastPage >= physicalDeliveryFirstPage &&
            index in physicalDeliveryFirstPage..physicalDeliveryLastPage
        if (effectiveProofDrawable &&
            !allowOutsideProofWindow &&
            !preFirstInitialContinuousProofDecode &&
            !isInInteractiveProofWindow(index, page) &&
            !(viewerActivated.get() && inCurrentPhysicalWindow)
        ) {
            logNtkPagePerf(index, "visible_generated_cached_decode_skip", "reason=$reason,outside_proof_gate=true")
            return false
        }
        if (
            gatedGenerated &&
            !effectiveProofDrawable &&
            !allowFullDuringActiveProof &&
            !isVisibleGeneratedDecodeEligible(index, page) &&
            !initialSurfaceGenerated
        ) {
            logNtkPagePerf(index, "visible_generated_cached_decode_skip", "reason=$reason,outside_visible_gate=true")
            return false
        }
        if (
            gatedGenerated &&
            !effectiveProofDrawable &&
            !allowFullDuringActiveProof &&
            initialGeneratedDirectDecodeInFlight.contains(index) &&
            !initialSurfaceGenerated
        ) {
            logNtkPagePerf(index, "visible_generated_cached_decode_skip", "reason=$reason,direct_in_flight=true")
            return false
        }
        if (gatedGenerated && !effectiveProofDrawable && initialGeneratedCachedDecodeInFlight.contains(index)) {
            logNtkPagePerf(index, "visible_generated_cached_decode_skip", "reason=$reason,initial_in_flight=true")
            return false
        }
        val image = page.image ?: return false
        val cached = ReaderImageCache.cachedFile(appContext, page.manga, image) ?: run {
            val registered = registerInitialGeneratedAssetCachedDecode(
                index,
                page,
                reason,
                byteStartedAt,
                proofDrawable = effectiveProofDrawable,
                allowOutsideProofWindow = allowOutsideProofWindow
            )
            if (registered && shouldJoinActiveInitialGeneratedFetch(index, page)) {
                val previewStarted = if (effectiveProofDrawable || isInInteractiveProofWindow(index, page)) {
                    ReaderImageCache.startVisibleInitialGeneratedPreviewFetch(
                        appContext,
                        page.manga,
                        image,
                        imageCancellation,
                        index
                    )
                } else {
                    false
                }
                scheduleVisibleGeneratedCachedDecodeRetry(
                    index,
                    page,
                    if (previewStarted) "${reason}_join_active_fetch_preview" else "${reason}_join_active_fetch",
                    byteStartedAt,
                    effectiveProofDrawable,
                    allowOutsideProofWindow = allowOutsideProofWindow
                )
                logNtkPagePerf(
                    index,
                    "visible_generated_cached_decode_join_active_fetch",
                    "reason=$reason,proof=$effectiveProofDrawable,previewStarted=$previewStarted"
                )
                return true
            }
            var streamStarted = false
            var previewStarted = false
            var directDecodeStarted = false
            if (effectiveProofDrawable || isInInteractiveProofWindow(index, page)) {
                val previewOnlyActiveProof =
                    effectiveProofDrawable &&
                        firstBitmapLogged.get() &&
                        isActiveGeneratedTouchOrQuiet() &&
                        index != currentStartPage()
                val racePreviewAlongsideStream: Boolean
                if (previewOnlyActiveProof) {
                    logNtkPagePerf(
                        index,
                        "visible_generated_active_proof_stream_suppressed",
                        "reason=$reason,anchor=${currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()}"
                    )
                    racePreviewAlongsideStream = false
                    previewStarted = startActiveGeneratedProofPreview(index, page, image, reason)
                } else {
                    val permit = ntkCoordinator?.imagePermit(
                        index,
                        page.manga,
                        image,
                        NtkImageLane.FOLLOWING_VISIBLE,
                        "visibleGeneratedCachedDecodeMiss"
                    )
                    streamStarted = startBoundedForegroundStreamFetch(
                        appContext,
                        page.manga,
                        image,
                        imageCancellation,
                        false,
                        permit,
                        index,
                        true
                    )
                    racePreviewAlongsideStream =
                        streamStarted &&
                            firstBitmapLogged.get() &&
                            isVisibleGeneratedDeliveryTarget(index)
                    previewStarted = if (!streamStarted || racePreviewAlongsideStream) {
                        ReaderImageCache.startVisibleInitialGeneratedPreviewFetch(
                            appContext,
                            page.manga,
                            image,
                            imageCancellation,
                            index
                        )
                    } else {
                        false
                    }
                }
                logNtkPagePerf(
                    index,
                    "visible_generated_cached_decode_miss_fetch",
                    "reason=$reason,streamStarted=$streamStarted,previewStarted=$previewStarted," +
                        "previewRace=$racePreviewAlongsideStream,proof=$effectiveProofDrawable"
                )
            directDecodeStarted = if (
                    !previewOnlyActiveProof &&
                    !shouldSuppressInitialContinuousStreamDirectDecode(index, reason) &&
                    (streamStarted || previewStarted || effectiveProofDrawable) &&
                    (index == currentStartPage() || firstBitmapLogged.get()) &&
                    (effectiveProofDrawable || isVisibleGeneratedDeliveryTarget(index))
                ) {
                    val directTargetWidth = if (effectiveProofDrawable) {
                        ntkProofTargetWidth()
                    } else if (allowFullDuringActiveProof) {
                        targetWidth(page, false)
                    } else {
                        targetWidth(page, true)
                    }
                    scheduleInitialGeneratedDirectDecode(
                        index,
                        page,
                        directTargetWidth,
                        "${reason}_stream_direct_decode",
                        byteStartedAt
                    )
                } else {
                    false
                }
                if (directDecodeStarted) {
                    logNtkPagePerf(
                        index,
                        "visible_generated_cached_decode_stream_direct",
                        "reason=$reason,proof=$effectiveProofDrawable"
                    )
                }
                if (registered || streamStarted || previewStarted || directDecodeStarted) {
                    scheduleVisibleGeneratedCachedDecodeRetry(
                        index,
                        page,
                        reason,
                        byteStartedAt,
                        effectiveProofDrawable,
                        allowOutsideProofWindow = allowOutsideProofWindow
                    )
                }
            }
                logNtkPagePerf(index, "visible_generated_cached_decode_skip", "reason=$reason,cached=false")
            return registered || streamStarted || previewStarted || directDecodeStarted
        }
        if (initialContinuousGenerated &&
            !firstBitmapLogged.get() &&
            !hasDeliveredOrPendingDrawable(currentStartPage())
        ) {
            logNtkPagePerf(index, "visible_generated_cached_decode_pre_anchor_allowed", "reason=$reason")
        }
        if (forceRequeue && !effectiveProofDrawable && !initialContinuousGenerated) {
            visibleGeneratedDecodeHedges.remove(index)
        }
        if (
            effectiveProofDrawable &&
            visibleGeneratedDecodeHedges.contains(index) &&
            !deliveredFullUpgrade
        ) {
            logNtkPagePerf(index, "visible_generated_cached_decode_skip", "reason=$reason,proof_decode_in_flight=true")
            return true
        }
        if (forceRequeue && effectiveProofDrawable && (allowOutsideProofWindow || isVisibleGeneratedDeliveryTarget(index))) {
            visibleGeneratedDecodeHedges.remove(index)
        }
        if (!visibleGeneratedDecodeHedges.add(index)) {
            return false
        }
        if (initialContinuousGenerated && !initialGeneratedCachedDecodeInFlight.add(index)) {
            visibleGeneratedDecodeHedges.remove(index)
            logNtkPagePerf(index, "visible_generated_cached_decode_skip", "reason=$reason,initial_in_flight=true")
            return false
        }
        val activeGeneratedProofGate =
            effectiveProofDrawable &&
                !allowOutsideProofWindow &&
                !initialAnchor &&
                firstBitmapLogged.get() &&
                isActiveGeneratedInputOrQuietForDelivery() &&
                isNtkGeneratedDescriptorOrImagePage(page) &&
                isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)
        val strictOriginalFlight = claimStrictInlineOriginalDecode(
            index,
            page,
            "visible_cached_$reason"
        )
        if (requiresAuthoritativeInlineTilePage(page) && strictOriginalFlight == null) {
            visibleGeneratedDecodeHedges.remove(index)
            if (initialContinuousGenerated) initialGeneratedCachedDecodeInFlight.remove(index)
            return true
        }
        val decodeExecutor = if (initialAnchor) initialAnchorDecode else urgentDecode
        if (initialAnchor && !initialAnchorCachedDecodeStarted.compareAndSet(false, true)) {
            logNtkPagePerf(index, "visible_generated_cached_decode_skip", "reason=$reason,anchor_already_started=true")
            if (initialContinuousGenerated) initialGeneratedCachedDecodeInFlight.remove(index)
            visibleGeneratedDecodeHedges.remove(index)
            releaseStrictInlineOriginalDecode(strictOriginalFlight)
            return false
        }
        try {
            decodeExecutor.execute {
                val startedAt = SystemClock.elapsedRealtime()
                var posted = false
                var activeProofGateAcquired = false
                try {
                    if (activeGeneratedProofGate) {
                        if (!activeVisibleDecodeGate.tryAcquire()) {
                            logNtkPagePerf(
                                index,
                                "visible_generated_cached_decode_gate_defer",
                                "reason=$reason,anchor=${currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()}"
                            )
                            scheduleVisibleGeneratedCachedDecodeRetry(
                                index,
                                page,
                                "${reason}_gate",
                                byteStartedAt,
                                effectiveProofDrawable,
                                allowOutsideProofWindow = allowOutsideProofWindow
                            )
                            return@execute
                        }
                        activeProofGateAcquired = true
                    }
                    if (
                        cancelled.get() ||
                        pageRef(index) != page ||
                        adoptAuthoritativeListenerDrawable(index, page, "cached_worker_$reason") ||
                        (hasDeliveredBitmap(index) && !deliveredFullUpgrade && hasListenerDrawableDelivery(index, page)) ||
                        (!effectiveProofDrawable && (pendingDeliveryWidths[index] ?: 0) > 0) ||
                        (!allowOutsideProofWindow && shouldSkipStaleGeneratedDecodeForScroll(index, page)) ||
                        (gatedGenerated && !effectiveProofDrawable && initialGeneratedDirectDecodeInFlight.contains(index) && !initialSurfaceGenerated)
                    ) {
                        return@execute
                    }
                    if (shouldSkipDecodeOutsideProtectedNumericWindow(
                            index,
                            page,
                            "visible_cached_pre"
                        )
                    ) {
                        return@execute
                    }
                    val targetWidth = if (effectiveProofDrawable) {
                        ntkProofTargetWidth()
                    } else if (allowFullDuringActiveProof) {
                        targetWidth(page, false)
                    } else {
                        targetWidth(page, true)
                    }
                    val result = if (requiresAuthoritativeInlineTilePage(page)) {
                        decodePage(index, page, cached, targetWidth, proofDrawable = effectiveProofDrawable)
                    } else if (initialAnchor) {
                        cachedDecodedResult(
                            index,
                            page,
                            targetWidth,
                            shouldUsePreviewDecodedCache(index, targetWidth)
                        ) ?: decodePage(index, page, cached, targetWidth, proofDrawable = effectiveProofDrawable)
                    } else {
                        if (effectiveProofDrawable) null else cachedDecodedResult(
                            index,
                            page,
                            targetWidth,
                            shouldUsePreviewDecodedCache(index, targetWidth)
                        )
                    } ?: decodePage(index, page, cached, targetWidth, proofDrawable = effectiveProofDrawable)
                    if (
                        cancelled.get() ||
                        pageRef(index) != page ||
                        currentPageIndexForDelivery(page, index) < 0
                    ) {
                        recycleDecodeResult(result)
                        return@execute
                    }
                    logNtkPagePerf(
                        index,
                        "visible_generated_cached_decode_ready",
                        "reason=$reason,byteMs=${startedAt - byteStartedAt},decodeMs=${SystemClock.elapsedRealtime() - startedAt},width=${result.width}"
                    )
                    posted = true
                    postDecodeResult(
                        Delivery(
                            index,
                            page,
                            result,
                            startedAt,
                            targetWidth,
                            retainWhenBusy = true,
                            proofDrawable = effectiveProofDrawable
                        )
                    )
                    if (!effectiveProofDrawable) {
                        cancelInitialGeneratedForegroundWorkAfterDrawableQueued(
                            page,
                            image,
                            "visible_cached_decode_posted"
                        )
                    }
                } catch (e: Exception) {
                    recordIfUnexpected(e)
                    postPageError(index, page, e)
                } finally {
                    if (initialAnchor && !posted && !firstBitmapLogged.get() && !hasDeliveredBitmap(index)) {
                        initialAnchorCachedDecodeStarted.set(false)
                        logNtkPagePerf(index, "visible_generated_cached_decode_aborted", "reason=$reason")
                    }
                    if (posted && effectiveProofDrawable) {
                        main.postDelayed(
                            { visibleGeneratedDecodeHedges.remove(index) },
                            NTK_VISIBLE_GENERATED_PROOF_DECODE_HOLD_MS
                        )
                    } else {
                        visibleGeneratedDecodeHedges.remove(index)
                    }
                    if (activeProofGateAcquired) {
                        releaseActiveGeneratedProofDecodeGate()
                    }
                    if (initialContinuousGenerated) initialGeneratedCachedDecodeInFlight.remove(index)
                    releaseStrictInlineOriginalDecode(strictOriginalFlight)
                }
            }
            return true
        } catch (_: RejectedExecutionException) {
            if (initialAnchor) initialAnchorCachedDecodeStarted.set(false)
            visibleGeneratedDecodeHedges.remove(index)
            if (initialContinuousGenerated) initialGeneratedCachedDecodeInFlight.remove(index)
            releaseStrictInlineOriginalDecode(strictOriginalFlight)
            return false
        }
    }

    private fun releaseActiveGeneratedProofDecodeGate() {
        // The decode gate only serializes CPU-heavy tile creation. Keeping it held after the
        // immutable result exists forced the next visible page into 64/160 ms retry timers.
        activeVisibleDecodeGate.release()
    }

    private fun shouldSuppressInitialContinuousStreamDirectDecode(index: Int, reason: String): Boolean {
        if (index == currentStartPage()) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (reason.startsWith("initial_continuous", ignoreCase = true)) return true
        if (
            isActiveGeneratedTouchOrQuiet() &&
            (
                reason.contains("active_generated_route_proof", ignoreCase = true) ||
                    reason.contains("_viewport_proof", ignoreCase = true)
            )
        ) {
            return true
        }
        return false
    }

    private fun shouldJoinActiveInitialGeneratedFetch(index: Int, page: PageRef): Boolean {
        if (!shouldUseImmediateGeneratedProofDrawable(page)) return false
        val image = page.image ?: return false
        if (!ReaderImageCache.hasActiveInitialNtkGeneratedFetch(page.manga, image)) return false
        return synchronized(pagesLock) {
            pages.withIndex().any { entry ->
                entry.index != index &&
                    entry.value.image == image &&
                    entry.value.sourceIndex == page.sourceIndex
            }
        }
    }

    private fun scheduleVisibleGeneratedCachedDecodeRetry(
        index: Int,
        page: PageRef,
        reason: String,
        byteStartedAt: Long,
        proofDrawable: Boolean,
        allowOutsideProofWindow: Boolean = false
    ) {
        if (cancelled.get() || pageRef(index) != page || hasDeliveredBitmap(index)) return
        val image = page.image.orEmpty()
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return
        val retryKey = "$index|$image|$proofDrawable|$allowOutsideProofWindow"
        if (!visibleGeneratedCachedDecodeRetries.add(retryKey)) return
        val delays = if (proofDrawable && allowOutsideProofWindow) {
            longArrayOf(24L, 64L, 128L, 256L, 512L)
        } else {
            longArrayOf(64L, 160L, 360L, 720L)
        }
        for (delayMs in delays) {
            main.postDelayed({
                if (
                    cancelled.get() ||
                    pageRef(index) != page ||
                    hasDeliveredBitmap(index) ||
                    (pendingDeliveryWidths[index] ?: 0) > 0
                ) {
                    visibleGeneratedCachedDecodeRetries.remove(retryKey)
                    return@postDelayed
                }
                if (ReaderImageCache.cachedFile(appContext, page.manga, image) == null) {
                    if (delayMs == delays.last()) {
                        visibleGeneratedCachedDecodeRetries.remove(retryKey)
                    }
                    return@postDelayed
                }
                visibleGeneratedCachedDecodeRetries.remove(retryKey)
                val scheduled = scheduleVisibleGeneratedCachedDecode(
                    index,
                    page,
                    "${reason}_cache_retry_${delayMs}ms",
                    byteStartedAt,
                    forceRequeue = true,
                    proofDrawable = proofDrawable,
                    allowOutsideProofWindow = allowOutsideProofWindow
                )
                logNtkPagePerf(
                    index,
                    "visible_generated_cached_decode_retry",
                    "reason=$reason,delayMs=$delayMs,scheduled=$scheduled"
                )
            }, delayMs)
        }
    }

    private fun scheduleInitialGeneratedDirectDecode(
        index: Int,
        page: PageRef,
        targetWidth: Int,
        reason: String,
        byteStartedAt: Long,
        allowAnchor: Boolean = false
    ): Boolean {
        if (shouldSuppressTrustedManifestGeneratedFallback(index, page, "initial_direct_$reason")) return false
        if (usesProtectedNumericNtkPipeline(page) && !isInsideProtectedNumericBitmapWindow(index, page)) {
            return false
        }
        val initialAnchor = shouldUseInitialGeneratedAnchorDirectDecode(index, page)
        val interactiveProofDirect =
            firstBitmapLogged.get() &&
                isInInteractiveProofWindow(index, page) &&
                isVisibleGeneratedDeliveryTarget(index)
        if (!shouldUseInitialGeneratedCachedDecodeGuard(index, page) &&
            !interactiveProofDirect &&
            !initialAnchor &&
            !(allowAnchor && initialAnchor)
        ) {
            return false
        }
        if (cancelled.get() || pageRef(index) != page) return false
        if (adoptAuthoritativeListenerDrawable(index, page, "direct_$reason")) return false
        if (hasDeliveredBitmap(index) || (pendingDeliveryWidths[index] ?: 0) > 0) return false
        if (!isVisibleGeneratedDecodeEligible(index, page)) return false
        val cachedDecodeInFlight = initialGeneratedCachedDecodeInFlight.contains(index)
        val visibleDecodeInFlight = visibleGeneratedDecodeHedges.contains(index)
        if (!interactiveProofDirect && (cachedDecodeInFlight || visibleDecodeInFlight)) {
            logNtkPagePerf(index, "initial_generated_direct_decode_skip", "reason=$reason,cached_or_decode_in_flight=true")
            return false
        }
        if (interactiveProofDirect && (cachedDecodeInFlight || visibleDecodeInFlight)) {
            logNtkPagePerf(index, "initial_generated_direct_decode_skip", "reason=$reason,proof_decode_in_flight=true")
            return false
        }
        val proofDirect =
            shouldUseImmediateGeneratedProofDrawable(page) &&
                targetWidth <= ntkProofTargetWidth()
        val image = page.image ?: return false
        ReaderImageCache.cachedFile(appContext, page.manga, image)?.let {
            return scheduleVisibleGeneratedCachedDecode(
                index,
                page,
                "${reason}_cached_first",
                byteStartedAt,
                forceRequeue = true,
                proofDrawable = interactiveProofDirect || proofDirect,
                allowOutsideProofWindow = proofDirect
            )
        }
        if (requiresAuthoritativeInlineTilePage(page)) {
            val registered = registerInitialGeneratedAssetCachedDecode(
                index,
                page,
                "${reason}_strict_original",
                byteStartedAt,
                proofDrawable = false,
                allowOutsideProofWindow = true,
                allowFullOutsideWindow = true
            )
            val permit = ntkCoordinator?.imagePermit(
                index,
                page.manga,
                image,
                if (initialAnchor) NtkImageLane.FIRST_IMAGE else NtkImageLane.FOLLOWING_VISIBLE,
                "strictInlineOriginalAsset"
            )
            val streamStarted = startBoundedForegroundStreamFetch(
                appContext,
                page.manga,
                image,
                imageCancellation,
                anchorHedge = false,
                permit = permit,
                pageIndex = index,
                visiblePriority = true
            )
            logNtkPagePerf(
                index,
                "strict_inline_direct_join_complete_asset",
                "reason=$reason,registered=$registered,streamStarted=$streamStarted"
            )
            return registered || streamStarted || ReaderImageCache.hasActiveInitialNtkGeneratedFetch(
                page.manga,
                image
            )
        }
        if (!initialGeneratedDirectDecodeInFlight.add(index)) {
            logNtkPagePerf(index, "initial_generated_direct_decode_skip", "reason=$reason,direct_in_flight=true")
            return false
        }
        val permit = ntkCoordinator?.imagePermit(
            index,
            page.manga,
            image,
            if (initialAnchor) NtkImageLane.FIRST_IMAGE else NtkImageLane.FOLLOWING_VISIBLE,
            "initialGeneratedDirectDecode"
        )
        if (!ntkCoordinatorAllowsStream(index, page, permit, "initialGeneratedDirectDecode")) {
            initialGeneratedDirectDecodeInFlight.remove(index)
            return false
        }
        val streamStarted = ReaderImageCache.startForegroundStreamFetch(
            appContext,
            page.manga,
            image,
            imageCancellation,
            false,
            permit,
            index,
            true
        )
        logNtkPagePerf(
            index,
            "initial_generated_direct_decode_stream_start",
            "reason=$reason,started=$streamStarted"
        )
        if (!streamStarted && isInitialSurfaceGeneratedPage(index, page)) {
            registerInitialGeneratedAssetCachedDecode(
                index,
                page,
                "${reason}_stream_join",
                byteStartedAt
            )
        }
        return try {
            urgentDecode.execute {
                val startedAt = SystemClock.elapsedRealtime()
                var posted = false
                try {
                    if (
                        cancelled.get() ||
                        pageRef(index) != page ||
                        adoptAuthoritativeListenerDrawable(index, page, "direct_worker_$reason") ||
                        hasDeliveredBitmap(index) ||
                        (pendingDeliveryWidths[index] ?: 0) >= targetWidth ||
                        shouldSkipStaleGeneratedDecodeForScroll(index, page)
                    ) {
                        return@execute
                    }
                    val result = decodeForegroundStream(
                        index,
                        page,
                        targetWidth,
                        foregroundFetch = true,
                        visiblePriority = true,
                        permit = permit,
                        bypassInitialCachedDecodeGuard = true,
                        proofDrawable = interactiveProofDirect || proofDirect
                    ) ?: return@execute
                    if (
                        cancelled.get() ||
                        pageRef(index) != page ||
                        currentPageIndexForDelivery(page, index) < 0
                    ) {
                        recycleDecodeResult(result)
                        return@execute
                    }
                    logNtkPagePerf(
                        index,
                        "initial_generated_direct_decode_ready",
                        "reason=$reason,byteMs=${startedAt - byteStartedAt},decodeMs=${SystemClock.elapsedRealtime() - startedAt},width=${result.width}"
                    )
                    posted = true
                    postDecodeResult(
                        Delivery(
                            index,
                            page,
                            result,
                            startedAt,
                            targetWidth,
                            retainWhenBusy = true,
                            proofDrawable = interactiveProofDirect || proofDirect
                        )
                    )
                    cancelInitialGeneratedForegroundWorkAfterDrawableQueued(
                        page,
                        image,
                        "initial_generated_direct_decode_posted"
                    )
                } catch (e: Exception) {
                    recordIfUnexpected(e)
                    postPageError(index, page, e)
                } finally {
                    initialGeneratedDirectDecodeInFlight.remove(index)
                    if (
                        !posted &&
                        !cancelled.get() &&
                        pageRef(index) == page &&
                        !hasDeliveredBitmap(index) &&
                        (pendingDeliveryWidths[index] ?: 0) <= 0 &&
                        !shouldSkipStaleGeneratedDecodeForScroll(index, page)
                    ) {
                        val cachedScheduled = scheduleVisibleGeneratedCachedDecode(
                            index,
                            page,
                            "${reason}_direct_fallback",
                            byteStartedAt,
                            forceRequeue = true,
                            proofDrawable = interactiveProofDirect || proofDirect,
                            allowOutsideProofWindow = proofDirect
                        )
                        if (!cachedScheduled) {
                            hedgeVisibleGeneratedByteFetch(
                                index,
                                page,
                                "${reason}_direct_fallback",
                                0L
                            )
                        }
                    }
                }
            }
            true
        } catch (_: RejectedExecutionException) {
            initialGeneratedDirectDecodeInFlight.remove(index)
            false
        }
    }

    private fun shouldSkipStalePage(index: Int, generation: Int, anchor: Boolean): Boolean {
        if (cancelled.get()) return true
        if (anchor) return false
        if (generation == PRIME_WARM_GENERATION) return false
        if (generation == FOREGROUND_PRIME_WARM_GENERATION) return false
        if (generation == windowGeneration.get()) return false
        if (
            isImmediateNtkGeneratedUx() &&
            viewportBusy.get() &&
            generation >= 0
        ) {
            return !isActiveNtkStaleDecodeStillVisible(index)
        }
        return !isRetainedPage(index)
    }

    private fun isActiveNtkStaleDecodeStillVisible(index: Int): Boolean {
        if (isRetainedPage(index)) return true
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return false
        val anchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?.coerceIn(0, count - 1)
            ?: currentStartPage().coerceIn(0, count - 1)
        val behind = if (isNtkWebtoonSource(manga, title)) {
            NTK_WEBTOON_BUSY_VISIBLE_DECODE_RADIUS
        } else {
            NTK_GENERATED_BUSY_VISIBLE_DECODE_RADIUS
        }
        val ahead = maxOf(initialContinuousViewportAheadPages(), NTK_ACTIVE_VISIBLE_DIRECT_DECODE_AHEAD_PAGES)
        return index in max(0, anchor - behind)..minOf(count - 1, anchor + ahead)
    }

    private fun shouldSuppressTrustedManifestGeneratedFallback(index: Int, page: PageRef, reason: String): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        val image = page.image.orEmpty()
        if (!isNtkGeneratedImageUrl(image)) return false
        val path = page.manga.ntkEpisodePath?.trim().orEmpty()
        if (!isNtkManhwaOrWebtoonEpisodePath(path)) return false
        if (
            isImmediateNtkGeneratedUx() &&
            (
                hasPageSourceReady(index, page) ||
                    ReaderImageCache.isKnownNtkGeneratedNotFound(page.manga, image) ||
                    ReaderImageCache.ntkAnchorAssetBytes(page.manga, image) != null ||
                    reason.startsWith("visible_byte_hedge") ||
                    reason.startsWith("initial_direct") ||
                    reason.startsWith("visible_cached_decode")
            )
        ) {
            return false
        }
        val trustedCount = ReaderImageCache.trustedNtkImageApiCount(path, SystemClock.elapsedRealtime() - 30000L)
        if (trustedCount <= 0) return false
        val trustedUrls = ReaderImageCache.earlyNtkImageUrls(path, SystemClock.elapsedRealtime() - 30000L)
        if (trustedUrls.size < trustedCount) return false
        val replacement = trustedUrls.getOrNull(index)
        if (!replacement.isNullOrBlank() && replacement != image) {
            logNtkPagePerf(
                index,
                "trusted_manifest_generated_fallback_replace",
                "reason=$reason,trusted=$trustedCount,old=${image.substringAfterLast('/')},new=${replacement.substringAfterLast('/')}"
            )
            page.image = replacement
            return false
        }
        if (isImmediateNtkGeneratedUx()) {
            return false
        }
        logNtkPagePerf(
            index,
            "trusted_manifest_generated_fallback_suppress",
            "reason=$reason,trusted=$trustedCount,image=${image.substringAfterLast('/')}"
        )
        return true
    }

    private fun shouldSkipStaleGeneratedDecodeForScroll(index: Int, page: PageRef): Boolean {
        if (!firstBitmapLogged.get()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (isImmediateNtkGeneratedUx()) return false
        if (hasDeliveredBitmap(index) || (pendingDeliveryWidths[index] ?: 0) > 0) return false
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        if (index >= anchor) return false
        if (isRetainedPage(index)) return false
        logNtkPagePerf(index, "skip_stale_generated_decode_scroll", "anchor=$anchor")
        return true
    }

    private fun rememberDesiredWidth(index: Int, targetWidth: Int) {
        while (true) {
            val current = desiredWidths[index]
            if (current != null && current >= targetWidth) return
            if (current == null) {
                if (desiredWidths.putIfAbsent(index, targetWidth) == null) return
            } else if (desiredWidths.replace(index, current, targetWidth)) {
                return
            }
        }
    }

    private fun retryPendingWidthIfNeeded(index: Int) {
        val wanted = achievableWidth(index, desiredWidths[index] ?: return)
        val have = decodedWidths[index] ?: 0
        if (wanted <= have) return
        if (cancelled.get() || !isRetainedPage(index)) {
            ViewerWarmupManager.logMetric("busy_to_idle_upgrade_miss", wanted.toLong())
            return
        }
        pageRef(index)?.let { page ->
            if (shouldDeferActiveGeneratedFullWidthUpgrade(index, page, wanted)) {
                logNtkPagePerf(index, "generated_full_upgrade_retry_defer_active_proof", "target=$wanted")
                scheduleIdleFullWidthUpgrade(index, wanted)
                return
            }
        }
        val effectiveWanted = achievableWidth(index, wanted)
        if ((pendingDeliveryWidths[index] ?: 0) >= effectiveWanted) return
        ViewerWarmupManager.logMetric("busy_to_idle_upgrade_retry", wanted.toLong())
        requestPage(index, false, false, windowGeneration.get())
    }

    private fun deliveredLowResGeneratedDrawableWidth(index: Int, page: PageRef, fullWidth: Int): Int {
        if (!isImmediateNtkGeneratedUx()) return 0
        if (!isNtkSource(page.manga, title)) return 0
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return 0
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return 0
        val keyWidth = drawableReadyKey(page)?.let { drawableReadyKeys[it] ?: 0 } ?: 0
        val delivered = maxOf(
            deliveredDrawableProofWidths[index] ?: 0,
            decodedWidths[index] ?: 0,
            pendingDeliveryWidths[index] ?: 0,
            keyWidth
        )
        val hasDrawable =
            delivered > 0 ||
                hasDeliveredOrPendingDrawable(index) ||
                hasListenerDrawableDelivery(index, page)
        if (!hasDrawable) return 0
        if (delivered <= 0) return 0
        val effectiveFull = achievableWidth(index, fullWidth)
        if (delivered >= effectiveFull) return 0
        return delivered
    }

    private fun shouldDeferActiveGeneratedFullWidthUpgrade(index: Int, page: PageRef, fullWidth: Int): Boolean {
        if (!isGeneratedFullUpgradeShieldActive()) return false
        return deliveredLowResGeneratedDrawableWidth(index, page, fullWidth) > 0
    }

    private fun isGeneratedFullUpgradeShieldActive(): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L && !firstDrawableDelivered.get()) return false
        return viewportBusy.get() ||
            isWithinFirstBitmapInputGrace() ||
            ntkInitialInteractiveSettleRemainingMs() > 0L ||
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L ||
            readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS) > 0L
    }

    private fun isRetainedPage(index: Int): Boolean = synchronized(deliveredBitmaps) {
        index in retainedFirstPage..retainedLastPage
    }

    private fun hasDeliveredBitmap(index: Int): Boolean {
        val tracked = synchronized(deliveredBitmaps) {
            deliveredBitmaps[index]?.let { !it.isRecycled } == true ||
                deliveredTiles[index]?.any { !it.bitmap.isRecycled } == true
        }
        if (tracked) return true
        // The strict Surface/native prewarm queue can retain the immutable first winner after the
        // ReaderSession has trimmed its own LRU bookkeeping to the decoded-pixel budget. Treat that
        // physical owner as delivered so forward traversal does not decode the same 114 pages over
        // and over merely because the session-side reference was released.
        return strictExactColdRolling &&
            listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)
    }

    private fun hasDeliveredOrPendingDrawable(index: Int): Boolean {
        if (hasDeliveredBitmap(index)) return true
        if ((pendingDeliveryWidths[index] ?: 0) > 0) return true
        if (initialDeliveryBacklog.containsKey(index)) return true
        if (initialPreparedBacklog.containsKey(index)) return true
        return false
    }

    private fun hasListenerDrawableDelivery(index: Int): Boolean {
        return listenerDrawableDeliveries.contains(index) || drawableReadyHistory.contains(index)
    }

    private fun hasListenerDrawableDelivery(index: Int, page: PageRef): Boolean {
        if (hasListenerDrawableDelivery(index)) return true
        return drawableReadyKey(page)?.let { key -> (drawableReadyKeys[key] ?: 0) > 0 } == true
    }

    private fun adoptAuthoritativeListenerDrawable(index: Int, page: PageRef, reason: String): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        // Delivery history is monotonic evidence, not current Surface ownership. Budget or pool
        // retirement can clear the drawable while preserving that history and the canonical body.
        // Returning solely from the history bit permanently hid the exact rehydrate route behind
        // a forward cap: Session believed the page existed while Surface reported missing pixels.
        // Query the lock-free current owner first; only suppress repeated proof/log work when both
        // the historic identity and its present authoritative drawable agree.
        val authoritativeInstalled =
            listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)
        if (hasListenerDrawableDelivery(index, page) && authoritativeInstalled) {
            retireSettledStrictAdjacentRehydrateFlight(index, page)
            return true
        }
        if (!authoritativeInstalled) return false
        markListenerDrawableDelivery(index)
        markCanonicalDrawableCompletion(index, page)
        drawableReadyKey(page)?.let { key -> drawableReadyKeys.putIfAbsent(key, 1) }
        retireSettledStrictAdjacentRehydrateFlight(index, page)
        logNtkPagePerf(index, "decode_skip_authoritative_surface", "reason=$reason")
        return true
    }

    private fun shouldKeepPreparedRunwayDecodeColdUntilInput(index: Int, page: PageRef): Boolean {
        if (preparedLaunchRunwaySpec == null) return false
        if (!isImmediateNtkGeneratedUx() || !isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        val physicalLast = preparedLaunchDrawableLast.get()
        val storeLast = refreshPreparedStoreDrawableLast()
        if (physicalLast < 0 && storeLast < 0) return false
        return shouldKeepPreparedRunwayDecodeColdPolicy(
            index,
            max(physicalLast, storeLast),
            viewerActivated.get(),
            lastUserInteractionMs.get() > 0L,
            viewportBusy.get()
        )
    }

    private fun refreshPreparedStoreDrawableLast(): Int {
        val spec = preparedLaunchRunwaySpec ?: return preparedLaunchDrawableLast.get()
        val latest = preparedEntry?.contiguousLaunchRunwayTileLast(spec)
            ?: preparedLaunchDrawableLast.get()
        return preparedStoreDrawableLast.updateAndGet { previous -> max(previous, latest) }
    }

    /**
     * Reconcile the late-published Store with the already-active attached root.  Only the exact
     * contiguous identities the listener says are physically installed advance the physical
     * watermark.  Remaining contiguous Store pages are handed to the real surface immediately;
     * no activation or scroll gate is introduced.
     */
    private fun handOffContiguousPreparedStoreRunwayOnActivation() {
        val spec = preparedLaunchRunwaySpec ?: return
        val snapshot = preparedEntry?.snapshot() ?: return
        if (!preparedSnapshotMatchesCurrentEpisode(snapshot)) return
        val images = snapshot.images ?: return
        var physicalLast = spec.startPage - 1
        var index = spec.startPage
        while (index < images.size) {
            val page = snapshot.tilePages[index] ?: break
            if (!ReaderPreparedStore.isCanonicalOriginalTilePage(page, images[index])) break
            if (!listener.isExactPreparedStoreTilePageInstalled(
                    index,
                    page.pageWidth,
                    page.pageHeight,
                    page.tiles
                )
            ) break
            physicalLast = index
            index++
        }
        preparedLaunchDrawableLast.updateAndGet { previous -> max(previous, physicalLast) }

        val storeLast = refreshPreparedStoreDrawableLast()
        val handoffFirst = max(spec.startPage, physicalLast + 1)
        if (handoffFirst <= storeLast) {
            for (storeIndex in handoffFirst..storeLast) {
                val page = snapshot.tilePages[storeIndex] ?: break
                deliverPreparedSourceTilePage(storeIndex, page)
            }
        }
        Log.d(
            TAG,
            "reader_ntk_prepared_activation_handoff physicalLast=$physicalLast," +
                "storeLast=$storeLast,handoffFirst=$handoffFirst"
        )
    }

    private fun startPreparedPostActivationContinuation() {
        if (cancelled.get() || !viewerActivated.get()) return
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty()) return
        val physicalLast = preparedLaunchDrawableLast.get()
        val storeLast = refreshPreparedStoreDrawableLast()
        val bounds = preparedPostActivationContinuationBounds(
            physicalLast,
            storeLast,
            refs.size
        )
        val first = bounds[0]
        val last = bounds[1]
        if (first > last) return
        val continuationBase = first - 1
        while (true) {
            val previous = preparedPostActivationContinuationBase.get()
            if (continuationBase <= previous) return
            if (preparedPostActivationContinuationBase.compareAndSet(previous, continuationBase)) break
        }
        val startedAt = SystemClock.elapsedRealtime()
        var decodeScheduled = 0
        var listeners = 0
        var byteStarted = 0
        for (index in first..last) {
            val page = refs[index]
            if (page.transitionTitle != null || !isNtkGeneratedDescriptorOrImagePage(page) ||
                hasDeliveredOrPendingDrawable(index)
            ) {
                continue
            }
            if (hasPageSourceReady(index, page)) {
                if (scheduleVisibleGeneratedCachedDecode(
                        index,
                        page,
                        "prepared_post_activation_continuation",
                        startedAt,
                        forceRequeue = true,
                        // This is the first real rolling viewport+runway window. Strict inline
                        // still decodes sample-1 original source tiles; proof only selects
                        // their physical delivery lane.
                        proofDrawable = true,
                        allowOutsideProofWindow = true,
                        allowFullDuringActiveProof = true
                    )
                ) {
                    decodeScheduled++
                }
                continue
            }
            val registered = registerInitialGeneratedAssetCachedDecode(
                index,
                page,
                "prepared_post_activation_continuation",
                startedAt,
                proofDrawable = true,
                allowFullOutsideWindow = true
            )
            if (registered) listeners++
            val image = page.image.orEmpty()
            val started = startBoundedForegroundStreamFetch(
                appContext,
                page.manga,
                image,
                imageCancellation,
                anchorHedge = false,
                permit = null,
                pageIndex = index,
                visiblePriority = true,
                verifiedEpisodeFanout = true
            )
            if (started) byteStarted++
        }
        Log.d(
            TAG,
            "reader_ntk_prepared_post_activation_continuation first=$first,last=$last," +
                "decodeScheduled=$decodeScheduled,listeners=$listeners,byteStarted=$byteStarted," +
                "physicalLast=$physicalLast,storeLast=$storeLast," +
                "fullQuality=true,preparePass=false"
        )
    }

    private fun markListenerDrawableDelivery(index: Int) {
        synchronized(indexedStateLock) {
            listenerDrawableDeliveries.add(index)
            drawableReadyHistory.add(index)
            strictInlineProofDeliveryIntents.remove(index)
        }
    }

    private fun markDecodedDrawableReady(index: Int, width: Int) {
        if (index < 0) return
        markListenerDrawableDelivery(index)
        if (width > 0) {
            deliveredDrawableProofWidths[index] = max(deliveredDrawableProofWidths[index] ?: 0, width)
            decodedWidths[index] = max(decodedWidths[index] ?: 0, width)
        }
    }

    private fun markDecodedDrawableReady(index: Int, page: PageRef, width: Int) {
        markDecodedDrawableReady(index, width)
        markCanonicalDrawableCompletion(index, page)
        val key = drawableReadyKey(page) ?: return
        if (width > 0) {
            drawableReadyKeys.merge(key, width, ::max)
        } else {
            drawableReadyKeys.putIfAbsent(key, 1)
        }
        // A tail bookmark can restore directly into the last few pages without producing another
        // viewport-window callback after those pages finish decoding. Re-evaluate the adjacent
        // gate on each genuine drawable completion; it opens only when every still-unread page is
        // ready, so current-episode work keeps priority while the next runway gains the otherwise
        // missing head start before the user's first fast swipe reaches the boundary.
        if (strictExactColdRolling && firstBitmapLogged.get()) {
            val restoredStart = currentStartPage()
            val last = pagesLastIndex()
            if (restoredStart > 0 &&
                last - restoredStart <= NTK_INITIAL_TAIL_ADJACENT_PREAPPEND_PAGES &&
                index >= restoredStart
            ) {
                main.post {
                    if (!cancelled.get()) {
                        maybeStartInitialTailAdjacentPreappendForAnchor(
                            index,
                            NtkAdjacentRunwayPreparationPolicy.RESUMED_TAIL_DRAWABLE_READY_REASON,
                        )
                    }
                }
            }
        }
    }

    private fun markImmediateGeneratedDecodedReady(delivery: Delivery, index: Int = delivery.index): Boolean {
        if (index < 0) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(delivery.page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(delivery.page.image.orEmpty())) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(delivery.page.manga.ntkEpisodePath)) return false
        if (delivery.result.width > 0) {
            decodedWidths[index] = max(decodedWidths[index] ?: 0, delivery.result.width)
        }
        return true
    }

    private fun drawableReadyKey(page: PageRef): String? {
        if (!isImmediateNtkGeneratedUx()) return null
        if (!isNtkSource(page.manga, title)) return null
        val path = page.manga.ntkEpisodePath?.trim()?.takeIf { it.isNotEmpty() } ?: return null
        if (!isNtkManhwaOrWebtoonEpisodePath(path)) return null
        val pageNumber = ntkImagePageNumber(page.image.orEmpty())
            ?: (page.sourceIndex + 1).takeIf { it > 0 }
            ?: (page.pageIndex + 1).takeIf { it > 0 }
            ?: return null
        return "$path#$pageNumber"
    }

    private fun markCanonicalDrawableCompletion(index: Int, deliveredPage: PageRef) {
        if (index < 0 || deliveredPage.transitionTitle != null || deliveredPage.sourceIndex < 0) return
        synchronized(pagesLock) {
            val page = pages.getOrNull(index) ?: return
            if (!sameCanonicalDrawableCompletionIdentity(deliveredPage, page)) return
            val path = NtkStripDigests.normalizeEpisodePath(page.manga.ntkEpisodePath.orEmpty())
            if (path.isEmpty() || page.canonicalAsset.isBlank()) return
            episodeDrawableCompletionLedger.mark(
                path,
                page.sourceIndex,
                page.side,
                page.canonicalAsset,
                page.manifestDigest,
                page.manifestPageCount,
            )
        }
    }

    private fun sameCanonicalDrawableCompletionIdentity(first: PageRef, second: PageRef): Boolean {
        if (first.transitionTitle != null || second.transitionTitle != null) return false
        return first.sourceIndex == second.sourceIndex &&
            first.side == second.side &&
            first.canonicalAsset == second.canonicalAsset &&
            first.manifestDigest == second.manifestDigest &&
            first.manifestPageCount == second.manifestPageCount &&
            NtkStripDigests.normalizeEpisodePath(first.manga.ntkEpisodePath.orEmpty()) ==
                NtkStripDigests.normalizeEpisodePath(second.manga.ntkEpisodePath.orEmpty())
    }

    private fun hasCanonicalDrawableCompletion(page: PageRef): Boolean {
        if (page.transitionTitle != null || page.sourceIndex < 0) return false
        val path = NtkStripDigests.normalizeEpisodePath(page.manga.ntkEpisodePath.orEmpty())
        if (path.isEmpty() || page.canonicalAsset.isBlank()) return false
        return episodeDrawableCompletionLedger.contains(
            path,
            page.sourceIndex,
            page.side,
            page.canonicalAsset,
            page.manifestDigest,
            page.manifestPageCount,
        )
    }

    private fun logFirstBitmapIfNeeded(startedAt: Long, drawHeightPx: Float = 0f) {
        if (firstBitmapLogged.compareAndSet(false, true)) {
            ntkCoordinator?.markAnchorBitmapDecoded(currentStartPage())
            val firstBitmapElapsedAt = SystemClock.elapsedRealtime()
            ntkFirstBitmapAtMs.set(SystemClock.uptimeMillis())
            if (drawHeightPx > 0f) {
                ntkFirstDrawableDrawHeightPx.compareAndSet(0, drawHeightPx.toInt().coerceAtLeast(1))
            }
            ViewerWarmupManager.logMetric("reader_first_bitmap_ms", SystemClock.elapsedRealtime() - startedAt)
            releasePreparedStoreBitmapsSoon()
            maybeStartInitialTailAdjacentPreappend(manga, currentStartPage(), pagesLastIndex() + 1, "first_bitmap")
            startFirstBitmapFollowups(startedAt, firstBitmapElapsedAt)
        }
    }

    private fun maybeStartInitialTailAdjacentPreappend(
        source: Manga,
        startPage: Int,
        count: Int,
        reason: String
    ) {
        if (cancelled.get()) return
        if (!isImmediateNtkGeneratedUx()) return
        if (!isNtkSource(source, title)) return
        if (!isNtkManhwaOrWebtoonEpisodePath(source.ntkEpisodePath)) return
        if (count <= 0) return
        val authoritativeCount = synchronized(pagesLock) {
            canonicalEpisodeImageCount(
                source,
                pages.filter { page ->
                    page.transitionTitle == null &&
                        looseSameEpisodeForAppend(page.manga, source)
                },
            )
        }
        if (authoritativeCount > count) {
            if (
                shouldLogRateLimitedDiagnostic(
                    "initial_tail_partial|${source.ntkEpisodePath}|$reason",
                )
            ) {
                Log.d(
                    TAG,
                    "append_adjacent_initial_tail_preappend_skip_partial_current reason=$reason " +
                        "count=$count authoritativeCount=$authoritativeCount"
                )
            }
            return
        }
        val currentTitle = title ?: source.title ?: manga.title ?: return
        // Legacy/non-strict readers can still prepare their bounded adjacent runway at first
        // pixels. A strict cold session already owns every current-episode body and decode; it
        // waits for the real tail-window signal below so adjacent work cannot lengthen the current
        // episode's finite all-images wave.
        if (
            NtkAdjacentRunwayPreparationPolicy.shouldStartAdjacentPrefetch(
                strictExactColdRolling,
                reason,
            ) && (
                reason == "first_bitmap" ||
                reason == "first_bitmap_prepared" ||
                reason == "first_actual_frame"
            )
        ) {
            maybeStartInitialTailAdjacentPrefetch(source, currentTitle, reason)
        }
        val boundedStart = startPage.coerceIn(0, count - 1)
        val distanceToTail = count - 1 - boundedStart
        if (distanceToTail > NTK_INITIAL_TAIL_ADJACENT_PREAPPEND_PAGES) return
        val sourcePath = source.ntkEpisodePath?.trim().orEmpty()
        if (sourcePath.isEmpty()) return
        // A legacy reader may keep its existing tail-triggered metadata prefetch. A strict cold
        // reader must not let even the adjacent metadata/body preparation contend with unfinished
        // current-episode images: the current episode is the foreground UX contract.
        if (!strictExactColdRolling) {
            maybeStartInitialTailAdjacentPrefetch(source, currentTitle, reason)
        }
        val currentRefs = synchronized(pagesLock) {
            pages.withIndex().filter { (_, page) ->
                page.transitionTitle == null && Manga.sameEpisodeIdentity(page.manga, source)
            }
        }
        val completeCurrentStructure = currentRefs.isNotEmpty() &&
            (authoritativeCount <= 0 || currentRefs.size >= authoritativeCount)
        val allCurrentDrawablesReady = completeCurrentStructure &&
            currentRefs.all { (index, page) ->
                hasListenerDrawableDelivery(index, page) || hasDeliveredBitmap(index)
            }
        val enforceFullCurrentEpisode =
            isNtkContinuousAdjacentCompletionPolicyActive()
        val restoredStart = currentStartPage()
        val resumedFromTail = strictExactColdRolling &&
            Manga.sameEpisodeIdentity(source, manga) &&
            restoredStart in 1 until currentRefs.size &&
            currentRefs.lastIndex - restoredStart <= NTK_INITIAL_TAIL_ADJACENT_PREAPPEND_PAGES
        val resumedForwardDrawablesReady = resumedFromTail &&
            currentRefs.drop(restoredStart).all { (index, page) ->
                hasListenerDrawableDelivery(index, page) || hasDeliveredBitmap(index)
            }
        if (resumedFromTail) {
            // Resolve only the adjacent document while the restored unread pages retain all image,
            // decode, and GPU priority. Starting this metadata request as soon as the complete
            // current structure is known hides its multi-second RTT without spending adjacent
            // bitmap resources before the current tail is actually drawable.
            maybeStartInitialAdjacentMetadataPrefetch(
                source,
                currentTitle,
                NtkAdjacentRunwayPreparationPolicy.RESUMED_TAIL_DRAWABLE_READY_REASON,
            )
        }
        val currentEpisodeReady = if (enforceFullCurrentEpisode) {
            // The generic structure snapshot treats an unknown authoritative count as usable for
            // legacy readers. Direct-Wi-Fi strict continuation cannot: a four-page runway with an
            // unknown count must never release next-episode page-list/document work. Reuse the
            // canonical, contiguous, drawable-complete proof that also guards B -> C warmup.
            isEpisodeFullyDrawableForAdjacent(source)
        } else {
            NtkAdjacentRunwayPreparationPolicy.isCurrentEpisodeReadyForAdjacent(
                completeCurrentStructure = completeCurrentStructure,
                allCurrentDrawablesReady = allCurrentDrawablesReady,
                strictExactColdRolling = strictExactColdRolling,
                resumedFromTail = resumedFromTail,
                resumedForwardDrawablesReady = resumedForwardDrawablesReady,
            )
        }
        if (!currentEpisodeReady) {
            if (shouldLogRateLimitedDiagnostic(
                    "append_adjacent_initial_tail_not_ready|$sourcePath"
                )
            ) {
                Log.d(
                    TAG,
                    "append_adjacent_initial_tail_preappend_skip_current_not_ready reason=$reason " +
                        "count=$count authoritativeCount=$authoritativeCount," +
                        "allReady=$allCurrentDrawablesReady,resumedTail=$resumedFromTail," +
                        "resumedForwardReady=$resumedForwardDrawablesReady"
                )
            }
            return
        }
        if (strictExactColdRolling) {
            maybeStartInitialTailAdjacentPrefetch(source, currentTitle, reason)
        }
        if (hasForwardNtkEpisodeAfterSource(source)) return
        val key = "${ReaderSurfaceView.DIRECTION_NEXT}:$sourcePath:initial_tail"
        val recentFailureAt = initialTailAdjacentPreappendFailedAtMs[key] ?: 0L
        if (
            recentFailureAt > 0L &&
            SystemClock.elapsedRealtime() - recentFailureAt < NTK_INITIAL_TAIL_ADJACENT_PREAPPEND_FAILURE_SUPPRESS_MS
        ) {
            return
        }
        if (shouldDeferInitialTailPreappendForActiveScroll(distanceToTail, reason)) {
            if (!initialTailAdjacentPreappendKeys.add(key)) return
            val retryMs = initialTailPreappendActiveScrollRetryMs()
            Log.d(
                TAG,
                "append_adjacent_initial_tail_preappend_defer_active_scroll reason=$reason " +
                    "start=$boundedStart count=$count distance=$distanceToTail " +
                    "source=$sourcePath retryMs=$retryMs"
            )
            main.postDelayed({
                initialTailAdjacentPreappendKeys.remove(key)
                if (!cancelled.get()) {
                    maybeStartInitialTailAdjacentPreappend(
                        source,
                        currentStartPage(),
                        pagesLastIndex() + 1,
                        "active_scroll_retry"
                    )
                }
            }, retryMs)
            return
        }
        if (shouldDeferInitialTailPreappendBehindActiveRemaining(source)) {
            if (!initialTailAdjacentPreappendKeys.add(key)) return
            val retryMs = initialTailPreappendActiveRemainingRetryMs()
            Log.d(
                TAG,
                "append_adjacent_initial_tail_preappend_defer_active_remaining reason=$reason " +
                    "source=$sourcePath retryMs=$retryMs active=${activeRemainingAdjacentRunwayTargetPaths.size}"
            )
            main.postDelayed({
                initialTailAdjacentPreappendKeys.remove(key)
                if (!cancelled.get()) {
                    maybeStartInitialTailAdjacentPreappend(
                        source,
                        currentStartPage(),
                        pagesLastIndex() + 1,
                        "active_remaining_retry"
                    )
                }
            }, retryMs)
            return
        }
        if (!initialTailAdjacentPreappendKeys.add(key)) return
        Log.d(
            TAG,
            "append_adjacent_initial_tail_preappend_start reason=$reason start=$boundedStart " +
                "count=$count distance=$distanceToTail source=$sourcePath"
        )
        try {
            adjacentNetwork.execute {
                var success = false
                try {
                    if (!cancelled.get()) {
                        source.title = currentTitle
                        source.titleId = currentTitle.id
                        success = appendImmediateGeneratedNumericAdjacentIfAvailable(
                            source,
                            currentTitle,
                            ReaderSurfaceView.DIRECTION_NEXT,
                            initialTailPreappend = true
                        )
                        Log.d(
                            TAG,
                            "append_adjacent_initial_tail_preappend_done reason=$reason " +
                                "success=$success source=$sourcePath"
                        )
                        if (success) {
                            initialTailAdjacentPreappendFailedAtMs.remove(key)
                        }
                    }
                } catch (e: Exception) {
                    recordIfUnexpected(e)
                } finally {
                    if (!success && !cancelled.get()) {
                        initialTailAdjacentPreappendFailedAtMs[key] = SystemClock.elapsedRealtime()
                        initialTailAdjacentPreappendKeys.remove(key)
                        if (shouldRetryInitialTailPreappendAfterFailure(reason)) {
                            main.postDelayed({
                                if (!cancelled.get()) {
                                    maybeStartInitialTailAdjacentPreappend(
                                        source,
                                        currentStartPage(),
                                        pagesLastIndex() + 1,
                                        "first_bitmap_retry"
                                    )
                                }
                            }, NTK_INITIAL_TAIL_ADJACENT_PREAPPEND_RETRY_MS)
                        }
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            initialTailAdjacentPreappendKeys.remove(key)
        }
    }

    /**
     * Starts one exact, generation-owned next-document flight without opening its image/API gate.
     * Subsequent episodes wait until the reader has physically reached source page four; the launch
     * episode may overlap from its first compositor-proven frame. Numeric/cellular targets merely
     * park at the coordinator control gate, while direct-Wi-Fi manhwa can fetch its document and
     * bounded format HEAD evidence before waiting on the same full-drawable predecessor event as
     * every body.
     */
    private fun maybeStartForwardAdjacentDocumentControl(
        source: Manga,
        currentTitle: Title,
        reason: String,
    ) {
        if (cancelled.get() || !strictExactColdRolling || reverse) return
        if (!isDirectWifiStrictAdjacentTransportActive()) return
        if (!isNtkSource(source, currentTitle)) return
        if (!isNtkManhwaOrWebtoonEpisodePath(source.ntkEpisodePath)) return
        val sourcePath = NtkStripDigests.normalizeEpisodePath(
            source.ntkEpisodePath?.trim().orEmpty(),
        )
        if (sourcePath.isEmpty() || !shouldStartWifiAdjacentCascade(source, sourcePath)) return
        if (hasForwardNtkEpisodeAfterSource(source)) return
        if (!hasNtkResolvedAdjacentMetadataCandidate(
                source,
                currentTitle,
                ReaderSurfaceView.DIRECTION_NEXT,
            )
        ) return
        if (!initialAdjacentDocumentControlPaths.add(sourcePath)) return
        try {
            adjacentNetwork.execute {
                var selectedTargetPath: String? = null
                try {
                    if (cancelled.get()) return@execute
                    source.title = currentTitle
                    source.titleId = currentTitle.id
                    selectedTargetPath = startForwardAdjacentExactDiscoveryAtCompletion(
                        source,
                        resolvedNext = null,
                        onResolvedForwardPath = null,
                        controlOnly = true,
                    )
                    val targetPath = selectedTargetPath.orEmpty()
                    Log.d(
                        TAG,
                        "append_adjacent_document_control reason=$reason source=$sourcePath " +
                            "target=$targetPath,early=${
                                NtkAdjacentMetadataControlPolicy.mayOpenAtFlightAdmission(
                                    directWifiAdjacentBodyGate = true,
                                    targetEpisodePath = targetPath,
                                )
                            }",
                    )
                } catch (failure: Exception) {
                    if (!isExpectedCancellation(failure)) recordIfUnexpected(failure)
                } finally {
                    if (selectedTargetPath.isNullOrEmpty()) {
                        initialAdjacentDocumentControlPaths.remove(sourcePath)
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            initialAdjacentDocumentControlPaths.remove(sourcePath)
        }
    }

    private fun maybeStartInitialAdjacentMetadataPrefetch(
        source: Manga,
        currentTitle: Title,
        reason: String,
    ) {
        if (cancelled.get() || !strictExactColdRolling) return
        if (!isImmediateNtkGeneratedUx() || reverse) return
        if (!isNtkSource(source, currentTitle)) return
        if (!isNtkManhwaOrWebtoonEpisodePath(source.ntkEpisodePath)) return
        maybeStartForwardAdjacentDocumentControl(source, currentTitle, reason)
        if (isNtkContinuousAdjacentCompletionPolicyActive() &&
            !isEpisodeFullyDrawableForAdjacent(source)
        ) return
        if (isNtkContinuousAdjacentCompletionPolicyActive()) {
            NtkStrictEpisodeDiscoveryCoordinator
                .releaseAdjacentBodiesAfterPredecessorComplete(
                    source.ntkEpisodePath,
                    null,
                    strictExactForegroundViewerGenerationAtCreation,
                    strictExactViewerOwnerEpisodePathAtCreation,
                )
        }
        val sourcePath = source.ntkEpisodePath?.trim().orEmpty()
        if (sourcePath.isEmpty()) return
        if (!shouldStartWifiAdjacentCascade(source, sourcePath)) return
        if (hasForwardNtkEpisodeAfterSource(source)) return
        if (preparedInitialAdjacentMetadata.containsKey(sourcePath)) return
        if (preparedInitialAdjacentRunways.keys.any { it.isNotEmpty() }) return
        val fullRunwayKey =
            "${ReaderSurfaceView.DIRECTION_NEXT}:$sourcePath:initial_tail_prefetch"
        if (initialTailAdjacentPrefetchKeys.contains(fullRunwayKey)) return
        if (!hasNtkResolvedAdjacentMetadataCandidate(
                source,
                currentTitle,
                ReaderSurfaceView.DIRECTION_NEXT,
            )
        ) return
        if (!initialAdjacentMetadataPrefetchPaths.add(sourcePath)) return
        Log.d(
            TAG,
            "append_adjacent_initial_metadata_start reason=$reason source=$sourcePath"
        )
        try {
            adjacentNetwork.execute {
                var success = false
                try {
                    if (!cancelled.get()) {
                        source.title = currentTitle
                        source.titleId = currentTitle.id
                        success = prefetchResolvedMetadataAdjacent(
                            source,
                            currentTitle,
                            ReaderSurfaceView.DIRECTION_NEXT,
                            metadataOnly = true,
                        )
                    }
                } catch (e: Exception) {
                    if (!isExpectedCancellation(e)) recordIfUnexpected(e)
                } finally {
                    initialAdjacentMetadataPrefetchPaths.remove(sourcePath)
                    Log.d(
                        TAG,
                        "append_adjacent_initial_metadata_done reason=$reason success=$success " +
                            "source=$sourcePath"
                    )
                    if (success && !cancelled.get()) {
                        main.post {
                            if (!cancelled.get()) {
                                val activeAnchor = currentViewportAnchor.get()
                                    .takeIf { it >= 0 }
                                    ?: currentStartPage()
                                maybeStartInitialTailAdjacentPreappendForAnchor(
                                    activeAnchor,
                                    NtkAdjacentRunwayPreparationPolicy
                                        .CURRENT_EPISODE_COMPLETE_IDLE_REASON,
                                )
                            }
                        }
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            initialAdjacentMetadataPrefetchPaths.remove(sourcePath)
        }
    }

    private fun maybeStartInitialTailAdjacentPrefetch(
        source: Manga,
        currentTitle: Title,
        reason: String
    ) {
        if (cancelled.get()) return
        if (isNtkContinuousAdjacentCompletionPolicyActive() &&
            !isEpisodeFullyDrawableForAdjacent(source)
        ) return
        if (!NtkAdjacentRunwayPreparationPolicy.shouldStartAdjacentPrefetch(
                strictExactColdRolling,
                reason,
            )
        ) {
            Log.d(
                TAG,
                "append_adjacent_initial_prefetch_defer_current_wave " +
                    "reason=$reason source=${source.ntkEpisodePath}"
            )
            return
        }
        // A bounded drawable runway already present after this source is authoritative. Window
        // callbacks from the final physical swipe can race the append commit and otherwise launch
        // the exact same document/fetch/decode wave again while those pixels are being scrolled.
        if (hasForwardNtkEpisodeAfterSource(source)) return
        // A real forward viewport inside the bounded tail is the strongest demand signal we can
        // receive. Deferring its two-page adjacent runway until input becomes quiet guarantees
        // that a continuous fling reaches the episode boundary before the next episode starts.
        // Other callers retain the quiet/grace guard, so this never turns into unconditional
        // next-episode downloading at viewer entry.
        val demandedByForwardReading =
                reason == "window_tail" ||
                reason == "first_bitmap" ||
                reason == "first_bitmap_prepared" ||
                reason == "first_actual_frame" ||
                reason == NtkAdjacentRunwayPreparationPolicy.RESUMED_TAIL_DRAWABLE_READY_REASON ||
                reason == NtkAdjacentRunwayPreparationPolicy.CURRENT_EPISODE_COMPLETE_IDLE_REASON
        if (
            !demandedByForwardReading &&
            (isActiveGeneratedTouchOrQuiet() || viewportBusy.get() || isWithinFirstBitmapInputGrace())
        ) {
            Log.d(
                TAG,
                "append_adjacent_initial_prefetch_skip_active reason=$reason source=${source.ntkEpisodePath}"
            )
            return
        }
        val sourcePath = source.ntkEpisodePath?.trim().orEmpty()
        if (sourcePath.isEmpty()) return
        if (!shouldStartWifiAdjacentCascade(source, sourcePath)) return
        if (initialAdjacentMetadataPrefetchPaths.contains(sourcePath)) {
            Log.d(
                TAG,
                "append_adjacent_initial_prefetch_wait_metadata reason=$reason source=$sourcePath"
            )
            return
        }
        val key = "${ReaderSurfaceView.DIRECTION_NEXT}:$sourcePath:initial_tail_prefetch"
        if (preparedInitialAdjacentRunways.keys.any { it.isNotEmpty() }) return
        if (!initialTailAdjacentPrefetchKeys.add(key)) return
        Log.d(
            TAG,
            "append_adjacent_initial_prefetch_start reason=$reason source=$sourcePath"
        )
        try {
            adjacentNetwork.execute {
                var success = false
                try {
                    if (!cancelled.get()) {
                        if (hasForwardNtkEpisodeAfterSource(source)) {
                            // The queued task lost its race to the normal append path. Treat the
                            // desired runway as satisfied without touching its network or pixels.
                            success = true
                        } else {
                            source.title = currentTitle
                            source.titleId = currentTitle.id
                            success = appendImmediateGeneratedNumericAdjacentIfAvailable(
                                source,
                                currentTitle,
                                ReaderSurfaceView.DIRECTION_NEXT,
                                prefetchOnly = true
                            )
                        }
                    }
                } catch (e: Exception) {
                    if (!isExpectedCancellation(e)) recordIfUnexpected(e)
                } finally {
                    if (!success) initialTailAdjacentPrefetchKeys.remove(key)
                    Log.d(
                        TAG,
                        "append_adjacent_initial_prefetch_done reason=$reason success=$success " +
                            "source=$sourcePath"
                    )
                }
            }
        } catch (_: RejectedExecutionException) {
            initialTailAdjacentPrefetchKeys.remove(key)
        }
    }

    private fun forwardNtkEpisodePathAfterSource(source: Manga): String? {
        val sourcePath = source.ntkEpisodePath?.trim().orEmpty()
        if (sourcePath.isEmpty()) return null
        val pageIndex = publishedPageIndex.get()
        var lastSourceIndex = -1
        for ((index, page) in pageIndex.withIndex()) {
            if (page.transitionTitle != null) continue
            val path = page.manga.ntkEpisodePath?.trim().orEmpty()
            if (path == sourcePath || Manga.sameEpisodeIdentity(page.manga, source)) {
                lastSourceIndex = index
            }
        }
        if (lastSourceIndex < 0 || lastSourceIndex >= pageIndex.lastIndex) return null
        for (index in (lastSourceIndex + 1)..pageIndex.lastIndex) {
            val page = pageIndex[index]
            if (page.transitionTitle != null) continue
            val path = page.manga.ntkEpisodePath?.trim().orEmpty()
            if (
                path.isNotEmpty() &&
                path != sourcePath &&
                isNtkManhwaOrWebtoonEpisodePath(path)
            ) {
                return path
            }
        }
        return null
    }

    private fun hasForwardNtkEpisodeAfterSource(source: Manga): Boolean =
        forwardNtkEpisodePathAfterSource(source) != null

    private fun shouldStartWifiAdjacentCascade(source: Manga, sourcePath: String): Boolean {
        val wifiTransportActive = MainApplication.getHttpClient().isNtkWifiTransportActive()
        if (!wifiTransportActive) return true
        val initialEpisode =
            sourcePath == initialNtkEpisodePath ||
                Manga.sameEpisodeIdentity(source, manga)
        if (initialEpisode) return true
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        val activeSourcePageIndex = synchronized(pagesLock) {
            var localIndex = -1
            val boundedAnchor = anchor.coerceAtMost(pages.lastIndex)
            for (index in 0..boundedAnchor) {
                val page = pages[index]
                if (page.transitionTitle != null) continue
                val path = page.manga.ntkEpisodePath?.trim().orEmpty()
                if (path == sourcePath || Manga.sameEpisodeIdentity(page.manga, source)) {
                    localIndex++
                }
            }
            localIndex
        }
        val shouldStart = NtkWifiAdjacentCascadePolicy.shouldStart(
            wifiTransportActive = true,
            initialEpisode = false,
            directWifiCurrentEpisodeComplete =
                isDirectWifiStrictAdjacentTransportActive() &&
                    isEpisodeFullyDrawableForAdjacent(source),
            activeSourcePageIndex = activeSourcePageIndex,
        )
        if (!shouldStart) {
            if (shouldLogRateLimitedDiagnostic("adjacent_cascade_defer|$sourcePath")) {
                Log.d(
                    TAG,
                    "append_adjacent_cascade_defer_wifi path=$sourcePath " +
                        "activeSourcePage=$activeSourcePageIndex," +
                        "required=${NtkWifiAdjacentCascadePolicy.MIN_ACTIVE_SOURCE_PAGE_INDEX}"
                )
            }
        }
        return shouldStart
    }

    private fun shouldYieldInitialAdjacentMetadata(source: Manga): Boolean {
        if (!hasForwardNtkEpisodeAfterSource(source)) return false
        return viewportBusy.get() ||
            physicalTouchQuietRemainingMs(NTK_APPEND_REMAINING_RUNWAY_PHYSICAL_QUIET_MS) > 0L
    }

    private fun cancelRedundantInitialAdjacentMetadataForPhysicalInput() {
        for ((sourcePath, activeFetch) in activeInitialAdjacentMetadataFetches.entries) {
            if (!hasForwardNtkEpisodeAfterSource(activeFetch.source)) continue
            if (!activeInitialAdjacentMetadataFetches.remove(sourcePath, activeFetch)) continue
            activeFetch.cancellation.cancel()
            Log.d(
                TAG,
                "append_adjacent_initial_metadata_cancel_physical_input source=$sourcePath"
            )
        }
    }

    private fun shouldRetryInitialTailPreappendAfterFailure(reason: String): Boolean {
        return reason == "first_bitmap_prepared"
    }

    private fun shouldDeferInitialTailPreappendForActiveScroll(distanceToTail: Int, reason: String): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (distanceToTail <= NTK_APPEND_CURRENT_TAIL_BOUNDARY_PAGES) return false
        if (reason == "first_bitmap" || reason == "first_bitmap_prepared") return false
        return isActiveGeneratedTouchOrQuiet() || viewportBusy.get()
    }

    private fun initialTailPreappendActiveScrollRetryMs(): Long {
        return maxOf(
            ntkAdjacentAppendStartDelayMs(),
            NTK_ADJACENT_CURRENT_INSTALL_RECHECK_MS
        )
    }

    private fun shouldDeferInitialTailPreappendBehindActiveRemaining(source: Manga): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isActiveGeneratedTouchOrQuiet() && !viewportBusy.get()) return false
        val path = activeRemainingAdjacentRunwayTargetPath(source)
        if (path.isEmpty()) return false
        return activeRemainingAdjacentRunwayTargetPaths.contains(path)
    }

    private fun initialTailPreappendActiveRemainingRetryMs(): Long {
        return maxOf(
            readerQuietRemainingMs(NTK_APPEND_REMAINING_RUNWAY_ACTIVE_QUIET_MS),
            NTK_ADJACENT_FOREGROUND_STREAM_RECHECK_MS
        )
    }

    private fun maybeStartInitialTailAdjacentPreappendForAnchor(anchor: Int, reason: String) {
        if (cancelled.get()) return
        if (!isImmediateNtkGeneratedUx()) return
        val result = synchronized(pagesLock) {
            val source = pages.getOrNull(anchor)?.manga ?: return@synchronized null
            if (!isNtkSource(source, title)) return@synchronized null
            if (!isNtkManhwaOrWebtoonEpisodePath(source.ntkEpisodePath)) return@synchronized null
            var localIndex = -1
            var total = 0
            for ((globalIndex, page) in pages.withIndex()) {
                if (page.transitionTitle != null || !Manga.sameEpisodeIdentity(page.manga, source)) continue
                if (globalIndex == anchor) {
                    localIndex = total
                }
                total++
            }
            if (localIndex < 0 || total <= 0) null else Triple(source, localIndex, total)
        } ?: return
        maybeStartInitialTailAdjacentPreappend(result.first, result.second, result.third, reason)
    }

    private fun requestInitialTailPreviousGeneratedPages(startPage: Int, count: Int, reason: String) {
        if (cancelled.get()) return
        if (!isImmediateNtkGeneratedUx()) return
        if (count <= 0) return
        val start = startPage.coerceIn(0, count - 1)
        val distanceToTail = count - 1 - start
        if (distanceToTail > NTK_INITIAL_TAIL_ADJACENT_PREAPPEND_PAGES) return
        val first = max(0, start - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)
        if (first >= start) return
        var requested = 0
        val requestedIndexes = ArrayList<Int>()
        for (index in first until start) {
            val page = pageRef(index) ?: continue
            if (page.transitionTitle != null || hasDeliveredOrPendingDrawable(index)) continue
            if (!hasPageSourceReady(index, page)) {
                forcePrefetchNtkPageSource(
                    index,
                    page,
                    "${reason}_tail_previous",
                    allowDuringInitialInteractive = true
                )
            }
            requestPage(index, busy = true, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
            requested++
            if (requestedIndexes.size < 32) requestedIndexes.add(index)
        }
        if (requested > 0) {
            Log.d(
                TAG,
                "reader_ntk_initial_tail_previous_runway reason=$reason,start=$start,count=$count," +
                    "range=$first-${start - 1},requested=$requested," +
                    "requestedIndexes=${requestedIndexes.joinToString("|")}"
            )
        }
    }

    private fun startFirstBitmapFollowups(startedAt: Long, firstBitmapElapsedAt: Long) {
        if (strictExactColdRolling) {
            // The strict session already owns the immutable manifest, every post-draw source body,
            // and its dedicated overlap/bulk decode queues. Re-entering the legacy generated
            // follow-up graph only scans the same pages, posts polling callbacks and competes with
            // the authoritative decode workers; its byte calls are no-ops by construction.
            firstBitmapFollowupsStarted.compareAndSet(false, true)
            return
        }
        if (isImmediateNtkGeneratedUx()) {
            val knownFullGenerated = isKnownFullGeneratedEpisodeInstalled()
            if (preparedLaunchRunwaySpec == null) {
                postFirstBitmapControl {
                    if (!cancelled.get()) {
                        requestInitialFastFlingGeneratedRunway("first_bitmap_immediate")
                    }
                }
            }
            if (!knownFullGenerated && isImmediateGeneratedShortPageRunway()) {
                postFirstBitmapControl {
                    if (!cancelled.get()) {
                        requestInitialContinuousGeneratedAfterFirstBitmap("first_bitmap_short_page")
                    }
                }
            } else {
                postFirstBitmapControl(NTK_FIRST_BITMAP_FOLLOWUP_INPUT_GRACE_MS) {
                    if (!cancelled.get()) {
                        requestInitialContinuousGeneratedAfterFirstBitmap("first_bitmap")
                    }
                }
            }
        } else {
            postFirstBitmapControl {
                if (!cancelled.get()) {
                    requestInitialContinuousGeneratedAfterFirstBitmap("first_bitmap")
                }
            }
        }
        postFirstBitmapControl {
            runFirstBitmapFollowupsWhenReady(startedAt, firstBitmapElapsedAt)
        }
    }

    private fun postFirstBitmapControl(delayMs: Long = 0L, block: () -> Unit) {
        val enqueue = Runnable {
            if (cancelled.get()) return@Runnable
            try {
                control.execute {
                    if (!cancelled.get()) block()
                }
            } catch (_: RejectedExecutionException) {
            }
        }
        if (delayMs > 0L) {
            main.postDelayed(enqueue, delayMs)
        } else {
            enqueue.run()
        }
    }

    private fun isInitialSurfaceGeneratedPage(index: Int, page: PageRef): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        val start = currentStartPage()
        return index in start..(start + 3)
    }

    private fun registerInitialGeneratedAssetCachedDecode(
        index: Int,
        page: PageRef,
        reason: String,
        byteStartedAt: Long,
        proofDrawable: Boolean = false,
        allowOutsideProofWindow: Boolean = false,
        allowFullOutsideWindow: Boolean = false
    ): Boolean {
        if (routeStrictAdjacentExactRehydrate(index, page, visibleIntent = true)) return true
        if (reason.contains("asset_ready")) return false
        if (!isNtkSource(page.manga, title)) return false
        if (pageRef(index) != page) return false
        if (adoptAuthoritativeListenerDrawable(index, page, "asset_listener_$reason")) return false
        if (usesProtectedNumericNtkPipeline(page) && !isInsideProtectedNumericBitmapWindow(index, page)) {
            return false
        }
        if (hasDeliveredBitmap(index) || (pendingDeliveryWidths[index] ?: 0) > 0) return false
        val expectedImage = page.image.orEmpty()
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        val initialSurfaceGenerated = isInitialSurfaceGeneratedPage(index, page)
        val visibleProofAssetListener = proofDrawable &&
            (allowOutsideProofWindow || isVisibleGeneratedDeliveryTarget(index))
        if (proofDrawable) {
            if (!allowOutsideProofWindow && !isInInteractiveProofWindow(index, page)) return false
        } else if (
            !allowFullOutsideWindow &&
            !isVisibleGeneratedDecodeEligible(index, page) &&
            !initialSurfaceGenerated
        ) return false
        if (
            !visibleProofAssetListener &&
            (
                (initialGeneratedDirectDecodeInFlight.contains(index) && !initialSurfaceGenerated) ||
                    initialGeneratedCachedDecodeInFlight.contains(index) ||
                    visibleGeneratedDecodeHedges.contains(index)
            )
        ) {
            logNtkPagePerf(index, "initial_generated_asset_decode_listener_skip", "reason=$reason,decode_in_flight=true,initialSurface=$initialSurfaceGenerated")
            return false
        }
        if (!initialGeneratedAssetDecodeListeners.add(index)) return true
        val accepted = ReaderImageCache.runWhenNtkInitialGeneratedAssetReady(
            appContext,
            page.manga,
            expectedImage,
            Runnable {
                // Forward-history compaction may renumber this immutable PageRef while its
                // encoded body is still arriving.  removePageStateRange() remaps the listener
                // ledger, so consulting only the captured numeric index both misses the page and
                // leaves the remapped "listener active" bit set forever. Resolve by PageRef at
                // callback time and clear both spellings before any terminal check.
                val currentIndex = currentPageIndexForDelivery(page, index)
                initialGeneratedAssetDecodeListeners.remove(index)
                if (currentIndex >= 0) {
                    initialGeneratedAssetDecodeListeners.remove(currentIndex)
                }
                if (
                    cancelled.get() ||
                    currentIndex < 0 ||
                    pageRef(currentIndex) != page ||
                    page.image.orEmpty() != expectedImage ||
                    adoptAuthoritativeListenerDrawable(currentIndex, page, "asset_ready_$reason") ||
                    hasDeliveredBitmap(currentIndex) ||
                    (pendingDeliveryWidths[currentIndex] ?: 0) > 0 ||
                    (usesProtectedNumericNtkPipeline(page) &&
                        !isInsideProtectedNumericBitmapWindow(currentIndex, page)) ||
                    (!visibleProofAssetListener &&
                        (
                            (initialGeneratedDirectDecodeInFlight.contains(currentIndex) &&
                                !isInitialSurfaceGeneratedPage(currentIndex, page)) ||
                                initialGeneratedCachedDecodeInFlight.contains(currentIndex) ||
                                visibleGeneratedDecodeHedges.contains(currentIndex)
                        )) ||
                    if (proofDrawable) {
                        !allowOutsideProofWindow &&
                            !isInInteractiveProofWindow(currentIndex, page)
                    } else {
                        !allowFullOutsideWindow &&
                            !isVisibleGeneratedDecodeEligible(currentIndex, page) &&
                            !isInitialSurfaceGeneratedPage(currentIndex, page)
                    }
                ) {
                    return@Runnable
                }
                if (visibleProofAssetListener) {
                    initialGeneratedDirectDecodeInFlight.remove(index)
                    initialGeneratedDirectDecodeInFlight.remove(currentIndex)
                    initialGeneratedCachedDecodeInFlight.remove(index)
                    initialGeneratedCachedDecodeInFlight.remove(currentIndex)
                    visibleGeneratedDecodeHedges.remove(index)
                    visibleGeneratedDecodeHedges.remove(currentIndex)
                    loading.remove(index)
                    loading.remove(currentIndex)
                    urgentLoading.remove(index)
                    urgentLoading.remove(currentIndex)
                    loadingPages.remove(index)
                    loadingPages.remove(currentIndex)
                    urgentLoadingPages.remove(index)
                    urgentLoadingPages.remove(currentIndex)
                    logNtkPagePerf(
                        currentIndex,
                        "initial_generated_asset_ready_preempt_inflight",
                        "reason=$reason",
                    )
                }
                scheduleVisibleGeneratedCachedDecode(
                    currentIndex,
                    page,
                    "${reason}_asset_ready",
                    byteStartedAt,
                    forceRequeue = true,
                    proofDrawable = proofDrawable,
                    allowOutsideProofWindow = allowOutsideProofWindow,
                    allowFullDuringActiveProof = allowFullOutsideWindow
                )
            }
        )
        if (!accepted) {
            initialGeneratedAssetDecodeListeners.remove(index)
            return false
        }
        logNtkPagePerf(index, "initial_generated_asset_decode_listener", "reason=$reason")
        return true
    }

    private fun runFirstBitmapFollowupsWhenReady(startedAt: Long, firstBitmapElapsedAt: Long) {
        if (cancelled.get() || firstBitmapFollowupsStarted.get()) return
        if (isImmediateNtkGeneratedUx()) {
            val inputGraceMs = NTK_FIRST_BITMAP_FOLLOWUP_INPUT_GRACE_MS -
                (SystemClock.elapsedRealtime() - firstBitmapElapsedAt)
            if (inputGraceMs > 0L) {
                synchronized(pagesLock) { pages.toList() }.takeIf { it.isNotEmpty() }?.let { refs ->
                    requestInitialRapidScrollGeneratedWindow(refs, "first_bitmap_followups_input_grace")
                }
                Log.d(
                    TAG,
                    "reader_first_bitmap_followups_defer_input_grace start=${currentStartPage()}," +
                        "delayMs=$inputGraceMs"
                )
                postFirstBitmapControl(
                    inputGraceMs.coerceAtMost(NTK_FIRST_BITMAP_FOLLOWUP_QUIET_POLL_MS)
                ) { runFirstBitmapFollowupsWhenReady(startedAt, firstBitmapElapsedAt) }
                return
            }
            val viewportAnchor = currentViewportAnchor.get()
            val viewportPage = viewportAnchor.takeIf { it >= 0 }?.let { pageRef(it) }
            if (viewportPage != null && viewportPage.manga.ntkEpisodePath != manga.ntkEpisodePath) {
                Log.d(
                    TAG,
                    "reader_first_bitmap_followups_stop_different_episode start=${currentStartPage()}," +
                        "viewport=$viewportAnchor,path=${viewportPage.manga.ntkEpisodePath}"
                )
                return
            }
        }
        if (shouldDeferFirstBitmapFollowups(firstBitmapElapsedAt)) {
            Log.d(
                TAG,
                "reader_first_bitmap_followups_defer start=${currentStartPage()}," +
                    "delivered=${initialViewportDeliveredForFollowupsCount()}"
            )
            val recheckMs = if (isImmediateNtkGeneratedUx()) {
                NTK_FIRST_BITMAP_FOLLOWUP_QUIET_POLL_MS
            } else {
                NTK_FIRST_BITMAP_FOLLOWUP_RECHECK_MS
            }
            postFirstBitmapControl(recheckMs) {
                runFirstBitmapFollowupsWhenReady(startedAt, firstBitmapElapsedAt)
            }
            return
        }
        if (shouldDeferNonVisibleFirstBitmapFollowups(firstBitmapElapsedAt)) {
            val activeRequested = synchronized(pagesLock) { pages.toList() }
                .takeIf { it.isNotEmpty() }
                ?.let { refs -> requestFirstBitmapActiveInputFollowupIfNeeded(refs) }
                ?: false
            if (activeRequested || shouldLogFirstBitmapActiveFollowupDefer()) {
                Log.d(
                    TAG,
                    "reader_first_bitmap_followups_defer_active_input start=${currentStartPage()}," +
                        "viewport=${currentViewportAnchor.get()},busy=${viewportBusy.get()}," +
                        "requested=$activeRequested"
                )
            }
            val recheckMs = if (isImmediateNtkGeneratedUx()) {
                NTK_FIRST_BITMAP_FOLLOWUP_QUIET_POLL_MS
            } else {
                NTK_FIRST_BITMAP_FOLLOWUP_RECHECK_MS
            }
            postFirstBitmapControl(recheckMs) {
                runFirstBitmapFollowupsWhenReady(startedAt, firstBitmapElapsedAt)
            }
            return
        }
        val quietDelayMs = ntkFirstBitmapFollowupQuietDelayMs()
        if (quietDelayMs > 0L) {
            postFirstBitmapControl(
                quietDelayMs.coerceAtMost(NTK_FIRST_BITMAP_FOLLOWUP_QUIET_POLL_MS)
            ) { runFirstBitmapFollowupsWhenReady(startedAt, firstBitmapElapsedAt) }
            return
        }
        requestInitialRapidScrollGeneratedWindowOnce("first_bitmap_followups")
        if (!firstBitmapFollowupsStarted.compareAndSet(false, true)) return
        appendLatestEarlyNtkUrlsAfterFirstBitmap(startedAt)
        upgradeNtkInitialPriorityPagesAfterFirstBitmap()
        prefetchNtkInitialNextBytesAfterFirstBitmap()
        requestImmediateGeneratedFullWarmOnce("first_bitmap_initial_ready")
        requestGeneratedFullEpisodeDecodeAfterFirstBitmap()
        scheduleNtkSecondaryInitialWarmAfterFirstBitmap()
        scheduleNtkSourcePrefetchAfterFirstBitmap()
        scheduleNtkGeneratedFullEpisodeBytePrefetchAfterFirstBitmap()
        scheduleNtkEpisodeMetadataAfterFirstBitmap()
        scheduleNtkForwardTimelinePrimeAfterFirstBitmap()
    }

    private fun requestFirstBitmapActiveInputFollowupIfNeeded(refs: List<PageRef>): Boolean {
        if (!isImmediateNtkGeneratedUx() || refs.isEmpty()) return false
        val start = currentStartPage().coerceIn(0, refs.lastIndex)
        val anchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?.coerceIn(0, refs.lastIndex)
            ?: start
        val runwayLast = initialInteractiveRunwayLastIndex(refs.size)
        val last = minOf(refs.lastIndex, runwayLast, anchor + activeGeneratedProofAheadPages())
        if (isFirstBitmapActiveFollowupWindowReady(refs, anchor, last)) {
            logFirstBitmapActiveFollowupReady(anchor, last)
            return false
        }
        val now = SystemClock.elapsedRealtime()
        val key = "$anchor:$last:${refs.size}"
        val previousKey = lastFirstBitmapActiveFollowupKey.get()
        val previousAt = lastFirstBitmapActiveFollowupAtMs.get()
        if (
            key == previousKey &&
            now - previousAt < NTK_FIRST_BITMAP_ACTIVE_INPUT_FOLLOWUP_REPEAT_SUPPRESS_MS
        ) {
            return false
        }
        lastFirstBitmapActiveFollowupKey.set(key)
        lastFirstBitmapActiveFollowupAtMs.set(now)
        requestInitialRapidScrollGeneratedWindow(refs, "first_bitmap_followups_active_input")
        return true
    }

    private fun isFirstBitmapActiveFollowupWindowReady(
        refs: List<PageRef>,
        anchor: Int,
        last: Int
    ): Boolean {
        if (refs.isEmpty()) return false
        val boundedAnchor = anchor.coerceIn(0, refs.lastIndex)
        val boundedLast = last.coerceIn(boundedAnchor, refs.lastIndex)
        for (index in boundedAnchor..boundedLast) {
            val page = refs.getOrNull(index) ?: return false
            if (page.transitionTitle != null) continue
            if (!isNtkGeneratedDescriptorOrImagePage(page)) continue
            if (
                !hasDeliveredOrPendingDrawable(index) &&
                !hasListenerDrawableDelivery(index, page)
            ) {
                return false
            }
        }
        return true
    }

    private fun logFirstBitmapActiveFollowupReady(anchor: Int, last: Int) {
        val now = SystemClock.elapsedRealtime()
        val previous = lastFirstBitmapActiveFollowupReadyLogAtMs.get()
        if (now - previous < NTK_FIRST_BITMAP_ACTIVE_INPUT_READY_LOG_SUPPRESS_MS) return
        if (!lastFirstBitmapActiveFollowupReadyLogAtMs.compareAndSet(previous, now)) return
        Log.d(
            TAG,
            "reader_first_bitmap_followups_active_window_ready anchor=$anchor,last=$last," +
                "start=${currentStartPage()},viewport=${currentViewportAnchor.get()}"
        )
    }

    private fun shouldLogFirstBitmapActiveFollowupDefer(): Boolean {
        val now = SystemClock.elapsedRealtime()
        val previous = lastFirstBitmapActiveFollowupDeferLogAtMs.get()
        if (now - previous < NTK_FIRST_BITMAP_ACTIVE_INPUT_DEFER_LOG_SUPPRESS_MS) return false
        return lastFirstBitmapActiveFollowupDeferLogAtMs.compareAndSet(previous, now)
    }

    private fun requestImmediateGeneratedFullWarmOnce(reason: String) {
        if (!canRunImmediateGeneratedFullWarm()) return
        val quietMs = if (isImmediateNtkGeneratedUx()) 0L else ntkBackgroundWarmQuietRemainingMs()
        if (quietMs > 0L) {
            main.postDelayed({
                if (!cancelled.get()) requestImmediateGeneratedFullWarmOnce(reason)
            }, quietMs.coerceAtLeast(NTK_BACKGROUND_WARM_RECHECK_MS))
            Log.d(
                TAG,
                "reader_ntk_immediate_generated_full_warm_defer reason=$reason," +
                    "delayMs=$quietMs,start=${currentStartPage()}"
            )
            return
        }
        if (!immediateGeneratedFullWarmStarted.compareAndSet(false, true)) return
        Log.d(
            TAG,
            "reader_ntk_immediate_generated_full_warm_start reason=$reason,start=${currentStartPage()}"
        )
        requestGeneratedFullEpisodeDecodeAfterFirstBitmap(forceImmediate = true)
        scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(
            NTK_GENERATED_FULL_BYTE_PREFETCH_BATCH_DELAY_MS
        )
    }

    private fun canRunImmediateGeneratedFullWarm(): Boolean {
        return isImmediateNtkGeneratedUx()
    }

    private fun ntkFirstBitmapFollowupQuietDelayMs(): Long {
        if (!isNtkSource(manga, title)) return 0L
        if (isImmediateNtkGeneratedUx()) return 0L
        if (!firstBitmapLogged.get()) return 0L
        val path = manga.ntkEpisodePath
        val initialContinuousPath =
            isNtkManhwaOrWebtoonEpisodePath(path) || manga.baseMode == MTitle.base_webtoon
        if (!initialContinuousPath) return 0L
        return maxOf(
            ntkBackgroundPrepareQuietRemainingMs(),
            readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS)
        )
    }

    private fun isImmediateNtkGeneratedUx(): Boolean {
        if (!isNtkSource(manga, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) return false
        return true
    }

    private fun requestInitialRapidScrollGeneratedWindow(refs: List<PageRef>, reason: String) {
        if (strictExactColdRolling) return
        if (!isImmediateNtkGeneratedUx()) return
        if (refs.isEmpty()) return
        val start = currentStartPage().coerceIn(0, refs.lastIndex)
        val activeInput = isActiveGeneratedTouchOrQuiet()
        val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 }?.coerceIn(0, refs.lastIndex)
        val anchor = if (activeInput) {
            viewportAnchor ?: start
        } else {
            start
        }
        val requestedAheadPages = if (shouldHoldNtkGeneratedTailForInitialContinuous()) {
            if (activeInput) {
                NTK_INITIAL_RAPID_SCROLL_DECODE_AHEAD_PAGES
            } else {
                NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
            }
        } else {
            ntkInitialRapidScrollAheadPages(reason)
        }
        val initialManifestRunway = reason == "initial_full_publish" || reason == "initial_warm_active"
        val aheadPages = if (activeInput && isImmediateNtkGeneratedUx()) {
            if (initialManifestRunway) {
                minOf(requestedAheadPages, NTK_GENERATED_IMMEDIATE_RUNWAY_PAGES)
            } else {
                minOf(requestedAheadPages, activeGeneratedProofAheadPages())
            }
        } else {
            requestedAheadPages
        }
        val runwayLast = initialInteractiveRunwayLastIndex(refs.size)
        val last = if (activeInput) {
            minOf(refs.lastIndex, runwayLast, anchor + aheadPages)
        } else {
            minOf(refs.lastIndex, anchor + aheadPages)
        }
        if (last <= anchor) return
        var requested = 0
        val requestedIndexes = ArrayList<Int>()
        for (index in (anchor + 1)..last) {
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (hasDeliveredBitmap(index)) {
                if (tryRedeliverRetainedGeneratedDrawable(index, page, "${reason}_active_surface_missing")) {
                    requested++
                    if (requestedIndexes.size < 32) requestedIndexes.add(index)
                }
                continue
            }
            if (!hasPageSourceReady(index, page)) {
                if (activeInput) {
                    val scheduled = startInitialInteractiveRunwayByteFetch(
                        index,
                        page,
                        "${reason}_active_proof",
                        forceProofDrawable = true,
                        allowOutsideProofWindow = true
                    )
                    if (scheduled) {
                        requested++
                        if (requestedIndexes.size < 32) requestedIndexes.add(index)
                    }
                    logNtkPagePerf(
                        index,
                        "initial_rapid_route_proof_bytes_active",
                        "reason=$reason,anchor=$anchor,scheduled=$scheduled"
                    )
                    continue
                }
                forcePrefetchNtkPageSource(
                    index,
                    page,
                    reason,
                    allowDuringInitialInteractive = false
                )
            }
            if (activeInput) {
                val scheduled = scheduleVisibleGeneratedCachedDecode(
                    index,
                    page,
                    "${reason}_active_proof",
                    SystemClock.elapsedRealtime(),
                    forceRequeue = true,
                    proofDrawable = true
                )
                if (scheduled) requested++
                if (!scheduled) startInitialInteractiveRunwayByteFetch(index, page, "${reason}_active_proof")
                if (requestedIndexes.size < 32) requestedIndexes.add(index)
                continue
            }
            requestPage(index, busy = true, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
            requested++
            if (requestedIndexes.size < 32) requestedIndexes.add(index)
        }
        Log.d(
            TAG,
            "reader_ntk_initial_rapid_scroll_window reason=$reason,anchor=$anchor," +
                "start=$start,active=$activeInput,requested=$requested,range=${anchor + 1}-$last," +
                "requestedIndexes=${requestedIndexes.joinToString("|")}"
        )
        if (activeInput && runwayLast > last && isImmediateNtkGeneratedUx()) {
            var byteStarted = 0
            val byteAhead = activeRollingRunwayByteAheadPages(anchor)
            val byteLast = minOf(runwayLast, last + byteAhead)
            if (byteAhead > 0 && byteLast > last) {
                for (index in (last + 1)..byteLast) {
                    val page = refs.getOrNull(index) ?: continue
                    if (page.transitionTitle != null) continue
                    if (hasDeliveredBitmap(index)) {
                        tryRedeliverRetainedGeneratedDrawable(index, page, "${reason}_rolling_runway_surface_missing")
                        continue
                    }
                    if (!isNtkGeneratedImageUrl(page.image.orEmpty())) continue
                    if (hasPageSourceReady(index, page)) continue
                    if (startInitialInteractiveRunwayByteFetch(index, page, "${reason}_rolling_runway")) {
                        byteStarted++
                    }
                }
            }
            if (byteStarted > 0) {
                Log.d(
                    TAG,
                    "reader_ntk_initial_rapid_scroll_runway_bytes reason=$reason,anchor=$anchor," +
                        "range=${last + 1}-$byteLast,runwayLast=$runwayLast,started=$byteStarted"
                )
            }
        }
        ViewerWarmupManager.logMetric("reader_ntk_initial_rapid_scroll_window", requested.toLong())
    }

    private fun requestInitialRapidScrollGeneratedWindowOnce(reason: String) {
        if (!initialRapidGeneratedWindowStarted.compareAndSet(false, true)) return
        val refs = synchronized(pagesLock) { pages.toList() }
        requestInitialRapidScrollGeneratedWindow(refs, reason)
    }

    private fun requestInitialFastFlingGeneratedRunway(reason: String) {
        if (strictExactColdRolling) return
        if (!isImmediateNtkGeneratedUx()) return
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty()) return
        val start = currentStartPage().coerceIn(0, refs.lastIndex)
        val defaultRunwayPages = if (isNtkWebtoonEpisodePath(manga.ntkEpisodePath)) {
            NTK_FAST_FLING_WEBTOON_RUNWAY_PAGES
        } else {
            NTK_FAST_FLING_MANHWA_RUNWAY_PAGES
        }
        val generatedOnlyRefs = refs.all { page ->
            page.transitionTitle != null || isNtkGeneratedDescriptorOrImagePage(page)
        }
        val now = SystemClock.elapsedRealtime()
        val trustedCount = ReaderImageCache.trustedNtkImageApiCount(
            manga.ntkEpisodePath,
            now - 30_000L
        )
        val beforeFirstDrawable = !firstDrawableDelivered.get() || ntkFirstBitmapAtMs.get() <= 0L
        val afterFirstImmediateRunway =
            reason == "first_bitmap_immediate" &&
                !beforeFirstDrawable
        val viewportAnchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?.coerceIn(0, refs.lastIndex)
            ?: start
        val startContinuousPending = !initialContinuousDrawableDelivered(start)
        val viewportContinuousPending = !initialContinuousDrawableDelivered(viewportAnchor)
        val initialContinuousPending = startContinuousPending || viewportContinuousPending
        val requiredLast = maxOf(
            start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1,
            viewportAnchor + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        )
        val runwayPages = if (afterFirstImmediateRunway) {
            minOf(defaultRunwayPages, ntkFirstBitmapFastScrollProofRunwayPages())
        } else if (initialContinuousPending) {
            val initialPendingRunway = if (beforeFirstDrawable) {
                if (isNtkWebtoonEpisodePath(manga.ntkEpisodePath)) {
                    NTK_PRE_FIRST_WEBTOON_DRAWABLE_RUNWAY_PAGES
                } else {
                    NTK_PRE_FIRST_MANHWA_DRAWABLE_RUNWAY_PAGES
                }
            } else {
                NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES + initialContinuousViewportAheadPages()
            }
            minOf(
                defaultRunwayPages,
                maxOf(
                    initialPendingRunway,
                    requiredLast - start + 1
                )
            )
        } else if (
            reason == "early_urls_pre_first" &&
            generatedOnlyRefs &&
            trustedCount <= 0
        ) {
            minOf(defaultRunwayPages, initialContinuousViewportAheadPages() + 1)
        } else {
            defaultRunwayPages
        }
        val last = minOf(refs.lastIndex, maxOf(start + runwayPages - 1, requiredLast))
        if (last < start) return
        val key = "$start|$last|${refs.size}|$reason"
        if (
            key == lastInitialFastFlingRunwayKey.get() &&
            now - lastInitialFastFlingRunwayAtMs.get() < NTK_FAST_FLING_RUNWAY_REPEAT_SUPPRESS_MS
        ) {
            return
        }
        lastInitialFastFlingRunwayKey.set(key)
        lastInitialFastFlingRunwayAtMs.set(now)
        var requested = 0
        var sourceRequested = 0
        var decodeRequested = 0
        var activeProofRequested = 0
        val requestedIndexes = ArrayList<Int>()
        val sourceOnlyIndexes = ArrayList<Int>()
        val activeProofLimit = if (
            afterFirstImmediateRunway &&
            (isActiveGeneratedTouchOrQuiet() || viewportBusy.get() || isWithinFirstBitmapInputGrace())
        ) {
            NTK_FIRST_BITMAP_ACTIVE_PROOF_REQUEST_LIMIT
        } else {
            Int.MAX_VALUE
        }
        val knownFullFirstBitmapRunway =
            reason == "early_urls_pre_first" &&
                beforeFirstDrawable &&
                isKnownFullGeneratedEpisodeInstalled()
        val physicalPreInputRunwayOnly =
            reason == "first_bitmap_immediate" &&
                lastUserInteractionMs.get() <= 0L &&
                !viewportBusy.get()
        val proofLast = if (knownFullFirstBitmapRunway || physicalPreInputRunwayOnly) {
            // The warmup owner already prepares the real viewport and 1.5-view runway. Decode
            // only that physical launch window before the first touch; keep the remaining fast-
            // fling range as compressed bytes so decode allocation cannot trigger GC on DOWN.
            minOf(last, requiredLast)
        } else {
            last
        }
        for (index in start..last) {
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (hasDeliveredBitmap(index) || (pendingDeliveryWidths[index] ?: 0) > 0) continue
            val image = page.image.orEmpty()
            if (image.isBlank()) continue
            if (isNtkGeneratedDescriptorOrImagePage(page)) {
                val proofDrawable = index <= proofLast && activeProofRequested < activeProofLimit
                val scheduled = if (hasPageSourceReady(index, page)) {
                    if (proofDrawable) {
                        scheduleVisibleGeneratedCachedDecode(
                            index,
                            page,
                            "fast_fling_$reason",
                            now,
                            forceRequeue = true,
                            proofDrawable = true,
                            allowOutsideProofWindow = true
                        )
                    } else {
                        false
                    }
                } else if (physicalPreInputRunwayOnly && !proofDrawable) {
                    scheduleProgressiveFarTailSource(
                        index,
                        page,
                        "fast_fling_${reason}_source"
                    )
                } else {
                    startInitialInteractiveRunwayByteFetch(
                        index,
                        page,
                        if (proofDrawable) "fast_fling_$reason" else "fast_fling_${reason}_source",
                        forceProofDrawable = proofDrawable,
                        allowOutsideProofWindow = proofDrawable
                    )
                }
                if (scheduled) {
                    requested++
                    if (proofDrawable && hasPageSourceReady(index, page)) {
                        decodeRequested++
                        activeProofRequested++
                    } else {
                        sourceRequested++
                        if (!proofDrawable && sourceOnlyIndexes.size < 32) sourceOnlyIndexes.add(index)
                    }
                    if (requestedIndexes.size < 32) requestedIndexes.add(index)
                } else if (index <= proofLast && !proofDrawable) {
                    if (!hasPageSourceReady(index, page) &&
                        startInitialInteractiveRunwayByteFetch(
                            index,
                            page,
                            "fast_fling_${reason}_active_limit_source",
                            forceProofDrawable = false,
                            allowOutsideProofWindow = false
                        )
                    ) {
                        requested++
                        sourceRequested++
                        if (sourceOnlyIndexes.size < 32) sourceOnlyIndexes.add(index)
                        if (requestedIndexes.size < 32) requestedIndexes.add(index)
                    }
                }
            } else {
                requestPage(
                    index,
                    busy = true,
                    anchor = index == start,
                    generation = FOREGROUND_PRIME_WARM_GENERATION
                )
                requested++
                decodeRequested++
                if (requestedIndexes.size < 32) requestedIndexes.add(index)
            }
        }
        Log.d(
            TAG,
            "reader_ntk_fast_fling_runway reason=$reason,start=$start,last=$last,total=${refs.size}," +
                "requested=$requested,source=$sourceRequested,decode=$decodeRequested,trusted=$trustedCount," +
                "beforeFirstDrawable=$beforeFirstDrawable,viewportAnchor=$viewportAnchor," +
                "startContinuousPending=$startContinuousPending," +
                "viewportContinuousPending=$viewportContinuousPending," +
                "proofLast=$proofLast,activeProofLimit=$activeProofLimit," +
                "sourceOnlyIndexes=${sourceOnlyIndexes.joinToString("|")}," +
                "requestedIndexes=${requestedIndexes.joinToString("|")}"
        )
    }

    private fun ntkInitialRapidScrollAheadPages(reason: String): Int {
        if (!isImmediateNtkGeneratedUx()) return NTK_INITIAL_RAPID_SCROLL_DECODE_AHEAD_PAGES
        return when (reason) {
            "first_bitmap_followups_input_grace" -> NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
            "first_bitmap_followups",
            "secondary_visible_quiet" -> NTK_INITIAL_INTERACTIVE_VIEWPORT_AHEAD_PAGES * 2
            "initial_full_decode_near",
            "generated_full_decode_initial_near",
            "generated_full_byte_prefetch_runway" -> NTK_INITIAL_INTERACTIVE_VIEWPORT_AHEAD_PAGES * 2
            else -> NTK_INITIAL_RAPID_SCROLL_DECODE_AHEAD_PAGES
        }
    }

    private fun ntkFirstBitmapFastScrollProofRunwayPages(): Int {
        return if (isNtkWebtoonEpisodePath(manga.ntkEpisodePath)) {
            NTK_FIRST_BITMAP_WEBTOON_PROOF_RUNWAY_PAGES
        } else {
            NTK_FIRST_BITMAP_MANHWA_PROOF_RUNWAY_PAGES
        }
    }

    private fun requestInitialContinuousGeneratedAfterFirstBitmap(reason: String) {
        if (strictExactColdRolling) return
        if (!isImmediateNtkGeneratedUx()) return
        val baseReason = initialContinuousFollowupBaseReason(reason)
        val quietMs = readerQuietRemainingMs(NTK_FIRST_BITMAP_FOLLOWUP_INPUT_GRACE_MS)
        if (quietMs > 0L) {
            if (shouldStopInitialContinuousInputGraceRunway()) {
                Log.d(
                    TAG,
                    "reader_initial_continuous_input_grace_stop reason=$baseReason," +
                        "start=${currentStartPage()},viewport=${currentViewportAnchor.get()}"
                )
                return
            }
            val beforeKey = lastInitialInteractiveRunwayReasonKey.get()
            val beforeAt = lastInitialInteractiveRunwayAtMs.get()
            primeInitialInteractiveRunwayBytes("${baseReason}_input_grace")
            val didRun = lastInitialInteractiveRunwayReasonKey.get() != beforeKey ||
                lastInitialInteractiveRunwayAtMs.get() != beforeAt
            if (didRun || !isActiveGeneratedTouchOrQuiet()) {
                postFirstBitmapControl(quietMs.coerceAtMost(NTK_FIRST_BITMAP_FOLLOWUP_QUIET_POLL_MS)) {
                    if (!cancelled.get()) requestInitialContinuousGeneratedAfterFirstBitmap(baseReason)
                }
            }
            return
        }
        val start = currentStartPage()
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0 || start !in 0 until count) return
        val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: start
        val activeInput = isActiveGeneratedTouchOrQuiet()
        val followupStart = if (activeInput) viewportAnchor else start
        val followupAhead = if (activeInput) {
            initialContinuousViewportAheadPages()
        } else {
            NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        }
        val last = if (activeInput) {
            minOf(count - 1, initialInteractiveRunwayLastIndex(count), followupStart + followupAhead)
        } else {
            minOf(count - 1, followupStart + followupAhead)
        }
        if (last <= start) return
        if (!initialContinuousAfterFirstBitmapStarted.compareAndSet(false, true)) return
        var requested = 0
        var generatedRequested = 0
        var directRequested = 0
        var promotedPending = 0
        for (index in maxOf(start + 1, followupStart)..last) {
            val page = pageRef(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!isInitialContinuousNtkImage(page)) continue
            if (hasDeliveredBitmap(index)) continue
            val pendingWidth = pendingDeliveryWidths[index] ?: 0
            if (pendingWidth > 0) {
                promoteVisiblePendingDelivery(index)
                requested++
                promotedPending++
                continue
            }
            val now = SystemClock.elapsedRealtime()
            val proofDrawable = activeInput || shouldUseImmediateGeneratedProofDrawable(page)
            if (isNtkGeneratedDescriptorOrImagePage(page)) {
                val cachedScheduled = scheduleVisibleGeneratedCachedDecode(
                    index,
                    page,
                    "initial_continuous_$reason",
                    now,
                    forceRequeue = true,
                    proofDrawable = proofDrawable,
                    allowOutsideProofWindow = proofDrawable
                )
                if (!cachedScheduled) {
                    if (proofDrawable) {
                        startInitialInteractiveRunwayByteFetch(
                            index,
                            page,
                            "initial_continuous_$reason",
                            forceProofDrawable = true,
                            allowOutsideProofWindow = true
                        )
                    } else {
                        hedgeVisibleGeneratedByteFetch(index, page, "initial_continuous_$reason", 0L)
                    }
                }
                generatedRequested++
            } else {
                requestPage(
                    index,
                    busy = true,
                    anchor = index == followupStart,
                    generation = FOREGROUND_PRIME_WARM_GENERATION
                )
                directRequested++
            }
            requested++
        }
        Log.d(
            TAG,
            "reader_initial_continuous_after_first_bitmap reason=$reason,start=$start," +
                "viewport=$viewportAnchor,followupStart=$followupStart,requested=$requested," +
                "generated=$generatedRequested,direct=$directRequested,promoted=$promotedPending"
        )
        if (collapseInitialMissingNtkGeneratedGapToCachedPage("initial_continuous_${reason}_immediate")) {
            requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), synchronized(pagesLock) { pages.size })
        } else {
            scheduleInitialMissingNtkGeneratedGapCollapse("initial_continuous_$reason", attempts = 18)
        }
    }

    private fun requestGeneratedFullEpisodeDecodeAfterFirstBitmap(forceImmediate: Boolean = false) {
        if (strictExactColdRolling) return
        if (!isNtkSource(manga, title)) return
        val quietMs = ntkBackgroundWarmQuietRemainingMs()
        if (!isImmediateNtkGeneratedUx() && quietMs > 0L) {
            scheduleGeneratedFullEpisodeDecodeRetry(quietMs)
            return
        }
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty()) return
        if (!isGeneratedOnlyNtkRefs(refs)) {
            requestInitialRapidScrollGeneratedWindow(refs, "initial_full_decode_near")
            return
        }
        if (isImmediateNtkGeneratedUx()) {
            requestGeneratedViewportProofAndRunwayBytes("generated_full_decode_initial")
            startInteractiveFullSourcePrefetch("first_bitmap_full_decode")
            requestAllUndeliveredNtkPages("generated_full_decode_initial")
            Log.d(
                TAG,
                "reader_ntk_generated_initial_request_full_surface total=${refs.size},forceImmediate=$forceImmediate"
            )
            return
        }
        requestInitialRapidScrollGeneratedWindow(refs, "generated_full_decode_initial_near")
        if (refs.size > NTK_FULL_SURFACE_WARM_MAX_PAGES) {
            scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(0L)
        } else if (hasUndeliveredNtkImmediateRunway(refs, currentStartPage().coerceIn(0, refs.lastIndex))) {
            if (!forceImmediate) {
                scheduleGeneratedFullEpisodeDecodeRetry(NTK_BACKGROUND_WARM_RECHECK_MS)
                return
            }
        }
        requestAllUndeliveredNtkPages("generated_full_decode_initial")
    }

    private fun scheduleGeneratedFullEpisodeDecodeRetry(delayMs: Long) {
        if (!generatedFullEpisodeDecodeRetryScheduled.compareAndSet(false, true)) return
        main.postDelayed({
            generatedFullEpisodeDecodeRetryScheduled.set(false)
            if (!cancelled.get()) requestGeneratedFullEpisodeDecodeAfterFirstBitmap()
        }, delayMs.coerceAtLeast(NTK_BACKGROUND_WARM_RECHECK_MS))
    }

    private fun shouldDeferFirstBitmapFollowups(firstBitmapElapsedAt: Long): Boolean {
        if (!isNtkSource(manga, title)) return false
        val path = manga.ntkEpisodePath ?: return false
        val initialContinuousPath = path.startsWith("/webtoon/", ignoreCase = true) ||
            path.startsWith("/manhwa/", ignoreCase = true) ||
            manga.baseMode == MTitle.base_webtoon
        if (!initialContinuousPath) return false
        if (SystemClock.elapsedRealtime() - firstBitmapElapsedAt >= NTK_FIRST_BITMAP_FOLLOWUP_MAX_DEFER_MS) {
            return false
        }
        val start = currentStartPage()
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0 || start !in 0 until count) return true
        val requiredAhead = if (
            path.startsWith("/webtoon/", ignoreCase = true) ||
            manga.baseMode == MTitle.base_webtoon
        ) {
            NTK_FIRST_BITMAP_WEBTOON_FOLLOWUP_READY_AHEAD
        } else {
            NTK_FIRST_BITMAP_MANHWA_FOLLOWUP_READY_AHEAD
        }
        val lastRequired = minOf(count - 1, start + requiredAhead)
        for (index in start..lastRequired) {
            if (!hasListenerDrawableDelivery(index)) return true
        }
        return false
    }

    private fun shouldDeferNonVisibleFirstBitmapFollowups(firstBitmapElapsedAt: Long): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (SystemClock.elapsedRealtime() - firstBitmapElapsedAt >=
            NTK_FIRST_BITMAP_FOLLOWUP_ACTIVE_INPUT_MAX_DEFER_MS
        ) {
            return false
        }
        return viewportBusy.get() ||
            ntkInitialInteractiveSettleRemainingMs() > 0L ||
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L
    }

    private fun initialContinuousFollowupBaseReason(reason: String): String {
        return reason.substringBefore("_quiet").substringBefore("_input_grace")
    }

    private fun shouldStopInitialContinuousInputGraceRunway(): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return true
        val start = currentStartPage().coerceIn(0, count - 1)
        val viewportAnchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?.coerceIn(0, count - 1)
            ?: start
        val viewportPage = pageRef(viewportAnchor)
        if (viewportPage != null && viewportPage.manga.ntkEpisodePath != manga.ntkEpisodePath) return true
        return viewportAnchor > start + NTK_INITIAL_INTERACTIVE_RUNWAY_PAGES - 1
    }

    private fun shouldDeferPostInitialContinuousNtkRequest(
        index: Int,
        page: PageRef,
        busy: Boolean,
        anchor: Boolean,
        generation: Int
    ): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        if (isImmediateNtkGeneratedUx() && busy && generation == FOREGROUND_PRIME_WARM_GENERATION) {
            Log.d(
                TAG,
                "reader_ntk_post_initial_continuous_bypass_full_prime page=$index," +
                    "start=${currentStartPage()},anchor=$anchor,generation=$generation"
            )
            return false
        }
        val start = currentStartPage()
        if (index < start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return false
        if (initialContinuousDrawableDelivered(start)) return false
        val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: start
        val actualViewportRequest =
            anchor ||
                index == viewportAnchor ||
                (generation == windowGeneration.get() && busy)
        if (actualViewportRequest || isInitialContinuousNarrowViewportRequest(index, viewportAnchor)) {
            Log.d(
                TAG,
                "reader_ntk_post_initial_continuous_bypass_viewport page=$index,start=$start," +
                    "viewportAnchor=$viewportAnchor,busy=$busy,anchor=$anchor,generation=$generation," +
                    "actualViewport=$actualViewportRequest"
            )
            return false
        }
        if (shouldBypassInitialContinuousGateForGeneratedUx(index, page, busy, anchor, generation)) {
            Log.d(
                TAG,
                "reader_ntk_post_initial_continuous_bypass page=$index,start=$start," +
                    "busy=$busy,anchor=$anchor,generation=$generation"
            )
            return false
        }
        if (!postInitialContinuousDeferredRequests.add(index)) return true
        val retryDelayMs = maxOf(
            NTK_POST_INITIAL_CONTINUOUS_RETRY_MS,
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS)
        )
        Log.d(
            TAG,
            "reader_ntk_post_initial_continuous_defer page=$index,start=$start," +
                "busy=$busy,anchor=$anchor,generation=$generation,delayMs=$retryDelayMs"
        )
        main.postDelayed({
            postInitialContinuousDeferredRequests.remove(index)
            if (cancelled.get()) return@postDelayed
            val latest = pageRef(index) ?: return@postDelayed
            if (!sameNtkSourceSlot(page, latest)) return@postDelayed
            requestPage(index, busy = busy, anchor = anchor, generation = generation)
        }, retryDelayMs)
        return true
    }

    private fun shouldBypassInitialContinuousGateForGeneratedUx(
        index: Int,
        page: PageRef,
        busy: Boolean,
        anchor: Boolean,
        generation: Int
    ): Boolean {
        if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        val start = currentStartPage()
        val lastAllowed = minOf(pagesLastIndex(), start + NTK_INITIAL_RAPID_SCROLL_DECODE_AHEAD_PAGES)
        if (index !in (start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)..lastAllowed) return false
        if (!initialContinuousDrawableDelivered(start)) return false
        val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: start
        val actualViewportRequest = generation >= 0 && (anchor || index == viewportAnchor)
        val initialRapidPrimeRequest =
            generation == FOREGROUND_PRIME_WARM_GENERATION &&
                busy &&
                index in max(0, viewportAnchor - 1)..(viewportAnchor + NTK_ACTIVE_VISIBLE_DIRECT_DECODE_AHEAD_PAGES)
        return actualViewportRequest || initialRapidPrimeRequest
    }

    private fun isInitialRapidGeneratedUrgent(
        index: Int,
        page: PageRef,
        busy: Boolean,
        generation: Int
    ): Boolean {
        if (!busy || generation != FOREGROUND_PRIME_WARM_GENERATION) return false
        if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        val start = currentStartPage()
        val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: start
        if (isWithinFirstBitmapInputGrace() || viewportBusy.get()) {
            return index in max(0, viewportAnchor - 1)..(viewportAnchor + activeGeneratedProofAheadPages())
        }
        return index <= start + NTK_INITIAL_RAPID_SCROLL_URGENT_PAGES ||
            index in max(0, viewportAnchor - 2)..(viewportAnchor + 2)
    }

    private fun initialContinuousDrawableDelivered(start: Int): Boolean {
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return false
        val last = minOf(count - 1, start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1)
        if (last < start) return false
        for (pageIndex in start..last) {
            if (!hasListenerDrawableDelivery(pageIndex)) return false
        }
        return true
    }

    private fun isInitialOrActiveContinuousWindowIndex(index: Int): Boolean {
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return false
        val start = currentStartPage().coerceIn(0, count - 1)
        val startFirst = max(0, start - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)
        val startLast = minOf(count - 1, start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1)
        if (index in startFirst..startLast) return true
        val viewportAnchor = currentViewportAnchor.get()
            .takeIf { it >= 0 }
            ?.coerceIn(0, count - 1)
            ?: start
        val viewportFirst = max(0, viewportAnchor - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)
        val viewportLast = minOf(count - 1, viewportAnchor + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1)
        return index in viewportFirst..viewportLast
    }

    private fun shouldHoldNtkGeneratedTailForInitialContinuous(): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        val start = currentStartPage()
        val count = synchronized(pagesLock) { pages.size }
        if (count <= start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return false
        return !initialContinuousDrawableDelivered(start)
    }

    private fun initialViewportDeliveredForFollowupsCount(): Int {
        val start = currentStartPage()
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0 || start !in 0 until count) return 0
        val path = manga.ntkEpisodePath.orEmpty()
        val requiredAhead = if (
            path.startsWith("/webtoon/", ignoreCase = true) ||
            manga.baseMode == MTitle.base_webtoon
        ) {
            NTK_FIRST_BITMAP_WEBTOON_FOLLOWUP_READY_AHEAD
        } else {
            NTK_FIRST_BITMAP_MANHWA_FOLLOWUP_READY_AHEAD
        }
        val lastRequired = minOf(count - 1, start + requiredAhead)
        var delivered = 0
        for (index in start..lastRequired) {
            if (hasListenerDrawableDelivery(index)) delivered++
        }
        return delivered
    }

    private fun scheduleObservedManhwaGeneratedExpansionAfterFirstBitmap(
        target: Manga,
        initialInstalledCount: Int,
        loadStartedAt: Long
    ) {
        if (cancelled.get() ||
            !isNtkSource(target, title) ||
            !isNtkManhwaEpisodePath(target.ntkEpisodePath)
        ) {
            return
        }
        try {
            control.execute {
            val firstBitmapDeadline =
                SystemClock.elapsedRealtime() + NTK_EARLY_GENERATED_EXPAND_AFTER_FIRST_BITMAP_WAIT_MS
            while (!cancelled.get() && !firstDrawableDelivered.get() && SystemClock.elapsedRealtime() < firstBitmapDeadline) {
                try {
                    Thread.sleep(NTK_EARLY_URL_POLL_MS)
                } catch (e: InterruptedException) {
                    Thread.currentThread().interrupt()
                    return@execute
                }
            }
            if (cancelled.get() || !firstDrawableDelivered.get()) return@execute
            var installedCount = initialInstalledCount
            val appendDeadline = SystemClock.elapsedRealtime() + NTK_OBSERVED_MANHWA_APPEND_AFTER_FIRST_BITMAP_WAIT_MS
            while (!cancelled.get() && SystemClock.elapsedRealtime() < appendDeadline) {
                val earlyUrls = ReaderImageCache
                    .earlyNtkImageUrls(target.ntkEpisodePath, SystemClock.elapsedRealtime() - 30000L)
                    .filter { isNtkGeneratedImageUrl(it) }
                val observed = observedInitialManhwaGeneratedUrls(target, earlyUrls)
                if (observed.size > installedCount) {
                    appendInitialNtkUrlsAfterEarlyInstall(
                        target,
                        observed,
                        loadStartedAt,
                        allowFirstBitmapDefer = false
                    )
                    installedCount = observed.size
                    logNtkRepositoryStage(
                        target,
                        "early_urls_observed_manhwa_append_after_first",
                        "count=$installedCount,raw=${earlyUrls.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
                    )
                    requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), installedCount)
                    if (installedCount >= ntkInitialGeneratedRecoveryPagesForTarget(target)) return@execute
                }
                try {
                    Thread.sleep(NTK_EARLY_URL_POLL_MS)
                } catch (e: InterruptedException) {
                    Thread.currentThread().interrupt()
                    return@execute
                }
            }
            }
        } catch (_: RejectedExecutionException) {
            // A late early-URL callback can race ReaderSession.cancel(). Once the
            // session is cancelled there is no expansion work left to preserve.
        }
    }

    private fun appendLatestEarlyNtkUrlsAfterFirstBitmap(loadStartedAt: Long) {
        if (!isNtkSource(manga, title)) return
        val latest = ReaderImageCache.earlyNtkImageUrls(manga.ntkEpisodePath, 0L)
        if (latest.isEmpty()) return
        val installedCount = synchronized(pagesLock) { pages.size }
        if (latest.size < installedCount && shouldAllowNtkGeneratedVerifiedShrink(manga, latest)) {
            appendInitialNtkUrlsAfterEarlyInstall(manga, latest, loadStartedAt, allowFirstBitmapDefer = true)
            logNtkRepositoryStage(
                manga,
                "early_urls_latest_shrink_after_first_bitmap",
                "from=$installedCount,to=${latest.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), latest.size)
            return
        }
        if (latest.size <= installedCount) {
            if (refreshInstalledNtkGeneratedImagesFromEarlyUrls(manga, latest, "early_urls_latest_same_size")) {
                requestAllUndeliveredNtkPages("generated_full_decode_refresh")
                requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), latest.size)
            }
            return
        }
        val trustedDirectGenerated = isTrustedDirectGeneratedEpisode(manga)
        val generatedFullExpansion = latest.all { isNtkGeneratedImageUrl(it) }
        val allowAppendDefer = !trustedDirectGenerated
        appendInitialNtkUrlsAfterEarlyInstall(
            manga,
            latest,
            loadStartedAt,
            allowFirstBitmapDefer = allowAppendDefer,
            forceImmediatePublish = shouldForceImmediateVerifiedEarlyUrlRefresh(latest, "after_first_latest")
        )
        if (generatedFullExpansion && allowAppendDefer && generatedFullAppendQuietRemainingMs() > 0L) {
            logNtkRepositoryStage(
                manga,
                if (trustedDirectGenerated) {
                    "early_urls_latest_append_after_first_bitmap_trusted_direct"
                } else {
                    "early_urls_latest_append_after_first_bitmap_deferred"
                },
                "from=$installedCount,to=${latest.size},trustedDirectGenerated=$trustedDirectGenerated,ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
            )
            if (!trustedDirectGenerated) return
        }
        logNtkRepositoryStage(
            manga,
            "early_urls_latest_append_after_first_bitmap",
            "from=$installedCount,to=${latest.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        requestInitialContinuousPagesFromEarlyUrls(currentStartPage(), latest.size)
    }

    private fun refreshInstalledNtkGeneratedImagesFromLatestEarlyUrls(
        target: Manga,
        reason: String,
        loadStartedAt: Long
    ): Boolean {
        if (cancelled.get() || !isNtkSource(target, title)) return false
        val latest = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, 0L)
        if (!shouldRefreshInstalledNtkGeneratedImagesFromEarlyUrls(target, latest)) return false
        if (!refreshInstalledNtkGeneratedImagesFromEarlyUrls(target, latest, reason)) return false
        val start = currentStartPage()
        logNtkRepositoryStage(
            target,
            "early_urls_latest_same_count_replace",
            "reason=$reason,count=${latest.size},ms=${SystemClock.elapsedRealtime() - loadStartedAt}"
        )
        requestPageForeground(start)
        requestInitialContinuousPagesFromEarlyUrls(start, latest.size)
        scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(0L)
        return true
    }

    private fun shouldRefreshInstalledNtkGeneratedImagesFromEarlyUrls(
        target: Manga,
        urls: List<String>,
        forceBySourceIndex: Boolean = false
    ): Boolean {
        if (urls.isEmpty() || !isNtkSource(target, title)) return false
        if (urls.any { !isNtkGeneratedImageUrl(it) }) return false
        val current = currentNtkInstalledImages(target)
        if (current.isEmpty()) return false
        if (
            shouldBlockTrustedNtkGeneratedShrink(target, urls.size, "refresh_installed_precheck") &&
            !shouldAllowKpUploadReplacementOverProtected(current, urls)
        ) {
            return false
        }
        if (forceBySourceIndex) {
            val limit = minOf(current.size, urls.size)
            for (index in 0 until limit) {
                val existing = current[index]
                val replacement = urls[index]
                if (existing != replacement && isNtkGeneratedImageUrl(existing)) return true
            }
        }
        return hasInitialVerifiedReplacement(current, urls)
    }

    private fun refreshInstalledNtkGeneratedImagesFromEarlyUrls(
        target: Manga,
        urls: List<String>,
        reason: String,
        forceBySourceIndex: Boolean = false
    ): Boolean {
        if (strictExactColdRolling) return false
        if (urls.isEmpty() || !isNtkSource(target, title)) return false
        if (urls.any { !isNtkGeneratedImageUrl(it) }) return false
        val currentImages = currentNtkInstalledImages(target)
        if (
            shouldBlockTrustedNtkGeneratedShrink(target, urls.size, reason) &&
            !shouldAllowKpUploadReplacementOverProtected(currentImages, urls)
        ) {
            return false
        }
        val changedIndexes = ArrayList<Int>()
        val changedImages = ArrayList<String>()
        val initialVisibleChangedImages = ArrayList<String>()
        val protectedInitialVisibleIndexes = ArrayList<Int>()
        val initialVisibleFirst = currentStartPage()
        val initialVisibleLast = initialVisibleFirst + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        val initialExtensionPromotionOnly =
            reason.contains("extension_promotion", ignoreCase = true) &&
                isPureGeneratedExtensionPromotion(currentNtkInstalledImages(target), urls)
        val initialExtensionRunwayLastSource =
            NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES + NTK_INTERACTIVE_PROOF_AHEAD_PAGES - 1
        val extensionRunwayBytePrefetches = ArrayList<Pair<Int, PageRef>>()
        synchronized(pagesLock) {
            for (index in pages.indices) {
                val ref = pages[index]
                if (ref.transitionTitle != null || !Manga.sameEpisodeIdentity(ref.manga, target)) continue
                if (initialExtensionPromotionOnly && ref.sourceIndex > initialExtensionRunwayLastSource) continue
                val replacement = urls.getOrNull(ref.sourceIndex) ?: continue
                val current = ref.image
                if (current == replacement) continue
                if (!isNtkGeneratedImageUrl(current.orEmpty())) continue
                val currentImage = current.orEmpty()
                if (
                    !forceBySourceIndex &&
                    !initialExtensionPromotionOnly &&
                    index in initialVisibleFirst..initialVisibleLast &&
                    hasInitialVisibleGeneratedWork(index)
                ) {
                    protectedInitialVisibleIndexes.add(index)
                    continue
                }
                changedImages.add(currentImage)
                if (!firstBitmapLogged.get() && index in initialVisibleFirst..initialVisibleLast) {
                    initialVisibleChangedImages.add(currentImage)
                }
                ref.image = replacement
                changedIndexes.add(index)
                if (
                    initialExtensionPromotionOnly &&
                    ref.sourceIndex in NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES..initialExtensionRunwayLastSource
                ) {
                    extensionRunwayBytePrefetches.add(index to ref)
                }
            }
        }
        if (changedIndexes.isEmpty()) return false
        if (initialVisibleChangedImages.isNotEmpty()) {
            ReaderImageCache.cancelNtkGeneratedForegroundWorkForImages(
                target,
                initialVisibleChangedImages,
                "${reason}_initial_visible"
            )
        }
        if (changedIndexes.contains(currentStartPage())) {
            initialAnchorCachedDecodeStarted.set(false)
            removeInitialAnchorAssetDecodeListenersForEpisode(target)
        }
        for (index in changedIndexes) {
            failedPages.remove(index)
            loading.remove(index)
            urgentLoading.remove(index)
            loadingPages.remove(index)
            urgentLoadingPages.remove(index)
            loadingStartedAtMs.remove(index)
            inFlightWidths.remove(index)
            pendingDeliveryWidths.remove(index)
            visibleGeneratedByteHedges.remove(index)
            visibleGeneratedDecodeHedges.remove(index)
            initialGeneratedAssetDecodeListeners.remove(index)
            initialInteractiveRunwayByteFetches.remove(index)
        }
        Log.d(
            TAG,
            "refresh_installed_ntk_generated_images reason=$reason,path=${target.ntkEpisodePath}," +
                "changed=${changedIndexes.size},indexes=${changedIndexes.take(32).joinToString("|")}," +
                "protectedInitial=${protectedInitialVisibleIndexes.take(8).joinToString("|")}"
        )
        if (initialVisibleChangedImages.isEmpty()) {
            scheduleCancelNtkGeneratedForegroundWorkForImages(target, changedImages, reason)
        } else {
            val initialVisibleSet = HashSet(initialVisibleChangedImages)
            scheduleCancelNtkGeneratedForegroundWorkForImages(
                target,
                changedImages.filterNot { initialVisibleSet.contains(it) },
                reason
            )
        }
        for ((index, ref) in extensionRunwayBytePrefetches) {
            startInitialInteractiveRunwayByteFetch(index, ref, "${reason}_extension_runway")
        }
        return true
    }

    private fun tryScheduleNtkAnchorBytesDecode(
        index: Int,
        page: PageRef,
        image: String,
        bytes: ByteArray,
        reason: String,
        startedAt: Long
    ): Boolean {
        if (!initialAnchorCachedDecodeStarted.compareAndSet(false, true)) {
            logNtkPagePerf(index, "ntk_anchor_bytes_decode_skip", "reason=$reason,already_started=true")
            return true
        }
        try {
            initialAnchorDecode.execute {
                val decodeStartedAt = SystemClock.elapsedRealtime()
                var posted = false
                try {
                    if (
                        cancelled.get() ||
                        firstBitmapLogged.get() ||
                        pageRef(index) != page ||
                        hasDeliveredBitmap(index)
                    ) {
                        return@execute
                    }
                    val targetWidth = targetWidth(page, true)
                    val result = decodePageBytes(index, page, bytes, targetWidth)
                    if (
                        cancelled.get() ||
                        pageRef(index) != page ||
                        currentPageIndexForDelivery(page, index) < 0
                    ) {
                        recycleDecodeResult(result)
                        return@execute
                    }
                    logNtkPagePerf(
                        index,
                        "ntk_anchor_bytes_decode_ready",
                        "reason=$reason,waitMs=${decodeStartedAt - startedAt},decodeMs=${SystemClock.elapsedRealtime() - decodeStartedAt},width=${result.width},image=${image.substringAfterLast('/').takeLast(64)}"
                    )
                    posted = true
                    postDecodeResult(Delivery(index, page, result, decodeStartedAt, targetWidth, retainWhenBusy = true))
                    cancelInitialGeneratedForegroundWorkAfterDrawableQueued(
                        page,
                        image,
                        "anchor_bytes_decode_posted"
                    )
                } catch (e: Exception) {
                    recordIfUnexpected(e)
                    postPageError(index, page, e)
                } finally {
                    if (!posted && !firstBitmapLogged.get() && !hasDeliveredBitmap(index)) {
                        initialAnchorCachedDecodeStarted.set(false)
                        logNtkPagePerf(index, "ntk_anchor_bytes_decode_aborted", "reason=$reason")
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            initialAnchorCachedDecodeStarted.set(false)
            return false
        }
        return true
    }

    private fun hasInitialVisibleGeneratedWork(index: Int): Boolean {
        if (hasDeliveredBitmap(index)) return true
        if ((pendingDeliveryWidths[index] ?: 0) > 0) return true
        if (initialDeliveryBacklog.containsKey(index)) return true
        if (initialPreparedBacklog.containsKey(index)) return true
        return false
    }

    private fun isInitialContinuousNarrowViewportRequest(index: Int, viewportAnchor: Int): Boolean {
        if (viewportAnchor < 0) return false
        val lastAllowed = minOf(
            pagesLastIndex(),
            viewportAnchor + NTK_INITIAL_INTERACTIVE_VIEWPORT_AHEAD_PAGES
        )
        return index in viewportAnchor..lastAllowed
    }

    private fun scheduleCancelNtkGeneratedForegroundWorkForImages(
        target: Manga,
        images: List<String>,
        reason: String
    ) {
        if (images.isEmpty()) return
        val snapshot = ArrayList(images)
        try {
            cleanup.execute {
                ReaderImageCache.cancelNtkGeneratedForegroundWorkForImages(target, snapshot, reason)
            }
        } catch (_: RejectedExecutionException) {
            // Session teardown: stale generated foreground work will be cancelled with the session.
        }
    }

    private fun shouldAllowNtkGeneratedVerifiedShrink(target: Manga, urls: List<String>): Boolean {
        if (!isNtkSource(target, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        if (urls.size <= 1 || urls.any { !isNtkGeneratedImageUrl(it) }) return false
        val knownCount = target.ntkImageCount
        if (knownCount > urls.size && !hasKnownMissingGeneratedTailAfter(target, urls.size)) return false
        val latest = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, SystemClock.elapsedRealtime() - 30000L)
        if (latest.size != urls.size || latest.any { !isNtkGeneratedImageUrl(it) }) return false
        return latest.toSet() == urls.toSet()
    }

    private fun hasKnownMissingGeneratedTailAfter(target: Manga, verifiedCount: Int): Boolean {
        if (verifiedCount <= 0) return false
        return synchronized(pagesLock) {
            val last = minOf(pages.lastIndex, verifiedCount + NTK_GENERATED_INITIAL_RECOVERY_PAGES)
            if (verifiedCount > last) return@synchronized false
            for (index in verifiedCount..last) {
                val page = pages.getOrNull(index) ?: continue
                if (!Manga.sameEpisodeIdentity(page.manga, target)) continue
                val image = page.image.orEmpty()
                if (isNtkGeneratedImageUrl(image) &&
                    ReaderImageCache.isKnownNtkGeneratedNotFound(target, image)
                ) {
                    return@synchronized true
                }
            }
            false
        }
    }

    private fun scheduleNtkSecondaryInitialWarmAfterFirstBitmap() {
        if (!isNtkSource(manga, title)) return
        val quietMs = ntkBackgroundWarmQuietRemainingMs()
        val immediateGeneratedUx = isImmediateNtkGeneratedUx()
        if (quietMs > 0L && !immediateGeneratedUx) {
            Log.d(TAG, "reader_ntk_secondary_initial_warm_defer_quiet delayMs=$quietMs")
            scheduleNtkSecondaryInitialWarmAfterFirstBitmap(quietMs)
            return
        }
        if (quietMs > 0L) {
            val refs = synchronized(pagesLock) { pages.toList() }
            requestInitialRapidScrollGeneratedWindow(refs, "secondary_visible_quiet")
            Log.d(TAG, "reader_ntk_secondary_initial_warm_defer_quiet_immediate delayMs=$quietMs")
            scheduleNtkSecondaryInitialWarmAfterFirstBitmap(quietMs)
            return
        }
        val first = currentStartPage()
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return
        val ntkWebtoon = isNtkWebtoonSource(manga, title)
        val nearDecodeAhead = if (ntkWebtoon) NTK_WEBTOON_INITIAL_NEAR_DECODE_AHEAD_PAGES else NTK_INITIAL_NEAR_DECODE_AHEAD_PAGES
        val fullDecodeAhead = if (ntkWebtoon) NTK_WEBTOON_INITIAL_DECODE_AHEAD_PAGES else NTK_INITIAL_DECODE_AHEAD_PAGES
        val priorityLast = minOf(count - 1, first + NTK_INITIAL_PRIORITY_PAGES)
        val nearLast = minOf(count - 1, first + nearDecodeAhead)
        if (priorityLast < nearLast) {
            main.postDelayed({
                if (cancelled.get()) return@postDelayed
                for (index in (priorityLast + 1)..nearLast) {
                    requestPage(
                        index,
                        busy = true,
                        anchor = false,
                        generation = if (immediateGeneratedUx) FOREGROUND_PRIME_WARM_GENERATION else PRIME_WARM_GENERATION
                    )
                }
            }, if (immediateGeneratedUx) 0L else NTK_INITIAL_SECONDARY_WARM_DELAY_MS)
        }
        if (immediateGeneratedUx) return
        val farLast = minOf(count - 1, first + fullDecodeAhead)
        if (nearLast >= farLast) return
        main.postDelayed({
            if (cancelled.get()) return@postDelayed
            scheduleNtkFarInitialWarmBatch(nearLast + 1, farLast)
        }, NTK_INITIAL_FAR_WARM_DELAY_MS)
    }

    private fun scheduleNtkSecondaryInitialWarmAfterFirstBitmap(delayMs: Long) {
        main.postDelayed({
            if (!cancelled.get()) scheduleNtkSecondaryInitialWarmAfterFirstBitmap()
        }, delayMs)
    }

    private fun scheduleNtkFarInitialWarmBatch(nextIndex: Int, farLast: Int) {
        if (cancelled.get() || nextIndex > farLast) return
        val delayMs = ntkCurrentBackgroundWarmDelayMs()
        val ackSafeLast = currentStartPage() + NTK_INITIAL_ACK_INFLIGHT_WARM_PAGES
        if (delayMs > 0L && nextIndex > ackSafeLast) {
            main.postDelayed({
                if (!cancelled.get()) scheduleNtkFarInitialWarmBatch(nextIndex, farLast)
            }, delayMs)
            return
        }
        val batchLast = minOf(
            farLast,
            nextIndex + NTK_INITIAL_FAR_WARM_BATCH_PAGES - 1,
            if (delayMs > 0L) ackSafeLast else farLast
        )
        for (index in nextIndex..batchLast) {
            requestPage(index, busy = true, anchor = false, generation = PRIME_WARM_GENERATION)
        }
        if (batchLast < farLast) {
            main.postDelayed({
                if (!cancelled.get()) scheduleNtkFarInitialWarmBatch(batchLast + 1, farLast)
            }, NTK_INITIAL_FAR_WARM_BATCH_DELAY_MS)
        }
    }

    private fun scheduleNtkSourcePrefetchAfterFirstBitmap() {
        if (!isNtkSource(manga, title)) return
        main.postDelayed({
            if (cancelled.get()) return@postDelayed
            val delayMs = ntkBackgroundWarmQuietRemainingMs()
            if (delayMs > 0L) {
                scheduleNtkSourcePrefetchAfterFirstBitmap(delayMs)
                return@postDelayed
            }
            prefetchImageFilesAround(currentStartPage(), ntkInitialSourcePrefetchAfterPages())
        }, NTK_INITIAL_SOURCE_PREFETCH_AFTER_FIRST_BITMAP_DELAY_MS)
    }

    private fun scheduleNtkSourcePrefetchAfterFirstBitmap(delayMs: Long) {
        main.postDelayed({
            if (!cancelled.get()) scheduleNtkSourcePrefetchAfterFirstBitmap()
        }, delayMs)
    }

    private fun ntkInitialSourcePrefetchAfterPages(): Int {
        return if (isNtkWebtoonSource(manga, title)) {
            NTK_WEBTOON_INITIAL_SOURCE_PREFETCH_AFTER
        } else {
            START_SOURCE_PREFETCH_AFTER
        }
    }

    private fun scheduleNtkGeneratedFullEpisodeBytePrefetchAfterFirstBitmap() {
        if (strictExactColdRolling) return
        if (!isNtkSource(manga, title)) return
        scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(
            if (isImmediateNtkGeneratedUx()) 0L else NTK_GENERATED_FULL_BYTE_PREFETCH_AFTER_FIRST_BITMAP_DELAY_MS
        )
    }

    private fun scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(delayMs: Long) {
        if (strictExactColdRolling) return
        main.postDelayed({
            if (isImmediateNtkGeneratedUx() && !firstDrawableDelivered.get()) {
                scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(
                    NTK_GENERATED_FULL_BYTE_PREFETCH_AFTER_FIRST_BITMAP_DELAY_MS
                )
                return@postDelayed
            }
            runNtkGeneratedFullEpisodeBytePrefetch()
        }, delayMs)
    }

    private fun runNtkGeneratedFullEpisodeBytePrefetch() {
        if (cancelled.get()) return
        if (shouldHoldNtkGeneratedTailForInitialContinuous()) {
            scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(NTK_GENERATED_FULL_BYTE_PREFETCH_BATCH_DELAY_MS)
            return
        }
        val delayMs = if (isImmediateNtkGeneratedUx()) {
            max(ntkBackgroundWarmQuietRemainingMs(), interactiveFullSourceQuietRemainingMs())
        } else {
            ntkBackgroundWarmQuietRemainingMs()
        }
        if (delayMs > 0L) {
            scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(delayMs)
            return
        }
        val refs = synchronized(pagesLock) { pages.toList() }
        if (!isGeneratedOnlyNtkRefs(refs)) return
        val anchor = currentStartPage().coerceIn(0, refs.lastIndex)
        if (hasUndeliveredNtkImmediateRunway(refs, anchor)) {
            requestInitialRapidScrollGeneratedWindow(refs, "generated_full_byte_prefetch_runway")
            scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(NTK_GENERATED_FULL_BYTE_PREFETCH_BATCH_DELAY_MS)
            return
        }
        if (hasUndeliveredNtkVisibleWindow(anchor, refs.lastIndex)) {
            scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(NTK_GENERATED_FULL_BYTE_PREFETCH_BATCH_DELAY_MS)
            return
        }
        val defaultFirst = minOf(refs.lastIndex, anchor + 1)
        if (defaultFirst > refs.lastIndex) return
        val first = ntkGeneratedFullBytePrefetchCursor.updateAndGet { current ->
            if (current < defaultFirst) defaultFirst else current
        }
        if (first > refs.lastIndex) return
        var scheduled = 0
        var nextIndex = first
        while (nextIndex <= refs.lastIndex && scheduled < NTK_GENERATED_FULL_BYTE_PREFETCH_BATCH_PAGES) {
            val index = nextIndex
            nextIndex++
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null || hasDeliveredBitmap(index)) continue
            network.execute {
                prefetchImageFileQuietly(index, page)
            }
            scheduled++
        }
        ntkGeneratedFullBytePrefetchCursor.set(nextIndex)
        Log.d(
            TAG,
            "reader_ntk_generated_full_byte_prefetch anchor=$anchor,from=$first," +
                "to=${refs.lastIndex},scheduled=$scheduled,next=$nextIndex"
        )
        ViewerWarmupManager.logMetric("reader_ntk_generated_full_byte_prefetch", scheduled.toLong())
        if (nextIndex <= refs.lastIndex) {
            scheduleNtkGeneratedFullEpisodeBytePrefetchAfterDelay(NTK_GENERATED_FULL_BYTE_PREFETCH_BATCH_DELAY_MS)
        }
    }

    private fun hasUndeliveredNtkVisibleWindow(anchor: Int, lastIndex: Int): Boolean {
        val first = max(0, anchor - NTK_WEBTOON_IDLE_VISIBLE_DECODE_RADIUS)
        val last = minOf(lastIndex, anchor + NTK_WEBTOON_IDLE_VISIBLE_DECODE_RADIUS)
        for (index in first..last) {
            val page = pageRef(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!hasDeliveredBitmap(index)) return true
        }
        return false
    }

    private fun hasUndeliveredNtkImmediateRunway(refs: List<PageRef>, anchor: Int): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isGeneratedOnlyNtkRefs(refs)) return false
        if (refs.isEmpty()) return false
        val safeAnchor = anchor.coerceIn(0, refs.lastIndex)
        val last = minOf(refs.lastIndex, safeAnchor + NTK_GENERATED_IMMEDIATE_RUNWAY_PAGES - 1)
        for (index in safeAnchor..last) {
            val page = refs.getOrNull(index) ?: continue
            if (page.transitionTitle != null) continue
            if (!isNtkGeneratedDescriptorOrImagePage(page)) continue
            if (!hasDeliveredBitmap(index)) return true
        }
        return false
    }

    private fun scheduleNtkEpisodeMetadataAfterFirstBitmap() {
        if (!isNtkSource(manga, title)) return
        main.postDelayed({
            val quietMs = ntkEpisodeMetadataQuietRemainingMs()
            if (quietMs > 0L) {
                scheduleNtkEpisodeMetadataAfterDelay(quietMs)
                return@postDelayed
            }
            fetchNtkEpisodeMetadataInBackground()
        }, NTK_EPISODE_METADATA_AFTER_FIRST_BITMAP_DELAY_MS)
    }

    private fun scheduleNtkEpisodeMetadataAfterDelay(delayMs: Long) {
        main.postDelayed({
            if (!cancelled.get()) scheduleNtkEpisodeMetadataAfterFirstBitmap()
        }, delayMs.coerceAtLeast(NTK_BACKGROUND_WARM_RECHECK_MS))
    }

    private fun fetchNtkEpisodeMetadataInBackground() {
        if (cancelled.get()) return
        if (!ntkEpisodeMetadataLoading.compareAndSet(false, true)) return
        try {
            primeNetwork.execute {
                try {
                    val quietMs = ntkEpisodeMetadataQuietRemainingMs()
                    if (quietMs > 0L) {
                        scheduleNtkEpisodeMetadataAfterDelay(quietMs)
                        return@execute
                    }
                    val currentTitle = title ?: manga.title ?: return@execute
                    if (!isNtkSource(manga, currentTitle)) return@execute
                    if (syncNtkTitlePathFromEpisode(currentTitle, manga)) {
                        currentTitle.removeEps()
                    }
                    restoreNtkEpisodeSnapshotIfNeeded(currentTitle, manga)
                    if ((currentTitle.eps?.size ?: 0) > 1) return@execute
                    val startedAt = SystemClock.elapsedRealtime()
                    val result = withRepositoryCancellation {
                        imageRepository.fetchEpisodesForeground(currentTitle, it)
                    }
                    if (cancelled.get()) return@execute
                    if (result == Title.LOAD_OK) {
                        attachTitle()
                        val episodes = Utils.snapshotEpisodes(currentTitle)
                        if (episodes.isNotEmpty()) {
                            manga.setEps(episodes)
                            persistNtkEpisodeSnapshot(currentTitle, episodes)
                        }
                    }
                    Log.d(
                        TAG,
                        "ntk_episode_metadata_prefetch result=$result ms=${SystemClock.elapsedRealtime() - startedAt} " +
                            "episodes=${currentTitle.eps?.size ?: 0}"
                    )
                } catch (e: Exception) {
                    recordIfUnexpected(e)
                } finally {
                    ntkEpisodeMetadataLoading.set(false)
                }
            }
        } catch (_: RejectedExecutionException) {
            ntkEpisodeMetadataLoading.set(false)
        }
    }

    private fun restoreNtkEpisodeSnapshotIfNeeded(currentTitle: Title, anchorManga: Manga): Boolean {
        if (!isNtkSource(anchorManga, currentTitle)) return false
        if ((currentTitle.eps?.size ?: 0) > 1) return true
        val episodes = readCachedNtkEpisodeSnapshot(currentTitle) ?: return false
        attachNtkEpisodeSnapshot(currentTitle, anchorManga, episodes)
        Log.d(
            TAG,
            "ntk_episode_snapshot_cache_hit titleId=${currentTitle.id} episodes=${episodes.size}"
        )
        return true
    }

    private fun readCachedNtkEpisodeSnapshot(currentTitle: Title): ArrayList<Manga>? {
        val primaryKey = EpisodeSnapshotCache.key(currentTitle, true)
        val legacyKey = EpisodeSnapshotCache.legacyKey(currentTitle)
        return readCachedNtkEpisodeSnapshot(primaryKey)
            ?: if (legacyKey == primaryKey) null else readCachedNtkEpisodeSnapshot(legacyKey)
    }

    private fun readCachedNtkEpisodeSnapshot(cacheKey: String): ArrayList<Manga>? {
        if (cacheKey.isEmpty()) return null
        val memoryJson = CacheFileStore.readMemory(cacheKey)
        parseCachedNtkEpisodeSnapshot(memoryJson)?.let { return it }
        val diskJson = CacheFileStore.read(appContext, cacheKey)
        return parseCachedNtkEpisodeSnapshot(diskJson)
    }

    private fun parseCachedNtkEpisodeSnapshot(json: String?): ArrayList<Manga>? {
        if (json.isNullOrEmpty()) return null
        return try {
            val snapshot = GSON.fromJson(json, CachedEpisodeSnapshot::class.java)
            val ordered = Title.orderedEpisodeSnapshot(snapshot?.episodes) ?: return null
            if (ordered.size > 1) ordered else null
        } catch (e: Exception) {
            recordIfUnexpected(e)
            null
        }
    }

    private fun attachNtkEpisodeSnapshot(currentTitle: Title, anchorManga: Manga, episodes: ArrayList<Manga>) {
        for (episode in episodes) {
            episode.title = currentTitle
            episode.titleId = currentTitle.id
        }
        currentTitle.setEps(episodes)
        manga.setEps(episodes)
        anchorManga.setEps(episodes)
        anchorManga.title = currentTitle
        anchorManga.titleId = currentTitle.id
    }

    private fun persistNtkEpisodeSnapshot(currentTitle: Title, episodes: List<Manga>) {
        if (!isNtkSource(manga, currentTitle) || episodes.size <= 1) return
        try {
            val snapshot = CachedEpisodeSnapshot()
            snapshot.episodes = ntkEpisodeSnapshotForCache(episodes)
            if (snapshot.episodes.isNullOrEmpty()) return
            CacheFileStore.writeAsync(appContext, EpisodeSnapshotCache.key(currentTitle, true), GSON.toJson(snapshot))
        } catch (e: Exception) {
            recordIfUnexpected(e)
        }
    }

    private fun ntkEpisodeSnapshotForCache(episodes: List<Manga>): ArrayList<Manga> {
        val ordered = Title.orderedEpisodeSnapshot(episodes) ?: return ArrayList()
        val copy = ArrayList<Manga>(ordered.size)
        for (episode in ordered) {
            val item = Manga(episode.id, episode.name, episode.date, episode.baseMode)
            item.addThumb(episode.thumb)
            item.mode = episode.mode
            item.titleId = episode.titleId
            item.setNtkEpisodePath(episode.ntkEpisodePath)
            item.ntkImageEpisodeId = episode.ntkImageEpisodeId
            item.ntkImageWorkId = episode.ntkImageWorkId
            item.ntkViewerPayloadHint = episode.ntkViewerPayloadHint
            item.setNtkImageCount(episode.ntkImageCount)
            item.offlinePath = episode.offlinePath
            copy.add(item)
        }
        return copy
    }

    private fun upgradeNtkInitialPriorityPagesAfterFirstBitmap() {
        if (!isNtkSource(manga, title)) return
        if (shouldLimitImmediateGeneratedToViewport()) {
            scheduleNtkInitialPriorityUpgradeAfterDelay(NTK_BACKGROUND_WARM_RECHECK_MS)
            return
        }
        val quietMs = ntkBackgroundWarmQuietRemainingMs()
        if (quietMs > 0L) {
            Log.d(TAG, "reader_ntk_initial_priority_upgrade_defer_quiet delayMs=$quietMs")
            scheduleNtkInitialPriorityUpgradeAfterDelay(quietMs)
            return
        }
        val first = currentStartPage()
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return
        val firstPriority = minOf(count - 1, first + NTK_INITIAL_PRIORITY_START_OFFSET)
        val priorityPages = if (isNtkWebtoonSource(manga, title)) {
            NTK_WEBTOON_INITIAL_BOOT_PRIORITY_PAGES
        } else if (isCurrentManhwaGeneratedOnlyRefs()) {
            NTK_MANHWA_GENERATED_INITIAL_VISIBLE_AHEAD_PAGES
        } else {
            NTK_INITIAL_PRIORITY_PAGES
        }
        val last = minOf(count - 1, first + priorityPages)
        if (firstPriority > last) return
        for (index in firstPriority..last) {
            requestPage(index, busy = true, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
        }
    }

    private fun scheduleNtkInitialPriorityUpgradeAfterDelay(delayMs: Long) {
        main.postDelayed({
            if (!cancelled.get()) upgradeNtkInitialPriorityPagesAfterFirstBitmap()
        }, delayMs.coerceAtLeast(NTK_BACKGROUND_WARM_RECHECK_MS))
    }

    private fun prefetchNtkInitialNextBytesAfterFirstBitmap() {
        if (!isNtkSource(manga, title)) return
        if (shouldLimitImmediateGeneratedToViewport()) {
            scheduleNtkInitialNextBytesAfterDelay(NTK_BACKGROUND_WARM_RECHECK_MS)
            return
        }
        val quietMs = ntkBackgroundWarmQuietRemainingMs()
        if (quietMs > 0L) {
            Log.d(TAG, "reader_ntk_initial_next_byte_prefetch_defer_quiet delayMs=$quietMs")
            scheduleNtkInitialNextBytesAfterDelay(quietMs)
            return
        }
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return
        prefetchNtkInitialNextBytes(currentStartPage(), count)
    }

    private fun scheduleNtkInitialNextBytesAfterDelay(delayMs: Long) {
        main.postDelayed({
            if (!cancelled.get()) prefetchNtkInitialNextBytesAfterFirstBitmap()
        }, delayMs.coerceAtLeast(NTK_BACKGROUND_WARM_RECHECK_MS))
    }

    private fun scheduleNtkForwardTimelinePrimeAfterFirstBitmap() {
        if (!isNtkSource(manga, title)) return
        if (NTK_PRIME_FORWARD_EPISODES <= 0) return
        if (!timelinePrimeRequested.compareAndSet(false, true)) return
        scheduleNtkForwardTimelinePrimeAfterDelay(ntkForwardPrimeDelayMs())
    }

    private fun scheduleNtkForwardTimelinePrimeAfterDelay(delayMs: Long) {
        main.postDelayed({
            if (cancelled.get()) return@postDelayed
            val quietMs = ntkBackgroundWarmQuietRemainingMs()
            if (quietMs > 0L) {
                scheduleNtkForwardTimelinePrimeAfterDelay(quietMs)
                return@postDelayed
            }
            primeForwardTimeline()
        }, delayMs)
    }

    private fun ntkBackgroundPrepareQuietRemainingMs(): Long {
        if (!isNtkSource(manga, title)) return 0L
        if (isImmediateNtkGeneratedUx()) return 0L
        val firstBitmapAt = ntkFirstBitmapAtMs.get()
        if (firstBitmapAt > 0L) {
            val quietFor = SystemClock.uptimeMillis() - firstBitmapAt
            val remaining = NTK_BACKGROUND_PREPARE_AFTER_FIRST_BITMAP_QUIET_MS - quietFor
            if (remaining > 0L) return remaining
        }
        if (viewportBusy.get()) return NTK_BACKGROUND_PREPARE_QUIET_MS
        val lastInteraction = lastUserInteractionMs.get()
        if (lastInteraction <= 0L) return 0L
        val quietFor = SystemClock.uptimeMillis() - lastInteraction
        return (NTK_BACKGROUND_PREPARE_QUIET_MS - quietFor).coerceAtLeast(0L)
    }

    private fun ntkBackgroundWarmQuietRemainingMs(): Long {
        if (!isNtkSource(manga, title)) return 0L
        if (isImmediateNtkGeneratedUx()) return 0L
        return maxOf(
            ntkBackgroundPrepareQuietRemainingMs(),
            ntkInitialInteractiveSettleRemainingMs(),
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS)
        )
    }

    private fun cancelNtkBackgroundFallbacksForActiveInput(reason: String) {
        if (!isNtkSource(manga, title)) return
        if (isImmediateNtkGeneratedUx()) return
        if (hasForegroundGeneratedDirectManifest()) return
        val now = SystemClock.uptimeMillis()
        val previous = ntkLastActiveInputFallbackCancelAtMs.get()
        if (now - previous < NTK_ACTIVE_INPUT_FALLBACK_CANCEL_THROTTLE_MS) return
        if (!ntkLastActiveInputFallbackCancelAtMs.compareAndSet(previous, now)) return
        try {
            MainApplication.getHttpClient().cancelNtkWebViewFallbacks()
            Log.d(TAG, "ntk_background_fallback_cancel_active_input reason=$reason,path=${manga.ntkEpisodePath}")
        } catch (_: Exception) {
        }
    }

    private fun ntkEpisodeMetadataQuietRemainingMs(): Long {
        if (!isNtkSource(manga, title)) return 0L
        val firstBitmapAt = ntkFirstBitmapAtMs.get()
        val launchQuietMs = if (firstBitmapAt > 0L) {
            (NTK_EPISODE_METADATA_INPUT_QUIET_MS -
                (SystemClock.uptimeMillis() - firstBitmapAt)).coerceAtLeast(0L)
        } else {
            NTK_EPISODE_METADATA_INPUT_QUIET_MS
        }
        return maxOf(
            launchQuietMs,
            readerQuietRemainingMs(NTK_EPISODE_METADATA_INPUT_QUIET_MS)
        )
    }

    private fun hasForegroundGeneratedDirectManifest(): Boolean {
        val path = manga.ntkEpisodePath ?: return false
        if (!MainApplication.isNtkForegroundViewerPath(path)) return false
        val urls = ReaderImageCache.earlyNtkImageUrls(path, SystemClock.elapsedRealtime() - 30_000L)
        if (urls.isNotEmpty() && urls.any { isNtkGeneratedImageUrl(it) }) return true
        return synchronized(pagesLock) {
            pages.isNotEmpty() &&
                pages.all { it.transitionTitle != null || isNtkGeneratedDescriptorOrImagePage(it) }
        }
    }

    private fun ntkInitialInteractiveSettleRemainingMs(): Long {
        if (!isNtkSource(manga, title)) return 0L
        if (isImmediateNtkGeneratedUx()) return 0L
        if (!firstBitmapLogged.get()) return 0L
        val path = manga.ntkEpisodePath
        val initialContinuousPath =
            isNtkManhwaOrWebtoonEpisodePath(path) || manga.baseMode == MTitle.base_webtoon
        if (!initialContinuousPath) return 0L
        val firstBitmapAt = ntkFirstBitmapAtMs.get()
        if (firstBitmapAt <= 0L) return 0L
        val quietFor = SystemClock.uptimeMillis() - firstBitmapAt
        return (NTK_INITIAL_INTERACTIVE_SETTLE_AFTER_FIRST_BITMAP_MS - quietFor).coerceAtLeast(0L)
    }

    private fun isNtkSilentAdjacentStillNearBoundary(anchor: Int, direction: Int): Boolean {
        if (!isNtkSource(manga, title)) return true
        return synchronized(pagesLock) {
            if (!isNtkGeneratedManhwaReadyForSilentAdjacentLocked()) return false
            val count = pages.size
            if (count <= 0) return false
            val boundedAnchor = anchor.coerceIn(0, count - 1)
            val viewportAnchor = currentViewportAnchor.get()
                .takeIf { it >= 0 }
                ?.coerceIn(0, count - 1)
            val effectiveAnchor = if (direction > 0) {
                maxOf(boundedAnchor, viewportAnchor ?: boundedAnchor)
            } else {
                minOf(boundedAnchor, viewportAnchor ?: boundedAnchor)
            }
            if (direction > 0) {
                val near = boundedAnchor >= count - NTK_SILENT_ADJACENT_BOUNDARY_PAGES
                if (!near) {
                    Log.d(
                        TAG,
                        "append_adjacent_silent_not_near_tail anchor=$anchor effective=$effectiveAnchor " +
                            "bounded=$boundedAnchor viewport=${viewportAnchor ?: -1} count=$count " +
                            "path=${manga.ntkEpisodePath}"
                    )
                }
                near
            } else {
                val near = boundedAnchor < NTK_SILENT_ADJACENT_BOUNDARY_PAGES
                if (!near) {
                    Log.d(
                        TAG,
                        "append_adjacent_silent_not_near_head anchor=$anchor effective=$effectiveAnchor " +
                            "bounded=$boundedAnchor viewport=${viewportAnchor ?: -1} count=$count " +
                            "path=${manga.ntkEpisodePath}"
                    )
                }
                near
            }
        }
    }

    private fun isNtkGeneratedManhwaReadyForSilentAdjacentLocked(): Boolean {
        if (!isNtkManhwaEpisodePath(manga.ntkEpisodePath)) return true
        val currentKey = Manga.episodeIdentityKey(manga)
        val currentRefs = pages.filter { Manga.episodeIdentityKey(it.manga) == currentKey }
        if (currentRefs.none { isNtkGeneratedImageUrl(it.image.orEmpty()) }) return true
        val currentCount = currentRefs.count { it.transitionTitle == null }
        if (currentCount >= NTK_GENERATED_INITIAL_RECOVERY_PAGES) return true
        val knownCount = manga.ntkImageCount
        return knownCount in 1..currentCount
    }

    private fun isNtkAdjacentAppendBlockedByCurrentTail(
        source: Manga,
        anchor: Int,
        direction: Int
    ): Boolean {
        if (!isNtkSource(source, title)) return false
        return synchronized(pagesLock) {
            val matchingRefs = pages.withIndex()
                .filter { (_, page) ->
                    page.transitionTitle == null && Manga.sameEpisodeIdentity(page.manga, source)
                }
            val matchingIndexes = matchingRefs.map { it.index }
            if (matchingIndexes.isEmpty()) return@synchronized false
            val first = matchingIndexes.minOrNull() ?: return@synchronized false
            val last = matchingIndexes.maxOrNull() ?: return@synchronized false
            val count = matchingIndexes.size
            val cachedCount = ReaderImageCache.earlyNtkAppendImageUrls(source.ntkEpisodePath, 0L).size
            val knownCount = ntkKnownOrAvailableGeneratedCountForAdjacent(source, count)
            val trustedKnownCount = knownCount > 0 &&
                ReaderImageCache.trustedNtkImageApiCount(source.ntkEpisodePath, 0L) >= knownCount
            val hasInsertedNextEpisode = direction > 0 &&
                ((last + 1)..pages.lastIndex).any { index ->
                    val page = pages[index]
                    page.transitionTitle == null && !Manga.sameEpisodeIdentity(page.manga, source)
                }
            val hasInsertedPreviousEpisode = direction < 0 &&
                (0 until first).any { index ->
                    val page = pages[index]
                    page.transitionTitle == null && !Manga.sameEpisodeIdentity(page.manga, source)
                }
            val missingKnownCurrentPages =
                (trustedKnownCount || cachedCount > count) &&
                    knownCount > count &&
                    count <= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD &&
                    direction > 0
            val blocked = when {
                hasInsertedNextEpisode -> true
                hasInsertedPreviousEpisode -> true
                missingKnownCurrentPages -> true
                isImmediateNtkGeneratedUx() && direction > 0 && anchor < last -> true
                isImmediateNtkGeneratedUx() && direction < 0 && anchor > first -> true
                direction > 0 && anchor < last - NTK_APPEND_CURRENT_TAIL_BOUNDARY_PAGES -> true
                direction < 0 && anchor > first + NTK_APPEND_CURRENT_TAIL_BOUNDARY_PAGES -> true
                else -> false
            }
            if (blocked) {
                Log.d(
                    TAG,
                    "append_adjacent_block_current_tail direction=$direction anchor=$anchor " +
                        "first=$first last=$last count=$count known=$knownCount " +
                        "path=${source.ntkEpisodePath}"
                )
            }
            if (missingKnownCurrentPages) {
                main.post {
                    if (cancelled.get()) return@post
                    val latest = currentGeneratedUrlsForAdjacentExpansion(source, knownCount, count)
                    if (latest.size >= knownCount && latest.size > count) {
                        val minGeneratedLimit = ntkCurrentGeneratedExpansionLimit(
                            source,
                            count,
                            anchor,
                            latest.size
                        )
                        appendInitialNtkUrlsAfterEarlyInstall(
                            source,
                            latest,
                            SystemClock.elapsedRealtime(),
                            allowFirstBitmapDefer = false,
                            minGeneratedLimit = minGeneratedLimit
                        )
                        logNtkRepositoryStage(
                            source,
                            "append_block_expand_current_from_early",
                            "from=$count,to=${latest.size},known=$knownCount,min=$minGeneratedLimit"
                        )
                    }
                    requestAllUndeliveredNtkPages("current_full_before_next")
                }
            }
            blocked
        }
    }

    private fun ntkCurrentBackgroundWarmDelayMs(): Long = 0L
    private fun ntkForwardPrimeDelayMs(): Long {
        return if (isNtkGeneratedFastParse()) {
            NTK_GENERATED_FORWARD_PRIME_AFTER_FIRST_BITMAP_DELAY_MS
        } else {
            NTK_NATIVE_FORWARD_PRIME_AFTER_FIRST_BITMAP_DELAY_MS
        }
    }

    private fun isNtkGeneratedFastParse(): Boolean {
        val reason = manga.getNtkViewerParseReason().lowercase()
        return reason.startsWith("generated") && !reason.startsWith("generated-unreachable")
    }

    private fun startBoundedForegroundStreamFetch(
        context: Context,
        target: Manga,
        image: String,
        cancellation: ReaderImageCache.Cancellation? = null,
        anchorHedge: Boolean = false,
        permit: NtkImagePermit? = null,
        pageIndex: Int = -1,
        visiblePriority: Boolean = true,
        verifiedEpisodeFanout: Boolean = false
    ): Boolean {
        // The launch episode's bytes are owned by NtkStrictSourceTransport. Adjacent episodes
        // have a different immutable identity and are intentionally loaded by the append
        // pipeline while this reader remains open; blocking them here made continuous forward
        // reading impossible even after the current sealed episode was fully delivered.
        if (strictExactColdRolling && Manga.sameEpisodeIdentity(target, manga)) return false
        if (!isNtkSource(target, title) ||
            !isModernProtectedNumericNtkPath(target.ntkEpisodePath?.trim().orEmpty())
        ) {
            return ReaderImageCache.startForegroundStreamFetch(
                context,
                target,
                image,
                cancellation,
                anchorHedge,
                permit,
                pageIndex,
                visiblePriority,
                verifiedEpisodeFanout
            )
        }
        val resolvedPage = pageRef(pageIndex)?.takeIf { page ->
            page.manga.ntkEpisodePath == target.ntkEpisodePath && page.image.orEmpty() == image
        }
        if (resolvedPage != null &&
            routeStrictAdjacentExactRehydrate(pageIndex, resolvedPage, visiblePriority)
        ) {
            return true
        }
        if (
            resolvedPage != null &&
            !Manga.sameEpisodeIdentity(target, manga)
        ) {
            ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
                target.ntkEpisodePath,
                NTK_ADJACENT_APPEND_FOREGROUND_PATH_TTL_MS,
                "attached_page_demand"
            )
        }
        if (ReaderImageCache.cachedFile(context.applicationContext, target, image) != null) {
            if (resolvedPage != null) markProtectedNumericSourceReady(pageIndex, resolvedPage, "stream_cache_hit")
            return true
        }
        val demand = if (visiblePriority) {
            ReaderPagePipeline.Demand.PHYSICAL_RUNWAY
        } else {
            ReaderPagePipeline.Demand.POST_ACTIVATION_BYTES
        }
        val flight = ReaderImageCache.acquireForegroundByteFlight(
            context.applicationContext,
            target,
            image,
            ReaderPagePipeline.PageKey(foregroundByteFlightEpoch, pageIndex.coerceAtLeast(0)),
            demand
        )
        val subscriberId = foregroundByteFlightSubscriberIds.incrementAndGet()
        val producerCancellation = (cancellation ?: imageCancellation)
            .forCoordinatorGeneratedForegroundPermit(permit, pageIndex)

        fun publishReady(file: File, source: String) {
            initialInteractiveRunwayByteFetches.remove(pageIndex)
            if (cancelled.get() || !file.exists()) return
            val latest = pageRef(pageIndex) ?: return
            if (latest.image.orEmpty() != image || latest.manga.ntkEpisodePath != target.ntkEpisodePath) return
            markProtectedNumericSourceReady(pageIndex, latest, source)
        }

        fun enqueueProducer(): Boolean {
            return try {
                sourcePrefetchNetwork.execute {
                    flight.runProducer {
                        withProtectedNumericNetworkPermit(target) {
                            ReaderImageCache.getOrFetchFileForeground(
                                context.applicationContext,
                                target,
                                image,
                                producerCancellation,
                                visiblePriority = visiblePriority
                            )
                        }
                    }
                }
                true
            } catch (_: RejectedExecutionException) {
                false
            }
        }

        val subscriber = ReaderImageCache.ByteFlightSubscriber { result ->
            when (result) {
                is ReaderImageCache.ByteFlightResult.Ready ->
                    publishReady(result.file, "foreground_byte_flight")
                ReaderImageCache.ByteFlightResult.RetryProducer -> {
                    if (flight.claimProducer() && !enqueueProducer()) flight.cancel()
                }
                is ReaderImageCache.ByteFlightResult.Failed -> {
                    initialInteractiveRunwayByteFetches.remove(pageIndex)
                    adjacentForegroundStreamedAppendKeys.remove(
                        adjacentForegroundStreamKey(target, image, pageIndex)
                    )
                    if (!cancelled.get() && !isExpectedCancellation(result.error)) {
                        val exception = result.error as? Exception ?: RuntimeException(result.error)
                        recordIfUnexpected(exception)
                        val latest = pageRef(pageIndex)
                        if (latest != null && latest.image.orEmpty() == image) {
                            postPageError(pageIndex, latest, exception)
                        }
                    }
                }
            }
        }
        return when (val snapshot = flight.subscribeOrSnapshot(subscriberId, subscriber)) {
            is ReaderImageCache.ByteFlightSnapshot.Ready -> {
                publishReady(snapshot.file, "foreground_byte_flight_cached")
                true
            }
            is ReaderImageCache.ByteFlightSnapshot.Subscribed ->
                !snapshot.startProducer || enqueueProducer()
            ReaderImageCache.ByteFlightSnapshot.Cancelled -> false
        }
    }

    private fun startBoundedVisiblePreviewFetch(
        context: Context,
        target: Manga,
        image: String,
        cancellation: ReaderImageCache.Cancellation?,
        pageIndex: Int
    ): Boolean {
        if (isModernProtectedNumericNtkPath(target.ntkEpisodePath?.trim().orEmpty())) {
            return startBoundedForegroundStreamFetch(
                context,
                target,
                image,
                cancellation,
                pageIndex = pageIndex,
                visiblePriority = true
            )
        }
        return ReaderImageCache.startVisibleInitialGeneratedPreviewFetch(
            context,
            target,
            image,
            cancellation,
            pageIndex
        )
    }

    private fun leaseImageFile(
        index: Int,
        page: PageRef,
        foreground: Boolean,
        visiblePriority: Boolean,
        foregroundPermit: NtkImagePermit? = null,
    ): ReaderImageCache.FileLease {
        if (strictExactColdRolling) {
            throw NtkSourceIdentityException("Strict rolling decode bypassed source body lease")
        }
        val image = page.image ?: throw java.io.IOException("Missing image for page $index")
        val requestCancellation = if (foreground) {
            imageCancellation.forCoordinatorGeneratedForegroundPermit(foregroundPermit, index)
        } else {
            imageCancellation
        }
        return withProtectedNumericNetworkPermit(page.manga) {
            ReaderImageCache.leaseFile(
                appContext,
                page.manga,
                image,
                foreground,
                requestCancellation,
                visiblePriority = visiblePriority
            )
        }
    }

    private fun prefetchImageFile(
        index: Int,
        page: PageRef,
        foreground: Boolean = false,
        visiblePriority: Boolean = false
    ) {
        if (strictExactColdRolling) return
        val image = page.image ?: return
        if (page.manga.isOnline) {
            withProtectedNumericNetworkPermit(page.manga) {
                if (foreground) {
                    ReaderImageCache.getOrFetchFileForeground(
                        appContext,
                        page.manga,
                        image,
                        imageCancellation,
                        visiblePriority = visiblePriority
                    )
                } else {
                    ReaderImageCache.getOrFetchFile(appContext, page.manga, image, imageCancellation)
                }
            }
            markProtectedNumericSourceReady(index, page, "prefetch")
        } else {
            File(image)
        }
    }

    private fun hasPageSourceReady(index: Int, page: PageRef): Boolean {
        val image = page.image ?: return false
        if (!page.manga.isOnline) return true
        return try {
            ReaderImageCache.cachedFile(appContext, page.manga, image) != null
        } catch (e: Exception) {
            if (!isExpectedCancellation(e)) {
                logNtkPagePerf(index, "source_ready_probe_error", "error=${e.javaClass.simpleName}")
            }
            false
        }
    }

    private fun prefetchImageFileQuietly(index: Int, page: PageRef) {
        try {
            if (!cancelled.get()) prefetchImageFile(index, page)
        } catch (e: Exception) {
            recordIfUnexpected(e)
        }
    }

    private fun recordIfUnexpected(e: Exception) {
        if (!cancelled.get() && !isExpectedCancellation(e)) {
            ml.melun.mangaview.report.CrashReporter.record(e)
        }
    }

    private fun postPageError(index: Int, page: PageRef, e: Exception) {
        if (isNtkGeneratedImageUrl(page.image.orEmpty()) && isImageNotFoundError(e)) {
            ReaderImageCache.markNtkGeneratedNotFound(
                page.manga,
                page.image,
                "reader_page_error"
            )
            if (trimRecordedKnownMissingNtkGeneratedTail(page.manga, "reader_page_error")) return
        }
        if (postNtkImageCloudflareCaptcha(index, page, e)) return
        if (refreshNtkGeneratedPageImage(index, page, e)) return
        if (trimNtkGeneratedTail(index, page, e)) return
        if (trimEarlyInvalidNtkGeneratedTail(index, page, e)) return
        if (removeInvalidNtkGeneratedPage(index, page, e)) return
        if (retryTransientNtkImagePageError(index, page, e)) return
        if (pageRef(index) != page) return
        if (hasDeliveredOrPendingDrawable(index)) {
            Log.d(
                TAG,
                "page_error_skip_delivered index=$index,pageIndex=${page.pageIndex},source=${page.sourceIndex}," +
                    "path=${page.manga.ntkEpisodePath},image=${page.image},error=${e.javaClass.simpleName}:${e.message}"
            )
            ViewerWarmupManager.logMetric("reader_page_error_skip_delivered", index.toLong())
            return
        }
        if (cancelled.get() || isExpectedCancellation(e) || !failedPages.add(index)) return
        Log.d(
            TAG,
            "page_error index=$index,pageIndex=${page.pageIndex},source=${page.sourceIndex},path=${page.manga.ntkEpisodePath},image=${page.image},error=${e.message}"
        )
        main.post {
            if (!cancelled.get() && pageRef(index) == page) {
                listener.onPageError(index, "Image load failed")
            }
        }
    }

    private fun shouldDeferInitialInteractiveGeneratedBackground(
        index: Int,
        page: PageRef,
        generation: Int
    ): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        if (!isImmediateNtkGeneratedUx()) return false
        val start = currentStartPage()
        val initialLast = start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        if (shouldHoldNtkGeneratedTailForInitialContinuous() && index > initialLast) {
            val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: start
            if (isInitialContinuousNarrowViewportRequest(index, viewportAnchor)) return false
            logNtkPagePerf(index, "generated_background_defer_initial_continuous", "generation=$generation")
            return true
        }
        if (generation == PRIME_WARM_GENERATION && ntkBackgroundWarmQuietRemainingMs() > 0L) {
            val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: start
            val lastAllowed = minOf(
                pagesLastIndex(),
                viewportAnchor + NTK_INITIAL_INTERACTIVE_VIEWPORT_AHEAD_PAGES
            )
            if (index > lastAllowed) {
                logNtkPagePerf(index, "generated_background_defer_interactive", "generation=$generation")
                return true
            }
        }
        return false
    }

    private fun deferGeneratedTailTrimIfBusy(
        index: Int,
        page: PageRef,
        e: Exception,
        reason: String
    ): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        val image = page.image.orEmpty()
        if (image.isNotEmpty() && ReaderImageCache.isKnownNtkGeneratedNotFound(page.manga, image)) {
            return false
        }
        val quietMs = readerQuietRemainingMs(NTK_GENERATED_TAIL_TRIM_QUIET_MS)
        if (quietMs <= 0L) return false
        val path = page.manga.ntkEpisodePath?.trim().orEmpty()
        val key = "$path|${page.sourceIndex}|$reason"
        if (!deferredGeneratedTailTrimKeys.add(key)) return true
        Log.d(
            TAG,
            "trim_generated_tail_defer path=$path,index=$index,source=${page.sourceIndex}," +
                "reason=$reason,quietMs=$quietMs,error=${e.message}"
        )
        main.postDelayed({
            try {
                control.execute {
                    deferredGeneratedTailTrimKeys.remove(key)
                    if (cancelled.get()) return@execute
                    val match = synchronized(pagesLock) {
                        val exact = if (index in pages.indices && pages[index] === page) index else -1
                        val found = if (exact >= 0) {
                            exact
                        } else {
                            pages.indexOfFirst {
                                it.transitionTitle == null &&
                                    it.sourceIndex == page.sourceIndex &&
                                    Manga.sameEpisodeIdentity(it.manga, page.manga)
                            }
                        }
                        if (found >= 0) found to pages[found] else null
                    } ?: return@execute
                    when (reason) {
                        "blank" -> trimBlankNtkGeneratedTail(match.first, match.second)
                        "early_invalid" -> trimEarlyInvalidNtkGeneratedTail(match.first, match.second, e)
                        else -> trimNtkGeneratedTail(match.first, match.second, e)
                    }
                }
            } catch (_: RejectedExecutionException) {
                deferredGeneratedTailTrimKeys.remove(key)
            }
        }, quietMs.coerceAtLeast(NTK_GENERATED_TAIL_TRIM_RECHECK_MS))
        return true
    }

    private fun skipKnownMissingNtkGeneratedPage(index: Int, page: PageRef, source: String): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        val image = page.image?.trim()?.takeIf { it.isNotEmpty() } ?: return false
        if (!isNtkGeneratedImageUrl(image)) return false
        if (!ReaderImageCache.isKnownNtkGeneratedNotFound(page.manga, image)) return false
        if (shouldPreserveNtkGeneratedExtensionProbe(page, image)) {
            Log.d(
                TAG,
                "reader_known_generated_not_found_preserve_extension_probe page=$index," +
                    "source=${page.sourceIndex},reason=$source,path=${page.manga.ntkEpisodePath}," +
                    "image=${image.substringAfterLast('/')}"
            )
            return false
        }
        val confirmedTailPage = ReaderImageCache.knownNtkGeneratedFirstNotFoundPage(page.manga.ntkEpisodePath)
        if (shouldPreserveTrustedNtkGeneratedPageCount(page) &&
            (confirmedTailPage <= 0 || page.sourceIndex + 1 < confirmedTailPage)
        ) {
            Log.d(
                TAG,
                "reader_known_generated_not_found_ignore_authoritative page=$index,source=${page.sourceIndex}," +
                    "trusted=${trustedNtkGeneratedImageCount(page.manga)},reason=$source," +
                    "path=${page.manga.ntkEpisodePath},image=${image.substringAfterLast('/')}"
            )
            return false
        }
        clearStaleLoadStateForIndex(index, page)
        loading.remove(index)
        loadingPages.remove(index, page)
        urgentLoading.remove(index)
        urgentLoadingPages.remove(index, page)
        inFlightWidths.remove(index)
        pendingDeliveryWidths.remove(index)
        failedPages.remove(index)
        Log.d(
            TAG,
            "reader_known_generated_not_found_skip page=$index,source=${page.sourceIndex}," +
                "reason=$source,path=${page.manga.ntkEpisodePath},image=${image.substringAfterLast('/')}"
        )
        trimNtkGeneratedTail(
            index,
            page,
            java.io.IOException("Generated image not found: page=${page.sourceIndex + 1} code=404")
        )
        return true
    }

    private fun trimRecordedKnownMissingNtkGeneratedTail(target: Manga, source: String): Boolean {
        if (!isNtkSource(target, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(target.ntkEpisodePath)) return false
        val firstMissingPage = ReaderImageCache.knownNtkGeneratedFirstNotFoundPage(target.ntkEpisodePath)
        if (firstMissingPage <= 1) return false
        val firstTailSourceIndex = firstMissingPage - 1
        val match = synchronized(pagesLock) {
            pages.withIndex().firstOrNull { item ->
                item.value.transitionTitle == null &&
                    item.value.sourceIndex >= firstTailSourceIndex &&
                    Manga.sameEpisodeIdentity(item.value.manga, target) &&
                    isNtkGeneratedImageUrl(item.value.image.orEmpty())
            }?.let { it.index to it.value }
        } ?: return false
        Log.d(
            TAG,
            "trim_recorded_generated_tail firstMissing=$firstMissingPage,index=${match.first}," +
                "sourceIndex=${match.second.sourceIndex},reason=$source,path=${target.ntkEpisodePath}"
        )
        return trimNtkGeneratedTail(
            match.first,
            match.second,
            java.io.IOException("Generated image not found: page=$firstMissingPage code=404 source=$source")
        )
    }

    private fun trimNtkGeneratedTail(index: Int, page: PageRef, e: Exception): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (shouldProtectKnownNtkGeneratedPage(page, e)) {
            Log.d(
                TAG,
                "trim_generated_tail_skip_known_page known=${page.manga.ntkImageCount}," +
                    "index=$index,source=${page.sourceIndex},path=${page.manga.ntkEpisodePath},error=${e.message}"
            )
            return false
        }
        val knownCount = page.manga.ntkImageCount
        val firstKnownMissingPage = ReaderImageCache.knownNtkGeneratedFirstNotFoundPage(page.manga.ntkEpisodePath)
        val confirmedKnownMissingTail =
            firstKnownMissingPage > 0 && page.sourceIndex + 1 >= firstKnownMissingPage
        if (shouldPreserveTrustedNtkGeneratedPageCount(page) && !confirmedKnownMissingTail) {
            Log.d(
                TAG,
                "trim_generated_tail_skip_authoritative_count known=$knownCount," +
                    "trusted=${trustedNtkGeneratedImageCount(page.manga)},index=$index," +
                    "source=${page.sourceIndex},path=${page.manga.ntkEpisodePath},error=${e.message}"
            )
            return false
        }
        val pastGeneratedTail = (e.message ?: "").startsWith("Generated image past tail:")
        val generatedNotFoundTail =
            isNtkGeneratedImageUrl(page.image.orEmpty()) &&
                isImageNotFoundError(e) &&
                (page.sourceIndex >= NTK_GENERATED_CONFIRMED_TAIL_MISSING_SOURCE_MIN ||
                    confirmedKnownMissingTail)
        if (knownCount <= 0 && !generatedNotFoundTail && !pastGeneratedTail && !confirmedKnownMissingTail) return false
        if (!pastGeneratedTail && isNtkGeneratedImageUrl(page.image ?: "")) {
            val displayTotalPages = synchronized(pagesLock) {
                pages.count { ref ->
                    ref.transitionTitle == null && Manga.sameEpisodeIdentity(ref.manga, page.manga)
                }
            }
            if (!generatedNotFoundTail && displayTotalPages > knownCount) {
                Log.d(
                    TAG,
                    "trim_generated_tail_skip_partial_known_count known=$knownCount,displayTotal=$displayTotalPages," +
                        "errorPage=$index,source=${page.sourceIndex},path=${page.manga.ntkEpisodePath},error=${e.message}"
                )
                return false
            }
        }
        val firstTailSourceIndex = when {
            confirmedKnownMissingTail -> firstKnownMissingPage - 1
            knownCount > 0 && page.sourceIndex >= knownCount -> knownCount
            generatedNotFoundTail -> page.sourceIndex
            pastGeneratedTail && page.sourceIndex >= knownCount -> page.sourceIndex
            else -> return false
        }
        if (firstTailSourceIndex < 0) return false
        if (!confirmedKnownMissingTail && deferGeneratedTailTrimIfBusy(index, page, e, "tail")) return true
        val ranges = ArrayList<Pair<Int, Int>>()
        val total: Int
        var displayTotalPages = 0
        synchronized(pagesLock) {
            val removeIndexes = pages.withIndex()
                .filter { item ->
                    item.value.transitionTitle == null &&
                        item.value.sourceIndex >= firstTailSourceIndex &&
                        Manga.sameEpisodeIdentity(item.value.manga, page.manga)
                }
                .map { it.index }
            if (removeIndexes.isEmpty()) return false
            beginStructurePublish()
            var start = removeIndexes.first()
            var previous = start
            for (i in 1 until removeIndexes.size) {
                val current = removeIndexes[i]
                if (current == previous + 1) {
                    previous = current
                } else {
                    ranges.add(start to previous)
                    start = current
                    previous = current
                }
            }
            ranges.add(start to previous)
            for ((rangeStart, rangeEnd) in ranges.asReversed()) {
                for (i in rangeEnd downTo rangeStart) pages.removeAt(i)
            }
            pages.forEachIndexed { pageIndex, ref -> ref.pageIndex = pageIndex }
            displayTotalPages = pages.count { ref ->
                ref.transitionTitle == null && Manga.sameEpisodeIdentity(ref.manga, page.manga)
            }
            if (displayTotalPages > 0) {
                page.manga.setNtkImageCount(displayTotalPages)
                pages.forEach { ref ->
                    if (ref.transitionTitle == null && Manga.sameEpisodeIdentity(ref.manga, page.manga)) {
                        ref.totalPages = displayTotalPages
                    }
                }
            }
            removePageStateRange(rangeStart = ranges.first().first, removedCount = removeIndexes.size)
            total = pages.size
            capturePublishedPageIndexLocked()
        }
        for ((start, end) in ranges.asReversed()) {
            val count = end - start + 1
            val suppressUnpublishedRemoval = consumeUnpublishedAdjacentAppendRemoval(page, start, count)
            if (!suppressUnpublishedRemoval) {
                main.post {
                    if (!cancelled.get()) {
                        listener.onPagesRemoved(start, count, total)
                    }
                }
            }
            Log.d(
                TAG,
                "trim_generated_tail start=$start,count=$count,known=$knownCount,tailSource=$firstTailSourceIndex," +
                    "errorPage=$index,total=$total,displayTotal=$displayTotalPages," +
                    "suppressedUnpublishedRemoval=$suppressUnpublishedRemoval"
            )
        }
        if (!main.post {
                finishStructurePublish()
                requestRetainedWindowAfterStructureChange()
            }) {
            finishStructurePublish()
            requestRetainedWindowAfterStructureChange()
        }
        return true
    }

    private fun trimBlankNtkGeneratedTail(index: Int, page: PageRef): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (!page.image.isNullOrBlank()) return false
        if (shouldPreserveTrustedNtkGeneratedPageCount(page)) {
            Log.d(
                TAG,
                "trim_blank_generated_tail_skip_authoritative_count known=${page.manga.ntkImageCount}," +
                    "trusted=${trustedNtkGeneratedImageCount(page.manga)},index=$index," +
                    "source=${page.sourceIndex},path=${page.manga.ntkEpisodePath}"
            )
            return false
        }
        if (isKnownNtkGeneratedPage(page)) {
            Log.d(
                TAG,
                "trim_blank_generated_tail_skip_known_page known=${page.manga.ntkImageCount}," +
                    "index=$index,source=${page.sourceIndex},path=${page.manga.ntkEpisodePath}"
            )
            return false
        }
        if (deferGeneratedTailTrimIfBusy(
                index,
                page,
                IllegalStateException("Blank generated tail"),
                "blank"
            )
        ) {
            return true
        }
        val total: Int
        val displayTotalPages: Int
        synchronized(pagesLock) {
            if (index !in pages.indices || pages[index] !== page || index != pages.lastIndex) return false
            if (index <= 0) return false
            beginStructurePublish()
            pages.removeAt(index)
            removePageStateRange(index, 1)
            pages.forEachIndexed { pageIndex, ref -> ref.pageIndex = pageIndex }
            displayTotalPages = pages.count { ref ->
                ref.transitionTitle == null && Manga.sameEpisodeIdentity(ref.manga, page.manga)
            }
            if (displayTotalPages > 0) {
                page.manga.setNtkImageCount(displayTotalPages)
                pages.forEach { ref ->
                    if (ref.transitionTitle == null && Manga.sameEpisodeIdentity(ref.manga, page.manga)) {
                        ref.totalPages = displayTotalPages
                    }
                }
            }
            total = pages.size
            capturePublishedPageIndexLocked()
        }
        main.post {
            if (!cancelled.get()) {
                listener.onPagesRemoved(index, 1, total)
            }
            finishStructurePublish()
            requestRetainedWindowAfterStructureChange()
        }
        Log.d(
            TAG,
            "trim_blank_generated_tail start=$index,count=1,path=${page.manga.ntkEpisodePath}," +
                "total=$total,displayTotal=$displayTotalPages"
        )
        return true
    }

    private fun trimEarlyInvalidNtkGeneratedTail(index: Int, page: PageRef, e: Exception): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        if (!isImageNotFoundError(e)) return false
        val firstKnownMissingPage = ReaderImageCache.knownNtkGeneratedFirstNotFoundPage(page.manga.ntkEpisodePath)
        val confirmedKnownMissingTail =
            firstKnownMissingPage > 0 && page.sourceIndex + 1 >= firstKnownMissingPage
        if (
            !confirmedKnownMissingTail &&
            shouldPreserveNtkGeneratedExtensionProbe(page, page.image.orEmpty())
        ) {
            Log.d(
                TAG,
                "trim_early_invalid_generated_tail_skip_extension_probe known=${page.manga.ntkImageCount}," +
                    "index=$index,source=${page.sourceIndex},path=${page.manga.ntkEpisodePath},error=${e.message}"
            )
            return true
        }
        if (isKnownNtkGeneratedPage(page) &&
            !confirmedKnownMissingTail &&
            !initialContinuousDrawableDelivered(currentStartPage())
        ) {
            Log.d(
                TAG,
                "trim_early_invalid_generated_tail_skip_initial_continuous known=${page.manga.ntkImageCount}," +
                    "index=$index,source=${page.sourceIndex},path=${page.manga.ntkEpisodePath},error=${e.message}"
            )
            return true
        }
        if (shouldProtectKnownNtkGeneratedPage(page, e) && !confirmedKnownMissingTail) {
            Log.d(
                TAG,
                "trim_early_invalid_generated_tail_skip_known_page known=${page.manga.ntkImageCount}," +
                    "index=$index,source=${page.sourceIndex},path=${page.manga.ntkEpisodePath},error=${e.message}"
            )
            return false
        }
        if (shouldPreserveTrustedNtkGeneratedPageCount(page) && !confirmedKnownMissingTail) {
            Log.d(
                TAG,
                "trim_early_invalid_generated_tail_skip_authoritative_count known=${page.manga.ntkImageCount}," +
                    "trusted=${trustedNtkGeneratedImageCount(page.manga)},index=$index," +
                    "source=${page.sourceIndex},path=${page.manga.ntkEpisodePath},error=${e.message}"
            )
            return false
        }
        val firstTailSourceIndex = page.sourceIndex
        if (!confirmedKnownMissingTail &&
            firstTailSourceIndex !in NTK_GENERATED_EARLY_TAIL_MISSING_SOURCE_MIN..NTK_GENERATED_EARLY_TAIL_MISSING_SOURCE_MAX
        ) {
            return false
        }
        if (!confirmedKnownMissingTail && deferGeneratedTailTrimIfBusy(index, page, e, "early_invalid")) return true
        val ranges = ArrayList<Pair<Int, Int>>()
        val total: Int
        var displayTotalPages = 0
        var removedCount = 0
        synchronized(pagesLock) {
            val removeIndexes = pages.withIndex()
                .filter { item ->
                    item.value.transitionTitle == null &&
                        item.value.sourceIndex >= firstTailSourceIndex &&
                        Manga.sameEpisodeIdentity(item.value.manga, page.manga)
                }
                .map { it.index }
            if (removeIndexes.size < NTK_GENERATED_EARLY_TAIL_MISSING_MIN_REMOVE) return false
            beginStructurePublish()
            var start = removeIndexes.first()
            var previous = start
            for (i in 1 until removeIndexes.size) {
                val current = removeIndexes[i]
                if (current == previous + 1) {
                    previous = current
                } else {
                    ranges.add(start to previous)
                    start = current
                    previous = current
                }
            }
            ranges.add(start to previous)
            for ((rangeStart, rangeEnd) in ranges.asReversed()) {
                val count = rangeEnd - rangeStart + 1
                repeat(count) { pages.removeAt(rangeStart) }
                removePageStateRange(rangeStart, count)
                removedCount += count
            }
            pages.forEachIndexed { pageIndex, ref -> ref.pageIndex = pageIndex }
            displayTotalPages = pages.count { ref ->
                ref.transitionTitle == null && Manga.sameEpisodeIdentity(ref.manga, page.manga)
            }
            if (displayTotalPages > 0) {
                page.manga.setNtkImageCount(displayTotalPages)
                pages.forEach { ref ->
                    if (ref.transitionTitle == null && Manga.sameEpisodeIdentity(ref.manga, page.manga)) {
                        ref.totalPages = displayTotalPages
                    }
                }
            }
            total = pages.size
            capturePublishedPageIndexLocked()
        }
        for ((start, end) in ranges.asReversed()) {
            val count = end - start + 1
            main.post {
                if (!cancelled.get()) {
                    listener.onPagesRemoved(start, count, total)
                }
            }
        }
        if (!main.post {
                finishStructurePublish()
                requestRetainedWindowAfterStructureChange()
            }) {
            finishStructurePublish()
            requestRetainedWindowAfterStructureChange()
        }
        Log.d(
            TAG,
            "trim_early_invalid_generated_tail index=$index,source=$firstTailSourceIndex,removed=$removedCount," +
                "displayTotal=$displayTotalPages,path=${page.manga.ntkEpisodePath},error=${e.message}"
        )
        return true
    }

    private fun shouldPreserveNtkGeneratedExtensionProbe(page: PageRef, image: String): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (!isNtkGeneratedImageUrl(image)) return false
        val path = page.manga.ntkEpisodePath ?: return false
        val confirmedTailPage = ReaderImageCache.knownNtkGeneratedFirstNotFoundPage(path)
        if (confirmedTailPage > 0 && page.sourceIndex + 1 >= confirmedTailPage) return false
        val knownCount = page.manga.ntkImageCount
        val earlyCount = ReaderImageCache.earlyNtkImageUrls(
            path,
            SystemClock.elapsedRealtime() - 30000L
        ).size
        return page.sourceIndex + 1 <= max(knownCount, earlyCount)
    }

    private fun refreshNtkGeneratedPageImage(index: Int, page: PageRef, e: Exception): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        val originalImage = page.image ?: return false
        if (!isNtkGeneratedImageUrl(originalImage)) return false
        if (!isImageNotFoundError(e)) return false
        val repositoryReplacement = imageRepository.imageUrls(page.manga, appContext).getOrNull(page.sourceIndex)
            ?.takeIf { it.isNotBlank() && it != originalImage }
            ?.takeIf { ntkImageCandidateMatchesEpisode(it, page.manga) }
        val replacement = repositoryReplacement
            ?: ntkReplacementImageUrlForPage(
                page.manga,
                originalImage,
                ntkImagePageNumber(originalImage) ?: (page.sourceIndex + 1),
                page.sourceIndex
            )
            ?: return false
        if (replacement == originalImage) {
            if (!hasPageSourceReady(index, page)) return false
            failedPages.remove(index)
            decodedWidths.remove(index)
            desiredWidths.remove(index)
            pendingDeliveryWidths.remove(index)
            sourceWidths.remove(index)
            achievableWidths.remove(index)
            inFlightWidths.remove(index)
            Log.d(
                TAG,
                "refresh_generated_page_image_cached index=$index,source=${page.sourceIndex}," +
                    "path=${page.manga.ntkEpisodePath},image=$originalImage"
            )
            requestPage(index, busy = true, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
            return true
        }
        synchronized(pagesLock) {
            if (index !in pages.indices || pages[index] != page) return false
            for (ref in pages) {
                if (
                    ref.transitionTitle == null &&
                    ref.sourceIndex == page.sourceIndex &&
                    ref.image == originalImage &&
                    Manga.sameEpisodeIdentity(ref.manga, page.manga)
                ) {
                    ref.image = replacement
                }
            }
        }
        failedPages.remove(index)
        decodedWidths.remove(index)
        desiredWidths.remove(index)
        pendingDeliveryWidths.remove(index)
        sourceWidths.remove(index)
        achievableWidths.remove(index)
        inFlightWidths.remove(index)
        Log.d(
            TAG,
            "refresh_generated_page_image index=$index,source=${page.sourceIndex},path=${page.manga.ntkEpisodePath}," +
                "from=$originalImage,to=$replacement"
        )
        requestPage(index, busy = true, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
        return true
    }

    private fun removeInvalidNtkGeneratedPage(index: Int, page: PageRef, e: Exception): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        val image = page.image ?: return false
        if (!isNtkGeneratedImageUrl(image)) return false
        if (!isImageNotFoundError(e)) return false
        val currentIndex = currentIndexForPageRef(index, page)
        if (currentIndex < 0) return false
        if (!firstBitmapLogged.get() && isKnownNtkGeneratedPage(page)) {
            Log.d(
                TAG,
                "remove_invalid_generated_page_skip_initial_known index=$currentIndex," +
                    "source=${page.sourceIndex},known=${page.manga.ntkImageCount}," +
                    "path=${page.manga.ntkEpisodePath},image=$image,error=${e.message}"
            )
            return true
        }
        if (shouldProtectKnownNtkGeneratedPage(page, e) ||
            shouldPreserveTrustedNtkGeneratedPageCount(page) ||
            (isKnownNtkGeneratedPage(page) &&
                (hasDeliveredBitmap(currentIndex) ||
                    hasListenerDrawableDelivery(currentIndex) ||
                    (pendingDeliveryWidths[currentIndex] ?: 0) > 0))
        ) {
            Log.d(
                TAG,
                "remove_invalid_generated_page_skip_known_page known=${page.manga.ntkImageCount}," +
                    "trusted=${trustedNtkGeneratedImageCount(page.manga)},index=$currentIndex," +
                    "source=${page.sourceIndex},path=${page.manga.ntkEpisodePath},image=$image,error=${e.message}"
            )
            return false
        }
        if (!firstBitmapLogged.get() && currentIndex == currentStartPage()) {
            val replacement = ntkReplacementImageUrlForPage(
                page.manga,
                image,
                ntkImagePageNumber(image) ?: (page.sourceIndex + 1),
                page.sourceIndex
            )
            if (!replacement.isNullOrBlank() && replacement != image) {
                synchronized(pagesLock) {
                    if (currentIndex !in pages.indices || pages[currentIndex] !== page) return false
                    for (ref in pages) {
                        if (
                            ref.transitionTitle == null &&
                            ref.sourceIndex == page.sourceIndex &&
                            ref.image == image &&
                            Manga.sameEpisodeIdentity(ref.manga, page.manga)
                        ) {
                            ref.image = replacement
                        }
                    }
                }
                failedPages.remove(index)
                decodedWidths.remove(index)
                desiredWidths.remove(index)
                pendingDeliveryWidths.remove(index)
                sourceWidths.remove(index)
                achievableWidths.remove(index)
                inFlightWidths.remove(index)
                Log.d(
                    TAG,
                    "remove_invalid_generated_page_retarget_anchor index=$currentIndex,source=${page.sourceIndex}," +
                        "path=${page.manga.ntkEpisodePath},from=$image,to=$replacement,error=${e.message}"
                )
                requestPage(currentIndex, busy = true, anchor = true, generation = FOREGROUND_PRIME_WARM_GENERATION)
                return true
            }
            Log.d(
                TAG,
                "remove_invalid_generated_page_drop_anchor index=$currentIndex,source=${page.sourceIndex}," +
                    "path=${page.manga.ntkEpisodePath},image=$image,error=${e.message}"
            )
        }
        val removeIndex: Int
        val total: Int
        val displayTotalPages: Int
        synchronized(pagesLock) {
            val latestIndex = if (currentIndex in pages.indices && pages[currentIndex] === page) {
                currentIndex
            } else {
                pages.indexOfFirst { it === page }
            }
            if (latestIndex < 0) return false
            beginStructurePublish()
            removeIndex = latestIndex
            pages.removeAt(removeIndex)
            pages.forEachIndexed { pageIndex, ref -> ref.pageIndex = pageIndex }
            displayTotalPages = pages.count { ref ->
                ref.transitionTitle == null && Manga.sameEpisodeIdentity(ref.manga, page.manga)
            }
            if (displayTotalPages > 0) {
                pages.forEach { ref ->
                    if (ref.transitionTitle == null && Manga.sameEpisodeIdentity(ref.manga, page.manga)) {
                        ref.totalPages = displayTotalPages
                    }
                }
            }
            removePageStateRange(removeIndex, 1)
            total = pages.size
            capturePublishedPageIndexLocked()
        }
        val posted = main.post {
            try {
                if (!cancelled.get()) {
                    listener.onPagesRemoved(removeIndex, 1, total)
                }
            } finally {
                finishStructurePublish()
                requestRetainedWindowAfterStructureChange()
            }
        }
        if (!posted) {
            finishStructurePublish()
            requestRetainedWindowAfterStructureChange()
        }
        Log.d(
            TAG,
            "remove_invalid_generated_page index=$removeIndex,source=${page.sourceIndex},displayTotal=$displayTotalPages," +
                "path=${page.manga.ntkEpisodePath},image=$image,error=${e.message}"
        )
        return true
    }

    private fun isKnownNtkGeneratedPage(page: PageRef): Boolean {
        val knownCount = page.manga.ntkImageCount
        return knownCount > 0 &&
            page.sourceIndex in 0 until knownCount &&
            isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)
    }

    private fun isNtkGeneratedDescriptorOrImagePage(page: PageRef): Boolean {
        return isNtkGeneratedImageUrl(page.image.orEmpty()) ||
            ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(page.image.orEmpty()) ||
            isKnownNtkGeneratedPage(page)
    }

    private fun trustedNtkGeneratedImageCount(target: Manga): Int {
        val path = target.ntkEpisodePath
        val trustedApiCount = ReaderImageCache.trustedNtkImageApiCount(path, 0L)
        val knownCount = target.ntkImageCount
        val authoritativeEarlyCount = if (
            knownCount > 0 &&
            ReaderImageCache.hasAuthoritativeCompleteEarlyNtkImageUrls(path, knownCount, 0L)
        ) {
            knownCount
        } else {
            0
        }
        return maxOf(trustedApiCount, authoritativeEarlyCount)
    }

    private fun installedNtkEpisodePageCount(target: Manga): Int = synchronized(pagesLock) {
        pages.count { ref ->
            ref.transitionTitle == null && Manga.sameEpisodeIdentity(ref.manga, target)
        }
    }

    private fun markProtectedNumericSourceReady(index: Int, page: PageRef, reason: String): Boolean {
        if (!usesProtectedNumericNtkPipeline(page) || !hasPageSourceReady(index, page)) return false
        val added = protectedNumericSourceReadyIndexes.add(index)
        if (added) {
            val total = synchronized(pagesLock) { pages.count { it.transitionTitle == null } }
            val ready = protectedNumericSourceReadyIndexes.size.coerceAtMost(total)
            if (ready == total || ready == 1 || ready % NTK_SOURCE_READINESS_LOG_BATCH == 0) {
                val key = "$ready/$total"
                if (protectedNumericReadinessLogKey.getAndSet(key) != key) {
                    Log.d(
                        TAG,
                        "reader_ntk_bounded_source_ready path=${manga.ntkEpisodePath}," +
                            "sourceReady=$ready,pageCount=$total,reason=$reason"
                    )
                    ViewerWarmupManager.logMetric("reader_ntk_bounded_source_ready_pages", ready.toLong())
                    ViewerWarmupManager.logMetric("reader_ntk_bounded_source_page_count", total.toLong())
                }
            }
        }
        return added
    }

    private fun shouldBlockTrustedNtkGeneratedShrink(
        target: Manga,
        incomingCount: Int,
        reason: String
    ): Boolean {
        val trustedCount = trustedNtkGeneratedImageCount(target)
        if (trustedCount <= 0 || incomingCount >= trustedCount) return false
        val installedCount = installedNtkEpisodePageCount(target)
        if (installedCount < trustedCount) return false
        logTrustedNtkGeneratedShrinkSkip(target, incomingCount, trustedCount, installedCount, reason)
        return true
    }

    private fun logTrustedNtkGeneratedShrinkSkip(
        target: Manga,
        incomingCount: Int,
        trustedCount: Int,
        installedCount: Int,
        reason: String
    ) {
        val now = SystemClock.uptimeMillis()
        val key = "${target.ntkEpisodePath}|$incomingCount|$trustedCount|$reason"
        synchronized(ntkTrustedShrinkLogLock) {
            if (key == lastNtkTrustedShrinkLogKey &&
                now - lastNtkTrustedShrinkLogAtMs < NTK_TRUSTED_SHRINK_LOG_INTERVAL_MS
            ) {
                return
            }
            lastNtkTrustedShrinkLogKey = key
            lastNtkTrustedShrinkLogAtMs = now
        }
        Log.d(
            TAG,
            "reader_ntk_skip_authoritative_shrink reason=$reason,path=${target.ntkEpisodePath}," +
                "installed=$installedCount,incoming=$incomingCount,trusted=$trustedCount,known=${target.ntkImageCount}"
        )
    }

    private fun shouldAllowKpUploadReplacementOverProtected(
        currentImages: List<String>,
        incomingUrls: List<String>
    ): Boolean {
        if (currentImages.isEmpty() || incomingUrls.isEmpty()) return false
        if (!incomingUrls.any { isNtkUploadCdnImageUrl(it) }) return false
        if (!currentImages.any { isNtkProtectedViewerApiImage(it) }) return false
        Log.d(
            TAG,
            "reader_ntk_allow_upload_replace_protected_shrink current=${currentImages.size}," +
                "incoming=${incomingUrls.size},first=${incomingUrls.firstOrNull().orEmpty()}"
        )
        return true
    }

    private fun shouldPreserveTrustedNtkGeneratedPageCount(page: PageRef): Boolean {
        if (!isKnownNtkGeneratedPage(page)) return false
        val knownCount = page.manga.ntkImageCount
        if (knownCount <= 0 || page.sourceIndex !in 0 until knownCount) return false
        val trustedCount = trustedNtkGeneratedImageCount(page.manga)
        return trustedCount >= knownCount
    }

    private fun shouldProtectKnownNtkGeneratedPage(page: PageRef, e: Exception): Boolean {
        if (!isKnownNtkGeneratedPage(page)) return false
        if (!firstBitmapLogged.get() && isImageNotFoundError(e)) return true
        if (isNtkGeneratedImageUrl(page.image.orEmpty()) && isImageNotFoundError(e)) {
            return false
        }
        return true
    }

    private fun currentIndexForPageRef(index: Int, page: PageRef): Int {
        synchronized(pagesLock) {
            if (index in pages.indices && pages[index] === page) return index
            return pages.indexOfFirst { it === page }
        }
    }

    private fun requestRetainedWindowAfterStructureChange() {
        if (cancelled.get()) return
        synchronized(retainedWindowRedriveStateLock) {
            retainedWindowRedriveRevision++
            retainedWindowRedrivePending.set(true)
        }
        scheduleRetainedWindowRedriveIfNeeded()
    }

    /**
     * Replays a window transaction that lost its page-table/proof race without manufacturing a
     * new structure revision.  Several progressive tail appends can invalidate concurrent control
     * turns; incrementing the durable redrive revision for every failed attempt made those retries
     * invalidate one another and produced an unbounded main/control replay loop.
     */
    private fun retryRetainedWindowAfterFailedCommit(expectedRevision: Long, reason: String) {
        if (cancelled.get()) return
        val ordinal = retainedWindowRetryReasonCounts
            .computeIfAbsent(reason) { AtomicLong(0L) }
            .incrementAndGet()
        if (ordinal <= 4L || (ordinal and (ordinal - 1L)) == 0L) {
            Log.d(
                TAG,
                "reader_retained_window_commit_retry reason=$reason,ordinal=$ordinal," +
                    "expectedRevision=$expectedRevision," +
                    "protectedRevision=${protectedBitmapWindowRevision.get()}," +
                    "structureGeneration=${indexedStateGeneration.get()}," +
                    "pageCount=${synchronized(pagesLock) { pages.size }}",
            )
        }
        val shouldSchedule = synchronized(retainedWindowRedriveStateLock) {
            when {
                retainedWindowRedriveRevision == expectedRevision -> {
                    retainedWindowRedrivePending.set(true)
                    true
                }
                // A real structure/proof transition superseded this failed transaction. Its
                // pending revision owns the retry; help schedule it without modifying identity.
                retainedWindowRedrivePending.get() -> true
                else -> false
            }
        }
        if (shouldSchedule) scheduleRetainedWindowRedriveIfNeeded()
    }

    private fun retainedWindowRedriveRevisionSnapshot(): Long =
        synchronized(retainedWindowRedriveStateLock) { retainedWindowRedriveRevision }

    private fun acknowledgeRetainedWindowRedrive(expectedRevision: Long): Boolean =
        synchronized(retainedWindowRedriveStateLock) {
            if (retainedWindowRedriveRevision != expectedRevision) {
                false
            } else {
                retainedWindowRedrivePending.set(false)
                true
            }
        }

    private fun scheduleRetainedWindowRedriveIfNeeded() {
        if (cancelled.get()) {
            retainedWindowRedrivePending.set(false)
            return
        }
        if (!retainedWindowRedrivePending.get() || isStructurePublishPending()) return
        if (!retainedWindowRedrivePosted.compareAndSet(false, true)) return
        val posted = main.post {
            retainedWindowRedrivePosted.set(false)
            if (cancelled.get()) {
                retainedWindowRedrivePending.set(false)
                return@post
            }
            // A structure publish may have started after the outer check. Leave ownership armed;
            // finishStructurePublish posts the next turn when the Surface table is current.
            if (isStructurePublishPending()) return@post
            performRetainedWindowRedrive()
        }
        if (!posted) retainedWindowRedrivePosted.set(false)
    }

    private fun performRetainedWindowRedrive() {
        if (cancelled.get()) {
            retainedWindowRedrivePending.set(false)
            return
        }
        val retainedRedriveRevisionAtStart = retainedWindowRedriveRevisionSnapshot()
        trimRecordedKnownMissingNtkGeneratedTail(manga, "structure_change")
        val reported = latestReportedWindow.get()
        val reportedSnapshot = reported?.let { window ->
            val pageIndex = publishedPageIndex.get()
            if (pageIndex.isEmpty()) {
                null
            } else {
                val resolvedAnchor = window.anchorPage?.let { page ->
                    pageIndexInPublishedSnapshot(pageIndex, page, window.fallbackAnchor)
                }?.takeIf { it in pageIndex.indices }
                    ?: currentViewportAnchor.get().takeIf { it in pageIndex.indices }
                    ?: window.fallbackAnchor.coerceIn(0, pageIndex.lastIndex)
                val first = (resolvedAnchor + window.firstOffset)
                    .coerceIn(0, pageIndex.lastIndex)
                val last = (resolvedAnchor + window.lastOffset)
                    .coerceIn(first, pageIndex.lastIndex)
                intArrayOf(
                    first,
                    last,
                    resolvedAnchor,
                    if (window.busy) 1 else 0,
                    window.directionHint,
                )
            }
        }
        val retainedSnapshot = synchronized(deliveredBitmaps) {
            if (retainedLastPage < retainedFirstPage) {
                null
            } else {
                val first = retainedFirstPage.coerceAtLeast(0)
                val last = retainedLastPage.coerceAtLeast(first)
                val anchor = retainedAnchorPage.coerceIn(first, last)
                Triple(first, last, anchor)
            }
        }
        val snapshot = reportedSnapshot ?: retainedSnapshot?.let { retained ->
            intArrayOf(
                retained.first,
                retained.second,
                retained.third,
                if (viewportBusy.get()) 1 else 0,
                0,
            )
        } ?: run {
            acknowledgeRetainedWindowRedrive(retainedRedriveRevisionAtStart)
            if (isNtkSource(manga, title) && !firstBitmapLogged.get()) {
                val anchor = currentStartPage()
                Log.d(
                    TAG,
                    "reader_structure_anchor_re_request page=$anchor,busy=${viewportBusy.get()}"
                )
                requestPageForeground(anchor)
                requestInitialContinuousPagesFromEarlyUrls(anchor, publishedPageIndex.get().size)
            }
            return
        }
        var offeredBusy = snapshot[3] != 0
        val offered = synchronized(retainedWindowRedriveStateLock) {
            if (!retainedWindowRedrivePending.get() ||
                retainedWindowRedriveRevision != retainedRedriveRevisionAtStart
            ) {
                false
            } else {
                // Keep the pending-state check linear with the internal offer. A successful newer
                // physical window can acknowledge this revision before this point and suppress the
                // obsolete replay. A structure retry is not physical input and must never restore
                // a stale moving level after Surface already published idle.
                offeredBusy = latestWindowIngressBusy.get()
                offerWindowAsync(
                    snapshot[0],
                    snapshot[1],
                    snapshot[2],
                    offeredBusy,
                    snapshot[4],
                )
                true
            }
        }
        if (!offered) return
        if (shouldLogRateLimitedDiagnostic("structure_window_re_request")) {
            Log.d(
                TAG,
                "reader_structure_window_re_request first=${snapshot[0]},last=${snapshot[1]},anchor=${snapshot[2]}," +
                    "busy=$offeredBusy,direction=${snapshot[4]}"
            )
        }
        val count = publishedPageIndex.get().size
        val edgeLast = minOf(count - 1, snapshot[1] + NTK_BUSY_VISIBLE_EDGE_EXTRA_PAGES)
        if (edgeLast > snapshot[1]) {
            for (index in (snapshot[1] + 1)..edgeLast) {
                requestPage(index, busy = true, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
            }
        }
    }

    private fun isImageNotFoundError(e: Exception): Boolean {
        var current: Throwable? = e
        while (current != null) {
            val message = current.message.orEmpty()
            if (message.contains("Image request failed: 404") || message.contains(" code=404")) return true
            if (message.contains("Image request failed: 410") || message.contains(" code=410")) return true
            if (message.contains("Image request failed: 520") || message.contains(" code=520")) return true
            if (message.contains("Generated image not found", ignoreCase = true)) return true
            current = current.cause
        }
        return false
    }

    private fun isNtkImageCloudflareHardBlockError(e: Exception): Boolean {
        var current: Throwable? = e
        while (current != null) {
            val message = current.message.orEmpty()
            if (message.contains("Image request failed: 403") ||
                message.contains(" code=403") ||
                message.contains("cloudflare-html-403", ignoreCase = true)
            ) {
                return true
            }
            current = current.cause
        }
        return false
    }

    private fun isTransientNtkImageError(e: Exception): Boolean {
        var current: Throwable? = e
        while (current != null) {
            val message = current.message.orEmpty()
            if (
                current is java.net.SocketException ||
                current is java.net.SocketTimeoutException ||
                current is java.io.FileNotFoundException ||
                current is java.io.InterruptedIOException ||
                message.contains("Partial foreground image response is not cacheable", ignoreCase = true) ||
                message.contains("Connection reset", ignoreCase = true) ||
                message.contains("foreground image race failed", ignoreCase = true) ||
                message.contains("foreground generated direct race failed", ignoreCase = true) ||
                message.contains("foreground generated direct shared race failed", ignoreCase = true) ||
                message.contains("Reader image request cancelled", ignoreCase = true) ||
                message.contains("Canceled", ignoreCase = true) ||
                message.contains(".img.part.", ignoreCase = true) ||
                message.contains("open failed: ENOENT", ignoreCase = true) ||
                message.contains("No such file or directory", ignoreCase = true) ||
                message.contains("timed out", ignoreCase = true) ||
                message.contains("timeout", ignoreCase = true)
            ) return true
            current = current.cause
        }
        return false
    }

    private fun isNtkGeneratedImageUrl(image: String): Boolean {
        return NTK_GENERATED_IMAGE_URL.matchEntire(image) != null || isNtkUploadCdnImageUrl(image)
    }

    private fun isRetryableTransientNtkImageUrl(image: String): Boolean {
        return isNtkGeneratedImageUrl(image) ||
            isNtkBoardUploadImageUrl(image) ||
            isNtkProtectedCdnImageUrl(image) ||
            isNaverWebtoonPageImageUrl(image)
    }

    private fun isTransientNtkCacheFileRaceError(e: Exception): Boolean {
        var current: Throwable? = e
        while (current != null) {
            val message = current.message.orEmpty()
            if (current is java.io.FileNotFoundException) return true
            if (message.contains(".img.part.", ignoreCase = true)) return true
            if (message.contains("open failed: ENOENT", ignoreCase = true)) return true
            if (message.contains("No such file or directory", ignoreCase = true)) return true
            current = current.cause
        }
        return false
    }

    private fun isNtkBoardUploadImageUrl(image: String?): Boolean {
        return image?.lowercase()?.contains("/board_uploads/") == true
    }

    private fun isNtkUploadCdnImageUrl(image: String?): Boolean {
        val lower = image?.lowercase() ?: return false
        return lower.contains("/webtoon_uploads/") ||
            lower.contains("/manhwa_uploads/") ||
            lower.contains("/comic_uploads/")
    }

    private fun isNtkKpDescriptorImageUrl(image: String?): Boolean {
        val lower = image?.lowercase() ?: return false
        return Regex(
            "^(?:https?://)?[^/?#]+/.*/(?:cv|mx|qc|rs)/[^/?#]+\\.(?:txt|xml|json)(?:[?#].*)?$",
            RegexOption.IGNORE_CASE
        ).matches(lower)
    }

    private fun isNtkProtectedCdnImageUrl(image: String?): Boolean {
        val lower = image?.lowercase() ?: return false
        return lower.contains("://toonflix.app/") ||
            lower.contains("://i.toonflix.app/") ||
            Regex("://flysky\\d*m\\.com/").containsMatchIn(lower) ||
            Regex("://apihost\\d*\\.com/").containsMatchIn(lower) ||
            lower.contains("://moamoabon.com/") ||
            Regex("://fvcdn\\d*\\.com/").containsMatchIn(lower) ||
            lower.startsWith("toonflix.app/") ||
            lower.startsWith("i.toonflix.app/") ||
            Regex("^flysky\\d*m\\.com/").containsMatchIn(lower) ||
            Regex("^apihost\\d*\\.com/").containsMatchIn(lower) ||
            lower.startsWith("moamoabon.com/") ||
            lower.startsWith("//moamoabon.com/") ||
            Regex("^fvcdn\\d*\\.com/").containsMatchIn(lower)
    }

    private fun ntkGeneratedSiblingImageUrl(seed: String, page: Int): String? {
        if (page <= 0) return null
        val match = NTK_GENERATED_IMAGE_URL.matchEntire(seed) ?: return null
        val candidate = "${match.groupValues[1]}p${page.toString().padStart(3, '0')}.${match.groupValues[2]}${match.groupValues[3]}"
        return ReaderImageCache.hintedNtkGeneratedImageUrl(candidate) ?: candidate
    }

    private fun ntkGeneratedSeedPage(seed: String): Int {
        return Regex("/p(\\d{3,})\\.").find(seed)
            ?.groupValues
            ?.getOrNull(1)
            ?.toIntOrNull()
            ?.takeIf { it > 0 }
            ?: 1
    }

    private fun ntkImagePageNumber(image: String): Int? {
        return Regex("/p(\\d{3,})\\.(?:jpg|jpeg|png|webp)(?:[?#].*)?$", RegexOption.IGNORE_CASE)
            .find(image)
            ?.groupValues
            ?.getOrNull(1)
            ?.toIntOrNull()
            ?.takeIf { it > 0 }
    }

    private fun ntkGeneratedPageNumber(image: String): Int? {
        return NTK_GENERATED_PAGE_URL.find(image)
            ?.groupValues
            ?.getOrNull(1)
            ?.toIntOrNull()
            ?.takeIf { it > 0 }
    }

    private fun ntkVerifiedImageUrlForPage(target: Manga, page: Int, sourceIndex: Int? = null): String? {
        if (page <= 0) return null
        val cachedImages = ReaderImageCache.cachedNtkApiFallbackImages(target.ntkEpisodePath)
        val earlyImages = ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, SystemClock.elapsedRealtime() - 30000L)
        val currentImages = target.getImgs(null)
        if (sourceIndex != null && sourceIndex >= 0) {
            sequenceOf(cachedImages, earlyImages, currentImages?.toList().orEmpty())
                .mapNotNull { list ->
                    list.getOrNull(sourceIndex)
                        ?.takeIf { it.isNotBlank() }
                        ?.takeIf { !isNtkGeneratedImageUrl(it) }
                }
                .firstOrNull()
                ?.let { return it }
        }
        val candidates = ArrayList<String>()
        candidates.addAll(cachedImages)
        candidates.addAll(earlyImages)
        if (!currentImages.isNullOrEmpty()) candidates.addAll(currentImages)
        return candidates.firstOrNull { candidate ->
            !isNtkGeneratedImageUrl(candidate) && ntkImagePageNumber(candidate) == page
        }
    }

    private fun postNtkImageCloudflareCaptcha(index: Int, page: PageRef, e: Exception): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        val image = page.image ?: return false
        if (!isNtkGeneratedImageUrl(image)) return false
        if (!isNtkImageCloudflareHardBlockError(e)) return false
        val client = MainApplication.getHttpClient()
        if (!client.hasRecentCloudflareChallenge()) return false
        val now = SystemClock.elapsedRealtime()
        val previous = ntkImageCaptchaLastPostedAt.get()
        if (now - previous < 15_000L) return true
        if (!ntkImageCaptchaLastPostedAt.compareAndSet(previous, now)) return true
        Log.d(
            TAG,
            "reader_ntk_image_cloudflare_captcha index=$index,source=${page.sourceIndex}," +
                "path=${page.manga.ntkEpisodePath},image=${image.substringAfterLast('/').takeLast(80)}," +
                "challenge=${client.getLastCloudflareChallengeUrl()},error=${e.message}"
        )
        postCaptchaRequired(page.manga)
        return true
    }

    private fun ntkReplacementImageUrlForPage(
        target: Manga,
        currentImage: String,
        page: Int,
        sourceIndex: Int? = null
    ): String? {
        if (page <= 0) return null
        val exactReplacement = ntkCachedOrEarlyReplacementImageUrlForPage(
            target,
            currentImage,
            page,
            sourceIndex
        )
        if (!exactReplacement.isNullOrBlank()) return exactReplacement
        val verified = ntkVerifiedImageUrlForPage(target, page, sourceIndex)
        if (!verified.isNullOrBlank() && verified != currentImage) return verified
        return ntkGeneratedImageUrlForTarget(currentImage, target, page)
    }

    private fun ntkCachedOrEarlyReplacementImageUrlForPage(
        target: Manga,
        currentImage: String,
        page: Int,
        sourceIndex: Int?
    ): String? {
        if (page <= 0) return null
        val lists = arrayOf(
            ReaderImageCache.cachedNtkApiFallbackImages(target.ntkEpisodePath),
            ReaderImageCache.earlyNtkImageUrls(target.ntkEpisodePath, SystemClock.elapsedRealtime() - 30000L),
            target.getImgs(null)?.toList().orEmpty()
        )
        if (sourceIndex != null && sourceIndex >= 0) {
            for (list in lists) {
                val candidate = list.getOrNull(sourceIndex) ?: continue
                if (isUsableNtkReplacementImage(candidate, currentImage, target, page)) return candidate
            }
        }
        for (list in lists) {
            for (candidate in list) {
                if (isUsableNtkReplacementImage(candidate, currentImage, target, page)) return candidate
            }
        }
        return null
    }

    private fun replaceUnavailableGeneratedInitialWithAdjacent(source: Manga, startedAt: Long) {
        if (firstBitmapLogged.get()) return
        if (!isNtkSource(source, title)) return
        if (!ntkInitialUnavailableReplacementStarted.compareAndSet(false, true)) return
        logNtkRepositoryStage(
            source,
            "ntk_initial_unavailable_replacement_start",
            "ms=${SystemClock.elapsedRealtime() - startedAt}"
        )
        try {
            initialRecovery.execute {
                try {
                    val replacement = resolveInitialNtkUnavailableEpisode(source)
                    if (cancelled.get() || replacement == null) {
                        logNtkRepositoryStage(
                            source,
                            "ntk_initial_unavailable_replacement_missing",
                            "ms=${SystemClock.elapsedRealtime() - startedAt}"
                        )
                        ntkInitialUnavailableReplacementStarted.set(false)
                        return@execute
                    }
                    val target = replacement.first
                    val urls = replacement.second
                    val removed = removeInitialUnavailableGeneratedPages(source)
                    Log.d(
                        TAG,
                        "ntk_initial_unavailable_generated_replaced sourcePath=${source.ntkEpisodePath} " +
                            "targetPath=${target.ntkEpisodePath} images=${urls.size} removed=$removed"
                    )
                    appendResolvedEpisode(target, urls, ReaderSurfaceView.DIRECTION_NEXT, warm = true)
                    val firstImage = firstDrawableIndexForEpisode(target)
                    if (firstImage >= 0) {
                        requestPageForeground(firstImage)
                        requestInitialContinuousPagesFromEarlyUrls(firstImage, synchronized(pagesLock) { pages.size })
                    }
                } catch (e: Exception) {
                    ntkInitialUnavailableReplacementStarted.set(false)
                    recordIfUnexpected(e)
                }
            }
        } catch (_: RejectedExecutionException) {
            ntkInitialUnavailableReplacementStarted.set(false)
        }
    }

    private fun removeInitialUnavailableGeneratedPages(source: Manga): Int {
        if (trustedNtkGeneratedImageCount(source) > 0) {
            Log.d(
                TAG,
                "remove_initial_unavailable_generated_skip_authoritative_count " +
                    "trusted=${trustedNtkGeneratedImageCount(source)},known=${source.ntkImageCount}," +
                    "path=${source.ntkEpisodePath}"
            )
            return 0
        }
        val start: Int
        val removed: Int
        val total: Int
        synchronized(pagesLock) {
            val indexes = pages.withIndex()
                .filter {
                    it.value.transitionTitle == null &&
                        Manga.sameEpisodeIdentity(it.value.manga, source) &&
                        isNtkGeneratedImageUrl(it.value.image.orEmpty())
                }
                .map { it.index }
            if (indexes.isEmpty()) return 0
            beginStructurePublish()
            start = indexes.first()
            removed = indexes.size
            for (index in indexes.asReversed()) {
                pages.removeAt(index)
            }
            pages.forEachIndexed { pageIndex, ref -> ref.pageIndex = pageIndex }
            clearPageStateFromIndex(start)
            total = pages.size
            capturePublishedPageIndexLocked()
        }
        val posted = main.post {
            try {
                if (!cancelled.get()) {
                    listener.onPagesRemoved(start, removed, total)
                }
            } finally {
                finishStructurePublish()
            }
        }
        if (!posted) finishStructurePublish()
        return removed
    }

    private fun firstDrawableIndexForEpisode(target: Manga): Int = synchronized(pagesLock) {
        pages.indexOfFirst {
            it.transitionTitle == null && Manga.sameEpisodeIdentity(it.manga, target)
        }
    }

    private fun isUsableNtkReplacementImage(
        candidate: String?,
        currentImage: String,
        target: Manga,
        page: Int
    ): Boolean {
        if (candidate.isNullOrBlank() || candidate == currentImage) return false
        if (ntkImagePageNumber(candidate) != page) return false
        if (!ntkImageCandidateMatchesEpisode(candidate, target)) return false
        if (isNtkGeneratedImageUrl(candidate) &&
            ReaderImageCache.isKnownNtkGeneratedNotFound(target, candidate)
        ) {
            return false
        }
        return true
    }

    private fun ntkGeneratedImageUrlForTarget(seed: String, target: Manga, page: Int): String? {
        if (page <= 0) return null
        val seedMatch = NTK_GENERATED_IMAGE_URL.matchEntire(seed) ?: return null
        val targetMatch = NTK_EPISODE_PATH.matchEntire(target.ntkEpisodePath.orEmpty()) ?: return ntkGeneratedSiblingImageUrl(seed, page)
        val seedTargetPath = ntkGeneratedPathFromPrefix(seedMatch.groupValues[1])
        if (shouldPreserveApiGeneratedSeedPrefix(seedMatch.groupValues[1], target, targetMatch)) {
            return ntkGeneratedSiblingImageUrl(seed, page)
        }
        if ((seedTargetPath != null && seedTargetPath.equals(target.ntkEpisodePath.orEmpty(), ignoreCase = true)) ||
            ntkGeneratedPrefixEpisodeMatchesTarget(seedMatch.groupValues[1], targetMatch)
        ) {
            return ntkGeneratedSiblingImageUrl(seed, page)
        }
        val segment = targetMatch.groupValues[1]
        val pathEpisodeId = targetMatch.groupValues[3]
        val imageEpisodeId = target.ntkImageEpisodeId.orEmpty().trim()
        val episodeId = pathEpisodeId.takeIf { it.matches(Regex("\\d+")) }
            ?: imageEpisodeId.takeIf { it.matches(Regex("\\d+")) }
            ?: pathEpisodeId
        val seedPrefix = seedMatch.groupValues[1]
        val targetPrefix = when {
            seedPrefix.contains("/blacktoon/episodes/", ignoreCase = true) -> {
                val seedWorkId = Regex("/blacktoon/episodes/([^/]+)/").find(seedPrefix)
                    ?.groupValues
                    ?.getOrNull(1)
                    ?: return ntkGeneratedSiblingImageUrl(seed, page)
                ntkGeneratedPrefixOrigin(seedPrefix) + "/blacktoon/episodes/$seedWorkId/$episodeId/"
            }
            seedPrefix.contains("/wt/episodes/", ignoreCase = true) -> {
                val seedWorkId = Regex("/wt/episodes/([^/]+)/").find(seedPrefix)
                    ?.groupValues
                    ?.getOrNull(1)
                    ?: return ntkGeneratedSiblingImageUrl(seed, page)
                ntkGeneratedPrefixOrigin(seedPrefix) + "/wt/episodes/$seedWorkId/$episodeId/"
            }
            else -> {
                val seedWorkId = Regex("/(?:manhwa|webtoon)/([^/]+)/").find(seedPrefix)
                    ?.groupValues
                    ?.getOrNull(1)
                    ?: targetMatch.groupValues[2]
                ntkGeneratedPrefixOrigin(seedPrefix) + "/$segment/$seedWorkId/$episodeId/"
            }
        }
        val actualPage = ntkGeneratedSeedPage(seed) + page - 1
        val candidate = "${targetPrefix}p${actualPage.toString().padStart(3, '0')}.${seedMatch.groupValues[2]}${seedMatch.groupValues[3]}"
        return ReaderImageCache.hintedNtkGeneratedImageUrl(candidate) ?: candidate
    }

    private fun shouldPreserveApiGeneratedSeedPrefix(
        prefix: String,
        target: Manga,
        targetMatch: MatchResult
    ): Boolean {
        if (!isProtectedApiGeneratedPrefix(prefix)) return false
        val targetEpisode = targetMatch.groupValues[3]
        if (!targetEpisode.matches(Regex("\\d+"))) return true
        val imageWorkId = target.ntkImageWorkId.trim()
        val seedWorkId = apiGeneratedPrefixWorkId(prefix)
        return imageWorkId.matches(Regex("\\d{1,12}")) && seedWorkId == imageWorkId
    }

    private fun isProtectedApiGeneratedPrefix(prefix: String): Boolean {
        return prefix.contains("/black/episodes/", ignoreCase = true) ||
            prefix.contains("/blacktoon/episodes/", ignoreCase = true) ||
            prefix.contains("/wt/episodes/", ignoreCase = true)
    }

    private fun apiGeneratedPrefixWorkId(prefix: String): String? {
        return Regex("^https?://[^/]+/(?:black(?:toon)?/episodes|wt/episodes)/([^/?#]+)/", RegexOption.IGNORE_CASE)
            .find(prefix)
            ?.groupValues
            ?.getOrNull(1)
    }

    private fun ntkGeneratedPrefixOrigin(prefix: String): String {
        val match = Regex("^(https?://[^/]+)", RegexOption.IGNORE_CASE).find(prefix)
        return match?.groupValues?.getOrNull(1) ?: "https://i.toonflix.app"
    }

    private fun ntkGeneratedPathFromPrefix(prefix: String): String? {
        Regex("^https?://[^/]+/(manhwa|webtoon)/(\\d+)/([^/?#]+)/$", RegexOption.IGNORE_CASE)
            .find(prefix)
            ?.let { return "/${it.groupValues[1]}/${it.groupValues[2]}/${it.groupValues[3]}" }
        Regex("^https?://[^/]+/black/episodes/(\\d+)/([^/?#]+)/$", RegexOption.IGNORE_CASE)
            .find(prefix)
            ?.let { return "/webtoon/${it.groupValues[1]}/${it.groupValues[2]}" }
        Regex("^https?://[^/]+/blacktoon/episodes/(\\d+)/([^/?#]+)/$", RegexOption.IGNORE_CASE)
            .find(prefix)
            ?.let { return "/webtoon/${it.groupValues[1]}/${it.groupValues[2]}" }
        Regex("^https?://[^/]+/wt/episodes/([^/?#]+)/([^/?#]+)/$", RegexOption.IGNORE_CASE)
            .find(prefix)
            ?.let { return "/webtoon/${it.groupValues[1]}/${it.groupValues[2]}" }
        return null
    }

    private fun ntkGeneratedPrefixEpisodeMatchesTarget(
        prefix: String,
        targetMatch: MatchResult
    ): Boolean {
        val targetSegment = targetMatch.groupValues[1]
        val targetEpisode = targetMatch.groupValues[3]
        val seedEpisode = when {
            prefix.contains("/black/episodes/", ignoreCase = true) ->
                Regex("^https?://[^/]+/black/episodes/[^/]+/([^/?#]+)/$", RegexOption.IGNORE_CASE)
                    .find(prefix)
                    ?.groupValues
                    ?.getOrNull(1)
            prefix.contains("/blacktoon/episodes/", ignoreCase = true) ->
                Regex("^https?://[^/]+/blacktoon/episodes/[^/]+/([^/?#]+)/$", RegexOption.IGNORE_CASE)
                    .find(prefix)
                    ?.groupValues
                    ?.getOrNull(1)
            prefix.contains("/wt/episodes/", ignoreCase = true) ->
                Regex("^https?://[^/]+/wt/episodes/[^/]+/([^/?#]+)/$", RegexOption.IGNORE_CASE)
                    .find(prefix)
                    ?.groupValues
                    ?.getOrNull(1)
            else ->
                Regex("^https?://[^/]+/(manhwa|webtoon)/[^/]+/([^/?#]+)/$", RegexOption.IGNORE_CASE)
                    .find(prefix)
                    ?.takeIf { it.groupValues[1].equals(targetSegment, ignoreCase = true) }
                    ?.groupValues
                    ?.getOrNull(2)
        }
        return !seedEpisode.isNullOrBlank() && seedEpisode == targetEpisode
    }

    private fun ntkImageCandidateMatchesEpisode(image: String, target: Manga): Boolean {
        if (!isNtkGeneratedImageUrl(image)) return true
        val targetMatch = NTK_EPISODE_PATH.matchEntire(target.ntkEpisodePath.orEmpty()) ?: return true
        val seedPrefix = NTK_GENERATED_IMAGE_URL.matchEntire(image)?.groupValues?.getOrNull(1) ?: return true
        if (shouldPreserveApiGeneratedSeedPrefix(seedPrefix, target, targetMatch)) return true
        val seedTargetPath = ntkGeneratedPathFromPrefix(seedPrefix)
        if (seedTargetPath != null)
            return seedTargetPath.equals(target.ntkEpisodePath.orEmpty(), ignoreCase = true)
        return ntkGeneratedPrefixEpisodeMatchesTarget(seedPrefix, targetMatch)
    }

    private fun removePageStateRange(rangeStart: Int, removedCount: Int) {
        if (removedCount <= 0) return
        if (rangeStart < (strictExactLaunchSeal?.pageCount ?: 0)) {
            strictForwardSuffixLaunchShapeValid.set(false)
        }
        shiftConcurrentMapAfterRemoval(decodedWidths, rangeStart, removedCount)
        shiftConcurrentMapAfterRemoval(desiredWidths, rangeStart, removedCount)
        shiftConcurrentMapAfterRemoval(pendingDeliveryWidths, rangeStart, removedCount)
        shiftConcurrentMapAfterRemoval(sourceWidths, rangeStart, removedCount)
        shiftConcurrentMapAfterRemoval(achievableWidths, rangeStart, removedCount)
        shiftConcurrentMapAfterRemoval(transientGeneratedRetries, rangeStart, removedCount)
        shiftConcurrentMapAfterRemoval(transientGeneratedVisibleRetries, rangeStart, removedCount)
        shiftConcurrentMapAfterRemoval(earlyPreparedBitmaps, rangeStart, removedCount)
        shiftConcurrentMapAfterRemoval(deliveredDrawableProofWidths, rangeStart, removedCount)
        synchronized(indexedStateLock) {
            indexedStateGeneration.incrementAndGet()
            shiftConcurrentMapAfterRemoval(authoritativeTileInstallRetryCounts, rangeStart, removedCount)
            shiftConcurrentMapAfterRemoval(authoritativeTileInstallRetryAtMs, rangeStart, removedCount)
            shiftConcurrentMapAfterRemoval(strictInlineTileRedecodeAttempts, rangeStart, removedCount)
            shiftConcurrentSetAfterRemoval(strictInlineProofDeliveryIntents, rangeStart, removedCount)
            shiftConcurrentSetAfterRemoval(listenerDrawableDeliveries, rangeStart, removedCount)
            shiftConcurrentSetAfterRemoval(drawableReadyHistory, rangeStart, removedCount)
            shiftConcurrentSetAfterRemoval(preRenderedInitialDeliveries, rangeStart, removedCount)
            shiftConcurrentSetAfterRemoval(preRenderedInitialContinuousDeliveries, rangeStart, removedCount)
            shiftConcurrentSetAfterRemoval(preRenderedCommittedDeliveries, rangeStart, removedCount)
            shiftConcurrentSetAfterRemoval(authoritativeTileInstallRetryPosted, rangeStart, removedCount)
            shiftConcurrentSetAfterRemoval(strictInlineTileRedecodePosted, rangeStart, removedCount)
            shiftConcurrentSetAfterRemoval(terminalBitmapRedrivePosted, rangeStart, removedCount)
            shiftConcurrentSetAfterRemoval(strictExactRollingRehydratePages, rangeStart, removedCount)
            shiftConcurrentSetAfterRemoval(hostExactPoolPressureRetiredPages, rangeStart, removedCount)
            indexedStateGeneration.incrementAndGet()
        }
        shiftConcurrentMapAfterRemoval(inFlightWidths, rangeStart, removedCount)
        shiftConcurrentMapAfterRemoval(loadingPages, rangeStart, removedCount)
        shiftConcurrentMapAfterRemoval(urgentLoadingPages, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(loading, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(urgentLoading, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(bytePrefetching, rangeStart, removedCount)
        shiftConcurrentMapAfterRemoval(bytePrefetchCompletedAtMs, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(fullEpisodeSourcePrefetching, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(preAnchorFallbackRetries, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(initialAdjacentDecodeRetries, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(initialGeneratedAssetDecodeListeners, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(initialGeneratedCachedDecodeInFlight, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(initialGeneratedDirectDecodeInFlight, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(initialInteractiveRunwayByteFetches, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(idleFullWidthUpgradeScheduled, rangeStart, removedCount)
        shiftConcurrentSetAfterRemoval(failedPages, rangeStart, removedCount)
        shiftDeliveryQueueAfterRemoval(rangeStart, removedCount)
        shiftDeliveryMapAfterRemoval(primedDeliveryBacklog, rangeStart, removedCount)
        shiftDeliveryMapAfterRemoval(initialDeliveryBacklog, rangeStart, removedCount)
        shiftPreparedMapAfterRemoval(initialPreparedBacklog, rangeStart, removedCount)
        synchronized(deliveredBitmaps) {
            shiftLinkedMapAfterRemoval(deliveredBitmaps, rangeStart, removedCount)
            shiftLinkedMapAfterRemoval(deliveredTiles, rangeStart, removedCount)
            val oldOwned = deliveredOwned.toList()
            deliveredOwned.clear()
            for (index in oldOwned) shiftedIndexAfterRemoval(index, rangeStart, removedCount)?.let { deliveredOwned.add(it) }
            retainedFirstPage = shiftedIndexAfterRemoval(retainedFirstPage, rangeStart, removedCount) ?: rangeStart
            retainedLastPage = shiftedIndexAfterRemoval(retainedLastPage, rangeStart, removedCount) ?: (rangeStart - 1)
            retainedAnchorPage = shiftedIndexAfterRemoval(retainedAnchorPage, rangeStart, removedCount) ?: retainedFirstPage
            recalculateDeliveredBitmapBytesLocked()
        }
        publishDeliveredBitmapBytes()
        physicalDeliveryFirstPage = shiftedIndexAfterRemoval(
            physicalDeliveryFirstPage,
            rangeStart,
            removedCount
        ) ?: 0
        physicalDeliveryLastPage = shiftedIndexAfterRemoval(
            physicalDeliveryLastPage,
            rangeStart,
            removedCount
        ) ?: -1
        synchronized(windowLock) {
            lastWindowAnchor = shiftedIndexAfterRemoval(lastWindowAnchor, rangeStart, removedCount) ?: -1
            windowGeneration.incrementAndGet()
        }
    }

    private fun clearPageStateFromIndex(startIndex: Int, appendOnlyTail: Boolean = false) {
        // Every forward append clears stale bookkeeping at the old tail before adding new refs.
        // No published numeric index changes when startIndex == pages.size, so advancing the
        // indexed generation there invalidated an otherwise current viewport after every p1..pN
        // append. A real in-table clear/remap (startIndex < pages.size) still brackets the mutation
        // with generation changes and therefore fails closed against concurrent transactions.
        val clearsPublishedIndex = synchronized(pagesLock) {
            !appendOnlyTail && startIndex < pages.size
        }
        clearConcurrentMapFromIndex(decodedWidths, startIndex)
        clearConcurrentMapFromIndex(desiredWidths, startIndex)
        clearConcurrentMapFromIndex(pendingDeliveryWidths, startIndex)
        clearConcurrentMapFromIndex(sourceWidths, startIndex)
        clearConcurrentMapFromIndex(achievableWidths, startIndex)
        clearConcurrentMapFromIndex(transientGeneratedRetries, startIndex)
        clearConcurrentMapFromIndex(transientGeneratedVisibleRetries, startIndex)
        clearConcurrentMapFromIndex(earlyPreparedBitmaps, startIndex)
        clearConcurrentMapFromIndex(deliveredDrawableProofWidths, startIndex)
        synchronized(indexedStateLock) {
            if (clearsPublishedIndex) indexedStateGeneration.incrementAndGet()
            clearConcurrentMapFromIndex(authoritativeTileInstallRetryCounts, startIndex)
            clearConcurrentMapFromIndex(authoritativeTileInstallRetryAtMs, startIndex)
            clearConcurrentMapFromIndex(strictInlineTileRedecodeAttempts, startIndex)
            clearConcurrentSetFromIndex(strictInlineProofDeliveryIntents, startIndex)
            clearConcurrentSetFromIndex(listenerDrawableDeliveries, startIndex)
            clearConcurrentSetFromIndex(drawableReadyHistory, startIndex)
            clearConcurrentSetFromIndex(preRenderedInitialDeliveries, startIndex)
            clearConcurrentSetFromIndex(preRenderedInitialContinuousDeliveries, startIndex)
            clearConcurrentSetFromIndex(preRenderedCommittedDeliveries, startIndex)
            clearConcurrentSetFromIndex(authoritativeTileInstallRetryPosted, startIndex)
            clearConcurrentSetFromIndex(strictInlineTileRedecodePosted, startIndex)
            clearConcurrentSetFromIndex(terminalBitmapRedrivePosted, startIndex)
            clearConcurrentSetFromIndex(strictExactRollingRehydratePages, startIndex)
            clearConcurrentSetFromIndex(hostExactPoolPressureRetiredPages, startIndex)
            if (clearsPublishedIndex) indexedStateGeneration.incrementAndGet()
        }
        clearConcurrentMapFromIndex(inFlightWidths, startIndex)
        clearConcurrentMapFromIndex(loadingPages, startIndex)
        clearConcurrentMapFromIndex(urgentLoadingPages, startIndex)
        clearConcurrentSetFromIndex(loading, startIndex)
        clearConcurrentSetFromIndex(urgentLoading, startIndex)
        clearConcurrentSetFromIndex(bytePrefetching, startIndex)
        clearConcurrentMapFromIndex(bytePrefetchCompletedAtMs, startIndex)
        clearConcurrentSetFromIndex(fullEpisodeSourcePrefetching, startIndex)
        clearConcurrentSetFromIndex(preAnchorFallbackRetries, startIndex)
        clearConcurrentSetFromIndex(initialAdjacentDecodeRetries, startIndex)
        clearConcurrentSetFromIndex(initialGeneratedAssetDecodeListeners, startIndex)
        clearConcurrentSetFromIndex(initialGeneratedCachedDecodeInFlight, startIndex)
        clearConcurrentSetFromIndex(initialGeneratedDirectDecodeInFlight, startIndex)
        clearConcurrentSetFromIndex(initialInteractiveRunwayByteFetches, startIndex)
        clearConcurrentSetFromIndex(idleFullWidthUpgradeScheduled, startIndex)
        clearConcurrentSetFromIndex(failedPages, startIndex)
        clearDeliveryQueueFromIndex(startIndex)
        clearDeliveryMapFromIndex(primedDeliveryBacklog, startIndex)
        clearDeliveryMapFromIndex(initialDeliveryBacklog, startIndex)
        clearPreparedMapFromIndex(initialPreparedBacklog, startIndex)
        synchronized(deliveredBitmaps) {
            val removedBitmaps = clearLinkedMapFromIndex(deliveredBitmaps, startIndex)
            val removedTiles = clearLinkedMapFromIndex(deliveredTiles, startIndex)
            removedBitmaps.forEach { bitmap ->
                deliveredBitmapBytes -= trackedBitmapBytes(bitmap)
            }
            removedTiles.forEach { tiles ->
                deliveredBitmapBytes -= trackedTileBytes(tiles)
            }
            deliveredOwned.removeIf { it >= startIndex }
            if (retainedFirstPage >= startIndex) {
                retainedFirstPage = 0
                retainedLastPage = -1
                retainedAnchorPage = 0
            } else if (retainedLastPage >= startIndex) {
                retainedLastPage = startIndex - 1
                retainedAnchorPage = retainedAnchorPage.coerceIn(retainedFirstPage, retainedLastPage)
            }
            deliveredBitmapBytes = deliveredBitmapBytes.coerceAtLeast(0L)
        }
        publishDeliveredBitmapBytes()
        if (physicalDeliveryFirstPage >= startIndex) physicalDeliveryFirstPage = 0
        if (physicalDeliveryLastPage >= startIndex) physicalDeliveryLastPage = startIndex - 1
    }

    private fun shiftedIndexAfterRemoval(index: Int, rangeStart: Int, removedCount: Int): Int? {
        if (index < rangeStart) return index
        if (index < rangeStart + removedCount) return null
        return index - removedCount
    }

    private fun <T> shiftConcurrentMapAfterRemoval(map: ConcurrentHashMap<Int, T>, rangeStart: Int, removedCount: Int) {
        if (map.isEmpty()) return
        val entries = map.entries.toList()
        map.clear()
        for (entry in entries) shiftedIndexAfterRemoval(entry.key, rangeStart, removedCount)?.let { map[it] = entry.value }
    }

    private fun shiftConcurrentSetAfterRemoval(set: MutableSet<Int>, rangeStart: Int, removedCount: Int) {
        if (set.isEmpty()) return
        val entries = set.toList()
        set.clear()
        for (index in entries) shiftedIndexAfterRemoval(index, rangeStart, removedCount)?.let { set.add(it) }
    }

    private fun <T> clearConcurrentMapFromIndex(map: ConcurrentHashMap<Int, T>, startIndex: Int) {
        if (map.isEmpty()) return
        // ConcurrentHashMap's weakly consistent key iterator permits direct removal. Building a
        // boxed key snapshot for each of the dozens of append ledgers created a large allocation
        // burst while pagesLock excluded physical input.
        for (key in map.keys) {
            if (key >= startIndex) map.remove(key)
        }
    }

    private fun clearConcurrentSetFromIndex(set: MutableSet<Int>, startIndex: Int) {
        if (set.isEmpty()) return
        set.removeIf { it >= startIndex }
    }

    private fun <T> clearLinkedMapFromIndex(map: MutableMap<Int, T>, startIndex: Int): List<T> {
        if (map.isEmpty()) return emptyList()
        val removed = ArrayList<T>()
        val iterator = map.entries.iterator()
        while (iterator.hasNext()) {
            val entry = iterator.next()
            if (entry.key >= startIndex) {
                removed += entry.value
                iterator.remove()
            }
        }
        return removed
    }

    private fun shiftDeliveryQueueAfterRemoval(rangeStart: Int, removedCount: Int) {
        if (deliveryQueue.isEmpty()) return
        val entries = ArrayList<Delivery>()
        while (true) {
            entries.add(deliveryQueue.poll() ?: break)
        }
        for (delivery in entries) {
            val current = currentPageIndex(delivery.page, delivery.index)
            if (current < 0) {
                recycleDecodeResult(delivery.result)
            } else {
                deliveryQueue.add(delivery.copy(index = current))
            }
        }
    }

    private fun shiftDeliveryMapAfterRemoval(
        map: ConcurrentHashMap<Int, Delivery>,
        rangeStart: Int,
        removedCount: Int
    ) {
        if (map.isEmpty()) return
        val entries = map.entries.toList()
        map.clear()
        for (entry in entries) {
            val current = currentPageIndex(entry.value.page, entry.value.index)
            if (current < 0) {
                recycleDecodeResult(entry.value.result)
            } else {
                map[current] = entry.value.copy(index = current)
            }
        }
    }

    private fun shiftPreparedMapAfterRemoval(
        map: ConcurrentHashMap<Int, PreparedDelivery>,
        rangeStart: Int,
        removedCount: Int
    ) {
        if (map.isEmpty()) return
        val entries = map.entries.toList()
        val retained = entries.mapNotNull { entry ->
            entry.value.bitmap.takeIf {
                shiftedIndexAfterRemoval(entry.key, rangeStart, removedCount) != null
            }
        }
        val recyclable = BitmapReleaseIdentityPolicy.uniqueCandidatesExcludingRetained(
            entries.filter { entry ->
                shiftedIndexAfterRemoval(entry.key, rangeStart, removedCount) == null &&
                    entry.value.owned
            }.map { entry -> entry.value.bitmap },
            retained,
        )
        map.clear()
        for (entry in entries) {
            val shifted = shiftedIndexAfterRemoval(entry.key, rangeStart, removedCount)
            if (shifted != null) {
                map[shifted] = entry.value
            }
        }
        recyclable.forEach(::recycleBitmapAsync)
    }

    private fun <T> shiftLinkedMapAfterRemoval(map: LinkedHashMap<Int, T>, rangeStart: Int, removedCount: Int) {
        if (map.isEmpty()) return
        val entries = map.entries.toList()
        map.clear()
        for (entry in entries) shiftedIndexAfterRemoval(entry.key, rangeStart, removedCount)?.let { map[it] = entry.value }
    }

    private fun clearDeliveryQueueFromIndex(startIndex: Int) {
        if (deliveryQueue.isEmpty()) return
        val entries = ArrayList<Delivery>()
        while (true) {
            entries.add(deliveryQueue.poll() ?: break)
        }
        for (delivery in entries) {
            if (delivery.index < startIndex) deliveryQueue.add(delivery)
        }
    }

    private fun clearDeliveryMapFromIndex(map: ConcurrentHashMap<Int, Delivery>, startIndex: Int) {
        clearConcurrentMapFromIndex(map, startIndex)
    }

    private fun clearPreparedMapFromIndex(map: ConcurrentHashMap<Int, PreparedDelivery>, startIndex: Int) {
        clearConcurrentMapFromIndex(map, startIndex)
    }

    private fun isExpectedCancellation(t: Throwable?): Boolean {
        if (t == null) return false
        if (cancelled.get()) return true
        if (t is java.util.concurrent.CancellationException) return true
        if (t is InterruptedException || t is InterruptedIOException) return true
        if (t.javaClass.name.endsWith("StreamResetException") && (t.message ?: "").contains("CANCEL")) return true
        if ((t.message ?: "").startsWith("Generated image past tail:")) return true
        if (t is ExecutionException) return isExpectedCancellation(t.cause)
        val cause = t.cause
        return cause != null && cause !== t && isExpectedCancellation(cause)
    }

    private fun decodePageWithLease(
        index: Int,
        page: PageRef,
        targetWidth: Int,
        foregroundFetch: Boolean,
        allowPreviewCache: Boolean,
        visiblePriority: Boolean,
        foregroundPermit: NtkImagePermit? = null
    ): PageDecodeResult {
        if (requiresAuthoritativeInlineTilePage(page)) {
            val image = page.image ?: throw java.io.IOException("Strict inline image is missing")
            val canonicalAsset = ReaderPreparedStore.canonicalOriginalAssetIdentity(image)
            ReaderImageCache.cachedFile(appContext, page.manga, image)?.let { cached ->
                return decodePage(index, page, cached, targetWidth, canonicalAsset = canonicalAsset)
            }
            leaseImageFile(index, page, true, true).use { lease ->
                if (ReaderPreparedStore.canonicalOriginalAssetIdentity(page.image) != canonicalAsset) {
                    throw java.io.IOException("Strict inline manifest changed before decode")
                }
                return decodePage(index, page, lease.file, targetWidth, canonicalAsset = canonicalAsset)
            }
        }
        val initialGeneratedAnchor = shouldUseInitialGeneratedAnchorDirectDecode(index, page)
        if (!initialGeneratedAnchor) {
            cachedDecodedResult(index, page, targetWidth, allowPreviewCache)?.let {
                logNtkPagePerf(index, "cache_hit_decode", "target=$targetWidth,width=${it.width}")
                return it
            }
        }
        if (index == currentStartPage() && isNtkSource(page.manga, title)) {
            val image = page.image
            if (!image.isNullOrBlank()) {
                if (initialGeneratedAnchor) {
                    ReaderImageCache.cachedFile(appContext, page.manga, image)?.let { cached ->
                        logNtkPagePerf(index, "anchor_cached_file_decode", "target=$targetWidth,bytes=${cached.length()}")
                        return decodePage(index, page, cached, targetWidth)
                    }
                }
                decodeForegroundStream(
                    index,
                    page,
                    targetWidth,
                    foregroundFetch = true,
                    visiblePriority = true,
                    permit = foregroundPermit,
                    bypassInitialCachedDecodeGuard = true
                )?.let {
                    logNtkPagePerf(index, "anchor_foreground_stream_hit", "target=$targetWidth,width=${it.width}")
                    return it
                }
                ReaderImageCache.cachedFile(appContext, page.manga, image)?.let { cached ->
                    logNtkPagePerf(index, "anchor_cached_file_decode", "target=$targetWidth,bytes=${cached.length()}")
                    return decodePage(index, page, cached, targetWidth)
                }
            }
        }
        if (initialGeneratedAnchor) {
            cachedDecodedResult(index, page, targetWidth, allowPreviewCache)?.let {
                logNtkPagePerf(index, "cache_hit_decode_after_anchor_stream", "target=$targetWidth,width=${it.width}")
                return it
            }
        }
        decodeForegroundStream(index, page, targetWidth, foregroundFetch, visiblePriority, foregroundPermit)?.let {
            logNtkPagePerf(index, "foreground_stream_hit", "target=$targetWidth,width=${it.width}")
            return it
        }
        val startPage = currentStartPage()
        val trace = shouldTraceNtkPage(index, page)
        val leaseStart = if (page.manga.isOnline && (index == startPage || trace)) SystemClock.elapsedRealtime() else 0L
        leaseImageFile(
            index,
            page,
            foregroundFetch || index == startPage,
            visiblePriority || index == startPage,
            foregroundPermit,
        ).use { lease ->
            if (leaseStart > 0L) {
                val leaseMs = SystemClock.elapsedRealtime() - leaseStart
                if (index == startPage) ViewerWarmupManager.logMetric("reader_first_fetch_wait_ms", leaseMs)
                val image = page.image
                val cached = image != null && ReaderImageCache.cachedFile(appContext, page.manga, image) != null
                logNtkPagePerf(
                    index,
                    "file_lease",
                    "ms=$leaseMs,foreground=$foregroundFetch,visiblePriority=$visiblePriority,cached=$cached"
                )
            }
            return decodePage(index, page, lease.file, targetWidth)
        }
    }

    private fun shouldTraceNtkPage(index: Int, page: PageRef): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        val start = currentStartPage()
        return index in max(0, start - 1)..minOf(start + NTK_TRACE_AHEAD_PAGES, start + 12)
    }

    private fun logNtkPagePerf(index: Int, stage: String, detail: String) {
        if (!isNtkSource(manga, title)) return
        if (shouldSuppressHotNtkPagePerfLog(stage)) return
        val start = currentStartPage()
        if (index !in max(0, start - 1)..minOf(start + NTK_TRACE_AHEAD_PAGES, start + 12)) return
        Log.d(TAG, "reader_ntk_page_perf page=$index,rel=${index - start},stage=$stage,$detail")
    }

    private fun shouldSuppressHotNtkPagePerfLog(stage: String): Boolean {
        if (!isActiveGeneratedInputOrQuietForDelivery()) return false
        return stage == "generated_full_upgrade_defer_active_proof" ||
            stage == "generated_full_upgrade_reschedule_active_proof" ||
            stage == "generated_full_upgrade_retry_defer_active_proof" ||
            stage == "generated_decode_route_active_proof" ||
            stage == "generated_decode_skip_active_runway_bytes" ||
            stage == "initial_continuous_prerender_skip_active_proof" ||
            stage == "visible_generated_route_proof" ||
            stage == "drop_duplicate_pending_delivery" ||
            stage == "generated_decode_skip_active_beyond_byte_window" ||
            stage == "generated_decode_skip_active_far_request" ||
            stage == "byte_prefetch_defer_scroll_quiet" ||
            stage == "visible_generated_byte_hedge_suppressed_active_far" ||
            stage == "initial_continuous_visible_suppressed_active_far"
    }

    private fun decodeForegroundStream(
        index: Int,
        page: PageRef,
        targetWidth: Int,
        foregroundFetch: Boolean,
        visiblePriority: Boolean,
        permit: NtkImagePermit?,
        bypassInitialCachedDecodeGuard: Boolean = false,
        proofDrawable: Boolean = false
    ): PageDecodeResult? = withProtectedNumericDecodePermit(page) {
        decodeForegroundStreamUnlocked(
            index,
            page,
            targetWidth,
            foregroundFetch,
            visiblePriority,
            permit,
            bypassInitialCachedDecodeGuard,
            proofDrawable
        )
    }

    private fun decodeForegroundStreamUnlocked(
        index: Int,
        page: PageRef,
        targetWidth: Int,
        foregroundFetch: Boolean,
        visiblePriority: Boolean,
        permit: NtkImagePermit?,
        bypassInitialCachedDecodeGuard: Boolean,
        proofDrawable: Boolean
    ): PageDecodeResult? {
        if (!page.manga.isOnline || (!foregroundFetch && index != currentStartPage())) return null
        val image = page.image ?: return null
        if (isNtkSource(page.manga, title) &&
            isNtkGeneratedImageUrl(image) &&
            (hasDeliveredBitmap(index) ||
                listenerDrawableDeliveries.contains(index) ||
                (pendingDeliveryWidths[index] ?: 0) > 0 ||
                (decodedWidths[index] ?: 0) > 0)
        ) {
            logNtkPagePerf(index, "foreground_stream_skip_ready", "target=$targetWidth")
            return null
        }
        if (!bypassInitialCachedDecodeGuard && shouldPreferInitialGeneratedCachedDecode(index, page)) {
            logNtkPagePerf(index, "foreground_stream_skip_cached_decode_in_flight", "target=$targetWidth")
            return null
        }
        if (!ntkCoordinatorAllowsStream(index, page, permit, "decodeForegroundStream")) return null
        val metric = SystemClock.elapsedRealtime()
        val raw = try {
            withProtectedNumericNetworkPermit(page.manga) {
                ReaderImageCache.decodeForegroundBitmap(
                    appContext,
                    page.manga,
                    image,
                    targetWidth,
                    autoCut,
                    page.allowAutoSplit,
                    imageCancellation,
                    anchorHedge = false,
                    visiblePriority = visiblePriority || index == currentStartPage(),
                    permit = permit,
                    pageIndex = index
                )
            }
        } catch (e: Exception) {
            recordIfUnexpected(e)
            null
        } ?: run {
            if (isNtkSource(page.manga, title) && isNtkGeneratedImageUrl(image)) {
                if (hasDeliveredBitmap(index) ||
                    listenerDrawableDeliveries.contains(index) ||
                    (pendingDeliveryWidths[index] ?: 0) > 0 ||
                    (decodedWidths[index] ?: 0) > 0
                ) {
                    logNtkPagePerf(
                        index,
                        "foreground_stream_cached_file_fallback_skip_ready",
                        "target=$targetWidth"
                    )
                    return null
                }
                ReaderImageCache.cachedFile(appContext, page.manga, image)?.let { cached ->
                    logNtkPagePerf(
                        index,
                        "foreground_stream_cached_file_fallback",
                        "bytes=${cached.length()},target=$targetWidth"
                    )
                    return decodePage(index, page, cached, targetWidth)
                }
            }
            return null
        }
        val rawAt = SystemClock.elapsedRealtime()
        if (shouldAbortNtkForegroundStreamAfterRaw(index, page, targetWidth, bypassInitialCachedDecodeGuard)) {
            if (!raw.isRecycled) raw.recycle()
            logNtkPagePerf(index, "foreground_stream_abort_after_raw_ready", "target=$targetWidth")
            return null
        }
        val decodeTargetWidth = decodeTargetWidth(raw.width, raw.height, targetWidth, page.allowAutoSplit)
        val decoded = if (raw.width <= decodeTargetWidth) {
            raw
        } else {
            Decoder(page.manga.seed, page.manga.id).decode(raw, decodeTargetWidth, Glide.get(appContext).bitmapPool)
        }
        if (decoded !== raw && !raw.isRecycled) raw.recycle()
        deliverAutoSplitSiblingFromDecoded(index, page, decoded)
        val transformedAt = SystemClock.elapsedRealtime()
        val displayDecoded = applyAutoSplit(decoded, page.side, page.allowAutoSplit)
        postPageBounds(index, page, displayDecoded.width, displayDecoded.height)
        val interactiveGeneratedPreview = !proofDrawable && shouldUseInteractiveGeneratedPreviewDecode(index, page)
        val trimmed = if (proofDrawable || interactiveGeneratedPreview || shouldSkipInitialGeneratedBlankTrim(index, page)) {
            displayDecoded
        } else {
            ViewerBitmapTrim.trimBlankVerticalEdges(displayDecoded, true)
        }
        val drawTargetWidth = targetWidth
        val bitmap = scaleInitialNtkGeneratedForDraw(index, page, trimmed, drawTargetWidth)
        val splitGenerated = !interactiveGeneratedPreview && shouldSplitNtkGeneratedBitmapForDraw(index, page, bitmap)
        val result = drawableResult(
            bitmap,
            splitForDraw = shouldSplitDecodedPageForDraw(index, page, splitGenerated),
            forceSplitForDraw = splitGenerated,
            tileHeight = if (splitGenerated) NTK_GENERATED_DRAW_TILE_HEIGHT else DECODED_DRAW_TILE_HEIGHT
        )
        ViewerWarmupManager.logMetric("reader_first_stream_raw_ms", rawAt - metric)
        ViewerWarmupManager.logMetric("reader_first_stream_transform_ms", transformedAt - rawAt)
        ViewerWarmupManager.logMetric("reader_first_decode_total_ms", SystemClock.elapsedRealtime() - metric)
        logNtkPagePerf(index, "foreground_stream_decode", "rawMs=${rawAt - metric},transformMs=${transformedAt - rawAt},totalMs=${SystemClock.elapsedRealtime() - metric},width=${result.width}")
        return result
    }

    private fun shouldAbortNtkForegroundStreamAfterRaw(
        index: Int,
        page: PageRef,
        targetWidth: Int,
        bypassInitialCachedDecodeGuard: Boolean = false
    ): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        val start = currentStartPage()
        if (hasDeliveredBitmap(index) || listenerDrawableDeliveries.contains(index)) return true
        val pendingWidth = pendingDeliveryWidths[index] ?: 0
        if (pendingWidth >= targetWidth) return true
        val decodedWidth = decodedWidths[index] ?: 0
        if (decodedWidth >= targetWidth) return true
        if (index == start && initialAnchorCachedDecodeStarted.get() && !bypassInitialCachedDecodeGuard) {
            return true
        }
        if (index !in (start + 1) until (start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)) return false
        return !bypassInitialCachedDecodeGuard && initialGeneratedCachedDecodeInFlight.contains(index)
    }

    private fun cancelInitialGeneratedForegroundWorkAfterDrawableQueued(
        page: PageRef,
        image: String,
        reason: String
    ) {
        if (!isNtkSource(page.manga, title)) return
        if (!isNtkGeneratedImageUrl(image)) return
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return
        ReaderImageCache.cancelNtkGeneratedForegroundWorkForImages(
            page.manga,
            listOf(image),
            reason
        )
    }

    private fun shouldUseInitialGeneratedCachedDecodeGuard(index: Int, page: PageRef): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        val start = currentStartPage()
        if (index <= start || index >= start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return false
        if (initialContinuousDrawableDelivered(start)) return false
        return true
    }

    private fun shouldSuppressFarInitialGeneratedVisibleActiveDecode(index: Int, page: PageRef): Boolean {
        if (!firstBitmapLogged.get()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (
            ntkInitialInteractiveSettleRemainingMs() <= 0L &&
            !viewportBusy.get() &&
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) <= 0L
        ) {
            return false
        }
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        if (index < anchor) {
            logNtkPagePerf(index, "visible_active_skip_direct_decode_suppressed", "anchor=$anchor,behind=true")
            return true
        }
        val activeAheadLimit = if (isImmediateNtkGeneratedUx()) {
            initialContinuousViewportAheadPages()
        } else if (pendingAdjacentAppendPublishKeys.isNotEmpty()) {
            NTK_PENDING_APPEND_VISIBLE_DIRECT_DECODE_AHEAD_PAGES
        } else {
            NTK_ACTIVE_VISIBLE_DIRECT_DECODE_AHEAD_PAGES
        }
        if (index > anchor + activeAheadLimit) {
            logNtkPagePerf(
                index,
                "visible_active_skip_direct_decode_suppressed",
                "anchor=$anchor,ahead=${index - anchor}"
            )
            return true
        }
        return false
    }

    private fun shouldUseInitialGeneratedStreamRunwayGuard(index: Int, page: PageRef): Boolean {
        if (firstBitmapLogged.get()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        val start = currentStartPage()
        if (index <= start || index >= start + NTK_GENERATED_INITIAL_CONTINUOUS_RUNWAY_PAGES) return false
        if (!ReaderImageCache.hasNtkAnchorAssetForEpisode(page.manga) &&
            index > start + NTK_PRE_ANCHOR_RUNWAY_WITHOUT_ANCHOR_ASSET
        ) return false
        if (initialContinuousDrawableDelivered(start)) return false
        return true
    }

    private fun shouldUseInitialGeneratedAnchorDirectDecode(index: Int, page: PageRef): Boolean {
        if (firstBitmapLogged.get()) return false
        if (index != currentStartPage()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedDescriptorOrImagePage(page)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        return true
    }

    private fun shouldPreferInitialGeneratedCachedDecode(index: Int, page: PageRef): Boolean {
        if (!shouldUseInitialGeneratedCachedDecodeGuard(index, page)) return false
        return initialGeneratedCachedDecodeInFlight.contains(index)
    }

    private fun shouldUsePreviewDecodedCache(index: Int, targetWidth: Int): Boolean {
        return targetWidth < targetWidth(false) && !hasDeliveredBitmap(index)
    }

    private fun cachedDecodedResult(
        index: Int,
        page: PageRef,
        targetWidth: Int,
        allowPreviewCache: Boolean
    ): PageDecodeResult? = withProtectedNumericDecodePermit(page) {
        cachedDecodedResultUnlocked(index, page, targetWidth, allowPreviewCache)
    }

    private fun cachedDecodedResultUnlocked(
        index: Int,
        page: PageRef,
        targetWidth: Int,
        allowPreviewCache: Boolean
    ): PageDecodeResult? {
        val image = page.image ?: return null
        val pageItem = PageItem(page.sourceIndex, image, page.manga, page.side)
        val bitmap = ViewerWarmupManager.getDecodedBitmapExclusive(
            pageItem,
            autoCut,
            reverse,
            targetWidth,
            false
        ) ?: if (allowPreviewCache) {
            ViewerWarmupManager.getDecodedBitmapExclusive(
                pageItem,
                autoCut,
                reverse,
                targetWidth,
                true
            )
        } else {
            null
        } ?: return null
        if (bitmap.isRecycled) return null
        var ownedIntermediate: Bitmap? = bitmap
        return try {
            val trimmed = ViewerBitmapTrim.trimBlankVerticalEdges(bitmap, true)
            ownedIntermediate = trimmed
            val displayBitmap = scaleInitialNtkGeneratedForDraw(
                index,
                page,
                trimmed,
                targetWidth,
                recycleSource = true
            )
            ownedIntermediate = displayBitmap
            val splitGenerated = shouldSplitNtkGeneratedBitmapForDraw(index, page, displayBitmap)
            drawableResult(
                displayBitmap,
                splitForDraw = shouldSplitDecodedPageForDraw(index, page, splitGenerated),
                forceSplitForDraw = splitGenerated,
                tileHeight = if (splitGenerated) NTK_GENERATED_DRAW_TILE_HEIGHT else DECODED_DRAW_TILE_HEIGHT
            ).also {
                // Full transfers this private identity; Tiles retired it after copying each tile.
                ownedIntermediate = null
            }
        } catch (_: Throwable) {
            ownedIntermediate?.let { owned ->
                if (!owned.isRecycled) releaseBitmapToPoolOrRecycle(owned)
            }
            null
        }
    }

    private fun decodePage(
        index: Int,
        page: PageRef,
        file: File,
        targetWidth: Int,
        proofDrawable: Boolean = false,
        canonicalAsset: String = ReaderPreparedStore.canonicalOriginalAssetIdentity(page.image)
    ): PageDecodeResult = withProtectedNumericDecodePermit(page) {
        withStrictDecodeTelemetry(index, page, canonicalAsset) {
            decodePageUnlocked(index, page, file, targetWidth, proofDrawable, canonicalAsset)
        }
    }

    private fun decodePageUnlocked(
        index: Int,
        page: PageRef,
        file: File,
        targetWidth: Int,
        proofDrawable: Boolean,
        canonicalAsset: String
    ): PageDecodeResult {
        val metric = index == currentStartPage() && page.manga.isOnline
        val trace = shouldTraceNtkPage(index, page)
        val startedAt = if (metric || trace) SystemClock.elapsedRealtime() else 0L
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        if (page.manga.isOnline || file.exists()) {
            BitmapFactory.decodeFile(file.absolutePath, bounds)
        } else {
            decodeLocal(page.image ?: "", bounds)
        }
        val boundsAt = if (metric || trace) SystemClock.elapsedRealtime() else 0L
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0) {
            throw java.io.IOException("Bitmap bounds decode failed")
        }
        val displayBounds = displayBounds(bounds.outWidth, bounds.outHeight, page.side, page.allowAutoSplit)
        postPageBounds(index, page, displayBounds.width(), displayBounds.height())
        if (shouldDecodePageAsTiles(index, page, file, bounds, proofDrawable)) {
            val result = decodePageTiles(
                file,
                bounds,
                targetWidth,
                // The inline surface accepts one immutable identity: original/sample-1 tiles
                // split on the 512-source-pixel Store boundary.  A "proof" for that surface is
                // therefore already the full-quality result; decoding a 1024px-tiled variant
                // only makes it fail authoritative ACK and consume the bounded decode gate again.
                forceOriginal = strictExactColdRolling || strictInlineForceOriginalTilesPolicy(
                    requiresAuthoritativeInlineTilePage(page),
                    proofDrawable
                ),
                canonicalAsset = canonicalAsset
            )
            if (trace) {
                logNtkPagePerf(index, "decode_tiles", "boundsMs=${boundsAt - startedAt},totalMs=${SystemClock.elapsedRealtime() - startedAt},target=$targetWidth,width=${result.width}")
            }
            return result
        }
        val decodeTargetWidth = decodeTargetWidth(bounds.outWidth, bounds.outHeight, targetWidth, page.allowAutoSplit)
        val initialGeneratedPreview = proofDrawable || shouldUseInteractiveGeneratedPreviewDecode(index, page)
        val decodeSampleSize = if (initialGeneratedPreview) {
            initialGeneratedPreviewSampleSize(bounds.outWidth, decodeTargetWidth)
        } else {
            sampleSize(bounds.outWidth, decodeTargetWidth)
        }
        val pooledDecodeBitmap = if (initialGeneratedPreview) {
            obtainInitialGeneratedDecodeInBitmap(
                bounds.outWidth,
                bounds.outHeight,
                decodeSampleSize,
                decodeTargetWidth
            )
        } else {
            null
        }
        val options = BitmapFactory.Options().apply {
            inPreferredConfig = Bitmap.Config.ARGB_8888
            inSampleSize = decodeSampleSize
            if (initialGeneratedPreview) {
                inMutable = true
                pooledDecodeBitmap?.let { inBitmap = it }
                applyInitialGeneratedDecodeScale(sampledBitmapWidth(bounds.outWidth, decodeSampleSize), decodeTargetWidth)
            }
        }
        val raw = decodeWithPooledBitmapFallback(options, pooledDecodeBitmap) { decodeOptions ->
            if (page.manga.isOnline || file.exists()) {
                BitmapFactory.decodeFile(file.absolutePath, decodeOptions)
            } else {
                decodeLocal(page.image ?: "", decodeOptions)
            }
        }
            ?: throw java.io.IOException("Bitmap decode failed")
        val rawAt = if (metric || trace) SystemClock.elapsedRealtime() else 0L
        if (!page.manga.isOnline) {
            val bitmap = ViewerBitmapTrim.trimBlankVerticalEdges(
                applyAutoSplit(raw, page.side, page.allowAutoSplit),
                true
            )
            bitmap.prepareToDraw()
            postPageBounds(index, page, bitmap.width, bitmap.height)
            val result = drawableResult(bitmap)
            if (trace) {
                logNtkPagePerf(index, "decode_local", "boundsMs=${boundsAt - startedAt},rawMs=${rawAt - boundsAt},totalMs=${SystemClock.elapsedRealtime() - startedAt},target=$targetWidth,width=${result.width}")
            }
            return result
        }
        val decoded = if (
            (isNtkSource(page.manga, title) && isNtkGeneratedImageUrl(page.image.orEmpty())) ||
            raw.width <= decodeTargetWidth
        ) {
            raw
        } else {
            Decoder(page.manga.seed, page.manga.id).decode(raw, decodeTargetWidth, Glide.get(appContext).bitmapPool)
        }
        if (decoded !== raw && !raw.isRecycled) raw.recycle()
        deliverAutoSplitSiblingFromDecoded(index, page, decoded)
        val transformedAt = if (metric || trace) SystemClock.elapsedRealtime() else 0L
        val autoSplit = applyAutoSplit(decoded, page.side, page.allowAutoSplit)
        val trimmed = if (proofDrawable || initialGeneratedPreview) {
            autoSplit
        } else {
            ViewerBitmapTrim.trimBlankVerticalEdges(autoSplit, true)
        }
        val drawTargetWidth = targetWidth
        val scaledForDraw = scaleInitialNtkGeneratedForDraw(index, page, trimmed, drawTargetWidth)
        val bitmap = if (proofDrawable) {
            ensureProofDrawableWidth(index, scaledForDraw, drawTargetWidth)
        } else {
            scaledForDraw
        }
        if (proofDrawable) {
            val result = PageDecodeResult.Full(bitmap)
            if (trace) {
                val finishedAt = SystemClock.elapsedRealtime()
                logNtkPagePerf(index, "decode_file_proof", "boundsMs=${boundsAt - startedAt},rawMs=${rawAt - boundsAt},transformMs=${transformedAt - rawAt},totalMs=${finishedAt - startedAt},target=$targetWidth,width=${result.width}")
            }
            return result
        }
        val splitGenerated = shouldSplitNtkGeneratedBitmapForDraw(index, page, bitmap)
        val result = drawableResult(
            bitmap,
            splitForDraw = shouldSplitDecodedPageForDraw(index, page, splitGenerated),
            forceSplitForDraw = splitGenerated,
            tileHeight = if (splitGenerated) NTK_GENERATED_DRAW_TILE_HEIGHT else DECODED_DRAW_TILE_HEIGHT
        )
        if (metric) {
            val finishedAt = SystemClock.elapsedRealtime()
            ViewerWarmupManager.logMetric("reader_first_bounds_ms", boundsAt - startedAt)
            ViewerWarmupManager.logMetric("reader_first_raw_decode_ms", rawAt - boundsAt)
            ViewerWarmupManager.logMetric("reader_first_transform_ms", transformedAt - rawAt)
            ViewerWarmupManager.logMetric("reader_first_decode_total_ms", finishedAt - startedAt)
        }
        if (trace) {
            val finishedAt = SystemClock.elapsedRealtime()
            logNtkPagePerf(index, "decode_file", "boundsMs=${boundsAt - startedAt},rawMs=${rawAt - boundsAt},transformMs=${transformedAt - rawAt},totalMs=${finishedAt - startedAt},target=$targetWidth,width=${result.width}")
        }
        return result
    }

    private fun decodePageBytes(
        index: Int,
        page: PageRef,
        bytes: ByteArray,
        targetWidth: Int,
        proofDrawable: Boolean = false
    ): PageDecodeResult = withProtectedNumericDecodePermit(page) {
        withStrictDecodeTelemetry(
            index,
            page,
            ReaderPreparedStore.canonicalOriginalAssetIdentity(page.image)
        ) {
            decodePageBytesUnlocked(index, page, bytes, targetWidth, proofDrawable)
        }
    }

    private inline fun withStrictDecodeTelemetry(
        index: Int,
        page: PageRef,
        sourceIdentity: String,
        block: () -> PageDecodeResult
    ): PageDecodeResult {
        val pagePath = page.manga.ntkEpisodePath.orEmpty()
        val normalizedPath = NtkStripDigests.normalizeEpisodePath(pagePath)
        val strictRollingMatch = strictExactLaunchSeal?.let { seal ->
            seal.matchesEpisodePath(pagePath) && seal.matchesSource(page.sourceIndex, page.image)
        } == true
        val activeTelemetryMatch = ViewerTelemetry.isActiveEpisode(pagePath) ||
            ViewerTelemetry.isActiveEpisode(normalizedPath)
        if (!usesProtectedNumericNtkPipeline(page) &&
            !strictRollingMatch &&
            !activeTelemetryMatch
        ) return block()
        val sourceKeyHash = NtkStripDigests.sha256Tokens(
            "viewer-decode-v1",
            sourceIdentity.ifBlank { page.image.orEmpty() }
        )
        val operationId = ViewerTelemetry.imageDecodeStarted(sourceKeyHash, index)
        return try {
            val result = block()
            val decodedBytes = when (result) {
                is PageDecodeResult.Full -> trackedBitmapBytes(result.bitmap)
                is PageDecodeResult.Tiles -> trackedTileBytes(result.tiles)
            }
            ViewerTelemetry.imageDecodeFinished(
                operationId,
                decodedBytes,
                if (result is PageDecodeResult.Tiles) "success_tiles" else "success_bitmap"
            )
            result
        } catch (t: Throwable) {
            ViewerTelemetry.imageDecodeFinished(
                operationId,
                0L,
                "failed_${t.javaClass.simpleName.ifBlank { "unknown" }}"
            )
            throw t
        }
    }

    private fun decodePageBytesUnlocked(
        index: Int,
        page: PageRef,
        bytes: ByteArray,
        targetWidth: Int,
        proofDrawable: Boolean
    ): PageDecodeResult {
        if (bytes.size < 32) throw java.io.IOException("Bitmap bytes too small")
        val metric = index == currentStartPage() && page.manga.isOnline
        val trace = shouldTraceNtkPage(index, page)
        val startedAt = if (metric || trace) SystemClock.elapsedRealtime() else 0L
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size, bounds)
        val boundsAt = if (metric || trace) SystemClock.elapsedRealtime() else 0L
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0) {
            throw java.io.IOException("Bitmap bounds decode failed")
        }
        val displayBounds = displayBounds(bounds.outWidth, bounds.outHeight, page.side, page.allowAutoSplit)
        postPageBounds(index, page, displayBounds.width(), displayBounds.height())
        val decodeTargetWidth = decodeTargetWidth(bounds.outWidth, bounds.outHeight, targetWidth, page.allowAutoSplit)
        val initialGeneratedPreview = proofDrawable || shouldUseInteractiveGeneratedPreviewDecode(index, page)
        val decodeSampleSize = if (initialGeneratedPreview) {
            initialGeneratedPreviewSampleSize(bounds.outWidth, decodeTargetWidth)
        } else {
            sampleSize(bounds.outWidth, decodeTargetWidth)
        }
        val pooledDecodeBitmap = if (initialGeneratedPreview) {
            obtainInitialGeneratedDecodeInBitmap(
                bounds.outWidth,
                bounds.outHeight,
                decodeSampleSize,
                decodeTargetWidth
            )
        } else {
            null
        }
        val options = BitmapFactory.Options().apply {
            inPreferredConfig = Bitmap.Config.ARGB_8888
            inSampleSize = decodeSampleSize
            if (initialGeneratedPreview) {
                inMutable = true
                pooledDecodeBitmap?.let { inBitmap = it }
                applyInitialGeneratedDecodeScale(sampledBitmapWidth(bounds.outWidth, decodeSampleSize), decodeTargetWidth)
            }
        }
        val raw = decodeWithPooledBitmapFallback(options, pooledDecodeBitmap) { decodeOptions ->
            BitmapFactory.decodeByteArray(bytes, 0, bytes.size, decodeOptions)
        }
            ?: throw java.io.IOException("Bitmap byte decode failed")
        val rawAt = if (metric || trace) SystemClock.elapsedRealtime() else 0L
        val decoded = if (
            (isNtkSource(page.manga, title) && isNtkGeneratedImageUrl(page.image.orEmpty())) ||
            raw.width <= decodeTargetWidth
        ) {
            raw
        } else {
            Decoder(page.manga.seed, page.manga.id).decode(raw, decodeTargetWidth, Glide.get(appContext).bitmapPool)
        }
        if (decoded !== raw && !raw.isRecycled) raw.recycle()
        deliverAutoSplitSiblingFromDecoded(index, page, decoded)
        val transformedAt = if (metric || trace) SystemClock.elapsedRealtime() else 0L
        val autoSplit = applyAutoSplit(decoded, page.side, page.allowAutoSplit)
        val trimmed = if (proofDrawable || initialGeneratedPreview) autoSplit else ViewerBitmapTrim.trimBlankVerticalEdges(autoSplit, true)
        val drawTargetWidth = targetWidth
        val scaledForDraw = scaleInitialNtkGeneratedForDraw(index, page, trimmed, drawTargetWidth)
        val bitmap = if (proofDrawable) ensureProofDrawableWidth(index, scaledForDraw, drawTargetWidth) else scaledForDraw
        val splitGenerated = !initialGeneratedPreview && shouldSplitNtkGeneratedBitmapForDraw(index, page, bitmap)
        val result = drawableResult(
            bitmap,
            splitForDraw = shouldSplitDecodedPageForDraw(index, page, splitGenerated),
            forceSplitForDraw = splitGenerated,
            tileHeight = if (splitGenerated) NTK_GENERATED_DRAW_TILE_HEIGHT else DECODED_DRAW_TILE_HEIGHT
        )
        if (metric) {
            val finishedAt = SystemClock.elapsedRealtime()
            ViewerWarmupManager.logMetric("reader_first_bounds_ms", boundsAt - startedAt)
            ViewerWarmupManager.logMetric("reader_first_raw_decode_ms", rawAt - boundsAt)
            ViewerWarmupManager.logMetric("reader_first_transform_ms", transformedAt - rawAt)
            ViewerWarmupManager.logMetric("reader_first_decode_total_ms", finishedAt - startedAt)
        }
        if (trace) {
            val finishedAt = SystemClock.elapsedRealtime()
            logNtkPagePerf(index, "decode_bytes", "boundsMs=${boundsAt - startedAt},rawMs=${rawAt - boundsAt},transformMs=${transformedAt - rawAt},totalMs=${finishedAt - startedAt},target=$targetWidth,width=${result.width},bytes=${bytes.size}")
        }
        return result
    }

    private fun ensureProofDrawableWidth(index: Int, bitmap: Bitmap, targetWidth: Int): Bitmap {
        if (bitmap.isRecycled || bitmap.width <= 0 || bitmap.height <= 0) return bitmap
        val viewWidth = viewerWidth.takeIf { it > 0 } ?: targetWidth
        val safeTargetWidth = max(1, minOf(max(targetWidth, ntkProofTargetWidth()), viewWidth))
        if (bitmap.width >= safeTargetWidth) return bitmap
        // The source pixels are already the full-quality asset. Canvas scaling preserves that
        // information; allocating a larger bitmap only duplicates pixels and creates GC churn.
        return bitmap
    }

    private fun BitmapFactory.Options.applyInitialGeneratedDecodeScale(sourceWidth: Int, targetWidth: Int) {
        if (sourceWidth <= 0 || targetWidth <= 0 || sourceWidth == targetWidth) return
        if (sourceWidth < targetWidth) {
            val delta = targetWidth - sourceWidth
            if (delta > max(8, targetWidth / 100)) return
        }
        inScaled = true
        inDensity = sourceWidth
        inTargetDensity = targetWidth
    }

    private fun initialGeneratedPreviewSampleSize(sourceWidth: Int, targetWidth: Int): Int {
        return sampleSize(sourceWidth, targetWidth)
    }

    private fun sampledBitmapWidth(sourceWidth: Int, sampleSize: Int): Int {
        val safeSample = max(1, sampleSize)
        return max(1, (sourceWidth + safeSample - 1) / safeSample)
    }

    private fun obtainInitialGeneratedDecodeInBitmap(
        sourceWidth: Int,
        sourceHeight: Int,
        sampleSize: Int,
        targetWidth: Int
    ): Bitmap? {
        return null
    }

    private fun decodeWithPooledBitmapFallback(
        options: BitmapFactory.Options,
        pooledBitmap: Bitmap?,
        decode: (BitmapFactory.Options) -> Bitmap?
    ): Bitmap? {
        return try {
            val decoded = decode(options)
            if (pooledBitmap != null && decoded == null) {
                initialGeneratedDecodeInBitmapDisabled.set(true)
                if (!pooledBitmap.isRecycled) releaseBitmapToPoolOrRecycle(pooledBitmap)
                options.inBitmap = null
                decode(options)
            } else {
                decoded.also {
                    if (pooledBitmap != null && it !== pooledBitmap && !pooledBitmap.isRecycled) {
                        releaseBitmapToPoolOrRecycle(pooledBitmap)
                    }
                }
            }
        } catch (_: IllegalArgumentException) {
            initialGeneratedDecodeInBitmapDisabled.set(true)
            if (pooledBitmap != null && !pooledBitmap.isRecycled) {
                releaseBitmapToPoolOrRecycle(pooledBitmap)
            }
            options.inBitmap = null
            decode(options)
        }
    }

    private fun shouldUseNtkInitialGeneratedDisplayDecode(index: Int, page: PageRef): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        val start = currentStartPage()
        if (index < start || index > start + NTK_INITIAL_DIRECT_DELIVERY_PAGES) return false
        val path = page.manga.ntkEpisodePath.orEmpty()
        return path.startsWith("/webtoon/", ignoreCase = true) ||
            path.startsWith("/manhwa/", ignoreCase = true)
    }

    private fun drawableResult(
        bitmap: Bitmap,
        splitForDraw: Boolean = true,
        forceSplitForDraw: Boolean = false,
        tileHeight: Int = DECODED_DRAW_TILE_HEIGHT
    ): PageDecodeResult {
        if (!splitForDraw || (!forceSplitForDraw && !shouldSplitDecodedBitmapForDraw(bitmap))) {
            return PageDecodeResult.Full(bitmap)
        }
        val tiles = ArrayList<ReaderTile>()
        val width = bitmap.width
        val height = bitmap.height
        val safeTileHeight = max(1, tileHeight)
        // Bitmap.createBitmap returns the immutable source itself for a full-bounds crop.  A
        // one-tile "split" would therefore put that same identity in the result and recycle it
        // below.  Split only when there are at least two distinct crop regions.
        if (height <= safeTileHeight) return PageDecodeResult.Full(bitmap)
        try {
            var top = 0
            while (top < height) {
                val bottom = minOf(height, top + safeTileHeight)
                val tileBitmap = Bitmap.createBitmap(bitmap, 0, top, width, bottom - top)
                tiles.add(ReaderTile(top, bottom, width, height, tileBitmap))
                top = bottom
            }
        } catch (_: Exception) {
            for (tile in tiles) {
                if (!tile.bitmap.isRecycled) tile.bitmap.recycle()
            }
            return PageDecodeResult.Full(bitmap)
        }
        if (!bitmap.isRecycled) bitmap.recycle()
        return PageDecodeResult.Tiles(width, height, width, tiles)
    }

    private fun shouldSplitDecodedPageForDraw(index: Int, page: PageRef, splitGenerated: Boolean): Boolean {
        if (isNaverWebtoonPageImageUrl(page.image.orEmpty())) {
            return index != currentStartPage()
        }
        return !isNtkGeneratedImageUrl(page.image.orEmpty()) || splitGenerated
    }

    private fun shouldSplitDecodedBitmapForDraw(bitmap: Bitmap): Boolean {
        if (bitmap.width <= 0 || bitmap.height <= 0) return false
        if (bitmap.height < DECODED_DRAW_TILE_MIN_HEIGHT) return false
        return bitmapBytes(bitmap) >= DECODED_DRAW_TILE_MIN_BYTES
    }

    private fun shouldSplitNtkGeneratedBitmapForDraw(index: Int, page: PageRef, bitmap: Bitmap): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (!firstBitmapLogged.get() && index == currentStartPage()) return false
        return shouldSplitDecodedBitmapForDraw(bitmap) || shouldSplitGeneratedBitmapForInteractiveDraw(bitmap)
    }

    private fun shouldSplitGeneratedBitmapForInteractiveDraw(bitmap: Bitmap): Boolean {
        if (bitmap.isRecycled || bitmap.width <= 0 || bitmap.height <= 0) return false
        if (bitmapBytes(bitmap) < NTK_GENERATED_DRAW_TILE_MIN_BYTES) return false
        val drawHeight = viewerWidth.toLong() * bitmap.height.toLong() / max(1, bitmap.width)
        val minDrawHeight = max(1, viewerHeight) * NTK_GENERATED_DRAW_TILE_MIN_VIEWPORT_PERMILLE / 1000
        return drawHeight >= minDrawHeight
    }

    private fun scaleInitialNtkGeneratedForDraw(
        index: Int,
        page: PageRef,
        bitmap: Bitmap,
        targetWidth: Int,
        recycleSource: Boolean = true
    ): Bitmap {
        if (!isNtkSource(page.manga, title)) return bitmap
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return bitmap
        if (bitmap.isRecycled || bitmap.width <= 0 || bitmap.height <= 0) return bitmap
        val requestedTargetWidth = max(1, targetWidth)
        val sourceWidth = bitmap.width
        val sourceHeight = bitmap.height
        if (sourceWidth < requestedTargetWidth) return bitmap
        val safeTargetWidth = if (sourceWidth < requestedTargetWidth) {
            minOf(requestedTargetWidth, max(sourceWidth, ntkProofTargetWidth()))
        } else {
            requestedTargetWidth
        }
        if (sourceWidth == safeTargetWidth) return bitmap
        if (sourceWidth < safeTargetWidth) {
            val scaledHeight = max(1, (sourceHeight.toLong() * safeTargetWidth / sourceWidth).toInt())
            return try {
                val scaled = Bitmap.createScaledBitmap(bitmap, safeTargetWidth, scaledHeight, true)
                if (recycleSource && scaled !== bitmap && !bitmap.isRecycled) {
                    releaseBitmapToPoolOrRecycle(bitmap)
                }
                logNtkPagePerf(
                    index,
                    "generated_upscale_for_draw",
                    "from=${sourceWidth}x${sourceHeight},to=${scaled.width}x${scaled.height},target=$safeTargetWidth,requested=$requestedTargetWidth"
                )
                scaled
            } catch (_: Throwable) {
                bitmap
            }
        }
        val scaledHeight = max(1, (sourceHeight.toLong() * safeTargetWidth / sourceWidth).toInt())
        return try {
            val scaled = Bitmap.createScaledBitmap(bitmap, safeTargetWidth, scaledHeight, true)
            if (recycleSource && scaled !== bitmap && !bitmap.isRecycled) {
                releaseBitmapToPoolOrRecycle(bitmap)
            }
            logNtkPagePerf(
                index,
                "generated_downscale_for_draw",
                "from=${sourceWidth}x${sourceHeight},to=${scaled.width}x${scaled.height},target=$safeTargetWidth"
            )
            scaled
        } catch (_: Throwable) {
            bitmap
        }
    }

    private fun shouldSkipInitialGeneratedBlankTrim(index: Int, page: PageRef): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        val start = currentStartPage()
        if (index !in start until (start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)) return false
        return !initialContinuousDrawableDelivered(start)
    }

    private fun shouldUseInitialGeneratedPreviewDecode(index: Int, page: PageRef): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        val start = currentStartPage()
        if (index !in start until (start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES)) return false
        if (initialContinuousDrawableDelivered(start)) return false
        return true
    }

    private fun shouldUseInteractiveGeneratedPreviewDecode(index: Int, page: PageRef): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (shouldUseInitialGeneratedPreviewDecode(index, page)) return true
        if (!isImmediateNtkGeneratedUx()) return false
        val start = currentStartPage()
        if (!firstBitmapLogged.get()) {
            return index in start until (start + NTK_GENERATED_INITIAL_CONTINUOUS_RUNWAY_PAGES)
        }
        val active = viewportBusy.get() ||
            ntkInitialInteractiveSettleRemainingMs() > 0L ||
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L ||
            readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS) > 0L
        if (!active) return false
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: start
        return index in max(0, anchor - NTK_INTERACTIVE_PROOF_BEHIND_PAGES)..(anchor + NTK_ACTIVE_VISIBLE_DIRECT_DECODE_AHEAD_PAGES)
    }

    private fun decodeTargetWidth(sourceWidth: Int, sourceHeight: Int, targetWidth: Int, allowSplit: Boolean): Int {
        val safeTarget = max(1, targetWidth)
        if (!autoCut || !allowSplit || !shouldAutoSplit(max(1, sourceWidth), max(1, sourceHeight))) return safeTarget
        return safeTarget * 2
    }

    private fun displayBounds(width: Int, height: Int, side: Int, allowSplit: Boolean): Rect {
        val safeWidth = max(1, width)
        val safeHeight = max(1, height)
        if (!autoCut || !allowSplit) return Rect(0, 0, safeWidth, safeHeight)
        if (shouldAutoSplit(safeWidth, safeHeight)) {
            val cropWidth = max(1, safeWidth / 2)
            return Rect(0, 0, cropWidth, safeHeight)
        }
        return if (side == PAGE_SIDE_FIRST) {
            Rect(0, 0, safeWidth, safeHeight)
        } else {
            Rect(0, 0, safeWidth, 1)
        }
    }

    private fun applyAutoSplit(bitmap: Bitmap, side: Int, allowSplit: Boolean): Bitmap {
        if (!autoCut || !allowSplit) return bitmap
        val decodedWidth = bitmap.width
        val decodedHeight = bitmap.height
        if (!shouldAutoSplit(decodedWidth, decodedHeight)) {
            if (side == PAGE_SIDE_FIRST) return bitmap
            val empty = Bitmap.createBitmap(max(1, decodedWidth), 1, displayConfig(bitmap))
            empty.eraseColor(Color.TRANSPARENT)
            if (!bitmap.isRecycled) bitmap.recycle()
            return empty
        }
        val cropWidth = max(1, decodedWidth / 2)
        val cropX = if (side == PAGE_SIDE_FIRST) {
            if (reverse) 0 else decodedWidth - cropWidth
        } else {
            if (reverse) decodedWidth - cropWidth else 0
        }
        val displayBitmap = Bitmap.createBitmap(cropWidth, decodedHeight, displayConfig(bitmap))
        Canvas(displayBitmap).drawBitmap(
            bitmap,
            Rect(cropX, 0, cropX + cropWidth, decodedHeight),
            Rect(0, 0, cropWidth, decodedHeight),
            null
        )
        if (!bitmap.isRecycled) bitmap.recycle()
        return displayBitmap
    }

    private fun deliverAutoSplitSiblingFromDecoded(index: Int, page: PageRef, decoded: Bitmap) {
        if (!autoCut || !page.allowAutoSplit || decoded.isRecycled) return
        val sibling = autoSplitSiblingPage(index, page) ?: return
        // Session lifetime tracking can outlive a pressure-retired Surface page. Only installed
        // pixels make the sibling redundant; otherwise this same source decode is the cheapest
        // and only lossless opportunity to repair both display halves atomically.
        if (hasDeliveredBitmap(sibling.first) &&
            listener.isPageDrawableInstalled(sibling.first)
        ) return
        if ((pendingDeliveryWidths[sibling.first] ?: 0) > 0) return
        val siblingBitmap = copyAutoSplitBitmap(decoded, sibling.second.side, sibling.second.allowAutoSplit)
            ?: return
        val trimmed = ViewerBitmapTrim.trimBlankVerticalEdges(siblingBitmap, true)
        postPageBounds(sibling.first, sibling.second, trimmed.width, trimmed.height)
        deliverPreparedBitmap(sibling.first, trimmed, true)
        ViewerWarmupManager.logMetric("reader_autosplit_sibling_delivered", sibling.first.toLong())
    }

    private fun autoSplitSiblingPage(index: Int, page: PageRef): Pair<Int, PageRef>? {
        val image = page.image ?: return null
        val siblingSide = if (page.side == PAGE_SIDE_FIRST) PAGE_SIDE_SECOND else PAGE_SIDE_FIRST
        return synchronized(pagesLock) {
            pages.withIndex().firstOrNull { entry ->
                entry.index != index &&
                    entry.value.image == image &&
                    entry.value.sourceIndex == page.sourceIndex &&
                    entry.value.side == siblingSide
            }?.let { it.index to it.value }
        }
    }

    private fun copyAutoSplitBitmap(bitmap: Bitmap, side: Int, allowSplit: Boolean): Bitmap? {
        if (!autoCut || !allowSplit || bitmap.isRecycled) return null
        val decodedWidth = bitmap.width
        val decodedHeight = bitmap.height
        if (!shouldAutoSplit(decodedWidth, decodedHeight)) {
            if (side != PAGE_SIDE_SECOND) return bitmap.copy(displayConfig(bitmap), false)
            return Bitmap.createBitmap(max(1, decodedWidth), 1, displayConfig(bitmap)).apply {
                eraseColor(Color.TRANSPARENT)
            }
        }
        val cropWidth = max(1, decodedWidth / 2)
        val cropX = if (side == PAGE_SIDE_FIRST) {
            if (reverse) 0 else decodedWidth - cropWidth
        } else {
            if (reverse) decodedWidth - cropWidth else 0
        }
        return Bitmap.createBitmap(cropWidth, decodedHeight, displayConfig(bitmap)).also { displayBitmap ->
            Canvas(displayBitmap).drawBitmap(
                bitmap,
                Rect(cropX, 0, cropX + cropWidth, decodedHeight),
                Rect(0, 0, cropWidth, decodedHeight),
                null
            )
        }
    }

    private fun displayConfig(bitmap: Bitmap): Bitmap.Config {
        return Bitmap.Config.ARGB_8888
    }

    private fun shouldAutoSplit(width: Int, height: Int): Boolean {
        if (width <= 0 || height <= 0) return false
        return width / height.toFloat() >= SPREAD_ASPECT_RATIO
    }

    private fun shouldAutoSplitImage(target: Manga, image: String, sourceIndex: Int): Boolean {
        if (!autoCut) return false
        val decisionKey = if (target.isOnline) {
            val path = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
            val canonical = ReaderPreparedStore.canonicalOriginalAssetIdentity(image)
            if (path.isNotBlank() && canonical.isNotBlank()) "$path|$sourceIndex|$canonical" else ""
        } else {
            ""
        }
        if (decisionKey.isNotEmpty()) {
            autoSplitDecisionByCanonicalAsset[decisionKey]?.let { return it }
        }
        return try {
            ReaderImageCache.strictSourceBounds(target.ntkEpisodePath, sourceIndex)?.let { bounds ->
                if (bounds.size >= 2) {
                    val split = shouldAutoSplit(bounds[0], bounds[1])
                    if (decisionKey.isNotEmpty()) {
                        autoSplitDecisionByCanonicalAsset.putIfAbsent(decisionKey, split)
                    }
                    return split
                }
            }
            val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
            if (target.isOnline) {
                val file = ReaderImageCache.cachedFile(appContext, target, image) ?: return false
                BitmapFactory.decodeFile(file.absolutePath, bounds)
            } else {
                decodeLocal(image, bounds)
            }
            if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return false
            val split = shouldAutoSplit(bounds.outWidth, bounds.outHeight)
            if (decisionKey.isNotEmpty()) {
                autoSplitDecisionByCanonicalAsset.putIfAbsent(decisionKey, split)
            }
            split
        } catch (e: Exception) {
            recordIfUnexpected(e)
            false
        }
    }

    private fun shouldDecodeTiles(index: Int, page: PageRef, file: File, bounds: BitmapFactory.Options): Boolean {
        if (page.manga.seed != 0) return false
        if (!file.isFile) return false
        val width = bounds.outWidth
        val height = bounds.outHeight
        if (width <= 0 || height <= 0) return false
        if (
            isNtkSource(page.manga, title) &&
            isNtkGeneratedImageUrl(page.image.orEmpty()) &&
            index == currentStartPage() &&
            !firstBitmapLogged.get()
        ) {
            return false
        }
        if (isNtkSource(page.manga, title) && isNtkGeneratedImageUrl(page.image.orEmpty())) {
            return height > NTK_GENERATED_DRAW_TILE_HEIGHT
        }
        val estimatedBytes = width.toLong() * height.toLong() * 2L
        return height / width.toFloat() >= TILE_PAGE_ASPECT_RATIO ||
            estimatedBytes >= TILE_PAGE_MIN_ESTIMATED_BYTES
    }

    private fun shouldDecodePageAsTiles(
        index: Int,
        page: PageRef,
        file: File,
        bounds: BitmapFactory.Options,
        proofDrawable: Boolean
    ): Boolean {
        if (strictExactColdRolling) {
            // Exact cold bodies have already been authority/digest checked. Preserve their
            // original sample-1 identity even before the inline Surface activation flag is set,
            // otherwise early full-episode decodes cannot enter the render-ready set.
            return file.isFile && bounds.outWidth > 0 && bounds.outHeight > 0
        }
        if (!proofDrawable && requiresAuthoritativeInlineTilePage(page)) {
            // The strict inline surface intentionally rejects whole Bitmap callbacks because
            // they carry no immutable original-tile provenance. Always produce sample-1 region
            // tiles for the current episode so a successful decode has an installable form.
            return file.isFile && bounds.outWidth > 0 && bounds.outHeight > 0
        }
        if (autoCut && !proofDrawable) return false
        if (proofDrawable &&
            isNtkSource(page.manga, title) &&
            isNtkGeneratedImageUrl(page.image.orEmpty()) &&
            isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)
        ) {
            return shouldDecodeGeneratedProofTiles(index, page, file, bounds)
        }
        return !proofDrawable && !autoCut && shouldDecodeTiles(index, page, file, bounds)
    }

    private fun shouldDecodeGeneratedProofTiles(
        index: Int,
        page: PageRef,
        file: File,
        bounds: BitmapFactory.Options
    ): Boolean {
        if (!file.isFile) return false
        val width = bounds.outWidth
        val height = bounds.outHeight
        if (width <= 0 || height <= 0) return false
        if (index == currentStartPage() && !firstBitmapLogged.get()) return false
        return height > NTK_GENERATED_DRAW_TILE_HEIGHT
    }

    private fun decodePageTiles(
        file: File,
        bounds: BitmapFactory.Options,
        targetWidth: Int,
        forceOriginal: Boolean = false,
        canonicalAsset: String = ""
    ): PageDecodeResult.Tiles {
        val sourceWidth = max(1, bounds.outWidth)
        val sourceHeight = max(1, bounds.outHeight)
        val sample = if (forceOriginal) {
            1
        } else {
            max(
                sampleSize(sourceWidth, targetWidth),
                sampleSizeForByteBudget(sourceWidth, sourceHeight, TILE_PAGE_MAX_BYTES)
            )
        }
        val sourceTileHeight = decodeTileSourceHeight(forceOriginal)
        val pendingTiles = ArrayList<PendingTile>()
        var removedSourceHeight = 0
        var success = false
        if (forceOriginal && hostExactNativeSurfaceStorageEnabled) {
            val hardwareTiles = runCatching {
                decodeStrictExactHardwareTiles(
                    file,
                    sourceWidth,
                    sourceHeight,
                    canonicalAsset,
                )
            }.getOrNull()
            if (hardwareTiles != null) return hardwareTiles
        }
        if (ReaderExactDecodeStoragePolicy.useSharedFullPageBitmap(
                forceOriginal,
                sourceWidth,
                sourceHeight,
            )
        ) {
            var decoded: Bitmap? = null
            try {
                val pageBitmap = decodeExactFullPageBitmap(file, sourceWidth, sourceHeight)
                decoded = pageBitmap
                check(pageBitmap.width == sourceWidth && pageBitmap.height == sourceHeight &&
                    pageBitmap.config == Bitmap.Config.ARGB_8888 && !pageBitmap.isMutable
                ) { "Original bitmap storage changed during decode" }
                var top = 0
                while (top < sourceHeight) {
                    val bottom = minOf(sourceHeight, top + sourceTileHeight)
                    pendingTiles.add(
                        PendingTile(top - removedSourceHeight, bottom - removedSourceHeight, pageBitmap)
                    )
                    top = bottom
                }
                success = true
            } finally {
                if (!success) decoded?.takeUnless(Bitmap::isRecycled)?.recycle()
            }
        } else {
            val decoder = BitmapRegionDecoder.newInstance(file.absolutePath, false)
                ?: throw java.io.IOException("Bitmap region decode failed")
            val rect = Rect()
            try {
                var top = 0
                while (top < sourceHeight) {
                    val bottom = minOf(sourceHeight, top + sourceTileHeight)
                    rect.set(0, top, sourceWidth, bottom)
                    val options = BitmapFactory.Options().apply {
                        inPreferredConfig = Bitmap.Config.ARGB_8888
                        inSampleSize = sample
                    }
                    val bitmap = decoder.decodeRegion(rect, options)
                        ?: throw java.io.IOException("Bitmap tile decode failed")
                    pendingTiles.add(
                        PendingTile(top - removedSourceHeight, bottom - removedSourceHeight, bitmap)
                    )
                    top = bottom
                }
                success = true
            } finally {
                if (!success) {
                    for (tile in pendingTiles) {
                        if (!tile.bitmap.isRecycled) tile.bitmap.recycle()
                    }
                }
                decoder.recycle()
            }
        }
        val decodedWidth = max(1, (sourceWidth + sample - 1) / sample)
        val pageHeight = max(1, sourceHeight - removedSourceHeight)
        val tiles = pendingTiles.map { tile ->
            val clampedTop = tile.sourceTop.coerceIn(0, pageHeight - 1)
            val clampedBottom = tile.sourceBottom.coerceIn(clampedTop + 1, pageHeight)
            ReaderTile(
                clampedTop,
                clampedBottom,
                sourceWidth,
                pageHeight,
                tile.bitmap
            )
        }
        val originalProof = if (forceOriginal) {
            ReaderPreparedStore.PreparedOriginalProof(
                canonicalAsset = ReaderPreparedStore.canonicalOriginalAssetIdentity(canonicalAsset),
                variant = ReaderPreparedStore.PreparedAssetVariant.ORIGINAL,
                originalWidth = sourceWidth,
                originalHeight = sourceHeight,
                inSampleSize = sample,
                postDecodeResized = false
            )
        } else {
            null
        }
        return PageDecodeResult.Tiles(sourceWidth, pageHeight, decodedWidth, tiles, originalProof)
    }

    /**
     * API 28's shared-memory allocator keeps the immutable sample-1 pixels out of ART's moving
     * heap. A long webtoon can legitimately retain hundreds of megabytes of exact decoded pixels;
     * putting those pixels in the managed heap made every later allocation trigger a full live-set
     * scan while downloads and eight decoders were still active. The ashmem-backed Bitmap remains
     * directly lockable by the native renderer and Canvas, so this changes storage only: source
     * dimensions, sRGB conversion and ARGB_8888 fidelity are identical to the legacy decode.
     */
    private fun decodeExactFullPageBitmap(
        file: File,
        sourceWidth: Int,
        sourceHeight: Int,
    ): Bitmap {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            val decoded = ImageDecoder.decodeBitmap(ImageDecoder.createSource(file)) {
                    decoder, _, _ ->
                decoder.allocator = ImageDecoder.ALLOCATOR_SHARED_MEMORY
                decoder.isMutableRequired = false
                decoder.memorySizePolicy = ImageDecoder.MEMORY_POLICY_DEFAULT
                decoder.setTargetSize(sourceWidth, sourceHeight)
                decoder.setTargetColorSpace(ColorSpace.get(ColorSpace.Named.SRGB))
            }
            if (decoded.width == sourceWidth && decoded.height == sourceHeight &&
                decoded.config == Bitmap.Config.ARGB_8888 && !decoded.isMutable
            ) return decoded
            if (!decoded.isRecycled) decoded.recycle()
            throw java.io.IOException("Shared-memory exact decode changed pixel storage")
        }
        return BitmapFactory.decodeFile(
            file.absolutePath,
            BitmapFactory.Options().apply {
                inPreferredConfig = Bitmap.Config.ARGB_8888
                inSampleSize = 1
                inScaled = false
                inMutable = false
            },
        ) ?: throw java.io.IOException("Bitmap full-page decode failed")
    }

    /** Exact memory-body counterpart of [decodePageTiles], with no bounds/file round trip. */
    private fun adoptPrivateStrictExactBitmap(
        bitmap: Bitmap,
        sourceWidth: Int,
        sourceHeight: Int,
        canonicalAsset: String,
    ): PageDecodeResult.Tiles {
        var success = false
        try {
            check(
                !bitmap.isRecycled && bitmap.width == sourceWidth &&
                    bitmap.height == sourceHeight && bitmap.config == Bitmap.Config.ARGB_8888 &&
                    !bitmap.isMutable
            ) { "Private exact bitmap identity changed before authority adoption" }
            val sourceTileHeight = decodeTileSourceHeight(forceOriginal = true)
            val tiles = ArrayList<ReaderTile>(
                (sourceHeight + sourceTileHeight - 1) / sourceTileHeight,
            )
            var top = 0
            while (top < sourceHeight) {
                val bottom = minOf(sourceHeight, top + sourceTileHeight)
                tiles += ReaderTile(top, bottom, sourceWidth, sourceHeight, bitmap)
                top = bottom
            }
            val proof = ReaderPreparedStore.PreparedOriginalProof(
                canonicalAsset = ReaderPreparedStore.canonicalOriginalAssetIdentity(canonicalAsset),
                variant = ReaderPreparedStore.PreparedAssetVariant.ORIGINAL,
                originalWidth = sourceWidth,
                originalHeight = sourceHeight,
                inSampleSize = 1,
                postDecodeResized = false,
            )
            success = true
            return PageDecodeResult.Tiles(
                sourceWidth,
                sourceHeight,
                sourceWidth,
                tiles,
                proof,
            )
        } finally {
            if (!success && !bitmap.isRecycled) bitmap.recycle()
        }
    }

    /**
     * Auto-cut is a user-requested display transform, so it cannot be published as an immutable
     * original tile proof. Keep the source bitmap exact until both display halves have been copied,
     * then hand the transformed pages to the ordinary drawable path.
     */
    private fun adoptPrivateStrictExactBitmapForPage(
        index: Int,
        page: PageRef,
        bitmap: Bitmap,
        sourceWidth: Int,
        sourceHeight: Int,
        canonicalAsset: String,
    ): PageDecodeResult {
        if (!shouldSplitPreparedBitmapForPage(autoCut, page.allowAutoSplit, sourceWidth, sourceHeight)) {
            return adoptPrivateStrictExactBitmap(bitmap, sourceWidth, sourceHeight, canonicalAsset)
        }
        check(
            !bitmap.isRecycled && bitmap.width == sourceWidth && bitmap.height == sourceHeight &&
                bitmap.config == Bitmap.Config.ARGB_8888 && !bitmap.isMutable
        ) { "Private exact bitmap identity changed before auto-cut" }
        deliverAutoSplitSiblingFromDecoded(index, page, bitmap)
        val displayBitmap = applyAutoSplit(bitmap, page.side, page.allowAutoSplit)
        postPageBounds(index, page, displayBitmap.width, displayBitmap.height)
        return PageDecodeResult.Full(displayBitmap)
    }

    /** Exact memory-body counterpart of [decodePageTiles], with no bounds/file round trip. */
    private fun decodeStrictExactPageBytes(
        index: Int,
        page: PageRef,
        bytes: ByteArray,
        sourceWidth: Int,
        sourceHeight: Int,
        canonicalAsset: String,
        parallelOversizedResidentTiles: Boolean = false,
        deferWhilePhysicalMotion: Boolean = false,
        deferWhilePhysicalInput: Boolean = false,
        bypassProtectedNumericSerialization: Boolean = false,
        allowTransientHostExactPoolOvercommit: Boolean = true,
        settledHostExactPoolOnly: Boolean = false,
        exactLaunchCompositorForwardWarmIntent: Boolean = false,
    ): PageDecodeResult {
        awaitHostLifecyclePixelDecodeAdmission()
        if (deferWhilePhysicalMotion) awaitStrictExactDecodeMotionAdmission()
        if (deferWhilePhysicalInput) awaitStrictExactDecodePhysicalInputAdmission()
        return withProtectedNumericDecodePermit(
            page,
            bypassSerialization = bypassProtectedNumericSerialization,
        ) {
        withStrictDecodeTelemetry(index, page, canonicalAsset) {
            if (sourceWidth <= 0 || sourceHeight <= 0 || bytes.size < 32) {
                throw java.io.IOException("Strict resident body metadata is invalid")
            }
            postStrictExactPageBounds(index, page, sourceWidth, sourceHeight)
            val splitSource = shouldSplitPreparedBitmapForPage(
                autoCut,
                page.allowAutoSplit,
                sourceWidth,
                sourceHeight,
            )
            if (hostExactNativeSurfaceStorageEnabled) {
                val displaySourceWidth = if (splitSource) max(1, sourceWidth / 2) else sourceWidth
                val displaySourceLeft = if (!splitSource) {
                    0
                } else if (page.side == PAGE_SIDE_FIRST) {
                    if (reverse) 0 else sourceWidth - displaySourceWidth
                } else {
                    if (reverse) sourceWidth - displaySourceWidth else 0
                }
                decodeStrictExactHardwareTiles(
                    bytes,
                    sourceWidth,
                    sourceHeight,
                    canonicalAsset,
                    deferWhilePhysicalMotion = deferWhilePhysicalMotion,
                    deferWhilePhysicalInput = deferWhilePhysicalInput,
                    allowTransientOvercommit = allowTransientHostExactPoolOvercommit,
                    settledPoolOnly = settledHostExactPoolOnly,
                    prioritizeMirrorPublication =
                        exactLaunchCompositorForwardWarmIntent ||
                            shouldPrioritizeStrictExactMirrorPublication(index, page),
                    mirrorPublicationRequiredNow = {
                        exactLaunchCompositorForwardWarmIntent ||
                            isStrictExactMirrorPublicationRequiredNow(index, page)
                    },
                    sourceLeft = displaySourceLeft,
                    sourceRegionWidth = displaySourceWidth,
                )?.let { hardwareTiles ->
                    return@withStrictDecodeTelemetry hardwareTiles
                }
            }
            if (!splitSource &&
                !ReaderExactDecodeStoragePolicy.useSharedFullPageBitmap(
                    forceOriginal = true,
                    sourceWidth = sourceWidth,
                    sourceHeight = sourceHeight,
                )
            ) {
                return@withStrictDecodeTelemetry if (parallelOversizedResidentTiles) {
                    decodeStrictExactResidentTilesParallel(
                        bytes,
                        sourceWidth,
                        sourceHeight,
                        canonicalAsset,
                    )
                } else {
                    decodeStrictExactResidentTiles(
                        bytes,
                        sourceWidth,
                        sourceHeight,
                        canonicalAsset,
                    )
                }
            }
            var decoded: Bitmap? = null
            var success = false
            try {
                val pageBitmap = decodeExactFullPageBitmap(bytes, sourceWidth, sourceHeight)
                decoded = pageBitmap
                check(pageBitmap.width == sourceWidth && pageBitmap.height == sourceHeight &&
                    pageBitmap.config == Bitmap.Config.ARGB_8888 && !pageBitmap.isMutable
                ) { "Resident original bitmap storage changed during decode" }
                if (shouldSplitPreparedBitmapForPage(
                        autoCut,
                        page.allowAutoSplit,
                        sourceWidth,
                        sourceHeight
                    )
                ) {
                    deliverAutoSplitSiblingFromDecoded(index, page, pageBitmap)
                    val displayBitmap = applyAutoSplit(pageBitmap, page.side, page.allowAutoSplit)
                    decoded = displayBitmap
                    postPageBounds(index, page, displayBitmap.width, displayBitmap.height)
                    success = true
                    return@withStrictDecodeTelemetry PageDecodeResult.Full(displayBitmap)
                }
                val sourceTileHeight = decodeTileSourceHeight(forceOriginal = true)
                val tiles = ArrayList<ReaderTile>(
                    (sourceHeight + sourceTileHeight - 1) / sourceTileHeight
                )
                var top = 0
                while (top < sourceHeight) {
                    val bottom = minOf(sourceHeight, top + sourceTileHeight)
                    tiles += ReaderTile(top, bottom, sourceWidth, sourceHeight, pageBitmap)
                    top = bottom
                }
                val originalProof = ReaderPreparedStore.PreparedOriginalProof(
                    canonicalAsset = ReaderPreparedStore.canonicalOriginalAssetIdentity(canonicalAsset),
                    variant = ReaderPreparedStore.PreparedAssetVariant.ORIGINAL,
                    originalWidth = sourceWidth,
                    originalHeight = sourceHeight,
                    inSampleSize = 1,
                    postDecodeResized = false
                )
                success = true
                PageDecodeResult.Tiles(
                    sourceWidth,
                    sourceHeight,
                    sourceWidth,
                    tiles,
                    originalProof
                )
            } finally {
                if (!success) decoded?.takeUnless(Bitmap::isRecycled)?.recycle()
            }
        }
    }
    }

    /**
     * Generation-bound disk bodies already carry verified dimensions. The host exact decoder can
     * consume that file directly, so reopening it with BitmapFactory.inJustDecodeBounds on every
     * runway/rehydration attempt only allocates decoder state and requests NativeAlloc GC. Keep
     * the ordinary decoder fallback for auto-cut and unsupported runtimes.
     */
    private fun decodeStrictExactPageFile(
        index: Int,
        page: PageRef,
        file: File,
        targetWidth: Int,
        sourceWidth: Int,
        sourceHeight: Int,
        canonicalAsset: String,
        proofDrawable: Boolean = false,
        deferWhilePhysicalMotion: Boolean = false,
        deferWhilePhysicalInput: Boolean = false,
        bypassProtectedNumericSerialization: Boolean = false,
        allowTransientHostExactPoolOvercommit: Boolean = true,
        settledHostExactPoolOnly: Boolean = false,
        exactLaunchCompositorForwardWarmIntent: Boolean = false,
    ): PageDecodeResult {
        awaitHostLifecyclePixelDecodeAdmission()
        if (deferWhilePhysicalMotion) awaitStrictExactDecodeMotionAdmission()
        if (deferWhilePhysicalInput) awaitStrictExactDecodePhysicalInputAdmission()
        return withProtectedNumericDecodePermit(
            page,
            bypassSerialization = bypassProtectedNumericSerialization,
        ) {
        withStrictDecodeTelemetry(index, page, canonicalAsset) {
            if (!file.isFile || file.length() < 32L || sourceWidth <= 0 || sourceHeight <= 0) {
                throw java.io.IOException("Strict resident file metadata is invalid")
            }
            postStrictExactPageBounds(index, page, sourceWidth, sourceHeight)
            val splitSource = shouldSplitPreparedBitmapForPage(
                autoCut,
                page.allowAutoSplit,
                sourceWidth,
                sourceHeight,
            )
            if (hostExactNativeSurfaceStorageEnabled) {
                val displaySourceWidth = if (splitSource) max(1, sourceWidth / 2) else sourceWidth
                val displaySourceLeft = if (!splitSource) {
                    0
                } else if (page.side == PAGE_SIDE_FIRST) {
                    if (reverse) 0 else sourceWidth - displaySourceWidth
                } else {
                    if (reverse) sourceWidth - displaySourceWidth else 0
                }
                decodeStrictExactHardwareTiles(
                    file,
                    sourceWidth,
                    sourceHeight,
                    canonicalAsset,
                    deferWhilePhysicalMotion = deferWhilePhysicalMotion,
                    deferWhilePhysicalInput = deferWhilePhysicalInput,
                    allowTransientOvercommit = allowTransientHostExactPoolOvercommit,
                    settledPoolOnly = settledHostExactPoolOnly,
                    prioritizeMirrorPublication =
                        exactLaunchCompositorForwardWarmIntent ||
                            shouldPrioritizeStrictExactMirrorPublication(index, page),
                    mirrorPublicationRequiredNow = {
                        exactLaunchCompositorForwardWarmIntent ||
                            isStrictExactMirrorPublicationRequiredNow(index, page)
                    },
                    sourceLeft = displaySourceLeft,
                    sourceRegionWidth = displaySourceWidth,
                )?.let { hardwareTiles ->
                    return@withStrictDecodeTelemetry hardwareTiles
                }
            }
            decodePageUnlocked(
                index,
                page,
                file,
                targetWidth,
                proofDrawable,
                canonicalAsset,
            )
        }
    }
    }

    private fun awaitStrictExactDecodeMotionAdmission() {
        if (cancelled.get() || Thread.currentThread().isInterrupted) {
            throw InterruptedException("Strict exact decode admission cancelled")
        }
        if (NtkReaderTransferPacer.isPhysicalMotionActive()) {
            throw NtkPhysicalMotionDecodeDeferredException()
        }
    }

    private fun awaitStrictExactDecodePhysicalInputAdmission() {
        if (cancelled.get() || Thread.currentThread().isInterrupted) {
            throw InterruptedException("Strict exact decode admission cancelled")
        }
        if (isHostExactOffscreenDecodeInputProtected()) {
            throw NtkPhysicalMotionDecodeDeferredException()
        }
    }

    /**
     * Physical-input fence for the host exact decoder, independent of generated-URL routing.
     * UiDevice and real touch flings have short gaps between gestures; treating each gap as idle
     * wakes the complete six-worker suffix underneath the next DOWN. A 750 ms quiet proof is longer
     * than those gaps but still leaves most of the existing all-ready runway for parallel drain.
     */
    private fun isHostExactOffscreenDecodeInputProtected(): Boolean =
        physicalTouchActive.get() ||
            physicalTouchQuietRemainingMs(HOST_EXACT_OFFSCREEN_DECODE_INPUT_QUIET_MS) > 0L

    /**
     * Redrives only exact identities whose native decode yielded to a newer physical gesture.
     * One coalesced main-loop check is enough for the whole backlog. While a fling is alive the
     * check remains cheap and infrequent; once pointer quiet is proven, the pages rejoin the
     * existing single-lane passive-fling gate in canonical order. They do not wait for a long
     * inertial fling to finish, and therefore cannot leave the complete-scene queue stranded.
     */
    private fun parkStrictExactMotionDeferredPage(index: Int, page: PageRef) {
        if (cancelled.get() || !isStrictExactIdentityValid(index, page)) return
        strictExactMotionDeferredPages[index] = page
        scheduleStrictExactMotionDeferredRetry()
    }

    private fun scheduleStrictExactMotionDeferredRetry() {
        if (cancelled.get() || strictExactMotionDeferredPages.isEmpty() ||
            !strictExactMotionDeferredRetryPosted.compareAndSet(false, true)
        ) return
        val pointerQuietMs = physicalTouchQuietRemainingMs(
            HOST_EXACT_OFFSCREEN_DECODE_INPUT_QUIET_MS,
        )
        val delayMs = if (pointerQuietMs > 0L) {
            maxOf(pointerQuietMs, HOST_EXACT_MOTION_DEFERRED_RECHECK_MS)
        } else {
            HOST_EXACT_MOTION_DEFERRED_IDLE_RECHECK_MS
        }
        if (!main.postDelayed(strictExactMotionDeferredRetryRunnable, delayMs)) {
            strictExactMotionDeferredRetryPosted.set(false)
        }
    }

    private fun drainStrictExactMotionDeferredPages() {
        strictExactMotionDeferredRetryPosted.set(false)
        if (cancelled.get()) {
            strictExactMotionDeferredPages.clear()
            return
        }
        if (isHostExactOffscreenDecodeInputProtected()) {
            scheduleStrictExactMotionDeferredRetry()
            return
        }
        val admission = strictRollingAdmission.get()
        if (admission == null) {
            strictExactMotionDeferredPages.clear()
            return
        }
        strictExactMotionDeferredPages.entries
            .sortedBy { (_, page) -> page.sourceIndex }
            .forEach { (fallbackIndex, page) ->
                if (!strictExactMotionDeferredPages.remove(fallbackIndex, page)) return@forEach
                val index = currentPageIndex(page, fallbackIndex)
                if (index >= 0 && admission.admitsSource(page.sourceIndex) &&
                    isStrictExactIdentityValid(index, page)
                ) {
                    requestStrictExactSourcePage(
                        index,
                        anchor = false,
                        generation = admission.epoch.toInt(),
                        overlap = false,
                    )
                }
            }
        if (strictExactMotionDeferredPages.isNotEmpty()) {
            scheduleStrictExactMotionDeferredRetry()
        }
    }

    /**
     * Decodes exact source rows into reusable host-emulator HardwareBuffers. The Bitmap wrapper is
     * a fresh immutable identity for every decode; only the backing slot is reused, and only after
     * Session/Surface/JNI retirement reaches [HostExactHardwareTilePool.retire].
     */
    private fun decodeStrictExactHardwareTiles(
        bytes: ByteArray,
        sourceWidth: Int,
        sourceHeight: Int,
        canonicalAsset: String,
        deferWhilePhysicalMotion: Boolean = false,
        deferWhilePhysicalInput: Boolean = false,
        allowTransientOvercommit: Boolean = true,
        settledPoolOnly: Boolean = false,
        prioritizeMirrorPublication: Boolean = false,
        mirrorPublicationRequiredNow: (() -> Boolean)? = null,
        sourceLeft: Int = 0,
        sourceRegionWidth: Int = sourceWidth,
    ): PageDecodeResult.Tiles? {
        if (!hostExactNativeSurfaceStorageEnabled) return null
        val sourceTileHeight = decodeTileSourceHeight(forceOriginal = true)
        val decodedBitmaps = HostExactHardwareTilePool.decodePage(
            encoded = bytes,
            sourceWidth = sourceWidth,
            sourceHeight = sourceHeight,
            tileCapacityHeight = sourceTileHeight,
            deferWhilePhysicalMotion = deferWhilePhysicalMotion,
            decodeAdmission = if (deferWhilePhysicalInput) {
                ::awaitStrictExactDecodePhysicalInputAdmission
            } else {
                null
            },
            allowTransientOvercommit = allowTransientOvercommit,
            settledPoolOnly = settledPoolOnly,
            prioritizeMirrorPublication = prioritizeMirrorPublication,
            mirrorPublicationRequiredNow = mirrorPublicationRequiredNow,
            sourceLeft = sourceLeft,
            sourceRegionWidth = sourceRegionWidth,
        ) ?: return null
        return buildStrictExactHardwareTiles(
            decodedBitmaps,
            sourceRegionWidth,
            sourceHeight,
            sourceTileHeight,
            canonicalAsset,
            proofOriginalWidth = sourceWidth,
            proofOriginalHeight = sourceHeight,
            sourceCropLeft = sourceLeft,
        )
    }

    /** Disk-backed exact bodies stay disk-backed through decoder construction. */
    private fun decodeStrictExactHardwareTiles(
        file: File,
        sourceWidth: Int,
        sourceHeight: Int,
        canonicalAsset: String,
        deferWhilePhysicalMotion: Boolean = false,
        deferWhilePhysicalInput: Boolean = false,
        allowTransientOvercommit: Boolean = true,
        settledPoolOnly: Boolean = false,
        prioritizeMirrorPublication: Boolean = false,
        mirrorPublicationRequiredNow: (() -> Boolean)? = null,
        sourceLeft: Int = 0,
        sourceRegionWidth: Int = sourceWidth,
    ): PageDecodeResult.Tiles? {
        if (!hostExactNativeSurfaceStorageEnabled) return null
        val sourceTileHeight = decodeTileSourceHeight(forceOriginal = true)
        val decodedBitmaps = HostExactHardwareTilePool.decodePage(
            encodedFile = file,
            sourceWidth = sourceWidth,
            sourceHeight = sourceHeight,
            tileCapacityHeight = sourceTileHeight,
            deferWhilePhysicalMotion = deferWhilePhysicalMotion,
            decodeAdmission = if (deferWhilePhysicalInput) {
                ::awaitStrictExactDecodePhysicalInputAdmission
            } else {
                null
            },
            allowTransientOvercommit = allowTransientOvercommit,
            settledPoolOnly = settledPoolOnly,
            prioritizeMirrorPublication = prioritizeMirrorPublication,
            mirrorPublicationRequiredNow = mirrorPublicationRequiredNow,
            sourceLeft = sourceLeft,
            sourceRegionWidth = sourceRegionWidth,
        ) ?: return null
        return buildStrictExactHardwareTiles(
            decodedBitmaps,
            sourceRegionWidth,
            sourceHeight,
            sourceTileHeight,
            canonicalAsset,
            proofOriginalWidth = sourceWidth,
            proofOriginalHeight = sourceHeight,
            sourceCropLeft = sourceLeft,
        )
    }

    private fun buildStrictExactHardwareTiles(
        decodedBitmaps: List<Bitmap>,
        sourceWidth: Int,
        sourceHeight: Int,
        sourceTileHeight: Int,
        canonicalAsset: String,
        proofOriginalWidth: Int = sourceWidth,
        proofOriginalHeight: Int = sourceHeight,
        sourceCropLeft: Int = 0,
    ): PageDecodeResult.Tiles? {
        val tiles = ArrayList<ReaderTile>(
            (sourceHeight + sourceTileHeight - 1) / sourceTileHeight,
        )
        var success = false
        try {
            var top = 0
            var tileIndex = 0
            while (top < sourceHeight) {
                if (cancelled.get() || Thread.currentThread().isInterrupted) {
                    throw InterruptedException("Host exact hardware tile decode cancelled")
                }
                val bottom = minOf(sourceHeight, top + sourceTileHeight)
                val bitmap = decodedBitmaps.getOrNull(tileIndex++) ?: return null
                check(bitmap.hasImmutableExactPixelConfig()) {
                    "Host exact hardware tile lost immutable storage"
                }
                val tile = ReaderTile(top, bottom, sourceWidth, sourceHeight, bitmap)
                check(tile.hasExactSourcePixelStorage()) {
                    "Host exact hardware tile changed logical source storage"
                }
                tiles += tile
                top = bottom
            }
            if (tileIndex != decodedBitmaps.size) return null
            val proof = ReaderPreparedStore.PreparedOriginalProof(
                canonicalAsset = ReaderPreparedStore.canonicalOriginalAssetIdentity(canonicalAsset),
                variant = ReaderPreparedStore.PreparedAssetVariant.ORIGINAL,
                originalWidth = proofOriginalWidth,
                originalHeight = proofOriginalHeight,
                inSampleSize = 1,
                postDecodeResized = false,
                sourceCropLeft = sourceCropLeft,
                sourceCropTop = 0,
                sourceCropWidth = if (sourceWidth != proofOriginalWidth || sourceCropLeft != 0) {
                    sourceWidth
                } else {
                    0
                },
                sourceCropHeight = if (sourceHeight != proofOriginalHeight) sourceHeight else 0,
            )
            success = true
            return PageDecodeResult.Tiles(
                sourceWidth,
                sourceHeight,
                sourceWidth,
                tiles,
                proof,
            )
        } finally {
            if (!success) {
                val pooled = HostExactHardwareTilePool.retireAll(decodedBitmaps)
                for (bitmap in decodedBitmaps) {
                    if (bitmap !in pooled && !bitmap.isRecycled) bitmap.recycle()
                }
            }
        }
    }

    /** Decode the exclusive exact anchor's immutable row regions on three host cores. */
    @Suppress("DEPRECATION")
    private fun decodeStrictExactResidentTilesParallel(
        bytes: ByteArray,
        sourceWidth: Int,
        sourceHeight: Int,
        canonicalAsset: String,
    ): PageDecodeResult.Tiles {
        val sourceTileHeight = decodeTileSourceHeight(forceOriginal = true)
        val tileCount = (sourceHeight + sourceTileHeight - 1) / sourceTileHeight
        val slots = arrayOfNulls<ReaderTile>(tileCount)
        val slotLock = Any()
        val abandoned = AtomicBoolean(false)
        fun decodePartition(partition: Int) {
            val decoder = BitmapRegionDecoder.newInstance(bytes, 0, bytes.size, false)
                ?: throw java.io.IOException("Resident anchor region decoder failed")
            try {
                val rect = Rect()
                var tileIndex = partition
                while (tileIndex < tileCount) {
                    if (abandoned.get() || cancelled.get() ||
                        Thread.currentThread().isInterrupted
                    ) {
                        throw InterruptedException("Resident anchor tile decode cancelled")
                    }
                    val top = tileIndex * sourceTileHeight
                    val bottom = minOf(sourceHeight, top + sourceTileHeight)
                    rect.set(0, top, sourceWidth, bottom)
                    val bitmap = decoder.decodeRegion(
                        rect,
                        BitmapFactory.Options().apply {
                            inPreferredConfig = Bitmap.Config.ARGB_8888
                            inSampleSize = 1
                            inScaled = false
                            inMutable = false
                        },
                    ) ?: throw java.io.IOException("Resident anchor tile decode failed")
                    check(
                        bitmap.width == sourceWidth && bitmap.height == bottom - top &&
                            bitmap.config == Bitmap.Config.ARGB_8888 && !bitmap.isMutable
                    ) { "Resident anchor tile storage changed during parallel decode" }
                    synchronized(slotLock) {
                        if (abandoned.get() || cancelled.get() ||
                            Thread.currentThread().isInterrupted
                        ) {
                            bitmap.recycle()
                            throw InterruptedException("Resident anchor tile decode abandoned")
                        }
                        slots[tileIndex] = ReaderTile(
                            top,
                            bottom,
                            sourceWidth,
                            sourceHeight,
                            bitmap,
                        )
                    }
                    tileIndex += STRICT_EXACT_ANCHOR_TILE_DECODE_PARALLELISM
                }
            } finally {
                decoder.recycle()
            }
        }

        val helpers = (0 until STRICT_EXACT_ANCHOR_TILE_DECODE_HELPERS).map { partition ->
            FutureTask { decodePartition(partition) }
        }
        var failure: Throwable? = null
        try {
            helpers.forEach(strictExactAnchorTileDecode::execute)
            runCatching {
                decodePartition(STRICT_EXACT_ANCHOR_TILE_DECODE_HELPERS)
            }.exceptionOrNull()?.let { failure = it }
            helpers.forEach { task ->
                try {
                    task.get()
                } catch (wrapped: ExecutionException) {
                    if (failure == null) {
                        failure = wrapped.cause ?: wrapped
                        abandoned.set(true)
                    }
                }
            }
            failure?.let { cause ->
                if (cause is Exception) throw cause
                throw java.io.IOException("Parallel resident anchor decode failed", cause)
            }
            val tiles = slots.mapIndexed { index, tile ->
                tile ?: throw java.io.IOException("Resident anchor tile $index was not decoded")
            }
            val proof = ReaderPreparedStore.PreparedOriginalProof(
                canonicalAsset = ReaderPreparedStore.canonicalOriginalAssetIdentity(canonicalAsset),
                variant = ReaderPreparedStore.PreparedAssetVariant.ORIGINAL,
                originalWidth = sourceWidth,
                originalHeight = sourceHeight,
                inSampleSize = 1,
                postDecodeResized = false,
            )
            return PageDecodeResult.Tiles(
                sourceWidth,
                sourceHeight,
                sourceWidth,
                tiles,
                proof,
            )
        } catch (cause: Throwable) {
            synchronized(slotLock) {
                abandoned.set(true)
                slots.filterNotNull().forEach { tile ->
                    if (!tile.bitmap.isRecycled) tile.bitmap.recycle()
                }
            }
            helpers.forEach { it.cancel(true) }
            throw cause
        }
    }

    /** Decode oversized resident originals into Canvas-safe sample-1 source-row resources. */
    @Suppress("DEPRECATION")
    private fun decodeStrictExactResidentTiles(
        bytes: ByteArray,
        sourceWidth: Int,
        sourceHeight: Int,
        canonicalAsset: String,
    ): PageDecodeResult.Tiles {
        val decoder = BitmapRegionDecoder.newInstance(bytes, 0, bytes.size, false)
            ?: throw java.io.IOException("Resident bitmap region decode failed")
        val sourceTileHeight = decodeTileSourceHeight(forceOriginal = true)
        val tiles = ArrayList<ReaderTile>(
            (sourceHeight + sourceTileHeight - 1) / sourceTileHeight,
        )
        var success = false
        try {
            val rect = Rect()
            var top = 0
            while (top < sourceHeight) {
                val bottom = minOf(sourceHeight, top + sourceTileHeight)
                rect.set(0, top, sourceWidth, bottom)
                val bitmap = decoder.decodeRegion(
                    rect,
                    BitmapFactory.Options().apply {
                        inPreferredConfig = Bitmap.Config.ARGB_8888
                        inSampleSize = 1
                        inScaled = false
                        inMutable = false
                    },
                ) ?: throw java.io.IOException("Resident bitmap tile decode failed")
                check(
                    bitmap.width == sourceWidth && bitmap.height == bottom - top &&
                        bitmap.config == Bitmap.Config.ARGB_8888 && !bitmap.isMutable
                ) { "Resident original tile storage changed during decode" }
                tiles += ReaderTile(top, bottom, sourceWidth, sourceHeight, bitmap)
                top = bottom
            }
            val proof = ReaderPreparedStore.PreparedOriginalProof(
                canonicalAsset = ReaderPreparedStore.canonicalOriginalAssetIdentity(canonicalAsset),
                variant = ReaderPreparedStore.PreparedAssetVariant.ORIGINAL,
                originalWidth = sourceWidth,
                originalHeight = sourceHeight,
                inSampleSize = 1,
                postDecodeResized = false,
            )
            success = true
            return PageDecodeResult.Tiles(
                sourceWidth,
                sourceHeight,
                sourceWidth,
                tiles,
                proof,
            )
        } finally {
            if (!success) {
                tiles.forEach { tile ->
                    if (!tile.bitmap.isRecycled) tile.bitmap.recycle()
                }
            }
            decoder.recycle()
        }
    }

    private fun decodeExactFullPageBitmap(
        bytes: ByteArray,
        sourceWidth: Int,
        sourceHeight: Int
    ): Bitmap {
        // gfxstream reports each immutable BitmapFactory pixel allocation to ART's native-
        // allocation pressure tracker. A normal 12-16 page chapter then requests a concurrent
        // compacting GC for almost every page while the user is physically scrolling. Keep exact
        // dimensions/config/immutability, but place host-emulator pixels in shared memory just as
        // the file-backed exact decoder already does. Physical devices retain BitmapFactory's
        // lower setup overhead.
        if (hostGpuEmulatorRuntime && Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            val decoded = ImageDecoder.decodeBitmap(
                ImageDecoder.createSource(ByteBuffer.wrap(bytes)),
            ) { decoder, _, _ ->
                decoder.allocator = ImageDecoder.ALLOCATOR_SHARED_MEMORY
                decoder.isMutableRequired = false
                decoder.memorySizePolicy = ImageDecoder.MEMORY_POLICY_DEFAULT
                decoder.setTargetSize(sourceWidth, sourceHeight)
                decoder.setTargetColorSpace(ColorSpace.get(ColorSpace.Named.SRGB))
            }
            if (decoded.width == sourceWidth && decoded.height == sourceHeight &&
                decoded.config == Bitmap.Config.ARGB_8888 && !decoded.isMutable
            ) return decoded
            if (!decoded.isRecycled) decoded.recycle()
            throw java.io.IOException("Shared-memory resident exact decode changed pixel storage")
        }
        // BitmapFactory decodes the resident compressed body directly into the renderer's final
        // immutable software bitmap. ImageDecoder's SHARED_MEMORY allocator first builds and maps
        // an ashmem-backed image for every page; on a cold 100+ page episode that setup dominated
        // the decode tail even though the renderer never shares the bitmap across processes.
        // These options preserve the exact sample-1 dimensions, ARGB_8888 storage and sRGB output.
        val options = BitmapFactory.Options().apply {
            inPreferredConfig = Bitmap.Config.ARGB_8888
            inSampleSize = 1
            inScaled = false
            inMutable = false
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                inPreferredColorSpace = ColorSpace.get(ColorSpace.Named.SRGB)
            }
        }
        val decoded = BitmapFactory.decodeByteArray(
            bytes,
            0,
            bytes.size,
            options
        ) ?: throw java.io.IOException("Resident bitmap full-page decode failed")
        if (decoded.width == sourceWidth && decoded.height == sourceHeight &&
            decoded.config == Bitmap.Config.ARGB_8888 && !decoded.isMutable
        ) return decoded
        if (!decoded.isRecycled) decoded.recycle()
        throw java.io.IOException("Resident exact decode changed pixel storage")
    }

    private fun postPageBounds(index: Int, page: PageRef, width: Int, height: Int) {
        if (width <= 0 || height <= 0) return
        val currentIndex = currentPageIndex(page, index)
        if (currentIndex < 0) return
        sourceWidths[currentIndex] = width
        main.post {
            val latestIndex = currentPageIndex(page, currentIndex)
            if (!cancelled.get() && latestIndex >= 0) {
                listener.onPageBoundsReady(latestIndex, width, height)
            }
        }
    }

    private fun achievableWidth(index: Int, requestedWidth: Int): Int {
        val sourceWidth = sourceWidths[index] ?: return requestedWidth
        val decodeCeiling = achievableWidths[index] ?: Int.MAX_VALUE
        // A decoded page cannot contain more detail than the immutable source asset. The old
        // generated-image exception treated a 764px source as if a later 1080px decode were
        // achievable, causing redundant decode/upgrade work and suppressing an already
        // full-quality rolling drawable while it was entering the viewport.
        val sourceCeiling = max(1, sourceWidth)
        return minOf(requestedWidth, sourceCeiling, max(1, decodeCeiling))
    }

    private fun pageRef(index: Int): PageRef? = synchronized(pagesLock) {
        pages.getOrNull(index)
    }

    private fun currentPageIndex(page: PageRef, fallback: Int): Int = synchronized(pagesLock) {
        pageIndexLocked(page, fallback)
    }

    private fun currentPageIndexForDelivery(page: PageRef, fallback: Int): Int = synchronized(pagesLock) {
        val strict = pageIndexLocked(page, fallback)
        if (strict >= 0) return@synchronized strict
        if (fallback in pages.indices && equivalentPageRefForDelivery(page, pages[fallback])) {
            return@synchronized fallback
        }
        pages.indexOfFirst { equivalentPageRefForDelivery(page, it) }
    }

    private fun pageIndexLocked(page: PageRef, fallback: Int): Int {
        val known = page.pageIndex
        if (known in pages.indices && pages[known] === page) return known
        if (fallback in pages.indices && pages[fallback] === page) return fallback
        return pages.indexOfFirst { it === page }
    }

    /** Identity lookup over one immutable publication, safe for input/main hot-path readers. */
    private fun pageIndexInPublishedSnapshot(
        pageIndex: Array<PageRef>,
        page: PageRef,
        fallback: Int,
    ): Int {
        val known = page.pageIndex
        if (known in pageIndex.indices && pageIndex[known] === page) return known
        if (fallback in pageIndex.indices && pageIndex[fallback] === page) return fallback
        return pageIndex.indexOfFirst { candidate -> candidate === page }
    }

    private fun pageIndexForDeliveryLocked(delivery: Delivery, fallback: Int): Int {
        val strict = pageIndexLocked(delivery.page, fallback)
        if (strict >= 0) return strict
        if (fallback in pages.indices && equivalentPageRefForDelivery(delivery.page, pages[fallback])) {
            return fallback
        }
        return pages.indexOfFirst { equivalentPageRefForDelivery(delivery.page, it) }
    }

    private fun equivalentPageRefForDelivery(a: PageRef, b: PageRef): Boolean {
        if (a.transitionTitle != null || b.transitionTitle != null) return false
        if (a.sourceIndex != b.sourceIndex || a.side != b.side) return false
        val firstImage = a.image
        val secondImage = b.image
        if (!firstImage.isNullOrBlank() && firstImage == secondImage) return true
        val first = a.manga
        val second = b.manga
        if (first === second) return true
        return first.id == second.id &&
            first.baseMode == second.baseMode &&
            first.titleId == second.titleId &&
            (first.ntkEpisodePath ?: "") == (second.ntkEpisodePath ?: "")
    }

    private fun deliveryAtCurrentIndex(delivery: Delivery): Delivery? {
        val currentIndex = synchronized(pagesLock) {
            pageIndexForDeliveryLocked(delivery, delivery.index)
        }
        if (currentIndex < 0) return null
        if (currentIndex != delivery.index) {
            Log.d(
                TAG,
                "reader_delivery_index_recovered page=${delivery.index},current=$currentIndex," +
                    "source=${delivery.page.sourceIndex},side=${delivery.page.side}"
            )
        }
        val current = if (currentIndex == delivery.index) delivery else delivery.copy(index = currentIndex)
        val currentPage = synchronized(pagesLock) { pages.getOrNull(currentIndex) }
        return if (!current.proofDrawable &&
            strictInlineProofDeliveryIntents.contains(currentIndex) &&
            requiresAuthoritativeInlineTileAck(current) &&
            currentPage != null &&
            isCanonicalOriginalTileResult(current.result, currentPage.image)
        ) {
            current.copy(proofDrawable = true)
        } else {
            current
        }
    }

    fun pageInfo(index: Int): PageInfo? {
        val page = publishedPageIndex.get().getOrNull(index) ?: return null
        val transition = page.transitionTitle != null
        return PageInfo(
            manga = page.manga,
            title = page.transitionTitle ?: displayEpisodeTitle(page.manga),
            localPage = if (transition) 0 else max(1, page.localPage),
            totalPages = displayTotalPages(page),
            sourcePageIndex = sourcePageIndex(page),
            side = page.side,
            layoutReady = transition || sourceWidths.containsKey(index) || decodedWidths.containsKey(index),
            transitionCard = transition
        )
    }

    /**
     * Coalesces Activity page changes onto the session control lane. Continuous NTK reading keeps
     * the active episode and its forward runway, but retires already consumed episodes so native
     * pixel storage and RenderNodes cannot grow for the lifetime of the Activity.
     */
    @JvmOverloads
    fun noteForwardReadingPosition(anchor: Int, surfaceMotionActive: Boolean = false) {
        if (anchor < 0 || reverse || cancelled.get() || !isNtkSource(manga, title)) return
        // Publish the observation revision before waiting for pagesLock.  A history-prune control
        // turn that already owns the lock must then fail its final revision check instead of
        // deleting pages underneath this newer physical viewport callback.
        val observationRevision = forwardReadingObservationRevision.incrementAndGet()
        if (strictExactDirectWifiRollingPixelResidency.get()) {
            // This callback arrives on main before its coalesced WindowEvent reaches the control
            // mailbox. Publish the Surface's native drag/fling state immediately so forward-only
            // history compaction cannot rebase page coordinates underneath a real fling. Keep an
            // explicit level too: a tall image can retain one global anchor for longer than the
            // quiet window while OverScroller is still producing pixels.
            directWifiForwardSurfaceMotionActive.set(surfaceMotionActive)
            directWifiForwardSurfaceMotionAtMs.set(SystemClock.uptimeMillis())
        }
        latestReportedReadingPage.set(publishedPageIndex.get().getOrNull(anchor))
        latestReportedReadingPageRevision.set(observationRevision)
        forwardReadingPosition.set(anchor)
        scheduleForwardReadingDrain()
    }

    /**
     * Revalidates the physical boundary after an asynchronous episode-list/manifest fetch.
     *
     * A p4 request may still be resolving while p5/p6 are published below it. The rolling window
     * immediately prefetches those new indexes, so [currentViewportAnchor] can already equal p6
     * even though the first visible/reading page is still p3. Only the Activity's identity-bearing
     * progress PageRef may authorize the next-next structure in that race.
     */
    private fun shouldRejectForwardAppendCompletionAfterSourceGrowth(
        requestedPage: PageRef?,
        source: Manga,
        direction: Int,
    ): Boolean {
        if (direction <= 0 || requestedPage == null || !isImmediateNtkGeneratedUx()) return false
        return synchronized(pagesLock) {
            val requestedIndex = pageIndexLocked(requestedPage, requestedPage.pageIndex)
            if (requestedIndex < 0) return@synchronized true
            var sourceTail = requestedIndex
            for (index in requestedIndex + 1 until pages.size) {
                val page = pages[index]
                if (page.transitionTitle == null &&
                    Manga.sameEpisodeIdentity(page.manga, source)
                ) {
                    sourceTail = index
                }
            }
            if (sourceTail <= requestedIndex) return@synchronized false
            val readingPage = latestReportedReadingPage.get()
            val readingIndex = if (readingPage == null) {
                -1
            } else {
                pageIndexLocked(readingPage, readingPage.pageIndex)
            }
            NtkAdjacentAdmissionPolicy.shouldRejectStaleForwardTail(
                direction = direction,
                requestedAnchor = requestedIndex,
                normalizedAnchor = sourceTail,
                viewportAnchor = readingIndex,
            )
        }
    }

    /** Releases the native-motion level only after ReaderSurfaceView closes its real fling. */
    fun noteForwardSurfaceMotionEnded() {
        if (!strictExactDirectWifiRollingPixelResidency.get()) return
        directWifiForwardSurfaceMotionActive.set(false)
        directWifiForwardSurfaceMotionAtMs.set(SystemClock.uptimeMillis())
        // This callback is emitted only after ReaderSurfaceView closes the real pointer/fling
        // interval. The latest-value window mailbox can legitimately retain its preceding busy
        // sample because no further pixel movement exists to publish another WindowEvent. Make
        // that same identity-bound viewport idle, then replay it once so the rolling ring may
        // restore one nearest missing forward page before the next gesture.
        while (true) {
            val reported = latestReportedWindow.get() ?: break
            if (!reported.busy) break
            if (latestReportedWindow.compareAndSet(reported, reported.copy(busy = false))) break
        }
        requestRetainedWindowAfterStructureChange()
    }

    /**
     * Starts no target image work. Once every still-unread current webtoon body has reached the
     * exact resident descriptor boundary, this host-emulator-only path lets the already persisted
     * next identity overlap its fresh document/challenge with the finite current decode tail. The
     * coordinator's separate full-drawable gate still blocks the target API, source and pixels.
     */
    private fun maybeStartForwardAdjacentControlAfterCurrentBodiesResident(
        launchSeal: StrictExactLaunchSeal,
    ) {
        if (reverse || cancelled.get() || !hostGpuEmulatorRuntime || strictForwardSourceFloor <= 0 ||
            !launchSeal.normalizedEpisodePath.startsWith("/webtoon/") ||
            !isDirectWifiStrictAdjacentTransportActive() ||
            !isStrictExactCurrentForegroundEpisode() ||
            forwardAdjacentControlAfterBodiesResidentStarted.get() ||
            !(strictForwardSourceFloor until launchSeal.pageCount).all(
                strictExactBodyDescriptors::containsKey,
            )
        ) return
        val source = synchronized(pagesLock) {
            pages.firstOrNull { page ->
                page.transitionTitle == null &&
                    launchSeal.matchesEpisodePath(page.manga.ntkEpisodePath)
            }?.manga
        } ?: return
        val currentTitle = title ?: source.title ?: manga.title ?: return
        val target = persistedForwardAdjacentControlCandidate(source, currentTitle) ?: return
        if (!forwardAdjacentControlAfterBodiesResidentStarted.compareAndSet(false, true)) return
        try {
            initialAdjacentRunwayNetwork.execute {
                if (cancelled.get() || !isDirectWifiStrictAdjacentTransportActive() ||
                    !isStrictExactCurrentForegroundEpisode()
                ) {
                    forwardAdjacentControlAfterBodiesResidentStarted.set(false)
                    return@execute
                }
                val selectedTargetPath = startForwardAdjacentExactDiscoveryAtCompletion(
                    source,
                    target,
                    persistedExactAdjacentAuthority = true,
                    onResolvedForwardPath = null,
                    controlOnly = true,
                ) ?: return@execute
                releaseClaimedForwardAdjacentControlAfterBodiesResident(
                    launchSeal.normalizedEpisodePath,
                    selectedTargetPath,
                )
                Log.d(
                    TAG,
                    "append_adjacent_body_resident_control_release " +
                        "source=${launchSeal.normalizedEpisodePath}," +
                        "target=$selectedTargetPath,requiredFirst=$strictForwardSourceFloor," +
                        "requiredCount=${launchSeal.pageCount - strictForwardSourceFloor}",
                )
            }
        } catch (_: RejectedExecutionException) {
            forwardAdjacentControlAfterBodiesResidentStarted.set(false)
        }
    }

    private fun persistedForwardAdjacentControlCandidate(
        source: Manga,
        currentTitle: Title,
    ): Manga? {
        if (!currentTitle.sourceSite.equals("ntk", ignoreCase = true)) return null
        val nextIdentity = currentTitle.snapshotResumeNtkNextEpisodeIdentity()
        if (!nextIdentity.isComplete) return null
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(source.ntkEpisodePath.orEmpty())
        val persistedPredecessor = NtkStripDigests.normalizeEpisodePath(
            currentTitle.resumeNtkEpisodePath,
        )
        val targetPath = NtkStripDigests.normalizeEpisodePath(
            nextIdentity.path,
        )
        if (predecessorPath.isEmpty() || predecessorPath != persistedPredecessor ||
            targetPath.isEmpty() || targetPath == predecessorPath ||
            !targetPath.startsWith("/webtoon/") ||
            !NtkStrictEpisodeDiscoveryCoordinator.ntkAdjacentOwnerAllowsTarget(
                predecessorPath,
                targetPath,
            )
        ) return null
        return Manga(
            nextIdentity.id,
            nextIdentity.name,
            "",
            currentTitle.baseMode,
        ).apply {
            mode = source.mode
            title = currentTitle
            titleId = currentTitle.id
            ntkEpisodePath = targetPath
            ntkImageWorkId = nextIdentity.workId
            ntkImageEpisodeId = nextIdentity.episodeId
            ntkImageCount = nextIdentity.imageCount
        }
    }

    /**
     * Starts the one forward runway immediately after the renderer proves the whole current
     * episode. This bypasses only input-quiet delay; every metadata/body/decode entry rechecks the
     * network-neutral full-drawable gate. Previous-episode preparation is intentionally absent.
     */
    fun prepareForwardAdjacentAfterCurrentComplete(
        completedEpisodePath: String,
        resolvedNext: Manga? = null,
        authoritativeCompletionProof: Boolean = false,
        persistedExactAdjacentAuthority: Boolean = false,
        onResolvedForwardPath: ((String, String, Long) -> Unit)? = null,
    ) {
        if (reverse || cancelled.get()) return
        if (!isNtkContinuousAdjacentCompletionPolicyActive()) return
        // This callback is invoked only after the Activity has queued every authoritative current
        // texture. Completing the predecessor gate is thread-safe and must happen on that exact
        // edge: posting it behind the busy session-control queue added ~300 ms before the next
        // document could even start, enough for a short chapter fling to reach its physical tail.
        // The actual metadata/append bookkeeping remains serialized on [control] below.
        val normalizedCompletedPath = NtkStripDigests.normalizeEpisodePath(
            completedEpisodePath,
        )
        if (normalizedCompletedPath.isEmpty()) return
        val completedSource = synchronized(pagesLock) {
            pages.firstOrNull { page ->
                page.transitionTitle == null &&
                    NtkStripDigests.normalizeEpisodePath(
                        page.manga.ntkEpisodePath.orEmpty(),
                    ) == normalizedCompletedPath
            }?.manga
        } ?: return
        // Only the launch-seal callback may bypass the Session's mirrored drawable ledger. Later
        // toolbar/episode refreshes carry no completion authority and must prove this exact
        // predecessor complete before they can release the next exact owner. Binding the proof to
        // a normalized episode path also prevents a stale viewport anchor from turning A's
        // completion into permission for B -> C work while B is still drawing.
        val trustedLaunchCompletionProof = authoritativeCompletionProof &&
            strictExactLaunchSeal?.matchesEpisodePath(normalizedCompletedPath) == true
        if (!trustedLaunchCompletionProof &&
            !isEpisodeFullyDrawableForAdjacent(completedSource)
        ) return
        val exactTargetPath = startForwardAdjacentExactDiscoveryAtCompletion(
            completedSource,
            resolvedNext,
            persistedExactAdjacentAuthority,
            onResolvedForwardPath,
        )
        if (exactTargetPath != null) {
            releaseClaimedForwardAdjacentBodiesAfterPredecessorComplete(
                completedSource.ntkEpisodePath.orEmpty(),
                exactTargetPath,
            )
            releaseAdjacentStrictClaimsAfterPredecessorComplete(normalizedCompletedPath)
        }
        // Once an exact pair is selected, its manifest watcher owns completion. Starting the
        // independent numeric/list fallback as well creates a second valid-image owner whose
        // opaque database id can win the structural race despite not being the next chapter.
        if (exactTargetPath == null) {
            try {
                control.execute {
                    if (cancelled.get()) return@execute
                    val source = synchronized(pagesLock) {
                        pages.firstOrNull { page ->
                            page.transitionTitle == null &&
                                NtkStripDigests.normalizeEpisodePath(
                                    page.manga.ntkEpisodePath.orEmpty(),
                                ) == normalizedCompletedPath
                        }?.manga
                    } ?: return@execute
                    if (!isEpisodeFullyDrawableForAdjacent(source)) return@execute
                    val currentTitle = title ?: source.title ?: manga.title ?: return@execute
                    maybeStartInitialAdjacentMetadataPrefetch(
                        source,
                        currentTitle,
                        NtkAdjacentRunwayPreparationPolicy.CURRENT_EPISODE_COMPLETE_IDLE_REASON,
                    )
                    val sourceTail = synchronized(pagesLock) {
                        pages.indexOfLast { page ->
                            page.transitionTitle == null &&
                                looseSameEpisodeForAppend(page.manga, source)
                        }
                    }
                    if (sourceTail >= 0) maybeWarmCompletedForwardEpisode(sourceTail, source)
                }
            } catch (_: RejectedExecutionException) {
            }
        }
    }

    private fun releaseAdjacentStrictClaimsAfterPredecessorComplete(predecessorPath: String) {
        val normalizedPredecessor = NtkStripDigests.normalizeEpisodePath(predecessorPath)
        if (normalizedPredecessor.isEmpty()) return
        adjacentStrictSourceClaims.forEach { (targetPath, claim) ->
            if (claim.predecessorEpisodePath.equals(normalizedPredecessor, ignoreCase = true) &&
                NtkStrictEpisodeDiscoveryCoordinator.isAdjacentBodyGateOpen(
                    targetPath,
                    strictExactForegroundViewerGenerationAtCreation,
                )
            ) {
                releaseAdjacentStrictClaimAfterPredecessorComplete(targetPath, claim)
            }
        }
    }

    /**
     * Selects exactly one forward structural target for a predecessor. The exact body manifest for
     * an episode is not adjacency evidence: opaque numeric record ids may point at a different
     * chapter that nevertheless has perfectly valid images. Keep the persisted six-field pair
     * ahead of those heuristics, while still permitting stronger fresh-provider evidence to
     * replace an unpublished hint.
     */
    private fun claimForwardAdjacentCompletionTarget(
        target: Manga,
        predecessorEpisodePath: String,
        authority: NtkForwardAdjacentTargetClaimPolicy.Authority,
    ): ForwardAdjacentCompletionTargetClaim? {
        if (cancelled.get()) return null
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(predecessorEpisodePath)
        val targetPath = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        if (predecessorPath.isEmpty() || targetPath.isEmpty()) return null
        val validatedCatchUpBoundaryPath = currentAdjacentValidatedBoundaryEvidence()
            .normalizedEpisodePath
        return synchronized(forwardAdjacentCompletionTargetClaimLock) {
            if (cancelled.get()) return@synchronized null
            val existing = forwardAdjacentCompletionTargetClaims[predecessorPath]
            val retired = forwardAdjacentValidatedRecoveryTombstones[predecessorPath]
            if (existing == null && retired != null &&
                NtkForwardAdjacentValidatedRecoveryPolicy.blocksOrdinarySameTargetReselection(
                    retired.targetEpisodePath,
                    targetPath,
                )
            ) {
                val catchUpEpoch = NtkAdjacentValidatedEpochCatchUpPolicy.consume(
                    retired.pendingValidatedRedriveEpoch,
                    retired.lastValidatedRedriveEpoch,
                    exactBoundary = ViewerTelemetry.isActiveViewer(
                        strictExactForegroundViewerGenerationAtCreation,
                        strictExactViewerOwnerEpisodePathAtCreation,
                    ) &&
                        NtkAdjacentValidatedEpochCatchUpPolicy.exactBoundaryMatches(
                            validatedCatchUpBoundaryPath,
                            predecessorPath,
                            targetPath,
                        ),
                )
                if (catchUpEpoch > 0L) {
                    val strongerObservation = authority.rank > retired.authority.rank
                    val restored = ForwardAdjacentCompletionTargetClaim(
                        target = if (strongerObservation) target else retired.target,
                        predecessorEpisodePath = retired.predecessorEpisodePath,
                        targetEpisodePath = retired.targetEpisodePath,
                        authority = if (strongerObservation) authority else retired.authority,
                        revision = forwardAdjacentCompletionTargetClaimSequence.getAndIncrement(),
                        lastValidatedRedriveEpoch = catchUpEpoch,
                        lastValidatedRedriveAtMs = SystemClock.elapsedRealtime(),
                        pendingValidatedRedriveEpoch = 0L,
                    )
                    forwardAdjacentCompletionTargetClaims[predecessorPath] = restored
                    forwardAdjacentCompletionTargetHistory[targetPath] = predecessorPath
                    forwardAdjacentValidatedRecoveryTombstones.remove(
                        predecessorPath,
                        retired,
                    )
                    return@synchronized restored
                }
                // The ordinary fresh-list fallback may rediscover the same cached target while the
                // network is still down. Keep it parked instead of manufacturing a new revision
                // with another four-launch budget. A stronger same-path observation can refresh
                // immutable signing hints, but only a new validated epoch may make it live again.
                if (authority.rank > retired.authority.rank) {
                    forwardAdjacentValidatedRecoveryTombstones[predecessorPath] = retired.copy(
                        target = target,
                        authority = authority,
                    )
                }
                return@synchronized null
            }
            if (existing != null && !existing.structureCommitted &&
                existing.targetEpisodePath.equals(targetPath, ignoreCase = true)
            ) {
                val catchUpEpoch = NtkAdjacentValidatedEpochCatchUpPolicy.consume(
                    existing.pendingValidatedRedriveEpoch,
                    existing.lastValidatedRedriveEpoch,
                    exactBoundary = ViewerTelemetry.isActiveViewer(
                        strictExactForegroundViewerGenerationAtCreation,
                        strictExactViewerOwnerEpisodePathAtCreation,
                    ) &&
                        NtkAdjacentValidatedEpochCatchUpPolicy.exactBoundaryMatches(
                            validatedCatchUpBoundaryPath,
                            predecessorPath,
                            targetPath,
                        ),
                )
                if (catchUpEpoch > 0L) {
                    // Keep the live revision, but replenish its bounded launch counter once for
                    // the retained epoch. A second selection sees pending=0 and cannot replenish.
                    existing.discoveryLaunchAttempts.set(0)
                    existing.lastValidatedRedriveEpoch = catchUpEpoch
                    existing.lastValidatedRedriveAtMs = SystemClock.elapsedRealtime()
                    existing.pendingValidatedRedriveEpoch = 0L
                }
            }
            when (NtkForwardAdjacentTargetClaimPolicy.decide(
                existing?.targetEpisodePath,
                existing?.authority,
                existing?.structureCommitted == true,
                targetPath,
                authority,
            )) {
                NtkForwardAdjacentTargetClaimPolicy.Decision.ACCEPT -> {
                    ForwardAdjacentCompletionTargetClaim(
                        target = target,
                        predecessorEpisodePath = predecessorPath,
                        targetEpisodePath = targetPath,
                        authority = authority,
                        revision = forwardAdjacentCompletionTargetClaimSequence.getAndIncrement(),
                    ).also { accepted ->
                        forwardAdjacentCompletionTargetClaims[predecessorPath] = accepted
                        forwardAdjacentValidatedRecoveryTombstones.remove(predecessorPath)
                        forwardAdjacentCompletionTargetHistory[targetPath] = predecessorPath
                    }
                }

                NtkForwardAdjacentTargetClaimPolicy.Decision.JOIN -> {
                    checkNotNull(existing)
                    if (authority.rank > existing.authority.rank) {
                        existing.copy(authority = authority).also { upgraded ->
                            // A same-path authority upgrade retains the revision so an already
                            // queued exact-manifest callback and its immutable target object remain
                            // valid. Replacing the object here would reopen an ABA publication race.
                            forwardAdjacentCompletionTargetClaims[predecessorPath] = upgraded
                            forwardAdjacentValidatedRecoveryTombstones.remove(predecessorPath)
                        }
                    } else {
                        forwardAdjacentValidatedRecoveryTombstones.remove(predecessorPath)
                        existing
                    }
                }

                NtkForwardAdjacentTargetClaimPolicy.Decision.REPLACE -> {
                    checkNotNull(existing)
                    forwardAdjacentExactManifestAppendGate.removePendingRevision(
                        existing.targetEpisodePath,
                        existing.revision,
                    )
                    ForwardAdjacentCompletionTargetClaim(
                        target = target,
                        predecessorEpisodePath = predecessorPath,
                        targetEpisodePath = targetPath,
                        authority = authority,
                        revision = forwardAdjacentCompletionTargetClaimSequence.getAndIncrement(),
                    ).also { replacement ->
                        forwardAdjacentCompletionTargetClaims[predecessorPath] = replacement
                        forwardAdjacentValidatedRecoveryTombstones.remove(predecessorPath)
                        forwardAdjacentCompletionTargetHistory[targetPath] = predecessorPath
                        Log.d(
                            TAG,
                            "append_adjacent_completion_target_replaced predecessor=$predecessorPath " +
                                "old=${existing.targetEpisodePath},new=$targetPath," +
                                "oldAuthority=${existing.authority},newAuthority=$authority",
                        )
                    }
                }

                NtkForwardAdjacentTargetClaimPolicy.Decision.REJECT -> {
                    checkNotNull(existing)
                    forwardAdjacentValidatedRecoveryTombstones.remove(predecessorPath)
                    // Keep a tombstone for the losing path so a callback already queued by an
                    // older metadata route cannot be mistaken for an unrelated generic append at
                    // the final page-table fence.
                    forwardAdjacentCompletionTargetHistory[targetPath] = predecessorPath
                    Log.d(
                        TAG,
                        "append_adjacent_completion_target_conflict_rejected " +
                            "predecessor=$predecessorPath,selected=${existing.targetEpisodePath}," +
                            "rejected=$targetPath,selectedAuthority=${existing.authority}," +
                            "rejectedAuthority=$authority,committed=${existing.structureCommitted}",
                    )
                    existing
                }
            }
        }
    }

    private fun isForwardAdjacentCompletionTargetCurrent(
        predecessorEpisodePath: String,
        targetEpisodePath: String,
        claimRevision: Long,
    ): Boolean {
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(predecessorEpisodePath)
        val targetPath = NtkStripDigests.normalizeEpisodePath(targetEpisodePath)
        if (predecessorPath.isEmpty() || targetPath.isEmpty() || claimRevision <= 0L) return false
        return synchronized(forwardAdjacentCompletionTargetClaimLock) {
            val selected = forwardAdjacentCompletionTargetClaims[predecessorPath]
            selected != null && selected.revision == claimRevision &&
                selected.targetEpisodePath.equals(targetPath, ignoreCase = true)
        }
    }

    /** Linearizes the final page-table mutation against target replacement. */
    private fun isForwardAdjacentStructurePublicationCandidateCurrent(target: Manga): Boolean {
        if (cancelled.get()) return false
        val targetPath = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        if (targetPath.isEmpty()) return true
        val predecessorPath = forwardAdjacentCompletionTargetHistory[targetPath]
            ?: adjacentStrictPredecessorPaths[targetPath]
            ?: return true
        return synchronized(forwardAdjacentCompletionTargetClaimLock) {
            if (cancelled.get()) return@synchronized false
            val selected = forwardAdjacentCompletionTargetClaims[predecessorPath]
                ?: return@synchronized true
            NtkForwardAdjacentTargetClaimPolicy.sameTarget(
                selected.targetEpisodePath,
                targetPath,
            )
        }
    }

    private data class ForwardAdjacentStructurePublicationContext(
        val targetPath: String,
        val predecessorPath: String,
        val persistedTargetPath: String?,
    )

    /**
     * Freezes the persisted exact-pair proof without pagesLock. MTitle owns an independent monitor
     * used by progress persistence, and waiting for that monitor while holding pagesLock used to
     * block input/pageInfo for hundreds of milliseconds at an adjacent runway publication.
     */
    private fun prepareForwardAdjacentStructurePublication(
        target: Manga,
    ): ForwardAdjacentStructurePublicationContext? {
        if (cancelled.get()) return null
        val targetPath = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        if (targetPath.isEmpty()) {
            return ForwardAdjacentStructurePublicationContext("", "", null)
        }
        val predecessorPath = forwardAdjacentCompletionTargetHistory[targetPath]
            ?: adjacentStrictPredecessorPaths[targetPath]
            ?: return ForwardAdjacentStructurePublicationContext(targetPath, "", null)
        val currentTitle = title ?: target.title ?: manga.title
        val persistedTargetPath = currentTitle
            ?.takeIf {
                hostGpuEmulatorRuntime && isDirectWifiStrictAdjacentTransportActive()
            }
            ?.takeIf { it.sourceSite.equals("ntk", ignoreCase = true) }
            ?.let { ntkTitle ->
                val identity = ntkTitle.snapshotResumeNtkNextEpisodeIdentity()
                val persistedPredecessor = NtkStripDigests.normalizeEpisodePath(
                    ntkTitle.resumeNtkEpisodePath,
                )
                NtkStripDigests.normalizeEpisodePath(identity.path)
                    .takeIf {
                        identity.isComplete &&
                            persistedPredecessor.equals(predecessorPath, ignoreCase = true)
                    }
            }
        return ForwardAdjacentStructurePublicationContext(
            targetPath,
            predecessorPath,
            persistedTargetPath,
        )
    }

    /** Linearizes the final page-table mutation against target replacement. */
    private fun claimForwardAdjacentStructurePublication(target: Manga): Boolean {
        val context = prepareForwardAdjacentStructurePublication(target) ?: return false
        return claimForwardAdjacentStructurePublication(target, context)
    }

    private fun claimForwardAdjacentStructurePublication(
        target: Manga,
        context: ForwardAdjacentStructurePublicationContext,
    ): Boolean {
        if (cancelled.get()) return false
        val targetPath = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        if (!targetPath.equals(context.targetPath, ignoreCase = true)) return false
        if (targetPath.isEmpty() || context.predecessorPath.isEmpty()) return true
        val predecessorPath = forwardAdjacentCompletionTargetHistory[targetPath]
            ?: adjacentStrictPredecessorPaths[targetPath]
            ?: return false
        if (!predecessorPath.equals(context.predecessorPath, ignoreCase = true)) return false
        val persistedTargetPath = context.persistedTargetPath
        return synchronized(forwardAdjacentCompletionTargetClaimLock) {
            if (cancelled.get()) return@synchronized false
            val selected = forwardAdjacentCompletionTargetClaims[predecessorPath]
            if (selected == null) {
                if (persistedTargetPath != null &&
                    !persistedTargetPath.equals(targetPath, ignoreCase = true)
                ) {
                    forwardAdjacentCompletionTargetHistory[targetPath] = predecessorPath
                    Log.d(
                        TAG,
                        "append_adjacent_completion_persisted_structure_rejected " +
                            "predecessor=$predecessorPath,persisted=$persistedTargetPath," +
                            "rejected=$targetPath",
                    )
                    return@synchronized false
                }
                val authority = if (persistedTargetPath != null) {
                    NtkForwardAdjacentTargetClaimPolicy.Authority.PERSISTED_EXACT_PAIR
                } else {
                    NtkForwardAdjacentTargetClaimPolicy.Authority.NUMERIC_OR_LIST_FALLBACK
                }
                val committed = ForwardAdjacentCompletionTargetClaim(
                    target = target,
                    predecessorEpisodePath = predecessorPath,
                    targetEpisodePath = targetPath,
                    authority = authority,
                    revision = forwardAdjacentCompletionTargetClaimSequence.getAndIncrement(),
                    structureCommitted = true,
                )
                forwardAdjacentCompletionTargetClaims[predecessorPath] = committed
                forwardAdjacentValidatedRecoveryTombstones.remove(predecessorPath)
                forwardAdjacentCompletionTargetHistory[targetPath] = predecessorPath
                return@synchronized true
            }
            if (!NtkForwardAdjacentTargetClaimPolicy.sameTarget(
                    selected.targetEpisodePath,
                    targetPath,
                )
            ) {
                Log.d(
                    TAG,
                    "append_adjacent_completion_stale_structure_rejected predecessor=$predecessorPath " +
                        "selected=${selected.targetEpisodePath},rejected=$targetPath",
                )
                return@synchronized false
            }
            if (selected.target !== target) {
                // Exact discovery, page-list refresh, and delayed motion-idle publication can
                // reconstruct the same Manga row. The selected canonical path and predecessor
                // claim remain unchanged, so the alias joins the existing token instead of being
                // mistaken for a conflicting target. A genuinely different path was rejected
                // above before any page-table mutation.
                Log.d(
                    TAG,
                    "append_adjacent_completion_target_alias_joined " +
                        "predecessor=$predecessorPath,target=$targetPath," +
                        "revision=${selected.revision}",
                )
            }
            forwardAdjacentValidatedRecoveryTombstones.remove(predecessorPath)
            if (!selected.structureCommitted) {
                forwardAdjacentCompletionTargetClaims[predecessorPath] =
                    selected.copy(structureCommitted = true)
            }
            true
        }
    }

    private fun releaseClaimedForwardAdjacentBodiesAfterPredecessorComplete(
        predecessorEpisodePath: String,
        fallbackTargetEpisodePath: String? = null,
    ): Int = synchronized(forwardAdjacentCompletionTargetClaimLock) {
        if (cancelled.get()) return@synchronized 0
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(predecessorEpisodePath)
        if (predecessorPath.isEmpty()) return@synchronized 0
        val selectedTarget = forwardAdjacentCompletionTargetClaims[predecessorPath]
            ?.targetEpisodePath
            ?: NtkStripDigests.normalizeEpisodePath(fallbackTargetEpisodePath.orEmpty())
        NtkStrictEpisodeDiscoveryCoordinator.releaseAdjacentBodiesAfterPredecessorComplete(
            predecessorPath,
            selectedTarget.takeIf { it.isNotEmpty() },
            strictExactForegroundViewerGenerationAtCreation,
            strictExactViewerOwnerEpisodePathAtCreation,
        )
    }

    private fun releaseClaimedForwardAdjacentControlAfterBodiesResident(
        predecessorEpisodePath: String,
        fallbackTargetEpisodePath: String?,
    ): Int = synchronized(forwardAdjacentCompletionTargetClaimLock) {
        if (cancelled.get()) return@synchronized 0
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(predecessorEpisodePath)
        if (predecessorPath.isEmpty()) return@synchronized 0
        val selectedTarget = forwardAdjacentCompletionTargetClaims[predecessorPath]
            ?.targetEpisodePath
            ?: NtkStripDigests.normalizeEpisodePath(fallbackTargetEpisodePath.orEmpty())
        NtkStrictEpisodeDiscoveryCoordinator.releaseAdjacentControlAfterPredecessorBodiesResident(
            predecessorPath,
            selectedTarget,
            strictExactForegroundViewerGenerationAtCreation,
            strictExactViewerOwnerEpisodePathAtCreation,
        )
    }

    private fun currentForwardAdjacentCompletionTargetClaim(
        predecessorEpisodePath: String,
    ): ForwardAdjacentCompletionTargetClaim? {
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(predecessorEpisodePath)
        if (predecessorPath.isEmpty() || cancelled.get()) return null
        return synchronized(forwardAdjacentCompletionTargetClaimLock) {
            if (cancelled.get()) null else forwardAdjacentCompletionTargetClaims[predecessorPath]
        }
    }

    private fun activateForwardAdjacentCompletionTargetClaim(
        claim: ForwardAdjacentCompletionTargetClaim,
        onResolvedForwardPath: ((String, String, Long) -> Unit)?,
        controlOnly: Boolean,
    ): String? {
        if (cancelled.get() || !isForwardAdjacentCompletionTargetCurrent(
                claim.predecessorEpisodePath,
                claim.targetEpisodePath,
                claim.revision,
            )
        ) return null
        val candidate = claim.target
        val targetPath = claim.targetEpisodePath
        val predecessorPath = claim.predecessorEpisodePath
        if (!controlOnly && claim.preappendLaunched.get()) {
            return targetPath
        }
        listener.onForwardAdjacentPathResolved(
            predecessorPath,
            targetPath,
            claim.revision,
        )
        onResolvedForwardPath?.invoke(predecessorPath, targetPath, claim.revision)
        // Preserve the selected target even when another joiner has already attached it. Returning
        // null would re-enable the independent numeric fallback in the completion caller.
        if (hasEpisode(candidate)) {
            if (!claimForwardAdjacentStructurePublication(candidate)) return null
            return targetPath
        }
        rememberAdjacentStrictPredecessor(targetPath, predecessorPath)
        // Both activation modes publish the same exact discovery request. In particular the
        // body-resident control edge can run while the Surface is still scrolling an older
        // predecessor. Protect the selected target before that request becomes visible; otherwise
        // active-scroll cleanup can classify its p0-p3 calls as unrelated episode work, cancel the
        // physical bodies, and leave the completion owner joining an unfinished Flight forever.
        ReaderImageCache.allowAdjacentNtkForegroundViewerPath(
            targetPath,
            NTK_INITIAL_ADJACENT_PREFETCH_PATH_TTL_MS,
            if (controlOnly) {
                "body_resident_exact_control"
            } else {
                "current_complete_exact_discovery"
            },
        )
        if (controlOnly) {
            listener.onAdjacentExactManifestRequired(candidate, predecessorPath)
            Log.d(
                TAG,
                "append_adjacent_body_resident_exact_control source=$predecessorPath " +
                    "target=$targetPath",
            )
            return targetPath
        }
        watchForwardAdjacentExactManifestForPreappend(
            candidate,
            predecessorPath,
            claim.revision,
        )
        listener.onAdjacentExactManifestRequired(candidate, predecessorPath)
        Log.d(
            TAG,
            "append_adjacent_completion_exact_discovery source=$predecessorPath target=$targetPath",
        )
        return targetPath
    }

    /**
     * Resolves only the already-present episode-list neighbor at the authoritative completion
     * edge, then starts its exact owner without waiting behind the session control/network queues.
     * No caller can enter this method before every current texture has been queued. The regular
     * metadata task still owns manifest adoption and atomic four-drawable publication; it simply
     * joins this flight instead of creating it roughly one third of a second later.
     */
    private fun startForwardAdjacentExactDiscoveryAtCompletion(
        source: Manga,
        resolvedNext: Manga?,
        persistedExactAdjacentAuthority: Boolean = false,
        onResolvedForwardPath: ((String, String, Long) -> Unit)?,
        freshOrderedProviderAuthority: Boolean = false,
        controlOnly: Boolean = false,
    ): String? {
        val currentTitle = title ?: source.title ?: manga.title ?: return null
        // nextEp() is the provider-owned exact neighbor and is already attached to the current
        // episode. Avoid snapshotting/copying the entire title list on this critical edge. The
        // full metadata path below still performs every consensus/list-order validation before
        // it adopts or publishes the runway.
        val sourcePath = NtkStripDigests.normalizeEpisodePath(
            source.ntkEpisodePath?.trim().orEmpty()
        )
        if (sourcePath.isEmpty()) return null
        // The body-resident control path may already own the persisted exact pair. A later full
        // completion with no attached list must join and arm that owner instead of returning null
        // and reopening the independent numeric fallback.
        if (resolvedNext == null && !freshOrderedProviderAuthority) {
            currentForwardAdjacentCompletionTargetClaim(sourcePath)?.let { existing ->
                return activateForwardAdjacentCompletionTargetClaim(
                    existing,
                    onResolvedForwardPath,
                    controlOnly,
                )
            }
        }
        val providerImmediate = ntkTrustedProvidedAdjacentCandidate(
            source,
            ReaderSurfaceView.DIRECTION_NEXT,
        )
        val resolvedNextProviderAuthority = resolvedNext != null && providerImmediate?.let { immediate ->
            Manga.sameEpisodeIdentity(immediate, resolvedNext)
        } == true
        val resolvedNextPersistedAuthority = resolvedNext != null &&
            persistedExactAdjacentAuthority &&
            isDirectWifiStrictAdjacentTransportActive() &&
            resolvedNext.id > 0 &&
            resolvedNext.ntkImageWorkId.isNotBlank() &&
            resolvedNext.ntkImageEpisodeId.isNotBlank() &&
            resolvedNext.ntkImageCount > 0
        val trustedCandidate = resolvedNext?.takeIf { provided ->
            val providedPath = NtkStripDigests.normalizeEpisodePath(
                provided.ntkEpisodePath?.trim().orEmpty()
            )
            sourcePath.isNotEmpty() && providedPath.isNotEmpty() &&
                !Manga.sameEpisodeIdentity(source, provided) &&
                (resolvedNextProviderAuthority || resolvedNextPersistedAuthority) &&
                NtkStrictEpisodeDiscoveryCoordinator.ntkAdjacentOwnerAllowsTarget(
                    sourcePath,
                    providedPath,
                )
        } ?: providerImmediate
        if (persistedExactAdjacentAuthority && trustedCandidate === resolvedNext) {
            Log.d(
                TAG,
                "reader_ntk_adjacent_persisted_exact_authority " +
                    "predecessor=$sourcePath,target=${trustedCandidate?.ntkEpisodePath}",
            )
        }
        val sharedCandidate = trustedCandidate ?: run {
            val titleEpisodes = Utils.snapshotEpisodes(currentTitle)
            val episodes = if (titleEpisodes.isNotEmpty()) {
                titleEpisodes
            } else {
                Utils.snapshotEpisodes(source)
            }
            if (episodes.isEmpty()) {
                resolveForwardAdjacentEpisodeListAtCompletion(
                    source,
                    currentTitle,
                    onResolvedForwardPath,
                )
                return null
            }
            adjacentEpisodeCandidates(
                source,
                episodes,
                ReaderSurfaceView.DIRECTION_NEXT,
            ).firstOrNull() ?: return null
        }
        val proposedAuthority = when {
            sharedCandidate === resolvedNext && resolvedNextPersistedAuthority ->
                NtkForwardAdjacentTargetClaimPolicy.Authority.PERSISTED_EXACT_PAIR

            providerImmediate?.let { immediate ->
                Manga.sameEpisodeIdentity(immediate, sharedCandidate)
            } == true -> if (freshOrderedProviderAuthority) {
                NtkForwardAdjacentTargetClaimPolicy.Authority.FRESH_ORDERED_PROVIDER_NEIGHBOR
            } else {
                NtkForwardAdjacentTargetClaimPolicy.Authority.ATTACHED_PROVIDER_NEIGHBOR
            }

            else -> NtkForwardAdjacentTargetClaimPolicy.Authority.NUMERIC_OR_LIST_FALLBACK
        }
        val expectedPath = NtkStripDigests.normalizeEpisodePath(
            sharedCandidate.ntkEpisodePath?.trim().orEmpty()
        )
        if (expectedPath.isEmpty()) return null
        // Discovery needs immutable identity/signing hints only. Copying the complete episode
        // list via setEps() measured ~170-250 ms and is unnecessary until the regular metadata
        // task consumes the result.
        val proposedCandidate = Manga(
            sharedCandidate.id,
            sharedCandidate.name,
            sharedCandidate.date,
            sharedCandidate.baseMode,
        ).apply {
            mode = source.mode
            title = currentTitle
            titleId = currentTitle.id
            ntkEpisodePath = expectedPath
            ntkImageEpisodeId = sharedCandidate.ntkImageEpisodeId
            ntkImageWorkId = sharedCandidate.ntkImageWorkId
            ntkViewerPayloadHint = sharedCandidate.ntkViewerPayloadHint
            ntkImageCount = sharedCandidate.ntkImageCount
        }
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(
            source.ntkEpisodePath?.trim().orEmpty()
        )
        if (expectedPath.isEmpty() || predecessorPath.isEmpty()) return null
        val declaredSourceWorkId = source.ntkImageWorkId.trim()
        if (proposedCandidate.ntkImageWorkId.isBlank() &&
            isAsciiDecimalId(declaredSourceWorkId)
        ) {
            // The common signed slug path already carries the provider's exact work id on its
            // predecessor. Avoid the broader generated-neighbor scan on the completion edge.
            proposedCandidate.ntkImageWorkId = declaredSourceWorkId
        } else {
            inheritNtkAppendGeneratedHints(proposedCandidate, source, currentTitle)
        }
        // The claim must precede every listener/cache/discovery side effect. A weaker conflicting
        // candidate joins the selected target rather than creating a second exact owner.
        val selectedClaim = claimForwardAdjacentCompletionTarget(
            proposedCandidate,
            predecessorPath,
            proposedAuthority,
        ) ?: return null
        return activateForwardAdjacentCompletionTargetClaim(
            selectedClaim,
            onResolvedForwardPath,
            controlOnly,
        )
    }

    /**
     * Turns the completion-owned exact manifest into a physically attached runway immediately.
     * The old path waited for a boundary gesture, fetched the title episode list again, and only
     * then consumed the exact source that was already resident. This listener is Direct-WiFi only
     * and is armed after the predecessor's complete-drawable gate, so it neither starts network
     * work early nor changes cellular/SNI behavior.
     */
    private fun watchForwardAdjacentExactManifestForPreappend(
        target: Manga,
        predecessorEpisodePath: String,
        claimRevision: Long,
    ) {
        if (cancelled.get() || !isDirectWifiStrictAdjacentTransportActive()) return
        val targetPath = NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty())
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(predecessorEpisodePath)
        if (targetPath.isEmpty() || predecessorPath.isEmpty() ||
            !isForwardAdjacentCompletionTargetCurrent(
                predecessorPath,
                targetPath,
                claimRevision,
            ) ||
            !NtkStrictEpisodeDiscoveryCoordinator.ntkAdjacentOwnerAllowsTarget(
                predecessorPath,
                targetPath,
            )
        ) return
        val pending = forwardAdjacentExactManifestAppendGate.installNewest(
            targetPath,
            ForwardAdjacentExactManifestAppend(target, predecessorPath, claimRevision),
        )
        if (pending.claimRevision != claimRevision) return
        if (!isForwardAdjacentCompletionTargetCurrent(
                predecessorPath,
                targetPath,
                claimRevision,
            )
        ) {
            forwardAdjacentExactManifestAppendGate.removePending(targetPath, pending)
            return
        }
        if (forwardAdjacentExactManifestSubscription.get() == null) {
            val created = NtkSourceSpoolRegistry.addAuthoritativeManifestListener(
                NtkAuthoritativeManifestListener { changedPath, manifest ->
                    onForwardAdjacentExactManifestInstalled(changedPath, manifest)
                },
            )
            if (!forwardAdjacentExactManifestSubscription.compareAndSet(null, created)) {
                created.close()
            }
        }
        // Close subscription-vs-publication ordering without polling. A joined discovery may
        // already have installed its authority immediately before the listener was registered.
        NtkSourceSpoolRegistry.currentAuthoritativeManifest(targetPath)?.let { manifest ->
            onForwardAdjacentExactManifestInstalled(targetPath, manifest)
        }
    }

    private fun onForwardAdjacentExactManifestInstalled(
        changedPath: String,
        manifest: NtkAuthoritativeManifest,
    ) {
        val path = NtkStripDigests.normalizeEpisodePath(changedPath)
        val pending = forwardAdjacentExactManifestAppendGate.current(path) ?: return
        if (!isForwardAdjacentCompletionTargetCurrent(
                pending.predecessorEpisodePath,
                path,
                pending.claimRevision,
            )
        ) {
            forwardAdjacentExactManifestAppendGate.removePending(path, pending)
            return
        }
        if (cancelled.get() || !isDirectWifiStrictAdjacentTransportActive() ||
            !manifest.isProductionClaimable ||
            manifest.seal.normalizedEpisodePath != path ||
            !forwardAdjacentExactManifestAppendGate.tryAcquire(path, pending.claimRevision)
        ) return
        try {
            adjacentNetwork.execute {
                var consumed = false
                var retired = false
                try {
                    if (cancelled.get() || !isDirectWifiStrictAdjacentTransportActive()) return@execute
                    if (!isForwardAdjacentCompletionTargetCurrent(
                            pending.predecessorEpisodePath,
                            path,
                            pending.claimRevision,
                        )
                    ) {
                        retired = true
                        return@execute
                    }
                    val predecessor = synchronized(pagesLock) {
                        pages.asSequence()
                            .filter { it.transitionTitle == null }
                            .map { it.manga }
                            .firstOrNull { pageManga ->
                                NtkStripDigests.normalizeEpisodePath(
                                    pageManga.ntkEpisodePath.orEmpty(),
                                ) == pending.predecessorEpisodePath
                            }
                    } ?: return@execute
                    // Registration happens only on the authoritative completion edge, but retain
                    // the exact predecessor proof here so a stale callback cannot append after a
                    // later structural transition or session replacement.
                    if (!isEpisodeFullyDrawableForAdjacent(predecessor)) return@execute
                    val authority = NtkSourceSpoolRegistry.currentAuthoritativeManifest(path)
                        ?.takeIf { current ->
                            current.isProductionClaimable &&
                                current.seal.digestSha256 == manifest.seal.digestSha256
                        }
                        ?: return@execute
                    rememberAdjacentStrictPredecessor(path, pending.predecessorEpisodePath)
                    val urls = exactViewerApiAdjacentUrls(pending.target) ?: return@execute
                    if (urls.isEmpty() || urls.size != authority.seal.pageCount) return@execute
                    if (!isForwardAdjacentCompletionTargetCurrent(
                            pending.predecessorEpisodePath,
                            path,
                            pending.claimRevision,
                        )
                    ) {
                        retired = true
                        return@execute
                    }
                    val launchClaim = synchronized(forwardAdjacentCompletionTargetClaimLock) {
                        forwardAdjacentCompletionTargetClaims[pending.predecessorEpisodePath]
                            ?.takeIf { selected ->
                                selected.revision == pending.claimRevision &&
                                    selected.targetEpisodePath.equals(path, ignoreCase = true)
                            }
                    } ?: run {
                        retired = true
                        return@execute
                    }
                    if (!launchClaim.preappendLaunched.compareAndSet(false, true)) {
                        consumed = true
                        return@execute
                    }
                    initialTailAdjacentPreappendTargetPaths.add(path)
                    Log.d(
                        TAG,
                        "append_adjacent_exact_manifest_preappend source=" +
                            "${pending.predecessorEpisodePath} target=$path images=${urls.size}",
                    )
                    try {
                        appendResolvedEpisode(
                            pending.target,
                            urls,
                            ReaderSurfaceView.DIRECTION_NEXT,
                        )
                    } catch (failure: Throwable) {
                        launchClaim.preappendLaunched.compareAndSet(true, false)
                        throw failure
                    }
                    consumed = true
                } finally {
                    var retryCurrent = false
                    if (consumed || retired) {
                        forwardAdjacentExactManifestAppendGate.removePending(path, pending)
                    } else if (!cancelled.get() &&
                        forwardAdjacentExactManifestAppendGate.isCurrent(path, pending) &&
                        pending.attempts.incrementAndGet() <= 20
                    ) {
                        retryCurrent = true
                    } else {
                        forwardAdjacentExactManifestAppendGate.removePending(path, pending)
                    }
                    releaseForwardAdjacentExactManifestFlight(
                        path,
                        pending,
                        retryCurrent = retryCurrent,
                    )
                }
            }
        } catch (_: RejectedExecutionException) {
            releaseForwardAdjacentExactManifestFlight(
                path,
                pending,
                retryRejectedCurrent = true,
            )
        }
    }

    /**
     * Releases only the revision that acquired this path and asynchronously hands the path to a
     * newer current claim. Executor rejection may also retry the same pending value, but remains
     * bounded and delayed so a closed executor cannot create a recursive rejection loop.
     */
    private fun releaseForwardAdjacentExactManifestFlight(
        path: String,
        pending: ForwardAdjacentExactManifestAppend,
        retryCurrent: Boolean = false,
        retryRejectedCurrent: Boolean = false,
    ) {
        if (!forwardAdjacentExactManifestAppendGate.release(path, pending.claimRevision)) return
        if (cancelled.get() || !isDirectWifiStrictAdjacentTransportActive()) return
        val successor = forwardAdjacentExactManifestAppendGate.current(path) ?: return
        val newerRevision = successor.claimRevision > pending.claimRevision
        val retrySameRevision = (retryCurrent || retryRejectedCurrent) && successor === pending
        if (!newerRevision && !retrySameRevision) return
        if (!isForwardAdjacentCompletionTargetCurrent(
                successor.predecessorEpisodePath,
                path,
                successor.claimRevision,
            )
        ) {
            forwardAdjacentExactManifestAppendGate.removePending(path, successor)
            return
        }
        val delayMs = if (newerRevision) {
            0L
        } else if (retryCurrent) {
            // The normal retry budget was charged before releasing the token. Scheduling only
            // after compare-release closes the callback-before-release lost-wakeup race.
            25L
        } else if (successor.attempts.incrementAndGet() <= 20) {
            25L
        } else {
            forwardAdjacentExactManifestAppendGate.removePending(path, successor)
            return
        }
        scheduleForwardAdjacentExactManifestRedrive(path, delayMs)
    }

    /** Always crosses the main queue before invoking the manifest callback; never recurses. */
    private fun scheduleForwardAdjacentExactManifestRedrive(path: String, delayMs: Long) {
        if (cancelled.get() || !isDirectWifiStrictAdjacentTransportActive()) return
        val redrive = Runnable {
            if (cancelled.get() || !isDirectWifiStrictAdjacentTransportActive()) return@Runnable
            val current = forwardAdjacentExactManifestAppendGate.current(path) ?: return@Runnable
            if (!isForwardAdjacentCompletionTargetCurrent(
                    current.predecessorEpisodePath,
                    path,
                    current.claimRevision,
                )
            ) {
                forwardAdjacentExactManifestAppendGate.removePending(path, current)
                return@Runnable
            }
            NtkSourceSpoolRegistry.currentAuthoritativeManifest(path)?.let { freshManifest ->
                onForwardAdjacentExactManifestInstalled(path, freshManifest)
            }
        }
        if (delayMs > 0L) main.postDelayed(redrive, delayMs) else main.post(redrive)
    }

    /**
     * Continue history intentionally stores no full episode list. Once the current native scene is
     * complete, resolve that tiny list immediately instead of waiting until the user's boundary
     * gesture. This does not overlap any current image work: the only caller is the authoritative
     * completion callback after every required current texture has been queued.
     */
    private fun resolveForwardAdjacentEpisodeListAtCompletion(
        source: Manga,
        currentTitle: Title,
        onResolvedForwardPath: ((String, String, Long) -> Unit)?,
    ) {
        val predecessorPath = NtkStripDigests.normalizeEpisodePath(
            source.ntkEpisodePath?.trim().orEmpty(),
        )
        if (predecessorPath.isEmpty() ||
            !completionAdjacentEpisodeResolutionPaths.add(predecessorPath)
        ) return
        try {
            adjacentNetwork.execute {
                try {
                    if (cancelled.get()) return@execute
                    var fetchedFreshOrderedProviderList = false
                    if (syncNtkTitlePathFromEpisode(currentTitle, source)) {
                        currentTitle.removeEps()
                    }
                    restoreNtkEpisodeSnapshotIfNeeded(currentTitle, source)
                    if ((currentTitle.eps?.size ?: 0) <= 1) {
                        val result = withRepositoryCancellation {
                            imageRepository.fetchEpisodesForeground(currentTitle, it)
                        }
                        if (cancelled.get() || result != Title.LOAD_OK) return@execute
                        fetchedFreshOrderedProviderList = true
                    }
                    attachTitle()
                    val episodes = Utils.snapshotEpisodes(currentTitle)
                    if (episodes.isEmpty()) return@execute
                    manga.setEps(episodes)
                    source.setEps(episodes)
                    persistNtkEpisodeSnapshot(currentTitle, episodes)
                    if (!isEpisodeFullyDrawableForAdjacent(source)) return@execute
                    val exactTargetPath = startForwardAdjacentExactDiscoveryAtCompletion(
                        source,
                        resolvedNext = null,
                        freshOrderedProviderAuthority = fetchedFreshOrderedProviderList,
                        onResolvedForwardPath = onResolvedForwardPath,
                    )
                    if (exactTargetPath != null) {
                        releaseClaimedForwardAdjacentBodiesAfterPredecessorComplete(
                            source.ntkEpisodePath.orEmpty(),
                            exactTargetPath,
                        )
                        releaseAdjacentStrictClaimsAfterPredecessorComplete(predecessorPath)
                    }
                    if (shouldReenterDirectWifiCompletionRunway(source)) {
                        maybeStartInitialAdjacentMetadataPrefetch(
                            source,
                            currentTitle,
                            NtkAdjacentRunwayPreparationPolicy.CURRENT_EPISODE_COMPLETE_IDLE_REASON,
                        )
                    }
                } finally {
                    completionAdjacentEpisodeResolutionPaths.remove(predecessorPath)
                }
            }
        } catch (_: RejectedExecutionException) {
            completionAdjacentEpisodeResolutionPaths.remove(predecessorPath)
        }
    }

    private fun shouldReenterDirectWifiCompletionRunway(source: Manga): Boolean {
        if (cancelled.get() || reverse || !strictExactColdRolling) return false
        if (!isDirectWifiStrictAdjacentTransportActive()) return false
        return isEpisodeFullyDrawableForAdjacent(source)
    }

    fun canPrepareForwardAdjacentNow(expectedCurrentEpisodePath: String? = null): Boolean {
        if (!isNtkContinuousAdjacentCompletionPolicyActive()) return true
        val expectedPath = NtkStripDigests.normalizeEpisodePath(
            expectedCurrentEpisodePath?.trim().orEmpty()
        )
        if (expectedCurrentEpisodePath != null && expectedPath.isEmpty()) return false
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        val source = synchronized(pagesLock) {
            if (pages.isEmpty()) return@synchronized null
            if (expectedPath.isNotEmpty()) {
                pages.asSequence()
                    .filter { it.transitionTitle == null }
                    .map { it.manga }
                    .firstOrNull {
                        NtkStripDigests.normalizeEpisodePath(
                            it.ntkEpisodePath?.trim().orEmpty()
                        ) == expectedPath
                    }
            } else {
                pages.getOrNull(anchor.coerceIn(0, pages.lastIndex))
                    ?.takeIf { it.transitionTitle == null }
                    ?.manga
            }
        } ?: return false
        return isEpisodeFullyDrawableForAdjacent(source)
    }

    /**
     * Exposes only the scope of the NTK completion-gated adjacent policy. The Activity uses this
     * to timestamp the launch episode's real tail commit even after an already-prepared next
     * runway has extended the surface. Mobile/SNI and Wi-Fi share this ordering contract while
     * retaining their existing transport behavior.
     */
    fun isNtkForwardAdjacentCompletionPolicyActive(): Boolean =
        !reverse && isNtkContinuousAdjacentCompletionPolicyActive()

    private fun scheduleForwardReadingDrain() {
        if (!forwardReadingDrainPosted.compareAndSet(false, true)) return
        try {
            control.execute(::drainForwardReadingPosition)
        } catch (_: RejectedExecutionException) {
            forwardReadingDrainPosted.set(false)
        }
    }

    private fun drainForwardReadingPosition() {
        try {
            while (!cancelled.get()) {
                val requestedAnchor = forwardReadingPosition.getAndSet(-1)
                if (requestedAnchor < 0) break
                // Global display indexes do not become authoritative until the Activity has
                // applied the matching Surface mutation. Drop any position sampled against the
                // old table while that publish is in flight; the retry below starts from the
                // already-adjusted session anchor after the UI callback acknowledges the batch.
                // Without this fence, a structural mutation could race a Surface frame that
                // still renders the previous global indexes.
                if (isStructurePublishPending()) {
                    scheduleForwardReadingRetry()
                    break
                }
                val expectedObservationRevision = forwardReadingObservationRevision.get()
                val activeObservation = currentForwardReadingObservationLocked(
                    expectedObservationRevision,
                    requestedAnchor,
                )
                if (activeObservation == null) {
                    scheduleForwardReadingRetry()
                    continue
                }
                val (observedAnchor, activePage) = activeObservation
                val activeEpisode = activePage.manga
                val physicalInputActive =
                    viewportBusy.get() ||
                        physicalTouchQuietRemainingMs(
                            NTK_STRICT_ACTIVE_RUNWAY_IDLE_COMPLETION_QUIET_MS
                        ) > 0L
                val currentTitle = title ?: activeEpisode.title
                if (physicalInputActive) {
                    // Document discovery ultimately enters the Activity and may cold-start the
                    // next ACK/WebView owner. Even with its API/body wall closed, that host work
                    // competes with the emulator compositor. Retain the latest reading position
                    // and start the whole adjacent control flight after the same physical-input
                    // quiet fence used by decode and structure publication.
                    scheduleForwardReadingRetry()
                } else {
                    // Pixel retirement and numeric prefix remapping both acquire the mutable
                    // page-table lock. A background control owner that starts either operation
                    // during MOVE can be descheduled while main is waiting for the same monitor.
                    // Run all history maintenance only after the physical-input fence is quiet;
                    // the immutable published index above remains the observation authority.
                    val adjustedAnchor = trimConsumedForwardHistory(
                        observedAnchor,
                        activePage,
                        expectedObservationRevision,
                    )
                    currentTitle?.let {
                        maybeStartInitialAdjacentMetadataPrefetch(
                            activeEpisode,
                            it,
                            "forward_episode_active",
                        )
                    }
                    maybeWarmCompletedForwardEpisode(adjustedAnchor, activeEpisode)
                }
            }
        } finally {
            forwardReadingDrainPosted.set(false)
            if (forwardReadingPosition.get() >= 0 && !cancelled.get()) {
                scheduleForwardReadingDrain()
            }
        }
    }

    private fun currentForwardReadingObservationLocked(
        expectedObservationRevision: Long,
        fallbackAnchor: Int,
    ): Pair<Int, PageRef>? {
        val reportedPage = latestReportedReadingPage.get() ?: return null
        val published = publishedPageIndex.get()
        val reportedIndex = when {
            fallbackAnchor in published.indices && published[fallbackAnchor] === reportedPage ->
                fallbackAnchor
            reportedPage.pageIndex in published.indices &&
                published[reportedPage.pageIndex] === reportedPage -> reportedPage.pageIndex
            else -> published.indexOfFirst { page -> page === reportedPage }
        }
        if (reportedIndex !in published.indices) return null
        if (!forwardReadingObservationStillAuthorizesLocked(
                expectedObservationRevision,
                reportedPage,
            )
        ) {
            return null
        }
        return reportedIndex to reportedPage
    }

    private fun forwardReadingObservationStillAuthorizesLocked(
        expectedObservationRevision: Long,
        candidatePage: PageRef,
    ): Boolean {
        val snapshot = publishedPageIndex.get()
        val publishedPage = latestReportedReadingPage.get()
        val publishedIndex = publishedPage?.let { page ->
            when {
                page.pageIndex in snapshot.indices && snapshot[page.pageIndex] === page ->
                    page.pageIndex
                else -> snapshot.indexOfFirst { candidate -> candidate === page }
            }
        } ?: -1
        return NtkForwardHistoryPolicy.currentViewportAuthorizesHistoryMutation(
            expectedObservationRevision = expectedObservationRevision,
            publishedObservationRevision = latestReportedReadingPageRevision.get(),
            latestObservationRevision = forwardReadingObservationRevision.get(),
            candidateMatchesPublishedPage =
                publishedPage === candidatePage &&
                    publishedIndex in snapshot.indices,
        )
    }

    private fun forwardPixelRetirementIdentity(
        activePage: PageRef,
    ): NtkForwardPixelRetirementIdentity? {
        if (activePage.transitionTitle != null) return null
        val path = NtkStripDigests.normalizeEpisodePath(
            activePage.manga.ntkEpisodePath.orEmpty(),
        )
        if (path.isEmpty()) return null
        val launchSeal = strictExactLaunchSeal?.takeIf { seal ->
            seal.normalizedEpisodePath.equals(path, ignoreCase = true)
        }
        val adjacentClaim = if (launchSeal == null) {
            adjacentStrictSourceClaims[path]
        } else {
            null
        }
        val digest = activePage.manifestDigest.ifBlank {
            launchSeal?.manifestDigest ?: adjacentClaim?.manifestDigest.orEmpty()
        }
        val pageCount = activePage.manifestPageCount.takeIf { it > 0 }
            ?: launchSeal?.pageCount
            ?: return null
        val revision = launchSeal?.manifestSeal?.revision
            ?: adjacentClaim?.takeIf { claim -> claim.manifestDigest == digest }?.episode?.value
            ?: return null
        if (launchSeal != null &&
            (digest != launchSeal.manifestDigest || pageCount != launchSeal.pageCount)
        ) {
            return null
        }
        if (launchSeal == null && adjacentClaim?.manifestDigest != digest) return null
        return NtkForwardPixelRetirementIdentity.create(
            episodePath = path,
            manifestDigest = digest,
            manifestRevision = revision,
            manifestPageCount = pageCount,
        )
    }

    private fun trimConsumedForwardHistory(
        anchor: Int,
        activePage: PageRef,
        expectedObservationRevision: Long,
    ): Int {
        if (activePage.transitionTitle != null || reverse) return anchor
        if (!hostLifecycleResumed) {
            // HOME/Recents owns an immutable compositor coordinate. Do not retire pixels or
            // renumber PageRefs while the task is invisible: a slow Launcher transition can keep
            // the process runnable for seconds after onPause, and an already-posted maintenance
            // retry would otherwise rebase the public viewport behind the frozen presentation.
            // onHostResumed explicitly re-drives this lane after its first-frame quiet fence.
            logForwardHistoryTrimDeferralOnce(
                "host_paused",
                activePage,
                "anchor=$anchor",
            )
            return currentPageIndex(activePage, anchor).takeIf { it >= 0 } ?: anchor
        }
        val observationAuthorized = forwardReadingObservationStillAuthorizesLocked(
            expectedObservationRevision,
            activePage,
        )
        if (!observationAuthorized) {
            scheduleForwardReadingRetry()
            return anchor
        }
        if (forwardHistoryPixelClearPending.get()) {
            logForwardHistoryTrimDeferralOnce(
                "surface_clear_pending",
                activePage,
                "anchor=$anchor",
            )
            scheduleForwardReadingRetry()
            return currentPageIndex(activePage, anchor).takeIf { it >= 0 } ?: anchor
        }
        if (isAdjacentDrawableBatchPublicationPending()) {
            scheduleForwardReadingRetry()
            return currentPageIndex(activePage, anchor).takeIf { it >= 0 } ?: anchor
        }
        val resumeQuietRemainingMs = forwardHistoryHostResumeQuietRemainingMs()
        if (resumeQuietRemainingMs > 0L) {
            logForwardHistoryTrimDeferralOnce(
                "host_resume_quiet",
                activePage,
                "anchor=$anchor,remainingMs=$resumeQuietRemainingMs",
            )
            scheduleForwardReadingRetry(resumeQuietRemainingMs)
            return currentPageIndex(activePage, anchor).takeIf { it >= 0 } ?: anchor
        }
        val pixelCandidate = synchronized(pagesLock) {
            val verifiedAnchor = pageIndexLocked(activePage, anchor)
            if (verifiedAnchor !in pages.indices) return@synchronized null
            forwardHistoryTrimCandidateLocked(
                verifiedAnchor,
                activePage,
                requireCompleteSourceStructure = false,
            )
        } ?: return currentPageIndex(activePage, anchor).takeIf { it >= 0 } ?: anchor

        // Pixel ownership and page-table ownership have different safety boundaries. Once the
        // third real image of the next episode is active -- or an exact one/two-image episode has
        // reached its terminal source -- decoded pixels older than the bounded predecessor tail
        // are physically behind the forward viewport and can be released.
        // Moving the page table itself during a fling, however, changes every global index and can
        // make an already-captured frame look incorrectly bound. Retire pixels now, but keep every
        // lightweight PageRef and source claim for the immediate predecessor. Only structure older
        // than that episode waits for a genuinely quiet viewport and a complete current page table.
        // Reserve before either destructive branch. The claim deliberately survives an empty
        // release set: the byte-budget LRU owns pixels decoded after this one threshold crossing.
        // A reverse visit to the same exact manifest therefore cannot clear its predecessor again.
        val ownsPixelRetirement = pixelCandidate.pixelRetireBefore > 0 &&
            forwardPixelRetirementIdentity(activePage)
                ?.let(forwardPixelRetirementLedger::tryClaim) == true
        // Prefix structure cannot be renumbered while its old pixels are still installed in the
        // Surface. Clear that exact prefix first, independently from the one-shot decoded-tail
        // claim. A later retry sees an empty release set and may then commit the numeric remap.
        if (pixelCandidate.removeCount > 0) {
            if (!forwardHistoryPixelClearPending.compareAndSet(false, true)) {
                // A different first pass won the surface-clear fence after the fast check above.
                // This exact claim remains consumed; the retry skips clearing and only revalidates
                // safe page-table pruning after that surface operation completes.
                scheduleForwardReadingRetry()
                return currentPageIndex(activePage, pixelCandidate.anchor)
                    .takeIf { it >= 0 } ?: pixelCandidate.anchor
            }
            var released = false
            try {
                released = retireConsumedForwardHistoryPixels(
                    pixelCandidate.removeCount,
                    activePage,
                    expectedObservationRevision,
                ) {
                    forwardHistoryPixelClearPending.set(false)
                    Log.d(
                        TAG,
                        "reader_forward_history_surface_clear_complete " +
                            "before=${pixelCandidate.removeCount}," +
                            "path=${activePage.manga.ntkEpisodePath}",
                    )
                    scheduleForwardReadingRetry()
                }
                if (released) {
                    // The callback above runs only after the Surface clear is stable. Until then
                    // every forward-history turn observes [forwardHistoryPixelClearPending] and
                    // cannot renumber the Session table beneath that old-index Surface operation.
                    return currentPageIndex(activePage, pixelCandidate.anchor)
                        .takeIf { it >= 0 } ?: pixelCandidate.anchor
                }
            } finally {
                if (!released) forwardHistoryPixelClearPending.set(false)
            }
        } else if (ownsPixelRetirement) {
            if (!forwardHistoryPixelClearPending.compareAndSet(false, true)) {
                scheduleForwardReadingRetry()
                return currentPageIndex(activePage, pixelCandidate.anchor)
                    .takeIf { it >= 0 } ?: pixelCandidate.anchor
            }
            var released = false
            try {
                released = retireConsumedForwardHistoryPixels(
                    pixelCandidate.pixelRetireBefore,
                    activePage,
                    expectedObservationRevision,
                ) {
                    forwardHistoryPixelClearPending.set(false)
                    Log.d(
                        TAG,
                        "reader_forward_history_surface_clear_complete " +
                            "before=${pixelCandidate.pixelRetireBefore}," +
                            "path=${activePage.manga.ntkEpisodePath}",
                    )
                    scheduleForwardReadingRetry()
                }
                if (released) {
                    return currentPageIndex(activePage, pixelCandidate.anchor)
                        .takeIf { it >= 0 } ?: pixelCandidate.anchor
                }
            } finally {
                if (!released) forwardHistoryPixelClearPending.set(false)
            }
        }
        if (pixelCandidate.removeCount <= 0) return pixelCandidate.anchor
        val candidate = synchronized(pagesLock) {
            val verifiedAnchor = pageIndexLocked(activePage, pixelCandidate.anchor)
            if (verifiedAnchor !in pages.indices) return@synchronized null
            forwardHistoryTrimCandidateLocked(
                verifiedAnchor,
                activePage,
                requireCompleteSourceStructure = true,
            )
        }
        if (candidate == null) {
            logForwardHistoryTrimDeferralOnce(
                "incomplete_current_structure",
                activePage,
                "anchor=${pixelCandidate.anchor},pages=${synchronized(pagesLock) { pages.size }}",
            )
            scheduleForwardReadingRetry()
            return pixelCandidate.anchor
        }
        if (
            viewportBusy.get() ||
            directWifiForwardHistoryMotionQuietRemainingMs() > 0L ||
            forwardHistoryHostResumeQuietRemainingMs() > 0L ||
            readerQuietRemainingMs(NTK_FORWARD_HISTORY_TRIM_QUIET_MS) > 0L
        ) {
            logForwardHistoryTrimDeferralOnce(
                "viewport_not_quiet",
                activePage,
                "anchor=${candidate.anchor},remove=${candidate.removeCount}",
            )
            scheduleForwardReadingRetry()
            return candidate.anchor
        }
        val removedDrawableKeys = ArrayList<String>()
        val consumedStrictPaths = LinkedHashSet<String>()
        val total: Int
        val adjustedAnchor: Int
        synchronized(hostLifecyclePixelLock) {
            if (!hostLifecycleResumed) {
                logForwardHistoryTrimDeferralOnce(
                    "host_paused",
                    activePage,
                    "anchor=${candidate.anchor},remove=${candidate.removeCount}",
                )
                return currentPageIndex(activePage, candidate.anchor)
                    .takeIf { it >= 0 } ?: candidate.anchor
            }
            synchronized(pagesLock) {
            // Close the check-to-lock race with an adjacent append that began after the fast
            // guard above. Both page-table mutations are serialized by pagesLock. A new physical
            // gesture can also begin after the outer quiet snapshot: revalidate every motion
            // fence at this final linearization point so prefix renumbering never steals a moving
            // frame or rebases a pointer-owned scroll coordinate.
            if (isAdjacentDrawableBatchPublicationPending()) {
                scheduleForwardReadingRetry()
                return candidate.anchor
            }
            if (
                viewportBusy.get() ||
                directWifiForwardHistoryMotionQuietRemainingMs() > 0L ||
                forwardHistoryHostResumeQuietRemainingMs() > 0L ||
                readerQuietRemainingMs(NTK_FORWARD_HISTORY_TRIM_QUIET_MS) > 0L
            ) {
                scheduleForwardReadingRetry()
                return candidate.anchor
            }
            if (!forwardReadingObservationStillAuthorizesLocked(
                    expectedObservationRevision,
                    activePage,
                )
            ) {
                scheduleForwardReadingRetry()
                return candidate.anchor
            }
            val verifiedAnchor = pageIndexLocked(activePage, candidate.anchor)
            if (verifiedAnchor !in pages.indices) {
                return candidate.anchor
            }
            val verified = forwardHistoryTrimCandidateLocked(verifiedAnchor, activePage)
            if (verified == null ||
                verified.removeCount != candidate.removeCount ||
                verified.pixelRetireBefore != candidate.pixelRetireBefore ||
                candidate.removeCount > pages.size
            ) {
                scheduleForwardReadingRetry()
                return candidate.anchor
            }
            val protectedPixelWindow = if (usesProtectedNumericNtkPipeline()) {
                protectedNumericBitmapWindow(pages.size)
            } else {
                IntRange.EMPTY
            }
            val removedPrefixLast = candidate.removeCount - 1
            if (!protectedPixelWindow.isEmpty() &&
                protectedPixelWindow.first <= removedPrefixLast &&
                protectedPixelWindow.last >= 0
            ) {
                // A stale protected-window snapshot intentionally expands to the full table, and
                // a current reverse window can overlap the predecessor tail. In either case the
                // matching pixels and PageRefs remain physically addressable, so defer both the
                // destructive clear and the numeric prefix remap until a later coherent window.
                logForwardHistoryTrimDeferralOnce(
                    "protected_window_overlap",
                    activePage,
                    "anchor=$verifiedAnchor,remove=${candidate.removeCount}," +
                        "window=${protectedPixelWindow.first}-${protectedPixelWindow.last}," +
                        "pages=${pages.size}",
                )
                scheduleForwardReadingRetry()
                return verifiedAnchor
            }
            for (index in 0 until candidate.removeCount) {
                drawableReadyKey(pages[index])?.let(removedDrawableKeys::add)
            }
            val removedPaths = pages.subList(0, candidate.removeCount)
                .asSequence()
                .filter { it.transitionTitle == null }
                .map { NtkStripDigests.normalizeEpisodePath(it.manga.ntkEpisodePath.orEmpty()) }
                .filter(String::isNotEmpty)
                .toCollection(LinkedHashSet())
            val retainedPaths = pages.subList(candidate.removeCount, pages.size)
                .asSequence()
                .filter { it.transitionTitle == null }
                .map { NtkStripDigests.normalizeEpisodePath(it.manga.ntkEpisodePath.orEmpty()) }
                .filter(String::isNotEmpty)
                .toHashSet()
            val activePath = NtkStripDigests.normalizeEpisodePath(
                activePage.manga.ntkEpisodePath.orEmpty(),
            )
            consumedStrictPaths.addAll(removedPaths)
            consumedStrictPaths.removeAll(retainedPaths)
            consumedStrictPaths.remove(activePath)
            beginStructurePublish()
            pages.subList(0, candidate.removeCount).clear()
            pages.forEachIndexed { pageIndex, ref -> ref.pageIndex = pageIndex }
            removePageStateRange(0, candidate.removeCount)
            adjustedAnchor = (verifiedAnchor - candidate.removeCount).coerceIn(0, pages.lastIndex)
            currentViewportAnchor.set(adjustedAnchor)
            resolvedInitialStartPage.set(0)
            lastSourcePrefetchAnchor = -1
            lastInteractiveFullSourcePrefetchAnchor.set(Int.MIN_VALUE)
            pendingInteractiveFullSourcePrefetchAnchor.set(Int.MIN_VALUE)
            lastActiveGeneratedScrollRunwayAnchor.set(Int.MIN_VALUE)
            total = pages.size
            capturePublishedPageIndexLocked()
            }
        }
        removedDrawableKeys.forEach(drawableReadyKeys::remove)
        episodeDrawableCompletionLedger.removeEpisodes(consumedStrictPaths)
        val posted = main.post {
            var surfaceApplied = false
            try {
                if (!cancelled.get()) {
                    listener.onPagesRemoved(0, candidate.removeCount, total)
                    surfaceApplied = true
                }
            } finally {
                finishStructurePublish()
                requestRetainedWindowAfterStructureChange()
                if (surfaceApplied && consumedStrictPaths.isNotEmpty()) {
                    try {
                        control.execute { retireConsumedStrictSources(consumedStrictPaths) }
                    } catch (_: RejectedExecutionException) {
                        // Session teardown owns the remaining sources if its control lane closed.
                    }
                }
            }
        }
        if (!posted) {
            finishStructurePublish()
            requestRetainedWindowAfterStructureChange()
        }
        Log.d(
            TAG,
            "reader_forward_history_pruned removed=${candidate.removeCount},total=$total," +
                "anchorOld=${candidate.anchor},anchorNew=$adjustedAnchor," +
                "currentOrdinal=${candidate.currentImageOrdinal}," +
                "path=${activePage.manga.ntkEpisodePath}"
        )
        return adjustedAnchor
    }

    private fun retireConsumedStrictSources(paths: Set<String>) {
        // The page-table prune has now made these episode paths unreachable. Only this exact
        // consumed-path boundary (and Session cancellation) reopens/removes retirement ownership.
        forwardPixelRetirementLedger.removeEpisodePaths(paths)
        val viewerGeneration = strictExactForegroundViewerGenerationAtCreation
        val viewerOwnerPath = strictExactLaunchSeal?.normalizedEpisodePath
            ?: NtkStripDigests.normalizeEpisodePath(initialNtkEpisodePath)
        for (path in paths) {
            if (path.isEmpty() || !consumedStrictSourcePaths.add(path)) continue

            val claim = synchronized(adjacentStrictSourceClaimLock) {
                adjacentStrictRecoveryStates.remove(path)
                adjacentStrictSourceClaims.remove(path)
            }
            cancelAdjacentStrictRecoveryBindDeadline(path)
            claim?.let {
                cancelAdjacentStrictDescriptorWaitWatchdog(path, it)
                synchronized(it.terminalFailureObserved) {
                    it.terminalFailureObserved.set(true)
                    adjacentStrictDescriptorBindingTokens.remove(path, it.descriptorBindingToken)
                }
            }
            runCatching { claim?.sourceEventBinding?.close() }
            runCatching { claim?.residentBinding?.close() }
            adjacentStrictBodyDescriptors.entries.removeIf { it.key.startsWith("$path|") }
            strictAdjacentRehydrateFlights.entries.removeIf { entry ->
                NtkStripDigests.normalizeEpisodePath(
                    entry.value.page.manga.ntkEpisodePath?.trim().orEmpty(),
                ).equals(path, ignoreCase = true)
            }
            adjacentStrictPredecessorPaths.remove(path)
            parkedAdjacentRemainderAppends.remove(path)
            pendingRemainingAdjacentRunwayAppends.remove(path)
            waitingStrictRemainingAdjacentAppends.remove(path)
            strictRemainingAdjacentWakeLatch.cancel(path)
            nearViewportParkedAdjacentWakePaths.remove(path)
            activeRemainingAdjacentRunwayTargetPaths.remove(path)
            initialTailAdjacentPreappendTargetPaths.remove(path)
            initialTailAdjacentPreappendFailedAtMs.remove(path)
            ReaderImageCache.releaseAdjacentNtkForegroundViewerPath(path, "forward_history_consumed")

            val retiredDrawables = ArrayList<PageDecodeResult>()
            preparedAdjacentRemainderDrawables.entries.forEach { entry ->
                if (entry.key.startsWith("$path|") &&
                    preparedAdjacentRemainderDrawables.remove(entry.key, entry.value)
                ) {
                    retiredDrawables += entry.value.result
                }
            }
            retiredDrawables.forEach(::recycleDecodeResult)

            val launchPath = strictExactLaunchSeal?.normalizedEpisodePath
            val launchTransport = if (launchPath?.equals(path, ignoreCase = true) == true) {
                strictExactResidentBodyBinding.getAndSet(null)?.close()
                strictExactSourceBinding.getAndSet(null)?.close()
                strictExactBodyDescriptors.clear()
                releaseStrictRequiredEpisodePath("forward_history_consumed")
                strictExactSourceTransport.getAndSet(null)
            } else {
                null
            }
            val launchGeneration = if (launchTransport != null) {
                strictExactEpisodeToken?.value ?: 0L
            } else {
                0L
            }
            val discoveryGeneration: Long = claim?.episode?.value ?: launchGeneration
            val retiredByCoordinator = NtkStrictEpisodeDiscoveryCoordinator
                .retireConsumedTargetOwnership(
                    path,
                    discoveryGeneration,
                    viewerGeneration,
                    viewerOwnerPath,
                    "forward_history",
                )
            if (!retiredByCoordinator && discoveryGeneration > 0L) {
                NtkSourceSpoolRegistry.retireDiscoveryGenerationForReplacement(
                    path,
                    discoveryGeneration,
                    "strict_exact_consumed_fallback",
                )
            }
            runCatching { (claim?.transport as? Closeable)?.close() }
            runCatching { (launchTransport as? Closeable)?.close() }
            Log.d(
                TAG,
                "reader_consumed_strict_source_retired path=$path," +
                    "generation=$discoveryGeneration,coordinator=$retiredByCoordinator," +
                    "drawables=${retiredDrawables.size}",
            )
        }
    }

    private data class ForwardHistoryTrimCandidate(
        val anchor: Int,
        val removeCount: Int,
        val currentImageOrdinal: Int,
        val pixelRetireBefore: Int,
    )

    private fun forwardHistoryTrimCandidateLocked(
        verifiedAnchor: Int,
        activePage: PageRef,
        requireCompleteSourceStructure: Boolean = true,
    ): ForwardHistoryTrimCandidate? {
        var firstCurrentImage = -1
        var currentImageOrdinal = -1
        var ordinal = 0
        val observedSourcePages = HashSet<Int>()
        for ((index, page) in pages.withIndex()) {
            if (page.transitionTitle != null ||
                !looseSameEpisodeForAppend(page.manga, activePage.manga)
            ) {
                continue
            }
            observedSourcePages.add(page.sourceIndex)
            if (firstCurrentImage < 0) firstCurrentImage = index
            if (index == verifiedAnchor) {
                currentImageOrdinal = ordinal
            }
            ordinal++
        }
        // Adjacent NTK episodes are first published as a tiny runway and then structurally
        // expanded. Moving their prefix while that expansion still holds old global indexes makes
        // later callbacks normalize against the launch episode and can strand the next boundary.
        // Bitmap readiness is not required here, but the complete source-page table is.
        val authoritativeSourceCount = canonicalEpisodeImageCount(activePage.manga, listOf(activePage))
        val terminalShortEpisode = NtkForwardHistoryPolicy.terminalShortEpisodeReached(
            authoritativeSourceCount = authoritativeSourceCount,
            observedSourceIndexes = observedSourcePages,
            activeSourceIndex = activePage.sourceIndex,
        )
        if (
            requireCompleteSourceStructure &&
            authoritativeSourceCount > 0 &&
            observedSourcePages.size < authoritativeSourceCount
        ) {
            return null
        }
        val retainedPreviousEpisodeStart = retainedPreviousEpisodeStartLocked(
            firstCurrentImage,
        )
        val removeCount = NtkForwardHistoryPolicy.removablePrefix(
            firstCurrentImage,
            currentImageOrdinal,
            forwardReading = true,
            retainedPreviousEpisodeStartIndex = retainedPreviousEpisodeStart,
            terminalShortEpisode = terminalShortEpisode,
            // During uninterrupted reading there may be no quiet p2 turn: the first quiet frame
            // is often the successor's p0. Exactly one predecessor remains structurally and
            // physically addressable, so only history older than that predecessor may compact.
            // Decoded-pixel retirement remains gated independently by currentImageOrdinal.
            allowOlderThanRetainedPredecessorBeforePixelThreshold = true,
        )
        val pixelRetireBefore = NtkForwardHistoryPolicy.decodedPixelRetireBefore(
            firstCurrentImage,
            currentImageOrdinal,
            forwardReading = true,
            terminalShortEpisode = terminalShortEpisode,
            retainedPreviousEpisodeStartIndex = retainedPreviousEpisodeStart,
        )
        if (removeCount <= 0 && pixelRetireBefore <= 0) return null
        return ForwardHistoryTrimCandidate(
            anchor = verifiedAnchor,
            removeCount = removeCount,
            currentImageOrdinal = currentImageOrdinal,
            pixelRetireBefore = pixelRetireBefore,
        )
    }

    /**
     * Finds the boundary card (or first image when no card exists) for exactly one predecessor
     * episode. The current episode's own transition card sits immediately before its first image,
     * so skip that card before discovering the predecessor identity. Everything older than the
     * returned index may be removed once the current episode's structure is complete.
     */
    private fun retainedPreviousEpisodeStartLocked(
        firstCurrentImage: Int,
    ): Int = NtkForwardHistoryPolicy.retainedPreviousEpisodeStart(
        pages = pages,
        firstCurrentImageIndex = firstCurrentImage,
        isTransitionCard = { page -> page.transitionTitle != null },
        sameEpisode = { first, second ->
            looseSameEpisodeForAppend(first.manga, second.manga)
        },
    )

    /**
     * Drops decoded pixels for a consumed prefix without changing page indexes or measured page
     * geometry. The Surface keeps each page's authoritative width/height, so this cannot collapse
     * content or expose a transient gap ahead of the forward viewport.
     */
    private fun retireConsumedForwardHistoryPixels(
        retireBefore: Int,
        activePage: PageRef,
        expectedObservationRevision: Long,
        afterSurfaceClears: (() -> Unit)? = null,
    ): Boolean {
        if (retireBefore <= 0) return false
        val releases = ArrayList<BitmapRelease>()
        var retiredBytes = 0L
        synchronized(hostLifecyclePixelLock) {
            if (!hostLifecycleResumed) return false
            synchronized(pagesLock) {
                if (!hostLifecycleResumed || !forwardReadingObservationStillAuthorizesLocked(
                    expectedObservationRevision,
                    activePage,
                ) || pageIndexLocked(activePage, activePage.pageIndex) !in pages.indices
                ) {
                    return false
                }
            val protectedPixelWindow = if (usesProtectedNumericNtkPipeline()) {
                protectedNumericBitmapWindow(pages.size)
            } else {
                IntRange.EMPTY
            }
            synchronized(deliveredBitmaps) {
                // Host-exact tokens are freshly allocated immutable identities and are never
                // published by two pages. Avoid building a whole-survivor IdentityHashMap while
                // pagesLock excludes the input thread when this consumed prefix contains only
                // those tokens. Ordinary shared full-page Bitmaps retain the conservative alias
                // scan below.
                var hostExactPrefixOnly = true
                for ((index, bitmap) in deliveredBitmaps) {
                    if (index < retireBefore && index !in protectedPixelWindow &&
                        !HostExactHardwareTilePool.isActiveToken(bitmap)
                    ) {
                        hostExactPrefixOnly = false
                        break
                    }
                }
                if (hostExactPrefixOnly) {
                    for ((index, tiles) in deliveredTiles) {
                        if (index < retireBefore && index !in protectedPixelWindow &&
                            tiles.any { tile ->
                                !HostExactHardwareTilePool.isActiveToken(tile.bitmap)
                            }
                        ) {
                            hostExactPrefixOnly = false
                            break
                        }
                    }
                }
                val retainedIdentities = if (hostExactPrefixOnly) {
                    null
                } else {
                    java.util.Collections.newSetFromMap(
                        IdentityHashMap<Bitmap, Boolean>()
                    ).also { retained ->
                        for ((index, bitmap) in deliveredBitmaps) {
                            if (index >= retireBefore || index in protectedPixelWindow) {
                                retained.add(bitmap)
                            }
                        }
                        for ((index, tiles) in deliveredTiles) {
                            if (index >= retireBefore || index in protectedPixelWindow) {
                                tiles.forEach { tile -> retained.add(tile.bitmap) }
                            }
                        }
                    }
                }

                val bitmapIterator = deliveredBitmaps.entries.iterator()
                while (bitmapIterator.hasNext()) {
                    val entry = bitmapIterator.next()
                    if (entry.key >= retireBefore || entry.key in protectedPixelWindow) continue
                    val owned = deliveredOwned.remove(entry.key)
                    val preserveStrictReady = pages.getOrNull(entry.key)?.let { page ->
                        page.transitionTitle == null && isStrictExactLaunchPage(page)
                    } == true
                    retiredBytes += trackedBitmapBytes(entry.value)
                    releases.add(
                        bitmapReleaseLocked(
                            index = entry.key,
                            bitmap = entry.value.takeIf { owned &&
                                (retainedIdentities == null || it !in retainedIdentities)
                            },
                            preserveStrictReady = preserveStrictReady,
                        )
                    )
                    deliveredBitmapBytes -= trackedBitmapBytes(entry.value)
                    bitmapIterator.remove()
                }

                val tileIterator = deliveredTiles.entries.iterator()
                while (tileIterator.hasNext()) {
                    val entry = tileIterator.next()
                    if (entry.key >= retireBefore || entry.key in protectedPixelWindow) continue
                    val owned = deliveredOwned.remove(entry.key)
                    val preserveStrictReady = pages.getOrNull(entry.key)?.let { page ->
                        page.transitionTitle == null && isStrictExactLaunchPage(page)
                    } == true
                    retiredBytes += trackedTileBytes(entry.value)
                    if (owned) {
                        if (hostExactPrefixOnly) {
                            for (tile in entry.value) {
                                releases.add(
                                    bitmapReleaseLocked(
                                        index = entry.key,
                                        bitmap = tile.bitmap,
                                        preserveStrictReady = preserveStrictReady,
                                    )
                                )
                            }
                        } else {
                            for (bitmap in uniqueTileBitmaps(entry.value)) {
                                releases.add(
                                    bitmapReleaseLocked(
                                        index = entry.key,
                                        bitmap = bitmap.takeIf { it !in retainedIdentities!! },
                                        preserveStrictReady = preserveStrictReady,
                                    )
                                )
                            }
                        }
                    } else {
                        releases.add(
                            bitmapReleaseLocked(
                                index = entry.key,
                                bitmap = null,
                                preserveStrictReady = preserveStrictReady,
                            )
                        )
                    }
                    deliveredBitmapBytes -= trackedTileBytes(entry.value)
                    tileIterator.remove()
                }
                deliveredBitmapBytes = deliveredBitmapBytes.coerceAtLeast(0L)
            }
            }
        }
        if (releases.isEmpty()) return false
        publishDeliveredBitmapBytes()
        postBitmapReleases(releases) {
            afterSurfaceClears?.invoke()
        }
        Log.d(
            TAG,
            "reader_forward_history_pixels_retired before=$retireBefore," +
                "releases=${releases.size},bytes=$retiredBytes," +
                "path=${activePage.manga.ntkEpisodePath}"
        )
        return true
    }

    private fun scheduleForwardReadingRetry(minimumDelayMs: Long = 0L) {
        if (!forwardReadingRetryPosted.compareAndSet(false, true)) return
        main.postDelayed(
            {
                forwardReadingRetryPosted.set(false)
                if (cancelled.get()) return@postDelayed
                val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: return@postDelayed
                forwardReadingPosition.set(anchor)
                scheduleForwardReadingDrain()
            },
            maxOf(NTK_FORWARD_HISTORY_TRIM_RETRY_MS, minimumDelayMs),
        )
    }

    private fun forwardHistoryHostResumeQuietRemainingMs(): Long {
        val deadline = forwardHistoryHostResumeNotBeforeMs.get()
        if (deadline <= 0L) return 0L
        return (deadline - SystemClock.uptimeMillis()).coerceAtLeast(0L)
    }

    private fun logForwardHistoryTrimDeferralOnce(
        reason: String,
        activePage: PageRef,
        detail: String,
    ) {
        val path = NtkStripDigests.normalizeEpisodePath(
            activePage.manga.ntkEpisodePath.orEmpty(),
        )
        if (!forwardHistoryTrimDeferralLogs.add("$path|$reason")) return
        Log.d(
            TAG,
            "reader_forward_history_prune_deferred reason=$reason,path=$path,$detail",
        )
    }

    private data class CompletedForwardEpisodeSnapshot(
        val episode: Manga,
        val refs: List<IndexedValue<PageRef>>,
        val authoritativeCount: Int,
        val lastDisplayIndex: Int,
    )

    private fun maybeWarmCompletedForwardEpisode(anchor: Int, expectedEpisode: Manga) {
        if (anchor < 0 || reverse || cancelled.get()) return
        val snapshot = publishedPageIndex.get().let { published ->
            val page = published.getOrNull(anchor) ?: return@let null
            if (page.transitionTitle != null ||
                !looseSameEpisodeForAppend(page.manga, expectedEpisode)
            ) {
                return@let null
            }
            val refs = published.withIndex().filter { (_, ref) ->
                ref.transitionTitle == null &&
                    looseSameEpisodeForAppend(ref.manga, page.manga)
            }
            if (refs.isEmpty()) return@let null
            val authoritativeCount = canonicalEpisodeImageCount(
                page.manga,
                refs.map { it.value },
            )
            CompletedForwardEpisodeSnapshot(
                episode = page.manga,
                refs = refs,
                authoritativeCount = authoritativeCount,
                lastDisplayIndex = refs.last().index,
            )
        } ?: return
        val complete = NtkCompletedForwardEpisodePolicy.isComplete(
            authoritativeCount = snapshot.authoritativeCount,
            sourceIndexes = snapshot.refs.map { it.value.sourceIndex },
            drawableReady = snapshot.refs.map { (index, ref) ->
                hasCanonicalDrawableCompletion(ref) ||
                    hasListenerDrawableDelivery(index, ref) ||
                    hasDeliveredBitmap(index)
            },
            requiredFirstSource = requiredForwardFirstSource(
                snapshot.episode,
                snapshot.authoritativeCount,
            ),
        )
        if (!complete) return
        // A physical-tail request can be waiting for this exact predecessor completion. Wake its
        // coalesced mailbox immediately instead of waiting for the low-frequency safety poll. The
        // already-posted delayed callback is harmless: [take] gives only one caller ownership.
        if (deferredAdjacentPrepareMailbox.hasPending()) {
            deferredAdjacentPrepareMailbox.accelerate()?.let { wakeup ->
                postDeferredAdjacentPrepareWakeup(wakeup, 0L)
            }
        }
        val path = snapshot.episode.ntkEpisodePath?.trim().orEmpty()
        if (path.isEmpty()) return
        val attachedForwardPath = forwardNtkEpisodePathAfterSource(snapshot.episode)
        if (attachedForwardPath != null) {
            // A bounded p0..pN runway proves structure, not that the flight's remaining body gate
            // is open. Returning merely because that prefix was attached stranded every suffix
            // request after the user entered the chapter. The exact attached path is stronger
            // authority than a stale speculative claim, and coordinator reconciliation retires
            // any mismatched flight before opening this predecessor/target pair.
            val released = NtkStrictEpisodeDiscoveryCoordinator
                .releaseAdjacentBodiesAfterPredecessorComplete(
                    path,
                    attachedForwardPath,
                    strictExactForegroundViewerGenerationAtCreation,
                    strictExactViewerOwnerEpisodePathAtCreation,
                )
            releaseAdjacentStrictClaimsAfterPredecessorComplete(
                NtkStripDigests.normalizeEpisodePath(path),
            )
            Log.d(
                TAG,
                "ntk_attached_adjacent_body_gate_release predecessor=$path," +
                    "target=$attachedForwardPath,released=$released",
            )
            return
        }
        // A completion retry is only a safety wake. While the exact episode-list or metadata
        // owner is already running, re-entering below rescans the full provider list and launches
        // another doomed numeric preappend on every timer edge. Join the existing owner; its
        // terminal callback explicitly re-enters this gate when more work is actually required.
        if (completionAdjacentEpisodeResolutionPaths.contains(path) ||
            initialAdjacentMetadataPrefetchPaths.contains(path)
        ) return
        // A re-entry can restore every decoded current page before the replacement viewer has
        // installed its own exact source owner.  Starting the adjacent discovery in that gap is
        // unsafe: the ACK browser is process-single-flight, so the newer adjacent generation can
        // supersede the still-running current discovery.  The replacement then has pixels in its
        // page list but no current source/manifest capable of publishing a frame, which presents
        // as a permanently black, motionless reader.  Keep the fully decoded episode warm, but do
        // not let speculative adjacent work outrank the exact foreground owner.
        if (NtkSourceSpoolRegistry.currentAuthoritativeManifest(path) == null) {
            val ownerWaitKey =
                "${ReaderSurfaceView.DIRECTION_NEXT}:$path:complete_idle_current_owner"
            if (completedEpisodeWarmupKeys.add(ownerWaitKey)) {
                Log.d(
                    TAG,
                    "append_adjacent_complete_idle_wait_current_owner source=$path " +
                        "discoveryActive=${NtkSourceSpoolRegistry.isDiscoveryActive(path)}",
                )
                main.postDelayed(
                    {
                        completedEpisodeWarmupKeys.remove(ownerWaitKey)
                        if (!cancelled.get() && isViewportInsideEpisode(snapshot.episode)) {
                            val retryAnchor = currentViewportAnchor.get()
                                .takeIf { it >= 0 }
                                ?: currentStartPage()
                            if (retryAnchor >= 0) {
                                maybeWarmCompletedForwardEpisode(
                                    retryAnchor,
                                    snapshot.episode,
                                )
                            }
                        }
                    },
                    NTK_CURRENT_OWNER_WARMUP_RETRY_MS,
                )
            }
            return
        }
        // Every current-episode drawable is decoded and handed to the Activity at this point.
        // Continuous forward input must not postpone the next-episode metadata/runway
        // indefinitely; the bounded adjacent work runs off-main and no unfinished current image
        // can lose priority.
        val key = "${ReaderSurfaceView.DIRECTION_NEXT}:$path:complete_idle"
        if (!completedEpisodeWarmupKeys.add(key)) return
        Log.d(
            TAG,
            "append_adjacent_complete_idle_warmup_start source=$path,count=${snapshot.refs.size}," +
                "anchor=$anchor,last=${snapshot.lastDisplayIndex}"
        )
        // The Session drawable ledger is the first point at which all current body/decode work is
        // finished. Start the exact next owner here instead of waiting for the Activity to queue
        // every already-decoded current texture. The exact target is reconciled before its body
        // gate opens, so no current network/decode resource can be displaced and a long fling can
        // consume the prepared runway without paying the document/manifest RTT at the boundary.
        val exactTargetPath = startForwardAdjacentExactDiscoveryAtCompletion(
            snapshot.episode,
            resolvedNext = null,
            onResolvedForwardPath = null,
        )
        if (exactTargetPath != null) {
            releaseClaimedForwardAdjacentBodiesAfterPredecessorComplete(path, exactTargetPath)
            releaseAdjacentStrictClaimsAfterPredecessorComplete(path)
        }
        maybeStartInitialTailAdjacentPreappend(
            snapshot.episode,
            snapshot.refs.size - 1,
            snapshot.refs.size,
            NtkAdjacentRunwayPreparationPolicy.CURRENT_EPISODE_COMPLETE_IDLE_REASON,
        )
        main.postDelayed(
            {
                if (!hasForwardNtkEpisodeAfterSource(snapshot.episode)) {
                    completedEpisodeWarmupKeys.remove(key)
                    val retryAnchor = currentViewportAnchor.get()
                        .takeIf { it >= 0 }
                        ?: currentStartPage()
                    if (
                        retryAnchor >= 0 &&
                        isViewportInsideEpisode(snapshot.episode)
                    ) {
                        // A transient document/manifest race must not permanently strand a fully
                        // read episode. Re-entering through the same completion gate keeps the
                        // retry bounded to the current foreground episode and stops immediately
                        // once a real forward runway exists or the viewport leaves this episode.
                        maybeWarmCompletedForwardEpisode(retryAnchor, snapshot.episode)
                    }
                }
            },
            NTK_COMPLETED_EPISODE_WARMUP_RETRY_MS,
        )
    }

    fun containsEpisodeForTest(target: Manga): Boolean = synchronized(pagesLock) {
        containsEpisodeForAppendLocked(target) || containsEpisodeFastLocked(target)
    }

    /**
     * Read-only liveness evidence for an instrumentation failure.  Numeric page state is copied
     * under [pagesLock], then Surface ownership is queried after releasing it so this diagnostic
     * can never participate in the page-table/renderer lock order it is intended to inspect.
     */
    fun pipelineLivenessDiagnosticForTest(): String {
        data class DiagnosticPage(
            val index: Int,
            val page: PageRef,
            val pressureRetired: Boolean,
            val pendingSurfaceRetirement: Boolean,
            val surfaceRetirementInFlight: Boolean,
        )

        val currentAnchor = currentViewportAnchor.get()
        val reported = latestReportedWindow.get()
        val snapshot = synchronized(pagesLock) {
            val reportedAnchor = reported?.anchorPage?.let { page ->
                pageIndexLocked(page, reported.fallbackAnchor)
            } ?: -1
            val requestedFirst = if (reported != null && reportedAnchor in pages.indices) {
                (reportedAnchor + reported.firstOffset).coerceIn(0, pages.lastIndex)
            } else {
                -1
            }
            val requestedLast = if (reported != null && reportedAnchor in pages.indices) {
                (reportedAnchor + reported.lastOffset).coerceIn(requestedFirst, pages.lastIndex)
            } else {
                -1
            }
            val physicalFirst = if (reported != null && reportedAnchor in pages.indices) {
                (reportedAnchor + reported.physicalFirstOffset).coerceIn(0, pages.lastIndex)
            } else {
                -1
            }
            val physicalLast = if (reported != null && reportedAnchor in pages.indices) {
                (reportedAnchor + reported.physicalLastOffset).coerceIn(physicalFirst, pages.lastIndex)
            } else {
                -1
            }
            val interesting = LinkedHashSet<Int>()
            fun addRange(first: Int, last: Int) {
                if (pages.isEmpty() || first < 0 || last < first) return
                for (index in first.coerceAtLeast(0)..last.coerceAtMost(pages.lastIndex)) {
                    interesting += index
                }
            }
            addRange(requestedFirst, requestedLast)
            addRange(physicalFirst, physicalLast)
            addRange(currentAnchor - 3, currentAnchor + 5)
            interesting += hostExactPoolPressureRetiredPages.filter { it in pages.indices }
            interesting += pendingDeliveryWidths.keys.filter { it in pages.indices }
            interesting += loading.filter { it in pages.indices }
            val rows = interesting.sorted().map { index ->
                val page = pages[index]
                DiagnosticPage(
                    index = index,
                    page = page,
                    pressureRetired = hostExactPoolPressureRetiredPages.contains(index),
                    pendingSurfaceRetirement =
                        hostPressurePendingSurfaceRetirements.containsKey(page),
                    surfaceRetirementInFlight =
                        hostPressureSurfaceRetirementsInFlight.contains(page),
                )
            }
            Triple(
                "anchor=$currentAnchor,reportedAnchor=$reportedAnchor," +
                    "requested=$requestedFirst-$requestedLast,physical=$physicalFirst-$physicalLast," +
                    "busy=${reported?.busy},direction=${reported?.directionHint}," +
                    "delivery=$physicalDeliveryFirstPage-$physicalDeliveryLastPage",
                rows,
                pages.size,
            )
        }
        val retained = synchronized(deliveredBitmaps) {
            "$retainedFirstPage-$retainedLastPage@$retainedAnchorPage"
        }
        val rows = snapshot.second.joinToString(";") { row ->
            val page = row.page
            val identity = strictAdjacentRehydrateIdentity(page).orEmpty()
            val flight = identity.takeIf(String::isNotEmpty)?.let(strictAdjacentRehydrateFlights::get)
            val path = NtkStripDigests.normalizeEpisodePath(
                page.manga.ntkEpisodePath?.trim().orEmpty(),
            ).substringAfterLast('/')
            "${row.index}:${page.sourceIndex}@$path{" +
                "card=${page.transitionTitle != null},pressure=${row.pressureRetired}," +
                "surfacePending=${row.pendingSurfaceRetirement}," +
                "surfaceFlight=${row.surfaceRetirementInFlight}," +
                "loading=${loading.contains(row.index)}/${loadingPages[row.index] === page}," +
                "inFlight=${inFlightWidths[row.index] ?: 0}," +
                "pending=${pendingDeliveryWidths[row.index] ?: 0}," +
                "delivered=${hasDeliveredBitmap(row.index)}," +
                "listener=${listener.isPageDrawableInstalled(row.index)}," +
                "authoritative=${listener.isPageAuthoritativeDrawableCurrentlyInstalled(row.index)}," +
                "batch=${isAdjacentDrawableBatchPublicationPending(page)}," +
                "launch=${isStrictExactLaunchPage(page)}," +
                "launchDescriptor=${strictExactBodyDescriptors.containsKey(page.sourceIndex)}," +
                "handoff=${strictExactAuthoritativeHandoffPages.contains(row.index)}," +
                "rollingRehydrate=${strictExactRollingRehydratePages.contains(row.index)}," +
                "protected=${row.index in protectedNumericBitmapWindow(snapshot.third)}," +
                "descriptor=${strictAdjacentBodyDescriptor(page) != null}," +
                "published=${strictAdjacentPublishedBody(page) != null}," +
                "flight=${flight != null}/${flight?.parked?.get()}/" +
                "${flight?.ownerScheduledOrRunning?.get()}}"
        }
        return "pages=${snapshot.third},${snapshot.first},retained=$retained," +
            "batchPublications=${adjacentDrawableBatchPublicationPending.get()}," +
            "rehydrateFlights=${strictAdjacentRehydrateFlights.size},rows=$rows"
    }

    fun hasReadyEpisodeRunwayForTest(target: Manga, minimumReadyImages: Int): Boolean {
        if (minimumReadyImages <= 0) return false
        val runway = synchronized(pagesLock) {
            pages.withIndex()
                .filter { (_, page) ->
                    page.transitionTitle == null &&
                        looseSameEpisodeForAppend(page.manga, target)
                }
                .take(minimumReadyImages)
        }
        val ready = runway.size >= minimumReadyImages && runway.all { (index, page) ->
            hasListenerDrawableDelivery(index, page) || hasDeliveredBitmap(index)
        }
        if (!ready && shouldLogRateLimitedDiagnostic("test_ready_episode_runway")) {
            Log.d(
                TAG,
                "test_ready_episode_runway path=${target.ntkEpisodePath} " +
                    "required=$minimumReadyImages found=${runway.size} entries=" +
                    runway.joinToString(";") { (index, page) ->
                        "$index/${page.sourceIndex}:listener=${hasListenerDrawableDelivery(index, page)}," +
                            "delivered=${hasDeliveredBitmap(index)}," +
                            "canonical=${hasCanonicalDrawableCompletion(page)}," +
                            "surface=${listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)}," +
                            "pending=${pendingDeliveryWidths[index] ?: 0}"
                    },
            )
        }
        return ready
    }

    fun hasPreparedEpisodeRunwayForTest(
        target: Manga,
        minimumPreparedImages: Int,
    ): Boolean {
        if (minimumPreparedImages <= 0) return false
        // A "prepared" adjacent chapter must always prove the canonical p0-p3 runway. Asking for
        // a smaller sample must not accidentally weaken the split/lifecycle precondition.
        val requiredRunwayPages = maxOf(
            NTK_STRICT_OFFSCREEN_PREPARED_RUNWAY_PAGES,
            minimumPreparedImages,
        )
        val snapshot = strictAdjacentPreparedRunwaySnapshot(target, requiredRunwayPages)
            ?: return false
        return NtkStrictOffscreenRemainderParkPolicy.hasPreparedRunway(
            episodePath = snapshot.normalizedPath,
            claimLive = snapshot.claimLive,
            requiredRunwayPages = requiredRunwayPages,
            orderedAttachedSourceIndexes = snapshot.orderedAttachedSourceIndexes,
            liveSourceIndexes = snapshot.liveSourceIndexes,
            recoverableSourceIndexes = snapshot.recoverableSourceIndexes,
        )
    }

    fun hasFullyReadyEpisodeForTest(target: Manga): Boolean {
        val snapshot = synchronized(pagesLock) {
            val refs = pages.withIndex()
                .filter { (_, page) ->
                    page.transitionTitle == null &&
                        looseSameEpisodeForAppend(page.manga, target)
                }
            val authoritativeCount = canonicalEpisodeImageCount(
                refs.firstOrNull()?.value?.manga ?: target,
                refs.map { it.value },
            )
            Pair(refs, authoritativeCount)
        }
        val drawableReady = snapshot.first.map { (index, page) ->
            hasCanonicalDrawableCompletion(page) ||
                hasListenerDrawableDelivery(index, page) ||
                hasDeliveredBitmap(index)
        }
        val complete = NtkCompletedForwardEpisodePolicy.isComplete(
            authoritativeCount = snapshot.second,
            sourceIndexes = snapshot.first.map { it.value.sourceIndex },
            drawableReady = drawableReady,
            requiredFirstSource = requiredForwardFirstSource(
                snapshot.first.firstOrNull()?.value?.manga ?: target,
                snapshot.second,
            ),
        )
        if (!complete && shouldLogRateLimitedDiagnostic(
                "test_fully_ready_episode|${target.ntkEpisodePath}",
            )
        ) {
            val missing = snapshot.first.mapIndexedNotNull { ordinal, (index, page) ->
                if (drawableReady.getOrNull(ordinal) == true) return@mapIndexedNotNull null
                val identity = strictAdjacentRehydrateIdentity(page).orEmpty()
                val flight = strictAdjacentRehydrateFlights[identity]
                "${page.sourceIndex}@${index}{canonical=${hasCanonicalDrawableCompletion(page)}," +
                    "listener=${hasListenerDrawableDelivery(index, page)}," +
                    "delivered=${hasDeliveredBitmap(index)}," +
                    "surface=${listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)}," +
                    "pending=${pendingDeliveryWidths[index] ?: 0}," +
                    "descriptor=${strictAdjacentBodyDescriptor(page) != null}," +
                    "published=${strictAdjacentPublishedBody(page) != null}," +
                    "flight=${flight != null},parked=${flight?.parked?.get()}," +
                    "running=${flight?.ownerScheduledOrRunning?.get()}," +
                    "idleCompletion=${flight?.enteredIdleCompletionIntent?.get()}," +
                    "physical=${flight?.exactAdjacentPhysicalIntent?.get()}," +
                    "compositor=${flight?.compositorForwardWarmIntent?.get()}}"
            }
            Log.d(
                TAG,
                "test_fully_ready_episode path=${target.ntkEpisodePath} " +
                    "authoritative=${snapshot.second},refs=${snapshot.first.size}," +
                    "entered=${latestEnteredExactEpisodePath.get()}," +
                    "viewportBusy=${viewportBusy.get()}," +
                    "motionActive=${NtkReaderTransferPacer.isPhysicalMotionActive()}," +
                    "touchQuietMs=${physicalTouchQuietRemainingMs(NTK_ENTERED_EXACT_PIXEL_COMPLETION_IDLE_MS)}," +
                    "completionOwner=${enteredExactEpisodePixelCompletionPaths.contains(
                        NtkStripDigests.normalizeEpisodePath(target.ntkEpisodePath.orEmpty()),
                    )},missing=${missing.joinToString(";")}",
            )
        }
        return complete
    }

    fun canonicalEpisodeSourceCountForTest(target: Manga): Int = synchronized(pagesLock) {
        val refs = pages.filter { page ->
            page.transitionTitle == null && looseSameEpisodeForAppend(page.manga, target)
        }
        canonicalEpisodeImageCount(refs.firstOrNull()?.manga ?: target, refs)
    }

    fun hasCanonicalEpisodeOrderForTest(target: Manga): Boolean {
        val refs = synchronized(pagesLock) {
            pages.filter { page ->
                page.transitionTitle == null &&
                    looseSameEpisodeForAppend(page.manga, target)
            }
        }
        if (refs.isEmpty() || refs.any { it.sourceIndex < 0 }) return false
        return refs.zipWithNext().all { (previous, next) ->
            next.sourceIndex > previous.sourceIndex ||
                (next.sourceIndex == previous.sourceIndex && next.side >= previous.side)
        }
    }

    fun transitionCardTitleForTest(target: Manga): String? = synchronized(pagesLock) {
        pages.firstOrNull { page ->
            page.transitionTitle != null &&
                looseSameEpisodeForAppend(page.manga, target)
        }?.transitionTitle
    }

    private fun sourcePageIndex(page: PageRef): Int {
        if (page.transitionTitle != null) return 0
        return page.sourceIndex.coerceAtLeast(0)
    }

    private fun displayTotalPages(page: PageRef): Int {
        if (page.transitionTitle != null) return page.totalPages
        val knownCount = page.manga.ntkImageCount
        if (knownCount > 0) return knownCount
        if (isNtkSource(page.manga, title) && page.totalPages >= NTK_UNKNOWN_GENERATED_DISPLAY_THRESHOLD) return 0
        return page.totalPages
    }

    private fun displayEpisodeTitle(pageManga: Manga): String {
        return pageManga.name?.takeIf { it.isNotBlank() }
            ?: title?.name?.takeIf { it.isNotBlank() }
            ?: manga.name?.takeIf { it.isNotBlank() }
            ?: "회차"
    }

    private fun sameEpisode(a: Manga, b: Manga): Boolean {
        if (a === b) return true
        if (a.id == b.id &&
            a.baseMode == b.baseMode &&
            a.titleId == b.titleId &&
            (a.ntkEpisodePath ?: "") == (b.ntkEpisodePath ?: "")
        ) return true
        val first = imageRepository.imageUrls(a, appContext)
        val second = imageRepository.imageUrls(b, appContext)
        return !first.isNullOrEmpty() && first == second
    }

    private fun episodeAppendKey(target: Manga?): String {
        if (target == null) return ""
        val path = target.ntkEpisodePath?.trim().orEmpty()
        if (path.isNotEmpty()) return "ntk:${target.baseMode}:$path"
        val titleId = target.titleId
        if (target.id > 0 && titleId > 0) return "id:${target.baseMode}:$titleId:${target.id}"
        if (target.id > 0) return "id:${target.baseMode}:${target.id}"
        return ""
    }

    private fun trackDeliveredBitmap(index: Int, page: PageRef, bitmap: Bitmap, owned: Boolean): Int {
        val cleared = ArrayList<BitmapRelease>()
        var pressureRejected = false
        val currentIndex = synchronized(pagesLock) {
            val resolvedIndex = pageIndexLocked(page, index)
            if (resolvedIndex < 0) return@synchronized -1
            // The pressure marker is published under pagesLock before Surface is cleared. A
            // decode that was already in flight can reach this central publication seam before
            // the main-thread clear. Never let that stale result repopulate deliveredBitmaps:
            // currentUndeliveredPageIndex() would then suppress the clear and the pooled token
            // would remain owned forever. A real physical re-entry removes the marker before it
            // requests a fresh decode, so this fence does not weaken reverse/forward navigation.
            if (!HostExactHardwareTilePoolPressurePolicy.mayPublishDecodedPixels(
                    hostExactPoolPressureRetiredPages.contains(resolvedIndex),
                )
            ) {
                pressureRejected = true
                return@synchronized -1
            }
            val strictLaunchIndexes = strictExactLaunchDisplayIndexesLocked()
            val protectedLaunchIndexes =
                protectedStrictExactLaunchDisplayIndexes(strictLaunchIndexes)
            val protectedPixelWindow = if (usesProtectedNumericNtkPipeline()) {
                protectedNumericBitmapWindow(pages.size)
            } else {
                IntRange.EMPTY
            }
            val accepted = synchronized(externallyOwnedBitmaps) {
                synchronized(deliveredBitmaps) {
                    if (bitmap.isRecycled || bitmap in surfaceRetirementTransferredBitmaps) {
                        false
                    } else {
                        deliveredDrawableProofWidths[resolvedIndex] = max(1, bitmap.width)
                        val previousOwned = deliveredOwned.remove(resolvedIndex)
                        val previous = deliveredBitmaps.put(resolvedIndex, bitmap)
                        if (previous !== bitmap) {
                            if (previous != null) deliveredBitmapBytes -= trackedBitmapBytes(previous)
                            deliveredBitmapBytes += trackedBitmapBytes(bitmap)
                        }
                        if (previous != null && previous !== bitmap && previousOwned) {
                            addReplacementBitmapReleases(
                                cleared,
                                resolvedIndex,
                                listOf(previous),
                                listOf(bitmap),
                            )
                        }
                        deliveredTiles.remove(resolvedIndex)?.let { removedTiles ->
                            deliveredBitmapBytes -= trackedTileBytes(removedTiles)
                            if (previousOwned) {
                                addReplacementBitmapReleases(
                                    cleared,
                                    resolvedIndex,
                                    removedTiles.map(ReaderTile::bitmap),
                                    listOf(bitmap),
                                )
                            }
                        }
                        deliveredBitmapBytes = deliveredBitmapBytes.coerceAtLeast(0L)
                        if (owned) deliveredOwned.add(resolvedIndex) else deliveredOwned.remove(resolvedIndex)
                        if (deliveredBitmapBytesLocked() > activeBitmapBudgetBytes()) {
                            trimDeliveredBudgetLocked(
                                cleared,
                                protectedLaunchIndexes,
                                strictLaunchIndexes,
                                protectedPixelWindow,
                                protectedDeliveryIndex = resolvedIndex,
                            )
                        }
                        true
                    }
                }
            }
            if (!accepted) return@synchronized -1
            resolvedIndex
        }
        if (currentIndex < 0) {
            if (pressureRejected && owned && !bitmap.isRecycled) recycleBitmapAsync(bitmap)
            return -1
        }
        terminalBitmapRedrivePosted.remove(currentIndex)
        publishDeliveredBitmapBytes()
        postBitmapReleases(cleared)
        if (strictExactDirectWifiRollingPixelResidency.get()) {
            trimDirectWifiLaunchPixelsOutsideWindow()
        }
        return currentIndex
    }

    private fun trackDeliveredResult(
        index: Int,
        page: PageRef,
        result: PageDecodeResult,
        owned: Boolean = true,
    ): Int {
        return when (result) {
            is PageDecodeResult.Full -> trackDeliveredBitmap(index, page, result.bitmap, owned)
            is PageDecodeResult.Tiles -> trackDeliveredTiles(index, page, result.tiles, owned)
        }
    }

    private fun trackDeliveredTiles(
        index: Int,
        page: PageRef,
        tiles: List<ReaderTile>,
        owned: Boolean = true,
    ): Int {
        val cleared = ArrayList<BitmapRelease>()
        val incomingBitmaps = uniqueTileBitmaps(tiles)
        var pressureRejected = false
        val currentIndex = synchronized(pagesLock) {
            val resolvedIndex = pageIndexLocked(page, index)
            if (resolvedIndex < 0) return@synchronized -1
            if (!HostExactHardwareTilePoolPressurePolicy.mayPublishDecodedPixels(
                    hostExactPoolPressureRetiredPages.contains(resolvedIndex),
                )
            ) {
                pressureRejected = true
                return@synchronized -1
            }
            val strictLaunchIndexes = strictExactLaunchDisplayIndexesLocked()
            val protectedLaunchIndexes =
                protectedStrictExactLaunchDisplayIndexes(strictLaunchIndexes)
            val protectedPixelWindow = if (usesProtectedNumericNtkPipeline()) {
                protectedNumericBitmapWindow(pages.size)
            } else {
                IntRange.EMPTY
            }
            val accepted = synchronized(externallyOwnedBitmaps) {
                synchronized(deliveredBitmaps) {
                    if (incomingBitmaps.any { bitmap ->
                            bitmap.isRecycled || bitmap in surfaceRetirementTransferredBitmaps
                        }
                    ) {
                        false
                    } else {
                        deliveredDrawableProofWidths[resolvedIndex] = max(
                            1,
                            tiles.firstOrNull()?.sourceWidth ?: tiles.firstOrNull()?.bitmap?.width ?: 1,
                        )
                        val previousOwned = deliveredOwned.remove(resolvedIndex)
                        val previous = deliveredBitmaps.remove(resolvedIndex)
                        if (previous != null) deliveredBitmapBytes -= trackedBitmapBytes(previous)
                        if (previous != null && previousOwned) {
                            addReplacementBitmapReleases(
                                cleared,
                                resolvedIndex,
                                listOf(previous),
                                incomingBitmaps,
                            )
                        }
                        val previousTiles = deliveredTiles.put(resolvedIndex, tiles)
                        if (previousTiles !== tiles) {
                            if (previousTiles != null) deliveredBitmapBytes -= trackedTileBytes(previousTiles)
                            deliveredBitmapBytes += trackedTileBytes(tiles)
                        }
                        if (previousTiles !== tiles && previousOwned) {
                            addReplacementBitmapReleases(
                                cleared,
                                resolvedIndex,
                                previousTiles.orEmpty().map(ReaderTile::bitmap),
                                incomingBitmaps,
                            )
                        }
                        deliveredBitmapBytes = deliveredBitmapBytes.coerceAtLeast(0L)
                        if (owned) deliveredOwned.add(resolvedIndex) else deliveredOwned.remove(resolvedIndex)
                        if (deliveredBitmapBytesLocked() > activeBitmapBudgetBytes()) {
                            trimDeliveredBudgetLocked(
                                cleared,
                                protectedLaunchIndexes,
                                strictLaunchIndexes,
                                protectedPixelWindow,
                                protectedDeliveryIndex = resolvedIndex,
                            )
                        }
                        true
                    }
                }
            }
            if (!accepted) return@synchronized -1
            resolvedIndex
        }
        if (currentIndex < 0) {
            if (pressureRejected && owned) incomingBitmaps.forEach(::recycleBitmapAsync)
            return -1
        }
        terminalBitmapRedrivePosted.remove(currentIndex)
        publishDeliveredBitmapBytes()
        postBitmapReleases(cleared)
        if (strictExactDirectWifiRollingPixelResidency.get()) {
            trimDirectWifiLaunchPixelsOutsideWindow()
        }
        return currentIndex
    }

    private fun addReplacementBitmapReleases(
        releases: MutableList<BitmapRelease>,
        index: Int,
        candidates: Iterable<Bitmap>,
        retained: Iterable<Bitmap>,
    ) {
        BitmapReleaseIdentityPolicy.uniqueCandidatesExcludingRetained(candidates, retained)
            .forEach { bitmap -> releases.add(BitmapRelease(index, bitmap, clearPage = false)) }
    }

    private fun tryClaimPendingDelivery(delivery: Delivery): Boolean {
        val index = delivery.index
        val width = delivery.result.width
        while (true) {
            val pending = pendingDeliveryWidths[index]
            if (pending == null) {
                if (pendingDeliveryWidths.putIfAbsent(index, width) == null) return true
                continue
            }
            if (strictInlineProofJoinsPendingOriginalPolicy(
                    requiresAuthoritativeInlineTileAck(delivery),
                    delivery.proofDrawable,
                    pending
                )
            ) {
                logNtkPagePerf(
                    index,
                    "strict_inline_proof_join_pending_original",
                    "stage=claim,pending=$pending,width=$width"
                )
                return false
            }
            if (pending >= width) {
                if (
                    pending > width &&
                    delivery.proofDrawable &&
                    !hasDeliveredBitmap(index) &&
                    shouldCommitActiveGeneratedDeliveryNow(delivery, index)
                ) {
                    if (replaceQueuedPendingDeliveryWithProof(delivery, pending)) {
                        return true
                    }
                    logNtkPagePerf(index, "deliver_proof_alongside_pending_full", "pending=$pending,width=$width")
                    return true
                }
                ViewerWarmupManager.logMetric("reader_drop_duplicate_pending_delivery", width.toLong())
                logNtkPagePerf(index, "drop_duplicate_pending_delivery", "pending=$pending,width=$width")
                return false
            }
            val canReplace = shouldDeliverInitialContinuousImmediately(delivery) &&
                !hasDeliveredBitmap(index)
            if (!canReplace) {
                ViewerWarmupManager.logMetric("reader_drop_duplicate_pending_delivery", width.toLong())
                logNtkPagePerf(index, "drop_duplicate_pending_delivery", "pending=$pending,width=$width,replace=false")
                return false
            }
            if (pendingDeliveryWidths.replace(index, pending, width)) {
                takeQueuedVisibleDelivery(index)?.let { stale ->
                    recycleDecodeResult(stale.result)
                    logNtkPagePerf(index, "replace_pending_initial_continuous_delivery", "pending=$pending,width=$width")
                }
                initialContinuousPostedWidthsByIdentity.remove(
                    initialContinuousPostedIdentity(delivery.page),
                )
                return true
            }
        }
    }

    /**
     * Adjacent episodes can be published from two concurrent metadata paths. One path may still
     * carry `ntkImageCount == 0` even though every PageRef was built from a complete, sealed
     * manifest. The immutable manifest count is therefore the structural authority for deciding
     * whether the foreground episode is complete. Treating the initially attached four-page
     * runway as a complete episode starts the following episode too early and can also prune page
     * indexes while the current remainder is still being committed.
     */
    private fun canonicalEpisodeImageCount(source: Manga, refs: Iterable<PageRef>): Int {
        var sealedManifestPageCount = 0
        for (ref in refs) {
            if (ref.transitionTitle != null || !looseSameEpisodeForAppend(ref.manga, source)) continue
            sealedManifestPageCount = maxOf(
                sealedManifestPageCount,
                ref.manifestPageCount.coerceAtLeast(0),
            )
        }
        return NtkAdjacentPartialManifestPolicy.canonicalCompletionPageCount(
            ntkEpisode = isNtkSource(source, title),
            declaredPageCount = source.ntkImageCount,
            sealedManifestPageCount = sealedManifestPageCount,
        )
    }

    fun pageIdentity(index: Int): PageIdentity? {
        val page = (pendingPublishedPageIndex.get() ?: publishedPageIndex.get())
            .getOrNull(index) ?: return null
        return pageIdentity(page)
    }

    /**
     * Records the Activity's post-Surface ACK as the durable canonical completion fact.
     *
     * Worker handoff acceptance is only queue ownership: host-pool pressure may retire the
     * Session-side pixel before that queue reaches Surface, so it cannot be the sole completion
     * edge. Conversely, the Activity must not mutate Session state by numeric index alone. Rebind
     * the callback to the active immutable launch seal and current PageRef before updating the
     * session-lifetime ledger. Pixel eviction may happen immediately after this method returns;
     * the canonical proof intentionally survives it.
     */
    fun markStrictAuthoritativeDrawableInstalled(
        episodePath: String,
        discoveryGeneration: Long,
        manifestDigest: String,
        manifestPageCount: Int,
        index: Int,
    ): Boolean {
        if (cancelled.get() || index < 0) return false
        val normalizedPath = NtkStripDigests.normalizeEpisodePath(episodePath)
        val seal = strictExactLaunchSeal ?: return false
        if (normalizedPath.isEmpty() ||
            seal.normalizedEpisodePath != normalizedPath ||
            seal.discoveryGeneration != discoveryGeneration ||
            seal.manifestDigest != manifestDigest ||
            seal.pageCount != manifestPageCount
        ) return false
        var installedInitialAnchor = false
        val installed = synchronized(pagesLock) {
            val page = pages.getOrNull(index) ?: return@synchronized false
            if (page.transitionTitle != null ||
                !isStrictExactLaunchPage(page) ||
                page.manifestDigest != manifestDigest ||
                page.manifestPageCount != manifestPageCount ||
                !seal.matchesSource(page.sourceIndex, page.canonicalAsset)
            ) return@synchronized false
            markCanonicalDrawableCompletion(index, page)
            hasCanonicalDrawableCompletion(page).also { completed ->
                installedInitialAnchor = completed && index == currentStartPage()
            }
        }
        if (installedInitialAnchor) {
            val firstAck = strictExactInitialAnchorPixelsInstalledAtMs.compareAndSet(
                0L,
                SystemClock.elapsedRealtime(),
            )
            strictExactInitialAnchorPixelsInstalled.countDown()
            if (firstAck) {
                Log.d(
                    TAG,
                    "reader_strict_anchor_install_ack_release page=$index," +
                        "path=$normalizedPath,generation=$discoveryGeneration",
                )
            }
        }
        return installed
    }

    fun pageIdentities(startIndex: Int, count: Int): List<PageIdentity?> {
        if (startIndex < 0 || count <= 0) return emptyList()
        val pageIndex = pendingPublishedPageIndex.get() ?: publishedPageIndex.get()
        val end = minOf(pageIndex.size, startIndex + count)
        if (startIndex >= end) return emptyList()
        return (startIndex until end).map { pageIdentity(pageIndex[it]) }
    }

    /**
     * One-time shape proof for the O(1) forward-resume suffix fast path.
     *
     * The immutable seal counts canonical sources, while the live page table counts display refs.
     * Auto-cut can map one source to two display refs, so a numeric display range of seal.pageCount
     * entries is not a complete source cohort. Only a one-display-per-source launch may publish the
     * suffix token; append-only adjacent refs are ignored because they carry another episode path.
     */
    fun hasCanonicalStrictLaunchDisplayCardinality(
        episodePath: String,
        discoveryGeneration: Long,
        manifestDigest: String,
        manifestPageCount: Int,
    ): Boolean {
        val normalizedPath = NtkStripDigests.normalizeEpisodePath(episodePath)
        if (normalizedPath.isEmpty() || discoveryGeneration <= 0L ||
            manifestDigest.isBlank() || manifestPageCount <= 0
        ) return false
        val seal = strictExactLaunchSeal ?: return false
        if (seal.normalizedEpisodePath != normalizedPath ||
            seal.discoveryGeneration != discoveryGeneration ||
            seal.manifestDigest != manifestDigest || seal.pageCount != manifestPageCount
        ) return false
        val canonical = synchronized(pagesLock) {
            val displayIndexes = ArrayList<Int>(manifestPageCount)
            val sourceIndexes = ArrayList<Int>(manifestPageCount)
            for ((displayIndex, page) in pages.withIndex()) {
                val identity = pageIdentity(page) ?: continue
                if (identity.normalizedEpisodePath != normalizedPath) continue
                if (identity.manifestDigest != manifestDigest ||
                    identity.manifestPageCount != manifestPageCount ||
                    identity.sourcePageIndex !in 0 until manifestPageCount ||
                    identity.canonicalAsset != seal.canonicalAssets[identity.sourcePageIndex]
                ) {
                    return@synchronized false
                }
                displayIndexes.add(displayIndex)
                sourceIndexes.add(identity.sourcePageIndex)
            }
            NtkStrictForwardSuffixFastPathPolicy.hasCanonicalLaunchDisplayShape(
                displayIndexes.toIntArray(),
                sourceIndexes.toIntArray(),
                manifestPageCount,
            )
        }
        if (!canonical) strictForwardSuffixLaunchShapeValid.set(false)
        return canonical
    }

    private fun pageIdentity(page: PageRef): PageIdentity? {
        if (page.transitionTitle != null) return null
        return PageIdentity(
            normalizedEpisodePath = NtkStripDigests.normalizeEpisodePath(
                page.manga.ntkEpisodePath.orEmpty()
            ),
            sourcePageIndex = page.sourceIndex,
            canonicalAsset = page.canonicalAsset,
            manifestDigest = page.manifestDigest.ifBlank {
                strictExactLaunchSeal
                    ?.takeIf { it.matchesEpisodePath(page.manga.ntkEpisodePath) }
                    ?.manifestDigest
                    .orEmpty()
            },
            manifestPageCount = page.manifestPageCount.takeIf { it > 0 }
                ?: strictExactLaunchSeal
                    ?.takeIf { it.matchesEpisodePath(page.manga.ntkEpisodePath) }
                    ?.pageCount
                    ?: 0
        )
    }

    private fun replaceQueuedPendingDeliveryWithProof(delivery: Delivery, pendingWidth: Int): Boolean {
        if (!delivery.proofDrawable) return false
        if (hasDeliveredBitmap(delivery.index)) return false
        if (!shouldCommitActiveGeneratedDeliveryNow(delivery, delivery.index)) return false
        val queued = takeQueuedVisibleDelivery(delivery.index) ?: return false
        if (queued.proofDrawable) {
            storePrimedDelivery(queued)
            return false
        }
        if (pendingDeliveryWidths.replace(delivery.index, pendingWidth, delivery.result.width)) {
            recycleDecodeResult(queued.result)
            logNtkPagePerf(
                delivery.index,
                "replace_pending_full_with_proof",
                "pending=$pendingWidth,width=${delivery.result.width}"
            )
            return true
        }
        storePrimedDelivery(queued)
        return false
    }

    private fun startVerifiedGeneratedCurrentEpisodeStreams() {
        if (strictExactColdRolling) return
        if (!viewerActivated.get() || cancelled.get()) return
        val directManifestCount = ReaderImageCache.trustedNtkImageApiCount(
            manga.ntkEpisodePath,
            SystemClock.elapsedRealtime() - 30_000L
        )
        val nativeDirectManifestComplete = directManifestCount > 0 &&
            ReaderImageCache.hasCompleteValidatedNativeDirectEarlyNtkImageUrls(
                manga.ntkEpisodePath,
                directManifestCount,
                SystemClock.elapsedRealtime() - 30_000L
            )
        if (!isImmediateNtkGeneratedUx() && !nativeDirectManifestComplete) return
        if (!verifiedGeneratedFullStreamStarted.compareAndSet(false, true)) return
        val refs = synchronized(pagesLock) {
            pages.withIndex()
                .filter { (_, page) ->
                    page.transitionTitle == null &&
                        Manga.sameEpisodeIdentity(page.manga, manga) &&
                        page.image?.isNotBlank() == true &&
                        (isNtkGeneratedImageUrl(page.image.orEmpty()) || nativeDirectManifestComplete)
                }
                .map { (index, page) -> index to page }
        }
        if (refs.isEmpty()) {
            verifiedGeneratedFullStreamStarted.set(false)
            return
        }
        val expectedCount = maxOf(initialDeclaredNtkImageCount, manga.ntkImageCount, refs.size)
        val retryWhenStructureExpands = refs.size < expectedCount
        val byteStartedAt = SystemClock.elapsedRealtime()
        val sourceWindow = protectedNumericBitmapWindow(refs.size)
        val sourceRefs = refs.filter { (index, _) -> index in sourceWindow }
        val preparedOwner = ReaderWarmupCoordinator.ownsKnownUrlsDecode(preparedStoreKey)
        val decodeLast = currentStartPage() + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        val preparedContinuationBase = max(
            preparedLaunchDrawableLast.get(),
            preparedStoreDrawableLast.get()
        )
        val preparedContinuationLast = if (preparedContinuationBase >= 0) {
            preparedContinuationBase + NTK_PREPARED_POST_ACTIVATION_CONTINUATION_PAGES
        } else {
            -1
        }
        val launchCriticalSourceLast = maxOf(
            decodeLast,
            preparedContinuationLast,
            (currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()) +
                NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        )
        val decodeRefs = if (preparedOwner) {
            // Staging owns the exact canonical Store set. Before activation this path is bytes
            // only; no extra decoded tile may join the pre-tap surface or prepare target set.
            emptyList()
        } else {
            sourceRefs.filter { (index, _) -> index <= decodeLast }
        }
        // Compressed-byte work must stay ahead of an unrestricted viewport. It runs on the
        // bounded verified fanout/background transport and does not publish geometry or draw on
        // the input thread. Restricting this list until the first touch made the network start only
        // after the prepared pixels were exhausted.
        val foregroundSourceRefs = sourceRefs
        decodeRefs.forEach { (index, page) ->
            registerInitialGeneratedAssetCachedDecode(
                index,
                page,
                "verified_generated_full_stream",
                byteStartedAt,
                proofDrawable = !nativeDirectManifestComplete,
                allowOutsideProofWindow = !nativeDirectManifestComplete,
                allowFullOutsideWindow = nativeDirectManifestComplete
            )
        }
        try {
            verifiedGeneratedFanout.execute {
                var scheduled = 0
                var alreadyReady = 0
                foregroundSourceRefs.forEach { (index, page) ->
                    if (cancelled.get()) return@forEach
                    if (hasPageSourceReady(index, page)) {
                        protectedNumericSourceReadyIndexes.add(index)
                        alreadyReady++
                        return@forEach
                    }
                    val launchCritical = ReaderPipelinePolicy.isNtkLaunchCriticalSource(
                        index,
                        launchCriticalSourceLast
                    )
                    val started = startBoundedForegroundStreamFetch(
                        appContext,
                        page.manga,
                        page.image.orEmpty(),
                        imageCancellation,
                        anchorHedge = false,
                        permit = null,
                        pageIndex = index,
                        visiblePriority = launchCritical,
                        verifiedEpisodeFanout = true
                    )
                    if (started) scheduled++
                    Log.d(
                        TAG,
                        "reader_ntk_verified_generated_stream_submit page=$index,started=$started,total=${refs.size}," +
                            "sourceWindow=${sourceWindow.first}-${sourceWindow.last}"
                    )
                }
                Log.d(
                    TAG,
                    "reader_ntk_verified_generated_full_stream_schedule total=${refs.size}," +
                        "sourceWindow=${sourceWindow.first}-${sourceWindow.last},decode=${decodeRefs.size}," +
                        "preparedOwner=$preparedOwner,scheduled=$scheduled,alreadyReady=$alreadyReady," +
                        "foregroundSources=${foregroundSourceRefs.size}," +
                        "launchCriticalLast=$launchCriticalSourceLast"
                )
            }
        } catch (_: RejectedExecutionException) {
            verifiedGeneratedFullStreamStarted.set(false)
        }
        if (retryWhenStructureExpands) {
            verifiedGeneratedFullStreamStarted.set(false)
            main.postDelayed({
                if (!cancelled.get()) startVerifiedGeneratedCurrentEpisodeStreams()
            }, 80L)
        }
    }

    private fun shouldPreferInFlightNumericManhwaApiManifest(): Boolean {
        val path = manga.ntkEpisodePath.orEmpty()
        if (!path.matches(Regex("^/manhwa/\\d{1,12}/\\d{1,12}(?:[/?#].*)?$"))) return false
        val apiFlight = Manga.isNtkEarlyViewerApiPrefetchInFlight(path)
        val knownCount = manga.ntkImageCount.coerceAtLeast(0)
        val cachedApiManifestReady = ReaderImageCache
            .earlyNtkImageUrls(path, SystemClock.elapsedRealtime() - 30_000L)
            .let { urls ->
                knownCount > 0 && urls.size >= knownCount &&
                    urls.any { !isNtkGeneratedImageUrl(it) }
            }
        if (!apiFlight && !cachedApiManifestReady) return false
        return synchronized(pagesLock) { pages.isNotEmpty() && isGeneratedOnlyNtkRefs(pages) }
    }

    /**
     * The delivery boundary already rejects decoded pixels outside the bounded numeric window.
     * Apply the same decision before allocating tiles: otherwise a fast-fling runway repeatedly
     * decodes an immutable source only to recycle it in [postDecodeResult]. The encoded source
     * remains admitted by the strict rolling window and is decoded when its page becomes eligible.
     */
    private fun shouldSkipDecodeOutsideProtectedNumericWindow(
        index: Int,
        page: PageRef,
        stage: String
    ): Boolean {
        // The strict cold contract owns a sealed full episode and must make every canonical page
        // render-ready even if the user starts moving immediately after the anchor appears. The
        // rolling bitmap window is an eviction policy for ordinary/generated paths; applying it
        // here made offscreen exact pages stay encoded until a later viewport reached them.
        if (strictExactColdRolling) return false
        if (!usesProtectedNumericNtkPipeline(page)) return false
        if (isInsideProtectedNumericBitmapWindow(index, page)) return false
        logNtkPagePerf(index, "decode_skip_outside_bounded_window", "stage=$stage")
        return true
    }

    /**
     * A pressure rehydrate is admitted only after the exact current PageRef intersects the real
     * Surface input window. Carry that single admission across asynchronous delivery; consulting
     * the launch-only snapshot again here would discard the decoded adjacent page. All ordinary
     * deliveries still have to satisfy the unchanged protected numeric window.
     */
    private fun isDeliveryInsideProtectedNumericBitmapWindow(delivery: Delivery): Boolean {
        return delivery.hostPressurePhysicalReentry ||
            delivery.exactAdjacentPhysicalIntent ||
            delivery.compositorForwardWarmIntent ||
            (delivery.startupAdjacentRunway && !physicalScrollEverStarted.get()) ||
            isInsideProtectedNumericBitmapWindow(delivery.index, delivery.page)
    }

    private fun postDecodeResult(delivery: Delivery) {
        val currentDelivery = deliveryAtCurrentIndex(delivery)
        if (currentDelivery == null) {
            recycleDecodeResult(delivery.result)
            return
        }
        if (strictExactColdRolling && isStrictExactLaunchPage(currentDelivery.page) &&
            (!isStrictExactColdPageDemanded(currentDelivery.index) ||
                !isStrictExactIdentityValid(currentDelivery.index, currentDelivery.page))
        ) {
            pendingDeliveryWidths.remove(currentDelivery.index)
            recycleDecodeResult(currentDelivery.result)
            Log.d(
                TAG,
                "reader_ntk_strict_cold_delivery_stale_drop page=${currentDelivery.index},stage=post"
            )
            return
        }
        if (usesProtectedNumericNtkPipeline(currentDelivery.page) &&
            !isDeliveryInsideProtectedNumericBitmapWindow(currentDelivery)
        ) {
            pendingDeliveryWidths.remove(currentDelivery.index)
            recycleDecodeResult(currentDelivery.result)
            logNtkPagePerf(currentDelivery.index, "decode_drop_outside_bounded_window", "stage=post")
            return
        }
        val strictAuthoritativeInstallRequired =
            hasIdentityBoundAdjacentAuthoritativeInstall(currentDelivery) ||
                mustInstallStrictAuthoritativeTilesPolicy(
                    strictInline = requiresAuthoritativeInlineTileAck(currentDelivery),
                    fullQualityTiles = isFullQualityOriginalTileResult(currentDelivery.result),
                    index = currentDelivery.index,
                    physicalFirst = physicalDeliveryFirstPage,
                    physicalLast = physicalDeliveryLastPage
                )
        if (hasDeliveredAtLeast(currentDelivery, currentDelivery.result.width) &&
            !shouldForceInitialAnchorDrawableDelivery(currentDelivery) &&
            !strictAuthoritativeInstallRequired
        ) {
            ViewerWarmupManager.logMetric("reader_drop_duplicate_before_queue", delivery.result.width.toLong())
            recycleDecodeResult(delivery.result)
            return
        }
        if (shouldForceInitialAnchorDrawableDelivery(currentDelivery)) {
            pendingDeliveryWidths.remove(currentDelivery.index)
        }
        if (!tryClaimPendingDelivery(currentDelivery)) {
            recycleDecodeResult(delivery.result)
            return
        }
        val activeGateIndex = currentPageIndex(currentDelivery.page, currentDelivery.index)
        if (activeGateIndex >= 0 &&
            shouldSuppressActiveGeneratedFullDelivery(currentDelivery, activeGateIndex)
        ) {
            logNtkPagePerf(
                activeGateIndex,
                "suppress_active_generated_full_delivery",
                "width=${currentDelivery.result.width},proofWidth=${deliveredDrawableProofWidths[activeGateIndex] ?: 0}"
            )
            pendingDeliveryWidths.remove(currentDelivery.index)
            recycleDecodeResult(currentDelivery.result)
            if (!hasDeliveredBitmap(activeGateIndex) &&
                !hasListenerDrawableDelivery(activeGateIndex, currentDelivery.page)
            ) {
                scheduleVisibleGeneratedCachedDecode(
                    activeGateIndex,
                    currentDelivery.page,
                    "suppress_full_request_proof",
                    SystemClock.elapsedRealtime(),
                    forceRequeue = true,
                    proofDrawable = true
                )
            }
            val fullWidth = achievableWidth(activeGateIndex, targetWidth(false))
            rememberDesiredWidth(activeGateIndex, fullWidth)
            scheduleIdleFullWidthUpgrade(activeGateIndex, fullWidth)
            return
        }
        if (isStructurePublishPending() && !shouldDeliverInitialGeneratedDuringStructurePublish(currentDelivery)) {
            deliveryQueue.add(currentDelivery)
            scheduleDeliveryDrain()
            return
        }
        logNtkPagePerf(currentDelivery.index, "decode_ready", "ms=${SystemClock.elapsedRealtime() - currentDelivery.startedAt},width=${currentDelivery.result.width},retain=${currentDelivery.retainWhenBusy}")
        val currentDirectManifestCount = ReaderImageCache.trustedNtkImageApiCount(
            manga.ntkEpisodePath,
            SystemClock.elapsedRealtime() - 30_000L
        )
        val hasCurrentNativeDirectManifest = currentDirectManifestCount > 0 &&
            ReaderImageCache.hasCompleteValidatedNativeDirectEarlyNtkImageUrls(
                manga.ntkEpisodePath,
                currentDirectManifestCount,
                SystemClock.elapsedRealtime() - 30_000L
            )
        if (isNtkGeneratedImageUrl(currentDelivery.page.image.orEmpty()) || hasCurrentNativeDirectManifest) {
            // A successful decode proves the actual episode extension. Promote
            // it before the remaining full-surface requests are launched so
            // each page uses the exact variant instead of an extension race.
            ReaderImageCache.rememberNtkGeneratedEpisodeExtensionHint(currentDelivery.page.image)
            startVerifiedGeneratedCurrentEpisodeStreams()
        }
        markImmediateGeneratedDecodedReady(currentDelivery)
        val deliverInitialAnchorNow = shouldDeliverInitialAnchorImmediately(currentDelivery)
        val holdInitialNtkDelivery = shouldHoldInitialNtkDelivery(currentDelivery)
        val primeNearAfterInitialAnchorDelivery = deliverInitialAnchorNow &&
            shouldPrimeNtkNearPagesAfterAnchorDecode(currentDelivery)
        if ((!deliverInitialAnchorNow || holdInitialNtkDelivery) &&
            shouldPrepareDecodeResultForDraw(currentDelivery)
        ) {
            prepareDecodeResultForDraw(currentDelivery.result)
        }
        if (holdInitialNtkDelivery) {
            if (!storeInitialHeldDelivery(currentDelivery)) return
            Log.d(
                TAG,
                "reader_initial_hold page=${currentDelivery.index},start=${currentStartPage()},width=${currentDelivery.result.width}"
            )
            if (maybePromoteInitialGeneratedStartToHeld(currentDelivery)) {
                val flushPromoted = Runnable {
                    if (!cancelled.get()) {
                        flushInitialHeldDeliveries("promote")
                    }
                }
                if (!mainImmediate.post(flushPromoted)) {
                    mainImmediate.post(flushPromoted)
                }
                scheduleInitialDeliveryFallback()
                return
            }
            flushInitialViewportIfReady()
            scheduleInitialDeliveryFallback()
            return
        }
        if (deliverInitialAnchorNow) {
            if (!initialAnchorDeliveryPosted.compareAndSet(false, true)) {
                ViewerWarmupManager.logMetric("reader_anchor_delivery_coalesced", currentDelivery.index.toLong())
                logNtkPagePerf(
                    currentDelivery.index,
                    "anchor_delivery_coalesced",
                    "width=${currentDelivery.result.width}"
                )
                pendingDeliveryWidths.remove(currentDelivery.index)
                recycleDecodeResult(currentDelivery.result)
                return
            }
            ViewerWarmupManager.logMetric("reader_anchor_delivery_direct", currentDelivery.index.toLong())
            val preRenderedInitialAnchor = preRenderInitialAnchorDrawable(currentDelivery)
            if (preRenderedInitialAnchor != InitialPrerenderResult.NOT_RENDERED) {
                markDecodedDrawableReady(currentDelivery.index, currentDelivery.page, currentDelivery.result.width)
                synchronized(indexedStateLock) {
                    preRenderedInitialDeliveries.add(currentDelivery.index)
                    if (preRenderedInitialAnchor == InitialPrerenderResult.RENDERED_AND_COMMIT) {
                        preRenderedCommittedDeliveries.add(currentDelivery.index)
                    }
                }
                logFirstBitmapIfNeeded(currentDelivery.startedAt, resultDrawHeightPx(currentDelivery.result))
                markFirstDrawableCommitted(currentDelivery.index, "initial_anchor_prerender")
            }
            val primeNearBeforeAnchorDelivery = primeNearAfterInitialAnchorDelivery &&
                shouldPrimeNtkNearPagesBeforeAnchorDelivery(currentDelivery)
            if (primeNearBeforeAnchorDelivery) {
                primeNtkNearPagesAfterAnchorDecode(currentDelivery.index)
            }
            val queuedAt = SystemClock.elapsedRealtime()
            val deliverAnchor = Runnable {
                val runStartedAt = SystemClock.elapsedRealtime()
                if (cancelled.get()) {
                    pendingDeliveryWidths.remove(currentDelivery.index)
                    recycleDecodeResult(currentDelivery.result)
                    return@Runnable
                }
                val queueMs = SystemClock.elapsedRealtime() - queuedAt
                if (queueMs > 120L) {
                    Log.d(TAG, "reader_anchor_delivery_queue_delay page=${currentDelivery.index},ms=$queueMs,pagesReady=${initialPagesReadyDelivered.get()}")
                }
                val pagesReadyBeforeDrawable =
                    isNtkSource(currentDelivery.page.manga, title) &&
                        currentDelivery.index == 0 &&
                        currentStartPage() == 0
                deliverDecodeResultOnMain(
                    currentDelivery,
                    false,
                    pagesReadyBeforeDrawable = pagesReadyBeforeDrawable
                )
                if (primeNearAfterInitialAnchorDelivery && !primeNearBeforeAnchorDelivery) {
                    val primeNear = Runnable {
                        if (!cancelled.get()) {
                            primeNtkNearPagesAfterAnchorDecode(currentDelivery.index)
                        }
                    }
                    main.post(primeNear)
                }
                val runMs = SystemClock.elapsedRealtime() - runStartedAt
                if (runMs > 32L) {
                    Log.d(TAG, "reader_anchor_delivery_run_ms page=${currentDelivery.index},ms=$runMs")
                }
            }
            val anchorCoalesceDelayMs = initialAnchorCoalesceDelayMs(currentDelivery)
            if (anchorCoalesceDelayMs > 0L) {
                Log.d(
                    TAG,
                    "reader_initial_anchor_coalesce_delay page=${currentDelivery.index}," +
                        "ms=$anchorCoalesceDelayMs"
                )
            }
            val posted = if (anchorCoalesceDelayMs > 0L) {
                mainImmediate.postDelayed(deliverAnchor, anchorCoalesceDelayMs)
            } else {
                mainImmediate.post(deliverAnchor)
            }
            if (!posted) {
                initialAnchorDeliveryPosted.set(false)
                pendingDeliveryWidths.remove(currentDelivery.index)
                recycleDecodeResult(currentDelivery.result)
            }
            return
        }
        if (shouldDeliverInitialContinuousImmediately(currentDelivery)) {
            if (!markInitialContinuousDeliveryPosted(currentDelivery)) {
                ViewerWarmupManager.logMetric("reader_initial_continuous_delivery_coalesced", currentDelivery.index.toLong())
                recycleDecodeResult(currentDelivery.result)
                return
            }
            val preRenderedInitialContinuous = preRenderInitialContinuousDrawable(currentDelivery)
            if (preRenderedInitialContinuous != InitialPrerenderResult.NOT_RENDERED) {
                if (trackDeliveredResult(
                        currentDelivery.index,
                        currentDelivery.page,
                        currentDelivery.result,
                        owned = false,
                    ) < 0
                ) {
                    rollbackPublishedBitmapConflict(
                        currentDelivery.index,
                        currentDelivery.page,
                        currentDelivery.result.width,
                        "initial_continuous_prerender",
                    )
                    return
                }
                markDecodedDrawableReady(currentDelivery.index, currentDelivery.page, currentDelivery.result.width)
                if (shouldCommitFirstDrawableForInitialContinuous(currentDelivery)) {
                    logFirstBitmapIfNeeded(currentDelivery.startedAt, resultDrawHeightPx(currentDelivery.result))
                    markFirstDrawableCommitted(currentDelivery.index, "initial_continuous_prerender")
                }
                Log.d(
                    TAG,
                    "reader_initial_continuous_prerender page=${currentDelivery.index}," +
                        "start=${currentStartPage()},result=$preRenderedInitialContinuous"
                )
                finishPreRenderedInitialContinuousDelivery(currentDelivery)
                return
            }
            if (firstBitmapLogged.get() &&
                (physicalTouchActive.get() || viewportBusy.get())
            ) {
                // InputDispatcher can still be holding a real MOVE while the main MessageQueue
                // already contains image completions. The pointer itself is up between physical
                // swipes, but the Surface keeps the viewport busy for that continuous reading
                // interval; treating that short gap as idle recreated the same 12-page Runnable
                // burst. Preserve the exact delivery and its per-page coalescing identity, but
                // route it through the existing busy drain (one bounded delivery turn per
                // display period).
                // A completion just below the current physical viewport is still part of the
                // exact forward runway. The busy drain may not admit it in this frame, but it
                // must retain the immutable result for the next reported window instead of
                // recycling it and leaving the drawable-prefix scroll cap permanently parked at
                // the episode boundary.
                // markInitialContinuousDeliveryPosted() owns only a Runnable posted directly to
                // main. This branch transfers the decoded result to deliveryQueue instead. Keep
                // the two ownership ledgers disjoint: leaving the posted-width claim behind makes
                // every later exact rehydrate coalesce against a Runnable that does not exist.
                // Remove only this delivery's observed value so a concurrently published wider
                // owner cannot be retired by the handoff.
                initialContinuousPostedWidthsByIdentity.remove(
                    initialContinuousPostedIdentity(currentDelivery.page),
                    currentDelivery.result.width,
                )
                deliveryQueue.add(currentDelivery.copy(retainWhenBusy = true))
                scheduleDeliveryDrain()
                return
            }
            // A strict strip can complete more than one hundred pages within a few seconds. Its
            // exact aggregate readiness ledger remains authoritative, so emitting two synchronous
            // log records for every successful page only steals CPU from decode and main delivery.
            // Preserve the anchor sample and keep all failure/rejection reporting unchanged.
            if (!strictExactColdRolling || currentDelivery.index == currentStartPage()) {
                ViewerWarmupManager.logMetric(
                    "reader_initial_continuous_delivery_direct",
                    currentDelivery.index.toLong()
                )
                Log.d(
                    TAG,
                    "reader_initial_continuous_delivery_direct page=${currentDelivery.index}," +
                        "start=${currentStartPage()},width=${currentDelivery.result.width}"
                )
            }
            val deliverInitialContinuous = Runnable {
                if (cancelled.get()) {
                    pendingDeliveryWidths.remove(currentDelivery.index)
                    initialContinuousPostedWidthsByIdentity.remove(
                        initialContinuousPostedIdentity(currentDelivery.page),
                    )
                    recycleDecodeResult(currentDelivery.result)
                    return@Runnable
                }
                try {
                    MainThreadStallMonitor.trace("reader_initial_continuous_delivery_main") {
                        deliverDecodeResultOnMain(currentDelivery, false)
                    }
                } finally {
                    initialContinuousPostedWidthsByIdentity.remove(
                        initialContinuousPostedIdentity(currentDelivery.page),
                    )
                }
            }
            val delayMs = initialContinuousDeliveryDelayMs(currentDelivery)
            val prioritizeAckIndependentLaunchRunway =
                delayMs == 0L &&
                    shouldDeliverAckIndependentGeneratedRunway(currentDelivery) &&
                    lastUserInteractionMs.get() <= 0L
            val posted = if (delayMs > 0L) {
                main.postDelayed(deliverInitialContinuous, delayMs)
            } else if (prioritizeAckIndependentLaunchRunway) {
                // Before the first gesture, the immutable launch runway must precede unrelated
                // bookkeeping so Activity RESUMED already has real pixels.
                mainImmediate.post(deliverInitialContinuous)
            } else {
                main.post(deliverInitialContinuous)
            }
            if (!posted) {
                pendingDeliveryWidths.remove(currentDelivery.index)
                initialContinuousPostedWidthsByIdentity.remove(
                    initialContinuousPostedIdentity(currentDelivery.page),
                )
                recycleDecodeResult(currentDelivery.result)
            }
            return
        }
        if (shouldDeliverRetainedImmediately(currentDelivery)) {
            ViewerWarmupManager.logMetric("reader_retained_delivery_direct", currentDelivery.index.toLong())
            val deliverRetained = Runnable {
                if (cancelled.get()) {
                    pendingDeliveryWidths.remove(currentDelivery.index)
                    recycleDecodeResult(currentDelivery.result)
                    return@Runnable
                }
                deliverDecodeResultOnMain(currentDelivery, viewportBusy.get())
            }
            val posted = if (shouldAvoidFrontQueueDuringNtkInput(currentDelivery)) {
                main.post(deliverRetained)
            } else {
                mainImmediate.post(deliverRetained)
            }
            if (!posted) {
                pendingDeliveryWidths.remove(currentDelivery.index)
                recycleDecodeResult(currentDelivery.result)
            }
            return
        }
        deliveryQueue.add(currentDelivery)
        scheduleDeliveryDrain()
    }

    private fun finishPreRenderedInitialContinuousDelivery(delivery: Delivery) {
        loading.remove(delivery.index)
        loadingPages.remove(delivery.index)
        loadingStartedAtMs.remove(delivery.index)
        urgentLoading.remove(delivery.index)
        urgentLoadingPages.remove(delivery.index)
        pendingDeliveryWidths.remove(delivery.index)
        failedPages.remove(delivery.index)
        transientGeneratedRetries.remove(delivery.index)
        transientGeneratedVisibleRetries.remove(delivery.index)
        initialContinuousPostedWidthsByIdentity.remove(
            initialContinuousPostedIdentity(delivery.page),
        )
        retryPendingWidthIfNeeded(delivery.index)
        deliverInitialPagesReadyForCurrentPagesIfNeeded()
        logNtkPagePerf(
            delivery.index,
            "initial_continuous_delivery_skip_prerendered",
            "width=${delivery.result.width}"
        )
    }

    private fun preRenderInitialContinuousDrawable(delivery: Delivery): InitialPrerenderResult {
        if (cancelled.get()) return InitialPrerenderResult.NOT_RENDERED
        if (!isInitialContinuousNtkImage(delivery.page)) return InitialPrerenderResult.NOT_RENDERED
        if (Looper.myLooper() != Looper.getMainLooper()) {
            return InitialPrerenderResult.NOT_RENDERED
        }
        if (
            delivery.proofDrawable &&
            isImmediateNtkGeneratedUx() &&
            firstBitmapLogged.get() &&
            isActiveGeneratedInputOrQuietForDelivery()
        ) {
            logNtkPagePerf(
                delivery.index,
                "initial_continuous_prerender_skip_active_proof",
                "width=${delivery.result.width}"
            )
            return InitialPrerenderResult.NOT_RENDERED
        }
        val publication = beginBitmapPublication(delivery.result)
            ?: return InitialPrerenderResult.NOT_RENDERED
        var outcome = InitialPrerenderResult.NOT_RENDERED
        try {
            outcome = when (val result = delivery.result) {
                is PageDecodeResult.Full ->
                    listener.onInitialContinuousPageDecoded(delivery.index, result.bitmap)
                is PageDecodeResult.Tiles ->
                    listener.onInitialContinuousPageTilesDecoded(
                        delivery.index,
                        result.pageWidth,
                        result.pageHeight,
                        result.tiles
                    )
            }
        } catch (e: Throwable) {
            Log.d(
                TAG,
                "reader_initial_continuous_prerender_error page=${delivery.index},error=${e.javaClass.simpleName}"
            )
        } finally {
            finishBitmapPublication(
                publication,
                externallyOwned = outcome != InitialPrerenderResult.NOT_RENDERED,
            )
        }
        return outcome
    }

    private fun shouldDeliverInitialAnchorImmediately(delivery: Delivery): Boolean {
        if (firstDrawableDelivered.get()) return false
        return delivery.index == currentStartPage()
    }

    private fun shouldForceInitialAnchorDrawableDelivery(delivery: Delivery): Boolean {
        if (!isNtkSource(delivery.page.manga, title)) return false
        if (firstDrawableDelivered.get()) return false
        return delivery.index == currentStartPage()
    }

    private fun preRenderInitialAnchorDrawable(delivery: Delivery): InitialPrerenderResult {
        if (cancelled.get()) return InitialPrerenderResult.NOT_RENDERED
        if (!isNtkSource(delivery.page.manga, title)) return InitialPrerenderResult.NOT_RENDERED
        if (delivery.index != currentStartPage()) return InitialPrerenderResult.NOT_RENDERED
        val publication = beginBitmapPublication(delivery.result)
            ?: return InitialPrerenderResult.NOT_RENDERED
        var outcome = InitialPrerenderResult.NOT_RENDERED
        try {
            outcome = when (val result = delivery.result) {
                is PageDecodeResult.Full ->
                    listener.onInitialPageDecoded(delivery.index, result.bitmap)
                is PageDecodeResult.Tiles ->
                    listener.onInitialPageTilesDecoded(
                        delivery.index,
                        result.pageWidth,
                        result.pageHeight,
                        result.tiles
                    )
            }
        } catch (e: Throwable) {
            Log.d(
                TAG,
                "reader_initial_anchor_prerender_error page=${delivery.index},error=${e.javaClass.simpleName}"
            )
        } finally {
            finishBitmapPublication(
                publication,
                externallyOwned = outcome != InitialPrerenderResult.NOT_RENDERED,
            )
        }
        return outcome
    }

    private fun initialAnchorCoalesceDelayMs(delivery: Delivery): Long {
        if (firstBitmapLogged.get()) return 0L
        if (!isNtkSource(manga, title)) return 0L
        if (isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) return 0L
        if (isNtkGeneratedImageUrl(delivery.page.image.orEmpty())) return 0L
        val start = currentStartPage()
        if (delivery.index != start) return 0L
        val firstNext = start + 1
        val secondNext = start + 2
        val firstNextReady = initialDeliveryBacklog.containsKey(firstNext) ||
            (pendingDeliveryWidths[firstNext] ?: 0) > 0
        val secondNextReady = initialDeliveryBacklog.containsKey(secondNext) ||
            (pendingDeliveryWidths[secondNext] ?: 0) > 0
        val firstNextLikelySoon = firstNextReady ||
            loading.contains(firstNext) ||
            urgentLoading.contains(firstNext)
        val secondNextLikelySoon = secondNextReady ||
            loading.contains(secondNext) ||
            urgentLoading.contains(secondNext)
        if (resultDrawHeightPx(delivery.result) < max(1, viewerHeight).toFloat() && firstNextLikelySoon) {
            return NTK_INITIAL_SHORT_ANCHOR_VIEWPORT_COALESCE_MS
        }
        if (!firstNextLikelySoon || !secondNextLikelySoon) return 0L
        if (!initialAnchorCoalesceDelayed.compareAndSet(false, true)) return 0L
        val decodeMs = SystemClock.elapsedRealtime() - delivery.startedAt
        return if (!secondNextReady && decodeMs < NTK_INITIAL_ANCHOR_FAST_COALESCE_MAX_DECODE_MS) {
            NTK_INITIAL_ANCHOR_FAST_COALESCE_MS
        } else {
            NTK_INITIAL_ANCHOR_COALESCE_MS
        }
    }

    private fun shouldDeliverInitialGeneratedDuringStructurePublish(delivery: Delivery): Boolean {
        if (!isNtkSource(delivery.page.manga, title)) return false
        val currentIndex = currentPageIndex(delivery.page, delivery.index)
        if (currentIndex != delivery.index) return false
        // An exact adjacent page can be the pixel prerequisite of the append publication that is
        // currently keeping structurePublishPending non-zero. Its decode was admitted only after
        // this immutable PageRef entered the real physical frontier. Keeping that result queued
        // until every structure owner finishes creates a cycle: the structure owner waits for the
        // page to become ready, while the page delivery waits for the structure owner. Cross only
        // an append-only stable-prefix boundary; a prefix removal/rebase still fails closed.
        if (shouldDeliverMissingPhysicalForwardFrontier(delivery, currentIndex) &&
            canAccessAppendOnlyStablePrefix(currentIndex)
        ) {
            return true
        }
        if (!firstBitmapLogged.get() && delivery.index == currentStartPage()) return true
        if (!isInitialContinuousNtkImage(delivery.page)) return false
        if (!isInitialOrActiveContinuousWindowIndex(delivery.index)) return false
        return true
    }

    private fun shouldAllowInitialRequestDuringStructurePublish(
        index: Int,
        page: PageRef,
        visibleIntent: Boolean
    ): Boolean {
        if (!visibleIntent) return false
        if (!isNtkSource(page.manga, title)) return false
        val start = currentStartPage()
        if (!firstBitmapLogged.get() && index == start) return true
        if (!isInitialContinuousNtkImage(page)) return false
        if (!isInitialOrActiveContinuousWindowIndex(index)) return false
        return currentPageIndex(page, index) == index
    }

    private fun isInitialContinuousNtkImage(page: PageRef): Boolean {
        val image = page.image.orEmpty()
        return isNtkGeneratedImageUrl(image) ||
            ReaderImageCache.isTrustedInitialNtkApiImageForEarlyStream(image) ||
            hasFreshEarlyNtkImageUrlFor(page.manga, image, requireExact = true)
    }

    private fun requiresAuthoritativeInlineTilePage(page: PageRef): Boolean {
        // Strict exact cold sessions must preserve immutable provenance even when no launch subset
        // happened to finish before Activity creation. Otherwise the decode-only full-episode
        // fanout is treated as disposable legacy work and every offscreen page is decoded again.
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(page.manga, title)) return false
        if (!Manga.sameEpisodeIdentity(page.manga, manga)) return false
        // The exact launch seal, rather than the spelling of its canonical URL, is the authority.
        // KP webtoon assets are direct canonical URLs while Booktoki assets are generated URLs;
        // requiring the latter here silently made only the first few webtoon pages persistent.
        if (strictExactColdRolling) return true
        if (preparedLaunchRunwaySpec == null) return false
        return isNtkGeneratedImageUrl(page.image.orEmpty())
    }

    private fun requiresAuthoritativeInlineTileAck(delivery: Delivery): Boolean {
        return delivery.authoritativeAdjacentRehydrate ||
            requiresAuthoritativeInlineTilePage(delivery.page)
    }

    private fun claimStrictInlineOriginalDecode(index: Int, page: PageRef, reason: String): String? {
        if (!requiresAuthoritativeInlineTilePage(page)) return ""
        val pageKey = drawableReadyKey(page) ?: return null
        val asset = ReaderPreparedStore.canonicalOriginalAssetIdentity(page.image)
        if (asset.isEmpty()) return null
        val key = "$pageKey|$asset"
        if (strictInlineOriginalDecodeFlights.tryClaim(key)) return key
        logNtkPagePerf(index, "strict_inline_original_decode_join", "reason=$reason,key=$key")
        return null
    }

    private fun releaseStrictInlineOriginalDecode(key: String?) {
        if (!key.isNullOrEmpty()) strictInlineOriginalDecodeFlights.release(key)
    }

    private fun isFullQualityOriginalTileResult(result: PageDecodeResult): Boolean {
        val tiles = result as? PageDecodeResult.Tiles ?: return false
        if (tiles.decodedWidth != tiles.pageWidth) return false
        if (tiles.originalProof == null) return false
        return AdoptedDrawableIdentity.fullQualityTiles(
            tiles.pageWidth,
            tiles.pageHeight,
            tiles.tiles
        ) != null
    }

    private fun isCanonicalOriginalTileResult(
        result: PageDecodeResult,
        expectedAsset: String?
    ): Boolean {
        val tiles = result as? PageDecodeResult.Tiles ?: return false
        if (!isFullQualityOriginalTileResult(tiles)) return false
        return ReaderPreparedStore.isCanonicalOriginalProof(
            tiles.originalProof,
            expectedAsset,
            tiles.pageWidth,
            tiles.pageHeight
        )
    }

    private fun shouldDeliverStrictInlinePhysicalTilesImmediately(
        delivery: Delivery,
        index: Int = delivery.index
    ): Boolean {
        // The reported physical interval deliberately includes the first clean-prefix blocker.
        // Its numeric delivery window can still end at the preceding drawable until this repair
        // is installed. Preserve the identity-bound admission that was captured before decode;
        // consulting only the later numeric window recreates a closed wait at the chapter tail.
        return hasIdentityBoundAdjacentAuthoritativeInstall(delivery) ||
            strictInlinePhysicalTileDeliveryPolicy(
            strictInline = requiresAuthoritativeInlineTileAck(delivery),
            activeInput = isActiveGeneratedInputOrQuietForDelivery(),
            fullQualityTiles = isFullQualityOriginalTileResult(delivery.result),
            proofDrawable = delivery.proofDrawable,
            index = index,
            physicalFirst = physicalDeliveryFirstPage,
            physicalLast = physicalDeliveryLastPage
        )
    }

    private fun hasIdentityBoundAdjacentAuthoritativeInstall(delivery: Delivery): Boolean {
        return delivery.authoritativeAdjacentRehydrate &&
            (delivery.hostPressurePhysicalReentry || delivery.exactAdjacentPhysicalIntent ||
                delivery.compositorForwardWarmIntent) &&
            isFullQualityOriginalTileResult(delivery.result)
    }

    private fun shouldDeliverInitialContinuousImmediately(delivery: Delivery): Boolean {
        if (shouldDeliverStrictInlinePhysicalTilesImmediately(delivery)) return true
        val ackIndependentRunway = shouldDeliverAckIndependentGeneratedRunway(delivery)
        if (ackIndependentRunway) return true
        if (shouldSuppressActiveGeneratedFullDelivery(delivery, delivery.index)) return false
        if (shouldDeliverPreFirstInitialContinuousNow(delivery)) return true
        if (!firstBitmapLogged.get()) return false
        if (!isNtkSource(manga, title)) return false
        if (!delivery.retainWhenBusy) return false
        val activeContinuousWindow = isInitialOrActiveContinuousWindowIndex(delivery.index)
        if (delivery.proofDrawable && shouldCommitActiveGeneratedDeliveryNow(delivery, delivery.index)) return true
        if (
            isImmediateNtkGeneratedUx() &&
            isNtkGeneratedImageUrl(delivery.page.image.orEmpty()) &&
            !delivery.proofDrawable &&
            !ackIndependentRunway
        ) {
            return false
        }
        if (isActiveGeneratedInputOrQuietForDelivery() &&
            !(delivery.proofDrawable && activeContinuousWindow) &&
            !ackIndependentRunway
        ) {
            return false
        }
        val start = currentStartPage()
        if (!activeContinuousWindow && !ackIndependentRunway) return false
        if (delivery.index <= start && delivery.index != start && !delivery.proofDrawable) return false
        val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: start
        if (delivery.index < viewportAnchor && !delivery.proofDrawable) return false
        if (viewportBusy.get() || ntkInitialInteractiveSettleRemainingMs() > 0L) {
            val ahead = initialContinuousViewportAheadPages()
            if (delivery.index > viewportAnchor + ahead && !ackIndependentRunway) return false
        }
        if (ackIndependentRunway) return true
        if (!initialContinuousDrawableDelivered(start)) return true
        val firstBitmapAt = ntkFirstBitmapAtMs.get()
        if (firstBitmapAt > 0L &&
            SystemClock.uptimeMillis() - firstBitmapAt > NTK_INITIAL_CONTINUOUS_DIRECT_WINDOW_MS
        ) return false
        return true
    }

    private fun shouldDeliverAckIndependentGeneratedRunway(delivery: Delivery): Boolean {
        if (delivery.result !is PageDecodeResult.Tiles) return false
        return isAckIndependentGeneratedRunwayIndex(delivery.index, delivery.page)
    }

    private fun joinExistingPagePipelineOwner(index: Int, page: PageRef, visibleIntent: Boolean): Boolean {
        val pipeline = pagePipeline ?: return false
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        val start = currentStartPage()
        if (index !in start until
            (start + ReaderWarmupCoordinator.authoritativeNtkRunwayDecodePages())
        ) return false
        return joinActivePagePipelineProducer(
            index,
            page,
            if (visibleIntent) "request_visible" else "request_runway"
        )
    }

    private fun joinActivePagePipelineProducer(index: Int, page: PageRef, reason: String): Boolean {
        val pipeline = pagePipeline ?: return false
        val snapshot = pipeline.pageSnapshot(index) ?: return false
        when (snapshot.stage) {
            ReaderPagePipeline.Stage.TILES_READY,
            ReaderPagePipeline.Stage.INSTALL_QUEUED,
            ReaderPagePipeline.Stage.INSTALLED -> {
                pipeline.preparedTilePage(index)?.let {
                    deliverPagePipelineTileIfPhysical(index, page, it)
                }
                logNtkPagePerf(index, "page_pipeline_owner_join", "reason=$reason,state=${snapshot.stage}")
                return true
            }
            ReaderPagePipeline.Stage.BYTE_IN_FLIGHT,
            ReaderPagePipeline.Stage.BYTES_READY,
            ReaderPagePipeline.Stage.DECODE_IN_FLIGHT -> {
                if (pagePipelineSubscribedPages.add(index)) {
                    val subscriberId = pagePipelineSubscriberIds.incrementAndGet()
                    pipeline.subscribeTilePage(index, subscriberId) { tilePage ->
                        pagePipelineSubscribedPages.remove(index)
                        if (cancelled.get()) return@subscribeTilePage
                        val latest = pageRef(index) ?: return@subscribeTilePage
                        if (latest.image.orEmpty() != page.image.orEmpty()) return@subscribeTilePage
                        deliverPagePipelineTileIfPhysical(index, latest, tilePage)
                    }
                }
                logNtkPagePerf(index, "page_pipeline_owner_join", "reason=$reason,state=${snapshot.stage}")
                return true
            }
            else -> return false
        }
    }

    private fun deliverPagePipelineTileIfPhysical(
        index: Int,
        page: PageRef,
        tilePage: ReaderPreparedStore.PreparedTilePage
    ) {
        if (index !in physicalDeliveryFirstPage..physicalDeliveryLastPage) return
        val proof = tilePage.originalProof ?: return
        if (proof.canonicalAsset != ReaderPreparedStore.canonicalOriginalAssetIdentity(page.image)) return
        main.post {
            if (cancelled.get()) return@post
            val latest = pageRef(index) ?: return@post
            if (latest.image.orEmpty() != page.image.orEmpty()) return@post
            listener.onPageBoundsReady(index, tilePage.pageWidth, tilePage.pageHeight)
            listener.onPageLaunchRunwayTilesReady(
                index,
                tilePage.pageWidth,
                tilePage.pageHeight,
                tilePage.tiles
            )
        }
    }

    private fun isAckIndependentGeneratedRunwayIndex(index: Int, page: PageRef): Boolean {
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return false
        // This lane is exclusively for the immutable physical launch runway. Once a real
        // gesture begins, rolling pages must keep the already-stable placeholder geometry;
        // treating a moving viewport as a new "launch" forces a full layout/anchor rebuild on
        // every decoded page and stalls touch delivery.
        if (lastUserInteractionMs.get() > 0L) return false
        val path = manga.ntkEpisodePath?.trim().orEmpty()
        if (path.isEmpty()) return false
        val minCreatedAt = SystemClock.elapsedRealtime() - 30_000L
        val expected = ReaderImageCache.trustedNtkImageApiCount(path, minCreatedAt)
        if (expected <= 0 ||
            !ReaderImageCache.hasCompleteValidatedNativeDirectEarlyNtkImageUrls(
                path,
                expected,
                minCreatedAt
            )
        ) {
            return false
        }
        val start = currentStartPage()
        return index in start..minOf(
            expected - 1,
            start + NTK_ACK_INDEPENDENT_LAUNCH_RUNWAY_PAGES - 1
        )
    }

    private fun shouldCommitFirstDrawableForInitialContinuous(delivery: Delivery): Boolean {
        if (firstDrawableDelivered.get()) return false
        if (!isNtkSource(manga, title)) return false
        if (!isInitialContinuousNtkImage(delivery.page)) return false
        val start = currentStartPage()
        if (delivery.index == start) return true
        if (delivery.index !in start until start + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES) return false
        val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: start
        val visibleRadius = if (isNtkWebtoonSource(manga, title)) 4 else 2
        return delivery.index in max(0, viewportAnchor - 1)..(viewportAnchor + visibleRadius)
    }

    private fun shouldDeliverPreFirstInitialContinuousNow(delivery: Delivery): Boolean {
        if (firstBitmapLogged.get() || ntkFirstBitmapAtMs.get() > 0L) return false
        if (!isNtkSource(manga, title)) return false
        if (!delivery.retainWhenBusy) return false
        val start = currentStartPage()
        val image = delivery.page.image.orEmpty()
        if (!isInitialContinuousNtkImage(delivery.page)) return false
        val runwayPages = if (
            isImmediateNtkGeneratedUx() &&
            isNtkGeneratedImageUrl(image) &&
            isNtkManhwaOrWebtoonEpisodePath(delivery.page.manga.ntkEpisodePath)
        ) {
            ntkPreFirstDrawableRunwayPages()
        } else {
            NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
        }
        if (delivery.index <= start || delivery.index >= start + runwayPages) return false
        if (isFreshExactEarlyNtkImageUrl(delivery.page.manga, image)) return true
        return hasFreshEarlyNtkImageUrlFor(delivery.page.manga, image, requireExact = false)
    }

    private fun initialContinuousDeliveryDelayMs(delivery: Delivery): Long {
        return 0L
    }

    private fun shouldAvoidFrontQueueDuringNtkInput(delivery: Delivery): Boolean {
        if (!delivery.retainWhenBusy) return false
        if (delivery.index == currentStartPage() && !firstDrawableDelivered.get()) return false
        if (isImmediateNtkGeneratedUx() && viewportBusy.get()) {
            val currentIndex = currentPageIndex(delivery.page, delivery.index)
            if (currentIndex >= 0 && shouldCommitActiveGeneratedDeliveryNow(delivery, currentIndex)) {
                return false
            }
            return true
        }
        return shouldAvoidFrontQueueDuringActiveNtkInput()
    }

    private fun shouldAvoidProofFrontQueueDuringNtkInput(delivery: Delivery): Boolean {
        if (!delivery.proofDrawable || !delivery.retainWhenBusy) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (!firstDrawableDelivered.get()) return false
        if (!isNtkSource(delivery.page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(delivery.page.image.orEmpty())) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(delivery.page.manga.ntkEpisodePath)) return false
        return isActiveGeneratedInputOrQuietForDelivery()
    }

    private fun markInitialContinuousDeliveryPosted(delivery: Delivery): Boolean {
        val identity = initialContinuousPostedIdentity(delivery.page)
        while (true) {
            val previous = initialContinuousPostedWidthsByIdentity[identity]
            if (previous == null) {
                if (initialContinuousPostedWidthsByIdentity.putIfAbsent(
                        identity,
                        delivery.result.width,
                    ) == null
                ) return true
                continue
            }
            return previous < delivery.result.width &&
                initialContinuousPostedWidthsByIdentity.replace(
                    identity,
                    previous,
                    delivery.result.width,
                )
        }
    }

    private fun initialContinuousPostedIdentity(page: PageRef): String {
        val path = NtkStripDigests.normalizeEpisodePath(
            page.manga.ntkEpisodePath?.trim().orEmpty(),
        )
        return buildString {
            append(path)
            append('|')
            append(page.manifestDigest)
            append('|')
            append(page.manifestPageCount)
            append('|')
            append(page.sourceIndex)
            append('|')
            append(page.side)
            append('|')
            append(NtkStripDigests.canonicalAssetDigestSha256(page.canonicalAsset))
        }
    }

    private fun shouldPrimeNtkNearPagesAfterAnchorDecode(delivery: Delivery): Boolean {
        if (firstBitmapLogged.get()) return false
        if (delivery.index != currentStartPage()) return false
        if (!isNtkSource(delivery.page.manga, title)) return false
        return initialNearAfterAnchorDecodeStarted.compareAndSet(false, true)
    }

    private fun primeInitialContinuousGeneratedAlongsideAnchor(anchor: Int, reason: String) {
        if (firstBitmapLogged.get()) return
        if (!isNtkSource(manga, title)) return
        if (!isImmediateNtkGeneratedUx()) return
        if (!initialNearAfterAnchorDecodeStarted.compareAndSet(false, true)) return
        main.post {
            if (cancelled.get() || firstBitmapLogged.get()) return@post
            val count = synchronized(pagesLock) { pages.size }
            if (count <= anchor + 1) return@post
            val last = minOf(
                count - 1,
                anchor + NTK_INITIAL_INTERACTIVE_VIEWPORT_AHEAD_PAGES + 1
            )
            var requested = 0
            for (index in (anchor + 1)..last) {
                val page = pageRef(index) ?: continue
                if (!isNtkGeneratedDescriptorOrImagePage(page)) continue
                requestPage(index, busy = true, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
                requested++
            }
            Log.d(
                TAG,
                "reader_ntk_anchor_start_prime_initial_continuous reason=$reason," +
                    "anchor=$anchor,requested=$requested,last=$last"
            )
            ViewerWarmupManager.logMetric("reader_ntk_anchor_start_prime_initial_continuous", requested.toLong())
        }
    }

    private fun shouldPrimeNtkNearPagesBeforeAnchorDelivery(delivery: Delivery): Boolean {
        if (!isNtkSource(delivery.page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(delivery.page.image.orEmpty())) return false
        if (isNtkManhwaOrWebtoonEpisodePath(delivery.page.manga.ntkEpisodePath) &&
            !initialContinuousDrawableDelivered(currentStartPage())
        ) return false
        return isNtkManhwaOrWebtoonEpisodePath(delivery.page.manga.ntkEpisodePath)
    }

    private fun primeNtkNearPagesAfterAnchorDecode(anchor: Int) {
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return
        val holdInitialContinuousTail = shouldHoldNtkGeneratedTailForInitialContinuous()
        val deferWideInitialPrime = isImmediateNtkGeneratedUx() &&
            (viewportBusy.get() || ntkInitialInteractiveSettleRemainingMs() > 0L ||
                ntkBackgroundWarmQuietRemainingMs() > 0L)
        val ahead = if (holdInitialContinuousTail || deferWideInitialPrime) {
            NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        } else if (isNtkWebtoonSource(manga, title)) {
            NTK_INITIAL_ANCHOR_DECODE_WEBTOON_PRIME_PAGES
        } else {
            NTK_INITIAL_ANCHOR_DECODE_PRIME_PAGES
        }
        val last = minOf(count - 1, anchor + ahead)
        if (last <= anchor) return
        for (index in (anchor + 1)..last) {
            requestPage(index, busy = true, anchor = false, generation = FOREGROUND_PRIME_WARM_GENERATION)
        }
        Log.d(
            TAG,
            "reader_ntk_anchor_decode_prime anchor=$anchor count=${last - anchor}," +
                "holdInitialContinuousTail=$holdInitialContinuousTail," +
                "deferWideInitialPrime=$deferWideInitialPrime"
        )
        ViewerWarmupManager.logMetric("reader_ntk_anchor_decode_prime", (last - anchor).toLong())
    }

    private fun shouldDeliverRetainedImmediately(delivery: Delivery): Boolean {
        if (!firstBitmapLogged.get()) return false
        if (!isNtkSource(manga, title)) return false
        val retainedFirst: Int
        val retainedLast: Int
        synchronized(deliveredBitmaps) {
            retainedFirst = retainedFirstPage
            retainedLast = retainedLastPage
        }
        if (!shouldCommitActiveGeneratedDeliveryNow(delivery, delivery.index)) return false
        return delivery.index in retainedFirst..retainedLast
    }

    private fun shouldHoldInitialNtkDelivery(delivery: Delivery): Boolean {
        if (strictExactColdRolling && delivery.index != currentStartPage()) {
            val nowMs = SystemClock.uptimeMillis()
            var resumeAtMs = strictOffscreenPublishResumeAtMs.get()
            if (firstDrawableDelivered.get() &&
                resumeAtMs > nowMs + STRICT_EXACT_FIRST_FRAME_PUBLICATION_GRACE_MS
            ) {
                // firstDrawableDelivered can win through the direct native handoff before the
                // ordinary bitmap callback initializes this deadline. Never let its constructor
                // sentinel become an unbounded p1+ publication hold after exact p0 is on screen.
                val boundedResumeAt = nowMs + STRICT_EXACT_FIRST_FRAME_PUBLICATION_GRACE_MS
                strictOffscreenPublishResumeAtMs.compareAndSet(resumeAtMs, boundedResumeAt)
                resumeAtMs = strictOffscreenPublishResumeAtMs.get()
            }
            if (nowMs < resumeAtMs) return true
        }
        if (shouldDeliverPreFirstInitialContinuousNow(delivery)) return false
        return shouldHoldInitialNtkIndex(delivery.index)
    }

    private fun shouldHoldInitialNtkIndex(index: Int): Boolean {
        if (firstBitmapLogged.get()) return false
        if (ntkFirstBitmapAtMs.get() > 0L) return false
        if (!isNtkSource(manga, title)) return false
        val start = currentStartPage()
        if (index == start) return false
        val firstHeld = if (start <= 0) {
            start + 1
        } else {
            max(0, start - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)
        }
        return index in firstHeld..minOf(start + NTK_INITIAL_PRIORITY_PAGES, start + 12)
    }

    private fun storeInitialHeldDelivery(delivery: Delivery): Boolean {
        while (true) {
            val previous = initialDeliveryBacklog[delivery.index]
            if (previous == null) {
                if (initialDeliveryBacklog.putIfAbsent(delivery.index, delivery) == null) return true
                continue
            }
            if (previous.result.width >= delivery.result.width) {
                recycleDecodeResult(delivery.result)
                return false
            }
            if (initialDeliveryBacklog.replace(delivery.index, previous, delivery)) {
                recycleDecodeResult(previous.result)
                return true
            }
        }
    }

    private fun maybePromoteInitialGeneratedStartToHeld(delivery: Delivery): Boolean {
        if (firstBitmapLogged.get()) return false
        if (!isNtkSource(manga, title)) return false
        if (!isNtkGeneratedImageUrl(delivery.page.image.orEmpty())) return false
        val start = currentStartPage()
        if (hasActiveOrDeliveredPage(start)) {
            Log.d(
                TAG,
                "reader_initial_generated_start_promote_defer oldStart=$start,newStart=${delivery.index}," +
                    "reason=start_active_or_delivered"
            )
            return false
        }
        if (delivery.index <= start) return false
        if (delivery.index > start + NTK_INITIAL_GENERATED_PROMOTE_MAX_AHEAD) return false
        var promotionIndex = delivery.index
        var promotionDelivery = delivery
        if (delivery.index > start + 1 &&
            (!initialHeldViewportReadyFrom(delivery.index) ||
                !initialPromotedScrollCushionReady(delivery.index))
        ) {
            val alternateIndex = findPromotableInitialGeneratedHeldStart(start)
            if (alternateIndex == null) {
                Log.d(
                    TAG,
                    "reader_initial_generated_start_promote_defer oldStart=$start,newStart=${delivery.index}," +
                        "reason=viewport_cushion,height=${resultDrawHeightPx(delivery.result).toInt()},viewport=$viewerHeight"
                )
                return false
            }
            val alternateDelivery = initialDeliveryBacklog[alternateIndex]?.let { deliveryAtCurrentIndex(it) }
                ?: return false
            promotionIndex = alternateIndex
            promotionDelivery = alternateDelivery
        }
        if (initialDeliveryBacklog.containsKey(start) || hasDeliveredBitmap(start)) return false
        val page = pageRef(promotionIndex) ?: return false
        if (page !== promotionDelivery.page) return false
        if (!promoteResolvedInitialStart(start, promotionIndex)) return false
        clearInitialStaleLoadingBeforePromotedStart(start, promotionIndex)
        Log.d(
            TAG,
            "reader_initial_generated_start_promote oldStart=$start,newStart=$promotionIndex," +
                "image=${promotionDelivery.page.image?.substringAfterLast('/')}"
        )
        ViewerWarmupManager.logMetric("reader_initial_generated_start_promote", promotionIndex.toLong())
        return true
    }

    private fun findPromotableInitialGeneratedHeldStart(oldStart: Int): Int? {
        val last = minOf(oldStart + NTK_INITIAL_GENERATED_PROMOTE_MAX_AHEAD, synchronized(pagesLock) { pages.size - 1 })
        for (index in (oldStart + 1)..last) {
            val delivery = initialDeliveryBacklog[index]?.let { deliveryAtCurrentIndex(it) } ?: continue
            if (!isNtkGeneratedImageUrl(delivery.page.image.orEmpty())) continue
            if (index > oldStart + 1 && !initialPreviousPageReadyForPromotedStart(index)) continue
            if (index == oldStart + 1 ||
                (initialHeldViewportReadyFrom(index) && initialPromotedScrollCushionReady(index))
            ) return index
        }
        return null
    }

    private fun initialPreviousPageReadyForPromotedStart(index: Int): Boolean {
        val previousIndex = index - 1
        if (previousIndex < 0) return true
        if (hasDeliveredBitmap(previousIndex)) return true
        val previousDelivery = initialDeliveryBacklog[previousIndex]?.let { deliveryAtCurrentIndex(it) }
            ?: return false
        if (previousDelivery.index != previousIndex) return false
        return resultDrawHeightPx(previousDelivery.result) > 0f
    }

    private fun clearInitialStaleLoadingBeforePromotedStart(oldStart: Int, newStart: Int) {
        if (newStart <= oldStart) return
        for (index in oldStart until newStart) {
            val stalePage = synchronized(pagesLock) { pages.getOrNull(index) } ?: continue
            loading.remove(index)
            loadingPages.remove(index)
            urgentLoading.remove(index)
            urgentLoadingPages.remove(index)
            inFlightWidths.remove(index)
            pendingDeliveryWidths.remove(index)
            if (!hasDeliveredBitmap(index)) {
                val publishClear = object : Runnable {
                    override fun run() {
                        var deferredForStructure = false
                        var cleared = false
                        synchronized(pagesLock) {
                            if (!cancelled.get() && isStructurePublishPending()) {
                                deferredForStructure = true
                            } else if (!cancelled.get()) {
                                val resolvedIndex = pageIndexLocked(stalePage, index)
                                if (resolvedIndex >= 0 && !hasDeliveredBitmap(resolvedIndex)) {
                                    // Hold the structure lock through the Surface mutation. A page
                                    // removal cannot compact a new occupant into this numeric slot
                                    // between exact PageRef resolution and the clear callback.
                                    listener.onPageCleared(resolvedIndex)
                                    cleared = true
                                }
                            }
                        }
                        if (deferredForStructure) {
                            dispatchWhenStructureStable(this)
                            return
                        }
                        if (cleared) {
                            // Proof invalidation is a state transition, not merely a UI callback.
                            // Re-drive the retained window so a clear after the suffix commit's
                            // final token sample cannot leave the missing source without an event.
                            requestRetainedWindowAfterStructureChange()
                        }
                    }
                }
                main.post(publishClear)
            }
        }
        Log.d(TAG, "reader_initial_promote_clear_stale_loading oldStart=$oldStart,newStart=$newStart")
    }

    private fun promoteResolvedInitialStart(oldStart: Int, newStart: Int): Boolean {
        while (true) {
            val resolved = resolvedInitialStartPage.get()
            val current = if (resolved >= 0) resolved else requestedStartPage()
            if (current != oldStart) return false
            val expected = if (resolved >= 0) resolved else -1
            if (resolvedInitialStartPage.compareAndSet(expected, newStart)) return true
        }
    }

    private fun scheduleInitialDeliveryFallback() {
        if (!initialDeliveryFallbackPosted.compareAndSet(false, true)) return
        mainImmediate.postDelayed({
            initialDeliveryFallbackPosted.set(false)
            if (cancelled.get() || firstBitmapLogged.get()) return@postDelayed
            val start = currentStartPage()
            if (!initialDeliveryBacklog.containsKey(start) && !hasDeliveredBitmap(start)) {
                scheduleInitialDeliveryFallback()
                return@postDelayed
            }
            flushInitialHeldDeliveries("fallback")
        }, NTK_INITIAL_DELIVERY_HOLD_FALLBACK_MS)
    }

    private fun promoteVisiblePendingDelivery(index: Int) {
        if (!isNtkSource(manga, title)) return
        if (hasDeliveredBitmap(index)) return
        val queuedAt = SystemClock.elapsedRealtime()
        val deliverVisible = Runnable {
            if (cancelled.get() || hasDeliveredBitmap(index)) return@Runnable
            val queued = takeQueuedVisibleDelivery(index)
            if (queued != null) {
                if (!shouldCommitActiveGeneratedDeliveryNow(queued, queued.index)) {
                    storePrimedDelivery(queued)
                    Log.d(
                        TAG,
                        "reader_visible_pending_promote_defer_active_gate page=${queued.index}," +
                            "ms=${SystemClock.elapsedRealtime() - queuedAt},width=${queued.result.width}"
                    )
                    return@Runnable
                }
                Log.d(
                    TAG,
                    "reader_visible_pending_promote_queued page=${queued.index}," +
                        "ms=${SystemClock.elapsedRealtime() - queuedAt},width=${queued.result.width}"
                )
                deliverDecodeResultOnMain(queued, false)
                return@Runnable
            }
            val prepared = initialPreparedBacklog.remove(index)
            if (prepared != null) {
                Log.d(
                    TAG,
                    "reader_visible_pending_promote_prepared page=$index," +
                        "ms=${SystemClock.elapsedRealtime() - queuedAt}"
                )
                deliverPreparedBitmap(index, prepared.bitmap, prepared.owned, false)
                return@Runnable
            }
            val held = initialDeliveryBacklog.remove(index)?.let { deliveryAtCurrentIndex(it) }
            if (held != null) {
                if (!shouldCommitActiveGeneratedDeliveryNow(held, held.index)) {
                    storePrimedDelivery(held)
                    Log.d(
                        TAG,
                        "reader_visible_pending_promote_defer_active_gate page=${held.index}," +
                            "ms=${SystemClock.elapsedRealtime() - queuedAt},width=${held.result.width}"
                    )
                    return@Runnable
                }
                Log.d(
                    TAG,
                    "reader_visible_pending_promote_decoded page=${held.index}," +
                        "ms=${SystemClock.elapsedRealtime() - queuedAt},width=${held.result.width}"
                )
                deliverDecodeResultOnMain(held, false)
                return@Runnable
            }
            scheduleDeliveryDrain()
        }
        val posted = if (viewportBusy.get() || ntkInitialInteractiveSettleRemainingMs() > 0L) {
            main.post(deliverVisible)
        } else {
            mainImmediate.post(deliverVisible)
        }
        if (!posted) main.post(deliverVisible)
    }

    private fun takeQueuedVisibleDelivery(index: Int): Delivery? {
        primedDeliveryBacklog.remove(index)?.let { primed ->
            return deliveryAtCurrentIndex(primed)
        }
        val iterator = deliveryQueue.iterator()
        while (iterator.hasNext()) {
            val delivery = iterator.next()
            val currentDelivery = deliveryAtCurrentIndex(delivery) ?: continue
            if (currentDelivery.index != index) continue
            if (deliveryQueue.remove(delivery)) return currentDelivery
        }
        return null
    }

    private fun promotePendingStrictInlineOriginalToProof(
        index: Int,
        page: PageRef,
        reason: String
    ): Boolean {
        val queued = takeQueuedVisibleDelivery(index) ?: return false
        if (queued.page !== page ||
            !requiresAuthoritativeInlineTileAck(queued) ||
            !isCanonicalOriginalTileResult(queued.result, page.image)
        ) {
            storePrimedDelivery(queued)
            return false
        }
        val promoted = queued.copy(proofDrawable = true)
        val deliver = Runnable {
            if (cancelled.get()) {
                pendingDeliveryWidths.remove(promoted.index)
                recycleDecodeResult(promoted.result)
                return@Runnable
            }
            deliverDecodeResultOnMain(promoted, viewportBusy.get())
        }
        // FIFO async delivery crosses Choreographer's sync barrier without jumping ahead of
        // touch/frame work that was already queued.
        val posted = mainImmediate.post(deliver)
        if (!posted) {
            storePrimedDelivery(promoted)
            scheduleDeliveryDrain()
        }
        logNtkPagePerf(
            index,
            "strict_inline_pending_original_promoted",
            "reason=$reason,posted=$posted,width=${promoted.result.width}"
        )
        return true
    }

    private fun flushInitialViewportIfReady() {
        if (!isNtkSource(manga, title) || firstBitmapLogged.get()) return
        val start = currentStartPage()
        if (!initialDeliveryBacklog.containsKey(start)) return
        val count = synchronized(pagesLock) { pages.size }
        if (!initialHeldViewportReady(start, count)) return
        mainImmediate.post {
            if (!cancelled.get() && !firstBitmapLogged.get()) {
                flushInitialHeldDeliveries("viewport")
            }
        }
    }

    private fun flushInitialHeldDeliveries(reason: String) {
        if (initialDeliveryBacklog.isEmpty() && initialPreparedBacklog.isEmpty()) return
        if ((reason == "anchor" || reason == "fallback") &&
            isNtkSource(manga, title) &&
            !firstBitmapLogged.get() &&
            !initialStableViewportReadyForFirstFlush()
        ) {
            Log.d(
                TAG,
                "reader_initial_hold_flush_defer reason=$reason,start=${currentStartPage()}," +
                    "backlog=${initialDeliveryBacklog.size},prepared=${initialPreparedBacklog.size}"
            )
            scheduleInitialDeliveryFallback()
            return
        }
        val prepared = initialPreparedBacklog.entries
            .sortedBy { it.key }
            .mapNotNull { entry ->
                val delivery = entry.value
                if (initialPreparedBacklog.remove(entry.key, delivery)) entry.key to delivery else null
            }
        val held = initialDeliveryBacklog.entries
            .sortedBy { it.key }
            .mapNotNull { entry ->
                val delivery = entry.value
                if (initialDeliveryBacklog.remove(entry.key, delivery)) {
                    deliveryAtCurrentIndex(delivery)
                } else {
                    null
                }
            }
        if (held.isEmpty() && prepared.isEmpty()) return
        for ((index, delivery) in prepared) {
            deliverPreparedBitmap(index, delivery.bitmap, delivery.owned, false)
        }
        val deliverHeldNow = (reason == "anchor" || reason == "viewport" || reason == "fallback" ||
            reason == "promote") &&
            Looper.myLooper() == Looper.getMainLooper()
        val immediateHeld = initialHeldDeliveriesForImmediateFlush(held, deliverHeldNow)
        if (deliverHeldNow) {
            initialDeliveryFlushInProgress.set(true)
            try {
                for (delivery in held) {
                    if (delivery.index in immediateHeld) {
                        // These pages were selected by [initialViewportHeldDeliveries] because
                        // their decoded pixels are required to cover the viewport that is about
                        // to be revealed. Activity/input settling must not demote them back into
                        // the primed backlog: doing so leaves an otherwise-ready viewport hidden
                        // until the first-bitmap follow-up grace period expires.
                        deliverDecodeResultOnMain(delivery, busy = false)
                    } else {
                        deliveryQueue.add(delivery)
                    }
                }
            } finally {
                initialDeliveryFlushInProgress.set(false)
            }
        } else {
            for (delivery in held) deliveryQueue.add(delivery)
        }
        Log.d(TAG, "reader_initial_hold_flush reason=$reason,prepared=${prepared.size},decoded=${held.size}")
        if (!deliverHeldNow || held.any { it.index !in immediateHeld }) scheduleDeliveryDrain()
    }

    private fun initialHeldDeliveriesForImmediateFlush(
        held: List<Delivery>,
        deliverHeldNow: Boolean
    ): Set<Int> {
        if (!deliverHeldNow || held.isEmpty()) return emptySet()
        if (strictExactColdRolling) {
            // Strict exact admission promises one immutable, all-page resident scene. A held
            // result has already paid its network, decode and prepare cost; placing an offscreen
            // member back on the interaction-throttled FIFO can make that already-ready bitmap
            // the final scene blocker several seconds later. Publish this small initial cohort as
            // a unit. The ordinary viewer keeps its viewport-only main-thread budget below.
            return held.mapTo(HashSet(held.size)) { it.index }
        }
        return initialViewportHeldDeliveries(held)
    }

    private fun initialStableViewportReadyForFirstFlush(): Boolean {
        val start = currentStartPage()
        val count = synchronized(pagesLock) { pages.size }
        if (!initialHeldViewportReady(start, count)) return false
        if (initialAnchorGeneratedCoversViewport(start)) return true
        return initialPromotedScrollCushionReady(start)
    }

    private fun initialAnchorGeneratedCoversViewport(start: Int): Boolean {
        if (!isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) return false
        val delivery = initialDeliveryBacklog[start]?.let { deliveryAtCurrentIndex(it) } ?: return false
        if (delivery.index != start) return false
        if (!isNtkGeneratedImageUrl(delivery.page.image.orEmpty())) return false
        return resultDrawHeightPx(delivery.result) >= max(1, viewerHeight).toFloat()
    }

    private fun initialHeldViewportReady(start: Int, count: Int): Boolean {
        val held = initialDeliveryBacklog.entries
            .mapNotNull { entry -> deliveryAtCurrentIndex(entry.value) }
            .sortedBy { it.index }
        if (held.isEmpty()) return false
        val byIndex = held.associateBy { it.index }
        var coveredHeight = 0f
        var index = start
        val requiredHeight = max(1, viewerHeight).toFloat()
        while (index < count) {
            val delivery = byIndex[index] ?: return false
            coveredHeight += resultDrawHeightPx(delivery.result)
            if (coveredHeight >= requiredHeight) return true
            if (index >= start + NTK_INITIAL_PRIORITY_PAGES) return true
            index++
        }
        return coveredHeight >= requiredHeight
    }

    private fun initialHeldViewportReadyFrom(startIndex: Int): Boolean {
        val count = synchronized(pagesLock) { pages.size }
        val requiredHeight = max(1, viewerHeight).toFloat()
        var coveredHeight = 0f
        var index = startIndex
        val last = minOf(count - 1, startIndex + NTK_INITIAL_PRIORITY_PAGES)
        while (index <= last) {
            val delivery = initialDeliveryBacklog[index]?.let { deliveryAtCurrentIndex(it) } ?: return false
            if (delivery.index != index) return false
            coveredHeight += resultDrawHeightPx(delivery.result)
            if (coveredHeight >= requiredHeight) return true
            index++
        }
        return coveredHeight >= requiredHeight
    }

    private fun initialPromotedScrollCushionReady(startIndex: Int): Boolean {
        val count = synchronized(pagesLock) { pages.size }
        val last = minOf(count - 1, startIndex + 3)
        for (index in startIndex..last) {
            val delivery = initialDeliveryBacklog[index]?.let { deliveryAtCurrentIndex(it) } ?: return false
            if (delivery.index != index) return false
        }
        return true
    }

    private fun initialViewportHeldDeliveries(held: List<Delivery>): Set<Int> {
        if (held.isEmpty()) return emptySet()
        if (!isNtkSource(manga, title)) return held.mapTo(HashSet()) { it.index }
        val start = currentStartPage()
        val byIndex = held.associateBy { it.index }
        val count = synchronized(pagesLock) { pages.size }
        val requiredHeight = max(1, viewerHeight).toFloat()
        var coveredHeight = 0f
        var promotedPrevious = start
        if (start > 0) {
            val firstPrevious = max(0, start - NTK_INITIAL_CONTINUOUS_PREVIOUS_PAGES)
            for (index in firstPrevious until start) {
                if (byIndex.containsKey(index)) {
                    promotedPrevious = index
                    break
                }
            }
        }
        var firstImmediate = promotedPrevious
        var lastImmediate = start
        var index = promotedPrevious
        val anchorAlreadyDelivered = !byIndex.containsKey(start) && hasDeliveredBitmap(start)
        if (anchorAlreadyDelivered) {
            firstImmediate = if (promotedPrevious < start) promotedPrevious else start + 1
            lastImmediate = start
            index = if (promotedPrevious < start) promotedPrevious else start + 1
        }
        while (index < count) {
            val delivery = byIndex[index] ?: break
            coveredHeight += resultDrawHeightPx(delivery.result)
            lastImmediate = index
            if (index < start + NTK_INITIAL_DIRECT_DELIVERY_PAGES) {
                index++
                continue
            }
            if (!anchorAlreadyDelivered && index >= start + 1 && coveredHeight >= requiredHeight) break
            if (index >= start + NTK_INITIAL_PRIORITY_PAGES) break
            index++
        }
        return held.asSequence()
            .map { it.index }
            .filter { it in firstImmediate..lastImmediate }
            .toHashSet()
    }

    private fun resultDrawHeightPx(result: PageDecodeResult): Float {
        val width = max(1, viewerWidth).toFloat()
        return when (result) {
            is PageDecodeResult.Full -> {
                val bitmapWidth = max(1, result.bitmap.width)
                val bitmapHeight = max(1, result.bitmap.height)
                max(1f, width * bitmapHeight / bitmapWidth.toFloat())
            }
            is PageDecodeResult.Tiles -> {
                val pageWidth = max(1, result.pageWidth)
                val pageHeight = max(1, result.pageHeight)
                max(1f, width * pageHeight / pageWidth.toFloat())
            }
        }
    }

    private fun shouldUseForegroundFetch(
        index: Int,
        page: PageRef,
        anchor: Boolean,
        urgent: Boolean,
        busy: Boolean,
        generation: Int
    ): Boolean {
        if (!page.manga.isOnline) return false
        if (anchor || index == currentStartPage()) return true
        val current = currentStartPage()
        val ntk = isNtkSource(page.manga, title)
        if (ntk &&
            shouldHoldNtkGeneratedTailForInitialContinuous() &&
            index > current + ntkInitialGeneratedRunwayPagesForHold() - 1
        ) {
            return false
        }
        if (isImmediateGeneratedFullSurfacePrimeRequest(index, page, busy, generation)) {
            return true
        }
        if (ntk && isInitialRapidGeneratedUrgent(index, page, busy, generation)) {
            return true
        }
        val foregroundAhead = if (ntk && isNtkWebtoonSource(page.manga, title)) {
            NTK_WEBTOON_FOREGROUND_STREAM_AHEAD_PAGES
        } else {
            NTK_FOREGROUND_STREAM_AHEAD_PAGES
        }
        val generatedPrimeLast = if (ntk && generation == FOREGROUND_PRIME_WARM_GENERATION) {
            ntkGeneratedPrimeForegroundLastIndex(current, foregroundAhead)
        } else {
            current + foregroundAhead
        }
        if (ntk && !firstBitmapLogged.get()) {
            if (
                urgent &&
                busy &&
                generation >= 0 &&
                isNtkWebtoonSource(page.manga, title) &&
                isNtkGeneratedImageUrl(page.image.orEmpty())
            ) {
                val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: current
                val radius = NTK_WEBTOON_BUSY_VISIBLE_DECODE_RADIUS
                if (index in max(0, viewportAnchor - radius)..(viewportAnchor + radius)) {
                    return true
                }
            }
            if (
                urgent &&
                generation == FOREGROUND_PRIME_WARM_GENERATION &&
                index <= generatedPrimeLast &&
                isVerifiedEarlyNtkGeneratedPage(page)
            ) {
                return true
            }
            return urgent &&
                generation == FOREGROUND_PRIME_WARM_GENERATION &&
                ntkCoordinator?.allowsPreAnchorFallback(index, page.image, "shouldUseForegroundFetch") == true
        }
        if (urgent) {
            if (
                ntk &&
                firstBitmapLogged.get() &&
                busy &&
                generation == FOREGROUND_PRIME_WARM_GENERATION &&
                index <= generatedPrimeLast &&
                isNtkGeneratedImageUrl(page.image.orEmpty())
            ) {
                return true
            }
            if (ntk && firstBitmapLogged.get() && busy && generation >= 0) {
                val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: current
                val radius = if (isNtkWebtoonSource(page.manga, title)) {
                    NTK_WEBTOON_ACTIVE_SCROLL_FOREGROUND_RADIUS
                } else {
                    NTK_ACTIVE_SCROLL_FOREGROUND_RADIUS
                }
                return index in max(0, viewportAnchor - radius)..(viewportAnchor + radius)
            }
            return true
        }
        if (generation == FOREGROUND_PRIME_WARM_GENERATION && ntk) {
            return index <= generatedPrimeLast
        }
        if (ntk && index > current + foregroundAhead) {
            return false
        }
        if (!urgent && (!busy || generation == PRIME_WARM_GENERATION)) return false
        val image = page.image
        val requestImage = image ?: return false
        return !ReaderImageCache.hasActiveFetch(page.manga, requestImage)
    }

    private fun isVerifiedEarlyNtkGeneratedPage(page: PageRef): Boolean {
        val image = page.image.orEmpty()
        if (!isNtkGeneratedImageUrl(image)) return false
        return isFreshExactEarlyNtkImageUrl(page.manga, image) ||
            hasFreshEarlyNtkImageUrlFor(page.manga, image, requireExact = false)
    }

    private fun ntkInitialGeneratedRunwayPagesForHold(): Int {
        return if (isImmediateNtkGeneratedUx()) {
            NTK_GENERATED_IMMEDIATE_RUNWAY_PAGES
        } else {
            NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
        }
    }

    private fun ntkGeneratedPrimeForegroundLastIndex(current: Int, foregroundAhead: Int): Int {
        if (!isNtkGeneratedFastParse()) return current + foregroundAhead
        val refs = synchronized(pagesLock) { pages.toList() }
        if (refs.isEmpty() || !isGeneratedOnlyNtkRefs(refs)) return current + foregroundAhead
        if (refs.size <= NTK_FULL_SURFACE_WARM_MAX_PAGES) return refs.lastIndex
        val initialLast = current + NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES - 1
        return maxOf(current + foregroundAhead, initialLast)
    }

    private fun shouldPostPageLoadingState(
        index: Int,
        page: PageRef,
        busy: Boolean,
        anchor: Boolean,
        generation: Int
    ): Boolean {
        if (!isNtkSource(page.manga, title)) return true
        if (!firstBitmapLogged.get()) return true
        if (!busy || generation < 0) return true
        if (anchor) return true
        return index == currentViewportAnchor.get()
    }

    private fun hasDeliveredAtLeast(delivery: Delivery, width: Int): Boolean {
        val currentIndex = synchronized(pagesLock) {
            pageIndexLocked(delivery.page, delivery.index)
        }
        if (currentIndex < 0) return false
        val deliveredWidth = decodedWidths[currentIndex] ?: 0
        if (
            isImmediateNtkGeneratedUx() &&
            isNtkGeneratedDescriptorOrImagePage(delivery.page) &&
            !hasListenerDrawableDelivery(currentIndex, delivery.page)
        ) {
            return false
        }
        return deliveredWidth >= width && hasDeliveredBitmap(currentIndex)
    }

    private fun prepareDecodeResultForDraw(result: PageDecodeResult) {
        when (result) {
            is PageDecodeResult.Full -> prepareBitmapForDraw(result.bitmap)
            is PageDecodeResult.Tiles -> result.tiles.forEach { prepareBitmapForDraw(it.bitmap) }
        }
    }

    private fun shouldPrepareDecodeResultForDraw(delivery: Delivery): Boolean {
        if (!isNtkSource(delivery.page.manga, title)) return true
        if (!isImmediateNtkGeneratedUx() ||
            !isNtkGeneratedDescriptorOrImagePage(delivery.page)
        ) return true

        // Bitmap.prepareToDraw() is a real RenderThread texture upload on HWUI/gfxstream. Keep
        // decoded CPU bitmaps drawable, but never enqueue speculative proof/tail uploads while
        // input is active or in its quiet window. The attached surface prepares the initial real
        // viewport runway in one bounded pass; later decode workers may only prepare the exact
        // current viewport anchor after the interaction has fully settled.
        if (viewportBusy.get()) return false
        if (ntkInitialInteractiveSettleRemainingMs() > 0L) return false
        if (readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L) return false
        if (readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS) > 0L) return false
        val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        return delivery.index == viewportAnchor &&
            !hasListenerDrawableDelivery(delivery.index, delivery.page)
    }

    private fun prepareBitmapForDraw(bitmap: Bitmap) {
        if (bitmap.isRecycled) return
        try {
            bitmap.prepareToDraw()
        } catch (_: Throwable) {
            // Best-effort GPU upload hint; correctness does not depend on it.
        }
    }

    private fun scheduleDeliveryDrain() {
        if (deliveryDrainPosted.compareAndSet(false, true)) {
            val delayMs = deliveryDrainDelayMs()
            if (delayMs > 0L) main.postDelayed(deliveryDrainRunnable, delayMs) else main.post(deliveryDrainRunnable)
        }
    }

    private fun drainDecodeDeliveries() {
        MainThreadStallMonitor.trace("reader_drain_decode_deliveries") {
            deliveryDrainPosted.set(false)
            if (cancelled.get()) {
                recycleQueuedDeliveries()
                return@trace
            }
            if (isStructurePublishPending()) {
                if (deliveryQueue.isNotEmpty() && deliveryDrainPosted.compareAndSet(false, true)) {
                    main.postDelayed(deliveryDrainRunnable, STRUCTURE_PUBLISH_DRAIN_DELAY_MS)
                }
                return@trace
            }
            enqueueRetainedPrimedDeliveries()
            val busy = viewportBusy.get()
            if (busy) {
                deliverBusyDecodeResults()
                if (deliveryQueue.isNotEmpty() && deliveryDrainPosted.compareAndSet(false, true)) {
                    main.postDelayed(deliveryDrainRunnable, BUSY_DELIVERY_DRAIN_DELAY_MS)
                }
                return@trace
            }
            val delayMs = deliveryDrainDelayMs()
            if (delayMs > 0L) {
                if (deliveryQueue.isNotEmpty() && deliveryDrainPosted.compareAndSet(false, true)) {
                    main.postDelayed(deliveryDrainRunnable, delayMs)
                }
                return@trace
            }
            val maxDeliveries = IDLE_DELIVERY_DRAIN_LIMIT
            var deliveredCount = 0
            while (deliveredCount < maxDeliveries) {
                val delivery = deliveryQueue.poll() ?: break
                deliverDecodeResultOnMain(delivery, busy)
                deliveredCount++
            }
            if (deliveryQueue.isNotEmpty() && deliveryDrainPosted.compareAndSet(false, true)) {
                if (viewportBusy.get()) {
                    main.postDelayed(deliveryDrainRunnable, BUSY_DELIVERY_DRAIN_DELAY_MS)
                } else {
                    main.postDelayed(deliveryDrainRunnable, IDLE_DELIVERY_FRAME_DELAY_MS)
                }
            }
        }
    }

    private fun deliveryDrainDelayMs(): Long {
        if (viewportBusy.get()) return BUSY_DELIVERY_DRAIN_DELAY_MS
        if (isImmediateNtkGeneratedUx() && hasQueuedVisibleGeneratedDelivery()) return 0L
        val resumeAt = deliveryResumeAtMs.get()
        val now = SystemClock.uptimeMillis()
        val idleDelay = if (resumeAt == Long.MAX_VALUE) IDLE_DELIVERY_RESUME_DELAY_MS else max(0L, resumeAt - now)
        val inputDelay = max(0L, lastUserInteractionMs.get() + INPUT_PRIORITY_QUIET_MS - now)
        return max(idleDelay, inputDelay)
    }

    private fun hasQueuedVisibleGeneratedDelivery(): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        var checked = 0
        for (delivery in deliveryQueue) {
            if (checked++ >= BUSY_DELIVERY_SCAN_LIMIT) break
            val currentDelivery = deliveryAtCurrentIndex(delivery) ?: continue
            if (!hasDeliveredBitmap(currentDelivery.index) &&
                (shouldCommitActiveGeneratedDeliveryNow(currentDelivery, currentDelivery.index) ||
                    shouldDeliverBusyGeneratedOutsideRetained(currentDelivery, currentDelivery.index))
            ) return true
        }
        for (delivery in primedDeliveryBacklog.values) {
            if (checked++ >= BUSY_DELIVERY_SCAN_LIMIT * 2) break
            val currentDelivery = deliveryAtCurrentIndex(delivery) ?: continue
            if (!hasDeliveredBitmap(currentDelivery.index) &&
                (shouldCommitActiveGeneratedDeliveryNow(currentDelivery, currentDelivery.index) ||
                    shouldDeliverBusyGeneratedOutsideRetained(currentDelivery, currentDelivery.index))
            ) return true
        }
        return false
    }

    private fun deliverBusyDecodeResults() {
        enqueueRetainedPrimedDeliveries()
        val retainedFirst: Int
        val retainedLast: Int
        val retainedAnchor: Int
        synchronized(deliveredBitmaps) {
            retainedFirst = retainedFirstPage
            retainedLast = retainedLastPage
            retainedAnchor = retainedAnchorPage
        }
        val retained = ArrayList<Delivery>(BUSY_DELIVERY_SCAN_LIMIT)
        val startedNs = System.nanoTime()
        var checked = 0
        while (checked < BUSY_DELIVERY_SCAN_LIMIT) {
            if (checked > 0 && System.nanoTime() - startedNs >= BUSY_DELIVERY_DRAIN_BUDGET_NS) break
            val delivery = deliveryQueue.poll() ?: break
            checked++
            val currentDelivery = deliveryAtCurrentIndex(delivery)
            if (currentDelivery == null) {
                pendingDeliveryWidths.remove(delivery.index, delivery.result.width)
                recycleDecodeResult(delivery.result)
                continue
            }
            val index = currentDelivery.index
            if ((index in retainedFirst..retainedLast &&
                    shouldCommitActiveGeneratedDeliveryNow(currentDelivery, index)) ||
                shouldDeliverBusyGeneratedOutsideRetained(currentDelivery, index)
            ) {
                retained.add(currentDelivery)
            } else if (currentDelivery.retainWhenBusy) {
                primedDeliveryBacklog[index] = currentDelivery
            } else {
                pendingDeliveryWidths.remove(index)
                parkUndeliveredHostExactAdjacentForPhysicalRehydrate(currentDelivery)
                recycleDecodeResult(currentDelivery.result)
            }
        }
        retained.sortWith(
            compareByDescending<Delivery> { it.proofDrawable }
                .thenBy { abs(it.index - retainedAnchor) }
                .thenBy { it.startedAt }
        )
        var deliveredProofCount = 0
        var deliveredFullCount = 0
        val activeGeneratedDelivery = isActiveGeneratedInputOrQuietForDelivery()
        for (delivery in retained) {
            if (delivery.proofDrawable && hasDeliveredBitmap(delivery.index) &&
                !requiresStrictAuthoritativeSurfaceRepair(delivery, delivery.index)
            ) {
                pendingDeliveryWidths.remove(delivery.index)
                recycleDecodeResult(delivery.result)
                continue
            }
            if (!delivery.proofDrawable && hasDeliveredAtLeast(delivery, delivery.result.width)) {
                pendingDeliveryWidths.remove(delivery.index)
                recycleDecodeResult(delivery.result)
                continue
            }
            val canDeliver = if (delivery.proofDrawable) {
                deliveredProofCount < BUSY_PROOF_DELIVERY_DRAIN_LIMIT
            } else {
                val visibleUndelivered = activeGeneratedDelivery &&
                    !hasDeliveredBitmap(delivery.index) &&
                    shouldCommitActiveGeneratedDeliveryNow(delivery, delivery.index)
                val surfaceUndelivered = activeGeneratedDelivery &&
                    !hasDeliveredBitmap(delivery.index) &&
                    shouldDeliverBusyGeneratedOutsideRetained(delivery, delivery.index)
                deliveredFullCount < BUSY_DELIVERY_DRAIN_LIMIT &&
                    (!activeGeneratedDelivery || visibleUndelivered || surfaceUndelivered)
            }
            if (canDeliver) {
                deliverDecodeResultOnMain(delivery, true)
                if (delivery.proofDrawable) deliveredProofCount++ else deliveredFullCount++
            } else {
                if (!delivery.proofDrawable && activeGeneratedDelivery && shouldKeepBusyGeneratedPrimed(delivery)) {
                    storePrimedDelivery(delivery)
                } else {
                    deliveryQueue.add(delivery)
                }
            }
        }
    }

    /**
     * A progressive adjacent suffix can finish far ahead of the active drag. Its immutable result
     * must not stay resident merely because the PageRef is already appended, but discarding it
     * without the same park used by pool-pressure eviction leaves no route allowed to decode that
     * strict-owned page again. Record the exact PageRef before returning its slots; the bounded
     * physical-forward window becomes the only authority that can rehydrate it later.
     */
    private fun parkUndeliveredHostExactAdjacentForPhysicalRehydrate(delivery: Delivery) {
        val tiles = (delivery.result as? PageDecodeResult.Tiles)?.tiles ?: return
        if (tiles.isEmpty() || tiles.any { tile ->
                !HostExactHardwareTilePool.isActiveToken(tile.bitmap)
            }
        ) return
        if (strictAdjacentRehydrateIdentity(delivery.page) == null) return
        synchronized(pagesLock) {
            val currentIndex = pageIndexLocked(delivery.page, delivery.index)
            if (currentIndex < 0 || strictAdjacentRehydrateIdentity(pages[currentIndex]) == null) {
                return@synchronized
            }
            hostExactPoolPressureRetiredPages.add(currentIndex)
        }
    }

    private fun enqueueRetainedPrimedDeliveries() {
        if (primedDeliveryBacklog.isEmpty()) return
        val retainedFirst: Int
        val retainedLast: Int
        synchronized(deliveredBitmaps) {
            retainedFirst = retainedFirstPage
            retainedLast = retainedLastPage
        }
        val nowMs = SystemClock.uptimeMillis()
        for ((key, delivery) in primedDeliveryBacklog.entries) {
            val retryAt = authoritativeTileInstallRetryAtMs[key]
            if (retryAt != null && (retryAt == Long.MAX_VALUE || nowMs < retryAt)) continue
            val currentDelivery = deliveryAtCurrentIndex(delivery)
            if (currentDelivery == null) {
                if (primedDeliveryBacklog.remove(key, delivery)) recycleDecodeResult(delivery.result)
                continue
            }
            val index = currentDelivery.index
            if ((index in retainedFirst..retainedLast ||
                    shouldDeliverBusyGeneratedOutsideRetained(currentDelivery, index)) &&
                primedDeliveryBacklog.remove(key, delivery)
            ) {
                deliveryQueue.add(currentDelivery)
            } else if (index != key && primedDeliveryBacklog.remove(key, delivery)) {
                primedDeliveryBacklog[index] = currentDelivery
            }
        }
    }

    private fun deliverDecodeResultOnMain(
        delivery: Delivery,
        busy: Boolean,
        pagesReadyBeforeDrawable: Boolean = true,
        allowDuringStructurePublish: Boolean = false,
        authoritativePrepared: Boolean = false
    ) {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            val deliver = Runnable {
                deliverDecodeResultOnMain(
                    delivery,
                    busy,
                    pagesReadyBeforeDrawable,
                    allowDuringStructurePublish,
                    authoritativePrepared
                )
            }
            val posted = if (shouldDeliverStrictInlinePhysicalTilesImmediately(delivery)) {
                // Full-quality original physical-runway tiles must cross Choreographer's sync
                // barrier, while FIFO ordering keeps already-queued touch/frame work ahead.
                mainImmediate.post(deliver)
            } else if (delivery.proofDrawable &&
                !shouldAvoidProofFrontQueueDuringNtkInput(delivery)
            ) {
                mainImmediate.post(deliver)
            } else if (isActiveGeneratedInputOrQuietForDelivery() ||
                shouldAvoidFrontQueueDuringNtkInput(delivery)
            ) {
                main.post(deliver)
            } else {
                mainImmediate.post(deliver)
            }
            if (!posted) {
                pendingDeliveryWidths.remove(delivery.index)
                recycleDecodeResult(delivery.result)
            }
            return
        }
        val deliveryMainStartedNs = SystemClock.elapsedRealtimeNanos()
        var deliveryTrackNs = 0L
        var deliveryListenerNs = 0L
        val currentDelivery = deliveryAtCurrentIndex(delivery)
        val deliveryLookupNs = SystemClock.elapsedRealtimeNanos() - deliveryMainStartedNs
        if (currentDelivery == null) {
            pendingDeliveryWidths.remove(delivery.index, delivery.result.width)
            recycleDecodeResult(delivery.result)
            return
        }
        if (strictExactColdRolling && isStrictExactLaunchPage(currentDelivery.page) &&
            (!isStrictExactColdPageDemanded(currentDelivery.index) ||
                !isStrictExactIdentityValid(currentDelivery.index, currentDelivery.page))
        ) {
            pendingDeliveryWidths.remove(currentDelivery.index)
            recycleDecodeResult(currentDelivery.result)
            Log.d(
                TAG,
                "reader_ntk_strict_cold_delivery_stale_drop page=${currentDelivery.index},stage=main"
            )
            return
        }
        if (!authoritativePrepared &&
            usesProtectedNumericNtkPipeline(currentDelivery.page) &&
            !isDeliveryInsideProtectedNumericBitmapWindow(currentDelivery)
        ) {
            pendingDeliveryWidths.remove(currentDelivery.index)
            recycleDecodeResult(currentDelivery.result)
            logNtkPagePerf(currentDelivery.index, "decode_drop_outside_bounded_window", "stage=main")
            return
        }
        if (cancelled.get()) {
            pendingDeliveryWidths.remove(currentDelivery.index)
            recycleDecodeResult(currentDelivery.result)
            return
        }
        if (!allowDuringStructurePublish &&
            isStructurePublishPending() &&
            !shouldDeliverInitialGeneratedDuringStructurePublish(currentDelivery)
        ) {
            deliveryQueue.add(currentDelivery)
            scheduleDeliveryDrain()
            return
        }
        val retainedFirst: Int
        val retainedLast: Int
        synchronized(deliveredBitmaps) {
            retainedFirst = retainedFirstPage
            retainedLast = retainedLastPage
        }
        val knownIndex = currentDelivery.index
        val allowBusyGeneratedDelivery = shouldDeliverBusyGeneratedOutsideRetained(currentDelivery, knownIndex)
        val activeGeneratedDeliveryQuiet = !busy &&
            isActiveGeneratedInputOrQuietForDelivery() &&
            shouldKeepBusyGeneratedPrimed(currentDelivery)
        if (activeGeneratedDeliveryQuiet &&
            !shouldCommitActiveGeneratedDeliveryNow(currentDelivery, knownIndex)
        ) {
            storePrimedDelivery(currentDelivery)
            Log.d(
                TAG,
                "reader_active_generated_delivery_primed page=${currentDelivery.index}," +
                    "width=${currentDelivery.result.width}"
            )
            return
        }
        if (busy && !allowBusyGeneratedDelivery && !shouldCommitActiveGeneratedDeliveryNow(currentDelivery, knownIndex)) {
            if (shouldKeepBusyGeneratedPrimed(currentDelivery)) {
                storePrimedDelivery(currentDelivery)
                Log.d(
                    TAG,
                    "reader_busy_generated_delivery_primed_active_gate page=${currentDelivery.index}," +
                        "width=${currentDelivery.result.width}"
                )
                return
            }
        }
        if (busy && knownIndex !in retainedFirst..retainedLast && !allowBusyGeneratedDelivery) {
            if (shouldKeepBusyGeneratedPrimed(currentDelivery)) {
                storePrimedDelivery(currentDelivery)
                Log.d(
                    TAG,
                    "reader_busy_generated_delivery_primed page=${currentDelivery.index}," +
                        "width=${currentDelivery.result.width}"
                )
                return
            }
            pendingDeliveryWidths.remove(currentDelivery.index)
            recycleDecodeResult(currentDelivery.result)
            return
        }
        var droppedLowerWidth = false
        val deliveryIndexStartedNs = SystemClock.elapsedRealtimeNanos()
        val currentIndex = synchronized(pagesLock) {
            val index = pageIndexForDeliveryLocked(currentDelivery, knownIndex)
            if (index >= 0 &&
                (!busy || index in retainedFirst..retainedLast || shouldDeliverBusyGeneratedOutsideRetained(currentDelivery, index))
            ) {
                val deliveredWidth = decodedWidths[index] ?: 0
                if (deliveredWidth >= currentDelivery.result.width &&
                    hasDeliveredBitmap(index) &&
                    !requiresStrictAuthoritativeSurfaceRepair(currentDelivery, index)
                ) {
                    droppedLowerWidth = true
                }
            }
            index
        }
        val deliveryIndexNs = SystemClock.elapsedRealtimeNanos() - deliveryIndexStartedNs
        if (currentIndex < 0 ||
            (busy && currentIndex !in retainedFirst..retainedLast &&
                !shouldDeliverBusyGeneratedOutsideRetained(currentDelivery, currentIndex))
        ) {
            if (currentIndex >= 0 && shouldKeepBusyGeneratedPrimed(currentDelivery)) {
                storePrimedDelivery(currentDelivery.copy(index = currentIndex))
                Log.d(
                    TAG,
                    "reader_busy_generated_delivery_primed page=$currentIndex," +
                        "width=${currentDelivery.result.width}"
                )
                return
            }
            pendingDeliveryWidths.remove(currentDelivery.index)
            recycleDecodeResult(currentDelivery.result)
            return
        }
        if (droppedLowerWidth) {
            ViewerWarmupManager.logMetric("reader_drop_stale_lower_width", currentDelivery.result.width.toLong())
            if (hasDeliveredBitmap(currentIndex)) {
                markDecodedDrawableReady(currentIndex, currentDelivery.page, currentDelivery.result.width)
            }
            pendingDeliveryWidths.remove(currentDelivery.index)
            recycleDecodeResult(currentDelivery.result)
            retryPendingWidthIfNeeded(currentIndex)
            return
        }
        if (requiresAuthoritativeInlineTileAck(currentDelivery) &&
            listener.isPageAuthoritativeDrawableCurrentlyInstalled(currentIndex)
        ) {
            val tiles = currentDelivery.result as? PageDecodeResult.Tiles
            val sameOwnedResources = tiles != null &&
                listener.isPageAuthoritativeDrawableCurrentlyInstalled(
                    currentIndex,
                    tiles.pageWidth,
                    tiles.pageHeight,
                    tiles.tiles
                )
            // FIRST_VALID_FULL_QUALITY_TILE is a single-winner policy. Once the generation-bound
            // Surface or its immutable install queue owns a canonical original, a later decode of
            // the same manifest page must not replace that winner with new Bitmap identities. The
            // old path forced every strict result through the listener and retained hundreds of
            // redundant 690x512 tiles during a long fling, eventually exhausting emulator swap.
            loading.remove(currentDelivery.index)
            loading.remove(currentIndex)
            loadingPages.remove(currentDelivery.index)
            loadingPages.remove(currentIndex)
            loadingStartedAtMs.remove(currentDelivery.index)
            loadingStartedAtMs.remove(currentIndex)
            urgentLoading.remove(currentDelivery.index)
            urgentLoading.remove(currentIndex)
            urgentLoadingPages.remove(currentDelivery.index)
            urgentLoadingPages.remove(currentIndex)
            pendingDeliveryWidths.remove(currentDelivery.index)
            pendingDeliveryWidths.remove(currentIndex)
            initialContinuousPostedWidthsByIdentity.remove(
                initialContinuousPostedIdentity(currentDelivery.page),
            )
            clearStrictInlineInstallRetryState(currentIndex)
            if (!sameOwnedResources) recycleDecodeResult(currentDelivery.result)
            logNtkPagePerf(
                currentIndex,
                "strict_inline_duplicate_winner_drop",
                "sameResources=$sameOwnedResources"
            )
            return
        }
        val deliveredWidth = decodedWidths[currentIndex] ?: 0
        decodedWidths[currentIndex] = max(deliveredWidth, currentDelivery.result.width)
        val fullWidth = achievableWidth(currentIndex, targetWidth(false))
        val shouldUpgradeRetainedLowRes =
            currentIndex in retainedFirst..retainedLast &&
                currentDelivery.result.width < fullWidth
        if (shouldUpgradeRetainedLowRes) {
            scheduleIdleFullWidthUpgrade(currentIndex, fullWidth)
        }
        desiredWidths[currentIndex] = max(desiredWidths[currentIndex] ?: 0, currentDelivery.requestedWidth)
        if (currentDelivery.result.width < currentDelivery.requestedWidth) {
            achievableWidths[currentIndex] = max(
                achievableWidths[currentIndex] ?: 0,
                currentDelivery.result.width
            )
        }
        var authoritativeTilesDispatched = false
        if (!authoritativePrepared && requiresAuthoritativeInlineTileAck(currentDelivery)) {
            val tiles = currentDelivery.result as? PageDecodeResult.Tiles
            val canonicalAtAck = synchronized(pagesLock) {
                pages.getOrNull(currentIndex)?.image
            }
            if (tiles == null ||
                !isCanonicalOriginalTileResult(currentDelivery.result, canonicalAtAck)
            ) {
                logNtkPagePerf(
                    currentIndex,
                    "strict_inline_tile_rejected_provenance",
                    "decoded=${tiles?.originalProof?.canonicalAsset.orEmpty().takeLast(96)}," +
                        "manifest=${canonicalAtAck.orEmpty().takeLast(96)}"
                )
                rejectStrictInlineNonTileDelivery(currentDelivery.copy(index = currentIndex))
                return
            }
            // Manifest replacement is serialized by pagesLock. Keep the exact identity stable
            // from final validation through listener dispatch and ACK so a completed old flight
            // can never be acknowledged for a newly installed manifest item.
            // Publish the external lifetime marker before listener dispatch. A previously
            // cleared copy can have a bounded cleanup callback racing this main delivery; marking
            // only after the listener ACK leaves a window where cleanup sees neither the marker
            // nor the new delivered-map entry and recycles the pending Surface winner.
            if (claimDecodeResultsExternallyOwned(listOf(currentDelivery.result)) == null) {
                rejectStrictInlineDeliveryForRedecode(
                    currentDelivery.copy(index = currentIndex),
                    "external_cleanup_won",
                )
                return
            }
            val authoritativeInstalled = try {
                synchronized(pagesLock) {
                    val currentManifest = pages.getOrNull(currentIndex)?.image
                    if (!isCanonicalOriginalTileResult(currentDelivery.result, currentManifest)) {
                        false
                    } else {
                        authoritativeTilesDispatched = listener.onPageAuthoritativeTilesReady(
                            currentIndex,
                            currentDelivery.page.sourceIndex,
                            tiles.pageWidth,
                            tiles.pageHeight,
                            tiles.tiles,
                            checkNotNull(tiles.originalProof)
                        )
                        authoritativeTilesDispatched && listener.isPageAuthoritativeDrawableInstalled(
                            currentIndex,
                            tiles.pageWidth,
                            tiles.pageHeight,
                            tiles.tiles
                        )
                    }
                }
            } catch (failure: Throwable) {
                throw failure
            }
            if (!authoritativeInstalled) {
                Log.e(
                    TAG,
                    "reader_authoritative_inline_handoff_reject page=$currentIndex," +
                        "dispatched=$authoritativeTilesDispatched," +
                        "activeTokens=${tiles.tiles.count { HostExactHardwareTilePool.isActiveToken(it.bitmap) }}," +
                        "surfaceCurrent=" +
                        listener.isPageAuthoritativeDrawableCurrentlyInstalled(
                            currentIndex,
                            tiles.pageWidth,
                            tiles.pageHeight,
                            tiles.tiles,
                        ),
                )
                preserveStrictInlineTileDeliveryForRetry(
                    currentDelivery.copy(index = currentIndex),
                    "authoritative_install_ack_false"
                )
                return
            }
            // Visible/urgent strict results use the normal main-delivery route instead of the
            // worker-side handoff above. Record the same ownership fact so later viewport demand
            // cannot schedule a second decode for an already installed canonical original.
            strictExactAuthoritativeHandoffPages.add(currentIndex)
            strictExactRollingRehydratePages.remove(currentIndex)
            // A pressure callback can publish a newer retirement while this decode is in flight.
            // Delivery success must not erase that decision; physical re-entry owns the claim.
            if (currentIndex == currentStartPage()) {
                strictExactInitialAnchorPixelsInstalledAtMs.compareAndSet(
                    0L,
                    SystemClock.elapsedRealtime(),
                )
                strictExactInitialAnchorPixelsInstalled.countDown()
            }
            clearStrictInlineInstallRetryState(currentIndex)
        }
        val prerenderState = synchronized(indexedStateLock) {
            booleanArrayOf(
                preRenderedInitialDeliveries.remove(currentIndex) &&
                    currentIndex == currentStartPage(),
                preRenderedInitialContinuousDeliveries.remove(currentIndex),
                preRenderedCommittedDeliveries.remove(currentIndex)
            )
        }
        val preRenderedInitialDelivery = prerenderState[0]
        val preRenderedInitialContinuousDelivery = prerenderState[1]
        val committedByPrerender = prerenderState[2]
        val deliveryTrackStartedNs = SystemClock.elapsedRealtimeNanos()
        val deliveryPreTrackNs = deliveryTrackStartedNs - deliveryMainStartedNs
        val trackedIndex = trackDeliveredResult(
            currentIndex,
            currentDelivery.page,
            currentDelivery.result,
            // An accepted authoritative dispatch transfers the exact tile lifetime to the
            // Activity's pending-install queue (and then ReaderSurfaceView). Keeping ReaderSession
            // ownership as well let its rolling byte budget recycle far-offscreen bitmaps before
            // the batched Surface install reached them, producing `reason=unusable` for the tail.
            owned = !preRenderedInitialDelivery &&
                !preRenderedInitialContinuousDelivery &&
                !authoritativeTilesDispatched
        )
        if (trackedIndex < 0) {
            if (authoritativeTilesDispatched) {
                // Listener dispatch transferred these exact identities before the final
                // pagesLock publication fence. A newer host-pressure retirement must win: clear
                // the installed PageRef and transfer its native lifetime instead of merely
                // scheduling another decode behind the still-owned pool slot.
                rollbackPublishedBitmapConflict(
                    currentIndex,
                    currentDelivery.page,
                    currentDelivery.result.width,
                    "main_delivery_pressure_retired",
                )
            } else {
                redriveAfterTerminalBitmapConflict(
                    currentIndex,
                    currentDelivery.page,
                    currentDelivery.result.width,
                    "main_delivery",
                )
            }
            return
        }
        deliveryTrackNs = SystemClock.elapsedRealtimeNanos() - deliveryTrackStartedNs
        loading.remove(currentDelivery.index)
        loading.remove(currentIndex)
        loadingPages.remove(currentDelivery.index)
        loadingPages.remove(currentIndex)
        loadingStartedAtMs.remove(currentDelivery.index)
        loadingStartedAtMs.remove(currentIndex)
        urgentLoading.remove(currentDelivery.index)
        urgentLoading.remove(currentIndex)
        urgentLoadingPages.remove(currentDelivery.index)
        urgentLoadingPages.remove(currentIndex)
        pendingDeliveryWidths.remove(currentDelivery.index)
        failedPages.remove(currentDelivery.index)
        failedPages.remove(currentIndex)
        transientGeneratedRetries.remove(currentDelivery.index)
        transientGeneratedRetries.remove(currentIndex)
        transientGeneratedVisibleRetries.remove(currentDelivery.index)
        transientGeneratedVisibleRetries.remove(currentIndex)
        initialContinuousPostedWidthsByIdentity.remove(
            initialContinuousPostedIdentity(currentDelivery.page),
        )
        val deliveryCleanupNs = SystemClock.elapsedRealtimeNanos() - deliveryTrackStartedNs - deliveryTrackNs
        if (pagesReadyBeforeDrawable) deliverInitialPagesReadyForCurrentPagesIfNeeded()
        logFirstBitmapIfNeeded(currentDelivery.startedAt, resultDrawHeightPx(currentDelivery.result))
        val deliveryListenerStartedNs = SystemClock.elapsedRealtimeNanos()
        if (!committedByPrerender && !authoritativeTilesDispatched) {
            PerfTrace.begin("ViewerItemBind")
            try {
                when (val result = currentDelivery.result) {
                    is PageDecodeResult.Full -> {
                        if (currentDelivery.proofDrawable) {
                            listener.onPageProofReady(currentIndex, result.bitmap)
                        } else {
                            listener.onPageReady(currentIndex, result.bitmap)
                        }
                    }
                    is PageDecodeResult.Tiles ->
                        dispatchTileDeliveryToListener(currentDelivery, currentIndex, result)
                }
            } finally {
                PerfTrace.end()
            }
        } else if (committedByPrerender) {
            logNtkPagePerf(
                currentIndex,
                "skip_committed_prerender_delivery",
                "width=${currentDelivery.result.width}"
            )
        }
        deliveryListenerNs = SystemClock.elapsedRealtimeNanos() - deliveryListenerStartedNs
        if (!pagesReadyBeforeDrawable) deliverInitialPagesReadyForCurrentPagesIfNeeded()
        markDecodedDrawableReady(currentIndex, currentDelivery.page, currentDelivery.result.width)
        recordAdjacentStrictDrawableCommit(currentDelivery.page)
        maybePromoteLowResGeneratedDrawable(currentIndex, currentDelivery.page, currentDelivery.result.width)
        if (currentIndex == currentStartPage() ||
            shouldCommitFirstDrawableForInitialContinuous(currentDelivery.copy(index = currentIndex))
        ) {
            markFirstDrawableCommitted(currentIndex, "decode_delivery")
        }
        ntkCoordinator?.markFirstDrawableCommitted(currentIndex)
        if (currentIndex == currentStartPage() && !initialDeliveryFlushInProgress.get()) {
            if (isNtkSource(currentDelivery.page.manga, title)) {
                main.post {
                    if (!cancelled.get()) flushInitialHeldDeliveries("anchor")
                }
            } else {
                flushInitialHeldDeliveries("anchor")
            }
        }
        postReleaseInitialFanoutIfPending(currentIndex)
        retryPendingWidthIfNeeded(currentIndex)
        val deliveryPostListenerNs = SystemClock.elapsedRealtimeNanos() - deliveryListenerStartedNs - deliveryListenerNs
        val deliveryMainNs = SystemClock.elapsedRealtimeNanos() - deliveryMainStartedNs
        if (deliveryMainNs >= 8_000_000L &&
            Log.isLoggable("ReaderDeliveryBreakdown", Log.DEBUG)
        ) {
            Log.d(
                TAG,
                "reader_delivery_main_breakdown page=$currentIndex," +
                    "totalUs=${deliveryMainNs / 1_000L},trackUs=${deliveryTrackNs / 1_000L}," +
                    "listenerUs=${deliveryListenerNs / 1_000L},lookupUs=${deliveryLookupNs / 1_000L}," +
                    "indexUs=${deliveryIndexNs / 1_000L},preTrackUs=${deliveryPreTrackNs / 1_000L}," +
                    "cleanupUs=${deliveryCleanupNs / 1_000L},postListenerUs=${deliveryPostListenerNs / 1_000L},busy=$busy," +
                    "proof=${currentDelivery.proofDrawable}"
            )
        }
    }

    private fun dispatchTileDeliveryToListener(
        delivery: Delivery,
        index: Int,
        result: PageDecodeResult.Tiles
    ) {
        if (shouldDeliverAckIndependentGeneratedRunway(delivery.copy(index = index))) {
            listener.onPageLaunchRunwayTilesReady(
                index,
                result.pageWidth,
                result.pageHeight,
                result.tiles
            )
        } else if (delivery.proofDrawable) {
            listener.onPageProofTilesReady(index, result.pageWidth, result.pageHeight, result.tiles)
        } else {
            listener.onPageTilesReady(index, result.pageWidth, result.pageHeight, result.tiles)
        }
    }

    private fun preserveStrictInlineTileDeliveryForRetry(delivery: Delivery, reason: String) {
        val index = delivery.index
        val page = delivery.page
        storePrimedDelivery(delivery)
        pendingDeliveryWidths[index] = max(
            pendingDeliveryWidths[index] ?: 0,
            delivery.result.width
        )
        val retry = synchronized(indexedStateLock) {
            val attempt = authoritativeTileInstallRetryCounts.merge(index, 1, Int::plus) ?: 1
            val delayMs = strictInlineInstallRetryDelayMs(attempt)
            authoritativeTileInstallRetryAtMs[index] = if (delayMs > 0L) {
                SystemClock.uptimeMillis() + delayMs
            } else {
                Long.MAX_VALUE
            }
            attempt to delayMs
        }
        val attempt = retry.first
        val delayMs = retry.second
        logNtkPagePerf(
            index,
            "authoritative_tile_install_retry",
            "reason=$reason,attempt=$attempt,delayMs=$delayMs"
        )
        val postedClaimed = synchronized(indexedStateLock) {
            delayMs > 0L && authoritativeTileInstallRetryPosted.add(index)
        }
        if (!postedClaimed) return
        main.postDelayed({
            val currentIndex = currentPageIndexForDelivery(page, index)
            synchronized(indexedStateLock) {
                authoritativeTileInstallRetryPosted.remove(index)
                if (currentIndex >= 0) authoritativeTileInstallRetryPosted.remove(currentIndex)
            }
            if (currentIndex < 0) return@postDelayed
            // A Session bitmap ledger may outlive the actual Surface installation. This retry was
            // created precisely because the authoritative listener ACK was false, so only a real
            // authoritative Surface owner can make the replacement redundant.
            if (cancelled.get() ||
                (hasDeliveredBitmap(currentIndex) &&
                    listener.isPageAuthoritativeDrawableCurrentlyInstalled(currentIndex))
            ) {
                clearStrictInlineInstallRetryState(currentIndex)
                return@postDelayed
            }
            if (primedDeliveryBacklog.isNotEmpty()) scheduleDeliveryDrain()
        }, delayMs)
    }

    private fun clearStrictInlineInstallRetryState(index: Int) {
        synchronized(indexedStateLock) {
            authoritativeTileInstallRetryCounts.remove(index)
            authoritativeTileInstallRetryAtMs.remove(index)
            authoritativeTileInstallRetryPosted.remove(index)
            strictInlineTileRedecodeAttempts.remove(index)
            strictInlineTileRedecodePosted.remove(index)
        }
    }

    private fun rejectStrictInlineNonTileDelivery(delivery: Delivery) {
        rejectStrictInlineDeliveryForRedecode(delivery, "non_tile")
    }

    private fun rejectStrictInlineDeliveryForRedecode(delivery: Delivery, reason: String) {
        val index = delivery.index
        pendingDeliveryWidths.remove(index)
        loading.remove(index)
        loadingPages.remove(index)
        loadingStartedAtMs.remove(index)
        urgentLoading.remove(index)
        urgentLoadingPages.remove(index)
        initialContinuousPostedWidthsByIdentity.remove(
            initialContinuousPostedIdentity(delivery.page),
        )
        visibleGeneratedDecodeHedges.remove(index)
        initialGeneratedCachedDecodeInFlight.remove(index)
        initialGeneratedDirectDecodeInFlight.remove(index)
        if (!hasDeliveredBitmap(index)) {
            decodedWidths.remove(index, delivery.result.width)
        }
        recycleDecodeResult(delivery.result)
        val attempt = synchronized(indexedStateLock) {
            strictInlineTileRedecodeAttempts.merge(index, 1, Int::plus) ?: 1
        }
        val delayMs = strictInlineTileRedecodeDelayMs(attempt)
        logNtkPagePerf(
            index,
            "strict_inline_non_tile_redecode",
            "reason=$reason,attempt=$attempt,delayMs=$delayMs,proof=${delivery.proofDrawable}"
        )
        val postedClaimed = synchronized(indexedStateLock) {
            delayMs > 0L && strictInlineTileRedecodePosted.add(index)
        }
        if (!postedClaimed) return
        val page = delivery.page
        main.postDelayed({
            val currentIndex = currentPageIndexForDelivery(page, index)
            synchronized(indexedStateLock) {
                strictInlineTileRedecodePosted.remove(index)
                if (currentIndex >= 0) strictInlineTileRedecodePosted.remove(currentIndex)
            }
            if (currentIndex < 0 || cancelled.get() || pageRef(currentIndex) !== page ||
                hasDeliveredBitmap(currentIndex) ||
                listener.isPageAuthoritativeDrawableCurrentlyInstalled(currentIndex)
            ) return@postDelayed
            visibleGeneratedDecodeHedges.remove(currentIndex)
            initialGeneratedCachedDecodeInFlight.remove(currentIndex)
            initialGeneratedDirectDecodeInFlight.remove(currentIndex)
            scheduleVisibleGeneratedCachedDecode(
                currentIndex,
                page,
                "strict_inline_authoritative_tiles",
                SystemClock.elapsedRealtime(),
                forceRequeue = true,
                proofDrawable = false,
                allowOutsideProofWindow = true,
                allowFullDuringActiveProof = true
            )
        }, delayMs)
    }

    /**
     * Defensive rollback for a listener path that already installed before borrowed tracking.
     * Remove the previous ledger entry before clearing Surface so the forced redrive cannot mistake
     * historical bookkeeping for a still-valid drawable.
     */
    private fun rollbackPublishedBitmapConflict(
        fallbackIndex: Int,
        page: PageRef,
        resultWidth: Int,
        reason: String,
    ) {
        val toRetire = ArrayList<Bitmap>()
        val resolvedIndex = synchronized(pagesLock) {
            val index = pageIndexLocked(page, fallbackIndex)
            if (index < 0) return@synchronized -1
            synchronized(deliveredBitmaps) {
                val owned = deliveredOwned.remove(index)
                deliveredBitmaps.remove(index)?.let { bitmap ->
                    deliveredBitmapBytes -= trackedBitmapBytes(bitmap)
                    if (owned) toRetire.add(bitmap)
                }
                deliveredTiles.remove(index)?.let { tiles ->
                    deliveredBitmapBytes -= trackedTileBytes(tiles)
                    if (owned) toRetire.addAll(uniqueTileBitmaps(tiles))
                }
                deliveredBitmapBytes = deliveredBitmapBytes.coerceAtLeast(0L)
            }
            // Keep the exact PageRef resolution and the downstream numeric Surface clear in the
            // same structure transaction. Otherwise a prepend/removal can compact an unrelated
            // page into this index after the identity check and have its fresh drawable cleared.
            listener.onPageCleared(index)
            index
        }
        if (resolvedIndex < 0) return
        publishDeliveredBitmapBytes()
        postSessionOwnedBitmapRetirement(toRetire)
        redriveAfterTerminalBitmapConflict(resolvedIndex, page, resultWidth, reason)
    }

    private fun redriveAfterTerminalBitmapConflict(
        fallbackIndex: Int,
        page: PageRef,
        resultWidth: Int,
        reason: String,
    ) {
        pendingDeliveryWidths.remove(fallbackIndex)
        loading.remove(fallbackIndex)
        loadingPages.remove(fallbackIndex)
        loadingStartedAtMs.remove(fallbackIndex)
        urgentLoading.remove(fallbackIndex)
        urgentLoadingPages.remove(fallbackIndex)
        initialContinuousPostedWidthsByIdentity.remove(
            initialContinuousPostedIdentity(page),
        )
        if (!hasDeliveredBitmap(fallbackIndex)) {
            decodedWidths.remove(fallbackIndex, resultWidth)
            deliveredDrawableProofWidths.remove(fallbackIndex)
            listenerDrawableDeliveries.remove(fallbackIndex)
            drawableReadyHistory.remove(fallbackIndex)
            drawableReadyKey(page)?.let { key -> drawableReadyKeys.remove(key) }
        }
        logNtkPagePerf(
            fallbackIndex,
            "bitmap_terminal_transfer_redrive",
            "reason=$reason,width=$resultWidth",
        )
        if (!terminalBitmapRedrivePosted.add(fallbackIndex)) return
        main.postDelayed({
            val currentIndex = currentPageIndexForDelivery(page, fallbackIndex)
            // This marker protects only the queued delay, not the eventual decode. Release both
            // the captured and remapped index before requesting so a second terminal conflict can
            // schedule another bounded retry instead of leaving the page permanently stalled.
            terminalBitmapRedrivePosted.remove(fallbackIndex)
            if (currentIndex >= 0 && currentIndex != fallbackIndex) {
                terminalBitmapRedrivePosted.remove(currentIndex)
            }
            if (currentIndex < 0 || cancelled.get() || pageRef(currentIndex) !== page ||
                hasDeliveredBitmap(currentIndex)
            ) return@postDelayed
            requestPage(
                currentIndex,
                busy = viewportBusy.get(),
                anchor = currentIndex == currentStartPage(),
                generation = windowGeneration.get(),
            )
        }, TERMINAL_BITMAP_REDRIVE_DELAY_MS)
    }

    private fun maybePromoteLowResGeneratedDrawable(index: Int, page: PageRef, width: Int) {
        if (width <= 0 || width >= ntkProofTargetWidth()) return
        if (isGeneratedFullUpgradeShieldActive()) return
        if (!isImmediateNtkGeneratedUx()) return
        if (!isNtkSource(page.manga, title)) return
        if (!isNtkGeneratedImageUrl(page.image.orEmpty())) return
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return
        if (!isVisibleGeneratedDeliveryTarget(index) && !isInInteractiveProofWindow(index, page)) return
        if ((pendingDeliveryWidths[index] ?: 0) >= ntkProofTargetWidth()) return
        if (ReaderImageCache.cachedFile(appContext, page.manga, page.image.orEmpty()) == null) return
        val scheduled = scheduleVisibleGeneratedCachedDecode(
            index,
            page,
            "low_res_visible_upgrade",
            SystemClock.elapsedRealtime(),
            forceRequeue = true,
            proofDrawable = false,
            allowOutsideProofWindow = true,
            allowFullDuringActiveProof = true
        )
        logNtkPagePerf(
            index,
            "low_res_visible_upgrade",
            "width=$width,target=${ntkProofTargetWidth()},scheduled=$scheduled"
        )
    }

    private fun shouldDeliverBusyGeneratedOutsideRetained(delivery: Delivery, index: Int): Boolean {
        if (shouldDeliverStrictInlinePhysicalTilesImmediately(delivery, index)) return true
        if (shouldDeliverMissingPhysicalForwardFrontier(delivery, index)) return true
        if (!delivery.retainWhenBusy) return false
        if (!isNtkSource(delivery.page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(delivery.page.image.orEmpty())) return false
        if (index < 0) return false
        if (shouldAllowImmediateGeneratedProofSurfaceDelivery(delivery)) return true
        if (isImmediateNtkGeneratedUx() &&
            !delivery.proofDrawable &&
            isNtkManhwaOrWebtoonEpisodePath(delivery.page.manga.ntkEpisodePath)
        ) return false
        if (!shouldCommitActiveGeneratedDeliveryNow(delivery, index)) return false
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        val radius = NTK_WEBTOON_BUSY_VISIBLE_DECODE_RADIUS
        return index in max(0, anchor - radius)..(anchor + radius)
    }

    private fun requiresStrictAuthoritativeSurfaceRepair(
        delivery: Delivery,
        index: Int,
    ): Boolean {
        if (requiresAuthoritativeInlineTileAck(delivery)) {
            return !listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)
        }
        // The session's decoded-width ledger is not a Surface ownership proof. Two adjacent
        // completion lanes can race: a wider result may be tracked before its listener handoff,
        // while a slightly narrower canonical original is already ready to fill the visible
        // successor viewport. Dropping the latter solely from the width ledger leaves the slot
        // permanently blank. Keep the ordinary first-winner rule once any drawable is actually
        // installed; only the missing strict appended Surface slot crosses this repair lane.
        return isDirectWifiStrictAdjacentRunwayProfile(delivery.page.manga) &&
            isCanonicalOriginalTileResult(delivery.result, delivery.page.image) &&
            !listener.isPageDrawableInstalled(index)
    }

    private fun shouldDeliverMissingPhysicalForwardFrontier(delivery: Delivery, index: Int): Boolean {
        if (!delivery.retainWhenBusy || index < 0) return false
        if (delivery.compositorForwardWarmIntent &&
            hasIdentityBoundAdjacentAuthoritativeInstall(delivery)
        ) return true
        // A normal proof is a disposable low-cost preview and must not jump the busy-delivery
        // window. A host-pressure adjacent rehydrate is different: it is the canonical original
        // whose one-shot admission was granted only after this exact PageRef entered the reported
        // physical Surface window. Keeping that result in the primed backlog while the forward
        // cap prevents the window from advancing creates a closed loop: the page cannot become
        // retained until it is drawn, and it cannot be drawn until it is retained. Let only this
        // identity-bound full-original proof cross the frontier; all speculative proofs retain
        // the existing restriction.
        if (!delivery.authoritativeAdjacentRehydrate ||
            (!delivery.hostPressurePhysicalReentry &&
                !delivery.exactAdjacentPhysicalIntent)
        ) return false
        if (hasIdentityBoundAdjacentAuthoritativeInstall(delivery) &&
            !listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)
        ) {
            return true
        }
        if (!isImmediateNtkGeneratedUx() || !isActiveGeneratedInputOrQuietForDelivery()) return false
        if (!isNtkSource(delivery.page.manga, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(delivery.page.manga.ntkEpisodePath)) return false
        if (hasDeliveredBitmap(index) &&
            listener.isPageAuthoritativeDrawableCurrentlyInstalled(index)
        ) return false
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        val physicalProtection = synchronized(pagesLock) {
            if (pages.isEmpty()) return@synchronized IntRange.EMPTY
            val safeAnchor = anchor.coerceIn(0, pages.lastIndex)
            reportedPhysicalDecodeProtectionWindowLocked(
                fallbackAnchor = safeAnchor,
                fallbackFirst = safeAnchor,
                fallbackLast = safeAnchor,
            )
        }
        return index in physicalProtection
    }

    private fun shouldAllowImmediateGeneratedProofSurfaceDelivery(delivery: Delivery): Boolean {
        return isImmediateNtkGeneratedUx() &&
            delivery.proofDrawable &&
            delivery.retainWhenBusy &&
            isNtkSource(delivery.page.manga, title) &&
            isNtkGeneratedImageUrl(delivery.page.image.orEmpty()) &&
            isNtkManhwaOrWebtoonEpisodePath(delivery.page.manga.ntkEpisodePath)
    }

    private fun isActiveGeneratedInputOrQuietForDelivery(): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (viewportBusy.get()) return true
        if (!firstBitmapLogged.get() && ntkFirstBitmapAtMs.get() <= 0L) return false
        return ntkInitialInteractiveSettleRemainingMs() > 0L ||
            readerQuietRemainingMs(NTK_BACKGROUND_WARM_TOUCH_QUIET_MS) > 0L ||
            readerQuietRemainingMs(NTK_APPEND_INITIAL_PUBLISH_TOUCH_QUIET_MS) > 0L
    }

    private fun shouldSuppressActiveGeneratedFullDelivery(delivery: Delivery, index: Int): Boolean {
        // Decode observation alone is not render readiness. A strict exact original must survive
        // until the Surface has installed and acknowledged the same immutable tile identity.
        if (hasIdentityBoundAdjacentAuthoritativeInstall(delivery)) return false
        if (mustInstallStrictAuthoritativeTilesPolicy(
                strictInline = requiresAuthoritativeInlineTileAck(delivery),
                fullQualityTiles = isFullQualityOriginalTileResult(delivery.result),
                index = index,
                physicalFirst = physicalDeliveryFirstPage,
                physicalLast = physicalDeliveryLastPage
            )
        ) return false
        if (shouldDeliverAckIndependentGeneratedRunway(delivery.copy(index = index))) return false
        if (delivery.proofDrawable) return false
        if (!delivery.retainWhenBusy) return false
        if (!isActiveGeneratedInputOrQuietForDelivery()) return false
        if (!isNtkSource(delivery.page.manga, title)) return false
        if (!isNtkGeneratedImageUrl(delivery.page.image.orEmpty())) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(delivery.page.manga.ntkEpisodePath)) return false
        val proofEquivalentWidth = maxOf(
            ntkProofTargetWidth().coerceAtLeast(1),
            achievableWidth(index, delivery.requestedWidth.coerceAtLeast(1))
        )
        if (
            delivery.result.width in 1..proofEquivalentWidth &&
            !hasDeliveredBitmap(index) &&
            (isVisibleGeneratedDeliveryTarget(index) || isInInteractiveProofWindow(index, delivery.page))
        ) {
            return false
        }
        val lowResWidth = deliveredLowResGeneratedDrawableWidth(index, delivery.page, delivery.result.width)
        if (lowResWidth > 0) return true
        if (index == currentStartPage()) return false
        if (!hasDeliveredBitmap(index) && isVisibleGeneratedDeliveryTarget(index)) return true
        if (isInInteractiveProofWindow(index, delivery.page)) return true
        return lowResWidth > 0
    }

    private fun isVisibleGeneratedDeliveryTarget(index: Int): Boolean {
        if (index < 0) return false
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        if (index in max(0, anchor - NTK_WEBTOON_BUSY_VISIBLE_DECODE_RADIUS)..(anchor + initialContinuousViewportAheadPages())) {
            return true
        }
        synchronized(deliveredBitmaps) {
            return index in retainedFirstPage..retainedLastPage
        }
    }

    private fun shouldCommitActiveGeneratedDeliveryNow(delivery: Delivery, index: Int): Boolean {
        if (shouldDeliverStrictInlinePhysicalTilesImmediately(delivery, index)) return true
        if (shouldDeliverAckIndependentGeneratedRunway(delivery.copy(index = index))) return true
        if (!firstBitmapLogged.get()) return true
        if (!delivery.retainWhenBusy) return true
        if (!isNtkSource(delivery.page.manga, title)) return true
        if (!isNtkGeneratedImageUrl(delivery.page.image.orEmpty())) return true
        val activeGeneratedInput = isActiveGeneratedInputOrQuietForDelivery()
        if (!activeGeneratedInput) return true
        val anchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        if (!delivery.proofDrawable) {
            if (shouldSuppressActiveGeneratedFullDelivery(delivery, index)) return false
            if (!hasDeliveredBitmap(index) &&
                index in max(0, anchor - NTK_WEBTOON_BUSY_VISIBLE_DECODE_RADIUS)..(anchor + initialContinuousViewportAheadPages())
            ) {
                return true
            }
            return false
        }
        if (shouldAllowImmediateGeneratedProofSurfaceDelivery(delivery)) return true
        return index in max(0, anchor - 1)..(anchor + initialContinuousViewportAheadPages())
    }

    private fun shouldKeepBusyGeneratedPrimed(delivery: Delivery): Boolean {
        return delivery.retainWhenBusy &&
            isNtkSource(delivery.page.manga, title) &&
            isNtkGeneratedImageUrl(delivery.page.image.orEmpty())
    }

    private fun storePrimedDelivery(delivery: Delivery) {
        val previous = primedDeliveryBacklog.put(delivery.index, delivery)
        if (previous != null && previous !== delivery) recycleDecodeResult(previous.result)
    }

    private fun scheduleIdleFullWidthUpgrade(index: Int, width: Int) {
        if (!idleFullWidthUpgradeScheduled.add(index)) return
        main.postDelayed({
            idleFullWidthUpgradeScheduled.remove(index)
            if (cancelled.get()) return@postDelayed
            val quietMs = readerQuietRemainingMs(LOW_RES_UPGRADE_QUIET_MS)
            if (quietMs > 0L) {
                scheduleIdleFullWidthUpgrade(index, width)
                return@postDelayed
            }
            pageRef(index)?.let { page ->
                if (shouldDeferActiveGeneratedFullWidthUpgrade(index, page, width)) {
                    logNtkPagePerf(
                        index,
                        "generated_full_upgrade_reschedule_active_proof",
                        "target=$width,delivered=${deliveredLowResGeneratedDrawableWidth(index, page, width)}"
                    )
                    scheduleIdleFullWidthUpgrade(index, width)
                    return@postDelayed
                }
            }
            if (!isRetainedPage(index)) return@postDelayed
            ViewerWarmupManager.logMetric("busy_to_idle_upgrade_retry", width.toLong())
            rememberDesiredWidth(index, width)
            requestPage(index, busy = false, anchor = false, generation = windowGeneration.get())
        }, LOW_RES_UPGRADE_QUIET_MS)
    }

    private fun readerQuietRemainingMs(requiredQuietMs: Long): Long {
        if (viewportBusy.get()) return requiredQuietMs
        val lastInteraction = lastUserInteractionMs.get()
        if (lastInteraction <= 0L) return 0L
        val quietFor = SystemClock.uptimeMillis() - lastInteraction
        return (requiredQuietMs - quietFor).coerceAtLeast(0L)
    }

    private fun physicalTouchQuietRemainingMs(requiredQuietMs: Long): Long {
        val lastTouch = lastPhysicalTouchMs.get()
        if (lastTouch <= 0L) return 0L
        val quietFor = SystemClock.uptimeMillis() - lastTouch
        return (requiredQuietMs - quietFor).coerceAtLeast(0L)
    }

    private fun directWifiForwardHistoryMotionQuietRemainingMs(): Long {
        if (!strictExactDirectWifiRollingPixelResidency.get()) return 0L
        if (directWifiForwardPhysicalTouchActive.get() ||
            directWifiForwardSurfaceMotionActive.get()
        ) return NTK_DIRECT_WIFI_FORWARD_HISTORY_NATIVE_QUIET_MS
        val lastMotion = directWifiForwardSurfaceMotionAtMs.get()
        if (lastMotion <= 0L) return 0L
        val quietFor = SystemClock.uptimeMillis() - lastMotion
        return (NTK_DIRECT_WIFI_FORWARD_HISTORY_NATIVE_QUIET_MS - quietFor).coerceAtLeast(0L)
    }

    private fun recycleQueuedDeliveries() {
        initialContinuousPostedWidthsByIdentity.clear()
        while (true) {
            val delivery = deliveryQueue.poll() ?: break
            pendingDeliveryWidths.remove(delivery.index)
            recycleDecodeResult(delivery.result)
        }
        for ((_, delivery) in primedDeliveryBacklog) {
            pendingDeliveryWidths.remove(delivery.index)
            recycleDecodeResult(delivery.result)
        }
        primedDeliveryBacklog.clear()
        authoritativeTileInstallRetryCounts.clear()
        authoritativeTileInstallRetryAtMs.clear()
        authoritativeTileInstallRetryPosted.clear()
        strictInlineTileRedecodeAttempts.clear()
        strictInlineTileRedecodePosted.clear()
        terminalBitmapRedrivePosted.clear()
        strictInlineProofDeliveryIntents.clear()
        for ((_, delivery) in initialDeliveryBacklog) {
            pendingDeliveryWidths.remove(delivery.index)
            recycleDecodeResult(delivery.result)
        }
        initialDeliveryBacklog.clear()
        for ((_, delivery) in initialPreparedBacklog) {
            if (delivery.owned && !delivery.bitmap.isRecycled) recycleBitmapAsync(delivery.bitmap)
        }
        initialPreparedBacklog.clear()
    }

    private fun recycleDecodeResult(result: PageDecodeResult) {
        when (result) {
            is PageDecodeResult.Full -> {
                if (!isBitmapProtectedFromRecycle(result.bitmap)) recycleBitmapAsync(result.bitmap)
            }
            is PageDecodeResult.Tiles -> uniqueTileBitmaps(result.tiles).forEach { bitmap ->
                if (!isBitmapProtectedFromRecycle(bitmap)) recycleBitmapAsync(bitmap)
            }
        }
    }

    private object ExternalBitmapOwnershipClaim

    private data class BitmapPublicationClaim(val identities: List<Bitmap>)

    private fun decodeResultBitmapIdentities(results: Iterable<PageDecodeResult>): List<Bitmap> {
        val identities = java.util.Collections.newSetFromMap(
            IdentityHashMap<Bitmap, Boolean>(),
        )
        for (result in results) {
            when (result) {
                is PageDecodeResult.Full -> identities.add(result.bitmap)
                is PageDecodeResult.Tiles -> uniqueTileBitmaps(result.tiles)
                    .forEach(identities::add)
            }
        }
        return identities.toList()
    }

    /**
     * Reserves identities across a pre-render callback that precedes delivered-map publication.
     * A terminal Surface transfer and a new publication are serialized by the same monitor.
     */
    private fun beginBitmapPublication(result: PageDecodeResult): BitmapPublicationClaim? {
        val identities = decodeResultBitmapIdentities(listOf(result))
        return synchronized(externallyOwnedBitmaps) {
            if (identities.any { bitmap ->
                    bitmap.isRecycled || bitmap in surfaceRetirementTransferredBitmaps
                }
            ) return@synchronized null
            identities.forEach { bitmap ->
                bitmapPublicationInFlight[bitmap] = (bitmapPublicationInFlight[bitmap] ?: 0) + 1
            }
            BitmapPublicationClaim(identities)
        }
    }

    private fun finishBitmapPublication(
        claim: BitmapPublicationClaim,
        externallyOwned: Boolean,
    ) {
        synchronized(externallyOwnedBitmaps) {
            if (externallyOwned) externallyOwnedBitmaps.addAll(claim.identities)
            claim.identities.forEach { bitmap ->
                val count = bitmapPublicationInFlight[bitmap] ?: return@forEach
                if (count <= 1) bitmapPublicationInFlight.remove(bitmap)
                else bitmapPublicationInFlight[bitmap] = count - 1
            }
        }
    }

    private fun claimDecodeResultsExternallyOwned(
        results: List<PageDecodeResult>,
    ): ExternalBitmapOwnershipClaim? = claimBitmapIdentitiesExternallyOwned(
        decodeResultBitmapIdentities(results),
    )

    private fun claimBitmapIdentitiesExternallyOwned(
        identities: Iterable<Bitmap>,
    ): ExternalBitmapOwnershipClaim? {
        val unique = BitmapReleaseIdentityPolicy.uniqueCandidatesExcludingRetained(
            identities,
            emptyList(),
        )
        return synchronized(externallyOwnedBitmaps) {
            // Cleanup performs its final check and recycle under this same lock. If it won first,
            // never publish a recycled immutable resource to Surface; the caller must re-decode.
            if (unique.any { bitmap ->
                    bitmap.isRecycled || bitmap in surfaceRetirementTransferredBitmaps
                }
            ) return@synchronized null
            externallyOwnedBitmaps.addAll(unique)
            ExternalBitmapOwnershipClaim
        }
    }

    /** Caller holds [deliveredBitmaps]. Ownership does not weaken current-residency protection. */
    private fun isCurrentlyDeliveredBitmapLocked(bitmap: Bitmap): Boolean {
        if (deliveredBitmaps.values.any { delivered -> delivered === bitmap }) return true
        return deliveredTiles.values.any { tiles ->
            tiles.any { tile -> tile.bitmap === bitmap }
        }
    }

    /** Snapshot prefilter only; terminal cleanup repeats this external -> delivered lock order. */
    private fun isBitmapProtectedFromRecycle(bitmap: Bitmap): Boolean =
        synchronized(externallyOwnedBitmaps) {
            synchronized(deliveredBitmaps) {
                bitmap in externallyOwnedBitmaps ||
                    bitmap in surfaceRetirementTransferredBitmaps ||
                    bitmapPublicationInFlight.containsKey(bitmap) ||
                    isCurrentlyDeliveredBitmapLocked(bitmap)
            }
        }

    private fun releaseDeliveredBitmaps() {
        val toRetire = ArrayList<Bitmap>()
        synchronized(deliveredBitmaps) {
            for ((index, bitmap) in deliveredBitmaps) {
                if (deliveredOwned.contains(index) && !bitmap.isRecycled) {
                    toRetire.add(bitmap)
                }
            }
            deliveredBitmaps.clear()
            for ((index, tiles) in deliveredTiles) {
                if (deliveredOwned.contains(index)) {
                    for (bitmap in uniqueTileBitmaps(tiles)) {
                        if (!bitmap.isRecycled) toRetire.add(bitmap)
                    }
                }
            }
            deliveredTiles.clear()
            deliveredOwned.clear()
            deliveredBitmapBytes = 0L
            deliveredDrawableProofWidths.clear()
            drawableReadyHistory.clear()
            retainedFirstPage = 0
            retainedLastPage = 0
            physicalDeliveryFirstPage = 0
            physicalDeliveryLastPage = -1
        }
        ViewerTelemetry.setBitmapBytes(0L)
        // These identities may still be owned by a queued native FrameCommand. Session shutdown is
        // not a native-retirement fence: transfer final ownership to the View and never fall back
        // to Bitmap.recycle() when the listener is already inactive or its Looper is stopping.
        postSessionOwnedBitmapRetirement(toRetire)
    }

    private fun trimPendingBitmapDeliveriesOutside(
        first: Int,
        last: Int,
        protectedDisplayIndexes: Set<Int> = emptySet(),
    ) {
        fun isRetained(index: Int): Boolean =
            index in first..last || index in protectedDisplayIndexes

        fun trimDeliveryMap(map: ConcurrentHashMap<Int, Delivery>) {
            for ((index, delivery) in map.entries) {
                if (isRetained(index)) continue
                if (map.remove(index, delivery)) {
                    pendingDeliveryWidths.remove(index)
                    recycleDecodeResult(delivery.result)
                }
            }
        }
        trimDeliveryMap(primedDeliveryBacklog)
        trimDeliveryMap(initialDeliveryBacklog)
        for ((index, prepared) in initialPreparedBacklog.entries) {
            if (isRetained(index)) continue
            if (initialPreparedBacklog.remove(index, prepared) && prepared.owned && !prepared.bitmap.isRecycled) {
                recycleBitmapAsync(prepared.bitmap)
            }
        }
        for (delivery in deliveryQueue) {
            val current = deliveryAtCurrentIndex(delivery)
            val index = current?.index ?: delivery.index
            if (isRetained(index)) continue
            if (deliveryQueue.remove(delivery)) {
                pendingDeliveryWidths.remove(delivery.index)
                recycleDecodeResult(delivery.result)
            }
        }
    }

    private fun trimPendingProtectedNumericBitmaps(first: Int, last: Int) {
        if (!usesProtectedNumericNtkPipeline()) return
        trimPendingBitmapDeliveriesOutside(first, last)
    }

    /**
     * A fixed host HardwareBuffer pool cannot wait for a whole wide chapter to remain decoded.
     * Encoded exact bodies and PageRefs are independently resident, so retire only replaceable
     * pixels outside the physical page plus the p0-p3 forward runway. The pool invokes this
     * callback before blocking an allocator; Surface/JNI retirement then wakes that same wait.
     * The exact adjacent decode itself can run on ReaderControl, so this callback must use the
     * independent cleanup lane. Queuing it back onto control would put the release behind the
     * allocation wait it is supposed to satisfy.
     */
    private fun scheduleHostExactPoolPressureTrim(minimumRetirementBytes: Long) {
        if (minimumRetirementBytes <= 0L || cancelled.get()) return
        hostExactPoolMinimumRetirementBytes.getAndUpdate { current ->
            maxOf(current, minimumRetirementBytes)
        }
        if (!hostExactPoolPressureTrimPosted.compareAndSet(false, true)) return
        try {
            cleanup.execute {
                val pressureReleases = ArrayList<BitmapRelease>()
                var deferredForPhysicalMotion = false
                try {
                    if (cancelled.get()) return@execute
                    if (isHostExactPoolPressureTrimBlockedByPhysicalMotion()) {
                        deferredForPhysicalMotion = true
                        return@execute
                    }
                    synchronized(pagesLock) {
                        // Recheck after acquiring the mutable page-table lock. ACTION_DOWN can
                        // arrive while this cleanup worker was queued; in that case leave every
                        // decoded owner untouched and let the existing drawable-prefix fence stop
                        // a waiting allocator until the short idle edge below retries.
                        if (isHostExactPoolPressureTrimBlockedByPhysicalMotion()) {
                            deferredForPhysicalMotion = true
                            return@synchronized
                        }
                        val pageCount = pages.size
                        if (pageCount <= 0) return@synchronized
                        val anchor = currentViewportAnchor.get()
                            .takeIf { it in pages.indices }
                            ?: currentStartPage().coerceIn(0, pageCount - 1)
                        val physicalVisibleRange = reportedPhysicalWindowLocked(
                            fallbackAnchor = anchor,
                            fallbackFirst = anchor,
                            fallbackLast = anchor,
                        )
                        val decodeProtectionRange =
                            reportedPhysicalDecodeProtectionWindowLocked(
                                fallbackAnchor = anchor,
                                fallbackFirst = anchor,
                                fallbackLast = anchor,
                            )
                        val keep = HostExactHardwareTilePoolPressurePolicy
                            .retainedWindowIncludingPhysicalViewport(
                                pageCount = pageCount,
                                anchor = anchor,
                                physicalVisibleFirst = decodeProtectionRange.first,
                                physicalVisibleLast = decodeProtectionRange.last,
                            )
                        val requiredRetirementBytes =
                            hostExactPoolMinimumRetirementBytes.getAndSet(0L)
                        // Exact adjacent p0..p4 can already own decoded/mirrored storage while its
                        // atomic Surface batch is still waiting in a pending-delivery container.
                        // The delivered-pixel eviction below protects that bounded runway by
                        // immutable episode identity; retain the same display indexes in every
                        // pending container or pressure can recycle a successful decode directly
                        // before the batch commit and expose a blank boundary.
                        val protectedPendingRunwayIndexes =
                            protectedExactOffscreenRunwayDisplayIndexesLocked()
                        // A Surface clear can temporarily reject an otherwise immutable prefix
                        // while its committed identity is crossing the append callback. Session
                        // has already removed that page from deliveredBitmaps, so a numeric-only
                        // pressure pass can never select it again. Reissue the exact PageRef until
                        // Activity acknowledges a successful Surface mutation.
                        val pendingSurfaceIterator =
                            hostPressurePendingSurfaceRetirements.entries.iterator()
                        while (pendingSurfaceIterator.hasNext()) {
                            val entry = pendingSurfaceIterator.next()
                            val retryIndex = pageIndexLocked(entry.key, entry.value)
                            if (retryIndex !in pages.indices ||
                                !hostExactPoolPressureRetiredPages.contains(retryIndex)
                            ) {
                                hostPressureSurfaceRetirementsInFlight.remove(entry.key)
                                pendingSurfaceIterator.remove()
                                continue
                            }
                            val stillDelivered = synchronized(deliveredBitmaps) {
                                deliveredBitmaps.containsKey(retryIndex) ||
                                    deliveredTiles.containsKey(retryIndex)
                            }
                            if (!stillDelivered &&
                                entry.key !in hostPressureSurfaceRetirementsInFlight
                            ) {
                                entry.setValue(retryIndex)
                                pressureReleases += bitmapReleaseLocked(
                                    index = retryIndex,
                                    bitmap = null,
                                    preserveStrictReady = true,
                                    hostPressureRetirement = true,
                                )
                            }
                        }
                        val deliveredBefore = synchronized(deliveredBitmaps) {
                            deliveredBitmapBytesLocked()
                        }
                        Log.d(
                            TAG,
                            "reader_host_exact_pool_pressure_trim anchor=$anchor," +
                                "keep=${keep[0]}-${keep[1]},pages=$pageCount," +
                                "deliveredBytes=$deliveredBefore," +
                                "minimumRetirementBytes=$requiredRetirementBytes",
                        )
                        // pagesLock is reentrant. Holding it through the exact PageRef selection
                        // prevents a prefix compaction from turning this pressure window into a
                        // stale numeric clear of a different page.
                        pressureReleases += evictDeliveredBitmaps(
                            first = keep[0],
                            last = keep[1],
                            forcePressure = true,
                            hostPressureRetirement = true,
                            deferPublication = true,
                        )
                        trimPendingBitmapDeliveriesOutside(
                            keep[0],
                            keep[1],
                            protectedPendingRunwayIndexes,
                        )
                        val deliveredAfterWindowTrim = synchronized(deliveredBitmaps) {
                            deliveredBitmapBytesLocked()
                        }
                        val selectedOutsideWindow =
                            (deliveredBefore - deliveredAfterWindowTrim).coerceAtLeast(0L)
                        val remainingRetirementBytes =
                            (requiredRetirementBytes - selectedOutsideWindow).coerceAtLeast(0L)
                        val missingPhysicalSurfaceBlocker =
                            hasMissingHostExactPhysicalSurfaceBlocker()
                        if (remainingRetirementBytes > 0L &&
                            HostExactHardwareTilePoolPressurePolicy
                                .mayRetireInsideForwardRunway(
                                    rollingPixelResidency =
                                        strictExactRollingPixelResidency.get(),
                                    missingPhysicalSurfaceBlocker =
                                        missingPhysicalSurfaceBlocker,
                                )
                        ) {
                            // Once an exact physical body is actually missing, the current
                            // viewport outranks the speculative runway. Release only enough of
                            // that runway to install the blocker. An idle offscreen decoder with
                            // no blocker uses the rolling pool's bounded transient headroom and
                            // cannot erase the next four HOME-return pages merely to converge to
                            // the smaller settled target.
                            pressureReleases += evictDeliveredBitmapsWithinHostPressureWindow(
                                anchor = anchor,
                                physicalVisibleFirst = physicalVisibleRange.first,
                                physicalVisibleLast = physicalVisibleRange.last,
                                minimumRetirementBytes = remainingRetirementBytes,
                                deferPublication = true,
                            )
                        } else if (remainingRetirementBytes > 0L &&
                            shouldLogRateLimitedDiagnostic(
                                "host_pressure_forward_runway_preserved",
                            )
                        ) {
                            Log.d(
                                TAG,
                                "reader_host_exact_pool_pressure_forward_runway_preserved " +
                                    "anchor=$anchor,keep=${keep[0]}-${keep[1]}," +
                                    "remainingBytes=$remainingRetirementBytes",
                            )
                        }
                    }
                    // PageRef selection and the decode-admission park above are the only work
                    // requiring pagesLock. Resolve release cohorts, post Surface clears and
                    // transfer final bitmap ownership after releasing it so physical input never
                    // waits behind allocation-pressure bookkeeping.
                    if (pressureReleases.isNotEmpty()) {
                        publishDeliveredBitmapBytes()
                        postBitmapReleases(pressureReleases)
                    }
                } finally {
                    hostExactPoolPressureTrimPosted.set(false)
                    val pending = hostExactPoolMinimumRetirementBytes.get()
                    if (pending > 0L && !cancelled.get()) {
                        if (deferredForPhysicalMotion) {
                            main.postDelayed(
                                {
                                    if (!cancelled.get()) {
                                        scheduleHostExactPoolPressureTrim(
                                            hostExactPoolMinimumRetirementBytes.get(),
                                        )
                                    }
                                },
                                NTK_HOST_EXACT_PRESSURE_MOTION_RECHECK_MS,
                            )
                        } else {
                            scheduleHostExactPoolPressureTrim(pending)
                        }
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            hostExactPoolPressureTrimPosted.set(false)
        }
    }

    private fun isHostExactPoolPressureTrimBlockedByPhysicalMotion(): Boolean =
        isHostExactOffscreenDecodeInputProtected() &&
            !hasMissingHostExactPhysicalSurfaceBlocker()

    /**
     * Repeated real swipes can keep the ordinary input quiet fence continuously active. If the
     * fixed pool is already full and the reported physical interval itself contains a missing
     * exact page, deferring every retirement until idle is a closed wait: the page cannot draw
     * until a slot is released, and the user cannot reach an idle clean viewport until it draws.
     * This probe grants only the emergency cleanup pass; that pass still protects the complete
     * reported physical range and can retire only replaceable pixels outside it.
     */
    private fun hasMissingHostExactPhysicalSurfaceBlocker(): Boolean {
        if (!hostExactNativeSurfaceStorageEnabled) return false
        val candidates = synchronized(pagesLock) {
            if (pages.isEmpty()) return@synchronized emptyList()
            val anchor = currentViewportAnchor.get()
                .takeIf { it in pages.indices }
                ?: currentStartPage().coerceIn(0, pages.lastIndex)
            val physical = reportedPhysicalWindowLocked(
                fallbackAnchor = anchor,
                fallbackFirst = anchor,
                fallbackLast = anchor,
            )
            physical.mapNotNull { index ->
                pages.getOrNull(index)
                    ?.takeIf { page ->
                        page.transitionTitle == null && !page.image.isNullOrBlank()
                    }
                    ?.let { page -> index to page }
            }
        }
        return candidates.any { (index, page) ->
            currentPageIndex(page, index) >= 0 &&
                !listener.isPageDrawableInstalled(index)
        }
    }

    /** Caller owns pagesLock; clear callbacks must follow this PageRef across index compaction. */
    private fun bitmapReleaseLocked(
        index: Int,
        bitmap: Bitmap?,
        pressure: Boolean = false,
        preserveStrictReady: Boolean = false,
        hostPressureRetirement: Boolean = false,
    ): BitmapRelease = BitmapRelease(
        index = index,
        bitmap = bitmap,
        clearPage = true,
        pressure = pressure,
        preserveStrictReady = preserveStrictReady,
        hostPressureRetirement = hostPressureRetirement,
        page = pages.getOrNull(index),
    )

    private fun evictDeliveredBitmaps(
        first: Int,
        last: Int,
        forcePressure: Boolean = false,
        hostPressureRetirement: Boolean = false,
        deferPublication: Boolean = false,
    ): List<BitmapRelease> {
        // A normal strict launch episode remains fully resident for immediate reverse scrolling.
        // Continuously appended episodes share the same page table, but must not inherit that
        // exemption: doing so retained every decoded chapter until Home forced an aggressive trim.
        val preserveStrictReady = forcePressure ||
            (strictExactColdRolling && strictExactRollingPixelResidency.get())
        val cleared = ArrayList<BitmapRelease>()
        synchronized(pagesLock) {
            val strictLaunchIndexes = strictExactLaunchDisplayIndexesLocked()
            val protectedLaunchIndexes = protectedStrictExactLaunchDisplayIndexes(strictLaunchIndexes)
            val protectedPixelWindow = if (usesProtectedNumericNtkPipeline()) {
                protectedNumericBitmapWindow(pages.size)
            } else {
                IntRange.EMPTY
            }
            synchronized(deliveredBitmaps) {
                val iterator = deliveredBitmaps.entries.iterator()
                while (iterator.hasNext()) {
                    val entry = iterator.next()
                    if (entry.key < first || entry.key > last) {
                        // A missing/stale protected-window snapshot deliberately expands to the
                        // whole page table during structure handoff. That is safe for ordinary
                        // trimming, but a physically full host pool has already selected its own
                        // exact viewport/runway window above. Let that pressure window retire
                        // outside pixels or every slot can remain protected forever while the
                        // next exact page waits for storage.
                        if (!forcePressure && entry.key in protectedPixelWindow) continue
                        if (shouldProtectDeliveredPixelFromClear(
                                entry.key,
                                protectedLaunchIndexes,
                                forcePressure,
                            )
                        ) continue
                        val owned = deliveredOwned.remove(entry.key)
                        if (hostPressureRetirement) {
                            // Publish the park while pagesLock still excludes a new window
                            // selection. Publishing it after this transaction let requestPage()
                            // re-admit the exact page before the main-thread Surface clear, which
                            // cancelled that clear and stranded the old pooled token indefinitely.
                            hostExactPoolPressureRetiredPages.add(entry.key)
                        }
                        cleared.add(
                            bitmapReleaseLocked(
                                index = entry.key,
                                bitmap = if (owned) entry.value else null,
                                preserveStrictReady = preserveStrictReady,
                            )
                        )
                        deliveredBitmapBytes -= trackedBitmapBytes(entry.value)
                        iterator.remove()
                    }
                }
                val tileIterator = deliveredTiles.entries.iterator()
                while (tileIterator.hasNext()) {
                    val entry = tileIterator.next()
                    if (entry.key < first || entry.key > last) {
                        if (!forcePressure && entry.key in protectedPixelWindow) continue
                        if (shouldProtectDeliveredPixelFromClear(
                                entry.key,
                                protectedLaunchIndexes,
                                forcePressure,
                            )
                        ) continue
                        val owned = deliveredOwned.remove(entry.key)
                        if (hostPressureRetirement) {
                            hostExactPoolPressureRetiredPages.add(entry.key)
                        }
                        if (owned) {
                            for (tile in entry.value) {
                                cleared.add(
                                    bitmapReleaseLocked(
                                        index = entry.key,
                                        bitmap = tile.bitmap,
                                        preserveStrictReady = preserveStrictReady,
                                    )
                                )
                            }
                        } else {
                            cleared.add(
                                bitmapReleaseLocked(
                                    index = entry.key,
                                    bitmap = null,
                                    preserveStrictReady = preserveStrictReady,
                                )
                            )
                        }
                        deliveredBitmapBytes -= trackedTileBytes(entry.value)
                        tileIterator.remove()
                    }
                }
                if (!hostPressureRetirement) {
                    trimDeliveredBudgetLocked(
                        cleared,
                        protectedLaunchIndexes,
                        strictLaunchIndexes,
                        protectedPixelWindow,
                    )
                }
            }
        }
        val publishedClears = if (hostPressureRetirement) {
            cleared.map { release -> release.copy(hostPressureRetirement = true) }
        } else {
            cleared
        }
        if (hostPressureRetirement) {
            hostExactPoolPressureRetiredPages.addAll(publishedClears.map(BitmapRelease::index))
        }
        if (!deferPublication) {
            publishDeliveredBitmapBytes()
            postBitmapReleases(publishedClears)
        }
        return publishedClears
    }

    /**
     * The ordinary pressure window is a latency preference, not an allocation guarantee: six
     * unusually wide pages can themselves occupy nearly the complete host pool. Once every pixel
     * outside that window has been selected for retirement, release only as many additional
     * off-screen pages as the blocked allocator reported. The exact visible PageRefs remain
     * protected and encoded bodies remain resident, so a later direction change rehydrates pixels
     * instead of exposing a blank frame.
     */
    private fun evictDeliveredBitmapsWithinHostPressureWindow(
        anchor: Int,
        physicalVisibleFirst: Int,
        physicalVisibleLast: Int,
        minimumRetirementBytes: Long,
        deferPublication: Boolean = false,
    ): List<BitmapRelease> {
        if (minimumRetirementBytes <= 0L) return emptyList()
        data class PressureCandidate(
            val index: Int,
            val bytes: Long,
            val tiles: Boolean,
        )

        val cleared = ArrayList<BitmapRelease>()
        var selectedBytes = 0L
        var visibleFirst = physicalVisibleFirst
        var visibleLast = physicalVisibleLast
        var direction = if (reverse) -1 else 1
        synchronized(pagesLock) {
            if (pages.isEmpty()) return@synchronized
            val safeAnchor = anchor.coerceIn(0, pages.lastIndex)
            val startupAnchor = currentStartPage().coerceIn(0, pages.lastIndex)
            visibleFirst = physicalVisibleFirst.coerceIn(0, pages.lastIndex)
            visibleLast = physicalVisibleLast.coerceIn(visibleFirst, pages.lastIndex)
            latestReportedWindow.get()?.let { reported ->
                val reportedAnchor = reported.anchorPage?.let { page ->
                    pageIndexLocked(page, reported.fallbackAnchor)
                } ?: -1
                if (reportedAnchor in pages.indices) {
                    direction = reported.directionHint.takeIf { it != 0 } ?: direction
                }
            }
            val protectedLaunchIndexes = protectedStrictExactLaunchDisplayIndexes(
                strictExactLaunchDisplayIndexesLocked(),
            )
            // Host-pool pressure retires only decoded storage. Canonical bodies and completion
            // evidence remain authoritative, and the rolling callback gives Surface terminal
            // ownership after its native FrameCommand/texture references have retired.
            val preserveStrictReady = true
            synchronized(deliveredBitmaps) {
                val candidates = ArrayList<PressureCandidate>()
                deliveredBitmaps.forEach { (index, bitmap) ->
                    if (index == startupAnchor ||
                        index in visibleFirst..visibleLast ||
                        shouldProtectDeliveredPixelFromClear(
                            index,
                            protectedLaunchIndexes,
                            forcePressure = true,
                        )
                    ) return@forEach
                    candidates += PressureCandidate(index, trackedBitmapBytes(bitmap), false)
                }
                deliveredTiles.forEach { (index, tiles) ->
                    if (index == startupAnchor ||
                        index in visibleFirst..visibleLast ||
                        shouldProtectDeliveredPixelFromClear(
                            index,
                            protectedLaunchIndexes,
                            forcePressure = true,
                        )
                    ) return@forEach
                    candidates += PressureCandidate(index, trackedTileBytes(tiles), true)
                }
                val candidateByIndex = candidates.associateBy(PressureCandidate::index)
                val orderedIndexes = HostExactHardwareTilePoolPressurePolicy.retirementOrder(
                    candidateIndexes = candidates.map(PressureCandidate::index).toIntArray(),
                    visibleFirst = visibleFirst,
                    visibleLast = visibleLast,
                    directionHint = direction,
                )
                for (candidateIndex in orderedIndexes) {
                    if (selectedBytes >= minimumRetirementBytes) break
                    val candidate = candidateByIndex[candidateIndex] ?: continue
                    if (candidate.tiles) {
                        val tiles = deliveredTiles.remove(candidate.index) ?: continue
                        val owned = deliveredOwned.remove(candidate.index)
                        // Candidate selection, delivered removal and the decode-admission park are
                        // one pagesLock transaction. A viewport callback can observe either the
                        // old delivered page or the parked absence, never an unparked gap.
                        hostExactPoolPressureRetiredPages.add(candidate.index)
                        if (owned) {
                            for (bitmap in uniqueTileBitmaps(tiles)) {
                                cleared += bitmapReleaseLocked(
                                    index = candidate.index,
                                    bitmap = bitmap,
                                    preserveStrictReady = preserveStrictReady,
                                    hostPressureRetirement = true,
                                )
                            }
                        } else {
                            cleared += bitmapReleaseLocked(
                                index = candidate.index,
                                bitmap = null,
                                preserveStrictReady = preserveStrictReady,
                                hostPressureRetirement = true,
                            )
                        }
                        deliveredBitmapBytes -= trackedTileBytes(tiles)
                    } else {
                        val bitmap = deliveredBitmaps.remove(candidate.index) ?: continue
                        val owned = deliveredOwned.remove(candidate.index)
                        hostExactPoolPressureRetiredPages.add(candidate.index)
                        cleared += bitmapReleaseLocked(
                            index = candidate.index,
                            bitmap = bitmap.takeIf { owned },
                            preserveStrictReady = preserveStrictReady,
                            hostPressureRetirement = true,
                        )
                        deliveredBitmapBytes -= trackedBitmapBytes(bitmap)
                    }
                    selectedBytes = (selectedBytes + candidate.bytes).coerceAtLeast(0L)
                }
                deliveredBitmapBytes = deliveredBitmapBytes.coerceAtLeast(0L)
            }
        }
        if (cleared.isEmpty()) return emptyList()
        hostExactPoolPressureRetiredPages.addAll(cleared.map(BitmapRelease::index))
        Log.d(
            TAG,
            "reader_host_exact_pool_pressure_adaptive_trim anchor=$anchor," +
                "visible=$visibleFirst-$visibleLast,direction=$direction," +
                "requestedBytes=$minimumRetirementBytes,selectedBytes=$selectedBytes," +
                "pages=${cleared.map(BitmapRelease::index).distinct()}",
        )
        if (!deferPublication) {
            publishDeliveredBitmapBytes()
            postBitmapReleases(cleared)
        }
        return cleared
    }

    /**
     * The short direct-Wi-Fi profile keeps verified encoded bodies for the whole forward tail,
     * but decoded launch-episode pixels only for the exact physical forward window. Adjacent
     * runway pages use later display indexes and are intentionally excluded from this retirement.
     */
    private fun trimDirectWifiLaunchPixelsOutsideWindow() {
        if (!strictExactDirectWifiRollingPixelResidency.get()) return
        val cleared = ArrayList<BitmapRelease>()
        synchronized(pagesLock) {
            val launchIndexes = pages.withIndex()
                .filter { (_, page) ->
                    page.transitionTitle == null && isStrictExactLaunchPage(page)
                }
                .mapTo(HashSet()) { it.index }
            if (launchIndexes.isEmpty()) return@synchronized
            val protectedPixelWindow = if (usesProtectedNumericNtkPipeline()) {
                protectedNumericBitmapWindow(pages.size)
            } else {
                IntRange.EMPTY
            }
            synchronized(deliveredBitmaps) {
                val keepFirst = retainedFirstPage
                val keepLast = retainedLastPage
                val bitmapIterator = deliveredBitmaps.entries.iterator()
                while (bitmapIterator.hasNext()) {
                    val entry = bitmapIterator.next()
                    if (entry.key !in launchIndexes ||
                        entry.key in keepFirst..keepLast ||
                        entry.key in protectedPixelWindow
                    ) continue
                    val owned = deliveredOwned.remove(entry.key)
                    cleared.add(
                        bitmapReleaseLocked(
                            index = entry.key,
                            bitmap = entry.value.takeIf { owned },
                            preserveStrictReady = true,
                        )
                    )
                    deliveredBitmapBytes -= trackedBitmapBytes(entry.value)
                    bitmapIterator.remove()
                }
                val tileIterator = deliveredTiles.entries.iterator()
                while (tileIterator.hasNext()) {
                    val entry = tileIterator.next()
                    if (entry.key !in launchIndexes ||
                        entry.key in keepFirst..keepLast ||
                        entry.key in protectedPixelWindow
                    ) continue
                    val owned = deliveredOwned.remove(entry.key)
                    if (owned) {
                        for (bitmap in uniqueTileBitmaps(entry.value)) {
                            cleared.add(
                                bitmapReleaseLocked(
                                    index = entry.key,
                                    bitmap = bitmap,
                                    preserveStrictReady = true,
                                )
                            )
                        }
                    } else {
                        cleared.add(
                            bitmapReleaseLocked(
                                index = entry.key,
                                bitmap = null,
                                preserveStrictReady = true,
                            )
                        )
                    }
                    deliveredBitmapBytes -= trackedTileBytes(entry.value)
                    tileIterator.remove()
                }
                deliveredBitmapBytes = deliveredBitmapBytes.coerceAtLeast(0L)
            }
        }
        if (cleared.isEmpty()) return
        publishDeliveredBitmapBytes()
        postBitmapReleases(cleared)
    }

    private fun trimDeliveredBudgetLocked(
        cleared: MutableList<BitmapRelease>,
        protectedLaunchIndexes: Set<Int>,
        strictLaunchIndexes: Set<Int>,
        protectedPixelWindow: IntRange,
        protectedDeliveryIndex: Int = -1,
    ) {
        check(Thread.holdsLock(pagesLock))
        val protectedPhysicalWindow = if (pages.isEmpty()) {
            IntRange.EMPTY
        } else {
            val fallbackAnchor = currentViewportAnchor.get().coerceIn(0, pages.lastIndex)
            reportedPhysicalDecodeProtectionWindowLocked(
                fallbackAnchor = fallbackAnchor,
                fallbackFirst = fallbackAnchor,
                fallbackLast = fallbackAnchor,
            )
        }
        val preserveStrictReady =
            strictExactColdRolling && strictExactRollingPixelResidency.get()
        val directWifiRolling = strictExactDirectWifiRollingPixelResidency.get()
        val budget = activeBitmapBudgetBytes()
        while (deliveredBitmapBytesLocked() > budget) {
            val iterator = deliveredBitmaps.entries.iterator()
            var trimmed = false
            while (iterator.hasNext()) {
                val entry = iterator.next()
                if (entry.key == protectedDeliveryIndex) continue
                if (directWifiRolling && entry.key !in strictLaunchIndexes) continue
                if (entry.key in protectedPixelWindow) continue
                if (entry.key in protectedPhysicalWindow) continue
                if (entry.key in retainedFirstPage..retainedLastPage) continue
                if (shouldProtectDeliveredPixelFromClear(
                        entry.key,
                        protectedLaunchIndexes,
                        forcePressure = false,
                    )
                ) continue
                val owned = deliveredOwned.remove(entry.key)
                cleared.add(
                    bitmapReleaseLocked(
                        index = entry.key,
                        bitmap = if (owned) entry.value else null,
                        pressure = true,
                        preserveStrictReady = preserveStrictReady,
                    )
                )
                deliveredBitmapBytes -= trackedBitmapBytes(entry.value)
                iterator.remove()
                trimmed = true
                break
            }
            if (!trimmed) {
                val tileIterator = deliveredTiles.entries.iterator()
                while (tileIterator.hasNext()) {
                    val entry = tileIterator.next()
                    if (entry.key == protectedDeliveryIndex) continue
                    if (directWifiRolling && entry.key !in strictLaunchIndexes) continue
                    if (entry.key in protectedPixelWindow) continue
                    if (entry.key in protectedPhysicalWindow) continue
                    if (entry.key in retainedFirstPage..retainedLastPage) continue
                    if (shouldProtectDeliveredPixelFromClear(
                            entry.key,
                            protectedLaunchIndexes,
                            forcePressure = false,
                        )
                    ) continue
                    val owned = deliveredOwned.remove(entry.key)
                    if (owned) {
                        for (tile in entry.value) {
                            cleared.add(
                                bitmapReleaseLocked(
                                    index = entry.key,
                                    bitmap = tile.bitmap,
                                    pressure = true,
                                    preserveStrictReady = preserveStrictReady,
                                )
                            )
                        }
                    } else {
                        cleared.add(
                            bitmapReleaseLocked(
                                index = entry.key,
                                bitmap = null,
                                pressure = true,
                                preserveStrictReady = preserveStrictReady,
                            )
                        )
                    }
                    deliveredBitmapBytes -= trackedTileBytes(entry.value)
                    tileIterator.remove()
                    trimmed = true
                    break
                }
            }
            if (!trimmed && shouldTrimRetainedUnderNtkPressure()) {
                trimmed = trimRetainedBitmapUnderPressureLocked(
                    cleared,
                    protectedLaunchIndexes,
                    strictLaunchIndexes,
                    protectedPixelWindow,
                    protectedPhysicalWindow,
                    protectedDeliveryIndex,
                )
            }
            if (!trimmed) return
        }
    }

    /**
     * Applies the normal decoded-pixel budget without treating a viewport move as memory
     * pressure. [deliveredBitmaps] and [deliveredTiles] are access ordered, so reverse scrolling
     * reuses the most recently traversed originals while memory stays strictly bounded.
     */
    private fun trimDeliveredBitmapsToBudget() {
        val cleared = ArrayList<BitmapRelease>()
        synchronized(pagesLock) {
            val strictLaunchIndexes = strictExactLaunchDisplayIndexesLocked()
            val protectedLaunchIndexes = protectedStrictExactLaunchDisplayIndexes(strictLaunchIndexes)
            val protectedPixelWindow = if (usesProtectedNumericNtkPipeline()) {
                protectedNumericBitmapWindow(pages.size)
            } else {
                IntRange.EMPTY
            }
            synchronized(deliveredBitmaps) {
                trimDeliveredBudgetLocked(
                    cleared,
                    protectedLaunchIndexes,
                    strictLaunchIndexes,
                    protectedPixelWindow,
                )
            }
        }
        publishDeliveredBitmapBytes()
        postBitmapReleases(cleared)
        if (strictExactDirectWifiRollingPixelResidency.get()) {
            trimDirectWifiLaunchPixelsOutsideWindow()
        }
    }

    private fun trimDeliveredPixelsForRetainedWindow(first: Int, last: Int) {
        if (ReaderStrictBitmapResidencyPolicy.shouldHardEvictOutsideRetainedWindow(
                strictColdSession = strictExactColdRolling,
                rollingPixelResidency = strictExactRollingPixelResidency.get(),
                directWifiRolling = strictExactDirectWifiRollingPixelResidency.get(),
            )
        ) {
            evictDeliveredBitmaps(first, last)
        } else {
            // Admission remains scoped to [first]..[last]. Only already-delivered, stable-identity
            // pixels survive outside it, and the production byte budget remains their sole owner.
            trimDeliveredBitmapsToBudget()
        }
    }

    private fun activeBitmapBudgetBytes(): Long {
        if (!isImmediateNtkGeneratedUx()) return ACTIVE_BITMAP_BYTES
        // The immutable launch scene stays resident unless its explicit multi-GiB rolling policy
        // is active. Appended episodes are replaceable pixel caches backed by exact resident bodies;
        // bound their combined cache so a long continuous reader session cannot grow to 500+ MiB
        // and enter a NativeAlloc-GC feedback loop. The launch protection is enforced per index by
        // [shouldProtectDeliveredPixelFromClear], so a launch larger than this target remains safe.
        if (strictExactColdRolling) {
            if (strictExactRollingPixelResidency.get()) {
                return NTK_STRICT_OVERSIZED_BITMAP_BYTES
            }
            return ReaderStrictBitmapResidencyPolicy.totalBitmapBudgetBytes(
                strictExactRequiredBitmapBytes.get(),
                Runtime.getRuntime().maxMemory(),
            )
        }
        return if (isActiveGeneratedInputOrQuietForDelivery()) {
            NTK_GENERATED_BUSY_BITMAP_BYTES
        } else {
            NTK_GENERATED_IDLE_BITMAP_BYTES
        }
    }

    private fun shouldTrimRetainedUnderNtkPressure(): Boolean {
        return ReaderStrictBitmapResidencyPolicy.shouldTrimRetainedUnderBudgetPressure(
            directWifiRolling = strictExactDirectWifiRollingPixelResidency.get(),
            immediateGeneratedUx = isImmediateNtkGeneratedUx(),
            strictColdSession = strictExactColdRolling,
            rollingPixelResidency = strictExactRollingPixelResidency.get(),
            protectsImmediateSurface = shouldProtectImmediateGeneratedSurfaceDrawablesFromClear(),
            viewportBusy = viewportBusy.get(),
            initialSettleActive = ntkInitialInteractiveSettleRemainingMs() > 0L,
        )
    }

    private fun trimRetainedBitmapUnderPressureLocked(
        cleared: MutableList<BitmapRelease>,
        protectedLaunchIndexes: Set<Int>,
        strictLaunchIndexes: Set<Int>,
        protectedPixelWindow: IntRange,
        protectedPhysicalWindow: IntRange,
        protectedDeliveryIndex: Int,
    ): Boolean {
        if (shouldProtectImmediateGeneratedSurfaceDrawablesFromClear() &&
            !strictExactColdRolling
        ) return false
        val protectedRadius = if (strictExactDirectWifiRollingPixelResidency.get()) {
            0
        } else if (
            isImmediateNtkGeneratedUx() &&
            ntkInitialInteractiveSettleRemainingMs() > 0L
        ) {
            NTK_INITIAL_INTERACTIVE_RUNWAY_PAGES
        } else if (isActiveGeneratedInputOrQuietForDelivery()) {
            NTK_GENERATED_BUSY_PROTECTED_RETAIN_RADIUS
        } else {
            NTK_GENERATED_IDLE_PROTECTED_RETAIN_RADIUS
        }
        val bitmapCandidate = deliveredBitmaps.keys
            .asSequence()
            .filter { it != protectedDeliveryIndex }
            .filter {
                !strictExactDirectWifiRollingPixelResidency.get() ||
                    it in strictLaunchIndexes
            }
            .filter { it !in protectedLaunchIndexes }
            .filter { it !in protectedPixelWindow }
            .filter { it !in protectedPhysicalWindow }
            .filter { it in retainedFirstPage..retainedLastPage }
            .filter { abs(it - retainedAnchorPage) > protectedRadius }
            .maxByOrNull { abs(it - retainedAnchorPage) }
        if (bitmapCandidate != null) {
            if (Log.isLoggable(TAG, Log.DEBUG)) {
                Log.d(
                    TAG,
                    "retained_trim kind=bitmap,index=$bitmapCandidate,anchor=$retainedAnchorPage," +
                        "protected=${protectedPixelWindow.first}-${protectedPixelWindow.last}," +
                        "physical=${protectedPhysicalWindow.first}-${protectedPhysicalWindow.last}," +
                        "retained=$retainedFirstPage-$retainedLastPage,radius=$protectedRadius," +
                        "bytes=${deliveredBitmapBytesLocked()},budget=${activeBitmapBudgetBytes()}," +
                        "busy=${viewportBusy.get()}"
                )
            }
            val bitmap = deliveredBitmaps.remove(bitmapCandidate)
            val owned = deliveredOwned.remove(bitmapCandidate)
            if (bitmap != null) deliveredBitmapBytes -= trackedBitmapBytes(bitmap)
            cleared.add(
                bitmapReleaseLocked(
                    index = bitmapCandidate,
                    bitmap = if (owned) bitmap else null,
                    pressure = true,
                )
            )
            return true
        }
        val tileCandidate = deliveredTiles.keys
            .asSequence()
            .filter { it != protectedDeliveryIndex }
            .filter {
                !strictExactDirectWifiRollingPixelResidency.get() ||
                    it in strictLaunchIndexes
            }
            .filter { it !in protectedLaunchIndexes }
            .filter { it !in protectedPixelWindow }
            .filter { it !in protectedPhysicalWindow }
            .filter { it in retainedFirstPage..retainedLastPage }
            .filter { abs(it - retainedAnchorPage) > protectedRadius }
            .maxByOrNull { abs(it - retainedAnchorPage) }
        if (tileCandidate != null) {
            if (Log.isLoggable(TAG, Log.DEBUG)) {
                Log.d(
                    TAG,
                    "retained_trim kind=tiles,index=$tileCandidate,anchor=$retainedAnchorPage," +
                        "protected=${protectedPixelWindow.first}-${protectedPixelWindow.last}," +
                        "physical=${protectedPhysicalWindow.first}-${protectedPhysicalWindow.last}," +
                        "retained=$retainedFirstPage-$retainedLastPage,radius=$protectedRadius," +
                        "bytes=${deliveredBitmapBytesLocked()},budget=${activeBitmapBudgetBytes()}," +
                        "busy=${viewportBusy.get()}"
                )
            }
            val tiles = deliveredTiles.remove(tileCandidate)
            val owned = deliveredOwned.remove(tileCandidate)
            if (tiles != null) deliveredBitmapBytes -= trackedTileBytes(tiles)
            if (owned && tiles != null) {
                for (tile in tiles) {
                    cleared.add(
                        bitmapReleaseLocked(
                            index = tileCandidate,
                            bitmap = tile.bitmap,
                            pressure = true,
                        )
                    )
                }
            } else {
                cleared.add(
                    bitmapReleaseLocked(
                        index = tileCandidate,
                        bitmap = null,
                        pressure = true,
                    )
                )
            }
            return true
        }
        return false
    }

    /**
     * Display indexes are mutable: consumed launch history can be pruned and renumber the already
     * attached next episode down to zero. Protect/retire pixels by immutable episode identity,
     * never by the launch episode's original numeric index range.
     */
    /** Caller holds [pagesLock] until any delivered-pixel operation using this index snapshot ends. */
    private fun strictExactLaunchDisplayIndexesLocked(): Set<Int> {
        if (!strictExactColdRolling) return emptySet()
        val indexes = HashSet<Int>()
        // The sealed launch episode is one contiguous prefix (transition cards may be embedded
        // between its split displays); continuous-reader successors are append-only. Stop at the
        // first real foreign page after the launch cohort instead of rescanning every accumulated
        // successor for every delivered tile. If launch history was pruned, no launch page is
        // observed and the full scan correctly returns empty.
        for ((index, page) in pages.withIndex()) {
            if (page.transitionTitle != null) continue
            if (isStrictExactLaunchPage(page)) {
                indexes.add(index)
            } else if (indexes.isNotEmpty()) {
                break
            }
        }
        return indexes
    }

    private fun protectedStrictExactLaunchDisplayIndexes(
        strictLaunchIndexes: Set<Int>,
    ): Set<Int> {
        val protected = HashSet<Int>()
        if (ReaderStrictBitmapResidencyPolicy.protectsLaunchPixel(
                strictColdSession = strictExactColdRolling,
                rollingPixelResidency = strictExactRollingPixelResidency.get(),
                belongsToLaunchEpisode = true,
                successorPhysicallyPresented = strictExactSuccessorPhysicallyPresented.get(),
            )
        ) {
            protected.addAll(strictLaunchIndexes)
        }
        protected.addAll(protectedExactOffscreenRunwayDisplayIndexesLocked())
        return protected
    }

    /**
     * Caller owns [pagesLock]. The result is bounded to the canonical initial sources of the one
     * exact successor that is still offscreen. It deliberately stops protecting the runway as
     * soon as that episode becomes the viewport owner, so normal rolling pressure can retire
     * already-read pixels without retaining chapter history.
     */
    private fun protectedExactOffscreenRunwayDisplayIndexesLocked(): Set<Int> {
        if (!strictExactColdRolling) return emptySet()
        val protected = HashSet<Int>()
        for ((index, page) in pages.withIndex()) {
            if (page.transitionTitle != null || page.sourceIndex < 0) continue
            val path = activeRemainingAdjacentRunwayTargetPath(page.manga)
            if (path.isEmpty() ||
                (path !in activeRemainingAdjacentRunwayTargetPaths &&
                    path !in publishedExactOffscreenRunwayPaths)
            ) continue
            if (!isDirectWifiStrictAdjacentRunwayProfile(page.manga, path)) continue
            // A transition card or a rebased numeric anchor can belong to the target before even
            // one target body is physically installed. Releasing here on isViewportInsideEpisode
            // recycled p1..p4 behind a clean card, so HOME restored p0 at an 8 px maximum and the
            // next real swipe appeared motion-locked. Hand ownership to the rolling viewport only
            // after an installed target body actually intersects its reported physical window.
            if (physicalViewportHasInstalledEpisodeBodyLocked(page.manga)) continue
            if (page.sourceIndex < requiredInitialAdjacentRunwayPages(page.manga)) {
                protected.add(index)
            }
        }
        return protected
    }

    /** Caller owns [pagesLock]. Structural cards and missing body slots never prove pixel entry. */
    private fun physicalViewportHasInstalledEpisodeBodyLocked(target: Manga): Boolean {
        if (pages.isEmpty()) return false
        val anchor = currentViewportAnchor.get().coerceIn(0, pages.lastIndex)
        val physical = reportedPhysicalWindowLocked(
            fallbackAnchor = anchor,
            fallbackFirst = anchor,
            fallbackLast = anchor,
        )
        return physical.any { index ->
            val candidate = pages.getOrNull(index) ?: return@any false
            candidate.transitionTitle == null &&
                candidate.sourceIndex >= 0 &&
                looseSameEpisodeForAppend(candidate.manga, target) &&
                listener.isPageDrawableInstalled(index)
        }
    }

    private fun shouldProtectDeliveredPixelFromClear(
        index: Int,
        protectedLaunchIndexes: Set<Int>,
        forcePressure: Boolean,
    ): Boolean {
        // The set includes both any still-protected launch pixels and the active adjacent p0-p3
        // boundary contract. Rolling launch residency disables the former, not the latter.
        if (index in protectedLaunchIndexes) return true
        if (strictExactColdRolling && !strictExactRollingPixelResidency.get()) {
            return false
        }
        return !forcePressure && shouldProtectImmediateGeneratedSurfaceDrawablesFromClear()
    }

    private fun shouldProtectImmediateGeneratedSurfaceDrawablesFromClear(): Boolean {
        if (strictExactRollingPixelResidency.get()) return false
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkSource(manga, title)) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(manga.ntkEpisodePath)) return false
        if (usesProtectedNumericNtkPipeline()) return false
        return true
    }

    private fun deliveredBitmapBytesLocked(): Long {
        return deliveredBitmapBytes.coerceAtLeast(0L)
    }

    private fun recalculateDeliveredBitmapBytesLocked() {
        var total = 0L
        for (bitmap in deliveredBitmaps.values) {
            total += trackedBitmapBytes(bitmap)
        }
        for (tiles in deliveredTiles.values) {
            total += trackedTileBytes(tiles)
        }
        deliveredBitmapBytes = total.coerceAtLeast(0L)
    }

    private fun trackedTileBytes(tiles: List<ReaderTile>): Long {
        var total = 0L
        if (tiles.isNotEmpty() &&
            tiles.all { tile -> HostExactHardwareTilePool.isActiveToken(tile.bitmap) }
        ) {
            for (tile in tiles) total += trackedBitmapBytes(tile.bitmap)
            return total
        }
        for (bitmap in uniqueTileBitmaps(tiles)) total += trackedBitmapBytes(bitmap)
        return total
    }

    private fun uniqueTileBitmaps(tiles: List<ReaderTile>): List<Bitmap> {
        if (tiles.size <= 1) return tiles.map(ReaderTile::bitmap)
        val seen = java.util.Collections.newSetFromMap(IdentityHashMap<Bitmap, Boolean>())
        return tiles.map(ReaderTile::bitmap).filter(seen::add)
    }

    private fun trackedBitmapBytes(bitmap: Bitmap): Long {
        return if (bitmap.isRecycled) 0L else bitmapBytes(bitmap).toLong()
    }

    private fun publishDeliveredBitmapBytes() {
        val bytes = synchronized(deliveredBitmaps) { deliveredBitmapBytesLocked() }
        ViewerTelemetry.setBitmapBytes(bytes)
    }

    private fun postBitmapReleases(
        releases: List<BitmapRelease>,
        afterSurfaceClears: (() -> Unit)? = null,
    ) {
        if (releases.isEmpty()) {
            afterSurfaceClears?.invoke()
            return
        }
        data class PageClearTarget(
            val page: PageRef,
            val fallbackIndex: Int,
            val hostPressureRetirement: Boolean,
        )

        val clearedPages = LinkedHashSet<Int>()
        val rollingEvictedPages = LinkedHashSet<Int>()
        val clearedTargets = ArrayList<PageClearTarget>()
        val rollingTargets = ArrayList<PageClearTarget>()
        val ownedBitmaps = ArrayList<Bitmap>()
        val seenBitmaps = java.util.Collections.newSetFromMap(
            IdentityHashMap<Bitmap, Boolean>()
        )
        val pageOrder = ArrayList<PageRef>()
        val pageFallbacks = IdentityHashMap<PageRef, Int>()
        val pagePreserves = IdentityHashMap<PageRef, Boolean>()
        val pageHostPressureRetirements = IdentityHashMap<PageRef, Boolean>()
        for (release in releases) {
            if (release.clearPage) {
                release.page?.let { page ->
                    if (!pagePreserves.containsKey(page)) {
                        pageOrder.add(page)
                        pageFallbacks[page] = release.index
                        pagePreserves[page] = release.preserveStrictReady
                        pageHostPressureRetirements[page] = release.hostPressureRetirement
                    } else {
                        // A hard clear dominates a rolling-ready-preserving release for the same
                        // exact PageRef (for example, a tile list containing several bitmaps).
                        pagePreserves[page] =
                            pagePreserves.getValue(page) && release.preserveStrictReady
                        pageHostPressureRetirements[page] =
                            pageHostPressureRetirements.getValue(page) ||
                                release.hostPressureRetirement
                    }
                }
            }
            release.bitmap
                ?.takeIf { !it.isRecycled && seenBitmaps.add(it) }
                ?.let(ownedBitmaps::add)
        }
        // Wake a compatible host-slot allocator only after these exact token identities have a
        // real retirement owner. Marking before the asynchronous main-thread Surface clear closes
        // the selection/publication race without releasing pixels before native reference proof.
        HostExactHardwareTilePool.noteRetirementPending(ownedBitmaps)
        for (page in pageOrder) {
            val fallback = pageFallbacks.getValue(page)
            val preserveStrictReady = pagePreserves.getValue(page)
            val currentIndex = clearReleasedPageStateIfStillUndelivered(
                page,
                fallback,
                preserveStrictReady,
            )
            if (currentIndex < 0) continue
            val target = PageClearTarget(
                page,
                currentIndex,
                pageHostPressureRetirements.getValue(page),
            )
            if (preserveStrictReady) {
                rollingEvictedPages.add(currentIndex)
                rollingTargets.add(target)
            } else {
                rollingEvictedPages.remove(currentIndex)
                clearedPages.add(currentIndex)
                clearedTargets.add(target)
            }
        }
        val publishedRollingTargets = ArrayList<PageClearTarget>(rollingTargets.size)
        synchronized(pagesLock) {
            for (target in rollingTargets) {
                if (!target.hostPressureRetirement) {
                    publishedRollingTargets.add(target)
                    continue
                }
                hostPressurePendingSurfaceRetirements[target.page] = target.fallbackIndex
                if (hostPressureSurfaceRetirementsInFlight.add(target.page)) {
                    publishedRollingTargets.add(target)
                }
            }
        }
        // Publish the exact display indexes before the listener clears them. A same-admission
        // viewport request can then distinguish a real rolling release from high-frequency
        // duplicate motion callbacks without widening source demand or rescanning the scene.
        if (strictExactRollingPixelResidency.get()) {
            strictExactRollingRehydratePages.addAll(rollingEvictedPages)
        }
        if (clearedPages.isNotEmpty() || rollingEvictedPages.isNotEmpty()) {
            val publishClears = object : Runnable {
                override fun run() {
                    var deferredForStructure = false
                    synchronized(pagesLock) {
                        val pendingStructurePublishes = structurePublishPending.get()
                        val stablePrefixHostPressureClear =
                            pendingStructurePublishes > 0 &&
                                clearedTargets.isEmpty() && publishedRollingTargets.isNotEmpty() &&
                                publishedRollingTargets.all { target -> target.hostPressureRetirement } &&
                                HostExactHardwareTilePoolPressurePolicy
                                    .canPublishStablePrefixRetirement(
                                        pendingStructurePublishes = pendingStructurePublishes,
                                        appendOnlyStablePrefixCounts =
                                            appendOnlyStructurePublishStablePrefixCounts.values
                                                .toIntArray(),
                                        targetIndexes = publishedRollingTargets.map { target ->
                                            pageIndexLocked(target.page, target.fallbackIndex)
                                        }.toIntArray(),
                                    )
                        if (!cancelled.get() && isStructurePublishPending() &&
                            !stablePrefixHostPressureClear
                        ) {
                            deferredForStructure = true
                        } else if (!cancelled.get()) {
                            // Keep pagesLock through the Surface operation. Every page-table
                            // mutation owns the same lock before beginStructurePublish, so a new
                            // numeric epoch cannot start after PageRef resolution but before clear.
                            for (target in clearedTargets) {
                                currentUndeliveredPageIndex(target.page, target.fallbackIndex)
                                    .takeIf { it >= 0 }
                                    ?.let(listener::onPageCleared)
                            }
                            for (target in publishedRollingTargets) {
                                currentUndeliveredPageIndex(target.page, target.fallbackIndex)
                                    .takeIf { it >= 0 }
                                    ?.let { index ->
                                        if (target.hostPressureRetirement) {
                                            listener.onPageHostPressureRollingEvicted(index)
                                        } else {
                                            listener.onPageRollingEvicted(index)
                                        }
                                    }
                            }
                        }
                    }
                    if (deferredForStructure) {
                        // Session indexes have already changed while the Surface mutation is still
                        // queued. A host-pressure retirement is self-validating and may become a
                        // safe stable-prefix clear when any one append owner completes, even when
                        // another tail owner keeps the global count non-zero. Ordinary clears still
                        // require full structure stability.
                        if (clearedTargets.isEmpty() && publishedRollingTargets.isNotEmpty() &&
                            publishedRollingTargets.all { target -> target.hostPressureRetirement }
                        ) {
                            dispatchWhenStructureOwnerFinishes(this)
                        } else {
                            dispatchWhenStructureStable(this)
                        }
                        return
                    }
                    synchronized(pagesLock) {
                        publishedRollingTargets.asSequence()
                            .filter { target -> target.hostPressureRetirement }
                            .forEach { target ->
                                hostPressureSurfaceRetirementsInFlight.remove(target.page)
                            }
                    }
                    // The exact Surface clear is now ordered. Only the View can prove that every
                    // native frame/prewarm GlobalRef has retired; transfer final ownership there.
                    transferSessionOwnedBitmapRetirement(ownedBitmaps)
                    afterSurfaceClears?.invoke()
                }
            }
            if (!main.post(publishClears)) {
                // A stopped Looper cannot order the clear. The View may keep the candidates until
                // detach/native destroy; a failed callback deliberately means GC, never recycle.
                synchronized(pagesLock) {
                    publishedRollingTargets.asSequence()
                        .filter { target -> target.hostPressureRetirement }
                        .forEach { target ->
                            hostPressureSurfaceRetirementsInFlight.remove(target.page)
                        }
                }
                transferSessionOwnedBitmapRetirement(ownedBitmaps)
                afterSurfaceClears?.invoke()
            }
        } else {
            // Replacement releases are collected before their listener setter runs. Defer one
            // main turn so the View first moves the old identity out of current/pending state.
            postSessionOwnedBitmapRetirement(ownedBitmaps, afterSurfaceClears)
        }
    }

    private fun postSessionOwnedBitmapRetirement(
        candidates: Iterable<Bitmap>,
        afterTransfer: (() -> Unit)? = null,
    ) {
        val bitmaps = BitmapReleaseIdentityPolicy.uniqueCandidatesExcludingRetained(
            candidates,
            emptyList(),
        ).filterNot(Bitmap::isRecycled)
        if (bitmaps.isEmpty()) {
            afterTransfer?.invoke()
            return
        }
        val transfer = Runnable {
            transferSessionOwnedBitmapRetirement(bitmaps)
            afterTransfer?.invoke()
        }
        if (!main.post(transfer)) {
            // The callback itself is thread-safe and can still attach the identities to a View
            // whose native destroy is completing. Failure/absence intentionally has no recycler.
            transfer.run()
        }
    }

    private fun transferSessionOwnedBitmapRetirement(bitmaps: List<Bitmap>) {
        if (bitmaps.isEmpty()) return
        val transferable = synchronized(externallyOwnedBitmaps) {
            synchronized(deliveredBitmaps) {
                bitmaps.filter { bitmap ->
                    !bitmap.isRecycled &&
                        bitmap !in externallyOwnedBitmaps &&
                        !bitmapPublicationInFlight.containsKey(bitmap) &&
                        !isCurrentlyDeliveredBitmapLocked(bitmap) &&
                        surfaceRetirementTransferredBitmaps.add(bitmap)
                }
            }
        }
        if (transferable.isEmpty()) return
        try {
            listener.onSessionOwnedBitmapRetirement(transferable)
        } catch (failure: Throwable) {
            // Explicit recycling is unsafe without the View's native-idle proof. Dropping this
            // final-owner transfer leaves Java/native reachability and GC as the safe fallback.
            Log.w(TAG, "Session bitmap retirement handoff failed; leaving identities to GC", failure)
        }
    }

    private fun clearReleasedPageStateIfStillUndelivered(
        page: PageRef,
        fallbackIndex: Int,
        preserveStrictReady: Boolean,
    ): Int = synchronized(pagesLock) {
        val index = pageIndexLocked(page, fallbackIndex)
        if (index < 0) return@synchronized -1
        val cleared = synchronized(deliveredBitmaps) {
            if (deliveredBitmaps.containsKey(index) || deliveredTiles.containsKey(index)) {
                false
            } else {
                decodedWidths.remove(index)
                desiredWidths.remove(index)
                if (!preserveStrictReady) {
                    sourceWidths.remove(index)
                    achievableWidths.remove(index)
                    listenerDrawableDeliveries.remove(index)
                    drawableReadyHistory.remove(index)
                    deliveredDrawableProofWidths.remove(index)
                    drawableReadyKey(page)?.let { key -> drawableReadyKeys.remove(key) }
                }
                true
            }
        }
        if (cleared) index else -1
    }

    private fun currentUndeliveredPageIndex(page: PageRef, fallbackIndex: Int): Int =
        synchronized(pagesLock) {
            val index = pageIndexLocked(page, fallbackIndex)
            if (index < 0) return@synchronized -1
            synchronized(deliveredBitmaps) {
                if (deliveredBitmaps.containsKey(index) || deliveredTiles.containsKey(index)) {
                    -1
                } else {
                    index
                }
            }
        }

    private fun clearDrawableReadyState(index: Int) {
        listenerDrawableDeliveries.remove(index)
        drawableReadyHistory.remove(index)
        deliveredDrawableProofWidths.remove(index)
        pageRef(index)?.let { page ->
            drawableReadyKey(page)?.let { key -> drawableReadyKeys.remove(key) }
        }
    }

    private fun ntkInitialGeneratedDecodeRunwayPages(): Int {
        if (!isImmediateNtkGeneratedUx()) return NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES
        if (!firstBitmapLogged.get() || shouldHoldNtkGeneratedTailForInitialContinuous()) {
            return ntkPreFirstDrawableRunwayPages()
        }
        if (viewportBusy.get() || ntkInitialInteractiveSettleRemainingMs() > 0L) {
            return NTK_INITIAL_CONTINUOUS_REQUIRED_PAGES + initialContinuousViewportAheadPages()
        }
        return minOf(NTK_GENERATED_INITIAL_CONTINUOUS_RUNWAY_PAGES, 24)
    }

    private fun ntkPreFirstDrawableRunwayPages(): Int {
        return if (isNtkWebtoonEpisodePath(manga.ntkEpisodePath)) {
            NTK_PRE_FIRST_WEBTOON_DRAWABLE_RUNWAY_PAGES
        } else {
            NTK_PRE_FIRST_MANHWA_DRAWABLE_RUNWAY_PAGES
        }
    }

    private fun recycleBitmapAfterDelay(bitmap: Bitmap) {
        main.postDelayed({
            // The matching Surface clear completed before this timer was armed. A current
            // delivery or pending external owner is rechecked by releaseBitmapToPoolOrRecycle;
            // active input must not extend this strong Runnable capture forever.
            recycleBitmapAsync(bitmap)
        }, REPLACED_BITMAP_RECYCLE_DELAY_MS)
    }

    private fun recycleBitmapAfterPressureDelay(bitmap: Bitmap) {
        main.postDelayed({
            recycleBitmapAsync(bitmap)
        }, PRESSURE_BITMAP_RECYCLE_DELAY_MS)
    }

    private fun recycleBitmapAsync(bitmap: Bitmap) {
        try {
            cleanup.execute {
                releaseBitmapToPoolOrRecycle(bitmap)
            }
        } catch (_: RuntimeException) {
            releaseBitmapToPoolOrRecycle(bitmap)
        }
    }

    private fun releaseBitmapToPoolOrRecycle(bitmap: Bitmap) {
        // Fixed order: the authoritative handoff marker is published under external ownership,
        // while ordinary/current delivery is published under deliveredBitmaps. Keep both locks
        // through the terminal operation so a delayed stale release cannot recycle the identity
        // currently installed by a replacement tile list, regardless of deliveredOwned state.
        synchronized(externallyOwnedBitmaps) {
            synchronized(deliveredBitmaps) {
                if (bitmap.isRecycled || bitmap in externallyOwnedBitmaps ||
                    bitmap in surfaceRetirementTransferredBitmaps ||
                    bitmapPublicationInFlight.containsKey(bitmap) ||
                    isCurrentlyDeliveredBitmapLocked(bitmap)
                ) return
                try {
                    // This terminal operation must remain observable to a later external-owner
                    // mark. Returning the object to a pool leaves isRecycled=false and permits a
                    // queued Surface handoff to adopt storage another decode can immediately reuse.
                    if (!HostExactHardwareTilePool.retire(bitmap)) bitmap.recycle()
                } catch (_: Throwable) {
                    if (!bitmap.isRecycled && !HostExactHardwareTilePool.retire(bitmap)) {
                        bitmap.recycle()
                    }
                }
            }
        }
    }

    private fun bitmapBytes(bitmap: Bitmap): Int {
        HostExactHardwareTilePool.storageBytes(bitmap)?.let { bytes ->
            return bytes.coerceAtMost(Int.MAX_VALUE.toLong()).toInt()
        }
        return try {
            bitmap.allocationByteCount
        } catch (_: Exception) {
            bitmap.byteCount
        }
    }

    private fun decodeLocal(image: String, options: BitmapFactory.Options): Bitmap? {
        val uri = Uri.parse(image)
        if (!uri.scheme.isNullOrEmpty()) {
            return appContext.contentResolver.openInputStream(uri)?.use {
                BitmapFactory.decodeStream(it, null, options)
            }
        }
        return BitmapFactory.decodeFile(image, options)
    }

    private fun sampleSize(sourceWidth: Int, targetWidth: Int): Int {
        if (sourceWidth <= 0 || targetWidth <= 0) return 1
        var sample = 1
        while (sourceWidth / (sample * 2) >= targetWidth) sample *= 2
        return max(1, sample)
    }

    private fun sampleSizeForByteBudget(sourceWidth: Int, sourceHeight: Int, maxBytes: Long): Int {
        if (sourceWidth <= 0 || sourceHeight <= 0 || maxBytes <= 0L) return 1
        var sample = 1
        while (estimatedRgb565Bytes(sourceWidth, sourceHeight, sample) > maxBytes) sample *= 2
        return sample
    }

    private fun estimatedRgb565Bytes(width: Int, height: Int, sample: Int): Long {
        val decodedWidth = max(1, (width + sample - 1) / sample)
        val decodedHeight = max(1, (height + sample - 1) / sample)
        return decodedWidth.toLong() * decodedHeight.toLong() * 2L
    }

    private fun targetWidth(busy: Boolean): Int {
        val width = max(1, viewerWidth)
        return if (busy) minOf(width, ReaderPipelinePolicy.BUSY_DECODE_WIDTH) else width
    }

    private fun targetWidth(page: PageRef, busy: Boolean): Int {
        val width = max(1, viewerWidth)
        if (isNtkWebtoonSource(page.manga, title) || isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) {
            if (
                busy &&
                isImmediateNtkGeneratedUx() &&
                isActiveGeneratedTouchOrQuiet()
            ) {
                return minOf(width, ntkProofTargetWidth())
            }
            return width
        }
        return targetWidth(busy)
    }

    private fun windowOrder(first: Int, last: Int, anchor: Int, direction: Int): List<Int> {
        val result = ArrayList<Int>(last - first + 1)
        fun add(index: Int) {
            if (index in first..last && !result.contains(index)) result.add(index)
        }
        val safeAnchor = anchor.coerceIn(first, last)
        add(safeAnchor)
        var distance = 1
        while (result.size < last - first + 1) {
            if (direction >= 0) {
                add(safeAnchor + distance)
                add(safeAnchor - distance)
            } else {
                add(safeAnchor - distance)
                add(safeAnchor + distance)
            }
            distance++
        }
        return result
    }

    private fun forwardBiasedWindowOrder(first: Int, last: Int, anchor: Int): List<Int> {
        val result = ArrayList<Int>(last - first + 1)
        fun add(index: Int) {
            if (index in first..last && !result.contains(index)) result.add(index)
        }
        val safeAnchor = anchor.coerceIn(first, last)
        add(safeAnchor)
        for (index in (safeAnchor + 1)..last) add(index)
        for (index in (safeAnchor - 1) downTo first) add(index)
        return result
    }

    private fun trimDecodedWidth(anchor: Int, busy: Boolean) {
        if (!busy) return
        val keepFirst = max(0, anchor - ReaderPipelinePolicy.BUSY_WINDOW_BEFORE)
        val keepLast = anchor + ReaderPipelinePolicy.BUSY_WINDOW_AFTER
        decodedWidths.keys.removeAll { (it < keepFirst || it > keepLast) && !hasDeliveredBitmap(it) }
        desiredWidths.keys.removeAll { it < keepFirst || it > keepLast }
    }

    private fun attachTitle() {
        if (title != null) {
            manga.title = title
            manga.titleId = title.id
        }
    }

    private fun isWfwfSource(manga: Manga?, title: Title?): Boolean {
        val source = (title?.sourceSite ?: manga?.title?.sourceSite ?: "")
            .trim()
            .lowercase(java.util.Locale.ROOT)
        return source == "wfwf" ||
            (source.isBlank() && !legacyBlankSourceNtkAtCreation)
    }

    private fun isNtkSource(manga: Manga?, title: Title?): Boolean {
        val source = (title?.sourceSite ?: manga?.title?.sourceSite ?: "")
            .trim()
            .lowercase(java.util.Locale.ROOT)
        return source == "ntk" ||
            (source.isBlank() && legacyBlankSourceNtkAtCreation)
    }

    private fun isNtkWebtoonSource(manga: Manga?, title: Title?): Boolean {
        if (!isNtkSource(manga, title)) return false
        return title?.baseMode == MTitle.base_webtoon ||
            manga?.baseMode == MTitle.base_webtoon ||
            manga?.title?.baseMode == MTitle.base_webtoon
    }

    private fun syncNtkTitlePathFromEpisode(title: Title?, episode: Manga?): Boolean {
        if (title == null || episode == null) return false
        if (!isNtkSource(episode, title)) return false
        val path = episode.ntkEpisodePath?.trim().orEmpty()
        if (path.isEmpty()) return false
        return title.applyNtkTitlePathFromEpisodePath(path)
    }

    private fun shouldRefreshNtkGeneratedAppendUrls(urls: List<String>): Boolean {
        if (urls.size <= NTK_GENERATED_APPEND_REFRESH_MIN_COUNT) return false
        val first = urls.firstOrNull()?.lowercase(java.util.Locale.ROOT) ?: return false
        val last = urls.lastOrNull()?.lowercase(java.util.Locale.ROOT) ?: return false
        if (!first.contains("://i.toonflix.app/")) return false
        if (!first.contains("/manhwa/") && !first.contains("/webtoon/")) return false
        val firstMatch = NTK_GENERATED_PAGE_URL.find(first) ?: return false
        val lastMatch = NTK_GENERATED_PAGE_URL.find(last) ?: return false
        return firstMatch.groupValues.getOrNull(1) == "001" &&
            lastMatch.groupValues.getOrNull(1)?.toIntOrNull()?.let { it > NTK_GENERATED_APPEND_REFRESH_MIN_COUNT } == true
    }

    private fun requestedStartPage(): Int {
        val storedPage = if (manga.useBookmark() && ml.melun.mangaview.MainApplication.p != null) {
            ml.melun.mangaview.MainApplication.p.getViewerBookmark(manga)
        } else {
            0
        }
        return NtkStrictResumeAnchorPolicy.resolve(
            strictExact = strictExactColdRolling,
            startAtFirstPage = startAtFirstPage,
            strictSourceFloor = strictForwardSourceFloor,
            storedPage = storedPage,
        )
    }

    private fun currentStartPage(): Int {
        val resolved = resolvedInitialStartPage.get()
        return if (resolved >= 0) resolved else requestedStartPage()
    }

    fun initialStartPage(): Int = currentStartPage()

    fun initialStartPageForTest(): Int = initialStartPage()

    private fun requestedStartSide(): Int {
        if (!autoCut || ml.melun.mangaview.MainApplication.p == null) return PAGE_SIDE_FIRST
        return if (ml.melun.mangaview.MainApplication.p.getViewerBookmarkSide(manga) == PAGE_SIDE_SECOND) {
            PAGE_SIDE_SECOND
        } else {
            PAGE_SIDE_FIRST
        }
    }

    private fun postMessage(message: String) {
        main.post { if (!cancelled.get()) listener.onMessage(message) }
    }

    private fun postInitialPageError(message: String) {
        if (!pagesInstalled.compareAndSet(false, true)) {
            postMessage(message)
            return
        }
        resolvedInitialStartPage.set(0)
        main.post {
            if (!cancelled.get()) {
                deliverInitialPagesReadyIfNeeded(1, 0, true)
                listener.onPageError(0, message)
            }
        }
    }

    private fun deliverInitialPagesReadyForCurrentPagesIfNeeded() {
        if (initialPagesReadyDelivered.get() || cancelled.get()) return
        val count = synchronized(pagesLock) { pages.size }
        if (count <= 0) return
        deliverInitialPagesReadyIfNeeded(count, currentStartPage(), true)
    }

    private fun deliverInitialPagesReadyIfNeeded(count: Int, startPage: Int, notifyInitialPage: Boolean) {
        if (count <= 0 || cancelled.get()) return
        if (!initialPagesReadyDelivered.compareAndSet(false, true)) return
        val startedAt = SystemClock.elapsedRealtime()
        listener.onPagesReady(count)
        val pagesReadyMs = SystemClock.elapsedRealtime() - startedAt
        if (notifyInitialPage && startPage >= 0) listener.onInitialPage(startPage)
        val totalMs = SystemClock.elapsedRealtime() - startedAt
        if (totalMs > 32L) {
            Log.d(
                TAG,
                "reader_initial_pages_ready_deliver_ms count=$count,start=$startPage," +
                    "pagesReadyMs=$pagesReadyMs,totalMs=$totalMs,notifyInitialPage=$notifyInitialPage"
            )
        }
    }

    private fun retryTransientNtkImagePageError(index: Int, page: PageRef, e: Exception): Boolean {
        if (!isNtkSource(page.manga, title)) return false
        val image = page.image ?: return false
        if (!isRetryableTransientNtkImageUrl(image)) return false
        if (!isTransientNtkImageError(e)) return false
        if (pageRef(index) != page || cancelled.get()) return true
        val attempt = transientGeneratedRetries.merge(index, 1) { previous, _ -> previous + 1 } ?: 1
        if (attempt > NTK_GENERATED_TRANSIENT_RETRY_ATTEMPTS) {
            transientGeneratedRetries.remove(index)
            if (!shouldKeepRetryingVisibleNtkImageTransient(index, page)) return false
            val visibleAttempt = transientGeneratedVisibleRetries.merge(index, 1) { previous, _ -> previous + 1 } ?: 1
            if (visibleAttempt > NTK_GENERATED_VISIBLE_TRANSIENT_RETRY_ATTEMPTS) {
                transientGeneratedVisibleRetries.remove(index)
                return false
            }
            clearTransientGeneratedPageState(index)
            Log.d(
                TAG,
                "retry_visible_transient_ntk_image_error index=$index,source=${page.sourceIndex}," +
                    "attempt=$visibleAttempt,path=${page.manga.ntkEpisodePath},image=$image," +
                    "error=${e.javaClass.simpleName}:${e.message}"
            )
            main.postDelayed({
                if (!cancelled.get() && pageRef(index) == page) {
                    requestPage(index, busy = true, anchor = true, generation = FOREGROUND_PRIME_WARM_GENERATION)
                }
            }, NTK_GENERATED_VISIBLE_TRANSIENT_RETRY_DELAY_MS * visibleAttempt)
            return true
        }
        transientGeneratedVisibleRetries.remove(index)
        clearTransientGeneratedPageState(index)
        val activeFetch = ReaderImageCache.hasActiveFetch(page.manga, image)
        val cacheFileRace = isTransientNtkCacheFileRaceError(e)
        val foregroundTransient = e.message.orEmpty().let { message ->
            message.contains("Partial foreground image response is not cacheable", ignoreCase = true) ||
                message.contains("Connection reset", ignoreCase = true) ||
                message.contains("stream was reset", ignoreCase = true) ||
                message.contains("unexpected end of stream", ignoreCase = true) ||
                message.contains("foreground image race failed", ignoreCase = true)
        }
        val delayMs = if (cacheFileRace) {
            NTK_TRANSIENT_CACHE_RACE_RETRY_DELAY_MS * attempt
        } else if (foregroundTransient) {
            if (activeFetch || ReaderImageCache.hasActiveInitialNtkGeneratedFetch(page.manga, image)) {
                NTK_GENERATED_ACTIVE_FETCH_RETRY_DELAY_MS * attempt
            } else {
                NTK_GENERATED_PARTIAL_RETRY_DELAY_MS * attempt
            }
        } else {
            NTK_GENERATED_TRANSIENT_RETRY_DELAY_MS * attempt
        }
        Log.d(
            TAG,
            "retry_transient_ntk_image_error index=$index,source=${page.sourceIndex},attempt=$attempt," +
                "delayMs=$delayMs,activeFetch=$activeFetch," +
                "activeInitialFetch=${ReaderImageCache.hasActiveInitialNtkGeneratedFetch(page.manga, image)}," +
                "cacheFileRace=$cacheFileRace," +
            "path=${page.manga.ntkEpisodePath},image=$image,error=${e.javaClass.simpleName}:${e.message}"
        )
        main.postDelayed({
            if (!cancelled.get() && pageRef(index) == page) {
                val visibleRetry = shouldKeepRetryingVisibleNtkImageTransient(index, page)
                requestPage(
                    index,
                    busy = true,
                    anchor = visibleRetry,
                    generation = if (visibleRetry) FOREGROUND_PRIME_WARM_GENERATION else PRIME_WARM_GENERATION
                )
            }
        }, delayMs)
        return true
    }

    private fun clearTransientGeneratedPageState(index: Int) {
        failedPages.remove(index)
        decodedWidths.remove(index)
        desiredWidths.remove(index)
        pendingDeliveryWidths.remove(index)
        sourceWidths.remove(index)
        achievableWidths.remove(index)
        inFlightWidths.remove(index)
        loading.remove(index)
        urgentLoading.remove(index)
        loadingPages.remove(index)
        urgentLoadingPages.remove(index)
    }

    private fun shouldKeepRetryingVisibleNtkImageTransient(index: Int, page: PageRef): Boolean {
        if (!isImmediateNtkGeneratedUx()) return false
        if (!isNtkManhwaOrWebtoonEpisodePath(page.manga.ntkEpisodePath)) return false
        if (hasDeliveredOrPendingDrawable(index)) return false
        val viewportAnchor = currentViewportAnchor.get().takeIf { it >= 0 } ?: currentStartPage()
        return index in max(0, viewportAnchor - 1)..(viewportAnchor + NTK_ACTIVE_VISIBLE_DIRECT_DECODE_AHEAD_PAGES)
    }

    private fun postCaptchaRequired(target: Manga) {
        main.post { if (!cancelled.get()) listener.onCaptchaRequired(target) }
    }

    private fun postBoundaryAppendFinished(anchor: Int, direction: Int, silent: Boolean, suppressedCaptcha: Boolean) {
        main.post { if (!cancelled.get()) listener.onBoundaryAppendFinished(anchor, direction, silent, suppressedCaptcha) }
    }

    private companion object {
        // The adjacent boundary already owns immutable p0..p4 bodies and the source actor admits
        // p5 once that finite runway is released. Four sources of viewport lookahead still made
        // p6 begin only after p2 became visible. On a healthy but variable CDN, a 1.5-2.3 MiB PNG
        // then reached EOF beside the drawable fence and produced measured 229-383 ms physical
        // stalls even though native decode itself stayed below 100 ms.
        //
        // Keep this bounded and source-count based, but admit eight directional sources from the
        // first exact p0 compositor frame. At the boundary that adds only p6-p8 beyond the already
        // owned p0-p5 cohort; it neither opens a whole chapter nor changes logical body ownership.
        // As the viewport advances the same fixed window applies to short manga and tall webtoon
        // sources, while background identities fall out of admission normally.
        private const val NTK_ADJACENT_VIEWPORT_SOURCE_LOOKAHEAD = 8
        private const val NTK_ADJACENT_VIEWPORT_OPPOSITE_LOOKAHEAD = 1
        private const val NTK_HOST_EXACT_PRESSURE_MOTION_RECHECK_MS = 48L
        private const val HOST_EXACT_OFFSCREEN_DECODE_INPUT_QUIET_MS = 750L
        private const val TAG = "ViewerPerf"
        private val FOREGROUND_BYTE_FLIGHT_EPOCH = AtomicLong()
        private val GSON = Gson()
        private const val NTK_PROTECTED_NETWORK_PARALLELISM = 6
        private const val BLOCKED_FORWARD_REDRIVE_MIN_INTERVAL_MS = 240L
        private const val BLOCKED_FORWARD_PENDING_AUDIT_DELAY_MS = 96L
        private const val NTK_PROTECTED_BITMAP_AHEAD_PAGES =
            ReaderPipelinePolicy.STRICT_ROLLING_WINDOW_AHEAD
        private const val NTK_PROTECTED_BITMAP_BEHIND_PAGES =
            ReaderPipelinePolicy.STRICT_ROLLING_WINDOW_BEHIND
        private const val NTK_SOURCE_READINESS_LOG_BATCH = 8
        private const val PREPARED_BITMAP_RELEASE_DELAY_MS = 12000L
        private const val PRIME_WARM_GENERATION = Int.MIN_VALUE
        private const val FOREGROUND_PRIME_WARM_GENERATION = Int.MIN_VALUE + 1
        private const val URGENT_VISIBLE_NETWORK_PARALLELISM = 8
        private const val URGENT_VISIBLE_DECODE_PARALLELISM = 8
        // The anchor owns its own display-priority lane. Keep the measured three-worker pool while
        // HTTP bodies are arriving so decode cannot steal network/render CPU. Once every canonical
        // body is verified, a sizeable finite queue may expand to five workers. Only the current
        // direct-Wi-Fi webtoon may use seven for a seven-or-larger final tail after the final EOF,
        // when no network body remains to compete with; every result still enters the same bounded
        // native install queue.
        private const val STRICT_EXACT_BULK_DECODE_PARALLELISM = 3
        private const val STRICT_EXACT_ROLLING_DECODE_PARALLELISM = 3
        private const val STRICT_EXACT_OVERLAP_DECODE_PARALLELISM = 3
        private const val STRICT_EXACT_OVERLAP_DECODE_LIMIT = 40
        private const val HOST_EXACT_MOTION_DEFERRED_RECHECK_MS = 250L
        private const val HOST_EXACT_MOTION_DEFERRED_IDLE_RECHECK_MS = 16L
        private const val DIRECT_WIFI_IDLE_FORWARD_WARM_PUMP_STEP_MS = 16L
        private const val DIRECT_WIFI_FORWARD_WARM_AHEAD_PAGES = 2
        private const val HOST_GPU_ADJACENT_P0_PREDECODE_WAIT_MS = 4L
        private const val STRICT_OVERSIZED_INITIAL_FORWARD_RUNWAY_PAGES = 32
        private const val STRICT_OVERSIZED_FORWARD_RUNWAY_PAGES = 32
        private const val STRICT_OVERSIZED_BEHIND_PAGES = 2
        private const val NTK_STRICT_OVERSIZED_BITMAP_BYTES = 768L * 1024L * 1024L
        // Reserve at least one vsync after the anchor Surface ACK. Decode and resident body work
        // continue during this window; only offscreen main-thread publication is coalesced.
        private const val STRICT_EXACT_FIRST_FRAME_PUBLICATION_GRACE_MS = 48L
        private const val PRIME_PIPELINE_PARALLELISM = 8
        private const val ADJACENT_PIPELINE_PARALLELISM = 3
        private const val NTK_GENERATED_EARLY_TAIL_MISSING_SOURCE_MIN = 3
        private const val NTK_GENERATED_EARLY_TAIL_MISSING_SOURCE_MAX = 12
        private const val NTK_GENERATED_EARLY_TAIL_MISSING_MIN_REMOVE = 2
        private const val NTK_GENERATED_CONFIRMED_TAIL_MISSING_SOURCE_MIN = 12
