        @JvmStatic
        fun protectedNumericBitmapWindowForTest(pageCount: Int, anchor: Int, direction: Int): IntArray {
            return protectedNumericBitmapWindowBounds(pageCount, anchor, direction)
        }

        @JvmStatic
        fun strictExactProtectedNumericBitmapWindowForTest(pageCount: Int): IntRange =
            strictExactProtectedNumericBitmapWindow(pageCount)

        @JvmStatic
        fun strictExactScopedBitmapWindowBoundsForTest(
            pageCount: Int,
            anchor: Int,
            direction: Int,
            launchFirst: Int,
            launchLast: Int,
        ): IntArray = strictExactScopedBitmapWindowBounds(
            pageCount,
            anchor,
            direction,
            launchFirst,
            launchLast,
        )

        @JvmStatic
        fun strictExactScopedBitmapWindowWithPhysicalSpanForTest(
            pageCount: Int,
            anchor: Int,
            direction: Int,
            launchFirst: Int,
            launchLast: Int,
            physicalFirst: Int,
            physicalLast: Int,
        ): IntArray {
            val bounds = strictExactScopedBitmapWindowBounds(
                pageCount,
                anchor,
                direction,
                launchFirst,
                launchLast,
            )
            includePhysicalSpanInBitmapWindow(
                bounds,
                pageCount,
                physicalFirst,
                physicalLast,
            )
            return bounds
        }

        @JvmStatic
        @JvmOverloads
        fun resolveWindowDirectionForTest(
            previousAnchor: Int,
            currentAnchor: Int,
            previousDirection: Int,
            directionHint: Int,
            busy: Boolean = true,
            blockedForwardIndex: Int = -1,
        ): Int = resolveWindowDirection(
            previousAnchor,
            currentAnchor,
            previousDirection,
            directionHint,
            busy,
            blockedForwardIndex,
        )

        private fun strictExactProtectedNumericBitmapWindow(pageCount: Int): IntRange =
            if (pageCount <= 0) IntRange.EMPTY else 0 until pageCount

        private fun strictExactScopedBitmapWindowBounds(
            pageCount: Int,
            anchor: Int,
            direction: Int,
            launchFirst: Int,
            launchLast: Int,
        ): IntArray {
            if (pageCount <= 0) return intArrayOf(0, -1)
            val bounds = protectedNumericBitmapWindowBounds(pageCount, anchor, direction)
            if (launchFirst >= 0 && launchLast >= launchFirst) {
                bounds[0] = minOf(bounds[0], launchFirst.coerceIn(0, pageCount - 1))
                bounds[1] = maxOf(bounds[1], launchLast.coerceIn(bounds[0], pageCount - 1))
            }
            return bounds
        }

        private fun includePhysicalSpanInBitmapWindow(
            bounds: IntArray,
            pageCount: Int,
            physicalFirst: Int,
            physicalLast: Int,
        ) {
            if (pageCount <= 0 || bounds.size < 2) return
            // Removal uses first..(first - 1) as the empty retained-window sentinel. Do not turn
            // that sentinel into a real page-zero admission during an ownership handoff.
            if (physicalFirst < 0 || physicalLast < physicalFirst || physicalFirst >= pageCount) return
            val first = physicalFirst.coerceIn(0, pageCount - 1)
            val last = physicalLast.coerceIn(first, pageCount - 1)
            bounds[0] = minOf(bounds[0], first)
            bounds[1] = maxOf(bounds[1], last)
        }

        private fun resolveWindowDirection(
            previousAnchor: Int,
            currentAnchor: Int,
            previousDirection: Int,
            directionHint: Int,
            busy: Boolean,
            blockedForwardIndex: Int = -1,
        ): Int = when {
            directionHint < 0 -> -1
            directionHint > 0 -> 1
            previousAnchor < 0 -> previousDirection
            currentAnchor > previousAnchor -> 1
            // A missing NEXT body can force the clean drawable viewport from that synthetic
            // blocker anchor back to its predecessor. That is a coordinate repair, not reverse
            // input. Surface's explicit reverse evidence above remains authoritative and clears
            // the blocker before this fallback is evaluated.
            busy && previousDirection > 0 && blockedForwardIndex > currentAnchor -> 1
            // Reverse evidence is sticky in the Surface mailbox, whereas a forward MOVE can be
            // coalesced into its following idle callback. Preserve that asymmetric contract:
            // accept an idle forward delta, but do not turn the synthetic blocked-forward
            // anchor's idle fallback into a reverse gesture and churn the strict source epoch.
            busy && currentAnchor < previousAnchor -> -1
            else -> previousDirection
        }

        @JvmStatic
        fun preparedRunwayDecodeColdForTest(
            index: Int,
            preparedLast: Int,
            viewerActivated: Boolean,
            inputObserved: Boolean,
            viewportBusy: Boolean
        ): Boolean {
            return shouldKeepPreparedRunwayDecodeColdPolicy(
                index,
                preparedLast,
                viewerActivated,
                inputObserved,
                viewportBusy
            )
        }

        private fun shouldKeepPreparedRunwayDecodeColdPolicy(
            index: Int,
            preparedLast: Int,
            viewerActivated: Boolean,
            inputObserved: Boolean,
            viewportBusy: Boolean
        ): Boolean {
            if (preparedLast < 0 || index <= preparedLast) return false
            val continuationLast = preparedLast + NTK_PREPARED_POST_ACTIVATION_CONTINUATION_PAGES
            if (viewerActivated && index <= continuationLast) return false
            if (inputObserved || viewportBusy) return false
            return true
        }

        private fun preparedPostActivationContinuationBounds(
            physicalLast: Int,
            storeReadyLast: Int,
            pageCount: Int
        ): IntArray {
            val base = max(physicalLast, storeReadyLast)
            if (base < 0 || pageCount <= 0 || base >= pageCount - 1) return intArrayOf(0, -1)
            return intArrayOf(
                base + 1,
                minOf(pageCount - 1, base + NTK_PREPARED_POST_ACTIVATION_CONTINUATION_PAGES)
            )
        }

        @JvmStatic
        fun preparedPostActivationContinuationBoundsForTest(
            physicalLast: Int,
            storeReadyLast: Int,
            pageCount: Int
        ): IntArray = preparedPostActivationContinuationBounds(
            physicalLast,
            storeReadyLast,
            pageCount
        )

        @JvmStatic
        fun isProtectedNumericNtkPathShapeForTest(path: String): Boolean {
            return isProtectedNumericNtkPathShape(path)
        }

        private fun protectedNumericBitmapWindowBounds(pageCount: Int, anchor: Int, direction: Int): IntArray {
            if (pageCount <= 0) return intArrayOf(0, -1)
            val safeAnchor = anchor.coerceIn(0, pageCount - 1)
            val reverse = direction < 0
            val behind = if (reverse) {
                NTK_PROTECTED_BITMAP_AHEAD_PAGES
            } else {
                NTK_PROTECTED_BITMAP_BEHIND_PAGES
            }
            val ahead = if (reverse) {
                NTK_PROTECTED_BITMAP_BEHIND_PAGES
            } else {
                NTK_PROTECTED_BITMAP_AHEAD_PAGES
            }
            return intArrayOf(
                max(0, safeAnchor - behind),
                minOf(pageCount - 1, safeAnchor + ahead)
            )
        }

        private fun isProtectedNumericNtkPathShape(path: String): Boolean {
            return path.matches(
                Regex("^/(?:manhwa|webtoon)/\\d{1,12}/\\d{1,12}(?:[/?#].*)?$", RegexOption.IGNORE_CASE)
            )
        }

        private fun shouldSplitPreparedBitmapForPage(
            autoCut: Boolean,
            allowSplit: Boolean,
            width: Int,
            height: Int
        ): Boolean {
            if (!autoCut || !allowSplit || width <= 0 || height <= 0) return false
            return width / height.toFloat() >= SPREAD_ASPECT_RATIO
        }

        private fun readerThreadFactory(name: String, priority: Int): ThreadFactory {
            val counter = AtomicInteger(1)
            return ThreadFactory { runnable ->
                Thread {
                    Process.setThreadPriority(priority)
                    runnable.run()
                }.apply {
                    this.name = "$name-${counter.getAndIncrement()}"
                    isDaemon = true
                    }
                }
            }
        }
    }
